pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = 0.0;

    // Base: wasted space, with a dead-space multiplier that punishes
    // small unusable gaps much more than large useful residuals.
    let pr = post_residual as f64;
    if pr == 0.0 {
        // Perfect fit: strongest reward.
        score -= 1000.0;
    } else if pr < 10.0 {
        // Unusable dead space (< min item size): heavy penalty.
        score += 500.0 + (10.0 - pr) * 50.0;
    } else {
        // Usable residual: mild reward for larger leftover space.
        score += pr * 0.5;
    }

    // Tightness of the fit: prefer bins where item fills a large fraction.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= fill_ratio * 100.0;

    // Open-bin pressure: discourage scattering across many open bins.
    score += open_bins_count as f64 * 5.0;

    // Last-chance bin: strongly reward using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate handling: opening a new bin should only win when
    // no open bin offers a good fit. Make the empty bin moderately
    // attractive (fresh residual) but not better than a tight fit.
    if bin_residual == bin_capacity {
        score += 150.0 - open_bins_count as f64 * 10.0;
        // Late in the stream, opening new bins is less attractive.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 100.0;
    }

    // Lookahead: if next item fits in the post residual, big reward.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 200.0;
    }
    // If next item almost fits (small gap), slight penalty for blocking it.
    else if next_item_size > 0 && pr > 0.0 && (next_item_size as f64) - pr <= 10.0 {
        score += 50.0;
    }

    // Prefer bins whose residual is near the mean (balance loads).
    score -= (mean_residual - pr).abs() * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item (1..=100) are pure waste.
    if post_residual == 0 {
        score -= 1000.0; // perfect fit: excellent
    } else if post_residual < 10 {
        score += 120.0; // unusable tiny gap: heavy penalty
    } else if post_residual < 20 {
        score += 60.0;
    } else if post_residual < 35 {
        score += 25.0;
    } else if post_residual < 60 {
        score += 8.0;
    }

    // Reward bins whose residual was already tight (good packing density).
    let fill_frac = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 30.0 * fill_frac;

    // Lookahead: if the next item fits exactly into the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 150.0;
        } else if next_item_size <= post_residual {
            score -= 40.0;
        } else {
            // next item can't use this gap; small gap becomes more wasteful
            if post_residual < next_item_size {
                score += 10.0;
            }
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor filling existing bins.
    let open_pressure = (open_bins_count as f64).ln().max(0.0);
    score += 6.0 * open_pressure;

    // New-bin candidate logic: opening a new bin is only attractive when the item
    // fits poorly everywhere else (large item, tight residuals elsewhere).
    if bin_residual == bin_capacity {
        let tight_elsewhere = mean_residual < item_size as f64 * 0.5;
        if tight_elsewhere || fitting_bins_count == 0 {
            score -= 50.0; // allow opening a fresh bin
        } else {
            score += 45.0 + 0.5 * mean_residual; // prefer reusing open bins
        }
    }

    // Early stream: slightly prefer consolidating into few bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into
    // capacity-fraction buckets (1/4, 1/3, 1/2, 3/4 of capacity).
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    let three_quarter = 3 * quarter;

    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Dead-space penalty: residuals too small for the smallest plausible item.
        if post_residual < 10 {
            score += 60.0;
        }
        // Harmonic bucket bonus: residuals near half capacity are the most reusable,
        // then quarter, then three-quarter.
        let bucket_bonus: f64 = if post_residual >= half - 5 && post_residual <= half + 5 {
            35.0
        } else if post_residual >= quarter - 5 && post_residual <= quarter + 5 {
            22.0
        } else if post_residual >= three_quarter - 5 {
            12.0
        } else {
            0.0
        };
        score -= bucket_bonus;

        // Reward residuals that can still host the lookahead item exactly-ish.
        if next_item_size > 0 && post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            score -= 25.0 + (10.0 - slack.min(10) as f64) * 2.0;
        } else if next_item_size > 0 && next_item_size > post_residual {
            // Lookahead cannot use this leftover: mild penalty scaled by gap.
            score += ((next_item_size - post_residual) as f64) * 0.5;
        }
    }

    // Integer-division class of item size relative to capacity quarters.
    let item_class = item_size / quarter; // 0..4
    let residual_class = bin_residual / quarter;
    // Reward pairing large items with large-residual bins (class matching).
    if item_class == residual_class && post_residual < bin_residual {
        score -= 8.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 45.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // no open bin fits well (mean residual low relative to item) or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mean_gap = (mean_residual - item_size as f64).max(0.0);
        // Prefer a new bin if existing residuals barely fit the item.
        score = 40.0 + mean_gap * 0.8 - progress * 10.0 - (open_bins_count as f64) * 0.5;
        if fitting_bins_count == 0 {
            score -= 80.0; // no alternative: new bin is fine
        }
        if next_item_size > 0 && next_item_size > item_size {
            score -= 5.0; // big lookahead: fresh capacity helps
        }
    } else {
        // Mild penalty for spreading across many open bins.
        score += (open_bins_count as f64) * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small to hold even the
    // smallest plausible item are almost pure waste — penalize them heavily.
    if post_residual > 0 && post_residual < item_size.min(20) {
        score += 40.0 + (20 - post_residual) as f64 * 2.5;
    }
    // Absolute dead space: residual so small nothing (<=10) can ever fit.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Reward tight fits (low post_residual relative to item size).
    if item_size > 0 {
        let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
        score -= 12.0 * fill_ratio;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: discourage spreading across many bins, but a brand-new
    // bin candidate (residual == capacity) is exempt from this pressure.
    if bin_residual != bin_capacity {
        score += (open_bins_count as f64) * 1.5;
    } else {
        // New bin: baseline cost, slightly reduced when current bins are crowded.
        score += 18.0 - (open_bins_count as f64).min(20.0) * 0.4;
        // Prefer a new bin if the lookahead item would be stranded by this placement.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score -= 15.0;
        }
    }

    // Lookahead coupling: if this placement leaves room exactly for the next
    // item, reward it; if it leaves a gap just barely too small, penalize.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 18.0;
        } else if post_residual > next_item_size && post_residual < next_item_size + 10 {
            score += 6.0;
        }
    }

    // Mild stream-progression regularization.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 2.0 * progress;

    // Prefer bins whose residual is close to the mean (keeps bin states uniform).
    score += 0.3 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: reward small post_residual nonlinearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Penalize dead space that cannot fit the next item (lookahead coupling).
    if next_item_size > 0 {
        if post_residual > 0 && (post_residual as u32) < next_item_size {
            score += 12.0 * (next_item_size as f64 - post_residual as f64);
        } else if (post_residual as u32) >= next_item_size {
            score -= 6.0; // this bin can still host the next item
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else {
        // Many alternatives: mildly penalize wasting this bin's space.
        score += 2.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Global pressure: many open bins -> consolidate; few bins -> spreading is ok.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = open_bins_count as f64 / (mean_residual.max(1.0) / bin_capacity as f64).max(0.5);
    score += 0.05 * pressure * (1.0 + progress);

    // Align with mean residual: prefer bins whose residual is below average (already tight).
    score += 0.3 * (post_residual as f64 - mean_residual).max(0.0);

    // New-bin candidate: only attractive when item is large relative to typical residuals
    // or no decent fit exists (large post_residual on new bin = full capacity available).
    if bin_residual == bin_capacity {
        let item_frac = item_size as f64 / bin_capacity as f64;
        let mean_frac = mean_residual / bin_capacity as f64;
        // Prefer new bin when item is big and existing residuals are small (poor fits).
        let new_bin_bonus = 30.0 * item_frac * (1.0 - mean_frac) - 20.0 * (1.0 - item_frac) * mean_frac;
        score -= new_bin_bonus;
        // Late in stream, discourage opening new bins to consolidate.
        score += 15.0 * progress;
    }

    // Small penalty for leaving very small unusable slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item.max(next_item_size.min(item_size)) {
        // gap too small for any future item -> dead space
        score += 40.0;
    }
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        score += 15.0; // cannot host the lookahead item
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 100.0;
    } else {
        let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
        score -= 20.0 * fill_ratio;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage spreading across many open bins when
    // mean residual is low (bins nearly full already).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score += (open_bins_count as f64) * (1.0 - progress) * 2.0;
        // Prefer bins whose residual deviates below the mean (consolidate fuller bins).
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        }
    } else {
        // New-bin candidate: only attractive when item is huge relative to residual
        // of typical open bins or no good fit exists.
        score += 10.0 + 5.0 * progress;
    }

    // Lookahead synergy: reward leaving exactly room for the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) more aggressively as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (bin_capacity - post_residual) as f64 * (0.4 + 0.8 * progress);

    // Penalize dead space that is too small to hold the next item (or a typical small item).
    let next_probe = if next_item_size > 0 { next_item_size } else { 20 };
    if post_residual > 0 && post_residual < next_probe {
        score += (next_probe - post_residual) as f64 * 2.5;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 + 15.0 * progress;
    }

    // Many fitting bins: mild penalty to keep fragmentation spread low; few bins: reward.
    if fitting_bins_count > 2 {
        score += 3.0 * (fitting_bins_count as f64 - 2.0).min(6.0);
    }

    // Prefer bins below mean residual (relatively emptier) early, tighter bins late.
    let res_f = bin_residual as f64;
    let dev = res_f - mean_residual;
    score += dev * (0.25 - 0.5 * progress);

    // New-bin candidate logic: open a new bin only when current bins fit poorly
    // (large dead space would result) or stream is early and item is large.
    if bin_residual == bin_capacity {
        let worst_waste = 40.0;
        let poor_fit_penalty = if post_residual > 0 && post_residual < next_probe { 35.0 } else { 0.0 };
        let early_open_bonus = (1.0 - progress) * 10.0 * (item_size as f64 / 100.0);
        let crowded_bonus = (open_bins_count as f64).ln().max(0.0) * 2.0;
        score -= 60.0 + poor_fit_penalty + early_open_bonus + crowded_bonus - worst_waste.min(post_residual as f64) * 0.2;
        // Discard new-bin option when an open bin gives a near-perfect fit.
        if post_residual == 0 || (fitting_bins_count == 1 && post_residual <= 10) {
            score += 80.0;
        }
    }

    // Slight preference for filling larger-residual bins when item is big.
    if item_size >= 60 {
        score -= res_f * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residual gaps too small for typical
    // future items (<= 20) are heavily penalized as wasted capacity.
    if post_residual > 0 && post_residual < 20 {
        score += 40.0 + (20 - post_residual) as f64 * 3.0;
    }

    // Gaps in the "awkward middle" (21..35) are mildly penalized too.
    if post_residual >= 20 && post_residual < 35 {
        score += 8.0;
    }

    // Reward perfect or near-perfect fits.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 10 {
        score -= 10.0;
    }

    // Lookahead: if the next item fits the post residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // If next item does NOT fit post residual, penalize slightly more when
    // the gap is dead space for the known future item.
    if next_item_size > post_residual && post_residual > 0 {
        score += 5.0;
    }

    // Last-chance bin pressure: if this is the only fitting bin, avoid
    // opening a new bin unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading; few open
    // bins -> encourage filling existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (0.4 + 0.6 * progress);

    // Mean residual coupling: prefer bins below mean residual (tighter bins
    // first), pushing big gaps to be filled later.
    score += (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate: only attractive when nothing fits well; make the
    // empty bin costly by default but slightly cheaper when many bins exist.
    if bin_residual == bin_capacity {
        score += 55.0 - open_bins_count as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Slack after accommodating the next item: smaller is better.
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 - slack.min(40.0);
        } else {
            // Next item cannot fit here; penalize proportionally to the shortfall.
            let shortfall = (next_item_size - post_residual) as f64;
            score += shortfall * 0.5;
        }
    }

    // Penalize leaving tight dead space that nothing (sizes >= 1) can use later.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Prefer bins with residuals below the mean (tighter packing target).
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // Early in the stream, allow opening fresh bins more freely; later, conserve bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline near mean residual, rising penalty later in stream.
        score = mean_residual + 10.0 + progress * 30.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0; // a fresh bin always fits the next item
        }
        if fitting_bins_count <= 1 {
            score -= 25.0; // no good alternative exists
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // for typical future items are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 200.0;
    } else if post_residual < 20 {
        score += 60.0;
    } else if post_residual < 30 {
        score += 15.0;
    }

    // Reward tight fits (small relative leftover).
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 40.0 * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead: if next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Pressure from number of open bins: prefer reusing existing bins
    // when many bins are already open.
    score += (open_bins_count as f64).ln().max(0.0) * 3.0;

    // Mean residual context: if this bin is far below mean residual (already tight),
    // mild bonus; if it would leave this bin much emptier than average, mild penalty.
    score += 0.2 * (mean_residual - post_residual as f64);

    // Mild preference for keeping large residuals on fresh bins early in the stream.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += 5.0 + 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for likely future items are wasted.
    // Treat residuals below a "usable threshold" as dead space and penalize quadratically.
    let usable_threshold = 30.0_f64.max(next_item_size as f64);
    if (post_residual as f64) < usable_threshold {
        let deficit = usable_threshold - post_residual as f64;
        score += deficit * deficit * 0.15;
    }

    // Perfect fit is excellent.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Tight fit reward: item fills most of the bin.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 20.0;

    // Lookahead coupling: if the next item fits exactly in post_residual, strongly favor.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item cannot follow here; penalize proportionally to leftover waste.
        score += (post_residual as f64) * 0.3;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading into new/partial bins.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual.max(1.0) / 10.0);
    score += pressure * 0.5;

    // New-bin candidate handling: only attractive when open bins are crowded or fits are poor.
    if bin_residual == bin_capacity {
        let crowded = if mean_residual > 0.0 { mean_residual / bin_capacity as f64 } else { 0.0 };
        let poor_fit = (item_size as f64 / bin_capacity as f64) < 0.5;
        if crowded < 0.3 || poor_fit {
            score -= 15.0 + crowded * 20.0;
        } else {
            score += 30.0;
        }
        // Early in stream, a fresh bin is fine.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo buckets on capacity fractions
    let pr = post_residual;
    let class = pr % 10;
    // Dead-space penalty: residuals that are unusable for typical small items
    if pr > 0 && pr < 10 {
        score += 60.0; // tiny dead space
    }
    // Harmonic reward: residuals that are multiples of common item classes
    if class == 0 {
        score -= 8.0;
    } else if pr % 25 == 0 {
        score -= 6.0;
    } else if pr % 5 == 0 {
        score -= 3.0;
    } else {
        score += 2.0;
    }

    // Perfect fit bonus
    if pr == 0 {
        score -= 100.0;
    }

    // Lookahead coupling: does post_residual fit next item exactly?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 50.0;
        } else if next_item_size <= pr {
            score -= (pr - next_item_size) as f64 * 0.3;
        } else {
            // next item won't fit here; residual becomes dead-ish
            score += (next_item_size - pr) as f64 * 0.2;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: only prefer new bin if all open bins fit poorly
    if bin_residual == bin_capacity {
        // baseline for a fresh bin; competitive unless existing fit is good
        score = 55.0 + mean_residual * 0.1 - (open_bins_count as f64) * 0.5;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0;
        }
    }

    // Progress factor: late in stream, prefer tighter packing
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.1;

    // Penalize bins whose residual is far below mean (fragmented bins)
    if (bin_residual as f64) < mean_residual * 0.5 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls into "nice"
    // residue classes (multiples of common small sizes) are more reusable.
    let pr = post_residual;
    if pr > 0 {
        // reward residuals divisible by common item granularities
        if pr % 10 == 0 { score -= 12.0; }
        else if pr % 5 == 0 { score -= 6.0; }
        if pr % 20 == 0 { score -= 8.0; }
        // dead space: residuals in awkward bands are penalized
        if pr < 10 { score += 25.0; }
        else if pr < 20 { score += 10.0; }
        // integer-division threshold: residual "capacity fraction" class
        let frac = pr as f64 / cap;
        if frac > 0.5 { score -= 15.0; }
        else if frac < 0.25 { score += 8.0; }
    } else {
        // perfect fill is the best outcome
        score -= 60.0;
    }

    // Lookahead coupling: does post_residual combine with next item?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // next item still fits here: strong reward, scaled by tightness
            let slack = (pr - next_item_size) as f64;
            score -= 20.0 + 0.3 * slack;
            // harmonic bonus if pair sums hit a nice class
            if (item_size + next_item_size) % 10 == 0 { score -= 10.0; }
        } else {
            // next item will not fit: penalty grows with how much we "wasted"
            score += 5.0 + 0.2 * (next_item_size - pr) as f64;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when existing
    // residuals are all poor and the item is large.
    if bin_residual == bin_capacity {
        // base penalty keeps new bins from being opened casually
        score += 40.0;
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mean_frac = mean_residual / cap;
        // open new bin if mean residual is small (bins nearly full) or
        // item is huge and nothing fits well
        if mean_frac < 0.15 { score -= 55.0; }
        if item_size > 70 && mean_frac < 0.3 { score -= 20.0; }
        if open_bins_count == 0 { score -= 100.0; }
        if progress > 0.9 && mean_frac < 0.25 { score -= 10.0; }
    }

    // mild pressure to consolidate when many bins are open
    score -= 0.05 * open_bins_count as f64;
    // slight preference for tighter fits overall
    score += 0.1 * (bin_residual - item_size) as f64 * 0.0; // no-op guard
    score -= 0.2 * (item_size as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are the worst outcome.
    // Define "unusable" as a gap smaller than the smallest plausible item (1..100 range,
    // but treat gaps below ~10 as dead since tiny items are rare).
    let dead_threshold: f64 = 10.0;
    let pr = post_residual as f64;

    if pr > 0.0 && pr < dead_threshold {
        // Severe penalty for creating a sliver of dead space.
        score += (dead_threshold - pr) * 8.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0; // exact fill is ideal
    } else if (pr as u32) <= item_size / 4 && pr < 25.0 {
        score -= 25.0; // very tight fit
    }

    // Moderate residual is preferred over huge residual (waste) but also
    // over tiny residual (dead space): quadratic shaping around a sweet spot.
    let sweet_spot = 30.0;
    score += 0.02 * (pr - sweet_spot) * (pr - sweet_spot);

    // Lookahead: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual > next_item_size {
            score -= 5.0;
        } else {
            // next item cannot use the remaining gap -> mild penalty proportional to gap
            score += pr * 0.3;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits to avoid
    // opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Open bins pressure: with many open bins, prefer filling existing ones
    // over spreading; penalize less when few bins are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (1.5 + 2.0 * progress);

    // New-bin candidate (empty bin): only attractive when existing bins would
    // leave bad dead space or no bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by how badly existing
        // bins would fit (proxy: mean residual vs item size).
        let fit_badness = (mean_residual - item_size as f64).max(0.0);
        score = 120.0 - fit_badness * 0.8 - (fitting_bins_count as f64) * 5.0;
        // Early in the stream, opening bins is cheaper; late, prefer consolidation.
        score += 40.0 * progress;
    }

    // Slight preference for bins whose residual is close to mean (balance).
    score += 0.05 * ((bin_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that nothing (min size 1..100, but
    // practically small gaps < ~10) can ever fill are pure waste. Penalize hard.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item.max(1) {
        score += 1000.0; // unreachable in practice; guard
    }
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // unusably small gap
    } else if post_residual < 20 {
        score += 15.0; // near-dead space
    }

    // Reward near-perfect fits (post_residual close to 0).
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Reward residual that can still host the lookahead item (k=2 lookahead).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            score += 5.0; // creating a gap the next item cannot use
        }
    }

    // Open-bin pressure: with many bins open, prefer consolidation into existing
    // bins rather than spreading; with few bins, filling is cheap.
    let pressure = open_bins_count as f64 * 1.5;
    score += pressure * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin is only attractive when the item
    // fits poorly everywhere else, or when mean residual is very low.
    if bin_residual == bin_capacity {
        // Baseline new-bin score: moderately high so tight fits in open bins win.
        score = (bin_capacity - item_size) as f64 * 0.6;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: new bin is fine
        }
        if mean_residual < 5.0 {
            score -= 10.0;
        }
    } else {
        // Existing-bin placements get a structural discount vs the new-bin baseline.
        score -= 10.0;
    }

    // Slight late-stream tightening: as the stream progresses, waste matters more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 5.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps are unusable, penalize them hard.
    let dead_zone = 12.0f64;
    if post_residual > 0 && (post_residual as f64) < dead_zone {
        score += (dead_zone - post_residual as f64) * 6.0;
    }
    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }
    // Reward leaving a gap that the lookahead item could use.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 4.0 + (post_residual - next_item_size) as f64 * 0.05;
    } else if next_item_size > 0 {
        // Gap too small for next item: dead space risk.
        score += 3.0;
    }

    // New-bin candidate logic: opening a bin is attractive when current fit is poor
    // or when this is a last-chance bin with bad residual.
    if bin_residual == bin_capacity {
        // Fresh bin: prefer it when fit quality elsewhere is bad or many bins are open.
        let fit_pressure = if fitting_bins_count <= 1 { 8.0 } else { 0.0 };
        score -= 5.0 + fit_pressure + (open_bins_count as f64).min(10.0) * 0.8;
    } else {
        // Last chance bin: strongly favor using it to avoid opening a new bin.
        if fitting_bins_count == 1 {
            score -= 10.0;
        }
        // Reward tight fits relative to residual.
        let tightness = item_size as f64 / bin_residual.max(1) as f64;
        score -= tightness * 8.0;
        // Open-bin pressure: discourage spreading across many bins unless tight.
        score += open_bins_count as f64 * 0.3;
    }

    // Mild preference for bins with residual close to mean (balance).
    score -= 0.2 * (1.0 - ((bin_residual as f64 - mean_residual).abs() / bin_capacity as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold the
    // smallest plausible future item are "dead". Penalize them heavily.
    let min_item = 1.0f64;
    if (post_residual as f64) < min_item {
        score += 1000.0; // exact fill, perfect
    } else if post_residual < 10 {
        // gap too small for most items -> dead space
        score += 40.0 + (10 - post_residual) as f64 * 5.0;
    } else if post_residual <= 25 {
        // moderately awkward gap
        score += 12.0;
    }

    // Reward tight fits (small post_residual relative to bin capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Lookahead coupling: if the next item fits the post-residual exactly or
    // nearly, reward this placement strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size < post_residual && post_residual - next_item_size < 10 {
            score -= 25.0;
        } else if next_item_size > post_residual {
            // next item won't fit here anyway; slightly penalize leaving a
            // gap that neither helps nor hurts
            score += 5.0;
        }
    }

    // Open-bin pressure: discourage spreading across many bins when a good
    // fit exists, but allow opening new bins when the current fit is bad.
    score += (open_bins_count as f64) * 2.0;

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Mean residual coupling: prefer bins whose residual is below the mean
    // (i.e., fuller bins), keeping emptier bins flexible.
    score += ((bin_residual as f64) - mean_residual) * 0.3;

    // New-bin candidate handling: an empty bin has a large residual; make it
    // attractive only when no decent fit exists among open bins.
    if bin_residual == bin_capacity {
        // baseline competitiveness: slightly worse than a perfect fit,
        // better than creating large dead space.
        score = 55.0 + (open_bins_count as f64) * 1.5;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // pairing large items in fresh bins
        }
    }

    // Mild stream-progression term: later in the stream, consolidate more
    // aggressively (less room to recover from fragmentation).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 8.0 * ((post_residual as f64) / (bin_capacity as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Tightness: reward small relative dead space
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * 50.0;

    // Penalize leaving residual that no typical item (1..=100) can use well:
    // residuals of 1..=9 are almost dead space
