    }

    // Lookahead: if next item fits exactly in post_residual, big bonus
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // next item fits but not perfectly; mild bonus scaled by waste
            score -= 60.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item cannot use this bin's leftover: penalize large leftovers
            score += (post_residual as f64) * 0.3;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // Many open bins: prefer filling existing bins over opening new ones
    score += open_bins_count as f64 * 2.0;

    // Prefer bins below mean residual (more filled) when many bins are open
    score += (bin_residual as f64 - mean_residual) * 0.5;

    // Time horizon: early in stream, be picky about tight fits; late in stream,
    // just pack anywhere that fits to avoid wasting bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 80.0;

    // New-bin candidate: make it moderately attractive only when current bins fit poorly
    if bin_residual == bin_capacity {
