    score += (mean_residual - post_residual as f64) * 0.05;

    // Late in stream, be greedier about closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in the "unusable gap" band
    // (too small to hold even the smallest plausible next item) are heavily penalized.
    let min_useful = 10.0_f64.min(bin_capacity as f64 * 0.1);
    let gap = post_residual as f64;
    if gap > 0.0 && gap < min_useful {
        score += (min_useful - gap) * 12.0;
    }

    // Non-linear penalty on wasted capacity fraction (quadratic dead-space pressure).
    let waste_frac = gap / bin_capacity as f64;
    score += waste_frac * waste_frac * 60.0;

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 25.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    } else if gap >= next_item_size as f64 && next_item_size > 0 {
        // Reward leaving room exactly for the lookahead item.
        score -= 15.0;
    } else if next_item_size > 0 && gap > 0.0 && gap < next_item_size as f64 {
        // Penalize blocking the known next item.
        score += (next_item_size as f64 - gap) * 4.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is excellent.
    score += open_bins_count as f64 * 1.5;

    // New-bin candidate: neutral-ish baseline, only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 20.0 + mean_residual * 0.3;
        // If nothing else fits, new bin becomes the escape hatch.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Mild stream-progression drift: later in stream, prefer consolidating.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * gap * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), but penalize post_residual
    // that is too small to ever be reused (dead space < min item size 1..100 range).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 1000.0;
    } else if post_residual < 10 {
        // Unusable dead space in a 1..100 world: heavy penalty.
        score += 200.0 * (10.0 - post_residual as f64);
    }

    // 2-step lookahead: how well does next_item_size relate to post_residual?
    if next_item_size > 0 {
        let next_f = next_item_size as f64;
        let post_f = post_residual as f64;
        if next_item_size == post_residual {
            // Chain fit: next item exactly fills this bin.
            score -= 800.0;
        } else if next_item_size <= post_residual {
            // Next item still fits here: reward proportionally to how tight.
            let tightness = 1.0 - (post_f - next_f) / bin_capacity as f64;
            score -= 300.0 * tightness;
        } else {
            // Next item does NOT fit: this bin's leftover is likely dead space
            // relative to the near future. Penalize gap size.
            let gap = (next_f - post_f).min(100.0);
            score += 60.0 + gap * 1.5;
        }

        // If next item fits ONLY in this bin, strongly favor it.
        if next_item_size <= post_residual && next_item_size <= bin_residual {
            // soft extra nudge for chain continuation
            score -= 50.0;
        }
    }

    // Last-chance bin: if this is the only bin that can fit the item, avoid
    // opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 150.0;
    } else if fitting_bins_count > 1 {
        // Many options: prefer the tightest, penalize slack relative to mean residual.
        score += 0.5 * (post_residual as f64 - mean_residual).max(-50.0).min(50.0);
    }

    // Relative-to-mean archetype coupling: bins with residual far below mean
    // are "almost full" — placing there consolidates waste.
    let rel = post_residual as f64 - mean_residual;
    score += 0.3 * rel;

    // New-bin candidate handling: an empty bin has huge post_residual, which
    // already scores high; add extra penalty so it's only chosen when open
    // bins give bad fits (their dead-space/lookahead penalties dominate).
    if bin_residual == bin_capacity {
        score += 80.0 + 0.2 * open_bins_count as f64;
    } else if open_bins_count > 0 {
        // Slight reward for using existing bins to keep bin count low.
        score -= 20.0;
    }

    // Mild pressure against opening many bins early in the stream.
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Post-residual that cannot fit the smallest possible item (1) is pure waste,
    // but any residual below the typical min size is suspect under unknown dists.
    if post_residual < item_size.min(20) && post_residual > 0 {
        score += 25.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Post-residual exactly matching next item: strong reward (lookahead chaining).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 35.0;
    }
    // Post-residual too small for the next item while still nonzero: mild penalty.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // Open bins pressure: discourage spreading across many bins.
    score += (open_bins_count as f64) * 1.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Mean residual coupling: prefer bins deviating below the mean residual
    // (tighter bins get priority), scaled by stream progress.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (mean_residual - post_residual as f64) * (0.3 + 0.4 * progress);

    // New-bin candidate: penalize mildly so it only wins when open bins are bad.
    if bin_residual == bin_capacity {
        score += 20.0;
        // Late in stream, opening fresh bins is more acceptable.
        score -= 25.0 * progress;
        // But if the current bin would leave a large residual and next item is big,
        // a fresh bin can be better.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    score = post_residual as f64 * 1.0;

    // Aggressive 2-step lookahead: strongly reward bins where the NEXT item
    // also fits into the post_residual (perfect chaining).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Reward proportional to how well next item fills remaining space.
            let chain_waste = (post_residual - next_item_size) as f64;
            score -= 40.0 - 0.5 * chain_waste;
        } else {
            // Penalize chains that leave awkward large gaps.
            let gap = (next_item_size - post_residual) as f64;
            if gap < 20.0 {
                score += 0.6 * gap;
            } else {
                score += 12.0;
            }
        }
    } else {
        // Last item: any residual is pure waste; push toward tightest fit.
        score += 5.0;
    }

    // Compare against mean residual: bins already below-mean residual are
    // precious; using them for loose fits is worse.
    if (bin_residual as f64) < mean_residual {
        score += 0.3 * (mean_residual - bin_residual as f64);
    } else {
        score -= 0.2 * (bin_residual as f64 - mean_residual);
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a
    // new bin unless the fit is truly terrible.
    if fitting_bins_count == 1 {
        score -= 25.0;
        // Extra penalty if placing here creates large dead space AND next
        // item could have used the fresh bin.
        if post_residual > 0 && next_item_size > post_residual {
            score += 5.0;
        }
    }

    // New empty bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // Neutral-ish base; discourage slightly so tight fits win,
        // but allow it when many bins are open and mean residual is low.
        score += 8.0;
        if open_bins_count > 3 && mean_residual < item_size as f64 {
            score -= 15.0;
        }
        if next_item_size > 0 && next_item_size >= bin_capacity - item_size {
            // Next item pairs perfectly with a fresh bin.
            score -= 20.0;
        }
    }

    // Dead-space penalty: residual too small to hold any plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Stream progression: early on, be conservative with new bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact / near-exact fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        score -= 300.0 / post_residual as f64;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // can accommodate the next item (chain packing).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // slack after placing both current and next item
            let slack2 = post_residual - next_item_size;
            score -= 150.0 + 100.0 / (1.0 + slack2 as f64);
        } else {
            // penalize blocking the next item
            let gap = next_item_size - post_residual;
            score += 40.0 + 0.5 * gap as f64;
        }
    }

    // Relative-to-mean coupling: bins tighter than the mean are
    // preferred targets for filling up.
    let res = post_residual as f64;
    if mean_residual > 0.0 {
        score += 0.4 * (res - mean_residual);
    }

    // Last-chance bin: strong preference to use it before opening new.
    if fitting_bins_count == 1 {
        score -= 120.0;
    } else if fitting_bins_count > 1 {
        // mild penalty so ties among many fitting bins are broken by fit quality
        score += 5.0 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // baseline cost of opening a fresh bin
        score += 80.0;
        // more attractive late in the stream when many bins are open
        // and mean residual is small (open bins are nearly full anyway)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 60.0 * progress * (mean_residual / bin_capacity as f64);
        if next_item_size > 0 && next_item_size >= bin_capacity {
            score -= 200.0; // next item needs a fresh bin anyway
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect or near-perfect fits
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    }

    // Aggressive 2-step lookahead: reward if next item fits into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 900.0; // exact two-item completion
        } else if next_item_size < post_residual {
            let leftover = post_residual - next_item_size;
            score -= 500.0 - (leftover as f64) * 2.0; // prefer tight chain fits
        } else {
            // next item cannot follow: penalize wasted potential
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.5;
        }
    }

    // Compare post_residual against mean residual across open bins
    score -= (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 250.0;
    }

    // Penalize opening a new bin when many bins are open and item could fit elsewhere
    if bin_residual == bin_capacity {
        // new-bin candidate: baseline score = capacity - item_size effectively
        // make it unattractive unless few bins open or lookahead is bad
        score += 120.0;
        if open_bins_count <= 1 {
            score -= 150.0;
        }
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // new bin can always chain, slight bonus
            score -= 40.0;
        }
    }

    // Mild late-stream tightening: prefer compact packing as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo common item sizes
    let r = post_residual;
    // Perfect-fit reward (zero dead space is ideal)
    if r == 0 {
        score -= 1000.0;
    }

    // Small residues are dead space unless they match a likely future item size.
    // Harmonic classes: residues divisible by common sizes (e.g. multiples of 10, 25, 50)
    let harmonic_bonus = if r > 0 {
        if r % 50 == 0 { 30.0 }
        else if r % 25 == 0 { 20.0 }
        else if r % 10 == 0 { 15.0 }
        else if r % 5 == 0 { 8.0 }
        else { 0.0 }
    } else { 0.0 };
    score -= harmonic_bonus;

    // Coupling with lookahead item: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual >= next_item_size {
            // next item fits: reward proportional to leftover tightness
            let rem = post_residual - next_item_size;
            score -= 50.0 + (rem as f64).min(60.0);
        } else {
            // next item cannot fit here: penalize small unusable residues more
            if post_residual < next_item_size && post_residual < 20 {
                score += 40.0;
            }
        }
    }

    // Integer division thresholds on post_residual: classify usability
    let quarter = bin_capacity / 4; // 25
    if r > 0 && r < quarter {
        score += 60.0; // tiny dead space penalty
    } else if r < bin_capacity / 2 {
        score += 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: only attractive when current bin fit is poor
    if bin_residual == bin_capacity {
        // base penalty so new bins aren't opened casually
        score += 120.0;
        // but if item leaves an awkward residue in any bin and stream is early,
        // opening a fresh bin that leaves room for the next item can be good
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 40.0;
        }
        if fitting_bins_count == 0 {
            score -= 500.0; // no existing bin fits: new bin mandatory anyway
        }
    }

    // Slight preference to fill bins with larger mean residual (balance load)
    score -= 0.05 * mean_residual;

    // Mild stream-progression term: later in stream, prefer closing bins tight
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 20.0 * progress * (r == 0 as u32 as bool) as i32 as f64;

    // Tightness reward: smaller leftover relative to item size is better
    if item_size > 0 {
        score -= 10.0 * (item_size as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let lookahead_waste = post_residual - next_item_size;
        score -= (bin_capacity as f64 - lookahead_waste as f64) * 0.8;
    } else if next_item_size > 0 {
        // Penalize blocking the next item.
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // Relative to mean residual: prefer bins tighter than average.
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Penalize creating small dead space that nothing can use (sizes >= 1).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Late in the stream, prefer closing out bins (reduce open bin count).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress > 0.8 && post_residual < 20 {
        score -= 15.0;
    }

    // Slight penalty for spreading across many open bins.
    score += open_bins_count as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest plausible
    // item are wasted forever. Penalize small-but-nonzero post_residual hard.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0; // unusable gap (< min item size) -> strong penalty
        } else if post_residual < 25 {
            score += 25.0; // very tight gap, unlikely to be reused
        } else if post_residual < 45 {
            score += 8.0;  // marginal gap
        } else {
            score -= 10.0; // large usable residual is good
        }
    } else {
        // Perfect fit: completely fills the bin, no dead space at all
        score -= 80.0;
    }

    // Reward exact or near-exact fits relative to item size
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fit_ratio > 0.9 {
        score -= 20.0 * (fit_ratio - 0.9);
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading items
    // into a new bin; encourage consolidating into existing ones.
    score += open_bins_count as f64 * 0.5;

    // Lookahead: if the next item fits into the post_residual, reward this placement
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && (post_residual as u32) < next_item_size {
        // next item cannot use this gap -> dead space likely
        score += 6.0;
    }

    // Prefer bins whose residual is close to the mean (balanced packing),
    // mildly; avoids leaving one bin with huge residual and others drained.
    score += ((bin_residual as f64 - mean_residual).abs()) * 0.1;

    // Early in the stream, allow slightly more freedom to open bins;
    // later, consolidation pressure increases.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 0.0 + progress * (bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fill = 1.0 - pr / cap; // normalized fullness after placement
    let norm_pr = pr / cap;

    // Base: penalize large residuals, with non-linear (quadratic/cubic) shaping
    let mut score = norm_pr * (1.0 + 2.0 * norm_pr * norm_pr);

    // Smooth coupling: fullness reward amplified as stream progresses
    let coupling = fill * fill * (0.5 + 2.0 * progress * (1.0 - progress) * 4.0);
    score -= 3.0 * coupling;

    // Dead-space penalty: residual too small to likely fit future items
    let dead = if norm_pr < 0.1 { (0.1 - norm_pr) * (0.1 - norm_pr) * 100.0 } else { 0.0 };
    score += dead;

    // Lookahead: reward residual matching next item size (smooth closeness)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let diff = (pr - nx) / cap;
        score -= 2.0 * (-diff * diff * 40.0); // Gaussian-like match reward
    }

    // Last-chance bin bonus (smooth, scaled by fit scarcity)
    if fitting_bins_count > 0 {
        let scarcity = 1.0 / fitting_bins_count as f64;
        score -= 4.0 * scarcity * fill;
    }

    // Mild penalty for proliferating bins early on
    score += (open_bins_count as f64).ln().max(0.0) * (1.0 - progress) * 0.3;

    // Tie-break toward mean residual convergence
    score += 0.1 * (pr - mean_residual).abs() / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: 2-step lookahead — reward bins whose post residual matches the next item size.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let post = post_residual as f64;
        if post >= next {
            let gap = post - next;
            // Perfect match: next item exactly fills the remaining space.
            if gap == 0.0 {
                score -= 60.0;
            } else {
                // Reward closeness of post_residual to next_item_size.
                score -= 40.0 * (1.0 - gap / bin_capacity as f64);
                // Penalize leaving a gap that is too small for anything useful (dead space).
                if gap < 10.0 {
                    score += 15.0;
                }
            }
        } else {
            // Next item cannot fit here; the leftover post_residual is likely dead space.
            score += 25.0 + (next - post);
        }
    } else {
        // Last item: prefer tightest fit overall.
        score += 5.0;
    }

    // Relative-to-mean coupling: prefer bins with residual below mean (tighter bins)
    // when they still fit well, penalize bins far above the mean (fragmentation).
    let mean = mean_residual;
    let post = post_residual as f64;
    if post < mean {
        score -= 8.0 * (mean - post) / bin_capacity as f64;
    } else {
        score += 6.0 * (post - mean) / bin_capacity as f64;
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin has post_residual == capacity - item_size.
    // Penalize opening a new bin mildly, unless current bin would leave heavy dead space.
    if bin_residual == bin_capacity {
        score += 20.0;
        // But if lookahead matches well in a fresh bin, soften the penalty.
        if next_item_size > 0 && (post_residual as f64 - next_item_size as f64).abs() < 5.0 {
            score -= 25.0;
        }
    }

    // Stream progression: later in the stream, be more conservative about wasting space
    // (dead-space penalty grows), since fewer chances remain to recover.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Many open bins: slight preference to consolidate into existing bins.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
