    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fill_ratio > 0.85 {
        score -= 30.0 * fill_ratio;
    } else if fill_ratio < 0.25 {
        // Penalize dumping a small item into a big residual, wasting flexibility.
        score += 12.0 * (0.25 - fill_ratio);
    }

    // Exact or near-exact closure is excellent.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        score -= 18.0;
    } else if post_residual < 20 {
        score -= 6.0;
    }

    // Lookahead coupling: if the next item fits the post-residual, reward;
    // if post-residual is awkward for the next item, penalize slightly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
            if post_residual - next_item_size < 10 {
                score -= 6.0; // chain closes nicely
            }
        } else if post_residual > 0 && next_item_size > post_residual {
            score += 4.0 * (next_item_size as f64 - post_residual as f64) / 100.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 + 0.1 * post_residual as f64;
    }

    // New-bin candidate handling: an empty bin is a fresh resource; prefer it only
    // when no open bin offers a decent fit or when open-bin residuals are large
    // and fragmented (many bins, high mean residual).
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let fragmentation = mean_residual / bin_capacity as f64;
        // Base cost of opening a bin, discounted late in the stream when leftover
        // items are few and fragmentation is high.
        let mut new_bin_cost = 55.0 - 25.0 * progress;
        if fragmentation > 0.6 && open_bins_count > 3 {
            new_bin_cost -= 12.0;
        }
        score += new_bin_cost;
        // Never let the empty bin win when the item closes an existing bin.
        if post_residual == 0 { score += 100.0; }
    } else {
        // Prefer using existing bins; mild bias toward bins with residuals near the mean
        // keeps residual spread tight (better future fits).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    // Slight preference for bins with smaller residuals overall (best-fit flavor).
    score += 0.05 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let x = pr / cap; // normalized post-residual in [0,1]

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = x * (1.0 + 1.5 * progress) - 0.8 * x * x * (1.0 - progress);

    // Reward tight fits: small post-residual penalized less when progress grows
    score -= 0.6 * (1.0 - x) * (1.0 - x) * (0.5 + progress);

    // Penalize dead space relative to mean residual across open bins
    score += 0.3 * ((pr - mean_residual) / cap) * (0.5 + progress);

    // Lookahead: reward leaving room for the next item
    let nxt = next_item_size as f64;
    if nxt > 0.0 {
        let gap = (pr - nxt) / cap;
        if gap >= 0.0 {
            score -= 0.5 * gap * (1.0 - gap);
        } else {
            score += 0.4 * (-gap) * (1.0 + progress);
        }
    }

    // Last-chance bin pressure: strongly favor the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 2.0 * (1.0 + progress);
    }

    // Mild penalty for spreading across many bins late in the stream
    score += 0.02 * open_bins_count as f64 * progress;

    // Small bonus for a new empty bin when current item is large and fits poorly elsewhere
    if bin_residual == bin_capacity {
        score -= 0.3 * (item_size as f64 / cap) * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // --- Tight fit reward: exponential decay of score as post_residual -> 0 ---
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 30.0 * tightness * tightness * tightness;

    // --- Harmonic class of post_residual (modulo 10 buckets) ---
    // Residuals in [0..10) are near-perfect; [10..20) still excellent;
    // mid classes (30..60) are "dead zone" waste; large residuals are fine.
    let r = post_residual;
    let class = r % 10;
    let bucket = r / 10;
    let class_bonus: f64 = match bucket {
        0 => 25.0 + (class as f64),          // 0..9 : golden class
        1 => 15.0,                            // 10..19: very good
        2 => 8.0,                             // 20..29: decent
        3 => -6.0,                            // 30..39: dead-zone start
        4 => -10.0,                           // 40..49: poor
        5 => -12.0,                           // 50..59: worst usable
        _ => 0.0,                             // >=60: essentially fresh bin
    };
    score -= class_bonus;

    // --- Harmonic coupling: does next item fit harmonically into post_residual? ---
    if next_item_size > 0 {
        let fits_next = next_item_size <= r;
        if fits_next {
            // Reward if next item lands in a good class with this residual
            let combo = r - next_item_size;
            if combo % 10 == 0 || combo <= 5 {
                score -= 18.0;
            } else if combo < 20 {
                score -= 10.0;
            } else if combo > 50 {
                score += 5.0;
            }
        } else {
            // Next item won't fit here; residual should ideally be near zero
            score += (r as f64) * 0.15;
            // Perfect harmonic: residual exactly matches a small "waste class"
            if r % 10 == 0 && r <= 20 {
                score -= 5.0;
            }
        }
    } else {
        // Last item: only tightness matters, slight extra reward
        score -= 5.0 * tightness;
    }

    // --- Last-chance bin: if this is the only fitting bin, strongly prefer using it ---
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin
        let mut new_bin_score = 55.0;
        // Discourage opening new bins early in the stream or when few bins open
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        new_bin_score += 20.0 * (1.0 - progress);
        new_bin_score += (open_bins_count as f64).min(10.0) * 2.0;
        // If mean residual across open bins is large, opening a new bin is wasteful
        new_bin_score += (mean_residual / cap) * 25.0;
        // If next item is large, a fresh bin is valuable
        if next_item_size >= 60 {
            new_bin_score -= 15.0;
        }
        score = score.max(new_bin_score) * 0.0 + new_bin_score;
    } else {
        // Mild global pressure: many open bins -> prefer consolidating
        score += (open_bins_count as f64) * 0.3;
        // Prefer bins whose residual deviates from mean in a useful (smaller) way
        let dev = (bin_residual as f64 - mean_residual) / cap;
        score += dev * 10.0;
    }

    // --- Integer-division threshold micro-tuning on post_residual ---
    if r / 7 == 0 { score -= 6.0; }        // r < 7: near-perfect harmonic
    if r >= 25 && r <= 35 { score += 8.0; } // hard-to-fill dead band

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 10.0 {
        // gap too small for any item (min size 1, but tiny gaps are waste) -> strong penalty
        score += (10.0 - pr) * 4.0;
    } else if pr == 0.0 {
        // perfect fit: big reward
        score -= 40.0;
    } else if pr < 20.0 {
        // moderately tight fit: mild reward
        score -= (20.0 - pr) * 1.5;
    }

    // Reward leaving room for the lookahead item if it fits.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
        // extra reward if next item exactly fills the remaining space
        if post_residual == next_item_size {
            score -= 15.0;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // gap cannot host the next item: mild penalty scaled by gap size
        score += 3.0;
    }

    // Last chance: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bins pressure: discourage scattering across many bins when
    // mean residual is already high; encourage compacting.
    if bin_residual < bin_capacity {
        let pressure = open_bins_count as f64 * (mean_residual / bin_capacity as f64);
        score += pressure * 0.3;
    } else {
        // new-bin candidate: only attractive when existing bins are crowded
        let avg_residual = mean_residual.max(1.0);
        let crowdedness = avg_residual / bin_capacity as f64; // high = bins nearly full
        score += 60.0 * (1.0 - crowdedness); // cheap to open new bin when bins are empty-ish
        score -= 20.0 * crowdedness * crowdedness; // attractive when bins nearly full
    }

    // Slight progression term: later in the stream, favor tighter packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (1.0 - pr / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack_after_next = post_residual - next_item_size;
        score -= 50.0 + (slack_after_next as f64) * 0.5;
        // exact chain fit (item + next fills bin)
        if slack_after_next == 0 {
            score -= 500.0;
        }
    } else if next_item_size > 0 {
        // penalize dead space that cannot host the next item, worse when large
        score += (post_residual as f64).min(next_item_size as f64) * 0.3;
    }

    // Prefer bins tighter than the mean residual (best-fit flavor)
    let diff = bin_residual as f64 - mean_residual;
    score += diff * 0.2;

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 200.0;
    }

    // New-bin candidate: penalize opening a new bin unless item is large
    if bin_residual == bin_capacity {
        score += 250.0 - (item_size as f64) * 1.5;
    }

    // Late in stream: consolidate more aggressively
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 30.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: minimize post_residual relative to bin capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 2.5 * tightness * (item_size as f64);

    // Penalize dead space that no future item (sizes >= 10... but unknown 1..100) can use.
    if post_residual > 0 && post_residual < item_size.min(60) {
        score += 8.0 * (1.0 - post_residual as f64 / 60.0);
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 20.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Lookahead coupling: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0 * (next_item_size as f64) / (bin_capacity as f64);
        } else {
            // Penalize blocking the next item slightly.
            score += 3.0 * (next_item_size as f64) / (bin_capacity as f64);
        }
    }

    // Global state: many open bins -> prefer consolidating into existing bins.
    let crowding = open_bins_count as f64 / (1.0 + total_items as f64 / 10.0);
    score += 5.0 * crowding * (bin_residual as f64 / bin_capacity as f64);

    // Mean residual coupling: if this bin is far from mean residual, slight penalty
    // (prefer bins consistent with global slack distribution).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Time horizon: early in stream, be more willing to open new bins (keep options open);
    // late in stream, pack tightly into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus progress-dependent penalty.
        score += 30.0 + 40.0 * progress;
        // If item is large relative to capacity, new bin is fine.
        if (item_size as f64) / (bin_capacity as f64) > 0.6 {
            score -= 10.0;
        }
    } else {
        // Existing bin: reward grows with progress for using it.
        score -= 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: post residual, smoothly warped by stream progress.
    // Late in the stream, small residuals matter more (dead space is permanent).
    let progress_warp = 1.0 + 1.5 * progress * progress;
    let mut score = pr * progress_warp;

    // Non-linear penalty on very tight fits: residual below ~15% of capacity
    // is likely unusable dead space. Smooth quadratic bowl around mid residuals.
    let dead = (norm_pr - 0.15).max(0.0);
    score += 30.0 * dead * dead * cap * progress;

    // Lookahead coupling: reward residuals that can still host the next item,
    // penalize residuals that neither fit it nor are near zero.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            // smooth reward proportional to how exactly the next item fits
            let fit_quality = 1.0 - ((pr - nxt) / cap).powf(2.0);
            score -= 12.0 * fit_quality * (0.5 + progress);
        } else {
            // residual can't fit next item: penalize proportionally to waste
            let waste = (nxt - pr) / cap;
            score += 8.0 * waste * waste * cap;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin (unless the fit is catastrophically wasteful).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        let waste_frac = pr / cap;
        let bonus = 25.0 * (1.0 - waste_frac * waste_frac);
        score -= bonus * (0.6 + 0.4 * progress);
    }

    // Mild penalty for leaving residual far from mean residual across open bins
    // (encourages balanced bin states, smooth quadratic coupling).
    let dev = pr - mean_residual;
    score += 0.05 * dev * dev / cap;

    // New-bin candidate: slightly penalize opening a new bin early,
    // more strongly when many open bins already exist.
    if bin_residual == bin_capacity {
        score += 5.0 + 2.0 * (open_bins_count as f64).sqrt() + 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into a
    // "reusable" class (large enough for typical small items) are favored.
    let pr = post_residual;
    let class: f64 = if pr == 0 {
        -8.0 // perfect fit, huge reward
    } else if pr >= 10 && pr <= 20 {
        -3.0 // leftover likely reusable by a small item
    } else if pr <= 9 {
        6.0 // dead space: too small for anything
    } else if pr <= 40 {
        -1.0
    } else if pr <= 60 {
        0.5
    } else {
        2.0
    };
    score += class * (cap / 100.0);

    // Integer-division thresholds: leftover divisible into common item sizes
    // (i.e., pr mod k == 0 for small k) is more likely to be exactly filled.
    if pr > 0 {
        let mut harmonicity = 0.0;
        for k in [10u32, 20, 25, 50] {
            if pr % k == 0 {
                harmonicity += 1.5;
            }
        }
        score -= harmonicity;
    }

    // Lookahead coupling: reward if next item exactly fills post_residual,
    // penalize if next item cannot use the leftover.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 10.0;
        } else if next_item_size <= pr {
            let waste = (pr - next_item_size) as f64;
            score -= 2.0 * (1.0 - waste / cap);
        } else {
            score += 1.5;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 7.0;
    }

    // New-bin candidate handling: only attractive early in the stream or when
    // open bins are nearly full on average; otherwise penalize opening a bin.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let freshness = (mean_residual / cap - 0.25).max(0.0);
        score = cap * (0.35 + 0.6 * freshness) - 12.0 * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 15.0; // nothing fits, must open
        }
    }

    // Mild pressure against spreading across many open bins.
    score += (open_bins_count as f64).sqrt() * 0.4;

    // Slight tie-break toward tighter fits as stream progresses.
    score += (post_residual as f64 / cap) * (step_index as f64 / (total_items.max(1) as f64)) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to ever fit the
    // smallest item (1..100 stream => anything under ~10 is likely waste)
    // are heavily penalized, quadratically.
    if post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64) * (10.0 - post_residual as f64) / 10.0;
    } else if post_residual < 20 {
        // Marginal zone: moderately discouraged gap sizes.
        score += 6.0 * (20.0 - post_residual as f64) / 10.0;
    }

    // Reward tight fits: the smaller the post_residual relative to capacity,
    // the better the packing density.
    let fill_ratio = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 12.0 * fill_ratio * fill_ratio;

    // Perfect or near-perfect fill bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Last-chance pressure: if this is the only bin that fits, strongly
    // prefer using it over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && post_residual < 10 {
        score += 30.0; // still not worth it if it creates dead space
    } else if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.6 * open_bins_count as f64 * (1.0 - 0.3 * progress);

    // Mean residual coupling: if this bin's residual is far below the mean,
    // it is already "dense" — favor finishing it off.
    let res_gap = mean_residual - post_residual as f64;
    score += 0.25 * res_gap;

    // Lookahead: if the next item fits exactly in the post-residual, reward
    // this placement (chain packing).
    if next_item_size > 0 && post_residual >= next_item_size {
        if post_residual == next_item_size {
            score -= 18.0;
        } else if post_residual - next_item_size < 10 {
            score -= 8.0;
        }
    }
    // If next item cannot fit the residual, this bin's leftover is more
    // likely to become dead space — mild penalty.
    if next_item_size > post_residual as u32 && post_residual > 0 {
        score += 4.0;
    }

    // New-bin candidate handling: an empty bin is a safe fallback with full
    // flexibility. Give it a moderate baseline so it wins only when open-bin
    // placements would create heavy dead space (their penalties above exceed
    // this baseline), but loses against any decent fit.
    if bin_residual == bin_capacity {
        score += 20.0 + 0.3 * open_bins_count as f64;
        // Late in the stream, opening fresh bins is cheaper than scattering.
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

