    }

    // Relative residual context: bins with residual far from the current
    // mean are less flexible; prefer bins near the mean residual.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: only attractive when no good fit exists elsewhere.
    if bin_residual == bin_capacity {
        // Penalize opening a new bin, but less when current bin's post
        // residual would be a large unusable gap.
        let gap_waste = if next_item_size > 0 && post_residual < next_item_size {
            post_residual as f64
        } else {
            0.0
        };
        score += 45.0 - 0.5 * gap_waste;
        // Early in stream, be more willing to open bins (diversification).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * (1.0 - progress);
    }

    // Mild preference to consolidate into fewer bins when many are open.
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fraction of stream completed
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer tight fits (low post_residual) — amplify quadratic waste penalty
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 25.0 * tightness * tightness;

    // Lookahead: reward bins whose post_residual can host the next item (k=2 lookahead)
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Perfect chain: penalize less (subtract) when post_residual == next_item_size exactly
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Post-residual too small for next item: penalize dead space proportionally
            let dead = post_residual as f64 / next_item_size as f64;
            score += 8.0 * dead.min(1.5);
        }
    } else {
        // Last item: purely minimize waste
        score -= 20.0 * tightness;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when existing
    // residuals are globally poor fits or when post_residual is very tight
    if bin_residual == bin_capacity {
        // New bin starts with large residual; penalize unless alternatives are bad
        let global_pressure = mean_residual / bin_capacity as f64;
        // If mean residual across open bins is small (bins nearly full), opening new bin is fine
        score += 40.0 * (1.0 - global_pressure);
        // Late in stream, slightly discourage proliferation of open bins
        score += 10.0 * progress * (open_bins_count as f64).ln().max(0.0);
        // But if item is huge relative to mean residual, new bin may be the only sane choice
        if (item_size as f64) > mean_residual {
            score -= 25.0;
        }
    } else {
        // Existing bin: reward spreading load when many open bins exist (balance residuals)
        let deviation = (bin_residual as f64 - mean_residual).abs();
        score += 4.0 * deviation / bin_capacity as f64;
        // Prefer bins closer to full (less residual) mildly
        score -= 3.0 * (1.0 - bin_residual as f64 / bin_capacity as f64);
    }

    // Mild time-horizon coupling: early in stream, be conservative (avoid many tiny slacks);
    // late in stream, prioritize exact fits aggressively
    let horizon = (1.0 - progress).max(0.05);
    score += 5.0 * horizon * tightness;
    score -= (1.0 - horizon) * 6.0 * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Smooth normalized post-residual and its powers
    let x = pr / cap;
    let x2 = x * x;
    let x3 = x2 * x;

    // Base: post residual, with non-linear dead-space penalty for mid-range gaps
    let mut score = pr as f64 * (1.0 + 2.0 * x - 3.0 * x2 + 1.5 * x3);

    // Stream-progress coupling: late in stream, tolerate small residuals more
    let prog_coupling = progress * (x2 * 30.0) - (1.0 - progress) * (x * 5.0);
    score += prog_coupling;

    // Tight fit reward: small post residual relative to item size
    let tight = 1.0 - x;
    score -= tight * item_size as f64 * 0.5;

    // Lookahead: bonus if next item fits into resulting residual
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 8.0 * (1.0 - (pr - next_item_size as f64) / cap);
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Mild penalty proportional to congestion, smoothed by mean residual
    score += (open_bins_count as f64).ln() * 0.5 + (mean_residual / cap) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Perfect fit: strong reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: bins whose leftover belongs to a
    // "reusable" residue class (small or common item sizes) are favored.
    let class = post_residual % 10;
    let class_bonus = match class {
        0 => 40.0,              // round leftover, very reusable
        1..=9 => (10 - class as f64) * 2.0, // smaller leftover mod 10 => better
        _ => 0.0,
    };
    score -= class_bonus;

    // Integer-division thresholds: leftover divisible by common sizes is good
    for d in [10u32, 20, 25, 50].iter() {
        if post_residual != 0 && post_residual % *d == 0 {
            score -= 15.0;
        }
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // next item fits: reward proportional to how tightly it fits
            score -= (post_residual - next_item_size) as f64 * 0.5 + 20.0;
        } else {
            // next item cannot use this leftover: penalize dead space mildly
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate handling: empty bin gets a moderate penalty so that
    // it is only chosen when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 120.0
            + mean_residual * 0.2
            + (open_bins_count as f64) * 5.0;
        // Late in the stream, prefer consolidation into open bins even more
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 80.0;
    }

    // Mild preference for tighter bins overall (waste fraction penalty)
    score += (post / cap) * 30.0;

    // Penalize bins whose residual deviates wildly from the mean (fragmentation)
    score += ((bin_residual as f64 - mean_residual).abs()) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead space avoidance: penalize small unusable gaps heavily.
    if post_residual > 0 {
        // Dead-space penalty: small nonzero residuals are far worse than large ones.
        if post_residual < 10 {
            score += 60.0; // tiny unusable sliver
        } else if post_residual < 20 {
            score += 25.0;
        } else if post_residual < 30 {
            score += 8.0;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Reward residuals that can still fit the lookahead item (avoid blocking next_item_size).
    if next_item_size > 0 {
        if post_residual >= next_item_size as f64 {
            score -= 12.0;
        } else {
            score += 10.0; // residual becomes dead space w.r.t. next item
        }
    }

    // Open-bin pressure: penalize spreading across many bins slightly.
    score += open_bins_count as f64 * 0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Mild preference for tighter bins overall (below mean residual is good).
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // Late in stream: consolidate more aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward near-perfect fits (small post_residual).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 10 {
        score -= 50.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches next item size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        let diff = (pr - nxt).abs();
        // Exact chain fit: next item fills this bin perfectly.
        if diff < 1.0 && pr >= nxt {
            score -= 400.0;
        } else if pr >= nxt {
            // Next item fits in leftover: scale reward by closeness of match.
            score -= 150.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Next item won't fit: penalize proportionally to wasted gap.
            score += 40.0 * (nxt - pr) / nxt.max(1.0);
        }
    }

    // Penalize bins that are much emptier than average (fragmenting space),
    // unless it's the fresh-bin candidate.
    if bin_residual < bin_capacity {
        score += 0.5 * (mean_residual - bin_residual as f64).max(0.0);
    }

    // Last-chance bin: if this is the only fitting bin, prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // Mild preference to fill already-open bins as stream progresses.
    if bin_residual < bin_capacity {
        score -= 0.2 * (step_index as f64 / total_items.max(1) as f64) * 100.0;
    }

    // New-bin candidate: make it unattractive unless current bin would leave
    // a large unusable gap and next item doesn't chain well.
    if bin_residual == bin_capacity {
        score += 250.0;
        if next_item_size > 0 && (post_residual as f64 - next_item_size as f64).abs() < 1.0 {
            score -= 500.0; // fresh bin perfectly chains with next item
        }
        if fitting_bins_count == 0 {
            score -= 600.0; // nothing fits anywhere: new bin is required
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins whose post residual is small.
    let cap = bin_capacity as f64;
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 12.0 * tightness * tightness;

    // Perfect-fit bonus: exact fill is always ideal.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    // Penalize dead space: residuals too small for the smallest plausible item (1..100 unknown,
    // so treat small residuals < item_size-like scale as risky unless near-perfect).
    if post_residual > 0 && post_residual < item_size {
        score += 6.0 + 0.15 * (post_residual as f64);
    }

    // Lookahead coupling: if the next item can fit into the post residual, reward; otherwise penalize.
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 8.0;
            // chain fit: next item then nearly fills too
            let chain = post_residual as u32 - next_item_size;
            if chain <= 10 {
                score -= 6.0;
            }
        } else {
            score += 4.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate logic: empty bin should only win when fits are poor.
    if bin_residual == bin_capacity {
        // Opening a new bin is expensive: penalize it, scaled by how many bins already fit the item
        // and how good the best fit likely is (approximated by mean residual).
        score += 25.0;
        if fitting_bins_count > 0 {
            score += 15.0 + 5.0 * (fitting_bins_count as f64).ln();
        }
        // Early in the stream, opening bins is cheaper (build a portfolio); late, avoid it.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * (1.0 - progress);
        // If mean residual across open bins is large, existing bins are roomy; no need for new bin.
        score += 0.2 * mean_residual;
    }

    // Mild preference for filling bins that are already relatively full (reduce bin spread).
    let fill_ratio = 1.0 - (bin_residual as f64) / cap;
    score -= 5.0 * fill_ratio;

    // Slight penalty for accumulating many open bins with large residuals (fragmentation).
    if open_bins_count > 4 && mean_residual > 30.0 && post_residual > 30 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit_frac = pr / cap;

    // Base: penalize leftover space, with a convex (squared) coupling so
    // large dead space is punished disproportionately.
    let mut score = pr + 60.0 * fit_frac * fit_frac * cap;

    // Stream-progress coupling: early in the stream, keep bins flexible
    // (mildly favor mid residuals); late, squeeze tightly (amplify waste penalty).
    let late = progress * progress;
    score += late * 80.0 * fit_frac;
    score -= (1.0 - progress) * 12.0 * (1.0 - (2.0 * fit_frac - 1.0) * (2.0 * fit_frac - 1.0));

    // Perfect/near-perfect fill reward (smooth, no hard threshold).
    let tightness = 1.0 - fit_frac;
    score -= 25.0 * tightness * tightness * tightness * (0.5 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 40.0 + 30.0 * progress;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement;
    // otherwise penalize slightly (dead space that blocks the next item).
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr >= ni {
            score -= 10.0 * (1.0 - (pr - ni) / cap);
        } else {
            score += 8.0 * (ni - pr) / cap;
        }
    }

    // Mean-residual coupling: if this bin's residual deviates far below the
    // mean (already fragmented), penalize; balanced bins are preferred.
    score += 0.15 * (mean_residual - pr).abs();

    // New-bin candidate: empty bin gets a moderate penalty so it only wins
    // when no open bin offers a decent fit (score above ~ small residual).
    if bin_residual == bin_capacity {
        score = cap as f64 * (1.1 - 0.35 * progress) + 0.2 * mean_residual;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the resulting residual: residuals divisible by 10 are
    // "harmonic" and more reusable by future items.
    let class = (post_residual % 10) as f64;
    score += class * 1.5;

    // Integer-division thresholds: small post_residual buckets are dead space.
    if post_residual < 10 {
        score -= 8.0; // perfect fill, excellent
    } else if post_residual < 20 {
        score -= 3.0;
    } else if post_residual < 30 {
        score += 1.0;
    } else if post_residual > 50 {
        score += 2.5; // large leftover, wasteful placement
    }

    // Lookahead coupling: if next item fits exactly into post_residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 12.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 4.0 * (1.0 - slack / cap);
        } else {
            // next item cannot use this bin's remainder: mild penalty scaled by mismatch
            score += ((next_item_size - post_residual) as f64).min(30.0) * 0.1;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 6.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // relative to typical residuals (harmonic fraction of capacity).
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / cap;
        score += 15.0;
        if frac > 0.6 {
            score -= 18.0; // big items deserve fresh bins
        }
        if open_bins_count == 0 {
            score -= 20.0;
        }
    }

    // Prefer tighter bins among open ones (relative fill pressure).
    let tightness = 1.0 - (bin_residual as f64) / cap;
    score -= tightness * 3.0;

    // Mean-residual coupling: when mean residual is small, conserve remaining space.
    score += (mean_residual - post_residual as f64).max(0.0) * 0.05;

    // Late-stream tie-breaker: pack more aggressively as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residual gaps too small for the minimum
    // item are pure waste — penalize them heavily.
    let min_item = 1u32;
    if post_residual < min_item {
        score -= 1000.0; // perfect fit, no dead space at all
    } else if post_residual < 10 {
        score += 40.0 * (10 - post_residual) as f64; // unusable sliver
    }

    // Reward exact/near-exact fits progressively (tight packing bonus).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Dead-space penalty scaled by how much of the bin is now wasted.
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    if waste_frac > 0.0 && waste_frac < 0.35 {
        score += 60.0 * (0.35 - waste_frac); // small-but-usable gaps are risky
    }

    // Open-bin pressure: prefer spreading load when many bins are open,
    // but discourage opening new bins (empty-bin candidate gets a surcharge).
    if bin_residual == bin_capacity {
        // New bin: only attractive when current item barely fits elsewhere
        // or fitting options are scarce.
        let scarcity = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        score += 30.0 * scarcity + 0.5 * open_bins_count as f64;
        // If next item is large and this item is small, new bin is fine.
        if next_item_size > 60 && item_size < 30 {
            score -= 20.0;
        }
    } else {
        // Existing bin: mild reward when it is the last chance.
        if fitting_bins_count == 1 {
            score -= 15.0;
        }
        // Prefer bins with residuals close to what's needed (best-fit core),
        // with slight bias toward fuller bins under high open-bin count.
        let pressure = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
        score -= pressure * (bin_residual as f64 - post_residual as f64) * 0.1;
    }

    // Lookahead: if the next item fits exactly in post_residual, reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        if slack < 10.0 {
            score -= 30.0 - 2.0 * slack; // chain a perfect follow-up
        }
    } else if next_item_size > post_residual && post_residual < 10 {
        score += 15.0; // dead space blocks the lookahead item too
    }

    // Slight time decay: early on, be more conservative with new bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact/near-exact fits (waste minimization).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // Aggressive 2-step lookahead: strongly reward bins whose post_residual
    // exactly matches the next item size (perfect chaining).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // Next item fits here afterwards: mild reward scaled by slack.
            let slack = (post_residual - next_item_size) as f64;
            score -= 60.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot use the leftover: penalize dead space creation.
            let dead = (next_item_size - post_residual) as f64;
            score += 40.0 * (dead / 100.0);
        }
    }

    // Relative-to-mean coupling: prefer bins tighter than the average residual.
    let diff = mean_residual - bin_residual as f64;
    score += 0.5 * diff;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // Penalize opening new bins when open bins exist and fit is decent.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 120.0;
    }

    // Late-stream bias: consolidate more aggressively as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post-residual is good).
    score += (post_residual as f64 / bin_capacity as f64) * 60.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 200.0;
    } else {
        // Penalize dead space that no future item can plausibly use.
        let t = step_index as f64 / (total_items.max(1) as f64);
        let min_size = 1.0f64;
        if (post_residual as f64) < min_size {
            score -= 50.0;
        }
        // Waste that is smaller than typical items is likely unusable.
        if post_residual > 0 && post_residual < 10 {
            score += 25.0;
        }
        // Late in the stream, compact bins more aggressively.
        score += t * 20.0;
    }

    // Lookahead coupling: if next item fits in post-residual, reward heavily.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 45.0 + 0.5 * next_item_size as f64;
        } else {
            // Leaving a gap that blocks the next item is costly, but only mildly
            // if the gap is tiny anyway.
            score += 15.0;
        }
        // Chain fit: next item exactly fills leftover space.
        if next_item_size == post_residual && post_residual > 0 {
            score -= 120.0;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // Prefer fuller bins relative to the fleet mean.
    score += (mean_residual - bin_residual as f64) * 0.8;

    // Mild preference for keeping the number of open bins small.
    score += open_bins_count as f64 * 0.5;

    // New-bin candidate handling: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = 100.0;
        // If existing fitting options are scarce, new bin becomes competitive.
        if fitting_bins_count == 0 {
            score -= 150.0;
        } else if fitting_bins_count == 1 {
            score -= 30.0;
        }
        // Early in the stream, opening bins is cheaper (future items can fill them).
        let t = step_index as f64 / (total_items.max(1) as f64);
        score -= (1.0 - t) * 40.0;
        // Lookahead: if next item is large, a fresh bin has good future use.
        if next_item_size > 60 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual

    // Base: penalize large wasted residual, with a non-linear (quadratic/cubic) shaping
    let mut score = x * (1.0 + 1.7 * x + 0.9 * x * x) * cap * 0.01;

    // Smooth stream-progress coupling: late in the stream, waste matters more
    score += 2.5 * progress * x * x * cap * 0.01;

    // Tight fit reward: non-linear bonus when post residual is small
    score -= 6.0 * (1.0 - x).powi(3);

    // Lookahead: if next item fits into post residual, reward this bin
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        if (next_item_size as f64) <= pr {
            score -= 3.0 * nx * (1.0 - progress);
        } else {
            score += 1.5 * nx * (1.0 - nx) * (1.0 - progress);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 4.0 + 3.0 * progress;
    }

    // Mean residual context: prefer bins whose post residual stays near the mean
    let dev = (pr - mean_residual) / cap;
    score += 1.2 * dev * dev * cap * 0.01;

    // New-bin candidate handling: penalize opening a new bin when it wastes potential,
    // but allow it when current bin would leave a very awkward residual
    if bin_residual == bin_capacity {
        score += 1.0 + 2.0 * (1.0 - progress);
        if fitting_bins_count > 0 && (item_size as f64) / cap > 0.5 {
            score += 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: items 1..100, capacity 100.
    // Class A: post_residual <= 10  -> near-perfect fill, heavily reward.
    // Class B: 11..25              -> still usable by small items.
    // Class C: 26..50              -> mid dead space.
    // Class D: >50                 -> wasteful split, penalize.
    if post_residual <= 10 {
        score -= 18.0;
    } else if post_residual <= 25 {
        score -= 6.0;
    } else if post_residual <= 50 {
        score += 4.0;
    } else {
        score += 14.0;
    }

    // Modulo arithmetic on post_residual: residuals that are multiples of
    // common item sizes (10, 20, 25, 50) are "harmonic" and more likely to
    // be exactly filled by a future item.
    if post_residual > 0 {
        let pr = post_residual;
        if pr % 10 == 0 { score -= 3.0; }
        if pr % 25 == 0 { score -= 2.0; }
        if pr % 50 == 0 { score -= 2.5; }
        // Odd, non-harmonic residuals tend to become dead space.
        if pr % 2 == 1 && pr < 30 { score += 2.0; }
    }

    // Lookahead coupling: does next_item_size fit into the post_residual?
    // If yes, reward (chain fill); if next item almost fits, mild penalty.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 5.0;
            // Exact harmonic match: next item exactly consumes leftover.
            if next_item_size == post_residual {
                score -= 12.0;
            }
            // Next item leaves a small remainder again -> good chain.
            let nr = post_residual - next_item_size;
            if nr <= 10 { score -= 3.0; }
        } else if next_item_size > post_residual && next_item_size <= post_residual + 10 {
            score += 3.0; // tantalizing near-miss, likely dead space
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: an empty bin has large post_residual,
    // which already scores high via the class-D penalty. Add extra bias so
    // a new bin is only chosen when all open bins are truly bad fits.
    if bin_residual == bin_capacity {
        score += 8.0 + 0.05 * open_bins_count as f64;
        // Late in the stream, opening bins is cheaper (fewer future items
        // to fill them), so soften the penalty.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * progress;
    }

    // Prefer filling bins with low mean residual (aging bins) to close them out.
    if bin_residual < bin_capacity {
        let deficit = (mean_residual - bin_residual as f64).abs();
        score -= 0.02 * deficit;
    }

    // Integer-division threshold: reward placements where item fills at
    // least half of the bin's current residual.
    if item_size * 2 >= bin_residual {
        score -= 4.0;
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.15 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size are pure waste.
    let min_item = 1u32;
    if post_residual < min_item {
        score -= 50.0; // perfect fill, reward heavily
    } else if post_residual <= 10 {
        // tiny gap likely unusable -> strong penalty on top of base residual
        score += (11 - post_residual) as f64 * 8.0;
    } else if post_residual <= 20 {
        score += (21 - post_residual) as f64 * 2.5;
    }

    // Reward leaving room for the lookahead item (k=2 lookahead).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
            // bonus scaled by how snugly the next item fits
            let slack = (post_residual - next_item_size) as f64;
            score -= (10.0 / (1.0 + slack)).min(4.0);
        } else {
            // next item can't fit here; penalize proportionally to wasted lookahead potential
            let miss = (next_item_size - post_residual) as f64;
            score += (miss / 20.0).min(5.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; prefer tighter bins.
    let open_pressure = (open_bins_count as f64).ln().max(0.0);
    score += open_pressure * 1.5;

    // Prefer bins tighter than the mean residual (compactness coupling).
    score += (mean_residual - bin_residual as f64) * 0.4;

    // Mild early-stream preference for keeping bins open (flexibility), later stream compaction.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= (1.0 - progress) * 3.0;

    // Slight preference for filling larger fraction of the bin.
    score -= (item_size as f64 / bin_capacity as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item -> huge reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 50.0;
    }

    // Dead space: post_residual too small for the next item (wasted unless later items fit).
    if next_item_size > 0 && post_residual < next_item_size {
        // Penalize proportionally to how close-but-insufficient the leftover is.
        let gap = (next_item_size - post_residual) as f64;
        score += gap * 0.5;
        // Very small unusable residue is pure dead space.
        if post_residual < 10 {
            score += 15.0;
        }
    }

    // Reward post_residual large enough to hold the next item with room to spare,
    // scaled by how much slack remains relative to mean residual across bins.
    if next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= slack * 0.15;
    }

    // Compare post_residual against the mean residual: leaving this bin far below
    // average residual means it is being "filled well" -> reward.
    score -= (mean_residual - post_residual as f64) * 0.1;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Penalize creating tight fits that leave < 10 (minimum item size) unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Late in the stream, prefer closing bins tightly (small post_residual valued more).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.2;

    // New-bin candidate: make it unattractive unless existing fits are bad.
    if bin_residual == bin_capacity {
        score += 8.0;
        // But early in the stream, opening bins is cheap and helps spread items.
        if progress < 0.3 {
            score -= 6.0;
        }
        // If next item is huge relative to typical residual, new bin may be fine.
        if next_item_size > 0 && (next_item_size as f64) > mean_residual {
            score -= 4.0;
        }
    }

    // Mild penalty when many bins are open (encourage consolidation).
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic penalty reduction for small post_residual.
    let tight = post_residual as f64 / bin_capacity as f64;
    score += 12.0 * tight * tight;

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 5 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 10.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; mildly penalize leaving large unusable gaps.
            let gap = (next_item_size - post_residual) as f64;
            if gap < 20.0 {
                score += 0.4 * gap;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when open bins have poor fits.
    if bin_residual == bin_capacity {
        // Base reluctance to open new bins grows with number of open bins.
        score += 15.0 + 2.0 * open_bins_count as f64;
        // If existing bins are quite full (small mean residual), opening fresh is fine.
        if mean_residual < 15.0 {
            score -= 25.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
        // If item is large, a fresh bin is a reasonable home.
        if item_size > bin_capacity / 2 {
            score -= 8.0;
        }
    }

    // Penalize bins whose residual deviates strongly below mean (fragmented bins).
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score += 0.15 * dev;
    }

    // Slight preference for filling fuller bins first.
    score -= 0.1 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap; // normalized post residual in [0,1]

    // Base: prefer small post residual, with a smooth non-linear penalty
    // on very large residuals (dead space), scaled by stream progress.
    let mut score = pr * (1.0 + 0.6 * progress);

    // Non-linear coupling: dead-space penalty grows quadratically with
    // normalized residual and with progress (late in the stream, big
    // leftover space is more wasteful).
    score += 40.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits: post residual near zero gets a smooth bonus.
    let tightness = (1.0 - norm_pr).powi(3);
    score -= 30.0 * tightness;

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoiding opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 20.0 * progress;
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // reward this placement strongly (smooth interaction).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        let fit_quality = 1.0 - (gap / cap).min(1.0);
        score -= 18.0 * fit_quality * fit_quality;
    }

    // New-bin candidate handling: only attractive when open bins are
    // crowded (mean residual low relative to item) or late in stream.
    if bin_residual == bin_capacity {
        let crowding = (mean_residual / cap).clamp(0.0, 1.0);
        // Penalize new bins when open bins still have usable space.
        score += 60.0 * (1.0 - progress) + 45.0 * crowding;
        // Mild attractiveness late in stream when bins are nearly full.
        score -= 15.0 * progress * (1.0 - crowding);
    }

    // Mild preference to fill bins among many open bins (consolidation),
    // smoothly coupled with progress.
    score -= 3.0 * (open_bins_count as f64).ln().max(0.0) * (0.3 + 0.7 * progress) * (1.0 - norm_pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: how "clean" is the residual?
    // Residuals that are exact multiples of small divisors (harmonic classes)
    // are more likely to be filled by future items.
    let pr = post_residual;
    let mut harmony_bonus = 0.0;
    if pr > 0 {
        if pr % 10 == 0 { harmony_bonus += 6.0; }
        else if pr % 5 == 0 { harmony_bonus += 3.0; }
        else if pr % 2 == 0 { harmony_bonus += 1.0; }
        // penalize awkward residuals in dead zones
        if pr < 10 { harmony_bonus -= 8.0; }
        else if pr < 20 { harmony_bonus -= 3.0; }
    } else {
        // perfect fit: strongly reward
        harmony_bonus += 25.0;
    }
    score -= harmony_bonus;

    // Integer-division thresholds on next_item_size: does the leftover
    // accommodate the lookahead item within a harmonic class?
    if next_item_size > 0 && next_item_size <= pr {
        let nxt = next_item_size;
        if pr % nxt == 0 || nxt % 10 == 0 {
            score -= 10.0; // lookahead fits harmonically
        } else if pr - nxt < 10 {
            score += 4.0; // lookahead fits but leaves dust
        } else {
            score -= 3.0;
        }
    } else if next_item_size > pr && next_item_size > 0 {
        // lookahead cannot use this bin's leftover: mild penalty scaled by gap
        score += ((next_item_size - pr) as f64) * 0.08;
    }

    // Last-chance bin: avoid opening a new bin if this is the only fitter
    if fitting_bins_count == 1 && pr > 0 {
        score -= 12.0;
    }

    // New-bin candidate handling: empty bin gets a baseline that makes it
    // attractive only when open bins would create bad dead space.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // cost of a new bin declines slightly late in the stream
        score = cap * 0.62 - 8.0 * progress;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 6.0; // pair the next two items together in a fresh bin
        }
        if fitting_bins_count == 1 && post_residual > 0 && post_residual < 15 {
            score += 20.0; // don't abandon the last fitter for a fresh bin
        }
        return score;
    }

    // Fill-rate coupling: reward bins whose residual after placement is a
    // large fraction of capacity used (dense packing).
    let fill = (bin_capacity - post_residual) as f64 / cap;
    score -= fill * 5.0;

    // Mean-residual alignment: prefer bins whose post residual sits near the
    // open-bin mean (keeps the residual distribution homogeneous and reusable).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Many open bins: discourage spreading, favor tightening existing bins.
    if open_bins_count > 4 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< 10) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Reward tightness relative to residual: waste ratio penalty.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score += (1.0 - fit_ratio) * 15.0;

    // Pressure on number of open bins: discourage spreading items.
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New empty bin candidate: penalize so it is only chosen when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 45.0;
        // Late in the stream, opening a new bin is less costly; relax the penalty.
        score -= 25.0 * (step_index as f64 / total_items as f64);
    }

    // Lookahead: if the next item fits exactly into the post residual, reward this placement.
    if next_item_size > 0 && post_residual > 0 && next_item_size == post_residual {
        score -= 50.0;
    } else if next_item_size > 0 && next_item_size > post_residual && next_item_size <= post_residual + 10 {
        score += 20.0; // next item would leave this residual unusable anyway
    }

    // Mean residual coupling: prefer bins close to the mean residual (balanced usage).
    score += (bin_residual as f64 - mean_residual).abs() * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits, but weight residual relative to mean residual of open bins.
    score += 0.35 * (post_residual as f64 - mean_residual);

    // 2-step lookahead: reward if next item fits exactly/well into post_residual,
    // penalize dead space the next item cannot use.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            // Perfect chaining: this bin will be closed by the next item.
            score -= 25.0;
        } else if next_item_size < post_residual {
            let leftover = post_residual - next_item_size;
            // Reward usable chain, scaled by how little waste remains after next item.
            score -= 12.0 * (1.0 - leftover as f64 / bin_capacity as f64);
        } else {
            // Next item cannot follow: post_residual risks becoming dead space.
            let unusable = (post_residual as f64).min(next_item_size as f64 - post_residual as f64);
            score += 0.6 * unusable;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate handling: make an empty bin attractive only when current bins
    // would leave large unusable fragments or the fit is poor.
    if bin_residual == bin_capacity {
        // Empty bin: neutral residual baseline; slight penalty so it's chosen only
        // when existing bins score badly (poor fit / dead space).
        score += 6.0;
        if next_item_size > 0 && next_item_size <= item_size {
            // A fresh bin can serve both current and next item nicely.
            score -= 4.0;
        }
        // Late in the stream, prefer closing existing bins over spawning new ones.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    } else {
        // Existing bin with very tight fit (post_residual small) is great.
        if post_residual <= 5 {
            score -= 6.0;
        }
    }

    // Mild penalty for spreading across many open bins when a tight option exists.
    if open_bins_count > 4 {
        score += 0.05 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Tight-fit reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // Penalize small leftover slivers (dead space) non-linearly.
    if post > 0.0 && post < 10.0 {
        score += 25.0 * (10.0 - post) / 10.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let gap = post - nxt;
            if gap < 5.0 {
                score -= 20.0;
            } else {
                score -= 8.0 * (1.0 - gap / cap);
            }
        } else {
            // Next item won't fit here; mildly penalize wasting a good bin.
            score += 4.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: prefer reusing open bins unless they fit poorly.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut penalty = 12.0 + 10.0 * (1.0 - fill_ratio);
        // Late in the stream, opening new bins is cheaper than fragmenting.
        penalty *= 1.0 - 0.5 * progress;
        // If open bins are crowded with residual, a new bin is more attractive.
        penalty -= 3.0 * (mean_residual / cap);
        if open_bins_count == 0 {
            penalty = 0.0;
        }
        score += penalty;
    }

    // Mild preference for bins below mean residual (consolidate emptier bins).
    if bin_residual < bin_capacity {
        score += 0.05 * (bin_residual as f64 - mean_residual);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits, penalized non-linearly as post_residual grows.
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, small residuals are fine; late in the stream, chase tighter fits harder.
    let tightness = 1.0 - norm_pr;
    score -= 12.0 * tightness * tightness * (0.3 + 0.7 * progress);

    // Penalize post_residual that is "almost useful" but likely dead space:
    // a smooth bump around mid-range residuals.
    score += 6.0 * (norm_pr * (1.0 - norm_pr) * 4.0 - 0.75).abs() * (1.0 - progress);

    // Lookahead coupling: reward a residual that fits the next item smoothly.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        let fits_next = if pr >= ni { 1.0 } else { pr / ni };
        score -= 8.0 * fits_next * fits_next * (1.0 - 0.5 * progress);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + 0.5 * progress);
    }

    // Mild crowding penalty: with many open bins, avoid spreading waste.
    score += 0.3 * open_bins_count as f64 * norm_pr;

    // New-bin candidate: make empty bins attractive only when they beat bad fits,
    // but slightly discourage opening bins early in the stream.
    if bin_residual == bin_capacity {
        score += 2.0 + 10.0 * (1.0 - progress) * (1.0 - progress);
        if mean_residual > 0.0 {
            score -= 3.0 * (mean_residual / cap).tanh();
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residuals divisible by common item
    // size classes (10, 20, 25, 50) are more reusable -> reward them.
    if post_residual > 0 {
        if post_residual % 10 == 0 {
            score -= 6.0;
            if post_residual % 50 == 0 {
                score -= 6.0; // perfectly harmonic residual (50, 100)
            } else if post_residual % 25 == 0 {
                score -= 3.0;
            }
        } else if post_residual % 5 == 0 {
            score -= 2.0;
        } else {
            // awkward residual, penalize non-harmonic dead space
            score += 4.0;
        }
    } else {
        score -= 20.0; // perfect fill
    }

    // Integer-division thresholds: residual large enough to host a
    // mid-size item is valuable.
    if post_residual >= 50 {
        score -= 5.0;
    } else if post_residual >= 25 {
        score -= 2.0;
    } else if post_residual < 10 && post_residual > 0 {
        score += 6.0; // dead space below the minimum item size
    }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.5;
            // harmonic bonus if next item divides residual
            if post_residual % next_item_size.max(1) == 0 {
                score -= 4.0;
            }
        } else {
            // next item cannot use this residual: mild penalty scaled by waste
            score += (next_item_size - post_residual).min(20) as f64 * 0.3;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new one (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: neutral-ish baseline; opening a new bin
    // is only attractive when existing residuals are all poor fits.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 0.75 + (open_bins_count as f64).sqrt() * 2.0;
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
        if next_item_size > 0 && next_item_size <= bin_capacity / 2 {
            score -= 5.0;
        }
    }

    // Late in the stream, prefer consolidating into few bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 3.0;
    score += (open_bins_count as f64) * 0.05;

    // Slight pull toward bins with residuals near the mean (balanced packing).
    score += ((post_residual as f64) - mean_residual).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small for any plausible
    // future item are pure waste. Penalize them super-linearly.
    let gap = post_residual as f64;
    if gap > 0.0 {
        if gap < 10.0 {
            // Unusable sliver (smallest item is 10): heavy penalty.
            score += 60.0 * (10.0 - gap);
        } else {
            // Usable but large gaps get a mild super-linear penalty so we
            // prefer compact residual profiles over sprawling ones.
            score += 0.05 * gap * gap / bin_capacity as f64;
        }
    }

    // Reward tight fits (small post_residual relative to bin capacity).
    let tightness = 1.0 - gap / bin_capacity as f64;
    score -= 30.0 * tightness * tightness;

    // Perfect fit: strongly favored.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // using it avoids opening a new bin. Strong reward.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin is a fresh resource. Prefer
    // reusing open bins unless the fit is poor. Penalize opening a new bin
    // when open bins exist with decent residual space.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin grows with the number of open bins
        // (pressure to consolidate) but shrinks when no open bin fits well.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 + 8.0 * (open_bins_count as f64).sqrt() + 10.0 * progress;

        // If other bins can fit the item, opening a new bin is usually worse.
        if fitting_bins_count > 0 {
            score += 35.0;
        }
        // If the next item is large, a fresh bin may still be valuable.
        if next_item_size > 0 && next_item_size as f64 > mean_residual {
            score -= 15.0;
        }
    } else {
        // Reusing an existing bin: reward proportional to consolidation need.
        score -= 2.0 * (open_bins_count as f64).ln().max(0.0);
    }

    // Lookahead: if the next item would fit exactly into the resulting
    // residual, this placement is excellent.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    } else if next_item_size > 0 && (next_item_size as f64) <= gap {
        score -= 8.0;
    }

    // Slight preference for bins whose residual deviates from the mean in a
    // controlled way: prefer placing into below-average-residual bins to
    // keep a spread of gap sizes for future odd items.
    score += 0.1 * (mean_residual - bin_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Next item fits perfectly after this placement (post_residual == next + something small handled above);
    // next item fits into the post residual: reward proportionally to how tight it is.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item cannot follow in this bin: penalize dead space that blocks lookahead.
        score += 15.0 * (post_residual as f64) / bin_capacity as f64;
    }

    // Penalize large post residuals relative to mean residual across open bins (wasteful fit).
    if post_residual as f64 > mean_residual {
        score += 0.5 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.3 * (mean_residual - post_residual as f64);
    }

    // Last-chance bin: strongly reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: make it attractive only when current bin fit is poor or lookahead is blocked.
    if bin_residual == bin_capacity {
        let poor_fit = (post_residual as f64) > 0.5 * bin_capacity as f64;
        let lookahead_blocked = next_item_size > 0 && post_residual < next_item_size;
        if poor_fit || lookahead_blocked {
            score -= 30.0;
        } else {
            score += 50.0; // discourage opening new bins when a good fit exists
        }
    }

    // Late in stream: consolidate harder, prefer filling existing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: reward small post_residual nonlinearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Penalize dead space that cannot fit the next item (lookahead coupling).
    if next_item_size > 0 {
        if post_residual > 0 && (post_residual as u32) < next_item_size {
            score += 12.0 * (next_item_size as f64 - post_residual as f64);
        } else if (post_residual as u32) >= next_item_size {
            score -= 6.0; // this bin can still host the next item
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else {
        // Many alternatives: mildly penalize wasting this bin's space.
        score += 2.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Global pressure: many open bins -> consolidate; few bins -> spreading is ok.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = open_bins_count as f64 / (mean_residual.max(1.0) / bin_capacity as f64).max(0.5);
    score += 0.05 * pressure * (1.0 + progress);

    // Align with mean residual: prefer bins whose residual is below average (already tight).
    score += 0.3 * (post_residual as f64 - mean_residual).max(0.0);

    // New-bin candidate: only attractive when item is large relative to typical residuals
    // or no decent fit exists (large post_residual on new bin = full capacity available).
    if bin_residual == bin_capacity {
        let item_frac = item_size as f64 / bin_capacity as f64;
        let mean_frac = mean_residual / bin_capacity as f64;
        // Prefer new bin when item is big and existing residuals are small (poor fits).
        let new_bin_bonus = 30.0 * item_frac * (1.0 - mean_frac) - 20.0 * (1.0 - item_frac) * mean_frac;
        score -= new_bin_bonus;
        // Late in stream, discourage opening new bins to consolidate.
        score += 15.0 * progress;
    }

    // Small penalty for leaving very small unusable slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post = post_residual as f64;
    let cap = bin_capacity as f64;

    // Smooth non-linear coupling of post_residual with stream progress
    let progress_weight = 0.5 + 1.5 * progress * (1.0 - progress) * 4.0;
    let mut score = post * (1.0 + 0.35 * progress_weight * (post / cap));

    // Penalize large post residuals more aggressively as stream progresses
    score += 0.8 * progress * post * post / cap;

    // Reward tight fits (small post residual) with a smooth quadratic bonus
    score -= 12.0 * (1.0 - (post / cap)).powi(3);

    // Last-chance bonus: strongly favor this bin when it's the only fitting one
    if fitting_bins_count == 1 {
        score -= 8.0 + 4.0 * progress;
    }

    // Lookahead: reward if next item fits smoothly into post residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let slack = (post - nxt) / cap;
            score -= 3.0 * (1.0 - slack) * (1.0 - progress * 0.5);
        } else {
            score += 2.0 * (nxt - post) / cap;
        }
    }

    // Mild penalty for spreading residual far from the mean across bins
    score += 0.05 * (post - mean_residual).abs();

    // Slight preference for keeping fewer open bins early on
    score += 0.02 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues modulo small integers
    // capture "nice" leftover sizes that future items can pair with.
    let pr = post_residual as i64;
    let r8 = pr % 8;
    let r10 = pr % 10;
    let r20 = pr % 20;

    // Reward post-residuals that are harmonically aligned (multiples / near multiples)
    if r8 == 0 { score -= 6.0; }
    if r10 == 0 { score -= 5.0; }
    if r20 == 0 { score -= 4.0; }
    if r8 == 1 || r8 == 7 { score += 3.0; } // awkward slivers
    if pr > 0 && pr < 10 { score += 8.0; }  // dead space penalty

    // Integer-division threshold on post_residual: quarter classes of capacity
    let q = post_residual / (bin_capacity / 4);
    match q {
        0 => score -= 2.0,  // very tight fit, great
        1 => score -= 1.0,  // quarter left
        2 => score += 0.5,  // half left
        _ => score += 2.0,  // mostly empty bin used poorly
    }

    // Coupling with lookahead item: does next item fit into the post-residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // exact or near-exact pairing is excellent
            let gap = (post_residual - next_item_size) as f64;
            score -= 10.0 - gap * 0.15;
            if gap == 0.0 { score -= 8.0; }
        } else {
            // next item won't fit here; slight penalty unless residual is tiny anyway
            score += 2.0;
        }
        // harmonic class match between post_residual and next item size
        if next_item_size as i64 % 10 == r10 && pr > 0 { score -= 2.5; }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: neutral baseline, slightly penalized so we
    // prefer existing bins unless the fit is truly bad.
    if bin_residual == bin_capacity {
        score += 15.0;
        // but if no existing bin fits decently, opening a new bin is fine
        if fitting_bins_count == 0 { score -= 20.0; }
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 { score -= 5.0; }
    }

    // Progress-based mild regularization
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.5 * (mean_residual - post_residual as f64) * 0.05;
    score -= progress * 1.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // (below the minimum item size) are pure waste; penalize them heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 120.0;
    } else if post_residual >= 10 && post_residual <= 20 {
        // Small-but-usable gaps: mild penalty, they rarely fit future items.
        score += 15.0 * (1.0 - (post_residual as f64 - 10.0) / 10.0);
    }

    // Reward very tight fits (perfect packing).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Large residual after placement is good (bin stays flexible), but only
    // when the item itself was not tiny (avoid dumping small items in fresh bins).
    if post_residual >= 40 && item_size >= 20 {
        score -= 10.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += 3.0 * open_bins_count as f64;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward it.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 50.0;
        } else if post_residual >= next_item_size {
            score -= 12.0;
        } else if next_item_size > post_residual && post_residual > 0 && post_residual < 10 {
            // next item cannot use this gap: extra dead-space penalty
            score += 25.0;
        }
    }

    // New-bin candidate: only attractive when current bins are crowded or
    // the item is large and fits would be sloppy.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowded = mean_residual < item_size as f64 * 1.5;
        if crowded || fitting_bins_count == 0 {
            score -= 30.0 + 20.0 * progress;
        } else {
            // Prefer reusing an existing reasonable fit.
            score += 40.0;
        }
    }

    // Mild tie-breaking: prefer bins with residual close to mean (balanced use).
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward exact match with next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match bonus: next item exactly fills this bin afterwards.
        if post_residual == next_item_size {
            score -= 1000.0;
        } else {
            // Penalize mismatch between post_residual and next item size.
            score += diff * 1.5;
            // Bonus if next item can still fit after this placement.
            if post_residual >= next_item_size {
                score -= 20.0;
            } else {
                // Dead space that next item cannot use; penalize proportionally.
                score += (next_item_size - post_residual) as f64 * 0.5;
            }
        }
    }

    // Penalize creating tiny unusable residuals (< 10, smallest possible item).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Compare against mean residual: prefer bins tighter than average.
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: discourage opening a new bin unless current fit is bad.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        score += 25.0;
        // But if no existing bin fits well, allow it: if this is the only
        // candidate context (few fitting bins), soften the penalty.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // Prefer opening new bins early in the stream (amortization).
        if total_items > 0 {
            let progress = step_index as f64 / total_items as f64;
            score += progress * 30.0;
        }
    }

    // Slight preference for fuller bins overall.
    score -= (bin_capacity - bin_residual) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / (total_items.max(1) as f64);

    // Base: prefer tight fits, but punish dead space below next item's size.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.8;
    }

    // Exact fit is gold.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 10.0;
    }

    // Last-chance bin before opening a new bin: strong reward.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a bin unless existing fits are wasteful.
    if is_new_bin {
        let waste_threshold = 0.45 * bin_capacity as f64;
        let poor_fits = (post_residual as f64) > waste_threshold; // always true for empty bin
        let _ = poor_fits;
        // Penalize by how many bins already fit the item well.
        let existing_ok = if fitting_bins_count > 1 { 1.0 } else { 0.0 };
        score += 30.0 + 10.0 * existing_ok * (1.0 - progress);
        // Late in stream, opening fresh bins is cheaper (less future to waste).
        score -= 20.0 * progress;
        // Many open bins with high mean residual: avoid spreading.
        if mean_residual > 30.0 && open_bins_count > 3 {
            score += 15.0;
        }
    } else {
        // Reward using bins whose residual is already fragmented.
        let frag = (bin_residual as f64 - mean_residual).abs();
        score += frag * 0.05;
        // Prefer bins that keep residual aligned with likely future needs.
        if next_item_size > 0 && post_residual as f64 >= next_item_size as f64 {
            score -= 3.0;
        }
        // Mild preference for bins below mean residual (consolidate emptier bins).
        if (bin_residual as f64) < mean_residual {
            score -= 2.0;
        }
    }

    // Early stream: be conservative, keep bins tidy for the long run.
    score *= 1.0 + 0.3 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fill = item / cap; // normalized item size
    let pr_norm = pr / cap;

    // Base: prefer small post residual, with a non-linear (quadratic) coupling
    let mut score = pr + pr_norm * pr_norm * 20.0;

    // Smooth interaction: tight fits get progressively more reward as stream advances
    let tightness = 1.0 - pr_norm; // 1.0 = perfect fit
    score -= 30.0 * tightness * tightness * (0.5 + progress);

    // Cubic coupling of post_residual with fill ratio: penalize mid-range dead space
    score += 15.0 * pr_norm * pr_norm * pr_norm * (1.0 - fill);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0 * (1.0 - progress);
    }

    // Lookahead: penalize if next item cannot fit into post residual
    if next_item_size > 0 && (next_item_size as f64) > pr {
        let gap = (next_item_size as f64 - pr) / cap;
        score += 25.0 * gap * gap;
    } else if next_item_size > 0 {
        // reward leaving room for the next item smoothly
        let room = 1.0 - (next_item_size as f64 - pr).abs() / cap;
        score -= 8.0 * room * progress;
    }

    // New-bin candidate handling: mildly penalize opening a new bin, more so early
    if bin_residual == bin_capacity {
        score += 35.0 * (1.0 - progress) + 5.0 * (open_bins_count as f64).sqrt();
        // but if existing bins would leave very poor fits, allow opening
        let waste = pr - item as f64;
        // (pr here equals cap for new bin, so compare against mean residual instead)
        if mean_residual > 0.0 && (mean_residual - item).abs() / cap > 0.5 {
            score -= 20.0;
        }
        let _ = waste;
    } else {
        // Slight penalty proportional to divergence from mean residual (prefer balance)
        score += 0.05 * (bin_residual as f64 - mean_residual).abs();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: dead space quality.
    // Class 0: residual in {0} -> perfect fit, huge reward.
    // Class 1: residual <= 10 -> near-perfect, strong reward.
    // Class 2: residual divisible by 20 (nice chunk) -> moderate reward.
    // Class 3: residual in awkward mid-range -> penalty.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0;
    } else if pr <= 10 {
        score -= 35.0;
    } else if pr % 20 == 0 {
        score -= 12.0;
    } else if pr % 10 == 0 {
        score -= 6.0;
    } else if pr > 30 {
        score += (pr as f64 - 30.0) * 0.15; // awkward large dead space
    }

    // Harmonic class of the item size itself (integer division thresholds).
    // Big items (>= half capacity) prefer tight bins; small items are flexible.
    let size_class = item_size / 20; // 0..4 harmonic bucket
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * (10.0 + 6.0 * size_class as f64);

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // this placement chains perfectly -> strong reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size <= pr {
            // Next item still fits: mild reward scaled by leftover quality.
            let chain_left = pr - next_item_size;
            if chain_left <= 10 {
                score -= 15.0;
            } else {
                score -= 5.0;
            }
        } else {
            // Next item cannot use this bin's leftover; penalize by how much
            // dead space remains, weighted by stream progression.
            let progress = step_index as f64 / total_items.max(1) as f64;
            score += (pr as f64 / 10.0) * (0.5 + 0.5 * progress);
        }
    } else {
        // Last item: prefer closing bins completely.
        score += pr as f64 * 0.5;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // and no good fit exists (post residual would be small in an empty bin).
    if bin_residual == bin_capacity {
        // Empty bin: post_residual == capacity - item_size.
        // Reward when item is big (little waste), penalize when small.
        let waste = post_residual as f64;
        score += 20.0 - 0.2 * waste;
        // Early in the stream, opening bins is cheaper (more future to fill them).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 15.0 * (1.0 - progress);
    }

    // Mild penalty for bin proliferation when many bins are already open.
    if bin_residual == bin_capacity && open_bins_count > 4 {
        score += 2.0 * ((open_bins_count as f64) - 4.0).min(10.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // smallest plausible item (<= 10) are pure waste; penalize them hard.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Semi-dead zone: residual too small for the lookahead item but nonzero.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Reward tight fits (small useful post_residual) nonlinearly.
    let fit_ratio = (post_residual as f64) / (bin_capacity as f64);
    score += 30.0 * fit_ratio * fit_ratio;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Perfect fill is ideal.
    if post_residual == 0 {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when open bins are crowded
    // (mean residual too small for the item) or many bins are open.
    if bin_residual == bin_capacity {
        score = 100.0 - (open_bins_count as f64) * 2.0;
        if (mean_residual as u32) < item_size + 5 {
            score -= 30.0;
        }
    }

    // Open-bin pressure: mildly discourage spreading across many bins.
    score += (open_bins_count as f64) * 0.3;

    // Lookahead: if the next item fits exactly in post_residual, reward this placement.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead matching: reward bins whose post_residual
    // closely matches the next item's size (perfect chain placement).
    if next_item_size > 0 {
        let post = post_residual as f64;
        let nxt = next_item_size as f64;
        let match_gap = (post - nxt).abs();
        if post >= nxt {
            // Next item can chain into this bin: reward tight match.
            score -= 40.0 * (1.0 - match_gap / bin_capacity as f64);
            // Perfect chain (post_residual == next_item_size) is gold.
            if match_gap < 1.0 {
                score -= 25.0;
            }
        } else {
            // Next item won't fit here: penalize leftover dead space,
            // scaled by how large the unusable remainder is.
            score += 0.5 * post;
            // Strong penalty if post_residual is small but unusable
            // (dead space below the minimum item size).
            if post < 10.0 {
                score += 30.0 * (10.0 - post);
            }
        }
    } else {
        // Last item: simply minimize waste.
        score += 10.0 * post_residual as f64 / bin_capacity as f64;
    }

    // Relative-to-mean-residual coupling: prefer filling below-average
    // residual bins (dense bins) over sparse ones.
    score += 0.3 * (mean_residual - bin_residual as f64).abs().copysign(1.0)
        * if (bin_residual as f64) < mean_residual { -1.0 } else { 1.0 };

    // Last-chance bonus: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual <= bin_residual {
        score -= 20.0;
    }

    // New-bin candidate handling: an empty bin should only win when no
    // open bin offers a decent fit. Penalize it moderately.
    if bin_residual == bin_capacity {
        score += 45.0;
        // But if lookahead suggests next item pairs well with a fresh bin
        // after this item, soften the penalty.
        if next_item_size > 0 && (post_residual as f64 - next_item_size as f64).abs() < 5.0 {
            score -= 30.0;
        }
    }

    // Early in the stream, allow more bin creation freedom (exploration);
    // late in the stream, be conservative and squeeze existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 15.0 * (1.0 - progress);
    } else {
        score -= 5.0 * progress;
    }

    // Mild penalty for many open bins: encourage consolidation.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post-residual).
    score -= (bin_capacity as f64 - post_residual as f64) * 0.35;

    // Penalize dead space: residual that is too small to be useful
    // for typical small items (assume min useful chunk ~ 10).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 25 {
        score += (25.0 - post_residual as f64) * 0.8;
    }

    // Lookahead: reward if the next item can still fit in this bin after placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 18.0 + (post_residual as f64 - next_item_size as f64) * 0.15;
        } else {
            score += 10.0;
        }
    }

    // Last chance: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 2 {
        // Many alternatives: be pickier about residual quality.
        score += post_residual as f64 * 0.12;
    }

    // New-bin candidate handling: opening a new bin should only win when
    // the item fits poorly everywhere else. Make the empty bin costly by default.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Cost decreases slightly over time (long streams amortize new bins less).
        let new_bin_cost = 55.0 + 40.0 * (1.0 - progress) + open_bins_count as f64 * 2.0;
        score += new_bin_cost;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // A fresh bin is attractive if the next item is large and likely
            // to need lots of space.
            score -= (next_item_size as f64 / bin_capacity as f64) * 20.0;
        }
    }

    // Global state coupling: prefer filling bins with above-average residual
    // (drain the roomiest bins first, keeping tight bins for small items).
    if (bin_residual as f64) < mean_residual {
        score -= 6.0;
    } else {
        score += (bin_residual as f64 - mean_residual) * 0.05;
    }

    // Time horizon: late in the stream, consolidate aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 8.0 * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins where the item occupies a large fraction of residual.
    let fill_ratio = item_size as f64 / (bin_residual.max(1) as f64);
    score -= fill_ratio * 12.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Smooth non-linear polynomial coupling of post_residual with stream progress.
    let pr = post_residual as f64;
    let pr_norm = pr / bin_capacity as f64;

    // Early in the stream: tolerate larger residuals (bins stay flexible).
    // Late in the stream: penalize residuals more aggressively (dead space matters).
    let late_weight = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score += late_weight * pr_norm * pr_norm * 40.0;

    // Reward tight fits more strongly as the stream progresses (quadratic in item fraction).
    let fill_fraction = item_size as f64 / bin_capacity as f64;
    score -= late_weight * fill_fraction * fill_fraction * 25.0;

    // Lookahead coupling: if next item fits the post residual, reward this placement smoothly.
    if next_item_size > 0 {
        let fits_next = if post_residual >= next_item_size { 1.0 } else { 0.0 };
        let slack = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64 / bin_capacity as f64;
        score -= fits_next * (1.0 - slack) * 15.0 * (0.5 + progress);
    }

    // Last-chance bin bonus: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 - late_weight * 0.5);
    }

    // Slight penalty when this bin's residual deviates from mean residual (keeps bin pool balanced).
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += dev * dev * 10.0 * late_weight;

    // Mild pressure against accumulating too many open bins early.
    let open_norm = open_bins_count as f64 / (1.0 + total_items as f64 * 0.05);
    score += open_norm * open_norm * 2.0 * (1.0 - late_weight);

    // New-bin candidate: encourage opening fresh bins early, discourage late.
    if bin_residual == bin_capacity {
        score -= 12.0 * (1.0 - progress) - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo capacity fractions (C=100 -> classes of 10)
    let post = post_residual as u32;
    let class = post / 10; // 0..10 harmonic class
    // Penalize dead space in low classes (tiny unusable gaps)
    if post > 0 && post < 10 {
        score += 25.0;
    }
    // Reward near-perfect fits strongly
    if post == 0 {
        score -= 60.0;
    } else if class <= 2 {
        score += 8.0; // small leftover but maybe usable
    }

    // Coupling with next item: if next item fits into post_residual, reward
    if next_item_size > 0 && next_item_size <= post {
        score -= 12.0;
        // extra reward if next fills it to a harmonic boundary
        let nxt_post = post - next_item_size;
        if nxt_post % 10 == 0 {
            score -= 8.0;
        }
    } else if next_item_size > post && next_item_size > 0 {
        // next item cannot use this leftover; penalize large stranded residual
        score += (post as f64) * 0.15;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        // Opening a new bin is fine early, costly when many bins already open
        score = cap * 0.5 + (open_bins_count as f64) * 3.0;
        if post == bin_capacity as u32 {
            // empty bin always has post_residual == capacity; neutralize class logic
            score += 5.0;
        }
    }

    // Progress-based drift: late in the stream, consolidate more aggressively
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * (mean_residual - post as f64).max(0.0) * 0.1;
    score -= progress * 5.0;

    // Prefer bins whose residual deviates favorably from the mean
    score += ((mean_residual - post as f64) * 0.05).max(-10.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let dead_zone: f64 = 15.0;
    if post_residual > 0 && (post_residual as f64) < dead_zone {
        score += (dead_zone - post_residual as f64) * 4.0;
    }
    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward when this bin can also fit the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 6.0; // lookahead won't fit: residual becomes dead space
    }

    // Last-chance bin before opening a new one: favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to open bins and progress.
        score += 40.0 + 8.0 * open_bins_count as f64 + 30.0 * progress;
        // Allow new bin only if mean residual across open bins is very tight.
        if mean_residual < 8.0 {
            score -= 60.0;
        }
    } else {
        // Slight preference for fuller bins among open ones.
        score -= (bin_capacity - bin_residual) as f64 * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Strong reward for near-perfect fit.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 30.0;
    } else if post_residual <= 20 {
        score -= 12.0;
    }

    // 2-step lookahead: does the leftover space fit the next item?
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual >= next_item_size && post_residual > 0 {
            // Chain-friendly leftover: reward proportionally to how snugly next item fits.
            let slack_after_next = (post_residual - next_item_size) as f64;
            score -= 18.0 * (1.0 - slack_after_next / cap).max(0.0);
        } else {
            // Leftover is dead space relative to next item: penalize more for large gaps.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.25 * gap.min(60.0);
        }
        // Extra penalty if leftover is just barely unusable (wasted sliver).
        if post_residual < next_item_size && post_residual > 0 && gap_is_sliver(post_residual, next_item_size) {
            score += 10.0;
        }
    }

    // Relative-to-mean coupling: bins with residual far above mean are "loose";
    // filling them is good if fit is tight, bad if it creates dead space.
    let dev = (bin_residual as f64 - mean_residual).max(0.0);
    score -= 0.10 * dev * (1.0 - post / cap);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
        if post_residual <= 15 {
            score -= 15.0;
        }
    }

    // New-bin candidate handling: only attractive when item is large and no open bin fits well.
    if bin_residual == bin_capacity {
        let fill_ratio = item / cap;
        score = 0.35 * cap * (1.0 - fill_ratio);
        if item_size >= 60 {
            score -= 10.0;
        }
        if fitting_bins_count == 0 {
            score -= 40.0; // must open a bin anyway
        }
        // Late in stream, prefer consolidating into open bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 8.0 * progress;
    }

    // Mild preference for many open bins being drained (avoid bin sprawl).
    score += 0.05 * open_bins_count as f64 * (post / cap);

    score
}

#[inline]
fn gap_is_sliver(post_residual: u32, next_item_size: u32) -> bool {
    // leftover too small relative to next item AND too small to be generally useful
    post_residual < next_item_size && post_residual < 12
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect or near-perfect fits are gold: reward heavily.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 10 {
        score -= 300.0 + 20.0 * (10 - post_residual) as f64;
    }

    // Dead-space penalty: residual too small for any plausible future item.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let min_item = 1.0f64;
    if (post_residual as f64) < min_item {
        score += 50.0;
    }

    // Lookahead: if the next item fits exactly in post_residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // slack relative to next item: smaller slack is better
            let slack = (post_residual - next_item_size) as f64;
            score -= 100.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here anyway; slight penalty for tight residuals
            score += 10.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, use it to avoid a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0 + 0.5 * item_size as f64;
    }

    // New-bin candidate: only attractive when no open bin is a decent fit
    // or the stream is early and we want to spread load.
    if bin_residual == bin_capacity {
        let decent_fit_exists = fitting_bins_count > 1
            || (fitting_bins_count == 1 && (bin_capacity - item_size) >= 20);
        if decent_fit_exists {
            score += 200.0; // discourage opening new bins when fits exist
        } else {
            score -= 50.0 * (1.0 - progress); // early stream: open bins more freely
        }
        // late stream: prefer filling existing bins, penalize new bins more
        score += 100.0 * progress;
    }

    // Prefer bins with below-average residual (concentrate filling).
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Mild preference for bins among many open bins (use existing capacity).
    score -= 0.1 * open_bins_count as f64;

    // Tightness coupling: reward small post_residual relative to capacity.
    score -= 50.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress
    let p2 = progress * progress;
    let p3 = p2 * progress;
    score -= (1.0 - progress) * (2.0 * p2 + 3.0 * p3) * 6.0;

    // Reward tight fits: quadratic decay of bonus as post_residual grows
    let tightness = 1.0 - pr / cap;
    score -= tightness * tightness * 12.0;

    // Penalize dead space that can't fit the next item (smooth cubic)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            let gap = (nxt - pr) / cap;
            score += gap * gap * gap * 30.0;
        } else {
            let slack = (pr - nxt) / cap;
            score -= slack * slack * 5.0;
        }
    }

    // Last-chance bin bonus, scaled smoothly by progress
    if fitting_bins_count == 1 {
        score -= 8.0 + 6.0 * progress;
    }

    // Mild penalty for spreading across many open bins, coupled with mean residual
    let mr = mean_residual / cap;
    score += (open_bins_count as f64).ln() * (0.5 + mr) * 1.5;

    // Penalize near-empty new-bin candidates unless current bins are fragmented
    if bin_residual == bin_capacity {
        score += 10.0 - 14.0 * mr - 6.0 * progress * p2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: residues divisible by common
    // small item classes (10/20/25/50) are reusable "harmonics".
    let cap = bin_capacity as f64;
    let fill_frac = item_size as f64 / cap;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 100.0;
    } else if post_residual <= 10 {
        score -= 40.0;
    }

    // Harmonic class check: leftover belongs to a reusable residue class.
    let harmonic = post_residual % 10 == 0 || post_residual % 25 == 0 || post_residual == 50;
    if harmonic {
        score -= 12.0;
    } else {
        // Penalize awkward dead space (prime-ish / odd residues).
        score += (post_residual % 7) as f64 * 1.5;
    }

    // Penalize leftover that is too small to hold even the smallest item (1..100 range).
    if post_residual < 10 && post_residual > 0 {
        score += 25.0; // dead space below minimum item size
    }

    // Lookahead coupling: if the next item fits the post-residue exactly,
    // this bin is a great chain candidate.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size < post_residual {
            let nxt_left = post_residual - next_item_size;
            score -= 8.0;
            if nxt_left % 10 == 0 || nxt_left % 25 == 0 {
                score -= 10.0;
            }
            if nxt_left < 10 {
                score += 15.0; // creates dead space after next placement
            }
        } else {
            score += 10.0; // next item won't fit here; bin likely closes
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Capacity-fraction thresholds: bins filled past 3/4 are valuable to top off.
    let used = (cap - post_residual as f64) / cap;
    if used > 0.75 {
        score -= 15.0 * (used - 0.75) / 0.25;
    } else if used < 0.4 {
        score += 8.0; // spreading thin across bins is bad
    }

    // Prefer bins below mean residual (tighter bins) mildly.
    score += (mean_residual - post_residual as f64).max(-50.0).min(50.0) * 0.2;

    // Late in stream: consolidate, avoid opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses or many bins open.
        score += 20.0 + 40.0 * progress + (open_bins_count as f64).sqrt() * 3.0;
        // Only attractive if no open bin fits well.
        if fitting_bins_count == 0 {
            score -= 45.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps.
    // A residual gap is "dead" if it is too small for the smallest plausible item.
    // Items are 1..=100; treat gaps below ~10 as nearly unusable, with a
    // smooth escalating penalty as the gap shrinks toward 0.
    if post_residual > 0 {
        let gap = post_residual as f64;
        if gap < 10.0 {
            // Very small gap: almost certainly dead space -> strong penalty.
            score += (10.0 - gap) * 6.0;
        } else if gap < 20.0 {
            // Small gap: risky, moderate penalty that decays with gap size.
            score += (20.0 - gap) * 1.5;
        }

        // Bonus for a "perfect" fit that leaves a still-usable gap
        // matching common small item sizes (10, 20, 25, 50).
        for target in [10.0f64, 20.0, 25.0, 50.0] {
            if (gap - target).abs() < 0.5 {
                score -= 8.0;
            }
        }
    } else {
        // Perfect fill: zero waste, strongly favored.
        score -= 15.0;
    }

    // Open-bins pressure: with many open bins, prefer consolidating into
    // existing bins over opening new ones (favor low post_residual even more).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = 1.0 + (open_bins_count as f64 / 20.0).min(1.5) + progress * 0.5;
    score *= pressure;

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Lookahead: if the next item would fit exactly in the post_residual,
    // reward this placement; if next item barely misses, penalize slightly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size > post_residual && next_item_size <= bin_residual {
            score += 4.0;
        }
    }

    // New-bin candidate: penalize opening a new bin unless current item is
    // large and would leave an awkward fit elsewhere. A fresh bin has
    // bin_residual == bin_capacity; its post_residual = capacity - item_size,
    // which is usually large, so the base score already discourages it.
    // Add extra fixed cost to opening new bins, softened when many bins are
    // open and mean residual is high (fragmentation -> consolidation fails).
    if bin_residual == bin_capacity {
        score += 10.0;
        if mean_residual > 30.0 && open_bins_count > 2 {
            score -= 6.0; // existing bins are fragmented; a fresh bin is okay
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead: post_residual exactly matches next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Post-residual can fit next item (partial lookahead reward, decays with slack).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0 - 0.3 * ((post_residual - next_item_size) as f64).min(50.0);
    }

    // Dead space: post_residual too small for next item (and likely unusable).
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += (next_item_size - post_residual) as f64 * 0.8;
    }

    // Penalize post_residual below the minimum item size (1) -> truly dead space.
    if post_residual < 10 {
        score += 40.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: only attractive when current bin fit is terrible
    // (large post_residual wasted relative to mean residual).
    if bin_residual == bin_capacity {
        let waste = post_residual as f64 - mean_residual;
        score += 70.0 - waste * 0.5;
        // Encourage new bin when next item is large and current fit is tight.
        if next_item_size > 0 && post_residual < next_item_size {
            score -= 20.0;
        }
    }

    // Mild reward for tight packing relative to mean residual.
    score -= (mean_residual - post_residual as f64) * 0.15;

    // Late-stream consolidation: prefer filling existing bins as stream ends.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near zero is ideal.
    score -= (bin_capacity as f64 - post_residual as f64) * 0.05;

    // Lookahead: if the next item also fits in the post-residual, strongly reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0 + (post_residual - next_item_size) as f64 * 0.3;
    }
    // If next item would NOT fit here but this bin could hold it, penalize wasting large residual.
    if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        score += post_residual as f64 * 0.15;
    }

    // Last-chance bonus: this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when the item
    // is large or existing residuals are poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let openness = open_bins_count as f64 * 0.5;
        // Penalize new bins generally, but less if item is big and fits poorly elsewhere.
        let mut new_bin_score = 40.0 + openness - progress * 10.0;
        if item_size > 60 {
            new_bin_score -= 10.0;
        }
        if next_item_size > 0 && next_item_size <= bin_residual - item_size {
            new_bin_score -= 8.0; // fresh bin can chain with next item
        }
        score += new_bin_score;
    } else {
        // Prefer bins whose residual is close to the item (good fill ratio).
        let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
        score -= fit_ratio * 10.0;

        // Slightly prefer bins below the mean residual (consolidate small leftovers).
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
    }

    // Mild time-horizon modulation: early in stream, be greedy with tight fits;
    // late in stream, avoid leaving many tiny residuals.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if post_residual <= 10 {
        score -= 8.0 * (1.0 - progress);
    }
    if post_residual > 0 && post_residual < 10 && progress > 0.7 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let r = post_residual as f64;
    let cap = bin_capacity as f64;
    let rn = r / cap;

    // Base: prefer tight fits, but weight grows with stream progress
    let mut score = rn * rn * (1.0 + 2.0 * progress);

    // Smooth polynomial coupling of residual with progress
    score += 0.5 * rn * (1.0 - progress) * (1.0 - progress);

    // Penalize dead space relative to mean residual (smooth quadratic)
    let dev = (r - mean_residual) / cap;
    score += 0.3 * dev * dev;

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 3.0 + 2.0 * progress;
    }

    // Lookahead: reward residual that can host next item smoothly
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let fits_next = (r >= n) as i32 as f64;
        let snug = 1.0 - ((r - n) / cap).abs();
        score -= 0.8 * fits_next * snug.max(0.0) * (0.5 + progress);
    } else {
        // last item: strongly prefer filling existing bins
        score -= 2.0;
    }

    // Mild penalty for opening new bins when many bins already open
    if bin_residual == bin_capacity {
        score += 1.5 + 2.0 * progress + 0.05 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify dead space into capacity fractions
    let frac = post_residual as f64 / cap; // fraction of capacity wasted
    // Reward small residuals (good packing) nonlinearly
    if post_residual == 0 {
        score -= 60.0; // perfect fit is ideal
    } else if post_residual <= 10 {
        score -= 40.0;
    } else if post_residual <= 20 {
        score -= 25.0;
    } else if post_residual <= 30 {
        score -= 10.0;
    } else {
        // large dead space: penalize superlinearly beyond linear baseline
        score += frac * frac * 50.0;
    }

    // Harmonic classes via integer division: residuals in multiples of small classes
    let class = post_residual / 10; // 0..10 classes
    score -= (10 - class.min(10)) as f64 * 3.0;

    // Lookahead: reward if next item fits into post_residual (chain packing)
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item fits exactly or nearly: strong reward
            let slack = post_residual - next_item_size;
            if slack == 0 {
                score -= 55.0;
            } else if slack <= 10 {
                score -= 30.0;
            } else {
                score -= 12.0;
            }
        } else {
            // next item won't fit: this residual becomes dead space; penalize if large
            score += (next_item_size as f64 - post_residual as f64) * 0.4;
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize mildly so it's chosen only when fits are bad
    if bin_residual == bin_capacity {
        score += 15.0 + mean_residual * 0.05;
    }

    // Prefer denser bins (low mean residual context) slightly
    score += (mean_residual - post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to host
    // typical future items (>=10) are pure waste; penalize hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Penalty ramps for gaps below the minimum item size band midpoint.
    if post_residual < 20 {
        score += (20 - post_residual) as f64 * 2.5;
    }

    // Reward exact / near-perfect fits.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead (k=2): if the next item fits the post-residual, reward this bin.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0 + (post_residual as f64 - next_item_size as f64) * 0.3;
        } else {
            // Gap cannot host the next item: mild penalty proportional to waste.
            score += (next_item_size as f64 - post_residual as f64).min(20.0) * 0.5;
        }
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + item_size as f64 * 0.2;
    }

    // New-bin candidate handling: opening a new bin is wasteful when many bins
    // are already open and residual space is plentiful; penalize proportionally.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 + open_bins_count as f64 * 4.0 + progress * 10.0;
        // But if the item leaves a huge hole in every other bin (large item),
        // a fresh bin is acceptable: soften the penalty.
        if item_size >= 60 {
            score -= 35.0;
        }
        if next_item_size > 0 && next_item_size >= bin_residual {
            score -= 20.0; // fresh bin guarantees fit for next item
        }
    }

    // Open-bins pressure: discourage spreading across many bins; prefer bins
    // with below-average residual (denser bins) when many bins are open.
    score += open_bins_count as f64 * 0.6;
    if (bin_residual as f64) < mean_residual {
        score -= (mean_residual - bin_residual as f64) * 0.4;
    } else {
        score += (bin_residual as f64 - mean_residual) * 0.4;
    }

    // Prefer filling fuller bins overall (tight packing bias).
    score -= (bin_capacity - bin_residual) as f64 * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: strongly reward leaving zero dead space.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual exactly matches the next item size.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // Next item can also fit here: mild bonus proportional to how snugly it would fit.
            let two_step_waste = (post_residual - next_item_size) as f64;
            score -= 50.0 - 0.5 * two_step_waste;
        } else {
            // Next item cannot fit in the leftover: penalize small dead zones.
            let dead = (next_item_size - post_residual) as f64;
            score += 0.3 * dead;
        }
    }

    // Compare post_residual relative to mean residual: avoid creating outliers of waste.
    let dev = post_residual as f64 - mean_residual;
    score += 0.2 * dev.abs();

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // Penalize opening a new bin when the item fits reasonably well in an existing bin.
    if bin_residual == bin_capacity {
        let fit_quality = (bin_capacity - item_size) as f64;
        score += 50.0 + fit_quality;
    }

    // Late in the stream, consolidate: prefer tighter bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) more aggressively than linear.
    let fit_frac = post_residual as f64 / bin_capacity as f64;
    score += 12.0 * fit_frac * fit_frac;

    // Penalize leaving residual smaller than the smallest plausible item (dead space),
    // but less harsh when the stream is near its end.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - 0.7 * progress);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead coupling: if the next item fits in the post residual, reward;
    // if not, penalize wasted compatibility.
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 10.0;
        } else if next_item_size > bin_residual {
            // next item won't fit here anyway; neutral
        } else {
            score += 6.0;
        }
    }

    // Prefer bins with below-average residual (denser bins) slightly.
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // When many bins are open, discourage spreading; prefer consolidating into
    // existing bins rather than opening new ones.
    if bin_residual == bin_capacity {
        let open_f = open_bins_count as f64;
        score += 8.0 + 2.0 * open_f.sqrt() * (1.0 - progress);
    } else {
        score -= 3.0;
    }

    // Mild time-horizon modulation: early in stream, be more selective (add
    // noise-free smoothing term); late in stream, just fill anything available.
    score *= 1.0 + 0.1 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let prn = pr / cap;
    let poly = prn * prn * (1.0 + progress) - 2.0 * prn * progress * (1.0 - progress);
    score += 12.0 * poly;

    // Reward tight fits more strongly as stream progresses.
    let tightness = 1.0 - prn;
    score -= (8.0 + 16.0 * progress) * tightness * tightness * it / cap;

    // Penalize dead space that cannot fit the next item (smooth quadratic).
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        let gap = (pr - ni).max(0.0) / cap;
        score += 10.0 * gap * gap * (1.0 - progress);
        // Reward leaving room exactly for next item.
        let match_term = 1.0 - ((pr - ni).abs() / cap);
        score -= 6.0 * match_term * match_term * progress;
    }

    // Last-chance bin bonus: strongly favor the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 * (1.0 - prn * prn);
    }

    // Mild penalty for spreading across many open bins early on.
    score += (open_bins_count as f64).ln() * 0.5 * (1.0 - progress);

    // Pull score toward mean residual alignment.
    score += 0.3 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into
    // capacity-fraction buckets (1/4, 1/3, 1/2, 3/4 of capacity).
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    let three_quarter = 3 * quarter;

    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Dead-space penalty: residuals too small for the smallest plausible item.
        if post_residual < 10 {
            score += 60.0;
        }
        // Harmonic bucket bonus: residuals near half capacity are the most reusable,
        // then quarter, then three-quarter.
        let bucket_bonus: f64 = if post_residual >= half - 5 && post_residual <= half + 5 {
            35.0
        } else if post_residual >= quarter - 5 && post_residual <= quarter + 5 {
            22.0
        } else if post_residual >= three_quarter - 5 {
            12.0
        } else {
            0.0
        };
        score -= bucket_bonus;

        // Reward residuals that can still host the lookahead item exactly-ish.
        if next_item_size > 0 && post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            score -= 25.0 + (10.0 - slack.min(10) as f64) * 2.0;
        } else if next_item_size > 0 && next_item_size > post_residual {
            // Lookahead cannot use this leftover: mild penalty scaled by gap.
            score += ((next_item_size - post_residual) as f64) * 0.5;
        }
    }

    // Integer-division class of item size relative to capacity quarters.
    let item_class = item_size / quarter; // 0..4
    let residual_class = bin_residual / quarter;
    // Reward pairing large items with large-residual bins (class matching).
    if item_class == residual_class && post_residual < bin_residual {
        score -= 8.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 45.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // no open bin fits well (mean residual low relative to item) or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mean_gap = (mean_residual - item_size as f64).max(0.0);
        // Prefer a new bin if existing residuals barely fit the item.
        score = 40.0 + mean_gap * 0.8 - progress * 10.0 - (open_bins_count as f64) * 0.5;
        if fitting_bins_count == 0 {
            score -= 80.0; // no alternative: new bin is fine
        }
        if next_item_size > 0 && next_item_size > item_size {
            score -= 5.0; // big lookahead: fresh capacity helps
        }
    } else {
        // Mild penalty for spreading across many open bins.
        score += (open_bins_count as f64) * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // for typical future items are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // unusable sliver
    } else if post_residual >= 10 && post_residual < 25 {
        score += 25.0; // poor gap
    } else if post_residual == 0 {
        score -= 40.0; // perfect fit: eliminate dead space entirely
    }

    // Encourage filling bins tightly: reward low post_residual relative to capacity.
    score -= (bin_capacity as f64 - post_residual as f64) * 0.15;

    // Open-bin pressure: discourage spreading items across many bins
    // unless the fit is good.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize when decent fits exist already.
        if fitting_bins_count > 0 && post_residual < bin_capacity as u32 {
            score += 30.0 + 5.0 * open_bins_count as f64;
        }
        // Opening a new bin is acceptable early in the stream.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
    } else {
        // Existing bin: slight reward for consolidating into fewer bins.
        score -= 3.0 * open_bins_count as f64;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Lookahead coupling: if the next item could use the post_residual,
    // reward leaving exactly that much space.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0; // perfect for next item
        } else if post_residual >= next_item_size && post_residual < next_item_size + 10 {
            score -= 10.0; // next item still fits after this placement
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 8.0; // gap too small for the known next item
        }
    }

    // Mean-residual coupling: prefer bins whose residual is below the mean
    // (tighter bins get filled first, keeping larger residuals available).
    let residual_f = bin_residual as f64;
    if residual_f < mean_residual {
        score -= 5.0;
    } else {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly (waste minimization, non-linear).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Aggressive 2-step lookahead: if next item exactly fills post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0; // perfect chain: bin completely closed
        } else if next_item_size <= post_residual {
            // next item fits; reward tight chaining, penalize large leftover-after-next
            let after_next = post_residual - next_item_size;
            score -= 25.0 * (1.0 - after_next as f64 / bin_capacity as f64);
            score -= 10.0 * (post_residual as f64 - next_item_size as f64).abs() / bin_capacity as f64;
        } else {
            // next item won't fit here: penalize, worse if post_residual is large dead space
            score += 8.0 + 0.15 * post_residual as f64;
        }
    }

    // Compare post_residual against mean residual across open bins:
    // leaving this bin with residual close to mean is fine; extreme outliers are bad.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Very small post_residual is excellent (bin nearly closed) unless it's dead space
    if post_residual < 5 {
        score -= 15.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize opening a new bin when existing bins fit decently,
    // unless the fit is poor and the new bin could serve future items.
    if bin_residual == bin_capacity {
        // new-bin candidate: base penalty so it's only chosen for poor fits / late stream
        score += 35.0;
        if next_item_size > 0 && next_item_size >= bin_residual {
            score -= 20.0; // fresh bin guarantees fit for next item
        }
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
        if fitting_bins_count == 0 {
            score -= 60.0; // must open a bin anyway
        }
    }

    // Mild pressure to consolidate into fewer bins early on.
    if open_bins_count > 4 {
        score += 0.01 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 60.0;
    }

    // Tight fit reward: small post_residual relative to item size
    if item_size > 0 {
        score -= (item_size as f64) * 0.35 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Penalize dead space: post_residual too small for the smallest plausible future item
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: strongly reward bins where the next item also fits the leftover
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 18.0 + 0.25 * next_item_size as f64;
        } else if post_residual > 0 {
            // leftover will be wasted for the known next item
            score += 8.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    }

    // Last-chance bonus: this is the only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Global pressure: when many bins are open, prefer compacting into existing ones
    let pressure = open_bins_count as f64 / (1.0 + mean_residual.max(1.0));
    score += pressure * 0.4;

    // Compare residual to mean residual: prefer bins below-average fullness when pressure is low
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // Time horizon: early in the stream, be more selective about tight fits;
    // late in the stream, prioritize closing bins out
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        score += 30.0 + 0.5 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 12.0; // fresh bin useful for chaining large items
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: quadratic penalty on post-residual (waste grows super-linearly)
    let mut score = norm_pr * norm_pr * 40.0 + norm_pr * 10.0;

    // Smooth non-linear coupling with stream progress:
    // early: tolerate residual; late: aggressively minimize it
    let progress_coupling = (1.0 + progress * progress * 3.0) * norm_pr;
    score += progress_coupling * 15.0;

    // Sine-modulated residual term for smooth exploration of fit quality
    score += 6.0 * (norm_pr * std::f64::consts::PI).sin() * (0.5 + progress);

    // Reward tight fits (small post_residual) more strongly as mean residual shrinks
    let tightness = 1.0 - (pr / (mean_residual.max(1.0) + pr));
    score -= tightness * 8.0 * (1.0 + progress);

    // Last-chance bin bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: penalize leaving residual that neither wastes nor helps next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            // good: next item can fit here too -> reward proportionally
            let fit_quality = 1.0 - ((pr - nx) / cap);
            score -= 10.0 * fit_quality * fit_quality;
        } else {
            // next item won't fit in leftover: mild penalty scaled by gap
            score += 5.0 * ((nx - pr) / cap);
        }
    }

    // New-bin candidate: only attractive when open bins are badly fragmented
    if bin_residual == bin_capacity {
        let fragmentation = if open_bins_count > 0 {
            (mean_residual / cap).clamp(0.0, 1.0)
        } else {
            1.0
        };
        // open new bin if mean residual across open bins is small (fragmented)
        score = 30.0 + 60.0 * fragmentation - 20.0 * progress;
    }

    // Mild penalty for too many open bins
    score += (open_bins_count as f64).ln().max(0.0) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual by integer-division thresholds.
    // Residual classes: dead (<10 unusable), small (10..=25), medium (26..=50), large (>50).
    let dead_zone = 9.0;
    if post_residual < 10 {
        score -= 40.0; // perfect closure: bin fully exploited
    } else {
        // fraction of capacity wasted
        let waste_frac = post_residual as f64 / cap;
        score += waste_frac * 30.0;
        // dead-space penalty grows superlinearly for unusable gaps
        if post_residual < item_size.min(10) {
            score += (10.0 - post_residual as f64) * 8.0;
        }
    }

    // Tightness reward: relative fit quality
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 25.0;

    // Lookahead coupling: reward residual that can host the next item (harmonic pairing)
    if next_item_size > 0 && post_residual >= next_item_size {
        let pair_eff = next_item_size as f64 / post_residual as f64;
        score -= pair_eff * 20.0;
        // exact pair closure bonus
        if post_residual == next_item_size {
            score -= 35.0;
        }
    } else if next_item_size > 0 {
        // next item cannot use this residual: penalize proportionally to blocked capacity
        score += (next_item_size as f64 - post_residual as f64).min(50.0) * 0.4;
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: penalize opening a new bin unless existing fits are terrible
    if bin_residual == bin_capacity {
        score += 45.0;
        // early stream: allow more bins to spread classes
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= progress * 15.0;
        if next_item_size > 0 && next_item_size >= item_size && item_size + next_item_size <= bin_capacity {
            score -= 30.0; // good pair candidate in fresh bin
        }
    }

    // Mean-residual pressure: if open bins are mostly full, avoid stuffing the emptiest one badly
    if (post_residual as f64) > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.3;
    } else {
        score -= (mean_residual - post_residual as f64) * 0.15;
    }

    // Harmonic modulo bonus: residual in friendly classes (multiples of 10 or matching item class)
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    }
    let item_class = item_size / 10;
    if post_residual >= 10 && (post_residual / 10) >= item_class {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold even
    // the smallest plausible item (<= 10) are pure waste; punish hard.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 30 {
        score += 8.0;
    }

    // Reward tight fits: small post_residual relative to item size.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // If the next item can exactly use the post residual, strongly favor.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    }
    // If next item fits in the post residual, mild bonus.
    if next_item_size > 0 && next_item_size < post_residual {
        score -= 5.0;
    }
    // If post residual is a dead gap that the next item cannot use, penalize.
    if next_item_size > 0 && next_item_size > post_residual && post_residual < 20 {
        score += 15.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // over opening new bins; make new bins progressively less attractive.
    if bin_residual == bin_capacity {
        // New-bin candidate score: base cost plus pressure.
        score = bin_capacity as f64 * 0.5 + 10.0 * open_bins_count as f64;
        // Early in stream, new bins are cheap; later, expensive.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0 * progress;
        // If mean residual across open bins is high, we should use them instead.
        score += 0.5 * mean_residual;
        // If no bin fits (fitting_bins_count == 0 among open bins handled elsewhere),
        // the new bin is the only option: make it attractive.
        if fitting_bins_count == 0 {
            score -= 1000.0;
        }
    } else {
        // Mild preference to keep residuals balanced with the mean.
        score += 0.1 * ((bin_residual as f64 - mean_residual).abs());
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to item size)
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 8.0 * tightness;

    // Aggressive 2-step lookahead: reward if next item fits the post residual exactly-ish
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack_after_next = (post_residual - next_item_size) as f64;
            // Strong reward when next item fills bin almost completely
            if slack_after_next <= 5.0 {
                score -= 25.0;
            } else {
                score -= 12.0 * (1.0 - slack_after_next / bin_capacity as f64);
            }
        } else {
            // Next item won't fit here -> penalize leaving a gap close to next_item_size (dead space)
            let gap = (post_residual - next_item_size.min(post_residual)) as f64;
            score += 6.0 + 4.0 * gap / bin_capacity as f64;
        }
    }

    // Compare post_residual against mean residual: prefer bins that become below-average residual
    let mean_c = mean_residual.max(1.0);
    if (post_residual as f64) < mean_c {
        score -= 5.0 * (1.0 - post_residual as f64 / mean_c);
    } else {
        score += 3.0 * (post_residual as f64 / mean_c - 1.0);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fits are poor
    if bin_residual == bin_capacity {
        score += 30.0;
        // But if lookahead would waste current bins' space, new bin is more acceptable
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
        // Fewer open bins -> cheaper to open a fresh one
        score -= 2.0 * (open_bins_count as f64).ln().max(0.0);
    }

    // Mild late-stream consolidation: prefer reusing bins as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 4.0 * progress * (bin_residual != bin_capacity) as i32 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: penalize large post-residual quadratically.
    score += 0.015 * (post_residual as f64).powi(2);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    // Dead-space penalty: residual too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 30 {
        score += (30 - post_residual) as f64 * 0.8;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: does the next item fit in the post-residual?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Chain-friendly placement.
            score -= 8.0;
            // Extra reward if next item fills it nearly exactly.
            let gap = post_residual - next_item_size;
            if gap <= 10 {
                score -= 6.0;
            }
        } else if next_item_size <= bin_residual {
            // Next item fits this bin now, but would be blocked by this placement.
            score += 10.0;
        }
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        // Prefer a fresh bin when the fit is loose and open bins are crowded.
        let tightness = item_size as f64 / bin_capacity as f64;
        if post_residual as f64 > mean_residual {
            score += 15.0 * (1.0 - tightness);
        }
        // Early in stream: opening new bins is cheap (spreads load).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 12.0 * (1.0 - progress);
        // If many bins already fit the item, opening a new one is wasteful.
        if fitting_bins_count > 2 {
            score += 20.0;
        }
    }

    // Global state coupling: prefer bins with residual near the mean (balanced packing),
    // unless this placement is exceptionally tight.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Late-stream consolidation: favor filling existing bins rather than spreading.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Slight preference for using fewer open bins overall.
    score -= 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64 / cap;
    let it = item_size as f64 / cap;

    // Base: quadratic penalty on wasted post-residual
    let mut score = pr * pr * 100.0 + pr * 30.0;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, waste is more tolerable (favor opening/spreading);
    // late, waste is costly (favor tight fits).
    let coupling = (1.0 - progress) * (pr - 0.5) * (pr - 0.5) * 40.0
                 - progress * pr * (1.0 - pr) * 25.0;
    score += coupling;

    // Reward good fit density (item fills large fraction of residual)
    let fill = it * (it / (bin_residual as f64 / cap)).min(1.0);
    score -= fill * 60.0;

    // Last-chance bin: strong reward, modulated by progress
    if fitting_bins_count == 1 {
        score -= 45.0 + 30.0 * progress;
    } else {
        score += 8.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // Lookahead: reward if next item fits post-residual, penalize near-miss
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post_residual as f64 {
            score -= 20.0 * (1.0 - (nxt / (post_residual as f64 + 1.0)));
        } else {
            score += 12.0 * (1.0 - progress);
        }
    }

    // Prefer bins with residual below mean residual (denser bins first)
    score += (mean_residual - bin_residual as f64) * 0.15;

    // Mild penalty on opening new bins when many are open
    if bin_residual == bin_capacity {
        score += 10.0 + 5.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: partition residual space into
    // capacity-fraction bands. Dead space below the smallest item is worthless.
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    let three_quarter = 3 * quarter;

    // Penalize residuals that fall into "useless" harmonic classes
    // (too small to hold a mid-size item, too large to be considered tight).
    if post_residual < 10 {
        score += 100.0; // pure dead space
    } else if post_residual < quarter {
        // residual in (0,25): only fits tiny items -> mild penalty unless last chance
        score += 12.0;
    } else if post_residual < half {
        score -= 4.0; // sweet spot: can host half-capacity items
    } else if post_residual < three_quarter {
        score += 2.0; // mediocre: large residual left after small item
    }

    // Integer-division harmonic class: post_residual / 10 buckets.
    // Reward buckets aligned to common item sizes (10s and 25s).
    let bucket = post_residual / 10;
    match bucket {
        0 => score += 30.0,
        1 | 2 => score -= 6.0,   // ~10-29 left: good for small follow-ups
        3 | 4 => score -= 10.0,  // ~30-49 left: hosts medium items
        5 | 6 => score += 5.0,   // ~50-69: awkward middle
        _ => score += 15.0,      // large leftover: wasteful placement
    }

    // Modulo coupling with next_item_size lookahead: if the next item
    // divides the post_residual evenly (harmonic match), reward strongly.
    if next_item_size > 0 && next_item_size <= post_residual {
        if post_residual % next_item_size == 0 {
            score -= 18.0;
        } else if post_residual >= next_item_size + 10 {
            score -= 6.0;
        } else {
            score += 8.0; // next item barely fits: risk of dead space after
        }
    } else if next_item_size > post_residual && next_item_size > 0 {
        // post_residual cannot host the next item at all: it becomes dead space
        score += (post_residual as f64) * 0.5;
    }

    // Last-chance bonus: only bin that fits -> avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless current
    // placements are all poor fits. Scale pressure with stream progress.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 45.0 - 25.0 * progress;
        if fitting_bins_count == 0 {
            score -= 60.0; // nothing fits anywhere: must open
        }
    }

    // Tight-fit reward: near-exact fills are ideal.
    if post_residual <= 5 {
        score -= 20.0;
    }

    // Mean-residual coupling: prefer bins deviating below the mean
    // (compact the small leftovers together, keep big holes big).
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Mild open-bin pressure: fewer open bins is better when scores tie.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero gaps are the worst outcome.
    if post_residual > 0 {
        let gap = post_residual as f64;
        // Penalize gaps that are too small to host any plausible future item
        // (items in [1,100]; a gap under ~10 is almost surely dead space).
        if gap < 10.0 {
            score += 60.0 * (10.0 - gap) / 10.0;
        } else if gap < 25.0 {
            // Medium-small gaps: moderately hostile, scaled by stream progress.
            let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
            score += 15.0 * (1.0 - progress) * (25.0 - gap) / 25.0;
        }
        // Very large leftover is fine (bin stays flexible): slight reward.
        if gap > 50.0 {
            score -= 5.0;
        }
    } else {
        // Perfect fit: strongly reward closing the bin exactly.
        score -= 100.0;
    }

    // Reward tight fits relative to residual (waste ratio penalty).
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    score += 20.0 * waste_ratio;

    // Open-bin pressure: when many bins are open, prefer filling existing ones
    // over spreading; when few bins are open, spreading is cheaper.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score -= 4.0 * pressure * (1.0 - waste_ratio);

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            if slack < 10.0 { score -= 10.0; } else { score += slack * 0.1; }
        } else {
            // Next item won't fit here: mild penalty, stronger late in stream.
            let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
            score += 5.0 + 10.0 * progress;
        }
    }

    // New-bin candidate handling: an empty bin is flexible but should only win
    // when no open bin offers a good fit. Base penalty keeps it behind decent fits.
    if bin_residual == bin_capacity {
        score += 25.0;
        // Late in the stream or with many open bins, opening new bins is worse.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0 * progress + 2.0 * open_bins_count as f64;
        // But if the item is large, a fresh bin is actually attractive.
        if item_size >= 60 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual with next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs();
        if diff == 0 {
            // Perfect two-item fill: strongly favored.
            score -= 60.0;
        } else {
            // Penalize gap between what we leave and what comes next,
            // scaled by how much of the bin is already used.
            let tightness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
            score += diff as f64 * (0.4 + 0.6 * tightness);
        }
        // If next item fits exactly into the CURRENT residual (place now, next elsewhere? no:
        // if residual == next size, leaving this residual is ideal).
        if bin_residual as i64 - item_size as i64 == next_item_size as i64 {
            score -= 25.0;
        }
    } else {
        // Last item: just minimize waste.
        score += 0.0;
    }

    // Dead-space penalty: post_residual too small for typical future items (1..100 range).
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Prefer bins tighter than the mean residual (well-filled bins).
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Early in stream: be more willing to open new bins for large items,
    // late in stream: consolidate into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus progress-dependent reluctance.
        score += 5.0 + 20.0 * progress;
        // Opening a new bin is attractive if item is large and no tight fit exists.
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small dead space after placement).
    score += (post_residual as f64).powi(2) / bin_capacity as f64 * 0.6;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // Slight penalty when many alternatives exist, scaled by how many.
        score += (fitting_bins_count as f64).ln() * 2.0;
    }

    // New-bin candidate handling: opening a fresh bin wastes residual elsewhere.
    if bin_residual == bin_capacity {
        // Cost of opening a new bin: proportional to mean leftover in open bins.
        let waste = mean_residual.max(0.0) * (open_bins_count as f64).sqrt() * 0.4;
        score += 15.0 + waste;
        // Reward opening a new bin for large items (good long-term residual shape),
        // and when next item is small (fits in leftover of other bins anyway).
        if item_size >= 50 {
            score -= (item_size - 50) as f64 * 0.5;
        }
        if next_item_size > 0 && next_item_size <= post_residual as u32 {
            score -= 8.0; // next item can also use this fresh bin
        }
    } else {
        // Reward reusing an open bin, more so when it's already fragmented.
        score -= 5.0;
    }

    // Lookahead: penalize leaving a residual that neither fits nor is useful,
    // reward residuals that exactly match the next item.
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        if post_residual as f64 >= nr {
            // Next item fits here: reward proportional to snugness.
            score -= 10.0 * (1.0 - ((post_residual as f64 - nr) / bin_capacity as f64));
        } else {
            // Dead space relative to lookahead item.
            score += (nr - post_residual as f64) * 0.15;
        }
    }

    // Time horizon: early in the stream, be conservative (favor reuse);
    // late in the stream, allow new bins since future amortization is short.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= progress * 10.0;
    } else {
        score += (1.0 - progress) * 3.0;
    }

    // Global state: many open bins -> discourage opening more; few -> allow.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 0.8;
    }

    // Discourage extremely small unusable slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Normalized post-residual (fraction of capacity left after placement)
    let x = pr / cap;

    // Base: prefer small post-residual, with a smooth non-linear polynomial
    // shaping that penalizes both very large leftover space (wasteful) and
    // very tiny leftover space (unusable dead space) asymmetrically.
    let mut score = x * x * (2.0 - x) * cap;

    // Smooth polynomial coupling with stream progress: later in the stream,
    // tighten the preference for tight fits (residual minimization gains weight).
    let progress_coupling = 1.0 + 2.0 * progress * progress;
    score *= progress_coupling;

    // Non-linear interaction: dead-space penalty grows super-linearly when the
    // leftover cannot plausibly hold the next item, smoothed via a quadratic gate.
    let nxt = next_item_size as f64;
    if nxt > 0.0 {
        let gap = (nxt - pr).max(0.0) / cap;
        score += 40.0 * gap * gap * (1.0 + progress);
    }

    // Reward filling bins tightly relative to the mean residual of open bins,
    // with a smooth saturating polynomial of the deviation.
    let dev = (mean_residual - pr) / cap;
    score -= 12.0 * dev * (1.0 - dev * dev).max(0.0);

    // Last-chance bonus: if this is the only fitting bin, strongly discourage
    // opening a new bin (subtract from score so this bin wins).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 * (1.0 - progress * 0.5);
    }

    // Mild penalty for spreading across many open bins, smoothed by progress.
    score += (open_bins_count as f64).ln().max(0.0) * (2.0 + 4.0 * progress);

    // Slight preference for keeping new bins as fallback early in the stream.
    if bin_residual == bin_capacity {
        score += 6.0 * (1.0 - progress) * (1.0 - x);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fill: strongest reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Harmonic dead-space class: residual in [1,9] can never fit another
    // item (sizes >= 1..100 unknown, but tiny residual = sealed bin).
    if post_residual >= 1 && post_residual < 10 {
        score -= 45.0;
    }

    // Modulo-10 harmonic class: residuals whose last digit is high leave
    // awkward gaps for typical item granularities; mildly penalize.
    let cls = (post_residual % 10) as f64;
    score += 0.35 * cls;

    // Integer-division threshold: residual >= 2 * 10 (two minimal slots)
    // is reusable; residual in [10,19] holds at most one small item.
    if post_residual >= 20 {
        score -= 8.0;
    } else if post_residual >= 10 {
        score += 4.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0;
        // Extra reward if next item exactly divides the residual class.
        if post_residual % next_item_size.max(1) == 0 {
            score -= 6.0;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Residual too small for the lookahead item: penalize proportionally.
        score += 0.25 * (next_item_size - post_residual) as f64;
    }

    // New-bin candidate handling (bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        // Base reluctance to open a new bin while others fit.
        score += 6.0;
        if fitting_bins_count > 0 {
            // If some open bin gives a tight fit (post_residual <= 25),
            // strongly prefer that bin over opening a fresh one.
            if post_residual <= 25 {
                score += 35.0;
            }
        }
        // Last-chance bin: if this is the only bin that can fit the item,
        // opening a new bin is wasteful — favor using it.
        if fitting_bins_count == 1 {
            score -= 30.0;
        }
        // If the next item is large and would pair well with the fresh
        // residual, opening a new bin becomes more attractive.
        if next_item_size > 0 && (bin_capacity - next_item_size) >= item_size {
            score -= 12.0;
        }
    }

    // Stream progression: later in the stream, prefer bins whose residual
    // is close to the mean (consolidation of slack).
    let t = step_index as f64 / (total_items.max(1) as f64);
    score -= t * 0.12 * (mean_residual - post_residual as f64);

    // Many open bins: encourage tightening the spread of residuals.
    if open_bins_count > 4 {
        score += 0.08 * (post_residual as f64 - mean_residual).abs();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable gaps harder (dead space avoidance)
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 20.0 * (20 - post_residual) as f64 / 20.0;
    }

    // Reward near-perfect fits
    if post_residual == 0 {
        score -= 100.0;
    }

    // Open bins pressure: discourage spreading across many bins
    if bin_residual != bin_capacity {
        score -= 5.0; // mild bonus for reusing an existing bin
    } else {
        score += 8.0 * (open_bins_count as f64 / 20.0).min(1.0);
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Lookahead: if next item fits into post_residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // If next item would leave another dead gap, penalize slightly
    if next_item_size > 0 && post_residual > next_item_size && (post_residual - next_item_size) < 10 {
        score += 10.0;
    }

    // Mean residual coupling: prefer bins whose residual is below mean (tighter bins)
    score += (bin_residual as f64 - mean_residual) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer post_residual == 0 (perfect fit)
    if post_residual == 0 {
        score -= 60.0;
    }

    // 2-step lookahead: reward bins whose leftover can host the next item
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item fits exactly or well after this placement
            score -= 20.0;
            if next_item_size == post_residual {
                score -= 30.0; // chain of perfect fits
            }
        } else {
            // next item won't fit here; penalize leaving awkward gaps
            score += 8.0;
        }
        // penalize residuals just below next_item_size (dead space for lookahead)
        let gap = next_item_size as f64 - post_residual as f64;
        if gap > 0.0 && gap <= 20.0 {
            score += (20.0 - gap) * 0.8;
        }
    }

    // Compare against mean residual: prefer bins with residual close to item size
    let res_f = bin_residual as f64;
    if res_f < mean_residual {
        score -= (mean_residual - res_f) * 0.5; // tighter bin favored
    } else {
        score += (res_f - mean_residual) * 0.3; // loose bin penalized
    }

    // Last-chance bin bonus: avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: only attractive if no open bin fits well
    if bin_residual == bin_capacity {
        score += 25.0; // default penalty for opening a new bin
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // fresh bin useful for large upcoming item
        }
        if post_residual as f64 > mean_residual + 40.0 {
            score -= 12.0; // item small relative to typical residual: new bin fine
        }
    }

    // Mild phase term: later in stream, consolidation matters more
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 3.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tightness of the fit: reward small post_residual relative to item size
    let fit_ratio = item_size as f64 / bin_capacity as f64;
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * (0.5 + fit_ratio);

    // Dead-space penalty: residual that is too small to be useful later
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, strongly reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size < post_residual {
            score -= 6.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item cannot use leftover space: penalize wasted space
            score += 4.0 * post_residual as f64 / bin_capacity as f64;
        }
    } else {
        // last item: prefer filling existing bins maximally
        score -= 15.0 * tightness;
    }

    // Last-chance bonus: if this is the only bin that can fit the item
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        // many alternatives: mild penalty to prefer better fits elsewhere
        score += 1.5 * (fitting_bins_count as f64).ln();
    }

    // Global state: when mean residual is high, prefer consolidating into open bins
    if mean_residual > 0.0 {
        let rel = post_residual as f64 / mean_residual;
        score += 3.0 * (rel - 1.0).abs().min(5.0);
    }

    // Late in the stream, discourage opening new bins
    if bin_residual == bin_capacity {
        score += 10.0 + 40.0 * progress;
        // but early on, a fresh bin is cheap and gives flexibility
        score -= 8.0 * (1.0 - progress);
    }

    // Mild preference for bins that are neither too empty nor too full
    let fill = 1.0 - bin_residual as f64 / bin_capacity as f64;
    score += 2.0 * (fill - 0.5).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / (total_items as f64 - 1.0) } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    // Base: post residual, with non-linear polynomial coupling to progress
    let mut score = pr;

    // Quadratic/cubic penalty on wasted residual, growing with stream progress
    let waste = norm_pr * norm_pr;
    score += 60.0 * waste * (0.5 + progress);
    score += 25.0 * norm_pr * norm_pr * norm_pr;

    // Reward tight fits (small post residual) more strongly as stream advances
    score -= 40.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * progress;

    // Interaction: residual that could still fit the lookahead item is valuable
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 * (1.0 - norm_next) * (1.0 - progress);
    } else if next_item_size > 0 {
        // Dead space relative to lookahead: penalize smoothly
        let gap = (next_item_size - post_residual) as f64 / cap;
        score += 20.0 * gap * gap;
    }

    // Fragmentation pressure: many open bins with high mean residual
    let bin_pressure = (open_bins_count as f64 / (1.0 + open_bins_count as f64)) * (mean_residual / cap);
    score += 30.0 * bin_pressure * (0.3 + progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 45.0 * (1.0 - progress * 0.5);
    }

    // New empty bin candidate: penalize mildly unless current fit is terrible
    if bin_residual == bin_capacity {
        score += 10.0 + 50.0 * (1.0 - norm_item) * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: best-fit core (minimize post_residual), scaled.
    score = post_residual as f64 * 1.0;

    // Harmonic class of post_residual: residue modulo capacity quarters.
    // Post-residuals in the smallest class (0..=10) are near-perfect fits.
    let quarter = bin_capacity / 4; // 25
    let r = (post_residual % quarter) as f64;
    let class = post_residual / quarter; // 0..=4 harmonic band
    match class {
        0 => score -= 8.0 + (quarter as f64 - r) * 0.15, // tiny leftover: excellent
        1 => score -= 3.0,                               // quarter-class: decent
        2 => score += 2.0,                               // half-class: mediocre
        3 => score += 6.0,                               // three-quarter: wasteful
        _ => score += 10.0,                              // nearly empty bin: bad choice
    }

    // Lookahead coupling: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let next_post = post_residual - next_item_size;
            // Reward tight sequential packing.
            score -= 6.0 - (next_post.min(20) as f64) * 0.2;
            // Harmonic bonus: next item leaves a residue in a small class.
            let nr = next_post % quarter;
            if nr <= 5 {
                score -= 4.0;
            }
        } else if next_item_size <= bin_residual {
            // Next item would need this bin's original residual; mild penalty
            // for consuming it now with a loose fit.
            if post_residual > 15 {
                score += 3.0;
            }
        } else {
            // Next item won't fit here regardless; prefer conserving residual
            // only if post_residual is genuinely dead space.
            if post_residual < next_item_size && post_residual > 0 {
                score += 1.0;
            }
        }
    } else {
        // Last item: just minimize waste.
        score -= 5.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin, unless post_residual is huge dead space.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
        if post_residual > 40 {
            score += 8.0;
        }
    }

    // New-bin candidate: residual == capacity. Give it a middling score so
    // it loses to good fits but beats poor fits (large post_residual).
    if bin_residual == bin_capacity {
        score = 55.0
            + (open_bins_count as f64).ln().max(0.0) * 2.0
            + (step_index as f64 / total_items.max(1) as f64) * 5.0;
        // If next item is large and mean residual is fragmented, opening fresh
        // becomes more attractive.
        if next_item_size > 60 && mean_residual < 30.0 {
            score -= 10.0;
        }
    }

    // Global pressure: many open bins with high mean residual -> discourage
    // spreading waste, encourage filling existing bins.
    if open_bins_count > 3 && mean_residual > 25.0 && bin_residual < bin_capacity {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Dead space avoidance: small unusable gaps are the worst outcome ---
    let pr = post_residual as f64;
    if post_residual > 0 && post_residual < 10 {
        // tiny gap: nearly worthless leftover space -> heavy penalty
        score += (10.0 - pr) * 12.0;
    } else if post_residual == 0 {
        // perfect fit: strongly reward
        score -= 40.0;
    } else {
        // moderate residual: mild decay so bigger usable leftovers preferred
        score += 0.15 * pr;
    }

    // --- Last-chance bonus: if this is the only bin that fits, avoid new bin ---
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // --- Lookahead: if the next item fits exactly in post_residual, reward ---
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0;
        if next_item_size == post_residual {
            score -= 20.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 && post_residual < 10 {
        // next item can't use this dead space -> extra penalty
        score += 10.0;
    }

    // --- Open bins pressure: discourage proliferation of bins ---
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (1.5 + 3.0 * progress);

    // --- Deviation from mean residual: prefer bins already below-average fullness usage ---
    score += 0.3 * (mean_residual - bin_residual as f64);

    // --- New empty bin candidate: only attractive when item is large or no good fit ---
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 >= 0.7 * bin_capacity as f64;
        if large_item || fitting_bins_count == 0 {
            score -= 15.0;
        } else {
            // penalize opening a new bin when existing bins could fit
            score += 20.0 + 5.0 * (fitting_bins_count as f64);
        }
        // residual after placing in fresh bin is large; slight normalization
        score += 0.05 * pr;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when the post residual matches the
    // next item size exactly (perfect chain), scaled by lookahead availability.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        let match_bonus = 60.0 / (1.0 + diff * 0.35);
        score -= match_bonus;
        // Penalize residuals that are too small to ever fit the next item
        if (post_residual as u32) < next_item_size {
            score += 0.35 * (next_item_size - post_residual) as f64;
        }
    }

    // Penalize tiny dead space (unusable slivers) with a nonlinear wedge.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (10 - post_residual) as f64;
    }

    // Compare against mean residual: prefer bins whose residual is tighter
    // than average (avoid spreading space thin across many bins).
    score += 0.5 * ((post_residual as f64) - mean_residual).max(0.0);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when item barely fits anywhere or
    // open bins are nearly full. Penalize opening a new bin when good fits exist.
    if bin_residual == bin_capacity {
        let tightness = (item_size as f64) / (bin_capacity as f64);
        let pressure = if open_bins_count > 0 { mean_residual / (bin_capacity as f64) } else { 0.0 };
        score = 100.0 - 30.0 * tightness - 50.0 * pressure;
        if next_item_size > 0 && (bin_capacity - item_size) >= next_item_size {
            score -= 15.0; // fresh bin can chain the next item too
        }
        if fitting_bins_count == 1 {
            score += 60.0; // don't abandon the only fitting bin
        }
    }

    // Mild stream progression term: late in the stream, consolidate harder.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - (post_residual as f64) / (bin_capacity as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor placements that nearly fill the bin.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 2.5 * tightness * tightness * (bin_residual as f64);

    // Dead-space penalty: residuals that are too small for the smallest item are wasted.
    if post_residual < 10 && post_residual > 0 {
        score += 40.0;
    } else if post_residual == 0 {
        score -= 30.0; // perfect fill
    }

    // Lookahead: reward if next item fits in the post residual (chaining), penalize otherwise.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0 + 0.1 * next_item_size as f64;
        } else {
            score += 0.05 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Penalize dumping large items into bins with large residuals when other fits exist.
    if fitting_bins_count > 1 {
        let waste = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
        score += 10.0 * waste;
    }

    // Global state coupling: spread load when many bins are open with high mean residual.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: acceptable early or when open bins are nearly full on average.
        let avg_tight = 1.0 - (mean_residual / bin_capacity as f64);
        let pressure = open_bins_count as f64 * avg_tight;
        score += 15.0 + 0.5 * open_bins_count as f64 - 0.3 * pressure - 20.0 * progress;
    } else {
        // Favor using existing bins more as the stream progresses.
        score -= 5.0 * progress;
        // Slight preference for bins below mean residual (balance residuals).
        score += 0.02 * (bin_residual as f64 - mean_residual);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let fit_norm = (item_size as f64) / cap;
    let next_norm = (next_item_size as f64) / cap;

    // Base: post residual, with non-linear polynomial shaping by stream progress
    let mut score = pr * (1.0 + 0.8 * progress * norm_pr);

    // Quadratic coupling: penalize mid-range dead space more as stream advances
    score += 40.0 * progress * norm_pr * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Reward tight fits (small post residual), stronger later in the stream
    score -= 25.0 * (1.0 - progress) * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Lookahead: reward if next item fits the post residual smoothly
    if next_item_size > 0 {
        let gap = next_norm - norm_pr;
        let fit_next = if gap <= 0.0 { 1.0 - gap * gap } else { 1.0 / (1.0 + 3.0 * gap * gap) };
        score -= 18.0 * fit_next * (1.0 - 0.5 * progress);
    }

    // Last-chance bin: strong reward to avoid wasting it
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 - norm_pr * norm_pr);
    }

    // Mild penalty for opening new bins when many open bins exist with slack
    if bin_residual == bin_capacity {
        score += 12.0 + 6.0 * (open_bins_count as f64).sqrt() * (1.0 - progress) + mean_residual * 0.05;
    }

    // Coupling with mean residual: prefer bins near the mean (smooth gaussian-ish)
    let dev = norm_pr - mean_residual / cap;
    score += 8.0 * dev * dev * (0.5 + 0.5 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: small dead space in classes that
    // match typical small item sizes is more reusable.
    let pr = post_residual;
    let class_bonus: f64 = if pr == 0 {
        0.0
    } else if pr <= 10 {
        // tiny dead space, nearly unusable
        30.0
    } else if pr <= 20 {
        10.0
    } else if pr <= 40 {
        0.0
    } else if pr <= 60 {
        -10.0
    } else {
        -20.0
    };
    score -= class_bonus;

    // Reward when post_residual can exactly fit the next item (lookahead pairing)
    if next_item_size > 0 && pr >= next_item_size {
        if pr == next_item_size {
            score -= 200.0;
        } else {
            score -= 40.0;
        }
    } else if next_item_size > 0 {
        // post_residual too small for next item: penalize proportionally
        score += 0.5 * (next_item_size as f64 - pr as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Prefer bins with tighter residual (best-fit flavor) scaled by fill fraction
    let fill = 1.0 - bin_residual as f64 / cap;
    score -= 50.0 * fill * fill;

    // New-bin candidate: neutral-ish baseline; make it attractive only when
    // existing bins would leave very awkward residuals or are crowded.
    if bin_residual == bin_capacity {
        score = 60.0 + 0.1 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 20.0; // fresh bin handles big next item well
        }
        if fitting_bins_count == 1 {
            score += 100.0; // don't abandon the last fitting bin
        }
    }

    // Late-stream consolidation: favor reusing open bins to close them out
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 30.0 * progress * (1.0 - (post_residual as f64 / cap));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // (below the minimum conceivable item size) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    } else if post_residual == 0 {
        // Perfect fit: strongly rewarded.
        score -= 80.0;
    }

    // Reward placing into tight residuals (waste-avoidance pressure).
    let tightness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness;

    // Open-bin pressure: discourage spreading across many bins.
    score += 2.5 * open_bins_count as f64;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 45.0;
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // reward this placement; if the next item would not fit but the
    // current residual would have held it, penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 20.0;
        } else if next_item_size <= bin_residual && post_residual > 0 {
            score += 15.0;
        }
    }

    // New-bin candidate logic: only attractive when no open bin offers a
    // reasonable fit (i.e., all fits would leave large dead space or the
    // bin is nearly full and the item is large).
    if bin_residual == bin_capacity {
        let bad_fit_exists = fitting_bins_count > 0
            && mean_residual > item_size as f64 + 15.0;
        if bad_fit_exists {
            score += 100.0; // keep using open bins when fits are decent
        } else {
            score -= 25.0; // opening a fresh bin is preferable to a bad fit
        }
    }

    // Stream progression: late in the stream, be slightly more conservative
    // about opening bins.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        if bin_residual == bin_capacity {
            score += 10.0 * progress;
        }
    }

    // Coupling: penalize placements that leave residual far below the mean
    // (fragmenting the pool of usable space).
    if post_residual > 0 {
        let gap = mean_residual - post_residual as f64;
        if gap > 0.0 {
            score += 0.3 * gap;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit bonus: reward tight packing.
    if post_residual == 0 {
        score -= 60.0;
    }

    // 2-step lookahead: if the next item fits exactly into the post-residual,
    // this is a great chain placement.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 80.0;
        } else if post_residual >= next_item_size {
            // next item fits, but leaves some slack; penalize leftover slack mildly
            score -= 20.0 - 0.3 * (post_residual - next_item_size) as f64;
        } else {
            // next item will NOT fit here; dead space created for lookahead
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Compare against mean residual: bins far below mean residual are "fresh"
    // and better used for awkward future items; penalize wasting them.
    let res_f = post_residual as f64;
    if res_f > mean_residual {
        score += 0.25 * (res_f - mean_residual);
    } else {
        score -= 0.10 * (mean_residual - res_f);
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // Baseline cost of a new bin; adjusted by how many alternatives exist.
        let scarcity = if fitting_bins_count == 0 { 0.0 } else { 35.0 };
        score = score.max(0.0) + 55.0 + scarcity
            - 0.15 * (open_bins_count as f64)
            - (step_index as f64 / (total_items.max(1) as f64)) * 10.0;
        // If next item is large and current item small, opening a fresh bin is fine.
        if next_item_size > 60 && item_size < 40 {
            score -= 25.0;
        }
    }

    // Late in the stream: consolidate harder, avoid opening new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress > 0.8 && bin_residual < bin_capacity {
        score -= 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: best-fit (minimize post residual) with a slight super-linear push
    // toward tight fits so near-exact matches are strongly preferred.
    score += (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64) * 0.01;

    // Lookahead: if the next item fits exactly into the post-residual, reward
    // this placement strongly (chained perfect fits).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            // Next item fits after this one: mildly good, scaled by how tight.
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit in the remaining space: penalize creating
            // dead space that strands the lookahead item.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.15 * waste;
        }
    }

    // Last-chance logic: if this is the ONLY bin that can fit the item,
    // heavily reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Penalize placements that leave hard-to-fill slivers (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Global state coupling: prefer filling bins below the mean residual
    // (draining underfilled bins) when many bins are open.
    let mean_gap = mean_residual - bin_residual as f64;
    if mean_gap > 0.0 {
        score -= 0.3 * mean_gap.min(50.0);
    }

    // Time horizon: early in the stream, be more conservative (favor tight
    // fits more); late in the stream, slightly favor consolidating into
    // existing bins to close them out.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 - 0.1 * progress;

    // New-bin candidate (empty bin): only attractive when the item is large
    // relative to typical residuals or no good existing fit exists; otherwise
    // push it behind open bins.
    if bin_residual == bin_capacity {
        score += 15.0 + 0.2 * open_bins_count as f64;
        // Large items deserve fresh space.
        if item_size >= 70 {
            score -= 20.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 5.0;
        }
    }

    // Mild penalty for spreading across too many open bins.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / (total_items - 1) as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr
        + 18.0 * norm_pr * norm_pr * (1.0 + progress)
        - 14.0 * norm_pr * progress * (1.0 - progress);

    // Penalize tiny dead space that likely becomes unusable
    if pr > 0.0 {
        score += 10.0 * (1.0 - pr / cap) * (-(pr / 12.0)).exp();
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: reward residual that can host the next item
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr >= ni {
            score -= 8.0 * (ni / cap) * (1.0 + progress);
        } else {
            score += 5.0 * (ni - pr) / cap;
        }
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: mildly penalize early, more acceptable late
    if bin_residual == bin_capacity {
        score += 15.0 * (1.0 - 0.7 * progress) + 0.05 * mean_residual;
    }

    // Mild pressure toward consolidation when many bins are open
    score += 0.01 * open_bins_count as f64 * (1.0 - norm_pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // --- Harmonic class of post_residual: reward residuals that are likely reusable ---
    // Perfect fit: zero residual is ideal.
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // Class residuals by divisibility structure: small multiples of common item
        // size classes (10/20/25/50) are more reusable for typical streams.
        let pr = post_residual;
        let mut harmony_bonus = 0.0;
        if pr % 10 == 0 { harmony_bonus += 6.0; }
        if pr % 20 == 0 { harmony_bonus += 4.0; }
        if pr % 25 == 0 { harmony_bonus += 3.0; }
        if pr % 50 == 0 { harmony_bonus += 5.0; }
        score -= harmony_bonus;

        // Dead-space penalty: residuals too small for the smallest plausible item.
        if pr < 10 {
            score += 40.0;
        } else if pr <= 15 {
            score += 12.0;
        }

        // Fractional capacity banding: residual < 1/4 of capacity is mostly dead space.
        let quarter = cap / 4.0;
        if (pr as f64) < quarter {
            score += 8.0;
        }

        // Lookahead harmony: if the next item fits exactly in post_residual,
        // strongly reward; if next item cannot fit, mildly penalize.
        if next_item_size > 0 {
            if next_item_size == pr {
                score -= 55.0;
            } else if next_item_size <= pr {
                // next fits: residual class match with next item
                if pr % next_item_size == 0 {
                    score -= 10.0;
                }
                score -= 4.0;
            } else {
                score += 5.0;
            }
        }
    }

    // Tightness reward: favor bins where the item fills a large fraction of residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 25.0;

    // Last-chance bin: if this is the only bin that fits, prefer using it over
    // opening a new bin (penalize new-bin competition).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate (empty bin): make it costly unless nothing else is good.
    if bin_residual == bin_capacity {
        score += 45.0;
        // Exception: item is huge relative to capacity, or many bins open and
        // mean residual is fragmented — then a fresh bin is attractive.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if item_size as f64 > 0.7 * cap {
            score -= 30.0;
        }
        if open_bins_count > 6 && mean_residual < 0.25 * cap {
            score -= 20.0;
        }
        // Early in stream, opening bins is cheaper (build diversity of partial bins).
        if progress < 0.15 {
            score -= 10.0;
        }
    }

    // Fragmentation guard: avoid spreading across too many open bins when
    // mean residual is already high (many half-empty bins).
    if open_bins_count > 4 && mean_residual > 0.5 * cap && bin_residual != bin_capacity {
        score += 6.0;
    }

    // Mild step-dependent drift: later in the stream, consolidation matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that no item (>=1) can use are pure waste,
    // and small gaps (below typical item sizes) are nearly unusable.
    if post_residual == 0 {
        score -= 60.0; // perfect fit: strongly reward
    } else if post_residual < 10 {
        score += 40.0; // tiny unusable gap: heavy penalty
    } else if post_residual < 20 {
        score += 18.0;
    } else if post_residual < 35 {
        score += 6.0;
    }

    // Reward tight fits relative to item size (waste ratio penalty).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fit_ratio * fit_ratio;

    // Open-bin pressure: discourage spreading across many bins, but soften late in stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (1.5 - 0.8 * progress);

    // Prefer bins whose residual is close to the mean (keep bin states homogeneous).
    score += 0.15 * (bin_residual as f64 - mean_residual).abs();

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            // next item cannot use this gap; penalize proportionally to wasted gap
            score += 0.3 * post_residual as f64;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && post_residual > 0 {
        score -= 20.0;
    }

    // New-bin candidate (empty bin): make it moderately attractive so we open a new
    // bin only when existing fits create dead space, but not so attractive that we
    // always open new bins.
    if bin_residual == bin_capacity {
        score = 45.0 + 0.5 * item_size as f64;
        if fitting_bins_count == 0 {
            score -= 50.0; // no open bin fits: must open new bin
        }
        if fitting_bins_count == 1 {
            score += 15.0; // keep the last-chance bin attractive
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are excellent: reward small post_residual.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Aggressive 2-step lookahead: perfect if next item exactly fills post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Next item fits here too: good, but worse than exact fill.
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / (bin_capacity as f64));
        } else {
            // Next item cannot use the leftover: penalize dead space proportionally.
            let dead = (next_item_size - post_residual) as f64;
            score += 0.35 * dead;
        }
    }

    // Compare post_residual against mean residual across open bins:
    // leaving less than average is efficient; leaving more wastes space.
    let mr = if mean_residual.is_finite() { mean_residual } else { 0.0 };
    if post_residual as f64 > mr {
        score += 0.5 * (post_residual as f64 - mr);
    } else {
        score -= 0.3 * (mr - post_residual as f64);
    }

    // Last chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Penalize opening a new bin when good fitting bins exist.
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline penalty, reduced if item is large.
        score += 15.0;
        if item_size >= 50 {
            score -= 10.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
        // Many open bins: avoid opening yet another.
        score += 1.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic bonus for small post-residual.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 60.0 * tight * tight;

    // Penalize dead space that nothing (size >= 10, or next item) can use.
    let min_size = if next_item_size > 0 && next_item_size < 10 { next_item_size } else { 10 };
    if post_residual > 0 && post_residual < min_size {
        score += 80.0; // unusable sliver
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Lookahead synergy: residual can host the next item.
        let gap = post_residual - next_item_size;
        score -= 25.0 * (1.0 - gap as f64 / bin_capacity as f64);
    } else if next_item_size > 0 {
        score += 15.0; // residual too small for lookahead item
    }

    // New-bin candidate handling.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Prefer opening a new bin when the item fits poorly everywhere:
        // i.e., best existing fit would leave a big awkward residual.
        let poor_fit = post_residual as f64 / bin_capacity as f64;
        // Base new-bin score: attractive when existing bins are numerous and fragmented.
        score = 40.0 + 30.0 * poor_fit;
        // Early in stream, keep bins consolidated; later, allow spreading.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * (1.0 - progress);
        // Many open bins with large mean residual: discourage new bin.
        score += 0.5 * open_bins_count as f64 + 0.3 * mean_residual;
        // If item is large, new bin is fine (it fills fresh space well).
        if item_size > bin_capacity / 2 {
            score -= 15.0;
        }
    } else {
        // Existing bins: slight preference for bins with less residual overall (consolidation),
        // but strong bonus when this bin is the last chance to avoid opening a new bin.
        score += 0.15 * (bin_residual as f64 - mean_residual);
        if fitting_bins_count == 1 {
            // Last chance: heavily favor using it unless the fit is terrible.
            let bad = post_residual as f64 / bin_capacity as f64;
            score -= 45.0 * (1.0 - bad * bad);
        }
        // Prefer bins whose residual is close to item size (best-fit sharpening).
        let waste = (bin_residual - item_size) as f64;
        score += 0.1 * waste;
    }

    // Global fragmentation guard: if many bins are open, discourage placements
    // that leave residuals near awkward mid-range values (hard to fill later).
    let mid_awkward = {
        let r = post_residual as f64;
        let center = bin_capacity as f64 * 0.35;
        let d = (r - center).abs();
        (1.0 - d / center).max(0.0)
    };
    score += 10.0 * mid_awkward * (open_bins_count as f64 / (open_bins_count as f64 + 4.0));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: wasted space after placement (lower is better fit).
    let mut score = pr;

    // Non-linear reward for tight fits: quadratic coupling of post_residual
    // with capacity, amplified as the stream progresses (endgame tightness matters).
    let tightness = 1.0 - pr / cap; // 1.0 = perfect fit
    score -= 30.0 * tightness * tightness * (0.5 + progress);

    // Penalize dead space that cannot host the lookahead item: smooth
    // non-linear interaction between post_residual and next_item_size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt).abs();
        // If post_residual just misses fitting next item, add a bump penalty.
        let miss = if pr < nxt { 1.0 } else { 0.0 };
        score += miss * 8.0 * (1.0 - (gap / cap).min(1.0)) * (1.0 - progress);
        // Reward residuals that exactly accommodate the next item (chaining).
        let chain = 1.0 - (gap / cap).min(1.0);
        score -= 10.0 * chain * chain;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (smooth in progress).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 * (0.5 + progress);
    }

    // New-bin candidate (bin_residual == bin_capacity): its raw post_residual
    // is large, but ensure it is not accidentally attractive; add a mild
    // opening cost that grows with the number of open bins.
    if bin_residual == bin_capacity {
        score += 6.0 + 0.5 * open_bins_count as f64;
    } else {
        // Slight preference for bins whose residual deviates from the mean
        // (consolidating waste into few bins).
        let dev = (pr - mean_residual) / cap;
        score += 4.0 * dev * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small residue" classes are more valuable to fill tightly.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class A: post_residual in (0, 10] -> excellent packing, reward strongly.
    if post_residual > 0 && post_residual <= 10 {
        score -= 30.0;
    }
    // Class B: post_residual in (10, 20] -> good, mild reward.
    else if post_residual <= 20 {
        score -= 12.0;
    }
    // Class C: post_residual in (20, 40] -> moderate dead space, slight penalty.
    else if post_residual <= 40 {
        score += 6.0;
    }
    // Class D: post_residual > 60 -> large dead space, heavy penalty.
    else if post_residual > 60 {
        score += 25.0;
    }

    // Modulo arithmetic on post_residual: residues that divide evenly into
    // typical item sizes (multiples of 10 / 20) are reusable classes.
    let m10 = post_residual % 10;
    if m10 == 0 {
        score -= 8.0; // perfectly aligned residue class
    } else if m10 >= 7 {
        score += 4.0; // awkward residue class, hard to refill
    }

    // Integer division thresholds: post_residual / 20 as a coarse class.
    let cls = post_residual / 20;
    score += cls as f64 * 3.0;

    // Lookahead coupling: if next item fits into post_residual, this bin
    // becomes a two-item chain -> reward proportional to tightness.
    if next_item_size > 0 && next_item_size <= post_residual {
        let chain_tightness = (post_residual - next_item_size) as f64;
        score -= 15.0 - chain_tightness * 0.2;
    }
    // If next item does NOT fit, penalize proportionally to how close it was
    // (near-miss wastes the residue class).
    else if next_item_size > 0 && next_item_size <= post_residual + 10 {
        score += 10.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when no good open-bin class exists.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin; offset when many bins are open and
        // mean residual is fragmented (consolidation is hopeless).
        let fragmentation = (mean_residual / cap) - 0.5;
        score = cap as f64 * 0.9 + open_bins_count as f64 * 2.0;
        if fragmentation > 0.2 {
            score -= 15.0 * fragmentation; // open new bin if open bins are wasteful
        }
        if next_item_size > 0 && next_item_size >= 50 {
            score -= 10.0; // big next item: fresh bin is valuable
        }
    }

    // Late-stream consolidation: near the end, prefer filling existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress > 0.8 && bin_residual != bin_capacity {
        score -= 10.0 * progress;
    }

    // Tie-break: prefer bins with lower residual relative to mean.
    score += 0.05 * (pr - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for any plausible item (min item 1,
    // but small gaps rarely reusable) are heavily penalized, non-linearly.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 12.0;
    }

    // Tight fit reward: penalize post_residual quadratically, but scaled so a
    // perfect fill (post_residual == 0) is strongly favored.
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 150.0;

    // If the next item fits exactly into the post_residual, reward heavily
    // (chain packing opportunity).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 - slack * 0.5;
    } else if next_item_size > post_residual {
        // Next item won't fit here; dead space is locked until bin closes.
        score += (next_item_size - post_residual) as f64 * 0.3;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // Open-bins pressure: with many open bins, prefer filling existing ones
    // over spreading; with few open bins, new-bin option is cheaper.
    score += open_bins_count as f64 * 1.5;

    // New-bin candidate handling: empty bin has large post_residual; make it
    // attractive only when the item fits poorly everywhere else (large
    // post_residual relative to mean residual) or few bins are open.
    if bin_residual == bin_capacity {
        let baseline = 25.0 + open_bins_count as f64 * 2.0;
        // If mean residual across open bins is large, opening new bin is fine.
        score = baseline + mean_residual * 0.2;
        if fitting_bins_count <= 2 {
            score -= 30.0;
        }
        // Early in stream, new bins are cheap.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 15.0;
    }

    // Mild reward for bins whose residual is close to item (good fill ratio).
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: perfect match with next item is heavily rewarded.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs();
        score -= 40.0 * (1.0 - diff as f64 / bin_capacity as f64).max(0.0);
        // Exact chain fit: item + next item fills bin completely.
        if post_residual == next_item_size {
            score -= 100.0;
        }
        // Post-residual too small for next item: dead space penalty grows as it shrinks.
        if post_residual < next_item_size && post_residual > 0 {
            score += 12.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    }

    // Penalize unusable dead space (smaller than the minimum plausible item).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Compare post_residual against mean residual across open bins: keeping
    // residuals balanced avoids many near-empty bins.
    score += 0.35 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin: strongly favor using it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when no open bin offers a decent fit
    // (i.e., this item would leave a very tight or very wasteful residual).
    if bin_residual == bin_capacity {
        let waste = (bin_capacity - item_size) as f64;
        let decent_fit = fitting_bins_count > 0 && post_residual <= bin_capacity / 2;
        if decent_fit {
            score += 60.0; // discourage opening new bin when a decent fit exists
        } else {
            score -= 5.0 + 0.1 * waste; // slight preference for fresh bin on bad fits
        }
    }

    // Slight early-stream preference for compact packing; later, consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 2.0 * open_bins_count as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic decay of penalty as post_residual shrinks.
    let pr = post_residual as f64;
    score -= (bin_capacity as f64 - pr) * 0.35;

    // Penalize dead space that cannot fit any plausible future item (items >= 1).
    if pr > 0.0 && pr < 1.0 {
        score += 1000.0;
    }

    // Lookahead coupling: if the next item fits the post-residual exactly-ish, reward heavily.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if n <= pr {
            let slack = pr - n;
            score -= 30.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here; mild penalty for stranding space
            score += 5.0 * ((n - pr) / bin_capacity as f64);
        }
    }

    // Last-chance bonus: this is the only bin that fits; strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin wastes residual capacity of this bin.
    if bin_residual == bin_capacity {
        // Prefer new bin only when existing bins would leave large awkward residuals.
        score += 10.0 + mean_residual * 0.2;
        // Early in stream, opening bins is cheap; later, prefer consolidation.
        let t = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 * (1.0 - t);
        // If many bins fit the item elsewhere, discourage opening a new one.
        score += 8.0 * fitting_bins_count as f64;
    } else {
        // Reward filling bins that are already open (consolidation).
        let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
        score -= 12.0 * fill_ratio;
        // Slight preference for bins with residual near the mean (balanced packing).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    // Pressure term: when many bins are open, favor compacting into existing ones.
    score += 0.3 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Time horizon: late in the stream, avoid leaving tiny unusable residuals.
    let t = step_index as f64 / (total_items.max(1) as f64);
    if post_residual > 0 {
        score += t * (post_residual as f64).powf(0.5) * 0.6;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (small post_residual), with non-linear emphasis.
    let mut score = pr + 40.0 * norm_pr * norm_pr;

    // Smooth polynomial coupling of post_residual with stream progress:
    // late in the stream, waste is penalized more heavily.
    let coupling = norm_pr * (1.0 + 3.0 * progress * progress);
    score += 60.0 * coupling;

    // Interact with mean residual: bins deviating from mean residual
    // (creating imbalance) get a smooth quadratic penalty.
    let dev = pr - mean_residual;
    score += 0.15 * dev * dev / (1.0 + mean_residual / cap);

    // Last-chance bonus: strongly favor the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0 + 40.0 * progress;
    }

    // New-bin candidate: penalize mildly so it's chosen only for bad fits,
    // but allow it more readily early in the stream.
    if bin_residual == bin_capacity {
        score += 25.0 + 45.0 * progress;
        // If next item can pair with this item in a fresh bin, encourage it.
        if next_item_size > 0 && next_item_size as f64 <= pr {
            score -= 15.0;
        }
    }

    // Lookahead: reward leaving space that the next item can use.
    if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap >= 0.0 {
            score -= 12.0 * (1.0 - (gap / cap)) * (1.0 - 0.5 * progress);
        } else {
            score += 5.0 * (-gap / cap);
        }
    }

    // Mild pressure against accumulating too many open bins.
    score += 0.3 * open_bins_count as f64 * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues mod 10 measure how
    // "usable" the leftover space is for typical item granularities.
    let residue_class = post_residual % 10;
    let half_class = (post_residual % 20) as f64;

    // Reward post-residuals that are multiples of common item granularity.
    if residue_class == 0 {
        score -= 12.0;
    } else if residue_class <= 2 {
        score += 6.0; // tiny dead space, hard to fill
    } else {
        score += residue_class as f64 * 0.8;
    }

    // Harmonic fraction of capacity consumed.
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    let fill_step = (fill * 4.0).floor() / 4.0; // quarter-capacity classes
    score -= fill_step * 10.0;

    // Lookahead: does next item fit exactly or well into post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0; // perfect harmonic closure
        } else if next_item_size <= post_residual {
            let nxt_res = post_residual - next_item_size;
            let nxt_class = nxt_res % 10;
            if nxt_class == 0 {
                score -= 15.0;
            } else {
                score += nxt_class as f64 * 1.2;
            }
        } else {
            // next item cannot follow here: penalize proportionally to overshoot class
            let over = (next_item_size - post_residual) % 10;
            score += 5.0 + over as f64 * 0.7;
        }
    }

    // Integer-division threshold on post_residual: small leftovers are dead space.
    let dead = post_residual / 10; // number of "10-slots" left
    if dead == 0 {
        score += 14.0;
    } else if dead >= 5 {
        score -= 8.0; // roomy leftover, still flexible
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when nothing fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let good_exists = !fitting_bins_count == 0; // fitting_bins_count>0 means open bins fit
        let pressure = (open_bins_count as f64) * 2.0 + mean_residual * 0.3;
        if good_exists {
            score += 45.0 + pressure; // discourage opening new bin when one fits
        } else {
            score -= 20.0;
        }
    }

    // Phase coupling: late in stream, prefer tighter packing (lower post-residual weight).
    let phase = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.4 * phase;

    // Half-class tiebreak modulation.
    score += half_class * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // Gaps that are too small to hold even the smallest plausible item are "dead space".
    // Penalize them heavily with a superlinear term.
    let dead_threshold = 12u32; // below this, residual is nearly unusable
    if post_residual < dead_threshold {
        score += (dead_threshold - post_residual) as f64 * 3.0;
    } else if post_residual == 0 {
        score -= 40.0; // perfect fill is the best outcome
    }

    // Reward tight fits: small post_residual relative to item size.
    let tightness = post_residual as f64 / (item_size as f64 + 1.0);
    score += tightness * tightness * 4.0;

    // Reward placements that leave room for the lookahead item exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0; // perfect two-item packing
        } else if post_residual >= next_item_size {
            // mild reward for keeping lookahead feasible
            score -= 2.0;
        } else {
            // lookahead item can't fit here; penalize proportionally to wasted potential
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // --- Open bins pressure ---
    // Encourage closing bins out (fewer open bins) when many are open, by
    // favoring placements into existing bins over opening new ones.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let bin_pressure = (open_bins_count as f64).ln().max(0.0);
    score -= bin_pressure * (2.0 + 3.0 * progress);

    // --- New-bin candidate handling ---
    // The brand-new empty bin has bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin: grows with number of open bins.
        score += 55.0 + 4.0 * open_bins_count as f64;
        // If the current item leaves a large awkward gap in a fresh bin
        // (item much smaller than capacity), add extra penalty.
        if post_residual > 50 {
            score += (post_residual - 50) as f64 * 0.3;
        }
        // Early in the stream, opening bins is cheaper (need bins available).
        score -= (1.0 - progress) * 20.0;
        // If no open bin fits, the new-bin call is the only option: it must win.
        if fitting_bins_count == 0 {
            score -= 1000.0;
        }
    } else {
        // Last-chance bin: strongly prefer filling the only bin that fits.
        if fitting_bins_count == 1 {
            score -= 30.0;
        }
        // Prefer bins whose residual is below the mean (consolidate fuller bins).
        score += (mean_residual - bin_residual as f64) * 0.25;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 40.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // 2-step lookahead: if the next item fits into the post residual, big bonus.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = post_residual as f64 - next_item_size as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > post_residual {
        // Next item won't chain here: penalize dead space that blocks it.
        score += 8.0 * (next_item_size as f64 - post_residual as f64).min(30.0) / 10.0;
    }

    // Compare against mean residual across open bins: prefer bins with residuals
    // close to the item (tight packing), avoid bins that are much emptier.
    let tightness = (bin_residual as f64 - item_size as f64) - mean_residual;
    score += 0.3 * tightness;

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let poor_fit = if fitting_bins_count == 0 { 1.0 } else {
            (post_residual as f64 / bin_capacity as f64).min(1.0)
        };
        score += 15.0 - 10.0 * poor_fit;
        // Slightly discourage proliferation of open bins.
        score += 0.5 * open_bins_count as f64;
    }

    // Late in the stream, favor consolidating into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 3.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual relative to capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - tightness) * 8.0;

    // Penalize dead space that is too small for the lookahead item (waste),
    // but only mildly if it could still absorb future small items.
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.6;
        } else if post_residual >= next_item_size {
            // Reward bins that can also host the next item (chaining).
            let chain_left = post_residual - next_item_size;
            score -= (chain_left as f64 / bin_capacity as f64) * 4.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 6.0;
    }

    // Many open bins: prefer consolidating into bins with above-mean residual
    // (drain crowded bins), keep mean-residual bins neutral.
    if open_bins_count > 1 {
        let dev = bin_residual as f64 - mean_residual;
        score -= dev * 0.05;
    }

    // Early in the stream: keep some exploration, mildly prefer filling bins
    // fully; late in the stream: be aggressive about tight packing.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * (bin_residual - post_residual) as f64 * 0.05;

    // New-bin candidate: make it moderately attractive only when no good fit
    // exists (large post_residual waste) or late in the stream with many bins.
    if bin_residual == bin_capacity {
        let waste_penalty = (bin_capacity - item_size) as f64;
        score = waste_penalty * (1.2 - 0.4 * progress);
        if fitting_bins_count == 0 {
            score -= 10.0; // must open a bin anyway
        }
        if open_bins_count == 0 {
            score -= 20.0;
        }
    }

    // Discourage leaving residuals in the awkward 1..=10 dead zone.
    if post_residual >= 1 && post_residual <= 10 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = step_index as f64 / (total_items.max(1) as f64);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: minimize post residual (best fit), smoothed polynomial
    let mut score = pr;

    // Non-linear coupling: post_residual with stream progress
    // Later in the stream, tighter fits matter more; early on, tolerate slack.
    let progress_weight = 0.5 + 1.5 * t * t;
    score += progress_weight * 20.0 * norm_pr * norm_pr;

    // Penalize dead space that cannot fit the lookahead item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            let unusable = (nxt - pr) / cap;
            score += 15.0 * unusable * unusable;
        } else {
            // Reward residual that still fits the next item (smoothly)
            score -= 5.0 * (pr - nxt) / cap;
        }
    }

    // Last-chance bin bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize opening new bins when many bins are already open and slack exists
    let mean_res_norm = mean_residual / cap;
    score += 3.0 * open_bins_count as f64 * mean_res_norm * (0.5 + t);

    // Mild reward for compacting near-full bins (quadratic in fill)
    let fill = 1.0 - norm_pr;
    score -= 10.0 * fill * fill * fill;

    // New-bin candidate: encourage it only when no open bin fits well
    if bin_residual == bin_capacity {
        score += 8.0 + 12.0 * (1.0 - t);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: leftovers divisible into common
    // item-size classes (multiples of 10) are more reusable than odd remainders.
    let leftover = post_residual;
    if leftover > 0 {
        let class = leftover % 10;
        // Dead-space penalty grows for non-decimal leftovers (poor reusability).
        if class != 0 {
            score += (class as f64) * 0.8;
        }
        // Perfect fills are heavily rewarded.
        if leftover == 0 {
            score -= 50.0;
        }
        // Leftovers that exactly match a harmonic class of the next item
        // (next item fits the leftover with zero waste) are rewarded.
        if next_item_size > 0 && next_item_size <= leftover {
            let waste = leftover - next_item_size;
            if waste == 0 {
                score -= 30.0;
            } else if waste % 10 == 0 {
                score -= 8.0;
            } else {
                score += (waste % 10) as f64 * 0.5;
            }
        }
    }

    // Integer-division threshold on post_residual: bins partitioned into
    // coarse capacity fractions (half / third / quarter) are "harmonic" states.
    let half = bin_capacity / 2;
    let third = bin_capacity / 3;
    if leftover == half {
        score -= 6.0;
    } else if leftover == third {
        score -= 3.0;
    } else if leftover < third {
        // Very small leftover is nearly dead space; penalize unless bin is nearly full.
        score += (third - leftover) as f64 * 0.4;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: if the next item cannot fit any other way, reserve space sensibly.
    if next_item_size > 0 && next_item_size > leftover {
        // This bin cannot host the next item anyway; mild penalty for tight fills
        // that strand the next item when few bins are open.
        if open_bins_count <= 2 {
            score += 5.0;
        }
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 40.0;
        } else {
            // Opening a new bin wastes existing residual capacity; penalize
            // proportionally to mean residual across open bins.
            score += mean_residual * 0.6 + 10.0;
        }
    }

    // Slight preference to consolidate into fewer bins early in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - progress) * (open_bins_count as f64).ln().max(0.0) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item (1..100) are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 1000.0;
    }

    // Penalize residuals that only fit very small items (likely dead space).
    if post_residual > 0 && post_residual < 20 {
        score += 40.0;
    }

    // Reward tight fits: small post_residual relative to item size.
    if post_residual > 0 {
        score += (item_size as f64) / (post_residual as f64) * 5.0;
    }

    // Perfect fit is excellent.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 50.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Open-bin pressure: with many open bins, avoid opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let bin_pressure = open_bins_count as f64 * (1.0 + progress);
    if bin_residual == bin_capacity {
        score += bin_pressure * 10.0;
        // But if all open bins would leave large dead space, opening new bin is fine.
        if post_residual as f64 > mean_residual {
            score -= 20.0;
        }
    }

    // Mild preference for bins below mean residual (consolidate fuller bins).
    score += (mean_residual - bin_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: item + next item fill the bin exactly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 200.0;
    }
    // Next item fits in the leftover space: strong reward, scaled by tightness.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 60.0 - 0.3 * slack;
    }
    // Leftover too small for the next item: penalize dead space, worse when tiny.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 0.5 * post_residual as f64;
    }

    // Tight fit reward: small post_residual relative to item size.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * tightness;

    // Penalize leaving large unusable gaps relative to mean residual of open bins.
    if (post_residual as f64) > mean_residual + 20.0 {
        score += 0.4 * (post_residual as f64 - mean_residual);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 50.0;
    }

    // Brand-new empty bin candidate: neutral-ish, discourage unless existing bins are poor.
    if bin_residual == bin_capacity {
        score += 30.0 + 0.1 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // New bin is attractive when the next item would pair with the current one.
            if next_item_size + item_size <= bin_capacity {
                score -= 45.0;
            }
        }
    }

    // Late in the stream: slightly prefer consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (open_bins_count as f64).sqrt();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (low post-residual).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small to be useful later.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if post_residual < 10 {
        score += 60.0 * (1.0 - 0.5 * t);
    } else if post_residual <= 20 {
        score += 15.0;
    }

    // Lookahead: reward if the next item fits into the post-residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0 + 0.15 * next_item_size as f64;
        } else {
            // Penalize wasting residual that the next item cannot use.
            score += 8.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Global state coupling: many open bins -> prefer filling existing ones.
    let pressure = open_bins_count as f64 / (open_bins_count as f64 + 8.0);
    score -= 20.0 * pressure * (mean_residual / bin_capacity as f64);

    // New-bin candidate handling: penalize opening a new bin unless current
    // fit is poor and there is slack in the stream.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 > 0.6 * bin_capacity as f64;
        let early = t < 0.7;
        if poor_fit && early && fitting_bins_count > 1 {
            score += 25.0; // discourage new bin when a decent fit exists
        } else {
            score -= 10.0; // encourage fresh bin for otherwise bad fits
        }
    }

    // Mild time decay: later in stream, consolidate aggressively.
    score -= 10.0 * t * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Base: prefer low post-residual (tight fit), scaled non-linearly.
    let mut score = post;

    // Non-linear tightness reward: quadratic coupling of fill fraction with stream progress.
    let fill = 1.0 - post / cap;
    score -= 12.0 * fill * fill * (0.5 + progress);

    // Penalize unusable dead space: post_residual smaller than the smallest plausible item (<=10)
    // is dead space; smooth penalty growing as post_residual approaches 0..10 zone.
    let dead = (10.0 - post).max(0.0);
    score += 2.5 * dead * (1.0 + progress);

    // Lookahead: reward if next item fits exactly in the post residual (perfect chain).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post - nxt).abs();
        if post >= nxt {
            score -= 8.0 * (1.0 - gap / cap);
        } else {
            score += 3.0 * (gap / cap);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 6.0 * (0.4 + 0.6 * progress);
    }

    // New-bin candidate handling: neutral-ish baseline, slightly discouraged early,
    // encouraged late when open bins have fragmented residuals.
    if bin_residual == bin_capacity {
        score = cap - item_size as f64;
        let fragmentation = (mean_residual / cap).clamp(0.0, 1.0);
        score -= 10.0 * progress * fragmentation;
        if open_bins_count == 0 {
            score = -1000.0;
        }
    } else {
        // Mild preference for bins with residual above the mean (balance residuals).
        score += 1.5 * (bin_residual as f64 - mean_residual) / cap;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that are "friendly"
    // to common small item sizes (modular arithmetic on capacity fractions).
    let cap = bin_capacity;
    if post_residual > 0 {
        // Residual classes: 0 mod 10 aligns with typical item granules.
        let class = post_residual % 10;
        score += class as f64 * 1.5; // penalize misaligned dead space
        // Reward residuals that exactly match a plausible next item size
        if next_item_size > 0 && post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            if slack % 10 == 0 {
                score -= 6.0; // perfect harmonic fit for lookahead item
            } else {
                score += slack as f64 * 0.05;
            }
        }
        // Dead-space penalty: residual too small for the smallest item (1..=10 range guard)
        let min_item = 10u32.min(cap);
        if post_residual < min_item {
            score += 25.0; // unusable dead space
        }
        // Integer-division thresholds on residual fraction of capacity
        let frac = (post_residual as f64) / (cap as f64);
        if frac < 0.1 {
            score += 8.0; // nearly full bin: good, but low flexibility
        } else if frac > 0.6 {
            score += 4.0; // wasteful placement leaving a huge residual
        } else {
            score -= 3.0; // sweet spot: half-ish residuals stay useful
        }
    } else {
        score -= 20.0; // perfect fill: strongly favored
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: penalize so it's chosen only when alternatives are bad.
    if bin_residual == bin_capacity {
        score += 12.0 + open_bins_count as f64 * 0.3;
        // But if the lookahead item is huge and no harmonic match exists, allow new bin
        if next_item_size > cap / 2 && post_residual >= 0 {
            score -= 6.0;
        }
    }

    // Stream progression: late in the stream, consolidate more aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 2.0;
    // Mean-residual coupling: if this bin's residual is far below mean, it's tight — prefer it.
    score -= (mean_residual - bin_residual as f64).max(0.0) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps.
    // A residual gap is "dead" if it is too small to hold even the smallest item.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Open bins pressure: penalize using a bin when many bins are open,
    // encouraging consolidation into fewer bins when possible.
    score += open_bins_count as f64 * 0.5;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: make it slightly unattractive by default, unless
    // current bin would leave a large dead gap while a fresh bin offers full space.
    if bin_residual == bin_capacity {
        // Neutral base for fresh bin; add small constant so only good fits
        // in existing bins beat it.
        score += 10.0;
    }

    // Lookahead coupling: if next item fits into the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0;
    }
    // If next item would NOT fit the post-residual but would fit a fresh bin,
    // penalize leaving a gap that blocks the next item.
    if next_item_size > post_residual as u32 && next_item_size > 0 {
        score += 15.0;
    }

    // Mean-residual coupling: prefer bins whose residual is below mean
    // (tighter bins get filled first, keeping loose bins flexible).
    if (bin_residual as f64) < mean_residual {
        score -= 10.0;
    } else {
        score += 5.0;
    }

    // Stream progression: late in the stream, be more conservative about
    // leaving dead space (fewer future items to fill gaps).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small dead space relative to capacity)
    let tightness = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 30.0 * tightness;

    // Strong reward for perfect fit
    if post_residual == 0 {
        score -= 200.0;
    }

    // 2-step lookahead: does the next item fit into the post-residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            // Perfect chain: next item exactly fills this bin
            score -= 150.0;
        } else if next_item_size <= post_residual {
            // Next item still fits, but leaves more waste
            score -= 40.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item won't fit here; penalize proportionally to how much
            // dead space is left behind
            let waste_frac = post_residual as f64 / bin_capacity as f64;
            score += 60.0 * waste_frac;
        }
    } else {
        // Last item: prefer zero waste
        score += 100.0 * post_residual as f64 / bin_capacity as f64;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Compare against mean residual: bins tighter than average are attractive
    score -= 10.0 * (mean_residual - bin_residual as f64) / bin_capacity as f64;

    // New-bin candidate: give it a moderate baseline so it wins only when
    // all open bins would leave poor fits
    if bin_residual == bin_capacity {
        score = 55.0 + item_size as f64 * 0.3;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 20.0; // fresh bin can chain with next item
        }
        if fitting_bins_count == 1 {
            score -= 40.0; // still prefer the last open bin over a new one
        }
    }

    // Slight late-stream pressure to consolidate into fewer bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are good: reward small post_residual non-linearly.
    if post_residual > 0 {
        score -= 30.0 / (post_residual as f64).sqrt();
    } else {
        score -= 40.0; // perfect fill
    }

    // Penalize dead space: leftover too small for any plausible future item (items >= 1).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // fragmented sliver
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward strongly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            score -= 5.0;
        } else {
            // leftover can't hold next item; mild penalty scaled by waste
            score += 0.1 * (next_item_size as f64 - post_residual as f64).min(30.0);
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits, to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: discourage opening a new bin when any open bin gives a decent fit.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Opening a new bin becomes slightly more acceptable late in the stream or when open bins are crowded.
        let crowding = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score += 35.0 - 15.0 * progress - 10.0 * crowding;
        // If item is large relative to capacity, a fresh bin is more natural.
        score -= (item_size as f64 / bin_capacity as f64) * 10.0;
    }

    // Mild preference for bins with residual close to item (best-fit sharpening).
    score += 0.05 * ((bin_residual as f64 - item_size as f64).abs());

    // Slight tie-break toward bins below mean residual (consolidating emptier bins).
    if (bin_residual as f64) < mean_residual {
        score -= 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = step_index as f64 / total_items.max(1) as f64;
    let smooth = progress * progress * (3.0 - 2.0 * progress); // smoothstep coupling

    // Normalized post-residual polynomial coupling
    let pr = post_residual as f64 / cap;
    let pr2 = pr * pr;
    let pr3 = pr2 * pr;
    // Penalize mid-range dead space quadratically; tiny residuals are great
    score += 12.0 * pr2 * (1.0 - pr) * (1.0 - smooth * 0.5);

    // Reward tight fits more strongly as stream progresses
    let tightness = 1.0 - pr;
    score -= 8.0 * tightness * tightness * (0.5 + smooth);

    // Last-chance bonus: only fitting bin
    if fitting_bins_count == 1 {
        score -= 6.0 + 10.0 * smooth;
    }

    // New-bin candidate: penalize mildly early, more strongly late unless residual is dead space
    let is_new = bin_residual == bin_capacity;
    if is_new {
        let open_f = open_bins_count as f64;
        let mean_gap = (mean_residual - pr * cap).abs();
        score -= 4.0 + 3.0 * smooth - 0.05 * open_f + 0.01 * mean_gap;
    } else {
        // Prefer bins whose residual deviates from mean (diversify residual sizes)
        let dev = (bin_residual as f64 - mean_residual) / cap;
        score += 2.0 * dev * dev * (1.0 - smooth);
    }

    // Lookahead: reward leaving room for next item, penalize near-miss
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if (post_residual as f64) >= ni {
            score -= 3.0 * (1.0 - ((post_residual as f64 - ni) / cap));
        } else {
            let miss = (ni - post_residual as f64) / cap;
            score += 6.0 * miss * miss;
        }
    }

    // Mild penalty for many open bins to encourage consolidation
    score += 0.02 * open_bins_count as f64 * pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space is worse in some residue classes.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Perfect fit bonus: harmonic class 0.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Small dead space that is "usable" (>= typical small item) is less harmful.
        let usable = post_residual >= 10 && post_residual <= 40;
        if usable {
            score -= 30.0;
        } else if post_residual > 60 {
            // Large leftover is fine — bin still highly reusable.
            score -= 20.0;
        } else {
            // 41..=60 dead zone: awkward gap, penalize extra.
            score += 25.0;
        }
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if next_item_size == post_residual {
            score -= 800.0;
        } else if next_item_size <= post_residual {
            // Fractional fill of the future gap.
            let fill = n / (pr + 1.0);
            score -= 200.0 * fill;
            // Harmonic class: post_residual % next_item_size small => good future fit.
            if next_item_size > 0 && post_residual % next_item_size == 0 {
                score -= 100.0;
            }
        } else {
            // Next item cannot use this bin's leftover; leftover may become dead.
            score += 40.0 * (n / cap);
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 150.0;
    } else if fitting_bins_count > 1 {
        // Mild crowding penalty to spread load among fitting bins.
        score += 10.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // New-bin candidate logic: only open a new bin when item is large relative
    // to all residuals and mean residual is tight.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let tight = mean_residual < item_size as f64;
        if tight && item_size >= 50 {
            score -= 120.0 + 200.0 * progress;
        } else {
            score += 60.0; // prefer filling existing bins
        }
    }

    // Mean residual alignment: prefer bins whose residual is near the mean
    // (keeps bin population balanced) — mild quadratic term.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 15.0 * dev * dev;

    // Tightness reward: small post_residual relative to capacity.
    score -= 50.0 * (1.0 - pr / cap);

    // Integer-division threshold classes on post_residual (decade buckets).
    let bucket = post_residual / 10;
    score += match bucket {
        0 => -10.0,
        1..=3 => 0.0,
        4..=5 => 15.0,
        6..=7 => -5.0,
        _ => -20.0,
    };

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small to be useful later are bad.
    // Treat gaps < 10 (min plausible item) as fully wasted; scale up to 30 as partially wasted.
    if post_residual < 10 {
        score += 40.0;
    } else if post_residual < 30 {
        score += (30.0 - post_residual as f64) * 0.8;
    }

    // Perfect or near-perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Last chance: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: with many open bins, favor compacting into existing bins
    // and discourage opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.15 + 0.25 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as open bins grow and stream progresses.
        score += 20.0 + pressure * 3.0;
    } else {
        score -= pressure;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward heavily.
    if next_item_size > 0 && post_residual > 0 && next_item_size == post_residual {
        score -= 45.0;
    } else if next_item_size > 0 && next_item_size <= post_residual && post_residual > 0 {
        // Mild reward if next item still fits; mild penalty otherwise (dead space for next item).
        if post_residual - next_item_size < 10 {
            score -= 10.0;
        } else {
            score += 5.0;
        }
    }

    // Prefer bins tighter than the mean residual (better-filled bins).
    score += (bin_residual as f64 - mean_residual) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match between post_residual and next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 12.0 * (-diff / 10.0).exp(); // strong reward for perfect lookahead fit
        if post_residual == next_item_size {
            score -= 8.0;
        }
        // Penalize leaving residual slightly larger than next item (dead space trap)
        if post_residual > next_item_size && post_residual < next_item_size + 10 {
            score += 6.0;
        }
    } else {
        // Last item: minimize waste directly
        score = post_residual as f64;
    }

    // Prefer bins tighter than the mean residual (fill crowded bins first)
    score += 0.35 * (post_residual as f64 - mean_residual);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Penalize opening a new bin unless current residual is truly unusable
    if bin_residual == bin_capacity {
        score += 5.0 + 0.1 * open_bins_count as f64;
    }

    // Slight decay over stream: early on, keep bins flexible (favor larger post_residual less)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 2.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: heavily discount small post-residuals.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that is too small to be useful for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 4.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size as u32 {
            score -= 8.0;
            // Perfect chain fit bonus.
            if post_residual == next_item_size as u32 {
                score -= 6.0;
            }
        } else {
            // Post-residual useless for the next item: mild penalty scaled by waste.
            let waste = post_residual as f64 / bin_capacity as f64;
            score += 5.0 * waste;
        }
    } else {
        // Last item: just minimize post residual (already the base).
        score -= 3.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        let fit_quality = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= 15.0 * fit_quality;
    }

    // New-bin candidate handling: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base reluctance to open a new bin, decaying as stream progresses
        // and as the fleet of open bins grows (fragmentation risk).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0 + 15.0 * (1.0 - progress) + 0.8 * open_bins_count as f64;

        // If many bins fit the item, opening a new bin is wasteful.
        if fitting_bins_count > 1 {
            score += 10.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
        }

        // If the current item is large, a fresh bin is more justified.
        score -= 0.15 * item_size as f64;

        // Lookahead synergy: new bin can absorb both current and next item.
        if next_item_size > 0 && (item_size + next_item_size) as u32 <= bin_capacity {
            score -= 25.0;
        }
    }

    // Global state coupling: prefer bins with residual far from the mean
    // to balance residual distribution across bins (reduce fragmentation).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Mild preference for filling already-open bins as the stream matures.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual < bin_capacity {
        score -= 4.0 * progress;
    }

    // Encourage bins whose residual is close to item_size (near-perfect fill).
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.08 * gap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap; // normalized post residual in [0,1]

    // Base: prefer tight fits (small post residual), non-linearly penalized
    let mut score = pr as f64;
    score += 30.0 * norm_pr * norm_pr * (1.0 + progress);

    // Smooth interaction: post residual vs stream progress (dead space costs more later)
    score += 20.0 * norm_pr * norm_pr * norm_pr * (1.0 - progress);

    // Penalize bins whose residual deviates from the mean residual (imbalance)
    let dev = (pr - mean_residual) / cap;
    score += 8.0 * dev * dev;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - norm_pr);
    }

    // Lookahead coupling: reward if next item can fit into the post residual
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            let slack = (pr - nx) / cap;
            score -= 12.0 * (1.0 - slack * slack);
        } else {
            let miss = (nx - pr) / cap;
            score += 15.0 * miss * miss;
        }
    }

    // Mild penalty for spreading across many open bins early (encourage consolidation)
    score += 2.0 * (open_bins_count as f64).ln() * (1.0 - progress);

    // Smooth new-bin deterrent: only attractive when post residual would be large waste
    if bin_residual == bin_capacity {
        score += 10.0 + 40.0 * (1.0 - norm_pr) * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls into "nice"
    // residue classes (multiples of common small sizes) are more reusable.
    let pr = post_residual;
    if pr > 0 {
        // reward residuals divisible by common item granularities
        if pr % 10 == 0 { score -= 12.0; }
        else if pr % 5 == 0 { score -= 6.0; }
        if pr % 20 == 0 { score -= 8.0; }
        // dead space: residuals in awkward bands are penalized
        if pr < 10 { score += 25.0; }
        else if pr < 20 { score += 10.0; }
        // integer-division threshold: residual "capacity fraction" class
        let frac = pr as f64 / cap;
        if frac > 0.5 { score -= 15.0; }
        else if frac < 0.25 { score += 8.0; }
    } else {
        // perfect fill is the best outcome
        score -= 60.0;
    }

    // Lookahead coupling: does post_residual combine with next item?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // next item still fits here: strong reward, scaled by tightness
            let slack = (pr - next_item_size) as f64;
            score -= 20.0 + 0.3 * slack;
            // harmonic bonus if pair sums hit a nice class
            if (item_size + next_item_size) % 10 == 0 { score -= 10.0; }
        } else {
            // next item will not fit: penalty grows with how much we "wasted"
            score += 5.0 + 0.2 * (next_item_size - pr) as f64;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when existing
    // residuals are all poor and the item is large.
    if bin_residual == bin_capacity {
        // base penalty keeps new bins from being opened casually
        score += 40.0;
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mean_frac = mean_residual / cap;
        // open new bin if mean residual is small (bins nearly full) or
        // item is huge and nothing fits well
        if mean_frac < 0.15 { score -= 55.0; }
        if item_size > 70 && mean_frac < 0.3 { score -= 20.0; }
        if open_bins_count == 0 { score -= 100.0; }
        if progress > 0.9 && mean_frac < 0.25 { score -= 10.0; }
    }

    // mild pressure to consolidate when many bins are open
    score -= 0.05 * open_bins_count as f64;
    // slight preference for tighter fits overall
    score += 0.1 * (bin_residual - item_size) as f64 * 0.0; // no-op guard
    score -= 0.2 * (item_size as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residual gaps too small to hold the
    // smallest plausible item (<= 10) are pure waste -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual > 0 && post_residual < 25 {
        // Small gaps that only tiny items could use: moderate penalty
        // scaled by how "orphaned" the gap is relative to stream position.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 25.0 * (1.0 - progress);
    }

    // Reward exact/tight fits strongly.
    if post_residual == 0 {
        score -= 40.0;
    } else {
        let tightness = item_size as f64 / bin_residual.max(1) as f64;
        score -= 20.0 * tightness;
    }

    // Open-bin pressure: discourage spreading across many open bins,
    // but ease pressure when this is the only fitting bin (last chance).
    if fitting_bins_count > 1 {
        score += 2.5 * open_bins_count as f64;
    } else {
        score -= 15.0;
    }

    // If a new empty bin candidate, penalize slightly so it's only chosen
    // when all open bins are genuinely poor fits (large dead-space risk).
    if bin_residual == bin_capacity && bin_capacity > 0 {
        score += 10.0;
    }

    // Lookahead: if next item fits the post-residual, this placement is great.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 8.0;
    }

    // Mild alignment with mean residual: prefer bins below-average residual
    // (denser bins) to consolidate packing.
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward when the next item exactly fills the remaining space.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs();
        if gap == 0 {
            score -= 40.0;
        } else {
            score += gap as f64 * 0.5;
        }
        // Reward if next item can still fit after this placement.
        if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            score += 6.0; // dead space: next item won't fit here
        }
    }

    // Penalize post_residual far above mean residual (poor consolidation).
    score += (post_residual as f64 - mean_residual).abs() * 0.15;

    // Last-chance bin bonus: avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad.
    if bin_residual == bin_capacity {
        score += 15.0;
        // Still allow opening if item leaves awkward residual and no good fit exists.
        if post_residual < 10 {
            score -= 20.0;
        }
    }

    // Slight preference for tighter fits overall.
    score += (item_size as f64 / bin_capacity as f64) * 5.0;

    // Late-stream: prefer closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64 / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += fit_ratio * fit_ratio * 40.0;

    // Penalize leaving residual that is too small to be useful for future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // dead space penalty
    }

    // Lookahead: reward bins whose post_residual fits the next item exactly or well.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            score += 8.0; // cannot host next item
        }
    } else {
        // Last item: prefer filling existing bins completely.
        score -= 15.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Many open bins: discourage spreading; prefer bins below mean residual (tighter bins).
    if open_bins_count > 1 {
        score += (mean_residual - bin_residual as f64) * 0.5;
    } else {
        score -= 5.0;
    }

    // Time horizon: late in the stream, consolidate into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * 12.0;

    // New-bin candidate: opening a new bin wastes the residual of the current bin;
    // make it attractive only when the current fit is bad.
    if bin_residual == bin_capacity {
        // New bin starts with full residual; base score is high (100).
        // Reward it when this item would leave a poor fit in any existing bin.
        let waste = (bin_residual - item_size) as f64;
        score -= 10.0;
        if fitting_bins_count == 0 {
            score -= 60.0; // must open a new bin
        }
        if item_size >= 60 {
            score -= 15.0; // large items deserve fresh space
        }
        // Early on, opening bins is cheaper; late, avoid it.
        score += progress * 20.0;
        let _ = waste;
    } else if fitting_bins_count == 0 {
        // Should not happen, but guard.
        score -= 50.0;
    }

    // Mild coupling: prefer bins whose residual is close to a multiple structure of item sizes.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Smooth non-linear coupling: quadratic residual shaping modulated by stream progress.
    score += 4.0 * norm_pr * norm_pr * (1.0 + progress) * cap;

    // Reward tight fits via cubic interaction of item size and residual.
    score -= 6.0 * norm_item * (1.0 - norm_pr) * (1.0 - norm_pr) * cap;

    // Penalize dead space that cannot fit the lookahead item (smooth gating).
    let gap = (next_item_size as f64 - pr).max(0.0) / cap;
    score += 3.0 * gap * gap * cap * (1.0 - progress);

    // Last-chance bonus: strongly reward using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0 * (1.0 - norm_pr) * cap;
    }

    // Mild dispersion penalty: avoid leaving residuals far from the mean.
    let dev = pr - mean_residual;
    score += 0.05 * dev * dev / cap;

    // Discard-new-bin bias: make the empty-bin candidate slightly less attractive
    // unless its residual (full capacity) is genuinely the best smooth fit.
    if bin_residual == bin_capacity {
        score += 1.5 * cap * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let nis = next_item_size as f64;

    let mut score = pr;

    // Base tightness reward: strongly favor small post_residual (cubic shaping).
    score -= 25.0 * (1.0 - pr / cap).powi(3);

    // Harmonic dead-space classes: near-perfect fills get extra bonuses.
    if post_residual == 0 {
        score -= 20.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    } else if post_residual <= 10 {
        score -= 6.0;
    } else if post_residual <= 20 {
        score += 2.0;
    } else if post_residual <= 30 {
        score += 6.0;
    } else {
        score += 10.0;
    }

    // Lookahead (k=2): reward bins whose residue can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // chain-friendly: reward proportionally to how well next item nests
            score -= 8.0 * (1.0 - pr / cap);
        } else {
            // penalize residue that is close-but-too-small for the next item (traps)
            let gap = nis - pr;
            if gap <= 10.0 {
                score += 7.0;
            }
        }
    }

    // New-bin candidate: default penalty so open bins are preferred...
    if bin_residual == bin_capacity {
        score += 14.0;
        // ...but if no open bin fits, opening is mandatory.
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
        // Late in the stream, prefer consolidating rather than spawning bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 6.0 * progress;
    }

    // Last-chance bin: if this is the only open bin that fits, use it.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 7.0;
    }

    // Many open bins: discourage spreading into bins far from mean residual.
    if open_bins_count > 1 {
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold any plausible
    // future item (min size 1..10 under unknown distribution) are wasted space.
    if post_residual > 0 && post_residual < 10 {
        score += 45.0;
    }
    // Semi-dead zone: residuals that only fit tiny items are mildly wasteful.
    if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }

    // Lookahead coupling: if the next item cannot use the leftover space,
    // the leftover is likely dead — penalize proportionally to its size.
    if next_item_size > 0 {
        if next_item_size > post_residual {
            score += next_item_size as f64 * 0.18;
        } else if post_residual - next_item_size < 10 {
            // Perfect chain: this placement sets up an exact fit next step.
            score -= 15.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: mild reward for consolidating into fewer bins.
    score += open_bins_count as f64 * 0.4;

    // New-bin candidate: opening a fresh bin is only attractive when the
    // current open bins are heavily fragmented (low mean residual) or we
    // are early in the stream with many items left to place.
    if bin_residual == bin_capacity {
        score += 6.0 + mean_residual * 0.25 - progress * 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item fits the post residual exactly well.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        if nxt <= post {
            // Next item fits: reward tighter chaining.
            score -= 30.0 * (1.0 - (post - nxt) / bin_capacity as f64);
            // Perfect chain bonus: post_residual exactly equals next item.
            if post_residual == next_item_size {
                score -= 40.0;
            }
        } else {
            // Next item won't fit here: penalize wasted residual.
            score += 0.5 * (post - nxt).abs();
        }
    } else {
        // Last item: strongly prefer minimal final residual.
        score += 20.0;
    }

    // Relative-to-mean coupling: prefer bins with residual below/at mean to consolidate.
    let mean = mean_residual;
    if (post_residual as f64) < mean {
        score -= 5.0;
    } else {
        score += 3.0 * (post_residual as f64 - mean) / bin_capacity as f64;
    }

    // Tight fit reward: small post residual generally.
    score += 2.0 * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible.
    if bin_residual == bin_capacity {
        score += 45.0;
        // Exception: if the item perfectly fills a fresh bin split for two items.
        if bin_capacity as f64 / (item_size as f64) >= 2.0 && next_item_size > 0
            && item_size + next_item_size <= bin_capacity {
            score -= 60.0;
        }
    }

    // Late-stream consolidation: fewer open bins preferred as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 10.0 * (open_bins_count as f64).sqrt() / 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Reward small post_residual relative to item size (tight fit)
    let tightness = post_residual as f64 / (item_size as f64 + 1.0);
    score += tightness * 8.0;

    // Penalize dead space that is too small for typical future items
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // unusable sliver
    }

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 && post_residual >= next_item_size {
        let lookahead_fit = (post_residual - next_item_size) as f64;
        score -= 40.0 - lookahead_fit * 0.5;
    } else if next_item_size > 0 && next_item_size > post_residual {
        score += 15.0; // next item won't fit here anyway; keep residual elsewhere flexible
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item fits poorly in all open bins
    let is_new_bin = bin_residual == bin_capacity && bin_capacity > 0;
    if is_new_bin {
        let mut base_penalty = 250.0;
        // In early stream, opening bins is cheaper (more future use of bins)
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        base_penalty *= 1.0 + progress * 1.5;
        // If many bins fit the item, opening a new one is wasteful
        if fitting_bins_count > 1 {
            base_penalty += 150.0 * (fitting_bins_count as f64 - 1.0);
        }
        // If item is large relative to capacity, new bin is more attractive
        base_penalty -= (item_size as f64 / bin_capacity as f64) * 100.0;
        // If mean residual is large, open bins have plenty of room; discourage new bin
        base_penalty += mean_residual * 2.0;
        // If next item is large and would need a fresh bin anyway
        if next_item_size >= bin_capacity - item_size && next_item_size > 0 {
            base_penalty -= 120.0;
        }
        score += base_penalty;
    }

    // Mild preference for filling bins with larger residuals when many bins are open
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Slight preference for fewer open bins
    score += open_bins_count as f64 * 0.5;

    // Prefer bins whose post_residual stays a "useful" size (>= 20 or 0)
    if post_residual >= 10 && post_residual < 20 {
        score += 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: post_residual (tight fit preferred), with non-linear dead-space growth.
    let mut score = pr + 0.045 * pr * pr / cap;

    // Smooth polynomial coupling of residual waste with stream progress:
    // later in the stream, waste becomes more costly.
    let prog_poly = progress * progress * (3.0 - 2.0 * progress);
    score += 12.0 * prog_poly * (pr / cap);

    // Reward filling the bin deeply (large item fraction).
    score -= 0.35 * it;

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let slack = pr - nx;
            score -= 8.0 * (1.0 - slack / cap);
        } else {
            // next item won't fit here; penalize residual that is neither reusable nor tight
            score += 4.0 * (pr / cap) * (1.0 - pr / cap);
        }
    }

    // Last-chance bonus: only one bin fits -> strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 20.0 + 15.0 * prog_poly;
    } else {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // Discourage deviating from mean residual (keeps bins balanced).
    let dev = (pr - mean_residual) / cap;
    score += 6.0 * dev * dev;

    // New-bin candidate: empty bin residual == capacity. Penalize so it only wins
    // when no open bin gives a decent fit (its post_residual is largest anyway).
    if bin_residual == bin_capacity {
        score += 30.0 + 25.0 * prog_poly;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space into capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // 0..1

    // Perfect fit strongly rewarded.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize dead space that is too small to hold the smallest plausible item.
        if post_residual < 10 {
            score += 50.0;
        }
        // Harmonic classes: leftover in [0, C/4), [C/4, C/2), [C/2, 3C/4), [C/4..]
        if frac < 0.25 {
            score += 20.0 * (0.25 - frac);
        } else if frac < 0.5 {
            score -= 5.0;
        } else if frac < 0.75 {
            score -= 15.0;
        } else {
            score -= 25.0;
        }

        // Lookahead: if next item fits in post_residual, big reward (chaining).
        if next_item_size > 0 {
            if next_item_size <= post_residual {
                score -= 40.0 + (post_residual - next_item_size) as f64 * 0.5;
            } else {
                // Next item won't chain; penalize based on wasted residual magnitude.
                score += (next_item_size as f64 - pr) * 0.3;
            }
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: only attractive when current bin residual is badly fragmented
    // relative to what the item needs, or many bins are open with high mean residual.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin; offset when item is large relative to capacity.
        score = 120.0 - (item_size as f64 / cap) * 100.0;
        if fitting_bins_count == 0 {
            score -= 200.0; // no open bin fits: must open
        }
        if mean_residual > 0.5 * cap && open_bins_count > 2 {
            score += 30.0; // plenty of slack around; avoid proliferation
        }
    }

    // Late-stream consolidation: as stream progresses, favor tight fits more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * (100.0 - post_residual as f64) * 0.1;

    // Tie-break: prefer bins whose residual deviates positively from mean (use slack).
    score += (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Post-residual that cannot fit the smallest possible item (1) is pure waste,
    // but any residual below the typical min size is suspect under unknown dists.
    if post_residual < item_size.min(20) && post_residual > 0 {
        score += 25.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Post-residual exactly matching next item: strong reward (lookahead chaining).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 35.0;
    }
    // Post-residual too small for the next item while still nonzero: mild penalty.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // Open bins pressure: discourage spreading across many bins.
    score += (open_bins_count as f64) * 1.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Mean residual coupling: prefer bins deviating below the mean residual
    // (tighter bins get priority), scaled by stream progress.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (mean_residual - post_residual as f64) * (0.3 + 0.4 * progress);

    // New-bin candidate: penalize mildly so it only wins when open bins are bad.
    if bin_residual == bin_capacity {
        score += 20.0;
        // Late in stream, opening fresh bins is more acceptable.
        score -= 25.0 * progress;
        // But if the current bin would leave a large residual and next item is big,
        // a fresh bin can be better.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match between post_residual and next_item_size
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let match_gap = (post_residual as f64 - next).abs();
        // Strong reward if the next item exactly fills the residual (perfect 2-step packing)
        if match_gap < 0.5 {
            score -= 60.0;
        } else if post_residual as f64 >= next {
            // Next item fits: scale reward by tightness of the match
            score -= 25.0 * (1.0 - match_gap / bin_capacity as f64);
        } else {
            // Next item does NOT fit this residual: penalize proportionally to wasted potential
            score += 12.0 * (next - post_residual as f64) / next;
        }

        // Coupling with mean residual: bins far from the mean residual are either
        // hoarders (too full) or wasteful (too empty); mildly penalize both.
        let dev = (post_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;

        // Two-step chain: if next item also leaves a residue matching a typical small item,
        // give extra credit for creating a dense packing corridor.
        let post2 = post_residual as f64 - next;
        if post2 >= 0.0 && post2 <= 10.0 {
            score -= 15.0;
        }
    } else {
        // Last item: just minimize final waste
        score += 0.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless post_residual would be terrible dead space).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        let waste_ratio = post_residual as f64 / bin_capacity as f64;
        if waste_ratio < 0.35 {
            score -= 40.0;
        } else {
            score -= 10.0;
        }
    }

    // New-bin candidate: penalize opening a new bin unless current bins are nearly full.
    if bin_residual == bin_capacity {
        let mean_fullness = 1.0 - mean_residual / bin_capacity as f64;
        // Opening a new bin is only attractive if existing bins are heavily loaded
        score += 55.0 * (1.0 - mean_fullness);
        // Slight preference for new bins late in the stream is removed; keep neutral there
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 5.0 * progress;
    }

    // General tightness reward: prefer placements leaving small residuals,
    // but avoid leaving residuals in the "dead zone" (1..10) that nothing fits into.
    if post_residual >= 1 && post_residual < 10 {
        score += 18.0; // unusable sliver penalty
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual small relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        score -= 40.0;
    } else if post_residual < 20 {
        score -= 15.0;
    }

    // Penalize dead space that likely cannot be filled by typical items.
    if post_residual > 0 && post_residual < item_size {
        score += 5.0; // stranded sliver
    }

    // Lookahead: if next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; mild penalty for wasting residual
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 50.0;
    }

    // Pressure term: many open bins with high mean residual -> prefer filling existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = (open_bins_count as f64).ln() * (mean_residual / bin_capacity as f64);
    score -= 8.0 * pressure * (0.5 + progress);

    // New-bin candidate: make it attractive only when existing bins fit poorly.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin.
        let mut new_bin_score = 55.0;
        // Early in stream, new bins are cheaper; later, reuse is preferred.
        new_bin_score *= 0.6 + 0.8 * progress;
        // If few fitting bins exist, opening a new bin is less bad.
        if fitting_bins_count <= 1 {
            new_bin_score -= 30.0;
        }
        // If mean residual across open bins is small (bins nearly full), new bin is fine.
        new_bin_score -= 20.0 * (1.0 - mean_residual / bin_capacity as f64);
        // Large items relative to capacity prefer fresh bins.
        new_bin_score -= 0.3 * item_size as f64;
        score = score.min(new_bin_score) * 0.5 + new_bin_score * 0.5;
        score = new_bin_score;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress in [0,1]
    let progress = if total_items > 1 { step_index as f64 / (total_items as f64 - 1.0) } else { 0.0 };

    // Normalized post-residual
    let pr = post_residual as f64 / bin_capacity as f64;

    // Smooth non-linear coupling: waste grows super-linearly with residual,
    // modulated by stream progress (later in stream => more pressure to fill bins).
    let coupling = pr * pr * (1.0 + 2.0 * progress);
    score += 30.0 * coupling;

    // Reward tight fits: cubic decay of penalty as post_residual shrinks
    score -= 20.0 * (1.0 - pr).powi(3);

    // Interaction with mean residual: penalize bins that deviate from the mean
    // residual by creating extreme post-residuals (fragmentation avoidance).
    let dev = (post_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 10.0 * dev * dev;

    // Lookahead: if the next item exactly fits the post-residual, strongly favor this bin.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 50.0;
    } else if next_item_size > post_residual && next_item_size > 0 {
        // Next item cannot use leftover; mild penalty scaled by leftover size
        score += 5.0 * pr;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    // unless post-residual would be tiny waste.
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - pr);
    }

    // New-bin candidate handling: an empty bin has maximal residual; make it
    // attractive only when the item is large relative to capacity or few bins fit.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let fill = item_size as f64 / bin_capacity as f64;
        // Prefer new bin for large items (good long-run use), penalize for small items.
        score -= 25.0 * fill * fill;
        score += 15.0 * (1.0 - fill) * (1.0 + progress);
    }

    // Slight preference to spread load when many bins are open and residual is high
    score += 3.0 * (open_bins_count as f64 / (open_bins_count as f64 + 5.0)) * pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: modulo arithmetic on capacity fractions.
    let post = post_residual as f64;
    let half = cap * 0.5;
    let third = cap / 3.0;
    let quarter = cap * 0.25;

    // Reward perfect fits and near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // Dead-space penalty: residuals in awkward harmonic classes are hard to fill.
    // Residuals in (0, 10) are nearly unusable for items >= 10 traditionally, but
    // with sizes 1..100 small residuals can still catch small items; still penalize lightly.
    if post < 10.0 && post > 0.0 {
        score += 15.0;
    }

    // Harmonic sweet spots: residuals near half/third/quarter of capacity are
    // reusable by many future item sizes. Reward proximity via cosine kernels.
    let kernel = |x: f64, center: f64, width: f64| -> f64 {
        let d = (x - center).abs();
        if d < width { (std::f64::consts::PI * d / width).cos() } else { 0.0 }
    };
    score -= 40.0 * kernel(post, half, 15.0);
    score -= 30.0 * kernel(post, third, 10.0);
    score -= 20.0 * kernel(post, quarter, 8.0);

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // this bin is a great choice; if next item barely misses, penalize.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= post {
            let slack = post - nx;
            score -= 60.0 * (1.0 - slack / cap);
            if slack == 0.0 { score -= 150.0; }
        } else {
            score += 0.5 * (nx - post).min(50.0);
        }
    }

    // Last-chance logic: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 {
        score -= 80.0;
    } else if fitting_bins_count > 3 {
        // Many alternatives: be picky, penalize mediocre fits.
        score += 10.0;
    }

    // New-bin candidate handling: an empty bin has high post_residual already
    // (post == cap - item). Bias toward reusing open bins unless the fit is poor.
    if bin_residual == bin_capacity {
        // Opening a new bin is justified only for large items or many open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 - 20.0 * progress;
        if open_bins_count == 0 { score -= 50.0; }
    }

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it is a tight bin; finishing it off is good (reduces fragmentation).
    let res = bin_residual as f64;
    if mean_residual > 0.0 {
        let diff = (res - mean_residual) / cap;
        score += 20.0 * diff; // tighter-than-average bins favored
    }

    // Modulo harmonic class bonus on post_residual: residuals divisible by
    // common item sizes (5, 10, 20, 25) are easier to fill later.
    let p = post_residual;
    if p % 5 == 0 { score -= 8.0; }
    if p % 10 == 0 { score -= 6.0; }
    if p % 25 == 0 && p > 0 { score -= 5.0; }

    // Integer-division threshold: post residual in [50, 100) keeps a half-bin
    // usable; below 50 the bin becomes "small change" — mild penalty gradient.
    if p >= 50 {
        score -= (p / 50) as f64 * 5.0;
    } else if p > 0 {
        score += (50 - p) as f64 * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small for the smallest
    // plausible item are pure waste; penalize them heavily.
    let dead_threshold = 9u32;
    if post_residual < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual) as f64 * 40.0;
    }
    if post_residual == 0 {
        // Perfect fit: strongly rewarded.
        score -= 100.0;
    }

    // Penalize leaving a gap that cannot fit the lookahead item if the next
    // item would otherwise need a new bin.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0;
    }
    // Reward leaving exactly enough room for the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    }

    // Open-bin pressure: when many bins are open, prefer tightening existing
    // bins rather than spreading items.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (1.0 + progress) * 0.05;

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 50.0;
    }

    // New-bin candidate handling: only open a new bin when the current bin's
    // fit is poor (large post residual that is unusable).
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 > mean_residual.max(10.0) * 0.6;
        if poor_fit {
            score -= 20.0; // encourage opening fresh bin on poor fits
        } else {
            score += 60.0; // discourage wasting a fresh bin on decent fits
        }
    }

    // Mild preference for bins whose residual is below the mean (tight bins).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits, but weight residual against capacity.
    score = post_residual as f64 * (1.0 + 0.5 * (bin_residual as f64 / bin_capacity as f64));

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let fit_gap = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - fit_gap / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item cannot fit here; penalize dead space.
        score += 8.0;
    }

    // Exact or near-exact closure bonus.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    // Compare against mean residual: avoid draining bins below average when
    // other bins have more room (keeps large residuals for large future items).
    if post_residual as f64 > mean_residual {
        score += 0.15 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.10 * (mean_residual - post_residual as f64);
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current item is large
    // and no good fit exists.
    if bin_residual == bin_capacity {
        score += 55.0;
        if item_size > 70 && (fitting_bins_count == 0 || next_item_size == 0) {
            score -= 60.0;
        }
    }

    // Mild stream progression bias: as stream ends, prefer closing bins tightly.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize large post_residual nonlinearly.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    score += 0.35 * (post * post) / cap;

    // Reward small absolute waste relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 12.0 * tightness * tightness;

    // Dead-space penalty: residuals too small for the smallest plausible item.
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // Lookahead: if next item fits in post_residual, reward this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0 + 0.15 * (next_item_size as f64);
    } else if next_item_size > 0 {
        // Next item won't fit here; slight penalty if we leave a large gap.
        score += 0.08 * post;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Many open bins: prefer consolidating into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.6 * (open_bins_count as f64).ln().max(0.0);

    // Compare against mean residual: prefer bins tighter than average.
    score += 0.10 * ((bin_residual as f64) - mean_residual);

    // New-bin candidate handling: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, reduced late in the stream.
        score = cap - 6.0 * progress;
        if fitting_bins_count == 1 {
            score += 30.0; // don't open a new bin when a last-chance bin exists
        }
        if post_residual as f64 > mean_residual {
            score += 4.0;
        }
    }

    // Early stream: be slightly more willing to spread items (future flexibility).
    score -= 5.0 * (1.0 - progress) * (1.0 - tightness);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;

    // Non-linear polynomial coupling: post_residual weighted by progress
    let coupling = pr * (0.5 + progress) + (pr * pr) / bin_capacity as f64 * (1.0 - progress);
    score += 0.15 * coupling;

    // Reward tight fits more strongly as stream progresses
    let tightness = (item_size as f64 / bin_capacity as f64).powi(2);
    score -= 8.0 * tightness * (0.3 + 0.7 * progress);

    // Penalize residual far from typical next-item need
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score += 0.2 * gap * (1.0 - progress * 0.5);
    }

    // Last-chance bin: strong reward to avoid opening new bins
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 6.0 + 4.0 * progress;
    }

    // New-bin candidate: penalize mildly, more when few bins open or early stream
    if bin_residual == bin_capacity {
        score += 5.0 + 3.0 * (1.0 - progress) + 0.5 * open_bins_count as f64;
    }

    // Dead-space penalty: residual too small to be useful for typical items
    let small_floor = 10.0f64.min(bin_capacity as f64 * 0.1);
    if pr > 0.0 && pr < small_floor {
        score += 10.0 * (small_floor - pr) / small_floor;
    }

    // Mild alignment with mean residual state
    score += 0.05 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fills get huge reward
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Modulo arithmetic classes on post_residual
        let pr = post_residual;
        let class = pr % 10;
        match class {
            0 => score -= 60.0,          // multiple of 10: highly reusable
            1 | 9 => score += 25.0,      // awkward edge residuals
            2 | 8 => score += 10.0,
            5 => score -= 15.0,          // half-decade residual, decent reuse
            _ => {}
        }
        // Integer division thresholds: small residuals are dead space
        if pr < 10 {
            score += 80.0;               // unusable for min-size items
        } else if pr < 20 {
            score += 30.0;
        } else if pr <= 30 {
            score -= 10.0;               // sweet spot: fits most small items
        }
        // Harmonic fraction: residual as fraction of capacity
        let frac = pr as f64 / bin_capacity as f64;
        if (frac * 4.0).round() as u32 == 1 {
            score += 12.0;               // quarter-capacity dead zone
        }
    }

    // Lookahead coupling: does post_residual fit the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // reward proportional to how snugly next item fits
            let snug = (post_residual - next_item_size) as f64;
            score -= 40.0 - snug.min(40.0) as f64;
        } else {
            // next item can't use this residual: penalize by gap size
            let gap = (next_item_size - post_residual) as f64;
            score += gap.min(50.0);
        }
        // next item exactly fills post residual: jackpot
        if post_residual == next_item_size {
            score -= 120.0;
        }
        // harmonic class match: next item size mod 10 equals post_residual mod 10
        if next_item_size % 10 == post_residual % 10 && post_residual >= next_item_size {
            score -= 20.0;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize unless current bins are nearly all full
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        // open new bin only if existing residuals are low (bins nearly full)
        score = 200.0 + pressure * 150.0
            - (fitting_bins_count as f64).recip() * 0.0;
        if fitting_bins_count == 0 {
            score -= 500.0; // no alternative, must open
        }
        if next_item_size > 0 && next_item_size > bin_capacity / 2 {
            score -= 30.0; // big next item: keep a fresh bin ready
        }
    }

    // Stream progression: late in stream, consolidate aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0 * (post_residual as f64 / bin_capacity as f64);

    // Many open bins: prefer filling existing ones over spreading
    score += open_bins_count as f64 * 0.5 * (post_residual as f64 / 10.0).floor();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps heavily.
    // A residual gap is "dead" if it cannot hold even a small future item.
    let dead_threshold = 10.0;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 8.0;
    }

    // Penalize mid-range residual that likely becomes stranded waste
    if post_residual > 0 && post_residual < item_size.max(1) {
        score += 2.0;
    }

    // Reward tight fits (small post_residual relative to item size)
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 12.0;

    // Open-bin pressure: discourage spreading across many bins when few needed
    score += open_bins_count as f64 * 0.35;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 6.0;
    } else if next_item_size > 0 && post_residual > 0 && (post_residual as u32) < next_item_size {
        score += 4.0;
    }

    // New-bin candidate: keep it attractive only when open bins are crowded
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        score = 25.0 + pressure * 20.0 + open_bins_count as f64 * 0.5;
    }

    // Mild stream-progression modulation: later in stream, prefer compacting
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead: item + next item exactly fills this bin.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Next item fits in the post-residual: strong reward, tighter is better.
    else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 50.0 + (next_item_size as f64 / post_residual.max(1) as f64) * 20.0;
    }
    // Next item would NOT fit: penalize proportionally to wasted potential.
    else if next_item_size > 0 {
        let waste = next_item_size as f64 - post_residual as f64;
        score += waste * 0.5;
    }

    // Reward tight fits relative to the mean residual of open bins.
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score -= (1.0 - tightness) * 30.0;
    score += (post_residual as f64 - mean_residual).abs() * 0.3;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: make it unattractive unless existing fits are terrible.
    if bin_residual == bin_capacity {
        score += 150.0;
        // Allow opening a new bin late in the stream if many bins are open.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 20.0;
    }

    // Slight preference for filling nearly-full bins to close them out.
    if post_residual < 10 {
        score -= 80.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / (total_items - 1) as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64 * (1.0 + 0.35 * progress);

    // Reward bins that absorb a large fraction of the item (tight packing).
    score -= 18.0 * (item_size as f64 / cap);

    // Lookahead (k=2): strongly reward leaving exactly the next item's size,
    // mildly reward leaving room for it, penalize stranding space it can't use.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) >= nxt {
            let slack = post_residual as f64 - nxt;
            score -= 14.0 * (1.0 - slack / cap);
        } else {
            score += 6.0 * (1.0 - post_residual as f64 / cap);
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 22.0;
    }

    // Coupling with global state: prefer bins whose residual is below the mean
    // (concentrate waste into few bins rather than spreading it).
    score += 0.12 * (mean_residual - post_residual as f64);

    // Mild pressure against proliferating bins late in the stream.
    score += 0.4 * open_bins_count as f64 * progress;

    // New-bin candidate: only chosen when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score = cap + 12.0 - 0.1 * item_size as f64 - 8.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: prefer small post-residual (tight fit), with non-linear sharpening.
    let mut score = post * (1.0 + 1.5 * norm_post * norm_post);

    // Reward near-perfect fits smoothly (quadratic dip around small residuals).
    score -= 25.0 * (1.0 - norm_post).powi(6);

    // Penalize residuals too small for likely future items: smooth coupling
    // between post_residual and the lookahead item size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = nxt - post;
        // If gap > 0, this residual likely becomes dead space; penalize smoothly.
        if gap > 0.0 {
            let g = gap / cap;
            score += 40.0 * g * g;
        } else {
            // Residual accommodates next item: reward, scaled by snugness.
            let snug = (-gap) / cap;
            score -= 10.0 * snug * (1.0 - snug);
        }
    }

    // Stream-progress coupling: early on, keep bins flexible (penalize fragmentation);
    // late, prioritize tight packing of current item.
    let flex_penalty = 12.0 * (1.0 - progress) * (norm_post * (1.0 - norm_post));
    score += flex_penalty;
    score -= 8.0 * progress * (1.0 - norm_post);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless existing fits are poor.
    if bin_residual == bin_capacity {
        let new_bin_base = 45.0 + 20.0 * progress;
        // If no other bin fits, this is the only choice: soften penalty.
        let softening = if fitting_bins_count == 0 { 60.0 } else { 0.0 };
        score += new_bin_base - softening;
        // Slight preference to open new bins when mean residual is high (fragmented state).
        score -= 0.05 * mean_residual;
    }

    // Mild penalty for spreading across many open bins early (encourages consolidation).
    score += 0.3 * open_bins_count as f64 * (1.0 - progress) * norm_post;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "usable"
    // classes (multiples of common item sizes) are favored.
    let pr = post_residual;
    if pr > 0 {
        let mut harmonic_bonus = 0.0;
        // Check divisibility by common size classes (10, 20, 25, 30, 40, 50)
        for m in [10u32, 20, 25, 30, 40, 50] {
            if pr % m == 0 {
                harmonic_bonus += 6.0 * (m as f64 / 10.0);
            }
        }
        score -= harmonic_bonus;
        // Dead space penalty: tiny leftovers are hard to fill
        if pr < 10 {
            score += 15.0;
        }
    }

    // Exact fit is perfect
    if post_residual == 0 {
        score -= 100.0;
    }

    // Integer division threshold on post_residual: quarter classes
    let quarter = bin_capacity / 4;
    if post_residual <= quarter {
        score += 5.0; // small leftover, mildly penalize unless exact/harmonic
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let gap = post_residual - next_item_size;
            score -= 10.0 * (1.0 - gap as f64 / cap);
            if gap < 10 {
                score += 8.0; // would create dead space next step
            }
        }
        // If next item can't use this bin's leftover anyway, prefer tighter fit now
        if next_item_size > post_residual {
            score += 3.0;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin gets a moderate default so it's
    // chosen only when no open bin offers a good (harmonic/exact) fit.
    if bin_residual == bin_capacity {
        score = cap * 0.5 + mean_residual * 0.2;
        if fitting_bins_count == 0 {
            score -= 30.0; // no alternative, must open
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // pairing large items together is fine
        }
    }

    // Progress-based mild consolidation pressure
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 2.0;
    score -= (open_bins_count as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong penalty for "dead space": residuals too small to be useful
    // (below the minimum plausible item size region), scaled non-linearly.
    if post_residual > 0 {
        let pr = post_residual as f64;
        if pr < 10.0 {
            score += 60.0 * (10.0 - pr) / 10.0; // tiny unusable gap
        } else if pr < 30.0 {
            // gap usable only by small items: mild penalty
            score += 0.35 * (30.0 - pr);
        }
    }

    // Reward tight fits (small post_residual relative to bin).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly into the post residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
        if post_residual == next_item_size {
            score -= 25.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        // next item cannot use this gap: penalize proportionally
        score += 0.2 * (next_item_size as f64 - post_residual as f64);
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Pressure from open bins: discourage opening new bins when few bins open,
    // but allow consolidation pressure when many bins are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let bin_pressure = open_bins_count as f64 * (0.3 + 0.7 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize it more as open_bins_count grows.
        score += 18.0 + bin_pressure;
        // Allow new bin if this item would leave a large unusable gap elsewhere
        // (handled implicitly since poor fits get high scores above).
    } else {
        // Mild reward for reusing existing bins, stronger later in the stream.
        score -= 2.0 + 3.0 * progress;
    }

    // Mean residual coupling: prefer bins whose residual is below the mean
    // (i.e., filling the emptier-of-space bins less is worse).
    let dev = mean_residual - bin_residual as f64;
    score += 0.08 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect/near-perfect fit
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 3 {
        score -= 500.0;
    }

    // 2-step lookahead: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual >= next_item_size {
            let lookahead_residual = post_residual - next_item_size;
            if lookahead_residual <= 5 {
                score -= 250.0;
            } else {
                // partial reward proportional to how much the next item consumes
                score -= 80.0 * (next_item_size as f64 / post_residual as f64);
            }
        } else {
            // next item won't fit here; penalize large dead space relative to next item
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Compare post_residual against mean residual across open bins:
    // leaving this bin far below mean residual creates outlier dead space.
    if post_residual as f64 > mean_residual {
        score += 0.3 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.15 * (mean_residual - post_residual as f64);
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // Penalize opening a new bin when open bins can reasonably fit the item
    if bin_residual == bin_capacity {
        score += 120.0;
        // but soften if few bins are open early in the stream
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 60.0 * (1.0 - progress);
    }

    // Mild penalty for large item into nearly empty bin (waste of big space)
    if item_size >= 60 && bin_residual == bin_capacity {
        score += 20.0;
    }

    // Small tie-break toward bins with tighter residual
    score += 0.01 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit bonus: reward small post_residual non-linearly.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tight * tight * tight;

    // Perfect-fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Penalize dead space that cannot fit a typical future item.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Lookahead coupling: if the next item fits the post-residual exactly or well,
    // reward this placement strongly.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let gap = (post_residual - next_item_size) as f64;
            score -= 18.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item won't fit here; slight penalty proportional to overflow.
            score += 0.08 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Global state: when many bins are open with high mean residual, discourage
    // spreading items thinly; prefer filling bins closer to mean residual.
    if open_bins_count > 0 {
        let spread = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * spread;
        score += 0.15 * open_bins_count as f64;
    }

    // Time horizon: late in the stream, prioritize consolidation (tight packing);
    // early, allow more exploration of new bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 15.0 * progress * tight;
    score += 8.0 * (1.0 - progress) * (bin_residual as f64 / bin_capacity as f64);

    // New-bin candidate: make opening a new bin moderately costly, but cheaper
    // when the item is large and no tight fit exists elsewhere.
    if bin_residual == bin_capacity {
        score += 10.0 + 0.3 * item_size as f64 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: reward tight fits via non-linear decay of post-residual
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth progress coupling: later in stream, penalize leftover space more strongly
    score += 30.0 * progress * norm_pr * norm_pr;

    // Dead-space penalty: residual too small for typical future items
    let dead = (30.0f64 - pr.min(30.0) as f64).max(0.0);
    score += 1.5 * dead * (0.5 + progress);

    // Lookahead: reward bins whose post-residual can host next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 12.0 * (1.0 - pr / (pr + nxt)) * (1.0 - progress);
        } else {
            score += 6.0 * (nxt - pr) / cap;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - 0.5 * progress);
    }

    // Mild penalty when bin deviates from mean residual (prefer balanced fills)
    score += 0.3 * ((pr - mean_residual) / cap).abs() * cap * 0.1;

    // New-bin candidate: keep neutral baseline so it's chosen only when open bins score poorly
    if bin_residual == bin_capacity {
        score += 20.0 + 15.0 * (1.0 - progress);
    }

    // Encourage consolidating into fewer bins when many are open
    score -= 1.0 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify dead space into residue classes mod 10.
    let pr = post_residual as i64;
    let cls = pr % 10;
    // Residues 1..9 are awkward; 0 is perfect fit; large residuals are still useful.
    if pr == 0 {
        score -= 60.0; // perfect fit — strongly reward
    } else if pr < 10 {
        // Dead space below minimum item size: unusable forever.
        score += (10 - pr) as f64 * 1.5;
    } else {
        // Modulo penalty: odd/awkward residues slightly penalized, class 5 penalized most
        // (hard to pair with typical item sizes), classes 2/4/8 pair well.
        let awkward = match cls {
            0 => -3.0,
            2 | 4 | 6 | 8 => 0.5,
            5 => 3.0,
            _ => 1.5,
        };
        score += awkward;
    }

    // Capacity fraction coupling: reward filling a large fraction of the bin.
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= fill_frac * 25.0;

    // Harmonic lookahead: does next_item_size divide into post_residual nicely?
    if next_item_size > 0 {
        let n = next_item_size as i64;
        if n <= pr {
            // next item fits here too: reward, scaled by how well it divides
            if pr % n == 0 {
                score -= 30.0; // exact harmonic pairing
            } else {
                score -= 12.0;
            }
        } else {
            // next item won't fit here; mild penalty unless post_residual is large enough
            // to be reusable for a typical future item (>= 10).
            if pr < 10 {
                score += 10.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current open bins
    // would leave very awkward residuals.
    if bin_residual == bin_capacity {
        // base cost of a fresh bin
        score += 45.0;
        // more open bins with slack => discourage new bin
        score += open_bins_count as f64 * 2.0;
        // early in stream, opening bins is cheaper (future packing flexibility)
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 20.0;
        // if item is large and mean residual is small, new bin is fine
        if fill_frac > 0.6 {
            score -= 25.0;
        }
    }

    // Tie-break: prefer bins whose residual is close to the mean (balanced packing).
    score += ((bin_residual as f64 - mean_residual) / bin_capacity as f64).abs() * 5.0;

    // Small deterministic tie-break via step parity (harmonic alternation).
    if step_index % 2 == 0 {
        score -= 0.125;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harsh penalty for small unusable gaps (dead space) after placement.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    if item_size > 0 {
        score -= (item_size as f64) * 0.8;
    }

    // Penalize leaving residual that cannot fit a typical next item.
    if next_item_size > 0 && (post_residual as u32) < next_item_size && post_residual > 0 {
        score += 15.0;
    }

    // Open-bin pressure: with many open bins, prefer reusing existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Slight reward when this is the only fitting bin (last chance).
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins).
    score -= (mean_residual - post_residual as f64) * 0.3;

    // New-bin candidate: make empty bins moderately attractive only when
    // no open bin fits well (post_residual large here means fresh bin).
    if bin_residual == bin_capacity {
        score += 8.0 + open_bins_count as f64 * 0.4;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: 2-step lookahead — reward bins whose post residual matches the next item size.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let post = post_residual as f64;
        if post >= next {
            let gap = post - next;
            // Perfect match: next item exactly fills the remaining space.
            if gap == 0.0 {
                score -= 60.0;
            } else {
                // Reward closeness of post_residual to next_item_size.
                score -= 40.0 * (1.0 - gap / bin_capacity as f64);
                // Penalize leaving a gap that is too small for anything useful (dead space).
                if gap < 10.0 {
                    score += 15.0;
                }
            }
        } else {
            // Next item cannot fit here; the leftover post_residual is likely dead space.
            score += 25.0 + (next - post);
        }
    } else {
        // Last item: prefer tightest fit overall.
        score += 5.0;
    }

    // Relative-to-mean coupling: prefer bins with residual below mean (tighter bins)
    // when they still fit well, penalize bins far above the mean (fragmentation).
    let mean = mean_residual;
    let post = post_residual as f64;
    if post < mean {
        score -= 8.0 * (mean - post) / bin_capacity as f64;
    } else {
        score += 6.0 * (post - mean) / bin_capacity as f64;
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin has post_residual == capacity - item_size.
    // Penalize opening a new bin mildly, unless current bin would leave heavy dead space.
    if bin_residual == bin_capacity {
        score += 20.0;
        // But if lookahead matches well in a fresh bin, soften the penalty.
        if next_item_size > 0 && (post_residual as f64 - next_item_size as f64).abs() < 5.0 {
            score -= 25.0;
        }
    }

    // Stream progression: later in the stream, be more conservative about wasting space
    // (dead-space penalty grows), since fewer chances remain to recover.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Many open bins: slight preference to consolidate into existing bins.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly prefer bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // Dead-space penalty: leftover space that is too small for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post residual can host the next item exactly-ish.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        } else if post_residual > 0 {
            score += 6.0;
        }
    } else {
        // Last item: just minimize waste, prefer any fit over a new bin.
        score -= 40.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // Global fragmentation pressure: many open bins with low mean residual -> consolidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual < bin_capacity {
        score -= 8.0 * (mean_residual / bin_capacity as f64) * (0.5 + progress);
    }

    // Penalize opening a new bin when decent fits exist, more so late in the stream.
    if bin_residual == bin_capacity {
        score += 15.0 + 20.0 * progress;
        if fitting_bins_count > 0 && (post_residual as f64) < 0.5 * bin_capacity as f64 {
            score += 10.0;
        }
    }

    // Mild preference for bins with residual close to the item (exactness).
    score -= 5.0 * (1.0 - ((bin_residual - item_size) as f64 / bin_capacity as f64)).min(1.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Normalized post residual
    let pr = post_residual as f64 / bin_capacity as f64;

    // Non-linear polynomial coupling: tight fits rewarded more strongly as stream progresses
    let tightness = (1.0 - pr).powi(3);
    score -= 12.0 * tightness * (0.5 + progress);

    // Quadratic penalty on wasted residual, amplified late in the stream
    score += 4.0 * pr * pr * (1.0 + 3.0 * progress);

    // Lookahead coupling: reward if the next item fits in the post residual
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if post_residual >= next_item_size {
            let snug = (post_residual as f64 - ns) / bin_capacity as f64;
            score -= 8.0 * (1.0 - snug) * (1.0 - snug);
        } else {
            // penalize leaving residual that cannot host the lookahead item
            score += 6.0 * pr * (1.0 - progress);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 * (1.0 + progress);
    }

    // Penalize opening a new bin when decent fits exist
    if bin_residual == bin_capacity {
        score += 20.0 + 10.0 * (1.0 - progress);
        // mild discount if open bins are crowded
        score -= 2.0 * (open_bins_count as f64).sqrt();
    }

    // Mild preference toward bins below mean residual (balance load)
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: reward residuals in "useful" bands
    // (small enough to be fillable by typical items, or exactly zero).
    let pr = post_residual;
    if pr == 0 {
        score -= 50.0; // perfect fit
    } else {
        // modulo classes on post_residual (harmonic classes of 10)
        let class = pr % 10;
        let class_bonus = match class {
            0 => 8.0,          // multiple of 10: highly reusable
            5 => 4.0,          // half-class
            1 | 9 => 1.0,
            _ => -2.0,         // awkward odd remainder
        };
        score += class_bonus;

        // integer-division thresholds: residual in [1..10] is nearly dead
        let band = pr / 10;
        score += match band {
            0 => 12.0,                 // <10: likely dead space
            1 => 2.0,
            2 => -1.0,
            3 => -3.0,
            _ => -2.0,
        };
    }

    // Capacity-fraction coupling: how full will the bin be
    let fill_frac = (bin_capacity - pr) as f64 / cap_f;
    score -= 6.0 * fill_frac; // prefer fuller bins

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / cap_f);
        } else {
            // next item cannot use this residual: penalize small leftovers harder
            let over = (next_item_size - pr) as f64;
            score += 0.05 * over;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Mean residual context: prefer bins with residual below mean (tighter bins)
    let res_f = bin_residual as f64;
    score += 0.5 * (res_f - mean_residual);

    // New-bin candidate handling: opening a new bin is only attractive when
    // no good fit exists. Base penalty keeps it behind decent fits.
    if bin_residual == bin_capacity {
        // fresh bin: score ~ waste of a whole empty bin, minus value of
        // guaranteed space for the future
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut nb = cap_f * 0.9; // heavy base penalty
        nb -= 10.0 * progress;    // slightly more willing later? keep conservative
        // if next item is large, a fresh bin is more useful
        if next_item_size >= 50 {
            nb -= 8.0;
        }
        // if many bins are open already, discourage spreading
        nb += 2.0 * open_bins_count as f64;
        score = score.max(nb); // never better than a true fit's score floor
        score = nb.max(score.min(cap_f)); // clamp interplay
        // Final: new bin chosen only if all open bins score above nb
        return nb + (score - nb) * 0.0 + 0.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. STRICT dead-space avoidance: residuals too small to be useful are dead space.
    // A residual is "dead" if it cannot hold the smallest plausible future item.
    let min_useful = 10u32.min(bin_capacity);
    if post_residual < min_useful {
        // Perfect fill: reward heavily.
        score -= 60.0;
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Residual cannot fit the known next item: strong dead-space penalty,
        // scaled by how close it is to being wasted entirely.
        let waste_frac = 1.0 - (post_residual as f64 / next_item_size as f64);
        score += 25.0 + 35.0 * waste_frac;
    }

    // 2. Non-linear tightness reward: exponential bonus for snug fits.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 20.0 * tightness * tightness;

    // 3. Open-bin pressure: discourage spreading across many bins when a
    //    good fit exists elsewhere; mild pressure only.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (open_bins_count as f64).sqrt() * (1.5 + 2.5 * progress);

    // 4. Last-chance bin: if this is the only bin that fits, strongly prefer it
    //    over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 + 0.5 * item_size as f64;
    }

    // 5. New-bin candidate handling: an empty bin has residual == capacity.
    //    Prefer it only when the item leaves a large, reusable gap AND the
    //    current bin would leave a dead gap.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, offset by the flexibility of a
        // full-capacity residual.
        score += 12.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 8.0;
        }
        // Late in the stream, consolidation matters more: penalize new bins.
        score += 10.0 * progress;
    } else {
        // 6. Alignment with mean residual: prefer bins whose post-residual
        //    stays near the fleet mean (keeps residuals homogeneous and usable).
        let dev = (post_residual as f64 - mean_residual).abs();
        score += 0.08 * dev;
    }

    // 7. Lookahead coupling: reward leaving exactly enough room for the next
    //    item (perfect two-item packing).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong 2-step lookahead: perfect match with next item is excellent.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // exact fill by the next item
        } else if post_residual >= next_item_size {
            // reward tight couplings: leftover after both items should be small
            score -= 40.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // dead space: next item cannot use this residual
            let waste = (next_item_size - post_residual) as f64;
            score += 0.8 * waste.min(50.0);
        }
    }

    // Prefer bins whose residual is small relative to the mean (tight packing),
    // penalize using bins with unusually large residuals when others are tight.
    score += 0.3 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive if no open bin fits well.
    if bin_residual == bin_capacity {
        let base = bin_capacity as f64;
        score = base + 10.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        } else if next_item_size > 0 && post_residual >= next_item_size {
            score -= 5.0;
        }
        // late in the stream, prefer closing out existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Mild bonus for very tight fits overall.
    if post_residual <= 5 {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong preference for tight fits (low post_residual).
    let tight_fit = post_residual as f64 / bin_capacity as f64;
    score += tight_fit * 30.0;

    // Reward filling the bin nearly completely (waste-aware term, quadratic).
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= fill_ratio * fill_ratio * 40.0;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize leaving residuals that are too small to be useful for typical items
    // (dead space): residual in (0, 10) is worst.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post_residual,
    // this placement chains perfectly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            // Next item fits, but leaves a residual gap; mild reward.
            score -= (post_residual - next_item_size) as f64 * 0.1;
        } else {
            // Next item won't fit here; penalize small leftover that traps nothing.
            score += (next_item_size - post_residual) as f64 * 0.05;
        }
    }

    // Global state: when many bins are open with high mean residual, encourage
    // consolidating into existing bins rather than opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive if current bins are fragmented
        // (mean residual high relative to item) or none fit well.
        let fragmentation = mean_residual / bin_capacity as f64;
        score += 35.0 - fragmentation * 20.0 + progress * 10.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        }
        // Prefer new bin late in the stream to avoid many slightly-used bins early.
        score += (1.0 - progress) * 15.0;
    } else {
        // Existing bin: slight bonus when mean residual is high (reduce fragmentation).
        score -= mean_residual * 0.05;
    }

    // Mild time-horizon effect: early on, be conservative about near-perfect fits
    // that waste capacity potential; late, grab any fit.
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post-residual, smoothed by non-linear polynomial in progress
    let mut score = pr * (1.0 + 0.5 * progress * progress);

    // Quadratic waste penalty: large residuals late in the stream are dead space
    score += 40.0 * norm_pr * norm_pr * (0.3 + 0.7 * progress);

    // Perfect-fit reward (smooth exponential-like polynomial coupling)
    let fit_quality = 1.0 - norm_pr;
    score -= 30.0 * fit_quality * fit_quality * fit_quality;

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: if next item fits in post_residual, reward
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = (pr - nxt) / cap;
            score -= 20.0 * (1.0 - slack) * (0.5 + 0.5 * progress);
        } else {
            // penalize leaving residual that cannot host next item
            score += 10.0 * (nxt - pr) / cap;
        }
    }

    // Mean-residual coupling: prefer bins below mean residual (tighter fits)
    score += 0.3 * (mean_residual - pr);

    // New-bin candidate handling: neutral-ish, penalized slightly more late
    if bin_residual == bin_capacity {
        score = cap * (1.1 + 0.4 * progress) - 5.0 * fit_quality;
    }

    // Mild penalty for spreading across many open bins
    score += 0.05 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that are "perfect" small
    // remainders (0, or <= 5) — near-perfect packing.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Integer-division harmonic classes: residuals divisible by common item
    // granularity (e.g. multiples of 10) are more reusable.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    } else if post_residual % 5 == 0 && post_residual > 0 {
        score -= 4.0;
    }

    // Dead-space penalty: residual too small for typical items (1..100, min 1,
    // but small residuals waste capacity fraction).
    let waste = post_residual as f64 / cap;
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // unusable sliver
    } else {
        score += 20.0 * waste * waste; // quadratic waste penalty
    }

    // Lookahead coupling: reward if next item fits exactly in post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / cap);
        } else {
            // next item won't fit here; slight penalty for hoarding space
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fits are bad.
    if bin_residual == bin_capacity {
        score += 30.0 + 0.5 * open_bins_count as f64;
        // but if mean residual across open bins is tiny, new bin is fine
        if mean_residual < 10.0 {
            score -= 25.0;
        }
    }

    // Prefer fuller bins relative to mean residual of open bins.
    score -= 5.0 * (mean_residual - post_residual as f64) / cap;

    // Mild stream-progression term: later in stream, be greedier (fill bins tight).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold even the
    // smallest plausible future item are "dead" — penalize them hard.
    let dead_threshold = 10.0_f64.min(cap * 0.2);
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 4.0;
    }

    // Reward tight fits (post_residual near zero is perfect).
    if post_residual == 0 {
        score -= 30.0;
    }

    // Perfect-fit anticipation: if the next item exactly fills the post
    // residual, strongly reward this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Next item still fits here: mild reward proportional to how snugly.
        let slack_after_next = (post_residual - next_item_size) as f64;
        score -= 10.0 * (1.0 - slack_after_next / cap);
    } else if next_item_size > post_residual && next_item_size > 0 {
        // This bin will be dead for the lookahead item: penalize proportionally.
        score += 8.0;
    }

    // Last-chance bin: if this is the only bin that fits, opening a new bin
    // would fragment capacity — reward using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins; opening a new bin (residual == capacity) is penalized
    // more as open_bins_count grows.
    if bin_residual == bin_capacity {
        score += 12.0 + 2.0 * open_bins_count as f64;
        // But if no existing bin fits well (large post residual elsewhere),
        // a fresh bin is fine — soften via mean residual comparison.
        if mean_residual < item_size as f64 {
            score -= 10.0;
        }
    } else {
        // Prefer bins whose residual is close to the item (snug fit).
        let snugness = 1.0 - ((bin_residual - item_size) as f64 / cap);
        score -= 6.0 * snugness;
    }

    // Early in the stream, tolerate opening bins (future items unknown);
    // late in the stream, be conservative and fill existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 10.0 * progress;
    } else {
        score -= 5.0 * progress;
    }

    // Penalize leaving residuals just below common item sizes (unusable gap).
    for gap in [10u32, 20, 25, 30, 40, 50] {
        if post_residual > 0 && post_residual < gap {
            score += 2.0;
            break;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual equals next item's size -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Near match: next item fits into the post residual with small slack.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
    }

    // Penalize dead space: post residual too small for any plausible future item
    // (below minimum plausible size), i.e. wasted capacity.
    if post_residual < 10 {
        score += 30.0;
    }

    // Relative-to-mean residual shaping: prefer bins whose post residual tracks
    // the fleet mean (balanced packing), penalize outliers.
    let diff = post_residual as f64 - mean_residual;
    score += 0.15 * diff.abs();

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a new bin leaves a huge residual.
    // Only attractive when no good fit exists (post_residual here is capacity).
    if bin_residual == bin_capacity {
        score += 20.0;
        // Dampen new-bin appeal when many bins are already open.
        score += open_bins_count as f64 * 2.0;
        // If the next item can fully use a fresh bin too, slightly favor it.
        if next_item_size == 0 {
            score -= 5.0;
        }
    }

    // Late-stream consolidation: as the stream progresses, prefer filling
    // existing bins tighter rather than spreading out.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits: low post_residual is good, but penalize
    // leaving residuals too small to ever be useful again.
    let useful_threshold = 10.0f64;
    if (post_residual as f64) < useful_threshold && post_residual > 0 {
        score += 25.0; // dead space penalty: residual can't fit min-size item
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 40.0;
    }

    // Fit quality: fraction of bin used by this placement
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio;

    // Lookahead coupling: if the next item fits the post-residual exactly or well,
    // reward this placement strongly (chaining placements).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chain
        } else if next_item_size <= post_residual {
            let chain_fit = next_item_size as f64 / post_residual.max(1) as f64;
            score -= 35.0 * chain_fit;
        } else {
            // next item cannot use this residual: mild penalty proportional to gap
            let gap = next_item_size as f64 - post_residual as f64;
            score += 0.15 * gap;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 + 0.1 * item_size as f64;
    }

    // New-bin candidate handling: opening a new bin should only win when existing
    // fits are poor. Penalize the empty-bin candidate dynamically.
    if bin_residual == bin_capacity {
        // Base cost of consuming fresh capacity
        score += 15.0;
        // More open bins already => higher cost of adding another (fragmentation)
        score += 2.0 * open_bins_count as f64;
        // Early in stream, opening bins is cheaper (need parallel capacity later)
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 40.0 * progress;
        // If mean residual across open bins is large, opening new bin is wasteful
        score += 0.5 * mean_residual;
        // But if next item is huge and won't fit anywhere typical, a fresh bin is valuable
        if next_item_size > 60 {
            score -= 30.0;
        }
    }

    // Prefer bins whose residual deviates favorably from the mean (consolidation)
    let dev = bin_residual as f64 - mean_residual;
    score += 0.05 * dev;

    // Mild time-horizon term: late in stream, be greedier about tight fits
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * fit_ratio;

    // Slight preference for filling larger bins when many bins are open
    score += 0.02 * (open_bins_count as f64) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;
    // Non-linear polynomial coupling of post_residual with stream progress
    let t = progress;
    let poly = 1.0 + 0.6 * t - 0.8 * t * t + 0.4 * t * t * t;
    score *= poly;
    // Penalize large dead space more than linearly (quadratic coupling)
    score += 6.0 * norm_pr * norm_pr * cap * (0.5 + t);
    // Reward tight fits, especially when few alternatives exist
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 - norm_pr) * (1.0 + t);
    } else {
        score += 2.0 * (fitting_bins_count as f64).ln().max(0.0) * norm_pr;
    }
    // Lookahead coupling: reward residual that can host the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 5.0 * (1.0 - nx / cap) * (1.0 - norm_pr);
        } else {
            score += 4.0 * (nx - pr) / cap * (0.5 + t);
        }
    }
    // Dampen preference for very full bins when many bins are open and mean residual is high
    score += 0.05 * (open_bins_count as f64) * (mean_residual - pr).abs() / cap;
    // Slight bonus for filling bins deeper as stream progresses
    score -= 10.0 * t * (1.0 - norm_pr) * (1.0 - norm_pr);
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // ---- Harmonic class of the post residual: quantize leftover space ----
    // Class 0: post_residual == 0 (perfect fit) -> huge reward.
    // Class 1: post_residual small (1..=10) -> strong reward (near-perfect).
    // Class 2: post_residual in "dead zone" (11..=25) -> penalty (waste).
    // Class 3: post_residual large enough to host a typical next item -> mild reward.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0;
    } else if pr <= 10 {
        score -= 40.0 - (pr as f64) * 2.0;
    } else if pr <= 25 {
        // dead space zone: unusable for most items (min size 1..100, but small
        // leftovers rarely match) -> penalty proportional to wasted fraction
        score += (pr as f64) * 0.8;
    } else {
        // usable leftover: reward keeping capacity for future items
        score -= (pr as f64) * 0.15;
    }

    // ---- Modulo arithmetic on post_residual vs common item sizes ----
    // Reward when post_residual is a "harmonic" multiple/divisor of typical sizes.
    let harmonic = |x: u32| -> f64 {
        let mut h = 0.0;
        for d in [10u32, 20, 25, 50, 80, 100] {
            if x % d == 0 && x > 0 {
                h += 6.0;
            }
        }
        h
    };
    score -= harmonic(pr);

    // ---- Lookahead coupling: does post_residual pair with next_item_size? ----
    if next_item_size > 0 {
        let n = next_item_size;
        if n <= pr {
            // next item fits exactly or nearly: reward tightness
            let gap = pr - n;
            if gap == 0 {
                score -= 35.0;
            } else if gap <= 10 {
                score -= 20.0;
            } else {
                score -= 5.0;
            }
        } else {
            // next item will NOT fit here: leftover is dead for the lookahead
            score += (pr as f64) * 0.35;
        }
        // harmonic pairing: post_residual + next_item sums to capacity-ish
        if pr + n == bin_capacity {
            score -= 25.0;
        }
    }

    // ---- Integer division thresholds on item_size ----
    let cls = item_size / 25; // 0..3 harmonic class of the item
    match cls {
        0 => score -= 3.0,  // small item: easy to place anywhere, slight bonus
        1 => {}             // medium
        2 => score += 1.0,  // large
        _ => score += 3.0,  // very large: prefer bins with tight fit (handled above)
    }

    // ---- Last-chance bin: strongly favor using the only fitting bin ----
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // ---- New-bin candidate handling ----
    if bin_residual == bin_capacity {
        // Opening a new bin: baseline cost, modulated by how bad existing options are.
        // If many fitting bins exist, opening new is wasteful.
        if fitting_bins_count > 0 {
            score += (fitting_bins_count as f64) * 8.0;
        } else {
            score -= 20.0;
        }
        // Late in the stream, prefer closing out existing bins (avoid stragglers)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 5.0;
        // If many open bins already, discourage opening yet another
        score += (open_bins_count as f64) * 1.5;
    }

    // ---- Mean residual context: prefer bins deviating favorably from mean ----
    let res_f = bin_residual as f64;
    if res_f > mean_residual {
        score -= (res_f - mean_residual) * 0.1;
    } else {
        score += (mean_residual - res_f) * 0.1;
    }

    // ---- Progress-based mild exploration: early stream, tighter fits matter more
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.1 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small to hold anything are worthless.
    // With unknown distribution, treat very small gaps (< ~15) as high-risk dead space.
    if post_residual < 15 {
        score += 60.0 * (15.0 - post_residual as f64);
    } else if post_residual == 0 {
        score -= 40.0; // perfect fit is ideal
    }

    // Reward tight fits: fraction of bin used by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill;

    // Penalize wasting a large-residual bin on a small item (poor utilization).
    if (bin_residual as f64) > 2.5 * item_size as f64 && post_residual > 30 {
        score += 15.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (open_bins_count as f64).sqrt() * 4.0 * (0.5 + 0.5 * progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: default moderate score; opened only if no decent fit exists.
    if bin_residual == bin_capacity {
        score = 70.0 + 0.5 * mean_residual - 10.0 * fill;
        // Late in the stream, consolidating into open bins is cheaper.
        score += 20.0 * progress;
        // If lookahead item is small, a fresh bin keeps flexibility.
        if next_item_size > 0 && (next_item_size as f64) < 0.35 * bin_capacity as f64 {
            score -= 15.0;
        }
    } else {
        // Lookahead coupling: leaving a gap exactly matching the next item is great.
        if next_item_size > 0 {
            let gap_diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
            score -= 20.0 / (1.0 + gap_diff);
        }
    }

    // Prefer bins whose residual is close to mean (balanced packing).
    score += 0.1 * ((bin_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate: penalize opening a new bin, but relax when current bin
    // fit is very poor (large dead space) or when this is the last fitting bin.
    let is_new_bin = bin_residual == bin_capacity;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    if is_new_bin {
        score = bin_capacity as f64 * 1.5;
        // Late in stream, keep consolidating: stronger penalty.
        score += 30.0 * progress;
        // If this bin is the only fitting option, opening a new bin is less bad.
        if fitting_bins_count == 1 {
            score -= 40.0;
        }
        // If existing bins would leave huge dead space, new bin is more attractive.
        let dead = (bin_residual as f64 - item_size as f64).max(0.0);
        if dead > 0.35 * bin_capacity as f64 {
            score -= 0.5 * (dead - 0.35 * bin_capacity as f64);
        }
        return score;
    }

    // --- 2-step lookahead matching ---
    let post = post_residual as f64;
    let next = next_item_size as f64;

    if next > 0.0 {
        // Perfect match: next item exactly fills post_residual.
        let diff = (post - next).abs();
        score -= 60.0 / (1.0 + diff);
        // Reward if next item fits exactly (diff == 0) extra bonus.
        if diff == 0.0 {
            score -= 25.0;
        }
        // Penalize if next item cannot fit into post_residual (wasted lookahead).
        if next > post {
            score += 0.15 * (next - post);
        }
    } else {
        // Last item: strongly prefer tightest fit.
        score -= 50.0;
    }

    // Relative to mean residual: prefer bins whose post_residual deviates
    // favorably (smaller than mean -> consolidating space).
    score += 0.3 * (post - mean_residual);

    // Last-chance bonus: if this is the only bin that fits, avoid opening new bin.
    if fitting_bins_count == 1 {
        score -= 45.0;
    }

    // Penalize creating tiny unusable slivers (dead space < 10, min item size).
    if post_residual > 0 && post_residual < 10 {
        score += 35.0;
    }
    // Reward exact fills.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Mild preference for filling already-open bins as stream progresses.
    score -= 5.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: square the post-residual to punish wasted space super-linearly.
    score += (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: if next item fits into the post-residual, strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.1 * (next_item_size as f64);
    } else if next_item_size > 0 && post_residual > 0 {
        // Dead space unusable by next item: penalize proportionally.
        score += 0.15 * (post_residual as f64);
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: opening a new bin is generally expensive; penalize it
    // unless the fit in existing bins would be terrible.
    if bin_residual == bin_capacity {
        score += 30.0;
        // Early in the stream, opening bins is cheaper (build flexibility).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 20.0 * (1.0 - progress);
        // If many open bins already have large residuals, avoid opening more.
        score += 0.05 * open_bins_count as f64;
        // If mean residual is large, prefer existing bins.
        score += 0.1 * mean_residual;
    }

    // Mild preference for bins below mean residual (keep some bins tight, save loose ones).
    if bin_residual < bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        score += 0.05 * diff;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit_frac = item_size as f64 / cap;

    // Base: prefer small post-residual, with non-linear emphasis on tight fits.
    let mut score = pr * (1.0 + 0.8 * fit_frac * (1.0 - progress));

    // Smooth penalty for large unusable residual (dead space grows super-linearly).
    let dead = (pr / cap).powi(3);
    score += 30.0 * dead;

    // Reward filling bins almost completely, stronger later in the stream.
    score -= (1.0 - (pr / cap)) * (1.0 + progress) * 10.0;

    // Lookahead coupling: penalize leaving residual that barely misses next item,
    // reward residual that can host the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = pr - nxt;
        if gap >= 0.0 {
            score -= 8.0 * (1.0 - (gap / cap).powi(2)) * (0.5 + progress);
        } else {
            score += 6.0 * ((-gap) / cap).powi(2);
        }
    }

    // Last-chance bin: strongly reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 * (0.5 + progress);
    }

    // New-bin candidate: penalize mildly, more when many bins are open and
    // mean residual is high (existing capacity is being wasted).
    if bin_residual == bin_capacity {
        let waste = (mean_residual / cap).clamp(0.0, 2.0);
        score += 12.0 + 4.0 * (open_bins_count as f64).ln1p() + 10.0 * waste * (1.0 - progress);
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.05 * open_bins_count as f64 * (pr / cap);

    // Small stream-progress drift to break ties toward reuse late.
    score += progress * 2.0 * (pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual;

    // Tight-fit rewards: dead space is the enemy
    if pr == 0 {
        score -= 60.0;
    } else if pr <= 5 {
        score -= 25.0;
    } else if pr <= 10 {
        score -= 10.0;
    }

    // Harmonic class logic: residual modulo 10 determines future pairing quality.
    // Residuals that are exact multiples of 10 align with the classic size grid.
    let cls = pr % 10;
    score -= match cls {
        0 => 6.0,
        1..=5 => 2.0,
        _ => 0.0,
    };

    // Lookahead coupling: strongly favor bins whose leftover can host the next item
    if next_item_size > 0 && next_item_size <= pr {
        let slack = (pr - next_item_size) as f64;
        score -= 12.0 + slack * 0.15;
    } else if next_item_size > 0 && next_item_size > bin_residual {
        // next item won't fit anywhere in this bin's trajectory; mild penalty
        score += 3.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // Relative waste vs. portfolio mean residual
    score += (pr as f64 - mean_residual) * 0.25;

    // New-bin candidate handling (empty bin: bin_residual == bin_capacity)
    if bin_residual == bin_capacity {
        // Base premium for opening a new bin; scales with the space that would be left
        let mut nb = 35.0 + pr as f64 * 0.6;
        // If no open bin fits, the new bin is the only choice
        if fitting_bins_count == 0 {
            nb -= 100.0;
        }
        // Early in stream, prefer consolidation less strongly
        let progress = step_index as f64 / (total_items.max(1) as f64);
        nb -= progress * 5.0;
        // If item is huge relative to capacity, new bin keeps big chunks usable
        if (item_size as f64) / cap > 0.5 {
            nb -= 10.0;
        }
        score = nb;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    // A residual gap is "dead" if it is smaller than the minimum plausible item (1)
    // or too small to be useful relative to the mean residual.
    let dead_threshold = (mean_residual * 0.25).max(4.0);
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += 60.0 * (1.0 - (post_residual as f64) / dead_threshold);
    }

    // Perfect fits are heavily rewarded.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Coupling: reward leaving room for the lookahead item if it fits.
    if next_item_size > 0 {
        if (post_residual as u64) >= next_item_size as u64 {
            score -= 12.0;
        } else if (post_residual as u64) > 0 {
            score += 8.0;
        }
    }

    // Open-bin pressure: penalize placements into bins when many bins are open,
    // unless this is the last fitting bin (avoid opening a new bin unnecessarily).
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 / (1.0 + progress * 10.0);
    if fitting_bins_count > 1 {
        score += pressure * 0.8;
    } else {
        score -= 25.0; // last-chance bin: strongly favor using it
    }

    // New-bin candidate: mild penalty so it's chosen only when open bins are bad.
    if bin_residual == bin_capacity {
        score += 18.0 + pressure * 1.5;
    } else {
        // Reward tight fits relative to bin residual (high fill ratio).
        let fill = item_size as f64 / bin_residual.max(1) as f64;
        score -= 10.0 * fill;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
