        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when no good existing fit exists.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let global_pressure = mean_residual / bin_capacity as f64;
        // Open a new bin when open bins are fragmented (low mean residual) or few bins fit.
        let open_bonus = 10.0 * (1.0 - global_pressure) + 6.0 * (fitting_bins_count as f64).recip();
        score += 40.0 - open_bonus - 10.0 * progress;
    } else {
        // Mild reward for consolidating into bins with low residual (reduce bin count).
        score -= 2.0 * (1.0 - bin_residual as f64 / bin_capacity as f64);
    }

    // Time horizon: late in the stream, be more aggressive about filling existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 6.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Slight penalty for proliferating open bins when many alternatives exist.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;

    // Base: prefer small post_residual (tight fit)
    let mut score = pr;

    // Smooth polynomial coupling: dead space penalty grows with stream progress
    let norm_pr = pr / cap;
    score += 30.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits super-linearly
    score -= 20.0 * (1.0 - norm_pr).powi(3);

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: bonus if next item fits into resulting residual
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - slack / cap);
    } else if next_item_size > 0 {
        score += 8.0 * progress;
    }

    // Perfect-fill extreme reward
    if post_residual == 0 {
        score -= 50.0;
    }

    // New-bin candidate: penalize opening a new bin, more so early and when alternatives exist
    if bin_residual == bin_capacity {
        let alt_pressure = if fitting_bins_count > 1 { 1.0 } else { 0.0 };
        score += 40.0 + 30.0 * (1.0 - progress) + 20.0 * alt_pressure;
    }

    // Mild dispersion penalty: avoid straying far from mean residual
    score += 3.0 * ((pr - mean_residual) / cap).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongest reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: classify leftover space via integer division
    // into usability buckets. Leftovers in small classes are "dead space".
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Class A: post_residual <= 10 -> nearly perfect, big reward.
    if post_residual <= 10 {
        score -= 60.0 + (10 - post_residual) as f64 * 3.0;
    }
    // Class B: 11..=30 -> moderate leftover, still reusable for small items.
    else if post_residual <= 30 {
        score -= 15.0;
        // penalize if next item can't use it anyway
        if next_item_size > post_residual {
            score += 10.0;
        }
    }
    // Class C: 31..=60 -> half-bin leftover, fine if next item fits.
    else if post_residual <= 60 {
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 20.0; // lookahead chains nicely
        } else {
            score += 8.0;
        }
    }
    // Class D: 61..=99 -> wasteful large leftover, penalize.
    else {
        score += 12.0;
    }

    // Modulo arithmetic: residuals divisible by common item sizes (10/20/25/50)
    // are "harmonic" and likely reusable.
    let pr = post_residual;
    if pr > 0 && (pr % 10 == 0 || pr % 25 == 0) {
        score -= 6.0;
    }
    // Odd primes-ish leftovers are awkward
    if pr > 0 && pr % 10 != 0 && pr % 5 != 0 {
        score += 4.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / cap;
        // Prefer new bin when open bins are fragmented (low mean residual relative
        // to item) or many bins already open.
        let fragmentation = 1.0 - (mean_residual / cap).min(1.0);
        score = 150.0 + fragmentation * 20.0 - pressure * 10.0;
        if fitting_bins_count == 0 {
            score -= 200.0; // must open
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 15.0; // fresh bin good for upcoming large item too
        }
    }

    // Mild preference to fill bins that are already mostly full (tight packing).
    let fill_ratio = 1.0 - bin_residual as f64 / cap;
    score -= fill_ratio * 8.0;

    // Stream progression: early on, be conservative (keep bins balanced);
    // late in stream, squeeze hard.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 5.0;

    // Penalize creating residual far from mean (keeps bin profile uniform early).
    let dev = (post - mean_residual).abs();
    if progress < 0.5 {
        score += dev * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: penalize creating more bins when many are open.
    if bin_residual == bin_capacity {
        score += 10.0 + 3.0 * open_bins_count as f64;
    }

    // Prefer bins with below-mean residual (tighter bins).
    if bin_residual < bin_capacity {
        score += (mean_residual - bin_residual as f64) * 0.3;
    }

    // Early stream: be more conservative about dead space.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.2 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post-residual can host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
