        }
    } else if next_item_size > 0 {
        // Penalize leaving a residual that the next item cannot use
        score += 15.0;
    }

    // Compare post_residual against mean residual: prefer tighter-than-average outcomes
    score -= 0.6 * (mean_residual - post_residual as f64);

    // Penalize large dead space relative to smallest plausible item (1..100 interface)
    if post_residual > 0 && post_residual < 10 {
        score += 20.0; // nearly useless sliver
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: keep it neutral-ish; only attractive when no good fit exists
    if bin_residual == bin_capacity {
        score += 35.0;
        if next_item_size > 0 && item_size >= 60 {
            score -= 20.0; // big items start fresh bins
        }
    }

    // Late in stream: consolidate, avoid opening bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 45.0 * tightness * tightness;

    // Penalize creating dead space that cannot hold the next item.
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            score += 18.0 + 0.35 * (next_item_size - post_residual) as f64;
        } else if post_residual >= next_item_size {
            score -= 10.0; // future item still fits here
        }
    } else {
        // Last item: just minimize waste.
        score -= 12.0 * tightness;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }
    // Many alternatives: mildly discourage spreading across many bins.
    if fitting_bins_count > 1 {
        score += 2.5 * (fitting_bins_count as f64).ln();
    }

    // Prefer bins with residual close to the item (exact-ish fit).
    score += 0.15 * (bin_residual as f64 - item_size as f64).abs();

    // Global state coupling: when mean residual is high, prefer filling bins well.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 0.25 * mean_residual * (0.4 + 0.6 * progress);

    // New-bin candidate: neutral baseline, penalized more when decent fits exist
    // or late in the stream (avoid bin proliferation).
    if bin_residual == bin_capacity {
        score = 55.0
            + 6.0 * (open_bins_count as f64)
            + 40.0 * progress
            + 0.2 * mean_residual;
        if fitting_bins_count <= 2 {
            score -= 70.0; // poor existing options -> allow new bin
        }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 15.0; // room to pair next item in fresh bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr_norm = pr / cap;

    // Base: penalize residual, smoothed by a non-linear polynomial coupling
    // with stream progress. Late in the stream, leftover space is more costly.
    let mut score = pr * (1.0 + 0.8 * progress * progress) + 12.0 * pr_norm * pr_norm;

    // Perfect fit reward via smooth quadratic trough around pr = 0
    score -= 15.0 * (1.0 - pr_norm) * (1.0 - pr_norm) * (1.0 - pr_norm);

    // Lookahead coupling: reward bins whose post-residual matches next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let diff = (pr - nx) / cap;
        score -= 20.0 * (-diff * diff * 400.0).exp();
        // penalize if next item cannot fit in post-residual
        if nx > pr {
            score += 6.0 * (nx - pr) as f64 / cap;
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: mildly penalize opening new bins early,
    // more strongly late when open bins exist
    if bin_residual == bin_capacity {
        score += 5.0 + 20.0 * progress + 2.0 * open_bins_count as f64;
    } else {
        // favor filling bins with large residual relative to mean residual
        score -= 3.0 * (bin_residual as f64 - mean_residual) / cap;
    }

    // Mild congestion term: with many open bins, prefer tighter fits
    score += 0.15 * open_bins_count as f64 * pr_norm;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tightness reward: quadratic bonus for small post_residual.
    let tight = 1.0 - (post_residual as f64) / cap;
    score -= 18.0 * tight * tight;

    // Harmonic class: post_residual divisible by common item sizes (10/20/25/50) is reusable.
    let pr = post_residual;
    if pr > 0 {
        let mut reuse_bonus = 0.0;
        if pr % 10 == 0 { reuse_bonus += 4.0; }
        if pr % 20 == 0 { reuse_bonus += 3.0; }
        if pr % 25 == 0 { reuse_bonus += 2.5; }
        if pr % 50 == 0 { reuse_bonus += 3.0; }
        // Perfect fit is king.
        if pr == 0 { reuse_bonus += 40.0; }
        score -= reuse_bonus;
    }

    // Lookahead coupling: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size <= pr {
            let fit_frac = next_item_size as f64 / pr as f64;
            score -= 10.0 * fit_frac;
        } else {
            // Next item cannot use this residual: penalize large leftover.
            score += 0.15 * (pr as f64 - cap * 0.5).abs();
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless current bins are nearly full
    // and the item fits poorly everywhere.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = mean_residual / cap;
        let mut nb = 8.0 + 10.0 * (1.0 - progress);
        // If this bin is the only fitting bin and it's tight, opening is bad.
        if fitting_bins_count <= 1 { nb += 25.0; }
        // If mean residual is small (bins nearly full), opening is acceptable.
        nb -= 15.0 * (1.0 - pressure.min(1.0));
        // Large items prefer fresh bins less often when a decent fit exists.
        if item_size as f64 > 0.6 * cap && fitting_bins_count > 0 {
            nb += 5.0;
        }
        score += nb;
    }

    // Mild penalty for leaving residuals in the awkward 1..10 dead zone.
    if pr > 0 && pr < 10 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

