pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong 2-step lookahead: reward when next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chain: this bin becomes exactly full after next item
        } else if next_item_size < post_residual {
            // reward tight fits for the next item too
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot fit here; penalize leaving large dead space
            score += 0.35 * (next_item_size - post_residual) as f64;
        }
    } else {
        // last item of stream: minimize wasted residual aggressively
        score += 0.5 * post_residual as f64;
    }

    // Penalize residual that is too small to ever be useful (dead space),
    // assuming minimum item size ~1 but weighting small unusable slacks.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        score += 8.0; // dead space penalty: nothing planned fits afterwards
    }

    // Relative-to-mean coupling: prefer bins with below-average residual
    // (fill fuller bins first, keep spacious bins for large future items).
    score += 0.6 * (mean_residual - bin_residual as f64).max(0.0);
    score -= 0.2 * (bin_residual as f64 - mean_residual).max(0.0);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new empty bin is only attractive
    // early in the stream or when no open bin offers a good fit.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // base cost of a fresh bin grows with progress (bins are expensive later)
        score += 20.0 + 40.0 * progress;
        // but a fresh bin is great if the next item is large and nothing fits well
        if next_item_size > 0 && next_item_size > bin_residual - item_size {
            score -= 15.0;
        }
        if fitting_bins_count == 0 {
            score -= 45.0; // no open bin fits: new bin is mandatory anyway
        }
    }

    // Mild preference for keeping the number of open bins low.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins whose residual is barely consumed.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
