        // If no existing bin fits well, opening a fresh bin is fine.
        if fitting_bins_count == 0 {
            score -= 10.0;
        }
    }

    // Mild global balancing: prefer bins with residual close to mean residual
    // to keep open bins homogeneous.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

