    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Slight penalty for spreading across many bins relative to mean residual
    score += 0.05 * (open_bins_count as f64) * (mean_residual - pr).abs() / cap;

    // Reward large fills of the current bin
    score -= 0.3 * (item_size as f64 / cap) * (1.0 + progress);

    // New-bin candidate: neutral-ish score so it wins only when fits are poor
    if bin_residual == bin_capacity {
        score = 55.0 + 25.0 * progress - 6.0 * (fitting_bins_count as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
