    // Dead-space classes: very small residuals are nearly unusable
    if pr == 0 {
        score -= 60.0; // perfect fit
    } else if pr < 10 {
        score += 40.0; // dead space penalty
    } else if pr < 20 {
        score += 12.0;
    } else if pr < 35 {
        score += 4.0;
    }

    // Modulo coupling: residual classes that align with common item sizes (10..80 multiples)
    let usable = (pr >= 10) as i32 as f64;
    score -= usable * 8.0;

    // Lookahead: can next item also fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 25.0 * (next_item_size as f64 / cap_f);
            // harmonic bonus if next item exactly fills to a class boundary
            let np = pr - next_item_size;
            if np < 10 { score -= 10.0; }
        } else {
            score += 6.0;
        }
    }

    // Last-chance bin: strongly reward using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current residuals are poor
    if bin_residual == bin_capacity {
        let mean_frac = mean_residual / cap_f;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = mean_frac * (open_bins_count as f64).sqrt();
        score += 35.0 + 40.0 * pressure - 20.0 * progress;
        // small items keep new-bin attractive early
        if item_size < 20 { score -= 15.0; }
    }

    // Fit tightness: reward snug fits relative to item size
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * tightness;

    // Mild preference to consolidate when many bins are open
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Medium dead space: quadratic penalty scaled by how far below a useful
    // item size (10..80) the gap falls.
    if post_residual > 0 && post_residual < 30 {
        let gap = post_residual as f64;
        score += (30.0 - gap) * (30.0 - gap) * 0.15;
    }

    // Reward tight fits (low post_residual relative to item size).
    let tightness = post_residual as f64 / (item_size.max(1) as f64);
    score -= 40.0 / (1.0 + tightness * 10.0);

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Open-bin pressure: penalize placements in bins when many bins are open,
    // discouraging spreading; but reward using existing bins when few open.
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad
    // or no bins fit well.
    if bin_residual == bin_capacity {
        score += 35.0;
        // If lookahead item could combine with the residual left here, opening
        // a fresh bin is less attractive.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0;
        }
        // Fewer open bins -> cheaper to open a new one.
        if open_bins_count <= 2 {
            score -= 15.0;
        }
    }

    // Lookahead synergy: if the residual after placement matches next item,
    // reward strongly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 45.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }

    // Stream progression: later in stream, prefer consolidating into open bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 12.0;

    // Mean residual coupling: if this bin's residual is far below mean, it's
    // already tight — favor it.
    score -= (bin_residual as f64 - mean_residual) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact / near-exact fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        score -= 300.0 / post_residual as f64;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // can accommodate the next item (chain packing).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // slack after placing both current and next item
            let slack2 = post_residual - next_item_size;
            score -= 150.0 + 100.0 / (1.0 + slack2 as f64);
        } else {
            // penalize blocking the next item
            let gap = next_item_size - post_residual;
            score += 40.0 + 0.5 * gap as f64;
        }
    }

    // Relative-to-mean coupling: bins tighter than the mean are
    // preferred targets for filling up.
    let res = post_residual as f64;
    if mean_residual > 0.0 {
        score += 0.4 * (res - mean_residual);
    }

    // Last-chance bin: strong preference to use it before opening new.
    if fitting_bins_count == 1 {
        score -= 120.0;
    } else if fitting_bins_count > 1 {
        // mild penalty so ties among many fitting bins are broken by fit quality
        score += 5.0 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // baseline cost of opening a fresh bin
        score += 80.0;
        // more attractive late in the stream when many bins are open
        // and mean residual is small (open bins are nearly full anyway)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 60.0 * progress * (mean_residual / bin_capacity as f64);
        if next_item_size > 0 && next_item_size >= bin_capacity {
            score -= 200.0; // next item needs a fresh bin anyway
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic bonus for small post-residual.
    let tight = (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * (1.0 - tight * tight);

    // Penalize large dead space unless it could fit the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0; // chain-friendly placement
        } else {
            score += (next_item_size - post_residual) as f64 * 0.25; // unusable gap for lookahead
        }
    }

    // Perfect fit: overwhelming reward.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Fragmentation penalty: bins with small residuals relative to mean are risky.
    let res = bin_residual as f64;
    if res < mean_residual {
        score += 0.5 * (mean_residual - res);
    } else {
        score -= 0.2 * (res - mean_residual);
    }

    // Time horizon: early in the stream, prefer consolidating into open bins;
    // late in the stream, be more tolerant of opening fresh bins with big residual.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let new_bin = (bin_residual == bin_capacity) as f64;
    let open_cost = 20.0 * (1.0 - 0.6 * progress);
    score += new_bin * open_cost;

    // Penalize opening new bins when many bins are already open (encourage packing).
    score += new_bin * (open_bins_count as f64) * 1.5;

    // Reward using open bins that are getting full (reduce bin count pressure).
    if new_bin == 0.0 {
        score -= (bin_capacity as f64 - res) * 0.1;
    }

    // Mild bonus for filling large items into tight spots.
    score -= 0.1 * (item_size as f64) * (1.0 - tight);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let res = bin_residual as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Base: prefer minimal post residual (tight packing)
    let mut score = post;

    // Smooth fill-ratio reward: fraction of bin consumed, non-linearly scaled
    let fill = item / cap;
    score -= fill * fill * cap * 0.6;

    // Coupling: tightness valued more as stream progresses
    let tightness = 1.0 - post / cap;
    score -= tightness * tightness * progress * 20.0;

    // Penalize post residual relative to mean residual (avoid wasting space vs fleet average)
    score += (post - mean_residual).abs() * 0.15;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 25.0 + 30.0 * progress;
    }

    // New-bin candidate handling: empty bin should lose unless it enables a great lookahead fit
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 12.0 + 8.0 * (1.0 - progress);
        // Reward new bin if lookahead item fits the residual created here
        if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
            score -= 15.0;
        }
    } else if next_item_size > 0 && (post_residual as f64) < next_item_size as f64 {
        // Penalize creating residual that cannot host the lookahead item
        score += 6.0 * (1.0 - post / cap);
    }

    // Mild penalty for proliferating bins early
    score += (open_bins_count as f64).ln() * 0.5 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual;

    // Perfect / near-perfect fits are gold: crush their score.
    if pr == 0 {
        score -= 1000.0;
    } else if pr <= 5 {
        score -= 60.0;
    } else if pr <= 10 {
        score -= 25.0;
    }

    // Harmonic class logic: residuals aligned to multiples of 10 (and 5)
    // are more likely reusable by future items drawn from typical streams.
    let cls = (pr % 10) as f64;
    score -= (10.0 - cls) * 2.0;              // class 0 best, class 9 worst
    if pr % 5 == 0 && pr > 0 {
        score -= 6.0;                          // secondary harmonic alignment
    }
    // Integer-division dead-space threshold: residuals in awkward
    // mid-classes (3..7) after large items are likely dead space.
    let half = pr / 2;
    if half >= 3 && half <= 7 && pr > 10 {
        score += 8.0;
    }

    // Lookahead (k=2): reward bins that can also host the next item,
    // especially when the pair (item, next) nearly saturates the bin.
    if next_item_size > 0 {
        if (next_item_size as u64) <= pr as u64 {
            score -= 15.0;
            score -= next_item_size as f64 * 0.1;
            let pair = item_size as u64 + next_item_size as u64;
            if pair as f64 >= cap * 0.9 {
                score -= 20.0;                 // near-perfect two-item packing
            }
        } else {
            score += (next_item_size - pr) as f64 * 0.3; // next item won't fit: dead end risk
        }
    }

    // Last chance before opening a new bin: strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive for large items where open bins
    // would fragment badly; otherwise keep it clearly worse than decent fits.
    if bin_residual == bin_capacity {
        score = cap - item_size as f64 + 10.0;
        if item_size >= 60 {
            score -= 15.0;
        }
        if item_size >= 80 {
            score -= 10.0;
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 8.0;                      // big items arriving in pairs
        }
    }

    // Stream progression: late in the stream, consolidation matters more,
    // so penalize leaving large unused fractions in chosen bins.
    let prog = step_index as f64 / (total_items.max(1) as f64);
    score -= prog * 6.0 * (1.0 - pr as f64 / cap);

    // Slight pull toward the mean residual: avoid extreme outliers
    // when many bins are open (fragmentation control).
    score += ((pr as f64 - mean_residual) / cap).abs() * 3.0 * (open_bins_count.min(20) as f64 / 20.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 20 {
        score += (20.0 - post_residual as f64) * 4.0;
    }
    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward bins whose residual is close to item size (tight packing).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += tightness * 10.0;

    // Open-bin pressure: discourage scattering across many bins.
    score += open_bins_count as f64 * 0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when the item is large relative to
    // remaining space or the fit is poor; otherwise penalize opening new bins.
    if bin_residual == bin_capacity {
        let poor_fit = (bin_capacity - item_size) as f64;
        score += 25.0 + poor_fit * 0.3;
        if fitting_bins_count > 0 {
            score += 10.0;
        }
        // Late in the stream, opening new bins is less costly.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 15.0;
    }

    // Lookahead: if the next item would fit the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for a perfect 2-step match: post_residual equals next item size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 25.0 * (1.0 - diff / (bin_capacity as f64));
        // Slight extra bonus for exact match
        if post_residual == next_item_size {
            score -= 15.0;
        }
        // Penalize leaving residual just below next item (dead space for lookahead)
        if post_residual < next_item_size {
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Compare against mean residual: bins already tight are preferable targets.
    score -= 0.8 * (mean_residual - post_residual as f64);

    // Penalize very small unusable residuals (< 10, min item size) heavily.
    if post_residual < 10 {
        score += 40.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when it's genuinely needed
    // (no open bin fits, or this bin is the only fitting one but poor fit).
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 30.0 };
        score += pressure + 0.3 * open_bins_count as f64;
        // Late in the stream, prefer consolidating rather than opening bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post residual).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 8.0 * tightness * tightness;

    // Penalize dead space that is too small for a typical future item.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bonus: if this is the only bin that fits, prefer it strongly.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Lookahead: reward leaving space for the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 4.0;
        } else {
            score += 3.0;
        }
    }

    // New-bin candidate handling: penalize opening a new bin unless the fit
    // into open bins is poor or this is a large item.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 10.0;
        if item_size > 50 {
            score -= 6.0; // large items fine in fresh bins
        }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 4.0; // pairable items benefit from a fresh bin
        }
    } else {
        // Slight preference for using already-open bins as they accumulate.
        score -= (open_bins_count.min(20) as f64) * 0.3;
    }

    // Time-horizon modulation: early in the stream, be conservative with new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress < 0.2 && is_new_bin {
        score += 8.0;
    }

    // Global state: if mean residual is high, prefer filling existing bins.
    if mean_residual > (bin_capacity as f64) * 0.4 && !is_new_bin {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    let fit = item_size as f64 / cap;

    // Base: quadratic penalty on wasted space, weighted by stream progress
    let mut score = pr_norm * pr_norm * (1.0 + progress);

    // Smooth polynomial coupling: small post-residuals are valuable early, dead space late
    let coupling = (1.0 - pr_norm) * (1.0 - pr_norm) * pr_norm;
    score += coupling * (0.8 + 0.6 * progress) * (1.0 - fit);

    // Reward tight fits
    score -= (1.0 - pr_norm) * (1.0 - fit) * 0.5;

    // Last-chance bonus
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 1.5;
    }

    // Lookahead: penalize if next item can't use the post-residual
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx > pr {
            score += (nx - pr) / cap * (0.5 + progress);
        } else {
            score -= (pr - nx) / cap * 0.3;
        }
    }

    // Mild penalty for spreading across many bins
    score += (open_bins_count as f64 / (total_items as f64).max(1.0)) * 0.1;

    // New-bin candidate: neutral-ish baseline with progress-dependent reluctance
    if bin_residual == bin_capacity {
        score += 0.6 + 0.8 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "useful"
    // residue classes (multiples of common item sizes) are rewarded.
    let pr = post_residual;
    if pr > 0 {
        // reward if post_residual can host typical next items (divisibility classes)
        if pr % 10 == 0 {
            score -= 6.0; // clean harmonic slot
        }
        if pr % 25 == 0 {
            score -= 3.0;
        }
        if pr % 20 == 0 {
            score -= 2.0;
        }
        // penalize awkward dead space in the 1..10 band
        if pr < 10 {
            score += 8.0 * (10 - pr) as f64;
        }
        // mid-range leftovers 30..60 are still reusable: mild reward
        if pr >= 30 && pr <= 60 {
            score -= 2.0;
        }
    } else {
        score -= 12.0; // perfect closure, strongly favored
    }

    // Integer-division threshold on post_residual vs next_item_size lookahead
    if next_item_size > 0 {
        if pr >= next_item_size {
            // exact-fit chain: post residual exactly matches next item
            if pr == next_item_size {
                score -= 10.0;
            } else {
                score -= 4.0 * (pr / next_item_size.max(1)) as f64;
            }
        } else {
            // next item cannot use this leftover: penalize proportional dead space
            score += 0.05 * (next_item_size - pr) as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when open bins are crowded or fit is bad
    if bin_residual == bin_capacity {
        let crowding = open_bins_count as f64 / (1.0 + step_index as f64 / total_items.max(1) as f64);
        let poor_fit = (post_residual as f64 / bin_capacity as f64) > 0.55 && next_item_size > post_residual;
        score += 20.0 - 8.0 * crowding;
        if poor_fit {
            score -= 25.0;
        }
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    // Waste relative to mean residual: placing into a bin far below mean
    // concentrates small leftovers, which is good.
    if (bin_residual as f64) < mean_residual {
        score -= 1.5;
    } else {
        score += 0.5;
    }

    // Progress coupling: later in stream, prefer tighter packs
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 3.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold even the
    // minimum item are pure waste; penalize them heavily.
    if post_residual < 10 && post_residual > 0 {
        score += 120.0;
    }

    // Post-residual that cannot fit the known next item is a partial dead
    // gap (unless the next item could go elsewhere); add moderate penalty.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // Perfect fit bonus: reward leaving nothing behind.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Open-bin pressure: discourage scattering across many bins when
    // open_bins_count grows relative to stream progress.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = open_bins_count as f64 * (1.0 - progress) * 0.35;
    score += pressure;

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoiding a forced new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when the item is huge relative to
    // typical residuals or the mean residual is badly fragmented.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 25.0;
        // But if this bin's residual would be very tight elsewhere, opening
        // a fresh bin keeps flexibility for the next item.
        if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
            score -= 20.0;
        }
        if mean_residual < item_size as f64 * 1.2 {
            score -= 10.0;
        }
    }

    // Mild reward for tight fits (small post_residual relative to item).
    score -= (item_size as f64) / (bin_residual.max(1) as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-exact fits strongly.
    let tight = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tight * tight;

    // Penalize dead space that is too small to ever be useful (< 10).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 / (1.0 + slack);
        } else {
            // Next item won't fit here; mild penalty scaled by leftover gap.
            let gap = (next_item_size - post_residual) as f64;
            score += 4.0 * gap / (bin_capacity as f64);
        }
    }

    // Relative to mean residual: prefer bins that keep residual near the mean.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Discourage opening new bins when reasonable open bins exist.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 + 8.0 * (1.0 - progress);
        if next_item_size > 0 && next_item_size <= bin_residual {
            score += 5.0; // an open bin could also host the next item
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress of the stream (0..1), used to anneal lookahead aggressiveness.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tight fit reward: quadratic bonus for small post_residual.
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 8.0 * waste_frac * waste_frac * (item_size as f64);

    // Lookahead: penalize bins whose post-residual cannot host the next item
    // (dead space), reward bins that remain useful for the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // The bin stays useful: reward proportional to leftover usefulness.
            score -= 3.0 * (next_item_size as f64) * (1.0 - 0.5 * progress);
        } else {
            // Dead space created relative to the next item's need.
            let dead = (next_item_size - post_residual) as f64;
            score += 1.5 * dead * (0.5 + progress);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 6.0;
    }

    // Fragmentation penalty: bins whose residual is very small after placement
    // are fine, but bins left with tiny unusable slivers are penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 5.0;
    }

    // Prefer bins that are already below-average residual (consolidate waste
    // into few bins, keep large-residual bins flexible).
    score += 0.4 * (mean_residual - bin_residual as f64);

    // Many open bins: encourage filling existing bins rather than spreading.
    score += 0.05 * open_bins_count as f64 * waste_frac;

    // New-bin candidate handling: an empty bin gets a neutral baseline that
    // only wins when every open bin would create bad fits (high waste or
    // dead space for the lookahead item).
    if bin_residual == bin_capacity {
        // Baseline: moderate score; opening a new bin is justified when the
        // computed score here undercuts all poor-fit alternatives.
        score = (bin_capacity - item_size) as f64 * 0.75;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 2.0;
        }
        // Late in the stream, slightly discourage opening new bins.
        score += 4.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: quadratic penalty on wasted space
    let mut score = pr * pr / cap;

    // Smooth polynomial coupling of waste with stream progress:
    // early on, waste is cheap; late in the stream it becomes costly.
    let progress_coupling = 1.0 + 2.0 * progress * progress;
    score *= progress_coupling;

    // Cubic interaction: penalize medium dead space (unusable for small items)
    // more than very tight or very loose fits, weighted by progress.
    let tightness = 1.0 - (pr / cap);
    score += 12.0 * tightness * tightness * tightness * (0.5 + progress);

    // Reward tight fits (small post_residual) more strongly as stream advances.
    score -= (1.0 - pr / cap) * (10.0 + 30.0 * progress);

    // Lookahead: if next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let gap = (pr - ns).abs();
        let fit_quality = 1.0 - gap / cap;
        if fit_quality > 0.0 {
            score -= 20.0 * fit_quality * fit_quality;
        } else {
            // next item cannot use this residual: penalize waste mildly
            score += 5.0 * (pr / cap);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Prefer bins with residuals below the mean (consolidate large gaps elsewhere).
    score += 0.15 * ((bin_residual as f64) - mean_residual);

    // Mild penalty for opening a new bin when many bins are already open and
    // stream is late (encourage closing out existing bins).
    let new_bin = (bin_residual as f64 - cap).abs() < 1e-9;
    if new_bin {
        score += 3.0 + 10.0 * progress * (open_bins_count as f64).sqrt();
    } else {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo 10 define "usability classes".
    let r = post_residual % 10;
    // Residue 0 => perfect harmonic slot; residue 1..=9 => partial; large residue => dead space risk.
    match r {
        0 => score -= 18.0,               // perfectly harmonic leftover
        1 | 2 => score -= 6.0,           // nearly harmonic
        3 | 4 | 5 | 6 | 7 => score += 4.0, // awkward mid-class dead space
        _ => score -= 2.0,               // 8..9 still moderately usable
    }

    // Integer-division thresholds: classify post_residual into capacity eighths.
    let eighth = bin_capacity / 8;
    if post_residual < eighth {
        score += 22.0; // tiny unusable sliver -> strong penalty
    } else if post_residual < 2 * eighth {
        score += 8.0;
    } else if post_residual < 4 * eighth {
        score -= 5.0; // sweet spot: half-ish remaining
    }

    // Exact fit reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead harmonic coupling: can next item fit into post_residual exactly or well?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0; // perfect chain fit
        } else if next_item_size < post_residual {
            let chain_res = (post_residual - next_item_size) % 10;
            if chain_res == 0 {
                score -= 14.0;
            }
            score -= 3.0; // next item fits, mild reward
        } else {
            score += 6.0; // next item won't fit here
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: keep it attractive only when current bin would leave bad residue
    // or open bins are already fragmented.
    if bin_residual == bin_capacity {
        let bad_fit = post_residual > 0 && post_residual < 15;
        let crowded = open_bins_count as f64 > 6.0 + mean_residual / 10.0;
        if bad_fit && !crowded {
            score -= 30.0;
        } else {
            score += 15.0;
        }
    }

    // Mean-residual coupling: penalize bins far above mean (fragmentation signal).
    score += ((bin_residual as f64) - mean_residual).abs() * 0.15;

    // Late-stream tightness: as stream progresses, prefer filling bins tighter.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * (bin_capacity - post_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable small gaps are heavily penalized.
    // A post_residual that no plausible item (>= 1) can exploit well is dead space.
    if post_residual > 0 {
        // Small gaps (< 20) are nearly unusable for typical items.
        if post_residual < 20 {
            score += (20.0 - post_residual as f64) * 3.0;
        } else if post_residual < 35 {
            score += (35.0 - post_residual as f64) * 1.2;
        }
        // Perfect or near-perfect fits are strongly rewarded.
        if post_residual == 0 {
            score -= 40.0;
        } else if post_residual <= 5 {
            score -= 20.0;
        }
    } else {
        score -= 40.0;
    }

    // Last-chance pressure: if this is the only bin that fits, prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor filling.
    score += open_bins_count as f64 * 0.8;

    // New-bin candidate handling: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Prefer reusing an open bin unless the fit there is terrible.
        // Penalize opening a new bin, more so when many bins are already open.
        score += 45.0 + open_bins_count as f64 * 0.5;
        // But if the current item would leave a terrible fit in every open bin,
        // the penalty is calibrated so a new bin can still win.
        // Lookahead: if next item is large and this item is small, new bin
        // preserves flexibility for the big item.
        if next_item_size > 60 && item_size < 30 {
            score -= 30.0;
        }
    }

    // Lookahead: reward placements that leave room for the next item.
    if next_item_size > 0 {
        if post_residual as f64 >= next_item_size as f64 {
            score -= 8.0;
        } else {
            // Leaving a gap just below the next item's size is wasted space.
            let waste = next_item_size as f64 - post_residual as f64;
            if waste < 15.0 {
                score += waste * 1.5;
            }
        }
    }

    // Mild alignment with mean residual: bins already fragmented get a nudge
    // toward being used (their residual is small anyway), keeping score
    // consistent with residual-based ranking.
    score -= (mean_residual - post_residual as f64) * 0.1;

    // Stream progression: late in the stream, consolidate aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 5.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near match: small gap between post_residual and next item.
    else if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        if gap <= 10.0 {
            score -= 40.0 - gap * 2.5;
        } else if post_residual < next_item_size {
            // Next item can't follow here; dead space penalty scaled by wasted chunk.
            score += (next_item_size - post_residual) as f64 * 0.6;
        }
    }

    // Reward tight packing relative to mean residual of open bins.
    if (post_residual as f64) < mean_residual {
        score -= (mean_residual - post_residual as f64) * 0.3;
    } else {
        score += (post_residual as f64 - mean_residual) * 0.15;
    }

    // Last chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize leaving tiny unusable slivers (< 10, min item size).
    if post_residual > 0 && post_residual < 10 {
        score += 35.0;
    }

    // Slight bias toward fuller bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (bin_capacity - bin_residual) as f64 * 0.1 * (0.5 + progress);

    // Mild preference for reusing existing bins over opening new ones.
    if bin_residual == bin_capacity {
        score += 8.0 + open_bins_count as f64 * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: normalized fill ratio of this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill * fill;

    // Penalize small dead space that is hard to reuse later
    // (items are >= 1, but very small residuals like 1..=9 are near-dead).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual,
    // strongly reward this bin; if next item can't fit anywhere else
    // but fits here, also reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            // Next item won't fit here; slight penalty for blocking
            // a bin that could have stayed more flexible.
            score += 4.0;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // New-bin candidate handling: an empty bin has large post_residual,
    // so the base score already penalizes it; add a mild extra penalty
    // unless the item is huge (better to give big items fresh bins).
    if bin_residual == bin_capacity {
        if item_size >= bin_capacity / 2 {
            score -= 10.0;
        } else {
            score += 12.0;
        }
    }

    // Global state: when many bins are open with slack, prefer
    // consolidating into bins with above-average residual.
    if open_bins_count > 1 {
        let avg = mean_residual;
        let this = bin_residual as f64;
        if this < avg {
            score -= 5.0; // below-average residual bin: use it up
        } else {
            score += 3.0 * (this - avg) / bin_capacity as f64;
        }
    }

    // Time horizon: early in the stream, be slightly more willing to
    // open new bins (long future to fill them); late, prefer packing tight.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 10.0 * (1.0 - progress);
    } else {
        score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early: prefer tight fills (low post_residual). Late: dead space is less costly,
    // so the quadratic penalty on post-residual fades smoothly with progress.
    let decay = (1.0 - progress) * (1.0 - progress);
    score += decay * 40.0 * norm_pr * norm_pr;
    score -= decay * 10.0 * norm_pr;

    // Cubic interaction: large post-residual late in stream is fine, early is bad.
    score += (1.0 - progress).powi(3) * 25.0 * norm_pr * norm_pr * norm_pr;

    // Penalize wasting a scarce fitting bin (last chance) — smooth reward instead.
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 - norm_pr);
    }

    // Prefer bins whose residual deviates from the mean (consolidate slack):
    let dev = (pr - mean_residual) / cap;
    score += 8.0 * dev * dev - 5.0 * dev;

    // Lookahead: reward leaving space that fits the next item, smoothly.
    if next_item_size > 0 {
        let fits_next = (next_item_size as f64 <= pr) as i32 as f64;
        let tight = 1.0 - ((pr - next_item_size as f64).abs() / cap);
        score -= 12.0 * fits_next * tight * tight;
    }

    // Slight preference for keeping the number of open bins low early on.
    score += progress * open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals in "usable" classes
    // (multiples of 10 or small enough to be filled by common items).
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit
    } else {
        let class = pr % 10;
        if class == 0 {
            score -= 25.0; // harmonic decade class: highly reusable
        } else if class <= 2 {
            score -= 8.0;
        } else if class >= 8 {
            score -= 5.0;
        } else {
            score += (5 - class) as f64 * 4.0; // mid-classes are dead-space prone
        }
    }

    // Integer-division threshold: residual that can host the lookahead item is gold.
    if next_item_size > 0 {
        if pr >= next_item_size {
            score -= 18.0 + (pr - next_item_size) as f64 * 0.3;
        } else {
            score += (next_item_size - pr) as f64 * 0.5;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening fresh bins unless current bin would waste a lot.
    if bin_residual == bin_capacity {
        score += 55.0;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score += 15.0; // could have paired items instead
        }
    }

    // Fraction of capacity consumed by this placement (coupling with stream progress).
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= fill_frac * 20.0 * (1.0 + step_index as f64 / (total_items.max(1) as f64));

    // Prefer bins tighter than the mean residual (best-fit flavor with harmonic twist).
    score += ((mean_residual - bin_residual as f64) * 0.4).max(-20.0).min(20.0);

    // Penalize scattering across too many open bins.
    score += open_bins_count as f64 * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small to hold the smallest
    // plausible item are pure waste; penalize them super-linearly.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item {
        score += 1000.0;
    }
    // Tight fits are excellent: reward near-zero post_residual.
    if post_residual == 0 {
        score -= 50.0;
    } else {
        // Penalize gaps that cannot fit the lookahead item either
        // (double-dead space), but only mildly if lookahead is 0 (end).
        if next_item_size > 0 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
        // Reward small gaps that still fit the next item (good chaining).
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 5.0;
        }
    }

    // Last-chance pressure: if this is the only fitting bin, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading;
    // with few open bins, opening a new bin is cheaper.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let bin_pressure = (open_bins_count as f64).ln().max(0.0);
    score += bin_pressure * 2.0 * (0.5 + progress);

    // New-bin candidate: make it moderately unattractive so it only wins
    // when existing bins have terrible fits (large residuals elsewhere).
    if bin_residual == bin_capacity {
        score += 25.0;
        // Late in the stream, consolidation matters more.
        score += 10.0 * progress;
    } else {
        // Reward using bins that are already partially filled relative
        // to the mean residual (compactness pressure).
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
    }

    // Mild preference for larger items into larger residuals (avoid
    // stranding big residual spaces).
    score -= (item_size as f64 / bin_capacity as f64) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect or near-perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 10 {
        score -= 500.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches next_item_size exactly
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        if gap == 0.0 {
            score -= 400.0;
        } else if gap < 10.0 {
            score -= 200.0 - gap * 15.0;
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // post_residual can't fit next item: penalize small dead space that blocks lookahead
        if post_residual < next_item_size && post_residual > 0 {
            score += (next_item_size - post_residual) as f64 * 2.0;
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Penalize opening a new bin when decent open bins exist, unless item is huge
    if bin_residual == bin_capacity {
        let pressure = if next_item_size > 0 { (item_size as f64 + next_item_size as f64) / 2.0 } else { item_size as f64 };
        if fitting_bins_count > 0 {
            score += 80.0 - pressure * 0.5;
        }
        // pair-fill bonus: new bin fits item plus lookahead comfortably
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 60.0;
        }
    }

    // Late in stream: tighten more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_residual - post_residual) as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but only if it isn't
    // a "dead space" sliver that nothing else will ever use.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Lookahead: if the next item fits exactly in the post residual,
    // strongly reward this placement (perfect chaining).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            // room for next item: mild reward proportional to leftover slack
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / (bin_capacity as f64));
        } else {
            // next item won't fit here; penalize proportionally to how
            // much of the residual becomes stranded relative to next item
            let stranded = (next_item_size - post_residual) as f64;
            score += 0.15 * stranded;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Prefer fuller bins overall: compare residual to mean residual.
    score += 0.35 * (bin_residual as f64 - mean_residual);

    // New-bin candidate handling: an empty bin should only win when the
    // current bin fit is poor. Penalize the empty-bin candidate so it is
    // chosen only for large items or when no open bin is decent.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // later in the stream, waste matters more -> harder to open new bins
        score += 20.0 + 25.0 * progress;
        // but if the item is large relative to capacity, new bin is natural
        score -= 0.25 * item_size as f64;
    }

    // Mild penalty for accumulating too many open bins (encourages closing
    // out existing bins rather than spreading items).
    score += 0.05 * open_bins_count as f64;

    // Time-horizon modulation: early in the stream, be more exploratory
    // (slightly flatten differences); late, be greedy on tight fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.1 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with non-linear polynomial shaping
    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * (1.0 - progress) * (1.0 - progress);
    score += 40.0 * poly;

    // Penalize large dead space late in the stream more strongly
    let dead = norm_pr * norm_pr * norm_pr;
    score += 30.0 * dead * (0.5 + progress);

    // Reward tight fits (small post residual) with smooth decay
    score -= 25.0 * (1.0 - norm_pr).powi(3) * (1.0 - progress);

    // Lookahead: reward bins whose post residual fits the next item
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        let fit_quality = 1.0 - ((post_residual as f64 - next_item_size as f64) / cap);
        score -= 20.0 * fit_quality * (0.5 + progress);
    } else if next_item_size > 0 {
        score += 10.0 * progress;
    }

    // Last-chance bin: strong bonus to use it rather than open a new one
    if fitting_bins_count == 1 {
        score -= 35.0 * (1.0 - 0.5 * progress);
    }

    // Slight penalty when many bins are open (encourage consolidation early)
    score += (open_bins_count as f64).ln().max(0.0) * (1.5 * (1.0 - progress));

    // Deviation from mean residual: prefer bins near mean to keep balance
    score += 0.15 * (pr - mean_residual).abs() * (1.0 - progress);

    // New-bin candidate: make empty bins less attractive unless post residual is huge
    if bin_residual == bin_capacity {
        score += 25.0 + 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic dead-space classes on post_residual (capacity = 100 scale)
    if post_residual > 0 && post_residual < 10 {
        // near-perfect fill: tiny unusable sliver is cheap
        score -= 6.0;
    } else if post_residual < 20 {
        // awkward class: wastes space that few item sizes (>=10) can use
        score += 4.0;
    } else if post_residual < 50 {
        // mid class: reusable by many item sizes
        score -= 2.0;
    }

    // Modulo-10 harmonic bonus: residual aligned to item granularity is reusable
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 1.5;
    }

    // Lookahead (k=2): reward bins that can also host the next item
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 4.0;
        } else {
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 {
        score -= 8.0;
    }

    // Crowding: many open bins -> prefer consolidating into tight fits
    if open_bins_count > 4 {
        score += 0.3 * (open_bins_count as f64 - 4.0).min(6.0);
    }

    // New empty bin candidate
    if bin_residual == bin_capacity {
        if open_bins_count == 0 || fitting_bins_count == 0 {
            // no alternative: new bin is fine
            score = 40.0;
        } else {
            // prefer existing bins unless they score terribly (dead-space classes push > 105)
            score = bin_capacity as f64 + 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (1.0 - post_residual as f64 / 10.0);
    }
    if post_residual > 0 && post_residual < item_size as f64 {
        // gap smaller than any plausible future item (items >= 1, but penalize
        // gaps well below typical sizes) — dead space penalty scaled by progress
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * (1.0 - progress) * (1.0 - post_residual as f64 / item_size as f64);
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Open-bins pressure: discourage spreading across many bins;
    // encourage reusing existing bins when several fit.
    score += 2.0 * open_bins_count as f64;
    if fitting_bins_count > 1 {
        score -= 6.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: empty bin gets a baseline opening cost,
    // but is attractive if next item would pair well with the fresh residual
    // or if all existing fits are poor (large post_residual).
    if bin_residual == bin_capacity {
        score += 30.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 25.0;
        }
        // If the item leaves a big hole in any existing bin, opening fresh is fine.
        if post_residual <= 10 {
            score -= 40.0;
        }
    } else {
        // Lookahead: if placing here leaves room exactly for the next item, reward.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 8.0;
        }
        // Penalize blocking: next item can't fit in the resulting gap.
        if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
            score += 10.0;
        }
    }

    // Mild preference for bins tighter than average (better homogeneity).
    score += 0.1 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect lookahead match: strong reward.
        score -= 60.0 * (-diff / 8.0).exp();
        // Bonus if next item fits exactly after placement.
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Penalize post-residuals that are small but useless (< next item and < 10).
        if post_residual < next_item_size && post_residual < 10 {
            score += 15.0;
        }
    } else {
        // Last item: prefer tightest fit.
        score *= 1.5;
    }

    // Penalize creating dead space relative to mean residual of open bins.
    let pr = post_residual as f64;
    if pr < mean_residual - 20.0 {
        score += (mean_residual - pr - 20.0) * 0.3;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New empty bin candidate: penalize mildly, but less when no open bin fits well
    // or lookahead item is large relative to current item.
    if bin_residual == bin_capacity {
        let mut penalty = 30.0;
        if next_item_size > 0 && (next_item_size as f64) > (item_size as f64) * 1.3 {
            penalty -= 15.0; // saving space for a bigger next item
        }
        if post_residual > 60 {
            penalty += 10.0; // wasteful to open a new bin for a small item
        }
        score += penalty;
    }

    // Mild preference for filling fuller bins early in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a nonlinear bonus.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let tight_bonus = (1.0 - post / cap).powi(3) * 40.0;
    score -= tight_bonus;

    // Penalize dead space that is too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward heavily.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 18.0 * (1.0 - slack / cap);
        } else {
            // Next item cannot follow here; penalize proportionally to waste.
            score += 0.15 * (post / cap) * nxt / cap * 20.0;
        }
    } else {
        // Last item: prefer filling existing bins as much as possible.
        score -= 30.0 * (1.0 - post / cap);
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 22.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Time horizon: early in the stream, be more willing to open/spread bins;
    // late in the stream, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 12.0 * progress * (1.0 - post / cap);

    // Penalize bins whose residual deviates far from the mean residual
    // (keeps residual distribution coherent).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Congestion: many open bins -> favor filling existing ones.
    score += 0.3 * open_bins_count as f64 * (post / cap);

    // New-bin candidate handling: an empty bin should only win when no open bin
    // offers a decent fit (e.g., item barely fits or many bins compete).
    if bin_residual == bin_capacity {
        let item_frac = item_size as f64 / cap;
        // Empty bin baseline: moderate score; becomes attractive if item is large
        // (large item wastes less relative space) or if fitting options are scarce.
        score = 55.0 - 30.0 * item_frac + 4.0 * fitting_bins_count as f64;
        if fitting_bins_count == 0 {
            score = -100.0; // no alternative: must open a new bin
        }
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 5.0; // room for the lookahead item too
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: penalize wasted post-residual quadratically (dead space is worse than even spread)
    let mut score = norm_post * norm_post * cap;

    // Non-linear coupling of post-residual with stream progress:
    // early on, prefer tight fits (low post-residual); late, tolerate slack less harshly
    let progress_coupling = (1.0 - progress) * (norm_post * (1.0 - norm_post));
    score += 12.0 * progress_coupling;

    // Smooth quartic smoothness term favoring post_residual near multiples of typical item sizes
    let harmonic = (norm_post * std::f64::consts::PI).sin().abs();
    score += 4.0 * harmonic * (0.5 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly reward using it
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - norm_post);
    }

    // Penalize bins far below mean residual (creates fragmented outliers)
    score += 0.5 * ((post - mean_residual) / cap).abs();

    // Lookahead: reward leaving room for the next item (smooth logistic interaction)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fit_next = if post >= nxt { 1.0 } else { 0.0 };
        let closeness = 1.0 - ((post - nxt).abs() / cap).min(1.0);
        score -= 8.0 * fit_next * closeness * (1.0 - progress);
    } else {
        // Last item: strongly prefer zero post-residual
        score += norm_post * norm_post * cap;
    }

    // Mild penalty for spreading across many open bins
    score += 0.3 * (open_bins_count as f64).ln().max(0.0);

    // New-bin candidate: make it attractive only when item fits poorly in open bins
    if bin_residual == bin_capacity {
        score = cap * (1.0 - (item_size as f64 / cap)) * (1.0 + progress) - 5.0 * (fitting_bins_count as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fits / small residues are golden.
    let pr = post_residual;
    if pr == 0 {
        score -= 40.0; // perfect fill
    } else if pr <= 5 {
        score -= 25.0;
    } else if pr <= 10 {
        score -= 12.0;
    } else if pr <= 20 {
        score -= 5.0;
    }

    // Modulo-10 dead-space class: residues that most item sizes (multiples of 10)
    // cannot use are dead space; residues matching common sizes are reusable.
    let m = pr % 10;
    score -= match m {
        0 => 15.0,
        1..=5 => 6.0,
        6..=9 => 0.0,
        _ => 0.0,
    } as f64;

    // Does the lookahead item fit into the post-residual? Strong reward.
    if next_item_size > 0 {
        if (post_residual as u64) >= (next_item_size as u64) {
            score -= 18.0 + 0.15 * (next_item_size as f64);
            // bonus if next item exactly fills the remainder (harmonic match)
            if post_residual == next_item_size {
                score -= 20.0;
            }
        } else {
            // next item cannot use this bin's remainder: penalize proportional waste
            score += 0.1 * (post_residual as f64);
        }
    }

    // Harmonic pairing: item_size + next_item_size near capacity -> chain reward
    if next_item_size > 0 {
        let pair = item_size as f64 + next_item_size as f64;
        if (pair - cap).abs() <= 2.0 && (bin_residual as f64) >= pair {
            score -= 10.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 22.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when all open bins
    // would leave large, awkward residues and stream is early enough to amortize.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let awkward = if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size { 1.0 } else { 0.0 };
        // fresh bin starts attractive, but gets worse as stream progresses
        score = 30.0 + 55.0 * progress - 25.0 * awkward;
        // if item is large relative to capacity, a fresh bin is reasonable
        if item_size as f64 > 0.7 * cap {
            score -= 20.0;
        }
        if fitting_bins_count == 0 {
            score -= 60.0; // no alternative
        }
    }

    // Mild tie-break: prefer bins below mean residual (concentrate fills).
    score += 0.05 * (mean_residual - bin_residual as f64).max(0.0);

    // Integer-division threshold: penalize residues in (20,35) band — too big to waste,
    // too small for common mid-size items.
    if pr > 20 && pr < 35 {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps.
    // Gaps below the minimum plausible item size (1..100 range, but keep a
    // conservative threshold) are wasted capacity; punish them hard.
    let dead_threshold = 12.0;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 4.0;
    }
    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 25.0;
    }

    // Coupling: dead space hurts more when many bins are open (pressure to consolidate).
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += pressure * 3.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: make it unattractive unless the fit elsewhere is bad.
    if bin_residual == bin_capacity {
        score += 10.0 + pressure * 2.0;
        // If next item is large, a fresh bin may be worthwhile later; slight relief.
        if next_item_size >= 50 {
            score -= 5.0;
        }
    }

    // Lookahead: if the next item fits exactly into the post residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0;
    } else if next_item_size > post_residual && next_item_size > 0 {
        // Next item cannot use the leftover: leftover is likely dead space.
        score += 2.0;
    }

    // Mild drift toward tighter bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 1.5;

    // Prefer bins below mean residual (tighter bins first).
    score += (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect 2-step lookahead match: post_residual exactly fits next item
    if next_item_size > 0 {
        if post_residual as u32 == next_item_size {
            score -= 60.0; // chain two items perfectly
        } else if (post_residual as i64 - next_item_size as i64).abs() <= 5 {
            score -= 25.0; // near-match lookahead
        } else if (post_residual as i64 - next_item_size as i64).abs() <= 15 {
            score -= 8.0;
        } else {
            // mismatch penalty scaled by gap size
            score += ((post_residual as i64 - next_item_size as i64).abs() as f64) * 0.3;
        }

        // Reward if post_residual can hold next item at all
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 && post_residual < 10 {
            // tiny dead space is fine (unusable anyway), small bonus
            score -= 3.0;
        } else {
            // leftover space that next item cannot use: penalize waste
            score += (post_residual as f64 - next_item_size as f64).max(0.0) * 0.4;
        }
    } else {
        // Last item: just minimize residual
        score -= 10.0;
    }

    // Compare against mean residual: prefer bins tighter than average
    if mean_residual > 0.0 {
        score += (bin_residual as f64 - mean_residual) * 0.15;
    }

    // Last-chance bin bonus: only one bin fits, avoid opening new bin unless residual huge
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Penalize new-bin candidate when any reasonable fit exists in open bins
    if bin_residual == bin_capacity {
        score += 30.0 + (bin_capacity as f64 - post_residual as f64) * 0.1;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0; // fresh bin still good if it chains next item
        }
    }

    // Late in stream: be more conservative, prefer filling existing bins
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 - 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a non-linear bonus.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space: residuals too small for likely future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: bonus if next item fits exactly in post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect follow-up fit
        } else if next_item_size < post_residual {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize wasting space it can't use
            score += 5.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    } else if fitting_bins_count > 1 {
        // With alternatives, mildly prefer bins that are more filled already.
        score += 0.05 * (bin_residual as f64 - mean_residual);
    }

    // New-bin candidate logic: only attractive when current fits are poor
    // or no open bin is tight, and the lookahead item is large.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 > bin_capacity as f64 * 0.5
            && (fitting_bins_count == 0 || mean_residual < bin_capacity as f64 * 0.2);
        if poor_fit || open_bins_count == 0 {
            score -= 20.0;
        } else {
            score += 45.0; // discourage opening new bins when good fits exist
        }
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0 * next_item_size as f64 / bin_capacity as f64;
        }
    }

    // Time horizon: early in stream, exploration is cheaper (favor consolidation later).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - tightness);

    // Mild penalty for proliferating bins.
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr_norm = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let base = pr - 12.0 * progress * (1.0 - progress) * 4.0 * pr_norm * (1.0 - pr_norm);

    // Penalize large dead space more as stream progresses (less chance to reuse).
    let dead_penalty = (pr_norm * pr_norm) * (1.0 + progress * 18.0);

    // Reward tight fits (small post_residual) with a smooth quadratic bonus.
    let tight_bonus = (1.0 - pr_norm) * (1.0 - pr_norm) * 6.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    let last_chance = if fitting_bins_count == 1 { 25.0 } else { 0.0 };

    // Lookahead: if next item fits into post_residual, reward this placement smoothly.
    let n = next_item_size as f64;
    let lookahead = if n > 0.0 {
        let fit = ((pr - n).max(0.0) / cap) * ((pr - n).max(0.0) / cap);
        -8.0 * (1.0 - fit) * (pr >= n) as i32 as f64
    } else {
        0.0
    };

    // Mild preference for consolidating items when many bins are open.
    let crowding = (open_bins_count as f64).ln() * pr_norm * 2.0;

    base + dead_penalty - tight_bonus + last_chance + lookahead + crowding
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover into capacity fractions
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let fraction = post / cap; // 0..1

    // Integer-division thresholds on post_residual: dead-space classes
    // Residuals <= 10 are "perfect" (almost full); 11..=25 usable; >25 wasteful
    if post_residual == 0 {
        score -= 50.0; // perfect fit, huge reward
    } else if post_residual <= 10 {
        score -= 25.0;
    } else if post_residual <= 25 {
        score -= 8.0;
    } else {
        score += 6.0; // large dead space penalty
    }

    // Modulo arithmetic on post_residual: multiples of 10 are "harmonic" with capacity
    let harmonic = post_residual % 10;
    if harmonic == 0 {
        score -= 5.0; // residual aligns with decile grid, easier to fill later
    } else if harmonic <= 3 {
        score -= 1.0;
    } else {
        score += harmonic as f64 * 0.3; // off-grid leftover is harder to reuse
    }

    // Lookahead: does next item fit exactly / at all in the resulting residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0; // chain fit
        } else if next_item_size <= post_residual {
            score -= (next_item_size as f64) * 0.15; // next item fits: good
        } else {
            // next item won't fit here; penalize more if residual is mid-range
            score += 4.0 + fraction * 5.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 18.0;
    } else {
        score += (fitting_bins_count as f64 - 1.0) * 0.5;
    }

    // New-bin candidate: only attractive when current bins are crowded or item huge
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowded = mean_residual < (item_size as f64) * 1.2;
        if fitting_bins_count == 0 || (crowded && item_size > bin_capacity / 2) {
            score -= 20.0; // opening fresh bin justified
        } else {
            score += 40.0 + 10.0 * (1.0 - progress); // discourage wasting bins early
        }
    }

    // Mild preference for bins tighter than average
    score -= (mean_residual - bin_residual as f64) * 0.25;

    // Small pressure to consolidate as stream progresses
    score += (open_bins_count as f64).ln().max(0.0) * 0.4;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the smallest plausible item are toxic.
    let min_item = 10u32;
    if post_residual < min_item && post_residual > 0 {
        // Completely unusable residue: heavy penalty scaled by how much was wasted.
        score += 40.0 + (post_residual as f64) * 2.0;
    } else if post_residual > 0 {
        // Partially usable gap: mild penalty if it is below the next item's needs
        // (creates dead space with respect to the lookahead).
        if next_item_size > 0 && post_residual < next_item_size {
            score += 8.0;
        }
        // Reward near-perfect fits strongly.
        if post_residual <= 5 {
            score -= 15.0;
        }
    }

    // Tight-fit reward: fraction of bin consumed by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 12.0;

    // Open-bin pressure: discourage spreading when many bins are open,
    // encourage consolidation; but when this bin is the LAST fitting bin,
    // strongly reward using it instead of opening a new one.
    if fitting_bins_count <= 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Pressure grows with open bin count: favor filling existing bins
    // rather than opening new ones when many are already open.
    let open_pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize increasingly with open bins and stream progress,
        // but allow it if this item is huge and mean residual is too small to host it.
        score += 20.0 + open_pressure * 10.0 + (step_index as f64 / total_items.max(1) as f64) * 15.0;
        // Escape hatch: if the item barely fits anywhere, opening a fresh bin is fine.
        if item_size as f64 > mean_residual + 5.0 {
            score -= 30.0;
        }
        // If next item is large, a fresh bin is more valuable.
        if next_item_size >= 60 {
            score -= 10.0;
        }
    } else {
        // Existing bin: slight bonus for choosing bins below mean residual
        // (i.e., emptier-than-average bins get consolidated less; prefer
        // filling fuller bins to keep slack concentrated).
        if (bin_residual as f64) < mean_residual {
            score += 3.0;
        } else {
            score -= 3.0;
        }
    }

    // Prefer exact-capacity completions overwhelmingly.
    if post_residual == 0 {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: low post_residual is good, but reward exact fills strongly.
    if post_residual == 0 {
        score -= 50.0;
    } else {
        // Penalize dead space that is too small for typical future items.
        let dead = post_residual as f64;
        if next_item_size > 0 && (post_residual as u32) < next_item_size {
            score += 12.0; // this leftover can't host the next item
        }
        // Non-linear penalty on unusable slack (small leftovers are worst).
        score += (dead / 10.0).powi(2) * 0.15;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item.
    if next_item_size > 0 {
        let match_gap = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        score -= 30.0 / (1.0 + match_gap);
        if post_residual == next_item_size {
            score -= 25.0; // perfect 2-step chain
        }
    } else {
        // Last item: strongly prefer tightest bin.
        score -= 40.0;
    }

    // Relative to mean residual: prefer bins tighter than average when they fit well.
    let rel = post_residual as f64 - mean_residual;
    score += rel * 0.3;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0 + (item_size as f64 / bin_capacity as f64) * 10.0;
    }

    // New-bin candidate handling: make empty bins attractive only when the item is
    // large or current bins are crowded.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowding = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
        let large_item = item_size as f64 / bin_capacity as f64;
        // Penalize new bin mildly; discount if item is big or bins are fragmented.
        score += 20.0 - 25.0 * large_item - 3.0 * crowding.min(5.0) - 10.0 * progress;
        // If next item is huge, a fresh bin gives flexibility.
        if next_item_size >= 60 {
            score -= 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Penalize dead space that no future item (>=10... but sizes 1..100) can use:
    // small residuals are trap space; large residuals are reusable.
    let pr = post_residual as f64;
    if pr > 0.0 {
        // dead-space penalty strongest when residual is small but nonzero
        let deadness = (bin_capacity as f64 - pr) / (bin_capacity as f64);
        score += (bin_capacity as f64 - pr) * (1.0 - deadness) * 0.5;
        // extra penalty if residual too small for typical items
        if pr < 20.0 {
            score += (20.0 - pr) * 2.0;
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            score -= 50.0 - slack as f64 * 0.3;
        } else {
            // next item won't fit here; penalize leaving awkward space
            score += 30.0;
        }
        // chain fit: item + next nearly fill the bin
        if item_size + next_item_size == bin_residual {
            score -= 400.0;
        }
    }

    // Prefer fuller bins over emptier ones (tightness reward)
    let tightness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= tightness * 40.0;

    // Global state: many open bins with high mean residual -> consolidate
    let progress = step_index as f64 / total_items.max(1) as f64;
    if mean_residual > item_size as f64 * 1.5 && open_bins_count > 2 {
        score -= 20.0 + mean_residual * 0.1;
    }

    // Early in stream: slightly favor opening new bins to build flexibility;
    // late in stream: strongly favor filling existing bins.
    score += progress * 15.0 - (1.0 - progress) * 10.0;

    // New-bin candidate: only attractive when item is large or no good fit exists
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 > 0.6 * bin_capacity as f64;
        if large_item || (fitting_bins_count == 0) {
            score -= 250.0;
        } else {
            score += 120.0; // discourage wasting a fresh bin on small items
        }
    }

    // Mild preference when many bins can fit: pick the tightest (already via residual)
    if fitting_bins_count > 3 {
        score += 5.0; // slight tie-break noise-free damping
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit_frac = pr / cap;
    let item_frac = item_size as f64 / cap;

    let mut score = pr;

    // Smooth non-linear coupling: value of post_residual decays quadratically with stream progress
    // (late in the stream, tight fits matter more; dead space is penalized more).
    let tightness = 1.0 - fit_frac;
    let progress_weight = progress * progress;
    score += progress_weight * 30.0 * tightness * tightness;

    // Reward near-perfect fits with a smooth Gaussian-like bump on small post_residual.
    score -= 25.0 * (-(fit_frac * fit_frac) / 0.02).exp();

    // Penalize leaving residual that no typical next item can use: mid-range dead space.
    let dead = (fit_frac - 0.5) * (fit_frac - 0.5);
    score += 10.0 * dead * (1.0 + progress);

    // Lookahead coupling: if next item fits into post_residual, reward this bin smoothly.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr as f64 {
            let snug = 1.0 - ((pr - nx) / cap).abs();
            score -= 12.0 * snug * (1.0 - progress);
        } else {
            score += 6.0 * ((nx - pr) / cap);
        }
    }

    // Last-chance bonus: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 40.0 * (0.5 + progress);
    }

    // Mild pressure toward consolidating many open bins.
    score += 0.5 * (open_bins_count as f64).ln().max(0.0) * fit_frac;

    // Prefer bins whose residual deviates from the mean (fill the emptiest first, smoothly).
    score += 2.0 * (mean_residual - bin_residual as f64) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify dead space into capacity fractions.
    let cap = bin_capacity as f64;
    let post_f = post_residual as f64;
    let frac = post_f / cap; // fraction of capacity left after placement

    // Reward tight fits: post_residual near zero is best.
    if post_residual == 0 {
        score -= 60.0; // perfect fill
    } else if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    } else if post_residual <= 20 {
        score -= 10.0;
    }

    // Penalize dead space in harmonic bands: residuals in (0,10) are hard to fill.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Integer-division classes: residual mod 10 measures "alignability".
    let align = post_residual % 10;
    if align == 0 {
        score -= 8.0; // residual is a multiple of 10, matches typical item sizes
    } else if align >= 7 {
        score += 5.0; // awkward leftover
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size < post_residual {
            let nxt_post = post_residual - next_item_size;
            if nxt_post <= 10 {
                score -= 20.0;
            } else {
                score -= (nxt_post as f64) * 0.15;
            }
        } else {
            // next item won't fit here; penalize small leftover dead space
            score += (post_f - frac * 20.0) * 0.1 + 5.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: opening a bin should only win when no open bin
    // gives a decent fit. Make the fresh bin unattractive unless item is large.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_penalty = 55.0;
        // large items pair poorly with existing partial residuals
        if item_size > 50 {
            new_bin_penalty -= 20.0;
        }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            new_bin_penalty -= 15.0; // room for pairing with lookahead
        }
        new_bin_penalty += progress * 10.0;
        score += new_bin_penalty;
    }

    // Prefer bins with residual close to item (best-fit flavor) via mean coupling.
    let diff = (bin_residual as f64 - item_size as f64).abs();
    score += diff * 0.3;

    // Spread pressure: many open bins -> prefer filling existing ones.
    score -= (open_bins_count as f64).sqrt() * 2.0;
    score += (mean_residual - post_f).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in [1, 9] is nearly unusable
    // (item sizes drawn from 1..=100, small gaps waste capacity).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - (post_residual as f64) * 4.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Reward when the leftover gap can still host the next item (lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Gap that cannot host the next item: mild penalty scaled by gap size.
        score += (post_residual as f64) * 0.3;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bins pressure: with many open bins, discourage spreading items thin;
    // with few open bins, mild bonus to consolidate.
    let ob = open_bins_count as f64;
    score += (ob.ln() + 1.0).max(0.0) * 3.0 * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate handling: empty bin should only win when no open bin
    // fits well. Penalize the fresh bin so it is chosen only for large items
    // or when all open bins would leave tiny dead space.
    if bin_residual == bin_capacity {
        score += 35.0;
        // Large items benefit from a fresh bin (avoid fragmentation).
        if item_size > bin_capacity / 2 {
            score -= 45.0;
        }
        // Late in the stream, opening new bins is less attractive.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 20.0;
    }

    // Prefer bins tighter than the average residual (best-fit flavor).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (low post_residual is good)
    score -= (bin_capacity as f64 - post_residual as f64).sqrt() * 2.0;

    // 2-step lookahead: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot fit here: penalize proportionally to wasted gap
            let gap = (next_item_size - post_residual) as f64;
            score += 0.3 * gap;
        }
    }

    // Compare against mean residual: bins tighter than average are preferable
    score += 0.15 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Penalize creating very small dead space (unusable for typical items)
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Early in the stream, be more willing to open fresh bins for good structure
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when lookahead matches well or few bins fit
        let bonus = if next_item_size > 0 && next_item_size <= bin_capacity {
            10.0 * (1.0 - progress)
        } else {
            0.0
        };
        score += 5.0 + bonus - (fitting_bins_count as f64) * 3.0;
    }

    // Prefer filling more-open-bins situations to keep bin count controlled
    score += 0.02 * open_bins_count as f64;

