    }

    // Global state coupling: many open bins with high mean residual -> prefer
    // consolidating into existing bins rather than opening new ones.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize when existing bins are roomy overall.
        score += 6.0 * mean_residual / bin_capacity as f64;
