        // Early in the stream, opening bins is cheaper; late, expensive.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    } else {
        // Existing bin: reward using it more when many bins are open.
        score -= 0.3 * open_bins_count as f64;
    }

    // Mild time-horizon term: later items should pack tighter.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - fit_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

