    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth interaction: tight fits matter more as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= (item_size as f64 / cap) * tightness * tightness * (1.0 + 2.0 * progress) * 12.0;

