    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = (pr - nxt) / cap;
            score -= 5.0 * (1.0 - slack * slack) * (0.5 + progress);
        } else {
            score += 3.0 * ((nxt - pr) / cap) * (0.5 + progress);
        }
    }

    // Mild penalty for spreading across many bins early (encourage consolidation)
    score += (open_bins_count as f64).ln() * 1.5 * (1.0 - progress);

    // New-bin candidate: only attractive when item is large relative to residuals
    if bin_residual == bin_capacity {
        let need = item_size as f64 / cap;
        score = pr - (need * need) * 8.0 * (0.3 + progress);
        if fitting_bins_count > 0 {
            score += 6.0 + 8.0 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: reward low post_residual non-linearly.
    if post_residual == 0 {
        score -= 1000.0; // perfect fit
    } else {
        // Dead-space penalty grows superlinearly for small residuals.
        let pr = post_residual as f64;
        score += (bin_capacity as f64 - pr) / bin_capacity as f64 * 20.0;
        score += 500.0 / pr; // tiny residuals are nearly useless
    }

    // Harmonic class of post_residual modulo 10: residuals that match
    // common small item sizes (10,20,...) are reusable, others are dead space.
    let class = post_residual % 10;
    if class == 0 {
        score -= 15.0;
    } else if class <= 5 {
        score += class as f64 * 2.0; // awkward leftover
    } else {
        score += (10 - class) as f64 * 3.0; // hard to fill gap
    }

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 25.0;
        // Extra reward if next item exactly fills post_residual.
        if next_item_size == post_residual {
            score -= 60.0;
        }
    } else if next_item_size > 0 {
        // Next item won't fit here afterwards: penalize wasting the bin.
        score += 10.0;
    }

    // Last chance: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // New-bin candidate handling: opening a new bin is only good when the
    // item is large relative to capacity or fits are scarce.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let frac = item_size as f64 / bin_capacity as f64;
        if frac > 0.6 {
            score -= 40.0 * frac; // big item: fresh bin is fine
        } else if fitting_bins_count <= 1 {
            score -= 10.0; // no alternatives anyway
        } else {
            score += 200.0; // discourage opening bins for small items
        }
        // Late in the stream, prefer consolidating into open bins.
        score += progress * 30.0;
        // Many open bins: prefer reusing them.
        score += open_bins_count as f64 * 3.0;
    }

    // Mild preference for bins below mean residual (balance the pool).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
