        let tightness = (item_size as f64 / bin_capacity as f64).powf(2.0);
        let poor_fit_penalty = if next_item_size > 0 && post_residual >= next_item_size { 0.0 } else { 0.0 };
        score += 300.0
            - tightness * 250.0
            - (1.0 - progress) * 40.0
            - if fitting_bins_count == 1 { 100.0 } else { 0.0 }
            + poor_fit_penalty;
