    // Mild penalty for opening many bins when mean residual is still large
    if open_bins_count > 4 {
        score += (open_bins_count as f64 - 4.0) * 2.0 * (mean_residual / bin_capacity as f64);
    }

    // Tie-break: prefer bins with less residual among equals
    score += (bin_residual as f64) * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
