    // late in stream, allow looser packing since bins matter less
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.3 * (1.0 - progress);

    // Global state: many open bins -> discourage opening new ones / spread waste
    if bin_residual == bin_capacity {
