    };

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    let last_chance = if fitting_bins_count == 1 { -60.0 } else { 0.0 };

    // Mild penalty for spreading across many open bins when mean residual is high
    let spread = 0.05 * open_bins_count as f64 * (mean_residual / cap).max(0.0);

    // Slight preference to keep new bins closed early, open them late if fit is poor
    let new_bin_bias = if bin_residual == bin_capacity {
        30.0 - 50.0 * progress
    } else {
        0.0
    };

    base + progress_coupling + dead + lookahead + last_chance + spread + new_bin_bias
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: which capacity fraction does the
    // post-residual fall into? Smaller classes (tighter fits) are better.
    let pr = post_residual;
    let class: f64 = if pr == 0 {
        -40.0 // perfect fit
    } else if pr <= 10 {
        -12.0
    } else if pr <= 25 {
        -4.0
    } else if pr <= 50 {
        0.0
    } else {
        6.0 // large dead space
    };
    score += class;

    // Modulo structure: leftovers that are "nice" sizes (multiples of small
    // harmonics) are more likely to be filled by future items.
    if pr > 0 {
        if pr % 10 == 0 {
            score -= 3.0;
        } else if pr % 5 == 0 {
            score -= 1.5;
        }
        if pr % 7 == 0 {
            score -= 1.0;
        }
    }

    // Lookahead coupling: reward when the next item fits the post-residual,
    // penalize when the next item just barely misses.
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 8.0;
            // Extra bonus for near-exact chain fit (integer division threshold)
            if pr / next_item_size.max(1) >= 2 {
                score -= 2.0;
            }
        } else if next_item_size <= pr + 10 {
            score += 4.0; // agonizing near-miss
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when current fit is bad
    // and many bins are already open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 30.0 + 0.3 * open_bins_count as f64 - 10.0 * progress;
        if item_size as f64 > 0.6 * cap {
            score -= 8.0; // big items prefer fresh bins
        }
        if next_item_size > 0 && next_item_size as f64 + item_size as f64 <= cap {
            score -= 5.0;
        }
    }

    // Mild pressure toward bins below mean residual (consolidation).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=12) are heavily penalized.
    if post_residual > 0 && post_residual <= 12 {
        score += 60.0 * (1.0 - (post_residual as f64) / 13.0);
    }

    // Reward tight fits (post_residual near zero but exact fits get the natural low score already).
    if post_residual <= 3 {
        score -= 8.0;
    }

    // Penalize leaving a gap that the lookahead item cannot use.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new bins.
    let new_bin = (bin_residual == bin_capacity) as f64;
    let pressure = (open_bins_count as f64 / (open_bins_count as f64 + 4.0)) * 25.0;
    score += new_bin * pressure;

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && !new_bin.bool_to_f64() {
        score -= 30.0;
    }

    // Slight preference for bins tighter than the mean residual (compactness).
    score += 0.3 * (mean_residual - bin_residual as f64);

    score
}

trait BoolToF64 { fn bool_to_f64(&self) -> f64; }
impl BoolToF64 for bool { fn bool_to_f64(&self) -> f64 { if *self { 1.0 } else { 0.0 } } }

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual).
    score -= (bin_capacity as f64 - post_residual as f64) * 0.05;

    // 2-step lookahead: strongly reward when next item fits into the post residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        let leftover_after_next = post_residual - next_item_size;
        score -= 30.0 - leftover_after_next as f64 * 0.3;
    } else if next_item_size > 0 {
        // Next item won't fit here: penalize leaving a gap smaller than next item (dead space).
        let dead = post_residual as f64;
        score += dead * 0.4;
        // Slight bonus if post_residual is large enough to be reusable later anyway.
        if post_residual >= 50 {
            score -= 5.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Prefer bins tighter than the mean residual (well-utilized bins).
    score += (mean_residual - post_residual as f64) * 0.25;

    // Penalize opening a new bin when good fitting bins exist, unless new bin is genuinely better.
    if bin_residual == bin_capacity {
        // New bin: baseline penalty that tight fits in existing bins can overcome.
        score += 15.0;
        // But if next item is large and nothing fits well, new bin is fine.
        if next_item_size > 0 && next_item_size > mean_residual {
            score -= 12.0;
        }
    }

    // Late in stream: be more conservative, avoid many tiny open bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * 0.3 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Reward tight fits: lower post_residual relative to capacity.
    score -= (1.0 - post / cap) * 30.0;

    // Penalize dead space that is too small for typical future items.
    if post > 0.0 && post < 10.0 {
        score += 40.0;
    }

    // Lookahead: if next item fits in this bin's post-residual, reward.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 15.0;
        // extra reward if next item fills the residual tightly
        let gap = post - next_item_size as f64;
        score -= (1.0 - gap / cap) * 10.0;
    } else if next_item_size > 0 && (next_item_size as f64) > post && (next_item_size as f64) <= post + 10.0 {
        // near-miss: slightly penalize leaving residual just below next item
        score += 8.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: penalize opening a new bin when stream is early
    // and open bins exist; allow it late when fragmentation is high.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 25.0 * (1.0 - progress);
        // discourage new bins when mean residual across open bins is large
        score += (mean_residual / cap).clamp(0.0, 1.0) * 20.0;
        // allow new bins late in the stream to avoid cascading small fills
        score -= progress * 10.0;
    }

    // Mild penalty for spreading across many open bins when mean residual is low.
    if open_bins_count > 4 && (mean_residual / cap) < 0.2 {
        score += 5.0;
    }

    // Prefer bins whose residual is close to item size (best-fit flavor).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Prefer tight fits: quadratic reward for small post-residual.
    let fit = 1.0 - (pr / cap).powi(2);
    score -= 30.0 * fit;

    // Non-linear coupling of residual with stream progress: early stream tolerates
    // slack, late stream punishes wasted space increasingly.
    let progress_weight = t * t * (3.0 - 2.0 * t); // smoothstep
    score += progress_weight * (pr * pr / cap) * 0.6;

    // Penalize bins whose residual diverges from the mean (fragmentation).
    score += 0.15 * (pr - mean_residual).abs();

    // Lookahead: reward if next item fits into post-residual, penalize near-miss.
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if ns <= pr {
            score -= 8.0 * (1.0 - ns / cap);
        } else {
            score += 4.0 * ((ns - pr) / cap);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - t * 0.5);
    }

    // Mild penalty for spreading across many open bins.
    score += 0.05 * open_bins_count as f64 * t;

    // New-bin candidate: keep it neutral-slightly high so it's chosen only
    // when all open bins score poorly (poor fits late in the stream).
    if bin_residual == bin_capacity {
        score += 12.0 + 10.0 * (1.0 - t);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how well post_residual decomposes into
    // "nice" divisors of the capacity (harmonic residue classes).
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Fraction of capacity left after placement.
    let frac = pr / cap;

    // Reward residuals that lie in harmonic classes (multiples of common item
    // size classes: 10, 20, 25, 50) — these are more likely to be filled later.
    let harmonic_bonus = if post_residual == 0 {
        -30.0 // perfect fit: strongly favored
    } else if post_residual % 50 == 0 {
        -12.0
    } else if post_residual % 25 == 0 {
        -8.0
    } else if post_residual % 20 == 0 {
        -6.0
    } else if post_residual % 10 == 0 {
        -4.0
    } else {
        0.0
    };
    score += harmonic_bonus;

    // Penalize small but nonzero dead space (unusable residue classes).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly favor this bin (chain fit).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            // reward proportionally to how well next item uses the leftover
            let fill = next_item_size as f64 / pr.max(1.0);
            score -= 10.0 * fill;
        } else {
            // next item cannot use this residual: mild penalty scaled by waste
            score += 3.0 * ((next_item_size - post_residual) as f64 / cap);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
        // but if the fit leaves a bad residue class, soften the reward
        if post_residual > 0 && post_residual < 10 {
            score += 12.0;
        }
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Prefer reusing open bins when they give decent fits; penalize the
        // fresh bin unless the current item is large relative to capacity or
        // no good fit exists.
        let tightness = item_size as f64 / cap;
        // large items start fresh bins more readily; small items should reuse
        score += 8.0 + 20.0 * (1.0 - tightness);
        // if many bins are open and mean residual is small, opening new is fine
        if (mean_residual / cap) < 0.15 && open_bins_count > 0 {
            score -= 6.0;
        }
    } else {
        // Reusing bins: reward tighter fits (smaller post_residual already
        // captured), plus a mild pressure to consolidate when many bins open.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 2.0 * progress * (open_bins_count as f64).sqrt();
    }

    // Mean-residual coupling: prefer bins whose residual is below the mean
    // (i.e., already partly filled) to keep a spread of usable residuals.
    let res_f = bin_residual as f64;
    if mean_residual > 0.0 {
        score += 0.05 * (res_f - mean_residual);
    }

    // Integer-division threshold on post_residual: residuals in the "mid"
    // band (cap/4 .. cap/2) are the most reusable; reward them.
    if pr > cap * 0.25 && pr <= cap * 0.5 {
        score -= 5.0;
    } else if pr > cap * 0.75 {
        // very empty bin after placement: item was tiny, mild penalty for waste
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // minimum plausible future item are "dead space" -> heavy penalty.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item {
        score += 1000.0;
    }

    // Penalize small-but-nonzero gaps more aggressively than exact fits,
    // scaled by how small the gap is relative to typical item sizes.
    let gap_ratio = post_residual as f64 / bin_capacity as f64;
    if post_residual > 0 {
        score += 30.0 * gap_ratio * gap_ratio;
    } else {
        // Perfect fit: strong reward.
        score -= 50.0;
    }

    // Reward snug fits: post_residual close to zero relative to item size.
    let snugness = post_residual as f64 / (item_size.max(1) as f64);
    score += 10.0 * snugness;

    // Open-bin pressure: discourage spreading across many bins when
    // open_bins_count grows; favor consolidating into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 2.0 * open_bins_count as f64 * (0.5 + progress);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Lookahead: if the next item fits in the post residual, reward this bin;
    // otherwise penalize creating a gap that wastes the next item's needs.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 6.0;
        }
    }

    // Compare against mean residual: bins with residual far below the mean
    // are nearly full (good to fill), so reward relative fullness.
    score -= 0.5 * (mean_residual - bin_residual as f64);

    // New-bin candidate handling: an empty bin is only attractive when the
    // current bin would leave a bad gap or no open bin fits well.
    if bin_residual == bin_capacity {
        if item_size == bin_capacity {
            score -= 20.0;
        } else {
            // Neutral-ish baseline; dead-space penalties above will dominate
            // for poor fits, letting tight existing bins win.
            score += 5.0 + 0.3 * open_bins_count as f64;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits: squash post_residual so small leftovers dominate.
    score = score * score / (bin_capacity as f64 + 1.0) + post_residual as f64 * 0.5;

    // 2-step lookahead: strongly reward leaving exactly next_item_size of room.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 20.0 / (1.0 + slack / 10.0);
    } else if next_item_size > 0 {
        // Can't fit the next item here afterwards; penalize dead space relative to next size.
        score += (next_item_size - post_residual) as f64 * 0.3;
    }

    // Relative-to-mean residual coupling: prefer bins tighter than average.
    let dev = post_residual as f64 - mean_residual;
    score += dev * 0.15;

    // Last-chance bonus: if this is the only bin that fits, use it rather than open a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when it enables a good 2-step chain,
    // i.e. fresh bin leaves room for the next item too.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 1.2; // base penalty for opening a new bin
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= (bin_capacity - next_item_size - item_size) as f64 * 0.1;
        }
        // Late in the stream, opening new bins is cheaper (fewer future items to strand).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 15.0;
        // If many bins are open and none fit well, new bin is fine.
        if fitting_bins_count == 0 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fit tightness: reward near-perfect fits strongly.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fit_ratio > 0.75 {
        score -= 12.0 * fit_ratio * fit_ratio;
    }

    // Penalize small unusable dead space; dead space below min item size is waste.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual == 0 {
        score -= 8.0; // perfect fill
    }

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Lookahead coupling: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
            // extra reward if next item fills remaining space well
            let nxt_fit = next_item_size as f64 / post_residual as f64;
            if nxt_fit > 0.7 {
                score -= 5.0;
            }
        } else {
            // next item won't fit here; penalize leaving awkward gaps
            if post_residual < next_item_size as f64 * 0.5 {
                score += 4.0;
            }
        }
    } else {
        // Last item: strongly prefer tightest fill.
        score -= 15.0 * fit_ratio;
    }

    // Global state: many open bins with large mean residual -> prefer consolidating into fuller bins.
    let progress = (step_index as f64) / (total_items.max(1) as f64);
    if mean_residual > 30.0 && open_bins_count > 3 {
        score += 0.05 * (mean_residual - post_residual as f64);
    }
    // Late in stream: be more conservative, prefer exact fits over spreading.
    if progress > 0.7 {
        score += 0.08 * post_residual as f64 * progress;
    }

    // New-bin candidate: penalize unless current bins are poor options.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 1.0 } else { (fitting_bins_count as f64).recip() };
        score += 18.0 * desperation - 6.0 * (1.0 - desperation);
        // opening new bin more attractive early (room to grow) or when mean residual is fragmented
        score -= 10.0 * (1.0 - progress) * if open_bins_count < 4 { 1.0 } else { 0.3 };
        if mean_residual < 15.0 {
            score -= 8.0; // existing bins nearly full, new bin is fine
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = pr_norm * (1.0 + 0.6 * progress) - 0.8 * pr_norm * pr_norm * (1.0 - progress);

    let mut score = poly * cap;

    // Reward tight fits (small post_residual) more strongly as stream progresses
    score -= (1.0 - pr_norm).powi(3) * 10.0 * (0.5 + progress);

    // Penalize dead space that cannot fit a typical next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx {
            score += (nx - pr) * (1.0 + 2.0 * progress);
        } else {
            // reward leaving room exactly usable by the next item
            score -= 3.0 * (1.0 - ((pr - nx) / cap).abs()) * progress;
        }
    }

    // Last-chance bonus: only one fitting bin -> strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 * (1.0 + progress);
    }

    // Mild penalty for spreading across many open bins when mean residual is large
    score += 0.02 * open_bins_count as f64 * (mean_residual / cap);

    // New-bin candidate: neutral-ish baseline, slightly penalized early, relaxed late
    if bin_residual == bin_capacity {
        score += 8.0 * (1.0 - progress) - 4.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: reward residuals that fall into
    // "usable" classes (multiples of common small item sizes), penalize dead space.
    let cap = bin_capacity as f64;

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Classify post_residual by modulo classes of typical small sizes.
    let pr = post_residual as f64;
    let mut class_bonus = 0.0;
    if post_residual % 10 == 0 { class_bonus += 6.0; }
    if post_residual % 20 == 0 { class_bonus += 4.0; }
    if post_residual % 25 == 0 { class_bonus += 3.0; }
    if post_residual % 50 == 0 { class_bonus += 5.0; }
    // Dead space: residual too small to fit the smallest plausible item.
    if post_residual < 10 && post_residual > 0 {
        score += 40.0; // unusable sliver
    }
    score -= class_bonus;

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly favor this bin (chain placement).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size <= post_residual {
            // Reward smooth packing of the chain.
            let frac = next_item_size as f64 / pr.max(1.0);
            score -= 30.0 * frac;
            // Penalize leaving a residual just barely above next item (awkward fit).
            let gap = post_residual - next_item_size;
            if gap > 0 && gap < 5 {
                score += 15.0;
            }
        } else {
            // Next item won't fit here; slight penalty proportional to overflow.
            score += 5.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: only open a new bin when current fit is poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Opening a new bin is expensive; require that this bin's fit is bad
        // (large waste relative to item) to prefer it.
        let waste = bin_residual - item_size;
        let waste_frac = waste as f64 / cap;
        // Base cost of a fresh bin, discounted if it would create a very clean class.
        score += 120.0;
        if waste_frac < 0.2 {
            score -= 60.0; // fresh bin with tight fit is fine
        }
        // Penalize opening new bins late in the stream.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 60.0 * progress;
        // Penalize hoarding too many open bins.
        score += 4.0 * open_bins_count as f64;
    } else {
        // Existing bins: prefer tighter fills; compare against mean residual.
        let rel = pr / mean_residual.max(1.0);
        score += 10.0 * (1.0 - rel); // bins below mean residual are more filled -> favored
        // Early in stream, keep bins flexible (prefer moderate residual).
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress < 0.3 && post_residual > 60 {
            score += 8.0;
        }
    }

    // Harmonic threshold on post_residual via integer division: residuals in
    // [50,100) can still host medium items; [20,50) only small; <20 nearly dead.
    if post_residual >= 50 {
        score -= 10.0;
    } else if post_residual >= 20 {
        score -= 3.0;
    } else if post_residual > 0 {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let dead_zone: f64 = 10.0;
    if post_residual > 0 && (post_residual as f64) < dead_zone {
        score += (dead_zone - post_residual as f64) * 8.0;
    }
    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward leaving a gap that can still host the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Lookahead can't use the leftover: mild penalty proportional to waste.
        score += (next_item_size as f64 - post_residual as f64).min(20.0) * 0.5;
    }

    // Last chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Open-bins pressure: many open bins -> discourage spreading, favor filling.
    let pressure = open_bins_count as f64;
    score += pressure * 0.8 * (post_residual as f64 / bin_capacity as f64);

    // Mean residual coupling: if this bin's residual is far below mean, it's a
    // good filler bin; if far above mean, penalize slightly.
    let residual = bin_residual as f64;
    score += (residual - mean_residual) * 0.15;

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, reduced when many bins already open
        // and the current item is large (poor fit elsewhere likely).
        let mut new_bin_cost = 35.0;
        if fitting_bins_count <= 1 {
            new_bin_cost -= 30.0; // no real alternative: opening is cheap
        }
        if item_size >= 60 {
            new_bin_cost -= 8.0;
        }
        score += new_bin_cost;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact or near-exact fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: strongly reward bins whose post_residual matches the next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual as f64 >= next_item_size as f64 {
            // Next item can follow in this bin: reward tight chaining.
            score -= 150.0 - 1.5 * gap;
        } else {
            // Next item cannot fit: penalize dead space proportional to gap.
            score += 0.5 * gap;
        }
        // Bonus if this bin becomes exactly reusable by next item.
        if post_residual == next_item_size {
            score -= 120.0;
        }
    }

    // Compare against mean residual: bins tighter than average are better targets.
    let dev = post_residual as f64 - mean_residual;
    score += 0.3 * dev;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 250.0;
    }

    // Penalize wasting a mostly-empty bin (bad fragmentation).
    if post_residual as f64 > 0.7 * bin_capacity as f64 {
        score += 60.0;
    }

    // Late in the stream, prefer closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 0.1 * post_residual as f64;

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 40.0 + 10.0 * fitting_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits: small post-residual is good, but dead space
    // below the minimum item size (1) is worthless. Penalize post_residual
    // super-linearly when it becomes "unusable".
    let waste = post_residual as f64;
    score += 0.35 * waste * waste / bin_capacity as f64;

    // Reward high fill ratio of the bin after placement.
    let fill_after = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 40.0 * fill_after;

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits into the post-residual, this placement
    // chains nicely; reward it proportionally to how well the next item fills
    // the leftover space.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let chain_fit = next_item_size as f64 / post_residual as f64;
            score -= 18.0 * chain_fit;
        } else {
            // Next item won't fit here; slight penalty if post_residual is
            // large enough that it might have been usable.
            if post_residual > 0 && post_residual >= next_item_size / 2 {
                score += 4.0;
            }
        }
    }

    // Global state coupling: when mean residual across open bins is high,
    // there is slack in the system; be pickier (penalize mediocre fits).
    // When mean residual is low, accept fits more readily.
    let mr = mean_residual.max(0.0);
    score += 0.08 * mr * (post_residual as f64 / bin_capacity as f64);

    // Many open bins: encourage consolidation into existing bins.
    score += 0.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Time horizon: early in the stream, keep bins flexible (favor larger
    // post_residual slightly); late in the stream, prioritize closing bins
    // out (favor small post_residual more aggressively).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * fill_after;
    score += 5.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate handling: an empty bin has maximal flexibility.
    // Only prefer opening a new bin when the item fits terribly in all open
    // bins (very large post_residual) or there are no open bins.
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score -= 100.0; // must open a bin
        } else {
            // Baseline cost of a fresh bin; adjust with how much slack the
            // system currently has. High mean residual -> new bin more
            // attractive since existing space is fragmented.
            score += 55.0 - 0.15 * mr;
            if next_item_size > 0 && next_item_size <= post_residual {
                score -= 8.0; // fresh bin can chain the next item
            }
            if fitting_bins_count == 1 {
                score += 30.0; // don't abandon the last fitting bin
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Non-linear polynomial coupling of post_residual with progress:
    // early in the stream, waste matters less; later, dead space is heavily penalized.
    let tightness = 1.0 + 2.5 * progress * progress;
    score *= tightness;

    // Smooth super-linear penalty on small post_residuals that are unusable
    // (residual too small to fit a plausible future item): reward very tight fits,
    // but penalize residuals in the awkward "dead zone".
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let dead_zone = (1.0 - pr / cap).powi(3); // grows as bin fills up
    score -= 8.0 * dead_zone * (1.0 - progress);

    // Penalize a nearly-full residual that cannot fit the lookahead item smoothly
    if next_item_size > 0 && post_residual > 0 {
        let gap = (next_item_size as f64 - pr).abs();
        score += 0.05 * gap * (0.5 + progress);
    } else if next_item_size > 0 && pr >= next_item_size as f64 {
        // this bin can still host the next item: reward
        score -= 3.0 * (pr / cap);
    }

    // Last chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize mildly early, more when open bins are underused
    if bin_residual == bin_capacity {
        let waste = mean_residual / cap;
        score += 12.0 + 15.0 * waste * (1.0 - progress);
    } else {
        // Encourage balancing residuals toward the mean
        score += 0.3 * (pr - mean_residual).abs();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "reusable" the leftover space is.
    // Residuals that are multiples of common small item sizes (10, 20, 25, 50)
    // are more likely to be filled by future items -> reward them.
    let pr = post_residual;
    let harmonic_bonus = if pr == 0 {
        -60.0 // perfect fill
    } else if pr % 50 == 0 {
        -18.0
    } else if pr % 25 == 0 {
        -12.0
    } else if pr % 20 == 0 {
        -10.0
    } else if pr % 10 == 0 {
        -6.0
    } else if pr < 10 {
        25.0 // dead space: too small for any item
    } else {
        0.0
    };
    score += harmonic_bonus;

    // Lookahead: does the next item fit exactly into the post residual?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0; // guaranteed perfect follow-up
        } else if next_item_size < pr {
            let gap = pr - next_item_size;
            score -= 8.0 - (gap as f64).min(20.0) * 0.3;
        } else {
            score += 6.0; // next item won't fit here
        }
    } else {
        // Last item: strongly prefer exact fill
        score -= (bin_capacity as f64 - pr as f64) * 0.2;
    }

    // Last-chance bin: avoid wasting a scarce fitting bin unless fit is tight.
    if fitting_bins_count == 1 && post_residual <= bin_residual {
        let tightness = (post_residual as f64) / (bin_capacity as f64);
        score -= 15.0 * (1.0 - tightness);
    }

    // Prefer bins with below-average residual (tighter bins) to consolidate waste.
    let dev = (bin_residual as f64 - mean_residual).max(0.0);
    score += dev * 0.15;

    // Late in the stream, be more aggressive about filling existing bins
    // rather than opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0;

    // New-bin candidate: only attractive when current bin would leave
    // unusable dead space and many bins are open.
    if bin_residual == bin_capacity {
        if post_residual == 0 {
            // empty-bin call always has post_residual == capacity; keep neutral-ish
            score = (bin_capacity as f64) - 10.0 + progress * 20.0;
        }
        if open_bins_count == 0 {
            score -= 100.0; // must open a bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Penalize residual that cannot fit the lookahead item (dead space w.r.t. next).
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 25.0;
    }
    // Reward bin that can still host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }

    // Last-chance bin: strong incentive to use it rather than open a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Open-bin pressure: with many open bins, favor consolidating into existing bins.
    let open_pressure = open_bins_count as f64 / 8.0;
    if bin_residual < bin_capacity {
        score -= open_pressure * 5.0;
    } else {
        score += open_pressure * 5.0;
    }

    // Late in the stream, avoid opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 30.0;
    }

    // Slight preference for bins already tighter than average.
    score += (mean_residual - bin_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: aggressive 2-step lookahead — reward bins whose leftover exactly fits the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect 2-chain: residual consumed by next item
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - slack / bin_capacity as f64); // partial 2-chain reward
        } else {
            // next item cannot use this residual: penalize proportional to mismatch
            let waste = (next_item_size - post_residual) as f64;
            score += 8.0 * (waste / bin_capacity as f64).min(1.0);
        }
    }

    // Penalize tiny dead space (unusable residuals) but reward exact fits.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    } else if post_residual == 0 {
        score -= 25.0; // perfectly closed bin
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Compare residual against mean residual: prefer bins with below-average residual
    // (tighter bins get filled first, keeping looser bins flexible).
    score -= 0.5 * (mean_residual - bin_residual as f64);

    // Mild penalty for opening a new bin when other bins fit, relaxed late in stream.
    if bin_residual == bin_capacity && bin_residual >= item_size {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let open_pressure = (open_bins_count as f64 / (1.0 + progress * 5.0)).min(10.0);
        score += 12.0 + open_pressure;
        // But if the item is large and would leave bad residual anywhere, new bin is fine.
        if item_size >= bin_capacity * 3 / 4 {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: smaller post_residual is better (already base), add non-linear bonus.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Penalize dead space that no future item can plausibly use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    }

    // Lookahead: penalize if placing here blocks the next item's fit.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 12.0 + 0.35 * next_item_size as f64;
        } else {
            // Reward leaving room for the next item.
            score -= 6.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        }
    } else {
        // Last item: prefer minimal waste overall.
        score -= 10.0 * fit_ratio;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Many open bins: encourage consolidation into existing bins.
    if open_bins_count > 2 {
        score -= 1.5 * (open_bins_count as f64).ln();
    }

    // Relative fill vs. fleet mean: prefer bins with residual below mean (denser bins).
    let dev = mean_residual - bin_residual as f64;
    score += 0.08 * dev;

    // New-bin candidate handling: empty bin should only win when fits are poor.
    if bin_residual == bin_capacity {
        let poor_fit_pressure = if fitting_bins_count <= 1 { 0.0 } else { 15.0 };
        let lookahead_penalty = if next_item_size > 0 && item_size + next_item_size <= bin_capacity { -14.0 } else { 8.0 };
        score += 20.0 + poor_fit_pressure + lookahead_penalty
            + 0.05 * (mean_residual.max(0.0))
            - 10.0 * (1.0 - step_index as f64 / total_items.max(1) as f64);
    }

    // Time horizon: late in the stream, be more conservative (prefer existing bins).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score -= 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let quad = norm_pr * norm_pr;
    let cubic = quad * norm_pr;
    score += 12.0 * cubic * progress;
    score -= 9.0 * quad * (1.0 - progress);

    // Reward tight fits more strongly as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * (1.0 + 6.0 * progress);

    // Penalize dead space relative to mean residual of open bins
    score += 0.35 * (pr as f64 - mean_residual).abs() * (0.5 + progress);

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - progress);
    }

    // Lookahead: favor bins whose post residual fits the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0 + 3.0 * progress;
    } else if next_item_size > 0 {
        score += 4.0 * progress;
    }

    // Mild pressure to consolidate when many bins are open
    score -= 0.05 * open_bins_count as f64 * (1.0 - quad);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: partition capacity into eighths.
    let eighth = bin_capacity as f64 / 8.0;
    let pr = post_residual as f64;

    // Perfect-fit class: post_residual in {0} is ideal.
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // Class of the leftover: which harmonic slot does it fall in?
        let slot = (pr / eighth).floor(); // 0..=7
        match slot as u32 {
            0 => score -= 25.0,            // tiny dead space, nearly full bin
            1 => score -= 12.0,            // small leftover, still useful-ish
            2 => score -= 4.0,             // quarter leftover
            3 => score += 2.0,             // awkward 3/8..1/2 zone
            4 => score += 0.0,             // half leftover: neutral
            5 => score += 3.0,             // awkward zone
            6 => score -= 2.0,             // 3/4 leftover: very reusable
            _ => score += 1.0,             // mostly-empty bin, nearly a new bin
        }
    }

    // Modulo-10 class of post_residual: residues that pair with common item sizes.
    let pr_mod10 = post_residual % 10;
    if pr_mod10 == 0 {
        score -= 8.0; // multiple of 10: aligns with typical item sizes
    } else if pr_mod10 <= 3 {
        score += 6.0; // tiny unusable sliver
    }

    // Integer-division thresholds on post_residual vs next item.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if post_residual >= next_item_size {
            // Can chain the next item: reward, scaled by leftover after chaining.
            let chain_left = post_residual - next_item_size;
            score -= 10.0 + (chain_left as f64) * 0.05;
            if chain_left % 10 == 0 && chain_left > 0 {
                score -= 4.0;
            }
        } else {
            // Next item won't fit here: penalize leaving this gap.
            score += 5.0 + n * 0.05;
        }
        // Dead-space coupling: gap in (0, next) is pure waste.
        if post_residual > 0 && post_residual < next_item_size {
            score += 12.0;
        }
    } else {
        // Last item: prefer tightest fit strongly.
        score -= 30.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate: make it moderately unattractive unless residuals are tight.
    if bin_residual == bin_capacity {
        score += 15.0 + (open_bins_count as f64).sqrt() * 2.0;
        // If mean residual is large, opening new bins is wasteful.
        score += mean_residual * 0.3;
    }

    // Mild pressure toward filling existing bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 3.0;

    // Prefer bins below mean residual (filling emptier bins keeps big gaps alive).
    score -= (mean_residual - pr) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // later are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // unusable dead space
    } else if post_residual < 20 {
        score += 15.0; // barely usable
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 100.0;
    }

    // If the next item fits exactly into the post residual, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
        // extra reward for exact fit of the lookahead item
        if post_residual == next_item_size {
            score -= 20.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // lookahead cannot use this bin's leftover: mild penalty
        score += 8.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: penalize creating more bins when many are open.
    if bin_residual == bin_capacity {
        // new-bin candidate: penalize proportionally to open bins and mean residual
        score += open_bins_count as f64 * 5.0 + mean_residual * 0.5;
        // if the item would leave a large residual in a fresh bin, extra penalty
        score += (post_residual as f64) * 0.3;
        // if no open bin fits at all, allow new bin
        if fitting_bins_count == 0 {
            score -= open_bins_count as f64 * 5.0 + 10.0;
        }
    } else {
        // using an existing bin relieves open-bin pressure slightly
        score -= open_bins_count as f64 * 0.5;
    }

    // Early in the stream, be more willing to open bins for large items.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= (1.0 - progress) * 10.0;
    }

    // Prefer bins whose residual is close to the item (tight fit).
    score += (bin_residual as f64 - item_size as f64).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward: leaving zero residual is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if the next item exactly fills the post_residual,
    // strongly favor this bin (perfect chain).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 500.0;
    }
    // If next item fits into post_residual, mild reward proportional to tightness.
    else if next_item_size > 0 && next_item_size <= post_residual {
        let fill_next = next_item_size as f64 / post_residual as f64;
        score -= 150.0 * fill_next;
    }
    // If next item cannot use the leftover space, penalize creating dead space,
    // especially when the leftover is small (unusable sliver).
    else if next_item_size > 0 && post_residual < next_item_size {
        let sliver = post_residual as f64 / bin_capacity as f64;
        score += 80.0 * (1.0 - sliver);
    }

    // Compare post_residual against mean residual: prefer bins that end up
    // tighter than average (concentrating usage), penalize spreading.
    if post_residual as f64 > mean_residual {
        score += 0.5 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.3 * (mean_residual - post_residual as f64);
    }

    // Last-chance bin: if this is the only bin that fits the item, using it
    // avoids opening a new bin.
    if fitting_bins_count == 1 {
        score -= 200.0;
    }

    // Prefer filling existing bins over opening new ones as stream progresses
    // and when many bins are open.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 0.2 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // New-bin candidate: make it unattractive unless it would be a very tight
    // long-term host (large item relative to capacity).
    if bin_residual == bin_capacity {
        score += 120.0 - 0.8 * item_size as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) more strongly as fit gets tighter.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio) * 8.0;

    // Penalize dead space that is too small for typical items (unusable gap).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 6.0;
    }

    // Lookahead: reward leaving room for the next item exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0; // perfect pairing
        } else if post_residual >= next_item_size {
            score -= 5.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            score += 4.0; // next item won't fit here anyway
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Prefer fuller bins when many bins are open (consolidation pressure).
    let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill * open_bins_count as f64 * 0.5;

    // Global state coupling: penalize bins whose residual deviates from the mean
    // when this bin is anomalously large (hoarding space).
    let dev = bin_residual as f64 - mean_residual;
    if dev > 0.0 {
        score += dev * 0.15;
    } else {
        score += dev * 0.05;
    }

    // Time horizon: early in the stream, be more willing to open new bins
    // (keep flexibility); late in the stream, pack tightly into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: open early when few bins exist, penalize heavily late.
        score += 12.0 * (1.0 - progress) - 18.0 * progress;
        if open_bins_count == 0 {
            score -= 100.0; // must open first bin
        }
    } else {
        score -= 6.0 * progress * fill;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: tight fit is good (low post residual preferred)
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early in the stream, dead space is cheap; late, it is expensive.
    let p2 = progress * progress;
    let p3 = p2 * progress;
    let dead_penalty = post * post / cap * (0.5 + 2.5 * p2 + 2.0 * p3);
    score += dead_penalty;

    // Reward near-perfect fits smoothly (quadratic trough at post ~ 0)
    let tightness = 1.0 - (post / cap);
    score -= 12.0 * tightness * tightness * tightness;

    // Lookahead coupling: reward residual that can host the next item,
    // penalize residuals just barely unable to fit it (smoothly).
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let gap = post - n;
        if gap >= 0.0 {
            // usable for next item: mild reward, stronger if gap small
            score -= 8.0 * (1.0 - gap / cap) * (1.0 - gap / cap);
        } else {
            // unusable dead space relative to lookahead: smooth penalty
            score += 3.0 * (gap / cap) * (gap / cap) * cap * 0.1 + 2.0 * (-gap / cap);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Mild pressure to consolidate when many bins are open
    score += 0.4 * open_bins_count as f64 * (post / cap);

    // Prefer bins whose residual deviates from mean toward small (consolidation)
    score += 0.15 * (mean_residual - post).abs().sqrt() * 10.0 * p2;

    // New-bin candidate: penalize opening a new bin unless it beats consolidation
    if bin_residual == bin_capacity {
        score += cap * (1.2 + 0.8 * progress) + 10.0 * fitting_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: modulo classes on capacity fractions.
    // Residuals divisible by 25 (quarter-capacity classes) are highly reusable.
    let q = post_residual / 25;
    let r = post_residual % 25;
    score -= (q as f64) * 3.0;           // reward quarter-aligned residuals
    score += (r as f64) * 0.35;          // penalize misaligned dead space

    // Integer-division thresholds: residuals < 10 are near-useless dead space.
    if post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Coupling with next item: if the next item fits exactly or snugly, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 30.0;
        } else if slack < 10 {
            score -= 15.0;
        } else {
            score -= 4.0;
        }
        // harmonic class match: next item size in same quarter class as residual
        if next_item_size / 25 == post_residual / 25 {
            score -= 6.0;
        }
    } else if next_item_size > post_residual {
        // next item cannot use this residual: mild penalty scaled by leftover size
        score += (post_residual as f64) * 0.15;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: only open a new bin when current residuals are poor.
    if bin_residual == bin_capacity {
        let avg_fit = mean_residual;
        if avg_fit < 25.0 {
            score -= 20.0; // open fresh bin when open bins are fragmented
        } else {
            score += 15.0; // prefer reusing decent open bins
        }
    }

    // Stream progression: later in the stream, be more conservative with new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += progress * 10.0;
    }

    // Tight fit bonus: item fills most of the bin.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fill_ratio > 0.9 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    if post_residual > 0 {
        // A gap is "unusable" if it's smaller than the smallest plausible item (1..100 range).
        // Treat gaps below a threshold as pure waste, escalating nonlinearly.
        let dead_threshold = 10.0f64.min(bin_capacity as f64 * 0.1);
        if (post_residual as f64) < dead_threshold {
            score += (dead_threshold - post_residual as f64).powf(2.0) * 8.0;
        }
        // Moderate penalty for gaps that can't fit the lookahead item either.
        if next_item_size > 0 && post_residual < next_item_size {
            score += 12.0 + (next_item_size - post_residual) as f64 * 0.5;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 25.0;
    }

    // Reward tight fits: fraction of bin consumed.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= fill_ratio * 10.0;

    // Last-chance pressure: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless post-residual is terrible dead space).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: penalize opening new bins when many bins are already open,
    // encouraging consolidation into existing bins.
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline cost plus pressure from open bins.
        score += 30.0 + (open_bins_count as f64 * 2.0);
        // Late in the stream, opening a new bin is cheaper than fragmenting.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 15.0;
        // If the new bin can also host the lookahead item, it's more attractive.
        if next_item_size > 0 && bin_capacity >= next_item_size {
            score -= 5.0;
        }
    } else {
        // Existing bin: mild bonus for keeping bin count down.
        score -= 5.0;
        // Prefer bins with residual below the mean (tighter bins first).
        score += (mean_residual - bin_residual as f64) * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: after placing this item, the next item
    // exactly fills the bin. Strongly reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Next item fits into post_residual (chainable bin): reward proportionally.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Dead space relative to the lookahead item: penalize the gap.
        let gap = (next_item_size - post_residual) as f64;
        score += 1.5 * gap;
    }

    // Penalize post_residual far above the mean residual (wasteful bin usage).
    score += 0.5 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin (only fitting bin): strongly favor using it over a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Mild reward for tightening bins when many bins are open.
    score -= 0.3 * open_bins_count as f64 * (item_size as f64 / bin_capacity as f64);

    // Prefer opening a new bin only when this item is huge and no open bin is tight.
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - item_size as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post residual).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        // Dead space below the minimum item size is nearly unusable.
        score -= 25.0;
    }

    // Lookahead: reward bins whose post-residual can still host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0;
        let slack = (post_residual - next_item_size) as f64;
        score -= 8.0 * (1.0 - slack / (bin_capacity as f64));
    } else if next_item_size > 0 && post_residual > 0 {
        // Post-residual exists but next item won't fit: mild penalty unless
        // the leftover is small enough to be dead space anyway.
        if post_residual >= 10 {
            score += 6.0;
        }
    }

    // Last-chance bonus: this is the only bin that can fit the item.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Penalize spreading across too many open bins (fragmentation control),
    // but relax this penalty as the stream progresses.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize opening a new bin, more strongly early on
        // and when many bins are already open.
        score += 55.0 + 12.0 * (open_bins_count as f64).ln().max(0.0);
        score -= 30.0 * progress;
        // If no open bin fits (this call is the only candidate), allow opening.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // If the next item is large, a fresh bin is more attractive.
        if next_item_size >= item_size {
            score -= 10.0;
        }
    } else {
        // Reward using already-open bins, scaled by how full they already are.
        let fill = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
        score -= 15.0 * fill;
    }

    // Global state coupling: prefer bins below the mean residual when the mean
    // is high (many large gaps), and above it when the mean is low.
    let dev = (bin_residual as f64 - mean_residual) / (bin_capacity as f64);
    score += 10.0 * dev;

    // Late-stream: consolidate aggressively, prefer bins that will be left
    // with minimal waste regardless of lookahead.
    if progress > 0.7 {
        score += 20.0 * (post_residual as f64) / (bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Base: penalize leftover space, with a super-linear (quadratic) dead-space penalty.
    let norm_post = post / cap;
    let mut score = norm_post + 2.5 * norm_post * norm_post;

    // Smooth non-linear coupling of dead space with stream progress:
    // late in the stream, wasted space is more costly.
    let late = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score += 6.0 * late * norm_post * (post / cap);

    // Reward tight fits: small post_residual gets a cubic discount.
    score -= 4.0 * (1.0 - norm_post).powi(3);

    // Lookahead: penalize if post_residual cannot fit the next item,
    // reward if it fits exactly-ish (leaves a useful remainder).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            // next item fits here: reward, stronger early when slack matters
            score -= 2.0 * (nxt / cap) * (1.0 - 0.5 * late);
            // prefer leaving a remainder that is itself small (near-perfect packing)
            let rem = (post - nxt) / cap;
            score -= 1.5 * (1.0 - rem).powi(2);
        } else {
            // next item won't fit: penalize proportionally to the shortfall
            let gap = (nxt - post) / cap;
            score += 3.0 * gap * (0.5 + late);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 8.0;
    } else if fitting_bins_count > 1 {
        // mild competition penalty to prefer bins with fewer alternatives? keep neutral
        score += 0.5 * ((fitting_bins_count as f64 - 1.0).ln());
    }

    // New-bin candidate handling: it has bin_residual == bin_capacity (post == cap).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Opening a new bin is only attractive when no existing bin fits well.
        // Penalize new bins normally; relax if this is the only fitting option.
        let base = 4.0 + 6.0 * late;
        if fitting_bins_count == 0 {
            score -= base; // forced fallback: neutralize the dead-space penalty
        } else {
            score += base * (1.0 - item / cap);
        }
    }

    // Mild preference for bins whose residual deviates from the mean
    // (consolidate waste in a few bins rather than spreading it).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 0.75 * dev * dev - 0.5 * dev;

    // Small early-stream bonus for using existing bins to keep many bins open
    // (classic diversity preservation), decaying smoothly with progress.
    score -= 1.0 * (1.0 - late) / (1.0 + open_bins_count as f64).ln();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongest reward.
    if post_residual == 0 {
        score -= 500.0;
    }

    // Harmonic class of post_residual: dead space below the smallest item
    // (1..=10) is unusable; penalize it hard.
    if post_residual < 10 && post_residual > 0 {
        score += 60.0;
    }

    // Modulo-class logic on post_residual: residuals that are multiples of
    // common small item sizes (10, 20, 25, 50) remain "harmonically usable".
    let harmonic = (post_residual % 10 == 0) || (post_residual % 25 == 0) || (post_residual % 50 == 0);
    if harmonic {
        score -= 25.0;
    } else {
        // Odd residuals waste potential; penalize proportional to distance
        // from the nearest multiple of 10.
        let dist = (10 - (post_residual % 10)) as f64;
        score += 3.0 * dist;
    }

    // Integer-division threshold: post_residual / 10 gives how many
    // "unit-10 slots" remain. Fewer slots = worse bin.
    let slots = post_residual / 10;
    if slots <= 1 {
        score += 20.0;
    } else if slots >= 5 {
        score -= 10.0;
    }

    // Lookahead coupling: does the next item fit harmonically here?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Reward if next item exactly consumes a harmonic class remainder.
            if post_residual % next_item_size.max(1) == 0 {
                score -= 40.0;
            } else {
                score -= 10.0;
            }
        } else {
            // Next item cannot follow into this bin: penalize by overflow gap.
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate (empty bin): only attractive when current bin's
    // post-fit residual is poor (small slots or dead space).
    if bin_residual == bin_capacity {
        let poor_fit = (post_residual < 10) || (slots <= 1) || (fitting_bins_count <= 1 && post_residual > 40);
        if poor_fit {
            score -= 30.0;
        } else {
            score += 40.0;
        }
    }

    // Stream progression: late in the stream, prefer tight packing of
    // existing bins over opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score -= 15.0 * progress;
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.05 * open_bins_count as f64;

    // Keep near mean residual to spread fill evenly across bins.
    score += 0.1 * (post_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero gaps are unusable -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64) / 10.0;
    }
    // Perfect fit rewarded strongly.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual >= 10 {
        // Residual that can still host the smallest item is mildly rewarded.
        score -= 5.0;
    }

    // Open-bin pressure: discourage proliferating bins.
    score += open_bins_count as f64 * 1.5;

    // Last chance: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a new bin.
        score += 30.0 + open_bins_count as f64 * 2.0;
        // If this item is the only fitter, opening a new bin is fine.
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    } else {
        // Prefer bins whose residual is close to the item (tight fit).
        let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
        score += tightness * 20.0;
    }

    // Lookahead: if next item would fit the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If next item is large and post-residual is a small dead gap, penalize more.
    if next_item_size > post_residual as u32 && post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Mean residual coupling: when open bins are generally full, avoid waste.
    score += (mean_residual - post_residual as f64) * 0.1;

    // Late in stream: be more conservative, prefer tight existing placements.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size exactly.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += diff * 0.8;                       // penalize mismatch with next item
        if post_residual == next_item_size {
            score -= 25.0;                          // perfect 2-step chain: place here
        }
        if post_residual >= next_item_size && post_residual <= next_item_size + 10 {
            score -= 8.0;                           // near-perfect chain
        }
        // Penalize dead space that neither current nor next item can ever use later
        if post_residual < next_item_size && post_residual < 10 {
            score += 15.0;
        }
    }

    // Prefer tight fits relative to mean residual of open bins.
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Penalize wasting a nearly-empty large-residual bin on a small item when many bins are open
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when existing bins would leave big unusable gaps
        let waste = post_residual as f64;
        score += 12.0 - waste * 0.05 + (open_bins_count as f64) * 1.5;
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 10.0; // opening fresh bin still forms perfect chain
        }
    } else {
        // Favor bins with small residual before placement (tight packing)
        score += (bin_residual as f64) * 0.1;
    }

    // Late in stream, be more conservative: keep bins reusable
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near zero is ideal.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 40.0;

    // Penalize dead space that becomes unusable (below minimum item size 1..=100 unknown, use capacity fraction).
    let dead = post_residual as f64 / bin_capacity as f64;
    if dead > 0.0 && dead < 0.1 {
        score += 25.0 * (0.1 - dead) * 10.0;
    }

    // Last chance: strongly favor using this bin if it is the only one that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Lookahead: if next item fits in post_residual, bonus; otherwise penalize wasting large residual.
    if next_item_size > 0 {
        if (next_item_size as u32) <= post_residual {
            score -= 15.0;
        } else {
            score += 8.0;
        }
    }

    // New-bin candidate: only attractive when open bins fit poorly.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Penalize opening new bins generally; scale with stream progression and open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 + 20.0 * progress + 0.5 * open_bins_count as f64;
        // If item is large relative to capacity, a fresh bin is more reasonable.
        score -= 20.0 * (item_size as f64 / bin_capacity as f64);
        // If mean residual is high, prefer reusing existing bins.
        score += mean_residual * 0.3;
    } else {
        // Slight preference for filling fuller bins (smaller residual) first.
        score += 0.1 * (bin_residual as f64 - mean_residual);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: prefer tight fits via non-linear post-residual shaping
    let mut score = pr_norm * (1.0 + 2.0 * pr_norm * pr_norm);

    // Smooth polynomial coupling with stream progress:
    // early on, tolerate larger residuals; later, penalize them more strongly
    let progress_coupling = 1.0 + 1.5 * progress * progress + 2.0 * progress * pr_norm;
    score *= progress_coupling;

    // Reward bins whose residual exactly accommodates the next item (lookahead)
    if next_item_size > 0 && post_residual as u64 == next_item_size as u64 {
        score -= 2.5;
    } else if next_item_size > 0 {
        let gap = (post_residual as f64 - next_item_size as f64).abs() / cap;
        score += 0.5 * gap * gap;
    }

    // Penalize dead space relative to mean residual across open bins (smooth quadratic)
    let dev = pr_norm - mean_residual / cap;
    score += 0.3 * dev * dev;

    // Last-chance bonus: strongly favor using the only fitting bin (smooth in fitting count)
    if fitting_bins_count <= 1 {
        score -= 1.2;
    } else {
        score += 0.1 * (fitting_bins_count as f64 - 1.0);
    }

    // Mild preference for consolidating into fewer bins
    score += 0.02 * open_bins_count as f64 * pr_norm;

    // New-bin candidate: penalize slightly so it only wins when fits are poor
    if bin_residual == bin_capacity {
        score += 0.8 + 1.5 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: extremely strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Tight-fit reward: penalize residual waste quadratically.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Harmonic classes: bins whose post_residual falls into "usable" residue
    // classes (multiples of 10 / small residues matching typical item sizes)
    // are more valuable; keep them attractive.
    let pr = post_residual;
    if pr % 10 == 0 && pr > 0 {
        score -= 8.0; // residue class aligned with common item granularity
    }
    if pr >= 10 && pr <= 20 {
        score -= 5.0; // small but still fillable residual zone
    }
    if pr > 0 && pr < 10 {
        score += 25.0; // dead space: nearly unusable residue class
    }

    // Integer division threshold on post_residual: how many average-size
    // items (>=10) could still fit? More divisibility => keep bin open.
    let slots = (pr / 10) as f64;
    score -= slots * 4.0;

    // Lookahead coupling: if next item fits exactly in the post residual,
    // strongly favor this bin (chained perfect packing).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 300.0;
        } else if next_item_size <= pr {
            score -= 20.0;
        } else {
            // next item won't fit here; mild penalty if it leaves this bin stranded
            score += 6.0;
        }
        // Harmonic check: next item size in same decade class as post residual
        if next_item_size > 0 && pr > 0 && (pr / 10) == (next_item_size / 10) {
            score -= 10.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Prefer using existing bins unless the current fit is poor.
        // A new bin is only attractive when the item is large relative to
        // the best possible fit or there are no real alternatives.
        if fitting_bins_count == 0 {
            score -= 500.0; // must open a new bin
        } else {
            // Penalize new bin when existing bins fit decently
            score += 90.0;
            // But if item is large (>60) and post_residual would be tiny
            // in this fresh bin, opening new bin may be fine: slight relief
            if item_size >= 60 {
                score -= 30.0;
            }
        }
    }

    // Stream progression: early in the stream, be more liberal with new bins
    // to build a good residual landscape; later, consolidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score -= progress * 10.0;
    }

    // Mean residual coupling: if this bin's residual is far below the mean,
    // it is an outlier small-space bin; prefer filling it to close it out.
    let diff = mean_residual - bin_residual as f64;
    if diff > 0.0 {
        score -= diff * 1.5;
    }

    // Open bins count: many open bins -> encourage consolidation into
    // existing bins rather than opening more.
    if bin_residual != bin_capacity {
        score -= (open_bins_count as f64) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small for any
    // plausible item (<= 10) are effectively wasted; penalize hard.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Reward near-perfect fits strongly (subtractive).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Open-bins pressure: when many bins are open, prefer consolidating
    // into existing bins (penalize opening a new one).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to open bin count
        // and stream progress; allow it only if open bins are few or
        // the item would leave a large dead gap elsewhere.
        score += 25.0 + 3.0 * open_bins_count as f64 + 20.0 * progress;
        // If this is the last-chance bin, opening a new bin is bad.
        if fitting_bins_count <= 1 {
            score += 30.0;
        }
    } else {
        // Reward using existing bins, more so as bins accumulate.
        score -= 2.0 * (open_bins_count as f64).min(15.0);
        // Last-chance bonus: strongly prefer the only bin that fits.
        if fitting_bins_count == 1 {
            score -= 35.0;
        }
    }

    // Mean-residual coupling: if the average open residual is large,
    // packing into existing bins is cheap; tighten preference.
    score -= 0.5 * mean_residual;

    // Lookahead: if the next item fits exactly in the post residual,
    // reward this placement (chaining).
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 25.0;
        } else if gap < 10 {
            score -= 10.0;
        } else {
            score += 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact-ish fits (small dead space).
    if post_residual < 10 {
        score -= 25.0;
    } else if post_residual < 20 {
        score -= 10.0;
    }

    // 2-step lookahead: if next item fits into the post residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack_after_next = post_residual - next_item_size;
        score -= 18.0 - 0.15 * slack_after_next as f64;
        // Perfect chain: item then next item exactly fills the bin.
        if slack_after_next < 5 {
            score -= 15.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here; penalize leaving residual that only
        // wastes capacity unless it is near-full.
        if post_residual >= 30 {
            score += 8.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Compare against mean residual: bins tighter than average are better targets.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Relative tightness of the fit.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 10.0 * tightness;

    // New-bin candidate: only attractive when nothing fits well or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit = post_residual as f64 > 40.0 || next_item_size > post_residual;
        if poor_fit && progress > 0.05 {
            score -= 5.0; // allow opening a new bin for poor fits
        } else {
            score += 40.0; // discourage wasting fresh bins on good fits
        }
    }

    // Mild preference for keeping the number of open bins low late in stream.
    score += 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual small relative to item size.
    if item_size > 0 {
        score -= (item_size as f64) * (1.0 - post_residual as f64 / bin_capacity as f64) * 0.5;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Penalize dead space that no plausible item can fill (items >= 1, but typical >= 10).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead coupling: if next item fits into the post residual, reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0 + 0.1 * next_item_size as f64;
    } else if next_item_size > post_residual && next_item_size > bin_residual {
        // Next item won't fit anywhere in this bin even before placement; mild penalty.
        score += 3.0;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Many open bins: prefer filling existing ones over opening new.
    score += (open_bins_count as f64) * 0.5;

    // Time horizon: later in the stream, be greedier about tight fits.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.3 * progress;

    // Relative residual vs mean: bins with below-average residual are more "committed", prefer them.
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate: make empty bins attractive only when existing fits are poor.
    if bin_residual == bin_capacity {
        score += 10.0 + (mean_residual * 0.2);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr;

    // Smooth interaction: large residuals become more valuable as stream progresses
    score -= 18.0 * norm_pr * norm_pr * (0.5 + 0.5 * progress);
    score += 10.0 * norm_pr * (1.0 - progress);

    // Penalize dead space (residual too small to be useful later), smoothly
    let deadness = (1.0 - norm_pr).powi(3);
    score += 14.0 * deadness * (0.4 + 0.6 * progress);

    // Lookahead coupling: reward residual that can host next item, smoothly
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if pr >= ns {
            let fit_quality = 1.0 - ((pr - ns) / cap).abs();
            score -= 12.0 * fit_quality * fit_quality;
        } else {
            score += 8.0 * (ns - pr) / cap;
        }
    }

    // Last-chance bin: reward using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0 * (0.5 + 0.5 * progress);
    }

    // Mean residual coupling: prefer bins deviating from mean smoothly
    let dev = (pr - mean_residual) / cap;
    score += 6.0 * dev * dev * progress;

    // Mild penalty for opening new bins when many are open
    if bin_residual == bin_capacity {
        score += 5.0 + 3.0 * (open_bins_count as f64).sqrt() * (0.5 + 0.5 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward near-perfect fits: post_residual in low harmonic classes.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 10.0;
    }

    // Dead-space penalty: residuals that few future items (min size 1..100) can use.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // unusable sliver
    }

    // Harmonic class of post_residual: multiples of common item sizes are reusable.
    let pr = post_residual;
    if pr % 10 == 0 && pr > 0 {
        score -= 5.0; // residual aligns with decile classes
    }

    // Lookahead: reward if next item fits exactly or well into post_residual.
    if next_item_size > 0 && next_item_size <= pr {
        let diff = pr - next_item_size;
        if diff == 0 {
            score -= 40.0;
        } else if diff <= 10 {
            score -= 15.0;
        } else {
            score -= 5.0;
        }
    } else if next_item_size > pr && next_item_size > 0 {
        score += 8.0; // next item won't fit here; keep space elsewhere flexible
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: neutral baseline, open new bin only when fits are poor.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 0.55; // ~55 baseline
        if fitting_bins_count == 0 {
            score -= 30.0; // no open bin fits: must open
        } else if fitting_bins_count == 1 {
            score += 15.0; // avoid abandoning last-chance bin
        }
        // Late in stream, prefer closing out open bins rather than spreading.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * (1.0 - progress);
        return score;
    }

    // Prefer fuller bins when many bins are open (consolidation pressure).
    score += (mean_residual - post_residual as f64) * 0.3;
    if open_bins_count > 4 {
        score -= 3.0;
    }

    // Fraction-of-capacity coupling: penalize leaving > half capacity wasted.
    if post_residual as f64 > bin_capacity as f64 * 0.5 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Hard penalty for tiny unusable gaps (dead space zone 1..12)
    if post_residual > 0 && post_residual < 12 {
        score += (12.0 - post_residual as f64) * 8.0;
    }
    // Perfect fit bonus
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward leaving room for the lookahead item when it fits the post residual
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }
    // Penalize when next item would be stranded by this placement's dead space
    if next_item_size > 0 && next_item_size > post_residual && post_residual < next_item_size.min(12) {
        score += 15.0;
    }

    // Open-bin pressure: discourage spreading across many bins; makes new bin
    // candidate (large post_residual) less attractive unless fits are terrible.
    score += open_bins_count as f64 * 0.35;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Slight preference for tighter bins overall (small residual before placement)
    score -= (bin_capacity as f64 - bin_residual as f64) * 0.1;

    // Mild stream-phase scaling of dead-space penalty (late stream: be greedier)
    let phase = step_index as f64 / (total_items.max(1) as f64);
    score -= phase * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Dead space: post residual too small for the next item (wasted unless future items are tiny).
    if next_item_size > 0 && post_residual < next_item_size {
        let waste = (next_item_size - post_residual) as f64;
        score += 0.8 * waste;
    }

    // Reward bins tighter than the mean residual (good consolidation).
    let tightness = mean_residual - bin_residual as f64;
    score += 0.35 * tightness;

    // Penalize very small post residual (fragmentation), but less if it's a perfect-fit situation.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Early in stream: mild preference for filling existing bins rather than spreading.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 4.0;

    // New-bin candidate: only attractive when no open bin fits well (residual-based tie-break).
    if bin_residual == bin_capacity {
        score += 18.0;
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: squared penalty on wasted space.
    let waste = post_residual as f64;
    score += 0.35 * waste * waste / bin_capacity as f64;

    // Lookahead: strongly reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0 + 0.25 * (post_residual - next_item_size) as f64;
    } else if next_item_size > 0 {
        // Penalize leaving a gap the next item just barely misses.
        score += 0.5 * (next_item_size as f64 - post_residual as f64).min(30.0);
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Perfect fit extreme reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Discourage fragmenting bins that still have lots of room when many bins are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if post_residual as f64 > mean_residual {
        score += 6.0 * (1.0 - progress);
    }

    // New-bin candidate: base handicap so it only wins when open bins fit badly.
    if bin_residual == bin_capacity {
        score += 30.0;
        // Open a new bin early in the stream when item is large (keeps big residual flexible).
        if item_size >= 60 && progress < 0.5 {
            score -= 35.0;
        }
        // Late in stream, prefer filling existing bins.
        if progress > 0.8 {
            score += 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let post_norm = post / cap;
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = post_norm * post_norm * (1.0 - post_norm);
    score += 40.0 * poly * (0.5 + progress);

    // Reward tight fits, stronger as stream progresses
    score -= (1.0 - post_norm) * (1.0 - post_norm) * (10.0 + 20.0 * progress);

    // Last-chance bonus: only bin that fits
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Penalize opening new bins when open bins fit well
    if bin_residual == bin_capacity {
        score += 15.0 + 10.0 * (1.0 - progress) - 0.5 * open_bins_count as f64;
    }

    // Lookahead: favor leaving space for next item
    let nxt = next_item_size as f64;
    if nxt > 0.0 {
        let gap = post - nxt;
        if gap >= 0.0 {
            score -= 8.0 * (1.0 - (gap / cap)).exp();
        } else {
            score += 0.05 * (-gap);
        }
    }

    // Mean residual coupling: prefer bins deviating below mean residual (denser bins)
    score += 0.3 * (post - mean_residual).abs() * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: capacity divided into 10 classes of 10.
    let post_class = post_residual / 10;
    // Dead space penalty grows super-linearly for small unusable remainders.
    if post_residual > 0 {
        let dead = post_residual as f64;
        let usable_by_next = (next_item_size > 0 && next_item_size <= post_residual) as u32;
        if usable_by_next == 0 {
            score += dead * dead / 40.0; // strongly punish unfillable gaps
        } else {
            score -= 6.0; // reward leaving room for the lookahead item
        }
    } else {
        score -= 12.0; // perfect closure
    }

    // Modulo-arithmetic coupling: residuals that are multiples of common item
    // sizes (10, 20, 25, 50) are more likely to be filled exactly later.
    let r = post_residual;
    if r % 50 == 0 {
        score -= 4.0;
    } else if r % 25 == 0 {
        score -= 2.5;
    } else if r % 10 == 0 {
        score -= 1.5;
    } else {
        score += 1.0; // awkward non-harmonic remainder
    }

    // Integer-division threshold: if next item also fits with harmonic remainder,
    // chain bonus.
    if next_item_size > 0 && next_item_size <= post_residual {
        let chain = post_residual - next_item_size;
        if chain % 10 == 0 {
            score -= 3.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity && bin_capacity > 0;
    if is_new_bin {
        // Base penalty so we prefer existing bins; relax late in the stream or
        // when many bins are open and mean residual is large (fragmentation).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut pen = 10.0 + post_residual as f64 * 0.5;
        if mean_residual > 40.0 && open_bins_count > 2 {
            pen -= 4.0;
        }
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            pen -= 3.0; // big lookahead: fresh bin gives clean space
        }
        let _ = progress;
        score += pen;
    }

    // Slight preference for tighter bins overall (small residual before placement).
    score += bin_residual as f64 * 0.05;
    // Mild exploration term tied to stream position.
    score += (step_index % 7) as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the smallest plausible item are wasted.
    let dead_threshold = 10u32.min(bin_capacity / 10);
    if post_residual < dead_threshold && post_residual > 0 {
        // Unusable sliver: strong penalty proportional to how much capacity is locked away.
        score += 40.0 + (dead_threshold - post_residual) as f64 * 3.0;
    } else if post_residual > 0 {
        // Perfect or near-perfect fit reward.
        let tightness = post_residual as f64 / bin_capacity as f64;
        score -= (1.0 - tightness) * 15.0;
    }

    // Penalize gaps that cannot fit the known next item (lookahead-aware dead space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0 + (next_item_size - post_residual) as f64 * 0.5;
    }
    // Reward gaps that can still host the next item (keeps bin useful).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage opening new bins when open bins already exist.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            score += 30.0 + open_bins_count as f64 * 2.0;
        } else {
            score -= 20.0;
        }
    } else {
        // Reusing an existing bin reduces fragmentation pressure; reward modestly.
        score -= 3.0;
        // Prefer bins with below-average residual (tighter bins first, best-fit style).
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        } else {
            score += 2.0;
        }
    }

    // Late in the stream, consolidation matters more: extra penalty for new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 15.0;
    } else {
        score -= progress * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // exactly (or closely) matches the next item's size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match for the next item: huge reward.
        if post_residual == next_item_size {
            score -= 60.0;
        } else {
            score += 0.6 * diff;
        }
        // Penalize post_residuals that are too small to fit the next item
        // (dead space), unless post_residual is 0 (perfect closure).
        if post_residual > 0 && post_residual < next_item_size {
            score += 0.35 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: prefer closing the bin completely.
        if post_residual == 0 {
            score -= 50.0;
        }
    }

    // Relative-to-mean coupling: prefer bins tighter than average residual.
    score += 0.25 * (bin_residual as f64 - mean_residual);

    // Tight fits get a bonus proportional to fill ratio.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill;

    // Last-chance bin: strong penalty to avoid wasting the only fitting bin
    // on a mediocre fit, but reward if the fit is very tight.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        let waste = post_residual as f64;
        if waste > 0.0 {
            score += 12.0;
        }
        if post_residual == 0 {
            score -= 30.0;
        }
    }

    // New-bin candidate: penalize so we only open a new bin when all
    // open bins would leave large dead space.
    if bin_residual == bin_capacity {
        score += 18.0;
        // But if next item exactly matches a fresh bin minus current item,
        // allow opening (rare strategic opening).
        if next_item_size > 0 && bin_capacity - item_size == next_item_size {
            score -= 25.0;
        }
    }

    // Late in the stream, tighten up: discourage leaving many open bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 8.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where post_residual is small.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 6.0 * tightness * tightness;

    // Penalize large wasted residual relative to mean residual of open bins.
    if post_residual as f64 > mean_residual {
        score += 0.5 * (post_residual as f64 - mean_residual);
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // Lookahead: penalize placements that leave residual incompatible with next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Good: next item can also fit here.
            score -= 3.0 * (next_item_size as f64 / bin_capacity as f64);
        } else {
            // Bad: dead space the next item cannot use.
            score += 0.6 * (post_residual as f64 * post_residual as f64) / (bin_capacity as f64 * bin_capacity as f64) * 10.0;
        }
        // Exact two-item fill is ideal.
        if post_residual == next_item_size {
            score -= 4.0;
        }
    }

    // New-bin candidate handling: only open a new bin when existing fits are poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin.
        score += 14.0;
        // More open bins -> higher cost of yet another bin.
        score += 0.4 * open_bins_count as f64;
        // Early in stream, opening bins is cheaper (build flexibility).
        let progress = step_index as f64 / (total_items as f64).max(1.0);
        score -= 10.0 * (1.0 - progress);
        // If next item is large and current fit leaves tiny residue, new bin is fine.
        if next_item_size >= item_size && post_residual < next_item_size {
            score -= 5.0;
        }
    } else {
        // Slight preference to reuse bins rather than proliferate.
        score -= 0.1 * open_bins_count as f64;
    }

    // Late-stream consolidation: penalize leaving scattered residuals when near the end.
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    if progress > 0.8 {
        score += 2.0 * progress * (post_residual as f64 / bin_capacity as f64);
    }

    // Small per-candidate noise-free regularizer toward exact fills.
    if post_residual == 0 {
        score -= 10.0;
    }
    if post_residual < 10 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let pr2 = norm_pr * norm_pr;
    let pr3 = pr2 * norm_pr;
    let p = progress;
    let p2 = p * p;

    // Base polynomial: dead space penalized more as stream progresses.
    score += 18.0 * pr2 * (0.4 + 0.6 * p) - 9.0 * pr3 * (0.5 + 0.5 * p);

    // Smooth interaction: tight fits (small post_residual) rewarded, amplified early.
    score -= 14.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 - 0.5 * p);

    // Cubic progress coupling with mean residual: prefer bins near mean, smoothly.
    let dev = (pr - mean_residual) / cap;
    score += 6.0 * dev * dev * (1.0 + p2) - 3.0 * dev * dev * dev;

    // Last-chance bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 - p2);
    }

    // Lookahead: reward leaving room for the next item, smoothly damped by progress.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        let gap = (pr - ni) / cap;
        if gap >= 0.0 {
            score -= 8.0 * gap * (1.0 - gap) * (1.0 - p);
        } else {
            score += 6.0 * -gap * -gap * (0.5 + p);
        }
    }

    // Mild penalty for proliferation of open bins late in the stream.
    score += 0.15 * open_bins_count as f64 * p;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the resulting residual: coarse buckets by capacity fraction.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let cls = (pr / (cap / 8.0)).floor(); // 0..=7 harmonic class

    // Reward tight fits: post_residual near zero is excellent.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 10.0;
    }

    // Penalize dead space that no future item (>=1) can use well:
    // residuals in awkward harmonic classes are worse.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0; // unusable sliver
    }
    // Class-based coupling: mid-range residuals (class 3-4) are reusable.
    score -= cls * 1.5;

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 - slack.min(20.0); // reward good lookahead fit
        } else {
            // next item cannot use this residual at all
            score += 5.0;
        }
    }

    // Last-chance logic: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin has huge residual; make it
    // attractive only when the current fit is poor or it's early with few bins.
    if bin_residual == bin_capacity {
        // base penalty so existing good fits win
        score += 15.0;
        // if item leaves a bad residual in any open bin, empty bin becomes better
        if post_residual >= 10 && post_residual < 20 {
            score -= 25.0;
        }
        if open_bins_count == 0 {
            score -= 100.0;
        }
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 10.0; // big next item benefits from fresh bin
        }
    }

    // Mild preference to consolidate into fewer bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 2.0;

    // Nudge toward bins with residuals close to what we consume (best-fit flavor).
    score += (mean_residual - bin_residual as f64).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // plausible future item (<= 10) are pure waste; penalize them hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Near-perfect fit: strong reward for closing a bin tightly.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Dead-space severity grows the fuller the bin was before placement
    // (we consumed scarce space and left an unusable sliver).
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * fill_ratio;
    }

    // Lookahead coupling: if the next item fits exactly in the post_residual,
    // reward heavily; if next item cannot fit but this bin is the only option,
    // penalize creating a gap the next item can't use.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0;
            if post_residual == next_item_size {
                score -= 35.0; // perfect lookahead fit
            }
        } else if post_residual < next_item_size {
            score += 15.0;
        }
    }

    // Last-chance pressure: if this is the only fitting bin, prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor new bin
    // only when current bin fit is poor.
    let open_pressure = open_bins_count as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive when fit elsewhere is bad or bins few.
        score -= 10.0;
        score += open_pressure * 2.0;
        if post_residual == bin_capacity {
            // empty-bin base score; keep moderate so good fits beat it
            score -= 5.0;
        }
    } else {
        // Reward reusing existing bins, scaled by how well the item fills them.
        let usage = item_size as f64 / bin_residual as f64;
        score -= 15.0 * usage;
        score -= open_pressure.min(10.0);
    }

    // Mean-residual coupling: if this bin's post-residual deviates badly from
    // the mean residual, penalize (keeps residual profile coherent).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Late-stream tightening: as the stream progresses, waste matters more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if post_residual > 0 && post_residual < 10 {
        score += 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward: post_residual exactly matches the next item (perfect 2-step chain).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Next item can also fit here later: mild reward scaled by tightness.
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 - slack * 0.3;
        } else {
            // Next item cannot use the leftover: penalize dead space proportionally.
            score += (next_item_size - post_residual) as f64 * 0.4;
        }
    }

    // Reward tight fits relative to current item.
    score -= (item_size as f64 / bin_capacity as f64) * 10.0;

    // Compare post_residual against mean residual across open bins.
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.2;
    } else {
        score -= (mean_residual - post_residual as f64) * 0.2;
    }

    // Last-chance bin: avoid opening a new bin if this is the only fitting one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize opening a new bin when open bins exist and fit is loose.
    if bin_residual == bin_capacity {
        score += 15.0 + (open_bins_count as f64) * 0.5;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0; // fresh bin is fine if next item fits too
        }
    }

    // Late in the stream: prefer packing into existing bins more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 8.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good.
    let tight = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tight * tight;

    // Penalize dead space that cannot fit the average upcoming item.
    let t = step_index as f64 / (total_items.max(1) as f64);
    if post_residual > 0 {
        let usable = if (post_residual as f64) >= mean_residual { 1.0 } else { 0.3 };
        score += (1.0 - usable) * (post_residual as f64) * 0.35;
    }

    // Lookahead: if next item fits in post_residual, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 6.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item won't chain here; mild penalty scaled by wasted space.
        score += 2.0 + 0.05 * (post_residual as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Many open bins: prefer consolidation into existing bins.
    score += 0.6 * (open_bins_count as f64).ln().max(0.0);

    // New-bin candidate handling: only attractive when residuals are fragmented
    // and this is a fresh empty bin.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        let new_bin_bonus = 4.0 + 30.0 * fragmentation * (1.0 - t);
        score = 55.0 - new_bin_bonus + 0.2 * (post_residual as f64);
        // If an existing bin fits tightly, discourage new bin.
        if fitting_bins_count > 1 && post_residual < item_size / 2 {
            score += 20.0;
        }
    }

    // Late in stream: be conservative, avoid leaving tiny unusable slivers.
    if t > 0.8 && post_residual > 0 && post_residual < 10 {
        score += 10.0 * (1.0 - t);
    }

    // Balance against mean residual: prefer bins near the mean to keep
    // residual distribution uniform for future items.
    score += 0.15 * ((post_residual as f64) - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let smooth_progress = progress * progress * (3.0 - 2.0 * progress); // smoothstep

    let mut score = pr;

    // Reward tight fits: strong bonus when post_residual is small relative to capacity.
    let tightness = 1.0 - (pr / cap);
    score -= 12.0 * tightness * tightness * (1.0 + smooth_progress);

    // Penalize dead space that likely can't hold anything: quadratic in post_residual.
    score += 0.08 * pr * pr / cap;

    // Perfect fit reward (post_residual near zero).
    if pr == 0 {
        score -= 15.0;
    }

    // Lookahead coupling: if the next item fits in the post-residual, reward;
    // if next item is large and this placement wastes space, penalize.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr as f64 {
            score -= 6.0 * (1.0 - (pr - nxt) / cap);
        } else {
            let gap = (nxt - pr) / cap;
            score += 8.0 * gap * gap;
        }
    }

    // New-bin candidate: penalize opening a new bin, more so early in the stream
    // and when other bins fit the item.
    if bin_residual == bin_capacity {
        let new_bin_penalty = 20.0 + 25.0 * (1.0 - smooth_progress) + 0.5 * open_bins_count as f64;
        score += new_bin_penalty;
        // But if no open bin fits, soften the penalty so a new bin is viable.
        if fitting_bins_count <= 1 {
            score -= 18.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // Slight preference to place into bins with low mean residual (balance load).
    score += 0.03 * (mean_residual - pr).abs();

    // Mild stream-progress pressure: late in stream, prefer filling existing bins.
    score += 4.0 * smooth_progress * (pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls into "nice"
    // residue classes (multiples of 10) tend to absorb future items cleanly.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Penalize dead space quadratically for large residuals.
    score += (pr * pr) / (2.0 * cap);

    // Reward tight fits: small post_residual gets a bonus.
    if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 15.0;
    }

    // Harmonic class: residual divisible by 10 is "harmonic" (matches common
    // item granularity), divisible by 5 semi-harmonic.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    } else if post_residual % 5 == 0 {
        score -= 3.0;
    } else {
        // Odd residues create unusable slivers; penalize proportionally.
        score += (post_residual % 5) as f64 * 1.5;
    }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // this placement is excellent.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            // Reward partial compatibility, scaled by how well next item's
            // complement also lands in a harmonic class.
            let next_left = post_residual - next_item_size;
            score -= 10.0;
            if next_left % 10 == 0 { score -= 5.0; }
        } else {
            // Next item won't fit here; residual becomes dead space.
            // Penalize more when residual is small-ish (worst of both worlds).
            if post_residual < 20 {
                score += 10.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: make empty bins attractive only when the
    // current item is large and open bins have poor fits.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let item_frac = item_size as f64 / cap;
        if item_frac > 0.6 || fitting_bins_count == 0 {
            score -= 12.0 + 10.0 * progress;
        } else {
            score += 15.0;
        }
    }

    // Mean residual coupling: when open bins are already slack-heavy,
    // prefer filling them rather than spreading.
    if mean_residual > 30.0 && bin_residual != bin_capacity {
        score -= (mean_residual - 30.0) * 0.1;
    }

    // Mild pressure to consolidate when many bins are open.
    score += open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // later (below the minimum plausible item size) are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - post_residual as f64; // small gaps are heavily penalized
    }
    // Perfect fit is the ideal outcome.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Dead-space severity grows quadratically with tightness of fit.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 30.0 * tightness;

    // Last chance bin: strongly favor using it instead of opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: reward a residual that can still hold the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            // residual wasted relative to next item: penalize proportionally
            score += 8.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
        }
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += 0.6 * open_bins_count as f64;

    // Prefer bins with lower-than-average residual (fill emptier bins less,
    // keep fuller bins fuller): penalize placing into bins with high residual.
    if bin_residual as f64 > mean_residual {
        score += 0.15 * (bin_residual as f64 - mean_residual);
    } else {
        score -= 0.10 * (mean_residual - bin_residual as f64);
    }

    // New-bin candidate: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        // Base penalty so we prefer reusing open bins with decent fits.
        score += 35.0;
        // But if this item is the only fit candidate (last chance failed) or
        // mean residual is very small (all bins nearly full), opening is fine.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        if mean_residual < item_size as f64 * 0.5 {
            score -= 20.0;
        }
        // Early in stream, opening bins is cheap.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 15.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect match: post_residual exactly equals next item size -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near match: next item could still fit with small slack left afterwards.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
    }
    // Penalize dead space that next item cannot use.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // Tight fits are good: small post_residual relative to capacity.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 20.0 * tightness * tightness;

    // Compare against mean residual across open bins: prefer bins whose
    // resulting residual is below the mean (consolidating space).
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize so we only open new bins when open bins fit poorly.
    if bin_residual == bin_capacity {
        score += 30.0;
        // Early in stream, opening bins is cheaper (more future items to fill).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic bonus for small post-residual.
    let tight = (post_residual as f64) / bin_capacity as f64;
    score -= (1.0 - tight) * (1.0 - tight) * 12.0;

    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        // Dead-space penalty for residuals too small for the smallest item.
        score += 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead: reward if the next item fits the post-residual (chain packing).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0;
        } else if post_residual > 0 {
            // Penalize leaving a residual that nothing useful can fill later.
            score += 5.0;
        }
        // If next item fits perfectly in post-residual, extra reward.
        if post_residual > 0 && next_item_size == post_residual {
            score -= 12.0;
        }
    }

    // New-bin candidate handling: only attractive when no good open-bin fit exists.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, softened when open bins are crowded.
        let crowdedness = if open_bins_count > 0 { mean_residual / bin_capacity as f64 } else { 0.0 };
        score += 18.0;
        score -= crowdedness * 20.0;
        // Late in the stream, prefer consolidating into existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
        // If few bins fit the item, opening a new bin is more acceptable.
        if fitting_bins_count <= 1 {
            score -= 15.0;
        }
    } else {
        // Favor filling more-emptied bins slightly to consolidate.
        score += (bin_residual as f64 - mean_residual).abs() * 0.05;
        // Many open bins: prefer bins with larger residuals (balance load).
        if open_bins_count > 4 {
            score += (post_residual as f64) * 0.05;
        }
    }

    // Early stream: slight preference for keeping residuals large and flexible.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * (post_residual as f64) * 0.03;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let norm_pr = pr / cap;
    let poly = norm_pr * norm_pr * (1.0 + progress) + norm_pr * progress * progress;
    score += 60.0 * poly;

    // Reward tight fits (small post_residual) more aggressively as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= 25.0 * tightness * tightness * (0.5 + progress);

    // Lookahead: if next item fits exactly in post_residual, strongly favor this bin
    if next_item_size > 0 && next_item_size as f64 <= pr {
        let exact = (pr - next_item_size as f64) / cap;
        score -= 30.0 * (1.0 - exact) * (0.5 + progress);
    } else if next_item_size > 0 {
        // next item won't fit here: penalize leaving medium dead space
        score += 15.0 * norm_pr * (1.0 - progress);
    }

    // Last-chance bin: avoid opening a new bin if this fits reasonably
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 - norm_pr);
    }

    // Prefer fuller bins relative to mean residual across open bins
    score += 0.3 * (mean_residual - pr);

    // New-bin candidate: mild penalty so it's chosen only when open bins fit poorly
    if bin_residual == bin_capacity {
        score += 12.0 * (1.0 + progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: which capacity fraction slot it lands in.
    // Dead space that is too small to hold even the smallest item (1) is perfect; but
    // residuals that are "almost useful" (just below common item sizes) are penalized.
    let cap_frac = post_residual as f64 / bin_capacity as f64;

    // Exact-fill reward
    if post_residual == 0 {
        score -= 60.0;
    }

    // Penalize awkward residual classes: residuals in (0, 10] are near-dead (min item 1,
    // but typical items larger); residuals just under 20/30/40 are classic trap zones.
    let trap = |r: u32| -> f64 {
        let mut p = 0.0;
        for t in [10u32, 15, 20, 25, 30, 40, 50].iter() {
            if *t > 0 && r < *t && r >= t - 6 {
                p += 4.0;
            }
        }
        p
    };
    score += trap(post_residual);

    // Harmonic bonus: post_residual divisible by next_item_size means lookahead fits perfectly.
    if next_item_size > 0 && post_residual >= next_item_size {
        if post_residual % next_item_size == 0 {
            score -= 25.0;
        }
        // Lookahead fits at all -> mild reward
        if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            // lookahead blocked by this residual: penalize proportionally
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Integer division threshold: residual class via /10
    let rclass = post_residual / 10;
    match rclass {
        0 => score += 6.0,          // tiny leftover, near-perfect use
        1 => score -= 2.0,          // 10-19: usable for small items
        2 => score -= 5.0,          // 20-29: good
        3 => score -= 4.0,          // 30-39: good
        _ => score -= 1.0,          // large residual: bin still flexible
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin wastes capacity equal to residual
    // left behind elsewhere; make new bins attractive only when current fit is poor.
    if bin_residual == bin_capacity {
        // new bin baseline: post_residual == capacity, so score starts high;
        // discount it when the item is large (packing big items fresh is good)
        score -= item_size as f64 * 0.4;
        // early in stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 15.0;
        // many open bins -> avoid adding more
        score += open_bins_count as f64 * 2.0;
    } else {
        // Existing bin with tight fit (post_residual small relative to item) is great
        let tightness = 1.0 - (post_residual as f64 / bin_residual.max(1) as f64);
        score -= tightness * 12.0;
    }

    // Prefer bins below mean residual (consolidating emptier bins)
    score -= (mean_residual - post_residual as f64) * 0.15;

    // Modulo-2 harmonic parity tweak on post_residual: even residuals pair better
    if post_residual % 2 == 0 {
        score -= 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for typical
    // future items (<= 10) are pure waste; punish them super-linearly.
    if post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    } else if post_residual <= 20 {
        // Moderately unusable gap: quadratic penalty scaled by how far below
        // the smallest plausible item it sits.
        score += 0.8 * (post_residual as f64).powi(2) * 0.1;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post
    // residual, this placement is highly desirable.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            let leftover = post_residual - next_item_size;
            score -= 10.0 - 0.2 * leftover as f64;
        } else {
            // Next item won't fit here: the leftover becomes dead space.
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // rather than spreading; add a mild penalty proportional to openness.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.4 * open_bins_count as f64 * (0.5 + progress);

    // Prefer bins whose residual is below the mean (tighter bins get filled
    // first, keeping large residuals flexible for large future items).
    score += 0.3 * (mean_residual - post_residual as f64);

    // New-bin candidate handling: an empty bin is only attractive when the
    // current bin fit is terrible (large post residual) or nothing fits well.
    if bin_residual == bin_capacity {
        // Baseline cost of opening a new bin; make it beat only bad fits.
        score = bin_capacity as f64 * 0.9 + 0.4 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // new bin can host a follow-up large item
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: the smaller the post_residual, the better.
    score += 0.5 * (post_residual as f64 / bin_capacity as f64);

    // 2-step lookahead: exact match of post_residual with next item is ideal.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 15.0;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score += 0.3 * slack;
            if slack < 10.0 {
                score -= 5.0; // near-exact match for next item
            }
        } else {
            // next item cannot fit here; residual becomes dead space
            score += 0.2 * (next_item_size - post_residual) as f64;
        }
    }

    // Relative to mean residual: prefer bins with residual near/below mean
    // (consolidate space) unless a tight fit justifies it.
    score += 0.4 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Penalize new-bin opening unless current bin fit is poor.
    if bin_residual == bin_capacity {
        let good_fit = post_residual as f64 <= 0.25 * bin_capacity as f64;
        if good_fit {
            score -= 8.0;
        } else {
            score += 10.0;
        }
        // Early in stream, opening bins is cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 5.0 * progress;
    }

    // Slight preference for filling fuller bins when many bins are open.
    score += 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual relative to capacity.
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= 12.0 * tightness;

    // Exact fill is perfect.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: if next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            // next item fits but leaves more waste; mild reward scaled by fit quality
            let nf = (next_item_size as f64) / (post_residual as f64).max(1.0);
            score -= 20.0 * nf;
        } else {
            // dead space penalty: post residual too small for next item
            score += 10.0;
        }
    }

    // Last chance: this is the only bin that fits; strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Penalize opening new bins when many open bins have room (consolidation).
    if bin_residual == bin_capacity {
        // New-bin candidate: base penalty grows with open bins that could fit.
        score += 25.0 + 3.0 * (open_bins_count as f64);
        // But if no open bin fits (fitting_bins_count==0 among open bins) allow it.
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
        // Late in stream, prefer consolidation less.
        let progress = step_index as f64 / (total_items as f64).max(1.0);
        score -= 10.0 * progress;
    }

    // Global residual pressure: if mean residual is low, waste is costlier.
    score += (post_residual as f64 - mean_residual).max(0.0) * 0.3;

    // Slight preference for bins with less residual (best-fit bias) modulated by time.
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    score += (bin_residual as f64) * 0.05 * (1.0 - progress);

    // Fragmentation penalty for large leftover chunks that likely won't be used.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // tiny unusable slivers
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;

    // Smooth non-linear coupling: tight fits are rewarded more strongly as the stream progresses.
    let tightness = 1.0 - pr / cap; // in (0,1], 1 = perfectly tight
    score -= tightness * tightness * (8.0 + 24.0 * progress);

    // Penalize large dead space with a convex term, stronger later in the stream.
    let dead = (pr / cap).powi(2);
    score += dead * (10.0 + 30.0 * progress);

    // Reward bins whose residual matches the lookahead item (k=2 lookahead).
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score -= (1.0 - gap / cap).max(0.0) * 6.0;
        // Penalize leaving a residual that is too small for the next item (wasted sliver).
        if pr < next_item_size as f64 {
            score += (next_item_size as f64 - pr) * 0.15;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: only attractive when existing fits are poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Penalize opening a new bin mildly; relief grows when current fit is loose.
        score += 6.0 + 20.0 * (1.0 - fit_ratio);
        // Early in the stream, new bins are cheaper (more future to consolidate).
        score -= 10.0 * (1.0 - progress) * (1.0 - fit_ratio);
        // If many open bins have large mean residual, discourage adding another.
        score += (open_bins_count as f64).ln() * 2.0;
    } else {
        // Slight preference for filling existing bins, scaled by how full the fleet is.
        score -= (mean_residual / cap).max(0.0) * 3.0;
    }

    // Smooth global coupling: polynomial interaction of progress with post_residual.
    let norm_pr = pr / cap;
    score += norm_pr * norm_pr * (1.0 - norm_pr) * 15.0 * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
