        score += fitting_bins_count as f64 * 25.0;
        // If this bin is the last chance, opening a new bin is fine.
        if fitting_bins_count <= 1 {
            score -= 100.0;
        }
        // Early in stream, bins are cheap; late, prefer consolidation.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 40.0;
    }

    // Lookahead: if next item exactly fills the post-residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size <= post_residual {
            // Next item fits: reward proportional to how well it fills.
            let next_fill = next_item_size as f64 / post_residual as f64;
            score -= 60.0 * next_fill;
        } else {
            // Next item cannot use this residual: slight penalty if residual small.
            if post_residual < next_item_size {
                score += 15.0;
            }
        }
    }

    // Prefer filling bins with larger residuals when many bins are open
    // (keeps number of open bins from proliferating).
    if open_bins_count > 4 {
