    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 6.0 * (post_residual as f64 / bin_capacity as f64);

    // New empty bin candidate: only attractive if current item is huge and nothing tight exists
    if bin_residual == bin_capacity {
        score += 20.0;
        if item_size > bin_capacity * 3 / 4 {
            score -= 18.0;
        }
        if fitting_bins_count <= 1 {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Smooth polynomial coupling of post_residual with stream progress.
    // Early in the stream, waste is cheap (bins get closed anyway);
    // late in the stream, dead space becomes increasingly costly.
    let p = 1.0 + 2.0 * progress; // exponent grows smoothly 1 -> 3
    let normalized_post = (post / cap).clamp(0.0, 1.0);
    score += (normalized_post.powf(p)) * cap * 0.5;

    // Reward tight fits: small post_residual relative to item size.
    let tightness = item_size as f64 / (bin_residual as f64).max(1.0);
    score -= tightness * cap * 0.4;

    // Lookahead coupling: reward if next item fits exactly into post_residual,
    // penalize if post_residual is just barely too small for next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let fit_quality = 1.0 - (post - nxt) / cap; // exact fit -> 1
            score -= fit_quality * cap * 0.3;
        } else {
            let miss = (nxt - post) / cap;
            score += miss * miss * cap * 0.2;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= cap * 0.6;
    }

    // Penalize scattering residual mass when many bins are open and mean
    // residual is large (fragmentation pressure), smoothly scaled by progress.
    let frag = (mean_residual / cap - normalized_post).max(0.0);
    score += frag * frag * cap * (0.1 + 0.3 * progress);

    // Mild preference for consolidating into fewer bins when many are open.
    score += (open_bins_count as f64).ln().max(0.0) * 2.0 * normalized_post;

    // New-bin candidate: neutral-ish baseline with slight smooth bias,
    // attractive only when existing residuals are badly fragmented.
    if bin_residual == bin_capacity {
        score = cap * 0.45 + frag * cap * 0.5 - progress * cap * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
