    } else if post_residual < 20 {
        score += 4.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            // next item fits: penalize proportionally to leftover after next
            let after_next = post_residual - next_item_size;
            score -= 8.0 - (after_next as f64) * 0.08;
            if after_next % 10 == 0 {
