    // Mean residual alignment: prefer bins whose residual is close to mean (balance)
    score += ((post - mean_residual) / cap).abs() * 3.0;

    // Stream progression: early on, be greedy-tight; late, allow more new bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 - 0.15 * progress;

