            score -= 0.5 * (next_item_size as f64);
        } else {
            // next item won't fit here; penalize wasting space that blocks it
            score += 0.3 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Prefer bins with larger residual when many bins are open (consolidation).
    score -= 0.2 * (bin_residual as f64 - mean_residual);

    // New-bin candidate handling: empty bin gets a penalty unless current fits are poor.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 30.0 + 5.0 * (open_bins_count as f64).sqrt() };
        score += pressure;
        // Early in stream, opening new bins is cheaper.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 20.0 * (1.0 - progress);
    }

    // Mild penalty for opening bins when many already open and residual mean is high.
    if bin_residual == bin_capacity && mean_residual > 30.0 && fitting_bins_count > 0 {
        score += 0.5 * mean_residual;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (low post residual), non-linearly scaled
    let mut score = norm_pr * norm_pr * 60.0 + norm_pr * 20.0;

    // Smooth coupling with stream progress: late in stream, penalize waste harder
    let late = progress * progress;
    score += late * norm_pr * 45.0;

    // Reward near-perfect fills (small post residual) more as stream advances
    let tightness = (1.0 - norm_pr).clamp(0.0, 1.0);
    score -= late * tightness * tightness * 25.0;

    // Lookahead: if next item fits in post residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 8.0 + 10.0 * (1.0 - pr / cap);
    } else if next_item_size > 0 {
        // next item cannot use the leftover space: mild penalty, stronger late
        score += 4.0 + 8.0 * late * norm_pr;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0 + 20.0 * tightness;
    }

    // Mean residual coupling: placing into a bin below-mean residual wastes capacity
    let dev = (pr - mean_residual) / cap;
    score += dev * 15.0 * (0.5 + progress);

    // New-bin candidate handling: empty bin should only win when open bins are poor
    if bin_residual == bin_capacity {
        // base cost of opening a new bin, decreasing if many items remain
        score += 35.0 - 20.0 * progress;
        if open_bins_count > 0 && fitting_bins_count > 0 {
            // discourage new bin when alternatives exist, unless they'd be very wasteful
            score += 10.0 * (1.0 - progress);
        }
    } else {
        // slight preference for reusing open bins
        score -= 5.0;
        // reward consolidating into bins with high residual (large leftover) to compact
        score -= (bin_residual as f64 / cap) * 6.0;
    }

    // Open bins pressure: many open bins -> prefer filling existing ones
    score += open_bins_count as f64 * 1.5 * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongest reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of the residual: residuals divisible by common item
    // granularity are more reusable than odd dead space.
    let granularity: u32 = 10;
    let residual_class = post_residual % granularity;
    if post_residual > 0 {
        if residual_class == 0 {
            score -= 12.0; // clean harmonic residual, likely reusable
        } else {
            score += residual_class as f64 * 1.5; // penalize ragged dead space
        }
    }

    // Dead-space threshold: residuals too small for the smallest item are waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Lookahead coupling: if the next item fits the post-residual exactly,
    // this bin chains nicely; penalize if next item would be stranded.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 200.0;
        } else if next_item_size <= post_residual {
            score -= 25.0;
        } else if post_residual > 0 && next_item_size > post_residual {
            // next item can't use this residual; weight by how close to waste
            score += (post_residual as f64) * 0.5;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Prefer fuller bins: favor small residual relative to capacity fraction.
    let fill_fraction = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= fill_fraction * 30.0;

    // New-bin candidate (empty bin): should only win when open bins are poor fits.
    if bin_residual == bin_capacity {
        score += 45.0 + (open_bins_count as f64).sqrt() * 5.0;
        // allow new bin late in stream if mean residual is low (open bins nearly full)
        if mean_residual < 15.0 {
            score -= 40.0;
        }
    }

    // Slight preference to consolidate early when many bins are open.
    score += (open_bins_count as f64) * 0.3;

    // Mild stream-progression tilt: tighten packing as stream ends.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that no plausible item can use are pure waste.
    // Minimum plausible item size ~10 (interface allows 1..100, use small threshold).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // tiny unusable sliver
    } else if post_residual == 0 {
        score -= 40.0; // perfect fit, zero waste
    }

    // Penalize mid-range dead space quadratically, scaled by item density.
    let tightness = item_size as f64 / bin_capacity as f64;
    score += 0.35 * (post_residual as f64).powi(2) / bin_capacity as f64 * (0.5 + tightness);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.2 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0; // dead space relative to the known future item
    }

    // Open-bin pressure: when many bins are open, prefer filling existing ones
    // over opening new bins; penalize the new-bin candidate.
    if bin_residual == bin_capacity {
        score += 25.0 + 3.0 * open_bins_count as f64;
    } else {
        score -= 2.0 * open_bins_count as f64;
    }

    // Prefer bins tighter than average (below-mean residual = well-used bin).
    score -= 0.5 * (mean_residual - bin_residual as f64);

    // Early stream: be slightly more conservative about fragmenting bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 0.1 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongly reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if the next item exactly fills the leftover space.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            // Next item fits: reward proportionally to how tightly it fits.
            let tightness = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 200.0 * tightness;
        } else {
            // Next item cannot use the leftover: penalize dead space a bit.
            score += 30.0 + 0.2 * (next_item_size - post_residual) as f64;
        }
    }

    // Penalize leftover space relative to mean residual across open bins
    // (creating more-than-average dead space is bad).
    if post_residual as f64 > mean_residual {
        score += 0.5 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.3 * (mean_residual - post_residual as f64);
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: only attractive when the current item is large or
    // open bins are nearly full (mean residual low).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let new_bin_bonus = 400.0
            - 3.0 * item_size as f64
            - 2.0 * mean_residual
            - 100.0 * progress;
        score += new_bin_bonus;
    }

    // Mild preference for bins with smaller residual before placement (best-fit core).
    score += 0.1 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: scale post_residual by how full the bin becomes.
    let fill = item_size as f64 / bin_capacity as f64;
    score += (1.0 - fill) * (post_residual as f64) * 0.8;

    // Lookahead: penalize leaving a residual that is smaller than the next item
    // (dead space), reward residuals that exactly or nearly fit the next item.
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        if post_residual as f64 >= nr {
            let slack = post_residual as f64 - nr;
            score -= (nr / 10.0) * (1.0 - slack / bin_capacity as f64);
        } else if post_residual > 0 {
            // Dead space: unusable for the next item.
            score += post_residual as f64 * 1.5 * (nr / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    } else {
        // When many bins fit, prefer the tightest; mild penalty otherwise.
        score += (fitting_bins_count as f64).ln().max(0.0) * 0.5;
    }

    // New-bin candidate: only attractive when open bins have large residuals
    // (poor fits) or late in the stream; penalize opening bins early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let avg_fit_gap = (mean_residual - item_size as f64).abs();
        let desperation = (avg_fit_gap / bin_capacity as f64) * 2.0
            + (open_bins_count as f64).ln().max(0.0) * 0.1;
        score += 25.0 - desperation * 10.0 - progress * 8.0;
        if next_item_size > 0 && post_residual as f64 >= next_item_size as f64 {
            score -= 6.0; // fresh bin can serve the next item too
        }
    }

    // Global residual balance: prefer bins whose residual is near the mean
    // (keeps open bins homogeneous, easier future packing).
    score += ((post_residual as f64 - mean_residual).abs()) * 0.3;

    // Late stream: prefer filling bins as completely as possible.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * progress * 0.5;

    // Slight penalty for very small leftovers that become dead space generally.
    if post_residual > 0 && post_residual < 10 {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;
    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * progress;
    score += 40.0 * poly;
    // Reward tight fits more strongly as stream progresses
    let tight = 1.0 - norm_pr;
    score -= 25.0 * tight * tight * (0.5 + progress);
    // Penalize dead space relative to mean residual
    score += 0.3 * (pr - mean_residual) * (1.0 + progress);
    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + progress);
    }
    // Lookahead: favor leaving room for the next item
    if next_item_size > 0 {
        let gap = pr as f64 - next_item_size as f64;
        if gap >= 0.0 {
            score -= 8.0 * (1.0 - (gap / cap)) * progress;
        } else {
            score += 6.0 * (-gap / cap);
        }
    }
    // Mild penalty for opening a new bin when many bins are open
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: capacity divided into 10 classes
    let class = post_residual / (bin_capacity / 10).max(1);
    score += (class as f64) * 2.0;

    // Reward tight fits: post_residual in the lowest harmonic classes
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 10 {
        score -= 20.0;
    }

    // Penalize dead space that no plausible item can use (items >= 1, but
    // typical items are chunky): leftover smaller than a "unit class" is waste
    if post_residual < 10 && post_residual > 0 {
        score += 15.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
        } else {
            // next item cannot use this leftover: leftover likely wasted
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // this placement would leave a large, awkward residual in an existing bin
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 - 30.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a bin
        }
    }

    // Progress-aware scaling: late in the stream, prefer consolidating
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (mean_residual - post_residual as f64).abs() * 0.5;

    // Modulo-based micro-classes on post_residual (harmonic texture)
    match post_residual % 5 {
        0 => score -= 3.0,
        1 | 4 => score += 1.5,
        _ => {}
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong dead-space penalty for small unusable gaps (< 10, the minimum item size)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Penalize moderately small gaps that few items can fill
    if post_residual >= 10 && post_residual < 25 {
        score += 8.0;
    }

    // Reward tight fits (post_residual small but >= 0 already base)
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 15.0 * fill_ratio;

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize unless current bin fit is bad or no open bin is good
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin
        score = 55.0;
        // Opening a new bin is more attractive when open bins are fragmented
        score -= (open_bins_count as f64).min(10.0);
        // If next item could exactly fill the residual of a fresh bin, mildly encourage
        if next_item_size > 0 && next_item_size as f64 >= mean_residual {
            score -= 5.0;
        }
        // Late in stream, avoid proliferation of bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * progress;
    }

    // Open-bin pressure: prefer consolidating into fewer bins when many are open
    score += 0.5 * (open_bins_count as f64).min(20.0);

    // Prefer bins whose residual deviates favorably: large residual bins absorb big items
    if (bin_residual as f64) > mean_residual + 15.0 && item_size as f64 > 40.0 {
        score -= 6.0;
    }

    // Lookahead: if this placement leaves room exactly for next item, reward
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward: perfect 2-step match (post_residual equals next item size)
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        score -= 60.0 / (1.0 + diff);
        // exact match bonus
        if post_residual == next_item_size {
            score -= 80.0;
        }
        // penalize leaving residual that next item can't use but is small (dead space)
        if next_item_size > post_residual && post_residual < 10 {
            score += 30.0;
        }
    } else {
        // last item: minimize waste directly
        score += 20.0;
    }

    // Compare against mean residual: prefer bins that end near the mean (keeps flexibility)
    let mean_gap = (post_residual as f64 - mean_residual).abs();
    score += 0.15 * mean_gap;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: penalize unless nothing else fits well
    if bin_residual == bin_capacity {
        score += 70.0;
        // if no open bin fits, opening is fine
        if fitting_bins_count == 0 {
            score -= 90.0;
        }
        // early in stream, opening bins is cheap
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 30.0 * (1.0 - progress);
    }

    // mild penalty for very large unusable residual
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Exact fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Penalize dead space that cannot fit the average/next item.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0; // tiny unusable sliver
    }
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0; // residual too small for lookahead item
    }

    // Lookahead synergy: reward residuals that still fit the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
        // extra reward if residual closely matches next item (good pair)
        let gap = post_residual - next_item_size;
        if gap <= 10 {
            score -= 10.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: make opening a new bin attractive only when
    // current bin would leave large waste or few bins fit.
    if bin_residual == bin_capacity {
        // Neutral base for new bin; penalize slightly when many bins fit well.
        score = bin_capacity as f64 * 0.55;
        if fitting_bins_count > 0 {
            score += 12.0 * (fitting_bins_count as f64).ln();
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
        // Large items leave big residuals in fresh bins; discourage if item large.
        if item_size > 60 {
            score += 8.0;
        }
    }

    // Prefer fuller bins relative to the fleet mean residual.
    score += 0.35 * (mean_residual - post_residual as f64).max(0.0);

    // Slight preference for bins with lower residual when many open bins exist.
    score += 0.10 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Early stream: encourage keeping residuals flexible (moderate residuals).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress < 0.3 && post_residual > 50 {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Smooth polynomial coupling of post_residual with stream progress
    let base = pr * (1.0 + 0.8 * progress * progress);

    // Penalize residuals that waste large fractions of capacity (dead space), smoothly
    let waste = (pr / c).powi(3) * 40.0;

    // Reward tight fits: small post_residual relative to capacity
    let tight = -30.0 * (1.0 - pr / c).powi(4);

    // Lookahead: if next item fits the post residual, reward this bin
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        return base + waste + tight - 25.0 * (1.0 - progress);
    }
    // If next item almost fits, mild penalty for near-miss dead space
    let near_miss = if next_item_size > 0 {
        ((next_item_size as f64 - pr) / c).powi(2) * 30.0
    } else {
        0.0
    };

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    let last_chance = if fitting_bins_count == 1 { -35.0 } else { 0.0 };

    // Slight preference to consolidate into fewer bins as stream progresses
    let consolidation = -0.5 * (open_bins_count as f64).ln().max(0.0) * (1.0 - progress);

    // Mean residual alignment: prefer bins close to mean residual (balanced packing)
    let align = -0.3 * (-(pr - mean_residual).abs() / c).exp() * 10.0;

    base + waste + tight + near_miss + last_chance + consolidation + align
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: bins whose leftover lands in
    // "small" classes (fits common item sizes) are more valuable to keep tight.
    let pr = post_residual;
    let cap = bin_capacity as f64;

    // Reward tight fits strongly (small post_residual).
    let tight_bonus = ((cap - pr as f64) / cap).powi(3) * 30.0;
    score -= tight_bonus;

    // Penalize dead space that no plausible item can use: post_residual in
    // (0, 10) is pure waste; classes 1..9 are the worst leftovers.
    if pr > 0 && pr < 10 {
        score += (10 - pr) as f64 * 4.0;
    }

    // Harmonic classes via integer division: leftover bucketed by ranges of
    // typical item sizes (1..100). Buckets: [0], [1,10), [10,20), ..., [90,100].
    let bucket = (pr / 10) as f64;
    score -= bucket * 2.0; // larger usable buckets are better than tiny ones

    // If the next item fits the resulting residual, big reward (lookahead k=2).
    if next_item_size > 0 && next_item_size <= pr {
        let fit_quality = (next_item_size as f64) / (pr as f64);
        score -= 12.0 * fit_quality; // prefer bins where next item fills residual well
    } else if next_item_size > 0 {
        // Next item cannot use this residual: penalize proportionally to waste.
        score += ((next_item_size as f64) - pr as f64).max(0.0) * 0.3;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when
    // existing residuals are large / fragmented.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 15.0;
        // If item is large, a fresh bin gives a clean fit: reduce penalty.
        score -= (item_size as f64 / 100.0) * 10.0;
        // If many open bins already have small mean residual, prefer them.
        score += (mean_residual / 10.0).min(10.0);
    }

    // Mild preference to consolidate into few bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (open_bins_count as f64) * 0.5 * (0.5 + progress);

    // Exact-fill perfection bonus.
    if pr == 0 {
        score -= 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space avoidance: residuals too small to hold the minimum item are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Residuals that cannot fit the lookahead item are likely dead space too.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: when many bins are open, prefer filling existing bins;
    // when few are open, tolerate opening a new bin.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Prefer bins tighter than the mean residual (better consolidation).
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // Slight preference for the new-bin candidate only when the item is large
    // and fits poorly everywhere (avoid fragmenting open bins with big items).
    if bin_residual == bin_capacity {
        score += 15.0;
        if item_size >= 70 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Tight fit reward (small leftover)
    let tight = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - tight * 8.0).max(0.0) * 50.0;

    // 2-step lookahead: reward if next item fits exactly in post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual >= next_item_size {
            score -= 100.0;
        } else {
            // dead space relative to next item
            score += (next_item_size - post_residual) as f64 * 1.5;
        }
    }

    // Compare post_residual against mean residual: avoid making bin much worse than average
    score += (post_residual as f64 - mean_residual).max(0.0) * 0.5;

    // Last chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 300.0;
    }

    // Penalize opening new bins early in the stream less; prefer consolidation late
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 50.0 + 200.0 * progress;
    }

    // Slight preference for bins with less residual among equals
    score += bin_residual as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post_residual is good).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Penalize dead space: residuals too small for typical future items.
    if post_residual < 10 {
        score -= 25.0; // perfectly packed bin is great
    } else if post_residual < 20 {
        score -= 10.0;
    } else if post_residual < 30 {
        score += 8.0;
    }

    // Lookahead: if next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size < post_residual {
            score -= 12.0 * (1.0 - (post_residual - next_item_size) as f64 / 100.0);
        } else {
            // next item won't fit here; slight penalty for wasting residual
            score += (post_residual as f64) * 0.15;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Global pressure: many open bins with low mean residual -> prefer filling existing bins.
    let pressure = mean_residual / bin_capacity as f64;
    if open_bins_count > 2 {
        score += pressure * 10.0;
        score -= (open_bins_count as f64).ln() * 5.0;
    }

    // Time horizon: early in stream, be more willing to open new bins (keep flexibility);
    // late in stream, consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let new_bin_bonus = (1.0 - progress) * 30.0;
    if bin_residual == bin_capacity {
        score -= new_bin_bonus;
        // Opening a new bin is only attractive if existing fits are poor.
        if fit_ratio > 0.5 {
            score += 35.0;
        }
    } else {
        score += progress * 12.0;
    }

    // Mild preference for bins whose residual is close to mean residual (balance load).
    score -= 6.0 * (1.0 - ((bin_residual as f64 - mean_residual).abs() / bin_capacity as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 + progress) - norm_pr * progress * progress;
    score += 8.0 * poly;

    // Reward tight fits more strongly later in the stream
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * (2.0 + 6.0 * progress);

    // Penalize dead space that cannot fit the lookahead item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            score += (nxt - pr) * (0.5 + progress);
        } else {
            score -= 0.3 * (1.0 - (pr - nxt) / cap);
        }
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 10.0 * (1.0 - norm_pr);
    }

    // Mild pressure to close bins when many are open
    score += 0.05 * open_bins_count as f64 * norm_pr;

    // Deviation from mean residual: prefer balanced residual usage
    score += 0.2 * (pr - mean_residual).abs() * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Harmonic class of post-residual: quantize into capacity fractions.
    // Residuals in the "useless" class (> cap/2) are penalized; tiny residuals are cheap.
    let pr = post_residual as f64;
    let class = (pr / (cap / 4.0)).floor(); // 0..4 harmonic class
    match class as u32 {
        0 => score -= 6.0,                 // near-perfect fill
        1 => score -= 2.0,                 // small leftover, still usable
        2 => {}                            // neutral
        _ => score += 8.0,                 // large dead space
    }

    // Lookahead (k=2): exact match with next item is gold.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            // usable next item: reward proportionally to how well it fits
            score -= 10.0 * (next_item_size as f64 / pr.max(1.0));
        } else {
            // next item cannot use this residual: penalize wasted potential
            score += 4.0;
        }
    }

    // Integer-division threshold: post_residual divisible into halves/quarters
    // of capacity pairs well with common item sizes.
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 3.0;
    }
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 1.5;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: residual == capacity means empty bin.
    if bin_residual == bin_capacity {
        // Opening a new bin wastes the remaining space of all open bins.
        let openness = open_bins_count as f64;
        score += 15.0 + 2.0 * openness;
        // But if the item is huge, a fresh bin is natural: soften penalty.
        score -= (item_size as f64 / cap) * 12.0;
        // If no other bin fits at all, opening is inevitable: cancel penalty.
        if fitting_bins_count <= 1 {
            score -= 18.0 + 2.0 * openness;
        }
        // Late in the stream, prefer consolidation into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 6.0 * progress;
    } else {
        // Existing bin: reward bins whose residual is below the mean
        // (tighter bins get filled first, keeping large gaps free).
        if pr < mean_residual {
            score -= 3.0;
        } else {
            score += 1.5;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable gaps (dead space) super-linearly
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 15.0;
    }

    // Reward tight fits
    if post_residual == 0 {
        score -= 50.0;
    }

    // Reward residual close to next item size (lookahead fit)
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += (next_item_size as f64 - post_residual as f64).abs() * 0.5;
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Open bins pressure: discourage spreading across many bins unless tight fit
    score += open_bins_count as f64 * 0.3 * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive if all existing fits are bad
    if bin_residual == bin_capacity {
        score += 20.0;
        if fitting_bins_count <= 1 {
            score -= 30.0;
        }
    }

    // Mild phase bias: later in stream, prefer using open bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // penalize leftover after next item too
            score += slack * 0.5;
            // reward chain fit proportional to tightness
            score -= (1.0 - slack / bin_capacity as f64) * 150.0;
        } else {
            // next item cannot fit here; penalize by mismatch gap
            score += (next_item_size - post_residual) as f64 * 1.5;
        }
    }

    // Penalize creating small unusable dead space (below min item size 1..100 unknown; treat <15 as dead)
    if post_residual > 0 && post_residual < 15 {
        score += 200.0;
    }

    // Compare against mean residual: prefer bins tighter than average
    score -= (mean_residual - post_residual as f64) * 0.8;

    // Last-chance bin: strong bonus to use it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: default neutral-ish, penalize opening new bins early in stream
    if bin_residual == bin_capacity {
        score += 50.0 + 100.0 * (step_index as f64 / total_items.max(1) as f64);
    }

    // Slight preference to fill fuller bins (smaller residual) as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (bin_capacity as f64 - bin_residual as f64) * 0.3 * (1.0 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fraction of stream completed: dynamic time horizon.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tightness of fit: reward near-perfect fills (post_residual small relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: residuals too small for the smallest plausible future item (<=10).
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // Lookahead: strongly reward bins whose post_residual can fit the next item (k=2 chaining).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let chain_quality = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 8.0 + 6.0 * chain_quality;
        } else {
            // Next item cannot follow here: mild penalty scaled by how much it misses by.
            let miss = (next_item_size - post_residual) as f64;
            score += 0.15 * miss;
        }
    } else {
        // Last item: just prefer fullest packing.
        score -= 5.0 * tightness;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0 + 5.0 * tightness;
    }

    // New-bin candidate handling: opening a bin is expensive when many bins are open
    // or when an existing bin fits decently.
    if bin_residual == bin_capacity {
        let open_pressure = (open_bins_count as f64).ln_1p();
        score += 18.0 + 4.0 * open_pressure + 10.0 * t;
        // Allow opening a new bin early in the stream or when open bins are quite full on average.
        if mean_residual < 20.0 {
            score -= 14.0;
        }
        if t < 0.15 {
            score -= 6.0;
        }
    } else {
        // Existing bin: reward using bins that are already committed (reduce bin count).
        score -= 2.0 * (1.0 - bin_residual as f64 / bin_capacity as f64);
        // Slight preference for bins with residuals near the mean (balanced closing).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    // Global pressure: when many bins are open, favor consolidating into existing ones.
    score += 0.3 * open_bins_count as f64 * (bin_residual == bin_capacity) as i32 as f64;

    // Nonlinear coupling: squared fill ratio interaction with time horizon.
    score -= 3.0 * tightness * (1.0 - t);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr_norm = pr / cap;
    let fit_norm = item_size as f64 / cap;
    let next_norm = next_item_size as f64 / cap;

    // Smooth polynomial coupling of post-residual with stream progress.
    let mut score = pr * (1.0 + 0.6 * progress * pr_norm);

    // Penalize large dead space quadratically, more so late in the stream.
    score += (pr_norm * pr_norm) * cap * (0.3 + 0.7 * progress);

    // Reward tight fits: item filling most of the residual.
    let tightness = 1.0 - pr_norm;
    score -= fit_norm * cap * (0.4 + 0.5 * tightness * tightness);

    // Lookahead: favor bins whose post-residual can host the next item.
    if next_item_size > 0 {
        let can_host = if pr >= next_item_size { 1.0 } else { 0.0 };
        let closeness = (pr_norm - next_norm).abs();
        score -= can_host * cap * (0.25 - 0.15 * closeness);
        // Penalize post-residual just barely below next item (dead space trap).
        let trap = ((next_norm - pr_norm).max(0.0) * (1.0 / next_norm.max(1e-6))).min(1.0);
        score += trap * cap * 0.35;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= cap * 0.9;
    }

    // Mild pressure to consolidate when many bins are open.
    score -= (open_bins_count as f64).ln().max(0.0) * pr_norm * cap * 0.1;

    // Deviation from mean residual: prefer bins leaving residuals near the mean.
    score += 0.3 * (pr - mean_residual).abs();

    // New-bin candidate: neutral-ish base, penalized early, relaxed late.
    if bin_residual == bin_capacity {
        score = cap * (0.55 - 0.35 * progress) + pr * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues near multiples of 10 are "clean" states.
    let pr = post_residual as i64;
    let residue = ((pr % 10 + 10) % 10) as i64;
    let harm_class = residue.min(10 - residue); // 0 = perfectly harmonic
    score += harm_class as f64 * 0.8;

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Tiny dead space is fine (harmonic class 0/1 already low), but mid-range dead space (3..7) is bad.
    if harm_class >= 3 && post_residual > 0 {
        score += 6.0;
    }

    // Lookahead: strongly reward bins where next_item_size fits post_residual exactly or harmonically.
    if next_item_size > 0 && next_item_size <= post_residual {
        let next_res = (post_residual - next_item_size) as i64;
        let next_residue = ((next_res % 10 + 10) % 10) as i64;
        let next_harm = next_residue.min(10 - next_residue);
        score -= 12.0 - next_harm as f64;
        if next_res == 0 {
            score -= 25.0;
        }
    } else if next_item_size > 0 {
        // Next item won't fit here: penalize slightly, scaled by how much it misses.
        let miss = (next_item_size - post_residual) as f64;
        score += (miss * 0.15).min(8.0);
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only attractive when no open bin is a good fit.
    if bin_residual == bin_capacity {
        // Base penalty so open bins are preferred, but reduced when open bins are fragmented.
        let mut nb = 25.0;
        if mean_residual > 0.0 {
            // Fragmentation signal: many open bins with small residuals.
            let frag = (mean_residual - post_residual as f64) / bin_capacity as f64;
            if frag < 0.05 {
                nb -= 20.0; // open bins nearly full -> new bin is fine
            }
        }
        if fitting_bins_count == 0 {
            nb -= 30.0;
        }
        // Late in stream, avoid opening bins for small items.
        let progress = step_index as f64 / total_items.max(1) as f64;
        nb += progress * 10.0;
        score = nb + (100 - item_size.min(100)) as f64 * 0.5;
        return score;
    }

    // Prefer fuller bins: reward low residual via fill ratio coupling.
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= fill * 5.0;

    // Many open bins: encourage consolidation into existing bins.
    if open_bins_count > 4 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residual gaps that are too small for the
    // smallest plausible item (<= 10) are pure waste; penalize them heavily.
    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 60.0;
    } else if post_residual < 10 {
        // Unusable dead space: large penalty, worse the closer to full-but-broken.
        score += (10 - post_residual) as f64 * 8.0;
    }

    // Progressive dead-space scaling: medium gaps are risky too.
    if post_residual >= 10 && post_residual < 20 {
        score += 6.0;
    }

    // Tightness reward: favor bins where the item fills a large fraction
    // of the residual capacity.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= fit_ratio * 25.0;

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only allow opening a new bin when existing
    // fits are genuinely poor (large dead space would result).
    if bin_residual == bin_capacity {
        // Base cost of consuming a fresh bin.
        score += 40.0;
        // Pressure from number of open bins: more open bins -> avoid new ones.
        score += open_bins_count as f64 * 3.0;
        // If the resulting residual would be unusable dead space anyway,
        // a fresh bin becomes more attractive.
        if post_residual < 10 && post_residual > 0 {
            score -= 55.0;
        }
        // Lookahead: if next item fits nicely in the leftover of a fresh bin
        // pairing, that's fine, but don't over-reward.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 5.0;
        }
    } else {
        // Placing into an existing bin: reward keeping bin count low,
        // scaled by stream progression (early on, consolidation matters more).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 + 10.0 * progress;

        // Lookahead synergy: if the next item exactly fits the post residual,
        // strongly reward this placement.
        if next_item_size > 0 && next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size > 0 && next_item_size <= post_residual {
            score -= 8.0;
        } else if next_item_size > post_residual && post_residual > 0 {
            // Next item cannot use the leftover: leftover may become dead space.
            score += (post_residual.min(20)) as f64 * 1.5;
        }
    }

    // Mild preference toward bins with lower residual (fill fullest bins first).
    score += (bin_residual as f64 - mean_residual) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Near match: next item fits with small leftover
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 500.0 - slack * 8.0;
    }
    // Next item does NOT fit: dead space penalty, stronger when gap is small (teasing)
    else if next_item_size > 0 {
        let gap = (next_item_size as f64 - post_residual as f64).max(0.0);
        score += 200.0 + gap * 2.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: penalize unless open bins are badly fragmented
    if bin_residual == bin_capacity {
        let fragmentation = if open_bins_count > 0 { (mean_residual - post_residual as f64).abs() } else { 0.0 };
        score += 150.0 - fragmentation * 3.0;
    } else {
        // Prefer bins tighter than the mean (fill the fullest bins first)
        score -= (mean_residual - post_residual as f64) * 1.5;
    }

    // Late in the stream: prefer compact placements to close out bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: lower score when the item nearly fills the bin.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * tightness * tightness;

    // Penalize very small post-residuals that no typical item can use,
    // unless it's a perfect fit (post_residual == 0).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual,
    // strongly favor this bin (chained packing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; slight penalty for leaving large gaps
            score += 3.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: a fresh empty bin should only win when
    // no open bin offers a decent fit. Penalize the new bin moderately.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Early on, opening bins is cheap; later, prefer filling open bins.
        score += 20.0 + 40.0 * progress;
        // If many open bins exist, opening yet another is wasteful.
        score += 2.0 * open_bins_count as f64;
        // If the item is large relative to capacity, a fresh bin is more attractive.
        score -= 0.15 * item_size as f64;
    }

    // Global state: prefer bins whose residual is close to the mean
    // (keeps residuals uniform, preserving flexibility).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Prefer more-filled bins among many open bins (best-fit bias).
    score -= 0.1 * (bin_capacity - bin_residual) as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual

    // Base: penalize leftover space, but with non-linear shape.
    let mut score = pr as f64;

    // Polynomial coupling: low post-residual is extra good early (tight fills),
    // moderate residual tolerance grows with progress.
    let poly = x * x * (1.0 - x) * (1.0 - x);
    score += 40.0 * poly * (1.0 - progress);

    // Reward tight fits (post_residual small) increasingly over the stream.
    score -= (1.0 - x) * (1.0 - x) * (10.0 + 30.0 * progress);

    // Perfect-fit bonus.
    if post_residual == 0 {
        score -= 25.0 + 25.0 * progress;
    }

    // Dead-space penalty: residual too small to fit likely next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr > 0.0 && pr < nx {
            score += 15.0 + 20.0 * progress + 0.5 * (nx - pr);
        } else if pr >= nx {
            // room for lookahead: mild reward
            score -= 5.0 * (1.0 - progress);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 40.0 * progress;
    }

    // New-bin candidate: prefer it only when open bins are nearly full on average
    // and stream is far along; otherwise discourage fragmentation.
    if bin_residual == bin_capacity {
        let mean_x = mean_residual / cap;
        let scarcity = (mean_x * mean_x).min(1.0);
        score = 20.0 + 60.0 * (1.0 - scarcity) + 30.0 * (1.0 - progress) - 50.0 * scarcity * progress;
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Mild penalty for spreading across many open bins.
    score += 0.5 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: classify post_residual into
    // capacity-fraction buckets. Residuals that are "harmonically useful"
    // (large, or exactly matching common small-item sizes) are rewarded.
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap;

    // Reward large post_residual (keeps bins flexible).
    score -= 12.0 * frac * frac;

    // Harmonic class via integer division thresholds on post_residual.
    // Class 0: post_residual < 10  -> dead space, heavy penalty.
    // Class 1: 10..25 -> fits only small items, mild penalty.
    // Class 2: 25..50 -> half-bin class, small bonus.
    // Class 3: >= 50  -> large class, strong bonus.
    let class = if post_residual < 10 { 0 }
        else if post_residual < 25 { 1 }
        else if post_residual < 50 { 2 }
        else { 3 };
    score += [8.0, 2.0, -3.0, -10.0][class];

    // Lookahead coupling: if the next item fits exactly in post_residual,
    // strongly reward (perfect harmonic pairing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            // Next item fits but leaves another residual: reward if the
            // double residual stays in a useful class.
            let nr = post_residual - next_item_size;
            if nr >= 10 { score -= 6.0; } else { score += 5.0; }
        }
        // Next item too big for this bin's post-residual: mild penalty,
        // but softened if other bins can absorb the next item.
        if next_item_size > post_residual && fitting_bins_count <= 1 {
            score += 4.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin (unless post_residual is dead space).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin should only win when the
    // current fit is poor. Penalize the empty-bin candidate by its
    // "wasted capacity" so it loses against decent fits.
    if bin_residual == bin_capacity {
        score += 20.0 + 0.3 * open_bins_count as f64;
        // But late in the stream, opening fresh bins is cheaper than
        // fragmenting many small residuals.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 18.0 * progress;
    }

    // Prefer bins whose residual deviates favorably from the mean:
    // placing into a below-average-residual bin consolidates space.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Small tie-break: prefer more filled bins (lower residual before).
    score += 0.05 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps hard.
    // A post_residual below the minimum item size is pure waste.
    if post_residual < 10 && post_residual > 0 {
        score += 40.0;
    } else if post_residual > 0 && post_residual < 20 {
        score += 15.0;
    } else if post_residual == 0 {
        // Perfect fit is highly desirable.
        score -= 25.0;
    }

    // Reward leaving room for the lookahead item (k=2 lookahead).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 10.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // Open-bin pressure: when many bins are open, prefer filling existing ones
    // over spreading items; penalize placements that waste space in that regime.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * (post_residual as f64 / bin_capacity as f64) * 8.0;

    // Tight fits (small relative waste) get a bonus scaled by pressure.
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - waste_frac) * 3.0;

    // New-bin candidate: only attractive when current bin fits are poor.
    if bin_residual == bin_capacity {
        // Neutral base; slightly penalized so existing tight fits win,
        // but becomes attractive when all open bins would leave big waste.
        score += 5.0;
        if post_residual > 40 {
            score -= 3.0; // large item into fresh bin is fine
        }
    }

    // Progression: later in the stream, be more conservative about waste.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.15;

    // Coupling with mean residual: prefer bins below mean residual (tighter bins).
    score += (mean_residual - post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post residual, but weight it non-linearly
    // (dead space matters more when it is small-but-unusable).
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    score = pr * (1.0 + 0.5 * (1.0 - pr / cap));

    // --- 2-step lookahead: reward when next item fits the post residual ---
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual >= next_item_size {
            // Slack after placing the next item too; small slack = great chain.
            let slack_after_next = post_residual - next_item_size;
            score -= 12.0 * (1.0 - slack_after_next as f64 / cap);
            // Perfect chain: post_residual exactly matches next item.
            if slack_after_next == 0 {
                score -= 15.0;
            }
        } else {
            // Next item cannot use this bin's leftover: penalize proportionally
            // to how close-but-failing the leftover is (near-miss dead space).
            let miss = (next_item_size - post_residual) as f64;
            if post_residual > 0 && miss <= 20.0 {
                score += 6.0 * (1.0 - miss / 20.0);
            }
        }
    }

    // --- Relative to mean residual: prefer using below-average-residual bins ---
    // (tighten crowded bins, keep loose bins flexible for future large items).
    score += 0.35 * (mean_residual - bin_residual as f64);

    // --- Last-chance bonus: if this is the only bin that fits, avoid opening a new bin ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive late in the stream or when the
        // item is large and would leave an open bin nearly empty.
        let progress = step_index as f64 / total_items.max(1) as f64;
        let waste_elsewhere = (bin_residual - item_size) as f64 / cap;
        // Penalize new bins by default; relax when many bins are open (spread risk)
        // or when the item is huge (>= 80% of capacity).
        let mut new_bin_penalty = 8.0;
        if item_size as f64 >= 0.8 * cap {
            new_bin_penalty -= 6.0;
        }
        if open_bins_count > 4 {
            new_bin_penalty -= 1.5;
        }
        new_bin_penalty -= 2.0 * progress;
        score += new_bin_penalty;
        // A fresh bin leaves a full residual: that residual is actually valuable,
        // so slightly discount the raw post_residual term for it.
        score -= 0.15 * pr;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness;

    // Penalize dead space: post_residual too small to hold typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // unusable sliver
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / (bin_capacity as f64));
        } else {
            score += 3.0; // next item can't follow here
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin is
    // nearly full or the fit is poor.
    if bin_residual == bin_capacity {
        let fill = item_size as f64 / bin_capacity as f64;
        score += 25.0 * (1.0 - fill);
        if fitting_bins_count > 0 {
            score += 10.0; // an open bin could take it
        }
    }

    // Global pressure: many open bins with large mean residual -> prefer
    // consolidating into existing bins.
    if open_bins_count > 2 {
        score += 0.05 * (open_bins_count as f64) * (mean_residual / (bin_capacity as f64));
    }

    // Time horizon: late in the stream, be more conservative (avoid waste).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on, prefer bins that leave small post_residual (tight packing);
    // later, tolerate larger residuals to keep flexibility.
    let norm_pr = pr / cap;
    let flex = 0.5 + 1.5 * progress;
    score += flex * (norm_pr * norm_pr) * cap;

    // Smooth interaction: residual vs mean residual deviation, weighted by progress.
    let dev = pr - mean_residual;
    score += (0.3 + 0.7 * progress) * 0.25 * dev;

    // Reward tight fits (small post_residual) with a cubic term.
    score -= (1.0 - norm_pr).powi(3) * (0.5 * cap) * (1.0 - 0.5 * progress);

    // Penalize bins that cannot also fit the next item if post_residual is close to it.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = pr - nxt;
        if gap >= 0.0 {
            // smooth decay of reward as gap grows
            let closeness = (1.0 - gap / cap).max(0.0);
            score -= closeness * closeness * nxt * 0.6;
        } else {
            // post_residual just below next item: mildly penalize
            score += 0.2 * (-gap) * (0.5 + 0.5 * progress);
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 6.0 * (1.0 + progress);
    }

    // New-bin candidate: penalize mildly early, more when many bins are open and residuals small.
    if bin_residual == bin_capacity {
        let avg_fill = cap - mean_residual;
        score += 3.0 + 0.05 * open_bins_count as f64 + 0.02 * avg_fill * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic penalty on wasted space fraction
    let waste_frac = post_residual as f64 / cap;
    score += 40.0 * waste_frac * waste_frac;

    // Perfect fit jackpot
    if post_residual == 0 {
        score -= 100.0;
    }

    // Harmonic classes: bucket post_residual into residue classes mod 10,
    // favor classes that historically pair well (small usable slivers)
    let hclass = post_residual % 10;
    let class_bias = match hclass {
        0 => -12.0,
        1 => -8.0,
        2 => -5.0,
        3 => -3.0,
        4 => 2.0,
        5 => 4.0,
        6 => 6.0,
        7 => 8.0,
        8 => 10.0,
        _ => 12.0,
    };
    score += class_bias as f64;

    // Integer-division threshold: residual in [1..=10] is a "dead sliver"
    if post_residual > 0 && post_residual <= 10 {
        score += 15.0;
    }
    // Residual in (10..=20] is still hard to fill with 10..80 items
    if post_residual > 10 && post_residual <= 20 {
        score += 6.0;
    }

    // Lookahead coupling: reward if next item exactly fits post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / cap);
        } else {
            // next item won't fit here; penalize slightly more for big leftovers
            score += 5.0;
        }
        // harmonic match: next_item_size shares residue class with post_residual
        if next_item_size % 10 == post_residual % 10 && next_item_size <= post_residual {
            score -= 8.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && post_residual < bin_residual {
        score -= 30.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current
    // fits are all poor (residual would be large) or few bins are open
    if bin_residual == bin_capacity {
        score = 55.0;
        if open_bins_count == 0 {
            score -= 60.0;
        }
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
        if fitting_bins_count == 1 {
            score += 25.0; // keep the last-chance bin alive
        }
        // late in stream, prefer consolidation into open bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * progress;
        // if mean residual across bins is large, don't open a new bin
        if mean_residual > item_size as f64 {
            score += 15.0;
        }
    }

    // Mild pressure to reduce open bin count early
    score += 0.5 * open_bins_count as f64 * (1.0 - (post_residual as f64 / cap));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any
    // plausible future item (items >= 1, but tiny gaps are practically
    // unusable) are heavily penalized as absolute waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    }
    if post_residual == 0 {
        // Perfect fill is the best outcome.
        score -= 100.0;
    }

    // Reward tight fits: fraction of bin consumed by this item.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill_ratio;

    // Penalize leaving a gap that cannot fit the known next item but could
    // otherwise be useful: wasted opportunity.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0;
    }
    // Reward leaving a gap that exactly accommodates the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading and
    // prefer compacting into existing bins (penalize new-bin candidate).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + 2.0 * progress);
    if bin_residual == bin_capacity {
        // New empty bin candidate: baseline cost plus pressure.
        score += 40.0 + pressure * 3.0;
    } else {
        // Mild reward for choosing already-open bins when many are open.
        score -= pressure * 0.3;
    }

    // Prefer bins whose residual is close to the item (tightest fit).
    score += (bin_residual as f64 - item_size as f64) * 0.4;

    // Deviation from mean residual: prefer bins that are already low
    // (consolidate waste) when mean residual is high.
    score += 0.2 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual already in score).

    // Aggressive 2-step lookahead: reward when next item exactly fills post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect chain: next item fills this bin exactly
        } else if post_residual >= next_item_size {
            let slack_after_next = post_residual - next_item_size;
            // small leftover after the next item is good
            score -= 20.0 * (1.0 - slack_after_next as f64 / bin_capacity as f64);
        } else {
            // next item cannot follow into this bin: penalize proportionally
            let deficit = (next_item_size - post_residual) as f64;
            score += 8.0 * (deficit / 100.0);
        }
    }

    // Penalize creating unusable dead space relative to mean residual.
    if (post_residual as f64) < mean_residual * 0.5 {
        score += (mean_residual - post_residual as f64) * 0.3;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when open bins are nearly full.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let avg_fill = bin_capacity as f64 - mean_residual;
        if mean_residual < 15.0 {
            score -= 10.0 * (1.0 - progress); // early stream, bins are packed: open fresh
        } else {
            score += 15.0 + avg_fill * 0.1; // discourage wasting a fresh bin
        }
    }

    // Slight preference for filling bins that are already low on space.
    score += (bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Primary: reward tight fits (low post residual) non-linearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 2.0 * fit_ratio * fit_ratio * bin_capacity as f64;

    // Penalize placing small items into bins with large residuals (waste potential).
    let fill = item_size as f64 / bin_residual as f64;
    score -= 5.0 * fill * fill;

    // Lookahead: if the next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 8.0;
        } else if next_item_size <= post_residual {
            score -= 2.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item won't fit here; slight penalty for creating near-dead space.
            if post_residual < next_item_size && post_residual < 20 {
                score += 1.5;
            }
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: only attractive when open bins are congested
    // or the item is large relative to capacity.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let congestion = open_bins_count as f64 / (open_bins_count as f64 + 3.0);
        let big_item = item_size as f64 / bin_capacity as f64;
        // Base cost of a fresh bin, discounted by congestion and item size.
        score += 25.0 - 12.0 * congestion - 8.0 * big_item - 3.0 * progress;
        // Opening a new bin is good when no open bin is a good fit.
        if fitting_bins_count > 0 {
            let best_possible = mean_residual.min(bin_capacity as f64);
            if (best_possible - item_size as f64) < 10.0 {
                score -= 4.0;
            }
        }
    } else {
        // Mild preference for using more-loaded bins (best-fit bias).
        score -= 0.02 * (bin_capacity as f64 - bin_residual as f64);
    }

    // Time horizon: early in the stream, be more conservative about fragmenting
    // residuals; late in the stream, just minimize post residual.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 0.05 * post_residual as f64;

    // Global state coupling: if mean residual is high, favor bins that reduce
    // dispersion (i.e., bins far from the mean get nudged toward use).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score -= 0.03 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Non-linear coupling of post_residual with stream progress
    let pr_norm = pr / cap;
    let poly = pr_norm * pr_norm * (1.0 - pr_norm);
    score += 40.0 * poly * (0.5 + progress);

    // Reward tight fits (small post_residual) more strongly later in the stream
    score -= (1.0 - pr_norm) * (1.0 - pr_norm) * (10.0 + 20.0 * progress);

    // Penalize dead space relative to next item lookahead
    let nx = next_item_size as f64;
    if nx > 0.0 {
        let waste = (pr - nx).max(0.0) / cap;
        score += 15.0 * waste * waste;
        if pr >= nx {
            score -= 8.0 * (1.0 - progress);
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (0.5 + 0.5 * progress);
    }

    // Slight penalty when many bins are open and this fit is loose
    let open_f = open_bins_count as f64;
    score += 0.5 * open_f * pr_norm * pr_norm;

    // Mean residual divergence penalty
    score += 0.1 * (pr - mean_residual).abs();

    // New-bin candidate: prefer opening new bins early or when item is large
    if bin_residual == bin_capacity {
        score -= 5.0 * (1.0 - progress) + 0.2 * it * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: classify leftover space into
    // capacity-fraction buckets. Residuals that are "harmonically usable"
    // (close to a capacity fraction like 1/4, 1/2, 3/4) are less dead.
    let pr = post_residual as f64;
    let frac = pr / cap; // 0..1
    let mut usable = 0.0;
    for (num, den) in [(1usize, 4usize), (1, 3), (1, 2), (2, 3), (3, 4)] {
        let target = num as f64 / den as f64;
        let d = (frac - target).abs();
        // closeness to a harmonic fraction reduces score (residual still useful)
        usable += 1.0 / (1.0 + 40.0 * d * d);
    }
    score -= 6.0 * usable;

    // Integer-division threshold: post_residual divisible by common small sizes
    // (10/20/25/50) means future items can tile it perfectly.
    if post_residual > 0 {
        if post_residual % 10 == 0 { score -= 3.0; }
        if post_residual % 20 == 0 { score -= 2.0; }
        if post_residual % 25 == 0 { score -= 2.0; }
        if post_residual % 50 == 0 { score -= 2.0; }
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / cap).max(0.0);
        } else {
            // next item does NOT fit here: penalize leaving residual that
            // neither fits next item nor is small/dead.
            score += 4.0 * (post_residual as f64 / cap);
        }
    }

    // Dead-space penalty: tiny residuals (< 10, min item size) are wasted.
    if post_residual < 10 {
        score -= 5.0; // fine, bin essentially closed
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when open bins are crowded
    // (mean residual low) or this bin is a fresh empty one with a bad fit.
    if bin_residual == bin_capacity {
        // opening a new bin: penalize when good fits exist elsewhere
        if fitting_bins_count > 1 {
            score += 20.0;
        }
        // early in the stream, opening bins is cheap-ish; later, expensive
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * progress;
        // if mean residual across open bins is large, prefer reusing them
        score += 0.3 * mean_residual;
    }

    // Mild penalty for spreading across too many open bins
    score += 0.5 * open_bins_count as f64;

    // Exact fill reward
    if post_residual == 0 {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny nonzero gaps are nearly unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 - 4.0 * post_residual as f64;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0; // moderately awkward gap
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly in the post residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0;
    }
    if next_item_size > 0 && next_item_size > post_residual {
        score += 5.0; // next item won't fit here; slight penalty
    }

    // Last chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize slightly so we prefer reusing open bins,
    // but relax when too many open bins already exist (fragmentation pressure).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 12.0 + 6.0 * (1.0 - progress);
    }

    // Open bins pressure: many open bins -> prefer filling existing ones.
    score += 0.15 * open_bins_count as f64;

    // Prefer bins below the mean residual (keep residuals balanced).
    score += 0.05 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item exactly fills post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chain: next item seals this bin
        } else if next_item_size <= post_residual {
            // penalize leftover proportional to mismatch (dead space after next item)
            let leftover = (post_residual - next_item_size) as f64;
            score += 0.5 * leftover;
            // bonus if leftover is small (tight fit)
            if leftover <= 10.0 {
                score -= 15.0;
            }
        } else {
            // next item cannot follow here; leftover becomes dead space
            score += 0.3 * (post_residual as f64);
        }
    }

    // Compare against mean residual: prefer bins tighter than average
    score += 0.4 * (mean_residual - post_residual as f64);

    // Penalize creating very small unusable residuals (dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    if post_residual == 0 {
        score -= 40.0; // perfect closure
    }

    // Last-chance bin: strongly favor if this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate handling: only open a new bin when no open bin fits well
    if bin_residual == bin_capacity {
        // opening new bin is costly; penalize unless lookahead suggests it's needed
        let mut newbin_penalty = 35.0;
        if next_item_size > 0 && next_item_size > bin_residual - item_size {
            // cannot happen for empty bin (residual=capacity fits everything), so keep penalty
        }
        if fitting_bins_count == 0 {
            newbin_penalty -= 60.0; // forced new bin
        }
        // late in stream, prefer reusing existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        newbin_penalty += 20.0 * progress;
        score += newbin_penalty;
    }

    // Slight preference for bins with larger residuals (waste bigger bins first)
    score -= 0.05 * (bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Penalize leaving dead space that no typical item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    }

    // Lookahead: if the next item can still fit here, reward keeping this bin viable.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 * (next_item_size as f64 / 100.0);
        } else {
            // Next item won't fit here; penalize more if we leave large stranded space.
            score += 0.15 * post_residual as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: make empty bin attractive only when fits are poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by stream progress.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 60.0 + 20.0 * (1.0 - progress);
        // If many bins fit the item, opening a new bin is wasteful.
        if fitting_bins_count > 1 {
            score += 40.0;
        }
        // If the current item is large and would leave a good residual in a fresh bin
        // (large item into empty bin is often good), slightly soften the penalty.
        if item_size >= 60 {
            score -= 10.0;
        }
        // If mean residual across open bins is high, prefer using existing bins.
        score += 0.3 * mean_residual;
    }

    // Mild preference to spread load when many bins are open with high mean residual.
    if bin_residual < bin_capacity {
        score += 0.05 * (open_bins_count as f64);
        if (bin_residual as f64 - mean_residual).abs() > 40.0 {
            score += 5.0; // avoid extreme outliers vs. fleet mean
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Smooth non-linear coupling of post_residual with stream progress:
    // waste becomes increasingly costly as the stream advances.
    let waste_weight = 1.0 + 1.5 * progress * progress;
    score += waste_weight * (post / cap) * (post / cap) * cap * 0.5;

    // Reward tight fits (small post_residual) with a quadratic bonus.
    score -= (1.0 - post / cap) * (1.0 - post / cap) * 8.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 + 10.0 * progress;
    }

    // Lookahead: penalize leaving a residual that neither fits the next item
    // well nor is large enough to be useful.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            // Reward leaving exactly the space the next item can use tightly.
            let slack = (post - nxt) / cap;
            score -= (1.0 - slack) * 6.0;
        } else {
            // Dead space relative to next item.
            score += (nxt - post) * 0.15;
        }
    }

    // Penalize bins far below mean residual (fragmented outlier bins).
    score += ((post - mean_residual) / cap).abs() * 3.0;

    // Mild pressure to reuse existing bins instead of opening new ones,
    // scaling with how many bins are already open.
    if bin_residual == bin_capacity {
        score += 4.0 + 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residue modulo 10 (classic dead-space ladder)
    let residue_class = (post_residual % 10) as f64;
    score += residue_class * 0.35;

    // Perfect-fit harmonic classes: post_residual divisible by small integers is valuable
    if post_residual == 0 {
        score -= 60.0;
    } else {
        if post_residual % 10 == 0 { score -= 8.0; }
        if post_residual % 20 == 0 { score -= 4.0; }
        if post_residual % 25 == 0 { score -= 3.0; }
        if post_residual % 50 == 0 { score -= 3.0; }
    }

    // Integer-division threshold: small post_residual = tight fit reward
    let tight = post_residual < 10;
    if tight {
        score -= 25.0;
    } else if post_residual < 20 {
        score -= 10.0;
    }

    // Lookahead coupling: does post_residual match a harmonic class of next_item_size?
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual >= next_item_size && post_residual < next_item_size + 10 {
            score -= 15.0;
        } else if post_residual < next_item_size {
            // dead space for the lookahead item
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
        // modulo coupling: post_residual mod next_item_size small => reusable chunks
        if next_item_size > 0 && post_residual % next_item_size.max(1) <= 5 {
            score -= 6.0;
        }
        let _ = n;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate: penalize slightly so we only open when truly bad fits exist
    if bin_residual == bin_capacity {
        score += 12.0;
        // open a fresh bin if current fits are all poor (large residue class)
        if post_residual > 30 {
            score -= 15.0;
        }
    }

    // Waste relative to mean residual across open bins
    let frac = post_residual as f64 / cap;
    score += (frac - mean_residual / cap).abs() * 10.0;

    // Late-stream consolidation: fewer open bins preferred as stream ends
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * 0.05 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
