    // New-bin candidate handling: only open a new bin when no good fit exists.
    if bin_residual == bin_capacity {
        // default cost of a fresh bin: moderate
        score = 45.0;
        if fitting_bins_count == 0 {
            score = -100.0; // must open a bin
        } else if fitting_bins_count == 1 {
            // last chance exists -> only open new bin if item is large relative to capacity
            score = if item_size as f64 > 0.8 * bin_capacity as f64 { 20.0 } else { 70.0 };
        }
        if next_item_size > 0 && next_item_size >= post_residual && next_item_size <= bin_capacity {
            score -= 10.0; // fresh bin will host next item too
        }
    }

    // Late-stream tightening: as stream progresses, favor closing bins tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item fits into post_residual exactly or well
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 200.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot follow here; penalize small dead space
            let dead = post_residual as f64;
            if dead < next_item_size as f64 {
                score += 0.5 * dead;
            }
        }
    }

    // Relative residual vs mean: prefer bins tighter than average
    score -= 2.0 * (mean_residual - post_residual as f64);

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 300.0;
    }

    // Penalize opening a new bin when decent fits exist among open bins
    if bin_residual == bin_capacity {
        score += 150.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 50.0;
        }
    }

    // Mild late-stream consolidation pressure
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 20.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits: post_residual near 0 is ideal.
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 40.0;

    // Lookahead (k=2): if the next item fits exactly in the post residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Penalize leaving a gap that the next item cannot use at all.
            score += 6.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Penalize placing into bins with large residuals when the item is small
    // (preserve big residual bins for bigger future items).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 10.0;

    // Global state: many open bins with high mean residual -> prefer consolidation.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if mean_residual > item_size as f64 * 1.5 {
        score -= 4.0 * mean_residual / bin_capacity as f64;
    } else {
        score += 3.0;
    }

    // Late in the stream, closing bins tightly matters more.
    score += progress * post_residual as f64 * 0.3;

    // New-bin candidate handling: empty bin gets a moderate penalty so it is
    // only chosen when no existing bin offers a decent fit.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 0.0 } else {
            // how wasteful would using an existing bin be?
            let best_existing_gap = post_residual as f64; // proxy: current call's gap
            (best_existing_gap / bin_capacity as f64).max(0.0)
        };
        score += 20.0 - 15.0 * desperation * progress;
        // Early stream: opening bins is cheap and flexible.
        if progress < 0.2 {
            score -= 10.0;
        }
    }

    // Small tie-breaker favoring fuller bins.
    score -= (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "useful"
    // residue classes (divisible by common small item sizes) are rewarded.
    let cap = bin_capacity as f64;
    let pr = post_residual;

    // Reward post-residuals that are exact multiples of 10 (harmonic alignment).
    if pr % 10 == 0 {
        score -= 6.0 + (pr as f64) * 0.05;
    }
    if pr % 25 == 0 && pr > 0 {
        score -= 3.0;
    }
    // Penalize awkward leftover classes (prime-ish / odd small remainders).
    if pr > 0 && pr < 10 {
        score += 12.0; // dead space dust
    }
    if pr % 10 != 0 && pr >= 10 && pr < 20 {
        score += 4.0;
    }

    // Integer-division threshold: leftover large enough to hold half-capacity
    // chunks is valuable.
    let half = bin_capacity / 2;
    if pr >= half {
        score -= 8.0;
    } else if pr >= half / 2 {
        score -= 2.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 20.0;
        } else if next_item_size < pr {
            score -= (pr - next_item_size) as f64 * 0.3;
            // harmonic check: next item leaves aligned residue again
            if (pr - next_item_size) % 10 == 0 {
                score -= 5.0;
            }
        } else {
            // next item won't fit here; penalize less if we're near stream end
            let progress = step_index as f64 / (total_items.max(1) as f64);
            score += 6.0 * (1.0 - progress);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Prefer tighter bins overall: reward small residual relative to mean.
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    } else {
        score += 1.0;
    }

    // New-bin candidate handling: make empty bin moderately attractive only
    // when nothing good exists; otherwise keep it slightly penalized so we
    // consolidate into open bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // late in stream, opening a bin is riskier (fewer chances to fill)
        score = 30.0 + 20.0 * progress;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 10.0;
        }
    }

    // Mild pressure to reduce open bin count.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no plausible item can use are waste.
    // Items in [1,100]; small unusable gaps (<10) are almost certain dead space.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 30 {
        score += 8.0;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 80.0;
    }

    // Lookahead: reward leaving room for the next item exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual >= next_item_size && post_residual < next_item_size + 10 {
            score -= 20.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 15.0; // next item won't fit here; residual likely dead
        }
    }

    // Last-chance pressure: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 && post_residual >= 10 {
        score -= 30.0;
    }

    // Open-bin pressure: penalize opening new bins when many bins are already open.
    if bin_residual == bin_capacity {
        score += 40.0 + 5.0 * open_bins_count as f64;
        // But allow a new bin late in the stream when open bins are fragmented.
        if open_bins_count as f64 > mean_residual / 10.0 && post_residual == bin_capacity {
            score -= 25.0;
        }
    } else {
        // Favor tighter bins (smaller residual before placement) slightly.
        score += (bin_residual as f64) * 0.05;
    }

    // Early-stream softness: be more exploratory (favor new bins) at the start.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress < 0.2 && bin_residual != bin_capacity {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual).
    score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Aggressive 2-step lookahead: reward when next item fits exactly into post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Perfect chain: this placement sets up the next item exactly.
            score -= 40.0;
        } else if post_residual > next_item_size {
            // Next item fits; reward proportional to how snugly.
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 - slack * 0.15;
        } else {
            // Next item does NOT fit here; penalize creating unusable gap.
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.6;
        }
    } else {
        // Last item: just minimize post_residual.
        score -= 5.0;
    }

    // Compare post_residual relative to mean residual of open bins.
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless it enables
    // a perfect lookahead chain or current fits are poor.
    if bin_residual == bin_capacity {
        let perfect_chain = next_item_size > 0 && post_residual == next_item_size;
        let poor_fits = fitting_bins_count == 0 || (post_residual as f64) < mean_residual * 0.2;
        if perfect_chain {
            score -= 30.0;
        } else if poor_fits {
            score -= 10.0;
        } else {
            // Prefer existing bins: make new bin unattractive.
            score += 60.0;
        }
    }

    // Late in the stream, consolidate: slightly favor reusing existing bins.
    score += progress * 5.0 * (open_bins_count as f64).ln().max(1.0) * 0.0
        + progress * 3.0;

    // Small tie-breaker: prefer bins with less residual overall.
    score += (bin_residual as f64) * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Time horizon: early in the stream, be conservative (keep bins flexible);
    // late in the stream, greedily fill existing bins tightly.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Dead-space penalty: residual that is too small to ever be useful
    // (nothing between 1 and item range can use it well). Penalize tiny leftovers.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0 * (1.0 - t);
    }

    // Lookahead coupling: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Bonus proportional to how snugly the next item would fit too.
            let slack = (post_residual - next_item_size) as f64;
            score -= (1.5 + 4.0 * t) * (1.0 - slack / bin_capacity as f64);
        } else {
            // Post-residual cannot fit next item: mild penalty scaled by how
            // close we came (wasted potential chain placement).
            let gap = (next_item_size - post_residual) as f64;
            score += (gap / bin_capacity as f64) * 6.0 * (1.0 - t);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin for a mediocre fit.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0 + 6.0 * t;
    }

    // New-bin candidate handling: an empty bin is attractive only if no open
    // bin offers a decent fit, or if open bins are already quite full.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; decays late in the stream when
        // consolidating matters less than spreading.
        score += 10.0 + 8.0 * (1.0 - t);
        // If many bins fit the item, opening a new one is wasteful.
        if fitting_bins_count > 0 {
            score += 6.0 + 2.0 * (fitting_bins_count.min(6) as f64);
        }
        // If open bins are nearly full on average, a new bin is fine.
        score -= (mean_residual / bin_capacity as f64) * 14.0;
    } else {
        // Reward placing into already-open bins, more so when they are fuller
        // (best-fit flavor with a fullness bias).
        let fullness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
        score -= 2.0 + 5.0 * fullness;

        // Perfect-fit bonus.
        if post_residual == 0 {
            score -= 15.0;
        }

        // Penalize scattering across many open bins when residuals are large.
        if open_bins_count > 4 {
            score += (open_bins_count as f64).ln() * (mean_residual / bin_capacity as f64) * 1.5;
        }
    }

    // Slight global pressure: as stream progresses, tighten preference for
    // minimal post-residual.
    score *= 1.0 + 0.3 * t;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let coupling = norm_pr * norm_pr * (1.0 - progress) * 30.0
                 + norm_pr * progress * progress * 15.0;
    score += coupling;

    // Reward tight fits (small post_residual) increasingly late in the stream
    score -= (1.0 - norm_pr).powi(3) * (10.0 + 20.0 * progress);

    // Penalize dead space below the smallest plausible item, smoothly
    let dead = (10.0 - pr).max(0.0) / 10.0;
    score += dead * dead * 25.0;

    // Lookahead: if next item fits into post_residual, reward this bin
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 8.0 + 6.0 * (1.0 - progress);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize mildly so we prefer reusing open bins,
    // unless residuals across open bins are badly fragmented
    if bin_residual == bin_capacity {
        score += 20.0 - 15.0 * (mean_residual / cap).min(1.0);
    } else {
        // Slight bonus for bins below mean residual (tighter bins first)
        score -= (mean_residual - pr).max(0.0) * 0.05;
    }

    // Mild penalty for many open bins to encourage consolidation
    score += open_bins_count as f64 * 0.02 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: prefer residuals that are multiples of
    // common item-size divisors (perfect fits leave reusable "harmonic" space).
    let pr = post_residual;
    let harmonic_bonus = if pr == 0 {
        -60.0 // perfect fit: ideal
    } else if pr % 10 == 0 {
        -25.0
    } else if pr % 5 == 0 {
        -12.0
    } else if pr % 2 == 0 {
        -5.0
    } else {
        8.0 // odd residual: dead space risk
    };
    score += harmonic_bonus;

    // Penalize residuals in the awkward band (51..=66): too big to waste,
    // too small for typical mid items.
    if pr > 50 && pr <= 66 {
        score += 18.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size < pr {
            // fractional match quality
            let q = (pr as f64 - next_item_size as f64) / cap;
            score -= 20.0 * (1.0 - q * 4.0).max(0.0);
        } else {
            score += 10.0; // next item won't fit here
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin should only win when nothing fits well.
    if bin_residual == bin_capacity {
        // Base penalty so open bins are preferred...
        score += 40.0;
        // ...unless all open bins leave terrible residuals (many open bins,
        // high mean residual fragmentation, late in stream).
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = mean_residual / cap;
        if fitting_bins_count == 0 {
            score -= 100.0; // nothing fits: must open
        } else if fragmentation > 0.35 && open_bins_count > 2 {
            score -= 30.0 * fragmentation * (0.5 + progress);
        }
    }

    // Mild preference to fill fuller bins (tight packing) via residual scaling.
    score += 0.15 * (bin_residual as f64 / cap) * 10.0;

    // Small penalty for opening bins early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // Dead space = post_residual too small for the smallest plausible item.
    let min_item = 1.0f64;
    if post_residual > 0 && (post_residual as f64) < min_item * 10.0 {
        score += 60.0; // tiny unusable sliver
    } else if post_residual > 0 && post_residual < item_size {
        // Gap below current item size: likely dead unless next item fits
        if next_item_size == 0 || next_item_size > post_residual {
            score += 35.0 * (1.0 - (post_residual as f64) / (bin_capacity as f64));
        }
    }

    // Reward tight fits (small post_residual) super-linearly.
    if post_residual <= item_size / 2 {
        score -= 25.0;
    }
    if post_residual == 0 {
        score -= 45.0; // perfect fill
    }

    // Lookahead: if next item fits exactly into post_residual, reward strongly.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    } else if next_item_size > 0 && next_item_size < post_residual {
        score -= 8.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 12.0; // gap unusable by the known next item
    }

    // Last-chance pressure: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bins pressure: prefer consolidating when many bins are open.
    score += (open_bins_count as f64) * 1.5 * (1.0 - (post_residual as f64) / (bin_capacity as f64));

    // Prefer bins with residuals close to the mean (balanced packing).
    score += 0.3 * ((bin_residual as f64) - mean_residual).abs();

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let bad_fit = post_residual > item_size && fitting_bins_count == 0;
        if bad_fit {
            score -= 20.0;
        } else {
            score += 25.0 + (open_bins_count as f64) * 2.0;
        }
    }

    // Early stream: be slightly conservative, keep large gaps for big future items.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if post_residual > 40.0 {
        score -= 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward: zero residual is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // exactly matches the next item size (perfect 2-chain).
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs();
        if diff == 0 {
            score -= 500.0;
        } else {
            // Penalize residuals the next item cannot use proportionally.
            score += diff as f64 * 0.8;
        }

        // Reward near-matches within a small tolerance band.
        if diff <= 5 && post_residual >= next_item_size {
            score -= 150.0;
        }
    }

    // Compare post_residual against mean residual across open bins:
    // leaving less-than-average slack is good (tight packing).
    score += (post_residual as f64 - mean_residual) * 0.5;

    // Last-chance bin: strongly favor using the only bin that fits,
    // otherwise a new bin gets opened.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // Penalize creating small unusable fragments (< 10) unless zero.
    if post_residual > 0 && post_residual < 10 {
        score += 200.0;
    }

    // Slight penalty for opening a brand-new bin when many bins exist.
    if bin_residual == bin_capacity {
        score += 50.0 + open_bins_count as f64;
    }

    // Early in the stream, be more liberal with new bins (spread items).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score -= (1.0 - progress) * 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits: small post-residual is good.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Perfect fit gets a big bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            // Extra reward if the next item then fits snugly too.
            let second_left = post_residual - next_item_size;
            score -= 6.0 * (1.0 - (second_left as f64) / (bin_capacity as f64));
        } else {
            // Post-residual can't host next item: penalize proportionally.
            score += 5.0 * (next_item_size as f64 / 100.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a bin is expensive when many open
    // bins can still absorb items, but attractive when residuals are fragmented.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by stream progress.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut new_bin_score = 55.0 - 20.0 * progress;

        // If open bins are fragmented (low mean residual), a fresh bin is good.
        new_bin_score -= 15.0 * (1.0 - mean_residual / (bin_capacity as f64));

        // If the next item is large and nothing else fits it well, new bin helps.
        if next_item_size >= 60 {
            new_bin_score -= 8.0;
        }

        // Late in the stream, avoid leaving many half-empty bins.
        if progress > 0.8 {
            new_bin_score += 10.0;
        }

        score = score.min(new_bin_score.min(score + 45.0));
        return new_bin_score.max(score - 45.0).max(0.0) + score - score; // placeholder-free normalization
    }

    // Mild penalty for spreading across too many open bins.
    score += 0.15 * open_bins_count as f64;

    // Encourage filling bins with large residuals when item is large.
    if item_size >= 50 && bin_residual >= item_size {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_post = post / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_post * norm_post * (1.0 - norm_post) * (1.0 - norm_post);
    let mut score = post
        - 18.0 * poly * (1.0 + 2.0 * progress)
        + 8.0 * norm_post * progress * progress;

    // Reward tight fits (small post_residual) more strongly late in stream
    let tightness = 1.0 - norm_post;
    score -= 6.0 * tightness * tightness * (0.5 + progress);

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: penalize if next item cannot use this residual
    if next_item_size > 0 {
        let next_fits = (next_item_size as f64) <= post;
        if !next_fits {
            score += 5.0 + 10.0 * norm_post * (1.0 - progress);
        } else {
            score -= 3.0 * (post - next_item_size as f64).abs() / cap;
        }
    }

    // New-bin candidate handling: mildly discourage opening new bins when good fits exist
    if bin_residual == bin_capacity {
        score += 12.0 + 10.0 * (1.0 - progress);
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Dampen with mean residual context
    score -= 2.0 * (mean_residual - post) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space by capacity fractions
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;
    let post = post_residual;
    let res_class: f64 = if post == 0 {
        -60.0 // perfect fit, strongly favored
    } else if post < eighth {
        -25.0 // near-perfect: tiny dead space
    } else if post % quarter == 0 {
        -18.0 // post_residual lands on a harmonic boundary (25/50/75) — reusable by common sizes
    } else if post % eighth == 0 {
        -10.0 // eighth-boundary leftover
    } else if post < quarter {
        5.0
    } else if post < bin_capacity / 2 {
        15.0
    } else {
        30.0 // large leftover: wasteful placement
    };
    score += res_class;

    // Reward tight fits scaled by how tight (nonlinear)
    let tightness = 1.0 - (post as f64) / cap;
    score -= 20.0 * tightness * tightness;

    // Harmonic lookahead: does next_item_size fit into post_residual exactly or on a boundary?
    if next_item_size > 0 {
        if next_item_size <= post {
            let next_post = post - next_item_size;
            if next_post == 0 {
                score -= 30.0; // chains to a perfect fit
            } else if next_post % quarter == 0 {
                score -= 12.0;
            } else if next_post < eighth {
                score -= 6.0;
            } else {
                score += (next_post % eighth) as f64 * 0.5;
            }
        } else {
            score += 8.0; // next item can't reuse this leftover
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize opening bins unless current leftovers are bad
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let avg_dead = mean_residual - 0.0;
        // open new bin only if mean residual of open bins is small (they're full-ish)
        let open_penalty = if mean_residual < 15.0 { -10.0 } else { 25.0 + avg_dead };
        score += open_penalty + 20.0 * (1.0 - progress) * (open_bins_count as f64).min(10.0);
        // never open when a perfect or near-perfect fit exists elsewhere
        if post == 0 { score += 100.0; }
    }

    // Mild preference for filling bins that are already committed
    score -= (bin_capacity - bin_residual) as f64 * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size (<=10)
    // are "perfect" (full bins) and heavily rewarded; residuals in the awkward
    // 11..=19 band are dead space no future item (min size 1..10 typical) may fill.
    if post_residual == 0 {
        score -= 60.0; // perfect fill
    } else if post_residual < 10 {
        score -= 25.0; // near-perfect, unusable gap but tiny
    } else if post_residual <= 19 {
        score += 30.0; // awkward dead space: too small for most items
    }

    // Reward tight fits: the smaller the item relative to the residual, the better.
    if bin_residual > 0 {
        let tightness = item_size as f64 / bin_residual as f64;
        score -= 20.0 * tightness;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure from open bins.
        score = 100.0 + 8.0 * open_bins_count as f64;
        // If the next item fits perfectly in a fresh bin alongside... mild discount
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // fresh bin can still host the next item afterwards: slight relief
            score -= 5.0;
        }
        // Early in the stream, opening bins is cheaper (builds a pool).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * (1.0 - progress);
    } else {
        // Using existing bins is favored when open_bins_count is high.
        score -= 0.5 * open_bins_count as f64;
    }

    // Lookahead: if the next item exactly fits the post-residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 50.0;
    } else if next_item_size > post_residual && post_residual > 0 && post_residual < 10 {
        score += 10.0; // dead space confirmed by lookahead
    }

    // Slight preference for bins below mean residual (consolidating emptier space).
    score -= 0.2 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect match: post_residual equals next item size -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near match: next item fits with small leftover afterwards.
    if next_item_size > 0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        score -= 30.0 - (after as f64).min(30.0);
    }
    // Next item does not fit in leftover: penalize proportional dead space.
    if next_item_size > 0 && post_residual < next_item_size {
        let waste = (next_item_size - post_residual) as f64;
        score += 0.35 * waste;
    }

    // Compare against mean residual: bins with residual below mean are more "loaded",
    // filling them tightly is good; bins above mean should be kept flexible.
    if (post_residual as f64) < mean_residual {
        score -= 6.0;
    } else {
        score += 4.0;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }
    // Many fitting bins: slight penalty to keep diversity of residual sizes.
    if fitting_bins_count > 3 {
        score += 3.0;
    }

    // Penalize leaving very small unusable slivers (< 10, min item size).
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Early in stream: be more conservative, prefer tight fits; late: reduce waste emphasis.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 - 0.15 * progress;

    // New-bin candidate (empty bin): only attractive if no open bin fits well.
    if bin_residual == bin_capacity {
        score += 15.0 + open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic penalty on wasted space
    let waste = post_residual as f64;
    score += 0.35 * waste * waste / (bin_capacity as f64);

    // Perfect or near-perfect fit bonus
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 2 {
        score -= 250.0;
    }

    // Lookahead: reward bins whose post-residual matches the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 60.0 / (1.0 + slack);
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // post-residual too small for next item: dead space penalty
        score += 25.0 + 0.5 * post_residual as f64;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 180.0;
    }

    // Prefer fuller bins when many bins are open
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 40.0 * fill_ratio * (1.0 + open_bins_count as f64 * 0.05);

    // Mean residual coupling: bins with residual below mean are good targets
    let dev = mean_residual - bin_residual as f64;
    score += 0.2 * dev;

    // Time horizon: early in stream, be conservative about new bins;
    // late in stream, allow tighter packing greed
    let t = step_index as f64 / (total_items.max(1) as f64);
    score -= 30.0 * t * fill_ratio;

    // New bin candidate: penalize moderately so it's chosen only when fits are bad
    if bin_residual == bin_capacity {
        score += 90.0 - 60.0 * t;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 20.0; // fresh bin can serve both items
        }
        if fitting_bins_count == 0 {
            score -= 400.0; // no alternative
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: quadratic penalty on post_residual (wasted space), scaled by capacity.
    let mut score = (post / cap) * (post / cap) * cap;

    // Smooth non-linear coupling: waste penalty grows with stream progress
    // (later in the stream, tight packing matters more).
    let progress_coupling = 1.0 + 2.0 * progress * progress;
    score *= progress_coupling;

    // Reward tight fits: subtract a bonus proportional to fill fraction,
    // amplified non-linearly near-full placements.
    let fill = item_size as f64 / cap;
    score -= fill * fill * cap * 0.5;

    // If the next item fits exactly into post_residual, strongly reward this bin
    // (perfect chaining), with a smooth decay as slack grows.
    if next_item_size > 0 && next_item_size <= post_residual {
        let chain = 1.0 - (post - next_item_size as f64) / cap;
        score -= 6.0 * chain * chain;
    }

    // Penalize leaving residual too small for the lookahead item (dead space),
    // smoothly scaled by how close the next item is to fitting.
    if next_item_size > post_residual {
        let gap = (next_item_size as f64 - post) / cap;
        score += 4.0 * gap * gap;
    }

    // Last-chance bin: this is the only bin that fits; strongly favor using it
    // over opening a new bin, especially as the stream matures.
    if fitting_bins_count == 1 {
        score -= 5.0 + 10.0 * progress;
    }

    // Mild pressure to consolidate: prefer bins when many are open.
    score += (open_bins_count as f64).ln().max(0.0) * post * 0.02;

    // Prefer bins whose residual is already below mean (compact existing bins),
    // smooth interaction with mean_residual.
    score += (mean_residual - post).max(0.0) * 0.1;

    // New-bin candidate: penalize opening a new bin unless the item is large
    // and residual space elsewhere is scarce; make it smooth via mean residual.
    if bin_residual == bin_capacity {
        let scarcity = (mean_residual / cap).min(1.0);
        score = cap * (0.6 + 0.4 * progress) - 3.0 * (1.0 - scarcity);
        // A new bin is attractive when the item nearly fills it alone.
        score -= fill * cap * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are strongly preferred
    score -= (bin_capacity as f64 - post_residual as f64) * 0.9;

    // Harmonic class of post_residual: dead space in awkward classes penalized
    let pr = post_residual;
    if pr > 0 {
        let class = pr % 10;
        // small dead space (1..=9) is hard to reuse -> penalize
        if class > 0 && class <= 5 {
            score += 12.0 - 2.0 * class as f64;
        } else {
            score -= 3.0;
        }
        // divisible residuals (nice harmonic slots) rewarded
        if pr % 20 == 0 { score -= 6.0; }
        if pr % 25 == 0 { score -= 4.0; }
        if pr % 50 == 0 { score -= 3.0; }
    }

    // Lookahead coupling: keep room for the next item if possible
    if next_item_size > 0 {
        if pr >= next_item_size {
            score -= 8.0;
            // exact pairing: post residual equals next item -> perfect chain
            if pr == next_item_size { score -= 10.0; }
            else {
                let slack = (pr - next_item_size) % 10;
                if slack == 0 { score -= 4.0; } else { score += slack as f64 * 0.5; }
            }
        } else {
            score += 6.0;
        }
    }

    // Last-chance bin: avoid opening a new bin if this fits decently
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when open bins are crowded or fit is poor
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowded = mean_residual < item_size as f64 * 0.5;
        if crowded || (fitting_bins_count <= 1 && item_size > 50) {
            score -= 10.0 + 5.0 * progress;
        } else {
            score += 25.0 + mean_residual * 0.3;
        }
    }

    // Mild pressure toward consolidating among many open bins
    score += open_bins_count as f64 * 0.15;
    score += (mean_residual - post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A gap is "unusable" if it cannot fit even the smallest plausible item (1..=3),
    // or if it is too small for the lookahead item while being nonzero.
    if post_residual > 0 && post_residual <= 3 {
        score += 25.0;
    }
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        score += 12.0 + (next_item_size - post_residual) as f64 * 0.5;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 20.0;
    }

    // Reward tight fits relative to bin capacity.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 10.0;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: prefer it only when open bins are crowded or the fit
    // here would create large dead space.
    if bin_residual == bin_capacity {
        // Base penalty so a new bin is only chosen when justified.
        score += 10.0 + open_bins_count as f64 * 0.0;
        // Justify new bin when mean residual of open bins is too small
        // relative to item size (bins are nearly full).
        if mean_residual < item_size as f64 * 1.2 {
            score -= 20.0;
        }
        // If the next item is large and current bins have small residuals,
        // reserving a fresh bin is attractive.
        if next_item_size > 0 && mean_residual < next_item_size as f64 {
            score -= 8.0;
        }
    }

    // Open-bin pressure: many open bins -> discourage spreading, encourage
    // filling existing bins (penalize new-bin creation indirectly).
    score += open_bins_count as f64 * 0.3;

    // Early in the stream, allow slightly more freedom to open bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    score = post_residual as f64 * 0.6;

    // Aggressive 2-step lookahead: reward bins whose post_residual exactly
    // or nearly matches the next item size (perfect chained placement).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        let next_frac = next_item_size as f64 / bin_capacity as f64;
        if gap == 0.0 {
            score -= 40.0 + 20.0 * next_frac; // perfect chain: huge reward
        } else if gap <= 10.0 {
            score -= 18.0 * (1.0 - gap / 10.0);
        } else {
            // penalize post_residuals that are just barely too small OR wastefully large
            score += 0.35 * gap;
        }
        // If post_residual can't fit next item and is small, it's dead space
        if (post_residual as i64) < (next_item_size as i64) && post_residual < 10 {
            score += 12.0;
        }
    }

    // Relative-to-mean coupling: bins with residual far below mean are scarce
    // space; using them for a loose fit is costly, tight fit is good.
    let pr = post_residual as f64;
    if pr < mean_residual {
        score -= 0.25 * (mean_residual - pr);
    } else {
        score += 0.15 * (pr - mean_residual);
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin is a fresh resource; prefer it
    // only when the current item is large relative to typical residuals
    // (i.e., all open residuals are small and post_residual would be tiny).
    if bin_residual == bin_capacity {
        // neutral-ish baseline; slight penalty so we prefer reusing bins with
        // genuinely good fits, but competitive when fits are terrible.
        score = 45.0 + 0.3 * item_size as f64;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 8.0; // fresh bin chains well with next item
        }
        if fitting_bins_count == 1 {
            score += 20.0; // don't abandon the sole fitting bin for a new one
        }
    }

    // Late-stream consolidation: as stream progresses, favor closing out bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 6.0 * progress * (1.0 - pr / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Base best-fit bias: reward tight fits (small post_residual).
    score -= (post_residual as f64) * 0.9;

    // Perfect-fit lookahead: if the next item exactly fills the leftover, strong reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 60.0;
    }
    // Next item fits in the post-residual: mild reward (keeps chain going).
    else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0;
    }
    // Next item cannot fit in leftover: penalize dead-space creation.
    else if next_item_size > 0 && next_item_size > post_residual {
        score += 8.0;
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin, more so when good
    // alternatives exist or many bins are already open.
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * (open_bins_count as f64).min(20.0);
        if fitting_bins_count >= 1 {
            score += 20.0;
        }
        // Late in the stream, closing out open bins is preferable.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Prefer bins whose residual deviates favorably from the mean:
    // placing into a below-average-residual bin concentrates fullness.
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Slight preference for fuller bins (smaller residual) overall.
    score += 0.1 * (cap - bin_residual as f64).max(0.0) * 0.0;
    score += 0.05 * (bin_residual as f64);

    // Nonlinear tightness term: reward post_residual near zero or
    // large enough to be reusable (> 20), penalize awkward mid-range.
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 20.0 {
        score += (20.0 - pr) * 0.5;
    } else if pr >= 20.0 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early stream: prefer tight fits but tolerate larger residuals to seed bins.
    // Late stream: aggressively penalize residual waste.
    let progress_weight = 0.5 + 1.5 * progress * progress;
    let mut score = pr * (0.6 + 0.8 * progress_weight);

    // Smooth convex penalty for large residuals (dead space), grows super-linearly.
    score += 40.0 * norm_pr * norm_pr * (0.5 + progress);

    // Cubic term: strongly punish near-empty post residuals late in stream.
    score += 25.0 * norm_pr * norm_pr * norm_pr * progress;

    // Reward good fits (small post_residual) more as stream progresses.
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * 15.0 * (0.3 + 0.7 * progress);

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0 + 15.0 * progress;
    }

    // Lookahead: favor leaving space for the next item.
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if pr >= ns {
            let gap = (pr - ns) / cap;
            score -= 12.0 * (1.0 - gap) * (1.0 - gap);
        } else {
            score += 8.0 * (ns - pr) / cap;
        }
    }

    // Prefer filling bins when many are open; penalize spreading thin.
    score += (open_bins_count as f64).ln().max(0.0) * 2.0 * norm_pr;

    // Slight preference for bins below mean residual (consolidate waste).
    score += 0.3 * (pr - mean_residual);

    // New-bin candidate: keep it neutral-to-slightly-high unless item is large
    // relative to residual of typical open bins.
    if bin_residual == bin_capacity {
        let size_frac = item_size as f64 / cap;
        score = 30.0 * size_frac * (1.0 - progress) + 10.0 * size_frac * progress + pr;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: overwhelming reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Lookahead: exact match for the next item in this bin's residual.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 500.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Next item fits here: mild reward proportional to leftover after both.
        let double_left = post_residual - next_item_size;
        score -= 60.0 - (double_left as f64) * 0.4;
    } else if next_item_size > post_residual && post_residual > 0 {
        // Dead space that even the lookahead item can't use: penalize.
        score += (post_residual as f64) * 0.5;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // Harmonic / modulo classes on post_residual: small residuals are dead space.
    // Classify post_residual into capacity fractions.
    let pr = post_residual;
    if pr > 0 {
        // Residuals <= 10 are nearly unusable (min item size assumption broken
        // for 1..100, but tiny residuals still waste space): heavy penalty.
        if pr <= 10 {
            score -= 40.0; // it's dead space, but bin was "used up" — mild reward
        } else if pr <= 20 {
            score += 5.0;
        } else if pr <= 33 {
            score += 10.0;
        } else if pr <= 50 {
            score += 15.0;
        } else {
            score += 20.0;
        }

        // Modulo-10 class: residuals that are multiples of 10 align with
        // common item sizes and are more reusable.
        if pr % 10 == 0 {
            score -= 12.0;
        }
        // Half-capacity residual is a very flexible class.
        if pr == bin_capacity / 2 {
            score -= 8.0;
        }
    }

    // Prefer bins whose residual is already below average (consolidate waste).
    if (bin_residual as f64) < mean_residual {
        score -= 15.0;
    } else {
        score += 5.0;
    }

    // Late in the stream: be more aggressive about filling bins tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.3 * progress;

    // New-bin candidate: penalize opening a new bin unless existing fits are bad.
    if bin_residual == bin_capacity {
        // Base cost of a new bin; offset if many open bins (prefer consolidation).
        score += 90.0 + 8.0 * (open_bins_count as f64).min(20.0);
        // If this is the last-chance situation (only one fitting bin), new bin is bad.
        if fitting_bins_count <= 1 && item_size <= bin_capacity {
            score += 50.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (<10) are heavily penalized,
    // medium gaps (10..=30) moderately penalized since many items can still use them.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // tiny dead space is pure waste
    } else if post_residual >= 10 && post_residual <= 30 {
        score += 8.0 * (1.0 - (post_residual as f64 - 10.0) / 20.0);
    } else if post_residual == 0 {
        score -= 25.0; // perfect fill: strongly reward
    }

    // Prefer bins whose residual was tight relative to the item (good fit ratio).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 15.0 * fit_ratio * fit_ratio;

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> favor consolidating into existing bins.
    let pressure = (open_bins_count as f64 / (open_bins_count as f64 + 4.0)).sqrt();
    score -= 10.0 * pressure;

    // Lookahead: if next item fits the post-residual exactly or well, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        let next_fit = next_item_size as f64 / post_residual as f64;
        score -= 12.0 * next_fit;
    } else if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
        // next item cannot use leftover: leftover is more likely dead space
        score += 6.0 * (post_residual as f64 / 40.0).min(1.0);
    }

    // Mean residual coupling: prefer bins tighter than average (consume the fullest first).
    let dev = mean_residual - bin_residual as f64;
    score -= 0.05 * dev;

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let base = 55.0;
        let scarcity = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        score = base + scarcity * 45.0 - pressure * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual)
    score -= 25.0 * (1.0 - (post_residual as f64) / (bin_capacity as f64));

    // Aggressive 2-step lookahead: perfect chain match with next item
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        // next item fits too, but penalize leftover waste after hypothetical chain
        let chain_waste = post_residual - next_item_size;
        score -= 20.0;
        score += 0.3 * chain_waste as f64;
    } else if next_item_size > 0 {
        // next item cannot follow; dead-space penalty grows with post_residual
        score += 0.5 * post_residual as f64;
    }

    // Relative to mean residual: prefer bins already below average residual (consolidation)
    score += 0.4 * ((post_residual as f64) - mean_residual);

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when no good fit exists
    if bin_residual == bin_capacity {
        score += 45.0 + 0.2 * open_bins_count as f64;
        // late in stream, avoid opening new bins even more
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
    }

    // Mild penalty for many open bins to encourage consolidation
    score += 0.15 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near zero is excellent.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize small unusable dead space (residual below min item size 1 is impossible,
    // but residual far below typical item sizes is wasted).
    if post_residual > 0 && post_residual < 10 {
        score += 6.0; // tiny sliver = dead space
    } else if post_residual >= 10 && post_residual < 20 {
        score += 2.0;
    }

    // Lookahead: if next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 15.0;
        } else if next_item_size <= post_residual {
            let frac = next_item_size as f64 / post_residual as f64;
            score -= 8.0 * frac;
        } else {
            // Next item won't fit here; leftover becomes dead space unless large.
            let leftover = post_residual as f64;
            if leftover < next_item_size as f64 {
                score += 0.04 * (next_item_size as f64 - leftover);
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // Many open bins: prefer filling existing ones rather than spreading.
    let open_pressure = (open_bins_count as f64) / ((total_items.max(1) as f64).sqrt() + 1.0);
    score += 1.5 * open_pressure;

    // Compare residual to mean residual: placing into a bin with residual near the mean
    // keeps balance; extremes (very small residual) are good to consume now.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.03 * dev;
    if (bin_residual as f64) < mean_residual {
        score -= 2.0; // consume bins that are already nearly full
    }

    // Time horizon: late in the stream, be conservative — prefer tight packing,
    // avoid opening new bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 6.0 * progress * tightness;
    if progress > 0.8 && bin_residual < bin_capacity {
        score -= 3.0;
    }

    // New-bin candidate (empty bin): make it moderately attractive only when no
    // open bin offers a good fit; otherwise it should lose to open bins.
    if bin_residual == bin_capacity {
        let base_new = 55.0
            - 25.0 * progress
            - 2.0 * (open_bins_count as f64).ln().max(0.0)
            - (fitting_bins_count as f64);
        // If next item is large and this item is small, opening fresh may be fine.
        let adj = if next_item_size > 0 && next_item_size >= item_size {
            4.0
        } else {
            0.0
        };
        score += base_new + adj;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Base: post residual, mildly super-linear to penalize large dead space
    let mut score = post + 0.35 * (post * post) / cap;

    // Smooth non-linear coupling of waste with stream progress:
    // later in the stream, waste becomes more costly (poly term)
    score += 18.0 * progress * (post / cap).powi(2) * cap / 100.0;

    // Reward tight fits: fill ratio of this placement
    let fill = item / cap;
    score -= 12.0 * fill * (1.0 - progress * 0.5);

    // Lookahead: if the next item fits exactly into post_residual, reward strongly
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let slack_gap = (post - nxt) / cap;
            score -= 10.0 * (1.0 - slack_gap);
        } else {
            // post_residual too small for next item: penalize unusable remainder
            score += 6.0 * (post / cap) * (1.0 - progress);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin has huge residual; make it attractive
    // only when current bins are nearly full / poor fits
    if bin_residual == bin_capacity {
        // neutral-ish baseline: new bin cost grows with number of open bins and progress
        score = 55.0 + 2.0 * (open_bins_count as f64).ln().max(0.0) + 10.0 * progress;
        // if item would leave a very usable residual anyway, slight preference for new bin early
        if post >= 30.0 {
            score -= 5.0 * (1.0 - progress);
        }
    }

    // Slight preference for bins with residuals above the mean (keep balanced options)
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "usable" is leftover space?
    // Residuals that are multiples of common item classes (10,20,25,50) are more reusable.
    let pr = post_residual;
    let class_bonus = if pr == 0 { 60.0 }
        else if pr % 50 == 0 { 30.0 }
        else if pr % 25 == 0 { 20.0 }
        else if pr % 20 == 0 { 16.0 }
        else if pr % 10 == 0 { 10.0 }
        else { 0.0 };
    score -= class_bonus;

    // Dead space penalty: small nonzero residuals are nearly useless.
    if pr > 0 && pr < 10 {
        score += 25.0 * (10 - pr) as f64 / 10.0;
    }

    // Tight fit reward: fraction of bin filled by this item.
    let fill = item_size as f64 / cap;
    score -= 15.0 * fill;

    // Last-chance bin: strongly favor using it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item exactly fits the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size <= pr {
            // next item fits: mild reward proportional to how well it fills leftover
            let nfill = next_item_size as f64 / pr.max(1) as f64;
            score -= 12.0 * nfill;
        } else {
            // next item cannot use this residual: penalize proportionally
            score += 8.0 * (next_item_size as f64 / cap);
        }
    }

    // New-bin candidate: only attractive when no open bin fits or residuals are poor.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let avg_fill = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
        // early stream: keep some openness; late stream: prefer consolidation
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let new_bin_penalty = 70.0 - 30.0 * progress - 20.0 * pressure - 25.0 * (1.0 - avg_fill);
        score += new_bin_penalty.max(-20.0);
    }

    // Prefer bins with more remaining space generally (spread load mildly).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    // Slight preference to fill bins as stream progresses.
    score -= 5.0 * (step_index as f64 / (total_items.max(1) as f64)) * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item (min size 1,
    // but practically < ~10) are wasted. Penalize tiny gaps super-linearly.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64);
    }
    // Mid-range dead space (10..25) is risky: few items fit.
    if post_residual >= 10 && post_residual < 25 {
        score += 8.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * tightness;

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: reward if the next item fits into the post residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 20.0;
        // Extra reward for near-exact pairing.
        let pair_waste = (post_residual - next_item_size) as f64;
        score -= 10.0 * (1.0 - pair_waste / post_residual.max(1) as f64);
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item can't use the gap: mild penalty proportional to gap.
        score += 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: when many bins are open, discourage spreading;
    // prefer filling existing bins rather than opening new ones.
    score += 2.5 * open_bins_count as f64;

    // Discourage new-bin opening when open bins have plenty of room on average.
    if bin_residual == bin_capacity {
        score += 30.0 + 3.0 * open_bins_count as f64;
        if mean_residual > item_size as f64 {
            score += 15.0;
        }
    } else {
        // Reward choosing bins with residuals above the mean (use big gaps first).
        if bin_residual as f64 > mean_residual {
            score -= 6.0;
        } else {
            score += 6.0;
        }
    }

    // Early in stream, be slightly more willing to open bins for good structure.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Slack after the lookahead item would fit
        let slack = (post_residual - next_item_size) as f64;
        score -= 30.0 - slack * 0.5;
    } else if next_item_size > 0 {
        // Lookahead item cannot follow: penalize proportionally to the shortfall
        let shortfall = (next_item_size - post_residual) as f64;
        score += shortfall * 0.4;
    }

    // Reward bins tighter than the mean residual (good compaction)
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize tiny dead space (< 10) that is unusable
    if post_residual < 10 && post_residual > 0 {
        score += 15.0;
    }

    // Late in the stream, prefer tighter packing
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.2 * progress;

    // New-bin candidate: only attractive when no good fit exists
    if bin_residual == bin_capacity {
        score += 40.0 + mean_residual * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let item = item_size as f64;
    let post = post_residual as f64;
    let residual = bin_residual as f64;

    // Base: prefer tight packing (low post residual)
    let mut score = post;

    // Strong reward for exact/near-exact fits
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    }

    // Penalize dead space that is too small to hold typical items
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: reward leaving post_residual that can fit the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual >= next_item_size {
            // next item fits in the leftover: mild reward, scaled by how snugly
            let snug = (post - nxt) / cap;
            score -= 10.0 * (1.0 - snug);
        } else {
            // leftover cannot fit next item: penalize proportionally to wasted potential
            score += 8.0 * (1.0 - post / cap);
        }
        // If next item fits exactly in current bin's residual but we leave post instead,
        // encourage keeping current bin for the next item when post fit is loose
        if bin_residual as u32 == next_item_size && post_residual > 0 {
            score += 20.0; // save this bin's residual for next item exactly
        }
    } else {
        // Last item: any fit is fine, prefer tightest
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin is expensive early (many future items),
    // cheap late. Penalize new bin more when many items remain.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 1.0 };
        let horizon = 1.0 - progress; // remaining fraction of stream
        score += 45.0 * horizon + 10.0;
        // But if no open bin fits well, allow new bin: compare against mean residual
        if fitting_bins_count == 0 {
            score -= 55.0;
        }
        // If open bins are nearly full on average, new bin is reasonable
        if mean_residual < item {
            score -= 30.0;
        }
    } else {
        // Existing bin: slight preference when it's tighter than average
        if residual < mean_residual {
            score -= 6.0;
        } else {
            score += 4.0 * ((residual - mean_residual) / cap);
        }
    }

    // Global state: many open bins -> consolidate into them rather than opening more
    if open_bins_count > 4 && bin_residual != bin_capacity {
        score -= 5.0;
    }

    // Mild nonlinearity: squared waste penalty for large leftovers
    score += (post * post) / (4.0 * cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_pr = pr / cap;

    // Base: penalize post residual, with quadratic growth (dead space is superlinearly bad)
    let mut score = norm_pr * (1.0 + 0.8 * norm_pr);

    // Smooth polynomial coupling with stream progress:
    // early on, prefer tight fits to keep bins compact; later, tolerate spread
    let p2 = progress * progress;
    let p3 = p2 * progress;
    let coupling = norm_pr * (1.0 - progress) * (1.0 + 1.5 * p2 + 0.5 * p3);
    score += 2.0 * coupling;

    // Lookahead: strongly reward if next item fits the post residual (chain packing)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let snug = 1.0 - (pr - nxt) / cap;
            score -= 1.2 * snug * (1.0 + 0.6 * progress);
        } else {
            // penalize leaving residual that no single typical item can use
            score += 0.4 * (1.0 - pr / nxt.max(1.0)).max(0.0);
        }
    }

    // Last-chance bin: heavy reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 3.0;
    }

    // Reward packing into bins that are already relatively full (low residual before placement)
    let pre_fill = 1.0 - bin_residual as f64 / cap;
    score -= 0.5 * pre_fill * pre_fill;

    // Mild penalty for proliferating bins early
    score += 0.02 * (open_bins_count as f64) * (1.0 - progress);

    // New-bin candidate: make it attractive only when existing bins fit poorly
    if bin_residual == bin_capacity {
        // neutral-ish baseline; existing bins with good fits beat it via their discounts
        score += 0.6 + 0.5 * (1.0 - progress);
    }

    // Slight pull toward mean residual to balance bin loads
    score += 0.1 * (pr - mean_residual).abs() / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into small
    // residue classes (mod 10) are "dead" — penalize them.
    let r = post_residual % 10;
    let dead_class = if r == 1 || r == 2 || r == 3 { 1.0 } else { 0.0 };
    score += dead_class * 8.0;

    // Perfect / near-perfect fits get strong rewards.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 3 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 15.0;
    }

    // Fractional fill: reward high utilization of the bin.
    let fill = 1.0 - (post_residual as f64) / cap;
    score -= 12.0 * fill * fill;

    // Lookahead coupling: if next item fits exactly in post_residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size < post_residual {
            let nxt_post = post_residual - next_item_size;
            // reward leaving a residue the next item can finish off
            if nxt_post % 10 == 0 || nxt_post <= 5 {
                score -= 10.0;
            }
            // penalize if next item barely misses post_residual
            let gap = post_residual - next_item_size;
            if gap <= 4 {
                score += 6.0 * (5 - gap) as f64;
            }
        } else {
            // next item won't fit here anyway; slight reward for small leftover
            score -= (post_residual as f64) * 0.05;
        }
    }

    // Integer division threshold: bins with residual in [50, 100) are
    // half-empty; prefer filling those before opening new ones.
    let half_class = post_residual / 50; // 0 if <50, 1 if >=50
    if half_class == 1 {
        score -= 10.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // no open bin fits well. Penalize the fresh bin when many bins fit.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 {
            -20.0
        } else {
            let best = (fitting_bins_count as f64).min(6.0);
            15.0 + 5.0 * best
        };
        score += pressure;
        // early in stream, tolerate new bins; late, discourage
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Many open bins with high mean residual: discourage spreading waste.
    if open_bins_count > 3 {
        let dev = (mean_residual - post_residual as f64).abs();
        score += 0.05 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps quadratically.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    }
    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Lookahead coupling: reward residual that can host the next item exactly-ish.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
            let slack = post_residual as f64 - next_item_size as f64;
            score += 0.15 * slack;
        } else {
            score += 8.0;
        }
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is good.
    score += 2.0 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Mean-residual alignment: prefer bins close to the mean residual (balanced packing).
    score += 0.3 * (bin_residual as f64 - mean_residual).abs();

    // New-bin candidate handling: only open a new bin when no open bin fits well.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { -100.0 } else if fitting_bins_count == 1 && post_residual < 10 { -20.0 } else { 40.0 + 3.0 * open_bins_count as f64 };
        score += pressure;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 0.05 * next_item_size as f64;
        }
    }

    // Mild stream progression: as stream advances, tighten packing further.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 3.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item -> huge reward
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Next item fits in the post residual: strong lookahead reward
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 50.0 + 0.5 * next_item_size as f64;
        // bonus proportional to tightness of the lookahead fit
        let tight = (post_residual - next_item_size) as f64;
        score -= (30.0 - tight.min(30.0)) * 0.8;
    }

    // Penalize residual that is small and unusable (dead space)
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 25 {
        score += (25.0 - post_residual as f64) * 2.0;
    }

    // Penalize leaving residual far above mean_residual (wasteful spread)
    score += 0.15 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: only attractive when no good fit exists elsewhere
    if bin_residual == bin_capacity {
        let has_good_lookahead = next_item_size > 0 && post_residual >= next_item_size;
        if !has_good_lookahead && fitting_bins_count <= 1 {
            score -= 80.0;
        } else {
            score += 200.0;
        }
    }

    // Mild early-stream preference to spread items, late-stream consolidate
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small to be useful later (unusable slivers).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 15.0;
        } else if next_item_size <= post_residual {
            score -= 4.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // Next item won't fit here; slight penalty for wasting residual.
            score += 1.5 * (1.0 - (post_residual as f64 / bin_capacity as f64));
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // Prefer fuller bins when many bins are open (consolidation pressure).
    let fill = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 3.0 * fill * (open_bins_count as f64).ln().max(0.0);

    // Time horizon: early in the stream, be more willing to spread (penalize new-bin less);
    // late in the stream, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: base penalty grows with progress and mean residual availability.
        score += 20.0 + 25.0 * progress;
        if mean_residual >= item_size as f64 {
            score += 6.0; // an open bin could hold it; opening new bin is wasteful
        }
    } else {
        // Reward using existing bins more as stream progresses.
        score -= 6.0 * progress;
        // Slight preference toward bins with residuals near the mean (balance).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Non-linear penalty on residual, amplified over stream progress
    score += 6.0 * pr_norm * pr_norm * (0.5 + progress);

    // Reward tight fits, stronger as stream advances
    let tightness = 1.0 - pr_norm;
    score -= 8.0 * tightness * tightness * tightness * (0.4 + 0.6 * progress);

    // Lookahead coupling: reward residuals that match next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let match_term = 1.0 - ((pr - nx).abs() / cap);
        score -= 5.0 * match_term * match_term;
    }

    // Penalize scarce alternatives lightly; reward when this is last-chance bin
    if fitting_bins_count <= 1 {
        score -= 3.0;
    } else {
        score += 0.8 * (fitting_bins_count as f64).ln();
    }

    // Mean residual deviation: prefer bins near mean to preserve diversity
    score += 0.05 * (pr - mean_residual).abs();

    // Mild penalty for spreading across too many open bins early
    score += 0.3 * (open_bins_count as f64) * (1.0 - progress) * 0.1;

    // New-bin candidate: penalize opening new bins unless current residual is tiny
    if bin_residual == bin_capacity {
        score += 12.0 * (1.0 - progress) + 4.0;
        if pr_norm > 0.2 && next_item_size > 0 {
            score -= 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: partition residuals into classes of 10
    let cls = (post_residual / 10) as f64;
    score += cls * 4.0; // reward low post_residual classes

    // Dead-space penalty: residuals below 10 are unusable for items >=10 (or >=1)
    if post_residual < 10 && post_residual > 0 {
        score += 30.0;
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 100.0;
    }

    // Coupling with next item: if next item fits into post_residual, big reward
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + 0.5 * next_item_size as f64;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item won't fit here; penalize leaving a mid-sized residual that nothing can use
        score += 0.2 * post_residual as f64;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize mildly so we only open when fits are poor
    if bin_residual == bin_capacity {
        score += 20.0;
        // but if no bin fits well, opening is fine — reduce penalty when many bins open
        score -= 0.3 * open_bins_count as f64;
    }

    // Tight fit reward: item fills most of the bin
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 10.0 * fill;

    // Progress-based adaptation: late in stream, prefer tighter packing
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * progress * (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64;

    // Mean-residual coupling: if this bin's residual is far below mean, it's a good squeeze
    score += 0.1 * (mean_residual - post_residual as f64);

    // Integer-division threshold: bins whose residual rounds to a half-capacity class
    let half_cls = (post_residual * 2) / bin_capacity;
    if half_cls == 1 {
        score -= 3.0; // residual near 50 is a flexible class, mildly favored
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable small gaps are heavily penalized.
    let dead_threshold = 9.0; // gaps below smallest plausible item are pure waste
    if (post_residual as f64) < dead_threshold {
        score += 50.0 * (dead_threshold - post_residual as f64);
    }

    // Non-linear penalty on small-but-usable residuals that fragment space.
    if post_residual > 0 {
        let frag = 1.0 / (post_residual as f64);
        score += 3.0 * frag;
    }

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 20.0 * tightness;

    // Pressure from number of open bins: discourage spreading across many bins.
    score += 2.0 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize mildly, but allow if current bin would leave bad dead space.
    if bin_residual == bin_capacity {
        score += 15.0;
        if (bin_residual as f64 - item_size as f64) < dead_threshold {
            score -= 100.0; // opening a new bin beats creating dead space
        }
    }

    // Lookahead coupling: if next item fits exactly into post_residual, reward heavily.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    }
    // Penalize if post_residual is just barely too small for the next item.
    if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual && (next_item_size as i64 - post_residual as i64) <= 10 {
        score += 10.0;
    }

    // Mean residual coupling: prefer bins whose residual deviates below mean (filling laggards).
    score += 0.5 * (mean_residual - post_residual as f64);

    // Slight progression adaptation: later in the stream, be more conservative about new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Near-perfect match: next item fits with small slack
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 200.0 - slack * 2.0;
    } else if next_item_size > 0 {
        // Next item won't fit here afterwards: penalize proportionally
        let miss = (next_item_size - post_residual) as f64;
        score += miss * 1.5;
    }

    // Tight fit reward relative to capacity
    let tightness = (bin_residual - post_residual) as f64 / bin_capacity as f64;
    score -= tightness * 50.0;

    // Compare residual to mean residual across open bins: prefer leaving
    // residuals near the mean (balanced bins), penalize outliers
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.5;

    // Last-chance bin: strongly favor using it rather than opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: only attractive when it enables a future perfect pair
    if bin_residual == bin_capacity {
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity
            && bin_capacity - item_size - next_item_size <= 5 {
            score -= 300.0;
        } else {
            score += 80.0 + (open_bins_count as f64) * 2.0;
        }
    }

    // Early in stream, be more exploratory toward opening bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity && progress < 0.2 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Reward tight fits: the fuller the bin becomes, the bigger the discount.
    let fill = 1.0 - pr / cap;
    score -= 30.0 * fill * fill * fill;

    // Last-chance bin: if this is the only bin that can host the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling (k=2): reward bins whose post-residual still
    // accommodates the next item; penalize bins where the next item
    // would have fit pre-placement but no longer fits afterwards.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= 8.0;
        } else if nxt <= bin_residual as f64 {
            score += 6.0;
        }
    }

    // New-bin candidate handling: opening a fresh bin is expensive;
    // only make it attractive when nothing decent can host the item
    // or the existing residuals are badly fragmented.
    if bin_residual == bin_capacity {
        score += 45.0;
        if fitting_bins_count == 0 {
            score -= 70.0;
        } else {
            // the worse the existing average fit, the more a new bin makes sense
            let best_possible_gap = mean_residual - item_size as f64;
            if best_possible_gap > 30.0 {
                score -= 10.0;
            }
            score += open_bins_count as f64 * 0.5;
        }
    }

    // Deviation from mean residual: prefer bins that leave residuals
    // consistent with the fleet average (avoids orphaned tiny gaps).
    score += (pr - mean_residual) * 0.15;

    // Time horizon: late in the stream, be greedier about filling bins
    // completely since fewer items remain to exploit leftover space.
    let t = step_index as f64 / (total_items.max(1) as f64);
    score -= 6.0 * t * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let poly = norm_pr * norm_pr * (1.0 + 3.0 * progress * (1.0 - progress));
    score += 30.0 * poly;

    // Reward tight fits more strongly as stream progresses.
    let tightness = 1.0 - norm_pr;
    score -= 25.0 * tightness * tightness * (0.5 + progress);

    // Penalize dead space relative to mean residual, smoothed non-linearly.
    let dev = (pr - mean_residual) / cap;
    score += 10.0 * dev * dev.abs();

    // Last-chance bonus: strongly favor the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0 * (1.0 + progress);
    }

    // Lookahead: reward if next item fits the post residual smoothly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fits = if pr as u32 >= next_item_size { 1.0 } else { 0.0 };
        score -= 15.0 * fits * (nxt / cap) * (1.0 - progress);
        score += 8.0 * (1.0 - fits) * (0.3 + 0.7 * progress);
    }

    // New-bin candidate: penalize mildly unless residuals across bins are low.
    if bin_residual == bin_capacity {
        let avg_tight = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
        score += 12.0 - 10.0 * avg_tight * avg_tight * (1.0 + progress);
    }

    // Slight penalty for too many open bins, smoothed.
    score += 2.0 * (open_bins_count as f64).sqrt() * (0.5 + 0.5 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals that are "nice" fractions
    // of capacity (small multiples of 10/20/25/50) are reusable dead space.
    let pr = post_residual;
    let harmonic_bonus: f64 = if pr == 0 {
        -1000.0 // perfect fit, always reward heavily
    } else if pr <= 5 {
        -200.0
    } else if pr % 50 == 0 {
        -150.0
    } else if pr % 25 == 0 {
        -100.0
    } else if pr % 20 == 0 {
        -80.0
    } else if pr % 10 == 0 {
        -50.0
    } else if pr % 5 == 0 {
        -25.0
    } else {
        0.0
    };
    score += harmonic_bonus;

    // Lookahead: if the next item fits exactly in the post-residual, strong reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 120.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot fit here regardless; mild penalty scaled by gap
            let gap = (next_item_size - post_residual) as f64;
            score += 0.3 * gap;
        }
    }

    // Last-chance bin: if this is the only fitting bin, penalize opening a new bin
    // by rewarding this one, unless the fit is terrible (huge post-residual).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        if post_residual as f64 <= mean_residual {
            score -= 150.0;
        } else {
            score -= 40.0;
        }
    }

    // New-bin candidate: penalize so it is only chosen when all fits are awful.
    if bin_residual == bin_capacity {
        score += 250.0 + 0.5 * open_bins_count as f64;
        // but if item is huge relative to capacity, opening fresh is fine
        if item_size * 2 >= bin_capacity {
            score -= 200.0;
        }
    }

    // Tightness coupling: reward small post_residual relative to item size.
    if item_size > 0 {
        score += 0.5 * (post_residual as f64) * (post_residual as f64) / (item_size as f64);
    }

    // Prefer filling bins as stream progresses (consolidation pressure).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.2;
    score -= 0.1 * open_bins_count as f64;

    // Penalty if post-residual is an awkward class below the smallest item (10),
    // i.e., unusable dead space (item sizes 1..100 though, so use small threshold).
    if pr > 0 && pr < 3 {
        score += 300.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold even
    // the smallest plausible future item are pure waste — penalize heavily.
    let min_future = if next_item_size > 0 { next_item_size.min(10) } else { 10 };
    if post_residual < min_future && post_residual > 0 {
        score += 60.0 * (1.0 - (post_residual as f64 / min_future.max(1) as f64));
    }

    // Reward near-perfect fits (tight packing).
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + 10.0 * (1.0 - (post_residual as f64 - next_item_size as f64) / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Post residual can't host the next item: mild penalty scaled by gap.
        score += 5.0 * (next_item_size - post_residual) as f64 / 50.0;
    }

    // Last chance: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones
    // (new-bin candidate has bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        score += 30.0 + 8.0 * (open_bins_count as f64).ln().max(0.0);
        // Late in the stream, consolidation matters more.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    } else {
        // Slight preference for fuller bins when many bins are open.
        score -= 6.0 * (1.0 - bin_residual as f64 / bin_capacity as f64) * (open_bins_count as f64).sqrt();
    }

    // Mean-residual coupling: if this bin's residual is far above the mean,
    // it is a good "sponge" for the current item.
    score += 0.15 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong penalty for large unusable dead space (nothing else can fit)
    if post_residual < 10u32.min(bin_capacity / 2) {
        score -= 25.0; // near-perfect fill
    }

    // 2-step lookahead: reward when next item exactly fills the post-residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect chaining
        } else if next_item_size <= post_residual {
            // partial credit proportional to tightness of the chain fit
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot fit here: post residual is likely dead space
            let waste = (next_item_size - post_residual) as f64;
            score += 5.0 + 0.3 * waste;
        }
    }

    // Compare against mean residual: bins tighter than average are preferred targets
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless current bins fit badly
    if bin_residual == bin_capacity {
        score += 30.0;
        if next_item_size > 0 && next_item_size == item_size {
            score -= 5.0; // opening a bin for repeated sizes is fine
        }
    }

    // Slight preference to consolidate early in the stream (keep open-bin count low)
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), scaled by bin fill ratio.
    let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score *= 0.7 + 0.6 * fill;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    } else if post_residual <= 10 {
        score -= 6.0;
    }

    // Penalize dead space that no plausible item can fill.
    if post_residual > 0 && (post_residual as f64) < mean_residual * 0.3 {
        score += 4.0;
    }

    // Lookahead: penalize placements that leave residual smaller than the next item
    // (wasted capacity), but reward residual that exactly accommodates it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            if post_residual == next_item_size {
                score -= 8.0; // perfect pairing
            } else if post_residual - next_item_size <= 5 {
                score -= 4.0;
            }
        } else {
            // residual unusable for next item: mild penalty, worse if large residual wasted
            score += (post_residual as f64) * 0.05 + 1.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when current bin fits are poor
    // (large post_residual relative to mean residual) or many bins already open.
    if bin_residual == bin_capacity {
        let poor_fit = (post_residual as f64) > mean_residual * 0.5 + 10.0;
        if poor_fit {
            score -= 10.0; // fresh bin is competitive
        } else {
            score += 20.0 + 2.0 * open_bins_count as f64; // discourage fragmentation
        }
    }

    // Time horizon: early in the stream, keep bins flexible (penalize tight closures
    // slightly less late when packing quality matters more than flexibility).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * (post_residual as f64) * 0.03;

    // Mild pressure to consolidate when many bins are open.
    score += open_bins_count as f64 * 0.15 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Smooth non-linear polynomial coupling of post_residual with stream progress
    let poly = pr_norm * pr_norm * (0.5 + 2.0 * progress) + pr_norm * (1.0 - progress);

    // Penalize large dead space more aggressively late in the stream
    let mut score = pr + 40.0 * poly * cap * 0.01;

    // Reward tight fits (small post_residual) with a smooth non-linear bonus
    let tightness = 1.0 - pr_norm;
    score -= 30.0 * tightness * tightness * tightness;

    // Lookahead: reward bins whose post_residual matches next item size
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        let match_bonus = 1.0 - gap / cap;
        score -= 15.0 * match_bonus * match_bonus * (0.5 + progress);
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + pr_norm);
    }

    // Mild penalty for spreading across many bins when mean residual is low
    score += 0.02 * open_bins_count as f64 * (mean_residual - pr).abs() / cap;

    // Slight preference for keeping new-bin option open early in the stream
    let is_new = bin_residual == bin_capacity;
    if is_new {
        score += 10.0 * (1.0 - progress) * (1.0 - tightness);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo classes on capacity fractions
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // capacity fraction left over

    // Penalize post_residuals that fall into "dead" classes: small but
    // not small enough to be filled by typical items. Harmonic classes
    // via integer division thresholds.
    let class = post_residual / 10; // integer division class (0..=10)
    let class_penalty = match class {
        0 => 0.0,           // perfect fit
        1 => 3.0,           // tiny sliver: dead space
        2 => 1.5,
        3 => 2.5,
        4 => 1.0,
        5 => 0.5,           // half-full residual: flexible
        6 => 1.0,
        7 => 2.0,
        8 => 1.5,
        9 => 0.8,
        _ => 0.0,           // near-empty bin: flexible
    };
    score += class_penalty;

    // Reward exact harmonic alignment: post_residual divisible nicely
    if post_residual % 25 == 0 { score -= 4.0; }
    if post_residual % 20 == 0 { score -= 3.0; }
    if post_residual % 10 == 0 { score -= 1.0; }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size < post_residual {
            let next_class = (post_residual - next_item_size) / 10;
            score -= 6.0 - (next_class as f64) * 0.8;
        } else {
            // next item cannot use this residual: mild penalty for wasting
            score += 2.0;
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: prefer new bin only when current best
    // fit would leave a dead class and item is large
    if bin_residual == bin_capacity {
        let dead_fit = post_residual > 0 && post_residual < 10;
        if dead_fit {
            score -= 8.0; // opening new bin beats tiny sliver
        } else {
            score += 10.0 + 20.0 * (1.0 - frac); // discourage opening when fit is decent
        }
        // early in stream, opening bins is fine
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 5.0 * (1.0 - progress);
    }

    // Tightness reward: fraction of bin used by this placement
    let used_frac = item_size as f64 / cap;
    score -= 8.0 * used_frac;

    // Coupling with mean residual: prefer bins below mean residual
    // (filling emptier bins keeps tight bins for small items)
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    } else {
        score += 1.0;
    }

    // Modulo coupling between item and residual (harmonic resonance)
    if post_residual > 0 && item_size > 0 && post_residual % item_size == 0 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual <= 10 {
        score += 25.0 * (1.0 + (10 - post_residual) as f64 / 10.0);
    } else if post_residual > 10 && post_residual < 20 {
        score += 6.0; // moderately awkward gap
    }

    // Reward near-perfect fits (post_residual 0 is best).
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 5.0; // still acceptable tight fit
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward strongly.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item cannot use this gap: the residual is likely dead space
        score += (post_residual as f64) * 0.5;
    } else if next_item_size > 0 {
        // next item fits but leaves another gap; slight preference for larger leftovers
        score -= (post_residual as f64 - next_item_size as f64).max(0.0) * 0.3;
    }

    // Open-bin pressure: prefer existing bins when many bins are open.
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Discourage opening a new bin unless the current item is large enough
    // that a fresh bin is genuinely useful.
    if bin_residual == bin_capacity {
        score += 10.0 + (bin_capacity - item_size) as f64 * 0.2;
        // but allow opening when nothing fits well elsewhere
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    }

    // Mild normalization against mean residual state.
    score -= 0.05 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fills strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    } else if post_residual <= 10 {
        score -= 100.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size.
    if next_item_size > 0 {
        let look = next_item_size as f64;
        let diff = (post_residual as f64 - look).abs();
        if post_residual == next_item_size {
            score -= 800.0; // perfect 2-step chain
        } else if post_residual >= next_item_size {
            score -= 200.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Next item can't fit here; penalize proportionally to wasted space.
            score += 50.0 + diff;
        }
        // If next item fits in post_residual, mild bonus scaled by fit tightness.
        if post_residual >= next_item_size && post_residual - next_item_size <= 10 {
            score -= 60.0;
        }
    }

    // Penalize dead space relative to mean residual across open bins.
    let dead = post_residual as f64 - mean_residual;
    if dead > 0.0 {
        score += 0.5 * dead;
    } else {
        score += 0.3 * dead; // slightly reward tighter-than-average bins
    }

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin fit is terrible.
    if bin_residual == bin_capacity {
        score += 120.0;
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 900.0; // still allow fresh bin if it chains perfectly
        }
    }

    // Late in the stream, consolidate aggressively into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 30.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Mild penalty for proliferating open bins.
    score += 2.0 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * fit_ratio * fit_ratio;

    // Penalize large wasted residual that no typical item can use.
    if post_residual > 0 && post_residual < 10 {
        score -= 15.0; // nearly perfect fill
    }

    // Lookahead: if next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_fit = post_residual - next_item_size;
        score -= 25.0 - 0.2 * chain_fit as f64;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here after placement; slight penalty if we waste the slot.
        score += 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are crowded.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = mean_residual / bin_capacity as f64;
        score += 60.0 - 40.0 * pressure - 20.0 * progress;
        // If the item is large and only fits poorly anywhere, new bin is fine.
        if item_size as f64 > 0.7 * bin_capacity as f64 {
            score -= 25.0;
        }
    }

    // Prefer filling bins with residuals far from mean (reduce fragmentation spread).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Mild load balancing late in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * progress * (open_bins_count as f64).ln().max(0.0) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let res = bin_residual as f64;
    let item = item_size as f64;
    let nxt = next_item_size as f64;

    // Base: waste after placement, normalized
    let mut score = pr / cap;

    // Smooth non-linear coupling of waste with stream progress:
    // waste matters more as the stream advances (fewer chances to fill gaps)
    let progress_weight = 0.5 + 2.0 * progress * progress;
    score += progress_weight * (pr / cap).powi(2);

    // Reward tight fits: normalized fill ratio, smoothed
    let fill = item / cap;
    score -= 1.5 * fill * (1.0 - (res / cap - fill).abs());

    // Lookahead: penalize if the next item cannot fit in post_residual
    // (dead space penalty), reward if it does (chained placement).
    if nxt > 0.0 {
        let gap = nxt - pr;
        if gap > 0.0 {
            score += 0.8 * (gap / cap) * (1.0 + progress);
        } else {
            score -= 0.5 * (nxt / cap) * (1.0 - progress);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 2.0;
    }

    // New-bin candidate (empty bin): mild penalty so we prefer reusing open
    // bins unless their fit is poor; penalty decays as stream progresses.
    if bin_residual == bin_capacity {
        score += 0.6 * (1.0 - progress) + 0.02 * open_bins_count as f64;
    }

    // Slight preference for bins whose residual is near the mean (balance)
    score += 0.1 * ((res - mean_residual) / cap).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "usable" classes
    // (divisible by small harmonic denominators) are preferred.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Fractional fill level of the bin after placement.
    let fill = 1.0 - pr / cap;

    // Reward high fill non-linearly (superlinear in fill).
    score -= 30.0 * fill * fill * fill;

    // Harmonic class bonus: post_residual that is a multiple of common item
    // granularities (e.g. multiples of 10, or of next_item_size) is "reusable".
    if next_item_size > 0 && post_residual >= next_item_size {
        // The lookahead item can still fit here -> strong reward.
        score -= 12.0;
        // Exact harmonic match: post_residual % next_item_size == 0 means a perfect
        // future split of the leftover.
        if post_residual % next_item_size == 0 {
            score -= 8.0;
        }
        // Integer-division threshold: leftover can hold floor(pr/next) >= 2 copies.
        if post_residual / next_item_size >= 2 {
            score -= 4.0;
        }
    } else if next_item_size > 0 {
        // Lookahead cannot fit: penalize proportionally to how close we came.
        let gap = (next_item_size - post_residual) as f64;
        score += 6.0 * (1.0 - gap / cap);
    }

    // Modulo classes of post_residual w.r.t. 10 (typical granularity).
    let m = post_residual % 10;
    if m == 0 {
        score -= 5.0;
    } else if m >= 5 {
        score -= 2.0 * (m as f64) / 10.0;
    } else {
        score += 3.0 * (m as f64) / 5.0; // small awkward remainders penalized
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 15.0;
        if post_residual < 10 {
            score -= 10.0; // near-perfect fit, definitely use it
        }
    }

    // New-bin candidate (empty bin): only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = 0.55 * cap;
        // Cheaper to open a new bin when many bins are already open and crowded.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * progress;
        // If mean residual is small (bins nearly full), new bin is good.
        score -= 0.15 * (cap - mean_residual);
        // If lookahead is large relative to item, prefer fresh space.
        if next_item_size > item_size && next_item_size > 0 {
            score -= 5.0;
        }
        // Discourage opening new bins when a good fit exists elsewhere.
        if fitting_bins_count > 0 && post_residual == 0 {
            score += 40.0; // item fits perfectly somewhere else
        }
        if fitting_bins_count > 2 {
            score += 5.0;
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps that no future item (min size 1..100,
    // but realistically >= 10 in classic streams) can fill are pure waste.
    let dead_threshold = 10.0;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 12.0;
    }
    if post_residual == 0 {
        score -= 60.0; // perfect fit: strongly reward
    }

    // Reward tight fits: fraction of bin used by this placement.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 25.0;

    // Open bins pressure: discourage spreading into many bins early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (1.0 - progress);
    score += pressure * 2.5;

    // Penalize bins whose residual deviates badly from mean (keeps bin family uniform).
    score += (post_residual as f64 - mean_residual).abs() * 0.35;

    // Last-chance bin: if this is the only bin that fits, avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0;
        } else if next_item_size < post_residual {
            score -= 10.0;
        } else {
            // next item cannot use the gap: penalize large unusable leftovers
            score += (post_residual as f64) * 0.15;
        }
    }

    // New-bin candidate handling: empty bin is a fallback; prefer it only when
    // item would leave a large residual in an existing bin or no bin fits well.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin, softened by stream progress and item size
        score = 45.0 + (1.0 - progress) * 30.0 - item_size as f64 * 0.2;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with non-linear penalty.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 60.0 * tightness * tightness;

    // 2-step lookahead: reward when post_residual exactly (or nearly) matches next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        let match_bonus = 45.0 * (-diff / 12.0).exp();
        score -= match_bonus;
        // Penalize post_residual too small for next item (dead space for lookahead).
        if (post_residual as u64) < (next_item_size as u64) {
            score += 15.0;
        }
        // Perfect chain: post_residual == next_item_size exactly.
        if post_residual == next_item_size {
            score -= 30.0;
        }
    } else {
        // Last item: pure tightness, no lookahead concerns.
        score -= 10.0;
    }

    // Relative to mean residual: bins with residual above mean are better candidates.
    score -= 0.35 * ((bin_residual as f64) - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Many open bins: encourage consolidation into existing bins.
    if open_bins_count > 4 {
        score -= 0.8 * open_bins_count as f64;
    }

    // New-bin candidate: penalize opening a new bin unless nothing fits well.
    if bin_residual == bin_capacity {
        let waste = bin_capacity as f64 - item_size as f64;
        score += 30.0 + 0.25 * waste;
        // Opening a new bin is OK early in the stream or when no open bin fits tightly.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if fitting_bins_count == 0 {
            score -= 200.0;
        } else if progress < 0.1 {
            score -= 20.0;
        }
    }

    // Slight reward for larger items placed into larger-residual bins.
    score -= 0.05 * item_size as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly prefer bins whose post_residual is small.
    let tight = (post_residual as f64) / (bin_capacity as f64);
    score -= 60.0 * (1.0 - tight) * (1.0 - tight);

    // Exact/near-exact fill bonus.
    if post_residual == 0 {
        score -= 150.0;
    } else if post_residual < 5 {
        score -= 80.0;
    } else if post_residual < 10 {
        score -= 40.0;
    }

    // Penalize creating dead space that nothing can likely fill later:
    // residual smaller than the minimum plausible item (1..100 stream, min ~1).
    let dead = if post_residual > 0 && post_residual < 10 { 1.0 } else { 0.0 };
    score += dead * 30.0;

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0 + 0.3 * (next_item_size as f64);
        } else {
            score += 15.0;
        }
        // Extra reward if post_residual exactly matches next item size.
        if post_residual == next_item_size {
            score -= 60.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 70.0;
    }

    // New-bin candidate handling: opening a new bin is expensive; discourage
    // unless no good fit exists (tight fits in open bins will already score low).
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // Base penalty for opening a new bin.
        let mut open_penalty = 90.0;
        // Late in the stream, fewer items remain -> new bins less recoverable.
        open_penalty += 40.0 * progress;
        // Many open bins with large mean residual -> should reuse instead.
        if mean_residual > item_size as f64 {
            open_penalty += 0.5 * mean_residual;
        }
        // If item is small relative to capacity, reusing is easy; penalize new bin more.
        open_penalty += 0.4 * (bin_capacity - item_size) as f64;
        score += open_penalty;
    }

    // Mild preference for fuller bins when many bins are open (bin consolidation).
    score += (open_bins_count as f64).ln().max(0.0) * (post_residual as f64 / bin_capacity as f64) * 10.0;

    // Small tie-break noise via deterministic coupling of variables.
    score += 0.01 * ((item_size as f64 * 7.0 + step_index as f64).sin());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit_frac = item_size as f64 / cap;
    let norm_post = pr / cap;

    // Base: waste after placement, smoothly damped by progress (late waste matters more)
    let mut score = norm_post * (1.0 + 1.5 * progress);

    // Non-linear tightness reward: strongly favor small post_residual (quadratic coupling)
    score -= (1.0 - norm_post) * (1.0 - norm_post) * (0.8 + 0.6 * progress);

    // Penalize post_residual that is unusable: close to next_item_size but not enough,
    // or awkward mid-range dead space (smooth bump around cap/2)
    let bump = (norm_post - 0.5) * (norm_post - 0.5);
    score += 0.6 * bump * (1.0 - fit_frac);

    // Lookahead coupling: reward leaving room exactly for the next item (smooth kernel)
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs() / cap;
        score -= 0.9 * (-8.0 * gap * gap);
    }

    // Last-chance bin: strong reward to use it instead of opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 2.5 + 1.5 * progress;
    }

    // New-bin candidate: penalize mildly early, more when many bins already open or mean residual is large
    if bin_residual == bin_capacity {
        score += 1.2 + 0.4 * (open_bins_count as f64).ln().max(0.0) + 0.02 * mean_residual;
        // But late in the stream, prefer fresh bins for tight future fits
        score -= 1.0 * progress * (1.0 - fit_frac);
    }

    // Reward using bins with larger residuals (consume fullest space first)
    score -= 0.3 * (bin_residual as f64 / cap) * (1.0 - norm_post);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fraction of capacity consumed by this placement.
    let fill_frac = item_size as f64 / bin_capacity as f64;
    // Reward high fill ratio (tight packing).
    score -= 40.0 * fill_frac * fill_frac;

    // Harmonic class of post_residual: dead space in small residue classes
    // (e.g. 1..=10) is nearly unusable; penalize it extra.
    let dead_class = post_residual % 25;
    if post_residual > 0 {
        if dead_class <= 10 {
            score += 12.0 - dead_class as f64; // small awkward leftovers
        } else {
            score -= 3.0; // residue still potentially usable
        }
    }

    // Integer-division thresholds on post_residual: residual that can host
    // a "typical" item chunk is valuable.
    let usable_chunks = post_residual / 30;
    score -= 6.0 * usable_chunks as f64;

    // Lookahead: does the next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Perfect chaining: next item slots in exactly.
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 - 0.15 * slack;
            if post_residual == next_item_size {
                score -= 25.0; // exact closure of the bin
            }
        } else {
            // Next item won't fit here; mildly penalize near-miss waste.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.25 * gap.min(30.0);
        }
    }

    // Last chance: if this is the only bin that fits, strongly favor it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when open bins are full-ish
    // or the item is huge and no good fit exists.
    if bin_residual == bin_capacity {
        let mean_tightness = 1.0 - (mean_residual / bin_capacity as f64);
        let pressure = open_bins_count as f64 / (open_bins_count as f64 + 3.0);
        let big_item = item_size as f64 / bin_capacity as f64;
        // Penalize new bins mildly; discount when bins are tight or item large.
        score += 18.0 - 25.0 * mean_tightness * pressure - 20.0 * big_item;
        // Late in the stream, opening bins is fine (no need to consolidate).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 8.0 * progress;
    } else {
        // Prefer reusing bins that are already partially filled when many
        // bins are open (consolidation pressure).
        score += 0.05 * (open_bins_count as f64).min(20.0) * (post_residual as f64 / bin_capacity as f64);
        // Slight preference for bins below mean residual (more filled than average).
        if (bin_residual as f64) < mean_residual {
            score -= 4.0;
        }
    }

    // Modulo harmony: residual that is a multiple of common item sizes
    // (10/20/25) is more likely to be filled later.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 5.0;
    }
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // typical items (min size 1..100, but small gaps < ~10 are near-wasted)
    // are heavily penalized, but a perfect fit (0) is ideal.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 15.0;
    }

    // Reward tight fits (waste ratio low).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 25.0 * fit_ratio;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Open-bin pressure: penalize placements that spread across many bins,
    // but only mildly, so tight fits still win.
    score += 2.0 * (open_bins_count as f64).ln().max(0.0);

    // Prefer bins with below-mean residual (consolidate space).
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Lookahead: if the next item fits exactly in the post_residual,
    // reward this placement strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        if post_residual == next_item_size {
            score -= 50.0;
        } else {
            score -= 8.0;
        }
    }
    // If next item cannot fit in post_residual, mild penalty for stranding space.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 10.0;
    }

    // New-bin candidate: default neutral score around capacity/2 adjusted;
    // opening a new bin is attractive only when current fits are poor.
    // Base it on post_residual (= capacity here) with a mild bias toward reuse.
    if bin_residual == bin_capacity {
        // New bin starts with score = capacity + small penalty so that only
        // genuinely bad fits (high penalized scores above) beat it.
        score = bin_capacity as f64 + 5.0 + 2.0 * (open_bins_count as f64).ln().max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect/near-perfect fits aggressively.
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 10 {
        score -= 60.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Exact chain match is excellent.
            if post_residual == next_item_size {
                score -= 300.0;
            } else {
                let leftover2 = (post_residual - next_item_size) as f64;
                score -= 80.0 * (1.0 - leftover2 / bin_capacity as f64);
            }
        } else {
            // Next item won't fit here: penalize proportionally to the gap.
            let gap = (next_item_size - post_residual) as f64;
            score += 20.0 + 0.5 * gap;
        }
    }

    // Compare post_residual against mean residual: leaving more than average
    // space free is good (bin stays flexible); less than average is wasteful.
    score += 0.6 * (mean_residual - post_residual as f64).max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Late in the stream, prefer closing bins out (tighter packing).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when current bin fits are poor.
    if bin_residual == bin_capacity {
        score += 25.0 + 0.4 * mean_residual;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Reward tight fits: squash small residuals harder.
    score -= 12.0 * (-(post / 12.0)).exp();

    // Penalize large dead space relative to mean residual across open bins.
    score += 0.35 * (post - mean_residual).max(0.0);

    // Lookahead: if next item fits into post_residual, big bonus.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 + 0.25 * (next_item_size as f64);
    } else if next_item_size > 0 && post_residual > 0 {
        // Dead space that next item cannot use.
        score += 0.15 * (next_item_size as f64) * (post / cap);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 8.0 + 10.0 * (1.0 - progress) + 0.5 * open_bins_count as f64;
        if fitting_bins_count == 0 { score -= 25.0; }
        if post_residual >= next_item_size && next_item_size > 0 { score -= 6.0; }
    }

    // Mild penalty for many open bins (encourage consolidation).
    score += 0.08 * open_bins_count as f64 * (post / cap);

    // Time horizon: late in the stream, tighten more aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 + 2.0 * progress) + norm_pr * (1.0 - progress);

    let mut score = 10.0 * poly;

    // Tight fits are strongly rewarded
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 6.0 * tightness * tightness;

    // Penalize leaving a residual that no plausibly-sized item can use
    if post_residual > 0 && post_residual < 10 {
        score += 8.0 * (10 - post_residual) as f64;
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 15.0;
    }

    // Last-chance bin before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 5.0;
    }

    // Lookahead: reward residual that can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 4.0 * (1.0 - progress);
        } else {
            score += 2.0 * (next_item_size - post_residual) as f64 / cap;
        }
    }

    // Prefer filling bins with larger mean residual late in the stream
    score += progress * mean_residual * 0.05;

    // Mild penalty for scattering across many open bins
    score += 0.1 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate: only attractive when no good fit exists
    if bin_residual == bin_capacity {
        score += 25.0 - 10.0 * tightness;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "usable" classes
    // (multiples of common small item sizes) are favored.
    let pr = post_residual;
    if pr > 0 {
        // class: gcd-like usability — residual divisible by 10 is highly reusable
        if pr % 10 == 0 {
            score -= 6.0;
        } else if pr % 5 == 0 {
            score -= 3.0;
        }
        // tiny dead-space classes are penalized super-linearly
        if pr < 10 {
            score += (10 - pr) as f64 * 2.5;
        }
        // mid-range awkward class 11..=19 is a trap: nothing fits later
        if pr >= 11 && pr <= 19 {
            score += 12.0;
        }
    }

    // Integer-division threshold: exact fit (post_residual 0) is perfect
    if pr == 0 {
        score -= 25.0;
    }

    // Lookahead coupling: does the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 8.0 + (next_item_size as f64 / bin_capacity as f64) * 10.0;
        } else {
            score += 4.0;
        }
        // harmonic pair: item + next exactly fills the bin
        if item_size + next_item_size == bin_residual {
            score -= 15.0;
        }
    }

    // Last-chance bin: strongly prefer using it rather than opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowded = mean_residual / bin_capacity as f64;
        // penalize new bin normally; relax penalty if residuals are fragmented
        score += 30.0 - crowded * 25.0 - progress * 5.0;
    } else {
        // prefer bins with residual closest below mean (tight packing)
        let diff = (bin_residual as f64 - mean_residual).abs();
        score += diff * 0.15;
    }

    // slight preference for fuller bins as stream progresses
    let fill = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= fill * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        let dead = if post_residual < 10 { 6.0 } else if post_residual < 20 { 3.0 } else { 0.0 };
        score += dead * (post_residual as f64);
    } else {
        // Perfect fit: strong reward.
        score -= 50.0;
    }

    // Post-residual that can fit the next item is valuable; reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }

    // Last-chance bin pressure: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (which would waste the residual here).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage opening another one.
    // (Only matters for the new-bin candidate; residual == capacity.)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 10.0 + 3.0 * open_bins_count as f64 + 5.0 * progress;
        // Opening a new bin is acceptable if the item would leave a tiny dead gap
        // in every existing bin; approximate via mean_residual.
        if post_residual as f64 > mean_residual {
            score += 5.0;
        }
    } else {
        // Favor bins with tighter fit relative to the fleet's mean residual.
        score += 0.3 * (post_residual as f64 - mean_residual);
    }

    // Mild preference for filling fuller bins first (smaller residual before placement).
    score += 0.2 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact-ish match between post_residual
    // and next_item_size so the next item can fill this bin perfectly.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match for next item -> strong reward.
        score -= 12.0 * (1.0 - gap / bin_capacity as f64).max(0.0);
        // If next item fits exactly leaving near-zero residual, extra reward.
        if gap == 0.0 {
            score -= 8.0;
        }
        // Penalize if next item will NOT fit in post_residual (dead space risk),
        // scaled by how much residual would be wasted.
        if post_residual < next_item_size {
            score += 0.35 * post_residual as f64;
        }
    }

    // Favor bins whose residual is small relative to mean residual
    // (tight packing, low fragmentation).
    score += 0.25 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Penalize very small unusable residuals (dead space), non-linearly.
    if post_residual > 0 && post_residual < 10 {
        score += 10.0;
    }

    // Zero residual is perfect closure.
    if post_residual == 0 {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when open bins would leave large waste
    // or few fitting bins exist. Empty-bin call has bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        let waste_if_open = open_bins_count as f64 * mean_residual;
        score += 25.0; // base cost of opening a new bin
        if next_item_size > 0 && next_item_size > bin_residual {
            score += 5.0;
        }
        // If existing bins are heavily fragmented, opening new bin less bad.
        score -= 0.15 * waste_if_open;
        if fitting_bins_count <= 1 {
            score -= 10.0;
        }
    }

    // Mild preference for consolidating into fewer bins as stream progresses.
    score += 0.02 * open_bins_count as f64 * (step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Base preference: tight fits (small post_residual), but penalize unusable slivers.
    if post_residual > 0 && post_residual < 5 {
        score += 8.0; // dead space too small for any item (min size 1..100, small slivers waste)
    }

    // Reward excellent fits strongly.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    let residual_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 6.0 * fill_ratio * (1.0 - residual_ratio);

    // Penalize placing into a bin whose residual is much larger than needed when
    // the next item could have used this space.
    if next_item_size > 0 && next_item_size <= post_residual + item_size {
        // If next item would fit better in the space we just consumed
        if next_item_size > post_residual && next_item_size <= bin_residual {
            // next item needed this bin's space; mild penalty unless fit was near-perfect
            score += 4.0 * (1.0 - fill_ratio);
        }
        // Reward if next item fits exactly in the leftover space (chain packing)
        if next_item_size == post_residual {
            score -= 10.0;
        } else if next_item_size <= post_residual {
            score -= 2.0 * (post_residual as f64 - next_item_size as f64).max(0.0) / bin_capacity as f64;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it
    // rather than opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0 + 6.0 * (1.0 - residual_ratio);
    }

    // New-bin candidate handling: empty bin should only win when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; grows with number of open bins and progress.
        let mut open_cost = 25.0 + 3.0 * open_bins_count as f64 * (0.4 + 0.6 * progress);
        // Late in the stream, be more reluctant to open new bins.
        open_cost += 15.0 * progress;
        // If many bins fit the item, opening new is wasteful.
        if fitting_bins_count > 1 {
            open_cost += 10.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
        }
        // If mean residual across open bins is large, there's slack available elsewhere.
        open_cost += (mean_residual / bin_capacity as f64) * 10.0;
        // If the next item is huge, having fresh capacity might help — slight discount.
        if next_item_size >= bin_capacity / 2 {
            open_cost -= 5.0;
        }
        score += open_cost;
    } else {
        // Open bins: mild preference for bins with residual close to mean (balance),
        // and slight preference for filling bins that are already fairly full.
        let dev = (bin_residual as f64 - mean_residual).abs() / bin_capacity as f64;
        score += 2.0 * dev;
        score -= 3.0 * (1.0 - bin_residual as f64 / bin_capacity as f64);
    }

    // Small stochastic-free tie-breaker varying by step to diversify exploration.
    score += ((step_index as f64 * 0.6180339887).fract() - 0.5) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear waste shaping: penalize large residuals super-linearly.
    let norm_pr = pr / cap;
    score += 30.0 * norm_pr * norm_pr;

    // Interaction: residual vs mean residual of open bins — favor bins tighter than average.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 20.0 * dev * dev.abs();

    // Stream progress coupling: late in the stream, waste is more costly.
    score += 15.0 * progress * norm_pr * norm_pr;

    // Lookahead coupling: reward residual that can hold the next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fit_next = if pr >= nx { 1.0 } else { 0.0 };
        let gap = (pr - nx).abs() / cap;
        score -= 12.0 * fit_next * (1.0 - gap * gap);
        // Perfect pairing bonus
        if (pr - nx).abs() < 3.0 { score -= 10.0; }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when decent fitting bins exist.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let pressure = if fitting_bins_count > 0 {
            let best_gap = ((bin_capacity - item_size) as f64 / cap).min(1.0);
            best_gap
        } else { 1.0 };
        score += 35.0 * (1.0 - pressure * pressure);
        // If no open bin fits, opening is necessary: reward modestly.
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
        // Early stream: opening bins is cheap; late stream: avoid proliferation.
        score += 20.0 * progress;
        // Discard tiny items into fresh bins less harshly.
        score -= 5.0 * (it / cap);
    }

    // Mild preference for fuller bins overall.
    score -= 8.0 * (1.0 - (bin_residual as f64 / cap));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls on a "useful"
    // class (divisible by small integers) are more likely to be filled later.
    let pr = post_residual;
    if pr > 0 {
        let mut harmony = 0.0;
        if pr % 10 == 0 { harmony += 6.0; }
        if pr % 20 == 0 { harmony += 5.0; }
        if pr % 25 == 0 { harmony += 4.0; }
        if pr % 50 == 0 { harmony += 3.0; }
        if pr % 5 == 0 { harmony += 1.5; }
        // dead-space penalty grows for tiny, non-harmonic residuals
        if pr < 10 && pr % 5 != 0 {
            harmony -= (10 - pr) as f64 * 2.0;
        }
        score -= harmony;
    } else {
        // perfect fill: reward strongly
        score -= 40.0;
    }

    // Lookahead: does the next item fit exactly / well in the post-residual?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 35.0; // perfect pair
        } else if next_item_size < pr {
            let slack = (pr - next_item_size) as f64;
            score -= 12.0 - 0.15 * slack;
        } else {
            score += 4.0; // next item won't fit here
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a bin unless current bins are crowded.
    if bin_residual == bin_capacity {
        let crowding = (open_bins_count as f64) * (mean_residual / cap);
        score += 30.0 - 12.0 * crowding.min(2.5);
    }

    // Prefer tight fills relative to mean residual of open bins.
    score += 0.25 * ((post_residual as f64) - mean_residual).max(-20.0).min(20.0);

    // Slight progression term: later in stream, be greedier about tight fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_capacity - post_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = 0.0;

    // Base: wasted space, with a dead-space multiplier that punishes
    // small unusable gaps much more than large useful residuals.
    let pr = post_residual as f64;
    if pr == 0.0 {
        // Perfect fit: strongest reward.
        score -= 1000.0;
    } else if pr < 10.0 {
        // Unusable dead space (< min item size): heavy penalty.
        score += 500.0 + (10.0 - pr) * 50.0;
    } else {
        // Usable residual: mild reward for larger leftover space.
        score += pr * 0.5;
    }

    // Tightness of the fit: prefer bins where item fills a large fraction.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= fill_ratio * 100.0;

    // Open-bin pressure: discourage scattering across many open bins.
    score += open_bins_count as f64 * 5.0;

    // Last-chance bin: strongly reward using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate handling: opening a new bin should only win when
    // no open bin offers a good fit. Make the empty bin moderately
    // attractive (fresh residual) but not better than a tight fit.
    if bin_residual == bin_capacity {
        score += 150.0 - open_bins_count as f64 * 10.0;
        // Late in the stream, opening new bins is less attractive.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 100.0;
    }

    // Lookahead: if next item fits in the post residual, big reward.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 200.0;
    }
    // If next item almost fits (small gap), slight penalty for blocking it.
    else if next_item_size > 0 && pr > 0.0 && (next_item_size as f64) - pr <= 10.0 {
        score += 50.0;
    }

    // Prefer bins whose residual is near the mean (balance loads).
    score -= (mean_residual - pr).abs() * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact/near-exact fits (waste minimization).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 15 {
        score -= 50.0;
    }

    // 2-step lookahead: reward if the NEXT item fits into this bin's post-residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item fits: bonus proportional to how snugly it fits afterwards.
            let post2 = post_residual - next_item_size;
            score -= 40.0 + (post2 as f64).min(60.0) * 0.5;
            // Extra reward for a chained near-perfect double fit.
            if post2 == 0 {
                score -= 300.0;
            } else if post2 <= 10 {
                score -= 100.0;
            }
        } else {
            // Next item won't fit here: penalize leaving a residual that is
            // "almost but not quite" large enough (dead space trap).
            let gap = (next_item_size - post_residual) as f64;
            if gap <= 10.0 {
                score += 60.0 - gap * 4.0; // painful near-miss
            } else {
                score += 10.0; // mild penalty, residual likely useless anyway
            }
        }
    }

    // Relative-to-mean residual shaping: prefer bins whose post-residual is
    // below the mean residual (tightening the average waste).
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bin: if this is the only bin that fits, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + item_size as f64 * 0.3;
    }

    // New-bin candidate handling: a fresh empty bin should only win when no
    // open bin offers a decent fit. Penalize opening a new bin, more so when
    // many bins are open (we want to consolidate) and early in the stream.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let consolidation = (open_bins_count as f64).sqrt() * 8.0;
        score += 120.0 + consolidation + 40.0 * (1.0 - progress);
        // If the item is large relative to capacity, a fresh bin is more tolerable.
        score -= (item_size as f64 / bin_capacity as f64) * 60.0;
    }

    // Small penalty for leaving residuals in the awkward 20..40 band (hard to fill).
    if post_residual >= 20 && post_residual <= 40 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squared post-residual penalty scaled down for near-perfect fits.
    let tight = post_residual as f64 / bin_capacity as f64;
    score += 4.0 * tight * tight * (bin_capacity as f64);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: reward leaving space compatible with the next item.
    if next_item_size > 0 {
        let gap = post_residual as f64 - next_item_size as f64;
        if gap >= 0.0 {
            score -= 6.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            score += 3.0 * (-gap) / bin_capacity as f64;
        }
    }

    // Global state: penalize opening new bins when many open bins have slack.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let slack_pressure = mean_residual / bin_capacity as f64;
        score += 18.0 * slack_pressure * (open_bins_count as f64).sqrt();
        // Early in stream, opening bins is cheaper; later, avoid fragmentation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Prefer bins whose residual is below the mean (consolidate waste).
    score += 2.0 * (bin_residual as f64 - mean_residual) / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual

    // Non-linear coupling: penalize post_residual more strongly as the stream progresses
    // (late stream => less room to exploit leftover space), via a smooth polynomial.
    let progress_weight = 0.5 + 2.5 * progress * progress;
    score += progress_weight * (x * x) * cap * 0.5;

    // Smooth reward for tight fits (small post_residual), stronger early-mid stream.
    let tightness = (1.0 - x).clamp(0.0, 1.0);
    score -= 6.0 * tightness * tightness * (1.0 - 0.5 * progress);

    // Penalize bins whose residual is far from mean residual (fragmentation signal),
    // scaled smoothly by how much the item deviates from the mean.
    let dev = (bin_residual as f64 - mean_residual).abs() / cap;
    score += 3.0 * dev * dev * (1.0 + progress);

    // Lookahead coupling: reward if next item fits into post_residual, smooth ramp.
    if next_item_size > 0 {
        let fits_next = (pr - next_item_size as f64) / cap;
        if fits_next >= 0.0 {
            score -= 4.0 * (1.0 - (fits_next * 2.0).min(1.0)) * (1.0 - progress * 0.5);
        } else {
            // Smooth penalty for leaving space that next item almost-but-doesn't fit.
            let miss = (-fits_next).min(1.0);
            score += 2.0 * miss * miss;
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0 * (1.0 + progress);
    }

    // New-bin candidate: penalize opening a new bin, but relax when many bins fit
    // poorly (few fitting bins) and stream is late.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let scarcity = 1.0 / (fitting_bins_count as f64);
        score += 15.0 * (1.0 - 0.4 * progress) - 5.0 * scarcity;
        // Mild reward if current item leaves large residual in new bin usable by next item.
        if next_item_size > 0 && pr >= next_item_size as f64 {
            score -= 3.0;
        }
    }

    // Mild penalty proportional to number of open bins to discourage sprawl.
    score += (open_bins_count as f64).ln().max(0.0) * 0.5 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Harmonic class of the post residual: reward residuals that form "clean" classes
    // (multiples of small divisors) which future items are more likely to fill.
    let pr = post_residual;
    if pr > 0 {
        let class_bonus: f64 = if pr % 10 == 0 {
            -6.0
        } else if pr % 5 == 0 {
            -3.0
        } else if pr % 2 == 0 {
            -1.0
        } else {
            1.5
        };
        score += class_bonus;

        // Dead-space penalty: very small residuals are hard to fill (items >= 1, but
        // realistically unusable slivers). Penalize tiny leftovers super-linearly.
        if pr < 10 {
            score += (10 - pr) as f64 * 3.0;
        }
    } else {
        // Perfect fit: strongly reward closing the bin.
        score -= 40.0;
    }

    // Tight fit reward: residual just above item size means efficient packing.
    let tightness = (bin_residual - item_size) as f64 / bin_residual.max(1) as f64;
    score -= 8.0 * tightness;

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 5.0 * (post_residual - next_item_size) as f64 / cap;
        } else {
            // next item cannot use this bin's leftover; slight penalty for large leftovers
            score += 0.02 * post_residual as f64;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate (empty bin): penalize opening a new bin unless current bins
    // are nearly full or there are many open bins with large mean residual.
    if bin_residual == bin_capacity {
        let mean_frac = mean_residual / cap;
        let pressure = (open_bins_count as f64).sqrt() * 0.5;
        score += 20.0 + 30.0 * (1.0 - mean_frac) - pressure.min(15.0);
        // Early in the stream, opening bins is cheap; late, prefer consolidation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * (1.0 - progress);
    }

    // Mild preference for bins with below-mean residual (fill fuller bins first).
    score -= 0.05 * (mean_residual - bin_residual as f64);

    // Harmonic integer-division threshold on post_residual vs capacity fraction.
    let quarter = bin_capacity / 4;
    if post_residual <= quarter && post_residual > 0 {
        score += 4.0; // leftover below quarter capacity is risky
    } else if post_residual > quarter && post_residual <= bin_capacity / 2 {
        score -= 2.0; // half-capacity class is a good harmonic target
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps are unusable, penalize them hard.
    let dead_zone = 12.0f64;
    if post_residual > 0 && (post_residual as f64) < dead_zone {
        score += (dead_zone - post_residual as f64) * 6.0;
    }
    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }
    // Reward leaving a gap that the lookahead item could use.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 4.0 + (post_residual - next_item_size) as f64 * 0.05;
    } else if next_item_size > 0 {
        // Gap too small for next item: dead space risk.
        score += 3.0;
    }

    // New-bin candidate logic: opening a bin is attractive when current fit is poor
    // or when this is a last-chance bin with bad residual.
    if bin_residual == bin_capacity {
        // Fresh bin: prefer it when fit quality elsewhere is bad or many bins are open.
        let fit_pressure = if fitting_bins_count <= 1 { 8.0 } else { 0.0 };
        score -= 5.0 + fit_pressure + (open_bins_count as f64).min(10.0) * 0.8;
    } else {
        // Last chance bin: strongly favor using it to avoid opening a new bin.
        if fitting_bins_count == 1 {
            score -= 10.0;
        }
        // Reward tight fits relative to residual.
        let tightness = item_size as f64 / bin_residual.max(1) as f64;
        score -= tightness * 8.0;
        // Open-bin pressure: discourage spreading across many bins unless tight.
        score += open_bins_count as f64 * 0.3;
    }

    // Mild preference for bins with residual close to mean (balance).
    score -= 0.2 * (1.0 - ((bin_residual as f64 - mean_residual).abs() / bin_capacity as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits (small dead space is super-linearly bad).
    if post_residual <= 5 {
        score -= 60.0 * (6.0 - post_residual as f64);
    }

    // 2-step lookahead: reward residuals that exactly or nearly match the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 80.0; // perfect chaining: next item fills this bin exactly
        } else if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            if slack <= 5 {
                score -= 50.0 - slack as f64 * 4.0;
            } else {
                score -= 10.0 / slack as f64;
            }
        } else {
            // next item cannot fit here; penalize proportionally to the mismatch
            let gap = next_item_size - post_residual;
            score += gap as f64 * 0.6;
        }
    }

    // Prefer bins whose residual is already below average (consolidating waste).
    if (post_residual as f64) < mean_residual {
        score -= (mean_residual - post_residual as f64) * 0.5;
    } else {
        score += (post_residual as f64 - mean_residual) * 0.3;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        score += 30.0 - pressure * 55.0;
        // late in the stream, avoid spawning bins unnecessarily
        score += (step_index as f64 / total_items.max(1) as f64) * 10.0;
    }

    // Mild preference for tighter existing bins overall.
    score += (bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress in stream
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;

    // Is this the new-bin candidate?
    let is_new_bin = bin_residual == bin_capacity;

    // ---- Perfect-fit detection (exact fill) ----
    if post_residual == 0 {
        score -= 1000.0; // bin closed perfectly, extremely desirable
    }

    // ---- Lookahead coupling: does the leftover space match the next item? ----
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0; // leftover exactly fits next item
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // reward leftovers that can still host the next item, scaled by slack quality
            score -= 60.0 * (1.0 - slack / cap);
        } else {
            // leftover cannot host next item: penalize dead space more when small
            let dead = (next_item_size - post_residual) as f64;
            score += 0.8 * dead;
        }
    }

    // ---- Tightness reward: prefer small post_residual non-linearly ----
    let pr = post_residual as f64;
    score += 0.02 * pr * pr / cap; // quadratic penalty on wasted space

    // ---- Last-chance logic: if only this bin fits, avoid opening a new one ----
    if !is_new_bin && fitting_bins_count == 1 && item_size <= bin_residual {
        score -= 150.0;
    }
    // Opening a new bin while other bins fit is costly unless the fit is terrible
    if is_new_bin && fitting_bins_count >= 1 {
        // how badly do existing bins fit? compare post_residual vs mean_residual
        let fit_quality = (pr as f64 - mean_residual).abs();
        // penalize new bin mildly; escape hatch when fit is very poor
        let base = 90.0 - 0.5 * fit_quality;
        score += base.max(0.0);
    }

    // ---- Global state: many open bins -> prefer filling existing ones ----
    if !is_new_bin {
        score -= 2.0 * (open_bins_count as f64).sqrt();
    } else {
        score += 1.5 * (open_bins_count as f64).sqrt();
    }

    // ---- Mean-residual steering: prefer bins whose residual is near mean (balance) ----
    let bin_res = bin_residual as f64;
    score += 0.15 * (bin_res - mean_residual).abs();

    // ---- Time horizon: early in stream, be conservative with new bins; late, pack tight ----
    if is_new_bin {
        score += 40.0 * (1.0 - progress); // early items: discourage new bins less? invert: keep open
        score -= 20.0 * progress;
    } else {
        score -= 30.0 * progress; // later: reward using existing bins more
    }

    // ---- Small-item handling: avoid putting tiny items into huge residuals ----
    if item_size < 20 && post_residual > 60 {
        score += 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer low post-residual, with smooth polynomial shaping.
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Stream-progress coupling: later in the stream, dead space matters more.
    let progress_coupling = 1.0 + 1.5 * progress * progress;
    score *= progress_coupling;

    // Reward tight fits: subtract bonus that grows as post_residual approaches 0.
    let tightness = 1.0 - norm_pr;
    score -= 20.0 * tightness * tightness * tightness;

    // Penalize large post-residual relative to mean residual (wasting space vs. fleet average).
    score += 0.5 * (pr - mean_residual).max(0.0);

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        if gap < 1.0 {
            score -= 15.0;
        } else {
            score += 0.1 * gap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Mild penalty for many open bins to encourage consolidation.
    score += 0.05 * open_bins_count as f64;

    // New-bin candidate: make it moderately attractive only when no good fit exists.
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo common item sizes
    let r = post_residual;
    // Perfect-fit reward (zero dead space is ideal)
    if r == 0 {
        score -= 1000.0;
    }

    // Small residues are dead space unless they match a likely future item size.
    // Harmonic classes: residues divisible by common sizes (e.g. multiples of 10, 25, 50)
    let harmonic_bonus = if r > 0 {
        if r % 50 == 0 { 30.0 }
        else if r % 25 == 0 { 20.0 }
        else if r % 10 == 0 { 15.0 }
        else if r % 5 == 0 { 8.0 }
        else { 0.0 }
    } else { 0.0 };
    score -= harmonic_bonus;

    // Coupling with lookahead item: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual >= next_item_size {
            // next item fits: reward proportional to leftover tightness
            let rem = post_residual - next_item_size;
            score -= 50.0 + (rem as f64).min(60.0);
        } else {
            // next item cannot fit here: penalize small unusable residues more
            if post_residual < next_item_size && post_residual < 20 {
                score += 40.0;
            }
        }
    }

    // Integer division thresholds on post_residual: classify usability
    let quarter = bin_capacity / 4; // 25
    if r > 0 && r < quarter {
        score += 60.0; // tiny dead space penalty
    } else if r < bin_capacity / 2 {
        score += 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: only attractive when current bin fit is poor
    if bin_residual == bin_capacity {
        // base penalty so new bins aren't opened casually
        score += 120.0;
        // but if item leaves an awkward residue in any bin and stream is early,
        // opening a fresh bin that leaves room for the next item can be good
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 40.0;
        }
        if fitting_bins_count == 0 {
            score -= 500.0; // no existing bin fits: new bin mandatory anyway
        }
    }

    // Slight preference to fill bins with larger mean residual (balance load)
    score -= 0.05 * mean_residual;

    // Mild stream-progression term: later in stream, prefer closing bins tight
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 20.0 * progress * (r == 0 as u32 as bool) as i32 as f64;

    // Tightness reward: smaller leftover relative to item size is better
    if item_size > 0 {
        score -= 10.0 * (item_size as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero gaps are "dead" — penalize hard.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0; // unusable sliver
        } else if post_residual < 20 {
            score += 25.0;
        } else if post_residual < 35 {
            score += 8.0;
        }
    } else {
        score -= 40.0; // perfect fit
    }

    // Reward tight fits: post_residual close to 0 relative to residual.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * tightness;

    // Dead space that could still fit the lookahead item is less dead.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 10.0; // gap likely unusable for next item
    }

    // Open-bin pressure: discourage opening new bins when many are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let new_bin = (bin_residual == bin_capacity) as f64;
    score += new_bin * (20.0 + 12.0 * open_bins_count as f64 + 25.0 * progress);

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && new_bin == 0.0 {
        score -= 50.0;
    }

    // Prefer bins with residual near the mean (keeps residuals uniform).
    score += 0.3 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

