        // Extra penalty if placing here creates large dead space AND next
        // item could have used the fresh bin.
        if post_residual > 0 && next_item_size > post_residual {
            score += 5.0;
        }
    }

    // New empty bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // Neutral-ish base; discourage slightly so tight fits win,
        // but allow it when many bins are open and mean residual is low.
        score += 8.0;
        if open_bins_count > 3 && mean_residual < item_size as f64 {
            score -= 15.0;
        }
        if next_item_size > 0 && next_item_size >= bin_capacity - item_size {
            // Next item pairs perfectly with a fresh bin.
            score -= 20.0;
        }
    }

    // Dead-space penalty: residual too small to hold any plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Stream progression: early on, be conservative with new bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
