    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        let mut new_bin_score = cap * 0.55;
        // cheaper to open new bin when many bins are open and mean residual is low
        new_bin_score -= (open_bins_count as f64).min(10.0) * 2.0;
        new_bin_score -= mean_residual * 0.4;
        // late in the stream, prefer consolidation
