    // Open-bin pressure: discourage proliferation of bins when many are open.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Prefer bins with residual near mean (balanced packing), slight pull.
    score += (bin_residual as f64 - mean_residual).abs() * 0.15;

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let bad_fit = (post_residual < 10) as i32 + ((next_item_size > 0 && post_residual < next_item_size && post_residual > 0) as i32);
        score += 35.0 - 35.0 * bad_fit as f64;
        score += fitting_bins_count as f64 * 2.0;
    }

    // Mild preference for tighter bins.
    score += (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact/near-exact fits (dead space minimization)
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 15 {
        score -= 50.0;
    }

    // 2-step lookahead: reward if next item fits into the post residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual >= next_item_size {
            // next item fits: reward proportional to how much slack remains after
            let after_next = post_residual - next_item_size;
            score -= 120.0 - (after_next as f64).min(60.0);
        } else {
            // next item does NOT fit: penalize wasted residual that is close to but below next_item_size
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.5;
        }
    }

    // Penalize residuals that are too small to be useful for typical items (1..100 range)
    if post_residual > 0 && post_residual < 10 {
        score += 80.0;
    }

    // Relative to mean residual: prefer bins with less residual than average (tighter bins)
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a new bin unless it enables a great 2-step chain
    if bin_residual == bin_capacity {
        let mut new_score = 250.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            new_score -= 100.0;
        }
        // late in stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        new_score += progress * 100.0;
        // many open bins: discourage opening more
        new_score += open_bins_count as f64 * 5.0;
        score += new_score;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) non-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that no plausible item can use.
    if post_residual > 0 {
        if post_residual < 10 {
            score -= 8.0; // near-perfect fill
        } else {
            // dead space penalty grows if next item cannot use it
            let usable = (next_item_size as f64) <= post_residual as f64 && next_item_size > 0;
            if !usable {
                score += 0.35 * post_residual as f64;
            }
        }
    }

    // Lookahead: favor bins where the next item also fits afterwards.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 {
        score += 4.0; // blocks the lookahead item
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when
    // existing residuals are large (fragmented) or many bins are open.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let fragmentation = mean_residual / bin_capacity as f64;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = fragmentation * 0.5 + (open_bins_count as f64 / 20.0).min(1.0) * 0.3 + progress * 0.2;
        // base penalty keeps tight fits winning; discount when pressure is high
        score += 40.0 * (1.0 - pressure.min(1.0));
        // opening a bin is good if item is large relative to capacity
        score -= 10.0 * (item_size as f64 / bin_capacity as f64);
    }

    // Mild bonus for bins below mean residual (consolidating emptier bins keeps
    // fuller bins available for large items).
    if (bin_residual as f64) > mean_residual {
        score += 3.0;
    } else {
        score -= 2.0;
    }

    // Slight time-horizon modulation: early on, be conservative with new bins;
    // late, prefer closing bins out tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let t = progress;
    let coupling = norm_pr * norm_pr * (1.0 + t) + norm_pr * (t * t);
    score += 40.0 * coupling;

    // Reward tight fits, stronger as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * (20.0 + 60.0 * t);

    // Penalize dead space that cannot fit a lookahead item
    if next_item_size > 0 && pr < next_item_size as f64 {
        score += 15.0 * (1.0 - pr / next_item_size as f64) * (1.0 + t);
    } else if next_item_size > 0 {
        // Reward leaving room exactly usable by the next item
        let fit_quality = 1.0 - ((pr - next_item_size as f64) / cap);
        score -= 25.0 * fit_quality * fit_quality;
    }

    // Last-chance bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0 * (1.0 + t);
    }

    // New-bin candidate: penalize opening a new bin, more so when good fits exist
    if bin_residual == bin_capacity {
        let open_pressure = (open_bins_count as f64).ln() + 1.0;
        score += 30.0 * open_pressure * (1.0 + 2.0 * t);
    }

    // Mild preference for bins below mean residual (balance load)
    score += 0.1 * (pr - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fits are golden: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: residual divisible by small divisors
    // pairs well with common item sizes (capacity fractions).
    let pr = post_residual;
    if pr > 0 {
        let mut harmony = 0.0;
        for &d in &[10u32, 20, 25, 50] {
            if pr % d == 0 {
                harmony += 15.0;
            }
        }
        if pr % 5 == 0 { harmony += 5.0; }
        if pr % 7 == 0 { harmony += 3.0; }
        score -= harmony;

        // Dead space penalty: residual too small for the smallest plausible item.
        if pr < 10 {
            score += 40.0;
        } else if pr < 20 {
            score += 15.0;
        }

        // Integer-division threshold classes on post_residual.
        let cls = pr / 10; // 0..10 class
        score += match cls {
            0 => 20.0,
            1 => 8.0,
            2 => 2.0,
            3 | 4 => -2.0,
            5 => -5.0, // half-full residual is very reusable
            _ => -1.0,
        };
    }

    // Lookahead coupling: does next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 12.0 + 0.2 * next_item_size as f64;
            // Harmonic match: next item divides post residual evenly.
            if pr % next_item_size == 0 {
                score -= 10.0;
            }
        } else {
            score += 6.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible
    // and the item is large (keeps small items consolidating).
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / bin_capacity as f64;
        score += 30.0 + 20.0 * (1.0 - frac);
        // Late in the stream, closing out open bins is cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 * progress;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 15.0; // new bin can host the pair nicely
        }
    }

    // Mild pressure to prefer fuller bins when many bins are open.
    score += 0.05 * open_bins_count as f64 * (bin_residual as f64 / bin_capacity as f64);

    // Tie-break: prefer bins whose residual is close to the mean residual.
    score += 0.1 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

