            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidation into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64).ln().max(0.0) * 2.0 * (1.0 - progress);

    // Mean residual coupling: prefer bins whose residual is below average (tighter bins).
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // Penalize opening a new bin unless no bin fits or it genuinely avoids dead space.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 50.0;
        } else {
            score += 20.0 + 0.5 * fitting_bins_count as f64;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-exact fits strongly.
    let cap = bin_capacity as f64;
    let exactness = 1.0 - (post_residual as f64) / cap;
    score -= 30.0 * exactness * exactness;

    // Aggressive 2-step lookahead: reward when next item fits into post_residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / cap);
            // Perfect chain: post_residual exactly matches next item.
            if post_residual == next_item_size {
                score -= 25.0;
            }
        } else {
            // Dead space relative to next item.
            score += 6.0 + 0.25 * ((post_residual as f64) - (next_item_size as f64)).abs();
        }
    } else {
        // Last item: prioritize tight packing even more.
        score -= 15.0 * exactness;
    }

    // Prefer bins whose residual is already below mean (consolidate waste).
    score += 0.15 * ((post_residual as f64) - mean_residual).max(0.0);

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless the item
    // is large relative to capacity or no good fit exists.
    if bin_residual == bin_capacity {
        let base = 25.0;
        let item_frac = item_size as f64 / cap;
        // Large items pack cleanly in fresh bins; small items should reuse bins.
        score = base + 40.0 * (1.0 - item_frac);
        if next_item_size > 0 && bin_residual >= next_item_size && item_size >= next_item_size {
            score -= 10.0;
        }
        // Late in the stream, discourage spawning extra bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * progress;
    }

    // Mild penalty for accumulating many open bins.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strong penalty for dead space: quadratic in post_residual.
    score += (post_residual as f64 / cap) * (post_residual as f64) * 0.5;

    // Reward near-perfect fits (waste <= 5).
    if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual <= 10 {
        score -= 15.0;
    }

    // Lookahead: reward if the next item fits into the resulting residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (next_item_size as u32) <= post_residual {
            score -= 8.0 + 12.0 * (1.0 - nxt / cap);
            // Extra reward for a chain fit (next item also near-exact).
            if post_residual as i64 - next_item_size as i64 <= 5 {
                score -= 10.0;
            }
        } else {
            // Penalize leaving residual that next item almost-but-not-quite fits.
            let gap = (next_item_size as u32 - post_residual) as f64;
            if gap <= 10.0 {
                score += 6.0 + gap;
            }
        }
    } else {
        // Last item: prefer the tightest possible closure.
        score -= 20.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // Mild competition bonus proportional to choice availability.
        score += 2.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // Global pressure: many open bins with high mean residual -> prefer consolidation.
    let pressure = mean_residual / cap;
    if pressure > 0.4 && open_bins_count > 3 {
        score -= 5.0 * pressure;
    }

    // New-bin candidate (empty bin): penalize unless existing fits are bad.
    if bin_residual == bin_capacity {
        score += 40.0;
        // But late in the stream, opening a fresh bin for large items is fine.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        if item_size >= 50 && progress > 0.7 {
            score -= 20.0;
        }
        // Never open a new bin when a near-perfect fit exists elsewhere.
        if post_residual as f64 > (cap - item_size as f64) * 0.5 {
            score += 10.0;
        }
    }

    // Time-horizon modulation: early stream, be conservative (slightly favor tight fits more).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.15 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post_residual, with non-linear sharpening
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Polynomial coupling of post_residual with stream progress:
    // early: tolerate larger residuals; late: demand tight fits
