    score *= progress_coupling;

    // Reward perfect / near-perfect fits non-linearly
    if pr == 0 {
        score -= 50.0;
    } else {
        score -= 40.0 * (1.0 - norm_pr).powi(6);
    }

    // Lookahead: penalize residual too small for next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 6.0 * (pr - nx) / cap;
        } else {
            score += 8.0 * (nx - pr) / cap;
        }
