    // Last-chance bin: strong bonus to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Mild penalty for spreading across many open bins vs mean residual
    score += 0.05 * (open_bins_count as f64).ln().max(0.0) * (norm_pr - mean_residual / cap).abs();

    // New-bin candidate: keep it neutral-slightly-high unless current fit is poor
    if bin_residual == bin_capacity {
        score = 25.0 + 20.0 * progress - 15.0 * (1.0 - norm_pr).powi(6);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual via integer division on capacity quarters.
    let quarter = bin_capacity / 4;
    let post_class = post_residual / quarter.max(1);
    let next_class = next_item_size / quarter.max(1);

    // Perfect fit is golden.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Reward when the lookahead item fits exactly into post_residual (harmonic coupling).
    if next_item_size > 0 && post_residual >= next_item_size {
        if post_residual == next_item_size {
