        score += (post_class as f64) * 25.0;
    }

    // Tight fits (small post_residual but nonzero) are near-dead space unless reusable.
    if post_residual > 0 && post_residual < 10 {
        score += 150.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // Prefer bins with residual already below mean (consolidate emptiness).
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Modulo-10 harmonic bonus: residuals divisible by 10 align with item grid.
    if post_residual % 10 == 0 {
        score -= 20.0;
    }

    // Late in stream: avoid opening new bins, pack tighter.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses and bins accumulate.
        score += 80.0 + 120.0 * progress + 5.0 * open_bins_count as f64;
    } else {
        score -= 10.0 * progress;
    }

    // Integer-division threshold: residuals in (25, 50] are semi-useful, discount slightly.
    if post_class == 1 {
        score -= 15.0;
    } else if post_class >= 2 {
        score -= 5.0 * post_class as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
