        // Penalize leaving residual too small for the next item (dead space)
        if post_residual < next_item_size && post_residual > 0 {
            score += 12.0 * (1.0 - post_residual as f64 / next_item_size.max(1) as f64);
        }
    } else {
        // Last item: prefer minimal waste
        score += 5.0;
    }

    // Favor bins with residual below the mean (tighter packing candidates)
    score += 0.25 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly reward using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate: only attractive when current bins are quite full
    if bin_residual == bin_capacity {
        let tight = mean_residual / bin_capacity as f64;
        score += 25.0 * (1.0 - tight); // high when bins are loose -> discourage new bin
        if fitting_bins_count == 0 {
            score -= 30.0; // nothing fits, must open
        }
    }

    // Mild preference for filling fuller bins (low residual)
    score -= 0.15 * (bin_capacity - bin_residual) as f64;

    // Slight time-decay urgency: as stream progresses, avoid fragmentation
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 6.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near 0 is best; amplify low waste.
    let waste_ratio = post_residual as f64 / cap;
    score += 12.0 * waste_ratio * waste_ratio;

    // Strong bonus for exact or near-exact fills.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    } else if post_residual < 10 {
        score -= 10.0;
    }

    // Lookahead (k=2): if the next item fits in the post-residual, reward;
    // if this placement creates residual that next item can't use, penalize.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (next_item_size as u32) <= post_residual {
            score -= 8.0 * (1.0 - nxt / cap);
        } else {
            // Dead space for the next item: penalize proportionally to unusable gap.
            score += 4.0 * (1.0 - (post_residual as f64) / cap);
            // If next item exactly matches residual, big bonus for leaving it.
            if (next_item_size as u32) == post_residual {
                score -= 15.0;
            }
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Many fitting bins: mild penalty to encourage consolidation into fuller bins.
    if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // Prefer bins whose residual is below mean residual (fuller bins),
    // keeping emptier bins available for larger future items.
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score += 0.15 * dev;
    } else {
        score -= 0.10 * (-dev);
    }

    // Time horizon: early in stream, be conservative about fragmenting bins;
    // late in stream, prefer closing bins out (tight fits weighted more).
    let progress = if total_items > 0 {
        step_index as f64 / total_items as f64
    } else {
        0.0
    };
    score -= 6.0 * progress * (1.0 - waste_ratio);

    // New-bin candidate: neutral-ish score so it's chosen only when no open bin
    // offers a decent fit. Scale with item size (large items in fresh bins are fine).
    if bin_residual == bin_capacity {
        score = cap - item_size as f64 + 30.0;
        if fitting_bins_count == 0 {
            score -= 60.0; // no alternative: must open
        }
        if next_item_size > 0 && (next_item_size as u32) <= post_residual {
            score -= 5.0;
        }
    }

    // Penalize opening bins when many are already open (fragmentation control).
    score += 0.5 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let fit = fitting_bins_count.max(1) as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post;

    // Smooth non-linear polynomial coupling of post_residual with stream progress.
    let norm_post = post / cap;
    let p = progress * progress;
    // Early stream: prefer tight fits; late stream: tolerate larger residuals less.
    score += 18.0 * norm_post * norm_post * (0.4 + 0.6 * p);
    score -= 10.0 * (1.0 - norm_post) * (1.0 - norm_post) * (1.0 - 0.5 * p);

    // Reward tight fits (small post_residual) with smooth decay.
    score -= 22.0 * (-post / 18.0).exp();

    // Lookahead coupling: reward residual that can host the next item smoothly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post - nxt).abs();
        score -= 8.0 * (-gap / 25.0).exp();
    }

    // Last-chance bin: strong bonus to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0 * (1.0 - 0.5 * progress);
    }

    // Mild penalty proportional to crowding of fitting bins (prefer scarce capacity).
    score += 2.5 * (fit - 1.0).ln().max(0.0);

    // Mean residual interaction: if this bin's residual is below mean, reward.
    let resid = bin_residual as f64;
    score -= 4.0 * ((mean_residual - resid) / cap).tanh();

    // Penalize opening a new bin when good fits exist: new-bin candidate has
    // bin_residual == bin_capacity; add smooth surcharge scaled by stream progress.
    if bin_residual == bin_capacity {
        score += 20.0 + 15.0 * (1.0 - progress) + 0.05 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward small post-residuals that align
    // with typical item size classes (mod 10 buckets), penalize awkward classes.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Fraction of capacity wasted after placement (non-linear, superlinear penalty)
    let waste_frac = pr / cap;
    score += waste_frac * waste_frac * 40.0;

    // Harmonic class reward: post_residual near multiples of 10 leaves room for
    // common item classes; classify via integer division thresholds.
    let class = post_residual / 10; // 0..10 harmonic class
    let class_penalty = match class {
        0 => -12.0,  // perfect fit or near-fit
        1 => -6.0,
        2 => -2.0,
        3 => 0.0,
        4 => 2.0,
        5 => 4.0,
        6 => 6.0,
        7 => 8.0,
        8 => 10.0,
        9 => 12.0,
        _ => 0.0,
    };
    score += class_penalty;

    // Dead-zone penalty: residuals in (0, 10) are unusable for any item (min size 1..100
    // but small leftovers rarely reusable); strongly discourage leaving tiny scraps.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if next <= pr {
            let fit_gap = (pr - next) / cap;
            score -= 10.0 * (1.0 - fit_gap * fit_gap);
            // exact harmonic match bonus
            if post_residual == next_item_size {
                score -= 8.0;
            }
        } else {
            // next item cannot use the leftover: mild penalty scaled by leftover size
            score += 0.05 * pr;
        }
    }

    // Last-chance logic: if this is the only fitting bin, avoid forcing us to open
    // a new bin unless the fit is genuinely good.
    if fitting_bins_count == 1 && post_residual > 0 {
        score -= 5.0;
    }

    // New-bin candidate (empty bin): prefer it only when no open bin gives a tight fit.
    if bin_residual == bin_capacity {
        // baseline score for fresh bin is its full residual (100); adjust with stream state
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 6.0 - 4.0 * progress;
        // if many bins fit the item, discourage opening yet another bin
        if fitting_bins_count > 0 {
            score += 8.0;
        }
        // if mean residual across open bins is small, opening new bin is reasonable
        score -= (mean_residual / cap) * 3.0;
    }

    // Mild preference for consolidating into bins below mean residual (tighter bins first)
    if (bin_residual as f64) < mean_residual {
        score -= 1.5;
    } else {
        score += 1.5;
    }

    // Small late-stream tightening: as stream progresses, prefer tighter fits more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 + (10 - post_residual as i32) as f64 * 3.0;
    }
    // Perfect fit is strongly rewarded.
    if post_residual == 0 {
        score -= 15.0;
    }

    // Reward tight fits relative to residual (small waste ratio).
    let waste_ratio = post_residual as f64 / bin_residual.max(1) as f64;
    score += waste_ratio * 10.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor filling.
    let pressure = open_bins_count as f64 / (1.0 + total_items as f64 * 0.05);
    score += pressure * 4.0;

    // New-bin candidate handling: only attractive when no open bin fits well
    // or open bins are nearly full on average.
    if bin_residual == bin_capacity {
        let mean_tight = mean_residual / bin_capacity as f64;
        if fitting_bins_count == 0 {
            score -= 20.0;
        } else if mean_tight < 0.35 && open_bins_count > 2 {
            score -= 3.0;
        } else {
            score += 10.0 + open_bins_count as f64 * 0.5;
        }
    }

    // Lookahead: if the next item would fit the post-residual exactly, reward it.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 8.0;
    }
    // Penalize leaving a gap that the next item cannot use at all.
    if next_item_size > post_residual && post_residual > 0 && post_residual < 10 {
        score += 5.0;
    }

    // Slight stream-progression term: later in stream, prefer consolidation.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 2.0 * (post_residual as f64 / 10.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect or near-perfect fits
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    }

    // Aggressive 2-step lookahead: reward if next item fits into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 900.0; // exact two-item completion
        } else if next_item_size < post_residual {
            let leftover = post_residual - next_item_size;
            score -= 500.0 - (leftover as f64) * 2.0; // prefer tight chain fits
        } else {
            // next item cannot follow: penalize wasted potential
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.5;
        }
    }

    // Compare post_residual against mean residual across open bins
    score -= (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 250.0;
    }

    // Penalize opening a new bin when many bins are open and item could fit elsewhere
    if bin_residual == bin_capacity {
        // new-bin candidate: baseline score = capacity - item_size effectively
        // make it unattractive unless few bins open or lookahead is bad
        score += 120.0;
        if open_bins_count <= 1 {
            score -= 150.0;
        }
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // new bin can always chain, slight bonus
            score -= 40.0;
        }
    }

    // Mild late-stream tightening: prefer compact packing as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward tight fits (small dead space relative to capacity)
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - tightness) * 10.0;

    // Penalize large unusable dead space: post_residual too small for typical future items
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // sliver waste
    }

    // Lookahead: if next item fits in post_residual, reward strongly
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0 + (next_item_size as f64) * 0.2;
    } else if next_item_size > 0 {
        // next item won't fit here; mild penalty proportional to mismatch
        let gap = (next_item_size as i64 - post_residual as i64).max(0) as f64;
        score += gap * 0.15;
    }

    // Last-chance bin: strongly favor using the only bin that can fit
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else {
        // Prefer bins that are more filled (smaller residual) among many options
        score += (bin_residual as f64) * 0.1;
    }

    // Global state: many open bins with high mean residual -> prefer consolidation
    if open_bins_count > 2 && mean_residual > 0.0 {
        let consolidation = (mean_residual - post_residual as f64) * 0.3;
        score += consolidation.max(-20.0).min(20.0);
    }

    // New-bin candidate logic: only open a new bin when no good fit exists
    if bin_residual == bin_capacity {
        // base cost of opening a bin
        score += 55.0;
        // open new bin if current item is large and existing fits are poor
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 20.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // forced new bin
        }
        // late in stream, avoid spreading
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 10.0;
    }

    // Time horizon: early items -> keep bins flexible (moderate residuals); late -> pack tight
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * (100.0 - post_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let pr_norm = pr / bin_capacity as f64;
    // Non-linear polynomial coupling: post_residual penalized more heavily as stream progresses
    score += 40.0 * progress * pr_norm * pr_norm;
    // Reward tight fits (small post_residual) with smooth quadratic bonus
    score -= 25.0 * (1.0 - pr_norm) * (1.0 - pr_norm) * (0.5 + 0.5 * progress);
    // Penalize creating dead space that next item cannot use (smooth interaction)
    if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap >= 0.0 {
            let g = gap / bin_capacity as f64;
            score -= 30.0 * g * (1.0 - g) * (1.0 - progress);
        } else {
            score += 15.0 * (pr / next_item_size as f64) * (pr / next_item_size as f64);
        }
    }
    // Last-chance bin bonus: strongly favor the single fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }
    // Discourage opening new bins when many bins already fit the item
    if bin_residual == bin_capacity {
        score += 20.0 + 5.0 * open_bins_count as f64 * (1.0 - progress);
    }
    // Mild penalty when bin residual deviates from mean residual (smooth coupling)
    score += 0.05 * (pr - mean_residual) * (pr - mean_residual) / bin_capacity as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that are "useful" slots
    // (multiples of common item-size classes), penalize dead-space classes.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fill
    } else {
        // modulo arithmetic on residual: 25/50/75 are highly reusable classes
        let class = pr % 25;
        score += match class {
            0 => -25.0,
            1..=5 => 8.0,
            _ => 0.0,
        };
        if pr % 50 == 0 { score -= 20.0; }
        if pr % 10 == 0 { score -= 6.0; }
        // small residuals (<10) are dead space unless zero
        if pr < 10 { score += 30.0; }
    }

    // Coupling with lookahead: post_residual matching next item's size is gold.
    if next_item_size > 0 {
        if pr == next_item_size {
            score -= 40.0;
        } else if pr > next_item_size {
            let slack = pr - next_item_size;
            // harmonic class of leftover after hypothetically placing next item
            if slack % 25 == 0 { score -= 12.0; }
            if slack < 10 { score += 10.0; }
        } else {
            // next item can't fit here; residual must serve future items
            score += 5.0;
        }
    } else {
        // last item: prefer tightest fill aggressively
        score -= 50.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize opening a bin unless current fits are poor.
    if bin_residual == bin_capacity {
        let tightness = (item_size as f64) / cap;
        score = 100.0 + tightness * 50.0;
        if fitting_bins_count == 0 { score -= 200.0; }
        // early stream: keep few bins; late stream: open freely for tight fits
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress < 0.2 { score += 20.0; }
        if item_size >= 80 { score -= 10.0; } // big items start fresh bins
    }

    // Mild pressure toward bins below mean residual (balance + consolidate).
    score += 0.15 * (mean_residual - bin_residual as f64).abs().signum()
        * (mean_residual - bin_residual as f64);

    // Prefer bins among many fitting options by residual tightness scaling.
    if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    score
}

