pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but exact/near-exact fits are heavily favored.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * tightness * tightness;

    // Strong bonus for (near-)perfect fill.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // 2-step lookahead: reward bins whose residual after placement matches the next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += 0.6 * gap;
        if post_residual == next_item_size {
            score -= 30.0; // perfect two-item chain
        } else if post_residual > next_item_size {
            score -= 10.0; // next item still fits here
        } else {
            score += 8.0; // next item won't fit; residual likely dead space
        }
        // Penalize leaving residual slightly below next_item_size (worst case: unusable sliver)
        if post_residual > 0 && post_residual < next_item_size {
            score += 12.0;
        }
    }

    // Compare against mean residual: prefer bins with more room than average when item is large,
    // and bins with less room when item is small (preserve big gaps for big items).
    let size_frac = item_size as f64 / bin_capacity as f64;
    score += size_frac * (mean_residual - bin_residual as f64).max(0.0) * 0.5;
    score -= (1.0 - size_frac) * (bin_residual as f64 - mean_residual).max(0.0) * 0.3;

    // Last-chance bin: strongly reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 5.0;
        } else {
            // Opening a new bin wastes the residual of existing bins; penalize mildly,
            // but allow it when the item is large and existing residuals are fragmented.
            let fragmentation = mean_residual / bin_capacity as f64;
            if item_size > 50 && fragmentation < 0.35 {
                score -= 8.0;
            } else {
                score += 20.0;
            }
        }
        // Early in the stream, opening bins is cheap and builds flexibility.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
    }

    // Penalize many open bins slightly to encourage consolidation.
    score += open_bins_count as f64 * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

