    let tight = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 6.0 * tight * tight;

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless the item is large
    // (large items in a fresh bin waste little space).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let item_frac = item_size as f64 / bin_capacity as f64;
        score += 4.0 + 10.0 * (1.0 - item_frac);
        // Early in the stream, opening bins is cheap; late, prefer consolidation.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 3.0 * progress;
    } else {
        // Reward keeping bins open (fewer open bins is good, but placing into
        // existing bins is the primary goal).
        score -= 1.0;
    }

    // Lookahead coupling: reward leaving a residual that can host the next item.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item chains perfectly: big reward, scaled by how snugly it fits.
            let snug = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 5.0 + 4.0 * snug;
        } else if (next_item_size as f64) <= mean_residual {
            // This placement consumes space the next item might have wanted elsewhere.
            score += 2.0;
        }
        // If next item is huge, prefer dumping current item here to keep flexibility.
        if next_item_size > post_residual && next_item_size > 60 {
            score -= 2.0;
        }
    }

    // Dead-space penalty: residuals too small for typical items are worthless.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Mild pressure against accumulating many open bins with large mean residual.
    score += 0.05 * open_bins_count as f64 * (mean_residual / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress.
    // Early on: prefer tight fills mildly; later: penalize wasted residual strongly.
    let progress_weight = 0.5 + 2.5 * t;
    score += progress_weight * pr_norm * pr_norm * cap;

    // Reward leaving residual that matches the next item (smooth quadratic).
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score -= 6.0 * (1.0 - gap / cap).max(0.0);
        // Exact next-item fit bonus (smooth exponential)
        score -= 10.0 * (-(gap * gap) / (2.0 * 25.0)).exp();
    }

    // Penalize dead space that nothing can ever use (below min item size).
    let min_item = 1.0f64;
    if pr < min_item {
        score += 100.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Crowding: many open bins with high mean residual -> prefer consolidating
    // into bins below mean residual (tighter bins).
    let dev = (pr - mean_residual) / cap;
    score += 3.0 * dev * dev * (1.0 + open_bins_count as f64 * 0.05);

    // Perfect fit bonus.
    score -= 8.0 * (-(pr * pr) / 50.0).exp();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals that are multiples of a
    // "harmonic base" are more reusable by future items (sizes 1..100).
    let base: u32 = 10;
    let class = post_residual % base;
    if class == 0 {
        score -= 8.0; // perfectly harmonic residual, highly reusable
    } else if class <= 2 || class >= base - 2 {
        score -= 3.0; // near-harmonic, still decent
    } else {
        score += 4.0; // awkward mid-class dead space
    }

    // Penalize small non-zero post_residual (dead space) more aggressively
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Reward tight fits (post_residual near zero)
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly into the post-residual, big bonus
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            score -= 6.0;
            // harmonic coupling between next item and post residual
            if post_residual % base == 0 && next_item_size % base == 0 {
                score -= 4.0;
            }
        } else {
            score += 5.0; // next item won't fit here anyway
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are crowded
    if bin_residual == bin_capacity {
        score += 30.0;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowd = open_bins_count as f64 / 10.0;
        if mean_residual < item_size as f64 * 1.5 && crowd > 1.0 {
            score -= 25.0 + 10.0 * (1.0 - progress);
        }
    }

    // Prefer filling bins with large residual relative to mean (balance avoidance)
    if bin_residual as f64 > mean_residual * 1.4 && bin_residual != bin_capacity {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest plausible
    // item (<= ~10) are pure waste; penalize them hard.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Residuals in the awkward 11..=25 band are only usable by small items;
    // apply a graded penalty proportional to how "dead" the gap is.
    if post_residual >= 10 && post_residual <= 25 {
        score += (25.0 - post_residual as f64) * 0.8;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Lookahead coupling: if the next item fits the post-residual, this is a
    // great chain placement — reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 + (next_item_size as f64) * 0.1;
    }

    // Last-chance pressure: if this is the only fitting bin, avoid opening a
    // new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // over spreading items out (penalizes new-bin temptation implicitly by
    // lowering scores of existing bins).
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln() * (1.0 + 0.5 * progress);
    if bin_residual != bin_capacity {
        score -= pressure;
    } else {
        // New-bin candidate: mildly discourage unless open bins are crowded.
        score += pressure * 0.5 + mean_residual * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let post = post_residual as f64;
    let fit = item_size as f64;

    // Base: waste after placement, with a convex penalty so large dead space is punished harder.
    let mut score = post + (post * post) / (2.0 * cap_f);

    // Reward tight fits: fraction of bin consumed by this item.
    let tightness = 1.0 - post / cap_f;
    score -= 8.0 * tightness * tightness;

    // Perfect-fit bonus: residual exactly zero or a "nice" small remainder.
    if post_residual == 0 {
        score -= 15.0;
    } else if post_residual <= 10 {
        score -= 5.0 * (1.0 - post / 10.0);
    }

    // Lookahead coupling: if the next item can fit into post_residual, this is a great pairing.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size <= post_residual {
            score -= 6.0 * (1.0 - (post - nxt) / cap_f);
        } else {
            // Next item won't fit here; slightly penalize leaving a useless gap.
            score += 2.0 * (post / cap_f);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // Global state: when many bins are open with high mean residual, prefer consolidating
    // into bins that are already relatively full (avoid fragmenting space).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let fill = 1.0 - (bin_residual as f64) / cap_f;
    score -= 4.0 * fill * (mean_residual / cap_f) * (1.0 + progress);

    // Early in the stream, be more willing to spread; late, prefer tight packing.
    score += 3.0 * (1.0 - progress) * (post / cap_f);

    // New-bin candidate handling: opening a new bin wastes capacity equal to item_size.
    // Only attractive when no open bin fits well (large post_residual in every open bin,
    // or this is effectively a last resort). Penalize moderately so tight existing fits win.
    if bin_residual == bin_capacity {
        score += 12.0;
        // But if the item is large, a fresh bin is natural (big items pack cleanly alone).
        score -= 4.0 * (fit / cap_f);
        // If many bins are open and mean residual is small, opening yet another bin is bad.
        score += 2.0 * (open_bins_count as f64 / (1.0 + mean_residual / cap_f));
        // Late in the stream, avoid proliferation of barely-used bins.
        score += 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;

    // Base: prefer tight fits (small post_residual), with quadratic penalty on waste
    let mut score = pr + (pr * pr) / cap;

    // Smooth non-linear coupling with stream progress: later in the stream,
    // waste becomes more costly (bins are harder to reuse at the tail).
    let progress_coupling = (pr / cap) * (progress * progress) * 30.0;
    score += progress_coupling;

    // Reward filling bins that are already mostly full (small residual before placement)
    let fullness = 1.0 - (bin_residual as f64) / cap;
    score -= fullness * fullness * 12.0;

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 20.0 * progress;
    }

    // Penalize bins whose residual is far from mean residual (fragmentation signal)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += dev * dev * 10.0;

    // Lookahead: if next item fits exactly in post_residual, reward strongly (smooth)
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= (1.0 - gap / cap).max(0.0) * 15.0;
    }

    // Mild penalty for opening a new bin when many bins are open (encourage consolidation)
    if bin_residual == bin_capacity {
        score += 8.0 + 6.0 * progress + open_bins_count as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with slight convexity
    score += (post_residual as f64).powi(2) / (2.0 * bin_capacity as f64);

    // Harmonic class of post_residual: modulo arithmetic on capacity fractions
    let cap = bin_capacity;
    let pr = post_residual;
    // Perfect-fill class: post_residual in {0, cap/2, cap/3, cap/4} is highly reusable
    let harmonic_divs = [1u32, 2, 3, 4, 5];
    for d in harmonic_divs {
        if pr != 0 && pr == cap / d {
            score -= 8.0;
        }
    }
    // Post_residual divisible by small integers => likely to fit future items exactly
    if pr > 0 && (pr % 10 == 0) {
        score -= 3.0;
    }
    if pr > 0 && pr % 5 == 0 {
        score -= 1.5;
    }
    // Dead-zone class: post_residual too small to be useful (below min item size ~1..10 typical)
    if pr < 10 && pr > 0 {
        score += 12.0; // unusable sliver
    }

    // Lookahead coupling: if next item exactly fits post_residual, strong reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 15.0;
        } else if next_item_size <= pr {
            let gap = (pr - next_item_size) as f64;
            score -= 5.0 * (1.0 - gap / cap as f64);
            // harmonic match: next item divides post_residual evenly
            if pr > 0 && next_item_size > 0 && pr % next_item_size == 0 {
                score -= 4.0;
            }
        } else {
            // next item cannot use this residual at all
            score += 4.0;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // New-bin candidate handling: opening a new bin should only win if fit is bad
    if bin_residual == bin_capacity {
        // penalize new bin mildly; tight fits elsewhere will beat it
        score += 6.0 + post_residual as f64;
        // but if no bin fits well (post_residual everywhere large), new bin is fine
        if mean_residual < item_size as f64 {
            score -= 4.0;
        }
    }

    // Prefer packing into bins with below-mean residual (balance/consolidation)
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Slight preference to fill older/fuller bins when many bins open
    score -= 0.05 * open_bins_count as f64 * (1.0 - bin_residual as f64 / cap as f64);

    // Stream progression: later in stream, consolidate harder
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 2.0 * progress * (1.0 - post_residual as f64 / cap as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residual gaps that are too small to be
    // useful are heavily penalized.
    let min_useful = 10u32;
    if post_residual > 0 && post_residual < min_useful {
        score += 60.0;
    } else if post_residual == 0 {
        // Perfect fit is strongly rewarded.
        score -= 80.0;
    }

    // Non-linear penalty on wasteful post-residual relative to capacity.
    let post_frac = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * post_frac * post_frac;

    // Favor bins whose residual is close to the item (tight fits).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score -= 25.0 * (1.0 - tightness);

    // Open-bins pressure: when many bins are open, prefer filling existing
    // bins rather than opening new ones.
    let pressure = open_bins_count as f64 / (1.0 + open_bins_count as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to open bins pressure.
        score += 30.0 * pressure;
        // Reward opening a new bin if nothing fits well anywhere.
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    } else {
        // Reward using an existing bin, more so under pressure.
        score -= 15.0 * pressure;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Lookahead coupling: if the next item fits in the post-residual,
    // reward this placement (keeps bins chainable).
    if next_item_size > 0 {
        if (post_residual as i64) >= (next_item_size as i64) {
            score -= 20.0;
        } else if post_residual > 0 && (post_residual as i64) < (next_item_size as i64) {
            // Post-residual becomes dead space relative to the next item.
            score += 10.0;
        }
    }

    // Stream progression: early on, be more willing to open bins (spread),
    // later, consolidate tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 20.0 * progress;
    } else {
        score -= 10.0 * progress;
    }

    // Deviation from mean residual: prefer bins whose residual is above the
    // mean (use the roomiest bins first, keeping tight bins for tight items).
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score -= 8.0 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Core: reward exact match between post_residual and next item size (2-step lookahead)
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs();
        score += diff as f64 * 1.5;
        // Strong bonus for perfect chain fit
        if post_residual as i64 == next_item_size as i64 {
            score -= 30.0;
        }
        // Penalize dead space too small for any plausible next item
        if post_residual < next_item_size && post_residual > 0 {
            score += 8.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    } else {
        // Last item: prefer fullest packing
        score -= 10.0;
    }

    // Compare residual against mean residual across open bins
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Penalize opening a new bin when open bins fit reasonably well
    if bin_residual == bin_capacity {
        let waste = (bin_capacity - item_size) as f64;
        score += waste * 0.2 + 15.0;
        // Late in the stream, opening new bins is worse
        score += 20.0 * progress;
        if fitting_bins_count > 0 {
            score += 10.0;
        }
    }

    // Slight preference for tighter fits overall
    score += (item_size as f64 / bin_residual.max(1) as f64) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Prefer bins where the item fills a large fraction of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fit_ratio * fit_ratio;

    // Penalize leaving small unusable slivers (dead space), reward exact fits.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }
    if post_residual == 0 {
        score -= 20.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let next_fit = next_item_size as f64 / post_residual as f64;
            score -= 12.0 * next_fit;
        } else {
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when open bins are crowded / bad fits.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowded = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
        score += 60.0 - 40.0 * progress - 2.0 * crowded - mean_residual * 0.3;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open new bin
        }
    }

    // Mild preference for filling bins with low mean residual across the fleet.
    score += (mean_residual - post_residual as f64) * 0.05;

    // Late in stream, be greedier about closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
