pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: capacity fraction classes
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap;

    // Class 1: near-perfect fit (residual in smallest decile) -> strong reward
    if post_residual <= bin_capacity / 10 {
        score -= 40.0;
    }
    // Class 2: unusable dead space (residual too small for any plausible item 1..100)
    if post_residual > 0 && post_residual < 8 {
        score += 25.0; // dead space penalty
    }

    // Integer-division harmonic classes on post_residual
    let class = post_residual / 10; // decile class 0..10
    match class {
        0 => score -= 15.0,
        1 => score -= 5.0,
        2 | 3 => score += 2.0,
        4 | 5 => score += 6.0,
        6 | 7 => score += 10.0,
        _ => {}
    }

    // Modulo coupling: does next item fit into post_residual harmonically?
    if next_item_size > 0 {
        let nxt = next_item_size;
        if nxt <= post_residual {
            // reward leaving room for next item, scaled by tightness of that fit
            let tight = (post_residual - nxt) as f64;
            score -= 12.0 - (tight / cap) * 10.0;
            // extra harmonic bonus if next item exactly matches a class boundary
            if post_residual % nxt == 0 {
                score -= 8.0;
            }
        } else {
            // next item won't fit here: penalize wasting space it could have used elsewhere
            score += 6.0;
            if nxt > post_residual && nxt <= bin_residual {
                score += 3.0; // bin could have held next item but not after this placement
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a bin unless current bins are badly fragmented
    if bin_residual == bin_capacity {
        score += 10.0;
        if mean_residual > frac * cap + 15.0 {
            score -= 18.0; // open bins fragmented -> new bin is fine
        }
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    // Prefer filling bins with large residual mismatch (balance residuals toward mean)
    let dev = bin_residual as f64 - mean_residual;
    score += dev * 0.05;

    // Stream progression: early on, be conservative about opening bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= progress * 5.0;
    }

    // Mild reward for high fill ratio of this placement
    score -= (item_size as f64 / cap) * 8.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // Post-residuals that are too small for the minimum item size (1) are fine only if 0;
    // small but nonzero gaps risk becoming permanent dead space.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let min_item = 1.0f64;

    if post_residual == 0 {
        // Perfect fit: heavily reward.
        score -= 60.0;
    } else if (post_residual as f64) < min_item * 3.0 {
        // Tiny unusable gap: strong penalty scaled by progress (late gaps are worse).
        score += 25.0 + 30.0 * progress;
    } else {
        // Usable gap: mild reward proportional to how well it matches typical item scale.
        let gap_fit = (post_residual as f64 / bin_capacity as f64).powf(1.5);
        score -= 10.0 * gap_fit;
    }

    // --- Tightness reward: prefer bins where the item fills a large fraction of residual ---
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * tightness * tightness;

    // --- Last-chance bin: if this is the only fitting bin, strongly prefer using it ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    } else if fitting_bins_count > 1 {
        // Among many fitting bins, prefer the emptiest (largest residual) to consolidate load.
        score += 0.15 * (bin_residual as f64 - mean_residual);
    }

    // --- Open bins pressure: discourage spreading across many bins ---
    score += 0.08 * open_bins_count as f64 * (1.0 - progress);

    // --- Lookahead: if next item fits the post-residual exactly-ish, reward ---
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            score += 5.0;
        }
    }

    // --- New-bin candidate handling: only open a new bin when no open bin offers a decent fit ---
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        let mut new_bin_score = 95.0 + 0.05 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            // Forced: no open bin fits; new bin is required.
            new_bin_score -= 200.0;
        } else if fitting_bins_count == 1 && (bin_residual - item_size) > 0 {
            // Only one fitting bin exists; opening new bin is wasteful unless that fit is terrible.
            let existing_tightness = item_size as f64 / bin_residual.max(1) as f64;
            if existing_tightness < 0.4 {
                new_bin_score -= 60.0; // poor existing fit -> new bin acceptable
            }
        }
        score = new_bin_score;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= fit_ratio * 12.0;

    // 2-step lookahead: reward bins whose post_residual matches the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let match_quality = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= match_quality * 18.0;
        } else {
            // Next item cannot follow here; penalize proportionally to the gap.
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.35;
        }
    } else {
        // Last item: only current fit matters.
        score -= fit_ratio * 8.0;
    }

    // Relative-to-mean residual shaping: bins below mean residual are precious.
    if (post_residual as f64) < mean_residual {
        score += (mean_residual - post_residual as f64) * 0.25;
    } else {
        score -= (post_residual as f64 - mean_residual) * 0.10;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when decent existing fits exist.
    if bin_residual == bin_capacity {
        if next_item_size > 0 && next_item_size >= bin_capacity {
            score -= 5.0; // nothing fits a full item anyway
        }
        score += 10.0 + open_bins_count as f64 * 0.5;
        // New bin looks better late in the stream if current bins are fragmented.
        if mean_residual < item_size as f64 {
            score -= 15.0;
        }
    }

    // Mild stream-progression term: consolidate more aggressively as stream ends.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * (bin_residual - post_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that no plausible item could use.
    if post_residual < 10 && post_residual > 0 {
        score -= 8.0; // near-perfect fill is excellent
    }
    if post_residual > 60 {
        score += 6.0 * ((post_residual - 60) as f64 / 40.0); // large unusable gap
    }

    // Lookahead coupling: bonus if the next item fits into the post residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 * (next_item_size as f64 / 100.0);
    } else if next_item_size > 0 && post_residual > 0 {
        // leftover too small for the next item: penalize proportionally
        score += 4.0 * (1.0 - (post_residual as f64) / (next_item_size as f64).max(1.0));
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Crowding pressure: when many bins are open, prefer consolidation.
    score += 2.0 * (open_bins_count as f64).ln().max(0.0) * (1.0 - tightness);

    // Global state: prefer bins whose residual is close to the mean residual
    // (keeps open bins homogeneous, easier to fill later).
    score += 0.5 * ((bin_residual as f64 - mean_residual).abs() / 50.0);

    // Time horizon: early in the stream, be conservative about wasting space;
    // late in the stream, accept slightly worse fits to close bins out.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * tightness;
    score += 3.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: baseline neutral score, only chosen when no open bin
    // is reasonably attractive; make it worse as open bins accumulate.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 0.9 + 8.0 * (open_bins_count as f64).ln().max(0.0);
        if next_item_size > 0 && item_size >= 70 {
            score -= 5.0; // big item alone in a fresh bin is fine
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let isz = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let t = progress.clamp(0.0, 1.0);
    let poly_t = 3.0 * t * t - 2.0 * t * t * t; // smoothstep-like coupling

    // Base: prefer tight fits (small post_residual), non-linearly amplified
    let mut score = pr * (1.0 + 0.8 * pr / cap) + 0.35 * (pr / cap) * (pr / cap) * cap;

    // Dead-space penalty: residuals too small for typical future items
    let dead = (cap * 0.2 - pr).max(0.0);
    score += 1.5 * dead * dead / cap;

    // Coupling: early in stream, tolerate larger residuals (keep bins flexible);
    // late in stream, strongly prefer small post_residual
    score += poly_t * pr * 0.6 - (1.0 - poly_t) * pr * 0.15;

    // Lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 && (pr as u32) >= next_item_size {
        score -= 6.0 + 4.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        score += 2.0 * (next_item_size as f64 - pr) / cap;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // Prefer bins with residuals near mean (balance), mild effect
    score += 0.3 * ((pr - mean_residual) / cap).abs();

    // Slight preference to fill already-open bins when many are open
    score += 0.05 * open_bins_count as f64;

    // New-bin candidate: make it moderately attractive only when fit is bad
    if bin_residual == bin_capacity {
        score += 3.0 + 2.0 * (isz / cap);
        score -= 0.5 * poly_t;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that are "nice" fractions
    // of capacity (divisible by 50, 25, 20, 10) since they invite future fits.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut harmony_bonus = 0.0;
    if post_residual % 50 == 0 { harmony_bonus += 6.0; }
    else if post_residual % 25 == 0 { harmony_bonus += 4.0; }
    else if post_residual % 20 == 0 { harmony_bonus += 3.0; }
    else if post_residual % 10 == 0 { harmony_bonus += 2.0; }
    if post_residual == 0 { harmony_bonus += 12.0; } // perfect fill
    score -= harmony_bonus;

    // Penalize small dead space that nothing (min size 1) can still use well:
    // residuals below 10 are nearly dead -> heavy penalty.
    if post_residual < 10 && post_residual > 0 {
        score += 15.0 * (1.0 - pr / 10.0);
    }

    // Lookahead coupling: if next item fits the post residual exactly, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            // reward proportional to how snugly next item fits
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / cap);
        } else {
            // next item cannot use this residual: mild penalty scaled by waste
            score += 3.0 * ((next_item_size - post_residual) as f64 / cap);
        }
        // Harmonic pairing: next item in same modulo class as post_residual
        if next_item_size > 0 && post_residual % next_item_size.max(1) == 0 && post_residual > 0 {
            score -= 4.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible.
    if bin_residual == bin_capacity {
        score += 18.0;
        if post_residual == bin_capacity - item_size {
            // fresh bin still gets a base score of post_residual; fine.
        }
    }

    // Prefer bins whose residual deviates favorably from the mean residual:
    // packing into below-mean-residual bins consolidates fragmentation.
    let dev = pr - mean_residual;
    score += 0.15 * dev;

    // Stream progression: early on, be conservative about tight fits;
    // later, push toward perfect closure.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * harmony_bonus * 0.5;

    // Many open bins: discourage spreading, favor tighter bins.
    if open_bins_count > 4 {
        score += 0.05 * open_bins_count as f64 * (pr / cap);
    }

    // Integer division threshold: post_residual in [10, 30) band is a sweet spot
    // for typical mid-size arrivals.
    if post_residual >= 10 && post_residual < 30 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to ever fit a future item
    // (min item size is 1, but practically gaps below ~10 are hard to fill) are waste.
    let dead_threshold = next_item_size.max(10).min(20) as f64;
    if (post_residual as f64) < dead_threshold {
        score += 2.5 * (dead_threshold - post_residual as f64);
    }

    // Reward tight fits (small post_residual) non-linearly.
    let tight = (post_residual as f64) / bin_capacity as f64;
    score += 12.0 * tight * tight;

    // Penalize bins whose residual is much larger than needed (wasteful packing).
    if bin_residual > item_size {
        let slack = (bin_residual - item_size) as f64;
        score += 0.05 * slack;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // Open-bin pressure: when many bins are open, prefer filling existing ones
    // over creating new bins; the new-bin candidate gets penalized via its full residual,
    // but add extra pressure proportional to open bins count.
    score += 0.15 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Lookahead: if the next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 6.0;
    }
    // If next item would be stranded by this placement, penalize slightly.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 1.5;
    }

    // Mild progress adaptation: early in the stream keep bins flexible.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 2.0 * progress * (1.0 - tight);

    // New-bin candidate normalization: an empty bin has post_residual == bin_capacity;
    // keep it competitive only when no good fit exists.
    if bin_residual == bin_capacity {
        score = 55.0 + 0.3 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 100.0; // no open bin fits: must open a new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual (tight fits).
    // Strong non-linear bonus when the leftover space is exactly usable by the next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 40.0 / (1.0 + diff * 0.15);
        // Exact match jackpot: next item perfectly fills the bin.
        if post_residual == next_item_size {
            score -= 30.0;
        }
        // Penalize leaving a residual slightly too small for the next item (dead space).
        if post_residual > 0 && post_residual < next_item_size {
            score += 0.4 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: just minimize leftover.
        score += 0.0;
    }

    // Reward filling a bin completely (waste elimination).
    if post_residual == 0 {
        score -= 50.0;
    }

    // Relative-to-mean coupling: bins with residuals below the mean are "ahead";
    // prefer deepening those, penalize dumping into already-empty bins.
    score += 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // the item is large relative to capacity or no open bin fits well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        // Base penalty for opening a new bin.
        score += 35.0;
        // Large items justify fresh bins; tiny items do not.
        score -= 30.0 * fill_ratio * fill_ratio;
        // Early in the stream, having few bins open makes new bins cheaper.
        score -= 10.0 * (1.0 - progress);
        // If many bins are already open and mean residual is high, reuse them.
        score += 0.3 * open_bins_count as f64 * (mean_residual / bin_capacity as f64);
    }

    // Mild penalty for very small leftover slivers that nothing (min size 1) can use.
    if post_residual > 0 && post_residual < 5 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let next = next_item_size as f64;

    // Base: prefer tight fits (low post_residual).
    let mut score = post;

    // Reward near-perfect fits disproportionately.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Dead-space penalty: residuals too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward strongly.
    if next > 0.0 && next <= post {
        let gap = post - next;
        if gap == 0.0 {
            score -= 30.0;
        } else if gap <= 5.0 {
            score -= 12.0;
        } else {
            score -= 6.0 * (1.0 - gap / cap);
        }
    }
    // Penalize if next item would be blocked by this placement while another bin could host it.
    if next > post && next > 0.0 && fitting_bins_count > 1 {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when current fit is poor or no real bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let fit_quality = 1.0 - item / cap; // higher = worse fit in empty bin
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowded = (open_bins_count as f64).min(10.0) / 10.0;
        // Prefer new bin when fit is wasteful, late in stream, bins crowded, or no alternative.
        let bonus = 18.0 * fit_quality + 20.0 * pressure + 15.0 * progress * fit_quality + 10.0 * crowded * fit_quality;
        score = 30.0 + post - bonus;
        // Never open a new bin when the item fits perfectly somewhere with tiny waste.
        if fitting_bins_count >= 1 && post >= 0.0 && item / cap >= 0.9 {
            score += 25.0;
        }
    }

    // Global residual coupling: prefer bins whose residual deviates from mean
    // (consolidate space, keep some bins tight and some loose).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Slight preference for emptier bins early (flexibility), tighter bins late.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let fill_ratio = 1.0 - bin_residual as f64 / cap;
    score += (0.5 - progress) * fill_ratio * 10.0;

    // Mild penalty for spreading across many open bins.
    score += 0.3 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, prefer filling bins tightly (waste penalized quadratically);
    // later, residual waste matters even more as options shrink.
    let waste_norm = pr / cap;
    let progress_coupling = waste_norm * waste_norm * (1.0 + 3.0 * progress);
    score += 40.0 * progress_coupling;

    // Reward near-perfect fits with a smooth saturating bonus.
    let fit_quality = 1.0 - waste_norm;
    score -= 15.0 * fit_quality * fit_quality * fit_quality;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 + 20.0 * progress;
    }

    // Lookahead: bonus if next item fits the post-residual (smooth coupling).
    if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap >= 0.0 {
            let tight = 1.0 - (gap / cap);
            score -= 12.0 * tight * tight;
        } else {
            score += 6.0 * (-gap / cap);
        }
    }

    // Slight preference for bins with below-average residual (consolidate emptier space).
    score += 0.15 * (mean_residual - pr);

    // New empty bin candidate: penalize mildly so it's chosen only when open bins fit poorly,
    // with the penalty easing late in the stream.
    if bin_residual == bin_capacity {
        score += 30.0 * (1.0 - 0.5 * progress) + 0.05 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
