pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // later are heavily penalized. Anything below the minimum item size (1)
    // is pure waste; small gaps (<= 20) are likely dead space.
    if post_residual == 0 {
        score -= 50.0; // perfect fit
    } else if post_residual < 10 {
        score += 30.0; // unusable sliver
    } else if post_residual <= 20 {
        score += 10.0; // probably dead space
    }

    // Reward a good fit: small relative waste.
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    score += 20.0 * waste_ratio;

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // strongly reward; if next item nearly fits, mild reward.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            score -= 15.0 / (1.0 + gap);
        } else {
            score += 5.0;
        }
    }

    // Open-bin pressure: discourage spreading across many open bins unless
    // the fit is excellent; encourage using existing bins when few are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let bin_pressure = open_bins_count as f64 * (1.0 + progress);
    score += 0.8 * bin_pressure * waste_ratio;

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when the item is large relative to a
    // fresh bin and open bins are numerous / residuals are poor.
    if bin_residual == bin_capacity {
        let mean_gap = mean_residual - score;
        let open_factor = (open_bins_count as f64 / 10.0).min(2.0);
        score += 40.0 - open_factor * 10.0;
        // penalize opening a new bin early in the stream
        score += (1.0 - progress) * 15.0;
        let _ = mean_gap;
    }

    // Mild tie-breaker: prefer bins whose residual is below the mean
    // (concentrate filling into tighter bins).
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward residual that exactly fits next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            // residual can host next item: mild reward proportional to tightness
            let tightness = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 50.0 * tightness;
        } else {
            // dead space relative to next item: penalize
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Compare residual to mean residual across open bins: prefer bins tighter than average
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: strong reward to use it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: make it attractive only when item is large relative to capacity
    if bin_residual == bin_capacity {
        score = item_size as f64 * 2.0 + 50.0;
        if fitting_bins_count <= 1 {
            score -= 100.0;
        }
    }

    // Late-stream consolidation: favor filling existing bins as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: reward small post_residual non-linearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * fit_ratio * fit_ratio;

    // Penalize creating dead space that cannot fit the next item (lookahead coupling).
    if next_item_size > 0 {
        if post_residual < next_item_size && post_residual > 0 {
            score += 12.0 * (1.0 - (next_item_size - post_residual) as f64 / 100.0);
        }
        // Reward leaving exactly enough room for the next item.
        if post_residual == next_item_size {
            score -= 15.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless existing fits are bad.
    if bin_residual == bin_capacity {
        score += 40.0;
        // Early in the stream, opening bins is cheaper.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * (1.0 - progress);
        // If many bins are open with large mean residual, discourage new bins.
        score += 0.15 * open_bins_count as f64;
        if mean_residual > item_size as f64 {
            score += 10.0;
        }
    }

    // Prefer bins whose residual deviates favorably from the mean (fill emptier bins).
    let dev = bin_residual as f64 - mean_residual;
    score -= 0.08 * dev;

    // Slight time-horizon modulation: later in stream, squeeze harder.
    let horizon = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 8.0 * horizon * (1.0 - fit_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: penalize leftover space, but with diminishing returns (quadratic coupling)
    let mut score = pr / cap;
    score += 0.8 * (pr / cap) * (pr / cap);

    // Smooth non-linear coupling with stream progress: early on, tolerate slack;
    // late in the stream, aggressively minimize post_residual.
    let progress_weight = 0.5 + 1.5 * progress * progress;
    score *= progress_weight;

    // Reward tight fits via smooth sigmoid-like term on fill ratio
    let fill = item_size as f64 / cap;
    score -= 0.6 * fill * (1.0 - fill) * 4.0;

    // Lookahead coupling: if next item fits in post_residual, reward this bin
    if next_item_size > 0 {
        let fits_next = (post_residual as u64 >= next_item_size as u64) as f64;
        let ratio = next_item_size as f64 / pr.max(1.0);
        score -= fits_next * (0.7 - 0.4 * ratio) * (1.0 - 0.5 * progress);
    }

    // Last-chance bonus: only one bin fits -> strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 1.2;
    }

    // Penalize opening a new bin when reasonable alternatives exist,
    // but relax this penalty late in the stream.
    if bin_residual == bin_capacity {
        let alt = fitting_bins_count as f64;
        score += (0.4 + 0.3 * alt) * (1.2 - 0.6 * progress);
    }

    // Mild coupling with mean residual: prefer bins near the mean (balance)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 0.15 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues mod 10 as "dead space classes".
    // Residuals near multiples of 10 are more reusable by typical item sizes.
    let post = post_residual as i64;
    let residue = post % 10;
    let dead_penalty = if post == 0 {
        -30.0 // perfect fit: strongly favored
    } else if residue == 0 {
        -12.0 // class-0 residual: highly reusable
    } else if residue <= 3 {
        8.0 * (4 - residue) as f64 // small dead space, hard to fill
    } else if residue >= 7 {
        -6.0 * (residue - 6) as f64 // close to next harmonic class, likely fillable
    } else {
        0.0
    };
    score += dead_penalty;

    // Integer-division thresholds: post_residual bucketed by quarters of capacity.
    let quarter = bin_capacity / 4;
    if post_residual < quarter / 2 {
        score += 10.0; // tiny residual: near-dead bin
    } else if post_residual <= quarter {
        score += 2.0;
    } else if post_residual <= 2 * quarter {
        score -= 3.0; // half-full class: versatile
    }

    // Lookahead coupling: does post_residual fit the next item exactly or well?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0; // chains perfectly
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            let nres = slack % 10.0;
            score -= 8.0 - 0.5 * nres; // good chain, penalize awkward slack
        } else {
            score += 4.0; // next item won't fit here anyway
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin (unless post_residual is truly dead).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
        if post_residual >= 10 {
            score -= 5.0;
        }
    }

    // New-bin candidate handling: neutral baseline; only attractive when open bins
    // are fragmented (low mean residual relative to item) or many bins are open.
    if bin_residual == bin_capacity {
        score = 55.0 + open_bins_count as f64 * 0.5 - mean_residual * 0.3;
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 10.0; // reserve fresh bins for large upcoming items
        }
    }

    // Slight progression term: early in the stream, tolerate opening bins;
    // later, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 3.0 * (mean_residual / bin_capacity.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero gaps are nearly unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 15.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Reward leaving room for the lookahead item when possible.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 20.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; favor filling.
    let pressure = (open_bins_count as f64).ln() * 6.0;
    score += pressure * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: attractive when it avoids dead space the item would create elsewhere.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin, reduced when open-bin count is low or fit elsewhere is bad.
        score = 100.0 + pressure - (mean_residual / 10.0);
        if post_residual < 10 {
            score += 40.0; // don't open a bin for a near-perfect wedge
        }
        if fitting_bins_count == 1 {
            score += 120.0; // never outcompete the sole fitting bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near match: next item fits with small waste (<= 10 dead space).
    else if next_item_size > 0 && post_residual >= next_item_size && (post_residual - next_item_size) <= 10 {
        score -= 25.0 - (post_residual - next_item_size) as f64;
    }
    // Next item cannot fit here: penalize proportionally to leftover dead space.
    else if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // Reward tight fits relative to bin capacity (low post residual is good).
    score -= (bin_capacity - post_residual) as f64 * 0.2;

    // Relative to mean residual: bins with less-than-average residual are
    // preferred targets (consolidate), bins with large residual are deprioritized.
    score += (post_residual as f64 - mean_residual) * 0.35;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Brand-new empty bin candidate: only attractive when no good fit exists
    // (many fitting bins -> make new bin expensive).
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 55.0 + 10.0 * fitting_bins_count as f64;
        } else {
            score -= 20.0;
        }
    }

    // Early in the stream, allow slightly more freedom to open bins; late in the
    // stream, tighten packing to squeeze into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 8.0;

    // Many open bins: discourage spreading items across bins.
    if open_bins_count > 4 {
        score += 0.5 * (open_bins_count as f64 - 4.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize proportionally wasted capacity.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 30.0;

    // Penalize leaving small dead space (< 10) that few items can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Reward residual sizes that are common item sizes (multiples of 10).
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }

    // Lookahead: if the next item fits the post-residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
        // Perfect chaining: post residual exactly matches next item.
        if post_residual == next_item_size {
            score -= 15.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Dead space relative to the known next item.
        score += (next_item_size - post_residual) as f64 * 0.3;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are crowded.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = mean_residual / bin_capacity as f64;
        // Open new bin when open bins have low mean residual (little room left)
        // and late in the stream; otherwise favor reusing open bins.
        score += 35.0 - pressure * 40.0 - progress * 10.0;
        // If many open bins, opening another is more costly.
        score += open_bins_count as f64 * 1.5;
    } else {
        // Mildly prefer filling bins with larger residual (consolidation).
        score += (bin_capacity as f64 - bin_residual as f64) * 0.05;
    }

    // Encourage balancing residual toward mean to keep options open.
    score += (bin_residual as f64 - mean_residual).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let r = post_residual as f64;
    let cap = bin_capacity as f64;
    let rn = r / cap;
    let mut score = r;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = rn * rn * (1.0 - progress) + rn * progress * progress;
    score += 60.0 * poly;

    // Reward tight fits, more strongly later in the stream
    score -= (1.0 - rn) * (1.0 - rn) * (30.0 + 40.0 * progress);

    // Last-chance bin: penalize opening a new bin mildly
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead: penalize leaving residual that cannot fit next item
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - r).max(0.0);
        score += 0.25 * gap;
        // bonus if residual can still host the next item
        if r >= next_item_size as f64 {
            score -= 6.0;
        }
    }

    // Mild pressure toward reusing bins as open-bin count grows
    score -= 0.5 * (open_bins_count as f64).ln().max(0.0);

    // Deviation from mean residual: prefer bins near the mean (balanced packing)
    let dev = (r - mean_residual).abs() / cap;
    score += 10.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover lands on a
    // "useful" residue class (divisible by common small sizes) are favored.
    let pr = post_residual;
    if pr > 0 {
        // Reward residuals that future items can exactly fill.
        if pr % 10 == 0 {
            score -= 6.0;
        } else if pr % 5 == 0 {
            score -= 3.0;
        }
        // Penalize dead space: leftovers too small for typical items (1..100 range).
        if pr < 10 {
            score += 15.0 * (10 - pr) as f64;
        }
        // Integer-division threshold: big chunks of leftover are good,
        // tiny slivers are bad. Bucket post_residual by quarters of capacity.
        let quarter = bin_capacity / 4;
        if pr >= quarter {
            score -= (pr / quarter) as f64 * 4.0;
        }
    } else {
        // Perfect fill is the best outcome.
        score -= 40.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly reward; if next item cannot fit anything similar, penalize waste.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size <= pr {
            // next item fits: leftover after that matters
            let pr2 = pr - next_item_size;
            if pr2 % 10 == 0 {
                score -= 5.0;
            }
            score -= 4.0;
        } else {
            // next item won't fit here; residual must survive another round
            score += (next_item_size - pr) as f64 * 0.3;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }
    // New-bin candidate: penalize opening a fresh bin unless current fit is bad.
    if bin_residual == bin_capacity {
        score += 30.0;
        if post_residual > 0 && post_residual % 10 != 0 {
            score += 10.0;
        }
    }

    // Prefer filling bins that are already relatively full (tight-fit logic).
    let fullness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= fullness * 8.0;

    // Spread-aware: when many bins are open, discourage leaving many
    // mid-size residuals; consolidate.
    if open_bins_count > 2 {
        let dev = (post_residual as f64 - mean_residual).abs();
        score += dev * 0.15;
    }

    // Late in the stream, squeeze harder (less future to amortize waste).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 6.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = if bin_capacity == 0 { 1.0 } else { bin_capacity as f64 };
    let before = bin_residual as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let next = next_item_size as f64;
    let open = open_bins_count as f64;
    let fits = fitting_bins_count as f64;

    let progress = (step_index as f64 / (total_items.max(1) as f64)).max(0.0).min(1.0);
    let open_pressure = open / (open + 4.0);
    let mean_pressure = (mean_residual / cap).max(0.0).min(1.0);
    let is_new_bin = item_size > 0 && bin_residual == bin_capacity;

    let mut score = post;

    // Mild normalized waste penalty, stronger when many bins are already open.
    let post_fraction = (post / cap).max(0.0).min(1.0);
    score += 1.2 * post_fraction * (1.0 + open_pressure);

    // Reward dense placement of the current item inside the available residual.
    let fill_ratio = if before > 0.0 { (item / before).max(0.0).min(1.0) } else { 0.0 };
    score -= (0.6 + 1.2 * open_pressure) * fill_ratio;

    // Strong reward for closing a bin exactly.
    if post <= 0.0 {
        score -= 4.0 + 3.0 * open_pressure;
    }

    // Prefer using lower-residual open bins; this reduces fragmentation when many bins are open.
    if !is_new_bin {
        let small_bin_advantage = (((mean_residual - before) / cap).max(0.0)).min(1.0);
        score -= (0.7 + 2.2 * open_pressure) * small_bin_advantage;

        // Last existing chance before a new bin would be opened.
        if fitting_bins_count == 1 {
            score -= 1.5 + 2.0 * open_pressure;
        }
    }

    // Strict dead-space avoidance against the lookahead item.
    if next > 0.0 && post > 0.0 {
        if post < next {
            let deficit = (next - post) / next;
            let mut dead_penalty = (7.0 + 20.0 * deficit)
                * (1.0 + 0.55 * open_pressure)
                * (1.15 - 0.35 * mean_pressure)
                * (1.10 - 0.35 * progress);

            dead_penalty = dead_penalty.min(38.0);
            score += dead_penalty;
        } else {
            let slack = ((post - next) / cap).max(0.0).min(1.0);
            let alignment = 1.0 - slack;
            let next_fraction = (next / cap).max(0.0).min(1.0);

            score -= (0.8 + 2.5 * next_fraction) * alignment * (0.5 + 0.8 * open_pressure);

            // Perfect lookahead fit: the next item should close this bin exactly.
            if post == next {
                score -= 2.0 + 2.0 * open_pressure;
            }
        }
    }

    // Opening a new bin is penalized, especially when usable open bins already exist.
    if is_new_bin {
        let alternative_pressure = 1.0 / (1.0 + fits);
        let mut new_bin_penalty = (2.0 + 5.5 * open_pressure + 3.0 * alternative_pressure)
            * (0.8 + 0.8 * progress)
            * (0.75 + 0.5 * mean_pressure);

        new_bin_penalty = new_bin_penalty.min(18.0);
        score += new_bin_penalty;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
