pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tight fit reward: post residual relative to item size
    let fit_ratio = post_residual as f64 / (item_size as f64).max(1.0);
    score -= 12.0 * (-fit_ratio).exp();

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: does the next item fit into the post residual?
    if next_item_size > 0 {
        let next_fits = (post_residual >= next_item_size) as i32;
        let wasted = (post_residual as i32 - next_item_size as i32).max(0) as f64;
        score += 8.0 * (1.0 - next_fits as f64); // penalize blocking next item
        score -= 6.0 * (-wasted / 30.0).exp(); // reward snug room for next item
        // discourage leaving residual that is uselessly small for the next item
        if next_fits == 0 && post_residual < next_item_size {
            score += 4.0 * (post_residual as f64 / cap);
        }
    } else {
        // last item: minimize residual strictly
        score += 10.0 * (post_residual as f64 / cap);
    }

    // Last chance: this is the only bin that fits -> strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New bin candidate handling
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 55.0;
        // opening a new bin is more attractive when few open bins or late in stream
        let progress = step_index as f64 / (total_items as f64).max(1.0);
        score -= 15.0 * progress;
        // if existing open bins are fragmented (high mean residual spread), new bin is fine
        score -= 10.0 * (mean_residual / cap);
        // small items justify new bins more (less waste risk)
        score -= 0.3 * item_size as f64;
        // if many bins already fit the item, opening a new bin is wasteful
        if fitting_bins_count > 1 {
            score += 20.0;
        }
    }

    // Prefer fuller bins overall: penalize bins far below mean residual usage
    score += 0.15 * (mean_residual - post_residual as f64).max(0.0);

    // Global fragmentation pressure: when many bins open, consolidate
    score += 0.5 * open_bins_count as f64 * (post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: post residual, with smooth polynomial coupling to stream progress.
    // Late in the stream, residual space becomes more valuable (penalize waste more).
    let mut score = pr * (1.0 + 1.5 * progress * progress);

    // Non-linear penalty on large post-residuals (dead space) that grows quadratically.
    score += 20.0 * pr_norm * pr_norm * (0.5 + progress);

    // Reward tight fits: bonus that is strongest when post_residual is small.
    let tightness = 1.0 - pr_norm;
    score -= 15.0 * tightness * tightness * tightness;

    // Lookahead: if next item fits the post residual, reward this placement smoothly.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let fill = nx / pr.max(1.0);
            score -= 12.0 * fill * (1.0 - progress * 0.5);
        } else {
            // Next item cannot fit: penalize proportionally to the gap.
            score += 8.0 * ((nx - pr) / cap);
        }
    }

    // Last-chance bin: strongly reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - 0.3 * progress);
    }

    // Mean residual coupling: prefer bins deviating from the mean toward smaller residual
    // (pack tight bins first), with smooth quadratic term.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 10.0 * dev * dev - 6.0 * dev;

    // Penalize opening new bins when many bins are open and progress is low.
    if bin_residual == bin_capacity {
        score += 30.0 + 20.0 * (1.0 - progress) + 2.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: dead space that no item (min 1..10) can use
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item.max(1) * 5 {
        score -= 5.0; // tiny residuals are nearly perfect fits
    }

    // Dead-space penalty: residual below smallest plausible item is worthless
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Harmonic classes via integer division on post_residual
    let class = post_residual / 10; // decile class
    score += match class {
        0 => -8.0,   // 0..9 residual: near-full bin, good
        1 => -3.0,   // 10..19: fits small items well
        2 => 2.0,    // 20..29
        3 => 0.0,
        4 => 4.0,    // 40..49: awkward class
        5 => 1.0,
        6 => 6.0,    // 60..69: large dead space risk
        _ => 8.0,    // >70: bin barely used
    };

    // Coupling with next item: does next_item_size fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // lookahead fits: reward proportional to tightness
            let slack = post_residual - next_item_size;
            score -= 10.0 + (slack as f64).min(20.0) * 0.3;
        } else {
            // next item won't fit here: penalize leaving bad remainder
            score += (post_residual as f64) * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Many open bins: discourage spreading; prefer filling existing bins
    if open_bins_count > 4 {
        score -= (open_bins_count.min(20) as f64) * 0.5;
    }

    // Mean residual coupling: prefer bins below mean residual (fill emptier bins less)
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 2.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless current fits are terrible
    if bin_residual == bin_capacity {
        score += 30.0;
        // but if item is huge and lookahead also huge, opening may be wise
        if item_size >= 60 && next_item_size >= 60 {
            score -= 20.0;
        }
    }

    // Stream progression: early on, be picky (large penalty for poor fits); late, pack greedily
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * (post_residual as f64) * 0.2;

    // Modulo-5 harmonic bonus: residuals divisible by 5 align with common item sizes
    if post_residual % 5 == 0 && post_residual > 0 {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=9) are heavily penalized.
    if post_residual > 0 && post_residual <= 9 {
        score += 40.0 * (1.0 - post_residual as f64 / 10.0);
    }
    // Perfect fit is maximally rewarded.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward tight fits relative to bin capacity.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 15.0 * fill_ratio;

    // Open-bin pressure: discourage spreading across many bins.
    score += 2.0 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when the item barely fits nowhere tightly
    // or the item is large; otherwise penalize opening new bins.
    if bin_residual == bin_capacity {
        score += 55.0;
        // Large items justify fresh bins more readily.
        score -= 20.0 * fill_ratio;
        // Late in the stream, avoid opening bins for marginal gains.
        if total_items > 0 {
            let progress = step_index as f64 / total_items as f64;
            score += 10.0 * progress;
        }
        // If many bins can fit, opening a new bin is wasteful.
        score += 5.0 * fitting_bins_count as f64;
    }

    // Lookahead: if next item fits exactly into the post residual, reward this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 25.0;
    }
    // Penalize leaving a gap the next item cannot use.
    if next_item_size > post_residual && post_residual > 0 {
        score += 8.0;
    }

    // Mild alignment with mean residual: prefer bins tighter than average.
    score -= (mean_residual - post_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Base: penalize wasted residual, scaled by capacity
    score += (post_residual as f64 / bin_capacity as f64) * 20.0;

    // Aggressive 2-step lookahead: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 100.0; // perfect 2-chain
        } else if next_item_size < post_residual {
            let new_post = post_residual - next_item_size;
            // reward tight second fit, penalize large leftover after chain
            score -= 40.0 - (new_post as f64 * 0.6);
        } else {
            // next item cannot follow: dead space risk grows with post_residual
            score += (post_residual as f64 - next_item_size as f64).abs() * 0.3;
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score += (post_residual as f64 - mean_residual) * 0.5;

    // Last-chance bonus: only fitting bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fits are bad
    if bin_residual == bin_capacity {
        // attractive early, or when item is small relative to residuals
        score = 60.0 - (item_size as f64 * 0.5) + progress * 20.0;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 25.0;
        }
    }

    // Slight preference to fill nearly-full bins as stream progresses
    score -= (bin_residual as f64 / bin_capacity as f64) * progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic bonus for small leftover space
    let tightness = (post_residual as f64 / bin_capacity as f64).powi(2);
    score -= 30.0 * tightness;

    // Penalize dead space that cannot fit a plausible future item
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // unusable sliver
    }

    // Lookahead coupling: reward bins whose post-residual fits the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 8.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    } else {
        // Last item: just fill as much as possible
        score -= 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Fragmentation pressure: when many bins are open, prefer filling the emptiest
    let rel = bin_residual as f64 / bin_capacity as f64;
    score += 5.0 * rel * (open_bins_count as f64 / (open_bins_count as f64 + 4.0));

    // Global residual context: bin much emptier than average is a good target
    score -= 4.0 * (mean_residual - bin_residual as f64) / bin_capacity as f64;

    // Time horizon: late in the stream, be conservative with new bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses
        score += 18.0 + 25.0 * progress;
    } else {
        score -= 6.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post-residual with non-linear polynomial shaping
    let mut score = pr
        + 40.0 * norm_pr * norm_pr          // penalize large leftover space quadratically
        + 30.0 * progress * norm_pr * norm_pr;

    // Reward tight fits via cubic coupling with progress
    let tightness = 1.0 - norm_pr;
    score -= 25.0 * tightness * tightness * tightness * (0.5 + progress);

    // Last-chance bonus: strongly favor this bin if it's the only fitting one
    if fitting_bins_count == 1 {
        score -= 60.0 + 40.0 * progress;
    }

    // Lookahead: if next item fits in post_residual, reward; else penalize
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            let slack_after_next = pr - nx;
            score -= 15.0 * (1.0 - slack_after_next / cap);
        } else {
            score += 10.0 + 20.0 * progress;
        }
    }

    // Mean-residual coupling: avoid bins far from the fleet mean
    score += 8.0 * ((pr - mean_residual) / cap).abs();

    // Prefer consolidating into fewer bins as stream progresses
    score += 3.0 * progress * (open_bins_count as f64).sqrt();

    // New-bin candidate: penalize opening a new bin unless item is large relative to residual norm
    if bin_residual == bin_capacity {
        score += 55.0 + 45.0 * progress - 30.0 * (item_size as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: quantize dead space into capacity fractions
    let frac = post_residual as f64 / bin_capacity as f64;

    // Penalize residuals that fall into "dead zones" where few item sizes (1..100) can fit.
    // Classes: (0,10] nearly perfect; (10,50] awkward; (50,100] still usable.
    if post_residual == 0 {
        score -= 40.0; // perfect fit: strongly reward
    } else if post_residual <= 10 {
        score -= 25.0 * (1.0 - frac);
    } else if post_residual <= 50 {
        // awkward class: penalize proportionally, worse near the middle
        score += 12.0 * (1.0 - (2.0 * frac - 0.1).abs());
    }

    // Modulo-class logic on post_residual: residuals divisible by 10 pair well
    // with items drawn from typical granularities.
    let m = post_residual % 10;
    score -= match m {
        0 => 6.0,
        1 | 9 => 1.0,
        5 => 3.0,
        _ => -1.5, // odd remainders slightly worse
    };

    // Lookahead: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = post_residual - next_item_size;
        score -= 20.0 - slack as f64 * 0.3;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item can't follow here: mild penalty unless this bin gets emptied
        score += 4.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 18.0;
    }

    // Many open bins: encourage consolidation into tighter bins.
    score += (open_bins_count as f64).ln() * 1.2;

    // Early in the stream, prefer keeping residuals balanced vs mean.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (mean_residual - post_residual as f64) * 0.08 * (1.0 - progress);

    // New-bin candidate: only attractive when current residuals are badly fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - 50.0).abs() / 50.0;
        score = 30.0 + fragmentation * 25.0 - (open_bins_count as f64) * 0.5;
        if fitting_bins_count <= 1 {
            score -= 10.0; // no good alternative: opening new bin is fine
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        let dead = if post_residual <= 25 {
            // tiny gap: almost certainly unusable dead space
            (26.0 - post_residual as f64) * 8.0
        } else if post_residual <= 45 {
            (46.0 - post_residual as f64) * 2.0
        } else {
            0.0
        };
        score += dead;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 120.0;
    } else if post_residual <= 10 {
        score -= 40.0;
    }

    // Favor bins whose residual closely matches the item (tight packing).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += tightness * 30.0;

    // Open-bins pressure: when many bins are open, discourage spreading;
    // prefer filling existing bins over opening new ones.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (open_bins_count as f64).ln().max(0.0) * 4.0 * (0.5 + progress);

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: only attractive when the item barely fits anywhere
    // or would create dead space in every open bin.
    if bin_residual == bin_capacity {
        score += 55.0;
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
        // If next item is large, a fresh bin may be valuable.
        if next_item_size > 60 && item_size <= 40 {
            score -= 25.0;
        }
    }

    // Lookahead: if this placement leaves exactly the next item's size, reward it.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 70.0;
    } else if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 10 {
        score -= 30.0;
    }

    // Slight preference for bins with residual below the mean (fill emptier-first
    // bins less; keep high-residual bins for large future items).
    if (bin_residual as f64) > mean_residual {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

