    }

    // Compare against mean residual: prefer bins with less residual than average
    // (tighter bins) to keep wide-open bins available for larger future items.
    score += (post_residual as f64 - mean_residual) * 0.5;

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // Penalize opening a new bin when open bins can fit the item.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 40.0;
    }

    // Late in the stream, prefer closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (low post residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
