    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 {
        let dead = post_residual as f64;
        if dead < 10.0 {
            score += 25.0; // unusable sliver
        } else {
            // reward residuals that can still host mid-size items
            score -= 4.0 * (dead / 100.0).ln().max(0.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }
    // Many fitting bins: mild penalty to encourage consolidation elsewhere.
    if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 22.0;
        } else if post_residual >= next_item_size {
            score -= 8.0 * (post_residual as f64 / next_item_size.max(1) as f64).min(2.0);
        } else {
            // next item won't fit here; slight penalty proportional to waste
            score += 3.0 * (1.0 - post_residual as f64 / next_item_size.max(1) as f64).min(1.0);
        }
    }

    // Global state coupling: when mean residual is high, prefer filling existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 6.0 * (mean_residual / bin_capacity as f64) * (0.5 + progress);

    // Time horizon: late in the stream, consolidate aggressively.
    score += 10.0 * progress * (open_bins_count as f64 / (1.0 + mean_residual / 20.0)).ln().max(0.0);

    // New-bin candidate handling: only attractive when item is huge relative to
    // all residuals or open bins are scarce/fragmented.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let big_item = item_size as f64 / bin_capacity as f64;
        score -= 35.0 * desperation;
        // allow new bin for very large items when existing fits are loose
        if fitting_bins_count > 0 {
            score += 20.0 * big_item;
        }
        score -= 5.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
