    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let x = pr / cap; // normalized post residual in [0,1]
    let g = 1.0 - progress; // remaining fraction of stream

    // Base: penalize residual, with quadratic and cubic smooth terms.
    let mut score = x * (1.0 + 0.6 * x + 0.9 * x * x);

    // Coupling: waste matters more early (long future to exploit tight fits),
    // less late; smooth interaction term.
    score += 2.0 * g * (1.0 - x) * x;

    // Dead-space penalty: residual too small for any plausible item (smooth soft threshold).
    let dead = (1.0 - (x / 0.09).tanh()) * 0.5; // ~1 when x near 0, ->0 as x grows
    score += 6.0 * dead * (0.5 + 0.5 * g);

    // Last-chance bonus: strongly favor using a bin when few fitting bins remain.
    if fitting_bins_count <= 1 {
        score -= 3.5;
    } else {
        score -= 1.2 / fitting_bins_count as f64;
    }

    // Lookahead: reward if next item fits in post residual (smooth).
    if next_item_size > 0 {
        let fits = (next_item_size as f64 <= pr) as i32 as f64;
        let tightness = 1.0 - ((next_item_size as f64 - pr).abs() / cap).min(1.0);
        score -= 1.5 * fits * (0.4 + 0.6 * tightness) * (0.5 + 0.5 * g);
    }

    // Mild penalty for spreading across many open bins vs consolidation.
    score += 0.05 * (open_bins_count as f64).ln().max(0.0) * (1.0 - x);

    // Slight preference for bins near mean residual (balance residuals smoothly).
    score += 0.3 * ((pr - mean_residual) / cap).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space into capacity fractions.
    let frac = post_residual as f64 / cap;
    // Penalize "dead zones": residuals that are too small to fit typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Reward residuals in useful harmonic bands (can host mid-size items later).
    let band = (post_residual / 10) % 10; // integer-division harmonic class
    match band {
        0 => score -= 4.0,          // residual ~0-9 or exact multiples: mostly dead or perfect
        1 => score += 2.0,          // 10-19: awkward sliver
        2 => score -= 1.0,          // 20-29: usable
        3 => score += 0.5,
        4 => score -= 3.0,          // 40-49: hosts half-capacity items
        5 => score -= 5.0,          // 50-59: prime slot
        6 => score -= 2.0,
        7 => score += 1.0,
        8 => score -= 6.0,          // 80-89: near-full bin, excellent closure
        _ => score -= 1.0,
    }

    // Exact-fill reward: closing a bin perfectly is ideal.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - slack / cap);
        if post_residual == next_item_size {
            score -= 30.0; // chained perfect fit
        }
    } else if next_item_size > post_residual {
        score += 3.0; // next item won't fit here anyway; mild penalty
    }

    // Last-chance logic: if this is the only fitting bin, prefer using it over new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin gets a baseline penalty so we only
    // open new bins when open bins have truly bad fits.
    if bin_residual == bin_capacity {
        score += 20.0 + 0.05 * open_bins_count as f64;
        // But if current item is small and stream is early, opening fresh bin is fine.
        if item_size <= 30 && (step_index as f64) < 0.5 * total_items as f64 {
            score -= 10.0;
        }
    }

    // Mean-residual coupling: if this bin's residual is far below mean, it's tight — prefer it.
    let residual_gap = mean_residual - bin_residual as f64;
    score += 0.3 * residual_gap;

    // Modulo harmonic tie-break on item_size classes.
    let item_class = item_size % 20;
    if item_class == 0 {
        score -= 2.0; // round-number items pack predictably
    }

    // Mild progression pressure: later in stream, prefer closing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * (1.0 - frac);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: extremely desirable.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: penalize small unusable gaps.
    if post_residual > 0 && post_residual <= 10 {
        score += 500.0;
    } else if post_residual > 10 && post_residual <= 20 {
        score += 120.0;
    } else if post_residual > 20 && post_residual <= 40 {
        score += 30.0;
    }

    // If next item fits exactly into the post residual, reward heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 800.0;
        } else if slack <= 10 {
            score -= 150.0;
        } else {
            score -= 40.0;
        }
    }
    // Next item cannot use the gap: penalize proportionally.
    if next_item_size > post_residual && post_residual > 0 {
        score += 60.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // Open bins pressure: with many open bins, discourage new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize by pressure and by mean residual waste.
        score += 150.0 + pressure * 10.0 + mean_residual * 2.0;
    } else {
        // Slight preference for tighter (smaller residual) bins.
        score += (bin_residual as f64 - mean_residual) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer exact or near-exact fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    } else if post_residual <= 15 {
        score -= 100.0;
    }

    // 2-step lookahead: reward bins whose post residual matches the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 80.0 * (1.0 - gap / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item won't fit here: penalize dead space creation.
        score += 40.0;
    }

    // Relative-to-mean coupling: bins with residual near mean are natural targets.
    let diff = post_residual as f64 - mean_residual;
    score += 0.5 * diff;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Penalize opening a new bin when decent open bins exist, unless early stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 50.0 + 30.0 * (1.0 - progress);
        if open_bins_count == 0 {
            score -= 200.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize large dead space relative to typical next-item needs.
    if next_item_size > 0 {
        if (post_residual as u32) < next_item_size {
            score += (next_item_size - post_residual as u32) as f64 * 0.6;
        } else {
            score -= 2.0; // room for the lookahead item: reward
        }
        // Perfect fit for the next item: strong reward
        if post_residual as u32 == next_item_size {
            score -= 8.0;
        }
    }

    // Reward tight fits (small post-residual) nonlinearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * tightness * 10.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Many open bins: discourage spreading; few bins: mild encouragement to fill.
    if open_bins_count > 4 {
        score += (open_bins_count as f64).ln() * 1.5;
    }

    // Time horizon: late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 3.0;

    // Penalize bins whose residual deviates far above the mean (hoarding space).
    let dev = bin_residual as f64 - mean_residual;
    if dev > 0.0 {
        score += dev * 0.05;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 0.0 } else { 12.0 };
        let bad_lookahead = if next_item_size > 0 && post_residual as u32 >= next_item_size { -4.0 } else { 0.0 };
        score += 6.0 + desperation + bad_lookahead;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let mut score = pr;

    // Non-linear polynomial penalty on wasted residual, coupled with progress.
    let x = pr / cap;
    score += 40.0 * x * x * (0.5 + progress);

    // Reward tight fits (small post-residual) with a smooth quadratic bonus.
    score -= 30.0 * (1.0 - x) * (1.0 - x) * (0.5 + 0.5 * progress);

    // Lookahead: penalize if the next item cannot use this bin's residual.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx > pr as f64 {
            score += 12.0 * (nx - pr) / cap;
        } else {
            score -= 8.0 * (1.0 - (nx / pr.max(1.0) as f64).abs());
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Mild preference for spreading load when many bins are open.
    score += 0.05 * open_bins_count as f64 * x;

    // New-bin candidate: make it attractive only when no open bin fits well.
    if bin_residual == bin_capacity {
        score = cap - pr + 35.0 * (1.0 - progress);
        if fitting_bins_count == 1 {
            score += 60.0; // discourage abandoning the only fitting bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: prefer residuals in "useful" classes
    // (divisible into common small item sizes like 10/20/25/50).
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Perfect fit: strongly reward zero residual.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Harmonic class bonus: residual exactly divisible by small units is reusable.
        let mut harmonic_bonus = 0.0;
        for unit in [10u32, 20, 25, 50] {
            if post_residual % unit == 0 {
                harmonic_bonus += 8.0 * (unit as f64 / 10.0);
            }
        }
        // Small residual (< 10) is dead space: penalize softly; large residual is fine.
        if post_residual < 10 {
            score += 15.0;
        }
        score -= harmonic_bonus;

        // Coupling with lookahead: if next item fits exactly into post_residual, big reward.
        if next_item_size > 0 {
            if next_item_size == post_residual {
                score -= 500.0;
            } else if next_item_size < post_residual {
                let nxt = next_item_size as f64;
                // Harmonic fraction: how well the next item divides the post residual
                let frac = pr / nxt;
                if frac.fract() == 0.0 && frac >= 2.0 {
                    score -= 20.0;
                }
                score -= 10.0 * (nxt / pr);
            }
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible (huge dead space).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize slightly so we prefer reusing bins with decent fits,
    // but allow opening a new bin when all fits would leave big dead space.
    if bin_residual == bin_capacity {
        score += 30.0;
        // If next item is large and current item is small, fresh bin is attractive
        if next_item_size >= item_size {
            score -= 10.0;
        }
    }

    // Tightness reward: filling most of the bin is good.
    score -= 25.0 * (item_size as f64 / cap);

    // Late in the stream, be more aggressive about consolidating (prefer fullest bins).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (bin_residual as f64 / cap);

    // Prefer bins below mean residual slightly (balance-aware tie-break).
    score += 0.05 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small to hold even the
    // smallest plausible item are pure waste — penalize them heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 6.0;
    }
    // Mid-range gaps (10..30) are only usable by small items; mild penalty.
    if post_residual >= 10 && post_residual < 30 {
        score += (30 - post_residual) as f64 * 1.2;
    }

    // Reward tight fits (small post_residual) proportionally.
    score -= (bin_capacity - post_residual) as f64 * 0.35;

    // Last-chance bin: if this is the only bin that fits, strongly favor using
    // it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones;
    // with few open bins, opening a new bin is cheaper.
    let pressure = open_bins_count as f64 / 8.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline cost plus pressure; lookahead may justify.
        score = 45.0 + pressure * 10.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            let pair_waste = (bin_capacity as f64 - item_size as f64 - next_item_size as f64).max(0.0);
            score += pair_waste * 0.5;
        }
    } else {
        // Filling an existing bin reduces open-bin pressure slightly.
        score -= pressure * 3.0;
        // Lookahead: if the next item fits exactly in the post-residual, reward.
        if next_item_size > 0 && next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size > 0 && next_item_size > post_residual {
            // Next item won't fit here; dead space is locked in — penalize.
            score += (post_residual as f64) * 0.4;
        }
        // Deviation from mean residual: prefer bins whose residual is close to
        // the mean to keep the open-bin pool homogeneous.
        score += (bin_residual as f64 - mean_residual).abs() * 0.15;
    }

    // Slight late-stream tightening: as the stream progresses, waste matters more.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score *= 1.0 + 0.2 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead matching.
    if next_item_size > 0 {
        // Perfect match: post_residual exactly equals the next item size.
        if post_residual == next_item_size {
            score -= 60.0;
        }
        // Near match: next item would fit with little waste.
        else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - slack / bin_capacity as f64);
        }
        // Next item does NOT fit: post_residual becomes dead space unless it
        // is large enough to still be useful; penalize proportionally.
        else {
            let waste = post_residual as f64;
            score += 12.0 + 18.0 * (waste / bin_capacity as f64);
        }
    } else {
        // Last item: just prefer tightest fit.
        score -= 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Relative-to-mean coupling: bins with residual far above the mean are
    // "richer" targets; slight bonus for using them when fit is decent.
    if post_residual as f64 <= mean_residual {
        score -= 6.0;
    } else {
        score += 3.0 * ((post_residual as f64 - mean_residual) / bin_capacity as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when existing bins are very
    // full (tiny residuals) or the item barely fits anywhere.
    if bin_residual == bin_capacity {
        let crowded = mean_residual < 25.0 && open_bins_count > 0;
        let desperate = fitting_bins_count == 0 || (fitting_bins_count == 1 && bin_residual - item_size < 5);
        if crowded || desperate {
            score -= 20.0;
        } else {
            score += 35.0 + 0.5 * open_bins_count as f64;
        }
    }

    // Penalize leaving tiny unusable slivers (<10) unless they match the
    // next item exactly.
    if post_residual > 0 && post_residual < 10 && post_residual != next_item_size {
        score += 15.0;
    }

    // Mild stream-progression pressure: early on, keep bins consolidated.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 4.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly penalize small unusable dead space; larger post-residuals are more reusable.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: avoid opening a new bin if this one fits well.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Lookahead: reward leaving room for the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // New-bin candidate logic: opening a fresh bin is attractive only when the
    // item is large and no open bin offers a good fit.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fit_tightness = item_size as f64 / bin_capacity as f64;
        // Penalize new bins mildly; the penalty shrinks when the item is big
        // or many bins are already open with poor residuals.
        let mut penalty = 20.0 - 15.0 * fit_tightness;
        // Late in the stream, avoid spawning bins with tiny leftovers.
        if post_residual > 0 && post_residual < 10 {
            penalty += 30.0;
        }
        // If the mean residual across open bins is already small, prefer new bin.
        if mean_residual < item_size as f64 * 0.5 {
            penalty -= 12.0;
        }
        // Early stream: consolidation is cheap, new bins are costlier.
        penalty += 10.0 * (1.0 - progress);
        score += penalty;
    } else {
        // Prefer bins whose residual is close to what we consume (tight packing).
        let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
        score += 5.0 * tightness;
        // Slight preference for bins below mean residual (fill the emptier ones? no —
        // fill the tighter ones first to preserve large residuals for big items).
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
    }

    // Time-horizon coupling: as the stream nears its end, prioritize closing out bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 6.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let residual_norm = post / cap;

    // Smooth non-linear coupling of post_residual with stream progress:
    // early on, waste matters less; later, tight packing is rewarded more.
    let progress_warp = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    let mut score = post * (1.0 + 1.5 * progress_warp);

    // Non-linear penalty on very small dead space (unusable slivers),
    // stronger as the stream progresses.
    let dead = (cap * 0.2 - post).max(0.0) / cap;
    score += 20.0 * dead * dead * (0.5 + progress_warp);

    // Reward excellent fits (low post residual) with smooth inverse coupling.
    let fit_quality = 1.0 - residual_norm;
    score -= 15.0 * fit_quality * fit_quality * item_size as f64 / cap;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress_warp;
    }

    // Lookahead: if the next item fits the post residual, reward this placement;
    // smooth interaction with progress.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let slack = 1.0 - (post - nxt) / cap;
            score -= 12.0 * slack * slack * (0.5 + progress_warp);
        } else {
            score += 6.0 * (nxt - post) / cap;
        }
    }

    // Mild preference for fuller bins relative to fleet mean residual,
    // with smooth saturation.
    let mean_gap = (mean_residual - post) / cap;
    score -= 8.0 * mean_gap / (1.0 + mean_gap.abs());

    // Slight penalty for proliferating bins early in the stream.
    score += (open_bins_count as f64).ln().max(0.0) * (1.0 - progress_warp);

    // New-bin candidate: make an empty bin moderately attractive only when
    // nothing else fits well; discourage opening new bins when progress is high
    // and fits exist.
    if bin_residual == bin_capacity {
        score = cap * (1.2 - 0.4 * progress_warp) + 10.0 * (1.0 - fit_quality);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class: classify post_residual into coarse residue classes (mod 10)
    // Small residues in {1..9} are "dead zones" — hard to fill later.
    let cls = (post_residual % 10) as f64;
    if post_residual > 0 {
        // penalize awkward small leftover amounts
        if cls >= 1.0 && cls <= 4.0 {
            score += 8.0 - 2.0 * cls; // dead-space penalty
        } else if cls == 0.0 {
            score -= 5.0; // perfectly divisible residual is attractive
        } else {
            score -= 1.0; // moderately reusable
        }
    } else {
        // perfect fit: strong reward
        score -= 40.0;
    }

    // Integer-division thresholds on post_residual: very small leftovers are wasteful
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 25.0;
        } else if gap < 5 {
            score -= 10.0;
        } else {
            score -= 4.0;
        }
    } else if next_item_size > post_residual {
        // next item won't fit here; penalize leaving a residual that nothing can use
        score += 3.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Prefer fuller bins among many open bins (best-fit style tilt)
    let fill_frac = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 6.0 * fill_frac;

    // New-bin candidate handling: empty bin gets baseline cost so it's chosen
    // only when no open bin offers a good fit.
    if bin_residual == bin_capacity {
        score += 10.0 + 0.02 * (open_bins_count as f64);
        // if stream is early, opening bins is cheap
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 5.0 * (1.0 - progress);
    }

    // Slight preference to balance against mean residual: avoid bins far from mean
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Tie-break: prefer earlier (more filled) bins subtly via residual itself
    score += 0.01 * (bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // (below the minimum plausible item size) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Perfect fit: strongly reward.
    if post_residual == 0 {
        score -= 100.0;
    }
    // Reward residual sizes that can still accommodate typical items.
    if post_residual >= 10 {
        score -= 8.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> prefer consolidating into existing
    // bins rather than opening new ones.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to open bins count.
        score += (open_bins_count as f64) * 12.0;
        // Allow new bins early in the stream when few bins exist.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= (1.0 - progress) * 10.0;
        // Discourage new bin if next item could share residual with an existing bin.
        if next_item_size > 0 && next_item_size <= bin_residual - item_size {
            score += 20.0;
        }
    } else {
        // Existing bin: slight reward for keeping bin count low.
        score -= 5.0;
    }

    // Prefer bins whose residual is close to the item (tight fit) relative to mean.
    let tightness = (bin_residual as f64 - item_size as f64);
    if tightness < mean_residual {
        score -= 4.0;
    }

    // Lookahead: if next item fits exactly in the post residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    }
    // Penalize if post residual is smaller than next item but nonzero (wasted gap).
    if next_item_size > post_residual && post_residual > 0 && next_item_size > 0 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Penalize dead space that cannot host the next item.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        let deadness = (next_item_size - post_residual) as f64 / bin_capacity as f64;
        score += 25.0 + 50.0 * deadness;
    }

    // Favor bins whose residual is tight relative to the mean (best-fit coupling).
    score += 0.15 * (mean_residual - bin_residual as f64);

    // Last-chance bonus: only one bin fits; avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Slight preference to keep many bins consolidated early vs late in stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when current bin is a poor fit
    // (large leftover after placement) or nothing fits well.
    if bin_residual == bin_capacity {
        let poor_fit = (post_residual as f64) / bin_capacity as f64;
        score = 55.0 + 40.0 * (1.0 - poor_fit);
        if next_item_size > 0 && post_residual >= next_item_size {
            score += 10.0;
        }
        if fitting_bins_count <= 1 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on, prefer filling bins tightly (penalize large post_residual quadratically);
    // late in the stream, dead space matters more, so amplify the penalty.
    let poly = norm_pr * norm_pr * (1.0 + 2.0 * progress) * cap;
    score += 0.35 * poly;

    // Smooth interaction: post_residual vs mean residual — reward bins below mean residual
    // (tighter than average), penalize bins far above it, with a cubic coupling.
    let mr = mean_residual.max(0.0);
    let diff = (pr - mr) / cap;
    score += 12.0 * diff * diff * diff * cap;

    // Lookahead coupling: if next item fits the post residual exactly-ish, reward;
    // smooth gaussian-like term instead of hard threshold.
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let gap = (pr - ns) / cap;
        let fit_bonus = (-gap * gap * 40.0).exp();
        score -= 8.0 * fit_bonus * (0.5 + progress);
        // penalize post residual that is too small for the next item (wasted capacity)
        if pr < ns {
            score += 6.0 * (ns - pr) / cap * (1.0 + progress);
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // unless post residual would be huge; smooth penalty scaling with wasted space.
    if fitting_bins_count <= 1 {
        score -= 15.0 * (1.0 - norm_pr * norm_pr);
    }

    // Many open bins: mild preference to consolidate into existing bins rather than open new ones.
    score += (open_bins_count as f64).ln() * 0.8 * norm_pr;

    // New-bin candidate: neutral-ish baseline; penalize slightly unless current bins are poor fits.
    if bin_residual == bin_capacity {
        score += 4.0 + 10.0 * progress * (1.0 - norm_pr);
        // open a new bin when existing bins would leave very bad dead space
        score -= 20.0 * (norm_pr - 0.5).max(0.0) * (norm_pr - 0.5).max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: bins whose post_residual falls into
    // "nice" residue classes (multiples of small divisors) are more reusable.
    let pr = post_residual;
    if pr > 0 {
        // Reward leftovers divisible by common small sizes (10, 20, 25, 50).
        if pr % 50 == 0 {
            score -= 12.0;
        } else if pr % 25 == 0 {
            score -= 8.0;
        } else if pr % 10 == 0 {
            score -= 5.0;
        } else if pr % 5 == 0 {
            score -= 2.0;
        } else {
            // Awkward leftover: penalize proportionally to how prime it is.
            score += 3.0;
        }
        // Dead-space cliff: leftovers too small for the minimum plausible item.
        if pr < 10 && pr > 0 {
            score += 15.0;
        }
    } else {
        // Perfect fit: strongly reward closing the bin exactly.
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post_residual,
    // this placement is ideal.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 20.0;
        } else if next_item_size <= pr {
            // Next item fits but leaves another gap: partial reward.
            score -= (pr - next_item_size) as f64 * 0.1;
        } else {
            // Next item cannot use this bin's leftover: mild penalty for hoarding space.
            score += 2.0;
        }
        // Harmonic pairing: post_residual and next item share a common divisor class.
        let g = gcd(pr.max(next_item_size), pr.min(next_item_size).max(1));
        if g >= 10 {
            score -= 4.0;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin wastes the residual of this bin.
    if bin_residual == bin_capacity {
        // Prefer new bin only when existing bins are tightly packed or many.
        let pressure = mean_residual / bin_capacity as f64
            + (open_bins_count as f64) * 0.05
            + (step_index as f64) / (total_items.max(1) as f64) * 5.0;
        // A fresh bin starts with score = capacity; subtract pressure so it wins
        // only when open bins look unattractive.
        score -= pressure * 10.0;
        // If the item would leave a perfect harmonic gap in an open bin elsewhere,
        // the fresh-bin bonus is reduced (score stays high).
        if item_size % 25 == 0 || item_size % 10 == 0 {
            score += 5.0;
        }
    } else {
        // Existing-bin bonus scaled by how full the bin already is.
        let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= fill * 10.0;
        // Prefer bins with below-average residual (denser bins) to consolidate.
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
    }

    // Integer-division threshold: quantize post_residual into capacity-tenths
    // and reward coarse granularity (large reusable chunks).
    let tenths = pr / 10;
    score -= tenths as f64 * 0.5;

    score
}

fn gcd(a: u32, b: u32) -> u32 {
    if b == 0 { a } else { gcd(b, a % b) }
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64);
    }

    // Reward tight fits (waste near zero).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 3 {
        score -= 25.0;
    }

    // Last chance: strongly prefer using the only bin that fits, avoid new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize opening a new bin, unless item fits poorly everywhere.
    if bin_residual == bin_capacity {
        score += 20.0 + 2.0 * open_bins_count as f64;
        // Allow opening a fresh bin for large items leaving a reusable residual.
        if post_residual >= 20 && post_residual <= 50 {
            score -= 30.0;
        }
    }

    // Lookahead: favor bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; prefer consolidation.
    score += 0.15 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins below mean residual (fill emptier bins less when many are open).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong penalty for leaving dead space that the next item cannot use.
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 1.5;
    }

    // Reward perfect 2-step lookahead match: post_residual == next_item_size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }

    // Partial lookahead match: next item leaves a small remainder.
    if next_item_size > 0 && post_residual > next_item_size {
        let second_residual = post_residual - next_item_size;
        if second_residual <= 10 {
            score -= 12.0;
        }
    }

    // Penalize bins that deviate strongly from the mean residual (fragmentation).
    let dev = post_residual as f64 - mean_residual;
    score += dev.abs() * 0.3;

    // Last-chance bin: strongly prefer filling it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // Reward tight fits (low post_residual) more aggressively when many bins are open.
    if open_bins_count > 3 {
        score -= (bin_capacity - post_residual) as f64 * 0.1;
    }

    // Discourage opening a new bin early in the stream when a fit exists.
    if bin_residual == bin_capacity {
        score += 10.0 + (item_size as f64) * 0.05;
        if next_item_size > 0 && next_item_size >= item_size {
            score += 5.0;
        }
    }

    // Late in the stream, prioritize closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress > 0.8 {
        score -= (bin_capacity - post_residual) as f64 * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that no realistic item can use
    if post_residual > 0 {
        let dead = (post_residual as f64) / (bin_capacity as f64);
        let unusable = if post_residual < 10 { 0.0 } else { dead };
        score += 30.0 * unusable * unusable;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: favor bins whose post_residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 * (next_item_size as f64) / (bin_capacity as f64);
        } else {
            // post_residual is too small for the next item: penalize wasted potential
            score += 8.0 * (post_residual as f64) / (bin_capacity as f64);
        }
    }

    // Prefer filling bins that are already relatively full vs. others
    let fill = (bin_capacity - bin_residual) as f64 / (bin_capacity as f64);
    score -= 10.0 * fill;

    // Global pressure: when many bins are open, discourage opening new ones
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when open bins exist and residuals are usable
        let pressure = (open_bins_count as f64) * (mean_residual / (bin_capacity as f64));
        score += 15.0 + 6.0 * pressure + 10.0 * (1.0 - progress);
        // Allow new bin only if item is huge relative to typical residual
        if (item_size as f64) > mean_residual + 20.0 {
            score -= 20.0;
        }
    } else {
        // Slight bonus for using existing bins when many are open
        score -= (open_bins_count.min(20) as f64) * 0.4;
    }

    // Mild time-horizon shaping: be more greedy (tight-fit focused) early, more conservative late
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let pr = post_residual as f64;
    let prn = pr / bin_capacity as f64;
    let p2 = prn * prn;
    let p3 = p2 * prn;

    // Early stream: prefer tight fills (low post_residual) more strongly.
    score += 40.0 * (1.0 - progress) * p3;
    // Late stream: penalize wasted residual quadratically.
    score += 30.0 * progress * p2;

    // Smooth dead-space term: residuals too small to be useful later.
    let dead = ((prn - 0.1).max(0.0)) * ((prn - 0.2).max(0.0));
    score += 25.0 * dead;

    // Reward near-perfect fits smoothly.
    score -= 20.0 * (1.0 - p2) * (1.0 - prn);

    // Last-chance bin bonus (smoothly scaled).
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - p2);
    }

    // Coupling with mean residual: avoid fragmenting relative to average state.
    score += 0.3 * (pr - mean_residual).abs() * (0.5 + progress);

    // Lookahead: penalize leaving residual that barely misses next item.
    if next_item_size > 0 && post_residual > 0 {
        let gap = post_residual as f64 - next_item_size as f64;
        if gap < 0.0 {
            score += 8.0 * (-gap / bin_capacity as f64);
        } else {
            score -= 6.0 * (gap / bin_capacity as f64);
        }
    }

    // Mild penalty for spreading across many open bins.
    score += 0.05 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual modulo small divisors: prefer residuals
    // in classes that pair well with typical item sizes.
    let pr = post_residual;
    let cls = pr % 10;
    // Reward residuals that are near multiples of 10 (easy future fits)
    let harmonic_bonus = match cls {
        0 => 12.0,
        5 => 6.0,
        1 | 9 => 3.0,
        _ => 0.0,
    };
    score -= harmonic_bonus;

    // Integer-division threshold: residual / item_size style fit quality
    if item_size > 0 {
        let ratio = bin_residual as f64 / item_size as f64;
        if ratio >= 1.0 && ratio < 1.2 {
            score -= 8.0; // very tight fit: excellent packing
        }
    }

    // Penalize dead space: post residual too small for the smallest item (1)
    // but too small for typical mid items -> dead zone
    if pr > 0 && pr < 10 {
        score += 6.0; // awkward sliver
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 && next_item_size <= pr {
        if pr == next_item_size {
            score -= 15.0;
        } else if pr - next_item_size < 10 {
            score -= 9.0;
        }
    } else if next_item_size > pr && pr > 0 {
        score += 4.0; // next item won't fit here: residual may become dead
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: penalize mildly so we only open when open bins are bad
    if bin_residual == bin_capacity {
        score += 25.0 + open_bins_count as f64;
        // but if no open bin fits well (this is the only fitting bin), allow opening
        if fitting_bins_count == 1 {
            score -= 30.0;
        }
    }

    // Stream progression: later in the stream, be more conservative with new bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 3.0;

    // Prefer bins with residual below mean (consolidating fuller bins)
    score += (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest item are worthless.
    if post_residual < 10 {
        score -= 40.0; // perfect fill or near-perfect fill is excellent
    } else if post_residual < next_item_size && next_item_size > 0 {
        // Dead space: leftover can't host the next item
        score += 25.0;
    }

    // Reward tight fits (small waste relative to item size)
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * tightness;

    // Penalize leaving a gap that exactly matches next item (good) vs slightly above (bad)
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score += 0.5 * slack;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage scattering across many bins unless fit is tight
    score += 0.15 * open_bins_count as f64;

    // Prefer bins whose residual deviates favorably from the mean (use large-residual bins)
    score -= 0.05 * (bin_residual as f64 - mean_residual);

    // Mild preference for keeping flexibility early in the stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        score += 60.0;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: waste-free placement strongly favored.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if next item exactly fills post_residual, this is a
    // chained perfect fit — extremely desirable.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 800.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Next item fits here afterwards: mild bonus proportional to how
        // tightly the pair packs the bin.
        let pair_waste = (post_residual - next_item_size) as f64;
        score -= 60.0 * (1.0 - pair_waste / bin_capacity as f64);
    } else if next_item_size > post_residual {
        // Next item cannot use this bin's leftover: penalize dead space,
        // worse when leftover is small (unusable sliver).
        let r = post_residual as f64;
        if r > 0.0 {
            score += 25.0 * (1.0 - r / bin_capacity as f64);
        } else {
            score += 40.0;
        }
    }

    // Compare post_residual against mean residual: leaving this bin below
    // the mean shrinks average slack (good consolidation).
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: if this is the only fitting bin, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: penalize opening a fresh bin when decent fits exist,
    // but allow it when the item is large and open bins are fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = if open_bins_count > 0 {
            mean_residual / bin_capacity as f64
        } else {
            0.0
        };
        // Open a new bin when existing residuals are too scattered (high
        // fragmentation) or item is large relative to typical residual.
        score += 120.0
            - 80.0 * fragmentation
            - 50.0 * (item_size as f64 / bin_capacity as f64)
            - 30.0 * progress;
    }

    // Mild penalty for leaving very small unusable slivers (1..=5).
    if post_residual > 0 && post_residual <= 5 {
        score += 35.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: reward small post_residual non-linearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that no realistic future item can use.
    if post_residual > 0 {
        let dead = (post_residual as f64) / (bin_capacity as f64);
        if post_residual < 10 {
            score += 18.0 * (1.0 - dead); // tiny slivers are waste
        } else {
            score += 2.0 * dead;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in the post_residual, reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot fit here; mild penalty proportional to overflow.
            let overflow = (next_item_size - post_residual) as f64;
            score += 3.0 * (overflow / bin_capacity as f64);
        }
    }

    // Prefer fuller bins relative to the mean residual of open bins.
    if bin_residual < bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        score += 0.15 * diff; // bins with less residual than mean get rewarded
    }

    // New-bin candidate handling: penalize opening a new bin unless item is large
    // and no good fit exists among open bins.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let item_frac = item_size as f64 / bin_capacity as f64;
        // Base penalty for opening a new bin; reduced for large items late in stream.
        score += 20.0 - 10.0 * item_frac - 8.0 * progress;
        // If several bins fit, opening a new one is usually wasteful.
        if fitting_bins_count > 1 {
            score += 15.0;
        }
        // If many open bins already exist with large mean residual, discourage.
        score += 0.05 * open_bins_count as f64 + 0.02 * mean_residual;
    }

    // Mild preference for consolidating into fewer bins when many are open.
    score += 0.01 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Time-horizon modulation: early in stream, be conservative (avoid waste);
    // late in stream, accept slightly worse fits to close bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear tightness reward: strongly favor bins where post_residual is small,
    // using a smooth quadratic coupling normalized by capacity.
    let tight = 1.0 - (pr / cap);
    score -= 2.5 * tight * tight * cap;

    // Penalize dead space that is too small to be useful later (smooth cubic term):
    // residuals just above the minimum item size are the worst "almost unusable" zones.
    let dead_zone = (pr / cap) * (1.0 - pr / cap);
    score += 1.2 * dead_zone * dead_zone * cap;

    // Lookahead coupling: if the next item fits the post residual, reward this bin;
    // if next item nearly fits, penalize wasting this bin on a bad pairing.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if ni <= pr {
            score -= 0.8 * (ni / cap) * cap * (1.0 - progress);
        } else {
            let miss = (ni - pr) / cap;
            score += 0.5 * miss * cap * (0.5 + progress);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 3.0 * (item_size as f64 / cap) * cap;
    }

    // Stream-progress coupling: later in the stream, prefer consolidating into
    // already-open bins (avoid opening new bins with residual fragments).
    let consolidation = (pr / cap) * (0.5 + progress);
    score += 0.6 * consolidation * cap * (open_bins_count as f64).ln().max(1.0);

    // Mean-residual coupling: if this bin's residual deviates from the mean,
    // smooth non-linear penalty encourages balanced residual distribution.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 0.4 * dev * dev * cap;

    // New-bin candidate handling: a fresh empty bin should only win when the item
    // is large and no good fit exists; add a smooth offset that grows with progress
    // and shrinks when the item nearly fills a bin.
    if bin_residual == bin_capacity {
        let fill = item_size as f64 / cap;
        score += cap * (0.25 + 0.5 * progress) * (1.0 - fill * fill);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits, but scale the reward by fill ratio
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 40.0 * fill * fill;

    // Harmonic class of post_residual modulo 10: residual divisible by 10
    // is "reusable" by the common item sizes; odd residues waste space.
    let mod10 = post_residual % 10;
    if mod10 == 0 {
        score -= 6.0;
    } else if mod10 == 5 {
        score -= 2.0;
    } else {
        score += 2.0 + 0.5 * mod10 as f64;
    }

    // Dead-space penalty: residual too small for the smallest plausible item (1..=10)
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // Lookahead coupling: if next item fits the post residual, big reward
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
        // Perfect chain: next item exactly consumes residual
        if next_item_size == post_residual {
            score -= 15.0;
        }
        // Harmonic: next item is an integer divisor-ish partner
        if post_residual % next_item_size == 0 {
            score -= 5.0;
        }
    } else if next_item_size > post_residual {
        // Next item won't fit here anyway; mild penalty for leaving mid-range gap
        score += 3.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate logic: only open a new bin when this item is large
    // relative to the residual of typical open bins (poor fit elsewhere)
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin
        score += 45.0;
        // But if the item is huge (>= 70) and other bins are crowded, opening is fine
        if item_size >= 70 && mean_residual < 30.0 {
            score -= 40.0;
        }
        // Early in stream, opening bins is cheaper (more future items to fill them)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
        // If many bins already fit the item, don't open a new one
        if fitting_bins_count > 2 {
            score += 15.0;
        }
    }

    // Prefer packing into bins with below-average residual (balance avoidance
    // of fragmentation): a bin with residual well below mean is scarce capacity
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    } else {
        score += 2.0;
    }

    // Late-stream: consolidate aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * progress * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small to fit the minimum item (1) are fine,
    // but residuals that are small yet nonzero waste capacity. Penalize small gaps.
    if post_residual > 0 {
        // gap smaller than typical items is dead space; scale penalty by gap smallness
        let gap = post_residual as f64;
        let dead_threshold = 20.0;
        if gap < dead_threshold {
            score += (dead_threshold - gap) * 1.5;
        }
    }

    // Reward perfect / near-perfect fits.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid proliferation of bins).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins
    // (penalize opening new bins when open_bins_count is high).
    if bin_residual == bin_capacity {
        // new-bin candidate: penalize proportionally to how many bins are already open
        // and how well the next item could use leftover space elsewhere.
        score += 30.0 + 8.0 * open_bins_count as f64;
        // Slight discount if item is huge (hard to fit later anyway)
        if item_size > bin_capacity * 3 / 4 {
            score -= 10.0;
        }
    } else {
        // placing into an existing bin reduces open-bin pressure slightly
        score -= 2.0 * open_bins_count as f64;
    }

    // Lookahead: if next item fits exactly in post_residual, reward strongly.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 5.0;
    }

    // Mean-residual coupling: if this bin's post placement residual is far below the
    // mean residual, we are consuming the "most fillable" space efficiently.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Progress term: late in the stream, waste matters more (less future to recover).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.5 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect or near-perfect fits (low post residual, especially exact matches)
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 500.0;
    }

    // Aggressive 2-step lookahead: if the next item fits exactly in the post residual,
    // this placement is excellent (chains two items into one bin).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 800.0;
        } else if post_residual > next_item_size {
            // Next item also fits here afterward: good chain potential
            let slack = (post_residual - next_item_size) as f64;
            score -= 200.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit in post residual: dead space risk proportional to gap
            let gap = (next_item_size - post_residual) as f64;
            score += 0.5 * gap;
        }
    }

    // Penalize wasted residual relative to mean residual of open bins
    score += 0.3 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: make it unattractive unless post_residual would be very usable
    if bin_residual == bin_capacity {
        score += 60.0;
        if next_item_size > 0 && post_residual >= next_item_size && post_residual <= next_item_size + 10 {
            score -= 250.0; // opening a new bin to host the next item well
        }
    }

    // Late in the stream, tighten packing (favor dense fills)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * post_residual as f64 * 0.4;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to item size).
    let tightness = post_residual as f64 / (item_size.max(1) as f64);
    score -= 12.0 * (1.0 - tightness.min(1.0));

    // Lookahead: reward bins whose post-residual can host the next item (k=2 chaining).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Perfect chain: post_residual exactly equals next item => big bonus.
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Penalize residuals too small for the next item (dead space risk).
            let waste = (next_item_size - post_residual) as f64;
            score += 3.0 * (waste / 100.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when open bins have poor fits.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 20.0;
        // Cheapen new bin when current item is large (little fragmentation risk anyway)
        // and few bins fit it, or when open bins are crowded on average.
        score -= 0.15 * item_size as f64;
        score -= (mean_residual / 100.0) * 10.0;
        if fitting_bins_count <= 1 {
            score -= 12.0;
        }
    } else {
        // Prefer reusing fuller bins (low bin_residual) among open bins.
        score += 0.05 * (bin_residual as f64 - mean_residual);
        // Slight preference for bins that are already quite full.
        score -= 0.03 * (bin_capacity as f64 - bin_residual as f64);
    }

    // Time horizon: early in the stream, be conservative about new bins
    // (many items left to fill them); late in the stream, pack tighter.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= (1.0 - progress) * 4.0;
    } else {
        score += progress * 2.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Mild penalty for spreading across many open bins.
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / (total_items as f64) } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Base: prefer small post-residual (tight fits), non-linearly.
    let norm_post = post / cap;
    let mut score = post as f64
        + 30.0 * norm_post * norm_post
        - 25.0 * (1.0 - norm_post) * (1.0 - norm_post) * norm_post;

    // Perfect-fit reward: strong, smooth quadratic dip near zero post-residual.
    let fit_quality = 1.0 - norm_post;
    score -= 40.0 * fit_quality * fit_quality * fit_quality;

    // Lookahead coupling: penalize post-residual that is too small to hold the
    // next item (dead space), reward residual that can host it.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let can_host = if post >= nxt { 1.0 } else { 0.0 };
        let gap = (post - nxt).abs();
        score += 0.25 * gap;
        score -= 18.0 * can_host * fit_quality;
        // If next item cannot fit here, slightly prefer bins whose leftover is
        // either large (still flexible) or tiny (nearly closed).
        if can_host < 0.5 {
            score += 10.0 * (0.5 - (norm_post - 0.5).abs()).abs() * 2.0;
        }
    } else {
        // Last item: just minimize post-residual, extra reward for near-exact fit.
        score -= 20.0 * fit_quality * fit_quality;
    }

    // Stream-progress coupling: early on, keep bins flexible (penalize low
    // residuals); late in the stream, aggressively close bins with tight fits.
    let flexibility = norm_post;
    score += 20.0 * (1.0 - progress) * flexibility * flexibility;
    score -= 15.0 * progress * fit_quality * fit_quality;

    // Last-chance bonus: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 35.0 * fit_quality * (0.5 + 0.5 * progress);
    }

    // Crowd penalty: with many open bins, prefer consolidating into bins with
    // residuals near the mean (balance), smoothly.
    if open_bins_count > 1 {
        let dev = (post - mean_residual).abs();
        score += 0.08 * dev * (open_bins_count as f64).ln();
    }

    // Mild penalty for very large items in nearly-full bins (waste avoidance).
    score += 5.0 * (item / cap) * (1.0 - fit_quality);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls into small
    // "dead zones" (1..=9) waste capacity; penalize creating them.
    let pr = post_residual;
    if pr > 0 && pr < 10 {
        score += 30.0;
    } else if pr < 20 {
        score += 10.0;
    }

    // Reward residuals that are multiples of common item classes (harmonic fit).
    if pr % 10 == 0 {
        score -= 8.0;
    }
    if pr % 25 == 0 {
        score -= 6.0;
    }

    // Integer-division threshold: perfect fills are excellent.
    if pr == 0 {
        score -= 200.0;
    }

    // Lookahead coupling: if the next item exactly fills the post residual,
    // strongly favor this bin (chained harmonic fit).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 120.0;
        } else if next_item_size <= pr && (pr - next_item_size) < 10 {
            score += 15.0; // chains into a dead zone, mildly bad
        } else if next_item_size <= pr {
            score -= 20.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when no good fit exists elsewhere.
    if bin_residual == bin_capacity {
        score += 25.0;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Progress-aware tightness: late in the stream, prefer tighter packing.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (mean_residual - post_residual as f64) * 0.3 * (0.5 + progress);

    // Slight preference for bins tighter than average.
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // minimum plausible item (<= 10) are pure waste; penalize hard.
    if post_residual < 10 {
        score += 120.0;
    } else if post_residual < 20 {
        score += 45.0;
    } else if post_residual < 35 {
        score += 12.0;
    }

    // Reward exact / tight fits.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Coupling with open bins pressure: discourage spreading across many bins
    // unless the fit is genuinely tight.
    score += (open_bins_count as f64) * (post_residual as f64) / (bin_capacity as f64) * 3.0;

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Lookahead: if the next item fits into the resulting residual, reward;
    // if it leaves a residual the next item cannot use, penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 25.0;
        } else {
            score += 10.0;
        }
    }

    // Prefer bins whose residual is already below the mean (consolidating
    // fragmentation in few bins rather than many half-empty ones).
    if (bin_residual as f64) < mean_residual {
        score -= 8.0;
    }

    // New-bin candidate: only attractive when nothing fits well; make the
    // empty bin mildly unattractive by default so tight fits win, but let it
    // win over heavily dead-space-prone residuals via the penalties above.
    if bin_residual == bin_capacity {
        score += 30.0 + (open_bins_count as f64) * 0.5;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // If next item cannot fit in the post-residual, penalize dead space proportionally.
    if next_item_size > 0 && post_residual < next_item_size {
        let dead = (next_item_size - post_residual) as f64;
        score += 0.5 * dead;
    }

    // If next item fits with slack left over, mild reward scaled by closeness.
    if next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 0.15 * (1.0 - slack / bin_capacity as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize creating tiny unusable residuals (< 10, the minimum item size).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Compare against mean residual: bins tighter than average are better targets.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Prefer bins with small residual overall (tight packing).
    score += 0.2 * (post_residual as f64 / bin_capacity as f64) * 10.0;

    // New-bin candidate: only attractive when current bin fits poorly,
    // i.e., when post_residual would be very small or next item won't fit.
    if bin_residual == bin_capacity {
        let poor_fit = if next_item_size > 0 && post_residual < next_item_size { 20.0 } else { 0.0 };
        score += 15.0 - poor_fit;
    }

    // Slight preference to consolidate into fewer bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 2.0 * progress * (open_bins_count as f64).ln().max(0.0) / (fitting_bins_count.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize bins whose post-residual is small.
    let fit_ratio = (item_size as f64) / (bin_residual.max(1) as f64);
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize dead space: post-residual too small to ever be useful
    // (smaller than the minimum plausible future item).
    if post_residual < 20 {
        score += (20 - post_residual) as f64 * 1.5;
    }

    // Lookahead: if the next item fits exactly into the post-residual,
    // strongly favor this bin; if next item cannot fit, slight penalty.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
        } else {
            score += 8.0;
        }
    }

    // Last chance: only one open bin fits this item; discourage opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Many open bins: prefer using existing ones over opening new bins.
    score += open_bins_count as f64 * 2.0;

    // Prefer bins with residual close to the mean residual (balanced packing),
    // mildly, scaled by stream progress.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.3 * dev * (0.5 + progress);

    // New-bin candidate: only attractive when the item is large and no tight fit exists.
    if bin_residual == bin_capacity {
        let large_item_bonus = 35.0 * (item_size as f64 / bin_capacity as f64);
        score = score + 15.0 - large_item_bonus;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post-residual, with smooth non-linear polynomial coupling to progress
    let mut score = pr * (1.0 + 0.6 * norm_pr * norm_pr);

    // Polynomial interaction: residual quality vs stream progress.
    // Early on, tight fits matter less; late, penalize large residuals harder.
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * progress;
    score += 30.0 * poly;

    // Reward filling the bin deeply (small post_residual), amplified by progress
    let fill = 1.0 - norm_pr;
    score -= 8.0 * fill * fill * (0.5 + progress);

    // Dead-space penalty: residual too small for typical items (smooth bump around tiny residuals)
    let dead = ((norm_pr - 0.08) / 0.08).powi(2);
    score += 6.0 * (-dead).exp() * pr;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    } else {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).min(4.0);
    }

    // Lookahead: bonus if next item fits the post-residual well (smooth match term)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let slack = (pr - nxt).abs();
        let match_term = 1.0 - (slack / cap).min(1.0);
        score -= 10.0 * match_term * match_term;
    } else {
        // Last item: strongly prefer fullest fill
        score -= 15.0 * fill;
    }

    // New-bin candidate: make it attractive only when open bins have poor fits
    if bin_residual == bin_capacity {
        let pressure = (mean_residual / cap).max(0.0);
        score = cap * 1.5 - 30.0 * pressure - 10.0 * progress;
        if fitting_bins_count <= 1 {
            score -= 20.0;
        }
    }

    // Mild penalty for bin proliferation
    score += 0.5 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic classes: post_residual divisible by small divisors => reusable
    let pr = post_residual;
    if pr > 0 {
        if pr % 10 == 0 { score -= 12.0; }
        else if pr % 5 == 0 { score -= 6.0; }
        if pr % 25 == 0 { score -= 8.0; }
        // dead-space penalty for tiny awkward leftovers
        if pr < 10 { score += 30.0 * (10 - pr) as f64; }
    }

    // Next-item coupling: reward residuals that can host the lookahead item
    if next_item_size > 0 && pr >= next_item_size {
        score -= 15.0;
        if (pr - next_item_size) % 10 == 0 { score -= 5.0; }
    } else if next_item_size > 0 && pr > 0 {
        // residual cannot host next item: mild penalty scaled by how close
        score += 5.0;
    }

    // Last-chance bin bonus: only fitting bin, avoid opening new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: prefer opening a new bin only when current
    // open bins would leave large dead space
    if bin_residual == bin_capacity {
        // neutral baseline: slightly worse than a good fit, better than dead space
        score = bin_capacity as f64 * 0.5 - 20.0;
        if fitting_bins_count == 0 { score -= 40.0; }
    }

    // Progress-aware mild pressure to consolidate early
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * (1.0 - progress);

    // Prefer bins tighter than the mean residual (better packing)
    score += (mean_residual - bin_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A gap is "dead" if it is below the minimum item size (10) or cannot
    // hold the lookahead item (which likely leaves it stranded forever).
    if post_residual > 0 {
        let below_min = post_residual < 10;
        let lookahead_stranded = next_item_size > 0 && (next_item_size as u32) > post_residual;
        if below_min || lookahead_stranded {
            // Penalize proportionally to how "wasted" the gap is relative to capacity.
            score += 40.0 + 60.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Lookahead reward: if the next item fits exactly into the resulting gap,
    // this placement chains nicely — reward it, more so early in the stream.
    if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        score -= 6.0 + 8.0 * (1.0 - progress);
    }

    // Last-chance bonus: if this is the only open bin that fits, prefer it
    // strongly to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Open-bins pressure applied to the NEW-BIN candidate: opening a bin is
    // penalized more as more bins are already open and as the stream matures,
    // but the penalty is bounded so a truly dead-space-creating fit still loses.
    if bin_residual == bin_capacity {
        score += 8.0 + 2.5 * open_bins_count as f64 * (0.4 + 0.6 * progress);
    }

    // Mild regularization: prefer bins whose residual is near the mean
    // (keeps the pool of open bins balanced and flexible).
    score += 0.05 * (mean_residual - bin_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong preference for tight fits: low post_residual wins.
    score += (post_residual as f64 / bin_capacity as f64) * 20.0;

    // 2-step lookahead: reward bins whose post_residual matches next_item_size.
    if next_item_size > 0 {
        let gap = if post_residual >= next_item_size {
            (post_residual - next_item_size) as f64
        } else {
            (next_item_size - post_residual) as f64 * 2.5 // unusable for next item: penalize more
        };
        score += gap * 1.5;

        // Perfect chain fit bonus.
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Next item fits and leaves another decent residual: mild bonus.
        if post_residual >= next_item_size && post_residual - next_item_size >= 10 {
            score -= 8.0;
        }
    } else {
        // Last item: just minimize post_residual.
        score -= 5.0;
    }

    // Relative-to-mean coupling: bins below mean residual are already tight;
    // prefer them to consolidate waste.
    let dev = mean_residual - post_residual as f64;
    score += dev * 0.6;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize creating dead space that no future item (>= 1) could use.
    if post_residual < 10 && post_residual > 0 {
        score += 15.0;
    }

    // New-bin candidate: only attractive when current bin would leave bad fit.
    if bin_residual == bin_capacity {
        // Neutral-ish base; lookahead decides.
        score += 12.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
        // Early in stream, opening bins is cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 10.0;
    }

    // Mild pressure against accumulating many open bins with fat residuals.
    score += (open_bins_count as f64).ln().max(0.0) * (post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Tight-fit reward: strongly favor placements that leave little waste
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 45.0 * tightness * tightness;

    // Penalize "awkward" residuals that few typical items can use
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny dead space is nearly useless
    } else if post_residual >= 10 && post_residual < 30 {
        score += 6.0; // moderately awkward zone
    }

    // Lookahead: reward if the next item exactly fits the post residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chain
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here: leftover becomes potential dead space
            score += 8.0 + 0.1 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, use it
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 35.0;
    }

    // New-bin decision: opening a bin is fine early, costly when many bins open
    if is_new_bin {
        let open_penalty = (open_bins_count as f64).ln() * 12.0;
        let time_discount = 20.0 * (1.0 - progress);
        // prefer new bin only if all existing fits are terrible
        score += 55.0 + open_penalty - time_discount;
        // if the next item is large, a fresh bin absorbs it well later
        if next_item_size >= bin_capacity / 2 {
            score -= 15.0;
        }
    }

    // Prefer filling bins that are already relatively empty (consolidation)
    score += 0.15 * (mean_residual - bin_residual as f64).abs();

    // Mild preference for bins with larger residuals as stream matures
    score += 0.05 * bin_residual as f64 * progress;

    // Slight penalty when many bins compete (spread items, keep flexibility)
    if fitting_bins_count > 3 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_post = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let progress_poly = 0.6 + 1.4 * t * t - 0.8 * t * t * t;
    let mut score = pr * progress_poly;

    // Quadratic penalty for small-but-nonzero dead space (unusable slivers)
    score += 40.0 * norm_post * (1.0 - norm_post) * (1.0 - norm_post);

    // Perfect fit bonus (smooth via squared term)
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward near-perfect fits smoothly
    let fit_quality = 1.0 - norm_post;
    score -= 25.0 * fit_quality * fit_quality;

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 15.0 + 20.0 * t;
    }

    // Lookahead coupling: reward residual that can host the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 18.0 * (1.0 - (pr - nxt) / cap);
        } else {
            score += 10.0 * (nxt - pr) / cap;
        }
    }

    // Congestion term: prefer spreading when many bins open with high mean residual
    let mean_norm = mean_residual / cap;
    score += 6.0 * mean_norm * (open_bins_count as f64).sqrt() * (0.5 + t);

    // Slight preference for tighter bins overall
    score += 8.0 * (1.0 - (bin_residual as f64) / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // ---- Harmonic class of the leftover space (integer division thresholds) ----
    // Class 0: perfect fit (post_residual == 0) -> huge reward
    // Class 1: post_residual in 1..=10  -> tiny dead space, good
    // Class 2: post_residual in 11..=25 -> moderate
    // Class 3: post_residual in 26..=49 -> half-bin dead zone, penalize
    // Class 4: post_residual >= 50      -> still reusable, mild penalty
    let post_class: u32 = if post_residual == 0 {
        0
    } else if post_residual <= 10 {
        1
    } else if post_residual <= 25 {
        2
    } else if post_residual <= 49 {
        3
    } else {
        4
    };

    match post_class {
        0 => { score -= 60.0; }
        1 => { score -= 25.0; }
        2 => { score += 5.0; }
        3 => { score += 20.0; }
        _ => { score += 10.0; }
    }

    // ---- Lookahead coupling: does the next item fit into the leftover? ----
    // Harmonic pairing: next_item_size / post_residual integer-division classes.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            // perfect chained fit
            score -= 45.0;
        } else if next_item_size <= post_residual {
            let ratio_class = (post_residual / next_item_size.max(1)).min(4);
            score -= 10.0 + 8.0 * ratio_class as f64;
        } else {
            // next item cannot use the leftover: dead space penalty scaled by
            // how much of the next item the residual would cover
            let cover = post_residual as f64 / next_item_size as f64;
            score += 12.0 * (1.0 - cover.min(1.0));
        }
    }

    // ---- Last-chance pressure: if this is the only fitting bin, strongly favor using it ----
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // ---- New-bin candidate handling ----
    if bin_residual == bin_capacity {
        // Opening a new bin costs ~1 bin; make it attractive only when the
        // item would leave a large, awkward hole in an existing bin.
        // Base cost of a fresh bin:
        let mut new_bin_score = bin_capacity as f64 * 0.55; // 55.0
        // If the item fills a large fraction of the new bin, opening is cheap.
        let fill = item_size as f64 / bin_capacity as f64;
        new_bin_score -= 40.0 * fill;
        // Late in the stream, prefer consolidating into existing bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        new_bin_score += 25.0 * progress;
        // Many open bins with slack -> discourage yet another bin.
        new_bin_score += 0.4 * open_bins_count as f64;
        // If an existing bin would be left with tiny dead space, opening a new
        // bin looks better (this call's score already reflects that via class).
        score = new_bin_score;
    }

    // ---- Mean-residual context: bins far below mean residual are "sinks" ----
    let dev = mean_residual - post_residual as f64;
    score += 0.05 * dev;

    // ---- Modulo harmonic: reward leftovers that are multiples of common sizes ----
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = 0.0;

    // Base: penalize wasted space, but nonlinearly — small unusable gaps are worst.
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let frac = pr / cap;

    // Dead-space penalty: quadratic in residual fraction, amplified when the gap
    // is too small to hold even the smallest plausible item (unusable gap).
    let dead_threshold = 0.10_f64; // gaps below ~10% of capacity are near-useless
    if frac > 0.0 && frac < dead_threshold {
        // worst zone: item nearly fills bin but leaves sliver
        score += 40.0 * (1.0 - frac / dead_threshold);
    }
    score += 12.0 * frac * frac;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 25.0;
    } else if pr < 5.0 {
        score -= 10.0;
    }

    // Reward residuals that can still host the lookahead item (k=2 chaining).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / cap);
        } else {
            // leftover can't fit next item: mild penalty scaled by gap size
            score += 4.0 * (1.0 - pr / next_item_size as f64).abs();
        }
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is tight.
    let pressure = (open_bins_count as f64).ln() + 1.0;
    score += 3.0 * pressure * frac;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless post_residual is a terrible sliver).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (1.0 - frac);
    }

    // Prefer bins whose residual is close to item (best-fit coupling).
    let tightness = 1.0 - (bin_residual - item_size) as f64 / cap;
    score -= 6.0 * tightness;

    // Progress scaling: later in stream, waste matters more (less room to recover).
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 5.0 * progress * frac;

    // Mean-residual coupling: if this bin is far below mean residual, it's a
    // "ragged" bin — using it normalizes open bins.
    score -= 2.0 * (mean_residual - pr) / cap;

    // New-bin candidate handling: empty bin has large residual; give it a
    // moderate baseline so it only wins when fits elsewhere are awful.
    if bin_residual == bin_capacity {
        score += 18.0 + 4.0 * pressure;
        // But if no other bin fits well, new bin becomes attractive:
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // --- 2-step lookahead coupling with next_item_size ---
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Perfect match: next item exactly fills this bin's leftover.
            score -= 40.0 + 10.0 * (item_size as f64 / 100.0);
        } else if post_residual > next_item_size {
            // Next item also fits here: reward proportionally to how snugly.
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 - slack.min(50.0) * 0.2;
        } else {
            // Next item won't fit: dead space penalty grows with gap and stream progress.
            let gap = (next_item_size - post_residual) as f64;
            score += gap * (0.25 + 0.35 * progress);
        }
    }

    // --- Tightness reward: small post_residual is good, but avoid unusable slivers ---
    if post_residual > 0 && post_residual < 10 {
        // Sliver below minimum item size is dead space.
        score += 12.0;
    }

    // --- Last-chance bonus: this is the only bin that can take the item ---
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // --- Compare against mean residual of open bins ---
    // Bins tighter than average (small residual relative to mean) are preferred targets.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // --- Mild penalty for opening new bins when many bins already fit the item ---
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when current bins are nearly full on average.
        score += 5.0 + 0.15 * (open_bins_count as f64) * (1.0 - progress);
    }

    // --- Late-stream consolidation: favor filling existing bins harder near the end ---
    if progress > 0.7 {
        score -= 6.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: squared post-residual penalizes wasted space superlinearly.
    score += (post_residual as f64).powi(2) / bin_capacity as f64;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Small dead-space band penalty: residuals too small for any item (min size 1).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when it's a genuinely good deal —
    // i.e., the item leaves a large, usable residual in a fresh bin AND
    // fits poorly everywhere else.
    if bin_residual == bin_capacity {
        let good_future = post_residual >= 50;
        let poor_fit = (bin_residual - item_size) >= 40 && fitting_bins_count >= 1;
        if good_future || poor_fit {
            score -= 12.0;
        } else {
            score += 30.0 + open_bins_count as f64;
        }
    }

    // Lookahead coupling: if the next item fits in the post-residual, reward;
    // if the next item would fit better elsewhere, mild penalty.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 6.0 + 0.05 * next_item_size as f64;
        }
        // Avoid consuming space the next item needs exactly.
        if post_residual < next_item_size && next_item_size <= bin_residual {
            score += 3.0;
        }
    }

    // Global state: many open bins with large mean residual → prefer consolidation.
    if open_bins_count > 2 && mean_residual > 20.0 {
        score -= 0.05 * mean_residual;
    }

    // Time horizon: early in the stream, be slightly conservative about
    // fragmenting bins; late in the stream, exploit tight fits harder.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.15 * (1.0 - progress);
    score -= 2.0 * progress * (post_residual as f64) / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let pr = post / cap;
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;

    let mut score = post;

    // Non-linear coupling: post_residual weighted by stream progress polynomial
    score *= 1.0 + 0.6 * progress * progress - 0.3 * progress * pr;

    // Penalize large dead space non-linearly
    score += 12.0 * pr * pr * cap * (0.5 + 0.5 * progress);

    // Reward tight fits (item nearly fills bin), stronger late in stream
    score -= 25.0 * fit_ratio * fit_ratio * (0.4 + 0.8 * progress);

    // Lookahead: favor bins whose post-residual still fits the next item
    if next_item_size > 0 {
        let next_fits = (post_residual >= next_item_size) as i32 as f64;
        score -= 8.0 * next_fits * (1.0 - progress);
    } else {
        // last item: strongly prefer filling bins tightly
        score -= 15.0 * fit_ratio;
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 * (1.0 - progress);
    }

    // New-bin candidate: penalize opening new bins mildly, more when many bins open
    if bin_residual == bin_capacity {
        score += 10.0 + 2.0 * open_bins_count as f64 * (0.5 + progress);
        // but allow new bin if all fits would be terrible
        score -= 30.0 * (1.0 - fit_ratio) * (fit_ratio < 0.35) as i32 as f64;
    }

    // Mean residual alignment: prefer bins near the mean (balanced packing)
    score += 0.15 * (post - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modular arithmetic on capacity fractions.
    // Residuals that are "nice" (multiples of 10 / 25 / 50) are more reusable.
    let nice_bonus = if post_residual == 0 {
        50.0 // perfect fit: heavily reward
    } else if post_residual % 50 == 0 {
        20.0
    } else if post_residual % 25 == 0 {
        12.0
    } else if post_residual % 10 == 0 {
        8.0
    } else if post_residual % 5 == 0 {
        4.0
    } else {
        0.0
    };
    score -= nice_bonus;

    // Dead-space penalty: residual too small to hold the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual < next_item_size as u32 && next_item_size > 0 && post_residual > 0 {
        // residual can't fit the lookahead item -> dead-ish space
        score += 6.0;
    }

    // Coupling with next_item_size: if post_residual exactly fits lookahead, reward strongly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 18.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= (post_residual - next_item_size).min(20) as f64 * 0.4;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // unless the fit is terrible (huge dead space).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        let waste_ratio = post_residual as f64 / bin_capacity as f64;
        if waste_ratio < 0.35 {
            score -= 30.0;
        } else {
            score -= 8.0;
        }
    }

    // New-bin candidate: penalize opening a new bin unless the current item is large
    // and no open bin fits well. Empty bin has bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 55.0;
        // less costly late in the stream or when open bins are nearly full on average
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= progress * 15.0;
        if open_bins_count > 0 && mean_residual < item_size as f64 {
            // no open bin can really help; opening is justified
            score -= 40.0;
        }
        if item_size >= 70 {
            score -= 10.0;
        }
    }

    // Tight-fit reward: item fills most of the bin
    let fill = item_size as f64 / bin_capacity as f64;
    if fill > 0.8 {
        score -= 10.0;
    } else if fill > 0.6 {
        score -= 5.0;
    }

    // Integer-division threshold: quantize post_residual into harmonic bands;
    // prefer residuals in the band [10, 30] (usable small-item slots).
    let band = post_residual / 10;
    match band {
        0 => { if post_residual > 0 { score += 10.0; } } // tiny residual
        1 | 2 | 3 => score -= 5.0, // sweet spot
        4 | 5 => score -= 2.0,
        _ => {}
    }

    // Slight preference for keeping number of open bins low when spread is wide
    if open_bins_count > 8 && post_residual as f64 > mean_residual {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold any item are pure waste.
    let min_item = 10.0f64;
    if (post_residual as f64) < min_item && post_residual > 0 {
        score += 1000.0; // unusable gap -> strong penalty
    } else if post_residual == 0 {
        score -= 50.0; // perfect fill reward
    } else {
        // penalize small-but-usable residuals that will likely become dead space
        let pr = post_residual as f64;
        if pr < 20.0 {
            score += (20.0 - pr) * 2.0;
        }
    }

    // Prefer bins whose residual tightly matches the item (low post residual relative to residual)
    if bin_residual > 0 {
        let tightness = item_size as f64 / bin_residual as f64;
        score -= tightness * 10.0;
    }

    // Last-chance bonus: only this bin can fit the item
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: discourage spreading across many bins when mean residual is high
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score += open_bins_count as f64 * (1.0 + progress);
        // favor bins below mean residual (consolidation)
        score += (mean_residual - bin_residual as f64) * 0.3;
    } else {
        // new-bin candidate: only attractive when open bins are crowded
        score += open_bins_count as f64 * 2.0;
        if mean_residual < item_size as f64 + 5.0 {
            score -= 30.0;
        }
    }

    // Lookahead: keep room for the next item if it fits in post residual
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact-ish fits: small post_residual strongly favored (non-linear).
    score -= (bin_capacity as f64 / (post_residual as f64 + 1.0)) * 4.0;

    // 2-step lookahead: reward if next item fits into the post residual.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if (next_item_size as u32) <= post_residual {
            // Perfect chain: post residual exactly matches next item.
            let slack = (post_residual as f64 - next).abs();
            score -= 30.0 / (1.0 + slack);
            // Extra bonus if next item then leaves a near-zero residual too.
            let post2 = post_residual as f64 - next;
            score -= 20.0 * (1.0 - post2 / bin_capacity as f64).max(0.0);
        } else {
            // Next item won't fit here: penalize leaving large awkward gaps,
            // especially gaps that are too small for typical future items.
            if post_residual < 10 {
                score += 15.0; // dead space trap
            } else if post_residual < next {
                score += 8.0 * (1.0 - post_residual as f64 / next);
            }
        }
    } else {
        // Last item: just minimize post residual.
        score -= 40.0;
    }

    // Penalize bins whose residual is far below mean (already tight, save them
    // for small items) — mildly; reward bins near the mean residual.
    let dev = post_residual as f64 - mean_residual;
    score += 0.15 * dev.abs();

    // Last-chance bin: if this is the only fitting bin, strongly prefer using
    // it over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 2 {
        // Many alternatives: we can afford to be picky, penalize mediocre fits.
        score += 3.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // New-bin candidate handling: an empty bin has post_residual == capacity.
    // Penalize opening a new bin unless the current item is large and would
    // leave an awkward residual in any existing bin.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 > 0.6 * bin_capacity as f64;
        let awkward = next_item_size > 0
            && (post_residual as u32) < next_item_size
            && post_residual < 10;
        if large_item || awkward {
            score -= 20.0; // allow opening a new bin for big/awkward items
        } else {
            score += 35.0; // discourage new bins for easy fits
        }
    }

    // Late in the stream, consolidate more aggressively into open bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Slight preference to keep number of open bins low early on.
    score += 0.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tight fit reward: strong discount as post_residual approaches 0.
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 55.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 120.0;
    }

    // Lookahead: reward if the next item can fit into the post residual,
    // penalize if post residual is a dead zone (too small for typical items).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post_residual as f64 {
            score -= 25.0 * (nxt / cap);
        } else {
            // Dead space: leftover too small for the next item.
            let waste = post_residual as f64;
            if waste > 0.0 {
                score += 15.0 * (waste / cap);
            }
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoids opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Many open bins: prefer consolidation into existing bins.
    score += 4.0 * (open_bins_count as f64).ln().max(0.0);

    // Deviation from mean residual: prefer bins with residuals close to mean
    // (keeps residual distribution balanced), but favor tighter-than-mean bins.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 10.0 * dev;

    // New-bin candidate handling: empty bin gets a base penalty so we only
    // open a new bin when fits into open bins are poor (large post_residual).
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // Early stream: more willing to open bins; late stream: consolidate.
        score = 100.0 + 60.0 * (1.0 - progress);
        if next_item_size > 0 && (next_item_size as f64) <= cap {
            score += 10.0;
        }
    }

    // Progress-scaled mild tightening: as stream advances, prefer tighter fits more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 20.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: post residual, mildly squashed
    let mut score = pr * (1.0 + 0.5 * pr_norm * pr_norm);

    // Smooth polynomial coupling with progress: early stream tolerates larger residuals,
    // late stream penalizes them quadratically.
    let prog_coupling = pr_norm * (0.5 + 2.5 * progress * progress);
    score += prog_coupling * cap;

    // Penalize residual that cannot fit the lookahead item (smooth ramp).
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let deficit = (ns - pr).max(0.0) / cap;
        score += deficit * deficit * cap * (1.0 + progress);
        // Reward residual that nicely accommodates lookahead (smooth bell around exact fit).
        let fit_quality = 1.0 - ((pr - ns) / cap).abs();
        if fit_quality > 0.0 {
            score -= fit_quality * fit_quality * 8.0;
        }
    }

    // Last-chance bin bonus: only fitting bin gets smooth reward.
    if fitting_bins_count == 1 {
        score -= 6.0 * (1.0 - pr_norm * pr_norm);
    }

    // Scarcity pressure: many open bins -> prefer filling existing ones (favor low post_residual).
    let scarcity = (open_bins_count as f64 / (open_bins_count as f64 + 4.0)) * progress;
    score += scarcity * pr_norm * 10.0;

    // Mild attraction toward bins near mean residual (balance loads smoothly).
    let dev = (pr - mean_residual) / cap;
    score += dev * dev * 3.0 * (1.0 - progress);

    // New-bin candidate: penalize opening a fresh bin unless residual is tiny elsewhere.
    if bin_residual == bin_capacity {
        score += 14.0 * (1.0 - progress) + 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues divisible by common item
    // size classes (10, 20, 25, 50) are more reusable dead space.
    let pr = post_residual;
    if pr == 0 {
        score -= 40.0; // perfect fill
    } else {
        let mut bonus = 0.0;
        if pr % 10 == 0 { bonus += 6.0; }
        if pr % 20 == 0 { bonus += 4.0; }
        if pr % 25 == 0 { bonus += 3.0; }
        if pr % 50 == 0 { bonus += 5.0; }
        // Integer-division tier: large residuals are more valuable than tiny slivers.
        let tier = pr / 10; // 0..=10
        bonus += tier as f64 * 1.5;
        score -= bonus;

        // Penalize unusable slivers: residual smaller than the minimum plausible item (10)
        if pr < 10 {
            score += 25.0;
        }
    }

    // Lookahead coupling: does next_item_size fit exactly into post_residual?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0; // perfect chain
        } else if next_item_size < pr {
            let slack = pr - next_item_size;
            // harmonic class of the slack after chaining
            if slack % 10 == 0 { score -= 8.0; }
            if slack < 10 { score += 10.0; } // chain creates sliver
            score -= (slack as f64).sqrt() * 2.0;
        } else {
            // next item cannot use this residual: check if it fits modulo class
            score += 5.0;
            if pr % 10 != 0 { score += 6.0; }
        }
    } else {
        // last item: strongly prefer exact fill
        score -= (bin_capacity - post_residual) as f64 * 0.1;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin gets base score = capacity (100).
    // Make it attractive only when existing residuals are poorly reusable.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Early stream: opening bins is fine; late stream: prefer filling.
        score -= 20.0 * (1.0 - progress);
        if open_bins_count == 0 {
            score -= 50.0;
        }
        // If mean residual across open bins is large and well-classed, prefer existing bins.
        if mean_residual > (item_size as f64) * 1.5 {
            score += 15.0;
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += open_bins_count as f64 * 0.3;
    score -= mean_residual * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable small gaps: dead space that no realistic future item (1..=100) can use well.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 25 {
        score += (25.0 - post_residual as f64) * 1.5;
    }

    // Reward tight fits: small post_residual relative to item size.
    if item_size > 0 {
        let tightness = post_residual as f64 / item_size as f64;
        score -= 40.0 / (1.0 + tightness);
    }

    // Pressure from number of open bins: prefer consolidating into existing bins
    // when many bins are already open.
    let open_pressure = open_bins_count as f64 * 0.8;
    score += open_pressure * (post_residual as f64 / bin_capacity as f64);

    // If this is the only fitting bin, strongly favor using it (last chance before new bin).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly into the post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack < 10 {
            score -= 20.0;
        } else {
            score -= 10.0 * (1.0 - slack as f64 / bin_capacity as f64);
        }
    }

    // Progress-based calibration: later in the stream, be stricter about waste.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0 * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: make an empty bin mildly unattractive unless existing bins are bad.
    if bin_residual == bin_capacity {
        score += 8.0 + mean_residual * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong 2-step lookahead: reward when next item exactly fills post_residual.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 40.0 * f64::exp(-gap / 8.0);
        // Penalize post_residual just below next_item_size (unusable for lookahead).
        if (post_residual as i64 - next_item_size as i64) < 0 {
            score += 12.0 * f64::exp(-(next_item_size as f64 - post_residual as f64) / 5.0);
        }
    } else {
        // Last item: just minimize waste.
        score += 5.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Penalize small dead space (<10) that likely becomes unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    if post_residual == 0 {
        score -= 30.0; // perfect closure
    }

    // Relative-to-mean coupling: prefer bins whose post residual stays near mean.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: make it moderately attractive only when no tight fit exists,
    // i.e., when this bin would leave large waste and many bins are open.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 - 15.0
            + 0.5 * (open_bins_count as f64).sqrt()
            - 25.0 * f64::exp(-(item_size as f64) / 30.0);
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 20.0; // pair next item into a fresh bin
        }
    }

    // Mild late-stream tightening: waste matters more as stream progresses.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 0.10 * progress * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress ratio of the stream
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Perfect fit bonus: strongly reward leaving no dead space
    if post_residual == 0 {
        score -= 50.0;
    } else {
        // Penalize small dead space that nothing can ever use (min item size 1)
        // but dead space that could fit a future item is less bad
        let waste = post_residual as f64 / bin_capacity as f64;
        score += waste * 40.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual,
    // this is a great chain placement; reward it.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            // next item can still fit: mild reward proportional to how well it fits
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here: slight penalty scaled by how much it overflows
            let overflow = (next_item_size - post_residual) as f64;
            score += 5.0 * (overflow / next_item_size.max(1) as f64).min(1.0);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        let tightness = item_size as f64 / bin_residual as f64;
        score -= 20.0 * tightness;
    }

    // New-bin candidate handling: a fresh empty bin should only win when the
    // current placement wastes a lot of space or many bins are already open.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, reduced later in the stream
        // (late in stream, salvage value of new bin is low).
        let mut new_bin_cost = 25.0 * (1.0 - 0.5 * progress);
        // If open bins are fragmented (mean residual low relative to item),
        // opening a fresh bin is more attractive.
        if mean_residual < item_size as f64 {
            new_bin_cost -= 10.0;
        }
        // If item leaves a perfect slot for next item in a fresh bin, discount.
        if next_item_size > 0 && next_item_size <= bin_capacity.saturating_sub(item_size) {
            new_bin_cost -= 5.0;
        }
        score += new_bin_cost.max(0.0);
    }

    // Prefer filling bins with larger residuals when many bins are open
    // (consolidation pressure), weighted by stream progress.
    score += (mean_residual - bin_residual as f64).max(0.0) * (0.3 + 0.4 * progress);

    // Mild preference for bins that are already partially filled early on,
    // to keep the number of open bins low.
    let fill_ratio = 1.0 - bin_residual as f64 / bin_capacity as f64;
    score -= fill_ratio * 8.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let p2 = progress * progress;
    let p3 = p2 * progress;
    score += (0.35 * p2 + 0.55 * p3) * pr_norm * cap * (1.0 - pr_norm);

    // Reward tight fits (low post residual) more strongly as stream advances.
    let tightness = 1.0 - pr_norm;
    score -= (1.5 * progress + 1.0) * tightness * tightness * 10.0;

    // Penalize leaving dead space that cannot fit the next item (smooth interaction).
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let gap = (ns - pr).max(0.0);
        score += 0.8 * gap * (1.0 + progress);
        // Reward bins whose post residual still accommodates the next item.
        let fit_next = 1.0 - (gap / cap).min(1.0);
        score -= 0.5 * fit_next * (1.0 + progress) * pr_norm * cap;
    }

    // Last-chance bin bonus: avoid opening new bins when only one fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0 * (0.5 + progress);
    }

    // Mild dispersion penalty relative to mean residual (smooth quadratic).
    let dev = pr - mean_residual;
    score += 0.05 * dev * dev / cap;

    // Slight preference to fill bins with larger residuals early, tighter later.
    score += (1.0 - 2.0 * progress) * 0.1 * (pr_norm - 0.5) * cap;

    // New-bin candidate: keep neutral baseline so poor fits trigger opening bins.
    if bin_residual == bin_capacity {
        score += 4.0 + 6.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: dead space classes modulo 10
    let class = post_residual % 10;
    let class_penalty = match class {
        0 => -20.0,               // perfect fill
        1 | 2 | 3 => 15.0,        // awkward tiny slivers
        4 | 5 | 6 => 5.0,         // medium classes
        7 | 8 | 9 => 10.0,        // moderately awkward
        _ => 0.0,
    };
    score += class_penalty;

    // Integer-division thresholds on post_residual: quanta of capacity
    let quantum = post_residual / 25; // 0..4 quanta
    score += quantum as f64 * 3.0;

    // Reward tight fits strongly
    if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 15 {
        score -= 10.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            // next item won't fit here; penalize large leftover less if mean residual is high
            score += 6.0;
        }
    }

    // Modulo harmonic on item_size: large items prefer emptier bins
    let item_class = item_size / 20; // 0..4
    score += item_class as f64 * (bin_residual as f64 - post_residual as f64) * 0.1;

    // Prefer keeping bins balanced early in the stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (mean_residual - post_residual as f64).abs() * (1.0 - progress) * 0.5;

    // Mild penalty for opening new bins when many are open
    if bin_residual == bin_capacity {
        score += 12.0 + open_bins_count as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps heavily.
    if post_residual > 0 {
        let next_size = if next_item_size > 0 { next_item_size } else { 10 };
        if post_residual < next_size {
            // Gap cannot fit the lookahead item: dead space penalty grows as gap shrinks.
            let gap_ratio = post_residual as f64 / next_size as f64;
            score += 40.0 * (1.0 - gap_ratio);
        }
        // Perfect fit bonus: strongly reward leaving exactly zero space.
        if post_residual == 0 {
            score -= 25.0;
        }
        // Reward gaps that exactly fit the next item (chain-friendly).
        else if next_item_size > 0 && post_residual == next_item_size {
            score -= 12.0;
        }
    }

    // Last-chance pressure: if this is the only fitting bin, avoid forcing a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Open-bin pressure: when many bins are open, prefer tighter packing (higher post_residual is fine);
    // when few bins are open, slightly prefer filling existing bins over opening new ones.
    let open_pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual < bin_capacity {
        // Existing bin: reward usage scaled by how many bins are already open.
        score -= 3.0 + open_pressure * 2.0;
    } else {
        // New empty bin candidate: penalize mildly unless it's a great fit (near-perfect fill).
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        score += 10.0 * (1.0 - fill_ratio);
    }

    // Mean-residual coupling: if this bin's residual is far below mean, it's already tight — keep using it.
    let residual_gap = mean_residual - bin_residual as f64;
    if residual_gap > 0.0 {
        score -= 2.0 * residual_gap.min(30.0) / 30.0;
    }

    // Stream progression: late in the stream, be more conservative about opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 8.0 * progress;
    } else {
        score -= 4.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Lookahead: reward bins whose post_residual perfectly fits the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 60.0 / (1.0 + gap);
        if gap == 0.0 {
            score -= 40.0;
        }
    } else if next_item_size > 0 {
        // Penalize dead space the next item cannot use.
        score += next_item_size as f64 * 0.35;
    }

    // Tight fit reward relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= tightness * 25.0;

    // Compare against mean residual: prefer bins tighter than average.
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Penalize opening a new bin when plenty of bins fit, mild early-stream bias to keep bins open.
    if bin_residual == bin_capacity {
        score += 12.0;
        if open_bins_count == 0 {
            score -= 200.0;
        }
    }

    // Late-stream consolidation: prefer filling existing bins more aggressively near the end.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that can't fit a typical item.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // unusable sliver
    }

    // Lookahead: if the next item fits exactly into post_residual, big bonus.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_fit = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - chain_fit / bin_capacity as f64);
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here; mildly penalize burning this bin's space.
        score += 4.0;
    }

    // Last-chance bonus: this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: opening a new bin should be moderately expensive,
    // but attractive when the fit elsewhere is terrible.
    if bin_residual == bin_capacity {
        score += 25.0 + 3.0 * open_bins_count as f64;
        // If current item is large and no open bin fits well, new bin is fine.
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    // Global state coupling: when mean residual is high, prefer using
    // existing slack rather than fragmenting more bins.
    score += 0.3 * (mean_residual - post_residual as f64);

    // Time horizon: early in the stream, be more conservative about
    // creating dead space; late, prioritize closure.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let x = post / cap; // normalized post residual in [0,1]

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = post;
    score += 18.0 * x * x * (1.0 + progress);
    score -= 10.0 * x * x * x * (1.0 - progress);
    score += 6.0 * (1.0 - x) * (1.0 - x) * progress;

    // Penalize dead space relative to mean residual
    score += 0.25 * (post - mean_residual).abs();

    // Reward tight fits (small post residual) more strongly as stream progresses
    score -= 8.0 * (1.0 - x) * x * (0.5 + progress);

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening new bins early, mildly late
    if bin_residual == bin_capacity {
        let open_f = open_bins_count as f64;
        score += 12.0 * (1.0 - progress) + 4.0 * progress + 0.5 * open_f.sqrt();
    }

    // Lookahead: reward bins whose post residual can host next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post >= nx {
            score -= 5.0 * (1.0 - progress) * (nx / cap);
        } else {
            score += 3.0 * progress * (1.0 - nx / cap);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that divide capacity cleanly
    let pr = post_residual;
    if pr > 0 {
        if bin_capacity % pr == 0 {
            score -= 12.0; // perfectly divisible residual: reusable in future exact fits
        } else if pr % 10 == 0 {
            score -= 6.0;
        } else if pr < 10 {
            score += 20.0; // dead space sliver
        }
    } else {
        score -= 40.0; // perfect closure
    }

    // Integer-division thresholds: classify post_residual into capacity fractions
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    if pr >= half {
        score -= 10.0;
    } else if pr >= quarter {
        score -= 4.0;
    } else if pr > 0 {
        score += (quarter as f64 - pr as f64) * 0.5;
    }

    // Lookahead coupling: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 18.0;
            // harmonic bonus: next item exactly consumes post_residual
            if next_item_size == pr {
                score -= 25.0;
            } else if pr % next_item_size == 0 {
                score -= 8.0;
            }
        } else {
            score += (next_item_size - pr) as f64 * 0.6;
        }
    } else {
        score -= 15.0; // last item: prefer closing bins
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 22.0;
    }

    // New-bin candidate handling: only attractive when open bins are fragmented
    let is_new = bin_residual == bin_capacity;
    if is_new {
        score += 8.0 * open_bins_count as f64;
        score += mean_residual * 0.3;
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    // Stream progression: tighten packing as stream advances
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += score * 0.15 * progress;

    // Penalize bins far from mean residual (fragmentation outlier)
    score += ((post_residual as f64 - mean_residual).abs()) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

