    }

    // Last-chance bin: strongly favor using it over opening a new bin
    if fitting_bins_count == 1 {
        score -= 45.0;
    }

    // Open bins pressure: penalize opening new bins when many are open
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // new-bin candidate: only attractive if item is large or few bins open
        score += open_bins_count as f64 * 8.0;
        score -= item_size as f64 * 0.5;
        if open_bins_count == 0 {
            score -= 100.0;
        }
    } else {
        score -= open_bins_count as f64 * 1.5;
    }

    // Prefer bins below mean residual (keeps residuals balanced)
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Late in stream: be more conservative, avoid new bins
    if progress > 0.7 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
