pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fill_ratio > 0.85 {
        score -= 30.0 * (fill_ratio - 0.85);
    }

    // Penalize dead space: small post-residuals that are too small for typical future items.
    let dead_threshold = cap * 0.12;
    if post_residual as f64 > 0.0 && (post_residual as f64) < dead_threshold {
        score += 12.0 * (dead_threshold - post_residual as f64) / dead_threshold;
    }

    // Lookahead: if next item fits into post_residual, reward; else penalize.
    if next_item_size > 0 {
        if (next_item_size as u32) <= post_residual {
            score -= 8.0;
        } else {
            score += 3.0 * (next_item_size as f64 - post_residual as f64).min(20.0) / 20.0;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 4 {
        score += 2.0 * (fitting_bins_count as f64 - 4.0);
    }

    // Global state: many open bins with low mean residual -> prefer consolidation into existing bins.
    let mean_res_ratio = mean_residual / cap;
    score += mean_res_ratio * 6.0;
    if open_bins_count > 8 {
        score -= (open_bins_count as f64 - 8.0).min(10.0);
    }

    // Time horizon: early in stream, be lenient (explore); late, pack tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - fill_ratio);

    // New-bin candidate: only attractive when current bin is a poor fit.
    if bin_residual == bin_capacity {
        score = 20.0 + 15.0 * fill_ratio - 10.0 * progress;
        if fitting_bins_count <= 1 {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let tightness = 1.0 - pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let p2 = progress * progress;
    let p3 = p2 * progress;
    let poly = 1.0 + 0.9 * p2 + 0.6 * p3;

