    score -= 40.0 * tightness * tightness * (1.0 + progress);

    // Penalize dead space that is too small to be useful (smooth gate).
    let usable = if next_item_size > 0 { (post_residual as f64 / next_item_size as f64).min(1.0) } else { 1.0 };
    score -= 25.0 * usable * (1.0 - (post_residual as f64 / cap));

    // Last-chance bonus: strongly favor the single fitting bin.
    if fitting_bins_count == 1 {
        score -= 60.0 * (1.0 + 0.5 * progress);
    }

    // Mild competition pressure: more open bins -> prefer reusing.
    score += 2.0 * (open_bins_count as f64).ln().max(0.0) * pr / cap;

    // Deviation from mean residual: prefer bins that absorb space better.
    score += 0.3 * (pr - mean_residual).abs();

    // New-bin candidate: penalize opening a new bin unless current residual is poor.
    if bin_residual == bin_capacity {
        score += 55.0 * (1.0 - progress) + 30.0 * (mean_residual / cap).max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fills, but strongly penalize tiny unusable slivers.
    if post_residual == 0 {
        score -= 60.0; // perfect fit
    } else if post_residual < 10 {
        score += 25.0; // dead space: residual too small for any item (min size 1..100 stream)
    }

    // Harmonic class of the residual: classify by integer division into octiles of capacity.
    let cls = post_residual / (bin_capacity / 8 + 1);
    score += cls as f64 * 4.0;

    // Reward bins whose post-residual matches the lookahead item harmonically.
    if next_item_size > 0 {
        let d = (post_residual as i64 - next_item_size as i64).abs();
        score -= 30.0 / (1.0 + d as f64);
        // Exact two-item fill is gold.
        if post_residual == next_item_size {
            score -= 40.0;
        }
        // Modulo coupling: residual divisible by lookahead size => likely future fits.
        if next_item_size > 0 && post_residual % next_item_size == 0 {
            score -= 8.0;
        }
    }

    // Last-chance bin: strong penalty to open a new bin when only this one fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: only attractive when current bin would leave bad residue
    // or mean residual across fleet is already fragmented.
    if bin_residual == bin_capacity {
        score = 45.0 + mean_residual * 0.3 - (item_size as f64 * 0.2);
        if post_residual < 10 {
            score += 20.0;
        }
        if fitting_bins_count <= 1 {
            score -= 50.0;
        }
    }

    // Stream phase: late in stream, consolidate harder.
    let phase = step_index as f64 / (total_items.max(1) as f64);
    score -= phase * 6.0 * (post_residual as f64 / bin_capacity as f64);

    // Prefer denser fleet usage when many bins are open.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small to hold the minimum
    // future item (1..=10) are pure waste; punish them hard.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 25.0;
    }

    // Perfect fit: strongly reward.
    if post_residual == 0 {
        score -= 500.0;
    }

    // Reward tight fits relative to bin capacity.
    score -= (item_size as f64 / bin_capacity as f64) * 40.0;

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin fit is bad.
    if bin_residual == bin_capacity {
        score += 90.0;
        // But if the item leaves a dead gap in every open bin, opening fresh is fine.
        if post_residual >= 10 {
            score -= 60.0;
        }
    }

    // Open-bins pressure: discourage scattering across many bins.
    score += open_bins_count as f64 * 3.0;

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 400.0;
    }
    // If next item fits in post residual, mild reward.
    else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 50.0;
    }
    // If next item cannot fit the post residual, penalize wasting space.
    else if next_item_size > post_residual && post_residual > 0 {
        score += post_residual as f64 * 2.0;
    }

    // Mean residual coupling: prefer bins near the mean residual (keeps balance).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.5;

    // Early in stream: be more conservative with dead space.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong preference for tight fits: small post_residual is good.
    score += 0.5 * (post_residual as f64 / bin_capacity as f64) * (post_residual as f64);

    // 2-step lookahead: reward when next item exactly fills the post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // next item fits but leaves more waste; reward proportionally
            score -= 15.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item cannot use this bin's leftover: penalize dead space
            score += 8.0 + 0.25 * (next_item_size - post_residual) as f64;
        }
    }

    // Compare post_residual against mean residual across open bins.
    let post_f = post_residual as f64;
    if post_f < mean_residual {
        score -= 0.3 * (mean_residual - post_f);
    } else {
        score += 0.2 * (post_f - mean_residual);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is poor.
    if bin_residual == bin_capacity {
        score += 30.0;
        // If item is large relative to capacity, opening fresh is less bad
        score -= 0.1 * item_size as f64;
    }

    // Slight bias toward filling bins more densely as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly prefer bins where item nearly fills residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Reward small post-residual, but penalize dead space that nothing can use.
    if post_residual > 0 {
        if post_residual < 10 {
            score -= 6.0; // essentially perfect fill
        } else {
            score += (post_residual as f64) * 0.05; // wasted capacity penalty
        }
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual,
    // this is a great chain placement; penalize if next item would be blocked.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 10.0;
        } else if next_item_size > post_residual {
            score += 2.0 * (next_item_size as f64 - post_residual as f64).min(20.0);
        } else {
            score += 0.02 * (post_residual - next_item_size) as f64;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // heavily favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Time horizon: early in the stream, be conservative (prefer filling existing
    // bins); late in the stream, tightness matters relatively more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * progress * fit_ratio;

    // Crowd control: with many open bins, prefer consolidating into fuller ones.
    score += 0.01 * open_bins_count as f64 * (bin_residual as f64 - mean_residual);

    // New-bin candidate handling: an empty bin should only win when no open bin
    // offers a decent fit (item much larger than mean residual slack).
    if bin_residual == bin_capacity {
        let slack_gap = item_size as f64 - mean_residual;
        if slack_gap > 0.0 && fitting_bins_count > 0 {
            score += 15.0 + slack_gap; // discourage new bin when fits exist
        } else if fitting_bins_count == 0 {
            score -= 20.0; // must open a new bin anyway
        } else {
            score += 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr_norm = pr / cap;
    let mean_norm = mean_residual / cap;

    // Smooth non-linear polynomial coupling of post_residual with stream progress
    let t = progress * pr_norm;
    score += 6.0 * t * t - 2.0 * t * pr_norm * mean_norm;

    // Cubic term: penalize large residual waste late in stream
    score += 4.0 * pr_norm.powi(3) * (0.5 + progress);

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Lookahead: reward leaving space that still fits the next item (smooth gate)
    if next_item_size > 0 {
        let fits_next = (pr >= next_item_size as f64) as f64;
        let tightness = 1.0 - ((pr - next_item_size as f64) / cap).abs();
        score -= 5.0 * fits_next * tightness * (1.0 - progress);
    }

    // Mild penalty when many bins are open and this creates large dead space
    score += 0.05 * (open_bins_count as f64) * pr_norm * pr_norm;

    // New-bin candidate: prefer it only when no tight fit exists among open bins
    if bin_residual == bin_capacity {
        score += 8.0 - 6.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into
    // "small dead space" classes (1..=9 mod 10) are penalized.
    let pr = post_residual as i64;
    let dead = if pr > 0 && pr <= 9 { 1.0 } else { 0.0 };
    score += dead * 25.0;

    // Reward post_residuals that are multiples of 10 (likely to fit future
    // items from a coarse-grained distribution).
    if pr > 0 && pr % 10 == 0 {
        score -= 8.0;
    }

    // Reward near-perfect fits.
    if pr == 0 {
        score -= 30.0;
    }

    // Coupling with next item: if next item fits exactly into post_residual,
    // strongly favor this bin (chaining).
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        score -= 10.0 - (gap as f64).min(10.0);
        if gap == 0 {
            score -= 20.0;
        }
    }
    // Penalize if next item cannot use the leftover at all.
    if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        score += 6.0;
    }

    // Last-chance bin: strong reward to avoid opening a new bin needlessly.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize slightly so it's chosen only when open
    // bins create bad dead space; scale with stream progress and open bins.
    if bin_residual == bin_capacity {
        score += 12.0 + 5.0 * (open_bins_count as f64).ln().max(0.0);
        let progress = step_index as f64 / (total_items as f64).max(1.0);
        score += 5.0 * progress;
    }

    // Prefer bins tighter than the mean residual (best-fit flavor).
    score += 0.3 * (bin_residual as f64 - mean_residual).max(0.0);

    // Fraction-of-capacity class: leftovers in [1/3, 1/2] of capacity are
    // moderately useful; leftovers below 1/5 are nearly dead.
    let frac = post_residual as f64 / bin_capacity as f64;
    if frac > 0.0 && frac < 0.2 {
        score += 12.0;
    } else if frac >= 0.33 && frac <= 0.5 {
        score -= 4.0;
    }

    // Integer-division threshold: leftover >= 80 (fits any item) is prime space.
    if post_residual >= 80 {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest plausible
    // item are wasted forever. Penalize small-but-nonzero post_residual hard.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0; // unusable gap (< min item size) -> strong penalty
        } else if post_residual < 25 {
            score += 25.0; // very tight gap, unlikely to be reused
        } else if post_residual < 45 {
            score += 8.0;  // marginal gap
        } else {
            score -= 10.0; // large usable residual is good
        }
    } else {
        // Perfect fit: completely fills the bin, no dead space at all
        score -= 80.0;
    }

    // Reward exact or near-exact fits relative to item size
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fit_ratio > 0.9 {
        score -= 20.0 * (fit_ratio - 0.9);
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading items
    // into a new bin; encourage consolidating into existing ones.
    score += open_bins_count as f64 * 0.5;

    // Lookahead: if the next item fits into the post_residual, reward this placement
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && (post_residual as u32) < next_item_size {
        // next item cannot use this gap -> dead space likely
        score += 6.0;
    }

    // Prefer bins whose residual is close to the mean (balanced packing),
    // mildly; avoids leaving one bin with huge residual and others drained.
    score += ((bin_residual as f64 - mean_residual).abs()) * 0.1;

    // Early in the stream, allow slightly more freedom to open bins;
    // later, consolidation pressure increases.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 0.0 + progress * (bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let lookahead_waste = post_residual - next_item_size;
        score -= (bin_capacity as f64 - lookahead_waste as f64) * 0.8;
    } else if next_item_size > 0 {
        // Penalize blocking the next item.
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // Relative to mean residual: prefer bins tighter than average.
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Penalize creating small dead space that nothing can use (sizes >= 1).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Late in the stream, prefer closing out bins (reduce open bin count).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress > 0.8 && post_residual < 20 {
        score -= 15.0;
    }

    // Slight penalty for spreading across many open bins.
    score += open_bins_count as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) more than linearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 8.0 * fit_ratio * fit_ratio;

    // Penalize dead space: small post-residual is good, but a residual too
    // small for the smallest possible item (1) is only penalized mildly since
    // min item is unknown; scale penalty by how close post_residual is to zero.
    if post_residual == 0 {
        score -= 3.0; // perfect fit bonus
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 6.0;
    }

    // New-bin candidate handling: opening a new bin is attractive early in the
    // stream or when the item fits poorly everywhere. Penalize the empty bin
    // slightly so we prefer existing bins unless fit is bad or many bins open.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Later in the stream, prefer packing into existing bins more strongly.
        let new_bin_penalty = 4.0 + 6.0 * progress;
        // If item leaves a large residual in any bin, opening fresh bin may be better.
        let poor_fit = if post_residual as f64 > mean_residual { 1.0 } else { 0.0 };
        score += new_bin_penalty - 5.0 * poor_fit;
        // Few open bins and early stream: new bin is cheap.
        if open_bins_count < 3 {
            score -= 3.0;
        }
    }

    // Lookahead: if next item could use this bin's post residual, reward.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Good: leaves room for the next item.
            score -= 2.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Post residual too small for next item: penalize proportionally.
            score += 1.5 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    }

    // Global state coupling: high mean residual means bins are loose;
    // prefer bins below mean residual (tighter bins) for tight fits.
    score += 0.5 * (mean_residual - bin_residual as f64).max(-10.0).min(10.0) * 0.1;

    // Slight preference to fill bins with more content already (fewer open bins is better).
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;
    let is_new = (bin_residual == bin_capacity) as f64;

    let mut score = pr;

    // Non-linear coupling of post_residual with stream progress:
    // late in the stream, prefer tight fits more aggressively.
    score += 40.0 * pr_norm * pr_norm * (0.5 + progress);

    // Penalize large residuals more than linearly (quadratic dead-space term).
    score += 0.15 * pr * pr / cap;

    // Reward near-perfect fits with a smooth saturating bonus.
    let tightness = 1.0 - pr_norm;
    score -= 30.0 * tightness * tightness * tightness;

    // Lookahead: bonus if the next item fits into post_residual (smooth interaction).
    if next_item_size > 0 {
        let fits_next = (next_item_size as f64 <= pr) as f64;
        let gap = (pr - next_item_size as f64).abs();
        score -= 12.0 * fits_next * (1.0 - gap / cap);
        score += 6.0 * (1.0 - fits_next) * (pr_norm * pr_norm);
    }

    // Last-chance bin: strongly favor using it (smoothly weighted by progress).
    if fitting_bins_count == 1 {
        score -= 20.0 + 25.0 * progress;
    }

    // New-bin candidate: penalize early, allow late in stream or when open bins are crowded.
    let crowd = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
    score += is_new * (35.0 * (1.0 - progress) * (1.0 - crowd) + 10.0 * (1.0 - progress));

    // Mild dispersion penalty: avoid bins far from mean residual.
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small residue" classes are penalized (dead space), while leftovers
    // that match common item sizes are rewarded.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Integer-division thresholds: leftover buckets of capacity/10.
    let bucket = post_residual / (bin_capacity / 10).max(1);
    match bucket {
        0 => score -= 30.0,            // near-perfect fit
        1 => score -= 12.0,            // good fit
        2 => score += 2.0,             // mediocre
        3 => score += 8.0,             // poor
        _ => score += 15.0,            // mostly empty, wasteful use
    }

    // Modulo-4 harmonic class of post_residual: leftover congruence classes
    // that align with typical item granularity get a bonus.
    let class = post_residual % 4;
    score -= (3 - class as i32) as f64 * 2.0;

    // Lookahead coupling: reward leftovers that can host the next item exactly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            score -= 10.0 - (slack.min(10) as f64);
            if post_residual == next_item_size {
                score -= 25.0; // perfect lookahead match
            }
        } else {
            score += 6.0; // leftover too small for the incoming item
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when the item is huge relative to
    // capacity or the stream is early and many bins will follow.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let big_item = (item_size as f64) / cap;
        score = cap * 0.35 + big_item * 40.0 - progress * 20.0;
        if item_size > bin_capacity * 3 / 4 {
            score -= 35.0; // huge items deserve fresh bins
        }
    }

    // Mild tie-break toward consolidating into fewer bins.
    score += (open_bins_count as f64).ln().max(0.0) * 0.5;

    // Prefer bins below the mean residual (tighter bins first).
    score += (mean_residual - pr) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever
    // hold a realistic future item are pure waste -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 45.0 + (10 - post_residual) as f64 * 3.0;
    }
    // Moderately small gaps (10..=20) are risky too, milder penalty.
    if post_residual >= 10 && post_residual <= 20 {
        score += 8.0;
    }

    // Reward a perfect / near-perfect fill.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Tight-fit bonus: filling most of the bin is desirable.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 12.0;

    // Last-chance pressure: if this is the only bin that fits, avoid
    // forcing a bad placement unless the fit is genuinely tight.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0 + post_residual as f64 * 0.2;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // bins with larger residuals rather than spreading thin.
    score += open_bins_count as f64 * 0.35;

    // Lookahead: if the next item fits exactly in the post-residual,
    // strongly favor this bin (chained packing).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack < 10 {
            score -= 25.0;
        } else {
            score -= 6.0;
        }
    }
    // If next item would NOT fit here, slight penalty for blocking chains.
    if next_item_size > post_residual && next_item_size > 0 {
        score += 3.0;
    }

    // New-bin candidate: only attractive when all open bins would leave
    // terrible dead space (post_residual small) or nothing fits well.
    if bin_residual == bin_capacity {
        let worst_open = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        score += 18.0 + worst_open * 0.0 - fill_ratio * 4.0;
        // Opening early in the stream or when bins are nearly full is fine.
        if fitting_bins_count > 0 {
            score += 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
