}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) non-linearly.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 8.0 * tight * tight;

    // Penalize dead space: residuals too small for any future item (1..100).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if next item fits exactly in post_residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 6.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; mild penalty for wasting space.
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Global state coupling: when many bins are open, prefer consolidation;
    // when few bins are open, allow opening new bins more freely.
    let openness = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
    score += 0.4 * openness;

    // New-bin candidate: penalize opening a new bin unless the item is large
    // or existing residuals are poor (mean_residual low relative to item).
    if bin_residual == bin_capacity {
        let avg_fit = mean_residual / item_size as f64;
        let progress = step_index as f64 / total_items.max(1) as f64;
        let new_bin_penalty = 18.0 - 10.0 * avg_fit.clamp(0.0, 2.0) - 6.0 * progress;
        score += new_bin_penalty.max(-5.0);
    }

    // Time horizon: later in the stream, tighten up and avoid new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 4.0 * progress * tight;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_norm = pr / cap;

    // Base: prefer tight fits via quadratic in post_residual.
    let mut score = fit_norm * fit_norm * cap;

    // Smooth non-linear coupling: post_residual penalized more as stream progresses
    // (early on, residual space is valuable; late, dead space is worse).
    let progress_coupling = (0.5 + 1.5 * progress) * fit_norm * fit_norm * fit_norm * cap;
    score += progress_coupling;

    // Interaction with mean residual: if this bin's post-residual is far below the
    // mean, it's a good consolidation; reward it smoothly.
    let dev = (pr - mean_residual) / cap;
    score += 3.0 * dev;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // (smoothly scaled by how well it fits).
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 - fit_norm);
    }

    // Lookahead coupling: reward leaving room (or none) compatible with next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt).abs() / cap;
        score += 4.0 * gap * gap;
    } else {
        // Last item: just minimize residual.
        score -= 2.0;
    }

    // Mild penalty for proliferation of open bins with large leftover space.
    let bins_f = open_bins_count as f64;
    score += 0.05 * bins_f * fit_norm;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Harmonic class of post_residual: reward residuals in "usable" classes
    // (>= 10 so they can accept typical future items), penalize dead space.
    let pr = post_residual as f64;
    if post_residual == 0 {
        score -= 60.0; // perfect fit is ideal
    } else if post_residual < 10 {
        score += 45.0; // unusable dead space penalty
    } else {
        // reward residuals that are multiples of common item classes (10..80)
        let mod10 = post_residual % 10;
        score -= (10 - mod10 as i32) as f64 * 0.8;
        // fractional capacity-fraction classes
        let frac = pr / cap;
        if frac < 0.2 {
            score += 18.0;
        } else if frac < 0.5 {
            score -= 6.0;
        }
        // integer-division thresholds: residual / 10 class
        let class = post_residual / 10;
        score -= (class as f64) * 0.5;
    }

    // Lookahead coupling: does this bin's post_residual fit the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 8.0;
        }
        // harmonic class match: next item mod 10 vs residual mod 10
        if next_item_size % 10 == post_residual % 10 && post_residual >= next_item_size {
            score -= 5.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current residuals are tight
    if bin_residual == bin_capacity {
        let tight = (mean_residual / cap) < 0.25;
        let late = (step_index as f64) / (total_items.max(1) as f64) > 0.8;
        if tight || late {
            score += 5.0;
        } else {
            score += 35.0 + open_bins_count as f64 * 2.0;
        }
    }

    // Mild preference for tightest existing bins
    score -= (bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space: gaps too small for the smallest plausible item
    if post_residual > 0 && post_residual < 10 {
