    }

    // Reward perfect or near-perfect fits
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; favor tighter fills
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (0.3 + 0.5 * progress);

    // Mild pull toward bins with below-average residual (denser bins)
    score += (mean_residual - bin_residual as f64) * 0.15;

    // New-bin candidate: make it unattractive unless current placements are very bad
    if bin_residual == bin_capacity {
        score += 20.0 + open_bins_count as f64 * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 500.0;
    }

    // 2-step lookahead: reward when next item fits exactly into post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 300.0;
        } else if post_residual >= next_item_size {
            // next item fits: mild reward proportional to how well it fits
            let slack = (post_residual - next_item_size) as f64;
            score -= 100.0 - slack.min(100.0);
        } else {
            // next item does not fit: penalize wasted residual slightly
            score += 20.0;
        }
    }

    // Compare post_residual against mean residual: prefer bins that tighten
    // residuals toward the mean (good packing balance)
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.3 * dev;

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // Penalize creating large unusable dead space relative to typical item sizes
    if post_residual > 0 && post_residual < 10 {
        score -= 50.0; // small dead space is fine (near-perfect fit)
    } else if post_residual >= 10 && post_residual < 40 {
        score += 0.2 * (post_residual as f64 - 10.0);
    }

    // Late in stream: be more aggressive about filling existing bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 40.0 * progress;

    // Many open bins: prefer consolidation into existing bins
    score += 0.5 * open_bins_count as f64;

    // New-bin candidate: penalize opening a new bin unless residuals are messy
    if bin_residual == bin_capacity {
        score += 60.0 + 5.0 * open_bins_count as f64;
        // allow new bin if lookahead suggests it's useful (big item, next big)
        if next_item_size >= item_size && item_size > bin_capacity / 2 {
            score -= 80.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic bonus for small post-residual
    score -= (bin_capacity as f64 - post_residual as f64) * 0.15;

    // Penalize dead space that cannot fit a typical future item
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 + 0.3 * next_item_size as f64;
        } else {
