    }

    // Time horizon: early in stream, prefer filling existing bins; late, be greedy
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.5 * progress;

    // Many open bins: encourage consolidation into low-residual bins
    score += 0.2 * (mean_residual - post_residual as f64);

    // New-bin candidate: penalize slightly unless current bin fit is poor
    if bin_residual == bin_capacity {
        let poor_fit = (post_residual as f64) > 40.0;
        if poor_fit {
