}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let fit_frac = post / cap;

    // Base: prefer small post-residual, with smooth polynomial shaping
    let mut score = post * (1.0 + 0.8 * fit_frac * (1.0 - fit_frac));

    // Progress coupling: later in stream, penalize larger residuals more strongly
    score += 12.0 * progress * fit_frac * fit_frac;
    score -= 6.0 * (1.0 - progress) * fit_frac;

    // Dead-space penalty: residuals too small for typical future items
    let dead = (fit_frac - 0.1).max(0.0) * (0.2 - fit_frac).max(0.0);
    score += 40.0 * dead * (1.0 + progress);

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - 0.5 * progress);
    }

    // Lookahead: reward if next item fits the post-residual well
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= post {
            let slack = (post - nx) / cap;
            score -= 15.0 * (1.0 - slack) * (1.0 - progress);
        } else {
            score += 8.0 * ((nx - post) / cap) * (1.0 - progress);
        }
    }

    // New-bin candidate: make empty bin mildly attractive only when current fit is poor
    if bin_residual == bin_capacity {
        score = 55.0 - 20.0 * progress + 0.3 * (open_bins_count as f64);
        if fitting_bins_count <= 1 {
            score -= 30.0;
        }
    }

    // Mild tie-break toward consolidating into fewer bins
    score += 0.05 * (open_bins_count as f64) * fit_frac;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how it partitions the capacity
    let pr = post_residual;
    let class = pr % 10;
    // Dead space penalty: residuals that can't hold typical small items (1..=10 range)
    // are penalized super-linearly via harmonic-like terms.
    if pr > 0 {
        // harmonic number H_pr scaled: penalize leaving awkward slivers
        let mut h = 0.0;
        let k = (pr / 10).min(10);
        for i in 1..=k {
            h += 1.0 / i as f64;
        }
        score += 6.0 * h * (1.0 - (pr as f64) / cap_f);
        // modulo classes: residuals in {1..9} mod 10 are nearly dead space
        if class > 0 && class < 10 {
            score += (10 - class) as f64 * 1.5;
        }
    } else {
        // perfect fit: strong reward
        score -= 40.0;
    }

    // Integer-division thresholds on post_residual
    if pr >= 50 {
        score -= 12.0; // still half-capacity useful
    } else if pr >= 30 {
        score -= 4.0;
    } else if pr > 0 {
        score += 8.0; // small sliver
    }

    // Lookahead: does the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 10.0;
            // bonus if next item's residue class harmonizes (mod 10)
            if (next_item_size % 10) == pr % 10 {
                score -= 6.0;
            }
            // exact chain: post_residual equals next item size
            if next_item_size == pr {
                score -= 15.0;
            }
        } else {
            // next item won't fit here; penalize slightly less if residual still large
            score += 3.0 + (next_item_size - pr) as f64 * 0.2;
        }
    } else {
        // last item: prefer near-perfect fills
        score -= (cap_f - (pr as f64)) * 0.1;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: prefer reusing open bins when mean residual is high
    if bin_residual == bin_capacity {
        // opening a new bin: penalize when existing bins could absorb the item
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 25.0 + 20.0 * (1.0 - progress) + open_bins_count as f64 * 2.0;
        if mean_residual > item_size as f64 {
            score += 15.0;
        }
        // but allow new bin if item is huge and mean residual is low
        if item_size > 60 && mean_residual < 30.0 {
            score -= 45.0;
        }
    }

    // Mild tie-break toward fuller bins (low residual)
    score += (bin_residual as f64) * 0.05;

    // Mean residual coupling: if this bin is much fuller than average, reward
    score -= (mean_residual - bin_residual as f64).max(0.0) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are the worst outcome.
    // Define "unusable" as a gap smaller than the smallest plausible item (1..100 range,
    // but treat gaps below ~10 as dead since tiny items are rare).
    let dead_threshold: f64 = 10.0;
    let pr = post_residual as f64;

    if pr > 0.0 && pr < dead_threshold {
        // Severe penalty for creating a sliver of dead space.
        score += (dead_threshold - pr) * 8.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0; // exact fill is ideal
    } else if (pr as u32) <= item_size / 4 && pr < 25.0 {
        score -= 25.0; // very tight fit
    }

    // Moderate residual is preferred over huge residual (waste) but also
    // over tiny residual (dead space): quadratic shaping around a sweet spot.
    let sweet_spot = 30.0;
    score += 0.02 * (pr - sweet_spot) * (pr - sweet_spot);

    // Lookahead: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual > next_item_size {
            score -= 5.0;
        } else {
            // next item cannot use the remaining gap -> mild penalty proportional to gap
            score += pr * 0.3;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits to avoid
    // opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Open bins pressure: with many open bins, prefer filling existing ones
    // over spreading; penalize less when few bins are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (1.5 + 2.0 * progress);

    // New-bin candidate (empty bin): only attractive when existing bins would
    // leave bad dead space or no bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by how badly existing
        // bins would fit (proxy: mean residual vs item size).
        let fit_badness = (mean_residual - item_size as f64).max(0.0);
        score = 120.0 - fit_badness * 0.8 - (fitting_bins_count as f64) * 5.0;
        // Early in the stream, opening bins is cheaper; late, prefer consolidation.
        score += 40.0 * progress;
    }

    // Slight preference for bins whose residual is close to mean (balance).
    score += 0.05 * ((bin_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
