        score += 25.0;
        if next_item_size > 0 && (post_residual as f64) <= (next_item_size as f64) {
            score -= 30.0; // fresh bin pairs well with the upcoming item
        }
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Slight preference for fuller bins over emptier ones.
    score += (bin_residual as f64 / bin_capacity as f64) * 10.0;

    // Stream progression: tighten packing as the stream advances.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual)
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += fit_ratio * fit_ratio * 40.0;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Penalize dead space that no future item can use (items >= 1, min item 1)
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // tiny unusable sliver
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 70.0;
        } else if next_item_size <= post_residual {
            score -= (next_item_size as f64 / post_residual as f64) * 20.0;
        } else {
            // next item won't fit here; slight penalty proportional to waste
            score += (next_item_size as f64 - post_residual as f64).min(30.0) * 0.3;
        }
    }

    // Time horizon: early in stream, prefer keeping residuals flexible (large post_residual);
    // late in stream, prefer consolidation into few bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 12.0 * (post_residual as f64 / bin_capacity as f64);

    // Crowding: many open bins -> prefer filling existing bins over opening new ones
    if open_bins_count > 4 {
        score -= (open_bins_count as f64).ln() * 6.0;
    }

    // Global residual context: if this bin's residual is far below mean, it's an outlier
    // worth filling down; if far above mean, keep it for future items.
    let res_f = bin_residual as f64;
    let dev = res_f - mean_residual;
    score += dev * 0.15 * (1.0 - progress);

    // New-bin candidate: make empty bin attractive only when it's genuinely better
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin
        score += 55.0;
        // But discount when current bins are crowded or fit is poor
        let poor_fit = if fitting_bins_count > 0 {
            let best_possible = mean_residual.max(1.0);
            (best_possible - item_size as f64).abs()
        } else {
            0.0
        };
        score -= poor_fit * 0.5;
        // Late in stream with many open bins, opening new bin is wasteful
        score += progress * 20.0;
        // Large items early: new bin can be fine
        if item_size > bin_capacity / 2 && progress < 0.3 {
            score -= 18.0;
        }
    }

    // Mild preference for bins with residual close to item size (tight but not forced)
    let slack = (bin_residual - item_size) as f64;
    score += (slack / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early stream: mild preference for tight fits; late stream: strong penalty on dead space.
    let norm_pr = pr / cap;
    let poly = norm_pr * norm_pr * (1.0 + 3.0 * progress) + norm_pr * progress * progress;
    score += 12.0 * poly;

    // Reward filling a bin exactly (post_residual 0) with a smooth bonus.
    let exact = (cap - pr) / cap;
    score -= 8.0 * (exact * exact) * (0.5 + progress);

    // Penalize creating residual that cannot fit the lookahead item smoothly.
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).max(0.0);
        let dead = 1.0 - gap / cap;
        score += 6.0 * dead * dead * progress;
    }

    // Last-chance bin bonus: fewer fitting bins -> stronger incentive to use this one.
    let scarcity = 1.0 / (fitting_bins_count as f64 + 1.0);
    score -= 10.0 * scarcity * (0.5 + progress);

    // Mild coupling with mean residual: prefer bins near the mean (balanced packing).
    let dev = (pr - mean_residual).abs() / cap;
    score += 3.0 * dev * dev;

    // Slight penalty for opening new bins as the stream progresses.
    if bin_residual == bin_capacity {
        score += 5.0 * (1.0 - progress) + 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover lies in small
    // modulo classes (hard-to-fill dead space) get penalized.
    let pr = post_residual;
    let class_penalty = match pr {
        0 => -30.0,                       // perfect fit: huge reward
        1..=5 => 8.0,                     // tiny slivers = dead space
        6..=10 => 3.0,
        _ => {
            // harmonic fraction of capacity used
            let used = (bin_capacity - pr) as f64 / bin_capacity as f64;
            let frac = 1.0 / (1.0 + used); // harmonic weighting
            frac * 4.0
        }
    };
    score += class_penalty;

    // Integer-division thresholds on post_residual vs next_item_size:
    // reward when next item can fit into the post residual.
    if next_item_size > 0 {
        if next_item_size <= pr {
            // next item fits: check pairing quality via integer division
            let q = pr / next_item_size.max(1);
            score -= 6.0 + (q as f64) * 1.5;
        } else {
            // next item cannot fit here; penalize more if this bin
            // would be left nearly empty of usable space
            let waste_ratio = next_item_size as f64 / bin_capacity as f64;
            score += waste_ratio * 10.0;
        }
    }

    // Modulo arithmetic on post_residual: multiples of common item
    // granularity (10) are "harmonic" and more reusable.
    if pr % 10 == 0 && pr > 0 {
        score -= 4.0;
    }
    if pr % 5 == 0 && pr > 0 {
        score -= 1.5;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: only attractive when current bins have low
    // residuals relative to the item (poor fits elsewhere) or late stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let tight = mean_residual < item_size as f64 * 1.2;
        if tight {
            score -= 8.0;
        } else {
            score += 10.0 + 5.0 * (1.0 - progress);
        }
        // prefer new bin if item is large (hard to place later)
        if item_size >= 60 {
            score -= 4.0;
        }
    }

    // Prefer fuller bins: reward low residual relative to mean.
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    } else {
        score += 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // smallest plausible item (1..100 stream) are pure waste.
    if post_residual > 0 {
        let dead_threshold = 10.0_f64.max(next_item_size as f64);
        if (post_residual as f64) < dead_threshold {
            score += 60.0 + 3.0 * (dead_threshold - post_residual as f64);
        }
        // Perfect fit: zero waste is highly desirable.
        if post_residual == 0 {
            score -= 80.0;
        }
    }

    // Reward bins whose residual closely matches the item (tight packing).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += 0.5 * tightness;

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading items
    // into fresh bins; prefer reusing existing capacity.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.08 * open_bins_count as f64 * (0.5 + progress);

    // Lookahead: if the next item fits into the post-residual, reward this
    // placement for enabling a chain of placements.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.2 * next_item_size as f64;
    } else if next_item_size > 0 {
        // Next item won't fit here: penalize leaving a mismatched gap.
        score += 8.0;
    }

    // Mean-residual coupling: bins far below the mean residual are good
    // candidates to drain; bins far above are wasteful targets.
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // New-bin candidate: only attractive when no open bin fits well
    // (i.e. this is a fresh empty bin and few bins can host the item).
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: new bin is mandatory anyway
        } else {
            // Opening a new bin costs; penalize proportional to open bins.
            score += 25.0 + 0.5 * open_bins_count as f64;
        }
    }

    score
}

