    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (low post residual)
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, tolerate slack; later, punish dead space quadratically.
    let slack_penalty = norm_pr * norm_pr * (1.0 + 3.0 * progress) * cap;
    score += slack_penalty;

    // Smooth reward for near-perfect fits, stronger as stream progresses.
    let perfect = (1.0 - norm_pr).powi(3);
    score -= 12.0 * perfect * (0.5 + progress);

    // Last-chance bin bonus (smooth, not piecewise)
    let last_chance = if fitting_bins_count <= 1 { 1.0 } else { 0.0 };
    score -= 8.0 * last_chance * (1.0 - norm_pr) * (1.0 + progress);

    // Lookahead coupling: reward leaving room shaped like the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt).abs();
        let shape_match = 1.0 - (gap / cap).min(1.0);
        score -= 6.0 * shape_match * shape_match;
    } else {
        // Last item: strongly prefer filling existing bins
        score -= 5.0 * (1.0 - norm_pr);
    }

    // Mild pressure to consolidate when many bins are open
    let open_pressure = (open_bins_count as f64).ln1p();
    score -= 2.0 * open_pressure * (1.0 - norm_pr);

    // Deviation from mean residual: prefer bins near the mean to keep balance
    let dev = (pr - mean_residual) / cap;
    score += 4.0 * dev * dev * cap * (0.3 + 0.7 * progress);

    // New-bin candidate: penalize opening a bin when others fit, smoothed.
    let is_new = (bin_residual as f64 - cap).abs() < 0.5 && item_size > 0;
    if is_new {
        score += 10.0 + 20.0 * progress + 3.0 * open_pressure;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

