    if post_residual >= 10 && post_residual < 20 {
        score += 6.0;
    } else if post_residual >= 20 && post_residual < 40 {
        score += 2.0;
    }

    // Lookahead coupling: if next item fits the post residual, big reward.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
