            score += (next_item_size as f64 - post_residual as f64) * 0.35;
        }
        // Harmonic check: next item leaves a further nice class (multiple of 10).
        if next_item_size <= post_residual {
            let two_step = post_residual - next_item_size;
            if two_step % 10 == 0 && two_step > 0 {
                score -= 8.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when all open bins are nearly full.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        // Low mean residual => open bins are crowded, new bin is fine.
        score += 30.0 * pressure + (open_bins_count as f64) * 0.5;
        if next_item_size > 0 && next_item_size >= 50 {
            score -= 5.0; // big next item: fresh bin useful
        }
    }

    // Exact fill reward (perfect packing).
    if post_residual == 0 {
        score -= 15.0;
    }

    // Mild progression term: late in the stream, be greedier about tight fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_residual - post_residual) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
