    let base = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) * cap
             - norm_pr * progress * cap * 0.5;

    // Dead-space penalty: tiny residuals are wasted space
    let dead = if pr > 0 && pr < 10 {
        (10.0 - pr) * (1.0 + progress)
    } else { 0.0 };

    // Reward near-perfect fits
    let fit_bonus = if pr == 0 { cap } else { 0.0 };

    // Last-chance bin: strongly favor using it before opening a new bin
    let last_chance = if fitting_bins_count == 1 { cap * (1.0 + progress) } else { 0.0 };

    // Lookahead: penalize leaving residual too small for next item, reward leaving room
    let look = if next_item_size > 0 {
        if pr >= next_item_size as f64 {
            -((pr - next_item_size as f64) / cap) * 20.0 * (1.0 - progress)
        } else {
            (next_item_size as f64 - pr) / cap * 30.0
        }
    } else { 0.0 };

    // Mild penalty when many bins already open (encourage consolidation)
    let spread = (open_bins_count as f64).ln() * 2.0;

    // Deviation from mean residual: prefer bins near/below mean (keeps residuals balanced)
    let mean_dev = (pr - mean_residual).abs() * 0.1;

    base + poly + dead - fit_bonus - last_chance + look + spread + mean_dev
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the item: coarse size classes via integer division
    let item_class = item_size / 10;
    let next_class = (next_item_size as u32) / 10;

    // Reward tight fits: post_residual in "good" harmonic classes (small dead space)
    let pr = post_residual as u32;
    if pr == 0 {
        score -= 60.0; // perfect fill
    } else if pr <= 10 {
        score -= 25.0; // near-perfect, still usable for small items
    } else {
        // Penalize dead space that cannot host the next item (harmonic mismatch)
        if next_item_size > 0 && pr < next_item_size {
            score += (next_item_size - pr) as f64 * 0.8;
        } else if next_item_size > 0 && pr >= next_item_size {
            score -= 8.0; // post-residual can host next item
        }
    }

    // Modulo arithmetic on post_residual: residuals that are multiples of common
    // small item sizes (10/20/25/50) remain "harmonically usable".
    let harmonically_usable = pr % 10 == 0 || pr % 25 == 0 || pr % 50 == 0;
    if harmonically_usable && pr > 0 {
        score -= 6.0;
    } else if pr > 0 && pr < 10 {
        score += 5.0; // tiny sliver, nearly dead space
    }

    // Fraction of capacity remaining as residual
    let frac = post_residual as f64 / cap;
    score += frac * 15.0; // prefer filling bins more fully

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current bin
    // would leave a bad residual class or the item is huge.
    if bin_residual == bin_capacity {
        // New empty bin: neutral baseline with mild penalty so existing good fits win
        score += 20.0;
        if item_size >= 60 {
            score -= 15.0; // large items are fine in fresh bins
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open
        }
    }

    // Lookahead coupling: if next item is large and this bin's post-residual
    // cannot host it, prefer to save larger-residual bins (penalize slightly less
    // than dead-space penalty to keep ordering sane).
    if next_item_size > 0 && post_residual < next_item_size && bin_residual < bin_capacity {
        score += 4.0;
    }

    // Stream progression: early on, be greedy about tight fits; late, consolidate
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * (post_residual as f64) * 0.1;

    // Class alignment bonus: item and next item in same harmonic class favor
    // stacking in the same bin family
    if next_item_size > 0 && item_class == next_class && post_residual >= next_item_size {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item.max(next_item_size.min(item_size)) {
        // gap too small for any future item -> dead space
        score += 40.0;
    }
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        score += 15.0; // cannot host the lookahead item
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 100.0;
    } else {
        let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
        score -= 20.0 * fill_ratio;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage spreading across many open bins when
    // mean residual is low (bins nearly full already).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score += (open_bins_count as f64) * (1.0 - progress) * 2.0;
        // Prefer bins whose residual deviates below the mean (consolidate fuller bins).
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        }
    } else {
        // New-bin candidate: only attractive when item is huge relative to residual
        // of typical open bins or no good fit exists.
        score += 10.0 + 5.0 * progress;
    }

    // Lookahead synergy: reward leaving exactly room for the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong penalty for large dead space after placement (wasted capacity).
    let post = post_residual as f64;
    if post > 0.0 {
        score += (post * post) / (bin_capacity as f64);
    }

    // Perfect fit bonus: post_residual == 0 is ideal.
    if post_residual == 0 {
        score -= 50.0;
    }

    // 2-step lookahead: reward if next item exactly matches post_residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        score += diff * 0.9;
        if post_residual == next_item_size {
            score -= 60.0; // chain fit: this bin will be exactly filled next step
        }
        // Penalize leaving residual too small for next item (dead space trap),
        // unless residual is near zero anyway.
        if next_item_size > post_residual && post_residual > 0 {
            let waste = nxt - post;
            score += waste * 0.5;
        }
    }

    // Relative to mean residual: prefer bins tighter than average when post
    // residual stays usable, but avoid draining already-small bins.
    let mr = mean_residual.max(1.0);
    let rel = post / mr;
    if rel < 1.0 {
        score -= (1.0 - rel) * 8.0; // tighter than average is good
    } else {
        score += (rel - 1.0) * 4.0; // looser than average is worse
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly favor using it to avoid opening a new bin for a small remainder.
    if fitting_bins_count <= 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // and no good chain is available.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin: proportional to remaining item size.
        score += 25.0;
        if item_size as f64 > 0.7 * bin_capacity as f64 {
            score -= 30.0; // large items fit naturally in fresh bins
        }
        if next_item_size > 0 && next_item_size as f64 >= post_residual as f64 {
            score -= 10.0; // fresh bin leaves a residual the next item can use
        }
    }

    // Early in the stream, be slightly more willing to open bins for flexibility.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= (1.0 - progress) * 5.0 * (open_bins_count as f64).sqrt().recip();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (low post-residual), superlinear.
    let cap = bin_capacity as f64;
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 12.0 * tightness * tightness;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize creating dead space that no plausible item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // tiny unusable sliver
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / cap);
        } else {
            // Next item won't fit here; slight penalty if we leave large gap anyway.
            score += 3.0;
        }
    }

    // New-bin candidate handling: penalize opening a new bin, but relax when
    // existing residuals are large (poor fits everywhere) or late in stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 20.0;
        // If mean residual is high, open bins are wasteful; new bin is fine.
        score -= (mean_residual / cap).min(1.0) * 18.0;
        // Early in stream, opening bins is cheaper (more future items to fill them).
        score -= 10.0 * (1.0 - progress);
        // If many bins already fit the item, opening a new one is rarely needed.
        if fitting_bins_count > 2 {
            score += 8.0;
        }
    }

    // Prefer using bins whose residual deviates from the mean toward fullness.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 4.0 * dev;

    // Mild pressure to consolidate when many bins are open.
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_post = pr / cap;

    // Base: prefer tight fits, scaled by smooth polynomial in post_residual
    let mut score = pr + 40.0 * norm_post * norm_post;

    // Non-linear coupling of post_residual with stream progress:
    // early on, tolerate loose fits (fill fresh bins); late, penalize waste harder
    let waste_penalty = 60.0 * norm_post * (0.25 + 0.75 * progress * progress);
    score += waste_penalty;

    // Smooth interaction: post_residual vs mean residual (avoid fragmenting similar bins)
    let mean_gap = (mean_residual - pr) / cap;
    score += 25.0 * mean_gap * mean_gap.abs();

    // Dead-space threshold effect, smoothed via sigmoid-like polynomial
    let dead = (norm_post - 0.2).max(0.0);
    score += 80.0 * dead * dead * (1.0 + progress);

    // Last-chance bonus: strongly reward using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 55.0 + 30.0 * progress;
    }

    // Lookahead: reward residual that can host the next item, smoothly
    if next_item_size > 0 {
        let fits_next = if pr >= next_item_size as f64 { 1.0 } else { 0.0 };
        let next_norm = next_item_size as f64 / cap;
        let tightness = (norm_post - next_norm).abs();
        score -= 35.0 * fits_next * (1.0 - tightness) * (0.5 + 0.5 * progress);
    }

    // Mild pressure to prefer fewer open bins when fits are plentiful
    score += 3.0 * (open_bins_count as f64).ln().max(0.0) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues mod 10 define
    // "companion slots" for typical small items (1..100 stream).
    let post = post_residual as i64;
    let cap = bin_capacity as f64;
    let fill = 1.0 - (post_residual as f64) / cap;

    // Reward tight fits: post_residual in a small harmonic class.
    let class = post % 10;
    if post == 0 {
        score -= 50.0; // perfect fit
    } else if class == 0 {
        score -= 12.0; // residue is a multiple of 10 -> easy to fill later
    } else if class <= 3 {
        score -= 4.0; // small dead space, likely fillable
    } else if class >= 7 {
        score += 6.0; // awkward residue band
    }

    // Penalize large wasted residuals relative to capacity fraction.
    if post_residual as f64 > 0.5 * cap {
        score += 8.0 * (post_residual as f64 / cap);
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual as u32 {
            score -= 30.0;
        } else if next_item_size < post_residual as u32 {
            let next_class = (post_residual as u32 - next_item_size) % 10;
            if next_class == 0 {
                score -= 10.0;
            }
            score -= 3.0;
        } else {
            // next item won't fit here; mild penalty if this bin was the only option
            if fitting_bins_count <= 1 {
                score += 5.0;
            }
        }
    }

    // Last-chance bonus: avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only prefer it when no open bin is a good fit.
    if bin_residual == bin_capacity {
        let spread = (mean_residual - post_residual as f64).abs();
        score += 20.0 + 0.5 * open_bins_count as f64 + spread * 0.1;
        // late in stream, prefer reusing bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 25.0 * progress;
    }

    // Mild pressure toward fuller bins as stream progresses.
    score -= 5.0 * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in small unusable gaps is heavily penalized.
    // A residual is "dead" if it is too small to hold even a minimal future item.
    if post_residual > 0 {
        if post_residual < 10 {
            // Unusable gap below the minimum item size: total dead space.
            score += 60.0;
        } else if post_residual <= 20 {
            // Very small gap: likely dead weight.
            score += 25.0;
        } else if post_residual <= 35 {
            // Marginal gap: moderate penalty.
            score += 8.0;
        } else {
            // Usable residual: mild reward scaled by usefulness.
            score -= 6.0;
        }
    } else {
        // Perfect fill: strongly reward.
        score -= 40.0;
    }

    // Reward tight fits: fraction of bin filled by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill_ratio;

    // Open-bin pressure: when many bins are open, discourage spreading; when few bins,
    // slightly favor using existing bins over opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / 20.0);
    score += 0.6 * pressure * (0.5 + progress);

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < 10.0 {
            score -= 25.0; // next item nearly perfect fit
        } else if slack <= 25.0 {
            score -= 12.0;
        } else {
            score -= 4.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        // Next item cannot use this residual: penalize leaving a gap it can't use.
        score += 10.0;
    }

    // New-bin candidate handling: make an empty bin attractive only when current
    // placement would waste a lot of space or mean residuals are already bloated.
    if bin_residual == bin_capacity {
        let waste = post_residual as f64;
        // Base cost of opening a new bin, discounted by how bad existing options are.
        score = 35.0 + waste * 0.3 - (mean_residual - 30.0).max(0.0) * 0.5;
        if fitting_bins_count == 0 {
            score -= 50.0; // no alternative, must open
        }
        if next_item_size > 0 && post_residual >= next_item_size && (post_residual - next_item_size) < 10 {
            score -= 15.0; // fresh bin can chain the next item tightly
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: strongly favor bins whose residual is fully consumed.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual exactly matches the next item,
    // penalize post_residuals that are small-but-unusable relative to the next item.
    if next_item_size > 0 {
        let post = post_residual as f64;
        let nxt = next_item_size as f64;
        if post_residual == next_item_size {
            score -= 500.0; // chain fit: this bin becomes perfectly reusable
        } else if post_residual >= next_item_size {
            // slack reward: bigger usable leftover after chaining
            score -= 0.3 * (post - nxt).min(30.0);
        } else {
            // dead space: leftover too small for the next item
            score += 0.6 * (nxt - post).min(20.0);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Penalize wasting a large bin residual on a small item when other bins exist.
    let waste = (bin_residual as f64 - item_size as f64).max(0.0);
    score += 0.2 * waste * (open_bins_count as f64 / (open_bins_count as f64 + 3.0));

    // Prefer bins tighter than the mean residual (best-fit flavor).
    score -= 0.15 * (mean_residual - bin_residual as f64);

    // New-bin candidate: penalize opening a new bin unless the item is large
    // relative to capacity and no good open option exists.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items as f64).max(1.0);
        let size_ratio = item_size as f64 / bin_capacity as f64;
        let open_penalty = 60.0 + 40.0 * (1.0 - progress);
        let size_relief = 70.0 * size_ratio * size_ratio; // big items justify new bins
        let last_chance_relief = if fitting_bins_count == 1 { 0.0 } else { 0.0 };
        let _ = last_chance_relief;
        score += open_penalty - size_relief;
        // If the next item chains perfectly into a fresh bin, soften slightly.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize small post-residual quadratically.
    score -= (bin_capacity as f64 - post_residual as f64).powi(2) * 0.05;

    // Penalize leaving dead space that is too small for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    }
    // Penalize if next item would fit current residual but not post-residual (blocking).
    if next_item_size > 0 && next_item_size <= bin_residual && next_item_size > post_residual {
        score += 15.0;
    }

    // Time horizon: early in stream, prefer consolidating into open bins less aggressively;
    // late in stream, pack tightly since fewer future items remain.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 - 0.3 * progress;

    // Many open bins: encourage filling existing ones rather than opening more.
    score += open_bins_count as f64 * 2.0;

    // Compare residual against mean residual: bins below mean residual are already tight,
    // prefer using them; bins above mean have slack, slightly penalize.
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // New-bin candidate: mild penalty so we only open new bins when fits are poor.
    if bin_residual == bin_capacity {
        score += 20.0 + post_residual as f64 * 0.1;
        // But if no tight option exists (many bins, big item), allow opening.
        if item_size > 60 {
            score -= 10.0;
        }
    }

    // Exact fill is perfect.
    if post_residual == 0 {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress:
    // later in the stream, tight fills (small post_residual) are rewarded more.
    let progress_weight = 1.0 + 2.0 * progress * progress;
    score -= progress_weight * cap * (1.0 - norm_pr) * (1.0 - norm_pr) * 0.5;

    // Non-linear penalty for dead space that cannot fit the next item.
    if next_item_size > 0 {
        let gap = norm_pr - norm_next;
        if gap < 0.0 {
            // post_residual too small for next item: penalize quadratically.
            score += 12.0 * gap * gap * cap;
        } else {
            // mild reward for leaving room exactly matching the next item.
            score -= 4.0 * (gap * (1.0 - gap)).max(0.0) * cap;
        }
    }

    // Reward last-chance bins (only fitting bin) with smooth saturation.
    let last_chance = 1.0 / fitting_bins_count as f64;
    score -= 8.0 * last_chance * last_chance;

    // Mild penalty when bin residual deviates from mean residual (balance pressure).
    score += 0.05 * ((bin_residual as f64 - mean_residual) / cap).abs() * cap;

    // Slight preference to consolidate into fewer bins as stream progresses.
    score += 0.02 * (open_bins_count as f64) * (1.0 - progress);

    // New-bin candidate: penalize opening a new bin smoothly, stronger early.
    if bin_residual == bin_capacity {
        score += 10.0 + 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual;
    let mut score = pr as f64;

    // Harmonic class: residuals that are multiples of 10 are more reusable
    let class = (pr % 10) as f64;
    score += class * 0.15;

    // Tight-fit rewards
    if pr <= 5 {
        score -= 30.0;
    } else if pr <= 10 {
        score -= 15.0;
    }

    // Lookahead coupling with next item size
    if next_item_size > 0 && (next_item_size as u64) <= (bin_capacity as u64) {
        if (pr as u64) < (next_item_size as u64) {
            // residual becomes dead space for the next item
            score += (pr as f64) * 0.5;
        } else {
            let gap = pr - next_item_size;
            score -= (gap as f64).min(20.0) * 0.4;
        }
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 1000.0; // must open a new bin
        } else if fitting_bins_count == 1 {
            score += 500.0; // last-chance existing bin: strongly prefer it
        } else {
            score += 25.0 + (open_bins_count as f64) * 0.5;
        }
    } else if fitting_bins_count == 1 {
        score -= 40.0; // this is the only bin that fits: use it
    }

    // Prefer tighter-than-average bins mildly
    score += (bin_residual as f64 - mean_residual).max(0.0) * 0.05;

    // Stream progression: consolidate residual space more aggressively later
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 2.0 * (pr as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space heavily (gaps that can't fit typical items)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual >= 10 && post_residual < 25 {
        score += 12.0;
    }

    // Reward near-perfect fits strongly
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Last chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open bins pressure: when many bins are open, prefer filling existing ones
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
    score += pressure * 0.8;

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }

    // Early stream: be slightly more willing to open bins to keep flexibility
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 3.0;

    // Brand-new bin candidate: neutral baseline with mild penalty so it's
    // chosen only when existing bins have bad fits
    if bin_residual == bin_capacity {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good.
    score += (post_residual as f64 / bin_capacity as f64) * 20.0;

    // 2-step lookahead: if the next item fits exactly in the post residual,
    // this is a perfect chain — strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size < post_residual {
            let new_post = post_residual - next_item_size;
            // reward small residual after the lookahead placement
            score -= (new_post as f64 / bin_capacity as f64) * 40.0;
        } else {
            // next item won't fit here: penalize dead space
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Relative to mean residual: prefer bins with residual close to item
    // (tight packing), penalize bins far above mean.
    let diff_mean = bin_residual as f64 - mean_residual;
    score += diff_mean * 0.15;

    // Last-chance bin: if this is the only bin that can fit, avoid opening
    // a new bin unless fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // relative to capacity and current bins are fragmented.
    if bin_residual == bin_capacity {
        let waste = (bin_capacity - item_size) as f64;
        score += waste * 0.6;
        if next_item_size > 0 && next_item_size >= post_residual {
            score -= 10.0;
        }
    }

    // Late in stream: consolidate, avoid opening new bins.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual != bin_capacity {
        score -= progress * 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual small relative to capacity.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 18.0 * fit_ratio;

    // Penalize dead space that is too small to hold a typical item.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Lookahead coupling: if next item fits in post_residual, bonus.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0 * (next_item_size as f64 / bin_capacity as f64);
    } else if next_item_size > post_residual && next_item_size > bin_residual {
        // Next item won't fit anywhere in this bin; wasting residual hurts.
        score += 8.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: discourage opening a new bin unless
    // no good fit exists or the item is huge.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0
            - 5.0 * fit_ratio
            - 10.0 * progress
            + 0.5 * open_bins_count as f64;
        if item_size >= 70 && fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    // Prefer bins with residual far below mean residual (tighter bins first).
    score -= 3.0 * (mean_residual - bin_residual as f64) / bin_capacity as f64;

    // Mild pressure to consolidate as the stream fills open bins.
    score += 0.02 * open_bins_count as f64;

    // Slight time decay: early on, keep bins flexible (prefer larger post residual).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.15 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap; // normalized post residual in [0,1]
    let fit = fitting_bins_count as f64;
    let nb = open_bins_count as f64;

    let mut score = pr as f64;

    // Non-linear polynomial coupling: dead space penalized quadratically as stream progresses
    score += 30.0 * norm_pr * norm_pr * (0.3 + progress);

    // Tight fit reward: cubic in fill fraction
    let fill = (item_size as f64) / cap;
    score -= 25.0 * fill * fill * fill;

    // Last-chance bonus (only fitting bin): strong reward, decaying with progress
    if fitting_bins_count == 1 {
        score -= 40.0 * (1.0 - progress) + 15.0;
    } else {
        score += 5.0 / fit.sqrt();
    }

    // Prefer bins below mean residual (balance load) with smooth term
    score += 0.15 * (pr - mean_residual);

    // Lookahead coupling: penalize leaving space that next item just barely misses
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let gap = norm_pr - ns / cap;
        if gap > 0.0 {
            score += 20.0 * gap * gap * (1.0 - gap);
        }
        // reward leaving exactly enough room for next item
        if gap.abs() < 0.02 {
            score -= 12.0;
        }
    }

    // Late stream: prefer consolidating into fewer bins
    score += progress * 0.5 * nb;

    // New-bin candidate: smooth penalty unless current bins are very full
    if bin_residual == bin_capacity {
        let mean_fill = 1.0 - mean_residual / cap;
        score += 18.0 * (1.0 - mean_fill * mean_fill) + 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: which capacity fraction band it falls into.
    let item_class = (item_size * 4) / bin_capacity; // 0..=3 harmonic class
    let post_class = (post_residual * 4) / bin_capacity;

    // Reward placements whose post-residual lands in a "usable" harmonic class
    // (residuals that still accommodate typical mid-size items: 20..50).
    let usable = post_residual >= 20 && post_residual <= 50;
    if usable {
        score -= 12.0;
    } else {
        // Penalize dead space: very small residuals that likely can't be filled.
        if post_residual < 20 && post_residual > 0 {
            score += 18.0;
        }
    }

    // Perfect or near-perfect fit: modulo-friendly residuals (multiples of 25).
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 8.0;
    }

    // Lookahead coupling: if next item fits the post-residual, strongly reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0;
        // Extra reward if next item exactly matches remaining class boundary.
        if post_residual - next_item_size < 10 {
            score -= 6.0;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item won't fit here: penalize wasting the residual.
        score += 6.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad
    // and mean residual is low (few good alternatives).
    if bin_residual == bin_capacity {
        score += 30.0;
        if item_size > bin_capacity / 2 {
            // Large items pair well in fresh bins (two per bin).
            score -= 20.0;
        }
        if mean_residual < item_size as f64 {
            score -= 10.0;
        }
    }

    // Tight fit bonus: minimize wasted space via integer-division thresholds.
    let tightness = (item_size * 100) / bin_residual.max(1);
    score -= (tightness as f64) * 0.05;

    // Class mismatch penalty: avoid mixing large-class items into small-residual bins.
    if item_class >= 2 && post_class == 0 {
        score += 10.0;
    }

    // Stream progression: early on, prefer consolidation; late, be greedy-tight.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * (bin_residual as f64 - post_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residual gaps too small for typical
    // future items (<= 20) are heavily penalized as wasted capacity.
    if post_residual > 0 && post_residual < 20 {
        score += 40.0 + (20 - post_residual) as f64 * 3.0;
    }

    // Gaps in the "awkward middle" (21..35) are mildly penalized too.
    if post_residual >= 20 && post_residual < 35 {
        score += 8.0;
    }

    // Reward perfect or near-perfect fits.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 10 {
        score -= 10.0;
    }

    // Lookahead: if the next item fits the post residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // If next item does NOT fit post residual, penalize slightly more when
    // the gap is dead space for the known future item.
    if next_item_size > post_residual && post_residual > 0 {
        score += 5.0;
    }

    // Last-chance bin pressure: if this is the only fitting bin, avoid
    // opening a new bin unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading; few open
    // bins -> encourage filling existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (0.4 + 0.6 * progress);

    // Mean residual coupling: prefer bins below mean residual (tighter bins
    // first), pushing big gaps to be filled later.
    score += (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate: only attractive when nothing fits well; make the
    // empty bin costly by default but slightly cheaper when many bins exist.
    if bin_residual == bin_capacity {
        score += 55.0 - open_bins_count as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer bins where the lookahead item fits snugly after this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        let snug = (post_residual - next_item_size) as f64;
        score -= 40.0 + 0.5 * (next_item_size as f64) - 0.3 * snug;
    } else if next_item_size > 0 {
        // Next item won't fit here afterward: penalize proportionally to how much it misses.
        let miss = (next_item_size - post_residual) as f64;
        score += 0.4 * miss;
    }

    // Penalize dead space relative to the mean residual of open bins.
    score += 0.25 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Late in the stream, consolidate into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    // Slight bias toward fuller bins (smaller residual before placement).
    score += 0.1 * bin_residual as f64;

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { -60.0 } else { 30.0 };
        score += desperation + 0.2 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is perfect.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Penalize large dead space quadratically, but forgive small leftovers.
    let pr = post_residual as f64;
    score += 0.35 * pr * pr / bin_capacity as f64;

    // Reward tight fits relative to current item size.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 12.0 * tightness;

    // Lookahead: bonus if next item fits into post_residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0;
            // extra reward for chained compactness
            score -= 5.0 * (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
        } else if next_item_size > post_residual && post_residual < 10 {
            // small dead space unusable by next item: slight penalty
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Time horizon: late in stream, prefer closing bins tightly; early, allow spreading.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - tightness);

    // Global state: many open bins -> prefer filling existing ones; few -> new bins cheap.
    let open_norm = open_bins_count as f64 / (total_items.max(1) as f64).sqrt();
    score += 4.0 * open_norm * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins below mean residual (keep balance, avoid stranding large residuals).
    let mean_norm = mean_residual / bin_capacity as f64;
    score += 6.0 * (pr / bin_capacity as f64 - mean_norm);

    // New-bin candidate: baseline cost that must be beaten by good existing fits,
    // but low enough when item is large and nothing fits well.
    if bin_residual == bin_capacity {
        score = 60.0 + 0.5 * item_size as f64 - 10.0 * progress;
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with polynomial coupling to stream progress
    let mut score = pr * (1.0 + 0.8 * progress * norm_pr);

    // Quadratic penalty on wasted space, amplified late in the stream
    score += 12.0 * norm_pr * norm_pr * (0.5 + progress);

    // Lookahead coupling: reward residuals that can still host the next item
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if pr >= n {
            let slack_fit = (pr - n) / cap;
            score -= 6.0 * (1.0 - slack_fit) * (1.0 + progress);
        } else {
            score += 4.0 * (n - pr) / cap * (1.0 + progress);
        }
    }

    // Last-chance bonus: strongly favor using a nearly exhausted set of fitting bins
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0 * (1.0 + progress);
    }

    // Mild penalty for spreading across too many open bins relative to mean residual
    score += 0.05 * open_bins_count as f64 * (mean_residual / cap).abs();

    // New-bin candidate: penalize opening a fresh bin unless current residuals are large
    if bin_residual == bin_capacity {
        score += 20.0 + 30.0 * progress - 0.3 * mean_residual;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: dead-space classes (1..=9) are nearly useless
    let small_dead = post_residual > 0 && post_residual < 10;
    if small_dead {
        score -= 40.0; // still slightly better than wasting a big residual? no: penalize? Actually reward tight fits
        score += 0.0;
    }

    // Prefer bins whose post_residual falls in "useful" harmonic classes
    // Classes via integer division thresholds of capacity fractions
    let cap_f = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap_f; // post residual as capacity fraction

    // Usable residual bands: (0.1,0.2], (0.2,0.35], (0.35,0.5], >0.5
    if frac > 0.5 {
        score -= 8.0;
    } else if frac > 0.35 {
        score -= 5.0;
    } else if frac > 0.2 {
        score -= 2.0;
    } else if frac > 0.1 {
        score -= 0.5;
    } else if pr > 0 {
        score += 6.0; // tiny dead space penalty
    }

    // Modulo-10 harmonic class: residuals divisible by 10 pair well with typical sizes
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 3.0;
    }

    // Lookahead coupling: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item fits exactly or well
            let slack = post_residual - next_item_size;
            score -= 6.0 + (slack as f64).min(10.0) * 0.3;
            if post_residual == next_item_size {
                score -= 8.0; // chain of perfect fits
            }
        } else {
            // next item won't fit here; penalize less if residual still generally useful
            score += 2.0;
            if small_dead {
                score += 5.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins are poor fits
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 30.0;
        // but if current bin leaves tiny dead space and next item is large, new bin is attractive
        if small_dead {
            score -= 20.0;
        }
        if next_item_size > 0 && next_item_size > post_residual && post_residual < 10 {
            score -= 15.0;
        }
        // early in stream, opening bins is cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 10.0;
        // many open bins => discourage more
        score += open_bins_count as f64 * 0.5;
    } else {
        // prefer filling existing bins, especially those below mean residual (underused)
        if (pr < mean_residual) && pr > 0.0 {
            score -= 1.5;
        }
        // slight preference for bins that will be closed out (low residual) when many bins open
        score -= (open_bins_count as f64 - 1.0).max(0.0) * (10.0 - pr.min(10.0)) * 0.05;
    }

    // mild step-based tightening: later in stream, be greedier about tight fits
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (item_size as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: residuals that are too small to hold
    // even the smallest plausible item (<= 10) are wasted capacity.
    if post_residual > 0 && post_residual < 10 {
        score += 200.0;
    }
    // Moderately small gaps are also risky, penalize quadratically.
    if post_residual >= 10 && post_residual < 25 {
        score += 2.0 * (25.0 - post_residual as f64);
    }

    // Reward residual that could still fit the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + 0.25 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 10.0; // dead space relative to lookahead
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // Pressure from number of open bins: discourage opening new bins
    // when many are already open.
    if bin_residual == bin_capacity {
        score += 50.0 + 8.0 * open_bins_count as f64;
    }

    // Prefer bins tighter than the mean residual (well-filled bins).
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Mild preference for high post_residual late in the stream is already
    // captured by the base term; add slight stream-progress tilt.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward perfect or near-perfect fits (low post residual)
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 15 {
        score -= 60.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item exactly
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0; // chain of perfect fits
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // reward ability to fit next item, penalize leftover slack after it
            score -= 120.0 - slack * 1.5;
        } else {
            // next item won't fit here: dead space risk grows with small post_residual
            let waste = post_residual as f64;
            score += 40.0 + waste * 0.8;
        }

        // If next item also fits with zero slack after it, extra reward
        if next_item_size > 0 && post_residual >= next_item_size {
            let two_step_res = post_residual - next_item_size;
            if two_step_res <= 5 {
                score -= 150.0;
            }
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score += (mean_residual - bin_residual as f64) * 2.0;

    // Penalize opening a new bin when decent alternatives exist,
    // but allow it when this is a new-bin candidate and item is large relative to capacity
    if bin_residual == bin_capacity {
        // New bin candidate: attractive only if item is large (would leave big residual elsewhere)
        score = post_residual as f64 + 30.0 - (item_size as f64 / bin_capacity as f64) * 60.0;
        if fitting_bins_count > 0 {
            // discourage new bin if other bins can fit the item
            score += 25.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 80.0; // new bin can chain next item too
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 100.0;
    }

    // Late in stream: consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: perfect or near-perfect fits are strongly favored.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        let fit_ratio = item_size as f64 / bin_residual as f64;
        score -= 60.0 * fit_ratio * fit_ratio;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0 * (next_item_size as f64 / 100.0);
        } else {
            // Dead space penalty scaled by how much of the next item is stranded.
            let stranded = (next_item_size as f64 - post_residual as f64).max(0.0);
            score += 0.4 * stranded;
        }
    }

    // Last-chance bin before opening a new bin: strongly favor using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Penalize scattering into many open bins when fragmentation is high.
    if open_bins_count > 0 {
        let frag = (mean_residual - post_residual as f64).abs();
        score += 0.15 * frag;
    }

    // Time horizon: early in the stream, be conservative (prefer filling existing bins);
    // late in the stream, allow tighter packing aggression.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 20.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Mild penalty for creating very small unusable slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Base: post-residual with non-linear shrinkage (dead space matters more when small)
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth polynomial coupling of post_residual with stream progress:
    // late in the stream, prioritize tighter fits (larger exponent effect)
    let late = progress * progress;
    score += pr * late * 0.6;

    // Reward near-perfect fits via smooth quadratic bonus
    let perfect = 1.0 - norm_pr;
    score -= 20.0 * perfect * perfect * (1.0 + late);

    // Penalize wasted space relative to mean residual (fragmentation pressure)
    score += 0.3 * (pr - mean_residual).abs() * (0.5 + progress);

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Lookahead: penalize leaving residual too small for the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = pr - nx;
        if gap < 0.0 {
            score += 0.2 * (-gap);
        } else {
            // smooth reward if next item still fits comfortably
            let fit = gap / cap;
            score -= 8.0 * fit * (1.0 - fit) * (1.0 + progress);
        }
    }

    // Mild penalty for too many open bins relative to progress (encourage consolidation)
    let bin_pressure = open_bins_count as f64 / (1.0 + (total_items as f64) * (1.0 - progress) * 0.5);
    score += 1.5 * bin_pressure * progress;

    // New-bin candidate: make empty bin moderately attractive only when fits are poor
    if bin_residual == bin_capacity {
        let bad_fit = (norm_item - 1.0).abs().min(1.0);
        score = cap * 0.55 + 10.0 * (1.0 - bad_fit) - 12.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residues divisible by common
    // item granularities (10, 20, 25, 50) are more reusable than odd ones.
    let pr = post_residual;
    let mut reusability = 0.0;
    if pr % 10 == 0 { reusability += 6.0; }
    if pr % 20 == 0 { reusability += 4.0; }
    if pr % 25 == 0 { reusability += 4.0; }
    if pr % 50 == 0 { reusability += 5.0; }
    score -= reusability;

    // Dead space: tiny post residuals are wasted capacity.
    if pr > 0 && pr < 10 {
        score += 25.0;
    }

    // Perfect fit is ideal.
    if pr == 0 {
        score -= 100.0;
    }

    // Lookahead: does the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 12.0;
            // Harmonic bonus: next item leaves another "nice" residue.
            if (pr - next_item_size) % 10 == 0 {
                score -= 6.0;
            }
        } else {
            score += 10.0;
        }
    }

    // Last chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: prefer existing bins unless this bin
    // is nearly full and the fit is poor.
    if bin_residual == bin_capacity {
        // Brand-new bin: moderate baseline; opening new bins is expensive.
        score = (bin_capacity as f64) * 0.75 + (open_bins_count as f64) * 2.0;
        if next_item_size > 0 && next_item_size >= 50 {
            score -= 15.0; // big next item may want fresh space
        }
    } else if bin_residual == item_size {
        // Exact fill of an existing bin is excellent.
        score -= 60.0;
    }

    // Fraction-of-capacity coupling: bins whose residual is a small
    // fraction of capacity are close to closure; fine to fill them.
    let frac = (bin_residual as f64) / (bin_capacity as f64);
    if frac < 0.25 {
        score -= 8.0;
    } else if frac > 0.75 {
        score += 4.0;
    }

    // Mean residual divergence: penalize bins far from the mean residual
    // to keep the pool homogeneous (integer-division threshold).
    let drift = ((post_residual as f64) - mean_residual).abs();
    if (drift as u32) / 20 > 0 {
        score += drift * 0.3;
    }

    // Stream progression: late in the stream, be more conservative about
    // opening new bins (favor consolidation).
    let progress = step_index as f64 / total_items as f64;
    if bin_residual != bin_capacity {
        score -= progress * 5.0;
    } else {
        score += progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // minimum item size (1) are not penalized, but gaps that can only hold
    // very small items are "dead space". Penalize gaps that cannot fit the
    // next item (lookahead-aware dead space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0 + (next_item_size - post_residual) as f64 * 0.5;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward bins whose post-residual still accommodates the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 4.0;
    }

    // Tightness reward: prefer bins where the item fills a large fraction.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 5.0;

    // Last-chance pressure: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // Open-bin pressure: with many open bins, keep using them; with few,
    // be pickier (slightly raise scores to allow new-bin opening).
    score += (open_bins_count as f64).ln().max(0.0) * 1.5;

    // Mean residual coupling: if this bin's residual is far below the mean,
    // it is an outlier bin; prefer consolidating into low-residual bins.
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.05;

    // New-bin candidate: neutral-ish baseline, opened only when fits are bad.
    if bin_residual == bin_capacity {
        score = 40.0 + post_residual as f64 * 0.1 - (fitting_bins_count as f64) * 0.0;
        // If no open bin fits well, allow the new bin.
        if fitting_bins_count == 0 {
            score = 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 500.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 300.0;
        } else if post_residual > next_item_size {
            score -= 0.5 * (post_residual - next_item_size) as f64;
        } else {
            // next item won't fit here: penalize by wasted gap
            score += 0.3 * (next_item_size - post_residual) as f64;
        }
    }

    // Penalize small unusable dead space (fragmentation)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Prefer tighter bins relative to mean residual
    score -= 0.2 * (mean_residual - post_residual as f64);

    // Early in stream: slightly prefer new bins for large items
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New bin candidate: baseline cost, less attractive late when open bins exist
        score += 60.0 + 40.0 * (1.0 - progress) - 5.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Base: prefer tight fits (low post_residual).
    let mut score = post;

    // Waste penalty: super-linear punishment for leaving large unusable gaps,
    // scaled by how large the gap is relative to capacity.
    let gap_frac = post / cap;
    score += 12.0 * gap_frac * gap_frac * cap;

    // Lookahead: if the next item fits exactly into the post residual, reward heavily.
    if next_item_size > 0 && next_item_size as f64 == post {
        score -= 30.0;
    } else if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        // Next item still fits: mildly reward leaving compatible space.
        let compat = 1.0 - ((post - next_item_size as f64) / cap).abs();
        score -= 8.0 * compat;
    } else if next_item_size > 0 {
        // Next item cannot use this residual: penalize dead space proportionally.
        score += 6.0 * gap_frac * cap;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Reward using bins that are already relatively empty (consolidation),
    // measured against the mean residual of open bins.
    score += 0.15 * (mean_residual - bin_residual as f64);

    // Late in the stream, tighten packing: prefer near-perfect fills more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (cap - post) * 0.25;

    // Many open bins: discourage spreading; favor bins with small residuals
    // to close them out.
    let crowding = (open_bins_count as f64).ln().max(0.0);
    score += crowding * post * 0.08;

    // New-bin candidate (empty bin): give it a moderate default so it only wins
    // when all open-bin fits are poor (high post_residual / dead space).
    if bin_residual == bin_capacity {
        score = cap * 0.75 + 10.0 * gap_frac * cap - 5.0 * (fitting_bins_count as f64);
        if next_item_size > 0 && (next_item_size as u32) <= bin_capacity {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let r = post_residual as f64;
    let cap = bin_capacity as f64;
    let rn = r / cap;

    // Base: prefer small post-residual, with smooth polynomial shaping.
    let mut score = r * (1.0 + 0.8 * rn * rn);

    // Non-linear coupling: as stream progresses, waste tolerance tightens.
    score += 40.0 * progress * rn * rn;

    // Dead-space penalty if residual can't fit the next item (smooth falloff).
    if next_item_size > 0 {
        let nn = next_item_size as f64;
        let gap = (r - nn).max(0.0);
        let usable = gap / cap;
        score -= 25.0 * (usable / (usable + 0.15)) * (1.0 - rn);
    }

    // Last-chance bonus: smooth reward when few bins fit.
    let fit_frac = fitting_bins_count.max(1) as f64;
    score -= 30.0 / (fit_frac * fit_frac);

    // Mild pressure against opening new bins when many exist.
    score += 2.0 * open_bins_count as f64 * rn;

    // Tie-break toward bins near mean residual (smooth term).
    score += 0.05 * (r - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual).
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap_f = bin_capacity as f64;

    // Harmonic class of post_residual: bins whose leftover falls in "dead" residue
    // classes (small but unusable slivers) are penalized.
    let pr = post_residual;
    let residue_class = pr % 10;
    match residue_class {
        0 => score -= 12.0,                 // perfectly decadal leftover: reusable
        1..=4 => score += 6.0 + 2.0 * residue_class as f64, // tiny dead slivers
        5..=8 => score -= 3.0,              // medium leftovers still useful
        _ => score += 1.0,
    }

    // Integer-division threshold: leftover >= half capacity is very flexible.
    if pr * 2 >= bin_capacity {
        score -= 8.0;
    } else if pr * 3 >= bin_capacity {
        score -= 4.0;
    }

    // Lookahead coupling: reward if next_item_size fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 20.0;
        } else if next_item_size < pr {
            let fit_frac = next_item_size as f64 / pr.max(1) as f64;
            score -= 10.0 * fit_frac;
        } else {
            // next item cannot fit here; leftover quality decides
            score += (next_item_size - pr) as f64 * 0.05;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Many open bins: discourage spreading; prefer consolidating into fuller bins.
    score += open_bins_count as f64 * 0.3 * (bin_residual as f64 / cap_f);

    // Mean residual coupling: bins much fuller than mean are attractive.
    let dev = mean_residual - bin_residual as f64;
    score += 0.25 * dev;

    // New-bin candidate: only attractive when this bin's leftover would be a
    // dead sliver and the stream is early enough to amortize a fresh bin.
    if bin_residual == bin_capacity {
        let dead = pr > 0 && pr < 10;
        if dead && progress < 0.9 {
            score -= 5.0;
        } else {
            score += 10.0 + 20.0 * progress;
        }
    }

    // Late stream: tighten up, avoid leaving many near-empty bins.
    score += progress * 5.0 * (pr as f64 / cap_f);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in (0, 10) is unusable for
    // future items (min item size assumed small but still wasteful) — penalize hard.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Perfect fit: strongly reward.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward bins whose residual exactly matches common future gap sizes
    // (post_residual in [10, 40] is reusable; larger gaps are less critical).
    if post_residual >= 10 && post_residual <= 40 {
        score -= 8.0;
    }

    // Last chance: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones;
    // the new-bin candidate has bin_residual == bin_capacity, so add a bias
    // that grows with open_bins_count to keep it from winning cheaply.
    if bin_residual == bin_capacity {
        score += 5.0 + 2.0 * open_bins_count as f64;
    }

    // Lookahead coupling: if the next item could exactly fill this bin's
    // post_residual, reward heavily (chain fit).
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 20.0;
        } else if gap < 10 {
            score += 10.0; // next item would create dead space here
        } else {
            score -= 5.0;
        }
    }

    // Prefer bins tighter than the mean residual (pack into nearly-full bins first).
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    }

    // Early stream: be slightly conservative, keep residual spread even;
    // late stream: be greedy, minimize waste aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 3.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: reward exact 2-step lookahead match (post_residual equals next item size).
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        // Strong bonus for perfect match, decaying with distance.
        score -= 40.0 * (-diff / 12.0).exp();

        // Reward leaving room for the next item at all (post_residual >= next_item_size).
        if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            // Dead space penalty: wasted space the next item cannot use.
            score += 0.35 * post_residual as f64;
        }

        // If this bin's post_residual is the closest among open bins to next_item_size,
        // mean_residual acts as a reference: reward being tighter than average.
        if (post_residual as f64) < mean_residual {
            score -= 2.0;
        } else {
            score += 0.05 * (post_residual as f64 - mean_residual);
        }
    } else {
        // Last item: minimize waste.
        score += 0.5 * post_residual as f64;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless post_residual is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: opening a fresh bin is only attractive when the item would
    // otherwise leave a large unusable gap. Penalize new bins by default.
    if bin_residual == bin_capacity {
        let gap_penalty = if next_item_size > 0 && post_residual < next_item_size {
            0.0 // item creates dead space; new bin may be justified
        } else {
            18.0
        };
        score += 15.0 + gap_penalty + 0.1 * open_bins_count as f64;
    }

    // Mild pressure to consolidate into fewer bins as the stream progresses.
    score += 0.02 * open_bins_count as f64 * (step_index as f64 / total_items.max(1) as f64);

    // Prefer filling larger residuals (tighter fits) slightly.
    score += 0.03 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // Penalize dead space that no plausible item can use.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let dead_threshold = 10.0 + 8.0 * (1.0 - progress);
    if (post_residual as f64) < dead_threshold {
        score += 6.0 * (post_residual as f64 / dead_threshold);
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Lookahead coupling: reward bins whose post-residual can host next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) >= nxt {
            score -= 8.0;
        } else {
            score += 0.35 * (nxt - post_residual as f64);
        }
    }

    // Spread pressure: prefer bins below mean residual (tighter bins) when many bins open.
    let res_f = bin_residual as f64;
    score += 0.15 * (res_f - mean_residual) * (1.0 + open_bins_count as f64 / 20.0);

    // Mild preference for already-opened bins over opening a new one.
    if bin_residual == bin_capacity {
        score += 12.0 + 10.0 * (1.0 - progress);
        // But allow opening a fresh bin if no open bin fits well.
        if fitting_bins_count == 0 || (fitting_bins_count == 1 && (bin_residual - item_size) > bin_capacity / 2) {
            score -= 20.0;
        }
    }

    // Late-stream consolidation: favor tighter fills as stream ends.
    score -= 10.0 * progress * (1.0 - post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = if total_items > 1 { step_index as f64 / (total_items as f64 - 1.0) } else { 0.0 };
    let post = post_residual as f64;
    let post_norm = post / cap;

    // Base: prefer filling bins tightly (small post_residual).
    let mut score = post;

    // Non-linear polynomial shaping of post_residual: quadratic + cubic coupling
    // rewards very tight fits and gently penalizes mid-range leftover space.
    let p = post_norm;
    score += 40.0 * p * p - 30.0 * p * p * p;

    // Stream-progress coupling: late in the stream, tighten further
    // (dead space matters more when few items remain to fill it).
    let late = progress * progress;
    score += 25.0 * late * p * (1.0 - p);

    // Lookahead: if the next item fits exactly in the post-residual, reward strongly;
    // if next item would leave this residual unusable, penalize mildly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let nxt_norm = nxt / cap;
            let exact = (post - nxt) / cap;
            score -= 30.0 * (1.0 - exact) * (1.0 - nxt_norm.abs() - 0.5).abs().min(1.0);
        } else {
            score += 8.0 * (1.0 - progress);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0 + 15.0 * progress;
    }

    // New-bin candidate handling: opening a new bin should only win when the item
    // fits poorly in all open bins. Penalize new bins by mean residual pressure:
    // many open bins with large residuals -> prefer reusing them.
    if bin_residual == bin_capacity {
        let mean_norm = mean_residual / cap;
        score += 10.0 + 45.0 * mean_norm + 5.0 * open_bins_count as f64;
        // Late in stream, opening new bins is more wasteful.
        score += 20.0 * late;
    }

    // Mild penalty for very wasteful placements leaving tiny unusable slivers
    // that no typical item (>=1) can... actually slivers of 1-9 are dead space.
    if post > 0 && post < 10 {
        score += 12.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of post_residual: bins whose leftover falls into a
    // "useful" residue class (small remainders or near half-capacity) are
    // preferred, since future items (1..100) can reuse them. ---
    let class = post_residual % 10;
    // Small leftover classes (0..=4) are near-perfect fills: reward.
    if class <= 4 {
        score -= 6.0 - 1.2 * class as f64;
    }
    // Awkward classes (5..=9) are dead-space prone: penalize mildly.
    else {
        score += 0.6 * (class as f64 - 4.0);
    }

    // Integer-division thresholds on post_residual: leftover below the
    // minimum item size is pure dead space.
    if post_residual < 10 {
        score += 25.0; // unusable remainder
    } else if post_residual <= 20 {
        score += 4.0; // only tiny items fit
    } else if post_residual >= 50 {
        score -= 3.0; // roomy bin stays flexible
    }

    // Coupling with next item (lookahead k=2): perfect harmonic match bonus.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 15.0; // next item exactly fills this bin
        } else if post_residual > next_item_size {
            let slack = post_residual - next_item_size;
            if slack < 10 {
                score -= 8.0; // next item leaves near-zero waste
            } else {
                score -= 2.0 * (slack as f64 / 100.0);
            }
        } else {
            // next item cannot reuse leftover: penalize by deficit class
            score += 0.08 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive
    // when the current item is large and open bins are fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = (mean_residual - post_residual as f64).abs();
        // Fresh bin baseline: slight penalty so it loses to good fits,
        // but reward when item is big and existing residuals are small.
        score += 12.0;
        score -= 0.15 * item_size as f64;
        if mean_residual < item_size as f64 {
            score -= 18.0; // existing bins too full -> open new bin
        }
        if fragmentation > 40.0 {
            score -= 5.0 * progress;
        }
    }

    // Slight preference to fill fuller bins first (tightest fit).
    score -= 0.05 * (bin_capacity - bin_residual) as f64;

    // Mild pressure against accumulating too many open bins.
    score += 0.05 * open_bins_count as f64;

    // Mean-residual coupling: avoid bins far from the fleet average
    // to keep residual distribution balanced.
    score += 0.03 * (post_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: extremely desirable.
    if post_residual == 0 {
