    } else {
        // Strict dead-space avoidance: small unusable gaps are heavily penalized.
        // A residual is "unusable" if smaller than the smallest plausible item (1..100, unknown dist).
        // Treat gaps <= 10 as pure dead space (smallest known bound), with graded penalty up to ~30.
        let pr = post_residual as f64;
        if post_residual <= 10 {
            score += 60.0; // worse than a moderately loose fit
        } else if post_residual < 30 {
            score += (30.0 - pr) * 1.5; // graded penalty for tight dead zones
        }

