        if next_item_size > 0 && post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 - slack.min(15.0); // prefer post_residual == next_item_size
        } else if next_item_size > 0 {
            score += 8.0; // cannot host the next item at all
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading into new/partial bins.
    let open_pressure = (open_bins_count as f64) * 1.2;
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure; cheaper only when nothing fits well.
        score += 25.0 + open_pressure;
    } else {
        // Slight preference for filling bins that are already relatively full.
        let fullness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
        score -= fullness * 10.0;
        score -= open_pressure * 0.5;
    }

    // Late in the stream: tighten up, prefer closing out bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 5.0 * (mean_residual / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
