    score += 0.8 * (open_bins_count as f64).ln() * (0.5 + progress);

    // Slight pull toward bins with residual near mean (stability term)
    score += 0.15 * ((resid - mean_residual) / cap).abs();

    // New-bin candidate: penalize mildly so it's chosen only when open bins fit poorly
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: residual modulo capacity quarters
    let q = post_residual % 25;
    if q == 0 && post_residual > 0 {
        score -= 40.0; // residual aligns with quarter classes — reusable
    } else if q >= 20 {
        score -= 20.0; // near a quarter boundary, still usable by small items
    } else if q < 10 {
        score += 15.0; // awkward dead-space band
    }

    // Penalize tiny unusable residuals (dead space)
    if post_residual < 10 && post_residual > 0 {
        score += 60.0;
    }

    // Lookahead: if next item fits exactly into post_residual, strong reward
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 300.0;
        } else if gap <= 10 {
            score -= 100.0;
        }
    }
    // If next item would NOT fit here anyway, this bin is free to absorb current item
    if next_item_size > 0 && next_item_size > post_residual {
        score -= 25.0;
    }

    // Last-chance bin before opening a new bin
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // New-bin candidate: penalize opening a new bin unless residual is very small
    if bin_residual == bin_capacity {
        score += 55.0 + 0.3 * open_bins_count as f64;
    }

    // Prefer filling bins with larger residuals when many bins open (consolidation)
    if open_bins_count > 3 && bin_residual > mean_residual {
        score -= 8.0;
    }

    // Early stream: slightly prefer new bins to spread load; late stream: pack tight
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 20.0 * (1.0 - progress);
    } else {
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Reward residual that can still host the typical next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 6.0;
    }

    // Pressure from number of open bins: prefer consolidating when many bins open.
    score += open_bins_count as f64 * 1.5;

    // Mean residual coupling: if the fleet average residual is small, tighten more.
    score += (mean_residual - post_residual as f64).abs() * 0.3;

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // New empty bin candidate: only attractive when no open bin fits or fit is terrible.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 200.0;
        } else {
            score += 40.0 + (item_size as f64) * 0.2;
        }
    }

    // Mild stream-progression tightening: later items favor tighter packing.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: reward post_residual that exactly matches next item size
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += gap * 0.9;
        if post_residual == next_item_size {
            score -= 30.0; // perfect two-item chain
        }
        // penalize leaving space that next item cannot use but is small (dead space)
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // dead-space penalty: small unusable leftovers are bad
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // compare against mean residual: bins with residual close to mean are natural targets
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // new-bin candidate: penalize opening a fresh bin unless it enables a great 2-step fit
    if bin_residual == bin_capacity {
        let mut penalty = 40.0;
        if next_item_size > 0 && (post_residual as i64 - next_item_size as i64).abs() <= 2 {
            penalty = 5.0;
        }
        // early in stream, opening bins is cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        penalty *= 1.0 - 0.4 * progress;
        // many open bins -> discourage more
        penalty += open_bins_count as f64 * 1.5;
        score += penalty;
    }

    // prefer tighter fits overall
    score += (bin_residual - item_size) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins whose post-residual is small.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 12.0;

    // Penalize large dead space relative to capacity.
    let dead = post_residual as f64 / bin_capacity as f64;
    score += dead * dead * 20.0;

    // Lookahead: reward if next item fits into post-residual (chained packing),
    // penalize if next item is large and would be stranded.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0 + (next_item_size as f64 / bin_capacity as f64) * 15.0;
        } else {
            score += (next_item_size as f64 - post_residual as f64) * 0.3;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else {
        // More competing bins: mild penalty to keep exploration diverse.
        score += (fitting_bins_count as f64).ln().max(0.0) * 2.0;
    }

    // Time horizon: early in stream, tolerate opening new bins (explore);
    // late in stream, consolidate to minimize total bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let new_bin_bonus = 18.0 * (1.0 - progress);
    if bin_residual == bin_capacity {
        score -= new_bin_bonus;
        // New bin is only attractive if existing bins have poor fit potential.
        score += mean_residual * 0.15;
    } else {
        score -= new_bin_bonus * 0.5;
    }

    // Prefer bins below mean residual (balancing residual distribution).
    score += (mean_residual - post_residual as f64) * 0.2;

    // Discourage excessive open bins late in the stream.
    score += (open_bins_count as f64) * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post residual, with non-linear (quadratic) shaping.
    let mut score = pr + 40.0 * norm_pr * norm_pr;

    // Smooth stream-progress coupling: later in stream, waste matters more.
    let progress_coupling = 60.0 * progress * norm_pr * (1.0 - norm_pr * 0.5);
    score += progress_coupling;

    // Lookahead: reward residual that can host the next item (smooth affinity).
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let fit = (norm_pr * cap - n).max(0.0) / cap;
        score -= 35.0 * fit * (1.0 + progress);
        // Penalize near-exact consumption that leaves nothing for next item.
        let tight = 1.0 - (norm_pr * cap - n).abs() / cap;
        score += 10.0 * tight * tight;
    }

    // Last-chance bin: strong reward to use it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 80.0 * (1.0 - norm_pr);
    } else {
        // Mild penalty when many bins compete, favoring best-fit concentration.
        score += (fitting_bins_count as f64).ln() * 4.0;
    }

    // Mean-residual coupling: avoid bins far from the fleet's average state
    // (smooth divergence penalty), stronger early when consolidation matters.
    let div = (pr - mean_residual) / cap;
    score += 15.0 * div * div * (1.5 - progress);

    // Prefer filling already-open bins over opening new ones, scaled by congestion.
    if bin_residual == bin_capacity {
        score += 30.0 + 20.0 * (1.0 - progress);
    } else {
        score -= 8.0 * (open_bins_count as f64).ln().max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post-fit residual ---
    // Class 0: perfect fit (post_residual == 0) -> strongest reward.
    // Class 1: residual can still host the next item -> good.
    // Class 2: residual is "dead space" (0 < r < next_item_size) -> penalize.
    // Class 3: large leftover -> mild penalty (wasteful but reusable).
    let r = post_residual;
    if r == 0 {
        score -= 40.0; // perfect fit
    } else if next_item_size > 0 && r >= next_item_size {
        score -= 12.0; // reusable for lookahead item
    } else if next_item_size > 0 {
        // dead space: fraction of capacity wasted
        score += 25.0 * (1.0 - (r as f64) / (bin_capacity as f64));
    }

    // Integer-division harmonic bands on post_residual (capacity fractions).
    let cap = bin_capacity;
    if r > 0 {
        if r <= cap / 10 {
            score += 6.0; // tiny unusable sliver
        } else if r <= cap / 4 {
            score += 2.0;
        } else if r <= cap / 2 {
            score -= 3.0; // mid-range residual still quite usable
        } else {
            score -= 5.0; // big residual = flexible bin
        }
    }

    // Modulo-style coupling: reward residuals that are multiples of common
    // small size classes (likely future item sizes).
    if r % 10 == 0 && r > 0 {
        score -= 4.0;
    }
    if r % 5 == 0 && r > 0 {
        score -= 1.5;
    }

    // Lookahead exact-match bonus: post_residual equals next item size
    // (perfect two-step chaining).
    if next_item_size > 0 && r == next_item_size {
        score -= 10.0;
    }
    // Lookahead near-match: residual within a small band of next item.
    if next_item_size > 0 && r > next_item_size && r - next_item_size <= 5 {
        score -= 3.0;
    }

    // Last chance: if this is the only bin that fits, strongly prefer using it
    // rather than opening a new bin (unless post-fit residual is tiny dead space).
    if fitting_bins_count == 1 {
        score -= 15.0;
        if next_item_size > 0 && r > 0 && r < next_item_size {
            score += 18.0; // ...but not if it creates dead space for the next item
        }
    }

    // New-bin candidate: residual == capacity. Should generally lose to any
    // decent existing fit, but win over catastrophic dead-space placements.
    if bin_residual == bin_capacity {
        score += 30.0;
        // Late in the stream, opening fresh bins is cheaper than fragmenting.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 20.0 * progress;
        // If no open bin fits at all, new bin is the only real option.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Mild preference for filling fuller bins (best-fit flavor) when several fit.
    if fitting_bins_count > 1 {
        let fullness = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
        score -= 8.0 * fullness;
    }

    // Tie-break with mean residual: prefer bins below the mean residual
    // (i.e., already tight bins get closed out first).
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    } else {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps.
    let pr = post_residual;
    if pr > 0 && pr < 10 {
        // gap too small for any item (min size 1..100 unknown, but tiny gaps are waste)
        score += 60.0 * (1.0 - pr as f64 / 10.0);
    } else if pr >= 10 && pr < 20 {
        score += 25.0 * (1.0 - (pr as f64 - 10.0) / 10.0);
    }

    // Reward tight fits (small but not dead post_residual).
    if pr == 0 {
        score -= 40.0; // perfect fill
    } else if pr < 25 {
        score -= 12.0 * (25.0 - pr as f64) / 25.0;
    }

    // Reward bins whose residual is nearly consumed relative to capacity.
    let fill_ratio = 1.0 - bin_residual as f64 / bin_capacity as f64;
    score -= 10.0 * fill_ratio;

    // Pressure from number of open bins: discourage spreading when many bins open.
    score += 1.5 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits the post-residual, this placement is attractive.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        score += 6.0; // next item won't use this gap
    }

    // New empty bin candidate: make it moderately attractive only when current
    // bins would leave large residual waste; baseline penalty keeps it from
    // winning against decent fits.
    if bin_residual == bin_capacity {
        score += 15.0 + 1.0 * open_bins_count as f64;
        // early stream: opening bins is cheap
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Lookahead: if the next item exactly fills the post residual, strongly favor this bin
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // next item fits: mild reward proportional to how snugly it fits
            let snug = (post_residual - next_item_size) as f64;
            score -= 50.0 * (1.0 - snug / bin_capacity as f64);
        } else {
            // next item will NOT fit in post residual: penalize wasted lookahead space
            let gap = (next_item_size - post_residual) as f64;
            score += 0.5 * gap;
        }
    }

    // Penalize large dead space relative to smallest possible item
    if post_residual > 0 && post_residual < 10 {
        score += 200.0; // tiny unusable sliver
    }

    // Compare against mean residual: prefer bins that are already below-average residual
    // (i.e., tighter bins), to keep large-residual bins available for big items.
    score += 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bonus: if this is the only bin that can fit the item, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when no open bin gives a decent fit
    if bin_residual == bin_capacity {
        // base penalty so open bins are preferred
        score += 250.0;
        // but if item is large relative to capacity, opening a new bin is more acceptable
        score -= 2.0 * item_size as f64;
        // late in the stream, slightly prefer consolidating
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 100.0 * progress;
    }

    // Mild preference for tighter existing bins
    score += 0.1 * (bin_residual as f64 - item_size as f64);

