}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize large post_residual nonlinearly.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize dead space that nothing typical can use (post_residual < 10).
    if post_residual < 10 {
        score -= 8.0; // perfect closure is good
    } else if post_residual < 25 {
        score += 6.0; // awkward dead zone
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits into post_residual, reward this placement.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 12.0;
    }
    // If next item exactly matches post_residual, huge reward (perfect chain).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0;
    }
    // If next item cannot fit anywhere after this placement, penalize.
    if next_item_size > 0 && next_item_size > post_residual && post_residual < next_item_size {
        score += 3.0;
    }

    // New-bin candidate logic: empty bin gets a baseline penalty so it's only
    // chosen when open bins are poor fits, scaled by how bad alternatives are.
    if bin_residual == bin_capacity {
        score += 15.0 + 0.3 * open_bins_count as f64;
        // Late in the stream, prefer consolidating into open bins more strongly.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
        // If next item is large, a fresh bin may be valuable.
        if next_item_size >= 50 {
            score -= 10.0;
        }
    }

    // Prefer bins with residual close to mean (balanced packing) mildly.
    score += 0.05 * ((bin_residual as f64 - mean_residual).abs());

    // Slight preference for fuller bins overall (smaller residual).
    score += 0.02 * bin_residual as f64;

    // Time horizon: early on, be conservative (favor tight fits more);
    // late in stream, avoid opening bins aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * (1.0 - progress) * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let pr = post / cap; // normalized post residual in [0,1]

    // Base: prefer small post residual, with non-linear (quadratic) sharpening
    let mut score = post * (1.0 + 2.0 * pr * pr);

    // Smooth polynomial coupling of post_residual with stream progress:
    // later in the stream, tighter packing matters more
    let coupling = pr * (1.0 - pr) * 4.0; // peaks mid-range, 0 at extremes
    score += 20.0 * coupling * progress;

    // Penalize dead space that cannot fit a "typical" future item,
    // scaled smoothly by progress (end-game waste is costlier)
    let dead = if next_item_size > 0 && post_residual < next_item_size {
        (next_item_size - post_residual) as f64
    } else {
        0.0
    };
    score += dead * (0.5 + 1.5 * progress * progress);

    // New-bin candidate: penalize smoothly, less so when few alternatives exist
    let is_new = (bin_residual as f64 - cap).abs() < 0.5;
    if is_new {
        let scarcity = 1.0 / (fitting_bins_count as f64 + 1.0);
        score += 30.0 * (1.0 - 0.5 * scarcity) * (1.0 - 0.3 * progress);
        // If the next item would fit perfectly in this fresh bin, soften penalty
        if next_item_size > 0 && (next_item_size as f64) <= cap {
            score -= 5.0 * (1.0 - (next_item_size as f64 / cap));
        }
    }

    // Last-chance bonus: if this is the only fitting bin, reward using it
    if fitting_bins_count == 1 && !is_new {
        score -= 10.0 * (1.0 - pr);
    }

    // Mild preference toward consolidating among many open bins
    score += 0.5 * (open_bins_count as f64).ln().max(0.0) * pr;

    score
}

