    // the better the packing efficiency, beyond the raw baseline.
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score += tightness * tightness * 20.0;

    // Lookahead coupling: if the next item fits exactly into the post_residual,
    // strongly reward; if post_residual is smaller than next item but nonzero
    // and next item has few homes, mildly penalize wasted potential.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 12.0;
        } else if (post_residual as f64) > (next_item_size as f64) {
            score -= 3.0; // keeps room for the lookahead
        } else if post_residual > 0 && (next_item_size as f64) > (post_residual as f64) {
            score += 2.0; // blocks the lookahead from this bin
        }
    }

    // Last-chance bonus: if this is the only bin that fits the item, avoid
    // opening a new bin at (almost) any cost.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // over spreading; with few open bins, opening a new bin is cheaper.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln() * 4.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are already open
        // or when the stream is late and consolidation matters.
        score += 8.0 + pressure + progress * 6.0;
        // But if no open bin fits (this call is the empty-bin candidate and
        // fitting_bins_count == 0 among open bins), the new bin is necessary;
        // soften so it wins naturally.
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    } else {
        // Slight reward for using existing bins as open count grows.
        score -= pressure * 0.5;
    }

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it is a "ragged" bin; consolidating into low-residual bins keeps the
    // fleet of open bins tidy and reduces fragmentation.
    let dev = mean_residual - post_residual as f64;
    if dev > 0.0 {
        score += dev * 0.3; // prefer bins with residual near/below mean? no: prefer above-mean usage
    } else {
        score += dev * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: strongly favor bins where the item fills them exactly.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when the post residual matches the next item size
    // (chained perfect fit), penalize when the leftover is too small for the next item.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if (post_residual as f64 - next).abs() < 1.0 {
            score -= 300.0;
        } else if post_residual >= next_item_size {
            score -= 40.0; // next item can still chain into this bin
        } else {
            score += 30.0; // dead space relative to lookahead
        }

        // Penalize creating a residual that is unlikely to be usable
        // (smaller than the minimum plausible item relative to capacity).
        if post_residual < bin_capacity / 10 {
            score += 50.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // Avoid spreading items across many bins when residuals are large;
    // prefer filling bins with below-average residual (tighter bins).
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.8;
    score -= (bin_residual as f64 - mean_residual).max(0.0) * 0.3;

    // Mild pressure to prefer already-open bins over a new empty bin,
    // scaled by stream progress (early stream: more willing to open bins).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 60.0 * (1.0 - progress) + 20.0;
    }

    // Slight preference to use bins with larger residual when item is large.
    if item_size > bin_capacity / 2 {
        score -= bin_residual as f64 * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong preference for tight fits: reward small post_residual nonlinearly.
    if post_residual == 0 {
        score -= 1000.0; // perfect fill
    } else {
        let pr = post_residual as f64;
        score += (pr * pr) / bin_capacity as f64; // penalize dead space quadratically
        // dead space unusable by typical next item
        if next_item_size > 0 && (post_residual as u32) < next_item_size {
            score += pr * 2.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 500.0;
    }

    // New-bin candidate handling: make empty bin attractive only when no good fit exists.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; grows with open bins to encourage consolidation.
        score = bin_capacity as f64 * 1.5 + open_bins_count as f64 * 10.0;
        // Early in the stream, opening bins is cheaper (build a pool).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= (1.0 - progress) * 60.0;
        // If next item is large, a fresh bin is valuable.
        if next_item_size >= 60 {
            score -= 80.0;
        }
        // If many bins fit the item, opening new bin is wasteful.
        if fitting_bins_count > 2 {
            score += 150.0;
        }
    }

    // Prefer bins whose residual is close to mean (balanced packing), mildly.
    let diff = (bin_residual as f64 - mean_residual).abs();
    score += diff * 0.1;

    // Late in stream, consolidate harder: penalize opening new bins implicitly via residual.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 20.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Non-linear waste penalty: squared normalized post-residual, amplified as stream progresses.
    let norm_post = post / cap;
    score += 40.0 * norm_post * norm_post * (0.5 + progress);

    // Reward tight fits (small post_residual) more aggressively later in the stream.
    score -= 25.0 * (1.0 - norm_post) * (1.0 - norm_post) * progress;

    // Lookahead coupling: penalize if post_residual cannot host the next item, reward if it can.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            score -= 12.0 * (1.0 - ((post - nxt) / cap)) * (0.4 + 0.6 * progress);
        } else {
            score += 10.0 * (nxt - post) / cap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 18.0;
    }

    // Many open bins with slack: discourage spreading into already-loose bins.
    score += 0.02 * open_bins_count as f64 * (mean_residual / cap);

    // New empty bin candidate: mild penalty so it only wins when open bins are truly poor.
    if bin_residual == bin_capacity {
        score += 6.0 + 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small residue" classes are penalized (dead space), unless it is zero.
    let pr = post_residual;
    if pr == 0 {
        score -= 40.0; // perfect fit reward
    } else {
        // class = floor(post_residual / 10): 0..9 harmonic buckets
        let class = pr / 10;
        score += (class as f64) * 3.0;

        // Penalize tiny un-usable residues (1..=9) heavily
        if pr < 10 {
            score += 25.0;
        }
        // Sweet spot: residual in 10..=30 can absorb typical small items
        if pr >= 10 && pr <= 30 {
            score -= 12.0;
        }
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 35.0;
        } else if next_item_size < pr {
            let slack = pr - next_item_size;
            // harmonic bucket of slack after the lookahead placement
            let slack_class = slack / 10;
            score -= 8.0 - (slack_class as f64) * 1.5;
        } else {
            score += 6.0; // next item won't fit here anyway
        }
    }

    // Last chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Fractional capacity coupling: item_size as fraction of capacity
    let frac = item_size as f64 / cap;
    if frac > 0.5 {
        score -= 10.0 * frac; // large items should go into emptiest bins
    }

    // Prefer tight bins vs mean residual (best-fit bias with harmonic scaling)
    let res_frac = bin_residual as f64 / cap;
    score += res_frac * 15.0;

    // New-bin candidate handling: make empty bin mildly attractive only when
    // current item is large or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let bias = if frac > 0.6 { 20.0 } else { 0.0 };
        score = 55.0 + 30.0 * progress - bias;
    }

    // Modulo harmonic on item_size: items with size % 10 == 0 pair well
    if item_size % 10 == 0 && pr % 10 == 0 && pr > 0 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the minimum item (1..10)
    // are pure waste -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 4.0;
    }

    // Reward tight fits strongly (waste-free placement).
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward when this bin can also host the lookahead item exactly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0;
    }
    // Penalize if leftover cannot fit the lookahead item (dead space relative to future).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }

    // Last-chance pressure: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // Penalize leaving very large residuals when bins are plentiful (fragmentation risk).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.5 * (0.5 + progress);
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing ones.
    score += open_bins_count as f64 * 0.3;

    // New-bin candidate: make empty bin attractive only when current fit is bad.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin; tight fits in existing bins still win.
        score += 8.0;
        if post_residual < 10 && post_residual > 0 {
            score -= 70.0; // existing fit creates dead space -> prefer fresh bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item fits the post residual
    if next_item_size > 0 {
        let slack = post_residual as f64 - next_item_size as f64;
        if slack >= 0.0 {
            score -= 18.0 + 0.35 * slack;
        } else {
            // next item won't fit here after placement -> penalize dead space
            score += 6.0 + 0.25 * (-slack);
        }
    }

    // Compare post_residual against mean residual: avoid creating outliers
    let diff = post_residual as f64 - mean_residual;
    score += 0.08 * diff.abs() + (if diff < 0.0 { 0.05 } else { 0.0 }) * diff;

    // Last-chance bin bonus: strongly prefer filling the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Prefer tight fits (small post residual relative to bin capacity)
    score += 0.10 * (post_residual as f64 / bin_capacity as f64) * (bin_capacity as f64 - item_size as f64);

    // Mild pressure to consolidate as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 4.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    // Penalize opening a new bin when open bins exist and item fits reasonably
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 30.0 - 8.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits: small post-residual is good.
    let tight = if item_size > 0 { 1.0 - (post_residual as f64 / bin_capacity as f64).powf(2.0) } else { 1.0 };
    score -= 18.0 * tight;

    // Penalize dead space that cannot fit a typical small item (min size ~1..10).
    if post_residual < 10 {
        score -= 6.0; // small dead space is acceptable, near-perfect fill
    } else if post_residual < item_size.min(50) {
        score += 3.0; // moderately wasted space
    } else {
        score += 8.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // avoid opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0 + 0.25 * (bin_residual as f64 - post_residual as f64);
    }

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_fit = 1.0 - (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
        score -= 10.0 * chain_fit;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Post-residual becomes dead space relative to the known next item.
        score += 5.0;
    }

    // Time horizon: early in the stream, be conservative (prefer filling existing bins);
    // late in the stream, tighter packing matters less, mild bonus for any fit.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 4.0 * (1.0 - progress) * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Global state: if many bins are open with large mean residual, prefer
    // consolidating into bins (penalize opening new bins implicitly by
    // rewarding bins below mean residual usage).
    if bin_residual < bin_capacity {
        let usage = (bin_capacity as f64 - bin_residual as f64) / bin_capacity as f64;
        let mean_usage = 1.0 - mean_residual / bin_capacity as f64;
        if usage > mean_usage {
            score -= 3.0 * (usage - mean_usage);
        } else {
            score += 2.0 * (mean_usage - usage);
        }
    }

    // New-bin candidate handling: empty bin should only win when no open bin
    // fits well or the item is large relative to residual of others.
    if bin_residual == bin_capacity {
        let item_frac = item_size as f64 / bin_capacity as f64;
        // Base cost of opening a new bin; cheaper late in stream when many bins open.
        score = bin_capacity as f64 * (0.55 + 0.35 * (1.0 - progress));
        score -= 14.0 * item_frac * item_frac; // large items justify fresh bins
        if fitting_bins_count == 0 {
            score -= 40.0; // no alternative: new bin is fine
        }
        if next_item_size > 0 && next_item_size >= item_size && item_frac > 0.5 {
            score -= 6.0; // pairing large items into a fresh bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Base: post residual, scaled by a smooth non-linear progress coupling
    let mut score = pr * (1.0 + 0.5 * progress * norm_pr);

    // Penalize dead space quadratically as stream progresses
    score += 40.0 * progress * norm_pr * norm_pr;

    // Reward tight fits: low post residual relative to item size
    score -= 25.0 * norm_item * (1.0 - norm_pr);

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + progress);
    }

    // Lookahead coupling: reward leaving room for the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64 / cap;
        let gap = norm_pr - nxt;
        if gap >= 0.0 {
            score -= 12.0 * gap * (1.0 - gap.abs());
        } else {
            score += 10.0 * gap.abs() * (1.0 + progress);
        }
    }

    // Slight preference to fill bins when many bins are open
    score -= 5.0 * (open_bins_count as f64 / (open_bins_count as f64 + 5.0)) * (1.0 - norm_pr);

    // Mean residual interaction: favor bins below mean residual (tighter packing)
    let mean_norm = mean_residual / cap;
    score += 8.0 * (norm_pr - mean_norm) * (norm_pr - mean_norm) - 4.0 * (norm_pr - mean_norm);

    // New-bin candidate: penalize opening a new bin unless residual is large
    if bin_residual == bin_capacity {
        score += 30.0 + 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: reward tight fits strongly (post_residual drives priority).
    let frac = post_residual as f64 / bin_capacity as f64;

    // Harmonic class of post_residual: classify dead-space into residue classes.
    // Classes near multiples of common item sizes (10..80) are "reusable".
    let class = post_residual % 10;
    // Residuals that are small (<=10) or multiples of 10 are more likely reusable.
    if class == 0 {
        score -= 6.0;
    } else if class <= 3 {
        score += 2.0 * class as f64;
    } else {
        score += 1.0;
    }

    // Integer-division thresholds: residual that can host the next item is gold.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
        // Extra bonus if post_residual - next_item_size is itself small (chained tight fit).
        let chain = post_residual - next_item_size;
        if chain <= 10 {
            score -= 4.0;
        }
        score -= (chain as f64).ln().max(0.0);
    } else if next_item_size > 0 {
        // This bin becomes dead for the next item: penalize proportionally.
        score += 3.0 + 0.1 * next_item_size as f64;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate logic: only attractive if existing bins would waste a lot.
    if bin_residual == bin_capacity {
        // Opening a new bin costs ~1 bin; make it unattractive unless frac of best
        // alternative is bad. We approximate: new bin score = capacity-based baseline.
        score = 40.0 + frac * 10.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // fresh bin fits future big items well
        }
    } else {
        // Existing bin: subtract a bonus scaled by how full the bin already is,
        // encouraging closing out nearly-full bins (best-fit-like behavior).
        let fullness = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= 5.0 * fullness;
    }

    // Stream progression: late in the stream, avoid leaving many scattered bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.05 * open_bins_count as f64 * progress;
    score += 0.1 * (mean_residual - frac * bin_capacity as f64).abs();

    // Modulo harmonic coupling on item size classes (odd/even style granularity).
    if item_size % 2 == 0 && post_residual % 2 == 0 {
        score -= 1.5;
    }
    if item_size % 5 == 0 && post_residual % 5 == 0 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residual gaps that are too small to hold
    // typical items (below the minimum plausible item size ~10) are dead space.
    // Penalize them quadratically; residual in a "usable" band is mildly OK.
    let pr = post_residual as f64;
    if post_residual > 0 {
        if post_residual < 10 {
            // unusable sliver -> heavy penalty
            score += (10.0 - pr) * 12.0;
        } else if post_residual < 20 {
            // marginal gap, only fits tiny items -> moderate penalty
            score += (20.0 - pr) * 3.0;
        } else {
            // large usable residual -> mild reward (subtracted)
            score -= (pr - 20.0).min(40.0) * 0.15;
        }
    } else {
        // perfect fill: strong reward
        score -= 25.0;
    }

    // Tight fit reward: item fills most of the bin's current residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fill_ratio > 0.85 && post_residual > 0 {
        score -= 8.0 * fill_ratio;
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // strongly favor this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 4.0;
    }

    // Open bins pressure: discourage scattering across many bins; prefer
    // filling existing bins when many are open.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    score += pressure * 0.3;

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Make it attractive only when open bins are scarce or residuals are
    // badly fragmented; otherwise it should lose to good existing fits.
    if bin_residual == bin_capacity {
        score += 18.0; // default penalty: prefer reusing open bins
        if open_bins_count == 0 {
            score -= 100.0; // must open a bin
        }
        // if mean residual of open bins is large but this item is large too,
        // a fresh bin can be preferable
        if mean_residual > 0.0 && (item_size as f64) > mean_residual + 15.0 {
            score -= 10.0;
        }
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    }

    // Mean residual coupling: prefer bins whose residual is below the mean
    // (i.e., more filled bins get priority).
    score += (mean_residual - bin_residual as f64).max(-30.0).min(30.0) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly favor exact/tight fits: post_residual == 0 is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize small dead space quadratically (unusable slivers).
        let pr = post_residual as f64;
        score += 0.05 * pr * pr / bin_capacity as f64;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 >= nxt {
            // Next item fits after this placement: big reward, tighter coupling
            // when the leftover after the next item is also small.
            let after_next = post_residual as f64 - nxt;
            score -= 40.0 + 0.3 * (bin_capacity as f64 - after_next);
        } else {
            // Next item won't fit: penalize proportionally to how close we came
            // (near-miss wastes the lookahead opportunity).
            let miss = nxt - post_residual as f64;
            score += 10.0 + 0.4 * miss;
        }
    }

    // Relative-to-mean coupling: bins below mean residual are "fuller" and
    // should be preferred to close them out; bins above mean are wasteful.
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive early in the stream or when no bin fits well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 60.0 + 80.0 * progress;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: new bin must be used
        }
    }

    // Late in the stream, consolidate harder (prefer filling existing bins).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear)
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Penalize small dead space that is hard to reuse (post_residual in awkward range)
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 10.0 {
        score += 12.0 * (10.0 - pr);
    } else if pr >= 10.0 && pr <= 25.0 {
        score -= 4.0; // reusable band
    }

    // Last-chance bonus: only bin that fits -> strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits in post_residual, reward; else penalize
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0 + 0.1 * next_item_size as f64;
        } else {
            score += 3.0;
        }
    }

    // New-bin candidate handling: make empty bin attractive only when existing fits are poor
    if bin_residual == bin_capacity {
        // baseline cost of opening a new bin
        score += 30.0;
        // but if many bins are open and mean residual is large, prefer new bin less
        score += 0.5 * open_bins_count as f64;
        // early in stream, opening bins is fine (exploration)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 25.0 * (1.0 - progress);
        // if next item is large, fresh bin is valuable
        if next_item_size > 60 {
            score -= 15.0;
        }
    } else {
        // Prefer bins whose residual deviates from mean (consolidate)
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
        // favor fullest bins slightly
        score -= 0.05 * bin_residual as f64;
    }

    // Late in stream: avoid opening new bins, squeeze existing
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 20.0 * progress;
    } else {
        score -= 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let is_new_bin = (bin_residual as f64 - cap).abs() < 1e-9;

    // Base: prefer small post residual (tight fit)
    let mut score = pr;

    // Non-linear tightness reward: quadratic coupling of fit quality with stream progress
    let fit_quality = 1.0 - pr / cap; // 1 = perfect fit
    score -= 12.0 * fit_quality * fit_quality * (0.5 + progress);

    // Penalize unusable dead space (post_residual too small for typical future items)
    let dead = (1.0 - pr / cap).max(0.0);
    score += 8.0 * (pr / cap) * (pr / cap) * (1.0 - progress);

    // Last-chance bonus: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 20.0 * (1.0 - progress);
    }

    // Lookahead: if next item fits exactly in post_residual, reward heavily
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if ni <= pr {
            let leftover = pr - ni;
            score -= 10.0 * (1.0 - leftover / cap);
        } else {
            score += 4.0 * (ni / cap);
        }
    }

    // New-bin candidate: penalize mildly so open bins are preferred unless very poor fits;
    // penalty decays with progress (later in stream, consolidation matters more)
    if is_new_bin {
        score += 15.0 * (1.0 - 0.5 * progress) - 0.3 * mean_residual;
    } else {
        // Reward bins whose residual deviates favorably from the mean (consolidation)
        score -= 0.2 * (mean_residual - pr);
    }

    // Mild penalty for many open bins to discourage fragmentation
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic penalty on wasted space
    score += (post_residual as f64 / bin_capacity as f64).powi(2) * 30.0;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 100.0;
    }

    // Harmonic class of post_residual: dead space is only "usable"
    // if a future item (sizes 1..=100) can fill it. Class the residual
    // by integer division thresholds.
    let r = post_residual;
    let class = r / 10; // harmonic class width 10
    match class {
        0 => score -= 20.0,          // r < 10: nearly dead space, good
        1 => score -= 8.0,           // 10..=19: small items can still fit
        2 | 3 => score += 4.0,       // mid residual: ambiguous
        4 | 5 => score += 10.0,      // large residual: wasteful placement
        _ => score += 18.0,          // huge residual left behind
    }

    // Modulo coupling: residuals divisible by common item sizes are
    // more likely to be filled exactly later.
    if r > 0 {
        if r % 10 == 0 { score -= 6.0; }
        if r % 25 == 0 { score -= 4.0; }
        if r % 50 == 0 { score -= 4.0; }
    }

    // Lookahead: prefer bins whose post_residual fits the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
        // chain fit: post_residual - next_item still small
        let chain = post_residual - next_item_size;
        if chain < 10 {
            score -= 8.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item cannot use leftover: leftover is dead weight
        score += (post_residual as f64) * 0.15;
    }

    // Last chance bin: strongly favor using it before opening new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        // Opening a new bin is attractive only if no tight fit exists
        // among open bins and item is large (would strand small residual
        // in an existing bin).
        let progress = step_index as f64 / total_items.max(1) as f64;
        if fitting_bins_count == 0 {
            score -= 50.0; // must open new bin
        } else if item_size >= 60 && post_residual <= 40 {
            score -= 10.0 + progress * 10.0; // big item, fresh bin keeps flexibility
        } else {
            score += 40.0; // prefer existing bins generally
        }
        // Penalize opening bins when many are already open with slack
        if mean_residual > 30.0 && open_bins_count > 2 {
            score += 15.0;
        }
    }

    // Mild pressure to consolidate when many bins are open
    score += open_bins_count as f64 * 0.3;

    // Slight preference to fill bins with lower residual (tighter bins)
    score += (bin_residual as f64 - post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the minimum item (1..=100 range)
    // are wasted. Penalize gaps below the smallest plausible item size harshly.
    let min_item = 1u32;
    if post_residual < min_item {
        score += 1000.0; // perfect fill, great
    } else if post_residual < 10 {
        // dead space: unusable for typical items
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    } else if post_residual < 20 {
        score += 15.0 + (20 - post_residual) as f64 * 2.0;
    }

    // Reward tight fits: post_residual close to 0 relative to capacity
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Open-bin pressure: discourage spreading when many bins are open
    score += (open_bins_count as f64) * 1.5;

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits the post_residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // next item cannot fit; leftover becomes dead space risk
        score += 6.0;
    }

    // Deviation from mean residual: prefer bins with residual below mean (denser bins)
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // Early stream: be more conservative about opening new bins (favor fitting)
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // new-bin candidate: penalize unless residual usage would be very wasteful
        score += 20.0 - 15.0 * progress;
        if item_size > bin_residual / 2 {
            score -= 10.0; // big item, fine to open fresh bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // closely matches the next item's size.
    if next_item_size > 0 {
        let next_f = next_item_size as f64;
        let post = post_residual as f64;
        let match_gap = (post - next_f).abs();
        // Exact match is a jackpot: next item fills this bin perfectly.
        if next_f <= post {
            score -= 30.0 * (1.0 - match_gap / (bin_capacity as f64));
            // Perfect chain (post_residual == next_item_size) heavily favored
            if post == next_f {
                score -= 40.0;
            }
        } else {
            // Next item cannot fit here; mild penalty scaled by overshoot.
            score += 5.0 + 0.2 * (next_f - post);
        }
    } else {
        // Last item: just minimize waste.
        score += 0.0;
    }

    // Prefer tight fits generally.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 10.0 * tightness;

    // Penalize bins far from the mean residual (avoid fragmentation outliers).
    score += 0.3 * ((post_residual as f64) - mean_residual).abs();

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: discourage unless residual capacity is truly needed
    // (i.e., current item barely fits nowhere well and next item is large).
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 45.0;
        // But if the next item is large and post_residual is large too,
        // a fresh bin may be attractive; discount slightly.
        if next_item_size > 0 && (next_item_size as f64) > post_residual as f64 {
            score -= 15.0;
        }
        // Early in the stream, new bins are cheaper (more future to amortize).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;

    // Reward tight fits: smaller post_residual relative to capacity is better.
    let tightness = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 6.0 * tightness;

    // Reward bins where the lookahead item also fits (chained packing).
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 4.0 + 3.0 * progress;
    } else if next_item_size > 0 {
        // Penalize leaving dead space that the next item cannot use.
        score += 2.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 8.0;
    }

    // Align with global mean residual: prefer bins close to mean residual
    // (keeps residual distribution balanced).
    let drift = (bin_residual as f64 - mean_residual).abs();
    score += 0.08 * drift;

    // New-bin candidate handling: penalize opening a new bin mildly, but
    // allow it for large items or when many bins already fit (fragmented state).
    if is_new_bin {
        let base_penalty = 10.0;
        let large_item_bonus = if item_size >= bin_capacity / 2 { 6.0 } else { 0.0 };
        let fragmentation_bonus = if fitting_bins_count >= 3 { 4.0 } else { 0.0 };
        let late_stream_bonus = 5.0 * progress;
        score += base_penalty - large_item_bonus - fragmentation_bonus - late_stream_bonus;
    } else {
        // Slight reward for using already-open bins, stronger late in stream.
        score -= 2.0 + 2.0 * progress;
    }

    // Mild penalty for very small leftovers that are likely dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual
    let t = step_index as f64 / total_items.max(1) as f64;

    // Smooth polynomial coupling of residual with stream progress
    let poly = x * x * (1.0 - t) + x * t * (1.0 - x);
    score += 12.0 * poly;

    // Penalize dead space that cannot fit the next item (smooth interaction)
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let waste = ((nx - x).max(0.0)) / cap;
        score += 20.0 * waste * (0.5 + t);
    }

    // Reward using the last fitting bin (avoid opening a new bin)
    if fitting_bins_count == 1 {
        score -= 8.0 * (1.0 - x);
    }

    // Mild penalty for spreading across many bins; encourage filling dense bins
    score += 0.05 * open_bins_count as f64 * x;

    // Align with mean residual: prefer bins below mean (denser packing)
    score += 0.3 * (mean_residual - pr) / cap;

    // New-bin candidate: keep it neutral-to-slightly-high unless item fits perfectly
    if bin_residual == bin_capacity {
        score += 3.0 - 6.0 * (1.0 - x);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fits (0), tiny slivers (1..=5),
    // mid classes, and large residuals.
    let post = post_residual;
    if post == 0 {
        score -= 60.0; // perfect fit is ideal
    } else if post <= 5 {
        score += 25.0; // dead sliver, nearly wasted space
    } else if post <= 10 {
        score += 10.0;
    } else if post <= 20 {
        score += 4.0;
    } else if post <= 30 {
        score -= 2.0;
    } else {
        score -= 6.0; // large residual keeps flexibility
    }

    // Modulo-10 harmonic classes: residuals that are multiples of 10 pair
    // well with the 10..80 item grid.
    if post % 10 == 0 && post > 0 {
        score -= 5.0;
    }

    // Lookahead coupling: does next_item_size fit into post_residual exactly?
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 40.0; // chain of perfect fits
        } else if next_item_size < post {
            let gap = post - next_item_size;
            if gap <= 5 {
                score += 8.0; // would create a sliver next step
            } else {
                score -= gap as f64 * 0.3; // good chain potential
            }
        } else {
            // next item cannot use this bin's remainder; residual may go idle
            score += (post.min(next_item_size.saturating_sub(post)) as f64) * 0.15;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize mildly so we only open when fits are bad,
    // scaled by how many bins are already open (avoid bin sprawl).
    if bin_residual == bin_capacity {
        score += 45.0 + 2.0 * open_bins_count as f64;
        // but if item is huge and would leave a bad residual anywhere, allow it
        if item_size >= 70 {
            score -= 20.0;
        }
    }

    // Prefer tighter bins generally: reward small residual before placement.
    score -= (bin_capacity - bin_residual) as f64 * 0.1;

    // Progress-based mild adaptation: early on, keep residuals flexible.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * post as f64 * 0.05;

    // Deviation from mean residual: bins far below mean are precious.
    if (bin_residual as f64) < mean_residual {
        score += (mean_residual - bin_residual as f64) * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // later are heavily penalized. Treat residual <= 20 as near-dead space.
    let dead_threshold = 20.0f64;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 4.0;
    }

    // Reward perfect / near-perfect fills strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Coupling with open bins pressure: more open bins -> prefer filling
    // existing bins over opening new ones, scaled by how empty the bin is.
    let pressure = open_bins_count as f64 * (bin_residual as f64 / bin_capacity as f64);
    score -= pressure * 0.5;

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Post residual too small for next item: penalize proportionally.
        score += (next_item_size as f64 - post_residual as f64) * 0.5;
    }

    // Penalize placing into a bin whose residual is much larger than the item
    // when other bins exist (wasteful big-gap consumption).
    if bin_residual > item_size * 2 && open_bins_count > 1 && bin_residual != bin_capacity {
        score += (bin_residual - item_size * 2) as f64 * 0.3;
    }

    // Early in the stream, be slightly more willing to consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0;

    // New-bin candidate: keep it moderately attractive only when open bins
    // are crowded or the item is large.
    if bin_residual == bin_capacity {
        let crowded = open_bins_count as f64 * 8.0;
        let large_item_bonus = (item_size as f64 - 50.0).max(0.0);
        score += 40.0 + crowded - large_item_bonus - mean_residual * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong preference for tight fits: reward small post_residual non-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // 2-step lookahead: if the next item fits exactly into the post_residual,
    // this placement chains perfectly -> big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            // next item fits but leaves slack; penalize proportional to leftover slack
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 - slack.min(12.0);
        } else {
            // next item won't fit after this placement: penalize dead space
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Compare against mean residual: bins with residual near/below mean are
    // better consolidation targets.
    let mean_gap = post_residual as f64 - mean_residual;
    score += 0.15 * mean_gap;

    // Penalize very large leftover residual (wasteful placement) super-linearly.
    if post_residual > bin_capacity / 2 {
        score += 0.2 * (post_residual as f64 - bin_capacity as f64 / 2.0);
    }

    // Slight preference for filling older bins when many bins are open.
    score += 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when item is huge relative to capacity
    // or the fit would be terrible elsewhere.
    if bin_residual == bin_capacity {
        if item_size >= bin_capacity * 8 / 10 {
            score -= 10.0;
        } else {
            score += 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a superlinear penalty curve.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that no future item can plausibly fill.
    if post_residual > 0 {
        let dead = if next_item_size > 0 && next_item_size <= post_residual { 0.0 }
                   else { (post_residual as f64).powf(1.35) };
        score += 0.6 * dead;
    }

    // Lookahead: reward bins that can also host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0 + 0.05 * next_item_size as f64;
    } else if next_item_size > post_residual {
        score += 0.15 * (next_item_size as f64 - post_residual as f64);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 8.0;
    } else if fitting_bins_count > 2 {
        // Many alternatives: slight penalty to keep flexibility elsewhere.
        score += 1.5 * (fitting_bins_count as f64 - 2.0).sqrt();
    }

    // Prefer filling bins that are already relatively full vs. fresher bins,
    // scaled by how the bin compares to the average residual.
    let rel = bin_residual as f64 - mean_residual;
    score -= 0.08 * rel;

    // Time horizon: early in the stream, be conservative (favor tight fits,
    // tolerate opening bins); late in the stream, minimize leftover waste.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.25 * progress;

    // New-bin candidate: make it attractive only when no open bin fits well.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        // Cost of a new bin amortized; less penalized late in the stream.
        score += 18.0 - 6.0 * progress;
    }

    // Mild discouragement of bin proliferation early on.
    score += 0.02 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;

    // Smooth non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * (1.0 - norm_pr);
    score += 4.0 * poly * cap;

    // Penalize large dead space more as stream progresses (less chance to reuse)
    score += progress * norm_pr * norm_pr * 30.0;

    // Reward tight fits (small post_residual) with a smooth bonus
    score -= (1.0 - norm_pr).powi(3) * 10.0;

    // Last-chance bin: strongly reward using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits the post residual, reward this placement
    if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        score -= 8.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        score += 3.0 * (next_item_size as f64 / cap) * norm_pr;
    }

    // Mild penalty for many open bins relative to mean residual imbalance
    let dev = (pr - mean_residual) / cap;
    score += 2.0 * dev * dev * cap;

    // New-bin candidate: keep it neutral-ish, slightly penalized unless residuals are high
    if bin_residual == bin_capacity {
        score += 5.0 - 10.0 * mean_residual / cap;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: classify dead space into capacity fractions
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // 0..1 fraction of capacity left over

    // Class boundaries via integer division thresholds on post_residual
    let class = post_residual / 10; // 0..=10 harmonic classes
    match class {
        0 => score -= 60.0,          // perfect fit: residual 0..9
        1 => score -= 35.0,          // near-perfect: 10..19
        2 => score -= 15.0,          // good: 20..29
        3 => score -= 5.0,           // acceptable: 30..39
        4 => score += 8.0,           // awkward zone
        5 => score += 15.0,          // half-empty: wasteful
        6 => score += 10.0,
        7 => score += 4.0,           // large residual may still fit big items
        _ => {}
    }

    // Non-linear penalty on fraction: penalize mid-range waste (0.3..0.6)
    if frac > 0.25 && frac < 0.65 {
        score += 25.0 * (frac - 0.25) * (0.65 - frac);
    }

    // Reward tight fits with a smooth bonus
    score -= 40.0 * (-frac * 8.0).exp();

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Many open bins: discourage spreading, prefer consolidation
    score += 0.4 * open_bins_count as f64;

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0;
        } else if next_item_size <= post_residual {
            score -= 12.0 * (post_residual - next_item_size) as f64 / cap;
        } else {
            // next item cannot use the leftover: penalize small unusable leftovers
            let gap = (next_item_size - post_residual) as f64;
            if gap < 10.0 {
                score += 10.0;
            }
        }
    }

    // New-bin candidate handling: empty bin gets a mild baseline penalty so it's
    // only chosen when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 45.0 - 0.15 * open_bins_count as f64;
    }

    // Deviation from mean residual: prefer bins that keep residuals balanced
    let dev = pr - mean_residual;
    score += 0.05 * dev * dev.abs();

    // Early in the stream, allow more freedom to open bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space strongly.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 18.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many bins open, prefer consolidating into existing bins.
    score += open_bins_count as f64 * 1.5;

    // New empty bin candidate: penalize unless it enables a better future fit.
    if bin_residual == bin_capacity {
        score += 35.0;
        // If next item is large and this item is small, opening a fresh bin may be wise.
        if next_item_size > 60 && item_size < 30 {
            score -= 40.0;
        }
    }

    // Lookahead: reward leaving space exactly for the next item.
    if next_item_size > 0 && post_residual as f64 == next_item_size as f64 {
        score -= 30.0;
    }

    // Slight preference for using tighter bins (small residual before placement).
    score += (bin_residual as f64) * 0.05;

    // Progress term: early in the stream, be a bit more conservative with new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 2.0;

    // Mean residual coupling: if mean residual is high, prefer filling a bin well.
    score -= (mean_residual - post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect lookahead match (item 2 fits exactly): strong reward
        if post_residual == next_item_size {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Next item fits in the residual left behind: reward proportional to tightness
            score -= 40.0 * (1.0 - diff / (bin_capacity as f64));
        } else {
            // Next item won't fit in the leftover space: penalize wasted potential
            score += 10.0 + 0.5 * diff;
        }
    } else {
        // Last item: purely minimize leftover
        score += 0.0;
    }

    // Relative-to-mean coupling: prefer bins tighter than average when lookahead is good
    let mean_gap = post_residual as f64 - mean_residual;
    score += 0.15 * mean_gap;

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Penalize creating tiny unusable dead space (unless next item matches it)
    if post_residual > 0 && next_item_size > post_residual && post_residual < 10 {
        score += 20.0;
    }

    // Slight preference for using existing bins over opening new ones,
    // but relax as stream progresses (late stream: consolidation matters more)
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize early, allow late when open bins are fragmented
        score += 30.0 - 20.0 * progress;
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Mild pressure to fill fuller bins as the stream advances
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    let cap = bin_capacity as f64;
    let tight = 1.0 - (post_residual as f64) / cap;
    score -= 18.0 * tight * tight;

    // Penalize dead space that can never be reused by typical items (post_residual < 10).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: bonus if next item fits exactly in the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // next item won't fit here; slight penalty proportional to wasted potential
            score += 4.0 * (next_item_size as f64 - post_residual as f64) / cap;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 2 {
        // many alternatives: mild penalty to encourage spreading exploration
        score += 1.5 * (fitting_bins_count as f64 - 2.0);
    }

    // Prefer bins with residual below the mean (consolidate fragmentation).
    score += 0.6 * ((bin_residual as f64) - mean_residual);

    // Time horizon: early in stream, favor filling existing bins less aggressively
    // (keep options open); late in stream, squeeze everything.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * tight;

    // New-bin candidate handling: empty bin gets a mild penalty so it's chosen
    // only when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 12.0 - 8.0 * (1.0 - progress);
        // If next item is large and current item is small, opening fresh bin is attractive.
        if next_item_size >= 60 && item_size <= 30 {
            score -= 6.0;
        }
    }

    // Mild penalty for many open bins (encourage consolidation overall).
    score += 0.15 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;
    let tightness = 1.0 - (pr / cap); // how full the bin becomes

    // Base: prefer small post-residual, with non-linear sharpening
    let mut score = pr * (1.0 + 0.8 * tightness * tightness);

    // Polynomial coupling of post-residual with stream progress:
    // late in the stream, dead space becomes more costly
    let progress_coupling = pr * pr / cap * (0.5 * progress * progress + 0.3 * progress);
    score += progress_coupling;

    // Reward near-perfect fits smoothly (cubic in tightness)
    score -= 12.0 * tightness * tightness * tightness;

    // Penalize leaving residuals that likely cannot host future items
    let nxt = next_item_size as f64;
    if nxt > 0.0 {
        let gap = (pr - nxt).max(0.0);
        score += 0.6 * gap * gap / cap;
        // bonus if this placement leaves room exactly compatible with next item
        if pr >= nxt && pr - nxt < 10.0 {
            score -= 4.0 * (1.0 - (pr - nxt) / 10.0);
        }
    }

    // Last-chance bonus: avoid opening a new bin when few options fit
    if fitting_bins_count == 1 {
        score -= 8.0 * fit_ratio;
    }

    // Mild pressure toward consolidating many open bins
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    // Smooth alignment with mean residual: prefer bins below mean residual (packing fuller bins)
    score += 0.3 * (mean_residual - pr).max(0.0);

    // New-bin candidate: penalize slightly so it only wins for genuinely poor fits
    if bin_residual == bin_capacity {
        score += 15.0 + 20.0 * progress;
        // but allow fresh bin when item is large and residuals are tight
        score -= 25.0 * fit_ratio * (mean_residual / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space classification by modulo classes.
    // Residuals in [1..10] are nearly unusable (items >= 10 typically, but sizes 1..100 possible),
    // [10..20] marginal, larger residuals are valuable.
    if post_residual == 0 {
        // Perfect fit: strongly reward.
        score -= 200.0;
    } else if post_residual <= 5 {
        // Dead space: heavily penalize.
        score += 120.0;
    } else if post_residual <= 10 {
        score += 60.0;
    } else if post_residual <= 20 {
        score += 25.0;
    }

    // Modulo arithmetic on post_residual: residuals that are multiples of common
    // size granularities (e.g. multiples of 10) are more reusable.
    if post_residual > 0 && post_residual % 10 == 0 {
        score -= 15.0;
    }
    // Residuals congruent to small values mod 10 pair well with typical item tails.
    if post_residual % 10 <= 2 && post_residual > 0 {
        score += 8.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post_residual,
    // this placement chains perfectly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 90.0;
        } else if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            if slack <= 10 {
                score -= 40.0;
            } else {
                score -= 10.0;
            }
        } else {
            // Next item cannot use this bin's remainder: penalize proportionally.
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Last-chance bin: if this is the only fitting bin, prefer using it over
    // opening a new bin (unless it would create dead space).
    if fitting_bins_count == 1 && post_residual <= 20 {
        score -= 50.0;
    }

    // New-bin candidate: reserve it unless current bins fit poorly.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin; adjusted by how crowded existing bins are.
        score += 70.0;
        if mean_residual < 15.0 {
            // Existing bins are nearly full; a new bin is reasonable.
            score -= 30.0;
        }
        if next_item_size > 0 && next_item_size >= 60 {
            // Large upcoming item may need fresh capacity.
            score -= 10.0;
        }
    }

    // Fraction of stream elapsed: late in the stream, prefer tighter packing
    // (fewer bins) since no future amortization of open bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0;

    // Slight preference for bins that are already fuller (small residual before placement).
    score += (bin_residual as f64) * 0.05;

    // Penalize scattering across many open bins mildly.
    score += open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space: gaps below the minimum item size are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 100.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 25.0 * (1.0 - (post_residual as f64) / 20.0);
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 50.0;
    }

    // Reward using bins that leave room for the lookahead item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // Last chance bin: strongly favor to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Open bins pressure: discourage opening new bins when many are open
    if bin_residual == bin_capacity {
        score += 30.0 + 5.0 * (open_bins_count as f64);
    }

    // Slight preference for fuller bins relative to mean residual
    score += (mean_residual - bin_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Slack after accommodating the next item: smaller is better.
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 - slack.min(40.0);
        } else {
            // Next item cannot fit here; penalize proportionally to the shortfall.
            let shortfall = (next_item_size - post_residual) as f64;
            score += shortfall * 0.5;
        }
    }

    // Penalize leaving tight dead space that nothing (sizes >= 1) can use later.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Prefer bins with residuals below the mean (tighter packing target).
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // Early in the stream, allow opening fresh bins more freely; later, conserve bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline near mean residual, rising penalty later in stream.
        score = mean_residual + 10.0 + progress * 30.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0; // a fresh bin always fits the next item
        }
        if fitting_bins_count <= 1 {
            score -= 25.0; // no good alternative exists
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squared dead-space penalty.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64 * 2.0);

    // Reward perfect fit strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 10 {
        score -= 50.0;
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0 + 0.5 * item_size as f64;
    }

    // Lookahead: if next item fits in the post residual, reward; else penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0;
        } else {
            score += 8.0;
        }
        // If next item fits perfectly after this placement, big reward.
        if next_item_size == post_residual {
            score -= 60.0;
        }
    }

    // New empty bin candidate: penalize unless item is large or no real alternative.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let large_item = (item_size as f64) > 0.6 * bin_capacity as f64;
        if large_item {
            score -= 10.0;
        } else if fitting_bins_count > 1 {
            score += 60.0 + 40.0 * (1.0 - progress);
        }
        // Mildly favor new bins late in stream when open bins are fragmented.
        if open_bins_count > 3 && mean_residual < item_size as f64 {
            score -= 20.0;
        }
    }

    // Prefer bins with residual close to item (relative fit quality).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio;

    // Slight preference for fuller bins overall.
    score -= 0.05 * (bin_capacity - bin_residual) as f64;

    // Time-decay term: early on be conservative with dead space; later accept.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.2 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_post = pr / cap;

    // Base: penalize remaining space, scaled non-linearly by stream progress.
    // Late in the stream, leftover space is more likely to become dead weight.
    let mut score = pr * (0.6 + 0.8 * progress * progress);

    // Smooth polynomial coupling: squared normalized post-residual term,
    // emphasizing avoidance of small unusable slivers (post_residual near 0
    // is great -> reward; moderate leftovers are wasteful).
    score += 12.0 * norm_post * norm_post * (1.0 - norm_post) * cap * (0.3 + 0.7 * progress);

    // Perfect fit reward (smooth, not piecewise).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * fit_ratio * fit_ratio;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 8.0 + 6.0 * progress;
    } else {
        // Slight penalty when many bins compete: prefer tighter consolidation.
        score += (fitting_bins_count as f64).ln() * 1.5;
    }

    // Lookahead coupling: reward leaving space that can still host the next item.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        let usable = (pr - ni).max(0.0);
        score -= 4.0 * (usable / cap) * (usable / cap).sqrt();
        // Penalize leaving exactly awkward space that barely misses next item.
        if pr >= ni && pr - ni < ni {
            score += 3.0 * (1.0 - (pr - ni) / ni.max(1.0));
        }
    }

    // Open-bin pressure: mildly discourage proliferating bins early.
    score += (open_bins_count as f64).sqrt() * (1.5 - progress) * 0.5;

    // Alignment with mean residual: prefer bins close to the average state
    // (keeps residual distribution balanced, smooth quadratic).
    let dev = (pr - mean_residual) / cap;
    score += 5.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "nice"
    // residue classes (small leftovers) are rewarded.
    let pr = post_residual as i64;
    let cap = bin_capacity as i64;

    // Reward tight fits: post_residual small relative to capacity.
    if pr == 0 {
        score -= 100.0; // perfect packing
    } else if pr <= 5 {
        score -= 40.0;
    } else if pr <= 10 {
        score -= 25.0;
    } else if pr <= 20 {
        score -= 10.0;
    }

    // Modulo-10 harmonic class: leftover divisible by 10 is more reusable
    // for typical item sizes.
    if pr > 0 && pr % 10 == 0 {
        score -= 8.0;
    }
    // Odd leftovers are less reusable.
    if pr % 2 == 1 && pr < 30 {
        score += 4.0;
    }

    // Lookahead: does the next item fit into the post_residual?
    if next_item_size > 0 {
        let nx = next_item_size as i64;
        if nx == pr {
            score -= 60.0; // chain: next item exactly fills this bin
        } else if nx <= pr {
            // next fits; reward proportional to how well it reuses space
            let reuse = (nx as f64) / (pr as f64);
            score -= 20.0 * reuse;
            if pr - nx <= 5 {
                score -= 15.0;
            }
        } else {
            // next item won't fit here; penalize leaving a big unusable gap
            if pr < nx && pr < 15 {
                score += 12.0; // dead space that even the next item can't use
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Many open bins: prefer consolidating into already-open bins over
    // opening new ones (penalize the new-bin candidate implicitly).
    if bin_residual == bin_capacity {
        // brand-new empty bin candidate
        score += 10.0 + 3.0 * (open_bins_count as f64);
        // but early in stream, opening bins is fine
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 20.0 * (1.0 - progress);
    }

    // Prefer bins whose residual is below the mean (use up the tight bins first).
    score += 0.15 * (mean_residual - bin_residual as f64);

    // Fraction-of-capacity class of the item: large items should go into
    // large-residual bins; small items prefer small-residual bins.
    let item_frac = item_size as f64 / bin_capacity as f64;
    let resid_frac = bin_residual as f64 / bin_capacity as f64;
    score += 10.0 * (resid_frac - item_frac).abs();

    // Integer-division threshold: post_residual in [1..=item/2] is nearly dead.
    if pr > 0 && pr <= (item_size as i64) / 2 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps (1..=12) are nearly unusable
    // given items >= 1 but practically hard to fill; penalize them heavily.
    if post_residual > 0 && post_residual <= 12 {
        score += (13 - post_residual as i32) as f64 * 8.0;
    }
    // Perfect fit is highly desirable.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack <= 12 {
            score -= 30.0 - slack as f64;
        } else {
            score -= 8.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item can't follow here; this bin's leftover is likely dead space.
        score += 10.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage scattering across many bins unless fit is tight.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * (open_bins_count as f64).ln().max(1.0) * 5.0;

    // Mild preference toward bins below the mean residual (fill emptier bins first
    // keeps tight bins available for future small items).
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    }

    // New empty bin candidate: make it unattractive unless current residuals are
    // all poor fits (post_residual small) — then a fresh bin is worth opening.
    if bin_residual == bin_capacity {
        score += 60.0;
        if fitting_bins_count >= 1 {
            // Existing bins can take the item; only open a new bin if every
            // existing fit would leave a tiny dead gap.
            score += 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item exactly
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual as i64 - next_item_size as i64 == 0 {
            score -= 500.0; // chainable: next item fits perfectly
        } else if (post_residual as i64 - next_item_size as i64) > 0 {
            score -= (10.0 - gap.min(10.0)) * 3.0; // next item still fits
        } else {
            score += gap * 2.0; // dead space relative to next item
        }
    } else {
        // last item: just minimize residual
        score -= 50.0;
    }

    // Penalize small unusable residuals (dead space) more than linear
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // New empty bin candidate: penalize unless no good fit exists among open bins
    if bin_residual == bin_capacity {
        let base = 30.0 + (mean_residual * 0.5);
        let penalty = if fitting_bins_count == 0 { -200.0 } else { 0.0 };
        score += base + penalty;
    }

    // Prefer bins tighter than the mean residual (better packing density)
    score += (post_residual as f64 - mean_residual) * 0.4;

    // Early in stream: be slightly conservative (keep bins flexible)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 20.0;

    // Prefer fewer open bins overall
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize large dead space quadratically.
    score += 0.05 * (post_residual as f64) * (post_residual as f64);

    // Reward tight fits (small post_residual relative to item).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item exactly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
            if post_residual == next_item_size {
                score -= 20.0; // perfect chain fit
            }
        } else {
            // dead space that next item cannot use
            score += 0.5 * (next_item_size.saturating_sub(post_residual)) as f64;
        }
    }

    // New-bin candidate logic: prefer opening a new bin when residuals are large
    // and item is big relative to mean residual.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let openness = mean_residual / bin_capacity as f64;
        // open new bin if item barely fits in average open bin
        let tightness = item_size as f64 / bin_capacity as f64;
        let new_bin_bias = 40.0 * (openness - tightness) + 20.0 * (1.0 - progress);
        // If no open bin fits well, new bin is attractive
        if open_bins_count == 0 {
            score -= 100.0;
        } else if openness - tightness > 0.25 {
            score -= new_bin_bias;
        } else {
            score += 15.0; // discourage wasting a fresh bin on small item
        }
    }

    // Mild penalty for spreading across many open bins (encourages consolidation).
    score += 0.3 * open_bins_count as f64;

    // Time-decay: later in stream, be more conservative (favor tighter fits more).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let pr_norm = post / cap;

    // Base: prefer tight fits (low post_residual), with non-linear sharpening
    let mut score = post * (1.0 + 0.8 * pr_norm * pr_norm);

    // Polynomial coupling with stream progress: late in the stream, waste is costlier
    score += 40.0 * progress * pr_norm * pr_norm;
    score -= 15.0 * (1.0 - progress) * pr_norm * (1.0 - pr_norm);

    // Penalize dead space relative to the mean residual of open bins
    score += 0.35 * (post - mean_residual).abs();

    // Last-chance bonus: only this bin fits, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Lookahead coupling: reward if next item fits the post residual smoothly
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= post {
            let fill = nx / post.max(1.0);
            score -= 25.0 * fill * (1.0 - fill) * 4.0;
        } else {
            score += 12.0 * (nx - post) / cap;
        }
    }

    // New-bin candidate: mildly discourage unless residuals are fragmented
    if bin_residual == bin_capacity {
        score += 8.0 + 10.0 * progress;
        if mean_residual < 20.0 {
            score -= 18.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post-residual: residue classes modulo 10.
    // Residuals that are "usable" (multiples of common item sizes) are rewarded.
    let pr = post_residual as u32;
    let class = pr % 10;
    if pr == 0 {
        score -= 30.0; // perfect fit
    } else if class == 0 {
        score -= 12.0; // residual aligns with decile classes
    } else if class >= 5 {
        score -= 4.0; // half-class still fairly usable
    } else {
        score += (5 - class) as f64 * 1.5; // dead-space penalty for odd residues
    }

    // Fractional capacity coupling: how much of the bin the item consumes.
    let fill_frac = item_size as f64 / cap;
    score -= fill_frac * 25.0;

    // Post-residual as capacity fraction: small slivers are dead space.
    let post_frac = post_residual as f64 / cap;
    if post_frac > 0.0 && post_frac < 0.10 {
        score += 15.0; // sliver penalty
    }

    // Lookahead: if next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = post_residual - next_item_size;
        score -= 20.0 - (slack % 10) as f64;
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 8.0; // this bin can't host the next item
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate: penalize opening fresh bins unless current fit is bad.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 35.0 - 20.0 * progress;
        if fitting_bins_count == 0 {
            score -= 40.0; // no alternative
        }
    }

    // Mean residual coupling: prefer bins below mean residual (tighter packing).
    score -= (mean_residual - post_residual as f64).max(0.0) * 0.3;

    // Integer division threshold on post_residual: large divisible chunks good.
    if pr >= 50 && pr % 25 == 0 {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item (1..=100
    // unknown distribution, so anything < ~10 is near-unusable) are heavily penalized.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 25 {
        // Small-but-possibly-usable gaps: moderate penalty scaling with tightness.
        score += 15.0 * (1.0 - post_residual as f64 / 25.0);
    }

    // Reward near-perfect fits (post_residual very small but nonzero is still dead).
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    if post_residual > 0 {
        score -= 20.0 * fill_ratio;
    }

    // Perfect closure of a bin is ideal.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Pressure from number of open bins: prefer consolidating into existing bins
    // rather than proliferating bins.
    score += 2.0 * open_bins_count as f64;

    // Lookahead coupling: if next item fits into the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // Penalize placements that leave a gap just barely too small for the next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 20 {
        score += 10.0;
    }

    // Last-chance bin (only fitting bin): strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when existing bins are very full/fragmented
    // (high mean residual spread) or late in the stream; otherwise discourage.
    if bin_residual == bin_capacity {
        score += 25.0 + 3.0 * mean_residual.min(50.0);
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress);
    }

    // Slight preference for bins whose residual is close to the item (tight packing).
    let tightness = 1.0 - (bin_residual - item_size) as f64 / bin_capacity as f64;
    score -= 5.0 * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post_residual)
    score -= 3.0 * (bin_capacity as f64 - post_residual as f64).max(0.0) / bin_capacity as f64;

    // Aggressive 2-step lookahead: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            score -= 12.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize large dead space if next item is big
            score += 0.15 * next_item_size as f64;
        }
    }

    // Relative to mean residual: prefer bins with residual below mean (consolidate fuller bins)
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize mildly so we prefer reusing open bins unless fit is poor
    if bin_residual == bin_capacity {
        score += 10.0;
        // But if lookahead item is large and current item leaves bad space, opening new bin is fine
        if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
            score -= 15.0;
        }
    }

    // Penalize leaving tiny unusable fragments
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize large dead space with non-linear growth.
    if post_residual > 0 {
        score += (post_residual as f64 / bin_capacity as f64).powf(2.0) * 40.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Small post-residual that still can't fit typical items is dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 35.0;
    }

    // Lookahead coupling: reward bins whose post-residual fits the next item exactly-ish.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Post-residual too small for next item: dead space risk.
            score += 15.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 45.0;
    }

    // Crowding: many open bins -> prefer consolidating into existing ones.
    score += open_bins_count as f64 * 1.5;

    // Global residual pressure: if mean residual is high, prefer tight fits less aggressively.
    score -= mean_residual * 0.05;

    // Time horizon: later in stream, discourage opening new bins (harder to fill them).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses.
        score += 30.0 + 70.0 * progress;
        if next_item_size > 0 && next_item_size >= bin_residual {
            score -= 10.0;
        }
    } else {
        score -= 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let prog = step_index as f64 / total_items.max(1) as f64;

    // Normalize post-residual and item size
    let prn = pr / cap;
    let isn = item_size as f64 / cap;
    let nsn = next_item_size as f64 / cap;

    // Smooth polynomial coupling: quadratic post-residual penalty scaled by progress
    let quad = prn * prn * (0.5 + 1.5 * prog);
    score += 20.0 * quad;

    // Reward tight fits (low post_residual) with cubic term
    let tight = (1.0 - prn).powi(3);
    score -= 15.0 * tight;

    // Lookahead coupling: penalize if next item cannot use the leftover space smoothly
    let gap = (prn - nsn).abs();
    score += 8.0 * gap * gap * (1.0 - prog);

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 10.0 + 5.0 * prog;
    }

    // Slight penalty for many open bins relative to progress (encourage consolidation)
    let obn = open_bins_count as f64;
    score += 0.05 * obn * (0.5 + prog);

    // Mean residual divergence penalty
    score += 0.3 * (mean_residual - pr).abs();

    // New-bin candidate: only attractive when fit is hopeless
    if (bin_residual as f64 - cap).abs() < 1e-9 {
        score += 6.0 - 4.0 * (1.0 - prn) * isn;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fill: strongly reward
    if post_residual == 0 {
        score -= 30.0;
    }

    // Dead-space penalty: post_residual too small for the lookahead item
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let waste = (next_item_size as f64 - post_residual as f64) / next_item_size as f64;
        score += 10.0 + 15.0 * waste;
    }
    // Reward residuals that can still host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 4.0;
    }

    // Harmonic classes on post_residual (base-10 residue):
    // residuals that are multiples of 10 are "usable" slots; odd/prime-ish residues are dead-ish
    if post_residual > 0 {
        let m = post_residual % 10;
        match m {
            0 => score -= 8.0,
            1 | 3 | 7 | 9 => score += 3.0,
            5 => score += 1.5,
            _ => {}
        }
        // Integer-division threshold: quarter-capacity granularity
        let q = post_residual / 25; // 0..4
        score -= q as f64 * 2.0;
    }

    // Modulo coupling between item_size and capacity fraction classes
    let cap_frac = (bin_capacity / 4) as f64; // 25
    let item_class = (item_size as f64 % cap_frac) / cap_frac;
    score += 2.0 * item_class;

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate: make it unattractive unless the item is huge
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 - item_size as f64 + 8.0;
        // allow new bin when item is very large relative to typical residual
        if item_size as f64 > mean_residual + 20.0 {
            score -= 12.0;
        }
    }

    // Progress coupling: later in the stream, prefer consolidating (low residual spread)
    let t = step_index as f64 / (total_items.max(1) as f64);
    score += t * 2.0 * ((mean_residual - post_residual as f64).abs() / 10.0);

    // Prefer bins tighter than the mean (best-fit flavor)
    if (post_residual as f64) < mean_residual {
        score -= 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=9) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Medium awkward gaps (10..=19) get a moderate penalty scaled by gap size.
    else if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }

    // Reward near-perfect fits (post_residual <= 5) strongly.
    if post_residual <= 5 {
        score -= 30.0;
    }

    // Perfect fill is ideal.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Open-bin pressure: penalize spreading across many bins.
    score += open_bins_count as f64 * 2.0;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin should only win when fits are poor.
    if bin_residual == bin_capacity {
        // Penalize opening a new bin, more so when many bins are open.
        score += 55.0 + open_bins_count as f64 * 3.0;
        // Early in the stream, opening bins is cheaper.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= progress * 20.0;
    }

    // Lookahead coupling: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // If next item is large and post_residual would be a tiny dead gap, penalize.
    if next_item_size > post_residual && post_residual > 0 && post_residual < 15 {
        score += 10.0;
    }

    // Relative fit quality: reward using a large fraction of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 20.0;

    // Deviation from mean residual: prefer bins whose residual is close to item need.
    let dev = (bin_residual as f64 - item_size as f64 - mean_residual).abs();
    score += dev * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize dead space: residual too small for any plausible future item (1..=100 range).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // 2-step lookahead: strongly reward exact match between post_residual and next item size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual as i64 >= next_item_size as i64 {
            // Next item fits: reward tightness of the match.
            score -= 30.0 - diff.min(30.0);
        } else {
            // Next item won't fit: mild penalty, worse if gap is small (wasted potential).
            score += diff.min(20.0) * 0.5;
        }
    }

    // Compare post_residual to mean residual: keep bins balanced, prefer bins whose
    // post residual is close to the mean (avoid fragmenting one bin while others stay full).
    let pr = post_residual as f64;
    score += (pr - mean_residual).abs() * 0.15;

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the current
    // item is large relative to capacity or open bins are all quite full.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fullness = 1.0 - mean_residual / bin_capacity as f64;
        // Prefer new bin when item is big and existing bins are crowded.
        let openness = (item_size as f64 / bin_capacity as f64) * 60.0
            + fullness * 40.0
            + progress * 10.0;
        score = 100.0 - openness; // low score = open new bin when justified
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tight fit reward: strongly prefer small post-residual, non-linearly.
    let tightness = 1.0 - (post_residual as f64 / cap);
    score -= 60.0 * tightness * tightness;

    // Penalize residual that is too small to ever be useful (dead space),
    // assuming typical item sizes in [10, 80]: residual < 10 is waste.
    let dead = if post_residual < 10 {
        (10 - post_residual) as f64
    } else {
        0.0
    };
    score += 8.0 * dead;

    // Lookahead: bonus if next item fits into post-residual (chain packing).
    if next_item_size > 0 {
        if (next_item_size as u32) <= post_residual {
            score -= 15.0;
            // Extra reward if next item fits almost exactly.
            let gap = post_residual - next_item_size;
            if gap <= 10 {
                score -= 10.0;
            }
        } else {
            // Next item won't chain here; slight penalty for large leftover.
            score += 3.0;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Prefer fuller bins relative to the average residual state.
    score += (mean_residual - bin_residual as f64) * 0.5;

    // Time horizon: early in the stream, be more willing to open new bins
    // (keep residuals flexible); late in the stream, consolidate tightly.
    let progress = if total_items > 0 {
        step_index as f64 / total_items as f64
    } else {
        0.0
    };
    score -= 20.0 * progress * tightness;
    score += 10.0 * (1.0 - progress) * (post_residual as f64 / cap);

    // New-bin candidate handling: an empty bin is attractive early or when
    // the fit elsewhere is poor; make the empty-bin score mildly high so it
    // is only chosen when its (perfect) tightness terms dominate.
    if bin_residual == bin_capacity {
        score += 12.0 - 20.0 * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    }

    // Mild penalty for spreading across too many open bins.
    score += (open_bins_count as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let item = item_size as f64;

    // Base: prefer tight fits (low post_residual), with non-linear shaping.
    let mut score = pr * (1.0 + 0.6 * progress);

    // Quadratic penalty on large post_residual scaled by capacity: dead space hurts more later.
    let prn = pr / cap;
    score += 25.0 * prn * prn * (0.3 + 0.7 * progress);

    // Smooth interaction: reward placements that leave room for the lookahead item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = pr - nxt;
        let s = 1.0 / (1.0 + (-gap / 20.0).exp()); // smooth sigmoid of gap fit
        score -= 12.0 * s * (1.0 - progress * 0.5);
    }

    // Cubic coupling of item size with progress: large items early are fine,
    // but late large-item placements in already-open bins are favored.
    score -= 0.15 * item * progress * progress * progress;

    // Last-chance bonus: only one fitting bin => strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 - prn);
    }

    // Mild penalty when bin residual deviates from mean residual (balance open bins),
    // smoothly scaled by number of open bins.
    let dev = (bin_residual as f64 - mean_residual).abs() / cap;
    score += 8.0 * dev * dev * (open_bins_count as f64).ln().max(1.0);

    // New-bin candidate: penalize slightly so it only wins when fits are truly bad,
    // with the penalty decaying as the stream progresses.
    if bin_residual == bin_capacity {
        score += 18.0 * (1.0 - progress) + 0.3 * pr;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: less wasted space relative to capacity.
    let fill_frac = (bin_residual as f64) / (bin_capacity as f64);
    let item_frac = (item_size as f64) / (bin_capacity as f64);
    score -= 30.0 * item_frac * fill_frac;

    // Penalize unusable dead space: post_residual too small for the smallest plausible item.
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    } else if post_residual == 0 {
        score -= 40.0; // perfect closure
    }

    // Harmonic classes: classify post_residual by modulo classes of common item sizes.
    let pr = post_residual;
    let harmonic_bonus = if pr == 0 { 0.0 }
        else if pr >= 10 && pr <= 80 {
            // post_residual itself is a plausible future item size -> reusable gap
            -12.0
        } else if pr % 10 == 0 {
            -6.0
        } else if pr % 5 == 0 {
            -3.0
        } else {
            4.0
        };
    score += harmonic_bonus;

    // Lookahead coupling: if next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 - slack * 0.3;
        } else {
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin before opening a new one.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate: opening a new bin should only win when current fit is poor.
    if bin_residual == bin_capacity {
        score += 18.0;
        if item_size as f64 >= 0.5 * bin_capacity as f64 {
            score -= 10.0; // big items pair well with a fresh bin
        }
    }

    // Progression: later in stream, prefer consolidating into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 8.0 * progress * (1.0 - fill_frac);

    // Slight preference for bins whose residual is far from the mean (outlier consolidation).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev * (1.0 - fill_frac);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for the smallest item (<= 9) are wasted.
    if post_residual < 10 && post_residual > 0 {
        score += 60.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 120.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Tightness coupling: fraction of bin consumed by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill_ratio;

    // Last chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: only attractive when item is large or open bins are crowded;
    // penalize opening new bins by default to encourage consolidation.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = open_bins_count as f64 / 20.0;
        let big_item_bonus = if item_size > 50 { 25.0 } else { 0.0 };
        score += 55.0 - pressure * 10.0 - big_item_bonus + 10.0 * progress;
    }

    // Open bins pressure: many open bins -> favor filling existing ones.
    score += open_bins_count as f64 * 1.5;

    // Lookahead: if the next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 50.0;
    }
    // Penalize leaving a residual just below the next item (blocking lookahead).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 25.0;
    }

    // Mean residual alignment: prefer bins whose residual is below average (dying bins first).
    let res = post_residual as f64;
    if res < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = 0.0;
    score
