pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity)
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 30.0 * (1.0 - fit_ratio) * (1.0 - fit_ratio);

    // Penalize dead space that cannot fit a typical next item
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0 + 0.5 * (post_residual as f64);
    }

    // Reward bins that can also accommodate the lookahead item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin is very full
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let openness = open_bins_count as f64 / (total_items.max(1) as f64 * 0.1 + 1.0);
        score += 40.0 + 20.0 * (1.0 - progress) + 10.0 * openness;
        // Allow new bin if item is large and residual space is fragmented
        if item_size > bin_capacity / 2 && mean_residual < item_size as f64 {
            score -= 45.0;
        }
    } else {
        // Prefer filling already-open bins more when many bins are open
        score += 0.3 * (open_bins_count as f64);
    }

    // Prefer bins whose residual is far from the mean (consolidate fragmentation)
    score += 0.2 * (bin_residual as f64 - mean_residual).abs();

    // Slight preference for fuller bins as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 10.0 * (1.0 - bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;
    let item_norm = item_size as f64 / cap;
    let next_norm = next_item_size as f64 / cap;

    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // residual waste matters more as the stream approaches its end.
    let waste_weight = 1.0 + 2.5 * progress * progress;
    score += waste_weight * 30.0 * pr_norm * pr_norm * cap;

    // Reward tight fits: post_residual near zero gets a smooth quadratic discount.
    let tightness = (1.0 - pr_norm) * (1.0 - pr_norm);
    score -= 45.0 * tightness * (0.4 + 0.6 * progress);

    // Penalize post-residuals that are unusable for typical items (dead space),
    // smooth via a bell-like polynomial in pr_norm around the awkward range.
    let dead = pr_norm * (1.0 - pr_norm);
    let awkward = pr_norm - 0.3;
    score += 25.0 * dead * awkward * awkward * 4.0;

    // Lookahead coupling: bonus if post_residual can host the next item,
    // penalize if it nearly-but-not-quite fits.
    if next_item_size > 0 {
        let fits_next = if pr >= next_item_size { 1.0 } else { 0.0 };
        let gap = (pr - next_item_size as f64).abs();
        score -= 18.0 * fits_next * (1.0 - gap / cap);
        score += 12.0 * (1.0 - fits_next) * (1.0 - (gap / cap).min(1.0));
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0 * (0.5 + 0.5 * progress);
    }

    // Many open bins: prefer consolidating into bins below mean residual
    // (i.e., filling fuller bins first), smooth polynomial in mean coupling.
    let mean_norm = mean_residual / cap;
    let diff = pr_norm - mean_norm;
    score += 15.0 * diff * diff * (open_bins_count as f64).ln().max(1.0);

    // Mild penalty for opening new bins early in the stream.
    score += 8.0 * (1.0 - progress) * (1.0 - item_norm);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong preference for tight fits (small post_residual).
    score += (post_residual as f64).powi(2) * 0.02;

    // Harmonic class of the leftover: post_residual mod 10 captures
    // "usable slot" structure. Leftovers in {0} are perfect; small
    // leftovers (1..10) are dead space unless they form a class
    // matching typical small items.
    let class = post_residual % 10;
    match class {
        0 => { score -= 8.0; }                    // perfect fill
        1 | 2 | 3 => { score += 6.0; }            // unusable slivers
        4 | 5 | 6 => { score += 2.0; }            // marginal
        _ => { score -= 1.0; }                    // 7..9: often fillable
    }

    // Reward leftovers that exactly accommodate the lookahead item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 12.0;
        } else if post_residual > next_item_size {
            score -= 3.0;
        } else {
            score += 4.0; // lookahead cannot use this bin's leftover
        }
        // Harmonic divisibility: leftover divisible by next item size
        // allows multiple future fills.
        if next_item_size > 0 && post_residual % next_item_size == 0 && post_residual > 0 {
            score -= 5.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is
    // huge relative to residual or open bins are badly fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / bin_capacity as f64;
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0
            - 10.0 * fragmentation
            - 8.0 * progress
            - (item_size as f64 / bin_capacity as f64) * 15.0;
        // Large items deserve fresh bins when few fit anywhere.
        if item_size >= 70 && fitting_bins_count <= 1 {
            score -= 20.0;
        }
    }

    // Mild bonus for bins tighter than the current mean residual
    // (concentrate waste in few bins).
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // Define "dead" as a post_residual too small to hold the smallest plausible item (1..100 stream, min item ~1).
    // Treat gaps below a calibrated threshold as wasted: quadratic penalty scaled by tightness.
    let dead_threshold = 9.0f64;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64).powi(2) * 4.0;
    }

    // Reward near-perfect fits: post_residual close to 0 is excellent.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 3 {
        score -= 25.0;
    }

    // Fit ratio coupling: prefer bins where item occupies a large fraction of residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 20.0;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: only open a new bin when residuals across open bins are large
    // (poor fits everywhere) or the next item would benefit from fresh space.
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
        // Base new-bin cost keeps it from being chosen trivially.
        score = bin_capacity as f64 * 0.9 + pressure * 10.0;
        // Lookahead: if next item is large, a fresh bin is more attractive.
        if next_item_size > 0 && (next_item_size as f64) > mean_residual {
            score -= 25.0;
        }
        // Late in stream, avoid proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 30.0;
    }

    // Open-bin pressure: with many open bins, tighten selection to consolidate.
    score += open_bins_count as f64 * 0.5;

    // Mild lookahead reward: if the post-residual exactly accommodates the next item, reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }
    if next_item_size > 0 && post_residual >= next_item_size && post_residual < next_item_size + 5 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize dead space that is too small for the smallest possible item (size 1..10).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Aggressive 2-step lookahead: reward when the next item exactly or nearly fits the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect 2-chain
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot use the leftover space; penalize proportionally.
            let overshoot = (next_item_size - post_residual) as f64;
            score += 0.15 * overshoot;
        }
    }

    // Tight fit reward: prefer bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fit_ratio;

    // Relative-to-mean residual coupling: prefer filling bins with larger residuals than average.
    if (bin_residual as f64) > mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate handling: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        score = 70.0 - 80.0 * pressure;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0;
        }
    }

    // Slight early-stream preference to open bins (build diversity of residual sizes).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 10.0 * (1.0 - progress);
    }

    // Mild penalty for accumulating many open bins with large residuals.
    score += 0.05 * open_bins_count as f64 * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are strongly favored: reward small post_residual non-linearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that nothing small could use later.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0; // tiny unusable sliver
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // Lookahead coupling: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 7.0;
    }
    // If next item would NOT fit in post-residual but item_size is large, slight penalty
    // (we consumed space the future needs).
    if next_item_size > post_residual && next_item_size > 0 && post_residual < next_item_size / 2 {
        score += 3.0;
    }

    // Prefer fuller bins relative to the mean residual of open bins.
    if (bin_residual as f64) < mean_residual {
        score += 2.5 * (mean_residual - bin_residual as f64) / (bin_capacity as f64);
    } else {
        score -= 1.5 * ((bin_residual as f64) - mean_residual) / (bin_capacity as f64);
    }

    // Time horizon: early in the stream, be more willing to open new bins
    // (discount the new-bin option); late in the stream, pack tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive early, expensive late.
        let new_bin_cost = 30.0 * (1.0 - progress) + 55.0 * progress;
        // Opening a new bin is good if current item is large and would leave
        // awkward residuals elsewhere; bad when many bins are open already.
        let load_penalty = 2.0 * open_bins_count as f64;
        score = new_bin_cost + load_penalty + post_residual as f64;
        // Slightly favor new bins for large items that nearly fill a fresh bin.
        if item_size as f64 / bin_capacity as f64 > 0.8 {
            score -= 8.0;
        }
    } else {
        // Late stream: push harder toward perfect packing.
        score -= 10.0 * progress * tightness;
        // Many open bins: encourage consolidating into emptier ones to close them.
        if open_bins_count > 4 && (bin_residual as f64) <= mean_residual {
            score -= 2.0;
        }
    }

    // Mild bonus for placing large items (they are hardest to place later).
    score -= 0.05 * item_size as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base: prefer bins that leave small post residual (tight packing).
    let mut score = pr;

    // Non-linear dead-space penalty: quadratic coupling of post residual with progress.
    // Dead space hurts more late in the stream when it can never be reused.
    let dead_frac = pr / cap;
    score += 18.0 * dead_frac * dead_frac * (0.4 + 0.6 * progress);

    // Reward very tight fits (smooth bell around zero post residual).
    score -= 12.0 * (-(pr / (0.15 * cap)).powi(2)).exp();

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 25.0 + 20.0 * (1.0 - dead_frac);
    }

    // Penalize new-bin candidate mildly, scaled by how many open bins exist
    // and how well the item would fit elsewhere; opening new bins early is cheap,
    // late it wastes capacity.
    if is_new_bin {
        score += 6.0 + 0.8 * open_bins_count as f64 + 30.0 * progress;
        // If the item is small relative to capacity, opening a new bin wastes space.
        score += 10.0 * (1.0 - item_size as f64 / cap);
    }

    // Lookahead coupling: if next item could exactly use this bin's post residual,
    // reward keeping this residual; otherwise prefer consuming residual now.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (pr - nx).abs();
        // If post residual matches next item well, mild bonus; if post residual is
        // just barely below next item (unusable for it), extra penalty.
        score -= 8.0 * (-(gap / (0.1 * cap)).powi(2)).exp();
        if pr < nx && pr > 0.0 {
            score += 6.0 * (1.0 - pr / nx);
        }
    }

    // Coupling with mean residual: prefer bins below mean residual
    // (fill the emptier bins first to consolidate full ones).
    score -= 3.0 * ((mean_residual - pr) / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual lands in "usable" classes
    // (multiples of common item sizes / capacity fractions) should be favored.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Reward residuals in friendly classes: divisible by 10, 20, 25, 50
    if post_residual > 0 {
        if post_residual % 10 == 0 { score -= 6.0; }
        if post_residual % 20 == 0 { score -= 4.0; }
        if post_residual % 25 == 0 { score -= 4.0; }
        if post_residual % 50 == 0 { score -= 5.0; }
        // Integer-division thresholds: small dead-space bands get penalized
        if post_residual < 10 { score += 12.0; }
        else if post_residual < 20 { score += 5.0; }
    } else {
        // Perfect fill is ideal
        score -= 25.0;
    }

    // Lookahead coupling: if next item fits the post residual, big reward
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0 + 0.1 * (next_item_size as f64);
        // Extra reward when next item exactly fills remaining space
        if next_item_size == post_residual { score -= 8.0; }
    } else if next_item_size > 0 {
        // Next item won't fit: penalize proportional to wasted opportunity
        score += 0.05 * ((next_item_size as f64) - post).max(0.0);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded or fit is poor
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 / (1.0 + mean_residual / cap);
        // Penalize new bins early / when open bins still have room
        score += 18.0 + 2.0 * pressure;
        if post_residual == 0 { score = 1e9; } // never open new bin for nothing
        // If nothing fits well, allow new bin: soften when mean residual is low
        if mean_residual < 15.0 { score -= 25.0; }
        if next_item_size > 0 && post_residual >= next_item_size { score -= 5.0; }
    }

    // Fractional progress coupling: late in the stream, tighten packing
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.15 * progress;

    // Prefer fuller bins (smaller residual before placement)
    score += 0.05 * ((bin_capacity as f64 - bin_residual as f64).max(0.0)).recip().min(1.0) * 0.0;
    score -= 0.02 * (bin_residual as f64).max(0.0).min(100.0) * (1.0 - progress);

    // Spread across bins when many are open with large residuals
    if open_bins_count > 2 && bin_residual as f64 > mean_residual + 20.0 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residual gaps too small to hold the
    // minimum item (1) are pure waste, but gaps below the typical item
    // floor are especially unusable. Penalize tiny gaps super-linearly.
    if post_residual < 10 && post_residual > 0 {
        score += 40.0 + (10 - post_residual) as f64 * 6.0;
    }

    // Reward near-perfect fits strongly (post_residual close to 0).
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    }

    // Coupling with next item lookahead: if the post residual can exactly
    // host the next item, this bin becomes doubly valuable.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 18.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size < 10 {
            // placing next item would leave dead space here; mild penalty
            score += 4.0;
        }
    }

    // Open-bins pressure: when many bins are open, prefer consolidation
    // into existing bins over spreading; when few bins are open, allow
    // slack. Scale penalty with open_bins_count.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    score += pressure * (post_residual as f64 / bin_capacity as f64) * 6.0;

    // Last-chance bonus: if this is the only fitting bin, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Mean-residual anchoring: bins far below the mean residual are
    // already tight; filling them further wastes little. Bins far above
    // the mean should be filled to keep the mean low.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // New-bin candidate handling: an empty bin has maximum flexibility.
    // Only prefer it when no open bin offers a decent fit (post_residual
    // would be small dead space) or when the stream is early and bins
    // are scarce.
    if bin_residual == bin_capacity {
        let dead_space_penalty = if post_residual < 10 { 55.0 } else { 0.0 };
        score += 30.0 - dead_space_penalty - 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: strong bonus for leaving minimal dead space.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // Aggressive 2-step lookahead: if the NEXT item fits exactly into post_residual,
    // this bin is an ideal chain target.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 900.0;
        } else if post_residual > next_item_size {
            // Next item fits, but leaves its own leftover: penalize proportionally.
            let after_next = (post_residual - next_item_size) as f64;
            score += after_next * 0.6;
            // Small chain bonus since it still uses the space productively.
            score -= 80.0;
        } else {
            // Next item does NOT fit into this bin's remainder:
            // penalize dead space that blocks the lookahead chain.
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 1.5;
        }
    }

    // Relative-to-mean residual coupling: prefer bins tighter than average.
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: strongly prefer using the only fitting bin to avoid opening new bins.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: make an empty bin less attractive than good fits,
    // but attractive when no open bin fits well (post_residual large gap penalty already handles it).
    if bin_residual == bin_capacity {
        // Neutral base for empty bin; add slight penalty that shrinks as stream progresses
        // (later in stream, consolidating matters more).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 40.0 + 60.0 * (1.0 - progress);
        // If next item is huge and would need a fresh bin anyway, opening early is fine.
        if next_item_size > 50 {
            score -= 30.0;
        }
    }

    // Penalize leaving very small unusable slivers generally.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.92;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Smooth non-linear coupling of post-residual with stream progress:
    // late in the stream, dead space becomes more costly.
    let progress_weight = 0.5 + 1.5 * progress * progress;
    score += progress_weight * (pr / cap) * pr * 0.05;

    // Reward tight fits: small post_residual relative to item size.
    let item = item_size as f64;
    let tightness = 1.0 - (pr / cap);
    score -= 8.0 * tightness * tightness * tightness;

    // Penalize waste proportional to mean residual deviation (avoid outliers).
    let dev = pr - mean_residual;
    score += 0.02 * dev * dev * (1.0 + progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    }

    // Lookahead: bonus if the leftover space can host the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 5.0 * (1.0 - (pr - nxt) / cap);
        } else {
            // leftover cannot fit next item; penalize proportionally.
            score += 0.1 * (nxt - pr);
        }
    }

    // Penalize opening a brand-new bin when open bins exist and could fit.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        let pressure = (open_bins_count as f64).ln() + 1.0;
        score += 10.0 * pressure * (1.0 + progress);
        // But if this bin would otherwise be a terrible fit (large post-residual
        // elsewhere), the penalty above may still be overcome naturally.
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class: post_residual bucketed by integer division thresholds
    let post = post_residual as f64;
    let class = (post_residual / 10) as f64; // decade class

    // Reward tight fits: small post_residual, especially in low classes
    score -= 45.0 * (-post / 30.0).exp();

    // Penalize "awkward" residuals: 1..=9 dead space is nearly unusable
    if post_residual >= 1 && post_residual < 10 {
        score += 60.0;
    }
    // Modulo harmonic: residuals that divide capacity well are reusable
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 12.0;
    }
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 10.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size < post_residual {
            let nxt = next_item_size as f64;
            score -= 25.0 * (nxt / post) * (1.0 - (post - nxt) / cap);
        } else {
            // next item won't fit here: slight penalty proportional to leftover
            score += 8.0;
        }
    }

    // Last-chance bonus: only fitting bin -> avoid opening new bin unless awful
    if fitting_bins_count == 1 {
        score -= 35.0;
    }
    if fitting_bins_count > 3 {
        score += 5.0 * (fitting_bins_count as f64 - 3.0).min(4.0);
    }

    // New-bin candidate handling: empty bin is a fallback
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // prefer existing bins when mean residual is healthy
        score += 70.0 - 40.0 * (mean_residual / cap);
        // late in stream, less eager to open bins
        score += 20.0 * progress;
        // item larger than half capacity justifies a fresh bin more
        if (item_size as f64) > 0.5 * cap {
            score -= 30.0;
        }
    }

    // Mild preference to fill bins below mean residual (balance avoidance of fragmentation)
    score += 0.15 * (mean_residual - post);

    // Class-based non-linear nudge: quadratic in decade class
    score += 0.6 * class * class * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< 10) are heavily penalized,
    // while exact/near-exact fits are strongly rewarded.
    if post_residual == 0 {
        score -= 200.0; // perfect fit
    } else if post_residual < 10 {
        score += 150.0; // dead space: unusable gap
    } else if post_residual <= 20 {
        score += 20.0; // marginal gap, only tiny items can use it
    }

    // Reward tight fits relative to residual (small waste ratio).
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fill_ratio;

    // Open-bins pressure: discourage spreading across many bins when few fit options exist.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Lookahead: if the next item fits the post residual, reward leaving that space.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0; // leftover space won't help the next item
    }

    // New-bin candidate: only attractive when open bins are tightly packed on average
    // or the item is large; otherwise keep using open bins.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        score += 80.0 - 100.0 * pressure;
        if item_size > 60 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match with next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect two-item packing
        } else if post_residual > next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            // gentle penalty proportional to leftover after next item
            score += gap * 0.5;
            if gap <= 10.0 {
                score -= 15.0; // near-match still good
            }
        } else {
            // next item can't fit here; penalize dead space more strongly
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Relative-to-mean coupling: prefer bins tighter than average.
    score += (mean_residual - bin_residual as f64) * 0.4;

    // Last-chance bonus: avoid wasting the only fitting bin's capacity badly,
    // but strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Penalize opening a new bin unless current residuals are all tight.
    if bin_residual == bin_capacity {
        let tight = mean_residual < 25.0;
        score += if tight { 40.0 } else { 10.0 };
        // early stream: be more willing to open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 15.0;
    }

    // Discard creating tiny unusable slivers
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: smaller post_residual relative to capacity is better.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 6.0 * tightness * tightness;

    // Penalize dead space: post_residual too small to be useful for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    } else if post_residual >= 10 && post_residual < 25 {
        score += 4.0; // hard to fill zone
    }

    // Lookahead: bonus if next item fits into the post_residual exactly or well.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            if slack == 0 {
                score -= 20.0; // perfect chain
            } else {
                score -= 8.0 * (1.0 - slack as f64 / post_residual as f64);
            }
        } else {
            score += 3.0; // next item won't fit here
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    } else {
        // Many fitting bins: prefer the fullest (smallest residual) via tightness term.
        score += 0.5 * fitting_bins_count as f64;
    }

    // Global state coupling: penalize creating fragmented residual far above mean.
    let diff = post_residual as f64 - mean_residual;
    score += 0.15 * diff.abs();

    // Many open bins: encourage closing bins (filling them) over spreading.
    score += 0.05 * open_bins_count as f64 * (1.0 - tightness);

    // Time horizon: early in stream, opening new bins is cheap; late, conserve bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize moderately, more so late in the stream.
        score += 10.0 + 20.0 * progress;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score += 2.0;
        }
    } else {
        score -= 5.0 * progress; // late stream: reuse open bins harder
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer low post_residual (tight fit), with stream-progress-dependent weight
    let mut score = pr * (1.0 + 0.8 * progress);

    // Non-linear coupling: squared post-residual term scaled by progress
    score += 12.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits more as stream advances (cubic interaction)
    let tightness = 1.0 - norm_pr;
    score -= 8.0 * tightness * tightness * tightness * (0.5 + progress);

    // Penalize bins whose residual deviates from mean residual (spread control)
    let dev = (pr - mean_residual) / cap;
    score += 6.0 * dev * dev;

    // Lookahead: if next item fits in post_residual, reward this bin
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 5.0 + 4.0 * progress;
    } else if next_item_size > 0 {
        // dead space unusable by next item: penalize proportionally
        score += 3.0 * norm_pr;
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // Mild penalty for many open bins to discourage fragmentation
    score += 0.15 * open_bins_count as f64;

    // New-bin candidate: neutral-ish baseline, slightly favored early, penalized late
    if bin_residual == bin_capacity {
        score = cap * (0.9 - 0.25 * progress) + 0.15 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: classify post_residual by
    // integer-division thresholds into "dead space" buckets.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Class 0: perfect fit -> huge reward
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Dead-space classes: leftover below the smallest item (<=10) is pure waste.
        if post_residual < 10 {
            score += 250.0; // unusable sliver
        } else if post_residual <= 20 {
            score += 60.0;  // nearly dead: only tiny items fit
        } else if post_residual <= 35 {
            score += 15.0;  // awkward mid class
        } else if post_residual <= 50 {
            score -= 5.0;   // half-bin class: still reusable
        } else {
            score -= 10.0;  // large residual, very reusable
        }

        // Harmonic coupling: does the NEXT item (lookahead) fit in the post-residual?
        if next_item_size > 0 {
            if next_item_size <= post_residual {
                // Next item fits here: reward proportional to how snugly it nests.
                let snug = (post_residual - next_item_size) as f64;
                score -= 40.0 - snug.min(40.0) * 0.5;
                // Extra reward if the pair fills the bin almost exactly.
                if post_residual - next_item_size <= 5 {
                    score -= 30.0;
                }
            } else {
                // Next item won't fit here: mild penalty scaled by the gap.
                let gap = (next_item_size - post_residual) as f64;
                score += gap.min(90.0) * 0.4;
            }
        } else {
            // Last item in stream: only perfect fills matter.
            score += post * 0.1;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
        if post_residual >= 10 {
            score -= 15.0;
        }
    }

    // New-bin candidate handling: an empty bin has large residual; make it
    // attractive only when current fits are poor (high post_residual elsewhere).
    if bin_residual == bin_capacity {
        // Baseline cost of opening a new bin, modulated by stream progress
        // and how many bins are already open.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 0.5 * cap + 25.0 * open_bins_count as f64 * (1.0 - progress) - 10.0 * progress;
        // If next item is huge, an empty bin gives flexibility.
        if next_item_size >= 60 {
            score -= 20.0;
        }
        // Don't open new bins when mean residual across open bins is healthy.
        score += (mean_residual - 40.0).max(0.0) * 0.8;
    }

    // Mean-residual coupling: prefer bins whose residual is below average
    // (tighten full-ish bins, keep loose bins free).
    if bin_residual != bin_capacity {
        score += (bin_residual as f64 - mean_residual) * 0.15;
    }

    // Small penalty for very tight fits that leave slivers, except when
    // it was the last fitting bin (already rewarded).
    if post_residual > 0 && post_residual < 5 && fitting_bins_count > 1 {
        score += 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual as i32) as f64 * 8.0;
    }

    // Perfect fit is highly rewarded.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Reward tight fits (small waste relative to capacity).
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    score += waste_ratio * 20.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Open bins pressure: with many open bins, discourage opening new ones
    // (the new-bin candidate has bin_residual == bin_capacity).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 10.0 + open_bins_count as f64 * 3.0 + progress * 10.0;
    }

    // Prefer bins whose residual is close to the mean (balanced packing),
    // penalize extreme outliers.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Lookahead: if the next item can exactly fill this bin's post_residual,
    // strongly favor this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    }
    // Penalize if next item cannot use the remaining space well.
    if next_item_size > post_residual && post_residual > 0 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Reward tight fits: smaller post_residual relative to capacity is better.
    score -= 0.5 * (1.0 - post / cap) * item_size as f64;

    // 2-step lookahead: if the next item fits exactly into the post residual,
    // strongly favor this bin (perfect chaining).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - slack / cap);
        if slack == 0.0 {
            score -= 20.0; // exact chain: post_residual == next_item_size
        }
    }
    // If next item cannot fit here, penalize creating a small dead zone.
    if next_item_size > 0 && post_residual < next_item_size {
        if post_residual > 0 && post_residual < 10 {
            score += 15.0; // tiny unusable dead space
        }
    }

    // Relative-to-mean coupling: bins with residual below mean are scarcer;
    // prefer filling below-mean bins (keeps large-residual bins flexible).
    score -= 0.3 * (mean_residual - post);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Early in the stream, be more willing to spread items (favor tight fits less,
    // keep bins balanced); late in the stream, consolidate aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 0.2 * post;
    score -= progress * 0.4 * post;

    // Penalize the brand-new-bin candidate slightly so it's chosen only when
    // no open bin gives a good fit.
    if bin_residual == bin_capacity {
        score += 18.0;
        // But if lookahead chain works perfectly in a fresh bin, ease the penalty.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Prefer tight fits: strongly reward small post-residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 30.0;

    // Penalize dead space that can't fit the next item (lookahead coupling).
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.8;
        }
        // Reward if next item fits perfectly in the post residual.
        if post_residual == next_item_size {
            score -= 15.0;
        }
    }

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize leaving residual far from common item sizes (dead space shaping).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0; // tiny unusable slivers
    }

    // Global state: when many bins are open, prefer consolidating into fuller bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if open_bins_count > 4 {
        score += (mean_residual - post_residual as f64).abs() * 0.15;
    }

    // Time horizon: early on, be pickier (explore); later, pack greedily.
    score *= 1.0 - 0.2 * progress;
    if post_residual == 0 {
        score -= 40.0; // perfect fill always wins
    }

    // New-bin candidate: only attractive when current bin fit is bad.
    if bin_residual == bin_capacity {
        // Opening a new bin costs roughly one bin; make it beat only poor fits.
        score = 45.0 + (bin_capacity - item_size) as f64 * 0.3;
        if next_item_size > 0 && bin_capacity - item_size >= next_item_size {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post;

    // Non-linear dead-space penalty: quadratic in normalized post_residual,
    // amplified as the stream progresses (later waste hurts more).
    let post_norm = post / cap;
    score += 40.0 * post_norm * post_norm * (0.5 + progress);

    // Tight-fit reward: strongly favor small post_residual, smoothly.
    score -= 15.0 * (1.0 - post_norm) * (1.0 - post_norm) * (1.0 - post_norm);

    // Lookahead coupling: if the next item fits into the post residual, reward;
    // smooth interaction between post_residual and next item size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let slack = (post - nxt) / cap;
            score -= 20.0 * (1.0 - slack * slack);
        } else {
            // Next item won't fit here: penalize proportional to overflow fraction.
            let over = (nxt - post) / cap;
            score += 10.0 * over * over;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (smoothly scaled by how well it fits).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 - post_norm);
    }

    // New-bin candidate (empty bin): post_residual == cap, large base score;
    // discourage opening new bins unless open bins are nearly saturated.
    if bin_residual == bin_capacity {
        score += 12.0 * (1.0 - (open_bins_count as f64) / (open_bins_count as f64 + mean_residual / cap + 1.0));
    } else {
        // Slight preference for bins with residuals close to the item (best-fit flavor).
        let diff = (bin_residual as f64 - item_size as f64) / cap;
        score += 5.0 * diff * diff;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit harmonic bonus: post_residual in {0, 25, 50, 75} classes
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0;
    } else if pr % 25 == 0 {
        score -= 20.0;
    }

    // Lookahead: does next item fit into post_residual? Reward compatibility.
    if next_item_size > 0 && next_item_size <= pr {
        score -= 15.0 + 0.25 * (pr - next_item_size) as f64;
    } else if next_item_size > 0 && next_item_size > pr {
        // dead space relative to lookahead
        score += 0.3 * (next_item_size - pr) as f64;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening new bins early, allow it late
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 30.0 - 20.0 * progress;
    }

    // Prefer bins below mean residual (tighter bins absorb waste better)
    score += 0.2 * (mean_residual - bin_residual as f64);

    // Harmonic class of item_size mod 10: reward aligning item to residual classes
    let cls = item_size % 10;
    if cls == 0 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual > 0 && post_residual < 20 {
        score += 25.0;
    } else if post_residual == 0 {
        score -= 40.0; // perfect fit is ideal
    }

    // Reward tight fits relative to capacity.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 20.0;

    // Open-bin pressure: discourage spreading across too many bins.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
    score += pressure * 3.0;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // Slight preference for new bins early in the stream when residuals are large.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score -= 5.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more than linearly.
    if post_residual <= 5 {
        score -= 20.0;
    } else if post_residual <= 15 {
        score -= 10.0;
    }

    // 2-step lookahead: reward if next item exactly fills the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            // next item fits here: the smaller the leftover after it, the better.
            let second_left = post_residual - next_item_size;
            score -= 15.0 - (second_left as f64) * 0.4;
        } else {
            // next item won't fit: penalize dead space that blocks it.
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.5;
        }
    }

    // Relative to mean residual: prefer bins that are already "loaded"
    // (below-mean residual) to consolidate, penalize near-empty bins.
    let res = post_residual as f64;
    if mean_residual > 0.0 {
        score += (res - mean_residual) * 0.3;
    }

    // Last-chance bonus: this is the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Penalize opening a new bin when existing bins fit well.
    if bin_residual == bin_capacity {
        // brand-new bin candidate: base cost of a fresh bin.
        score += 60.0;
        // but if item perfectly fills it or lookahead wants it, reduce cost.
        if post_residual == 0 {
            score -= 70.0;
        } else if next_item_size > 0 && next_item_size == post_residual {
            score -= 40.0;
        }
        // early in stream, opening bins is cheaper (more future items to fill them)
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 10.0;
    }

    // Slight penalty for very large dead space creating unusable slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: smaller post_residual relative to capacity is better.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= 40.0 * (1.0 - tightness).powi(3);

    // Penalize dead space that no plausible future item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    }

    // Lookahead coupling: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size < post_residual {
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            score += 8.0; // next item won't fit here; residual likely wasted
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 2 {
        // Many alternatives: mild penalty to prefer the best-fitting one via post_residual anyway.
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Prefer bins below mean residual when residuals are plentiful (balance load),
    // but prefer above-mean bins when open bins are scarce.
    let diff = bin_residual as f64 - mean_residual;
    if open_bins_count > 4 {
        score -= 0.1 * diff;
    } else {
        score += 0.1 * diff;
    }

    // Time horizon: early on, be conservative (penalize near-full bins slightly to keep
    // flexibility); late in the stream, fill bins aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 15.0 * (1.0 - tightness);
    score += (1.0 - progress) * 5.0 * tightness;

    // New-bin candidate: only attractive when nothing fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty so a new bin is chosen only when open bins leave large waste.
        score += 55.0;
        // But if the item is large and residuals are small, opening fresh is reasonable.
        let avg_open = if open_bins_count > 0 { mean_residual } else { bin_capacity as f64 };
        if item_size as f64 > avg_open * 0.8 {
            score -= 45.0;
        }
        // Late in stream, avoid spawning bins that will barely be used.
        score += 20.0 * progress;
        // If the only fitting option is poor, allow new bin more readily.
        if fitting_bins_count <= 1 {
            score -= 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;
    let next_ratio = next_item_size as f64 / cap;

    // Base: post residual, with non-linear polynomial coupling to stream progress.
    // Early on (progress ~ 0): tolerate residual (future items can fill it).
    // Late (progress ~ 1): residual is dead weight, penalize super-linearly.
    let mut score = pr * (1.0 + 1.5 * progress * progress);

    // Reward tight fits: post_residual near 0 gets a smooth bonus.
    let tightness = 1.0 - pr / cap;
    score -= 6.0 * tightness * tightness * tightness * fit_ratio;

    // Lookahead coupling: if next item fits the post-residual, reward this placement
    // with a smooth interaction term.
    if next_item_size > 0 {
        let next_fits = if (pr - next_item_size as f64) >= 0.0 { 1.0 } else { 0.0 };
        let slack = (pr - next_item_size as f64).abs() / cap;
        score -= 3.0 * next_fits * (1.0 - slack * slack);
        // Penalize if next item barely misses the post-residual (near-miss waste)
        let near_miss = ((pr - next_item_size as f64) / cap).abs();
        score += 2.0 * (1.0 - next_fits) * (-near_miss * 10.0).exp() * fit_ratio;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 8.0 + 4.0 * progress;
    }

    // Slight penalty when many bins are open and this one is far from mean residual
    // (encourages consolidation toward average fill).
    let dev = (pr - mean_residual) / cap;
    score += 1.5 * dev * dev;

    // New-bin candidate (empty bin): make it attractive only when item is large
    // and few bins are open, or late in the stream with poor fits elsewhere.
    if bin_residual == bin_capacity {
        let emptiness_bonus = 2.0 + 3.0 * fit_ratio + 2.0 * progress;
        score -= emptiness_bonus;
        // But discourage opening bins when many already open and item is small.
        score += 0.15 * open_bins_count as f64 * (1.0 - fit_ratio);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how it partitions the capacity
    let post_class = post_residual % 10;
    let post_div = post_residual / 10;

    // Reward tight fits strongly (small post residual)
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 120.0;
    } else if post_residual <= 10 {
        score -= 60.0;
    }

    // Penalize dead space classes: residuals in (10..30] are awkward
    if post_residual > 10 && post_residual < 30 {
        score += (30 - post_residual) as f64 * 1.5;
    }

    // Harmonic coupling: if the next item fits exactly into the post residual,
    // this placement is perfect — reward heavily.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 150.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Next item still fits, but with slack; scale by how well it fits
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 * (1.0 - slack / cap);
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate logic: only attractive when current bin residuals are large
    // (i.e. existing bins are nearly full anyway)
    if bin_residual == bin_capacity {
        let mean_frac = mean_residual / cap;
        // Opening new bin is penalized unless open bins are nearly saturated
        score += 60.0 + 100.0 * (1.0 - mean_frac);
        // Late in the stream, prefer filling existing bins
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 40.0 * progress;
        // Large items start fresh bins more willingly
        if item_size > bin_capacity / 2 {
            score -= 50.0;
        }
    }

    // Modulo threshold on post_residual: multiples of small harmonics are reusable
    if post_residual % 5 == 0 && post_residual > 0 {
        score -= 10.0;
    }
    if post_class == 0 && post_div >= 1 && post_residual < bin_capacity {
        score -= 5.0;
    }

    // Slight preference for bins with above-mean residual when many bins are open
    if open_bins_count > 1 {
        let diff = bin_residual as f64 - mean_residual;
        score += 0.05 * diff;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize dead space: gaps too small for the minimum item size (1) are pure waste,
    // but gaps that can't fit the lookahead item are semi-dead.
    if post_residual > 0 {
        if next_item_size > 0 && post_residual < next_item_size {
            score += 6.0; // can't fit the next item: likely dead space
        }
        if post_residual < 10 {
            score += 10.0; // tiny unusable sliver
        }
    }

    // Reward tight fits (best-fit core): subtract for small post_residual relative to item size.
    let tightness = (item_size as f64) / (bin_residual.max(1) as f64);
    score -= 4.0 * tightness;

    // Last chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Open bins pressure: with many open bins, discourage opening new ones;
    // new-bin candidate (residual == capacity) gets penalized as bins accumulate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 8.0 + 12.0 * (open_bins_count as f64 / 10.0) + 5.0 * progress;
    } else {
        score -= 2.0 * (open_bins_count as f64 / 10.0);
    }

    // Prefer bins with residuals below the mean (consolidate space into fuller bins).
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Exact fill bonus.
    if post_residual == 0 {
        score -= 20.0;
    }

    // If lookahead fits exactly in post_residual, reward heavily.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let diff = (post_residual as f64 - next).abs();
        if post_residual as f64 >= next {
            // next item fits exactly-ish after this placement
            score -= 250.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize small dead space
            score += 120.0 * (1.0 - post_residual as f64 / 100.0);
        }
        // exact match bonus
        if post_residual as u32 == next_item_size {
            score -= 400.0;
        }
    } else {
        // last item: prefer tightest fit
        score += 50.0;
    }

    // Relative to mean residual: prefer bins tighter than average
    score += 1.5 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // Penalize new-bin opening unless current bins are poor fits
    if bin_residual == bin_capacity {
        // new bin candidate: baseline cost plus pressure from open bins
        score += 150.0 + 10.0 * open_bins_count as f64;
        if fitting_bins_count <= 1 && next_item_size > 0 && post_residual as f64 >= next_item_size as f64 {
            score -= 200.0; // fresh bin pairs well with next item
        }
    }

    // Late in stream: consolidate, avoid spreading
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 30.0 * progress * (post_residual as f64 / 100.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post-residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 45.0 * tightness * tightness;

    // Penalize unusable dead space: residual too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Lookahead coupling: if the next item fits the post-residual, strongly reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 35.0;
    } else if next_item_size > 0 {
        // Penalize if next item cannot use the leftover space.
        score += 8.0 * (next_item_size as f64 / 100.0);
    }

    // Last-chance bonus: if this is the only bin that can fit the item, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: discourage opening a new bin unless the item fits poorly everywhere.
    if bin_residual == bin_capacity {
        score += 40.0;
        if fitting_bins_count > 0 {
            // If some open bin has decent tightness, penalize the new bin more.
            score += 30.0 * (1.0 - (post_residual as f64) / (bin_capacity as f64));
        }
        // Early in stream, new bins are cheap-ish; late in stream, prefer consolidation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 * (1.0 - progress);
    }

    // Global state: many open bins with high mean residual -> favor consolidation.
    if open_bins_count > 1 {
        let spread = (bin_residual as f64 - mean_residual).abs();
        // Prefer bins close to the mean residual (balanced packing).
        score += 0.15 * spread;
        if mean_residual > 50.0 {
            score -= 6.0;
        }
    }

    // Mild time-horizon modulation: later items prefer tighter bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 12.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: penalize post-residual, with a smooth non-linear (quadratic) shaping
    // that increasingly punishes large dead space as the stream progresses.
    let mut score = pr * (1.0 + 0.8 * progress * norm_pr);

    // Smooth coupling: post-residual vs next item size compatibility.
    // If next item fits exactly into post_residual, reward strongly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fit_gap = (pr - nxt).abs() / cap;
        score -= 6.0 * (-8.0 * fit_gap).exp();
        // Penalize post-residuals that are slightly too small for the next item
        // (dead space that cannot host the lookahead).
        let unusable = (nxt - pr).max(0.0) / cap;
        score += 5.0 * (1.0 - (-6.0 * unusable).exp());
    } else {
        // Last item: strongly prefer minimal leftover.
        score += 0.5 * pr * pr / cap;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 3.0 + 4.0 * progress;
    }

    // Smooth pressure from mean residual: when open bins are already loose,
    // prefer filling them rather than fragmenting space.
    let mean_norm = mean_residual / cap;
    score -= 2.0 * mean_norm * norm_pr;

    // Mild penalty for opening a brand-new bin when many bins are open and tight.
    if bin_residual == bin_capacity {
        score += 4.0 * (open_bins_count as f64).ln().max(0.0) * (0.5 + 0.5 * progress);
    }

    // Small smooth reward for tight fits (low post_residual relative to item size).
    let tightness = 1.0 - (pr / (item_size as f64 + pr));
    score -= 2.0 * tightness * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: items 1..100, capacity 100.
    // Residuals that are "harmonic" (divisible by 10, 20, 25, 50) are more reusable.
    let harmonic_bonus = |r: u32| -> f64 {
        if r == 0 { return 0.0; } // perfect fit, ideal
        let mut h = 0.0;
        if r % 50 == 0 { h += 18.0; }
        else if r % 25 == 0 { h += 12.0; }
        if r % 20 == 0 { h += 10.0; }
        if r % 10 == 0 { h += 6.0; }
        if r % 5 == 0 { h += 2.0; }
        h
    };
    score -= harmonic_bonus(post_residual);

    // Penalize awkward dead space: small non-harmonic leftovers are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 14.0 - post_residual as f64; // very small scraps are near-useless
    }

    // Lookahead: reward leaving exactly enough room for the next item (harmonic pairing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0; // perfect two-item chain
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // tighter future fit is better
            score -= 8.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here: leftover becomes dead space for lookahead
            score += 6.0;
        }
    }

    // Last-chance bin: strongly prefer filling the only bin that fits,
    // avoiding opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when no
    // open bin offers a decent fit (high mean residual fragmentation, many bins).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // base cost of opening a new bin
        score += 30.0;
        // cheaper to open a bin early in the stream / when few bins exist
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * (1.0 - progress);
        // if existing bins are fragmented (mean residual low relative to item), new bin is fine
        if (mean_residual < item_size as f64) {
            score -= 20.0;
        }
        // perfect-fit potential: an empty bin always fits the next item too
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0;
        }
    } else {
        // Tighter fits in existing bins: reward small post_residual generally.
        score += 4.0 * (post_residual as f64 / bin_capacity as f64);
        // Prefer bins whose residual is close to the item (waste-minimizing).
        let waste = (bin_residual - item_size) as f64;
        score += waste * 0.15;
    }

    // Mild preference for consolidating into fewer bins when many are open.
    if open_bins_count > 4 {
        score += 0.5 * open_bins_count as f64 * 0.01;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small to hold even the
    // smallest plausible item (<= 10) are pure waste; penalize them heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Gaps too small for the lookahead item are also likely dead space.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0;
    }

    // Reward near-perfect fits (post_residual close to 0 but still usable).
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Reward bins whose residual is consumed by a large fraction.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fill_ratio;

    // Last-chance pressure: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when open bins are crowded or the fit
    // would create dead space. Penalize opening new bins under low pressure.
    let is_new_bin = bin_residual == bin_capacity && bin_capacity > 0;
    if is_new_bin {
        let pressure = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
        score += 45.0 - 10.0 * pressure.min(4.0);
        // If the item fits poorly anywhere, opening fresh is more acceptable.
        if post_residual < 10 {
            score -= 20.0;
        }
    }

    // Mild open-bin pressure: consolidate into fewer bins when many are open.
    if !is_new_bin {
        score += 0.05 * open_bins_count as f64;
    }

    // Late-stream tightening: as the stream progresses, avoid creating gaps.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.87;
