pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fills
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 60.0 * (1.0 - post_residual as f64 / 5.0);
    }

    // Penalize dead space relative to smallest plausible future item
    let dead_threshold = 10.0;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 8.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 250.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 * (1.0 - slack / 80.0);
        } else {
            // next item cannot follow here; mild penalty proportional to gap
            let gap = (next_item_size - post_residual) as f64;
            score += 0.3 * gap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 45.0;
    } else if fitting_bins_count > 1 {
        // prefer tighter bins among many candidates: scale by relative tightness
        let tightness = item_size as f64 / bin_residual as f64;
        score -= 20.0 * tightness;
    }

    // Prefer fuller bins (small residual before placement) slightly
    score += 0.25 * (bin_residual as f64 - item_size as f64).max(0.0);

    // Time horizon: early in stream, allow looser packing; later, be greedy
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 15.0 * (1.0 - progress) * (mean_residual / bin_capacity as f64);

    // When many bins are open with high mean residual, discourage spreading
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate adjustment: only attractive if current bin fit is terrible
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 > 40.0 && next_item_size > 0 && next_item_size > post_residual;
        if poor_fit {
            score -= 30.0;
        } else {
            score += 50.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let item = item_size as f64;
    let norm_item = item / cap;
    let norm_next = next_item_size as f64 / cap;

    let mut score = pr;

    // Smooth non-linear coupling of post-residual with stream progress:
    // later in the stream, compact placements matter more.
    let progress_coupling = norm_pr * norm_pr * (0.5 + 2.0 * progress * (1.0 - progress) * 2.0);
    score += 8.0 * progress_coupling;

    // Reward tight fits with a smooth cubic term (subtract for small post_residual).
    score -= 12.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 - norm_pr) * (0.5 + progress);

    // Penalize dead space that no future item (10..80 range scaled) can use.
    let dead = (norm_pr * (1.0 - norm_pr)).sqrt();
    score += 6.0 * dead * (1.0 - progress);

    // Lookahead: reward if next item fits into post-residual (smooth sigmoid-like).
    if next_item_size > 0 {
        let fits = (norm_pr - norm_next) / (0.05 + norm_next);
        let bonus = 1.0 / (1.0 + (-fits * 3.0).exp());
        score -= 10.0 * bonus * norm_next;
    }

    // Last-chance bin: strongly favor using it rather than opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 * (1.0 + progress);
    }

    // Mean-residual dispersion: prefer bins far from mean (extreme residuals)
    // to consolidate near-full bins and keep empty-ish bins flexible.
    let dev = (mean_residual - pr) / cap;
    score -= 2.0 * dev.abs() * (1.0 - norm_pr);

    // Mild penalty for many open bins to encourage consolidation.
    score += 0.5 * (open_bins_count as f64).ln().max(0.0) * norm_pr;

    // New-bin candidate: keep it expensive unless nothing else fits well.
    if bin_residual == bin_capacity {
        score += 20.0 + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues mod small divisors
    let r = post_residual;
    let mod3 = (r % 3) as f64;
    let mod5 = (r % 5) as f64;
    let mod7 = (r % 7) as f64;

    // Penalize residuals that fall in "dead" harmonic classes (hard to fill later)
    if r > 0 && r < 10 {
        score += 40.0; // tiny unusable slivers
    } else if r <= 20 {
        score += 8.0 + mod5;
    } else {
        score -= (r as f64) * 0.15; // reward leaving useful space
        // harmonic bonuses: residuals divisible by common item sizes
        if r % 10 == 0 { score -= 4.0; }
        if r % 20 == 0 { score -= 3.0; }
        if r % 25 == 0 { score -= 2.0; }
    }

    // Lookahead coupling: does next item fit in post_residual?
    if next_item_size > 0 {
        if next_item_size <= r {
            score -= 12.0 - (r - next_item_size) as f64 * 0.1;
        } else {
            score += 6.0 + mod7 * 0.5; // next item won't fit here
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Many open bins: discourage fragmentation, prefer tight fits
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (open_bins_count as f64) * 0.3 * (1.0 - progress);

    // Pull toward mean residual: avoid outlier bins
    score += (post_residual as f64 - mean_residual).abs() * 0.05;

    // New-bin candidate: neutral baseline with mild penalty so it only wins when fits are bad
    if bin_residual == bin_capacity {
        score = cap * 0.6 + (open_bins_count as f64) * 0.5;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 2.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any
    // plausible future item (1..=100) are pure waste; penalize hard.
    if post_residual > 0 {
        // unusable gap: nothing can ever fit exactly well in tiny gaps
        if post_residual < 10 {
            score += 60.0 * (1.0 - post_residual as f64 / 10.0);
        }
        // gap too small for the lookahead item but nonzero: risk of stranding
        if next_item_size > 0 && post_residual < next_item_size {
            score += 25.0;
        }
        // gap that fits the next item exactly is excellent
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 20.0;
        }
    } else {
        // perfect closure: no dead space at all
        score -= 40.0;
    }

    // Reward tight fits (high fill ratio of the residual before placement).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // Last chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, encourage
    // consolidating into existing bins; few bins -> mild new-bin tolerance.
    score += (open_bins_count as f64) * 0.8;

    // Mean residual coupling: if the fleet average residual is small, this
    // bin's post_residual matters more (protect remaining usable space).
    score += 0.5 * (mean_residual - post_residual as f64).max(0.0);

    // New-bin candidate: empty bin. Prefer it only when no open bin offers a
    // decent fit (i.e., when post_residual here is large = fresh space).
    if bin_residual == bin_capacity {
        // base cost of opening a bin, offset by its full flexibility
        score += 55.0 - 0.3 * (open_bins_count as f64);
        // late in the stream, opening bins is safer than stranding items
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are great: strongly reward small post_residual
    score -= 8.0 * (1.0 - (post_residual as f64 / bin_capacity as f64)).powi(6);

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 30.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host next item exactly
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // dead space relative to next item
            let waste = (next_item_size - post_residual) as f64;
            score += 0.3 * waste;
        }
    }

    // Compare against mean residual: prefer bins tighter than average
    score += 0.4 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: avoid opening a new bin when this is the only fitting one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 6.0;
    }

    // Penalize opening new bins when a reasonable fit exists
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 5.0 + 0.5 * (open_bins_count as f64);
        // but allow new bin if item is large and would leave big dead space elsewhere
        if item_size > bin_capacity / 2 && post_residual < 20 {
            score -= 10.0;
        }
    }

    // Late in stream: be more conservative, prefer filling existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 3.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize small dead space that likely becomes unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: bonus if next item fits the post-residual exactly or well.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack_after_next = post_residual - next_item_size;
            score -= 12.0 * (1.0 - slack_after_next as f64 / bin_capacity as f64);
        } else {
            score += 6.0; // next item won't fit here
        }
    }

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when open bins fit poorly.
    if bin_residual == bin_capacity {
        let avg_waste = mean_residual.max(0.0);
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Penalize new bins generally, less so when existing residuals are large.
        score += 55.0 - 0.4 * avg_waste + 10.0 * progress;
        if item_size > bin_capacity / 2 {
            score -= 10.0; // big items do fine in fresh bins
        }
    }

    // Mild preference to fill bins with larger residuals when many bins open.
    score += 0.05 * (open_bins_count as f64) * (bin_residual as f64 / bin_capacity as f64);

    // Time horizon: early on, be conservative with tight fits (keep flexibility).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_post = post / cap;

    // Base: prefer minimal post-residual, with a smooth non-linear penalty
    // that grows super-linearly for large leftover space (wasted potential).
    let mut score = post + 40.0 * norm_post * norm_post;

    // Progress coupling: early in the stream, keep bins flexible (favor
    // balanced residuals); later, aggressively fill bins tight.
    let flexibility = (1.0 - progress) * (1.0 - progress);
    score += 60.0 * flexibility * (norm_post - mean_residual / cap).abs();

    // Smooth polynomial coupling of post_residual with stream progress:
    // late in the stream, small residuals are rewarded more strongly.
    score -= 25.0 * (1.0 - norm_post) * (1.0 - norm_post) * progress * progress;

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 30.0 + 20.0 * progress;
    }

    // Lookahead: if the next item fits exactly into the post-residual,
    // reward this placement smoothly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let fit_quality = 1.0 - (post - nxt) / cap;
            score -= 15.0 * fit_quality * fit_quality;
        } else {
            // penalize placements that leave no room for the lookahead item
            score += 10.0 * (nxt - post) / cap;
        }
    }

    // Mild penalty for spreading across many open bins with large mean residual.
    score += 0.5 * open_bins_count as f64 * norm_post;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.98;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 12.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Reward tight packing relative to capacity (fractional fill).
    score -= (item_size as f64 / bin_capacity as f64) * 8.0;

    // Lookahead: if the next item fits exactly in the post residual, reward;
    // if it cannot fit, penalize creating a gap that strands the next item.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 6.0;
        } else if post_residual > 0 {
            score += (post_residual as f64) * 0.5;
        }
    }

    // Open-bin pressure: discourage spreading across many bins when
    // a decent fit exists; encourage using existing bins.
    score += open_bins_count as f64 * 0.35;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Mean-residual coupling: prefer bins below the mean residual
    // (i.e., fuller bins) to consolidate packing.
    score += (mean_residual - bin_residual as f64) * 0.4;

    // New-bin candidate: only attractive when no open bin fits well,
    // i.e., make the empty bin slightly worse than a good existing fit
    // but better than a terrible fit (large dead space).
    if bin_residual == bin_capacity {
        score += 15.0 + open_bins_count as f64 * -0.2;
        if next_item_size > 0 && next_item_size >= bin_capacity - 10 {
            score -= 10.0; // reserve space for big upcoming item
        }
    }

    // Mild stream-progression damping: early on, be more open to new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 - 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 200.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // dead space relative to next item
        score += 50.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
    }

    // Penalize post_residual far below mean residual (fragmented bin)
    score += 0.5 * (mean_residual - post_residual as f64).abs();

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: make it attractive only when no good fit exists
    if bin_residual == bin_capacity {
        score += 150.0 + 0.3 * mean_residual;
    }

    // Late-stream tightening: waste hurts more as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.5 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core tightness: strongly reward near-perfect fits.
    let frac_used = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * frac_used * frac_used;

    // Dead-space penalty: residual fragments below the minimum item size are wasted.
    let min_item = 1u32;
    if post_residual < min_item {
        score -= 100.0; // perfect fill
    } else {
        // Penalize leaving small unusable gaps relative to capacity.
        let gap = post_residual as f64 / bin_capacity as f64;
        score += 10.0 * gap * gap;
    }

    // Lookahead: if the next item fits exactly into post_residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 15.0;
        } else {
            // Next item won't fit here; mildly penalize leaving a medium gap
            // that neither fits next item nor is likely useful.
            let overshoot = (next_item_size - post_residual) as f64;
            if overshoot < 20.0 {
                score += 8.0;
            }
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits,
    // avoiding opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Global pressure: many open bins with high mean residual -> prefer
    // consolidating into existing space rather than opening new bins.
    if bin_residual != bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        score -= 12.0 * pressure;
    } else {
        // New-bin candidate: penalize unless it produces a better long-term fit.
        // Opening a new bin is attractive early (few bins) or when existing
        // residuals are all small (mean_residual low means existing bins are full).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let scarcity = 1.0 - (mean_residual / bin_capacity as f64).min(1.0);
        let open_bonus = (open_bins_count as f64).ln().max(0.0);
        score += 5.0 + 20.0 * progress - 15.0 * scarcity - 2.0 * open_bonus;
        // If item is large, a fresh bin keeps flexibility for pairing.
        if item_size > bin_capacity / 2 {
            score -= 10.0;
        }
    }

    // Mild time-varying exploration term: early stream favors tight packing,
    // later stream favors consolidation of open bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 6.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post = post_residual as f64;
    let post_norm = post / cap;

    // Base: post residual, damped by progress (late stream: waste matters more)
    let mut score = post * (0.7 + 0.6 * progress * progress);

    // Smooth non-linear coupling: dead space penalty grows quadratically when post_residual is small
    score += 12.0 * (1.0 - post_norm) * (1.0 - post_norm) * progress;

    // Reward tight fits more strongly as stream progresses
    let tightness = 1.0 - post_norm;
    score -= 8.0 * tightness * tightness * tightness * (0.5 + progress);

    // Lookahead: bonus if next item fits into post residual (smooth decay with mismatch)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fits_next = (post - nxt).max(0.0) / cap;
        let match_bonus = (1.0 - (post_norm - nxt / cap).abs()).max(0.0);
        score -= 6.0 * match_bonus * (1.0 - fits_next);
        // Penalize leaving residual just under next item size (dead space trap)
        if post < nxt && post > 0.0 {
            score += 5.0 * (1.0 - post / nxt) * (1.0 + progress);
        }
    }

    // Last-chance bin: strongly favor using it (avoid opening new bin)
    if fitting_bins_count == 1 {
        score -= 10.0 * (0.5 + progress);
    }

    // Mild penalty when many bins open and residual is near mean (no diversification value)
    let mean_gap = (mean_residual - post).abs() / cap;
    score -= 3.0 * mean_gap * mean_gap * (open_bins_count as f64 / (open_bins_count as f64 + 4.0));

    // New-bin candidate handling: empty bin should only win when open bins are poor fits
    if bin_residual as f64 == cap {
        // Neutral-ish base for new bin; slight progress-dependent reluctance
        score = 0.85 * cap + 20.0 * progress;
        if next_item_size > 0 && (cap - next_item_size as f64) >= item_size as f64 {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: reward residuals that are "useful"
    // sizes for future items (multiples of 10 and small values).
    let pr = post_residual;
    let class = pr % 10;
    let class_bonus: f64 = match class {
        0 => 18.0,   // perfect harmonic residual
        5 => 8.0,    // half-class still useful
        1 | 9 => 2.0,
        _ => 0.0,
    };
    score -= class_bonus;

    // Dead-space penalty: tiny residuals are unusable.
    if pr > 0 && pr < 10 {
        score += 25.0;
    }

    // Integer-division threshold: how many minimum-size items (size 10) fit.
    let fits10 = pr / 10;
    score -= (fits10 as f64).min(5.0) * 6.0;

    // Lookahead coupling: reward exact match with next item size.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size <= pr {
            let slack = pr - next_item_size;
            let slack_class = slack % 10;
            if slack_class == 0 {
                score -= 12.0;
            } else if slack < 10 {
                score += 8.0;
            }
        } else {
            // next item cannot use this residual -> penalize proportionally
            score += ((next_item_size - pr) as f64) * 0.3;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when open bins have poor fits
    // (large mean residual spread) or many bins already open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let openness = open_bins_count as f64;
        let waste = (mean_residual - pr as f64).abs();
        score -= 10.0 + 15.0 * progress - openness * 1.5 + waste * 0.2;
        // Don't open new bins if an existing bin fits near-perfectly.
        if pr == 0 && bin_residual >= item_size {
            score += 5.0;
        }
    }

    // Tight-fit reward: leaving small-but-valid residuals is good.
    if pr > 0 && pr <= 15 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
