pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is already the base, amplify it.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Exact fit is golden.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead: if the next item fits into the post_residual, reward this bin;
    // otherwise penalize leaving a gap that is too small for the next item.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0 * (next_item_size as f64 / 100.0);
        } else {
            let waste = post_residual as f64;
            score += 0.3 * waste;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Penalize bins far from the mean residual (prefer typical-fill bins),
    // keeping some residual spread healthy.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Time horizon: early in the stream, be conservative (favor filling existing
    // bins); late in the stream, be more willing to open fresh bins for big items.
    let progress = step_index as f64 / total_items.max(1) as f64;

    // New-bin candidate handling: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is attractive when the item is large and few bins fit it,
        // or when we are early and there is plenty of stream left.
        let large_item_bonus = (item_size as f64 / 100.0) * 20.0;
        score -= large_item_bonus * (1.0 - progress) + 8.0 * (1.0 - progress);
        // But discourage hoarding too many open bins.
        score += 1.5 * open_bins_count as f64;
    } else {
        // Slight preference for filling already-open bins as bins accumulate.
        score += 0.4 * open_bins_count as f64 * (1.0 - progress);
    }

    // Mild bonus for keeping post_residual in a "useful" band (>= smallest plausible item).
    if post_residual >= 10 && post_residual < 20 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let fit = item_size as f64 / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let norm_post = post / cap;
    let poly = norm_post * norm_post * (1.0 - progress) + norm_post * (0.5 + 0.5 * progress);

    let mut score = post * (1.0 + 0.5 * poly);

    // Penalize large post residual more as the stream progresses (less time to fill it)
    score += 30.0 * norm_post * norm_post * progress;

    // Reward tight fits (small post residual)
    score -= 10.0 * (1.0 - norm_post) * (1.0 - norm_post) * fit;

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize slightly unless post residual is large enough
    // to serve future items (compare with lookahead)
    if bin_residual == bin_capacity {
        let need = next_item_size as f64 / cap;
        let usefulness = 1.0 - (norm_post - need).abs();
        score += 8.0 - 10.0 * usefulness * (0.3 + 0.7 * progress);
    }

    // Lookahead coupling: prefer bins whose post residual fits the next item
    if next_item_size > 0 && post >= next_item_size as f64 {
        score -= 6.0 * (post / cap);
    }

    // Mean-residual divergence penalty: avoid creating outliers in residual spread
    score += 0.15 * (post - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Strongly reward tight fits (small post_residual relative to capacity).
    let tightness = post / cap;
    score += 30.0 * tightness * tightness;

    // Harmonic class of post_residual: dead space that no small item (<=30)
    // can fill is heavily penalized.
    let dead = post > 30.0 && post_residual < item_size;
    if dead {
        score += 40.0;
    }

    // Modulo/harmonic classes: post_residual near multiples of common small
    // item sizes (10,20,25,50) are reusable; reward closeness to those classes.
    let classes: [f64; 4] = [10.0, 20.0, 25.0, 50.0];
    let mut best_gap = f64::INFINITY;
    for c in classes.iter() {
        let gap = (post - c).abs();
        if gap < best_gap {
            best_gap = gap;
        }
    }
    score += 0.6 * best_gap;

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let perfect = (post_residual - next_item_size) == 0;
        if perfect {
            score -= 25.0;
        } else {
            score -= 8.0;
        }
    }

    // Last chance bin: if this is the only fitting bin, favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless the item
    // is large (poor fits in existing bins are likely).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let base = 45.0
            - 20.0 * (item_size as f64 / cap)
            - 10.0 * progress
            - 2.0 * (open_bins_count as f64).ln().max(0.0);
        // If existing bins leave very fragmented residuals, new bin is ok.
        if mean_residual < 25.0 && open_bins_count > 2 {
            return base - 20.0;
        }
        return base;
    }

    // Slight preference for bins below mean residual (balance load).
    score += 0.15 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space heavily (dead space < 10 is worthless).
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual as f64) * 12.0;
    }

    // Reward exact / near-exact fits strongly.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bonus: if this is the only fitting bin, prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening new bins when open-bin pressure is high.
    if bin_residual == bin_capacity {
        score += 15.0 + open_bins_count as f64 * 2.0;
    }

    // Lookahead coupling: if the next item fits into the post residual, reward this placement.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 18.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item won't fit in the gap: mild penalty for blocking future use.
        score += 6.0;
    }

    // Mild preference for tighter bins overall (deviation from mean residual).
    score += (bin_residual as f64 - mean_residual) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits: minimize post_residual aggressively.
    let tight_fit = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 2.5 * tight_fit * tight_fit * (bin_capacity as f64);

    // Exact fit bonus (item fills bin completely).
    if post_residual == 0 {
        score -= 100.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches the
    // next item size (chain of perfect fits), penalize wasted small residuals.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if (post_residual as u32) >= next_item_size {
            // Next item fits perfectly or well into this bin's leftover.
            if gap < 5.0 {
                score -= 60.0;
            } else {
                score -= 25.0 / (1.0 + gap);
            }
        } else {
            // Leftover too small for next item: dead space penalty, worse when
            // the leftover is small and unusable.
            let dead = post_residual as f64;
            score += 1.5 * dead * (1.0 - dead / bin_capacity as f64);
        }
    }

    // Relative to mean residual: prefer bins that are already more filled
    // (smaller residual) than average -> best-fit-like consolidation.
    let rel = bin_residual as f64 - mean_residual;
    score -= 0.8 * rel;

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless the item
    // is large relative to capacity or no good fit exists.
    if bin_residual == bin_capacity {
        // Empty bin baseline: neutral-ish score, penalized so it loses to
        // decent fits, but wins when open bins have huge residuals.
        score += 0.35 * (bin_capacity as f64) + 0.5 * mean_residual;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            // Pairing lookahead favors a fresh bin for a clean two-item load.
            score -= 30.0;
        }
    }

    // Stream progression: late in the stream, be more conservative about
    // spreading (favor filling existing bins).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Mild penalty for many open bins to encourage consolidation.
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but zero residual is ideal.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    } else if post_residual <= 25 {
        score -= 4.0;
    }

    // Lookahead: if the next item fits exactly into the post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            if slack <= 10.0 {
                score -= 8.0;
            } else {
                score += slack * 0.15;
            }
        } else {
            // Next item cannot follow here; slight penalty, worse for large overflow.
            let over = (next_item_size - post_residual) as f64;
            score += over * 0.05;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Penalize creating dead space relative to mean residual of open bins.
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.3;
    } else {
        score -= (mean_residual - post_residual as f64) * 0.1;
    }

    // Time horizon: late in the stream, prefer filling existing bins tightly over opening new ones.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual < bin_capacity {
        score -= progress * 10.0;
    } else {
        // New-bin candidate: penalize opening new bins when many bins are open or late in stream.
        score += progress * 8.0 + (open_bins_count as f64).sqrt() * 3.0;
    }

    // Mild penalty for many open bins to encourage consolidation.
    score += open_bins_count as f64 * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalize stream progress
    let progress = if total_items > 1 { step_index as f64 / (total_items - 1) as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Smooth polynomial coupling of post_residual with progress:
    // waste is penalized more heavily as the stream progresses
    let poly = post / cap;
    score += (poly * poly) * (1.0 + 2.0 * progress) * 30.0;

    // Reward tight fits (small post_residual relative to capacity), smoothly
    let tightness = 1.0 - poly;
    score -= tightness * tightness * (10.0 + 20.0 * progress);

    // Penalize dead space that next item cannot use (smooth quadratic mismatch)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post - nxt).abs();
        score += (gap / cap) * (gap / cap) * 40.0 * (0.5 + progress);
    }

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 100.0;
    }

    // Penalize opening a new bin when decent open bins exist, more so late in stream
    if bin_residual == bin_capacity {
        let mean_ok = if mean_residual > item_size as f64 { 1.0 } else { 0.5 };
        score += 25.0 * (0.5 + progress) * mean_ok * (1.0 + open_bins_count as f64 * 0.05);
    }

    // Mild penalty for too many open bins relative to mean residual
    score += (open_bins_count as f64).sqrt() * (mean_residual / cap) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues near "dead zones"
    // (very small leftovers that nothing can reuse) are heavily penalized.
    let dead_threshold = (cap * 0.1) as u32; // post_residual <= 10 => dead space
    if post_residual <= dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual + 1) as f64 * 2.0;
    }

    // Reward perfect or near-perfect fits (harmonic match to capacity).
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 3 {
        score -= 20.0;
    }

    // Integer-division thresholds: how many items of the *next* size could
    // still fit into the post-residual? Reward multiples of the lookahead size.
    if next_item_size > 0 && post_residual >= next_item_size {
        let k = post_residual / next_item_size;
        score -= k as f64 * 5.0;
        // exact match: next item fills bin completely -> strong reward
        if post_residual == next_item_size {
            score -= 25.0;
        }
    } else if next_item_size > 0 {
        // next item cannot follow into this bin: mild penalty scaled by
        // how big the next item is relative to capacity.
        score += (next_item_size as f64 / cap) * 10.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Prefer filling more-congested bins (tight residual relative to mean).
    score -= (bin_residual as f64 - mean_residual) * 0.3;

    // New-bin candidate: only attractive when no open bin fits well or
    // stream is early (few open bins). Penalize otherwise.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let poor_fit_exists = fitting_bins_count == 0
            || (post_residual as f64) > cap * 0.5;
        if poor_fit_exists {
            score -= 10.0 + 20.0 * (1.0 - progress);
        } else {
            score += 30.0 + open_bins_count as f64 * 2.0;
        }
    }

    // Slight preference for bins whose residual is harmonically aligned
    // with common item sizes (multiples of 10 in the 1..100 interface).
    let harmon = post_residual % 10;
    if harmon == 0 && post_residual > 0 {
        score -= 3.0;
    } else {
        score += harmon as f64 * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small to hold even the
    // smallest plausible item are almost pure waste — penalize them heavily.
    if post_residual > 0 && post_residual < item_size.min(20) {
        score += 40.0 + (20 - post_residual) as f64 * 2.5;
    }
    // Absolute dead space: residual so small nothing (<=10) can ever fit.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Reward tight fits (low post_residual relative to item size).
    if item_size > 0 {
        let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
        score -= 12.0 * fill_ratio;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: discourage spreading across many bins, but a brand-new
    // bin candidate (residual == capacity) is exempt from this pressure.
    if bin_residual != bin_capacity {
        score += (open_bins_count as f64) * 1.5;
    } else {
        // New bin: baseline cost, slightly reduced when current bins are crowded.
        score += 18.0 - (open_bins_count as f64).min(20.0) * 0.4;
        // Prefer a new bin if the lookahead item would be stranded by this placement.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score -= 15.0;
        }
    }

    // Lookahead coupling: if this placement leaves room exactly for the next
    // item, reward it; if it leaves a gap just barely too small, penalize.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 18.0;
        } else if post_residual > next_item_size && post_residual < next_item_size + 10 {
            score += 6.0;
        }
    }

    // Mild stream-progression regularization.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 2.0 * progress;

    // Prefer bins whose residual is close to the mean (keeps bin states uniform).
    score += 0.3 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate: make it costly unless no open bin fits or fit is terrible.
    if bin_residual == bin_capacity {
        let mut penalty = 45.0;
        if fitting_bins_count == 0 {
            penalty = -1000.0; // must open a new bin
        } else if post_residual as f64 > mean_residual {
            // opening new bin wastes more space than average
            penalty += 15.0;
        }
        // late in the stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        penalty *= 1.0 + 0.5 * progress;
        score += penalty;
        return score;
    }

    // Reward tight fits (low post_residual) relative to mean residual.
    score -= 0.8 * (mean_residual - post_residual as f64);

    // Aggressive 2-step lookahead: if next item fits exactly into post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect 2-chain
        } else if next_item_size <= post_residual {
            let leftover = post_residual - next_item_size;
            // reward good secondary fits, penalize tiny dead space after two items
            score -= 25.0 - 0.5 * leftover as f64;
        } else {
            // next item won't fit here: penalize wasted potential
            let gap = next_item_size - post_residual;
            score += 0.3 * gap as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Penalize leaving awkward dead space (< smallest plausible item) after placement.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Slight preference for bins already below mean residual (compact packing).
    if (post_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core tightness reward: quadratic penalty on post_residual (dead space).
    let pr = post_residual as f64;
    score += 0.65 * pr * pr / bin_capacity as f64;

    // Reward near-perfect fits strongly.
    if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual <= 12 {
        score -= 12.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            // fraction of post residual consumed by next item
            let fill = nxt / pr.max(1.0);
            score -= 15.0 * fill;
        } else {
            // next item won't fit here: penalize bins that leave a tempting but unusable gap
            let gap_ratio = pr / bin_capacity as f64;
            score += 8.0 * gap_ratio;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Many fitting bins: mild penalty to encourage diversity of residual sizes
    if fitting_bins_count > 3 {
        score += 2.0 * (fitting_bins_count as f64 - 3.0);
    }

    // Prefer bins with residual below mean residual (consolidate small gaps).
    let res = bin_residual as f64;
    score += 0.35 * (res - mean_residual);

    // Time horizon: early on, be pickier about dead space; late, just fill bins.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 - 0.25 * t;

    // New-bin candidate handling: only attractive when current bins fit poorly.
    if bin_residual == bin_capacity {
        let open = open_bins_count as f64;
        // Opening a new bin costs ~1 bin; make it unattractive unless residuals are large.
        score = bin_capacity as f64 + 25.0;
        // If mean residual is large (bins are fragmented), new bin is more acceptable.
        score -= 0.5 * mean_residual;
        // More open bins => slightly discourage opening yet another.
        score += 1.5 * open.sqrt();
        // If item is large relative to capacity, opening fresh bin is reasonable.
        score -= 0.3 * item_size as f64;
        // Late in stream, prefer filling existing bins.
        score += 20.0 * t;
        // If this is the only chance (no other fitting bin), opening is fine.
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: waste left behind, slightly discounted early (long stream to fill bins).
    let mut score = pr * (1.0 - 0.35 * progress);

    // Non-linear coupling: quadratic waste penalty grows as stream progresses.
    let waste_frac = pr / cap;
    score += 18.0 * waste_frac * waste_frac * (0.3 + progress);

    // Reward tight fits: smooth cubic bonus for small post_residual.
    let tight = 1.0 - waste_frac;
    score -= 12.0 * tight * tight * tight;

    // Coupling with mean residual: prefer bins whose post-residual moves bin toward mean
    // (keeps residuals uniform, easier to pack small future items).
    let dev = (pr - mean_residual).abs() / cap;
    score += 6.0 * dev * dev;

    // Lookahead: if next item fits exactly into post_residual, strong reward; if next item
    // is slightly larger than post_residual, penalize (dead space blocking lookahead).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            score -= 10.0 * (1.0 - (pr - nx) / cap);
        } else {
            score += 5.0 * ((nx - pr) / cap);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: mildly penalize opening a new bin when good fits exist,
    // but allow it when the item is large (would leave tiny unusable residual elsewhere).
    if bin_residual == bin_capacity {
        let large_item_bonus = 8.0 * (it / cap) * (it / cap);
        score += 6.0 + 4.0 * (open_bins_count as f64).sqrt() - large_item_bonus;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: capacity divided into eighths.
    // Residuals in the lowest class (<= 12) are near-perfect fits -> strong reward.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let eighth = cap / 8.0;
    let class = (pr / eighth).floor() as i32; // 0..=8
    score -= match class {
        0 => 30.0,
        1 => 15.0,
        2 => 7.0,
        3 => 3.0,
        4 => 0.0,
        _ => -2.0, // larger residuals slightly favored over mid ones (more usable)
    };

    // Non-linear exact-fit bonus: quadratic decay of residual.
    score += (pr * pr) / (2.0 * cap);

    // Lookahead coupling: reward if next item fits the post residual well.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let gap = pr - nxt;
            score -= (eighth - gap).max(0.0) * 0.5; // perfect lookahead fit rewarded
            score -= 4.0; // bin stays useful
        } else {
            // next item cannot use this bin's remainder; penalize wasted space
            score += (pr - nxt).abs() * 0.15;
        }
    }

    // Last-chance bin: strongly prefer using it rather than opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no open bin fits decently.
    if bin_residual == bin_capacity {
        let base = cap * 0.55;
        let pressure = if fitting_bins_count == 0 { 0.0 } else { open_bins_count.min(10) as f64 * 6.0 };
        score = base + pressure + pr;
        if next_item_size > 0 && (next_item_size as f64) <= cap * 0.5 {
            score -= 8.0; // new bin can host next item too
        }
        if fitting_bins_count == 1 {
            score += 40.0; // don't abandon the only fitting bin
        }
    }

    // Mean-residual context: if this bin's residual is far below mean, it's a tight fit -> good.
    score -= (mean_residual - pr).max(0.0) * 0.3;

    // Slight stream-phase tilt: prefer consolidating early, keep slack later.
    let phase = step_index as f64 / (total_items.max(1) as f64);
    score += phase * (pr / cap) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // even the smallest plausible item are pure waste -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (1.0 - post_residual as f64 / 10.0);
    }
    if post_residual == 0 {
        // Perfect fit: strongly reward closing a bin completely.
        score -= 40.0;
    }

    // Moderate residuals (10..30) are semi-dead space: penalize mildly.
    if post_residual >= 10 && post_residual < 30 {
        score += 8.0 * (1.0 - (post_residual as f64 - 10.0) / 20.0);
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual,
    // reward this placement (enables a perfect second fit).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
        if post_residual == next_item_size {
            score -= 15.0;
        }
    }
    // If next item does NOT fit in the resulting gap, that gap may become dead
    // space; penalize small gaps more when lookahead fails.
    if next_item_size > post_residual && post_residual > 0 && post_residual < next_item_size {
        score += 5.0;
    }

    // Open-bin pressure: discourage scattering across many open bins unless
    // the fit is good; scale mild penalty with number of open bins.
    if bin_residual != bin_capacity {
        score += (open_bins_count as f64).sqrt() * 1.5;
    } else {
        // New-bin candidate: slightly favor it when few bins fit or when
        // the current bin would leave a very poor residual.
        if fitting_bins_count <= 1 {
            score -= 10.0;
        }
        // Prefer opening a fresh bin when mean residual across bins is low
        // (existing bins are nearly full anyway).
        score += mean_residual / 10.0;
    }

    // Tight-fit preference: reward using most of the bin.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect two-step match: residual after placing equals next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 30.0 / (1.0 + gap);
        // Exact match bonus
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Penalize residual that is too small for next item (dead space risk)
        if post_residual < next_item_size && post_residual > 0 {
            score += 12.0 * (1.0 - post_residual as f64 / next_item_size.max(1) as f64);
        }
    } else {
        // Last item: prefer minimal residual
        score -= 20.0;
    }

    // Tight fit reward relative to capacity
    score -= 15.0 * (item_size as f64 / bin_capacity as f64);

    // Prefer bins with residual below mean (dense bins), penalize above-mean bins
    score += 0.35 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strong bonus to use it rather than waste it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New empty bin candidate: penalize moderately so it wins only when open bins fit poorly
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 22.0 + 10.0 * (1.0 - progress);
        // Opening a new bin is more attractive if item is large and would leave tiny residue
        if item_size as f64 / bin_capacity as f64 > 0.8 {
            score -= 30.0;
        }
    }

    // Mild pressure against accumulating too many open bins
    score += 0.15 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize residual that is small but nonzero (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }
    if post_residual == 0 {
        score -= 25.0; // perfect fill is excellent
    }

    // Lookahead: if the next item fits exactly into post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            // next item won't fit here; penalize proportionally to wasted potential
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Prefer bins with below-average residual (keep fat bins for future big items).
    let residual_gap = bin_residual as f64 - mean_residual;
    score += residual_gap * 0.3;

    // Time horizon: early in the stream, be conservative (favor compacting into few bins);
    // later, allow more aggressive spreading.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    // Many open bins: discourage adding to spread; few open bins: encourage using them.
    if open_bins_count > 4 {
        score += 0.5 * open_bins_count as f64;
    } else {
        score -= 1.0;
    }

    // New-bin candidate: empty bin should only win if no good fit exists.
    if bin_residual == bin_capacity {
        score += 20.0 + 0.5 * item_size as f64;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;

    // Reward tight fits: normalized fill ratio, non-linearly amplified
    let fill = 1.0 - (post_residual as f64 / cap);
    score -= 24.0 * fill * fill * (1.0 + progress);

    // Penalize dead space that is too small to be useful (below typical item scale)
    let dead = post_residual as f64;
    let dead_norm = dead / cap;
    score += 18.0 * dead_norm * dead_norm * (1.0 - dead_norm);

    // Lookahead: reward leaving room for the next item (smooth coupling)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (post_residual as f64 - nx).abs();
        let gap_norm = gap / cap;
        score += 6.0 * gap_norm * gap_norm;
        if post_residual >= next_item_size {
            score -= 4.0 * (nx / cap) * (1.0 - gap_norm);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 - progress);
        score -= 12.0;
    }

    // More fitting bins => competition; mild penalty to spread preference toward tightest fit
    if fitting_bins_count > 1 {
        score += 1.5 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate: only attractive when existing residuals are poor fits
    if bin_residual == bin_capacity {
        let mean_fit_penalty = (mean_residual - item_size as f64).abs();
        let need = (mean_fit_penalty / cap).powf(2.0);
        score = cap - 20.0 * need - 8.0 * progress;
        if fitting_bins_count <= 1 {
            score -= 15.0;
        }
    }

    // Mild preference to consolidate into fewer bins early
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals divisible by common
    // item sizes are more reusable, so reward them (subtract).
    let cap = bin_capacity as f64;
    let pr = post_residual as u32;

    // Reward post_residuals in "harmonic" residue classes (multiples of 10/20/25)
    if pr > 0 {
        if pr % 10 == 0 {
            score -= 6.0;
            if pr % 20 == 0 { score -= 3.0; }
            if pr % 50 == 0 { score -= 2.0; }
        } else {
            // Penalize awkward residues (prime-ish / odd chunks)
            score += (pr % 10) as f64 * 0.8;
        }
    }

    // Perfect fit is ideal
    if pr == 0 {
        score -= 25.0;
    }

    // Tight fill fraction: reward bins that end up mostly full
    let fill = (bin_capacity - post_residual) as f64 / cap;
    score -= fill * fill * 8.0;

    // Lookahead: if the next item fits exactly into the post-residual,
    // strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 18.0;
        } else if next_item_size < pr {
            // harmonic-class match between lookahead and residual
            let diff = pr - next_item_size;
            if diff % 10 == 0 { score -= 5.0; }
            score -= 3.0 * (1.0 - diff as f64 / cap);
        } else {
            // next item cannot fit here; slight penalty proportional to waste
            score += 1.5;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless the item is
    // large (poor fit elsewhere is unlikely) or many bins are already open.
    if bin_residual == bin_capacity {
        score += 10.0;
        if item_size >= 60 { score -= 6.0; }
        if fitting_bins_count == 0 { score -= 15.0; }
        // late in the stream, avoid proliferating bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 8.0 * progress;
    }

    // Prefer bins whose residual is below the mean residual (denser bins)
    score -= (mean_residual - post_residual as f64) * 0.05;

    // Mild preference for using older/more-filled bins when many are open
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harder than large ones.
    // A residual that is too small to hold even the smallest plausible future item is "dead".
    let dead_threshold = 15.0; // below this, residual is nearly useless
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 8.0;
    } else {
        // Prefer tighter fits nonlinearly: reward small post_residual more than linearly.
        score += (post_residual as f64 / bin_capacity as f64) * 30.0;
    }

    // Reward perfect or near-perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new bins
    // and prefer consolidating into existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (1.0 + progress);
    score += pressure * 2.0;

    // Last-chance bin: if this is the only fitting bin, heavily favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are quite full.
    if bin_residual == bin_capacity {
        // Base penalty so new bins are only chosen when existing fits are terrible.
        score += 45.0 + open_bins_count as f64 * 3.0;
        // If the next item is large, a fresh bin may still be valuable later;
        // slight relief when mean residual across open bins is low.
        if mean_residual < 20.0 {
            score -= 20.0;
        }
    }

    // Lookahead: if the next item fits exactly in the post_residual, reward this placement
    // (it enables a perfect follow-up packing).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item cannot use this bin's leftover; leftover is more likely dead space.
        score += (post_residual as f64).min(next_item_size as f64) * 0.5;
    }

    // Mild preference for bins whose residual is above the item size by a comfortable margin
    // (avoid fragmenting bins that could serve larger future items).
    if post_residual > 0 && post_residual < item_size as f64 * 0.5 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is always excellent.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Small post-residuals are good; penalize dead space quadratically.
    score += (post_residual as f64).powi(2) / bin_capacity as f64;

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0 + 0.25 * (post_residual - next_item_size) as f64;
        } else {
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: penalize opening a new bin unless it is genuinely needed.
    if bin_residual == bin_capacity {
        score += 120.0;
        if fitting_bins_count > 0 {
            score += 60.0 * fitting_bins_count as f64;
        }
        // Late in the stream, opening new bins is more wasteful.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 80.0 * progress;
    }

    // Prefer bins that are already tight relative to the fleet mean residual.
    if bin_residual < bin_capacity {
        let tightness = (bin_capacity as f64 - bin_residual as f64) / bin_capacity as f64;
        score -= 10.0 * tightness;
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        }
    }

    // Mild preference for consolidating into fewer bins when many are open.
    score -= 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1)

    // Base: prefer tight fits (small post_residual), with quadratic sharpening.
    let mut score = pr as f64 * (1.0 + 1.5 * x * x);

    // Smooth non-linear coupling of post_residual with stream progress:
    // early in stream, tolerate larger residuals (bins still useful later);
    // late in stream, penalize residuals more aggressively to close bins out.
    let progress_coupling = 0.5 + 2.0 * progress * progress;
    score *= progress_coupling;

    // Dead-space penalty: residual too small to fit the next item is wasted.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            score += (nxt - pr) * (1.0 + progress);
        } else {
            // Reward bins that can also accommodate the lookahead item,
            // scaled by how snugly the next item fits.
            let snug = (pr - nxt) / cap;
            score -= 8.0 * (1.0 - snug * snug) * (0.5 + progress);
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).sqrt();
    }

    // Prefer bins with residuals close to the item (best-fit flavor),
    // smoothly interpolated via mean residual context.
    let fit_gap = (bin_residual as f64 - item_size as f64) / cap;
    score += 5.0 * fit_gap * fit_gap;

    // Mild pressure to consolidate: penalize spreading across many open bins,
    // modulated by how far above the mean residual this bin sits.
    let mean_gap = bin_residual as f64 - mean_residual;
    score += 0.05 * mean_gap * mean_gap / cap;

    // Slight preference for keeping older bins busy (smooth decay with count).
    score += 0.3 * (open_bins_count as f64).ln().max(0.0);

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let openness = (fitting_bins_count as f64).max(1.0);
        score = pr + 20.0 / openness + 10.0 * (1.0 - progress);
        if next_item_size > 0 && next_item_size as f64 <= pr {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: classify dead space by capacity fraction.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // fraction of capacity left after placement

    // Integer-division thresholds on post_residual (harmonic bands of C):
    // residuals divisible by common item sizes are more reusable.
    let pr_u = post_residual;
    if pr_u == 0 {
        score -= 60.0; // perfect fit: best possible outcome
    } else {
        // Reward residuals that are multiples of common small sizes (10,20,25,50)
        if pr_u % 10 == 0 { score -= 12.0; }
        if pr_u % 20 == 0 { score -= 6.0; }
        if pr_u % 25 == 0 { score -= 6.0; }
        if pr_u % 50 == 0 { score -= 8.0; }
        // Penalize residuals in awkward bands (just above typical item sizes)
        if pr_u > 80 && pr_u < 90 { score += 4.0; }
        if pr_u > 30 && pr_u < 40 { score += 3.0; }
        if pr_u > 10 && pr_u < 20 { score += 5.0; } // small dead space hard to reuse
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            let slack = post_residual - next_item_size;
            score -= 15.0 * (1.0 - slack as f64 / cap);
            // harmonic bonus if post_residual % next_item_size == 0
            if next_item_size > 0 && post_residual % next_item_size == 0 {
                score -= 10.0;
            }
        } else {
            // next item cannot follow here: slight penalty for small residuals
            score += 3.0 * (1.0 - frac);
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Prefer tighter fits generally: weight residual relative to mean residual.
    if mean_residual > 0.0 {
        score += 0.5 * (pr - mean_residual);
    }

    // New-bin candidate handling: opening a new bin wastes capacity unless
    // current fits are poor. Penalize new bin when decent fits exist.
    if bin_residual == bin_capacity {
        // base cost of a fresh bin
        score = cap * 0.55;
        // if item is large relative to capacity, new bin is fine
        score -= 0.3 * item_size as f64;
        // if many bins are open and mean residual is large, prefer existing bins
        if open_bins_count > 0 && mean_residual > item_size as f64 {
            score += 20.0;
        }
        // last item: never open a new bin
        if next_item_size == 0 {
            score += 100.0;
        }
    }

    // Progress-based mild scaling: early stream, be conservative with bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // Gaps that are too small for typical items are "dead space": heavy penalty.
    // Treat gaps < 10 (or < smallest plausible item) as waste; gaps >= 30 are reusable.
    let dead_threshold = 12.0f64;
    let usable_threshold = 30.0f64;
    if (post_residual as f64) < dead_threshold {
        score += 60.0; // nearly unusable gap -> very bad
    } else if (post_residual as f64) < usable_threshold {
        // small gap: penalty grows as gap shrinks toward dead_threshold
        let t = (post_residual as f64 - dead_threshold) / (usable_threshold - dead_threshold);
        score += 25.0 * (1.0 - t);
    } else {
        // large reusable gap: reward
        score -= 10.0;
    }

    // --- Perfect / near-perfect fit reward ---
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // --- Reward using a bin whose residual was close to the item (tight fit) ---
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 20.0 * tightness;

    // --- Open-bin pressure: with many open bins, prefer filling existing ones ---
    let pressure = open_bins_count as f64 / (1.0 + total_items as f64 * 0.05);
    score += 8.0 * pressure;

    // --- Last-chance bin: if this is the only bin that fits, strongly prefer it ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // --- Lookahead: if the next item fits exactly in the post residual, reward ---
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual > next_item_size {
            score -= 8.0;
        }
    }

    // --- Mean residual coupling: prefer bins with residual below mean (fill emptier-of-space bins) ---
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // --- New-bin candidate: opening a new bin should only win when no open bin fits well.
    // Penalize the empty-bin candidate by open-bin count pressure so existing bins win
    // unless their scores are terrible (e.g. large dead space).
    if bin_residual == bin_capacity {
        score += 45.0 + 5.0 * open_bins_count as f64;
        // but if the item is huge relative to capacity, a fresh bin is fine
        if item_size as f64 > 0.7 * bin_capacity as f64 && open_bins_count > 0 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect or near-perfect fits (low post_residual).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        if diff <= 2.0 {
            score -= 300.0; // exact 2-step chain match
        } else if post_residual as f64 >= nxt {
            score -= 80.0 / diff; // graded reward, stronger for close matches
        } else {
            // Next item cannot fit here: dead space penalty scaled by gap.
            score += 0.5 * (nxt - post_residual as f64);
        }
    }

    // Relative-to-mean coupling: prefer bins that keep residuals balanced
    // when many bins are open, but break balance when few are open.
    let balance = post_residual as f64 - mean_residual;
    if open_bins_count > 2 {
        score += 0.3 * balance;
    } else {
        score += 0.1 * balance;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize mildly so we only open when truly better;
    // penalize more when open bins are getting fragmented (high mean residual spread).
    if bin_residual == bin_capacity {
        score += 60.0 + 0.2 * mean_residual;
        // But if next item is large and post_residual here would be huge, opening
        // a fresh bin is attractive: reduce penalty.
        if next_item_size > 0 && next_item_size > post_residual {
            score -= 40.0;
        }
    }

    // Early in the stream, be slightly more willing to open bins (build diversity).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post_residual).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 12.0 * fit_ratio * fit_ratio;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly into the post_residual, big bonus.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual >= next_item_size {
            score -= 6.0 * (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
        } else {
            // Next item won't fit here; penalize leaving medium-size dead space.
            score += 0.05 * post_residual as f64;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when good existing fits exist, unless residual is very small.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // New bins are cheaper early when many items remain; more costly later.
        score += 20.0 + 15.0 * progress;
        if mean_residual > item_size as f64 * 2.0 {
            score += 10.0; // plenty of slack elsewhere; don't open new bin
        }
    }

    // Prefer bins with residual close to the item (minimize fragmentation).
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.08 * gap;

    // Mild penalty when bin residual deviates from mean residual (keep balance).
    score += 0.02 * (bin_residual as f64 - mean_residual).abs();

    // Slight preference to fill already-open bins when many are open.
    if bin_residual != bin_capacity {
        score -= 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let fit = item_size as f64 / cap;
    let post = post_residual as f64;

    // Reward tight fits: squared normalized fill, amplified by stream progress.
    let tightness = 1.0 - post / cap;
    score -= 30.0 * tightness * tightness * (0.5 + progress);

    // Penalize post-residual dead space non-linearly (quartic-ish coupling with progress).
    let dead = post / cap;
    score += 40.0 * dead * dead * dead * (1.0 - progress);

    // Perfect-fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead coupling: favor bins whose post-residual matches next item size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post - nxt).abs();
        let match_score = 1.0 - gap / cap;
        score -= 25.0 * match_score * match_score;
        // If next item fits exactly after this placement, strong reward.
        if post_residual == next_item_size {
            score -= 20.0;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0 * (1.0 - progress);
    }

    // Prefer bins with residual below mean (consolidation), smooth interaction.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 15.0 * dev * (0.5 + progress);

    // Mild penalty for spreading across many open bins when progress is low.
    score += 2.0 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tight-fit reward: small post_residual strongly favored (quadratic decay)
    score -= 40.0 * (1.0 - (post_residual as f64) / cap).powi(6);

    // Harmonic classes: classify post_residual into capacity fractions.
    // Dead space in the lowest classes (tiny unusable slivers) is penalized.
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    if post_residual == 0 {
        score -= 60.0; // perfect fill
    } else if post_residual < quarter / 2 {
        score += 12.0; // tiny sliver: hard to reuse
    } else if post_residual < quarter {
        score += 4.0;
    } else if post_residual < half {
        score -= 6.0; // mid residual: reusable for typical items
    }

    // Integer-division harmonic classes: residual divisible classes pair well
    // with items of similar residue class (mod 10 buckets).
    let pr_class = (post_residual / 10) as f64;
    let ni_class = (next_item_size / 10) as f64;
    let class_gap = (pr_class - ni_class).abs();
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // lookahead fits: reward, more so when it nearly fills the residual
            score -= 18.0 * (1.0 - ((post_residual - next_item_size) as f64 / cap));
            if post_residual == next_item_size {
                score -= 30.0; // exact lookahead match: chain completion
            }
        } else {
            // lookahead cannot use this bin: penalize proportionally to gap
            score += 6.0 + 0.5 * class_gap;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // among many fitting bins, prefer tighter fits (already via post_residual)
        score += 1.5 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 {
            -100.0
        } else {
            let best_possible = (bin_residual - item_size) as f64;
            // open new bin if this placement would leave a very loose residual
            if best_possible > cap * 0.55 { -20.0 } else { 30.0 }
        };
        score += pressure + 0.5 * open_bins_count as f64;
    }

    // Stream progression: late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * progress * (1.0 - (post_residual as f64) / cap);

    // Prefer bins below mean residual (balancing loads across open bins).
    score += 0.3 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance: small unusable gaps are heavily penalized ---
    // Threshold: residual below the smallest plausible future item (1..100 interface,
    // but typical items are mid-sized) is "dead". Use a soft threshold around 15-20.
    let dead_threshold: f64 = 17.0;
    let pr = post_residual as f64;
    if pr > 0.0 && pr < dead_threshold {
        // Dead space: quadratic blow-up so near-exact fits are strongly preferred
        score += (dead_threshold - pr) * (dead_threshold - pr) * 4.0;
    }

    // --- Reward tight fits (small positive post_residual, still usable) ---
    if pr >= dead_threshold {
        // Mild bonus proportional to tightness relative to capacity
        score -= (bin_capacity as f64 - pr) * 0.35;
    }

    // --- Exact fit: massive reward ---
    if post_residual == 0 {
        score -= 500.0;
    }

    // --- Last-chance bin: strongly favor using it to avoid opening a new bin ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // --- Open-bin pressure: with many open bins, prefer consolidating ---
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    if bin_residual != bin_capacity {
        score -= pressure * 3.0;
    }

    // --- Lookahead coupling: if the next item fits in post_residual, bonus ---
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 40.0;
    }
    // If next item does NOT fit in post_residual, penalize creating a residual
    // that strands the lookahead (unless residual is large/usable anyway)
    if next_item_size > 0 && (next_item_size as f64) > pr && pr > 0.0 && pr < dead_threshold {
        score += 60.0;
    }

    // --- Mean-residual calibration: prefer bins whose residual is near the mean
    // (keeps open bins homogeneous, easier to pack later) ---
    if bin_residual != bin_capacity {
        let dev = (pr - mean_residual).abs();
        score += dev * 0.2;
    }

    // --- New-bin candidate handling: opening a new bin is only attractive when
    // current item is large relative to residuals of open bins, or many bins open
    // with poor fits. Base cost for a fresh bin: ---
    if bin_residual == bin_capacity {
        // Fresh bin starts with full residual; its raw score is bin_capacity.
        // Apply a moderate opening cost so tight fits elsewhere win, but allow
        // opening when open bins are fragmented (high count, high mean residual).
        let fragmentation = (mean_residual / bin_capacity as f64).powi(2);
        score += 30.0 - open_bins_count as f64 * 0.8 * fragmentation;
        // Late in the stream, slightly discourage opening extra bins
        score += progress * 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Lookahead: reward bins whose post_residual matches the next item well
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // next item cannot fit here: penalize wasted potential
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
        // near-exact match bonus (chain packing)
        let d = (post_residual as f64 - next_item_size as f64).abs();
        if d <= 5.0 {
            score -= 25.0;
        }
    }

    // Compare against mean residual: prefer bins below mean residual (tighter fit)
    score += 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: penalize opening a new bin unless no decent fit exists
    if bin_residual == bin_capacity {
        score += 120.0;
        if fitting_bins_count == 0 {
            score -= 500.0;
        }
        // open new bins more readily early in the stream
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 40.0 * (1.0 - progress);
    }

    // Mild preference to fill already-open bins when many are open
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward near-perfect fits.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 35.0;
    } else if post_residual <= 15 {
        score -= 12.0;
    }

    // Penalize leaving residual that no plausible future item can use.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if post_residual > 0 && post_residual < 10 {
        // dead space: too small for min-size item (sizes >= 1... be conservative)
        score += 8.0 * (1.0 - t);
    }

    // Lookahead: reward bins whose post_residual can host the next item exactly-ish.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 / (1.0 + slack);
        } else {
            // next item cannot follow here; mild penalty scaled by gap
            let gap = (next_item_size - post_residual) as f64;
            score += (gap / 20.0).min(10.0);
        }
    } else {
        // last item: prefer any bin, avoid opening new bins
        score -= 20.0;
    }

    // Last-chance bin: strongly favor using it to avoid proliferation.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin is costly unless current bin
    // fit is poor or many bins are already open with high mean residual.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 > mean_residual.max(1.0);
        let crowded = open_bins_count as f64 > 4.0 + 10.0 * t;
        if poor_fit || crowded {
            score -= 10.0; // acceptable to open
        } else {
            score += 25.0; // discourage needless bin opening
        }
    } else {
        // Slight preference for bins with below-mean residual (consolidate waste).
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
        // Prefer fuller bins early (first-fit-like), softer later.
        score += (bin_residual as f64 / bin_capacity as f64) * (6.0 - 4.0 * t);
    }

    // Mild exploration term coupling open-bin count and progress.
    score += 0.05 * (open_bins_count as f64).ln().max(0.0) * (1.0 - t);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer tight fits (low post_residual), with a smooth non-linear penalty
    // on both very small and moderately large residuals.
    let mut score = pr * (1.0 + 0.8 * progress) + 0.35 * (pr / c) * (pr / c) * c;

    // Smooth coupling: post_residual interacts with stream progress quadratically.
    score += 0.9 * (pr / c) * progress * (1.0 - progress) * c * 0.1;

    // Reward filling bins completely (post_residual near 0 gets extra subtraction).
    score -= 6.0 * (-pr / 12.0).exp();

    // Lookahead: if next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let fit_ratio = 1.0 - (pr - nxt) / c;
            score -= 8.0 * fit_ratio * fit_ratio;
        } else {
            score += 3.0 * (nxt - pr) / c;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 5.0 + 3.0 * progress;
    } else if fitting_bins_count > 1 {
        // Mild penalty proportional to abundance of alternatives.
        score += 0.4 * (fitting_bins_count as f64 - 1.0).min(4.0);
    }

    // Prefer bins whose residual is below the mean (more "used" bins).
    score += 0.5 * (pr - mean_residual) / c * 10.0;

    // Prefer fewer open bins (consolidation), smoothly scaled.
    score += 0.15 * open_bins_count as f64 * (pr / c);

    // New-bin candidate handling: empty bin gets a moderate penalty that decays
    // with progress, so early on new bins are acceptable but later we pack tighter.
    if bin_residual == bin_capacity {
        let decay = (-4.0 * progress).exp();
        score += 4.0 + 10.0 * decay;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which "slot band" does the leftover fall into
    // (0 = perfect fit, 1..=9 = progressively worse classes).
    let slot = bin_capacity / 10;
    let post_class = (post_residual / slot) as f64;
    score += post_class * 4.0;

    // Dead-space penalty: leftover too small for the smallest plausible future item (1..100 range).
    // Harmonic banding on next_item_size: can the lookahead item consume the leftover?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward chaining: leftover fits next item; stronger reward when it's a tight chain.
            let tightness = (next_item_size as f64 / post_residual as f64).powi(2);
            score -= 8.0 * tightness;
        } else {
            // Dead space: leftover can never be used by the next item.
            let dead = post_residual as f64 / bin_capacity as f64;
            score += 6.0 * dead * dead;
            // Extra penalty if leftover is in the "useless sliver" class (0..10).
            if post_residual < slot {
                score += 10.0;
            }
        }
        // Harmonic coupling: does post_residual land in the same modulo class as next_item_size?
        if post_residual % 10 == next_item_size % 10 && post_residual >= next_item_size {
            score -= 3.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits, else a new bin opens.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Prefer fuller bins: reward small bin_residual (tight packing pressure).
    score += (bin_residual as f64 / bin_capacity as f64) * 2.0;

    // Modulo arithmetic on post_residual: harmonics of 25 (quarter-bin classes).
    let quarter = post_residual % 25;
    if quarter == 0 {
        score -= 5.0; // exact quarter/half/three-quarter fill -> clean harmonic state
    } else {
        score += quarter as f64 * 0.1; // penalize misaligned residuals
    }

    // Integer-division thresholds: residual classes of size 10.
    let small_class = post_residual / 10;
    if small_class == 0 {
        score += 4.0; // sliver class, nearly unusable
    } else if small_class >= 5 {
        score -= 2.0; // large residual, bin stays flexible
    }

    // Stream progression: early on, keep bins open and flexible; late, pack tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (post_residual as f64 / bin_capacity as f64) * 4.0;

    // Many open bins with high mean residual: discourage adding to fragmentation.
    if open_bins_count > 3 && (post_residual as f64) < mean_residual {
        score += 1.5;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible.
    if bin_residual == bin_capacity {
        score += 12.0;
        if post_residual >= 60 {
            score -= 4.0; // big item into fresh bin is fine
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // conceivable future item are pure waste -> heavy penalty.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item.max(1) * 1 {
        score += 1000.0;
    }
    // Softer: penalize gaps that cannot fit the lookahead item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0 + 0.5 * post_residual as f64;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Reward leaving room for the lookahead item.
        score -= 10.0;
    }

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // Open-bin pressure: when many bins are open, discourage spreading;
    // prefer consolidating into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (2.0 + 4.0 * progress);

    // Mean residual coupling: prefer bins below mean residual (tighter bins).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate handling: opening a new bin is only attractive when
    // current item is large and no bin fits well; make empty-bin baseline
    // moderately high but not prohibitive.
    if bin_residual == bin_capacity {
        score += 30.0 + 20.0 * progress;
        // Large items keep their value in a fresh bin; small items waste bins.
        score -= 0.2 * item_size as f64;
    }

    // Penalize leaving exactly awkward gaps (e.g., tiny odd residuals).
    if post_residual > 0 && post_residual <= 5 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Exact or near-exact chaining is extremely valuable.
            let chain_waste = (post_residual - next_item_size) as f64;
            score -= 60.0 - 0.6 * chain_waste;
            if post_residual == next_item_size {
                score -= 80.0; // perfect 2-step fill
            }
        } else {
            // Post-residual too small for next item: penalize proportionally
            // to how much dead space is stranded.
            let stranded = post_residual as f64;
            score += 0.5 * stranded;
            // Extra penalty if the stranded space is small (unusable sliver).
            if stranded < 10.0 {
                score += 25.0;
            }
        }
    }

    // Prefer tight fits overall: small post_residual relative to mean residual.
    let pr = post_residual as f64;
    if pr < mean_residual {
        score -= 0.4 * (mean_residual - pr);
    } else {
        score += 0.3 * (pr - mean_residual);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 45.0;
    }

    // Penalize leaving residuals that no typical item (>=1, practically >=10)
    // can use if the stream is mid-way.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if pr > 0.0 && pr < 10.0 {
        score += 30.0 * (1.0 - progress);
    }

    // Mild pressure to consolidate into fewer bins when many are open.
    score -= 0.5 * (open_bins_count as f64).ln().max(0.0);

    // New-bin candidate: make it attractive only when no good chaining exists
    // (empty bin gives full flexibility for the next item).
    if bin_residual == bin_capacity {
        // Baseline cost of a fresh bin; beats poor fits but not chain fits.
        score = 50.0 + 0.1 * (next_item_size as f64);
        if next_item_size > 0 && next_item_size == bin_capacity {
            score -= 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor small post_residual
    let cap = bin_capacity as f64;
    let tight = 1.0 - (post_residual as f64) / cap;
    score -= 1.6 * tight * tight * (item_size as f64);

    // Exact or near-exact fills get a big bonus
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        score -= 18.0;
    }

    // Dead-space penalty: residuals that few future items can use
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 && post_residual < 10 {
        score += 6.0 * (1.0 - progress);
    }

    // Lookahead: reward if next item fits the post-residual (chain packing)
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
            // extra bonus if next item fills almost perfectly too
            let pr2 = post_residual - next_item_size;
            if pr2 < 10 { score -= 8.0; }
        } else {
            // next item won't fit here; penalize wasting a tight bin
            let gap = (next_item_size - post_residual) as f64;
            score += 0.08 * gap;
        }
    } else {
        // last item: just minimize waste
        score += 0.5 * (post_residual as f64);
    }

    // Last-chance bin: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // open bins are fragmented (high mean residual) or item is large
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap - 0.5).max(0.0);
        let pressure = (item_size as f64) / cap;
        let newbin_bonus = 14.0 * fragmentation + 20.0 * pressure * pressure - 18.0 * (1.0 - progress);
        score += newbin_bonus;
        // never open a new bin if an existing bin gives a near-perfect fit
        if item_size >= bin_capacity.saturating_sub(10) {
            score += 30.0;
        }
    }

    // Mild penalty for spreading across too many open bins when residuals are small
    let avg_open = open_bins_count as f64;
    score += 0.02 * avg_open * (mean_residual / cap).max(0.0);

    // Small tie-break noise-free deterministic jitter based on residual structure
    score += (post_residual as f64) * 0.001 * ((step_index % 7) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;
    // smooth polynomial coupling of post_residual with stream progress
    let coupling = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * (1.0 - norm_pr * progress);
    score -= 12.0 * coupling;
    // penalize tight fits when next item could use the leftover
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= 4.0 * (1.0 - (nxt / cap)) * (1.0 - progress);
        } else {
            score += 3.0 * (nxt - pr) / cap;
        }
    }
    // last-chance bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }
    // discourage opening new bins late in stream
    if bin_residual == bin_capacity {
        score += 15.0 * (0.5 + 0.5 * progress) - 0.5 * mean_residual / cap;
    }
    // mild compactness pressure via mean residual
    score += 2.0 * (mean_residual / cap) * (1.0 - progress);
    // non-linear dead-space penalty
    score += 6.0 * (norm_pr * (1.0 - norm_pr)) * progress;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: which "slot family" does the leftover fall into?
    // Residuals in [1,10] are nearly dead space; [11,30] still fit small items; >30 are healthy.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fill — best possible outcome
    } else if pr <= 5 {
        score -= 40.0;
    } else if pr <= 10 {
        score -= 25.0;
    } else if pr <= 20 {
        score -= 10.0;
    } else if pr <= 30 {
        score -= 3.0;
    } else if pr <= 50 {
        score += 5.0;
    } else {
        score += 12.0; // wasteful large leftover
    }

    // Modulo-class penalty: residuals that are multiples of common item sizes (10, 20, 25)
    // are more likely to be exactly filled later, so reward them.
    if pr > 0 {
        if pr % 10 == 0 {
            score -= 8.0;
        }
        if pr % 20 == 0 {
            score -= 4.0;
        }
        if pr % 25 == 0 {
            score -= 4.0;
        }
        if pr % 5 == 0 {
            score -= 2.0;
        }
    }

    // Lookahead coupling: does the next item fit the post-residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 15.0; // chains nicely
            // exact match is golden
            if next_item_size == pr {
                score -= 25.0;
            }
            // harmonic compatibility: next item leaves another usable residue
            let nr = pr - next_item_size;
            if nr % 10 == 0 {
                score -= 5.0;
            }
        } else {
            score += 6.0; // next item won't fit here afterwards
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // rather than opening a new bin — unless the fit is atrocious.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
        if pr <= 10 {
            score -= 15.0; // tight fit in the only candidate is great
        }
    }

    // New-bin candidate handling: an empty bin should only win when the current fit is bad.
    if bin_residual == bin_capacity {
        // opening a new bin: neutral baseline, penalized slightly so we prefer decent fits,
        // but rewarded when no good fit exists.
        score = cap - item_size as f64; // leaves max flexibility = 100 - item
        score += 20.0; // mild preference for existing bins by default
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        }
        if fitting_bins_count == 1 {
            // only one fitting bin; if its post-residual would be tiny, opening may still be worse,
            // so keep the penalty strong.
            score += 10.0;
        }
        if next_item_size > 0 && next_item_size >= item_size && next_item_size > 60 {
            score -= 10.0; // big next item benefits from a fresh large residual
        }
    }

    // Late-stream tightening: as the stream progresses, waste matters more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.3 * progress;

    // Mild pressure against spreading across too many open bins
    score += (open_bins_count as f64).sqrt() * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small for the smallest
    // plausible items are pure waste. Penalize them super-linearly.
    let min_item = 1.0f64;
    if (post_residual as f64) < min_item {
        score += 1000.0; // exact fit -> perfect
    }
    let dead_threshold = 10.0f64.min(bin_capacity as f64 * 0.15);
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 6.0;
    }

    // Reward tight fits: the smaller the post_residual relative to item size,
    // the better the packing density.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= tightness * 25.0;

    // Open-bin pressure: discourage spreading items across many bins
    // unless the fit is genuinely good. New-bin candidate (residual==capacity)
    // gets a base penalty that tight fits can overcome.
    if bin_residual == bin_capacity {
        score += 40.0 + (open_bins_count as f64) * 2.0;
    } else {
        score -= 5.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // reward this placement (chaining good fits).
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap <= 5 {
            score -= 30.0;
        } else if (gap as f64) < dead_threshold {
            score -= 10.0;
        }
    } else if next_item_size > post_residual as u32 && post_residual > 0 {
        // next item cannot use the leftover: leftover becomes dead space
        if (post_residual as f64) < dead_threshold {
            score += 20.0;
        }
    }

    // Mean-residual coupling: when open bins are already loose on average,
    // be pickier about creating more small residuals.
    if post_residual > 0 {
        score += (mean_residual - post_residual as f64).abs() * 0.3;
    }

    // Slight stream-progress tilt: later in the stream, prefer consolidating
    // into existing bins (lower new-bin tendency).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual != bin_capacity {
        score -= progress * 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect or near-perfect fills
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 120.0;
    } else if post_residual <= 10 {
        score -= 60.0;
    }

    // 2-step lookahead: strongly reward bins whose residual can host the next item
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 80.0 - 0.5 * slack; // tighter next-fit is better
            if slack == 0.0 {
                score -= 100.0; // chain of perfect fits
            }
        } else {
            // next item won't fit here; penalize proportionally to overshoot
            let overshoot = (next_item_size - post_residual) as f64;
            score += 0.6 * overshoot;
        }
        // Bonus if next item exactly fills the current bin's residual after this placement
        if next_item_size == post_residual {
            score -= 50.0;
        }
    } else {
        // Last item: pure waste minimization
        score = post_residual as f64;
    }

    // Compare against mean residual across open bins: prefer bins with less residual than average
    score += 0.3 * (mean_residual - bin_residual as f64).max(0.0);
    score -= 0.2 * (bin_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a new bin unless current residuals are all poor fits
    if bin_residual == bin_capacity {
        score += 60.0;
        if next_item_size > 0 && next_item_size <= item_size {
            score += 10.0; // prefer reusing bins when stream shows small items
        }
        // Early in stream, opening bins is cheaper; late in stream, pack tightly
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 40.0 * progress;
        if open_bins_count == 0 {
            score -= 500.0; // must open a bin
        }
    }

    // Penalize leaving dead space that no plausible item (min size 1, typical >=10) can use
    if post_residual > 0 && post_residual < 10 {
        score -= 30.0;
    }

    // Slight preference for bins with lower residual overall (best-fit bias)
    score += 0.1 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize large wasted residual non-linearly (dead space).
    let frac = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * frac * frac;

    // Reward tight fits.
    score -= 15.0 * (item_size as f64 / bin_residual as f64).powi(2);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead coupling: favor bins whose post-residual matches next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            score += 8.0;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Global pressure: when many bins are open relative to stream length, prefer consolidation.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
    score += 0.05 * pressure * (1.0 - progress);

    // Prefer bins with below-mean residual (fill emptier bins less, keep spread usable).
    score += 0.3 * (mean_residual - bin_residual as f64);

    // New-bin candidate: mildly penalize so real fits win, but allow it when fit is awful.
    if bin_residual == bin_capacity {
        score += 12.0 - 10.0 * frac;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Smooth non-linear coupling of post_residual with stream progress:
    // early on, prefer tight fits less aggressively; later, dead space hurts more.
    let progress_weight = 0.5 + 2.5 * progress * progress;
    score += progress_weight * (pr * pr) / cap;

    // Reward near-perfect fits smoothly (post_residual close to 0).
    let fit_quality = 1.0 - (pr / cap);
    score -= 10.0 * fit_quality * fit_quality * fit_quality;

    // Penalize leaving residuals that no plausible next item can use,
    // coupled smoothly with lookahead size.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        let gap = (pr - ni).abs();
        score += 0.05 * gap * gap / cap;
        // Bonus when this placement leaves room almost exactly for the next item.
        let next_fit = 1.0 - (gap / cap);
        score -= 4.0 * next_fit * next_fit;
    } else {
        // Last item: strongly prefer minimizing post_residual.
        score -= 6.0 * (1.0 - pr / cap);
    }

    // Last-chance bin: reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 8.0 + 6.0 * progress;
    }

    // Mild penalty for spreading across many open bins relative to mean residual.
    let mean_gap = (pr - mean_residual).abs();
    score += 0.03 * mean_gap * open_bins_count as f64;

    // New-bin candidate: neutral-ish baseline, penalized slightly more late in stream
    // unless residual is large (i.e., current bins are all poor fits).
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * progress - 0.02 * mean_residual;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits; scale relative residual
    let frac = post_residual as f64 / bin_capacity as f64;
    score += frac * 40.0;

    // Harmonic class of post_residual: residual classes that are "usable"
    // for typical item sizes (1..100) get rewarded.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fill
    } else {
        // Class the residual by integer division into harmonic buckets
        let class = pr / 10; // 0..10 classes
        match class {
            0 => score -= 25.0,           // 1..9: nearly dead but tiny
            1 => score += 5.0,            // 10..19: awkward dead zone
            2 => score -= 10.0,           // 20..29: fits small items
            3 => score += 8.0,            // 30..39: moderately awkward
            4 => score -= 15.0,           // 40..49: very usable
            5 => score += 3.0,
            6 => score -= 12.0,           // 60..69
            7 => score += 2.0,
            8 => score -= 8.0,            // 80..89
            _ => score += 0.0,
        }
        // Modulo coupling: residuals divisible by 5 or 10 pair better
        // with the integer item sizes, slightly reward them.
        if pr % 10 == 0 {
            score -= 6.0;
        } else if pr % 5 == 0 {
            score -= 3.0;
        }
    }

    // Lookahead: if next item fits the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 20.0 + 15.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            score += 10.0; // dead space for the known next item
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 18.0;
    }

    // Prefer fuller bins when many bins are open (contain bin proliferation)
    let pressure = open_bins_count as f64 / (1.0 + total_items as f64 * 0.05);
    score += pressure * 3.0 * frac;

    // Deviation from mean residual: prefer bins that deviate below mean
    // (filling the emptier-than-average bins keeps a set of tight bins)
    score += 0.15 * (mean_residual - bin_residual as f64);

    // New-bin candidate: only attractive when current fit is bad
    // or no good fit exists. Make new bin moderately expensive by default.
    if bin_residual == bin_capacity && item_size > 0 {
        let good_fit_exists = fitting_bins_count > 0 && (bin_capacity - item_size) % 10 == 0;
        let base_new = 55.0;
        let penalty = if fitting_bins_count == 0 {
            -80.0 // must open a new bin
        } else if next_item_size > 0 && next_item_size <= bin_capacity - item_size && next_item_size > mean_residual {
            base_new - 30.0 // fresh bin serves the lookahead well
        } else if good_fit_exists {
            base_new + 20.0
        } else {
            base_new
        };
        score += penalty - frac * 10.0;
    }

    // Mild time modulation: early in stream, be slightly more liberal
    // with tight packing; later, prioritize closing bins out.
    let t = step_index as f64 / (total_items.max(1) as f64);
    score -= 8.0 * (1.0 - t) * (1.0 - frac);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Hard penalty: residuals too small to ever hold a typical item are dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Prefer bins whose leftover can still fit the next item (k=2 lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // Penalize blocking the next item while leaving a tiny gap.
    if next_item_size > post_residual && post_residual > 0 {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, avoid opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.5 + 0.5 * progress);

    // New-bin candidate: make it costly unless current fit is terrible.
    if bin_residual == bin_capacity {
        score += 30.0 + mean_residual * 0.2;
    } else {
        // Reward tight fits (small post_residual relative to bin).
        score -= (bin_capacity - post_residual) as f64 * 0.1;
    }

    // Slight preference toward bins with residuals close to item size (tight packing).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact or near-exact fit (small dead space).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 35.0;
    } else if post_residual <= 15 {
        score -= 15.0;
    }

    // 2-step lookahead: reward when post_residual exactly matches next item size.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // Mild penalty proportional to leftover after hypothetical next placement.
            score += slack * 0.25;
        } else {
            // Next item can't fit here; residual is likely dead space.
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Penalize bins whose residual deviates favorably from mean (keeps diversity),
    // i.e. prefer bins with residual below mean (tighter bins get used first).
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // Penalize opening a new bin, unless existing fits are all poor.
    if bin_residual == bin_capacity {
        let poor_fit_penalty = if next_item_size > 0 && post_residual >= next_item_size { 10.0 } else { 0.0 };
        score += 30.0 + (open_bins_count as f64) * 2.0 - poor_fit_penalty;
        // Early in stream, opening bins is cheaper.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic bonus for small post-residual.
    let tight = (post_residual as f64) / bin_capacity as f64;
    score -= 40.0 * (1.0 - tight) * (1.0 - tight);

    // Perfect fit is extremely attractive.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Dead-space penalty: residual too small for typical future items
    // (items >= 1, but small leftovers below ~15 are hard to reuse).
    if post_residual > 0 && post_residual < 15 {
        score += 20.0 * (15.0 - post_residual as f64);
    }

    // Lookahead coupling: reward if next item fits into post_residual exactly-ish.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; slight penalty scaled by overflow.
            let over = (next_item_size - post_residual) as f64;
            score += 5.0 * over / bin_capacity as f64;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoiding a new bin opening.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Crowding control: when many bins are open, prefer filling existing
    // ones rather than opening more; when few are open, opening is cheaper.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let open_penalty = open_bins_count as f64 * 3.0 * (0.5 + progress);
    score += open_penalty * if bin_residual == bin_capacity { 1.0 } else { 0.0 };

    // New-bin candidate handling: an empty bin is a fallback; make it
    // attractive only when this bin's fit is poor (large post_residual)
    // or when mean residual across open bins is already high.
    if bin_residual == bin_capacity {
        let poor_fit = if post_residual > 40 { 1.0 } else { 0.0 };
        let high_mean = if mean_residual > 45.0 { 1.0 } else { 0.0 };
        score -= 50.0 * poor_fit + 20.0 * high_mean;
        // Early in stream, opening bins is fine.
        score -= 15.0 * (1.0 - progress);
    } else {
        // Prefer bins whose residual deviates favorably from the mean
        // (fill the emptier-than-average bins to consolidate).
        let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
        score += 10.0 * dev;
    }

    // Mild time-horizon modulation: later in the stream, be greedier
    // about tight fits since future opportunities shrink.
    score -= 10.0 * progress * (1.0 - tight);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: prefer minimal post-residual, with smooth non-linear (quadratic) coupling.
    let mut score = pr + 0.015 * pr * pr / cap;

    // Tightness reward: strongly favor near-perfect fills (smooth exponential term).
    let tightness = 1.0 - pr / cap;
    score -= 8.0 * tightness * tightness * tightness;

    // Lookahead coupling: penalize post-residual that is just barely too small
    // for the next item (dead space), reward residuals that can host it.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = pr - nxt;
        if gap >= 0.0 {
            // next item fits into this bin's future residual: reward, more so later in stream.
            score -= 2.0 + 3.0 * progress;
        } else {
            // smooth penalty for wasted residual that cannot host the next item,
            // peaking when gap is small (nearly usable -> worst dead space).
            let near_miss = (1.0 + gap / nxt).max(0.0);
            score += 3.0 * near_miss * (1.0 - near_miss) * 4.0 * (0.5 + progress);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 6.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the
    // item fits poorly everywhere (large post_residual would remain anyway) or
    // late in the stream when consolidation matters less.
    if bin_residual == bin_capacity {
        let penalty = 10.0 + 12.0 * (1.0 - progress) + 0.05 * open_bins_count as f64;
        score += penalty;
        // If item is large relative to capacity, a fresh bin is less wasteful.
        score -= 6.0 * (item_size as f64 / cap);
    }

    // Mild preference for filling bins below mean residual (balance avoidance of
    // many half-empty bins): smooth coupling with mean_residual.
    let mean_norm = mean_residual / cap;
    let post_norm = pr / cap;
    score += 2.0 * (post_norm - mean_norm) * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // New-bin candidate: penalize opening a bin unless it is genuinely needed
    if bin_residual == bin_capacity {
        score += 60.0 + 0.25 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 200.0; // no open bin fits: opening is mandatory
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: reward if next item fits in the post residual
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 + 0.1 * next_item_size as f64;
        } else {
            // dead space for next item: penalize proportionally to wasted fraction
            let waste = (next_item_size - post_residual) as f64;
            score += 0.3 * waste;
        }
    }

    // Harmonic class logic on post_residual: residues near 0 are "clean" states
    let r = post_residual % 10;
    score += match r {
        0 => -6.0,
        1 | 9 => -2.0,
        2 | 8 => 0.0,
        3 | 7 => 1.5,
        4 | 6 => 3.0,
        _ => 4.5, // residue 5: half-capacity ambiguity, mild penalty
    };

    // Integer-division thresholds: tiny residuals are near-perfect packing
    if post_residual <= bin_capacity / 10 {
        score -= 10.0;
    } else if post_residual <= bin_capacity / 4 {
        score -= 4.0;
    } else if post_residual > bin_capacity * 3 / 4 {
        // large residual after placement means item was small in a big bin
        score += 5.0;
    }

    // Mean residual coupling: prefer bins whose residual is below mean (tighter bins)
    score += (post_residual as f64 - mean_residual) * 0.15;

    // Late-stream tightening: conserve open bins as stream progresses
    score += 6.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftover gaps are worthless.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // unusable dead space
    } else if post_residual == 0 {
        score -= 40.0; // perfect closure is excellent
    } else if post_residual < 20 {
        score += 12.0; // likely dead space given min item size 1..100
    }

    // Reward tight fits (item fills a large share of the residual).
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 25.0 * fill_ratio * fill_ratio;

    // Pressure from many open bins: prefer packing existing bins tighter
    // instead of spreading across bins.
    score += 2.0 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Lookahead: if the next item fits exactly in the post residual, strong reward.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 18.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            score += 8.0; // next item can't use this bin's leftover
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoiding a new bin opening.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: only attractive when current bins fit poorly.
    if bin_residual == bin_capacity {
        score = 55.0 + 3.0 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 100.0; // nothing fits elsewhere: new bin is correct
        } else if fitting_bins_count == 1 {
            score += 40.0; // avoid stealing the last-chance bin
        }
        if post_residual as f64 > mean_residual {
            score += 10.0;
        }
    }

    // Mild late-stream tightening: as stream progresses, waste matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Deviation from mean residual: prefer bins whose residual is close to item need.
    score += 0.15 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits
    score += (post_residual as f64 / bin_capacity as f64) * 20.0;

    // Aggressive 2-step lookahead: reward if next item exactly fills post_residual
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - gap / bin_capacity as f64);
            // Perfect chain: next item fills bin completely
            if post_residual == next_item_size {
                score -= 40.0;
            }
        } else {
            // Next item cannot use this bin's leftover: penalize dead space
            let dead = (post_residual as f64) / bin_capacity as f64;
            score += 25.0 * dead * dead;
        }
    } else {
        // Last item: prefer minimal post residual
        score -= 15.0;
    }

    // Relative to mean residual: bins tighter than average are good targets
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Penalize opening new bins when decent open bins exist
    if bin_residual == bin_capacity {
        score += 10.0 + 2.0 * open_bins_count as f64;
    }

    // Late in stream: consolidate aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squaring post_residual punishes wasteful placements.
    score += (post_residual as f64 / bin_capacity as f64).powi(2) * 20.0;

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if the next item fits exactly/roughly in post_residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; mildly penalize leaving large unusable gaps.
            score += (post_residual as f64) * 0.05;
        }
    }

    // Penalize opening a new bin when open bins already fit reasonably well.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Only open a new bin if existing residuals are poor fits (large post_residual everywhere).
            let best_possible = post_residual.min(bin_residual.saturating_sub(item_size)) as f64;
            score += 8.0 + mean_residual * 0.03;
            let _ = best_possible;
        } else {
            score -= 5.0; // no alternative: new bin is fine
        }
    }

    // Global state coupling: many open bins with high mean residual -> prefer filling existing bins.
    if open_bins_count > 2 {
        score += (mean_residual - post_residual as f64) * 0.02;
    }

    // Time horizon: late in the stream, consolidation matters more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Non-linear waste penalty: quadratic coupling of post_residual with progress.
    score += 0.9 * (post / cap) * (post / cap) * cap * (0.5 + progress);

    // Reward tight fits (small post_residual) more strongly as stream advances.
    score -= 12.0 * (1.0 - post / cap) * (1.0 - post / cap) * (0.4 + 0.6 * progress);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0 * (1.0 + progress);
    }

    // New-bin candidate: prefer opening fresh bins early, penalize later
    // unless the current fit would be very poor.
    if bin_residual == bin_capacity {
        let fit_quality = 1.0 - post / cap;
        score += 10.0 * progress - 8.0 * fit_quality * fit_quality;
        score += 2.0 * (open_bins_count as f64).ln().max(0.0);
    }

    // Lookahead coupling: penalize leaving a residual that cannot hold the
    // next item but is close to it (dead space), reward residuals that can.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post >= nx {
            score -= 6.0 * (nx / cap) * (1.0 - post / cap);
        } else {
            score += 5.0 * (nx - post) / cap * (0.5 + progress);
        }
    }

    // Mild coupling with mean residual: prefer bins deviating below the mean
    // (closing out small-residual bins first).
    score += 0.05 * (mean_residual - post).max(-50.0).min(50.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: classify leftover into usable bands.
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / c; // capacity fraction of leftover

    // Items sized 1..100; leftover classes via integer division thresholds.
    // Small leftovers (<10) are nearly dead space; penalize strongly.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Modulo arithmetic: leftover divisible by common item sizes is reusable.
    if post_residual >= 10 {
        if post_residual % 10 == 0 {
            score -= 12.0; // decade-aligned leftover, easy to refill
        }
        if post_residual % 25 == 0 {
            score -= 8.0;
        }
        if post_residual % 50 == 0 {
            score -= 6.0;
        }
    }

    // Lookahead coupling: does next item fit into this leftover?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // slack after also placing next item
            let slack2 = post_residual - next_item_size;
            score -= 10.0 + (slack2 as f64).min(20.0) * 0.4;
            if next_item_size == post_residual {
                score -= 25.0; // exact two-item chain
            }
        } else {
            // next item won't fit here; mildly penalize large stranded leftovers
            score += (frac * 30.0).min(25.0);
        }
    }

    // Last-chance bonus: only one bin fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin residual == capacity.
    if bin_residual == bin_capacity {
        // Prefer new bin when open bins are crowded (mean residual low)
        // or item is large; discourage when many open bins have room.
        let crowding = (mean_residual / c).clamp(0.0, 1.0);
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 20.0 + 40.0 * crowding - 10.0 * progress
            + if item_size > bin_capacity / 2 { -15.0 } else { 0.0 };
        if fitting_bins_count == 1 {
            score += 50.0; // don't open a bin if it's the last chance elsewhere
        }
    }

    // Tie-break: prefer bins with residual closest to item (tight fit)
    score += ((bin_residual - item_size) as f64 / c) * 5.0;

    // Slight preference to keep fewer bins open early on.
    score += open_bins_count as f64 * 0.05 * (1.0 - step_index as f64 / (total_items.max(1) as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size are unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // tiny unusable gap -> heavy penalty
    }
    // Penalize gaps too small for the lookahead item but nonzero.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0;
    }
    // Reward perfect and near-perfect fits.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 10 {
        score -= 20.0;
    }
    // Reward when this bin's residual exactly matches next item (pre-pack lookahead).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0;
    }

    // Last chance: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Open-bin pressure: discourage opening new bins when many bins are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure from open bins and progress.
        score = 100.0 + 8.0 * open_bins_count as f64 + 40.0 * progress;
        // If no open bin fits at all, opening a new bin is acceptable.
        if fitting_bins_count == 0 {
            score -= 90.0;
        }
    } else {
        // Slight preference for bins with larger residual (fill emptier bins first)
        // to consolidate waste, but only mildly so dead-space rule dominates.
        score -= 0.05 * bin_residual as f64;
        // Slight penalty for spreading across many bins.
        score += 0.5 * open_bins_count as f64;
    }

    // Mean-residual coupling: if bin residual is far below mean, penalize (fragmentation).
    let diff = mean_residual - bin_residual as f64;
    score += 0.3 * diff.max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

