    if next_item_size > 0 {
        let nr = next_item_size as f64;
        let pr = post_residual as f64;
        if pr >= nr {
            let gap = pr - nr;
            // Perfect chaining: next item exactly fills remaining space
            if gap == 0.0 {
                score -= 60.0;
            } else {
                // Reward proportional to how small the leftover after the lookahead placement would be
                score -= (1.0 - gap / 100.0) * 25.0;
                // Extra bonus if lookahead leaves a very small unusable sliver
                if gap < 10.0 {
                    score -= 15.0;
                }
            }
        } else {
            // Next item does NOT fit in post-residual: penalize wasted large residuals
            let waste = pr / 100.0;
            score += waste * 20.0;
        }
    }

    // Relative-to-mean coupling: bins with residual far below mean are "tight" -> prefer filling them
    let dev = post_residual as f64 - mean_residual;
    if dev < 0.0 {
        score += dev * 0.4; // negative deviation lowers score -> favors tight bins
    } else {
        score += dev * 0.15; // mild penalty for looser-than-average bins
    }

    // Last-chance bin: strongly favor using the only bin that fits to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Penalize opening a new bin when open bins already fit reasonably well
    if bin_residual == bin_capacity {
        // New-bin candidate: base penalty so it only wins when fits are terrible
        score += 35.0;
        // But if the item is large and lookahead suggests a fresh bin chains well, soften
        if next_item_size > 0 && (bin_capacity as f64 - item_size as f64 - next_item_size as f64).abs() < 5.0 {
            score -= 40.0;
        }
        // Fewer open bins -> cheaper to open new bin
        if open_bins_count <= 2 {
            score -= 10.0;
        }
    }

    // Progress-aware pressure: late in the stream, be more conservative with new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 15.0;
    }

    // Dead-space penalty: residual that can never fit a typical small item (min size 1..10)
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: quadratic penalty on wasted space relative to capacity.
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    score += 8.0 * waste_ratio * waste_ratio * (bin_capacity as f64);

    // Perfect fit is excellent.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits in the post residual, reward this bin strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.15 * (next_item_size as f64);
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Dead space that the next item cannot use: penalize.
        score += 0.25 * (post_residual as f64);
    }

    // Last chance: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // Penalize opening a brand-new bin when decent alternatives exist.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 + 10.0 * (1.0 - progress);
        // But if the new bin would fit both this item and the next one, it's attractive.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 14.0;
        }
        // If mean residual across open bins is small (all bins nearly full),
        // opening a new bin is natural: soften the penalty.
        score -= (mean_residual / 10.0).min(15.0);
    }

    // Mild pressure to consolidate: prefer bins with below-mean residual
    // (filling emptier bins first keeps tighter bins available).
    if bin_residual != bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        score += 0.05 * diff;
    }

    // Slight preference for bins with larger residual when many bins are open
    // (reduce bin count by emptying the fullest-capable bins).
    score += 0.03 * (open_bins_count as f64) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * progress;
    score += 30.0 * poly;

    // Reward tight fits more strongly as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * (10.0 + 40.0 * progress);

    // Penalize dead space below next item's need
    if next_item_size > 0 {
        let gap = next_item_size as f64 - pr;
        if gap > 0.0 {
            score += gap * (1.0 + progress);
        } else {
            // next item fits in residual: reward
            score -= 8.0 * (1.0 - gap / cap);
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress);
    }

    // Mild penalty for spreading across too many bins relative to mean residual
    score += 0.05 * (open_bins_count as f64) * (mean_residual - pr).abs() / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which "slot band" it lands in.
    // Residuals are classified by integer division into bands of size 10.
    let band = (post_residual / 10) as f64;
    // Harmonic penalty: perfect-fitting residuals (0) are gold; tiny residuals (1..5)
    // are dead space; residuals that are multiples of 10 are reusable by small items.
    if post_residual == 0 {
        score -= 60.0; // perfect fit: strongly reward
    } else if post_residual <= 5 {
        score += 40.0; // dead space penalty
    } else if post_residual % 10 == 0 {
        score -= 15.0; // clean multiple of 10: likely reusable
    } else if post_residual % 5 == 0 {
        score -= 5.0; // half-harmonic residual
    } else {
        score += (post_residual % 10) as f64; // ragged remainder penalty
    }

    // Reward filling bins tightly: fraction of bin consumed by this item.
    let fill_frac = item_size as f64 / cap_f;
    score -= 25.0 * fill_frac;

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size <= post_residual {
            // harmonic class match: next item divides post_residual nicely
            if post_residual % next_item_size == 0 {
                score -= 20.0;
            } else {
                score -= 8.0;
            }
        } else {
            // next item won't fit here; penalize leaving large unusable gaps
            score += 10.0 * (1.0 - (post_residual as f64 / cap_f));
        }
    } else {
        // last item: prefer tightest fit overall
        score -= 10.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin should only win when fits are bad.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 45.0;
        // Cheaper to open a new bin early in the stream (plenty of future items
        // to fill it) and when many bins are already open (fragmentation).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * (1.0 - progress);
        score += 0.5 * (open_bins_count as f64).min(20.0);
        // If current bin leaves a ragged residual and next item is large,
        // opening a fresh bin is attractive.
        if next_item_size > post_residual && post_residual > 0 && post_residual < 20 {
            score -= 25.0;
        }
    }

    // Mild preference for bins whose residual is close to the item (tight fit)
    let tightness = (bin_residual - item_size) as f64 / cap_f;
    score += 10.0 * tightness * tightness;

    // Mean-residual coupling: if this bin is far below mean residual, it is
    // "leftover-ish"; prefer placing into above-mean bins to consolidate.
    let dev = mean_residual - bin_residual as f64;
    score += 0.3 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual is the primary driver.
    // Penalize small unusable gaps heavily (dead space zone: 1..=10).
    if post_residual > 0 && post_residual <= 10 {
        score += 45.0 - 3.0 * post_residual as f64; // smaller gap => worse
    } else if post_residual == 0 {
        // Perfect fit is highly desirable: strong reward.
        score -= 60.0;
    } else if post_residual >= 11 && post_residual <= 20 {
        // Moderately awkward zone, but still potentially usable.
        score += 8.0;
    }

    // Reward leaving a gap that exactly fits the lookahead item (k=2 lookahead).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual > next_item_size {
            // Gap can still hold the next item: mildly good.
            score -= 6.0;
        } else if post_residual > 0 {
            // Gap cannot hold next item: dead space relative to lookahead.
            score += 12.0;
        }
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: more open bins => discourage spreading, prefer
    // consolidating into existing bins; but soften when many bins exist.
    let ob = open_bins_count as f64;
    score += 0.6 * ob * (1.0 - (item_size as f64 / bin_capacity as f64));

    // Mean residual coupling: prefer bins with residual close to the mean
    // (balanced packing); penalize outliers that hoard large residuals.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.25 * dev;

    // Progress-aware scaling: early in stream, be more conservative about
    // tight fits (distribution unknown); later, exploit tighter fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.15 * progress;

    // New-bin candidate: only attractive when no open bin fits well
    // (fitting_bins_count == 0 handled implicitly) or fit would be awful.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin: keep it moderately high so we
        // only open when existing fits create dead space.
        score += 55.0 + 1.5 * ob;
        // If the item would leave a large usable residual in the new bin,
        // slightly reduce the penalty (a fresh bin is versatile).
        if post_residual >= 20 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer exact/near-exact fills.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 10 {
        score -= 200.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let tight = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= 150.0 * tight;
    } else if next_item_size > 0 {
        // Penalize dead space the next item cannot use.
        score += 0.5 * post_residual as f64;
    }

    // Relative to mean residual: prefer bins tighter than average.
    score += (post_residual as f64 - mean_residual) * 0.8;

    // Last-chance bin: avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: only attractive when current fit is terrible.
    if bin_residual == bin_capacity {
        let bad_fit = if next_item_size > 0 && post_residual < next_item_size { 1.0 } else { 0.0 };
        score += 80.0 - 90.0 * bad_fit;
    }

    // Early in stream, be more conservative with new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 30.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) especially when item is large
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 8.0;

    // Penalize creating dead space that is too small to be useful later
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    // Lookahead: if next item fits exactly in post_residual, strongly reward
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = post_residual - next_item_size;
        score -= 10.0 - slack as f64 * 0.15;
    }
    // If next item won't fit here anyway, mild penalty for wasting the lookahead option
    if next_item_size > 0 && next_item_size > post_residual {
        score += 2.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 12.0;
    } else {
        score += (fitting_bins_count as f64 - 1.0) * 0.8;
    }

    // Global state coupling: many open bins with low mean residual -> prefer filling existing bins
    let mean_res_ratio = mean_residual / bin_capacity as f64;
    if mean_res_ratio < 0.2 && open_bins_count > 2 {
        score -= 4.0 * (0.2 - mean_res_ratio);
    }

    // Prefer bins whose residual is close to item size (near-perfect packing)
    let fit_gap = (bin_residual as f64 - item_size as f64).abs();
    score += fit_gap * 0.05;

    // Time horizon: early in stream, be more exploratory (favor new bins slightly);
    // late in stream, consolidate into existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New bin candidate: penalize more as stream progresses
        score += 3.0 + progress * 10.0 - fill_ratio * 2.0;
    } else {
        score -= progress * 2.0;
    }

    // Mild penalty for using very empty open bins when item is small (save them for large items)
    if item_size < 30 && bin_residual > 70 && bin_residual < bin_capacity {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: post_residual scaled non-linearly (quadratic waste growth).
    let pr = post_residual as f64;
    let mut score = pr + 0.9 * (pr * pr) / cap;

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = 1.0 - pr / cap;
    score -= 12.0 * tightness * tightness * tightness;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0 + 6.0 * progress;
    }

    // New-bin candidate: penalize opening a bin when open bins exist and fit,
    // unless residual fragmentation is high (mean_residual low -> waste).
    if bin_residual == bin_capacity {
        let fragmentation = 1.0 - (mean_residual / cap);
        score += 10.0 + 8.0 * (1.0 - progress);
        score -= 6.0 * fragmentation;
        // If next item is large and mean residual is small, opening new bin is fine.
        if next_item_size as f64 > mean_residual {
            score -= 7.0;
        }
    } else {
        // Lookahead: bonus if next item fits into post_residual (chain packing).
        if next_item_size > 0 && (next_item_size as f64) <= pr {
            score -= 5.0 * (1.0 - pr / cap) + 3.0 * progress;
        } else if next_item_size > 0 {
            // Penalize leaving residual that no plausible next item uses.
            score += 2.0 * (pr / cap);
        }
    }

    // Mild penalty for spreading across many open bins late in the stream.
    score += 0.05 * open_bins_count as f64 * progress;

    // Smooth stream-progress coupling: prefer consolidating early, tightening late.
    score -= 4.0 * progress * (1.0 - pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: perfect fits (0) and residuals
    // that exactly accommodate common small-item sizes (10, 20, 25, 50) are gold.
    if post_residual == 0 {
        score -= 1000.0; // perfect fit, always take it
    } else {
        let pr = post_residual;
        // Class A: residual is an exact multiple of small item sizes
        if pr % 10 == 0 { score -= 12.0; }
        if pr % 20 == 0 { score -= 6.0; }
        if pr % 25 == 0 { score -= 5.0; }
        if pr % 50 == 0 { score -= 4.0; }
        // Class B: dead-space penalty for awkward residuals (prime-like / odd)
        if pr % 10 != 0 { score += 8.0; }
        if pr < 10 { score += 25.0; } // unusable sliver
        // Class C: lookahead coupling — can next item exactly fill residual?
        if next_item_size > 0 {
            if next_item_size == pr {
                score -= 60.0; // next item completes this bin perfectly
            } else if pr >= next_item_size {
                score -= 5.0;
                let rem2 = pr - next_item_size;
                if rem2 % 10 == 0 { score -= 6.0; }
                if rem2 == 0 { score -= 30.0; }
            } else {
                score += 10.0; // next item cannot use this bin anyway
            }
        }
    }

    // Last-chance bin: strongly prefer using the single fitting bin
    // rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    // or open-bin pool is getting fragmented.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 - 15.0; // baseline for fresh bin
        if fitting_bins_count == 0 { score -= 20.0; }
        if fitting_bins_count == 1 { score += 30.0; } // don't abandon the last chance bin
        if open_bins_count > 0 && mean_residual > (item_size as f64 + 15.0) {
            score += 25.0; // open bins have plenty of room; don't open new
        }
        if step_index as f64 / total_items.max(1) as f64 > 0.9 && open_bins_count > 3 {
            score += 10.0; // late stream: consolidate
        }
    }

    // Mild preference to fill fuller bins (small residual before placement)
    score += (bin_capacity - bin_residual) as f64 * -0.05;

    // Tie-break by mean residual alignment: bins far from mean get slight penalty
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.02;

    // Progress-based tightness: as stream advances, favor tighter packing
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold the smallest
    // plausible item (1..100 interface => treat < 8 as dead) are heavily penalized.
    let dead_threshold = 8.0f64;
    if (post_residual as f64) < dead_threshold {
        score += 40.0 * (dead_threshold - post_residual as f64);
    }

    // Non-linear waste curve: quadratic penalty on unusable gap size.
    score += 0.02 * (post_residual as f64).powi(2);

    // Reward tight fits strongly (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Open-bin pressure: discourage spreading across many bins; prefer filling
    // existing bins when several are open, but allow new bins early in stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 1.5 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Mean-residual coupling: bins far below mean residual are poor choices
    // unless they fit tightly; penalize deviation from mean.
    score += 0.3 * ((bin_residual as f64 - mean_residual).abs());

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // post_residual too small for next item: penalize proportionally
            score += 8.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when all open bins fit poorly.
    if bin_residual == bin_capacity {
        let base = 15.0 + 2.0 * open_bins_count as f64;
        // If item leaves a large unusable gap in existing bins, new bin looks good.
        if post_residual == bin_capacity - item_size {
            score = base + (bin_capacity - item_size) as f64 * 0.1;
            if fitting_bins_count == 0 { score -= 20.0; }
        } else {
            score = base;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits: low post_residual is good.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 40.0 * (1.0 - fit_ratio) * (1.0 - fit_ratio);

    // 2-step lookahead: if next item exactly fills post_residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 60.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Next item fits here: mild reward proportional to how snugly.
        let slack_after_next = post_residual - next_item_size;
        score -= 25.0 * (1.0 - slack_after_next as f64 / bin_capacity as f64);
    } else if next_item_size > post_residual {
        // Next item would NOT fit: penalize leaving a gap that blocks it.
        score += 10.0 + (next_item_size - post_residual) as f64 * 0.3;
    }

    // Reward residuals that are close to mean_residual (keeps bins homogeneous).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Penalize opening a new bin when plenty of open bins could fit the item.
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * fitting_bins_count as f64;
        // But if next item is large and no open bin will hold both, opening is fine.
        if next_item_size > 0 && next_item_size + item_size > bin_capacity {
            score -= 20.0;
        }
    }

    // Late in stream: consolidate, avoid new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score -= 8.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 500.0;
    }

    // Tightness: reward small post-residual relative to capacity
    let tight = post_residual as f64 / bin_capacity as f64;
    score += tight * tight * 120.0;

    // Lookahead coupling: penalize if next item fits post-residual well (save that space)
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let waste = (post_residual - next_item_size) as f64;
            score += 0.5 * waste + 30.0;
        } else {
            // post-residual too small for next item: dead space unless tiny
            if post_residual > 0 && post_residual < 10 {
                score -= 40.0; // negligible crumb, fine to use
            }
        }
    }

    // Last chance bin: strong reward to use it instead of opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        // Prefer opening a new bin only if no good fit exists among open bins
        // i.e. if current item leaves bad residual in existing bins anyway
        let spread = (mean_residual - post_residual as f64).abs();
        score = 60.0 + spread * 0.3;
        if post_residual == 0 {
            score -= 1000.0; // never open new bin if an open bin fits perfectly
        }
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 25.0; // fresh bin can host the next item too
        }
        if fitting_bins_count <= 1 {
            score -= 200.0; // poor alternatives: new bin attractive
        }
    }

    // Global state: many open bins -> discourage spreading, encourage filling
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.6 * (1.0 - progress);

    // Deviation from mean residual: prefer bins whose residual is larger than mean
    // (consolidate space into emptier bins)
    if bin_residual < bin_capacity {
        let dev = bin_residual as f64 - mean_residual;
        score += dev * 0.4;
    }

    // Late-stream: prioritize closing bins tightly
    score += tight * progress * 200.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let residual = bin_residual as f64;
    let item = item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Base: prefer minimizing post_residual (tight fit), normalized
    let x = post / cap;
    let mut score = 100.0 * x * x;

    // Smooth non-linear coupling: post_residual interacts with stream progress
    // Later in the stream, tight fits matter more (waste compounds).
    score += 40.0 * x * x * (progress * progress);

    // Reward filling bins deeply relative to current mean residual state
    let fill_ratio = item / cap;
    score -= 25.0 * fill_ratio * (1.0 - progress);

    // Penalize bins whose residual deviates from mean residual (fragmentation)
    let dev = (residual - mean_residual) / cap;
    score += 15.0 * dev * dev * (1.0 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 50.0;
    }

    // Lookahead coupling: smooth interaction between post_residual and next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post - nxt) / cap;
        // If next item fits exactly in post_residual, reward strongly (smooth quadratic)
        score -= 30.0 * (-gap * gap);
        // Penalize leaving post_residual just barely too small for next item
        score += 10.0 * (1.0 - gap.signum()) * gap.abs() * gap.abs();
    }

    // Mild penalty for opening new bins late in the stream
    if bin_residual == bin_capacity {
        score += 20.0 + 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: tight fit preference (best-fit core)
    score -= (item_size as f64 / bin_capacity as f64) * 20.0;

    // Harmonic class: reward post_residual that is "usable" (large enough chunks)
    // Classify post_residual into harmonic buckets via integer division on 10
    let pr = post_residual;
    let class = pr / 10; // harmonic class 0..10
    match class {
        0 => score -= 60.0,            // near-perfect fit: dead space < 10
        1 => score -= 25.0,            // small but often usable
        2 => score -= 15.0,
        3 => score -= 8.0,
        4 => score += 5.0,
        5 => score -= 12.0,            // ~50 residual: fits half-capacity items
        6 => score += 3.0,
        7 => score += 6.0,
        8 => score += 9.0,
        9 => score += 12.0,
        _ => {}                        // class 10 = empty/new bin
    }

    // Modulo coupling: post_residual divisible by 10 aligns with common item sizes
    if pr % 10 == 0 && pr > 0 {
        score -= 10.0;
    }

    // Lookahead: if next item fits exactly into post_residual, strongly reward
    if next_item_size > 0 && next_item_size <= pr {
        let slack = (pr - next_item_size) as f64;
        score -= 18.0 * (1.0 - slack / bin_capacity as f64);
        if pr == next_item_size {
            score -= 25.0; // perfect chain
        }
    } else if next_item_size > pr {
        // next item cannot use the leftover; penalize proportionally to waste
        score += 8.0 * (next_item_size as f64 - pr as f64) / 10.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // among many fitting bins, prefer tighter ones (already via post_residual)
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate handling: only open a new bin when no open bin offers
    // a decent harmonic fit (post_residual large = poor fit)
    if bin_residual == bin_capacity {
        // neutral baseline for a fresh bin
        score = (bin_capacity - item_size) as f64;
        // penalize opening new bins when the stream is early or bins are few
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 * (1.0 - progress);
        if open_bins_count == 0 {
            score -= 100.0; // must open the first bin
        }
        // if item is large, new bin leaves a predictable large residual
        if item_size >= 50 {
            score -= 10.0;
        }
    }

    // Mild preference to balance residual mass across bins
    score += 0.05 * (mean_residual - post_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold any
    // future item are pure waste -> quadratic penalty on unusable gaps.
    let dead = post_residual > 0 && post_residual < 10;
    if dead {
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 120.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Reward tight fill relative to capacity (fractional waste term).
    score -= (item_size as f64 / bin_capacity as f64) * 25.0;

    // Open-bin pressure: when many bins are open, discourage opening new ones
    // and favor consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (1.5 + progress * 2.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are already open.
        score += 20.0 + pressure;
    } else {
        score -= pressure * 0.15;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Lookahead: if the next item fits the post-residual exactly-ish, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack <= 5.0 {
            score -= 30.0;
        } else {
            score -= 10.0 * (1.0 - slack / bin_capacity as f64);
        }
    }

    // Prefer bins whose residual is below the mean (tighter bins close out faster).
    if bin_residual != bin_capacity {
        let dev = mean_residual - bin_residual as f64;
        score += dev * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        score -= 500.0 / post_residual as f64;
    }

    // 2-step lookahead: reward if next item fits into post_residual (chained packing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size < post_residual {
            let chain_residual = post_residual - next_item_size;
            score -= 150.0 / (chain_residual as f64 + 1.0);
        } else {
            // Next item won't fit here; penalize leaving medium dead space.
            score += (post_residual as f64 - mean_residual).abs() * 0.5;
        }
    }

    // Relative-to-mean fit quality: prefer bins whose post_residual stays near/below mean residual.
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * 2.0;
    } else {
        score -= mean_residual - post_residual as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are genuinely poor fits.
    if bin_residual == bin_capacity {
        score += 80.0;
        if fitting_bins_count > 0 {
            score += 120.0 * (fitting_bins_count as f64).ln() + 1.0;
        }
        // Early in stream, allow opening bins more freely.
        if total_items > 0 {
            let progress = step_index as f64 / total_items as f64;
            score -= 60.0 * (1.0 - progress);
        }
    }

    // Mild penalty for spreading across many open bins late in the stream.
    score += open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual) with a nonlinear term.
    let tightness = (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64;
    score -= 30.0 * tightness * tightness;

    // Penalize dead space: residuals too small to be useful for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Lookahead: reward bins whose post_residual can still host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            score += 6.0;
        }
        // Perfect chain: post_residual exactly matches next item.
        if post_residual == next_item_size {
            score -= 20.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let fit_quality = if fitting_bins_count == 0 { 1.0 } else { (post_residual as f64).min(100.0) / 100.0 };
        // Penalize opening new bins more when many bins are open (consolidate),
        // less when few bins are open or early in the stream.
        score += 55.0
            - 15.0 * progress
            - 2.0 * (open_bins_count as f64).ln().max(0.0)
            + 35.0 * (1.0 - fit_quality);
        // If an open bin fits and leaves a usable residual, discourage new bin.
        if fitting_bins_count >= 1 {
            score += 30.0;
        }
    } else {
        // Mild preference for filling bins that are already relatively full.
        let fill = 1.0 - bin_residual as f64 / bin_capacity as f64;
        score -= 10.0 * fill;
        // Prefer bins with residuals below the mean (consolidate emptier space usage).
        score += 0.05 * (mean_residual - bin_residual as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Non-linear tightness reward: quadratic+quartic decay of residual value,
    // strengthened as the stream progresses (late residual is more likely dead space).
    let tight = 1.0 - (post / cap).powi(2);
    score -= 12.0 * tight * (0.5 + progress);

    // Reward when the lookahead item fits exactly-ish in the post residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let slack = (post - nxt) / cap;
            score -= 8.0 * (1.0 - slack * slack);
        } else {
            // Penalize residuals that are too small for the next item (dead space risk).
            score += 4.0 * (1.0 - nxt / post.max(1.0)) * (0.5 + progress);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 6.0 * (1.0 - progress * 0.5);
    }

    // Mild penalty when this bin's residual is far from the mean (imbalance),
    // interacting smoothly with open bin count.
    let dev = (post - mean_residual) / cap;
    score += 3.0 * dev * dev * (1.0 + (open_bins_count as f64).ln().max(0.0));

    // Slight preference for filling existing bins over opening new ones,
    // growing smoothly with stream progress.
    if bin_residual < bin_capacity {
        score -= 2.0 * progress;
    } else {
        // New-bin candidate: penalize unless residual after placement is small.
        score += 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class: which "resonance band" does the post residual fall into?
    // Small residuals that are unusable by typical items are dead space -> penalize.
    let harmonic = post_residual % 10;
    let class = post_residual / 10;

    // Dead-space penalty: residual in 1..10 is nearly unusable (items >= 10... but sizes 1..100 possible)
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }
    // Modulo coupling: residuals that pair badly with next item get extra penalty
    if next_item_size > 0 {
        if next_item_size > post_residual {
            // next item can't use this bin's leftover; weight dead space by gap
            score += 0.3 * ((next_item_size - post_residual) as f64).min(40.0);
        } else {
            // next item fits nicely: reward tight two-item packing
            score -= 6.0;
            let pair_waste = post_residual - next_item_size;
            score += 0.2 * pair_waste as f64;
        }
        // harmonic alignment: next item leaves a multiple-of-10 residual
        if next_item_size <= post_residual && (post_residual - next_item_size) % 10 == 0 {
            score -= 4.0;
        }
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Integer-division thresholds on post_residual: penalize mid-range unusable bands
    if class == 1 && harmonic >= 1 {
        score += 3.0; // residual 11..20 often wasted
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // penalize opening new bins unless current bins are fragmented or early stream
        score += 25.0 + 40.0 * pressure - 20.0 * progress;
        if fitting_bins_count == 0 {
            score -= 60.0; // must open a new bin
        }
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 10.0; // big next item: fresh bin is useful
        }
    }

    // Prefer filling bins that are already low on space (compact placement)
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 8.0 * fill_ratio;

    // Many open bins: prefer tighter packing to consolidate
    score += 0.15 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 12.0;
    }
    // Perfect fit is strongly rewarded.
    if post_residual == 0 {
        score -= 150.0;
    }

    // Reward using bins whose residual is close to the item (tight packing).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += tightness * 30.0;

    // Pressure from number of open bins: prefer existing bins when many are open.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: make it attractive only if the item fits poorly
    // everywhere (large item, few fitting bins, high mean residual waste).
    if bin_residual == bin_capacity {
        let waste_estimate = (bin_capacity - item_size) as f64;
        if fitting_bins_count == 0 {
            score -= 200.0; // no alternative: must open new bin
        } else if waste_estimate > mean_residual * 1.2 {
            score -= 10.0; // fresh bin leaves more usable space
        } else {
            score += 60.0; // discourage opening new bins unnecessarily
        }
    }

    // Lookahead: avoid leaving a gap that exactly blocks the next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.8;
    } else if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0; // gap perfectly hosts next item
    }

    // Late in the stream, consolidate harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0 * (mean_residual / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fit via post_residual, but discount residual slightly
    score = post_residual as f64 * 1.0;

    // Aggressive 2-step lookahead: reward exact match of next item into post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect 2-chain
        } else if post_residual > next_item_size {
            let leftover = (post_residual - next_item_size) as f64;
            score -= 40.0 * (1.0 - leftover / bin_capacity as f64);
        } else {
            // next item won't fit here: penalize wasting space that could have helped
            let gap = (next_item_size - post_residual) as f64;
            score += 0.15 * gap;
        }
    }

    // Compare post_residual against mean residual: avoid creating outliers
    let dev = post_residual as f64 - mean_residual;
    score += 0.05 * dev.abs();

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize large dead space that nothing small can use
    if post_residual > 0 && post_residual < 10 {
        score -= 15.0; // nearly-full bin is great
    }

    // New-bin candidate: make empty bins less attractive unless nothing fits well
    if bin_residual == bin_capacity {
        score += 20.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0; // fresh bin fine if it enables the chain
        }
    }

    // Late in stream: consolidate harder
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core best-fit bias: strongly reward tight fits.
    let tightness = (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64;
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that is too small to be useful for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    }

    // Reward leaving room for the lookahead item if it fits exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0; // perfect chaining opportunity
        } else if post_residual >= next_item_size {
            score -= 6.0; // lookahead still fits
        } else {
            score += 4.0; // lookahead won't fit here
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 0.5 * (post_residual as f64);
    }

    // New-bin candidate handling: prefer opening a new bin only when the
    // best available fit is poor (large post_residual relative to capacity).
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 20.0;
        // Early in the stream, opening bins is cheaper (more future items
        // to fill them); later, conserve bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 * progress;
        // Many open bins with high mean residual => fragmentation; opening
        // a fresh bin is more attractive then.
        score -= 0.3 * open_bins_count as f64;
        score -= 0.05 * mean_residual;
        // If item is large relative to capacity, a fresh bin is safer.
        score -= 0.2 * item_size as f64;
    } else {
        // Existing bin: slight preference when bin residual is small overall
        // (consolidation), and when many bins are open (avoid spreading).
        score += 0.02 * bin_residual as f64;
        if open_bins_count > 4 {
            score -= 1.0;
        }
    }

    // Global pressure: when mean residual across open bins is high, favor
    // placements that consume the most space (already via tightness), but
    // add a mild extra coupling.
    score -= 0.03 * mean_residual * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Core: reward tight packing (low post_residual) with smooth non-linear shaping.
    let mut score = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // later in the stream, dead space hurts more; emphasize small residuals.
    let pr_norm = pr / cap;
    score += 0.6 * pr_norm * pr_norm * (0.5 + progress);
    score -= 0.4 * pr_norm * progress * (1.0 - pr_norm);

    // Penalize near-full bins only mildly when they still fit the next item
    if next_item_size > 0 && post_residual > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 0.5 * (nx / cap) * (1.0 - pr_norm);
        } else {
            score += 0.8 * (nx / cap) * (1.0 - pr_norm);
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 1.5;
    }

    // New empty bin candidate: neutral-to-slightly-high baseline; allow it to win
    // only when existing bins would leave very awkward residuals.
    if bin_residual == bin_capacity {
        score = 1.2 + 0.5 * progress + 0.002 * open_bins_count as f64;
        // If all fitting bins would leave tiny unusable space, opening is fine.
        if fitting_bins_count >= 1 {
            score += 0.3 * (1.0 - (item_size as f64 / cap));
        }
    }

    // Mild diversity pressure: many open bins with high mean residual -> prefer reusing fuller bins.
    if open_bins_count > 1 && bin_residual < bin_capacity {
        score += 0.1 * (mean_residual / cap - pr_norm).max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: reward residuals that form
    // "nice" capacity fractions (small denominators), penalize awkward ones.
    let pr = post_residual;
    if pr == 0 {
        score -= 25.0; // perfect fit is always excellent
    } else {
        // class by post_residual / capacity fraction
        let frac = pr as f64 / cap;
        // harmonics: 0, 1/4, 1/3, 1/2, 2/3, 3/4 -> useful slots
        let harmonics = [0.25f64, 1.0 / 3.0, 0.5, 2.0 / 3.0, 0.75];
        let mut best_h = f64::INFINITY;
        for &h in harmonics.iter() {
            let d = (frac - h).abs();
            if d < best_h { best_h = d; }
        }
        score -= 12.0 * (1.0 - (best_h * 8.0).min(1.0)); // reward near-harmonic residuals
        // integer-division threshold classes on post_residual
        let cls = pr / 10; // decade class
        match cls {
            0 => score -= 6.0,             // tiny dead space, nearly full
            1 => score += 2.0,
            2 => score -= 3.0,             // ~20-29 leaves room for small items
            3 => score += 1.0,
            4 => score -= 4.0,             // ~40-49: half-ish bin, flexible
            5 => score -= 5.0,             // exactly ~half
            6 => score += 2.0,
            7 => score -= 2.0,
            _ => {}                        // large residual: neutral
        }
        // modulo-5 residue: residuals divisible by 5 pair well with 10-multiple items
        if pr % 5 == 0 { score -= 3.0; }
        if pr % 10 == 0 { score -= 3.0; }
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 20.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / cap).max(0.0);
            // harmonic check for pair leftover
            let lfrac = slack / cap;
            if (lfrac * 4.0).fract() < 0.05 || (lfrac * 3.0).fract() < 0.05 || (lfrac * 2.0).fract() < 0.05 {
                score -= 4.0;
            }
        } else {
            // next item won't fit here: penalize mildly, worse if this was last-chance
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin gets a baseline cost that scales
    // with how many bins are already open and stream progression.
    if bin_residual == bin_capacity {
        score = cap * 0.55 + (open_bins_count as f64) * 1.5;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // opening fresh bin is better if next item is big too
        }
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 4.0 * progress;
        return score;
    }

    // Prefer tight fits generally: reward small post_residual relative to item
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 6.0 * tightness;

    // Mild preference to balance residual spread vs mean
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable gaps: dead space if residual < smallest plausible item (1..100 unknown, use 10 as floor)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Reward near-perfect fits
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, prefer tightening existing bins over spreading
    let obp = open_bins_count as f64;
    score += 0.8 * obp * (post_residual as f64 / bin_capacity as f64);

    // Dead-space shaping: penalize residuals too small for typical items relative to mean residual
    let pr = post_residual as f64;
    if pr > 0.0 && pr < mean_residual * 0.3 {
        score += 15.0;
    }

    // Lookahead coupling: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 20.0;
    } else if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
        score += 8.0;
    }

    // New-bin candidate handling: neutral baseline, slight bonus early when few bins open
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 45.0 - 10.0 * (1.0 - progress) - 2.0 * obp;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let t = step_index as f64 / (total_items.max(1) as f64);

    // --- 2-step lookahead coupling ---
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Perfect chain: this bin's leftover exactly hosts the next item.
            score -= 70.0;
        } else if next_item_size > post_residual {
            // Leftover too small for the next item -> dead space penalty,
            // stronger the more it wastes relative to item size.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.7 * waste + 0.3 * (waste * waste) / (bin_capacity as f64);
        } else {
            // Leftover larger than next item: mild preference for tight leftovers.
            score += 0.15 * (next_item_size - post_residual) as f64;
        }
    }

    // --- Last-chance bonus: only bin that fits -> avoid opening a new bin ---
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Base penalty for spreading items across bins.
        let mut new_bin_penalty = 45.0;
        // If open bins have lots of slack on average, opening new bin is worse.
        new_bin_penalty += 0.6 * mean_residual;
        // Late in the stream, consolidation matters more.
        new_bin_penalty += 20.0 * t;
        // If many bins can fit, definitely prefer an existing bin.
        if fitting_bins_count > 1 {
            new_bin_penalty += 25.0;
        }
        score += new_bin_penalty;
    }

    // --- General tightness shaping: reward near-full bins slightly superlinearly ---
    let fill = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 10.0 * fill * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Tightness: reward small relative dead space
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * 50.0;

    // Penalize leaving residual that no typical item (1..=100) can use well:
    // residuals of 1..=9 are almost dead space
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big bonus
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // next item fits but not perfectly; mild bonus scaled by waste
            score -= 60.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item cannot use this bin's leftover: penalize large leftovers
            score += (post_residual as f64) * 0.3;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // Many open bins: prefer filling existing bins over opening new ones
    score += open_bins_count as f64 * 2.0;

    // Prefer bins below mean residual (more filled) when many bins are open
    score += (bin_residual as f64 - mean_residual) * 0.5;

    // Time horizon: early in stream, be picky about tight fits; late in stream,
    // just pack anywhere that fits to avoid wasting bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 80.0;

    // New-bin candidate: make it moderately attractive only when current bins fit poorly
    if bin_residual == bin_capacity {
        // base cost of opening a new bin, reduced if many bins open or late stream
        score = 300.0 - progress * 100.0 - (open_bins_count as f64).min(20.0) * 3.0;
        // if next item is large, a fresh bin is more valuable
        if next_item_size >= 50 {
            score -= 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_norm = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress.
    let base = pr * (1.0 + 0.9 * progress * (1.0 - progress) * 4.0);
    let quad = 12.0 * fit_norm * fit_norm * (1.0 + progress);
    let quartic = 3.0 * fit_norm.powi(4) * (1.0 - progress);

    // Reward tight fits (low post residual) via subtraction.
    let tight_bonus = -8.0 * (1.0 - fit_norm) * (1.0 - fit_norm);

    // Penalize wasted space relative to mean residual of open bins.
    let waste_penalty = 0.35 * (pr as f64 - mean_residual).max(0.0);

    // Last-chance bin gets a strong reward to avoid opening new bins.
    let last_chance = if fitting_bins_count == 1 { -15.0 } else { 0.0 };

    // Lookahead: reward leaving space for the next item.
    let nx = next_item_size as f64;
    let lookahead = if nx > 0.0 {
        let diff = pr - nx;
        if diff >= 0.0 { -6.0 * (diff / cap) } else { 10.0 * (-diff / cap) }
    } else {
        0.0
    };

    // Mild penalty for spreading across many open bins late in stream.
    let spread = 0.5 * (open_bins_count as f64).ln() * progress;

    base + quad + quartic + tight_bonus + waste_penalty + last_chance + lookahead + spread
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: capacity fraction buckets.
    // Residuals in the same "class" (multiples of small units) are more reusable.
    let unit: u32 = 10;
    let class_fit = post_residual % unit == 0;
    if class_fit {
        score -= 12.0; // residual aligns with harmonic grid -> likely reusable
    }

    // Dead-space penalty: small awkward residuals (nonzero mod class) are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: does the next item fit exactly into post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect two-item packing
        } else if next_item_size <= post_residual {
            // harmonic class of leftover after hypothetical next placement
            let post2 = post_residual - next_item_size;
            if post2 % unit == 0 {
                score -= 15.0;
            }
            score += post2 as f64 * 0.3;
        } else {
            // next item cannot follow here; residual likely stranded
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin wastes current residual.
    if bin_residual == bin_capacity {
        // Only attractive when existing residuals are poor fits for item or next item.
        let waste = bin_residual - item_size;
        score = waste as f64 + 5.0;
        if next_item_size > 0 && next_item_size <= waste {
            score -= 10.0;
        }
        if open_bins_count == 0 {
            score -= 100.0;
        }
        // penalize opening new bins when a good harmonic fit exists elsewhere
        if class_fit && fitting_bins_count > 0 {
            score += 20.0;
        }
    }

    // Prefer tight fits generally: reward small post_residual relative to capacity.
    score -= (bin_capacity - post_residual) as f64 * 0.1;

    // Mild pressure to consolidate when many bins are open.
    if bin_residual < bin_capacity {
        score -= (open_bins_count as f64).ln().max(0.0) * 2.0;
    }

    // Progress-based tie-break: later in stream, prefer filling bins fully.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * post_residual as f64 * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the next item are unusable
    let next = if next_item_size == 0 { 10 } else { next_item_size };
    if post_residual > 0 && post_residual < next {
        score += 60.0 + 0.5 * post_residual as f64; // dead space penalty
    }

    // Perfect / near-perfect fits get strong reward
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Tight fit reward: item dominates the residual
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio;

    // Last-chance bin: strongly favor using it to avoid opening a bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Pressure from many open bins: prefer consolidating into existing bins
    score += (open_bins_count as f64) * 0.8;

    // Penalize bins whose residual deviates badly from the mean (fragmentation signal)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // New-bin candidate: only attractive when no decent fit exists
    if bin_residual == bin_capacity {
        let bad_fit = if bin_residual < item_size { 1.0 } else { 0.0 };
        score += 45.0 - 20.0 * bad_fit;
        if post_residual > 0 && post_residual < next {
            score += 30.0; // opening a bin that immediately dead-ends
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Aggressive 2-step lookahead: reward when next item fits into post_residual
    if next_item_size > 0 && next_item_size <= post_residual {
        // Exact/near-exact chain match is highly desirable
        let slack_after_next = post_residual as f64 - next_item_size as f64;
        score -= 25.0 * (1.0 - slack_after_next / bin_capacity as f64);
        // Extra reward for perfect two-item chain
        if slack_after_next < 1.0 {
            score -= 15.0;
        }
    } else if next_item_size > 0 {
        // Next item cannot follow here: penalize, more so if it leaves awkward dead space
        let dead = post_residual as f64;
        if next_item_size > post_residual {
            // penalize proportionally to how "wasted" the residual is relative to next item
            let gap = next_item_size as f64 - post_residual as f64;
            if gap < 10.0 {
                score += 6.0; // near-miss: mildly wasteful
            } else {
                score += dead * 0.15; // large dead space the next item can't use
            }
        }
    }

    // Prefer bins with residual below the mean (consolidating fullness)
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current fits are poor
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin
        score += 55.0;
        // Reduce penalty late in stream (fewer future items to fill it)
        score -= 25.0 * progress;
        // If next item is large and current bin can't chain, opening fresh is more attractive
        if next_item_size > 0 && next_item_size > post_residual && post_residual < next_item_size {
            score -= 10.0;
        }
        // If item fits perfectly in a fresh bin chain with next item
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 8.0;
        }
    } else {
        // Slight preference for reusing existing bins vs opening new ones early
        score -= 5.0 * (1.0 - progress);
    }

    // Discard fragments that are likely unusable (residual below minimum item size)
    if post_residual < 10 && post_residual > 0 {
        score += 8.0;
    }
    if post_residual == 0 {
        score -= 30.0; // perfect fill
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tightness of fit: reward placements that leave little residual,
    // but only when the leftover is genuinely unusable.
    let tight_bonus = (item_size as f64 / bin_capacity as f64).powi(2) * 40.0;
    score -= tight_bonus;

    // Penalize residual space that is too small for the smallest plausible
    // future item (dead space), scaled by stream progress.
    let dead_threshold = 10.0;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * (1.5 + progress);
    }

    // Lookahead coupling: if the next item fits exactly into the post-residual,
    // strongly reward this placement (perfect pair).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // next item fits, but leaves more waste -> mild reward
            score -= 15.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item cannot use leftover -> penalize proportional to gap
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Last-chance bin: if this is the only bin that fits, using it avoids
    // opening a new bin. Strongly reward.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: opening a new bin should generally be
    // discouraged unless the item fits poorly everywhere else.
    if bin_residual == bin_capacity {
        let crowd = open_bins_count as f64;
        // Cost grows with number of open bins (fragmentation) and progress.
        score += 25.0 + 5.0 * crowd.sqrt() + 20.0 * progress;
        // But if item is large, a fresh bin is natural (perfect-ish fit).
        if item_size >= 70 {
            score -= 30.0;
        }
        // If mean residual across open bins is large, prefer reusing them:
        // penalize new bin more.
        if mean_residual >= item_size as f64 {
            score += 15.0;
        }
    }

    // Mild reward for keeping mean residual balanced: avoid extreme bins.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Prefer bins whose residual is close to item size (best-fit flavor),
    // modulated by global state.
    let fit_gap = (bin_residual as f64 - item_size as f64).abs();
    score += fit_gap * 0.3 * (1.0 - 0.5 * progress);

    // Slight preference for denser packing late in the stream.
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let pr = post_residual as f64 / bin_capacity as f64;
    let poly = pr * pr * (0.5 + 2.0 * progress) + pr * (1.0 - progress) * 0.3;
    score += poly * bin_capacity as f64 * 0.5;

    // Reward tight fits more strongly as stream progresses.
    let tightness = 1.0 - pr;
    score -= tightness * tightness * (10.0 + 40.0 * progress);

    // Penalize opening new bins late unless residual is large.
    let is_new_bin = (bin_residual == bin_capacity) as f64;
    score += is_new_bin * (5.0 + 30.0 * progress * (1.0 - pr));

    // Last-chance bonus: strongly favor the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: reward bins whose post_residual can still fit the next item.
    if next_item_size > 0 {
        let fits_next = (post_residual >= next_item_size) as f64;
        score -= fits_next * (1.0 + progress) * 8.0;
        // Penalize post_residual that is small but nonzero (dead space for next item).
        let waste = if post_residual > 0 && post_residual < next_item_size { 1.0 } else { 0.0 };
        score += waste * 10.0 * (0.5 + progress);
    }

    // Mild dispersion penalty relative to mean residual.
    score += ((bin_residual as f64 - mean_residual) / bin_capacity as f64).abs() * 3.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo buckets on capacity fractions
    let pr = post_residual;
    let class = pr % 10;
    // Dead-space penalty: residuals that are unusable for typical small items
    if pr > 0 && pr < 10 {
        score += 60.0; // tiny dead space
    }
    // Harmonic reward: residuals that are multiples of common item classes
    if class == 0 {
        score -= 8.0;
    } else if pr % 25 == 0 {
        score -= 6.0;
    } else if pr % 5 == 0 {
        score -= 3.0;
    } else {
        score += 2.0;
    }

    // Perfect fit bonus
    if pr == 0 {
        score -= 100.0;
    }

    // Lookahead coupling: does post_residual fit next item exactly?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 50.0;
        } else if next_item_size <= pr {
            score -= (pr - next_item_size) as f64 * 0.3;
        } else {
            // next item won't fit here; residual becomes dead-ish
            score += (next_item_size - pr) as f64 * 0.2;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: only prefer new bin if all open bins fit poorly
    if bin_residual == bin_capacity {
        // baseline for a fresh bin; competitive unless existing fit is good
        score = 55.0 + mean_residual * 0.1 - (open_bins_count as f64) * 0.5;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0;
        }
    }

    // Progress factor: late in stream, prefer tighter packing
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.1;

    // Penalize bins whose residual is far below mean (fragmented bins)
    if (bin_residual as f64) < mean_residual * 0.5 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small to hold typical items are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 15.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
        if post_residual < 10 {
            score += 50.0; // still avoid trapping dead space
        }
    }

    // New-bin candidate: only attractive when open bins would create dead space
    // or when bin pressure is low.
    if bin_residual == bin_capacity {
        score += 40.0;
        score -= (open_bins_count as f64) * 3.0;
        if fitting_bins_count >= 1 {
            score += 20.0; // discourage abandoning existing fitting bins
        }
    }

    // Lookahead: if the next item fits exactly into the post_residual, keep this bin.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
        score -= 30.0;
    }
    // Penalize leaving a gap that the next item almost fits (wasted reservation).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual >= next_item_size - 5 {
        score += 20.0;
    }

    // Open-bin pressure: many open bins -> prefer filling existing ones.
    score += (open_bins_count as f64) * 1.5;

    // Progress: later in the stream, tighten up (avoid spreading items).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 5.0;

    // Slight preference for bins below mean residual (balance load).
    score += ((post_residual as f64) - mean_residual) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact/near-exact matches with next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs();
        if post_residual == next_item_size {
            score -= 60.0; // perfect 2-step chain
        } else if (post_residual as u32) >= next_item_size {
            score -= (20.0 - diff as f64).max(0.0);
        } else {
            // dead space relative to next item: penalize proportionally
            score += diff as f64 * 0.5;
        }
    }

    // Reward tight fits relative to mean residual
    let pr = post_residual as f64;
    if pr < mean_residual {
        score -= (mean_residual - pr) * 0.3;
    } else {
        score += (pr - mean_residual) * 0.2;
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize opening a new bin when open bins fit reasonably well
    if bin_residual == bin_capacity {
        score += 25.0 + open_bins_count as f64 * 2.0;
        if post_residual as f64 >= next_item_size as f64 && next_item_size > 0 {
            score += 10.0; // new bin only attractive if it chains too
        }
    }

    // Small bonus for compactness late in the stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item nearly fills the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fill_ratio * fill_ratio;

    // Penalize creating small unusable dead space (residual too small for typical items).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward if the next item fits exactly into the post-residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate handling: penalize opening a new bin, more so when
    // good open options exist or many bins are already open.
    if bin_residual == bin_capacity {
        score += 35.0 + 3.0 * open_bins_count as f64;
        // But if the item is large, opening a fresh bin is less bad.
        score -= 0.2 * item_size as f64;
    }

    // Global pressure: when mean residual is low (bins are tight), prefer
    // spreading load; when high, prefer consolidation into fuller bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.1 * (mean_residual - post_residual as f64) * (1.0 - progress);

    // Late in the stream, favor closing out bins tightly.
    if progress > 0.8 {
        score -= 0.15 * post_residual as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: f64, fitting_bins_count: usize) -> f64 {
    let _ = item_size;
    let _ = bin_residual;
    let _ = bin_capacity;
    let _ = step_index;
    let _ = total_items;
    let _ = open_bins_count;
    let _ = mean_residual;
    let _ = next_item_size;
    let _ = fitting_bins_count;
