}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues that form "good" pairing classes
    // (small leftovers) get rewarded, mid-range dead space gets penalized.
    let pr = post_residual;
    let cls = pr % 10;
    match cls {
        0 => score -= 12.0,           // perfect class: zero-ish waste
        1 | 2 => score -= 8.0,        // near-perfect fit class
        3 | 4 => score -= 3.0,        // acceptable
        5 | 6 => score += 6.0,        // half-capacity dead zone
        _ => score += 2.0,            // large residue but plausibly fillable
    }

    // Integer-division thresholds on post_residual: can next item land here?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Coupling: residual class must match next item's size class
            let next_cls = next_item_size % 10;
            let compat = (next_cls + cls) % 10;
            score -= (compat as f64) * 0.8;
            score -= 5.0; // keeping this bin usable for the lookahead is good
        } else {
            score += 7.0; // this bin becomes dead for the lookahead
        }
        // If next item exactly fills to a harmonic boundary, strongly reward
        if next_item_size == pr {
            score -= 15.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // New-bin candidate (empty bin): penalize opening a new bin unless
    // the current item is large and would leave a clean harmonic residual.
    if bin_residual == bin_capacity {
        let large_item = item_size > bin_capacity / 2;
        if large_item {
            score -= 4.0;
        } else {
            score += 14.0 + (open_bins_count as f64).sqrt() * 2.0;
        }
        // Opening fresh is attractive early in the stream
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 6.0 * (1.0 - progress);
    }

    // Prefer bins whose residual is far below the mean (tight packing trend)
    score += (mean_residual - bin_residual as f64) * 0.35;

    // Mild penalty for spreading across many bins
    score += open_bins_count as f64 * 0.15;

    // Small harmonic tie-breaker on bin residual itself
    score -= ((bin_residual % 20) as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // possible item (1..100 unknown distribution, be conservative at <=8)
    // are "dead space" — penalize them quadratically.
    if post_residual < 8 {
        score += (8.0 - post_residual as f64) * (8.0 - post_residual as f64) * 6.0;
    }

    // Reward tight fits: fraction of bin consumed by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 25.0;

    // Reward exact / near-exact closure of the bin.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 3 {
        score -= 15.0;
    }

    // Lookahead coupling: if the next item fits the post-residual,
    // this placement chains nicely; otherwise the residual is likely waste.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0;
        } else {
            score += 5.0;
        }
    }

    // Open-bin pressure: discourage spreading across many bins when a
    // compact choice exists; stronger pressure later in the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (0.4 + 0.6 * progress);

    // Nudge toward bins whose residual is close to the mean residual
    // (keeps the bin pool homogeneous, avoids stranded outliers).
    score += (bin_residual as f64 - mean_residual).abs() * 0.05;

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate (bin_residual == bin_capacity): only attractive
    // if the item is large or no open bin fits well; otherwise penalize
    // opening fresh bins to avoid bin proliferation.
    if bin_residual == bin_capacity {
        let base = 12.0;
        let large_item_bonus = if item_size >= 60 { -10.0 } else { 0.0 };
        let scarcity_bonus = if fitting_bins_count == 0 { -20.0 } else { 0.0 };
        score += base + large_item_bonus + scarcity_bonus
            + open_bins_count as f64 * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if next item fits exactly in post_residual, reward heavily.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 800.0;
    }

    // If next item fits in post_residual, mild reward proportional to fit quality.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 200.0 * (next_item_size as f64 / post_residual as f64);
    } else if next_item_size > 0 {
        // Dead space: next item cannot fit in leftover; penalize unusable residual.
        score += 50.0 + 0.5 * post_residual as f64;
    }

    // Penalize residuals that are too small to ever be useful (below min item size 1 already ok, but small scraps waste).
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Relative to mean residual: prefer bins whose post_residual is below mean (tight packing).
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins have poor fits.
    if bin_residual == bin_capacity {
        score += 250.0;
        // But if no existing bin fits well, allow opening (offset when mean residual is low relative to item).
        if fitting_bins_count == 0 {
            score -= 400.0;
        }
    }

    // Early stream: be slightly more conservative about opening bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 100.0 * (1.0 - progress);
    }

    // Many open bins: encourage closing them out by filling.
    score -= 2.0 * open_bins_count as f64 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near zero is best.
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 {
        let dead = post_residual as f64;
        if dead < 10.0 {
            score += 8.0 * (10.0 - dead) / 10.0; // unusable sliver
        } else if next_item_size > 0 && (next_item_size as f64) > dead {
            score += 0.05 * (next_item_size as f64 - dead);
        }
    }

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 6.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Prefer bins whose residual deviates favorably from the mean (use fuller bins first).
    score += 0.3 * (mean_residual - bin_residual as f64).max(-20.0).min(20.0);

    // Time horizon: early on, be conservative about fragmenting; later, pack aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * progress * tightness;

    // New-bin candidate handling: empty bin is a fallback; make it costly unless
    // no good fit exists (post_residual large relative to item) or many bins open.
    if bin_residual == bin_capacity {
        let base = cap * 0.9;
        let mut penalty = base;
        // If the item is large relative to capacity, opening fresh is less bad.
        penalty -= 30.0 * (item_size as f64 / cap);
        // Late in the stream, opening new bins is fine (bins won't be reused much).
        penalty -= 15.0 * progress;
        // If many bins are open, prefer consolidating instead of opening.
        penalty += 3.0 * open_bins_count as f64;
        // If next item is huge, a fresh bin gives flexibility.
        if next_item_size > 0 && (next_item_size as f64) > 0.7 * cap {
            penalty -= 20.0;
        }
        score += penalty;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer low post-residual, with non-linear (quadratic) penalty
    let mut score = pr + 30.0 * norm_pr * norm_pr * cap;

    // Smooth coupling with stream progress: later in stream, waste matters more
    let progress_coupling = 1.0 + 2.0 * progress * progress;
    score *= progress_coupling;

    // Reward tight fits more strongly as the stream advances
    let tightness = 1.0 - norm_pr;
    score -= 25.0 * tightness * tightness * (0.5 + progress);

    // Lookahead: bonus if next item fits the post-residual
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 12.0 * (1.0 - (next_item_size as f64 / cap));
    }

    // Penalize bins with residual far from mean (fragmentation)
    let dev = (pr - mean_residual) / cap;
    score += 8.0 * dev * dev * cap;

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Mild penalty for opening new bins when many are open
    let new_bin = if bin_residual == bin_capacity { 1.0 } else { 0.0 };
    score += new_bin * (5.0 + 3.0 * (open_bins_count as f64).ln().max(0.0)) * (1.0 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues divisible by common item
    // granularities are more reusable than awkward residues.
    let pr = post_residual;
    if pr == 0 {
        // Perfect fit: strongly reward.
        score -= 1000.0;
    } else {
        // Modulo classes on post_residual (capacity 100 -> useful residuals
        // cluster around multiples of 10 and small values).
        let class10 = (pr % 10) as f64;
        score += class10 * 2.5; // penalize non-decade residue
        if pr % 20 == 0 { score -= 15.0; }
        if pr % 5 == 0 { score -= 6.0; }

        // Integer-division thresholds: tiny residuals are dead space.
        if pr < 10 {
            score += 60.0 + (10 - pr) as f64 * 4.0;
        } else if pr <= 20 {
            score -= 10.0; // sweet spot for medium items
        }

        // Harmonic coupling with next item: reward if next item fits
        // harmonically into post_residual.
        if next_item_size > 0 {
            if next_item_size <= pr {
                let slack = pr - next_item_size;
                score -= 25.0;
                if slack % 10 == 0 { score -= 12.0; }
                if slack == 0 { score -= 40.0; } // chains two perfect fits
            } else {
                // Next item cannot use this bin's residue; penalize awkward waste.
                score += (next_item_size - pr).min(30) as f64 * 0.8;
            }
        } else {
            // Last item: only zero residual matters.
            score += pr as f64 * 0.5;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: only attractive when existing residuals are poor.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        // Base penalty keeps new bins from opening casually.
        score += 90.0;
        // If mean residual is small (bins are tight), opening fresh is fine.
        score -= pressure * 120.0;
        // Large items favor fresh bins.
        if item_size >= 50 { score -= 25.0; }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 30.0;
    }

    // Slight preference for tighter bins among equals.
    score += (bin_residual as f64 / bin_capacity as f64) * 5.0;
    // Mild penalty for many open bins to encourage consolidation.
    score += open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
