pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: huge reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual exactly matches next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // penalize leftover that is slightly larger than next item (wasted chain potential)
            let gap = (post_residual - next_item_size) as f64;
            score -= 20.0 - gap.min(20.0);
        } else {
            // dead space relative to next item
            let dead = (next_item_size - post_residual) as f64;
            score += dead * 0.5;
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Last-chance bin: strong reward to use it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: make empty bin attractive only when no good fit exists
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 + 50.0;
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 60.0;
        }
        if fitting_bins_count <= 1 {
            score -= 100.0;
        }
    }

    // Early stream: encourage consolidating into few bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // --- New-bin candidate handling ---
    let is_new_bin = bin_residual == bin_capacity && bin_capacity > 0;
    if is_new_bin {
        // Opening a new bin is a fallback: prefer it only when the item fits
        // badly everywhere else. Base cost slightly above a perfect fit in an
        // existing bin, modulated by how many alternatives exist.
        let mut nb = bin_capacity as f64 * 0.95;
        // If many bins fit the item, opening a new one is wasteful.
        nb += (fitting_bins_count as f64) * 12.0;
        // Late in the stream, prefer reusing bins (avoid trailing fragmentation).
        nb += t * 15.0;
        // If the next item is large, a fresh bin is more valuable as a buffer.
        if next_item_size > 0 {
            let look_tight = (next_item_size as f64 / bin_capacity as f64).clamp(0.0, 1.0);
            nb -= look_tight * 10.0;
        }
        return nb;
    }

    // --- Reward tight fits (small post_residual) ---
    // Perfect fit gets a strong bonus; wasted space is penalized super-linearly.
    let waste = post_residual as f64;
    score -= (bin_capacity as f64 - waste) * 0.35; // reward fill ratio
    score += (waste / bin_capacity as f64).powf(1.6) * 40.0; // dead-space penalty

    // Dead space is worse if it's unusable for the next item but the bin
    // could have been closed neatly instead.
    if next_item_size > 0 && (next_item_size as u32) > post_residual {
        // Next item cannot use the leftover: leftover is likely permanent waste.
        score += waste * 0.25;
        // But if next item is huge, leaving a mid-size gap is tolerable.
        if next_item_size >= 70 { score -= waste * 0.10; }
    } else if next_item_size > 0 {
        // Next item fits in the gap: this pairing is efficient, reward it.
        let snug = 1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64);
        score -= snug * 8.0;
    }

    // --- Last-chance bin bonus ---
    if fitting_bins_count == 1 {
        // This is the only bin that fits; strongly favor using it rather
        // than opening a new bin and stranding this capacity.
        score -= 25.0;
    } else {
        // With multiple candidates, prefer the one closest to mean residual
        // balance? No: prefer the emptiest-fitting bin to consolidate load.
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.05;
    }

    // --- Global state coupling ---
    // Many open bins: encourage filling existing ones to allow closing.
    let pressure = open_bins_count as f64 / (1.0 + (bin_capacity as f64 / 10.0));
    score -= pressure.min(20.0) * 0.8;

    // Early in the stream, be slightly exploratory (keep bins balanced);
    // late in the stream, greedily minimize waste.
    let balance_pull = (mean_residual - bin_residual as f64) * (1.0 - t) * 0.15;
    score += balance_pull;

    // Small tie-breaking jitter grounded in state (deterministic).
    score += ((item_size as f64 * 0.013 + post_residual as f64 * 0.007) % 1.0) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Non-linear penalty on wasted space, amplified by stream progress
    let pr = post_residual as f64;
    let pr_norm = pr / bin_capacity as f64;
    score += 40.0 * pr_norm * pr_norm * (0.5 + progress);

    // Reward tight fits (small post_residual) more strongly as stream progresses
    score -= 15.0 * (1.0 - pr_norm).powi(3) * (0.5 + progress);

    // Penalize bins with residual far below mean residual (poor future usability)
    score += 0.3 * (mean_residual - pr).abs() * (0.5 + progress);

    // Last-chance bin bonus: strongly reward using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 10.0 * progress;
    }

    // Lookahead: reward leaving room for the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 8.0 * (1.0 - (pr - nxt) / bin_capacity as f64);
        } else {
            score += 6.0;
        }
    }

    // New-bin candidate: penalize opening a bin unless current fit is poor
    if bin_residual == bin_capacity {
        score += 20.0 * (1.0 - progress) + 0.5 * pr_norm * 100.0 * (1.0 - progress);
    }

    // Mild pressure to consolidate when many bins are open
    score += 0.1 * open_bins_count as f64 * pr_norm;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "usable"
    // classes (multiples of common item sizes) are rewarded.
    let usable = |r: u32| -> f64 {
        let mut h = 0.0f64;
        for &d in &[10u32, 20, 25, 30, 40, 50] {
            if r % d == 0 && r > 0 {
                h += 6.0;
            }
        }
        h
    };
    score -= usable(post_residual);

    // Penalize dead space: small nonzero leftovers are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 8.0;
    }

    // Perfect fit is excellent.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: reward if the next item can exactly fill the leftover.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 + (post_residual - next_item_size) as f64 * 0.2;
        } else {
            // next item cannot use the leftover: penalize large leftovers less
            // if they fall into reusable classes.
            let waste = post_residual as f64 - 0.0;
            score += waste * 0.15 - usable(post_residual) * 0.5;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else {
        score += (fitting_bins_count as f64 - 1.0) * 2.0;
    }

    // Prefer filling bins below the mean residual (tighter bins first).
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Integer-division thresholds on post_residual: quarters of capacity.
    let q = post_residual / (bin_capacity / 4);
    match q {
        0 => score -= 12.0,          // leftover < 25: nearly full bin, good
        1 => score += 3.0,
        2 => score += 6.0,
        _ => {}
    }

    // New-bin candidate: make opening a new bin only attractive when the item
    // is large and no tight fit exists elsewhere.
    if bin_residual == bin_capacity {
        score += 20.0;
        if item_size >= 60 && fitting_bins_count == 0 {
            score -= 45.0;
        }
        if next_item_size > 0 && next_item_size > bin_capacity - item_size {
            score -= 5.0; // fresh bin gives room for a big next item
        }
    }

    // Late in the stream, consolidate: prefer reusing open bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that can never fit a future item
    // (sizes range 1..100, so anything < 1 is truly dead; but small gaps below
    // the typical minimum are nearly dead) are heavily penalized.
    if post_residual == 0 {
        // Perfect fit: strongly reward.
        score -= 200.0;
    } else if post_residual < 10 {
        // Unusable sliver -> penalize hard on top of its small raw value.
        score += 60.0;
    } else if post_residual < 25 {
        score += 25.0;
    } else if post_residual < 50 {
        score += 8.0;
    }

    // Tightness reward: the smaller post_residual relative to residual, the better.
    let tightness = 1.0 - (post_residual as f64) / (bin_residual as f64).max(1.0);
    score -= 40.0 * tightness;

    // Lookahead coupling: if the next item fits exactly into the resulting gap,
    // reward strongly; if the gap is just barely too small for the next item,
    // penalize.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0;
        } else if next_item_size < post_residual {
            score -= 15.0;
        } else if next_item_size > post_residual && next_item_size <= post_residual + 10 {
            score += 20.0;
        }
    }

    // Open-bin pressure: discourage spreading across many bins; encourage
    // filling existing bins when many are open.
    score += 3.0 * open_bins_count as f64;

    // Deviation from mean residual: prefer bins whose residual is close to the
    // mean (balanced packing), penalize outliers.
    score += 0.5 * ((bin_residual as f64 - mean_residual).abs());

    // Last-chance bin: if this is the only bin that fits, strongly prefer using
    // it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // New-bin candidate handling: an empty bin has bin_residual == bin_capacity.
    // Opening a new bin is only attractive when the item fits poorly everywhere
    // else; make the empty-bin score a moderate default so tight fits elsewhere
    // beat it.
    if bin_residual == bin_capacity {
        score = 100.0
            + 3.0 * open_bins_count as f64
            + if fitting_bins_count == 0 { -50.0 } else { 0.0 }
            + if next_item_size > 0 && next_item_size >= bin_capacity && item_size >= bin_capacity { -30.0 } else { 0.0 };
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Lookahead: strongly reward an exact match with the next item (2-step chain).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 / (1.0 + slack);
        } else {
            // Next item cannot use the leftover; penalize dead space proportionally.
            let waste = (next_item_size - post_residual) as f64;
            score += waste * 0.15;
        }
    } else {
        // Last item: leftover is pure waste.
        score += 10.0;
    }

    // Penalize leftover space that is too small to ever be useful (< min item size 1..100 heuristic floor).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Prefer bins with residuals below the mean (tight packing), punish outliers.
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when nothing fits well; discourage opening bins early.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 15.0 + 10.0 * (1.0 - progress);
        if fitting_bins_count > 0 {
            score += 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong preference for tight fits: exact fill is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize residuals that are too small to ever be useful (dead space).
        let min_item = 1u32;
        if post_residual < min_item {
            score += 500.0;
        }
        // Fractional waste relative to capacity, amplified for small leftovers
        // that nothing else will likely fit into.
        let waste_frac = post_residual as f64 / bin_capacity as f64;
        score += waste_frac * 40.0;
        // Coupling with lookahead: if the next item fits exactly in the
        // post-residual, this placement is excellent.
        if next_item_size > 0 && next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size > 0 && next_item_size > post_residual {
            // Next item cannot go here afterward; slight penalty proportional
            // to how much leftover is stranded.
            score += waste_frac * 30.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // the item is large relative to capacity or fits are very loose.
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        // Base cost of a fresh bin.
        let mut new_bin_score = 100.0 - tightness * 60.0;
        // If many bins fit the item, the existing fit is probably fine; make
        // the new bin less attractive.
        if fitting_bins_count > 0 {
            new_bin_score += 30.0 + 5.0 * fitting_bins_count as f64;
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        new_bin_score += progress * 40.0;
        // If mean residual across open bins is high, we are wasting space
        // globally; a new bin may consolidate better.
        new_bin_score -= (mean_residual / bin_capacity as f64) * 20.0;
        // Exact-fit items deserve a fresh bin sometimes.
        if item_size == bin_capacity {
            new_bin_score -= 500.0;
        }
        return new_bin_score;
    }

    // Mild preference for bins whose residual is close to what we consume
    // (best-fit reinforcement beyond raw post_residual).
    score -= (bin_residual as f64 - item_size as f64).abs() * 0.1;

    // Slight preference for older bins to encourage closing out early bins.
    score += (open_bins_count as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;
    // non-linear polynomial coupling with stream progress
    let coupling = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress;
    score += 20.0 * coupling;
    // penalize creating dead space below next item size
    if next_item_size > 0 && (pr as u32) < next_item_size && pr > 0.0 {
        score += 8.0 * (1.0 - pr / next_item_size as f64);
    }
    // reward exact-ish fits
    score -= 6.0 * (1.0 - norm_pr) * (1.0 - progress);
    // last-chance bonus
    if fitting_bins_count == 1 {
        score -= 5.0;
    }
    // mild pressure to reuse open bins vs new bin
    score -= 0.5 * (open_bins_count as f64).ln().max(0.0);
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual (modulo arithmetic on capacity classes)
    let class = post_residual % 20; // capacity fraction classes of size 20
    let harmonic = match class {
        0 => 0.0,                 // perfectly reusable class (exact multiples)
        1..=5 => -3.0,            // near-perfect: tiny dead space, very desirable
        6..=12 => 6.0,            // awkward mid-class residual
        _ => -1.5,                // large-ish residual still fairly usable
    };
    score += harmonic;

    // Integer-division thresholds on post_residual: reward residuals that can
    // still host a typical small item (<= 25) or the lookahead item.
    if post_residual >= 25 { score -= 8.0; }
    if next_item_size > 0 && post_residual >= next_item_size { score -= 6.0; }

    // Reward tight fits (post_residual small relative to item)
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * tightness;

    // Penalize creating unusable dead space (post_residual in 1..10)
    if post_residual > 0 && post_residual < 10 { score += 15.0; }

    // Last-chance bin: strongly favor using it rather than opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when no good fit exists elsewhere
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let bad_fit = fitting_bins_count == 0
            || (post_residual as f64) > mean_residual * 0.5;
        if bad_fit { score -= 5.0 + 10.0 * progress; }
        else { score += 25.0; } // discourage opening bins when open bins fit well
        score += 2.0 * open_bins_count as f64; // mild pressure to consolidate
    }

    // Coupling with mean residual: prefer bins that keep the fleet balanced
    score += 0.3 * ((post_residual as f64) - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize residuals too small to hold
    // typical future items (below the minimum item size => truly dead space).
    if post_residual < 1 {
        score += 1000.0;
    }
    // Penalize small-but-not-dead gaps less harshly, scaled by how "wasted"
    // the gap is relative to the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 2.0;
    }

    // Reward tight fits (low post_residual) more aggressively.
    score -= (bin_capacity as f64 - post_residual as f64) * 0.05;

    // Pressure from number of open bins: discourage spreading across many
    // bins when consolidation is possible.
    score += open_bins_count as f64 * 0.3;

    // Last-chance bin: strongly favor using it if it fits, avoiding a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Lookahead: if the next item fits in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }
    // If next item would leave this bin's residual dead anyway, mild penalty.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 3.0;
    }

    // New-bin candidate handling: a fresh bin should only win when no open bin
    // offers a decent fit. Give it a baseline cost that grows with open bins
    // but is offset by its large residual.
    if bin_residual == bin_capacity {
        score = 60.0 + open_bins_count as f64 * 0.5 - mean_residual * 0.1;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: new bin is fine
        }
    }

    // Stream progression: as the stream nears its end, tighten up packing
    // (favor filling existing bins more).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual (best-fit core).
    score = post_residual as f64;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual can host the next item exactly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            // Chain of two perfect fits: extremely desirable.
            score -= 800.0;
        } else {
            // Reward proportionally to how well the next item matches leftover space.
            let match_ratio = next_item_size as f64 / post_residual as f64;
            score -= 300.0 * match_ratio * match_ratio;
            // Penalize residual dead space after the hypothetical second placement.
            score += slack as f64 * 0.5;
        }
    } else if next_item_size > 0 {
        // Next item cannot fit here: penalize leaving medium-sized unusable gaps.
        let dead = post_residual as f64;
        if dead < next_item_size as f64 {
            score += dead * 0.8;
        }
    }

    // Compare post_residual relative to mean residual across open bins:
    // prefer bins that become tighter than average (consolidating space).
    let mr = mean_residual;
    if mr > 0.0 {
        let rel = post_residual as f64 / mr;
        if rel < 1.0 {
            score -= 40.0 * (1.0 - rel);
        } else {
            score += 40.0 * (rel - 1.0);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when no
    // open bin offers a good fit. Penalize the fresh empty bin normally, but
    // discount the penalty when many bins are open and the item is large.
    if bin_residual == bin_capacity {
        let base = 120.0;
        let large_item_bonus = if item_size > bin_capacity / 2 { 60.0 } else { 0.0 };
        let crowding = (open_bins_count as f64).min(10.0) * 5.0;
        score += base + large_item_bonus + crowding;
        // Lookahead: a fresh bin pairs well with a large next item.
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 100.0;
        }
    }

    // Slight stream-phase modulation: early on, be more willing to open bins
    // (keep flexibility); late, squeeze into existing bins.
    let phase = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score -= 50.0 * (1.0 - phase);
    } else {
        score -= 30.0 * phase;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize large post_residual relative to capacity.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * 20.0;

    // Reward near-perfect fills strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 50.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Lookahead: if the next item fits the post-residual, bonus; else penalty.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 30.0;
        } else {
            // Penalize leaving residual that no realistic item can use well.
            let dead = if post_residual < 10 { 40.0 } else { 0.0 };
            score += dead;
        }
    }

    // New-bin candidate: only attractive when existing bins fit poorly.
    if bin_residual == bin_capacity {
        let avg_fit_quality = if fitting_bins_count > 0 {
            (mean_residual - item_size as f64).abs()
        } else {
            0.0
        };
        // Prefer new bin when mean residual is small (existing bins are tight)
        // or when few bins fit the item.
        score = 40.0 + avg_fit_quality * 0.3 - (fitting_bins_count as f64) * 5.0;
        // Early in stream, opening bins is cheap; later, prefer consolidation.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 30.0;
        if open_bins_count == 0 {
            score -= 200.0;
        }
    }

    // Mild penalty for spreading across too many open bins.
    score += open_bins_count as f64 * 0.5;

    // Prefer bins whose residual is close to item size (best-fit flavor).
    let gap = (bin_residual - item_size) as f64;
    score += gap * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: quadratic-ish penalty on wasted space
    let mut score = norm_post * norm_post * 120.0 + norm_post * 20.0;

    // Non-linear coupling of waste with stream progress:
    // late in the stream, waste matters more; smooth polynomial weight
    let prog_weight = 1.0 + 3.0 * progress * progress + 2.0 * progress;
    score *= prog_weight;

    // Coupling with mean residual: penalize bins that deviate from mean waste
    let dev = (mean_residual - post) / cap;
    score += dev * dev * 30.0 - dev * 10.0;

    // Lookahead coupling: reward bins whose post-residual can fit the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            let slack = (post - nxt) / cap;
            score -= 25.0 * (1.0 - slack * slack);
        } else {
            // next item can't fit here: mild penalty scaled by how far off
            let gap = (nxt - post) / cap;
            score += 15.0 * gap * gap;
        }
    }

    // Last-chance bin: strongly reward using it to avoid opening a bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0 * (1.0 - progress);
        score -= 20.0;
    }

    // New-bin candidate handling: prefer opening a new bin only when the item
    // leaves a tight residual here or fits poorly elsewhere
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Penalize new bin mildly; waive penalty if item is large relative to capacity
        let fill = item_size as f64 / cap;
        score += 35.0 - 20.0 * fill * fill;
    } else {
        // Reward tight fits (small post residual) with smooth saturating term
        let tight = 1.0 - norm_post;
        score -= 20.0 * tight * tight;
    }

    // Slight preference for bins with fewer total open bins (consolidation)
    score += (open_bins_count as f64).ln().max(0.0) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate: prefer it only when it beats the best existing fit.
    if bin_residual == bin_capacity {
        score = 50.0 + 0.35 * (item_size as f64);
        // Late in stream, favor reusing open bins more strongly.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 * progress;
        // If only this bin fits, opening a new one is wasteful.
        if fitting_bins_count <= 1 {
            score += 60.0;
        }
        return score;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Harmonic classes on post_residual: tiny dead space is good, awkward bands are bad.
    let pr = post_residual;
    let class: f64 = match pr {
        0 => -20.0,
        1..=5 => -10.0,
        6..=15 => -4.0,
        16..=25 => 3.0,
        26..=40 => 0.0,
        41..=60 => 5.0,
        _ => 8.0,
    };
    score += class;

    // Modulo-10 structure: residuals divisible by 10 pair well with typical sizes.
    if pr % 10 == 0 && pr > 0 {
        score -= 6.0;
    }
    // Odd residuals in mid-range are dead-space prone.
    if pr % 2 == 1 && pr >= 20 && pr <= 60 {
        score += 4.0;
    }

    // Lookahead coupling: does the residual nicely accommodate next item?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0; // chain perfect fit
        } else if next_item_size < pr {
            let gap = pr - next_item_size;
            if gap <= 10 {
                score -= 12.0;
            } else if gap > 40 {
                score += 6.0;
            }
        } else {
            // next item cannot use this residual: residual is dead weight
            score += 3.0 + 0.1 * (pr as f64);
        }
    } else {
        // Last item: minimize waste outright.
        score += 0.5 * (pr as f64);
    }

    // Last-chance bin: strongly prefer using it before opening new bins.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Prefer filling bins that are already low relative to the mean residual.
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 2.0;
    }

    // Mild pressure to close bins early as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 4.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead space: gaps too small for the minimum item (1..=100 range, assume small items >= 5 exist)
    // Penalize unusable slivers heavily.
    let dead_threshold = 10.0;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 8.0;
    }
    if post_residual == 0 {
        score -= 60.0; // perfect fit
    }

    // Reward tight fits relative to item size
    score -= (item_size as f64) * 0.3;

    // Last chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones
    let new_bin = bin_residual == bin_capacity;
    if new_bin {
        score += 25.0 + open_bins_count as f64 * 3.0;
        // But if the item fits poorly everywhere, opening a fresh bin may be fine
        if post_residual > 40 {
            score -= 15.0;
        }
    }

    // Lookahead: if next item fits the post-residual, reward this placement
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 20.0;
    } else if next_item_size > 0 && post_residual > 0 && (post_residual as u32) < next_item_size {
        score += 10.0; // creates a gap the next item cannot use
    }

    // Mean residual coupling: prefer bins with residual below mean (tighter bins)
    score += (mean_residual - bin_residual as f64).max(-30.0).min(30.0) * 0.2;

    // Slight preference early in stream to consolidate
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - progress) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strong base weight on post residual (tight fits preferred)
    score += 0.9 * post_residual as f64;

    // 2-step lookahead: reward when next item fits the post residual exactly/well
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if next <= post_residual as f64 {
            // next item can follow: reward tighter chained fit
            let chain_gap = post_residual as f64 - next;
            score -= 6.0 * (1.0 - chain_gap / cap);
            if chain_gap == 0.0 {
                score -= 12.0; // perfect 2-chain
            }
        } else {
            // next item cannot follow: penalize dead space relative to next item
            score += 0.35 * (next - post_residual as f64);
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score += 0.25 * (mean_residual - post_residual as f64);

    // Last-chance bin bonus: if only this bin fits, strongly favor using it
    if fitting_bins_count == 1 && post_residual <= bin_residual {
        score -= 15.0;
    }

    // Penalize leaving tiny unusable slivers (dead space) unless near-full
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Perfect closure reward
    if post_residual == 0 {
        score -= 20.0;
    }

    // Late in stream: be more aggressive at closing bins tightly
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.15 * progress;

    // New-bin candidate: only attractive when open bins are crowded
    if bin_residual == bin_capacity {
        let crowded = if open_bins_count > 0 { mean_residual / cap } else { 1.0 };
        score = cap * (1.0 - 0.5 * (1.0 - crowded)) + 5.0;
        // discourage opening new bin if a good chain exists elsewhere
        if next_item_size > 0 && post_residual as f64 >= next_item_size as f64 {
            score += 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small post-residuals are wasteful unless perfectly tight.
    let t = step_index as f64 / (total_items as f64).max(1.0);
    if post_residual > 0 {
        let waste = post_residual as f64 / bin_capacity as f64;
        score += 12.0 * waste * waste * (0.5 + t);
    } else {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Lookahead: reward if next item can still fit in the post-residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        score -= 15.0 * (1.0 - gap / bin_capacity as f64);
    } else if next_item_size > post_residual {
        // Post-residual too small for the lookahead item: mild penalty.
        score += 6.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Prefer bins whose residual is below the mean (consolidating emptier space usage).
    let diff = mean_residual - bin_residual as f64;
    score -= 0.3 * diff;

    // Crowding: with many open bins, favor filling existing ones over opening new.
    if open_bins_count > 4 {
        score -= 0.5 * open_bins_count as f64;
    }

    // New-bin candidate: penalize opening a new bin, more so late in the stream,
    // unless the item is large and the fit would be very tight.
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        score += 25.0 + 30.0 * t - 20.0 * tightness;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 10.0; // new bin can host both current and next item
        }
    }

    // Reward near-tight fits (post_residual in a small band) to leave usable gaps.
    if post_residual >= 1 && post_residual <= 10 {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64 / cap;
    let it = item_size as f64 / cap;
    let ni = next_item_size as f64 / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let base = pr.powf(1.0 + 1.5 * t) - 0.8 * pr * t * (1.0 - t);

    // Reward tight fits, modulated by progress
    let fit_reward = -2.0 * (1.0 - pr).powi(3) * (0.5 + t);

    // Dead-space penalty: small unusable residuals, stronger late in stream
    let dead = 1.5 * (pr * (1.0 - pr)).powi(2) * (0.5 + t);

    // Lookahead coupling: favor bins whose post_residual matches next item
    let look = if ni > 0.0 {
        let d = (pr - ni / cap).abs();
        -1.0 * (1.0 - d.min(1.0)).powi(2)
    } else {
        0.0
    };

    // Last-chance bonus: penalize opening new bin when this is the only fitting bin
    let last_chance = if fitting_bins_count == 1 {
        -1.2 * (1.0 - pr)
    } else {
        0.0
    };

    // Mild penalty for opening new bins when many are open
    let new_bin = if bin_residual == bin_capacity {
        0.6 + 0.8 * t + 0.02 * open_bins_count as f64
    } else {
        0.0
    };

    base + fit_reward + dead + look + last_chance + new_bin
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: classify post_residual by capacity fractions.
    let c = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / c; // 0..1

    // Penalize dead space in fine-grained harmonic bands.
    // Residuals in (0, 10] are nearly useless; residuals near 0 are perfect fits.
    if post == 0 {
        score -= 50.0; // perfect fit: strongly reward
    } else if post < 10 {
        score += 40.0; // tiny dead space: heavily penalize
    } else if post <= 20 {
        score += 15.0;
    } else if post <= 30 {
        score += 5.0;
    }

    // Harmonic quarter classes: reward leaving space that matches common item sizes.
    // Items are 1..100; leaving ~50 or ~25 residual keeps future harmonic splits viable.
    let q = post_residual / (bin_capacity / 4);
    match q {
        0 => score += 8.0,
        1 => score -= 4.0, // ~25..50 residual: versatile
        2 => score -= 6.0, // ~50 residual: half-capacity, very reusable
        3 => score -= 2.0,
        _ => {}
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // reward proportionally to how well next item fills leftover
            let fill = next_item_size as f64 / post.max(1.0);
            score -= 20.0 * fill;
        } else {
            // next item won't fit here: slight penalty proportional to overflow
            let over = (next_item_size - post_residual) as f64;
            score += 5.0 * (over / c).min(1.0);
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins fit poorly.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin; reduced late in stream or when bins are fragmented
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut open_cost = 55.0;
        // if mean residual is small (fragmented bins), opening is more attractive
        open_cost -= 0.3 * mean_residual;
        open_cost -= 10.0 * progress;
        score += open_cost;
    } else {
        // using an existing bin: mild reward scaled by how much it consolidates
        score -= 10.0;
        // prefer bins tighter than average (best-fit flavor)
        score += 0.2 * (mean_residual - bin_residual as f64);
    }

    // Stream-phase modulation: early on, be conservative about tight fills
    // (keep options open); later, pack aggressively.
    if total_items > 0 {
        let t = step_index as f64 / total_items as f64;
        if t < 0.3 {
            score += 0.05 * post; // early: slightly punish wasting big residuals
        } else {
            score -= 0.05 * post; // late: reward tight fills more
        }
    }

    // Modulo-flavored bonus: residuals divisible by common item sizes (10/20/25)
    // are more reusable.
    if post_residual > 0 && (post_residual % 10 == 0 || post_residual % 25 == 0) {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A post_residual below the minimum item size (1) is impossible, but gaps
    // smaller than a typical useful chunk create dead space.
    if post_residual > 0 {
        // Dead-space severity grows super-linearly as the gap shrinks.
        let gap = post_residual as f64;
        let dead_threshold = 12.0; // gaps <= this are largely wasted
        if gap < dead_threshold {
            let severity = (dead_threshold - gap) / dead_threshold;
            score += 40.0 * severity * severity;
        }
        // Perfect fit bonus: exact fill eliminates all dead space.
        if post_residual == 0 {
            score -= 25.0;
        }
    }

    // Lookahead coupling: if the next item fits exactly in the post_residual,
    // strongly reward this placement (perfect chained fit).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    }
    // Penalize if post_residual cannot fit the next item (creates stranded gap).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // Open-bins pressure: discourage spreading across many open bins when
    // residuals are already fragmented; encourage closing bins out.
    let open_pressure = open_bins_count as f64;
    score += 0.5 * open_pressure;

    // Last-chance bin: if this is the only bin that fits, using it avoids
    // opening a new bin; reward it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // Mean residual coupling: bins with residual far below the mean are the
    // fragmented ones; placing there consolidates waste.
    let residual_f64 = bin_residual as f64;
    if mean_residual > 0.0 && residual_f64 < mean_residual {
        score -= 0.3 * (mean_residual - residual_f64);
    }

    // Slight preference for tighter fits as the stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
