    score += (post_residual as f64 / bin_capacity as f64) * 30.0;

    // Penalize large dead space relative to the smallest plausible future item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable slivers are wasted space
    }

    // Last-chance bin: strongly reward using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // Lookahead: if the next item fits into the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0 + 0.5 * next_item_size as f64;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here anyway; slight penalty for fragmenting.
        score += 5.0;
    }

    // Reward filling bins that are already mostly full (consolidation).
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * 15.0;

    // Time horizon: early in the stream, be more willing to open new bins (explore);
    // late in the stream, squeeze into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let new_bin_bonus = 40.0 * (1.0 - progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive early, less so late; penalize opening
        // when good fits exist among open bins.
        score = bin_capacity as f64 - new_bin_bonus;
        if fitting_bins_count > 0 && post_residual as f64 <= mean_residual {
            score += 30.0; // open bins offer decent fits, discourage new bin
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // future items may be large; a fresh bin is useful
        }
    }

    // Global balance: prefer bins whose residual is near the mean (avoid outlier bins).
    score += (bin_residual as f64 - mean_residual).abs() * 0.3;

    // Many open bins: encourage closing them out by filling.
    score -= (open_bins_count as f64).ln().max(0.0) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual

    // Base: minimize post residual (tight packing)
    let mut score = pr as f64;

    // Smooth non-linear coupling: penalize large dead space more as stream progresses
    let dead_penalty = (x * x) * cap * (0.5 + 1.5 * progress);
    score += dead_penalty;

    // Reward near-perfect fits via smooth gaussian-like bump around x ~ 0
    let fit_bonus = -20.0 * (-(x * x) / 0.005).exp();
    score += fit_bonus;

    // Interact post residual with mean residual: prefer bins deviating below mean late in stream
    let dev = (mean_residual - pr) / cap;
    score += 10.0 * dev * (0.3 + progress);

    // Last-chance bonus: smooth reward when few fitting bins
    if fitting_bins_count > 0 {
        let scarcity = 1.0 / fitting_bins_count as f64;
        score -= 15.0 * scarcity * (1.0 - x);
    }

    // Lookahead: reward leaving space usable by next item (smooth kernel)
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let slack = (x * cap - n).abs();
        let usable = (-(slack * slack) / 400.0).exp();
        score -= 12.0 * usable * (0.5 + 0.5 * progress);
    }

    // Mild penalty for proliferating open bins, stronger early
    score += open_bins_count as f64 * (2.0 * (1.0 - progress));

    // New-bin candidate: penalize opening a new bin unless post residual is large (item is big)
    if bin_residual == bin_capacity {
        let big_item = item_size as f64 / cap;
        score += 30.0 * (1.0 - big_item) * (1.0 - big_item) * (1.0 + progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo 10 define "usable" classes.
    // Residuals that are multiples of 10 or small (<=10) are reusable; penalize odd residues.
    let post = post_residual;
    let residue_class = post % 10;
    if residue_class == 0 {
        score -= 15.0; // perfectly harmonic leftover
    } else if residue_class <= 3 {
        score += 5.0 + residue_class as f64; // near-dead space
    } else {
        score += (10 - residue_class) as f64 * 0.5; // mildly awkward class
    }

    // Integer-division thresholds: post_residual / 10 bucket count.
    let bucket = post / 10;
    score -= bucket as f64 * 2.0; // larger usable chunks preferred

    // Harmonic coupling with next item: if next item fits exactly into post_residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 40.0;
        } else if next_item_size <= post {
            let next_class = next_item_size % 10;
            // reward when next item's harmonic class matches post_residual's class
            if next_class == residue_class {
                score -= 12.0;
            }
            score -= (post - next_item_size) as f64 * 0.3;
        } else {
            // next item won't fit here; penalize holding a large unusable residual
            score += (next_item_size - post).min(20) as f64 * 0.4;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        score += (fitting_bins_count as f64 - 1.0) * 1.5; // prefer tightest among many
    }

    // New-bin candidate: neutral-ish baseline; discourage early in stream, allow late.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 - 30.0 * progress;
        // opening a new bin is fine if current best fit leaves a bad harmonic class
        if residue_class > 5 && post > 0 {
            score -= 10.0;
        }
    }

    // Mild pull toward bins below mean residual (tighter bins first).
    score -= (mean_residual - bin_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold the smallest
    // plausible item (1..100 range, but tiny gaps under ~15 are near-useless)
    // are heavily penalized. A perfect fit (post_residual == 0) is ideal.
    if post_residual > 0 && post_residual < 15 {
        score += 40.0 + (15 - post_residual) as f64 * 3.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual <= 5 {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // this placement is excellent; penalize if next item overshoots the gap.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if next_item_size > post_residual && next_item_size <= bin_residual {
            score += 10.0; // next item would need another bin anyway
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid pushing us
    // toward opening a new bin unless the fit is truly bad.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins (penalize opening new ones); scale with count.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 18.0 + open_bins_count as f64 * 1.5 - progress * 5.0;
    } else {
        score -= (open_bins_count.min(20)) as f64 * 0.8;
    }

    // Prefer bins with residual below the mean (tighter bins fill first),
    // keeping looser bins available for larger future items.
    score += (bin_residual as f64 - mean_residual) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
