pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let fit_norm = pr / cap;

    // Base: prefer tight fits, with a non-linear penalty on mid-size residuals.
    let mut score = pr as f64 * (1.0 + 0.6 * fit_norm * (1.0 - fit_norm) * 4.0);

    // Smooth polynomial coupling with stream progress:
    // early on, tolerate loose fits (keep bins flexible); late, punish dead space quadratically.
    let flexibility = 1.0 - progress;
    score += (pr * pr) / cap * (0.5 + 1.5 * progress * progress);

    // Reward filling bins almost exactly, stronger as the stream progresses.
    let tightness = 1.0 - fit_norm;
    score -= (cap - pr) * 0.25 * (1.0 - tightness * tightness) * (0.5 + progress);

    // Last-chance bonus: strongly favor the only bin that fits, smoothly scaled.
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 - progress * 0.5);
    }

    // Lookahead coupling: if next item fits the post-residual, reward; else mild penalty.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= 8.0 * (1.0 - (pr - nxt) / cap) * (1.0 - progress * 0.5);
        } else {
            score += 4.0 * (nxt - pr) / cap;
        }
    }

    // Prefer consolidating into fewer bins when many are open; smooth in open count.
    score -= (open_bins_count as f64).ln().max(0.0) * 2.0 * (1.0 - fit_norm);

    // New-bin candidate: penalize opening a bin unless the item is large relative to capacity
    // or the stream is early (flexibility phase).
    if bin_residual == bin_capacity {
        let size_frac = item_size as f64 / cap;
        score += 25.0 - 20.0 * size_frac * size_frac - 15.0 * flexibility;
        score += 5.0 * (mean_residual / cap).min(1.0);
    }

    // Mild penalty for deviating far from mean residual, encouraging balance.
    score += ((pr - mean_residual) / cap).abs() * 3.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo small divisors
    let r = post_residual;
    let mod10 = (r % 10) as f64;
    let mod25 = (r % 25) as f64;

    // Penalize post-residuals in "dead" harmonic classes (hard to fill later)
    // Small nonzero residues (1..10) are nearly unusable -> strong penalty.
    if r > 0 {
        if r < 10 {
            score += 60.0 - 3.0 * r as f64;
        } else {
            // residue 0 mod 10 is ideal; others slightly penalized
            score += mod10 * 0.8;
            score += mod25 * 0.15;
        }
    } else {
        // Perfect fill: big reward
        score -= 120.0;
    }

    // Coupling with next item: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == r {
            score -= 90.0;
        } else if next_item_size <= r {
            let nmod = next_item_size % 10;
            let tight = (r - next_item_size) as f64;
            score += tight * 0.6;
            if nmod == 0 { score -= 8.0; }
        } else {
            // next item won't fit here: mild penalty scaled by overshoot class
            let over = (next_item_size - r) % 20;
            score += over as f64 * 0.3;
        }
    } else {
        // Last item: prefer tightest fit overall
        score += 0.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Progression: later in stream, consolidate more aggressively
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 10.0 * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: penalize opening a new bin unless current bin would be badly fragmented
    if bin_residual == bin_capacity {
        // baseline for fresh bin: score by what it leaves for the future
        score = 100.0 - item_size as f64 * 0.4;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0;
        }
    }

    // Prefer bins with residual below mean (tighter bins)
    score += (post_residual as f64 - mean_residual) * 0.25;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space heavily (strict dead-space avoidance)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 8.0;
    }

    // Reward near-perfect fits
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward leaving space usable for the lookahead item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Pressure from number of open bins: prefer filling existing bins when many are open
    let open_pressure = open_bins_count as f64 * 0.5;
    if bin_residual != bin_capacity {
        score -= open_pressure.min(10.0);
    }

    // Prefer bins with residual close to mean residual (balanced packing)
    score += ((bin_residual as f64 - mean_residual) / 10.0).abs().min(5.0);

    // Late in the stream, be more conservative about opening new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact chain fit (post_residual == next_item_size)
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        score -= 40.0 * (1.0 - diff / (bin_capacity as f64)).max(0.0).powi(3);

        // Penalize post_residual that is small but unusable (dead space < next item)
        if post_residual < next_item_size {
            score += 12.0 * (1.0 - post_residual as f64 / 50.0).max(0.0);
        }
    } else {
        // Last item: prefer tightest packing
        score -= 20.0;
    }

    // Penalize creating dead space below the minimum item size (unusable gap)
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Relative to mean residual: prefer bins tighter than average
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Discourage opening new bins when reasonable fits exist, unless residual is huge waste
    if bin_residual == bin_capacity {
        score += 15.0;
        // Opening a new bin is attractive only if it enables a perfect 2-chain
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 45.0;
        }
    }

    // Late in stream: consolidate harder
    let progress = step_index as f64 / total_items as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize small post_residual nonlinearly.
    if post_residual > 0 {
        score -= 12.0 * (1.0 - (post_residual as f64 / bin_capacity as f64)).powi(6);
    } else {
        score -= 30.0; // perfect fit bonus
    }

    // Penalize dead space that no future item (min size 1, typical small) can use.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead coupling: if the next item fits the post residual exactly, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 6.0 * (1.0 - slack / bin_capacity as f64).powi(3);
        } else {
            score += 5.0; // next item won't fit here anyway
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        // With many fitting bins, prefer tighter fits; mild penalty to spread risk.
        score += 2.0 * (fitting_bins_count.min(10) as f64).ln();
    }

    // Time horizon: late in stream, prefer filling existing bins aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Global state: many open bins with high mean residual -> discourage spreading.
    if open_bins_count > 0 {
        let spread = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * spread;
        score += 0.3 * open_bins_count as f64 * (1.0 - progress);
    }

    // New-bin candidate: keep it competitive only when current bin fit is poor.
    if bin_residual == bin_capacity {
        // Empty bin baseline: slightly worse than a decent fit, better than awful fits.
        score += 14.0 - 6.0 * progress;
        if item_size > bin_capacity * 3 / 4 {
            score -= 10.0; // huge item: fresh bin is fine
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Normalized post-residual and its smooth polynomial shaping
    let x = pr / cap; // in [0,1]
    let base = pr;

    // Smooth non-linear coupling with stream progress:
    // early stream: prefer tight fills less aggressively; late stream: penalize leftover space more
    let poly = x * x * (3.0 - 2.0 * x); // smoothstep in [0,1]
    let progress_term = (1.0 + progress) * poly * cap * 0.5;

    // Waste penalty: quadratic in dead space, amplified when few bins fit the item
    let scarcity = 1.0 + 2.0 / (fitting_bins_count as f64);
    let waste = (x * x) * cap * 0.3 * scarcity;

    // Reward good fit: small post_residual relative to item size
    let fit_reward = -(item_size as f64) * (1.0 - x) * 0.8;

    // Lookahead coupling: if next item fits the post-residual smoothly, reward this bin
    let lookahead = if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap >= 0.0 {
            -10.0 * (1.0 - (gap / cap)) * (1.0 - progress)
        } else {
            5.0 * (-gap / cap) * (1.0 + progress)
        }
    } else {
        0.0
    };

    // Slight preference to keep mean residual balanced (avoid many near-empty bins)
    let balance = ((pr - mean_residual) / cap) * 2.0;

    let score = base + progress_term + waste + fit_reward + lookahead + balance;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: reward residuals that lie in
    // "friendly" classes likely to be filled by future items (multiples of
    // common item sizes 10, 20, 25, 50).
    let pr = post_residual;
    let harmonic_bonus = if pr == 0 {
        -30.0 // perfect fill is best
    } else if pr % 50 == 0 {
        -12.0
    } else if pr % 25 == 0 {
        -8.0
    } else if pr % 20 == 0 {
        -6.0
    } else if pr % 10 == 0 {
        -4.0
    } else {
        0.0
    };
    score += harmonic_bonus as f64;

    // Dead space penalty: residuals too small for the smallest plausible item
    // (<=10) are worthless.
    if pr > 0 && pr < 10 {
        score += 25.0;
    }

    // Lookahead coupling: does the next item fit exactly / well into the
    // post residual?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 20.0; // perfect chaining
        } else if next_item_size <= pr && (pr - next_item_size) < 10 {
            score -= 10.0; // near-perfect chain
        } else if next_item_size > pr {
            score += 6.0; // next item can't reuse this bin's remainder
        }
        // Harmonic class match between next item and post residual
        if pr >= next_item_size && pr % next_item_size.max(1) == 0 {
            score -= 5.0;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits,
    // avoiding opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate logic: an empty bin is only attractive when current
    // bins are crowded or the fit here is bad.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / cap;
        // penalize opening new bins under low pressure
        score += 40.0 * (1.0 - pressure);
        // but reward opening a new bin when the item is large relative to
        // typical residuals
        if item_size as f64 > mean_residual {
            score -= 10.0;
        }
    }

    // Tight fit reward: relative fill fraction of this placement.
    let fill = item_size as f64 / cap;
    score -= 10.0 * fill;

    // Late-stream consolidation: as the stream progresses, prefer packing
    // into existing bins to close them out.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 8.0 * progress * (post_residual as f64 / cap);

    // Penalize bins that deviate strongly from the mean residual (keeps
    // residual distribution homogeneous, easier future packing).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Penalize moderate dead space softly, reward near-perfect fits.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 20 {
        score += 8.0;
    }

    // Open-bin pressure: prefer denser packing when many bins are open.
    let pressure = (open_bins_count as f64).ln() * 3.0;
    score += pressure * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: reward leaving room for the next item, penalize blocking it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 10.0;
        }
    }

    // New-bin candidate: only attractive when open bins have poor residuals
    // relative to the item, otherwise keep it unattractive.
    if bin_residual == bin_capacity {
        score += 15.0 + mean_residual * 0.3;
        if fitting_bins_count > 0 && mean_residual > item_size as f64 {
            score += 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward post_residual that closely matches next_item_size.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 60.0 * (1.0 - gap / bin_capacity as f64).max(0.0);
    } else if next_item_size > 0 {
        // next item cannot fit here; penalize proportionally to overshoot of dead space.
        score += 15.0 + 0.3 * (next_item_size - post_residual) as f64;
    }

    // Strong reward for near-perfect fills (small post_residual = tight fit).
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 10 {
        score -= 40.0;
    }

    // Relative-to-mean coupling: bins with residual far below mean are precious tight fits;
    // prefer placing into them rather than leaving them as outliers.
    let res_f = post_residual as f64;
    if res_f < mean_residual {
        score -= 0.5 * (mean_residual - res_f);
    } else {
        score += 0.3 * (res_f - mean_residual);
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Discard new-bin candidate unless current fit is poor: penalize empty-bin choice
    // mildly so open bins with decent fits win, but keep it viable when post_residual is tiny.
    if bin_residual == bin_capacity {
        score += 25.0;
        if post_residual > 50 {
            score += 20.0; // opening a bin for a tiny item wastes capacity
        }
    }

    // Late in the stream, close out bins aggressively (consolidation matters more).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - res_f / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize post_residual quadratically relative to capacity.
    let frac_post = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * frac_post * frac_post;

    // Reward perfect fit strongly.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_quality = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= 30.0 * chain_quality;
    } else if next_item_size > 0 && post_residual > 0 {
        // Dead space that next item cannot use: penalize, scaled by how "wasted" it is.
        score += 10.0 * frac_post;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: opening a new bin should be discouraged unless it's early
    // in the stream or current bins have poor average residual.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mean_fit_gap = (mean_residual - item_size as f64).abs();
        // Penalize new bins late in the stream; allow more freely early.
        score += 20.0 + 80.0 * progress;
        // But if mean residual is far from item size, opening fresh bin is attractive.
        score -= 0.5 * mean_fit_gap;
        // If many bins open, opening another is cheaper than fragmenting.
        score -= 1.0 * open_bins_count as f64;
        // If next item is large and would need a fresh bin anyway, plan ahead.
        if next_item_size > item_size && post_residual == 0 {
            score -= 15.0;
        }
    }

    // Prefer bins whose residual deviates strongly from mean (consolidate outliers).
    let deviation = (bin_residual as f64 - mean_residual).abs();
    score -= 0.2 * deviation;

    // Mild preference for filling fuller bins as stream progresses.
    let fill_ratio = 1.0 - bin_residual as f64 / bin_capacity as f64;
    score -= 10.0 * fill_ratio * (step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_post = post / cap;

    // Base: tight fit preferred, with non-linear decay on wasted space
    let mut score = post + 8.0 * norm_post * norm_post * cap;

    // Stream-progress coupling: later in stream, tolerate larger residuals less
    let prog_coupling = 6.0 * norm_post * progress * (1.0 + progress);
    score += prog_coupling * cap * 0.1;

    // Reward tight fits more strongly as stream progresses (smooth cubic in progress)
    score -= 10.0 * (1.0 - norm_post) * (1.0 - norm_post) * (0.5 + progress);

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    }

    // Penalize when many bins fit (avoid fragmenting choice bins)
    if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64 - 1.0).sqrt();
    }

    // Lookahead: if next item fits the post-residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= post {
        score -= 12.0 * (1.0 - post / cap);
    } else if next_item_size > 0 {
        // next item won't fit: penalize dead space proportionally
        score += 4.0 * norm_post * (next_item_size as f64 / cap);
    }

    // Mean residual context: prefer bins below mean residual (tighter than average)
    score += 2.0 * (mean_residual - post) / cap * 10.0;

    // Mild penalty for spreading across many open bins late in the stream
    score += 0.5 * (open_bins_count as f64).ln() * (1.0 - progress);

    // New-bin candidate handling: opening a new bin is only attractive when
    // residuals are fragmented and the item is large
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / cap;
        score = post + 20.0 * (1.0 - fragmentation) - 18.0 * (item_size as f64 / cap) * (0.5 + progress);
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space into coarse bands
    // (dead-space classes). Small post_residual = tight, efficient packing.
    let cls = post_residual / 10; // 0..10 harmonic class
    let class_penalty = match cls {
        0 => -60.0,                       // near-perfect fit: reward strongly
        1 => -35.0,                       // very tight
        2 => -15.0,
        3 => 0.0,
        4 => 10.0,
        5 => 22.0,                        // half-empty: mediocre
        6 => 30.0,
        7 => 40.0,
        8 => 52.0,
        9 => 66.0,
        _ => 80.0,                        // essentially untouched bin
    };
    score += class_penalty;

    // Parity / modulo structure of post_residual: leftovers that are multiples
    // of small common sizes (10, 20, 25) are reusable; odd remainders are dead.
    let mod10 = post_residual % 10;
    score += mod10 as f64 * 1.5;
    if post_residual % 20 == 0 && post_residual > 0 { score -= 12.0; }
    if post_residual % 25 == 0 && post_residual > 0 { score -= 8.0; }

    // Lookahead coupling: does next_item_size fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Chain-friendly: reward proportional to how well next item fills remainder
            let next_fit = (post_residual - next_item_size) as f64;
            score -= 25.0 - next_fit * 0.4;
        } else {
            // Next item cannot use this residual: penalize proportional to gap
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    } else {
        // Last item: just minimize post_residual (already base score)
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // especially when residual is tight.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
        if post_residual < 10 { score -= 20.0; }
    }

    // New-bin candidate handling: an empty bin has high residual; discourage
    // opening a new bin unless current bins would leave large dead space.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 55.0 - 40.0 * progress;
        // If many bins are already open, prefer consolidating into them.
        score += (open_bins_count as f64).min(10.0) * 3.0;
        // If next item is large, a fresh bin is more attractive.
        if next_item_size > 60 { score -= 30.0; }
    }

    // Mean-residual coupling: placing into a bin below mean residual keeps
    // the residual distribution balanced (avoids many half-full stragglers).
    if (bin_residual as f64) < mean_residual {
        score -= 8.0;
    } else {
        score += 4.0;
    }

    // Exact fill bonus.
    if post_residual == 0 { score -= 100.0; }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< 10, min item size)
    // are pure waste — penalize heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Gaps too small for the next item are risky dead space.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 10 {
        score -= 40.0;
    }

    // Last chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bins pressure: with many open bins, prefer reusing existing bins
    // over opening new ones; with few bins, consolidation is fine.
    score += (open_bins_count as f64).sqrt() * 2.0;

    // New-bin candidate: make it attractive only when the item fits poorly
    // everywhere else (large post_residual in existing bins) — otherwise
    // discourage opening a new bin.
    if bin_residual == bin_capacity {
        score += 45.0 + mean_residual * 0.5;
        // Late in the stream, new bins are cheaper than wasted capacity.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 20.0;
        // If next item is large, a fresh bin is valuable.
        if next_item_size >= 60 {
            score -= 15.0;
        }
    }

    // Slight preference for bins whose residual is close to mean (balanced use).
    score += ((bin_residual as f64) - mean_residual).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base preference: tighter post-fit residual (best-fit core).
    score -= 0.5 * (bin_residual as f64 - post_residual as f64);

    // 2-step lookahead: strongly reward when the next item exactly fills post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect chain: this bin becomes exactly full
        } else if next_item_size < post_residual {
            let gap = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - gap / bin_capacity as f64).powi(3);
        } else {
            // next item cannot follow into this bin: penalize leftover dead space
            score += 0.6 * post_residual as f64;
        }
    }

    // Relative-to-mean coupling: bins with residual far above mean are less precious;
    // prefer consuming bins that are already tight relative to the fleet.
    let res = bin_residual as f64;
    if mean_residual > 0.0 {
        let rel = res / mean_residual;
        score += 8.0 * (rel - 1.0);
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible (large post_residual).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 0.2 * (post_residual as f64).max(0.0);
    }

    // New-bin candidate: only attractive when it enables a perfect future chain
    // or when all open bins fit poorly. Penalize generic new-bin opening.
    if bin_residual == bin_capacity {
        score += 30.0;
        if next_item_size > 0 && (next_item_size + item_size) as f64 >= bin_capacity as f64 {
            score -= 45.0; // opening a fresh bin to pack item + next perfectly
        }
    }

    // Late-stream tightening: waste matters more near the end.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 0.3 * post_residual as f64;

    // Mild penalty for leaving residuals too small to be useful (dead space < 10).
    if post_residual > 0 && post_residual < 10 {
        score -= 5.0; // actually good: nearly-full bin
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item nearly fills the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fill_ratio;

    // Penalize creating tiny dead space that few future items can use.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }
    if post_residual >= 10 && post_residual <= 20 {
        score -= 4.0; // usable window for mid-size items
    }

    // Lookahead coupling: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
            let slack = (post_residual - next_item_size) as f64;
            score -= 3.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            score += 2.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when no open bin
    // fits well (large post_residual everywhere relative to item).
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Penalize new bins mildly; less penalty when open bins are crowded late in stream.
        score += 8.0 - 6.0 * pressure - 4.0 * progress;
        if open_bins_count == 0 {
            score -= 100.0; // must open the first bin
        }
    } else {
        // Slight preference for bins below mean residual (consolidating fuller bins).
        if (bin_residual as f64) < mean_residual {
            score -= 2.0;
        }
    }

    // Late-stream consolidation: as stream progresses, prefer filling existing bins harder.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * fill_ratio;

    // Prefer bins among many fitting candidates that leave the most balanced residual.
    if fitting_bins_count > 1 {
        score += 0.5 * (fitting_bins_count as f64).ln();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tightness: reward small post_residual non-linearly (quartic decay of waste).
    let tight = 1.0 - (post_residual as f64 / cap);
    score -= 30.0 * tight * tight * tight * tight;

    // Perfect-ish fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    }

    // Lookahead coupling: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64 / cap;
        score -= 8.0 * (1.0 - slack * slack);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Penalize dead space that blocks the next item, scaled by progress.
        let dead = (next_item_size - post_residual) as f64 / cap;
        score += 10.0 * dead * (1.0 + progress);
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0 + 15.0 * progress;
    }

    // New-bin candidate: penalize opening a bin when good fits exist, less so early.
    if bin_residual == bin_capacity {
        score += 15.0 + 10.0 * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 30.0; // no alternative, must open
        }
    }

    // Mild preference for fuller bins relative to mean residual across open bins.
    score += 0.15 * (post_residual as f64 - mean_residual).max(-30.0).min(30.0);

    // Smooth progress coupling: later in stream, consolidate more aggressively.
    score *= 1.0 - 0.2 * progress * (1.0 - tight);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes of post_residual: residues near multiples of capacity fractions
    // are "usable" dead space (small items can fill them); large odd residues are waste.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class 1: post_residual in [0, 10] -> near-perfect fit, strong reward
    if post_residual <= 10 {
        score -= 30.0;
    }
    // Class 2: post_residual divisible by 10 (harmonic decade classes) -> easy to fill
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }
    // Class 3: awkward dead space in (10, 25) -> penalize (too small for most items >=10)
    if post_residual > 10 && post_residual < 25 {
        score += 18.0;
    }
    // Class 4: mid-range residue (25..50): usable by small/medium items
    if post_residual >= 25 && post_residual < 50 {
        score -= 4.0;
    }
    // Integer-division harmonic: post_residual / (item_size) quotient classes
    let q = post_residual / item_size.max(1);
    if q >= 1 {
        score -= 5.0 * q as f64; // bin can hold another item of same size later
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            score -= 6.0;
        } else {
            score += 10.0; // next item won't fit here; residue likely wasted
        }
    }

    // Last chance: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin wastes the residual of all open bins.
    if bin_residual == bin_capacity {
        // base cost of a fresh bin
        score += cap;
        // prefer new bin only when open bins are nearly full / few fit
        score -= 0.5 * mean_residual;
        if fitting_bins_count == 0 {
            score -= cap; // no alternative: new bin is fine
        } else if fitting_bins_count == 1 && post_residual < 15 {
            // perfect fit into the single existing bin beats a new bin
            score += 20.0;
        }
        // late in stream, opening bins is less costly (no need to reuse)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
    }

    // Slight preference for fuller bins (tie-break by mean residual deviation)
    score -= (cap - mean_residual).max(0.0) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead space avoidance: penalize unusable small gaps left behind.
    if post_residual > 0 {
        // A residual gap is "dead" if it's too small to fit any plausible future item.
        // Treat gaps below a small-item threshold as wasted space, with superlinear penalty.
        let dead_threshold = 10.0_f64.min(next_item_size.max(1) as f64);
        if (post_residual as f64) < dead_threshold {
            score += 40.0 + 8.0 * (dead_threshold - post_residual as f64);
        }
        // Moderate gaps (barely above small-item size) are also risky.
        if post_residual >= 10 && post_residual < 20 {
            score += 6.0;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // Reward tight fits: small post_residual relative to item size.
    let tightness = item_size as f64 / (bin_residual as f64).max(1.0);
    score -= 25.0 * tightness;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open bins pressure: when many bins are open, prefer filling existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * (2.0 + 3.0 * progress);

    // Lookahead: if the next item fits exactly in the post residual, reward heavily.
    if next_item_size > 0 && next_item_size as f64 == post_residual as f64 {
        score -= 30.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item can't use the leftover gap: penalize.
        score += 5.0;
    }

    // Prefer bins whose residual is below the mean residual (denser bins).
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    } else {
        score += 2.0;
    }

    // New-bin candidate: only attractive when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 55.0;
        // But if current bin would leave a very large dead gap, opening new bin is better.
        if post_residual >= 30 && post_residual < 50 {
            score -= 25.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: zero post-residual is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post-residual exactly matches the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual >= next_item_size {
            // leftover after also placing next item: tighter is better
            let two_step_left = post_residual - next_item_size;
            score -= 200.0 * (1.0 - two_step_left as f64 / bin_capacity as f64);
        } else {
            // next item cannot follow: penalize proportionally to wasted space
            score += 50.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    }

    // Relative to mean residual: prefer bins already tight (small residual) when fit is good.
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    // (i.e., item is large relative to residuals) or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fits = if fitting_bins_count <= 1 { 1.0 } else { 0.0 };
        score = 150.0 + 200.0 * (1.0 - poor_fits) - 100.0 * (1.0 - progress) - (item_size as f64 - post_residual as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: residual too small for the smallest plausible future item
    if post_residual < next_item_size && post_residual > 0 {
        score += 6.0 + 0.15 * post_residual as f64;
    }

    // Lookahead: reward bins whose post_residual can still fit the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
            // bonus if post residual is a near-perfect match for the next item
            let slack = (post_residual - next_item_size) as f64;
            if slack <= 10.0 { score -= 5.0; }
        } else if next_item_size > bin_residual {
            // next item won't fit anywhere here anyway; mild bonus for using this bin
            score -= 2.0;
        } else {
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Many open bins: prefer consolidating into existing bins
    let pressure = open_bins_count as f64 / (1.0 + step_index as f64);
    if bin_residual != bin_capacity {
        score -= 2.0 * pressure.min(5.0);
    }

    // New-bin candidate: penalize opening a new bin unless current bin is very fragmented
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmented = mean_residual < item_size as f64 * 0.6;
        score += 25.0 - 10.0 * progress;
        if fragmented { score -= 20.0; }
        if fitting_bins_count == 0 { score -= 30.0; }
        // avoid new bin if mean residual across open bins is large
        score += 0.3 * mean_residual;
    }

    // Global residual alignment: prefer bins close to mean residual (keeps residuals uniform)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Slight preference for fuller bins over emptier ones
    score -= 0.05 * (bin_residual as f64);

    // Time-decay urgency: late in stream, be more conservative with new bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 3.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // later in the stream, tight fills (small post_residual) are rewarded more strongly.
    let tightness = 1.0 - (pr / cap).powf(2.0);
    score -= tightness * (8.0 + 22.0 * progress);

    // Penalize large dead space quadratically, damped early in the stream.
    let dead = (pr / cap).powi(3);
    score += dead * 30.0 * (0.35 + 0.65 * progress);

    // Reward perfect-ish fits even more via a smooth bump.
    let bump = (-(pr / cap - 0.05).powi(2) / 0.02).exp();
    score -= bump * 12.0 * (0.3 + 0.7 * progress);

    // Last-chance bin: strong discount to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (1.0 - progress * 0.5);
    }

    // Lookahead: if next item fits exactly in post_residual, reward heavily.
    if next_item_size > 0 {
        let diff = (pr - next_item_size as f64).abs();
        if pr >= next_item_size as f64 {
            score -= (1.0 - diff / cap) * 10.0;
        }
        // Penalize post_residual that is slightly too small for next item (wasted sliver).
        if pr > 0.0 && pr < next_item_size as f64 {
            score += (1.0 - pr / cap) * 6.0;
        }
    }

    // Mild pressure against scattering across many open bins mid-stream.
    let open_pressure = (open_bins_count as f64).ln() / (cap).ln();
    score += open_pressure * mean_residual * 0.02 * progress;

    // New-bin candidate: keep it moderately attractive early, less so late.
    if bin_residual == bin_capacity {
        score += 3.0 + 10.0 * progress - 6.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover lies in a "usable"
    // residue class (divisible into small future-friendly chunks) are favored.
    let pr = post_residual;
    if pr > 0 {
        // Class A: post_residual divisible by 10 -> highly reusable slots
        if pr % 10 == 0 {
            score -= 6.0;
        }
        // Class B: divisible by 5 -> moderately reusable
        else if pr % 5 == 0 {
            score -= 3.0;
        }
        // Class C: small prime-ish dead space (1..4) -> mild penalty
        if pr < 5 {
            score += 4.0;
        }
    } else {
        // Perfect fit: strong reward
        score -= 25.0;
    }

    // Integer-division thresholds: leftover large enough for the next item
    // is valuable; leftover just barely too small is dead space.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 + 0.05 * (post_residual - next_item_size) as f64;
        } else if post_residual > 0 {
            score += 3.0 + 0.10 * (next_item_size - post_residual) as f64;
        }
    }

    // Tightness reward: fraction of bin consumed by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 10.0 * fill * fill;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when nothing fits well
    // or current fit is very poor.
    if bin_residual == bin_capacity {
        let waste = post_residual as f64;
        if fitting_bins_count == 0 {
            score -= 20.0; // must open a new bin
        } else if waste > 40.0 && fill < 0.5 {
            score -= 5.0; // poor fits justify a fresh bin
        } else {
            score += 12.0; // prefer reusing an existing bin
        }
    }

    // Mean-residual coupling: penalize bins far from the mean residual
    // (encourages balanced depletion across open bins).
    score += 0.15 * ((bin_residual as f64 - mean_residual).abs());

    // Early stream: slight preference to keep bins homogeneous early on.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress < 0.3 && post_residual > 60 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item (1..=100 range,
    // but typical min item ~10) are pure waste -> hard penalty scaled by gap smallness.
    let dead_threshold: f64 = 10.0;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += 50.0 + (dead_threshold - post_residual as f64) * 5.0;
    }
    if post_residual == 0 {
        // Perfect fit: strongly reward.
        score -= 100.0;
    }

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 20.0 * tightness * tightness;

    // Penalize gaps that can't fit the known next item (lookahead coupling).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0;
    }
    // Reward if the leftover exactly accommodates the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, prefer consolidating into existing
    // bins (penalize the new-bin candidate, which has bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        score += 30.0 + 2.0 * open_bins_count as f64;
    } else {
        // Mild reward for using existing bins, stronger when bin count is high.
        score -= (1.0 + open_bins_count as f64).min(10.0);
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Mean-residual coupling: prefer bins whose residual is below mean (tighter bins),
    // penalize dumping into very loose bins when many bins are open.
    let dev = mean_residual - post_residual as f64;
    score += 0.3 * dev * (open_bins_count as f64).ln().max(1.0);

    // Early-stream: be slightly greedier about tight fits; late-stream: conserve bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * tightness * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when the next item fits the post residual exactly.
    if next_item_size > 0 {
        let diff = post_residual as i64 - next_item_size as i64;
        if diff == 0 {
            score -= 60.0; // perfect 2-step chain
        } else if diff > 0 {
            // next item fits: penalize leftover after both placements
            score -= 25.0 - (diff as f64).min(25.0) * 0.8;
        } else {
            // next item won't fit here: mild penalty scaled by wasted gap
            score += (-diff as f64) * 0.15;
        }
    }

    // Reward tight fits relative to current residual (avoid dead space).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 20.0;

    // Penalize small unusable post-residuals (dead space below min item size).
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive if it enables a good 2-step chain
    // or existing bins are all loose fits.
    if bin_residual == bin_capacity {
        let open_pressure = if open_bins_count == 0 { 0.0 } else { mean_residual / bin_capacity as f64 };
        if next_item_size > 0 && (post_residual as i64 - next_item_size as i64) == 0 {
            score -= 10.0; // fresh bin enables perfect chain
        }
        // discourage opening new bins when open bins have plenty of room
        score += 12.0 * (1.0 - open_pressure);
        if fitting_bins_count > 2 {
            score += 25.0; // plenty of alternatives exist
        }
    }

    // Late in the stream, consolidate into existing bins harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0 * (mean_residual - post_residual as f64).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Prefer tight fits: reward small post_residual relative to bin capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness;

    // Penalize dead space that is too small to be useful later (below min item size).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: strongly favor bins whose post_residual exactly fits the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; mild penalty proportional to leftover waste.
            score += 6.0 * (next_item_size as f64 - post_residual as f64) / 100.0;
        }
    }

    // Last-chance bin: avoid opening a new bin when this is the only fitting one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // open bins have poor fits (high mean residual relative to item).
    if bin_residual == bin_capacity {
        // Base cost of consuming a fresh bin.
        score += 55.0;
        // If existing bins are fragmented, a new bin becomes more attractive.
        let fragmentation = (mean_residual - item_size as f64).max(0.0) / bin_capacity as f64;
        score -= 45.0 * fragmentation;
        // Early in the stream, be more willing to open bins (future flexibility).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
        // If the next item is large and current bins are tight, prefer new bin.
        if next_item_size > 0 && next_item_size > mean_residual {
            score -= 15.0;
        }
    }

    // Slight preference for filling bins that are already heavily loaded
    // (consolidation reduces bin count over the stream).
    let load = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 5.0 * load * load;

    // Mild penalty for spreading across many open bins.
    score += 0.15 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, scaled smoothly by stream progress
    let mut score = pr * (1.0 + 0.5 * progress * progress);

    // Non-linear penalty for tiny dead space (unusable residual)
    score += 40.0 * (1.0 - norm_pr).powi(6);

    // Reward tight fits with a smooth cubic coupling of post_residual and progress
    score -= 30.0 * (1.0 - norm_pr).powi(2) * (1.0 - progress);

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    }

    // Lookahead: reward if next item fits in post residual (smooth interaction)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let snug = 1.0 - ((pr - nxt) / cap);
            score -= 12.0 * snug * snug;
        } else {
            score += 8.0 * (1.0 - progress);
        }
    }

    // Mild pressure toward consolidating bins when many are open
    score += 2.0 * (open_bins_count as f64).ln().max(0.0) * (1.0 - norm_pr);

    // New-bin candidate: penalize opening new bins unless residuals are tight
    if bin_residual == bin_capacity {
        let tightness = (mean_residual / cap).clamp(0.0, 1.0);
        score += 20.0 + 30.0 * tightness * (1.0 - progress) + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls into "usable"
    // classes (divisible into common small item sizes) are rewarded.
    let pr = post_residual;
    if pr > 0 {
        // reward residuals that are multiples of common item sizes
        let mut harmony = 0.0f64;
        for m in [10u32, 20, 25, 50].iter() {
            if pr % m == 0 {
                harmony += 6.0;
            }
        }
        if pr % 5 == 0 { harmony += 2.0; }
        score -= harmony;

        // penalize tiny awkward residuals (dead space)
        if pr < 10 {
            score += 12.0 * (10.0 - pr as f64);
        }
    } else {
        // perfect fit: strong reward
        score -= 40.0;
    }

    // Fraction-of-capacity class of post_residual
    let frac = post_residual as f64 / cap;
    if frac > 0.0 && frac < 0.1 {
        score += 15.0; // nearly-dead bin
    } else if frac >= 0.5 {
        score -= 8.0; // half-full or more residual still useful
    }

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size < pr {
            score -= 4.0 + (pr - next_item_size) as f64 * 0.05;
        } else {
            // next item won't fit here; slight penalty proportional to gap
            score += (next_item_size - pr) as f64 * 0.03;
        }
    }

    // Last-chance bin: if this is the only fitting bin, prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin is expensive when many
    // open bins still have room; penalize empty-bin candidate accordingly.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 + 10.0 * open_bins_count as f64 * (1.0 - progress);
        // but if mean residual is very low (all bins nearly full), new bin is fine
        if mean_residual < 15.0 {
            score -= 30.0;
        }
    }

    // Tight-fill bonus: item consuming most of the bin
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fill_ratio > 0.9 {
        score -= 10.0;
    }

    // Modulo threshold coupling between item class and post_residual class
    let item_class = item_size / 10;
    let pr_class = pr / 10;
    if item_class == pr_class && pr > 0 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly penalize small unusable dead space (post_residual in (0, 10))
    // since items are >= 1 and small gaps are hard to fill.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual == 0 {
        // Perfect fit: heavily reward closing a bin completely.
        score -= 100.0;
    } else {
        // Larger residual is more reusable; mild reward proportional to size.
        score -= (post_residual as f64).sqrt() * 2.0;
    }

    // Penalize creating residual smaller than the next item if it could have fit it
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && next_item_size <= bin_residual {
        score += 15.0;
    }
    // Reward residual that exactly accommodates the lookahead item
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Open bins pressure: with many open bins, prefer consolidating into
    // existing bins (penalize new-bin opening implicitly via this term).
    score += open_bins_count as f64 * 1.5;

    // Mean residual coupling: if mean residual across open bins is large,
    // we should use existing space rather than spreading.
    if bin_residual >= mean_residual {
        score -= 3.0;
    } else {
        score += 3.0;
    }

    // New-bin candidate: bin_residual == bin_capacity means empty bin.
    // Give it a moderate score so it beats only truly poor fits
    // (e.g., placements leaving tiny dead space), but loses to decent fits.
    if bin_residual == bin_capacity {
        score += 60.0;
        // If item is large relative to capacity, opening a fresh bin is safer
        if item_size as f64 > bin_capacity as f64 * 0.7 {
            score -= 30.0;
        }
    }

    // Slight preference for tighter fits overall: reward small waste ratio
    score += (post_residual as f64 / bin_capacity as f64) * 10.0;

    // Stream progression: later in the stream, be more conservative about
    // opening bins (slightly stronger consolidation pressure).
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score += progress * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // next item fits: mild reward proportional to tightness
            score -= 50.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item cannot fit: penalize leftover dead space
            score += 0.5 * post_residual as f64;
        }
    }

    // Relative to mean residual: prefer bins with less residual than average (tighter bins)
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: penalize unless current residuals are all large (poor fits elsewhere)
    if bin_residual == bin_capacity {
        let avg_post = mean_residual - item_size as f64;
        if avg_post < 20.0 {
            score -= 100.0; // opening fresh bin is good when open bins are nearly full
        } else {
            score += 200.0 + 0.5 * (open_bins_count as f64);
        }
    }

    // Late in stream: consolidate, avoid spreading
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 20.0 * progress * (open_bins_count as f64).sqrt();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual).
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 2.5 * tightness * tightness * (item_size as f64);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    // Dead-space penalty: residual left that is hard to reuse later.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0; // tiny unusable slivers
    }

    // Last-chance bin: strongly favor filling the only bin that fits,
    // otherwise we open a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly in the post_residual,
    // keep this bin's space; penalize consuming it now.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score += 40.0; // reserve for perfect next fit
        } else if next_item_size < post_residual {
            score += 5.0 * (post_residual as f64 - next_item_size as f64) / cap;
        }
    }

    // Global pressure: many open bins with high mean residual -> consolidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let consolidation = (open_bins_count as f64 / (1.0 + mean_residual / 10.0)) * (0.5 + progress);
    score += consolidation * (bin_residual as f64 - post_residual as f64) / cap * 3.0;

    // New-bin candidate handling: empty bin gets a baseline cost so we only
    // open new bins when the fit into existing bins is genuinely poor.
    if bin_residual == bin_capacity {
        let poor_fit = (post_residual as f64) / cap; // = 1 - item/cap
        score = cap - (item_size as f64) + 25.0;
        if item_size > 70 { score -= 20.0; } // big items deserve fresh bins
        if poor_fit > 0.7 && next_item_size > 0 && next_item_size <= post_residual {
            score -= 10.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post-residual in [0,1]

    let mut score = pr;

    // Smooth non-linear coupling of post_residual with stream progress:
    // early on, prefer tight fits less aggressively; later, demand tight fits.
    let progress_weight = 0.5 + 1.5 * t * t;
    score -= progress_weight * (1.0 - x) * (1.0 - x) * cap * 0.35;

    // Penalize large post-residual non-linearly (dead space grows superlinearly).
    score += 0.25 * cap * x * x * x;

    // Reward exactness: if post_residual could fit the next item, discount slightly.
    if next_item_size > 0 && next_item_size <= post_residual {
        let nx = next_item_size as f64 / cap;
        score -= 8.0 * (1.0 - (nx - x).abs()) * (1.0 - t * 0.5);
    }

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0 * (1.0 - x);
    }

    // Mild penalty when bin residual deviates from mean residual (keeps bin pool balanced).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 3.0 * dev * dev;

    // Slight preference for filling existing bins when many are open.
    score += (open_bins_count as f64).ln() * x * 2.0;

    // New-bin candidate: keep it competitive only when fits are poor.
    if bin_residual == bin_capacity {
        score += 6.0 + 20.0 * (1.0 - (item_size as f64 / cap)) * (1.0 - t);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residue modulo 10 buckets.
    let r = post_residual;
    let class = r % 10;
    // Dead-space penalty: residuals that cannot serve typical small items (1..10)
    // are pure waste; penalize proportionally to how "useless" the class is.
    if r > 0 {
        let usable = if class == 0 { 10.0 } else { class as f64 };
        score += 0.35 * (10.0 - usable) * (r as f64 / cap);
    }

    // Perfect-fit harmonic reward: post_residual divisible by 10 leaves
    // clean class-0 space for future small items.
    if r % 10 == 0 {
        score -= 2.5;
    }
    if r == 0 {
        score -= 6.0; // bin closed exactly — best outcome
    }

    // Integer-division threshold: does the leftover fit the lookahead item?
    if next_item_size > 0 {
        if r >= next_item_size {
            score -= 3.0; // chain placement possible
            // extra reward if leftover after chaining is also harmonic (mod 10 == 0)
            if (r - next_item_size) % 10 == 0 {
                score -= 2.0;
            }
        } else {
            score += 2.0 * (next_item_size as f64 - r as f64) / 10.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 5.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when the current
    // placement would create large dead space and other bins exist.
    if bin_residual == bin_capacity {
        let waste = post_residual as f64;
        let pressure = if fitting_bins_count > 0 { 4.0 } else { 0.0 };
        score += pressure + 0.15 * waste - 1.0;
    }

    // Tight-fill reward: fraction of bin consumed by this item.
    let fill = item_size as f64 / cap;
    score -= 4.0 * fill * fill;

    // Late in the stream, consolidate: prefer bins below mean residual
    // (keeps few large-residual bins for future big items).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 0.5 * (post_residual as f64 - mean_residual);

    // Mild consolidation pressure with many open bins.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead space avoidance: residuals in [1,9] are nearly unusable for items >=10.
    if post_residual > 0 && post_residual <= 9 {
        score += 60.0 + (10 - post_residual) as f64 * 4.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward tight fits (small waste relative to capacity).
    score -= (1.0 - (post_residual as f64 / bin_capacity as f64)) * 20.0;

    // Last chance: strongly favor this bin if it is the only one that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Lookahead: penalize if post_residual cannot fit the next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }

    // Open-bin pressure: discourage spreading when many bins are open.
    score += open_bins_count as f64 * 0.5;

    // New-bin candidate: prefer opening a new bin only when it keeps residual
    // small (item nearly fills it) or when open bins have large mean residual.
    if bin_residual == bin_capacity {
        let fill_frac = item_size as f64 / bin_capacity as f64;
        score = 100.0 - fill_frac * 90.0 + open_bins_count as f64 * 0.3;
        if mean_residual > 60.0 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong base preference for tight fits (low post_residual).
    score *= 1.0;

    // 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item fits perfectly-ish: big reward scaled by snugness.
            let slack_after_next = post_residual - next_item_size;
            score -= (next_item_size as f64) * 1.5
                   - (slack_after_next as f64) * 0.3;
        } else {
            // Post-residual cannot host next item: penalize leftover dead space.
            score += (post_residual as f64) * 0.8;
        }
    }

    // Relative-to-mean coupling: bins with residual below mean are precious;
    // prefer placing into bins that are already "tight" relative to fleet.
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.5;
    } else {
        score -= (mean_residual - post_residual as f64) * 0.4;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize the new-bin candidate (empty bin) unless it enables a
    // perfect two-item pairing (item + next item exactly fill capacity).
    if bin_residual == bin_capacity {
        let pair_fill = item_size as f64 + next_item_size as f64;
        if next_item_size > 0 && (pair_fill - bin_capacity as f64).abs() < 1e-6 {
            score -= 100.0; // perfect pair: open the new bin
        } else {
            score += 55.0;  // otherwise prefer existing bins
        }
    }

    // Late in the stream: consolidate more aggressively into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_capacity - post_residual) as f64 * 0.2;

    // Mild penalty when many bins are open: encourage consolidation.
    score += open_bins_count as f64 * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: waste ratio penalty
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize creating dead space that the lookahead item cannot use
    if next_item_size > 0 {
        if post_residual < next_item_size && post_residual > 0 {
            score += 15.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        } else if post_residual >= next_item_size {
            // Bonus if residual after placement still accommodates next item
            score -= 5.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Many open bins: encourage consolidation into existing bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.5 * open_bins_count as f64 * (0.5 + progress);

    // Deviation from mean residual: prefer bins whose residual is close to item size
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.1 * dev;

    // Slight preference for fuller bins (smaller residual)
    score += 0.05 * bin_residual as f64 * (1.0 - progress);

    // New-bin candidate: penalize mildly so it's chosen only when fits are bad
    if bin_residual == bin_capacity {
        score += 20.0 + 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post-residual in [0,1]

    // Base: prefer tight fits, but weight tightness more as the stream progresses.
    let mut score = pr * (1.0 + 2.0 * progress);

    // Non-linear polynomial coupling of post-residual with progress:
    // mid-sized dead space is penalized quadratically; tiny dead space is fine.
    score += 40.0 * x * (1.0 - x) * (1.0 + progress * progress) * cap * 0.01;

    // Lookahead: reward if next item fits the post-residual (smooth coupling).
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let fit_gap = (pr - n).abs();
        let fits = if n <= pr { 1.0 } else { -1.0 };
        score -= fits * (1.0 - fit_gap / cap) * 15.0 * (0.5 + progress);
    }

    // Last-chance bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Mild penalty for many open bins with large mean residual (fragmentation).
    score += (open_bins_count as f64).sqrt() * (mean_residual / cap) * 3.0;

    // Slight preference to keep new bins as fallback: penalize the empty-bin candidate
    // softly early, more late (reuse bins as stream matures).
    if bin_residual == bin_capacity {
        score += 10.0 + 40.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class: post_residual in multiples of 10 is "usable" residual
    let harmonic = (post_residual % 10) as f64;
    score += harmonic * 2.0; // penalize off-class residuals (dead space)

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Small residual that is still useful (>= 10) gets a bonus
    if post_residual >= 10 && post_residual <= 30 {
        score -= 15.0;
    }

    // Penalize large wasted residuals (inefficient packing into big bin)
    if post_residual > 50 {
        score += (post_residual - 50) as f64 * 0.5;
    }

    // Lookahead coupling: if next item fits into post_residual, reward this bin
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 25.0;
        // harmonic bonus if the pair lands on a class boundary
        if (post_residual % 10) as u32 == next_item_size % 10 {
            score -= 10.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item can't use the leftover: penalize leaving stranded space
        score += (post_residual.min(next_item_size - 1)) as f64 * 0.3;
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: mild penalty so it's chosen only when it beats poor fits
    if bin_residual == bin_capacity {
        score += 30.0 + (open_bins_count as f64) * 0.1;
        // if item is large relative to capacity, opening fresh bin is fine
        if item_size > bin_capacity / 2 {
            score -= 20.0;
        }
    }

    // Stream progression: later in the stream, consolidate more aggressively
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0;

    // Mean residual coupling: if this bin's residual is far below mean, it's a tight fit — reward
    let diff = mean_residual - bin_residual as f64;
    score += diff * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space (post_residual below typical small item size)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 15.0;
    }

    // Reward tight fits
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Last chance bin: strongly favor using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open bins pressure: when many bins are open, favor filling existing bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.3 + 0.4 * progress);
    if bin_residual != bin_capacity {
        score -= pressure;
    } else {
        // New bin candidate: penalize slightly unless existing fit is terrible
        score += 10.0 + pressure;
    }

    // Lookahead: if next item fits into post_residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }

    // Deviation from mean residual: prefer bins whose residual is near mean (balanced packing)
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.2 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual), with non-linear penalty
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // 2-step lookahead: reward bins whose post_residual can host the next item exactly-ish
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 30.0 * (1.0 - gap / bin_capacity as f64);
        // Perfect chain: post_residual == next_item_size
        if gap == 0.0 {
            score -= 25.0;
        }
    } else if next_item_size > 0 {
        // Next item cannot fit here after placement: penalize dead space
        score += 8.0;
    }

    // Penalize bins far from mean residual (avoid fragmenting typical bins)
    score += ((post_residual as f64) - mean_residual).abs() * 0.3;

    // Last-chance bin: strong reward to use it instead of opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    // Make it costly by default; discount when many bins are open and item is large.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 35.0 - 20.0 * progress;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // fresh bin is good for pairing with a big next item
        }
    }

    // Prefer filling nearly-full bins first
    score -= (bin_capacity - bin_residual) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: quadratic penalty on wasted space.
    score += (post_residual as f64 / bin_capacity as f64).powi(2) * 30.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: if next item fits exactly into post_residual, strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - gap / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Dead space for the known next item: penalize proportionally.
        score += 8.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
    }

    // Last chance: this is the only fitting bin; avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when existing bins are crowded or fit is poor.
    if bin_residual == bin_capacity {
        let crowding = mean_residual / bin_capacity as f64;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Penalize new bins early and when open bins still have room.
        score += 45.0 + 40.0 * crowding + 15.0 * (1.0 - progress);
        // If item is large, a fresh bin is less wasteful.
        score -= item_size as f64 * 0.2;
        // If no bin fits well (post_residual large relative to item), soften penalty.
        if post_residual > bin_capacity / 2 {
            score -= 20.0;
        }
    }

    // Mild preference for filling bins with below-average residual (consolidate).
    if bin_residual < bin_capacity {
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        } else {
            score += 3.0;
        }
    }

    // Prefer using more-open-bins states to close bins rather than spreading.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Base: prefer small post residual (tight fit), with non-linear shaping
    let mut score = pr as f64;

    // Smooth non-linear coupling with stream progress:
    // early in stream, tolerate larger residuals (flexibility); later, punish them harder.
    let progress_coupling = x * x * (0.5 + progress) * cap;
    score += progress_coupling;

    // Penalize residuals that are too small to ever be useful (dead space),
    // smoothly via a quadratic bump around small residuals.
    let dead = (1.0 - x) * (1.0 - x);
    score += 40.0 * dead * (0.5 + 0.5 * progress);

    // Lookahead: reward if next item fits smoothly in post residual (smooth kernel)
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if n <= pr {
            let fit_quality = 1.0 - ((pr - n) / cap).abs();
            score -= 15.0 * fit_quality * fit_quality;
        } else {
            score += 10.0 * ((n - pr) / cap);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 - x * x);
    }

    // Mild penalty for spreading across many open bins when residuals are already low on average
    let mean_x = mean_residual / cap;
    score += (open_bins_count as f64).sqrt() * mean_x * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the residual after placement: capacity divided into
    // 10-wide classes; low classes (tight fits) are desirable.
    let class = (post_residual / 10) as f64;
    score += class * 6.0;

    // Exact fit (post_residual == 0) is perfect.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Dead-space penalty: residual too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Modulo arithmetic on post_residual: residuals near capacity fractions
    // (multiples of 25 or 50) pair well with common item sizes.
    let r = post_residual;
    if r % 50 == 0 && r > 0 {
        score -= 15.0;
    } else if r % 25 == 0 && r > 0 {
        score -= 8.0;
    }

    // Lookahead coupling: reward when the next item fits the post residual,
    // penalize when it nearly fits (would leave a nasty remainder).
    if next_item_size > 0 {
        if next_item_size <= r {
            let gap = r - next_item_size;
            if gap == 0 {
                score -= 35.0;
            } else if gap < 10 {
                score += 10.0; // chains into dead space
            } else {
                score -= 12.0;
            }
        } else {
            score += 8.0; // next item cannot use this bin's remainder
        }
    } else {
        // Last item: prefer the tightest possible fit, ignore future reuse.
        score -= 30.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: neutral-ish baseline so it only wins when open bins
    // have poor residuals. Penalize opening bins when many are already open.
    if bin_residual == bin_capacity {
        score += 55.0 + 2.0 * open_bins_count as f64;
        // But if the next item is huge, a fresh bin gives flexibility.
        if next_item_size >= 70 {
            score -= 40.0;
        }
    }

    // Mild pressure against bin proliferation over the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.02 * open_bins_count as f64 * (0.5 + progress);

    // Nudge toward bins below the mean residual (fill emptier bins first,
    // keeping tight bins for later items)? No — prefer bins below mean to
    // preserve large residuals: subtract when bin_residual < mean_residual.
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small to host any future item
    // (items are >= 1, but typical useful chunks are larger) are wasted capacity.
    if post_residual > 0 {
        let usable = (post_residual as f64 / bin_capacity as f64).sqrt();
        // Sharp penalty when the leftover is a thin unusable sliver.
        if post_residual < 10 {
            score += (10.0 - post_residual as f64) * 3.0;
        } else if post_residual < 30 {
            // Mid-range gap: mild penalty proportional to how unusable it is.
            score += (30.0 - post_residual as f64) * usable;
        } else {
            // Large leftovers are actually good (room for future items): reward.
            score -= (post_residual as f64 - 30.0) * 0.15 * usable;
        }
    } else {
        // Perfect fit: strongly reward.
        score -= 50.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post_residual,
    // reward heavily; if it cannot fit anywhere else, prefer keeping space for it.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size > post_residual {
            score += 8.0;
        }
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Open-bin pressure: many open bins -> prefer consolidating into existing
    // bins rather than fragmenting; add a mild penalty scaled by bin count.
    score += open_bins_count as f64 * 0.5;

    // Mean residual coupling: if this bin's post placement residual is far
    // below the mean, it is a tight fit — reward reducing dispersion slightly.
    score -= (mean_residual - post_residual as f64).max(0.0) * 0.05;

    // Early in the stream, be slightly more willing to open bins (better packing
    // later); late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is ideal
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins where next item fits exactly into post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // next item fits, but penalize leftover waste after that
            let two_step_waste = post_residual - next_item_size;
            score -= 100.0;
            score += two_step_waste as f64 * 0.5;
        } else {
            // next item won't fit here; penalize small dead space more
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Prefer tight fits relative to mean residual of open bins
    score -= (mean_residual - post_residual as f64) * 0.2;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // Penalize opening a new bin when reasonable alternatives exist
    if bin_residual == bin_capacity {
        score += 50.0 + mean_residual * 0.5;
        if fitting_bins_count > 0 {
            score += 150.0;
        }
    }

    // Mild pressure to close nearly-full bins as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * (0.1 + 0.3 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post residual)
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize dead space: residuals too small for the smallest plausible item
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if next item fits the post residual, big reward
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 20.0 + 0.5 * next_item_size as f64;
        } else {
            // post residual can't host next item; penalize proportionally to waste
            score += 0.3 * (next_item_size as f64 - post_residual as f64).min(60.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 35.0;
    } else if fitting_bins_count > 1 {
        // many options: prefer the tightest, slight penalty to reduce ambiguity
        score += 2.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // Global state: many open bins with high mean residual -> prefer filling existing bins
    if open_bins_count > 0 {
        let congestion = mean_residual / bin_capacity as f64;
        score -= 10.0 * congestion * (open_bins_count as f64).ln().max(1.0);
    }

    // New-bin candidate handling: empty bin should only win when nothing fits well
    if bin_residual == bin_capacity {
        // baseline cost of opening a new bin; cheaper early, expensive later
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 40.0 + 30.0 * progress;
        // if an existing bin fits tightly, discourage new bin
        if fit_ratio > 0.8 && fitting_bins_count >= 1 {
            score += 20.0;
        }
        // lookahead: new bin can always host next item, slight relief
        if next_item_size > 0 && (bin_capacity as u32) >= next_item_size {
            score -= 5.0;
        }
    }

    // Time horizon: late in the stream, avoid leaving scattered residuals
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_post = pr / cap;
    let mut score = pr as f64;
    // smooth polynomial coupling of post_residual with stream progress
    let poly = norm_post * norm_post * (0.5 + 2.0 * progress * (1.0 - progress));
    score += 40.0 * poly;
    // penalize large dead space more late in the stream
    score += 20.0 * progress * norm_post * norm_post * norm_post;
    // reward tight fits (low post residual) especially when few alternatives
    let tight = 1.0 - norm_post;
    score -= 15.0 * tight * tight * (1.0 + (fitting_bins_count == 1) as i32 as f64 * 0.5);
    // lookahead: favor bins whose post residual fits next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 * (1.0 - (next_item_size as f64 / cap));
    } else if next_item_size > 0 {
        score += 8.0 * (1.0 - progress);
    }
    // mild penalty for opening new bins when many are open
    if bin_residual == bin_capacity {
        score += 12.0 * (1.0 - progress) + 3.0 * open_bins_count as f64;
    }
    // encourage balancing residuals near mean
    score += 5.0 * ((pr - mean_residual) / cap).abs();
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residue modulo capacity quarters
    let quarter = bin_capacity / 4; // 25
    let residue_class = post_residual % quarter;
    let class_index = post_residual / quarter; // 0..4

    // Reward tight fits: post_residual near zero is excellent
    if post_residual == 0 {
        score -= 100.0; // perfect closure
    } else if residue_class <= 2 {
        score -= 12.0 - (residue_class as f64) * 3.0;
    } else if residue_class >= quarter - 2 {
        // post_residual just below a quarter boundary: still fairly usable
        score -= 4.0;
    } else {
        // dead-space zone: penalize proportionally to distance from usable classes
        score += (residue_class as f64) * 0.6;
    }

    // Higher harmonic classes (larger residuals) are less attractive targets
    score += class_index as f64 * 2.5;

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            // harmonic reward decays with slack
            score -= 25.0 * (1.0 - slack as f64 / quarter as f64).max(0.0);
        } else {
            // next item cannot use this residual: slight penalty scaled by waste
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate: make it attractive only when current fit is poor
    if bin_residual == bin_capacity {
        // base cost of opening a bin, offset when open bins are crowded
        score += 40.0;
        let progress = step_index as f64 / total_items.max(1) as f64;
        if mean_residual < item_size as f64 * 1.2 && open_bins_count > 0 {
            score -= 55.0 * (1.0 - progress * 0.5);
        }
    }

    // Prefer bins whose residual is already below mean (consolidating space)
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // Item size harmonic: large items deserve tightest packing priority
    if item_size > bin_capacity / 2 {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space: residuals too small for typical items
    let dead_threshold = 10.0f64;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += 40.0;
    }

    // Reward tight fits (small post_residual) extra
    if post_residual <= 5 {
        score -= 25.0;
    }

    // Last-chance bin pressure: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage opening new bins when many are open
    if bin_residual == bin_capacity {
        score += 15.0 + open_bins_count as f64 * 3.0;
    }

    // Lookahead: favor bins whose post_residual can still host the next item
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && (post_residual as f64) < next_item_size as f64 {
        score += 10.0;
    }

    // Mild preference for bins with residual above mean (keep balanced spread)
    score += 0.05 * (mean_residual - post_residual as f64);

    // Slight stream-progression tightening: later items favor tighter fits more
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * (bin_residual as f64 - post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Near-perfect match within a small window.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if gap <= 5.0 {
            score -= 40.0 - gap * 6.0;
        }
        // Penalize residual that is just barely too small for the next item
        // (dead space that will likely never be used).
        if next_item_size > post_residual && next_item_size - post_residual <= 8 {
            score += (next_item_size - post_residual) as f64 * 4.0;
        }
        // Reward post_residual that can still hold next item comfortably.
        if post_residual >= next_item_size && post_residual > 0 {
            score -= (post_residual as f64 / next_item_size as f64).min(2.0) * 5.0;
        }
    }

    // Strong preference for tight fits relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 25.0;

    // Compare against mean residual: placing into a bin whose post-residual
    // diverges favorably from the mean is good (reduces fragmentation).
    let dev = post_residual as f64 - mean_residual;
    if dev < 0.0 {
        score += dev * 0.15; // below-mean residual is rewarded
    } else {
        score += dev * 0.10; // above-mean residual is mildly penalized
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Opening a new empty bin: penalize unless current bin would leave
    // a very large unusable residual (poor fit).
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        if fill_ratio > 0.5 {
            score += 35.0; // decent fit exists elsewhere, don't open new bin
        } else {
            score -= 5.0; // small item, new bin may be acceptable
        }
    }

    // Mild bonus for consolidating when many bins are open.
    if open_bins_count > 4 && bin_residual < bin_capacity {
        score -= (open_bins_count.min(20)) as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: less post-residual relative to capacity is better.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 8.0;

    // Lookahead: if the next item fits exactly into the post-residual,
    // strongly reward this placement (perfect pairing).
    if next_item_size > 0 && next_item_size <= post_residual {
        let pair_waste = post_residual - next_item_size;
        score -= 14.0 - (pair_waste as f64) * 0.5;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item cannot follow into this bin: mild penalty scaled by wasted potential.
        score += (next_item_size as f64 - post_residual as f64).min(40.0) * 0.15;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Penalize creating tiny dead space (< 10) that likely nothing can use,
    // unless the fit was very tight.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    // Time horizon: early in the stream, be more willing to open new bins
    // (keep residuals large for the future); late in the stream, consolidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize early, discount late.
        score += 30.0 * (1.0 - progress) - 10.0 * progress;
    } else {
        // Existing bins become more attractive as the stream progresses.
        score -= 6.0 * progress;
    }

    // Global state coupling: if open bins have lots of residual on average,
    // prefer filling existing bins rather than spreading further.
    score += (mean_residual - post_residual as f64) * 0.1;

    // If many bins are open, favor consolidation into existing bins.
    score += open_bins_count as f64 * (0.4 * (1.0 - progress));

    // Perfect fit bonus: leaving exactly zero residual is ideal.
    if post_residual == 0 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Base: waste after placement, with smooth non-linear polynomial coupling to progress.
    let mut score = pr * (1.0 + 0.8 * progress * progress);

    // Quadratic dead-space penalty: small residuals are more likely unusable.
    score += 12.0 * pr_norm * pr_norm * (0.5 + progress);

    // Reward tight fits smoothly via cubic decay in pr_norm.
    score -= 20.0 * (1.0 - pr_norm).powi(3) * (1.0 - progress);

    // Lookahead: reward if next item fits the post-residual, penalize otherwise.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= 8.0 * (1.0 - (nxt / cap)) * (1.0 - progress);
        } else {
            score += 6.0 * ((nxt - pr) / cap) * (1.0 - progress);
        }
    }

    // Last-chance bonus: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 * (1.0 + progress);
    }

    // Mild penalty for spreading across many open bins late in the stream.
    score += 0.15 * open_bins_count as f64 * progress * progress;

    // New-bin candidate: keep it competitive early, discourage late.
    if bin_residual == bin_capacity {
        score += 5.0 * progress + 2.0 * (mean_residual / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into coarse buckets.
    // Small post-residuals are good (tight fit); large ones are dead space.
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap;

    // Integer-division thresholds on post_residual (harmonic classes of width 10)
    let class = post_residual / 10;
    score += match class {
        0 => -12.0,             // near-perfect fit
        1 => -6.0,
        2 => -2.0,
        3 => 1.0,
        4 => 3.0,
        5 => 5.0,
        6 => 7.0,
        7 => 9.0,
        8 => 11.0,
        _ => 13.0,              // mostly empty bin, wasteful
    };

    // Non-linear penalty on wasted fraction (dead space that few items can use)
    score += 18.0 * frac * frac;

    // Modulo arithmetic: residuals that pair well with common item sizes are valuable.
    // Items 1..100; small residuals (<=15) are hard to fill later.
    if post_residual > 0 && post_residual < 15 {
        score += 8.0;
    }
    // Residuals that are exact multiples of 10 are "harmonic" and easy to fill
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 5.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            score -= 6.0;
            // harmonic pairing: post_residual - next_item_size small
            let gap = post_residual - next_item_size;
            if gap <= 5 {
                score -= 4.0;
            }
        } else {
            // next item cannot follow here; penalize proportionally
            score += 3.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the
    // item is large relative to capacity and no decent open fit exists.
    if bin_residual == bin_capacity {
        // base cost of a fresh bin
        score = 0.55 * cap + 10.0;
        if item_size as f64 > 0.6 * cap {
            score -= 18.0;
        }
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            // room for a companion item in the fresh bin
            score -= 6.0;
        }
    }

    // Mild pressure against bin proliferation as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.02 * open_bins_count as f64 * (0.5 + progress);

    // Slight preference for bins tighter than average (consolidation)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 4.0 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny gaps are wasted space.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0; // unusable dead space (min item is 1..100, small gaps likely unusable)
        } else if post_residual < 25 {
            score += 25.0;
        } else if post_residual < 40 {
            score += 8.0;
        }
    } else {
        score -= 40.0; // perfect fit is ideal
    }

    // Reward good relative fill of the bin.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill_ratio;

    // Pressure from number of open bins: prefer consolidating when many bins open.
    score += (open_bins_count as f64) * 1.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        // Base penalty so we prefer existing bins unless they leave dead space.
        score += 55.0;
        // Less penalty early in the stream (building a diverse pool can help).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 20.0 * (1.0 - progress);
        // If next item is large and this item is small, a fresh bin is useful.
        if next_item_size > 60 && item_size < 40 {
            score -= 15.0;
        }
        // If mean residual is high, existing bins have room; penalize new bin more.
        score += mean_residual * 0.4;
    }

    // Lookahead: reward leaving a gap that exactly fits the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    }
    // Penalize leaving a gap slightly larger than the next item (near-miss waste).
    if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size < 10 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: reward perfect 2-step matches (post_residual == next_item_size)
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        // residual can still host the next item: mild reward proportional to tightness
        let slack = (post_residual - next_item_size) as f64;
        score -= 10.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // next item won't fit here: penalize wasted potential
        score += 8.0;
    }

    // Tight fit reward: small post_residual is good dead-space-wise
    let tightness = 1.0 - post_residual as f64 / bin_capacity as f64;
    score -= 6.0 * tightness;

    // Penalize large unusable gaps relative to mean residual
    if post_residual as f64 > mean_residual {
        score += 0.5 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.25 * (mean_residual - post_residual as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Early in stream: be more conservative, prefer new bins to keep flexibility
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // Many open bins: discourage spreading items too thin
    score += 0.15 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a non-linear bonus.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio).powi(3) * 12.0;

    // Penalize dead space that cannot hold the lookahead item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.6;
        } else if post_residual == next_item_size {
            // Perfect lookahead fit: strong reward.
            score -= 8.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: only attractive when existing fits are poor.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        let time_frac = step_index as f64 / (total_items.max(1) as f64);
        let poor_fit_penalty = if next_item_size > 0 && post_residual < next_item_size { 1.0 } else { 0.0 };
        score += 6.0
            - pressure * 4.0
            - poor_fit_penalty * 5.0
            + time_frac * 2.0;
        if fitting_bins_count == 0 {
            score -= 20.0; // must open a new bin anyway
        }
    }

    // Mildly prefer filling bins that deviate from the mean residual (consolidation).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score -= (bin_capacity as f64 - dev) * 0.01;

    // Slight preference for bins with larger residual when many bins are open.
    score += (open_bins_count as f64).ln().max(0.0) * (bin_residual as f64 / bin_capacity as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with smooth polynomial shaping
    let mut score = pr;

    // Non-linear coupling of post-residual with stream progress:
    // early on, dead space is cheap; late, it is costly.
    let progress_weight = 0.6 * progress * progress + 0.4 * progress;
    score += 1.5 * progress_weight * pr * (1.0 - norm_pr * 0.5);

    // Penalize large residuals quadratically, scaled by progress
    score += 0.25 * progress * norm_pr * norm_pr * cap;

    // Reward tight fits (small post-residual relative to item) smoothly
    let tightness = 1.0 - (pr / (bin_residual as f64 + 1.0));
    score -= 2.0 * tightness * tightness * item_size as f64 * (0.5 + 0.5 * progress);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 {
        score -= 8.0 * (1.0 + progress);
    }

    // Lookahead: if next item fits in post-residual, reward this placement
    if next_item_size > 0 {
        let next_fits = if (next_item_size as f64) <= pr { 1.0 } else { 0.0 };
        score -= 4.0 * next_fits * (1.0 - norm_pr);
        // Penalize leaving residual that is just barely too small for next item
        let gap = pr - next_item_size as f64;
        if gap > 0.0 && gap < 10.0 {
            score += 1.0 * (10.0 - gap) / 10.0;
        }
    }

    // Smooth penalty for opening many bins with large mean residual (fragmentation)
    let frag = (mean_residual / cap - norm_pr).abs();
    score += 0.5 * frag * (1.0 + 0.5 * progress);

    // Mild preference for keeping bins balanced across open bins
    score += 0.1 * ((open_bins_count as f64).ln() + 1.0) * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "reusable" the leftover is
    // under common item-size classes (multiples of 5, 10, 20).
    let pr = post_residual;
    let class_bonus = if pr == 0 {
        -60.0 // perfect fit: strongly reward
    } else if pr <= 10 {
        0.0
    } else if pr % 10 == 0 {
        -25.0 // residual is a round class, easy to fill later
    } else if pr % 5 == 0 {
        -12.0
    } else {
        6.0 + (pr % 5) as f64 * 2.0 // awkward remainder
    };
    score += class_bonus;

    // Penalize large dead space quadratically (wasted capacity grows superlinearly).
    let frac = pr as f64 / bin_capacity as f64;
    score += 40.0 * frac * frac;

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size <= pr {
            let gap = pr - next_item_size;
            score -= 20.0 - (gap % 10) as f64 * 1.5;
        } else {
            // next item cannot fit here; mild penalty proportional to overflow class
            score += ((next_item_size - pr) % 20) as f64 * 0.8;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Fresh-bin candidate handling: only open a new bin when the current bin
    // would leave an awkward large residual and the item is big.
    if bin_residual == bin_capacity {
        // new-bin candidate: baseline preference unless existing bins fit well
        score += 25.0;
        if item_size % 10 == 0 && item_size >= 50 {
            score -= 20.0; // big round items start fresh bins happily
        }
    }

    // Stream progression: later in the stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 15.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    // Mean residual coupling: if this bin is far from the mean, normalize toward it.
    score += 0.15 * (post_residual as f64 - mean_residual).abs();

    // Congestion: many open bins -> favor tight packing of existing ones.
    if open_bins_count > 4 {
        score -= 0.5 * open_bins_count as f64 * (1.0 - frac);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable small gaps (< 10, the min item size)
    // are pure waste; penalize them heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Gaps too small to fit the lookahead item are risky if the lookahead
    // would otherwise need a new bin.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }
    // Perfect fit: zero waste, strongly reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless dead space is severe).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
        if post_residual >= 10 {
            score -= 10.0;
        }
    }

    // Open-bin pressure: with many open bins, discourage opening another;
    // the new-bin candidate has bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        // New bin: penalize proportionally to how many bins are already open.
        score += 15.0 + 6.0 * open_bins_count as f64;
        // But if no existing bin fits well (large dead space elsewhere),
        // a fresh bin is attractive; reduce penalty when mean residual is low.
        if mean_residual < item_size as f64 {
            score -= 10.0;
        }
    } else {
        // Existing bin: mild reward when open bin count is high (consolidation).
        score -= 2.0 * (open_bins_count as f64).ln().max(0.0);
    }

    // Prefer bins whose residual is close to the item (tight fits).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 40.0 * tightness;

    // Slight preference to fill bins with larger residuals early on.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item well.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual >= next_item_size {
            // Exact-ish match bonus: next item fills this bin's leftover.
            let lookahead_waste = (post_residual - next_item_size) as f64;
            score -= 18.0 * (1.0 - lookahead_waste / bin_capacity as f64);
            // Strong bonus for near-perfect two-item packing.
            if lookahead_waste <= 5.0 {
                score -= 25.0;
            }
        } else {
            // Post-residual too small for next item: penalize dead space proportionally.
            let dead = (post_residual as f64) / bin_capacity as f64;
            score += 12.0 * dead;
            // Extra penalty if dead space is tiny (unusable sliver).
            if post_residual < 10 {
                score += 20.0;
            }
        }
    } else {
        // Last item: just minimize waste.
        score += 2.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Tight fits are generally good.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 10.0 * fit_ratio;

    // Relative to mean residual: prefer bins tighter than average.
    score += 0.3 * ((bin_residual as f64) - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are poor fits.
    if bin_residual == bin_capacity {
        score += 30.0;
        // Early in stream, opening bins is cheaper; late, prefer consolidation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * (1.0 - progress);
        // If next item is large, a fresh bin is more attractive.
        if next_item_size > 60 {
            score -= 10.0;
        }
    }

    // Mild penalty for many open bins (encourage consolidation).
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) more aggressively as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (bin_capacity - post_residual) as f64 * (0.4 + 0.8 * progress);

    // Penalize dead space that is too small to hold the next item (or a typical small item).
    let next_probe = if next_item_size > 0 { next_item_size } else { 20 };
    if post_residual > 0 && post_residual < next_probe {
        score += (next_probe - post_residual) as f64 * 2.5;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 + 15.0 * progress;
    }

    // Many fitting bins: mild penalty to keep fragmentation spread low; few bins: reward.
    if fitting_bins_count > 2 {
        score += 3.0 * (fitting_bins_count as f64 - 2.0).min(6.0);
    }

    // Prefer bins below mean residual (relatively emptier) early, tighter bins late.
    let res_f = bin_residual as f64;
    let dev = res_f - mean_residual;
    score += dev * (0.25 - 0.5 * progress);

    // New-bin candidate logic: open a new bin only when current bins fit poorly
    // (large dead space would result) or stream is early and item is large.
    if bin_residual == bin_capacity {
        let worst_waste = 40.0;
        let poor_fit_penalty = if post_residual > 0 && post_residual < next_probe { 35.0 } else { 0.0 };
        let early_open_bonus = (1.0 - progress) * 10.0 * (item_size as f64 / 100.0);
        let crowded_bonus = (open_bins_count as f64).ln().max(0.0) * 2.0;
        score -= 60.0 + poor_fit_penalty + early_open_bonus + crowded_bonus - worst_waste.min(post_residual as f64) * 0.2;
        // Discard new-bin option when an open bin gives a near-perfect fit.
        if post_residual == 0 || (fitting_bins_count == 1 && post_residual <= 10) {
            score += 80.0;
        }
    }

    // Slight preference for filling larger-residual bins when item is big.
    if item_size >= 60 {
        score -= res_f * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let br = bin_residual as f64;
    let item = item_size as f64;
    let progress = (step_index as f64) / (total_items.max(1) as f64);
    let pr_norm = pr / cap;

    // Base: prefer tight fits (low post residual), with non-linear emphasis
    let mut score = pr * (1.0 + 1.5 * pr_norm * pr_norm);

    // Smooth polynomial coupling of post residual with stream progress:
    // early on, waste matters less; later, tighten packing harder.
    let progress_coupling = pr * (0.5 + 2.0 * progress * progress + 1.5 * progress * pr_norm);
    score += progress_coupling;

    // Penalize dead space relative to mean residual (smooth quadratic mismatch)
    let mismatch = pr - mean_residual;
    score += 0.3 * mismatch * mismatch / cap;

    // Lookahead: reward bins whose post residual fits next item smoothly
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fits_next = (pr >= nxt) as i32 as f64;
        let tightness = 1.0 - ((pr - nxt).abs() / cap).min(1.0);
        score -= 6.0 * fits_next * tightness * tightness;
    } else {
        // last item: strongly prefer filling existing space
        score -= 4.0 * (1.0 - pr_norm) * (1.0 - pr_norm);
    }

    // Last-chance bin bonus (smooth in fitting_bins_count scarcity)
    let scarcity = 1.0 / (fitting_bins_count as f64);
    score -= 3.0 * scarcity;

    // Mild penalty for spreading across many open bins (smooth saturation)
    score += 0.4 * (open_bins_count as f64).ln().max(0.0) * pr_norm;

    // New-bin candidate: encourage only when current bin would leave bad residue
    if bin_residual == bin_capacity {
        let bad_fit = (pr_norm - 0.5).abs(); // distance from half-full ideal
        score = cap * (0.6 + 1.2 * bad_fit * bad_fit) - 2.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits, with a slight convexity penalty on waste.
    score += 0.05 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // Harmonic class of post_residual: classify leftover into capacity fractions.
    let frac = post_residual as f64 / bin_capacity as f64;
    let class = (frac * 10.0).floor(); // 0..10
    // Dead-space classes: leftovers that few item sizes can use are penalized.
    // Classes 1..4 (residual 10-49) are awkward; class 0 is perfect; large residuals fine.
    score += match class as u32 {
        0 => -20.0,
        1 => 6.0,
        2 => 4.0,
        3 => 2.0,
        4 => 1.0,
        _ => 0.0,
    };

    // Modulo arithmetic on post_residual: leftovers matching common small item sizes
    // (multiples of 10, and 25/50/75 classes) are reusable.
    let pr = post_residual;
    if pr > 0 && pr <= 80 {
        if pr % 10 == 0 { score -= 5.0; }
        else if pr % 5 == 0 { score -= 2.0; }
        if pr == 25 || pr == 50 || pr == 75 { score -= 3.0; }
    }

    // Lookahead coupling: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item won't fit here; penalize leaving this bin very full
            // only mildly, since bin will close anyway.
            score += 2.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin should only win when no open bin fits well.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 30.0; // must open a new bin
        } else {
            // Prefer reusing open bins unless their residuals are all poor.
            // If mean residual is large, open bins are roomy -> prefer them.
            score += 12.0 + 0.3 * mean_residual;
            // Early in stream, opening bins is cheaper (more future items to fill them).
            let progress = step_index as f64 / (total_items.max(1) as f64);
            score -= 10.0 * (1.0 - progress);
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.2 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 {
        // Any leftover that is smaller than the smallest plausible item is dead space.
        if post_residual < 10 {
            score += 60.0;
        } else if post_residual < 20 {
            score += 25.0;
        } else if post_residual < 30 {
            score += 8.0;
        }
        // Nonzero post residual is only good if the lookahead item can use it.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 12.0;
        } else if next_item_size > post_residual && post_residual > 0 {
            score += 10.0;
        }
    } else {
        // Perfect fill is ideal.
        score -= 40.0;
    }

    // Tight fit reward: prefer bins where the item occupies a large fraction of residual.
    if bin_residual > 0 {
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score -= 20.0 * fill_ratio;
    }

    // Open bins pressure: when many bins are open, avoid spreading; when few, tolerate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln().max(0.0) * (1.0 + progress);
    score += 2.0 * pressure;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Mean residual context: if this bin's residual is far below the mean,
    // it is the "dirtiest" bin — prefer to dump the item here.
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Slight preference for using existing bins over opening a new one.
    if bin_residual == bin_capacity {
        score += 5.0 + pressure;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize small dead space that no item (min size 1) can use well
        if post_residual < 10 {
            score += 15.0;
        }
        // 2-step lookahead: reward residuals that exactly match the next item
        if next_item_size > 0 {
            let nr = next_item_size as f64;
            if (post_residual as f64 - nr).abs() < 1e-9 {
                score -= 250.0; // perfect chain fit
            } else if post_residual as f64 > nr {
                score -= 0.8 * nr; // next item still fits here
            } else {
                score += 0.6 * (nr - post_residual as f64); // next item won't fit
            }
            // Chain: post_residual == item + next exactly consumed
            if post_residual as f64 + nr == bin_residual as f64 {
                score -= 120.0;
            }
        }
    }

    // Relative to mean residual: prefer filling below-average-residual bins
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin bonus: avoid opening a new bin when this is the only fitting one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New bin candidate: penalize unless nothing fits well (poor fit avoidance)
    if bin_residual == bin_capacity {
        score += 40.0;
        // open a fresh bin if lookahead suggests a large next item needing space
        if next_item_size > 0 && (post_residual as f64) < next_item_size as f64 {
            score -= 30.0;
        }
    }

    // Late in stream: consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize small post_residual quadratically.
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score += tightness * tightness * 40.0;

    // Penalize dead space that can never be filled by typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver is wasted capacity
    }

    // Lookahead coupling: if the next item fits into post_residual, reward this placement.
    if next_item_size > 0 && (post_residual as f64) >= (next_item_size as f64) {
        score -= 12.0 + 0.15 * (next_item_size as f64);
    } else if next_item_size > 0 && (post_residual as f64) > 0.0 {
        // next item cannot use leftover space: penalize proportionally
        score += 8.0 * (1.0 - (next_item_size as f64) / (bin_residual as f64).max(1.0));
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).ln().max(0.0);
    }

    // Prefer bins with residuals below the mean (compact bins), discourage dumping into large-residual bins early.
    let dev = (bin_residual as f64) - mean_residual;
    score += 0.10 * dev;

    // Time horizon: early in stream, opening new bins is cheap (more future items to fill them);
    // late in stream, prefer existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate score: attractive early, expensive late.
        score = 15.0 + 60.0 * progress + 0.05 * (open_bins_count as f64);
        if item_size >= 90 {
            score -= 10.0; // huge items fit nothing else anyway; fresh bin is fine
        }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 5.0; // pairing potential with fresh bin
        }
    } else {
        // Late stream: extra penalty for leaving large residuals in open bins.
        score += 10.0 * progress * tightness;
    }

    // Global pressure: many open bins -> discourage opening more, encourage filling.
    score += 0.03 * (open_bins_count as f64) * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 + 3.0 * progress) - norm_pr * (0.5 + progress);

    // Reward tight fits, stronger late in the stream
    let tightness = (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 + progress);

    // Penalize dead space relative to mean residual
    let dead = (pr - mean_residual).max(0.0) / cap;

    // Last-chance bonus
    let last_chance = if fitting_bins_count == 1 { -2.0 * (1.0 + progress) } else { 0.0 };

    // Lookahead: reward residual that can fit the next item
    let lookahead = if next_item_size > 0 && (next_item_size as f64) <= pr {
        -0.5 * (1.0 - progress)
    } else if next_item_size > 0 {
        0.25 * norm_pr * progress
    } else {
        0.0
    };

    let mut score = pr + 10.0 * poly + 5.0 * tightness + 8.0 * dead + last_chance + lookahead;

    // Mild penalty for spreading across many bins
    score += 0.05 * open_bins_count as f64 * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space in residue classes mod 10
    let res_class = post_residual % 10;
    let res_div = post_residual / 10;
    // Penalize awkward residue classes (hard-to-fill remainders)
    let awkward = match res_class {
        0 => 0.0,
        1 | 9 => 4.0,
        2 | 8 => 3.0,
        3 | 7 => 2.0,
        4 | 6 => 1.0,
        _ => 1.5,
    };
    score += awkward * (1.0 + res_div as f64 * 0.1);

    // Perfect fit reward
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 10 {
        score -= 30.0;
    }

    // Lookahead: does the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item can also go here: chain reward, scaled by tightness
            let tight = 1.0 - (post_residual - next_item_size) as f64 / cap;
            score -= 20.0 + 15.0 * tight;
        } else {
            // Next item won't fit here: slight penalty proportional to gap
            let gap = (next_item_size - post_residual) as f64;
            score += gap.min(20.0) * 0.5;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowded = mean_residual < item_size as f64 * 1.2;
        if crowded {
            score -= 15.0 * progress;
        } else {
            score += 20.0 + mean_residual * 0.3;
        }
    }

    // Mild preference for tighter bins overall (below mean residual)
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    // Scale by number of open bins: spreading load slightly penalized
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small to fit any plausible
    // future item are wasted. Penalize them super-linearly.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (10.0 - post_residual as f64);
    } else if post_residual >= 10 && post_residual < 20 {
        // Moderately awkward gap: mild penalty to prefer fuller packing elsewhere.
        score += 6.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // this placement is part of a chain — reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack < 10 {
            score -= 18.0;
        } else {
            score -= 5.0;
        }
    }
    // If next item cannot fit the post residual, mildly penalize (fragmentation risk),
    // but only when the gap is small enough to matter.
    if next_item_size > post_residual && post_residual > 0 && post_residual < next_item_size {
        score += 4.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += 0.9 * open_bins_count as f64;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // existing bins are fragmented (high mean residual) or the fit here is poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin scales with stream progress (sunk bins).
        score += 55.0 + 20.0 * (step_index as f64 / total_items.max(1) as f64);
        // If mean residual across open bins is large, opening new bins is wasteful.
        score += 0.35 * mean_residual;
    } else {
        // Reward using bins with larger residuals when the fit is decent,
        // since they are the hardest to fill later.
        let fit_ratio = item_size as f64 / bin_residual as f64;
        score -= 10.0 * fit_ratio;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) with a non-linear boost.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // 2-step lookahead: strongly reward when next item exactly fits post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chain: bin becomes exactly full
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // penalize leftover slack after the chained placement
            score += slack * 0.45;
            score -= 12.0; // base bonus for chain feasibility
        } else {
            // next item cannot fit here: penalize leaving a gap near next size
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.30;
        }
    }

    // Compare post_residual against mean residual of open bins.
    // Leaving below-average residual is good (bin well filled).
    score -= (mean_residual - post_residual as f64) * 0.35;

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize opening new bins when many bins are already open but underused.
    if bin_residual == bin_capacity {
        // new-bin candidate: base cost + penalty scaled by open bins count
        score += 40.0 + 3.0 * (open_bins_count as f64).sqrt();
        // but if mean residual is small (bins nearly full), new bin is fine
        score -= (mean_residual / bin_capacity as f64) * 30.0;
    }

    // Mild progression term: late in the stream, favor filling existing bins more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 6.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic bonus for small post-residual
    score -= (post_residual as f64).powi(2) / cap;

    // Waste ratio of this placement
    let fill = (item_size as f64) / bin_residual as f64;
    score -= fill * 12.0;

    // Lookahead: if next item fits into post_residual, reward strongly
    if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        score -= 8.0 + (next_item_size as f64) * 0.1;
    }
    // If next item would leave this bin nearly dead, penalize
    if next_item_size > 0 && post_residual > 0 && (next_item_size as u32) > post_residual && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Time horizon: early in stream, prefer compacting into few bins; late, be greedy
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * (mean_residual - post_residual as f64).abs() * 0.05;

    // New-bin candidate: only attractive when no good open bin exists
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // base penalty so new bins are opened only when open bins fit poorly
        score += 25.0;
        // more open bins -> discourage opening yet another
        score += open_bins_count as f64 * 1.5;
        // early in stream, opening bins is cheaper (future items can fill them)
        score -= (1.0 - progress) * 20.0;
        // if item is large relative to capacity, a fresh bin is fine
        score -= (item_size as f64 / cap) * 10.0;
        // if next item is large, fresh bin may serve it
        if (next_item_size as f64) / cap > 0.6 {
            score -= 6.0;
        }
    } else {
        // prefer bins whose residual is close to item (best-fit style)
        let tightness = (bin_residual as f64 - item_size as f64) / cap;
        score += tightness * 5.0;
        // bonus for draining bins with small residuals (avoid fragmentation)
        if bin_residual < 30 {
            score -= 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / cap;

    // Base: prefer tight fits (small post_residual), scaled by capacity.
    let mut score = norm_pr;

    // Smooth polynomial coupling of post-residual with stream progress:
    // early on, tolerate leftover space; late in the stream, penalize it harder.
    let prog2 = progress * progress;
    let prog3 = prog2 * progress;
    let progress_weight = 0.5 + 1.5 * prog2 + 1.0 * prog3;
    score += progress_weight * norm_pr * norm_pr;

    // Penalize dead space relative to the mean residual of open bins,
    // smoothly coupled with progress.
    let mean_norm = mean_residual / cap;
    score += progress_weight * (norm_pr - mean_norm).abs() * 0.5;

    // Lookahead: if the next item fits into the post-residual, reward this bin
    // (subtracted score), with a smooth quadratic in next-item tightness.
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if ns <= pr {
            let tightness = 1.0 - (pr - ns) / cap;
            score -= 0.8 * tightness * tightness * (1.0 - progress * 0.5);
        } else {
            // Next item won't fit here: mildly penalize leaving a gap it can't use.
            score += 0.3 * (ns - pr) / cap * progress_weight;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly reward using it
    // to avoid opening a new bin (smooth ramp with progress).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 1.5 * (1.0 + progress);
    }

    // Mild penalty for spreading across many open bins when residual is large.
    let open_norm = open_bins_count as f64;
    score += 0.05 * open_norm * norm_pr;

    // New-bin candidate: neutral reference slightly above good fits,
    // but competitive when existing bins would waste a lot of space.
    if bin_residual == bin_capacity && item_size > 0 {
        score = 0.9 - 0.4 * progress + 0.5 * (item_size as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals that form "nice" slots
    // (multiples of 10, or exact halves/quarters) are more reusable.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Reward post-residuals aligned to harmonic grid points (10, 20, 25, 50).
    if post_residual % 50 == 0 && post_residual > 0 {
        score -= 12.0;
    } else if post_residual % 25 == 0 && post_residual > 0 {
        score -= 8.0;
    } else if post_residual % 10 == 0 && post_residual > 0 {
        score -= 5.0;
    }

    // Penalize tiny dead space: a post-residual that no realistic item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Exact fit is perfect.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // strongly reward this bin (chained packing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            // Reward proportional to how well the chain continues.
            let chain_waste = (post_residual - next_item_size) as f64;
            score -= 6.0 * (1.0 - chain_waste / cap);
        } else {
            // Next item cannot use this bin's leftover: mild penalty scaled
            // by how much unusable space remains.
            score += 0.05 * pr;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when current fit is bad
    // and we are early/mid-stream with room to consolidate later.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; make it attractive only for large items
        // relative to mean residual (poor fits elsewhere).
        score = 0.35 * cap + 0.5 * (item_size as f64);
        if item_size as f64 > mean_residual + 20.0 {
            score -= 15.0;
        }
        if progress > 0.85 {
            score += 10.0; // late stream: consolidate into open bins
        }
    }

    // Mild pressure toward bins with below-average residual (tighter bins first),
    // keeping some diversity in open bin states.
    let dev = mean_residual - bin_residual as f64;
    score += 0.08 * dev;

    // Harmonic class of item itself: large items (mod classes near capacity halves)
    // should prefer tighter bins.
    if item_size > bin_capacity / 2 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps heavily.
    // A gap that no future item (min size 1) can reasonably use is pure waste.
    if post_residual > 0 {
        if post_residual <= 3 {
            // Nearly full bin: excellent fit, reward strongly.
            score -= 40.0;
        } else if post_residual < 10 {
            // Tiny dead space below minimum item size: worst outcome.
            score += 60.0;
        } else if post_residual <= 15 {
            // Small gap only usable by very small items.
            score += 25.0;
        }
    }

    // Reward tight fits relative to item size.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill_ratio;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 45.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual < 10 {
        // Next item can't use this dead space either.
        score += 20.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: prefer consolidating into existing bins when many are open,
    // but allow new bins when few are open (keeps placement flexibility).
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    score += pressure * 0.8;

    // Compare against mean residual: bins with more room than average are
    // less precious; bins below average residual are scarce, use them.
    if (bin_residual as f64) < mean_residual {
        score -= 8.0;
    } else {
        score += 4.0;
    }

    // New-bin candidate: discourage opening a new bin unless the item is large
    // and no tight option exists. The base post_residual for an empty bin is
    // already high (capacity - item), so this only tips marginal cases.
    if bin_residual == bin_capacity {
        score += 15.0 + 25.0 * (1.0 - fill_ratio);
        // Late in the stream, opening new bins is more wasteful.
        score += 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }

    // Post-residual slightly larger than next item: partial reward proportional to closeness.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 25.0 * (-gap / 15.0).exp();
    }

    // Dead space: post_residual too small for the next item is wasted unless tiny.
    if next_item_size > 0 && post_residual < next_item_size {
        let waste = post_residual as f64;
        score += (waste / 10.0).powi(2) * 1.5;
    }

    // Prefer bins with residual below mean residual (tight packing), i.e. fuller bins.
    score += 0.6 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin fit is terrible
    // (large post_residual that won't hold next item) or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let bad_fit = if next_item_size > 0 && post_residual < next_item_size { 0.0 } else { 25.0 };
        score += 55.0 - bad_fit - 10.0 * (1.0 - progress);
    }

    // Mild penalty for very small unusable leftovers.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: strong discount when post_residual is small.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio) * 18.0;

    // Penalize dead space that is too small to hold a plausible future item
    // (items are >= 1; treat residual < 10 as nearly useless).
    if post_residual < 10 {
        score -= 6.0; // perfect closure is good
    } else if post_residual <= 15 {
        score += 8.0; // awkward sliver: penalize
    }

    // Lookahead: if the next item fits exactly into the post_residual,
    // strongly favor this bin (chained placement).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            score -= 4.0;
        } else {
            // next item won't fit here; mild penalty proportional to waste
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.15;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // avoid opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0 + 0.05 * (bin_residual - item_size) as f64;
    }

    // Prefer fuller bins relative to the mean residual of open bins:
    // placing into a below-mean-residual (fuller) bin is favored.
    score += (bin_residual as f64 - mean_residual) * 0.12;

    // Mild pressure to consolidate when many bins are open.
    score += open_bins_count as f64 * 0.05;

    // New-bin candidate handling: an empty bin has bin_residual == bin_capacity.
    // Make it attractive only when the item is large relative to capacity
    // (poor fit anywhere else) or no tight option exists implicitly.
    if bin_residual == bin_capacity {
        let load_frac = item_size as f64 / bin_capacity as f64;
        // Base neutrality with slight preference for large items in fresh bins.
        score = bin_capacity as f64 * 0.55 - load_frac * 30.0;
        // Discourage opening new bins early in the stream when consolidation
        // is still cheap; encourage later as fragmentation grows.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += (0.5 - progress) * 20.0;
        if fitting_bins_count == 0 {
            score -= 40.0; // no alternative: must open new bin
        }
        if next_item_size > 0 && post_residual >= next_item_size && item_size >= 50 {
            score -= 10.0; // fresh bin enables a good chain for big items
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let residual = bin_residual as f64;
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };

    let mut score = post;

    // Tightness: reward small post_residual non-linearly (quartic shaping).
    let tight = 1.0 - post / cap;
    score -= 12.0 * tight * tight * tight * tight;

    // Exact-ish fit reward when post_residual is small relative to item size.
    if post > 0.0 {
        let ratio = item / post;
        score -= 6.0 * (ratio / (1.0 + ratio));
    } else {
        score -= 10.0; // perfect fill
    }

    // Last-chance bonus: strongly prefer the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (0.5 + progress);
    }

    // Lookahead coupling: penalize if next item could not use post_residual,
    // reward if next item fits snugly into the resulting residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let waste = post - nxt;
            score -= 8.0 * (1.0 - waste / cap) * (1.0 - waste / cap);
        } else {
            let unusable = (nxt - post) / cap;
            score += 10.0 * unusable * unusable;
        }
    }

    // Dead-space penalty: small residuals below the min item size are waste.
    let dead = (10.0 - post).max(0.0) / 10.0;
    score += 15.0 * dead * dead;

    // Relative-to-mean residual shaping: prefer bins deviating from mean in useful ways.
    let dev = (residual - mean_residual) / cap;
    score += 4.0 * dev * dev - 3.0 * dev;

    // New-bin candidate: penalize mildly early, allow late when stream nearly done
    // and existing bins are fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = if open_bins_count > 0 { mean_residual / cap } else { 0.0 };
        score += 18.0 - 30.0 * progress + 10.0 * fragmentation;
        // Prefer new bin if item fits poorly everywhere else.
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    // Stream-progress coupling: later in the stream, be greedier about tight fits.
    score -= 6.0 * progress * (1.0 - post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead-space classes (small residuals are hard to fill)
    let cls = match post_residual {
        0 => 0,          // perfect fit
        1..=10 => 1,     // near-perfect
        11..=25 => 2,    // awkward small gap
        26..=50 => 3,    // medium
        _ => 4,          // large residual, still useful
    };
    // Reward exact and near fits heavily; penalize awkward gaps
    score += match cls {
        0 => -60.0,
        1 => -30.0,
        2 => 20.0,
        3 => 0.0,
        _ => -5.0,
    };

    // Modulo arithmetic on post_residual: residuals that are multiples of common
    // small item sizes (10,20,25,50) are more likely to be filled later.
    let fillable = (post_residual % 10 == 0 && post_residual > 0)
        || (post_residual % 25 == 0)
        || (post_residual % 20 == 0);
    if fillable {
        score -= 8.0 + (post_residual as f64) * 0.05;
    } else if post_residual > 0 {
        score += 6.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            // next item fits: how tight is the second-level fit?
            let second = post_residual - next_item_size;
            score -= 15.0 + (second as f64).min(30.0);
        } else {
            // next item won't fit here; residual wasted relative to lookahead
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a new bin should only win when
    // no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        let mut new_bin_score = (bin_capacity - item_size) as f64;
        // penalize more when many bins are already open and fit exists
        if fitting_bins_count > 0 {
            new_bin_score += 35.0 + 2.0 * (open_bins_count as f64).sqrt() * 5.0;
        }
        // early in stream, allow more bin openings
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        new_bin_score -= (1.0 - progress) * 10.0;
        // if next item is large, a fresh bin is more valuable
        if next_item_size > 50 {
            new_bin_score -= 12.0;
        }
        return new_bin_score;
    }

    // Slight preference for fuller bins overall (best-fit bias)
    score -= (bin_capacity - bin_residual) as f64 * 0.05;

    // Tie-break with mean residual divergence: prefer bins below mean residual
    // (i.e., above-mean fullness)
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Hard reward: perfect fit creates zero dead space.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: residuals that are too small to be useful
    // (below the minimum conceivable item size) are heavy penalties.
    let dead_threshold: u32 = 10;
    if post_residual > 0 && post_residual < dead_threshold {
        score += 500.0 + (dead_threshold - post_residual) as f64 * 20.0;
    }

    // Near-fit bonus: leaving a gap that the next item might fill is good.
    if next_item_size > 0 && post_residual > 0 {
        if post_residual == next_item_size {
            score -= 300.0;
        } else if post_residual >= next_item_size {
            // gap can host next item: mild reward proportional to tightness
            let tightness = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 50.0 * tightness;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless the fit
    // is good; scale penalty with fraction of stream completed.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (2.0 + 6.0 * progress);

    // Prefer bins with residual close to what we consume (tight packing),
    // penalize wasting a large residual on a small item.
    let waste_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score += (1.0 - waste_ratio) * 30.0;

    // Mild pull toward bins whose residual is below mean (consolidate small gaps).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // New-bin candidate: penalize opening a new bin unless no open bin fits
    // well (i.e., only when this empty bin genuinely minimizes score).
    if bin_residual == bin_capacity {
        score += 40.0 + open_bins_count as f64 * 3.0;
        // Allow new bin when current item is large and open bins are fragmented.
        if item_size > bin_capacity / 2 && mean_residual < item_size as f64 {
            score -= 60.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: reward when the next item exactly fills the post residual (perfect 2-step packing).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += gap * 0.8;
        if post_residual == next_item_size {
            score -= 60.0; // exact 2-item closure: strong reward
        } else if next_item_size <= post_residual {
            score -= 10.0; // next item still fits
        } else {
            score += 15.0; // next item won't fit here: penalty
        }
    } else {
        // Last item: prefer minimal post residual.
        score -= 20.0;
    }

    // Relative-to-mean coupling: bins tighter than average are better to fill.
    score += (post_residual as f64 - mean_residual) * 0.5;

    // Penalize large dead space that nothing (min size 1) can use — small post residual is good.
    if post_residual < 10 {
        score -= 12.0;
    }

    // Last-chance bin before opening a new one: strong incentive to use it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current item is huge or bins are few.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = (item_size as f64 / bin_capacity as f64).powi(2);
        score += 40.0 - 30.0 * pressure - 10.0 * progress;
        // Prefer opening a new bin if the item would leave a big hole in an existing bin.
        if post_residual > bin_capacity / 2 {
            score -= 35.0;
        }
    }

    // Slight preference for bins that will become nearly full (waste minimization).
    let fill_ratio = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * fill_ratio * 15.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual) with a non-linear term.
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 60.0;

    // Lookahead: if the next item can fit into the post residual, reward this bin.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Perfect chaining: next item exactly fills leftover space.
            let chain_waste = (post_residual - next_item_size) as f64;
            score -= 12.0 - (chain_waste / bin_capacity as f64) * 10.0;
        } else {
            // Next item cannot chain here: slight penalty scaled by gap size.
            let gap = (next_item_size - post_residual) as f64;
            score += (gap / bin_capacity as f64) * 8.0;
        }
    } else {
        // Last item in stream: only absolute tightness matters, extra reward.
        score -= 5.0;
    }

    // Last-chance bonus: this is the only bin that fits; avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Penalize bins whose residual deviates far below the mean residual
    // (they are "precious" small-capacity bins; save them unless fit is tight).
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score += (dev / bin_capacity as f64) * 10.0;
    }

    // Time horizon: early in the stream, be more willing to spread load
    // (mildly reward larger residuals); late in the stream, pack tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * (bin_residual as f64 / bin_capacity as f64) * 4.0;

    // Many open bins: encourage consolidation into existing bins.
    score += (open_bins_count as f64).ln().max(0.0) * 1.5;

    // New-bin candidate handling: it has bin_residual == bin_capacity.
    // Penalize opening a new bin, but less when the current item is large
    // (a big item leaves little waste in a fresh bin anyway) and when
    // no tight option exists is implicitly handled by other terms.
    if bin_residual == bin_capacity {
        let big_item_relief = (item_size as f64 / bin_capacity as f64) * 20.0;
        score += 25.0 - big_item_relief;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Base: penalize post_residual, with non-linear (quadratic) waste term
    let mut score = pr + 40.0 * norm_pr * norm_pr * cap;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, prefer tight fits less; later, demand tighter packing.
    let progress_coupling = (1.0 + 3.0 * progress * progress) * (1.0 - norm_pr * (2.0 - progress));
    score += 30.0 * progress_coupling;

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Lookahead: reward if next item can fit into the post-residual
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 12.0 * (next_item_size as f64 / cap) * (1.0 + progress);
    } else if next_item_size > 0 {
        // dead space penalty if next item won't fit in the leftover
        score += 8.0 * (1.0 - norm_pr) * (1.0 + progress);
    }

    // Prefer bins with residual below mean (consolidating small leftovers)
    score += 6.0 * ((pr - mean_residual) / cap).tanh();

    // Mildly discourage scattering across many open bins early on
    score += 0.15 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate: penalize slightly unless current bin would leave awkward waste
    if bin_residual == bin_capacity {
        let awkward = norm_item * (1.0 - norm_item);
        score += 10.0 - 18.0 * awkward * (1.0 + progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify dead space by residue mod 10
    let r = post_residual;
    if r > 0 {
        let class = r % 10;
        // Residuals that are "usable" (multiples of 10, or >= 10) get a bonus
        if class == 0 {
            score -= 6.0; // perfect harmonic alignment
        } else if r < 10 {
            score += 8.0; // tiny dead space, unusable for items >= 1? still penalize mildly
        } else {
            // awkward class: penalize proportional to misalignment
            score += (class as f64) * 0.4;
        }
    } else {
        // perfect fit
        score -= 25.0;
    }

    // Lookahead coupling: does post_residual fit the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // exact harmonic match with next item is excellent
            let slack = post_residual - next_item_size;
            if slack % 10 == 0 {
                score -= 5.0;
            }
            score -= (next_item_size as f64) * 0.05;
        } else {
            // bin will be dead for next item
            score += 4.0;
        }
    } else {
        // last item: strongly prefer tight fits
        score -= 10.0;
    }

    // Last-chance bin: if this is the only fitting bin, favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 7.0;
    }

    // New-bin candidate: penalize opening a new bin unless item is large
    if bin_residual == bin_capacity {
        score += 12.0;
        if item_size >= 50 {
            score -= 10.0;
        }
        // late in stream, prefer reusing existing capacity
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 6.0;
    }

    // Prefer bins below mean residual (tighter bins) mildly
    score += (mean_residual - bin_residual as f64) * 0.05;

    // Integer-division threshold on item size: big items prefer emptiest bins
    let size_class = item_size / 20; // 0..4
    score += (size_class as f64) * (bin_residual as f64 - post_residual as f64) * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / (total_items.max(1) as f64);
    let min_useful = 10.0_f64.min(bin_capacity as f64 * 0.1);

    // Strict dead-space avoidance: tiny leftover gaps are almost unusable.
    let pr = post_residual as f64;
    if pr > 0.0 && pr < min_useful {
        score += (min_useful - pr) * 6.0; // heavy penalty for unusable slivers
    }
    if pr == 0.0 {
        score -= 40.0; // perfect fit strongly rewarded
    }

    // Tightness reward: fraction of residual consumed by this item.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 25.0;

    // Last-chance pressure: if this is the only bin that fits, prefer it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New empty bin candidate: neutral baseline; only attractive when the
    // alternative is a bad fit. Give it a mild penalty that grows with
    // progress so late in the stream we consolidate rather than open bins.
    if bin_residual == bin_capacity {
        score += 12.0 + 30.0 * progress;
        // But if next item is large and this item is small, opening a fresh
        // bin may preserve big residual for the next item.
        if next_item_size > 0 && (next_item_size as f64) > pr + min_useful && pr > 0.0 {
            score -= 20.0;
        }
    }

    // Open-bin pressure: with many open bins, favor filling existing ones.
    score += (open_bins_count as f64).ln().max(0.0) * 3.0;

    // Slight preference for bins with residual close to the mean (balance).
    score += ((bin_residual as f64 - mean_residual) / bin_capacity as f64).abs() * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong base preference for tight fits
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // 2-step lookahead: reward if the next item fits exactly/nicely in post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            // Perfect chain: place here to set up a perfect next placement
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Next item fits: bonus scaled by how much slack remains after it
            let next_post = post_residual - next_item_size;
            score -= 25.0 * (1.0 - next_post as f64 / bin_capacity as f64);
        } else {
            // Next item does NOT fit after this placement: penalize,
            // worse when post_residual is small (dead space) relative to next item
            let gap = (next_item_size - post_residual) as f64;
            score += 0.6 * gap.min(60.0);
            // Extra penalty for leaving tiny unusable slivers
            if post_residual < 10 {
                score += 15.0;
            }
        }
    }

    // Prefer bins already below mean residual (consolidating waste)
    score -= 0.3 * (mean_residual - bin_residual as f64);

    // Last-chance bonus: if this is the only bin that can fit the item, strongly favor it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Discourage opening new bins when open bins exist and fit is decent
    if bin_residual == bin_capacity {
        // New bin candidate: neutral residual, add penalty unless lookahead chain is perfect
        score += 20.0;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 15.0;
        }
        // Early in stream, new bins are cheaper to open
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
    }

    // Mild penalty for fragmenting many open bins
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: strongly favor low post-residual (non-linear).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        // Dead space below minimum item size is nearly unusable.
        score -= 8.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // unless the fit is terrible (huge dead space).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
        if post_residual as f64 > mean_residual {
            score += 6.0; // but penalize if it leaves more waste than average
        }
    }

    // New-bin candidate handling: empty bin should only win when open bins fit badly.
    if bin_residual == bin_capacity {
        // Base penalty so existing decent fits are preferred.
        score += 18.0;
        // Early in the stream, opening bins is cheap and useful for future flexibility.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * (1.0 - progress);
        // If no open bin fits, opening is necessary (fitting_bins_count counts only open ones).
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // If open bins are nearly full on average, a fresh bin is attractive.
        if mean_residual < item_size as f64 * 1.2 {
            score -= 8.0;
        }
    }

    // Lookahead coupling: if the next item could exactly fill this bin's post-residual,
    // that's a great chaining opportunity.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            // Next item fits: leftover after both matters.
            let second_leftover = post_residual - next_item_size;
            score -= 6.0 * (1.0 - second_leftover as f64 / bin_capacity as f64);
            if second_leftover < 10 {
                score += 5.0; // creates dead space after two placements
            }
        } else {
            // Next item won't fit here: mild penalty proportional to overflow.
            let overflow = (next_item_size - post_residual) as f64;
            score += 0.05 * overflow;
        }
    }

    // Penalize leaving residuals that no plausible item (min size 1, typical mid) can use:
    // tiny residuals are waste; large residuals are flexible.
    let r = post_residual as f64;
    if r > 0.0 && r < 10.0 {
        score += (10.0 - r) * 1.5;
    }

    // Mild preference to spread load when many bins are open (balance residuals).
    score += 0.02 * (post_residual as f64 - mean_residual).abs();

    // Slight time discount: later in stream, be more greedy (favor tight fits harder).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 4.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, tolerate leftover space; later, penalize it more aggressively.
    let progress_coupling = post * post / cap * (0.5 + 1.5 * progress * progress);
    score += progress_coupling;

    // Smooth quadratic penalty on post_residual relative to mean residual:
    // prefer bins whose leftover tracks (or undercuts) the fleet average.
    let dev = post - mean_residual;
    score += 0.05 * dev * dev / cap;

    // Dead-space term: cubic penalty when leftover becomes unusable for
    // typical items (smooth ramp around the smallest plausible item size).
    let dead = ((item_size as f64) - post).max(0.0);
    score += 0.02 * dead * dead * dead / (cap * cap);

    // Lookahead: reward bins whose leftover can host the next item,
    // penalize leftovers just barely too small for it.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            score -= 3.0 * (1.0 - post / cap) * (1.0 - progress);
        } else {
            let gap = (nxt - post) / cap;
            score += 2.0 * gap * gap * cap;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // over opening a new bin (smooth decay as more bins fit the item).
    if fitting_bins_count >= 1 {
        let scarcity = 1.0 / fitting_bins_count as f64;
        score -= 6.0 * scarcity * (0.4 + 0.6 * progress);
    }

    // New-bin candidate bias: make the empty bin mildly attractive only when
    // existing residuals are poor, via smooth interaction with mean_residual.
    if bin_residual == bin_capacity {
        let mean_frac = (mean_residual / cap).clamp(0.0, 1.0);
        score += 8.0 - 10.0 * mean_frac * (1.0 - mean_frac) * 4.0;
        score += 2.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how "reusable" is the leftover space?
    // Class 0: perfect fill (post_residual == 0) -> strongly reward.
    // Class 1: post_residual < 10 (unusable dead space for typical items) -> penalize hard.
    // Class 2: post_residual divisible cleanly (fits common size classes) -> mild reward.
    let progress = step_index as f64 / (total_items.max(1) as f64);

    if post_residual == 0 {
        score -= 1000.0; // perfect fit: always prefer
        return score;
    }

    // Dead space: leftover too small for the smallest plausible item (1..100 range, use ~10 as threshold)
    if post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 4.0;
    } else {
        // Modulo harmonic classes: reward leftovers that are multiples of common item granularities
        if post_residual % 10 == 0 {
            score -= 8.0;
        }
        if post_residual % 20 == 0 {
            score -= 6.0;
        }
        if post_residual % 25 == 0 {
            score -= 5.0;
        }
        if post_residual % 50 == 0 {
            score -= 6.0;
        }
    }

    // Integer-division threshold classes on post_residual
    let class = post_residual / 10; // 0..10 harmonic band
    score += class as f64 * 1.5; // prefer tighter fills within usable range

    // Lookahead coupling: does this bin's post-residual still serve the next item?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item can chain into this bin -> reward proportional to tightness of that fit
            let chain_gap = post_residual - next_item_size;
            if chain_gap == 0 {
                score -= 200.0; // perfect chain
            } else if chain_gap < 10 {
                score -= 15.0;
            } else {
                score -= 5.0;
            }
        } else {
            // next item cannot use this bin: leftover becomes dead weight
            score += 12.0;
            if post_residual < next_item_size && post_residual < 10 {
                score += 25.0; // double penalty: dead for both current and next
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin unless fit is terrible
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + item_size as f64 * 0.2;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad
    if bin_residual == bin_capacity {
        // base cost of a fresh bin
        score += 70.0;
        // allow new bin when existing fits leave lots of dead space
        let waste = post_residual; // = capacity - item
        if waste > 60 {
            score -= 40.0; // big item into fresh bin is fine
        }
        // late in stream, prefer consolidating into open bins
        score += progress * 20.0;
        // many open bins: discourage more
        score += open_bins_count as f64 * 2.0;
    }

    // Mean residual context: placing into a bin far below mean residual is wasteful
    let dev = mean_residual - post_residual as f64;
    if dev > 0.0 {
        score += dev * 0.15;
    } else {
        score += dev * 0.05; // slight reward for tighter-than-average bins
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any future
    // item (items >= 1, but realistically small usable gaps matter) are dead space.
    // Penalize unusable small gaps heavily (post_residual in 1..=10).
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0 * (1.0 - (post_residual as f64) / 10.0);
    }

    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Reward tight fits: fraction of residual consumed.
    let fill_frac = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fill_frac * fill_frac;

    // Penalize wasting a large residual on a small item (poor utilization).
    if fill_frac < 0.3 && post_residual > 20 {
        score += 15.0;
    }

    // Lookahead: if next item fits exactly in the post_residual, reward heavily.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 70.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item won't fit here -> this residual is likely dead space.
        score += 20.0;
    }

    // Open-bin pressure: fewer open bins is better; encourage consolidation
    // when many bins are already open.
    score += 2.0 * open_bins_count as f64;

    // Last chance: if this is the only bin that can fit the item, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 100.0;
    }

    // New-bin candidate: only attractive if the item fits poorly everywhere
    // else or mean residual across open bins is very low.
    if bin_residual == bin_capacity {
        // Base penalty so a new bin is only chosen when justified.
        score += 40.0;
        // If no open bin fits (fitting_bins_count == 0 open bins fit, only new bin),
        // the new bin call is the natural choice.
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
        // If mean residual is small, opening a fresh bin is reasonable.
        score -= 0.5 * mean_residual;
        // Late in the stream, prefer reusing bins to avoid excess bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
        // If the next item is large, a fresh bin can serve both.
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 15.0;
        }
    }

    // Slight bonus for bins already below mean residual (balancing residuals
    // keeps future flexibility).
    if (bin_residual as f64) < mean_residual && bin_residual != bin_capacity {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more than linearly.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tight * tight;

    // 2-step lookahead: if the next item fits exactly in the post residual,
    // strongly favor this bin (perfect 2-item packing).
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let diff = post_residual as f64 - next;
        if diff == 0.0 {
            score -= 25.0; // exact two-item completion
        } else if diff > 0.0 && diff <= 10.0 {
            score -= 14.0; // near-exact next fit
        } else if diff < 0.0 {
            // next item won't fit here; penalize by how wasted the space is
            score += 0.35 * (-diff);
        }
        // mild reward if next item would fit with small slack
        if diff > 10.0 && diff <= 25.0 {
            score -= 5.0;
        }
    }

    // Prefer bins whose residual is below the mean (concentrate waste),
    // penalize dipping into large-residual bins for small items.
    let mr = mean_residual;
    if (bin_residual as f64) > mr + 15.0 {
        score += 4.0;
    } else if (bin_residual as f64) < mr - 15.0 {
        score -= 3.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate: make it unattractive unless item is huge relative
    // to all residuals (handled implicitly by fitting bins' low scores);
    // add a fixed opening cost plus slight early-stream relaxation.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 - 8.0 * progress;
        // if the item nearly fills a fresh bin, opening is reasonable
        if item_size >= 70 {
            score -= 15.0;
        }
    }

    // Slight penalty for leaving many open bins around (fragmentation control)
    score += 0.15 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) with a non-linear bonus.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 6.0 * tightness * tightness;

    // Penalize dead space: residuals too small for any plausible future item (1..100).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // nearly unusable sliver
    } else if post_residual >= 10 && post_residual < 30 {
        score += 8.0 * (1.0 - (post_residual as f64 / 30.0));
    }

    // Lookahead: if the next item fits exactly in the post residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0; // perfect chaining
        } else if next_item_size <= post_residual {
            score -= 6.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; slight penalty proportional to wasted potential
            score += 2.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
        if post_residual < 5 {
            score -= 5.0; // still worth using the bin fully
        }
    }

    // Many open bins: prefer consolidating into existing bins rather than spreading.
    if open_bins_count > 4 {
        let pressure = (open_bins_count as f64).ln();
        score -= pressure * tightness * 3.0;
    }

    // Compare against mean residual: bins with residual far below mean are scarce
    // resources; using them for a good fit is valuable.
    let dev = bin_residual as f64 - mean_residual;
    if dev < 0.0 {
        score += 0.05 * dev; // small residual bins slightly favored when fit is good
    } else {
        score += 0.03 * dev; // large-residual bins deprioritized (save them for big items)
    }

    // Time horizon: early in the stream, be more liberal about opening new bins
    // (keeps flexibility); late in the stream, pack tightly into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive early, expensive late.
        score += 12.0 * progress - 4.0 * (1.0 - progress);
        if item_size > bin_capacity / 2 {
            score -= 5.0; // big items start fresh bins cleanly
        }
    } else {
        score -= 3.0 * progress * tightness;
    }

    // Mild penalty when item barely fits with large leftover that no typical item uses.
    if post_residual > 60 {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear coupling: reward small post_residual more strongly as stream progresses.
    let tightness = 1.0 - pr / cap; // 0..1, higher = tighter fit
    score -= (progress * tightness * tightness) * 12.0;

    // Smooth penalty for large post_residual, amplified late in the stream.
    let waste_norm = pr / cap;
    score += waste_norm * waste_norm * (8.0 + 10.0 * progress);

    // Lookahead: bonus if next item fits into post_residual, decaying smoothly.
    if next_item_size > 0 && next_item_size as f64 <= pr {
        let fit_quality = next_item_size as f64 / pr.max(1.0);
        score -= 6.0 * fit_quality * (1.0 - 0.3 * progress);
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 9.0;
    }

    // Mild preference for consolidating into few bins when many are open.
    score -= (open_bins_count as f64).ln().max(0.0) * (1.0 - tightness);

    // New-bin candidate: penalize slightly, but relax early when few bins exist.
    if bin_residual == bin_capacity {
        score += 5.0 - 3.0 * progress - (open_bins_count as f64).ln().max(0.0);
    }

    // Mean-residual coupling: prefer bins whose resulting residual approaches the mean.
    score += ((pr - mean_residual) / cap).abs() * 2.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Harmonic class of the item: which capacity fraction band it falls in.
    let item_class = item_size / 10; // 0..=10 integer division class
    let next_class = (next_item_size as u32).min(bin_capacity) / 10;

    // Reward near-perfect fits strongly (post_residual small).
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 14.0 * tightness * tightness;

    // Dead-space penalty: residuals that are too small for any plausible
    // future item (items >= 1) but awkwardly sized are waste.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0; // unusable sliver
    }

    // Harmonic complementarity: does next_item_size fit exactly in post_residual?
    if next_item_size > 0 {
        let nxt = next_item_size as u32;
        if nxt <= post_residual {
            // Reward when the next item fits into this bin's leftover.
            let slack = post_residual - nxt;
            score -= 6.0 + 0.15 * (slack as f64);
            // Exact harmonic match (complement in same class family).
            if item_size + nxt <= bin_capacity {
                score -= 4.0;
            }
        } else {
            // Next item won't fit here; slight penalty so we don't
            // burn this bin's residual on a bad pairing.
            score += 0.05 * ((nxt - post_residual) as f64);
        }
    }

    // Modulo arithmetic on post_residual: residuals divisible by common
    // item sizes (10/20/25) are "harmonic" and more reusable.
    if post_residual > 0 {
        if post_residual % 10 == 0 { score -= 3.0; }
        if post_residual % 20 == 0 { score -= 2.0; }
        if post_residual % 25 == 0 { score -= 2.0; }
        if post_residual % 5 == 0 { score -= 1.0; }
    }

    // Integer-division thresholds: prefer leaving residuals in the
    // "reusable band" (>= 30, or exactly 0).
    if post_residual >= 30 && post_residual < 50 {
        score -= 2.0;
    } else if post_residual >= 10 && post_residual < 30 {
        score += 3.0; // awkward mid-band residual
    }

    // Last-chance bin: strongly prefer using the only fitting bin
    // rather than opening a new one.
    if fitting_bins_count == 1 {
        score -= 8.0;
    }

    // New-bin candidate handling: a fresh empty bin has high post_residual,
    // which already scores high (bad). Penalize further unless open bins
    // are crowded or the item is large relative to mean residual.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowding = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
        score += 18.0
            - 6.0 * crowding.min(4.0)
            - 10.0 * (item_size as f64 / cap)
            - 5.0 * progress;
        // Opening a new bin is attractive when item is huge and nothing fits well.
        if item_size > 70 { score -= 8.0; }
        if mean_residual < item_size as f64 { score -= 6.0; }
    } else {
        // Mild preference to fill bins that are already quite full.
        let fill = 1.0 - (bin_residual as f64) / cap;
        score -= 4.0 * fill;
    }

    // Stream-progression coupling: late in the stream, consolidation matters.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 2.0 * progress * tightness;

    // Small tie-breaker by class harmony: pair items of the same class
    // (they tend to tile bins in complementary multiples).
    if next_item_size > 0 && next_class == item_class && next_item_size as u32 <= post_residual {
        score -= 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // for typical future items are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 200.0;
    } else if post_residual < 20 {
        score += 60.0;
    } else if post_residual < 30 {
        score += 15.0;
    }

    // Reward tight fits (small relative leftover).
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 40.0 * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead: if next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Pressure from number of open bins: prefer reusing existing bins
    // when many bins are already open.
    score += (open_bins_count as f64).ln().max(0.0) * 3.0;

    // Mean residual context: if this bin is far below mean residual (already tight),
    // mild bonus; if it would leave this bin much emptier than average, mild penalty.
    score += 0.2 * (mean_residual - post_residual as f64);

    // Mild preference for keeping large residuals on fresh bins early in the stream.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += 5.0 + 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Perfect 2-step match: this bin's leftover exactly fits the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }

    // Post-residual can still hold the next item: mild reward proportional to tightness.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 50.0 - 0.4 * slack.min(50.0);
    }

    // Penalize dead space: post_residual too small for next item (and too small to matter).
    if next_item_size > 0 && post_residual < next_item_size {
        score += 0.5 * (next_item_size - post_residual) as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Penalize leaving very small unusable slivers (<10).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Prefer filling bins that deviate from mean residual (reduce variance / consolidate).
    score -= 0.3 * (bin_residual as f64 - mean_residual);

    // Late in stream: prefer tighter fills; early: keep bins balanced.
    score += 20.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when current bin is a bad fit (large post_residual).
    if bin_residual == bin_capacity {
        score += 30.0 + 0.5 * open_bins_count as f64 - (bin_residual as f64 - post_residual as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post-residual is already low, amplify it.
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score += 12.0 * tightness * tightness;

    // Penalize creating dead space that cannot fit the next item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 6.0 + 0.15 * (next_item_size - post_residual) as f64;
        } else {
            // Reward leaving exactly enough room for the next item.
            let gap = (post_residual - next_item_size) as f64;
            score -= 3.0 * (1.0 - gap / (bin_capacity as f64)).max(0.0);
        }
    } else {
        // End of stream: fill bins as tightly as possible.
        score -= 8.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New empty bin candidate: penalize opening a new bin, but relax the
    // penalty when the item is large and would leave a big residual anyway,
    // or when existing bins are crowded.
    if bin_residual == bin_capacity {
        let base_penalty = 20.0;
        let crowding = (mean_residual / (bin_capacity as f64)).clamp(0.0, 1.0);
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let size_factor = (item_size as f64) / (bin_capacity as f64);
        // Big items late in the stream with crowded bins: new bin less bad.
        let relief = 14.0 * size_factor * (0.5 + 0.5 * crowding) * (0.4 + 0.6 * progress);
        score += base_penalty - relief;
    }

    // Mildly prefer bins whose residual is below the current mean
    // (consolidate waste into few bins).
    score += 0.05 * ((bin_residual as f64) - mean_residual);

    // Slight preference for using more-open bins to keep bin count low.
    score += 0.01 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fill = 1.0 - pr / cap; // normalized fullness after placement
    let norm_pr = pr / cap;

    // Base: penalize large residuals, with non-linear (quadratic/cubic) shaping
    let mut score = norm_pr * (1.0 + 2.0 * norm_pr * norm_pr);

    // Smooth coupling: fullness reward amplified as stream progresses
    let coupling = fill * fill * (0.5 + 2.0 * progress * (1.0 - progress) * 4.0);
    score -= 3.0 * coupling;

    // Dead-space penalty: residual too small to likely fit future items
    let dead = if norm_pr < 0.1 { (0.1 - norm_pr) * (0.1 - norm_pr) * 100.0 } else { 0.0 };
    score += dead;

    // Lookahead: reward residual matching next item size (smooth closeness)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let diff = (pr - nx) / cap;
        score -= 2.0 * (-diff * diff * 40.0); // Gaussian-like match reward
    }

    // Last-chance bin bonus (smooth, scaled by fit scarcity)
    if fitting_bins_count > 0 {
        let scarcity = 1.0 / fitting_bins_count as f64;
        score -= 4.0 * scarcity * fill;
    }

    // Mild penalty for proliferating bins early on
    score += (open_bins_count as f64).ln().max(0.0) * (1.0 - progress) * 0.3;

    // Tie-break toward mean residual convergence
    score += 0.1 * (pr - mean_residual).abs() / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover: classify post_residual into capacity fractions.
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap; // fraction of bin left empty

    // Dead-space classes: leftover in (0,10] is nearly perfect; (10,30] is a "harmonic
    // pocket" that many small items (1..30) can still fill; >50 is mostly wasted.
    if post_residual == 0 {
        score -= 60.0; // perfect fit
    } else if post_residual <= 10 {
        score -= 45.0;
    } else if post_residual <= 30 {
        score -= 12.0;
    } else if post_residual <= 50 {
        score += 8.0;
    } else {
        score += 25.0; // large dead space
    }

    // Modulo / divisibility logic: if next item exactly fills the post_residual,
    // this is a golden chaining placement.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 70.0;
        } else if post_residual >= next_item_size {
            // next item still fits here: keep chain alive, reward proportionally
            score -= 10.0 + 0.3 * (post_residual - next_item_size) as f64;
        } else {
            // next item cannot use this leftover: penalize unusable small remainders
            score += 6.0 + 0.2 * next_item_size as f64;
        }
        // Harmonic class match: leftover and next item in same decade -> good pairing
        if post_residual / 10 == next_item_size / 10 && post_residual >= next_item_size {
            score -= 8.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 55.0;
    }

    // New-bin candidate handling: an empty bin has huge residual; make it attractive
    // only when no open bin offers a tight fit (i.e., when post_residual here is large
    // relative to capacity) — otherwise push it behind packed bins.
    if bin_residual == bin_capacity {
        // base competitiveness: fresh bin score ~ capacity minus small bonus
        score = cap - 20.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // slight nudge when lookahead is big too
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // nothing fits elsewhere: must open
        }
    }

    // Congestion control: many open bins with high mean residual -> prefer filling
    // existing bins harder.
    if open_bins_count > 2 {
        score += 0.15 * (open_bins_count as f64 - 2.0) * (frac - 0.2).max(0.0) * 10.0;
        score -= 0.05 * mean_residual.min(50.0);
    }

    // Stream progression: early on, be greedy for tight fits; late, consolidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= (1.0 - progress) * 5.0 * (1.0 - frac);
    score += progress * 3.0 * frac;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        let gap = post_residual as f64;
        // Penalize gaps that are too small for likely future items (below typical min item size).
        if gap < 10.0 {
            score += 25.0 * (10.0 - gap);
        } else if gap < 20.0 {
            // Moderately small gaps: penalize proportionally, but allow near-perfect fits.
            score += 4.0 * (20.0 - gap);
        }
    }

    // Reward tight fits (small post_residual relative to residual).
    let fit_ratio = if bin_residual > 0 { item_size as f64 / bin_residual as f64 } else { 0.0 };
    score -= 8.0 * fit_ratio;

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage opening new bins when many bins are open.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize unless it avoids a very poor fit elsewhere.
        score += 12.0 + 1.5 * open_bins_count as f64;
        // If the next item is small, a fresh bin is more useful.
        if next_item_size > 0 && (next_item_size as f64) <= 0.35 * bin_capacity as f64 {
            score -= 10.0;
        }
        // Late in stream, prefer consolidating into open bins.
        if total_items > 0 {
            let progress = step_index as f64 / total_items as f64;
            score += 15.0 * progress;
        }
    }

    // Prefer bins whose residual is close to the mean (balanced packing).
    score += 0.15 * (bin_residual as f64 - mean_residual).abs();

    // Lookahead: reward leaving space that fits the next item.
    if next_item_size > 0 {
        if post_residual as u64 >= next_item_size as u64 {
            score -= 6.0;
        } else {
            score += 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward exact fills heavily.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: strongly reward placements whose post_residual
    // exactly fits the next item (perfect 2-chain).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // next item can also fit here: mild reward proportional to tightness
            let slack = (post_residual - next_item_size) as f64;
            score -= 50.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // post_residual too small for next item: penalize dead space
            score += 30.0 + 0.5 * post_residual as f64;
        }
    }

    // Compare against mean residual across open bins: bins tighter than
    // average are better candidates for consolidation.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: only attractive when it would beat poor fits.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin, discounted early in the stream
        score += 250.0 - 150.0 * progress;
        // if many bins already fit, opening new is wasteful
        score += 40.0 * fitting_bins_count as f64;
        // if next item is large, a fresh bin is more valuable
        if next_item_size > 0 && next_item_size + item_size > bin_capacity {
            score -= 100.0;
        }
    }

    // Prefer keeping many open bins' residuals large / consolidated:
    // penalize scattering into bins with big residuals when tighter options exist.
    score += 0.2 * (bin_residual as f64 - mean_residual).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong preference for tight fits (small post_residual).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 12.0 * fit_ratio * fit_ratio;

    // Reward filling a bin nearly completely (post_residual very small).
    if post_residual <= 5 {
        score -= 20.0;
    } else if post_residual <= 10 {
        score -= 10.0;
    }

    // Lookahead: penalize if leftover space is a dead zone that next item can't use.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0; // leftover is reusable by the next item
        } else if post_residual > 0 {
            // dead space: worse the larger it is relative to typical item size
            let dead = post_residual as f64;
            score += 0.4 * dead;
        }
    }

    // Last-chance bin: strongly favor using it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize spreading residual across many open bins: prefer compacting.
    score += 0.5 * open_bins_count as f64 * fit_ratio;

    // New-bin candidate handling: opening a new bin is attractive early or when
    // mean residual of open bins is small (poor global fit landscape).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let global_fit = mean_residual / bin_capacity as f64;
        // open new bin if existing bins are crowded (low mean residual)
        let openness = (global_fit - 0.5).clamp(-1.0, 1.0);
        score = 35.0 + 25.0 * progress - 20.0 * openness;
        // never open a new bin when a perfect-ish fit exists elsewhere
        if post_residual == 0 { score = 1e9; }
        if fitting_bins_count == 1 { score += 40.0; }
    }

    // Mild time-horizon modulation: late in stream, consolidation matters more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 4.0 * progress * (1.0 - fit_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let post_norm = post / cap;
    let item_norm = item_size as f64 / cap;
    let next_norm = next_item_size as f64 / cap;

    // Base: penalize leftover space, but with a non-linear (quadratic) curve
    // so small residuals are punished disproportionately (tight fits rewarded).
    let mut score = post * (1.0 + post_norm * post_norm);

    // Smooth non-linear coupling of post_residual with stream progress:
    // early on, waste matters less; later, pack tighter.
    let progress_coupling = 1.0 + 2.0 * progress * progress * (1.0 - post_norm);
    score *= progress_coupling;

    // Reward bins whose residual after placement matches the next item closely
    // (smooth kernel over the gap between post_residual and next_item_size).
    if next_item_size > 0 {
        let gap = (post - next_item_size as f64).abs() / cap;
        score -= 12.0 * (-8.0 * gap * gap).exp();
    }

    // Last-chance bin: strongly favor using it (avoid opening new bins needlessly).
    if fitting_bins_count == 1 {
        score -= 20.0 + 10.0 * item_norm;
    }

    // Slight penalty when many bins are open and this bin is far from the mean residual
    // (encourage balanced residual distribution, smooth cubic weighting).
    let dev = (post - mean_residual) / cap;
    score += open_bins_count as f64 * dev * dev * dev.abs();

    // New-bin candidate: make it moderately attractive only when no open bin fits well.
    if bin_residual == bin_capacity {
        score = post * 1.1 + 5.0 - 8.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues mod common item sizes
    let pr = post_residual;
    let zero = if pr == 0 { 1 } else { 0 };

    // Perfect fit -> huge reward
    score -= 1000.0 * zero as f64;

    // Post-residual modulo classes: small usable leftovers (<=10) are near-perfect
    if pr > 0 && pr <= 10 {
        score -= 120.0;
    }
    // Harmonic classes: post_residual divisible by common small sizes (10,20,25,50)
    if pr > 0 {
        if pr % 10 == 0 { score -= 40.0; }
        if pr % 20 == 0 { score -= 25.0; }
        if pr % 25 == 0 { score -= 20.0; }
        if pr % 50 == 0 { score -= 30.0; }
    }
    // Dead zone: unusable slivers (1..10 already covered); penalize mid dead space 11..19
    if pr >= 11 && pr <= 19 {
        score += 60.0;
    }

    // Lookahead coupling: if next item fits the post residual exactly or well
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if (next_item_size as u32) == pr {
            score -= 300.0;
        } else if next_item_size < pr {
            let left2 = pr - next_item_size;
            if left2 <= 10 { score -= 150.0; }
            if left2 % 10 == 0 { score -= 30.0; }
        } else {
            // next item cannot fit here: leftover must be reusable by others
            score += 10.0;
        }
        // reward if post residual is a harmonic multiple of next item size
        if pr > 0 && next_item_size > 0 && pr % next_item_size == 0 {
            score -= 50.0;
        }
        let _ = ni;
    }

    // Fraction of capacity wasted
    let waste_frac = post_residual as f64 / cap_f;
    score += 30.0 * waste_frac * waste_frac;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }
    // Crowding: many fitting bins -> mild penalty to spread via tightness preference (already via post_residual)

    // New-bin candidate handling: opening a new bin is only attractive when
    // current item is large and mean residual across open bins is small
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let big_item = item_size as f64 > 0.6 * cap_f;
        if big_item && mean_residual < item_size as f64 {
            score -= 150.0 * (1.0 - progress * 0.5);
        } else {
            score += 250.0;
        }
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins)
    score += (mean_residual - bin_residual as f64) * 0.5;

    // Slight preference early in stream to consolidate
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 20.0 * (1.0 - progress) * (1.0 - waste_frac);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small for the smallest
    // plausible future item are pure waste. Penalize them heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 25.0;
    }

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 0.5 * tightness * (item_size as f64);

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading to new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.05 * open_bins_count as f64 * (0.5 + progress);

    // New-bin candidate: neutral-ish baseline, penalize if open bins are
    // underutilized on average (better to fill them first).
    if bin_residual == bin_capacity {
        score += 8.0 + 0.15 * mean_residual;
        // But if this bin is the only option, allow it (score already low enough
        // via the fitting_bins_count logic for real bins).
        if fitting_bins_count <= 1 {
            score -= 30.0;
        }
    }

    // Lookahead: if the next item fits exactly in the post_residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward: item exactly fills the bin.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: strongly reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Chain bonus scaled by tightness of the chain (small leftover after next item).
            let after_next = post_residual - next_item_size;
            score -= 60.0 + (after_next as f64) * 0.5;
            // Extra reward for a perfect two-item chain.
            if after_next == 0 {
                score -= 200.0;
            }
        } else {
            // Penalize creating dead space that the next item cannot use,
            // especially when the dead space is small (unusable sliver).
            let dead = post_residual as f64;
            if dead < next_item_size as f64 {
                score += 30.0 + (next_item_size as f64 - dead) * 0.8;
            }
        }
    }

    // Reward tight fits relative to capacity: small post_residual is good, but
    // only when it's not an unusable sliver for the next item (handled above).
    score -= (bin_residual - post_residual) as f64 * 0.1;

    // Compare against mean residual: prefer bins that are already more filled
    // than average (consolidation strategy).
    if (post_residual as f64) < mean_residual {
        score -= 15.0;
    } else {
        score += (post_residual as f64 - mean_residual) * 0.3;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: make it moderately attractive only when open bins are
    // fragmented or the item is large relative to all residuals.
    if bin_residual == bin_capacity {
        // Base penalty so we don't open bins too eagerly.
        score += 40.0;
        // But if many bins are open and mean residual is small (fragmentation),
        // opening fresh space becomes more attractive.
        if open_bins_count > 3 {
            score -= (open_bins_count as f64) * 2.0;
        }
        if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
            score -= 25.0;
        }
    }

    // Mild stream-progression bias: later in the stream, prefer closing out
    // existing bins more aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Smooth non-linear reward for tight fits: cubic decay of reward with post_residual.
    let tightness = 1.0 - pr / cap; // in (0,1], larger = tighter fit
    score -= 18.0 * tightness.powi(3);
    score -= 6.0 * tightness * tightness * (1.0 + progress);

    // Penalize residuals too small to be useful later (smooth via quadratic in pr).
    let dead_zone = (10.0 - pr).max(0.0);
    score += 0.9 * dead_zone * dead_zone / 10.0;

    // Lookahead coupling: reward residuals that can host the next item smoothly.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (pr - nx).abs();
        let compat = (1.0 - gap / cap).max(0.0);
        score -= 5.0 * compat * compat;
        // If post_residual exactly leaves awkward space vs next item, penalize smoothly.
        if pr < nx {
            score += 3.0 * (nx - pr) / cap * (1.0 + progress);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, discourage opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 4.0;
    }

    // Late-stream consolidation: favor filling existing bins as stream ends.
    score += progress * (pr / cap) * 8.0;

    // Mild penalty when bin is far below mean residual (fragmentation signal).
    score += 0.05 * (mean_residual - pr).abs();

    // New-bin candidate: make empty-bin call less attractive unless nothing fits well.
    if bin_residual == bin_capacity {
        score += 6.0 + 4.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Exact fit: huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: residues divisible by common small sizes
    // (10,20,25,50) are more likely to be filled by future items.
    let pr = post_residual;
    if pr > 0 {
        let harmonic_bonus = if pr % 50 == 0 { 12.0 }
        else if pr % 25 == 0 { 8.0 }
        else if pr % 20 == 0 { 7.0 }
        else if pr % 10 == 0 { 5.0 }
        else { 0.0 };
        score -= harmonic_bonus;
    }

    // Penalize dead space that cannot fit even the smallest plausible item.
    if pr > 0 && pr < 10 {
        score += 30.0;
    }

    // Lookahead: if the next item fits the post residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 150.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 40.0 * (1.0 - slack / cap);
        } else {
            // next item won't fit here; mild penalty proportional to overshoot class
            let over = (next_item_size - pr) as f64;
            score += 5.0 + over / 10.0;
        }
    }

    // Fraction-of-capacity coupling: prefer residuals that are "nice" fractions.
    let post_frac = post_residual as f64 / cap;
    if (post_frac * 4.0).fract() < 1e-9 {
        score -= 6.0; // quarter-multiple residuals are reusable
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // many bins are open with large mean residual (fragmentation) or when
    // this bin's fit is poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a bin, modulated by stream progress and openness.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut new_bin_cost = 60.0 + 40.0 * progress;
        if open_bins_count > 4 && mean_residual > 40.0 {
            new_bin_cost -= 20.0; // fragmentation: a fresh bin may pack better
        }
        if next_item_size > 0 && next_item_size <= bin_capacity {
            new_bin_cost += (next_item_size as f64) * 0.1;
        }
        score += new_bin_cost;
    } else {
        // Mild reward for keeping bins balanced: prefer bins whose residual
        // is near the mean (avoid starving one bin while others stay full).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.15;
    }

    // Integer-division threshold on post_residual: waste buckets.
    let waste_bucket = post_residual / 10; // 0..=10
    score += waste_bucket as f64 * 1.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small to be useful later are costly.
    // Treat gaps < 10 (or < min plausible item) as pure waste; weight them heavily.
    let dead_threshold = 10.0f64;
    if (post_residual as f64) < dead_threshold {
        score += 40.0 * (dead_threshold - post_residual as f64);
    } else {
        // Mild reward for leaving a gap that exactly matches the lookahead item
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 25.0;
        }
        // Reward leaving gaps that can still fit typical items (>= 10)
        score -= 6.0 * ((post_residual as f64) / bin_capacity as f64);
    }

    // Tight fit reward: penalize proportional to wasted fraction
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * waste_ratio * waste_ratio;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the
    // item fits badly everywhere else. Make the empty bin score neutral-ish,
    // penalized slightly more when open bins are few (avoid bin proliferation).
    if bin_residual == bin_capacity {
        score = 0.5 * bin_capacity as f64
            + 5.0 * open_bins_count as f64
            - 2.0 * mean_residual.min(50.0);
        if fitting_bins_count == 1 {
            score += 80.0; // never open new bin when exactly one bin fits
        }
    }

    // Open-bin pressure: mild penalty for bins with residual far from mean
    score += 0.15 * ((bin_residual as f64) - mean_residual).abs();

    // Late-stream consolidation: prefer filling nearly-full bins as stream ends
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - waste_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual closely matches next item
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match bonus (next item exactly fills the bin)
        if post_residual == next_item_size {
            score -= 60.0;
        } else {
            score += gap * 0.6;
        }
        // Penalize leaving residual too small for next item (dead space)
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.4;
        }
    } else {
        // Last item: prefer tightest fit
        score += 10.0;
    }

    // Prefer bins already below mean residual (denser bins get filled)
    score += (mean_residual - post_residual as f64) * 0.15;

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize new-bin candidate mildly unless it's genuinely needed
    if bin_residual == bin_capacity {
        score += 30.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0; // fresh bin can host next item too
        }
    }

    // Late in stream: tighten packing more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * (0.2 + 0.3 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (low post_residual) non-linearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * fit_ratio * fit_ratio;

    // Penalize wasted capacity relative to current item size.
    score += 0.35 * (bin_residual as f64 - item_size as f64).max(0.0);

    // Lookahead: if the next item fits exactly in the post-residual, big bonus.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; mildly penalize leaving awkward residuals.
            score += 6.0;
        }
        // Perfect chain: next item exactly fills the bin.
        if post_residual == next_item_size {
            score -= 30.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when existing bins fit poorly.
    if bin_residual == bin_capacity {
        let avg_fit = if fitting_bins_count > 0 { mean_residual } else { bin_capacity as f64 };
        let pressure = (item_size as f64) / bin_capacity as f64;
        // Prefer new bin when item is large relative to mean residual spread.
        score -= 15.0 * pressure;
        score += 0.5 * (mean_residual - item_size as f64).max(0.0);
        // Early in stream, opening bins is cheap; later, prefer consolidation.
        let t = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * t;
        let _ = avg_fit;
    }

    // Prefer filling bins with many open bins (limit bin proliferation).
    score += 0.15 * open_bins_count as f64 * fit_ratio;

    // Time horizon: as stream progresses, prioritize compacting residuals.
    let t = step_index as f64 / (total_items.max(1) as f64);
    score += t * 8.0 * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Smooth non-linear penalty on wasted residual, amplified as stream progresses.
    let norm_post = post / cap;
    score += 18.0 * norm_post * norm_post * (0.4 + 0.6 * progress);

    // Reward tight fits (small post_residual) more strongly later in the stream.
    score -= 12.0 * (1.0 - norm_post) * (1.0 - norm_post) * (0.5 + 0.5 * progress);

    // If the next item exactly fits the resulting residual, strongly favor this bin.
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if ns == post {
            score -= 25.0;
        } else if ns < post {
            let leftover = (post - ns) / cap;
            score += 10.0 * leftover * leftover;
        } else {
            // next item cannot use this residual: mild penalty scaled by dead space
            score += 6.0 * norm_post;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Penalize bins whose residual deviates far below the mean (fragmented bins),
    // with a smooth coupling to how many bins are open.
    let open_f = open_bins_count as f64;
    let dev = (mean_residual - post) / cap;
    score += 4.0 * dev * dev * (1.0 + open_f / 20.0);

    // Slight preference to keep fewer bins open early on (fill existing first),
    // but allow spreading when many bins are already open.
    score += (open_f / (open_f + 10.0)) * 3.0 * norm_post;

    // New-bin candidate: make empty bins moderately attractive only when the fit
    // elsewhere would be poor; an empty bin has zero post-residual penalty already,
    // so add a small opening cost that tight fits can overcome.
    if bin_residual == bin_capacity {
        score += 8.0 + 4.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small residue" classes are nearly full -> reward them.
    let pr = post_residual;
    let class = pr / 10; // integer division thresholds: 0..10 classes
    let harmonic_weight = match class {
        0 => -12.0, // post_residual < 10: bin is sealed, excellent
        1 => -8.0,
        2 => -5.0,
        3 => -2.5,
        4 => 0.0,
        5 => 1.5,
        6 => 3.0,
        7 => 4.5,
        8 => 6.0,
        9 => 7.5,
        _ => 9.0,
    };
    score += harmonic_weight;

    // Modulo coupling: residues divisible by common item granularities (5,10)
    // are more reusable by future items.
    if pr % 10 == 0 && pr > 0 {
        score -= 4.0;
    } else if pr % 5 == 0 && pr > 0 {
        score -= 2.0;
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // this placement chains perfectly.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 15.0;
        } else if next_item_size < pr {
            let slack = (pr - next_item_size) as f64;
            // prefer chains leaving small slack; harmonic penalty on slack
            score += slack * 0.3;
            if (pr - next_item_size) % 5 == 0 {
                score -= 2.0;
            }
        } else {
            // next item cannot use this bin's residue: penalize big residues
            score += pr as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: opening a new bin should only win when no
    // open bin offers a decent fit. Base new-bin score on wasted capacity.
    if bin_residual == bin_capacity {
        // waste = capacity - item_size, but it is fresh capacity, usable later
        let waste = post_residual as f64;
        score = waste * 0.9 + 6.0;
        // late in the stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 4.0;
        // if many bins already open, discourage further proliferation
        score += open_bins_count as f64 * 0.4;
    }

    // Mild preference for bins tighter than average (good fits).
    let res_f = bin_residual as f64;
    if mean_residual > 0.0 {
        score += (res_f - mean_residual) * 0.08;
    }

    // Exact fit is always ideal.
    if post_residual == 0 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Dead space: small unusable gaps are the worst outcome.
    // A residual is "unusable" if no plausible future item (1..=100) is likely,
    // but especially if it's below the minimum item size (1) — never happens —
    // so we treat small residuals (< 10) as near-dead.
    if post_residual < 10 {
        score += 200.0;
    } else {
        // Non-linear dead-space penalty: penalize residuals that few item sizes could use.
        // Fraction of item sizes (1..=100) that would NOT fit into post_residual.
        let unusable_frac = 1.0 - (post_residual.min(100) as f64) / 100.0;
        score += 40.0 * unusable_frac * unusable_frac;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 150.0;
        } else if next_item_size <= post_residual {
            score -= 0.5 * (post_residual - next_item_size) as f64;
        } else {
            // Next item won't fit here; this residual becomes more dead.
            score += 0.3 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Open-bins pressure: when many bins are open, prefer consolidating
    // (favor bins with low residual); when few bins are open, tolerate spreading.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * (post_residual as f64 / bin_capacity as f64) * (20.0 + 30.0 * progress);

    // Prefer bins tighter than the mean residual (pack full bins first).
    let mean_r = mean_residual.max(0.0);
    if (post_residual as f64) < mean_r {
        score -= 0.5 * (mean_r - post_residual as f64).min(50.0);
    } else {
        score += 0.3 * ((post_residual as f64) - mean_r).min(50.0);
    }

    // New-bin candidate: opening a fresh bin should only win when no decent fit exists.
    if bin_residual == bin_capacity {
        // Base cost of a new bin, softened if existing fits are terrible.
        score += 60.0 + 0.5 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: aggressive 2-step lookahead matching.
    // Reward bins whose post_residual can host the next item exactly or well.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // Perfect chain match gets a big reward; larger slack is penalized.
            score -= 60.0 - 0.5 * slack;
            // Extra bonus for exact pairing (post_residual == next_item_size).
            if post_residual == next_item_size {
                score -= 40.0;
            }
        } else {
            // Cannot host next item: penalize proportionally to the shortfall.
            let shortfall = (next_item_size - post_residual) as f64;
            score += 0.3 * shortfall;
        }
    }

    // Compare post_residual against mean residual across open bins.
    // Leaving a residual close to (but below) mean wastes less usable space.
    let dev = post_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // Penalize creating very small unusable dead space (unfillable slivers).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when no open bin fits well,
    // i.e. when current item is large relative to residual.
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        // Prefer new bin when item nearly fills it or no other bin fits.
        score = 100.0 - 40.0 * tightness;
        if fitting_bins_count == 0 {
            score -= 80.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 30.0;
        }
    }

    // Mild late-stream consolidation: prefer filling existing bins as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: bonus proportional to fill ratio of the bin after placement.
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 12.0 * fill * fill;

    // Penalize dead space: post_residual that is too small to ever hold a typical item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0; // hard to fill
    }

    // Lookahead: if the next item fits exactly in the post residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; slight penalty if we waste a lot of residual
            score += 0.05 * post_residual as f64;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits to avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin, more so when good fits exist
    // and many bins are already open with slack.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut penalty = 18.0 + 10.0 * progress;
        if fitting_bins_count > 0 {
            penalty += 6.0 * (fitting_bins_count as f64).min(5.0);
        }
        if mean_residual > 25.0 {
            penalty += 5.0;
        }
        // If item is huge relative to capacity, opening fresh is less bad.
        penalty -= 8.0 * (item_size as f64 / bin_capacity as f64);
        score += penalty.max(0.0);
    }

    // Mild preference for bins with residuals below the mean (consolidate slack).
    if bin_residual != bin_capacity {
        score += 0.1 * (bin_residual as f64 - mean_residual).max(0.0);
    }

    // Time horizon: late in the stream, be more conservative about residual waste.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 0.05 * post_residual as f64;

    // Small tie-breaker favoring fewer open bins (consolidation).
    score += 0.01 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on, small residuals matter less; late in the stream, dead space is costly.
    let pr_norm = pr / cap;
    let progress_sq = progress * progress;
    score += 40.0 * pr_norm * pr_norm * (0.5 + progress_sq);

    // Reward tight fits (small post_residual) more strongly as stream advances.
    let tightness = 1.0 - pr_norm;
    score -= 30.0 * tightness * tightness * (0.3 + progress);

    // Penalize leaving residual that cannot fit the next item (smooth quadratic).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx {
            let gap = (nx - pr) / cap;
            score += 25.0 * gap * (1.0 + progress);
        } else {
            let slack = (pr - nx) / cap;
            score += 8.0 * slack * slack;
        }
    }

    // Last-chance bonus: strongly favor the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 20.0 + 15.0 * progress;
    }

    // Mild pressure from many open bins: encourage filling existing ones.
    let open_norm = open_bins_count as f64 / (open_bins_count as f64 + 10.0);
    score += 10.0 * open_norm * pr_norm;

    // Penalize bins far from the mean residual (fragmentation smoothing).
    let dev = (pr - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // Slight bias against opening a new bin unless post_residual is large.
    if bin_residual as f64 == cap {
        score += 12.0 * (1.0 - progress) + 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residues that are "dead" (too small
    // for typical items) get penalized via modulo arithmetic.
    let dead_threshold = bin_capacity / 10; // 10 units
    if post_residual > 0 && post_residual < dead_threshold {
        score += (dead_threshold - post_residual) as f64 * 2.0;
    }

    // Perfect fit reward: post_residual exactly divisible into capacity fractions
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual % 10 == 0 {
        score -= 10.0;
    } else if post_residual % 5 == 0 {
        score -= 4.0;
    }

    // Integer-division thresholds: post_residual class relative to item size
    let fits_next = next_item_size > 0 && post_residual >= next_item_size;
    if next_item_size > 0 {
        if fits_next {
            // Reward bins whose leftover can host the next item, scaled by
            // how "tight" that future fit is.
            let tightness = (post_residual - next_item_size) as f64;
            score -= 20.0 - tightness.min(20.0) * 0.5;
        } else {
            // Penalize leaving a gap that the next item cannot use
            score += (next_item_size as f64) * 0.3;
        }
    }

    // Exact match of post_residual to next item: chain-fit jackpot
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Prefer filling bins that are already relatively full (small residual class)
    let fill_class = bin_residual / (bin_capacity / 4); // quarter classes
    score -= fill_class as f64 * 3.0;

    // New-bin candidate handling: empty bin starts with a handicap so it is
    // chosen only when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 35.0;
        // Late in the stream, opening new bins is cheaper (fewer future regrets)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 15.0;
        // If the item is large relative to mean residual of open bins, new bin less bad
        if (mean_residual < item_size as f64) && open_bins_count > 0 {
            score -= 20.0;
        }
    }

    // Mild penalty for spreading across many open bins (encourage consolidation)
    score += (open_bins_count as f64) * 0.15;

    // Small harmonic tie-breaker on item size class to stabilize choices
    score += (item_size % 3) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Strict dead-space avoidance: gaps that no plausible item can fill are heavily penalized.
    // Treat gaps below ~10 (or below the current item's size class) as dead space.
    let dead_threshold = (item_size.min(bin_residual)).max(1) as f64;
    if post_residual > 0 && post < dead_threshold.min(12.0) {
        score += 40.0 + (12.0 - post) * 8.0;
    }
    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }
    // Reward leaving room for the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + next_item_size as f64 * 0.15;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Gap just below the next item: likely dead space.
        score += 6.0 + (next_item_size as f64 - post) * 0.5;
    }

    // Tightness reward: relative fill of the bin before placement.
    let fill_ratio = (bin_residual as f64) / cap;
    score -= (1.0 - fill_ratio) * 10.0;

    // Open-bin pressure: prefer consolidating into existing bins when many are open,
    // but relax pressure when this is the last fitting bin (avoid forced bad fits).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).sqrt() * (3.0 + 4.0 * progress);
    if fitting_bins_count > 1 {
        score -= pressure;
    } else if fitting_bins_count == 1 {
        // Last-chance bin: strong reward unless the resulting gap would be dead.
        score -= pressure + 15.0;
        if post_residual > 0 && post < 10.0 {
            score += 25.0;
        }
    }

    // Mean-residual coupling: bins far below the mean residual are less attractive
    // (save them for bigger items); bins near/below mean fit well here.
    if (bin_residual as f64) > mean_residual + 20.0 {
        score += 5.0;
    } else {
        score -= 3.0;
    }

    // New-bin candidate (empty bin): make it costly so we only open when fits are bad.
    if bin_residual == bin_capacity {
        score = cap - item_size as f64; // post_residual baseline
        score += 18.0 + (open_bins_count as f64).sqrt() * 2.0;
        // But if the only fitting bin would create heavy dead space, allow opening a new bin.
        if fitting_bins_count == 1 && post < 10.0 && post > 0.0 {
            score -= 45.0;
        }
        // Early stream: opening bins is cheaper.
        if progress < 0.3 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when the next item exactly fills
    // the post-residual of this bin (perfect chaining).
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        score -= 40.0 * (1.0 - gap / bin_capacity as f64);
        if gap == 0.0 {
            score -= 60.0;
        }
    } else if next_item_size > post_residual {
        // Next item cannot use the leftover; penalize dead space relative to mean residual.
        score += 0.5 * (post_residual as f64 - mean_residual).abs();
    }

    // Penalize creating tiny unusable fragments (dead space below min item size).
    if post_residual < 1 {
        score += 100.0;
    }

    // Last-chance bonus: if this is the only bin that fits, prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: keep it neutral-to-slightly-worse so we prefer
    // existing bins with good lookahead fits; open a new bin when the
    // current fit leaves large mismatched residual.
    if bin_residual == bin_capacity {
        score += 15.0;
    }

    // Slight preference for tighter bins early (best-fit flavor).
    score += 0.1 * (bin_residual as f64 / bin_capacity as f64);

    // Progress-based nudge: as the stream matures, be greedier about
    // exact matches vs. leaving residual.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - (post_residual as f64 / bin_capacity as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Penalize dead space that no plausible item can fill (items >= 1, min useful chunk)
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // tiny unusable sliver
    } else if post_residual >= 10 {
        // reward residuals that can still hold a typical small item
        score -= 8.0;
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Lookahead: if the next item fits into post_residual, reward this placement
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 25.0;
            // extra reward if next item is large (hard to place later)
            if next_item_size >= 50 {
                score -= 20.0;
            }
        } else {
            // next item won't fit here; mild penalty proportional to overflow
            let gap = (next_item_size - post_residual) as f64;
            score += 0.15 * gap.min(50.0);
        }
    }

    // New-bin candidate logic: empty bin should only win when open bins fit poorly
    if bin_residual == bin_capacity && open_bins_count > 0 {
        // base cost of opening a new bin
        score += 55.0;
        // cheaper to open new bin when many open bins have large residuals already
        if mean_residual > 40.0 {
            score -= 20.0;
        }
        // if current bin is a poor fit (big post_residual), opening new bin is more attractive
        if post_residual as f64 > 0.45 * bin_capacity as f64 {
            score -= 30.0;
        }
        // late in stream, prefer consolidating into open bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 40.0 * progress;
        // avoid opening a bin when this item is huge and would waste most of a fresh bin
        if item_size >= 60 {
            score += 15.0;
        }
    }

    // Mild penalty for placing into bins whose residual deviates far from the mean
    // (keeps residual distribution homogeneous for future items)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Encourage filling already-open bins as bin count grows
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: quadratic coupling of post_residual with stream progress.
    // Early on, prefer tight packing (low post_residual); later, tolerate slack
    // since fragmentation matters less on a long horizon.
    let mut score = pr * (1.0 + 0.5 * pr_norm) - 12.0 * progress * pr_norm * (1.0 - pr_norm);

    // Smooth penalty for dead space too small to be useful later.
    let dead = (pr_norm * (1.0 - pr_norm)).min(0.25);
    score += 8.0 * (0.25 - dead);

    // Lookahead: reward leaving room for the next item (smooth kernel).
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score -= 6.0 * (1.0 - gap / cap).max(0.0) * (1.0 - progress);
    }

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * (1.0 - pr_norm);
    }

    // Mild pressure toward consolidating into fewer bins as stream progresses.
    score += 0.05 * open_bins_count as f64 * (0.5 + progress);

    // Slight preference for bins already below mean residual (balance).
    score += 0.02 * (mean_residual - pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space analysis via integer division thresholds.
    // Residuals <= 9 (below min item size) are pure waste but "sealed" — mildly acceptable.
    if post_residual == 0 {
        // Perfect fit: strongest reward.
        score -= 1000.0;
    } else if post_residual < 10 {
        // Sealed dead space: unusable forever, but bin is "closed" efficiently.
        score -= 40.0 + 4.0 * post_residual as f64;
    } else {
        // Usable residual: reward if the lookahead item can fit into it (chained fit).
        if next_item_size > 0 && next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            score -= 30.0 + 0.5 * slack as f64;
        }
        // Modulo-10 harmonic class: residuals near multiples of 10 tend to recombine
        // with future item sizes drawn from broad ranges.
        let class = post_residual % 10;
        if class == 0 {
            score -= 8.0;
        } else if class >= 7 {
            score += 6.0; // awkward small remainder on top of a usable chunk
        }
        // Penalize mid-range residual that is too big to seal but likely stranded.
        if post_residual > 50 {
            score += 0.2 * (post_residual as f64 - 50.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: penalize opening fresh bins when open bins exist,
    // scaled by how crowded the fleet is.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 25.0 + 3.0 * open_bins_count as f64;
    }

    // Early in the stream: encourage bin consolidation less aggressively;
    // late in the stream: squeeze harder into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    // Slight pull toward bins below mean residual (balance the fleet).
    score += 0.05 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual below the smallest possible
    // item (1) is impossible, but gaps that are too small to be practically
    // reusable are penalized heavily. Treat residuals under ~15 as dead space.
    if post_residual > 0 && post_residual < 15 {
        score += 60.0;
    } else if post_residual < 25 {
        score += 25.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward tight fits relative to the bin capacity.
    score -= 0.3 * (item_size as f64 / bin_capacity as f64) * 100.0;

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoiding opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Pressure from number of open bins: discourage spreading across many bins.
    score += 2.0 * open_bins_count as f64;

    // New-bin candidate: penalize slightly so we only open a new bin when
    // existing bins would create bad dead space.
    if bin_residual == bin_capacity {
        score += 10.0;
        // If the current item would leave a clean gap for the lookahead item,
        // opening a new bin can still be reasonable.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0;
        }
    }

    // Lookahead: reward bins whose post_residual accommodates the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 {
        score += 8.0;
    }

    // Mean residual coupling: prefer bins close to the mean residual
    // (keeps residual distribution balanced).
    score += 0.1 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) relative to mean residual.
    let mean_r = if mean_residual.is_finite() && mean_residual > 0.0 { mean_residual } else { bin_capacity as f64 };
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness;

    // Aggressive 2-step lookahead: perfect match between post_residual and next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Exact match: next item will fill this bin completely.
            score -= 40.0;
        } else if post_residual >= next_item_size {
            // Next item fits here: reward, scaled by how much slack remains after both.
            let double_left = post_residual - next_item_size;
            score -= 20.0 - (double_left as f64) * 0.25;
        } else {
            // Next item does NOT fit after placing here: penalize dead space,
            // worse when the leftover is small (unusable) relative to next item.
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.6;
        }
    } else {
        // Last item: strongly prefer minimal final waste.
        score += (post_residual as f64) * 0.5;
    }

    // Penalize large absolute residuals relative to mean residual (hoarding space).
    score += ((post_residual as f64) - mean_r).abs() * 0.15;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual <= bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate: neutral baseline; slightly discourage opening a new bin
    // when the item is small, but encourage it when it would create a huge
    // residual in an existing bin (handled above). Keep empty-bin score near
    // its residual (bin_capacity) so only good fits beat it.
    if bin_residual == bin_capacity {
        score += 2.0;
    }

    // Mild pressure to consolidate as stream progresses.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (post_residual as f64) * 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear).
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 30.0 * tightness * tightness;

    // Penalize small unusable dead space (post_residual too small for typical items).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 15.0;
    }

    // Last-chance bonus: only this bin fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Lookahead: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        if post_residual == next_item_size {
            score -= 50.0;
        } else {
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Next item won't fit here; mild penalty for wasting space.
        score += 8.0;
    }

    // New-bin candidate: prefer opening a new bin when current item is large
    // relative to residuals or when open bins are fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = mean_residual / bin_capacity as f64;
        // Open new bin if existing bins are tight on average or many bins open.
        score += 55.0 * fragmentation + open_bins_count as f64 * 2.0;
        // Early in the stream, opening fresh bins is cheaper; later, prefer filling.
        score -= 20.0 * (1.0 - progress);
        // If item is large, a fresh bin is safe.
        if item_size >= 50 {
            score -= 15.0;
        }
        // If next item is also large, fresh bin chains well.
        if next_item_size >= 50 {
            score -= 10.0;
        }
    }

    // Discourage spreading across many bins: prefer bins below mean residual
    // (filling emptier-ish bins keeps others flexible is debatable; instead
    // prefer bins with residual near mean to keep balance).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits; non-linear penalty on residual
    let mut score = pr as f64 + 30.0 * norm_pr * norm_pr;

    // Smooth interaction: residual matters more as stream progresses
    score *= 1.0 + 0.8 * progress;

    // Reward bins whose post-residual matches the next item (lookahead coupling)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (pr - nx).abs();
        score -= 12.0 * (1.0 - gap / cap).max(0.0);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    }

    // Mild penalty when bin residual deviates from mean residual (smooth coupling)
    score += 0.15 * (pr - mean_residual).abs();

    // Slight preference for keeping number of open bins small
    score += 0.5 * open_bins_count as f64 * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: capacity fraction buckets
    let frac = item_size as f64 / bin_capacity as f64;
    let item_class = (frac * 4.0).floor() as i32; // 0..3 harmonic quarter classes

    // Post-residual harmonic class: how "reusable" is the leftover space
    let pr = post_residual;
    let pr_class = (pr / 10) % 10; // decade class of leftover

    // Reward tight fits: post_residual in small reusable classes (0,1,2 decades low)
    let tight_bonus = match pr {
        0 => 60.0,                    // perfect fit
        1..=5 => 35.0,
        6..=10 => 22.0,
        11..=20 => 10.0,
        _ => 0.0,
    };
    score -= tight_bonus;

    // Penalize dead space: leftovers that few item classes can use.
    // Usable leftovers are those matching common item sizes (mod 10 bands).
    let usable = pr == 0 || (pr >= 10 && pr <= 80);
    if !usable {
        score += 12.0;
    }

    // Coupling with next item: if the leftover exactly or nearly fits next_item_size, big reward
    if next_item_size > 0 {
        let gap = pr as i64 - next_item_size as i64;
        if gap == 0 {
            score -= 40.0;
        } else if gap > 0 && gap <= 10 {
            score -= 18.0;
        } else if gap < 0 && (-gap) <= 5 {
            // next item nearly fits: slight penalty, wasted potential
            score += 6.0;
        }
        // modulo harmony: pr and next item share a residue class mod 10
        if next_item_size <= pr && (pr % 10) == (next_item_size % 10) {
            score -= 8.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin gets a baseline cost so we prefer
    // reusing open bins unless the fit is poor.
    if bin_residual == bin_capacity {
        score += 30.0 + (open_bins_count as f64).sqrt() * 4.0;
        // But if item is huge and no tight fit possible, new bin is fine
        if item_class >= 3 {
            score -= 15.0;
        }
    }

    // Penalize bins whose residual deviates far from mean (fragmentation control)
    score += ((bin_residual as f64 - mean_residual).abs()) * 0.15;

    // Late in the stream, be more aggressive about closing bins tightly
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (if pr <= 10 { 8.0 } else { 0.0 });

    // Integer-division threshold: bins with post_residual divisible by 5 are more reusable
    if pr % 5 == 0 && pr > 0 {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for any future item are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 15.0;
    } else if post_residual <= 5 {
        score -= 6.0;
    }

    // Tightness coupling: fraction of bin used by this placement.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * tightness;

    // Pressure: penalize opening/selecting bins when many are open, to fill existing bins first.
    score += 0.35 * open_bins_count as f64;

    // Last-chance bin: strongly favor using the only bin that fits, avoiding a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive if no open bin fits well (large item, or all residuals small).
    if bin_residual == bin_capacity {
        let poor_options = mean_residual < item_size as f64 * 1.15;
        if poor_options {
            score -= 18.0;
        } else {
            score += 10.0 + 0.5 * open_bins_count as f64;
        }
    }

    // Lookahead: if next item exactly matches post_residual, this is a perfect pairing.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 18.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 4.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
    }

    // Late in stream: consolidate aggressively into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (bin_residual - post_residual) as f64 / bin_capacity as f64;

    // Prefer bins whose residual is close to the mean (balanced packing).
    score += 0.15 * ((bin_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits: squash the penalty of small post_residual.
    let pr = post_residual as f64;
    score -= 12.0 * (-(pr / 10.0)).exp();

    // Heavy penalty for dead space: post_residual too small for any future item (min size 1).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 2-step lookahead: strongly reward bins whose post_residual matches next_item_size.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        if post_residual >= next_item_size {
            score -= 15.0 * (-(gap / 12.0)).exp();
        } else {
            // next item cannot follow in this bin: mild penalty proportional to waste
            score += 0.35 * gap;
        }
    } else {
        // last item: prefer tightest fit
        score -= 5.0 * (-(pr / 5.0)).exp();
    }

    // Relative-to-mean coupling: bins with residual far below mean are "tight" —
    // prefer packing them (reduce fragmentation), penalize dumping into roomy bins.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.25 * dev;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual <= bin_capacity / 2 {
        score -= 8.0;
    }

    // Late in the stream, consolidate harder.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 2.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Slight preference for filling fuller bins overall.
    score -= 0.1 * (item_size as f64 / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post * 1.0;

    // Reward tight fits (small post_residual) super-linearly.
    score -= (cap - post).powf(1.6) * 0.35;

    // Penalize dead space: residuals too small for typical future items.
    if post > 0.0 && post < 10.0 {
        score += (10.0 - post) * 2.0;
    }

    // Lookahead: if next item fits the post residual, reward strongly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            score -= 12.0 + (post - nxt) * 0.2;
        } else {
            // Next item won't fit here: penalize wasting a big residual on this item.
            score += (nxt - post).max(0.0) * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a bin unless the fit elsewhere is bad.
    if bin_residual == bin_capacity {
        let base = cap * 0.25 + open_bins_count as f64 * 1.5;
        score += base;
        // Late in the stream, prefer closing out bins rather than opening new ones.
        let t = step_index as f64 / total_items.max(1) as f64;
        score += t * 8.0;
        // If next item is large, a fresh bin is more attractive.
        if next_item_size > 0 && (next_item_size as f64) > post.min(cap) {
            score -= 6.0;
        }
    }

    // Global state: many open bins with high mean residual -> favor filling existing bins.
    if mean_residual > 0.0 {
        score += (mean_residual - post) * 0.08;
        if open_bins_count > 4 {
            score -= 2.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit_frac = item_size as f64 / cap;
    let mut score = pr;

    // Reward tight fits: non-linear polynomial in fill ratio.
    let fill = 1.0 - pr / cap;
    score -= 30.0 * fill * fill * fill;

    // Penalize dead space that is too small to be useful later.
    if pr > 0.0 {
        let dead = pr / cap;
        if dead < 0.1 {
            score += 25.0 * (0.1 - dead) * (0.1 - dead) / 0.01;
        }
    }

    // Lookahead coupling: bonus if next item fits exactly in post_residual.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let snug = 1.0 - (pr - nx).abs() / cap;
            score -= 20.0 * snug * snug;
        } else {
            score += 8.0 * (nx - pr) / cap;
        }
    } else {
        // Last item: strongly prefer minimal post_residual.
        score -= 40.0 * fill;
    }

    // Last-chance bin: avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else {
        score += 3.0 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate: penalize mildly, less as stream progresses or bins are many.
    if bin_residual == bin_capacity {
        score += 12.0 - 10.0 * progress - 0.5 * (open_bins_count as f64).ln();
        // Opening new bin is good if mean residual of open bins is small.
        score -= 10.0 * (mean_residual / cap).powi(2);
    }

    // Smooth stream-progress term: late in stream, favor consolidating into fewer bins.
    score += 5.0 * (1.0 - progress) * (mean_residual - pr).abs() / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: integer division thresholds
    let post = post_residual as f64;
    let class = (post_residual / 10).min(9); // 0..9 harmonic class of leftover space

    // Reward small post_residual strongly (best-fit core), non-linearly
    score -= (10.0 - class as f64) * (10.0 - class as f64) * 1.5;

    // Perfect or near-perfect fit gets a big bonus
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 120.0;
    }

    // Penalize dead space: residuals that few future items can use.
    // Items are 1..100, but small residuals (<10) are nearly unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Modulo coupling: if next item exactly fills post_residual, big bonus
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 150.0;
        } else if next_item_size <= post_residual {
            // next item fits here: reward leaving a good harmonic class
            let next_post = post_residual - next_item_size;
            let next_class = (next_post / 10).min(9);
            score -= (10 - next_class) as f64 * 8.0;
            if next_post == 0 {
                score -= 100.0;
            }
        } else {
            // next item cannot use this residual: penalize leaving awkward gaps
            score += 15.0;
        }
    }

    // Harmonic class matching between item and residual (modulo arithmetic on capacity fractions)
    let item_class = (item_size / 10).min(9);
    let res_class = (bin_residual / 10).min(9);
    if item_class == res_class {
        score -= 20.0; // same decile: natural fit
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: only open a new bin when the item is large
    // relative to remaining stream progress and open bins are fragmented.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = if open_bins_count > 0 {
            (mean_residual / cap).clamp(0.0, 1.0)
        } else {
            1.0
        };
        // Penalize new bins generally, less so when open bins are fragmented
        // and the item is large (harmonic class of large items pairs with empty bins).
        let mut penalty = 90.0 * fragmentation;
        if item_size >= 50 {
            penalty -= 30.0 * (item_size as f64 / cap);
        }
        if progress > 0.8 {
            penalty += 20.0; // late stream: consolidate, avoid new bins
        }
        score += penalty;
    }

    // Mild consolidation pressure: prefer bins with below-average residual
    score += (post - mean_residual) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong penalty for small unusable dead space (post_residual < 10 cannot fit any item).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0;
    } else if post_residual < 35 {
        score += 4.0;
    }

    // Reward tight fits (small post_residual relative to bin).
    let fill_ratio = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 25.0 * fill_ratio;

    // Pressure from number of open bins: discourage spreading across many bins.
    score += 1.5 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
        if post_residual == next_item_size {
            score -= 15.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual < 10 {
        // Dead space that even the next item cannot use.
        score += 10.0;
    }

    // Mean residual coupling: prefer bins whose residual is below mean (consolidate).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 2.0;
    }

    // New-bin candidate: make it attractive only when no good fit exists among open bins.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 || post_residual < 10 {
            score -= 20.0;
        } else {
            score += 15.0 + 2.0 * open_bins_count as f64;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }
    // Near-perfect match: next item fits with little slack left.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > post_residual && next_item_size > 0 {
        // Next item won't fit here; penalize proportionally to wasted gap.
        let gap = (next_item_size - post_residual) as f64;
        score += 6.0 * (gap / bin_capacity as f64);
    }

    // Dead-space penalty: small unusable residual (below min item size).
    let min_size = 1.0f64;
    if (post_residual as f64) < min_size.max(0.0) {
        score += 100.0;
    }
    // Penalize residuals too small to be useful relative to mean residual.
    let pr = post_residual as f64;
    if pr < mean_residual {
        score += 0.5 * (mean_residual - pr);
    } else {
        score -= 0.2 * (pr - mean_residual);
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Prefer filling tight bins: reward small post_residual relative to capacity.
    score -= 10.0 * (1.0 - pr / bin_capacity as f64);

    // Early in the stream, allow opening new bins more freely to build diversity.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost, cheaper early, expensive late.
        score = bin_capacity as f64 - 15.0 * (1.0 - progress) + 25.0 * progress;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = 1.0 - (post_residual as f64) / cap;
    score -= 24.0 * fill_ratio * fill_ratio;

    // Penalize dead space that no future item (min size 1, typical >=10) can use.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0; // unusable sliver
    } else if post_residual >= 10 && post_residual < 20 {
        score += 6.0; // awkward but usable
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let waste = post_residual - next_item_size;
            score -= 15.0 * (1.0 - waste as f64 / cap);
        } else {
            // next item won't fit here; mild penalty if we leave a medium hole
            score += 4.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: opening a bin is expensive when many bins
    // are already open or when mean residual is high (fragmented state).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut open_penalty = 18.0 + 2.5 * open_bins_count as f64;
        open_penalty += 10.0 * (mean_residual / cap);
        // Early in the stream, opening bins is cheaper (build diversity);
        // late in the stream, consolidate into existing bins.
        open_penalty *= 1.0 + 0.8 * progress;
        // If the item is huge, a fresh bin is naturally attractive.
        if item_size as f64 / cap > 0.8 {
            open_penalty -= 12.0;
        }
        score += open_penalty;
    } else {
        // Favor bins whose residual is close to the item (best-fit shaping),
        // but slightly prefer bins with more room when many bins are open.
        let snug = (bin_residual as f64 - item_size as f64) / cap;
        score += 8.0 * snug;
        if open_bins_count > 6 {
            score -= 2.0 * (mean_residual - bin_residual as f64).abs() / cap;
        }
    }

    // Mild time-horizon term: as the stream progresses, discourage leaving
    // large residuals (less future to recover from fragmentation).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 3.0 * progress * (post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with non-linear polynomial shaping.
    let mut score = pr * (1.0 + norm_pr * norm_pr);

    // Smooth stream-progress coupling: early on, tolerate slack; later, punish it.
    let progress_coupling = 1.0 + 2.0 * progress * progress;
    score += norm_pr * pr * progress_coupling * 0.5;

    // Reward tight fits relative to mean residual state.
    let mean_gap = (mean_residual - pr) / cap;
    score -= mean_gap * mean_gap * cap * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0 + 20.0 * progress;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        let snug = 1.0 - ((post_residual - next_item_size) as f64) / cap;
        score -= 10.0 + 15.0 * snug * snug;
    } else if next_item_size > 0 {
        // Penalize leaving residual that cannot host the next item.
        score += 5.0 * (next_item_size as f64 / cap) * (1.0 + progress);
    }

    // New-bin candidate: mildly discourage opening bins unless residual is hopeless.
    if bin_residual == bin_capacity {
        score += 25.0 + 30.0 * progress + 2.0 * open_bins_count as f64;
    }

    // Many open bins: prefer consolidating into existing ones.
    score += 0.5 * open_bins_count as f64 * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: exact fill is perfect; tiny dead space (<10) is poison.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score += 45.0; // unusable sliver
    } else {
        // Integer-division harmonic classes: post_residual / 10 buckets
        let class = post_residual / 10;
        score -= class as f64 * 2.5;
        // Mid-band residuals (20..50) are reusable by typical items
        if post_residual >= 20 && post_residual <= 50 {
            score -= 12.0;
        }
    }

    // Lookahead: does the next item fit exactly into post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0; // perfect chaining
        } else if next_item_size <= post_residual {
            let chain_waste = post_residual - next_item_size;
            score -= 20.0 * (1.0 - chain_waste as f64 / cap);
            if chain_waste < 10 {
                score += 25.0; // would create sliver next step
            }
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize opening a fresh bin when good open bins exist.
    if bin_residual == bin_capacity {
        score += 25.0 + open_bins_count as f64 * 1.5;
        if next_item_size > 0 && next_item_size <= bin_residual {
            score += 5.0;
        }
    }

    // Tight fits are valuable: reward low post_residual relative to capacity.
    score -= 15.0 * (1.0 - post_residual as f64 / cap);

    // Progress-aware tie-break: later in stream, prefer tighter packing.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * (1.0 - post_residual as f64 / cap);

    // Mean residual coupling: if this bin is far from mean residual, mild penalty.
    score += 0.05 * (post_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold the minimum item
    // (size 1..10 range is unknown; treat < 10 as likely dead) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 15.0;
    }

    // Reward near-perfect fits (waste minimization core term).
    if post_residual == 0 {
        score -= 100.0;
    }

    // Prefer bins whose current residual was already tight (good historical fit).
    let tightness = (bin_capacity as f64 - bin_residual as f64) / bin_capacity as f64;
    score -= 10.0 * tightness;

    // Open-bin pressure: when many bins are open, discourage spreading into new bins.
    score += 0.8 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: make an empty bin attractive only when the item
    // would leave a large, usable residual AND no open bin fits well.
    if bin_residual == bin_capacity {
        // Baseline neutral score for a fresh bin.
        score = post_residual as f64 + 5.0 + 0.8 * open_bins_count as f64;
        // A fresh bin is good if it keeps large usable residual and item is small.
        if post_residual >= 40 {
            score -= 10.0;
        }
        // But if other bins fit and this item would waste a fresh bin's space, penalize.
        if fitting_bins_count >= 1 && post_residual < 40 {
            score += 30.0;
        }
        // Late in the stream, avoid opening new bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Lookahead coupling: if the next item fits exactly into the post_residual,
    // reward this placement strongly (perfect chain).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual && post_residual - next_item_size < 10 {
            score += 20.0; // next item would create dead space here
        } else if next_item_size > post_residual {
            score += 3.0; // next item won't fit here; slight penalty for stranding space
        }
        // If next item fits the mean residual, avoid hogging this bin.
        if (next_item_size as f64) <= mean_residual && post_residual > 30 {
            score += 5.0;
        }
    }

    // Mild preference to balance residuals across bins (avoid one bin hogging space).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

