    // 2-step lookahead: if next item exactly fills post_residual, strongly reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // next item fits: penalize wasting the slot it would occupy
            score -= 20.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item does NOT fit here: penalize leaving awkward large-ish residual
            let gap = (next_item_size - post_residual) as f64;
            score += 0.3 * gap;
        }
    }

    // Penalize residuals that are dead space (too small for typical items 1..100)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable slivers
    }

    // Compare against mean residual across open bins
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a new bin is expensive unless
    // the current bin fit is bad. Penalize the fresh empty bin moderately.
    if bin_residual == bin_capacity {
        score += 55.0;
        // But if the fresh bin gives a great 2-step chain start, soften the penalty
        if next_item_size > 0 && (bin_capacity - item_size) >= next_item_size {
            score -= 10.0;
        }
    }

    // Mild late-stream consolidation pressure
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual relative to capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= 30.0 * (1.0 - tightness * tightness);

    // Penalize leaving residual that no plausible item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // dead space too small for any item
    }

    // Lookahead: bonus if the next item fits exactly in post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0; // perfect chain
        } else if post_residual >= next_item_size {
            score -= 10.0; // next item still fits here
        } else {
            score += 8.0; // next item won't fit, chain broken
        }
        // If next item is large and barely fits now, prefer this bin to keep big-item pairing.
        if next_item_size >= item_size && post_residual >= next_item_size {
            score -= 5.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate logic: opening a new bin is expensive when many open bins
    // already fit the item; allow it only when fits are scarce or residual is wasted.
    if bin_residual == bin_capacity {
        let fit_pressure = if fitting_bins_count == 0 { 1.0 } else { 1.0 / (fitting_bins_count as f64) };
        let waste = post_residual as f64; // = capacity - item_size for new bin
        score += 15.0 + 12.0 * fit_pressure + 0.15 * (open_bins_count as f64);
        // If item is large, a fresh bin wastes little; discount penalty.
        score -= 0.25 * (item_size as f64);
        // Late in stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
        // If this bin would otherwise be a wasteful fit, opening new bin looks better.
        if fitting_bins_count > 0 && (bin_residual - item_size) > 40 {
            score -= 18.0;
        }
    }

    // Prefer bins whose residual is close to mean (keep residuals homogeneous).
    score += 0.1 * ((bin_residual as f64 - mean_residual).abs());

    // Mild preference for filling fuller bins (larger item_size relative to residual).
    score -= 0.2 * (item_size as f64 / bin_residual.max(1) as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;
    let norm_pr = pr / cap;

    // Base: penalize post-residual with smooth non-linear growth
    let mut score = norm_pr.powf(1.8);

    // Quadratic coupling: post-residual squared scaled by stream progress
    score += 0.6 * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits (small post_residual) more strongly late in the stream
    let tightness = 1.0 - norm_pr;
    score -= 0.5 * tightness.powf(2.0) * (0.3 + 0.7 * progress);

    // Penalize dead space that can't fit the next item (smooth interaction)
    if next_item_size > 0 {
        let nxt = next_item_size as f64 / cap;
        let unusable = ((nxt - norm_pr) / cap).max(0.0);
        score += 0.8 * unusable.powf(1.5) * (0.4 + 0.6 * progress);
    }

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 1.2 * (1.0 - fit_ratio * 0.5);
    }

    // Mild penalty for many open bins with high mean residual (fragmentation)
    score += 0.05 * (open_bins_count as f64).sqrt() * (mean_residual / cap) * progress;

    // New-bin candidate: make empty bin attractive only when current fit is poor
    if bin_residual == bin_capacity {
        score = 0.9 + norm_pr * 0.0 - fit_ratio * 0.4 + progress * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect / near-perfect fit rewards (harmonic classes of residual)
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    } else if post_residual <= 10 {
        score -= 150.0;
    }

    // Harmonic class of post_residual: penalize residuals in "wasteful" bands
    let class = post_residual / 10;
    score += match class {
        0 => -50.0,
        1 => 0.0,
        2 => 10.0,
        3 => 25.0,
        4 => 40.0,
        5 => 55.0,
        6 => 70.0,
        7 => 85.0,
        8 => 100.0,
        9 => 115.0,
        _ => 130.0,
    } as f64;

    // Lookahead coupling: reward residuals that can host the next item exactly
    if next_item_size > 0 && post_residual >= next_item_size {
        let nxt_post = post_residual - next_item_size;
        if nxt_post == 0 {
            score -= 250.0;
        } else if nxt_post <= 10 {
            score -= 100.0;
        } else {
            score += nxt_post as f64 * 0.3;
        }
    } else if next_item_size > 0 {
        // next item cannot fit here: mild penalty, dead space likely
        score += 20.0;
    }

    // Last chance bin: strongly favor using it instead of opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: only attractive when current fit is terrible
    if bin_residual == bin_capacity {
        let tight = post_residual as f64 / bin_capacity as f64;
        if post_residual <= 10 {
            score += 500.0; // never open new bin for near-perfect fits
        } else if tight > 0.4 {
            score -= 50.0 + tight * 50.0;
        } else {
            score += 80.0;
        }
    }

    // Progress-aware: later in stream, prefer tighter packing
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (post_residual as f64) * progress * 0.2;

    // Prefer bins below mean residual (keep balance, save big residuals)
    if (bin_residual as f64) > mean_residual + 15.0 {
        score += 25.0;
    } else if (bin_residual as f64) < mean_residual - 15.0 {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

