    // Harmonic classes: classify post_residual into usable/dead space classes.
    // Residuals that can still host common item sizes (harmonic slots) are valuable.
    let harmonic_slots: [u32; 8] = [10, 20, 25, 30, 40, 50, 60, 75];
    let mut usable = false;
    for &h in harmonic_slots.iter() {
        if post_residual >= h {
            usable = true;
            break;
        }
    }
    if !usable && post_residual > 0 {
        // dead space: residual too small for any harmonic class
        score += 25.0;
        // modulo penalty: dead space not near a harmonic boundary
        score += (post_residual % 10) as f64 * 0.5;
    }

    // Fractional capacity coupling: how much of the bin this item consumes.
    let frac = item_size as f64 / bin_capacity as f64;
    score -= frac * 15.0; // prefer filling bins substantially

    // Lookahead: if next item fits the resulting post_residual, big reward (chain fit).
    if next_item_size > 0 && post_residual >= next_item_size {
