        score -= (bin_capacity - bin_residual) as f64 * 0.1;
    }

    // New-bin candidate logic: opening a new bin should only win when placement
    // elsewhere is bad (no fitting bins or huge waste).
    if bin_residual == bin_capacity && bin_capacity > 0 {
        let base = bin_capacity as f64;
        // default cost of a fresh bin: high, beaten by any decent placement
        score = base + 40.0;
        // if item is large relative to capacity, a fresh bin is more acceptable
        score -= frac * 60.0;
        // if no other bin fits, opening new is necessary-ish: reduce penalty
        if fitting_bins_count == 0 {
            score -= 100.0;
        } else if fitting_bins_count == 1 {
            score -= 10.0;
        }
        // early in stream, more open bins is fine; late stream, consolidate
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 20.0;
        // if mean residual across open bins is large, avoid opening new bins
        score += (mean_residual / base).max(0.0) * 30.0;
    }

    // Mean residual alignment: prefer bins whose residual is close to mean (balanced packing)
    let diff = (bin_residual as f64 - mean_residual).abs();
    score += diff * 0.05;

    // Modulo harmonic bonus on item size: items in classic classes pack predictably
    if item_size % 10 == 0 {
        score -= 3.0;
