        if gap < 10.0 {
            score += 60.0 * (10.0 - gap); // tiny unusable sliver => strong penalty
        } else if gap < 25.0 {
            score += 15.0 * (25.0 - gap) / 15.0; // awkward small gap
        }
    }

    // Reward tight fits (small post_residual relative to item)
    let tightness = 1.0 - (post_residual as f64) / (bin_residual.max(1) as f64);
    score -= 30.0 * tightness;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Lookahead: if next item fits in post_residual, reward; else penalize
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0 + next_item_size as f64 * 0.2;
        } else {
            score += 5.0;
        }
    }

    // Open bin pressure: many open bins => discourage spreading, prefer consolidation
    score += open_bins_count as f64 * 0.5;

    // New-bin candidate handling: empty bin gets baseline cost; only chosen when
    // all open bins score worse (poor fits).
    if bin_residual == bin_capacity {
        score = 100.0 - 10.0 * tightness + open_bins_count as f64 * 0.3;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 5.0;
        }
        if fitting_bins_count == 1 {
            score += 40.0; // never open new bin when a last-chance bin exists
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches the next item well.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if next <= post_residual as f64 {
            // Next item fits perfectly after this placement -> strong reward.
            let perfect = (post_residual as f64 - next).abs();
            score -= 2.5 * (1.0 - perfect / bin_capacity as f64) * (bin_capacity as f64 / 100.0);
            // Bonus scaled by how large the next item is relative to residual.
            score -= 1.2 * (next / post_residual as f64);
        } else {
            // Next item will NOT fit here -> penalize leaving a gap smaller than next item.
            let waste = post_residual as f64;
            if waste > 0.0 && waste < next {
                score += 1.5 * (1.0 - waste / next.max(1.0));
            }
        }
    } else {
        // Last item: prefer tightest fit only.
        score -= 0.5;
    }

    // Relative to mean residual: prefer bins with residual below mean (denser bins),
    // penalize placing into unusually empty bins when alternatives exist.
    let rel = post_residual as f64 - mean_residual;
    score += 0.35 * rel;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 6.0;
    }

    // New-bin candidate handling: make the empty-bin call moderately attractive only
    // when no open bin offers a good fit (post_residual large relative to item),
    // otherwise discourage opening new bins.
    if bin_residual == bin_capacity {
        let fit_quality = item_size as f64 / bin_capacity as f64;
        // Big items justify a fresh bin; small items should go into open bins.
        score = 100.0 - 40.0 * fit_quality;
        if fitting_bins_count <= 1 {
            score -= 8.0;
        }
        if next_item_size > 0 && next_item_size <= item_size {
            score -= 2.0; // a fresh bin can likely also host the next item
        }
    }

    // Slight time regularization: later in the stream, be more conservative
    // about waste (dead space hurts more when few items remain to fill it).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.25 * progress * post_residual as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;

    // Tight fits are excellent: reward small post_residual super-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 0.6 * tightness * tightness * (item_size as f64);

    // Penalize dead space that the next item cannot use (lookahead k=2).
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size > post_residual {
            // next item can't use leftover: penalize proportionally to waste
            score += 0.5 * (post_residual as f64 / bin_capacity as f64) * (next_item_size as f64);
        } else {
            // next item fits into leftover: strong reward
            score -= 0.4 * (next_item_size as f64);
        }
    }

    // Last-chance bin: strongly reward using it before opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening new bins, more when many bins are open
    // and mean residual across open bins is still large (fragmented capacity).
    if is_new_bin {
        score += 30.0 + 2.0 * open_bins_count as f64;
        score += 0.5 * mean_residual;
        // Late in the stream, closing out existing bins matters more: harsher penalty.
        score += 20.0 * progress;
        // But if item is huge relative to typical residual, opening may be inevitable:
        // soften penalty when it barely fits anywhere.
        if fitting_bins_count <= 1 {
            score -= 15.0;
        }
    }

    // Prefer bins whose residual is far from mean (use the odd-sized bins first),
    // keeping a pool of similarly-sized residuals for better future packing.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.2 * dev;

    // Mild time pressure: as stream progresses, favor compacting existing bins.
    score -= 5.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap;

    let mut score = pr as f64;

    // Smooth non-linear coupling: post-residual polynomial interacting with stream progress
    let poly = x * x * (3.0 - 2.0 * x); // smoothstep-like shaping of residual
    score += poly * (1.0 + progress) * 20.0;

    // Penalize large residuals more as stream progresses (favor tight fits late)
    score += progress * x * x * 15.0;

    // Reward near-exact fits: low post residual subtracted
    let fit_bonus = (1.0 - x).powi(2);
    score -= fit_bonus * (10.0 + 25.0 * progress);

    // Lookahead coupling: if next item can fit into post residual, reward this bin
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = (pr - nxt) / cap;
            score -= (1.0 - slack) * 12.0;
        } else {
            score += 8.0 * progress;
        }
    }

    // Last-chance bin: strong reward to use it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: penalize opening fresh bins unless residual spread is high
    if bin_residual == bin_capacity {
        let spread = (mean_residual - pr).abs();
        score += 25.0 + 20.0 * (1.0 - progress) - spread * 0.5;
    }

    // Mild penalty for many open bins to encourage consolidation
    score += open_bins_count as f64 * 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fits (residual in small classes) are gold.
    let cap_f = bin_capacity as f64;
    let post_f = post_residual as f64;
    let frac = post_f / cap_f;

    // Reward tight packing: the smaller the post_residual fraction, the better.
    score -= 60.0 * (1.0 - frac).powi(3);

    // Integer-division thresholds on post_residual: residual that cannot fit
    // even the smallest plausible item (<= ~10) is dead space.
    if post_residual < 10 {
        score -= 25.0; // near-perfect bin closure
    } else if post_residual < 20 {
        score -= 10.0;
    } else if post_residual < 40 {
        score += 8.0;
    } else {
        score += 18.0; // large residual = wasteful placement
    }

    // Lookahead: does the next item fit in the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Bonus scaled by how snugly the next item fits.
            let snug = next_item_size as f64 / post_f;
            score -= 20.0 * snug;
        } else {
            // Post residual too small for the next item: penalize if it's stranded space.
            if post_residual < 10 {
                score += 2.0; // acceptable dead space
            } else {
                score += 12.0; // wasted usable space
            }
        }
    } else {
        // Last item: closing bins tightly is all that matters.
        score -= 15.0 * (1.0 - frac);
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 {
            0.0
        } else {
            let best_possible = mean_residual.max(0.0);
            (best_possible / cap_f).clamp(0.0, 1.0)
        };
        // Base cost of opening a new bin, discounted when existing bins are fragmented.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut new_bin_score = 55.0 - 25.0 * desperation - 10.0 * (1.0 - progress);
        // Harmonic class check on current item: big items start fresh bins more readily.
        let class = item_size / (bin_capacity / 4);
        if class >= 2 {
            new_bin_score -= 8.0;
        }
        score = new_bin_score + post_residual as f64 * 0.1;
    }

    // Modulo-arithmetic harmonic bonus: residuals divisible into common item sizes
    // (e.g. multiples of 10 or 25) pair well with future items.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 5.0;
    }
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 5.0;
    }

    // Slight penalty when many bins are open and this placement is loose.
    if open_bins_count > 4 && frac > 0.5 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable gaps (post_residual smaller than
    // the smallest plausible item) are heavily penalized.
    let min_item = 1.0f64;
    if post_residual > 0 && (post_residual as f64) < min_item * 10.0 {
        score += 500.0;
    }
    // Penalize small gaps that likely can't fit the next item either.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 40.0 + 0.5 * (next_item_size - post_residual) as f64;
    }

    // Reward exact / tight fits strongly.
    if post_residual == 0 {
        score -= 200.0;
    } else {
        let tightness = post_residual as f64 / bin_capacity as f64;
        score -= 60.0 * (1.0 - 2.0 * tightness).max(-1.0);
    }

    // Last-chance bonus: if this is the only bin that fits, prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: opening a bin is penalized when any open
    // bin offers a decent fit, but encouraged when open bins are nearly full
    // or there are no open bins at all.
    if bin_residual == bin_capacity {
        score += 25.0;
        if open_bins_count == 0 {
            score -= 1000.0;
        } else {
            // pressure grows with number of open bins and their slack
            score += 3.0 * open_bins_count as f64;
            score += 0.5 * mean_residual;
            // if item is large, better to place it in an open bin's slack
            if item_size >= 50 {
                score += 30.0;
            }
        }
    }

    // Mild pressure to consolidate into fewer bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.05 * open_bins_count as f64 * (0.5 + progress);

    // Slight preference for bins with residual above the mean (keep balanced slack).
    score += 0.1 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect 2-step lookahead match: residual becomes exactly next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= (bin_capacity as f64 - diff) * 0.8;
        // Extra bonus for exact match
        if diff == 0.0 {
            score -= 40.0;
        }
        // Penalize leaving residual too small for next item (dead space)
        if (post_residual as u32) < next_item_size && post_residual > 0 {
            score += 15.0 + 0.3 * (next_item_size as f64 - post_residual as f64);
        }
    } else {
        // Last item: prefer minimal leftover
        score += 10.0;
    }

    // Relative to mean residual: prefer bins with residual close to mean (balanced),
    // but strongly prefer tight fits when this bin is far above mean.
    let pr = post_residual as f64;
    let dev = pr - mean_residual;
    score += 0.25 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate: penalize unless current bins are nearly full / bad fits.
    if bin_residual == bin_capacity {
        let openness = open_bins_count as f64;
        score += 30.0 + 5.0 * openness;
        // Allow opening new bin if mean residual is very low (bins mostly full)
        if mean_residual < 15.0 {
            score -= 60.0;
        }
    }

    // Tightness reward: smaller post_residual relative to capacity is good.
    score -= 0.2 * (bin_capacity as f64 - pr);

    // Mild progression scaling: tighten packing as stream advances.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * progress * (pr / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear in wasted space).
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    score += 8.0 * waste_ratio * waste_ratio;

    // Perfect fit: strong bonus.
    if post_residual == 0 {
        score -= 25.0;
    }
    // Near-perfect fit.
    if post_residual <= 2 {
        score -= 12.0;
    }

    // Lookahead: penalize leaving residual that matches next item poorly,
    // reward residual that the next item can fill.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 15.0;
        } else if post_residual > next_item_size && post_residual - next_item_size <= 5 {
            score -= 8.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            // Dead space the next item can't use; mild penalty scaled by gap.
            score += 0.15 * (post_residual as f64).sqrt();
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless the item
    // is large or existing residuals are poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let item_ratio = item_size as f64 / bin_capacity as f64;
        // Opening a new bin is attractive for large items or late in stream.
        score += 30.0 - 25.0 * item_ratio - 10.0 * progress;
        // If no good open bins exist (mean residual small relative to item),
        // reduce the penalty to encourage a fresh bin.
        if mean_residual < item_size as f64 {
            score -= 18.0;
        }
        // Many open bins with slack: discourage new bin.
        score += 0.5 * (open_bins_count as f64).min(10.0);
    } else {
        // Prefer bins whose residual is close to the item (best-fit coupling).
        let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
        score += 5.0 * tightness;
        // Slight preference for bins below mean residual (consolidating slack).
        if (bin_residual as f64) < mean_residual {
            score -= 2.0;
        }
    }

    // Time horizon: later in stream, be greedier about tight fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 6.0 * progress * (1.0 - waste_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: wasted space after placement, normalized.
    let mut score = post / cap;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // later in the stream, large leftovers are increasingly penalized (dead space matters more).
    let post_norm = post / cap;
    let coupling = post_norm * post_norm * (1.0 + 2.0 * progress * progress);
    score += 1.5 * coupling;

    // Reward tight fits (small post_residual) with a smooth saturating term.
    score -= 0.8 * (1.0 - post_norm).powi(3) * (1.0 + progress);

    // Lookahead: if the next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 && (next_item_size as f64) <= post {
        let fit_gap = (post - next_item_size as f64) / cap;
        score -= 0.6 * (1.0 - fit_gap) * (1.0 + progress);
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 2.0;
    }

    // Penalize spreading across too many open bins relative to mean residual.
    score += 0.1 * (open_bins_count as f64 / (1.0 + mean_residual / cap));

    // New-bin candidate: mild penalty so existing bins are preferred unless they fit poorly.
    if bin_residual == bin_capacity {
        score += 0.5 + 0.3 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: reward residuals that fall into
    // "useful" classes (multiples of 10 / small gaps), penalize dead zones.
    let pr = post_residual;
    let class_bonus = match pr {
        0 => -60.0,                       // perfect fit
        1..=5 => -35.0,                   // near-perfect
        6..=10 => -20.0,                  // small usable gap
        11..=20 => -5.0,                  // medium gap
        21..=40 => 10.0,                  // awkward
        _ => 20.0,                        // large residual: bin stays flexible
    };
    score += class_bonus;

    // Integer-division threshold coupling: residual mod 10 as a fine penalty.
    let rem10 = (pr % 10) as f64;
    score += 0.4 * rem10;

    // Lookahead: reward if next item fits exactly into the post-residual.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size < pr {
            let slack = (pr - next_item_size) as f64;
            score -= 20.0 * (-slack / 15.0).exp(); // decaying reward for closeness
        } else {
            // next item won't fit here: mild penalty scaled by overflow amount
            score += 0.15 * ((next_item_size - pr) as f64);
        }
    }

    // Fractional capacity coupling: prefer filling bins proportionally deep.
    let fill_frac = (bin_capacity - post_residual) as f64 / cap;
    score -= 30.0 * fill_frac * fill_frac;

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless it's early in the
    // stream or the current item is huge relative to capacity.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let big_item = item_size as f64 / cap;
        score += 55.0 * (1.0 - progress) - 25.0 * big_item;
        // opening new bins when many are already open fragments capacity
        score += 1.5 * open_bins_count as f64;
    } else {
        // Mild preference for tighter bins when many fit
        score += 0.5 * (fitting_bins_count as f64 - 1.0);
        // Nudge toward bins whose residual deviates from the mean less
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    // Late-stream pressure: consolidate into fewer bins as stream ends.
    let t = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * t * (post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold the
    // smallest plausible item (<= 10) are pure waste -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Small residual gaps (10..25) are hard to fill with typical items.
    if post_residual >= 10 && post_residual < 25 {
        score += 8.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Tight-fit bonus scaled by how snugly the item lands.
    score -= (item_size as f64 / bin_capacity as f64) * 6.0;

    // Open-bin pressure: with many bins open, prefer consolidating into
    // existing bins rather than spreading out; discourage opening new bins.
    score += open_bins_count as f64 * 1.5;

    // New-bin candidate penalty: opening a fresh bin wastes the mean residual
    // already sitting in open bins.
    if bin_residual == bin_capacity {
        score += mean_residual * 0.8 + 5.0;
        // But if this item fits nowhere else, opening a bin is fine.
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // reward this placement strongly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            score -= 5.0;
        } else if post_residual > 0 {
            score += 3.0; // next item won't fit here; mild penalty
        }
    }

    // Late in the stream, be slightly more aggressive about tight packing.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact or near-exact fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize small dead space non-linearly (small leftovers are wasteful).
        if post_residual <= 10 {
            score -= 60.0;
        } else if post_residual <= 20 {
            score -= 25.0;
        }
        // Dead space relative to capacity.
        score += (post_residual as f64 / bin_capacity as f64) * 30.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post_residual as f64 >= nx {
            let gap = post_residual as f64 - nx;
            if gap == 0.0 {
                score -= 400.0;
            } else if gap <= 10.0 {
                score -= 150.0;
            } else if gap <= 25.0 {
                score -= 60.0;
            } else {
                score -= 20.0;
            }
            // Extra reward if next item leaves a further tiny residual (chain fit).
            let chain = post_residual as f64 - nx;
            if chain >= 0.0 && chain < 15.0 {
                score -= 40.0;
            }
        } else {
            // Next item cannot fit here: mild penalty proportional to overflow.
            score += (nx - post_residual as f64) * 0.5;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // Compare post_residual against mean residual across open bins:
    // leaving a residual near the mean keeps flexibility.
    let pr = post_residual as f64;
    let dev = (pr - mean_residual).abs();
    score += dev * 0.3;

    // Prefer filling older/more crowded bins to keep open-bin count low.
    score += open_bins_count as f64 * 0.05;
    if bin_residual != bin_capacity {
        score -= 10.0; // favor reusing an existing bin over a fresh one
    }

    // Progress-based tightening: later in stream, be greedier about tight fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 20.0 * (1.0 - pr / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post-residual) with a non-linear decay.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 20.0 * (1.0 - fit_ratio).powi(3);

    // Penalize dead space that is too small to be useful for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 * (next_item_size as f64 / bin_capacity as f64);
        } else {
            // Post-residual useless for next item: mild penalty scaled by wasted amount.
            score += 4.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    }

    // Perfect-fill bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin is generally costly, but attractive
    // when this item fits poorly everywhere (large post_residual would be created).
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 18.0;
        // Cheaper to open a new bin early in the stream when many items remain.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
        // If many bins fit the item, opening a new bin is wasteful.
        score += 3.0 * (fitting_bins_count as f64).min(6.0);
        // If the item would leave a poor residual elsewhere, new bin gains appeal.
        if post_residual == 0 {
            score -= 35.0; // item fills a fresh bin exactly (e.g. size == capacity)
        }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 6.0; // room to also take the next item
        }
    }

    // Global-state coupling: prefer bins with residual near the mean (balanced packing).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Slight preference for older bins (first-fit flavor) to close bins sooner.
    score -= 0.01 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let mut score = pr;

    // Quadratic waste penalty: dead space grows quadratically in cost.
    let norm_pr = pr / cap;
    score += 6.0 * norm_pr * norm_pr * cap;

    // Reward very tight fits (small post_residual) super-linearly.
    if post_residual <= item_size {
        score -= 8.0 * (1.0 - norm_pr);
    }

    // Smooth interaction: tightness valued more as stream progresses.
    score -= 4.0 * progress * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Lookahead: bonus if the next item fits into the resulting residual.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            let fit_ratio = nx / pr.max(1.0);
            score -= 5.0 * fit_ratio * (1.0 - fit_ratio) * 4.0 * fit_ratio.max(0.25);
        } else {
            // residual too small for next item: penalize proportionally to waste
            score += 3.0 * (1.0 - pr / cap) * (nx / cap);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize opening a new bin mildly, scaled by how many
    // open bins exist and mean residual (opening fresh bin resets fragmentation).
    if bin_residual == bin_capacity {
        let open_f = open_bins_count as f64;
        score += 10.0 + 2.0 * open_f.sqrt();
        // But if mean residual is very fragmented, opening fresh is attractive.
        score -= 6.0 * (mean_residual / cap).clamp(0.0, 1.0);
        // Late in the stream, prefer filling existing bins.
        score += 8.0 * progress;
    }

    // Mild preference for bins with less residual among equals (fill fullest first).
    score += 0.02 * (bin_residual as f64 - pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: dead space in coarse capacity fractions.
    let cap_f = bin_capacity as f64;
    let post_f = post_residual as f64;
    let frac = post_f / cap_f;

    // Penalize residuals that fall into "unusable" harmonic bands.
    // Items are >= 1, so residual < smallest plausible next item is dead space.
    if post_residual > 0 {
        // Modulo-style classification of post_residual into harmonic classes.
        let class = post_residual % 25; // quarter-capacity harmonics
        score += 0.35 * (class as f64) / 25.0;

        // Very small residuals are nearly dead: strong penalty.
        if post_residual < 10 {
            score += 25.0;
        } else if post_residual < 20 {
            score += 8.0;
        } else if post_residual < 30 {
            score += 3.0;
        }
    } else {
        // Perfect fill: huge reward.
        score -= 60.0;
    }

    // Tight fit reward: item occupies most of the bin.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * tightness * tightness;

    // Lookahead coupling: reward if the next item fits the post residual exactly or well.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect chain
        } else if next_item_size <= post_residual {
            let chain_fit = next_item_size as f64 / post_f;
            score -= 15.0 * chain_fit;
        } else {
            // Next item won't fit here; mildly penalize leaving a gap it almost fits.
            if post_residual >= next_item_size - 5 {
                score += 2.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    // or many bins are already open with slack.
    let is_new_bin = bin_residual == bin_capacity && bin_capacity == 100;
    if is_new_bin {
        let pressure = open_bins_count as f64;
        let mean_slack = mean_residual / cap_f;
        // New bin is bad if some bin fits and residuals are healthy.
        if fitting_bins_count > 0 {
            score += 30.0 + 2.0 * pressure * (1.0 - mean_slack);
        } else {
            score -= 5.0; // no alternative: new bin is fine
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Mild reward for bins already below mean residual (consolidating slack).
    if post_f < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any
    // realistic future item (<= 10) are pure waste -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // "Awkward gap" zone: 10..=25 tends to strand space; scale penalty.
    if post_residual >= 10 && post_residual < 25 {
        score += 12.0 * (1.0 - (post_residual as f64) / 25.0);
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post
    // residual, strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 - slack * 0.5;
    }
    // Penalize if next item would strand this residual.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Open-bin pressure: discourage spreading across many bins when a
    // tight fit exists elsewhere.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly prefer using the only bin that fits,
    // avoiding a new bin opening.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New empty bin candidate: neutral-to-slightly-high baseline so it is
    // chosen only when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 20.0 + mean_residual * 0.1;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open a new bin
        }
    }

    // Mean residual coupling: when open bins are mostly full, prefer
    // consolidating into this bin.
    score -= (mean_residual - post_residual as f64).max(0.0) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let capacity_f = bin_capacity as f64;
    let post_f = post_residual as f64;
    let mut score = post_f;

    // Reward exact/near-perfect fits strongly.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 2 {
        score -= 25.0;
    }

    // Aggressive 2-step lookahead: reward if next item fits into the post residual.
    if next_item_size > 0 {
        let next_f = next_item_size as f64;
        if next_item_size == post_residual {
            score -= 40.0; // perfect chain: item + next item fill bin exactly
        } else if next_item_size < post_residual {
            // reward proportional to how well the next item uses remaining space
            let chain_waste = post_f - next_f;
            score -= 20.0 * (1.0 - chain_waste / capacity_f);
            // extra bonus if the chain leaves a still-usable residual
            let pr = post_residual - next_item_size;
            if pr >= 10 {
                score -= 5.0;
            }
        } else {
            // next item cannot follow here; penalize dead space left behind
            score += 8.0 * (post_f / capacity_f);
        }
    } else {
        // last item in stream: only current fit matters
        score -= 10.0;
    }

    // Compare post_residual relative to mean residual of open bins.
    // Leaving more space than the average is wasteful when mean residual is tight.
    score += 0.15 * (post_f - mean_residual);

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize opening a new bin when decent open bins exist.
    if bin_residual == bin_capacity {
        score += 20.0 + 2.0 * open_bins_count as f64;
        // opening a new bin is acceptable only if item is large and would leave
        // a tiny residual in existing bins
        if item_size as f64 > 0.8 * capacity_f {
            score -= 25.0;
        }
    }

    // Mild pressure to consolidate as the stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * progress * (post_f / capacity_f);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are strongly preferred: reward small post-residual quadratically.
    score -= (bin_capacity as f64 - post_residual as f64) * (bin_capacity as f64 - post_residual as f64) * 0.02;

    // Exact or near-exact fill bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 10.0;
    }

    // Dead-space penalty: post_residual that is too small to fit anything useful.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: if next item fits the post-residual, reward; if not, penalize leftover.
    if next_item_size > 0 {
        if (next_item_size as f64) <= post_residual as f64 {
            score -= 20.0;
        } else {
            let waste = post_residual as f64;
            score += waste * 0.3;
        }
    }

    // Last-chance bin: strongly favor using the single fitting bin to avoid a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Many open bins: discourage spreading into bins with large residuals when
    // mean residual is high (keep some bins concentrated for large future items).
    if open_bins_count > 2 && mean_residual > 30.0 {
        if (bin_residual as f64) > mean_residual + 20.0 {
            score += 10.0; // penalize burning the largest-residual bins on small items
        }
        if (bin_residual as f64) < mean_residual - 10.0 {
            score -= 8.0; // favor consolidating into low-residual bins
        }
    }

    // New-bin candidate logic: empty bin only attractive when no tight fit exists
    // (post_residual large) or late in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 45.0 - 25.0 * progress;
        if item_size as f64 > bin_residual as f64 * 0.6 {
            score -= 20.0; // large item: fresh bin is fine
        }
    }

    // Late-stream squeeze: prefer filling bins almost completely near the end.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress > 0.8 {
        score += post_residual as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post;

    // Non-linear coupling: waste matters more as stream progresses
    let norm_post = post / cap;
    let waste_penalty = norm_post * norm_post * (1.0 + progress * 2.0) * cap * 0.5;
    score += waste_penalty;

    // Reward tight fits (small post_residual) with smooth saturating term
    let tight_reward = (cap / (1.0 + post * 0.15)) * 0.6;
    score -= tight_reward;

    // Lookahead coupling: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= post {
        let fit_bonus = (next_item_size as f64 / cap) * 8.0 * (1.0 + progress);
        score -= fit_bonus;
    } else if next_item_size > 0 {
        // Next item cannot use leftover: mild penalty scaled by leftover size
        score += (post / cap) * 4.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Penalize bins far below mean residual (fragmentation signal), smooth term
    let dev = (post - mean_residual) / cap;
    score += dev * dev * cap * 0.3;

    // New-bin candidate: prefer it only when all open bins fit poorly
    if bin_residual == bin_capacity {
        let open_pressure = (open_bins_count as f64).ln() + 1.0;
        score = post + 6.0 + open_pressure * 2.0 - (fitting_bins_count as f64) * 0.0;
        if fitting_bins_count == 1 {
            score -= 4.0; // still somewhat tempted to open new bin
        }
        if progress > 0.8 {
            score += 5.0 * (1.0 - progress); // near end, reuse bins
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo-10 residue classes.
    // Residuals that are multiples of 10 (or near) are "usable" classes for
    // items drawn from 1..100; odd/prime residues waste space.
    let r = post_residual;
    let class10 = r % 10;
    if class10 == 0 {
        score -= 6.0; // perfect harmonic class: residual reusable by round sizes
    } else if class10 <= 2 || class10 >= 8 {
        score -= 2.0; // near-harmonic, small item can still fill
    } else {
        score += 4.0; // dead-zone residue (3..7): hard to fill later
    }

    // Integer-division thresholds: residual that can host a "large" item (>=50)
    let big_fit = (r >= 50) as i32;
    score -= 3.0 * big_fit as f64;

    // Lookahead coupling: if next item fits exactly in post_residual, strong reward
    if next_item_size > 0 {
        if next_item_size == r {
            score -= 25.0;
        } else if next_item_size <= r {
            let slack = r - next_item_size;
            score -= 8.0 - (slack as f64).min(8.0); // prefer tight lookahead fit
        } else {
            // next item cannot fit here: penalize small post residuals more
            score += (r as f64).powf(0.5) * 0.5;
        }
    }

    // Exact fill is ideal
    if r == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: penalize opening a bin unless current fit is bad
    if bin_residual == bin_capacity {
        score += 30.0;
        // but if the item would leave a harmonic residual anyway, opening is fine
        if item_size % 10 == 0 {
            score -= 25.0;
        }
        // late in stream, prefer closing out open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += (1.0 - progress) * 5.0;
    }

    // Prefer bins whose residual deviates strongly from the mean (consolidate waste)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score -= dev * 0.15;

    // Many open bins: encourage filling existing ones rather than spreading
    score -= (open_bins_count as f64).ln().max(0.0) * 1.5;

    // Slight preference for tighter fits overall
    score += (post_residual as f64) / bin_capacity as f64 * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

