    }

    // New-bin candidate: only attractive when current bins fit poorly.
    if bin_residual == bin_capacity {
        score += 25.0 + mean_residual * 0.3;
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    }

    // Favor bins whose residual is close to mean (balanced packing).
    score -= 5.0 - ((bin_residual as f64 - mean_residual).abs() * 0.1);

    // Late in the stream, tighten packing further.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (bin_residual as f64 - post_residual as f64) * progress * 0.5;

