    // Aggressive 2-step lookahead: perfect match of next item into post residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // chain fit: this bin becomes exactly full next step
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // prefer bins where the next item leaves a small remainder too
            score -= 20.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot follow here; penalize proportionally to wasted gap
            let gap = (next_item_size - post_residual) as f64;
            score += 0.5 * gap;
        }
    }

    // Penalize dead space that is too small for typical items (unusable sliver).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Relative to mean residual: favor bins tighter than average.
    score += 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when current fits are poor or none exist.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a bin
        } else {
            // cost of opening a new bin vs wasting space in an existing one
            let poor_fit = (post_residual as f64 - mean_residual).max(0.0);
            score += 40.0 - 0.5 * poor_fit;
            if next_item_size > 0 && post_residual >= next_item_size {
                score -= 10.0; // fresh bin chains well with next item
            }
        }
    }

    // Mild pressure to consolidate bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 2.0 * progress * open_bins_count as f64 / 100.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong preference for tight fits: reward small post_residual.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 14.0 * tightness;

    // Penalize dead space that no plausible future item can fill.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0; // tiny unusable sliver
    }

    // Lookahead: reward if next item fits exactly in the post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / (bin_capacity as f64));
        } else {
            // next item won't fit here; mildly penalize wasting large residuals
            score += 0.05 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0;
    }

    // Many open bins: encourage consolidation into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.15 * (open_bins_count as f64) * (1.0 - progress);

    // Compare residual to global mean residual: prefer bins whose residual
    // is close to item size (good use of typical leftover space).
    let diff = (bin_residual as f64 - item_size as f64).abs();
    score += 0.08 * diff;
    score -= 0.05 * (mean_residual - (bin_residual as f64)).abs();

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 1.0 } else {
            (post_residual as f64 / bin_capacity as f64).powi(3)
        };
        // Opening a bin costs ~one bin; make it competitive but not free.
        score = 55.0 - 20.0 * desperation - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * (1.0 - norm_pr) * progress;
    score += 20.0 * poly;

    // Reward tight fits, stronger as stream progresses
    score -= 12.0 * (1.0 - norm_pr) * (1.0 + progress);

    // Last-chance bonus: avoid opening new bins when few can fit
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - progress);
    }

    // Penalize bins far from mean residual (fragmentation)
    score += 0.5 * (pr - mean_residual).abs() / cap;

    // Lookahead: reward leaving space for the next item
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if pr >= ns {
            let gap = (pr - ns) / cap;
            score -= 8.0 * (1.0 - gap * gap);
        } else {
            score += 5.0 * (ns - pr) / cap;
        }
    }

    // Mild penalty for many open bins
    score += 0.05 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the residual gap: small gaps are "dead space" classes.
    let gap_class = post_residual / 10; // integer division threshold classes
    // Penalize mid-range gaps (hard to fill), reward near-full or perfectly reusable gaps.
    match gap_class {
        0 => score -= 25.0,               // residual <= 9: tight fit, excellent
        1 => score += 8.0,                // 10..19: awkward small gap
        2 => score += 15.0,               // 20..29: worst dead zone
        3 => score += 10.0,               // 30..39: bad
        4 => score += 2.0,                // 40..49: mediocre
        5 | 6 => score -= 5.0,            // 50..69: still broadly reusable
        _ => score -= 12.0,               // 70+: large residual, plenty of room left
    }

    // Modulo harmony: if next item divides evenly into post_residual, reward strongly.
    if next_item_size > 0 && post_residual > 0 {
        if post_residual % next_item_size == 0 {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            // reward when next item fits with a small leftover class
            let nxt_gap = post_residual - next_item_size;
            if nxt_gap <= 10 {
                score -= 10.0;
            } else if nxt_gap <= 30 {
                score += 6.0;
            }
        } else {
            // next item won't fit here; mild penalty unless gap is tiny anyway
            if post_residual < next_item_size && post_residual <= 5 {
                score -= 3.0;
            } else {
                score += 4.0;
            }
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin to avoid opening a new one.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate handling: penalize opening a fresh bin unless current fit is terrible.
    if bin_residual == bin_capacity {
        // Fresh bin: baseline penalty proportional to how many bins already fit the item.
        if fitting_bins_count > 0 {
            score += 40.0 + 10.0 * fitting_bins_count as f64;
        } else {
            score -= 5.0;
        }
        // In late stream, prefer consolidating: extra penalty for new bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
    }

    // Reward bins whose residual is close to the mean (balanced packing), slight effect.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Congestion coupling: with many open bins, favor filling existing ones harder.
    score -= (open_bins_count as f64).ln().max(0.0) * 2.0;

    // Exact-fill bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps after placement.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 30.0;
    }

    // Dead space that cannot fit the lookahead item is worse.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is tight.
    score += open_bins_count as f64 * 0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Prefer bins with residual close to the item (tight fit) over loose fits.
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score += tightness * 10.0;

    // New-bin candidate: mildly penalize opening a new bin unless nothing fits well.
    if bin_residual == bin_capacity {
        score += 15.0 + open_bins_count as f64 * 0.3;
        // But if the item is large relative to mean residual, opening is attractive.
        if mean_residual > 0.0 && (item_size as f64) > mean_residual * 1.5 {
            score -= 25.0;
        }
    }

    // Favor reusing bins whose residual is near the mean (balanced packing).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), but penalize post_residual
    // that is too small to ever be reused (dead space < min item size 1..100 range).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 1000.0;
    } else if post_residual < 10 {
        // Unusable dead space in a 1..100 world: heavy penalty.
        score += 200.0 * (10.0 - post_residual as f64);
    }

    // 2-step lookahead: how well does next_item_size relate to post_residual?
    if next_item_size > 0 {
        let next_f = next_item_size as f64;
        let post_f = post_residual as f64;
        if next_item_size == post_residual {
            // Chain fit: next item exactly fills this bin.
            score -= 800.0;
        } else if next_item_size <= post_residual {
            // Next item still fits here: reward proportionally to how tight.
            let tightness = 1.0 - (post_f - next_f) / bin_capacity as f64;
            score -= 300.0 * tightness;
        } else {
            // Next item does NOT fit: this bin's leftover is likely dead space
            // relative to the near future. Penalize gap size.
            let gap = (next_f - post_f).min(100.0);
            score += 60.0 + gap * 1.5;
        }

        // If next item fits ONLY in this bin, strongly favor it.
        if next_item_size <= post_residual && next_item_size <= bin_residual {
            // soft extra nudge for chain continuation
            score -= 50.0;
        }
    }

    // Last-chance bin: if this is the only bin that can fit the item, avoid
    // opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 150.0;
    } else if fitting_bins_count > 1 {
        // Many options: prefer the tightest, penalize slack relative to mean residual.
        score += 0.5 * (post_residual as f64 - mean_residual).max(-50.0).min(50.0);
    }

    // Relative-to-mean archetype coupling: bins with residual far below mean
    // are "almost full" — placing there consolidates waste.
    let rel = post_residual as f64 - mean_residual;
    score += 0.3 * rel;

    // New-bin candidate handling: an empty bin has huge post_residual, which
    // already scores high; add extra penalty so it's only chosen when open
    // bins give bad fits (their dead-space/lookahead penalties dominate).
    if bin_residual == bin_capacity {
        score += 80.0 + 0.2 * open_bins_count as f64;
    } else if open_bins_count > 0 {
        // Slight reward for using existing bins to keep bin count low.
        score -= 20.0;
    }

    // Mild pressure against opening many bins early in the stream.
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize by fraction of bin consumed.
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= 12.0 * fill_frac;

    // Penalize small-but-nonzero dead space (unusable slivers).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item cannot use this residual: mild penalty for leaving large gaps.
            score += 3.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // When many bins are open, discourage opening new ones.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 + 0.15 * open_bins_count as f64 * (0.5 + progress);
    }

    // Prefer bins whose residual is close to the mean residual (balanced packing).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Slight preference for fuller bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with non-linear shaping
    let mut score = norm_pr * (1.0 + 0.8 * norm_pr * (1.0 - norm_pr));

    // Smooth coupling of post-residual with stream progress:
    // later in the stream, tight fits (small post_residual) matter more
    score = score * (1.0 + 0.6 * progress * (1.0 - norm_pr) * (1.0 - norm_pr));

    // Penalize leaving residual that cannot fit the lookahead item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            // reward bins whose leftover can still host the next item
            let usable = (nx / cap) * (1.0 - (pr - nx) / cap);
            score -= 2.0 * usable;
        } else {
            // dead-space penalty, stronger late in the stream
            let dead = (nx - pr) / cap;
            score += 1.5 * dead * dead * (0.5 + progress);
        }
    }

    // Last-chance bonus: only one bin can fit the item -> strongly prefer it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 3.0;
    }

    // Mild preference for fuller bins relative to the fleet average
    score -= 0.3 * ((bin_residual as f64 - mean_residual) / cap);

    // Slight pressure to consolidate when many bins are open
    score += 0.2 * (open_bins_count as f64 / (open_bins_count as f64 + 10.0)) * norm_pr;

    // New-bin candidate: penalize mildly so it is chosen only when open bins fit poorly
    if bin_residual == bin_capacity {
        score += 2.5 + 1.5 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residue modulo 10 (capacity fractions / 10).
    let res = post_residual % 10;
    // Dead-space penalty: small nonzero residues are nearly unusable.
    if post_residual > 0 {
        score += match res {
            0 => -30.0,                       // perfectly aligned residual, very reusable
            1..=3 => 25.0,                    // sliver: high dead-space risk
            4..=7 => 5.0,                     // marginal
            _ => -8.0,                        // half-class residuals often fit small items
        };
    } else {
        score -= 40.0; // perfect fill, best outcome
    }

    // Integer-division thresholds: classify post_residual into usability bands.
    let band = post_residual / 10;
    score -= (band as f64) * 2.0; // bigger usable residual preferred mildly

    // Lookahead coupling: does next item fit exactly into post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect follow-up fit
        } else if next_item_size <= post_residual {
            score -= 20.0 + (post_residual - next_item_size) as f64 * -0.5;
        } else {
            score += 10.0; // next item cannot use this bin's remainder
        }
        // Harmonic pairing: next_item_size and post_residual share a class
        if post_residual % 10 == next_item_size % 10 && post_residual >= next_item_size {
            score -= 12.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible.
    if bin_residual == bin_capacity {
        score += 55.0
            - (open_bins_count as f64).min(8.0) * 1.5
            + (item_size as f64 / cap) * 20.0;
    }

    // Tight fit reward: small post_residual relative to item size is efficient packing.
    score -= (item_size as f64 / (bin_residual as f64 + 1.0)) * 15.0;

    // Stream progression: early on, keep bins flexible (favor larger post_residual).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * (post_residual as f64 / cap) * 5.0;

    // Mean residual coupling: prefer bins whose residual deviates favorably from mean.
    score -= (mean_residual - post_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps (< 10, the
    // classic minimum item size, but interface allows items down to 1, so
    // treat gaps below a small threshold as near-dead with a sharp penalty).
    let dead_threshold = 6.0f64;
    if (post_residual as f64) < dead_threshold {
        score += 40.0;
    } else if (post_residual as f64) < 10.0 {
        score += 25.0;
    }

    // Reward tight fits: the smaller post_residual relative to item_size,
    // the better the fill.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 8.0 * fill_ratio;

    // Penalize wasting a very large residual on a small item (poor fit).
    if (post_residual as f64) > 0.5 * bin_capacity as f64 && (item_size as f64) < 0.4 * bin_residual as f64 {
        score += 12.0;
    }

    // Open-bins pressure: with many open bins, prefer consolidating into
    // existing bins rather than spreading; penalize placements that leave
    // large residuals when bin count is high.
    let ob_pressure = (open_bins_count as f64 / 20.0).min(1.5);
    score += ob_pressure * (post_residual as f64 / bin_capacity as f64) * 10.0;

    // Lookahead: if the next item fits exactly into post_residual, strongly
    // reward this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // mild reward if next item still fits afterward
        score -= 5.0;
    } else if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
        // next item cannot use this residual; penalize leaving medium gaps
        if post_residual < next_item_size as f64 {
            score += 6.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using
    // it over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: an empty bin has post_residual == capacity - item.
    // Make opening a new bin attractive only when no open bin gives a good fit,
    // i.e., when the best existing fit would leave a large residual.
    if bin_residual == bin_capacity {
        // neutral-ish baseline; slight preference early in the stream
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 5.0 * (1.0 - progress);
    }

    // Mild preference for bins below mean residual (balance loads slightly).
    score += 0.05 * (post_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // 2-step lookahead: reward if next item fits exactly into post_residual.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Next item fits: reward proportionally to how snugly.
        let slack = (post_residual - next_item_size) as f64;
        score -= 18.0 * (1.0 - slack / (bin_capacity as f64));
    } else if next_item_size > post_residual {
        // Next item won't fit here: penalize leaving a gap that is nearly
        // useless (too small for anything, i.e. post_residual < min size 10).
        if post_residual < 10 {
            score -= 5.0; // dead space but tiny; mildly fine
        } else {
            score += 6.0 * ((post_residual as f64) / (bin_capacity as f64));
        }
    }

    // Compare post_residual against mean residual across open bins:
    // prefer bins whose residual ends up close to the mean (balanced packing),
    // unless the fit is exact.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.35 * dev;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin would
    // leave a large awkward residual and next item is large.
    if bin_residual == bin_capacity {
        let poor_fit = if post_residual > 0 && next_item_size > post_residual { 1.0 } else { 0.0 };
        score += 30.0 - 22.0 * poor_fit;
    }

    // Early in stream, be slightly more open to new bins (build diverse residuals).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score -= 8.0 * (1.0 - progress);
    }

    // Penalize very large post_residual relative to capacity (wasted space).
    score += 4.0 * ((post_residual as f64) / (bin_capacity as f64)).powi(3);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 20.0 * tightness * tightness;

    // Penalize dead space that is too small to be useful for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, big bonus.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            score -= 0.3 * (post_residual - next_item_size) as f64;
        } else {
            // Next item cannot use the leftover; mild penalty proportional to waste.
            score += 0.15 * (next_item_size - post_residual) as f64;
        }
    }

    // Global state: prefer filling bins when many bins are open.
    score -= 0.5 * open_bins_count as f64;

    // Mean residual coupling: if this bin's residual is below mean, it's a "dying" bin — fill it.
    let res = bin_residual as f64;
    if res < mean_residual {
        score -= 2.0 * (mean_residual - res);
    } else {
        score += 0.5 * (res - mean_residual);
    }

    // Time horizon: early in the stream, be more willing to open new bins;
    // late in the stream, squeeze into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate scoring.
        let mut new_score = bin_capacity as f64; // baseline: fresh bin has full residual
        // Early stream: opening new bins is cheap.
        new_score -= 40.0 * (1.0 - progress);
        // If no bin fits (fitting_bins_count refers to open bins; new bin always fits),
        // this call competes normally. Penalize opening when few bins are open early.
        new_score += 2.0 * open_bins_count as f64 * progress;
        // If next item is large and this item is small, better to keep fresh bins.
        if next_item_size > 60 && item_size < 30 {
            new_score -= 10.0;
        }
        return new_score;
    }

    // Late-stream urgency to use existing space.
    score += 20.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, tolerate leftover space (quadratic damping); late, punish it hard.
    let progress_poly = 0.5 + 1.5 * progress * progress;
    score += (post / cap) * (post / cap) * cap * 0.6 * progress_poly;

    // Reward tight fits: subtract more when post_residual is small relative to capacity.
    let tightness = 1.0 - (post / cap);
    score -= tightness * tightness * cap * 0.35;

    // Lookahead coupling: if next item fits perfectly in the post residual, reward strongly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let gap = post - nxt;
            score -= (1.0 - gap / cap) * 12.0;
        } else {
            // next item won't fit here: penalize wasted pairing potential, smoothly
            score += (nxt - post).min(cap) * 0.08;
        }
    }

    // Last chance: if this is the only bin that can fit the item, strongly favor it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else {
        // spread items across bins; slight penalty when many bins fit
        score += (fitting_bins_count as f64).ln().max(0.0) * 1.5;
    }

    // Coupling with mean residual: prefer bins whose residual deviates favorably
    // (below-mean residual bins are closer to closing -> reward packing them tight).
    let dev = (post - mean_residual) / cap;
    score += dev * 10.0 * progress_poly;

    // New-bin candidate handling: neutral-ish baseline so it's chosen only when
    // no open bin offers a good fit; slightly discourage when open bins exist early.
    if bin_residual == bin_capacity {
        score = cap * (0.55 + 0.25 * progress) + (open_bins_count as f64) * 0.5;
        if fitting_bins_count == 0 {
            score -= 40.0; // no alternative, must open
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo arithmetic on capacity fractions
    let pr = post_residual as u32;
    let class = pr / 10; // coarse harmonic class of dead space
    let phase = pr % 10;

    // Dead space that can never be used by typical items is heavily penalized
    if pr > 0 && pr < 10 {
        score += 60.0; // unusable sliver
    }
    // Harmonic penalty: dead space in awkward classes (11..19, 31..39) is hard to fill
    if pr >= 11 && pr <= 19 {
        score += 18.0 + (phase as f64) * 1.5;
    }
    if pr >= 31 && pr <= 39 {
        score += 10.0;
    }
    // Perfect closures are rewarded
    if pr == 0 {
        score -= 45.0;
    }

    // Coupling with lookahead item: post_residual exactly matching next item is gold
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr as f64 == nxt {
            score -= 55.0;
        } else if pr as f64 > nxt {
            let slack = pr as f64 - nxt;
            // residual after hypothetically placing next item
            let pr2 = slack;
            if pr2 < 10.0 && pr2 > 0.0 {
                score += 20.0; // would create sliver for item after next
            } else {
                score += slack * 0.35;
            }
        } else {
            score += 25.0 + (nxt - pr as f64) * 0.4; // next item won't fit here
        }
    }

    // Integer-division threshold on item fit tightness
    let tight = (item_size as f64) / cap;
    if tight > 0.7 {
        score -= 12.0; // big items prefer tightest available fit
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: baseline attractiveness grows with stream progress and crowding
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 55.0 - 20.0 * progress + 2.0 * (open_bins_count as f64).sqrt();
        if next_item_size > 0 && (next_item_size as f64) / cap > 0.6 {
            score -= 15.0; // big next item: keep capacity free
        }
    }

    // Mild preference to keep mean residual balanced
    score += 0.15 * ((post_residual as f64) - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< 10) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 25 {
        score += 12.0;
    } else if post_residual == 0 {
        score -= 40.0; // perfect fit reward
    }

    // Reward tight fits relative to bin capacity (low waste ratio).
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * waste_ratio * waste_ratio;

    // Reward filling bins deeply (item_size relative to residual).
    score -= 20.0 * (item_size as f64 / bin_residual.max(1) as f64);

    // Open-bin pressure: when many bins are open, avoid opening new bins.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to open bins and mean residual.
        score += 25.0 + 3.0 * open_bins_count as f64 + 0.35 * mean_residual;
        // If only this new bin fits, it must be chosen anyway (low score).
        if fitting_bins_count == 0 {
            score -= 1000.0;
        }
        // If few open bins and item is large, opening fresh bin is fine.
        if open_bins_count <= 2 && item_size > 60 {
            score -= 30.0;
        }
    } else {
        // Existing bin: strong reward when it's the last chance.
        if fitting_bins_count == 1 {
            score -= 35.0;
        }
        // Lookahead: if next item fits in post_residual, reward this placement.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0;
        }
        // Penalize if next item would NOT fit and gap becomes dead space.
        if next_item_size > 0 && post_residual < next_item_size && post_residual < 10 {
            score += 20.0;
        }
        // Slight reward for preferring fuller bins (mean residual comparison).
        if (post_residual as f64) < mean_residual {
            score -= 5.0;
        }
    }

    // Late-stream tightening: be more conservative as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 8.0 * progress * waste_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fit_ratio;

    // Perfect / near-perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 35.0;
    } else if post_residual <= 10 {
        score -= 20.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches the next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual >= next_item_size {
            // Next item fits exactly into this bin's leftover: strong reward.
            score -= 45.0 / (1.0 + gap);
            if gap == 0.0 {
                score -= 40.0; // exact chain: item then next item fills bin perfectly
            }
        } else {
            // Leftover too small for next item: penalize dead space scaled by waste.
            let dead = (post_residual as f64).min((next_item_size - post_residual) as f64);
            score += 0.9 * dead;
        }
        // Coupling with mean residual: bins deviating far below mean residual are precious.
        let dev = mean_residual - post_residual as f64;
        score += 0.35 * dev.max(0.0);
        score -= 0.15 * (-dev).max(0.0);
    } else {
        // Last item: just minimize leftover.
        score -= 10.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 55.0;
    } else if fitting_bins_count > 1 {
        // With alternatives, mildly prefer bins that are already committed (less residual).
        score -= 3.0;
    }

    // Prefer filling nearly-full bins over spreading load across many open bins.
    let fill = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 25.0 * fill * fill;

    // New-bin candidate (empty bin): penalize so it's chosen only when no good fit exists,
    // but allow it when the item is large and open bins would leave big unusable gaps.
    if bin_residual == bin_capacity {
        score += 70.0;
        if item_size >= 60 {
            score -= 30.0; // large items justify fresh bins
        }
        if next_item_size > 0 && next_item_size + item_size > bin_capacity {
            score -= 15.0; // next item can't share with this one anyway
        }
    }

    // Late in the stream, consolidate harder (avoid leaving many partially-filled bins).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 15.0 * progress * fill;

    // Mild penalty on opening bins when many are already open with slack.
    if open_bins_count > 4 && bin_residual == bin_capacity {
        score += 5.0 * (open_bins_count as f64).ln();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits: small post_residual relative to capacity.
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score += tightness * tightness * 40.0;

    // Penalize exact-equality waste slightly differently: a post_residual of 0 is ideal.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 12.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            // Partial credit proportional to how well next item uses the leftover.
            let fill = (next_item_size as f64) / (post_residual as f64);
            score -= 10.0 * fill;
        } else {
            // Next item cannot use the leftover; penalize large dead space more.
            score += ((post_residual as f64) - (next_item_size as f64)).max(0.0) * 0.15;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0 + (item_size as f64) / (bin_residual as f64) * 10.0;
    }

    // New-bin candidate handling: make opening a new bin costly unless current
    // residual is nearly unusable for typical items.
    if bin_residual == bin_capacity {
        // Baseline score for a fresh bin: moderately high so tight fits win.
        score = 55.0;
        // Open a new bin more willingly late in the stream or when many bins
        // are open with scattered residuals (fragmentation).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= progress * 5.0;
        if mean_residual < 15.0 && open_bins_count > 0 {
            score -= 10.0; // existing bins are nearly full anyway
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open new bin
        }
    } else {
        // Prefer bins whose residual is below mean (consolidating fuller bins).
        if (bin_residual as f64) < mean_residual {
            score -= 6.0;
        } else {
            score += 4.0;
        }
    }

    // Mild penalty for spreading across many open bins when residual is large.
    if post_residual > 50 {
        score += (open_bins_count as f64) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalize stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Smooth non-linear penalty on wasted residual: quadratic in post_residual,
    // amplified as the stream progresses (dead space late in the stream is costlier).
    let waste = (post_residual as f64 / bin_capacity as f64).powi(2);
    score += 40.0 * (0.5 + progress) * waste;

    // Cubic coupling: very small residuals are nearly dead space — penalize extra.
    let r = post_residual as f64 / bin_capacity as f64;
    score += 15.0 * r.powi(3);

    // Lookahead coupling: reward bins whose post_residual can host the next item,
    // smoothly scaled by how tightly the next item fits.
    if next_item_size > 0 && next_item_size <= post_residual {
        let tight = next_item_size as f64 / (post_residual as f64 + 1.0);
        score -= 12.0 * (1.0 + tight);
    } else if next_item_size > post_residual {
        // Post-residual cannot host next item: smooth penalty growing with the gap.
        let gap = (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
        score += 8.0 * gap;
    }

    // Reward tight fits overall (small post_residual relative to item size).
    score -= 6.0 * (item_size as f64 / bin_capacity as f64);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // over opening a new bin (smooth decay of the bonus with progress).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 - 0.5 * progress);
    }

    // New-bin candidate handling: penalize opening a new bin mildly, more so when
    // fitting bins exist and mean residual is large (good space being abandoned).
    if bin_residual == bin_capacity {
        let abandon = (mean_residual / bin_capacity as f64).max(0.0);
        score += 10.0 + 20.0 * abandon * (0.5 + progress);
    } else {
        // Mild reward for keeping bins balanced: prefer bins with residual near mean.
        let dev = (bin_residual as f64 - mean_residual).abs() / bin_capacity as f64;
        score += 5.0 * dev;
    }

    // Slight preference for filling bins with more content already (fewer total bins).
    score -= 3.0 * (1.0 - bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: items leaving tiny residues create dead space.
    // Class 0: post_residual == 0 (perfect fit) -> strong reward.
    // Class 1: post_residual < 10 -> nearly perfect, mild reward.
    // Class 2: 10..=20 -> usable for small future items, neutral.
    // Class 3: larger -> penalize proportionally.
    let class = if post_residual == 0 { 0 }
        else if post_residual < 10 { 1 }
        else if post_residual <= 20 { 2 }
        else { 3 };

    match class {
        0 => score -= 40.0,
        1 => score -= 12.0,
        2 => score += 0.0,
        _ => score += (post_residual as f64 - 20.0) * 0.15,
    }

    // Harmonic residue classes via modulo: residues divisible by common item granularities
    // (5, 10) are more likely reusable by future items.
    if post_residual > 0 && post_residual % 10 == 0 {
        score -= 6.0;
    } else if post_residual % 5 == 0 {
        score -= 3.0;
    }

    // Lookahead: reward if the next item fits exactly in the post residual (perfect chain).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            // Harmonic class of leftover after a hypothetical next placement.
            let post2 = post_residual - next_item_size;
            if post2 == 0 {
                score -= 20.0;
            } else if post2 < 10 {
                score -= 8.0;
            } else {
                score += post2 as f64 * 0.05;
            }
        } else {
            // Next item cannot use this bin's residue; penalize large wasted residue
            // relative to the next item size gap.
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.08;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate (empty bin): discourage opening a new bin unless the item
    // leaves a well-structured residue or no good open bin exists. Empty bin has
    // post_residual == bin_capacity - item_size which is large; add penalty scaled
    // by how many bins could already fit the item.
    if bin_residual == bin_capacity {
        let crowding = if fitting_bins_count == 0 { 0.0 } else { fitting_bins_count as f64 };
        score += 30.0 + crowding * 10.0;
        // But if the item is large (harmonic class of item size: > half capacity),
        // opening fresh bins is often fine.
        if item_size * 2 > bin_capacity {
            score -= 20.0;
        }
    }

    // Stream progression: early on, prefer tighter packing discipline; late in the
    // stream, allow slightly more aggressive use of existing bins to close them out.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 5.0 * (mean_residual / bin_capacity as f64);

    // Prefer bins whose residual is close to the mean (balanced closing strategy),
    // penalize outliers.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Many open bins: favor filling existing ones to consolidate.
    score += open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // for typical future items are heavily penalized.
    let dead_threshold = 12.0;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 6.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward tight fits relative to bin residual (high fill ratio).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 8.0;

    // Penalize wasting a large residual on a small item (poor packing).
    if fill_ratio < 0.35 {
        score += (0.35 - fill_ratio) * 15.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading;
    // with few open bins, slightly favor reusing existing bins.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * 1.5;

    // Lookahead: if the next item fits exactly in post_residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size < post_residual {
            // next item fits: mild reward proportional to remaining slack after that.
            let second_residual = post_residual - next_item_size;
            score -= (second_residual as f64) * 0.05;
        } else {
            // next item will not fit here: small penalty for creating a near-miss gap.
            let gap = (next_item_size - post_residual) as f64;
            if gap < dead_threshold {
                score += (dead_threshold - gap) * 2.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: prefer a fresh bin only when this item fits
    // poorly everywhere else (large post_residual elsewhere) or no real fit.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        let mut new_bin_score = 30.0 + open_bins_count as f64 * 2.0;
        // If mean residual across open bins is large, opening a new bin is wasteful.
        new_bin_score += mean_residual * 0.4;
        // Late in the stream, prefer consolidation into existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        new_bin_score += progress * 10.0;
        // If the next item is large, a fresh bin is more valuable.
        if next_item_size >= item_size {
            new_bin_score -= 8.0;
        }
        score = score.max(new_bin_score);
        score = new_bin_score.max(score);
        // blend: take the worse (higher) of item-placement score and new-bin cost
        score = if new_bin_score > score { new_bin_score } else { score };
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong 2-step lookahead: reward exact/near-exact match of post_residual to next item.
    if next_item_size > 0 {
        let match_gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 / (1.0 + match_gap);
        // Perfect chain: post_residual exactly equals next item size
        if post_residual == next_item_size {
            score -= 40.0;
        }
        // Penalize post_residual that is slightly too small to fit next item (dead space)
        if post_residual < next_item_size {
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: prefer filling bins as tightly as possible
        score -= 50.0;
    }

    // Reward tight fits relative to bin capacity (low post_residual fraction)
    score -= 30.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Penalize bins whose residual is far above the mean residual (wasteful bin)
    score += 0.3 * ((post_residual as f64 - mean_residual).abs());

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // New-bin candidate (empty bin): usually worse than a good existing fit,
    // but attractive when no open bin fits well or lookahead is poor.
    if bin_residual == bin_capacity {
        score += 25.0;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        if next_item_size > 0 && next_item_size > bin_capacity {
            score -= 20.0;
        }
    }

    // Late in the stream, consolidate: avoid opening new bins
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 40.0 * progress;
    }

    // Many open bins: prefer compacting into existing bins
    score += 0.5 * open_bins_count as f64 * (bin_residual == bin_capacity) as i32 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits (small post_residual is already rewarded,
    // but amplify the tight-fit region non-linearly).
    let cap = bin_capacity as f64;
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 18.0 * tightness * tightness * tightness;

    // Penalize creating dead space that is too small to be useful for future items
    // (residuals in [1, 9] are nearly unusable since items are >= 1 but typical sizes larger).
    if post_residual > 0 && post_residual < 12 {
        score += 8.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item exactly/well.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 12.0; // perfect chaining
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 6.0 * (1.0 - slack / cap);
        } else {
            // next item cannot fit here; slight penalty proportional to how wasted the space is
            score += 2.0 * (next_item_size as f64 - post_residual as f64) / cap;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // rather than opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: opening a new bin should only win when no open bin
    // fits well. Penalize the fresh bin by the residual it locks in.
    if bin_residual == bin_capacity {
        // Base penalty so open bins with decent fits win.
        score += 6.0;
        // If many bins fit already, opening new is wasteful.
        if fitting_bins_count > 0 {
            score += 3.0 * (fitting_bins_count as f64).ln().max(0.0);
        }
        // Early in the stream, new bins are cheap; late, prefer consolidation.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 6.0 * progress;
        // If the item is large relative to capacity, a fresh bin is natural.
        score -= 0.05 * item_size as f64;
    } else {
        // Mild preference for bins with below-average residual (balance load),
        // but keep tight fits dominant.
        score += 0.02 * ((bin_residual as f64) - mean_residual);
        // Slight bonus for keeping the number of open bins from exploding.
        score += 0.01 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let x = post / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early stream: prefer tight fills (low post_residual); late stream:
    // increasingly penalize large dead space quadratically.
    let mut score = post * (1.0 + 0.8 * progress) + 2.5 * x * x * (0.5 + progress);

    // Lookahead: reward residual that can host the next item (smooth kernel).
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let fit = (post - n).abs() / cap;
        score -= 1.2 * (-3.0 * fit * fit) * (1.0 - progress * 0.5);
    }

    // Last-chance bin: strongly discourage opening a new bin when only one fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 3.0 + 2.0 * progress;
    }

    // New empty bin candidate: penalize mildly, more when many bins already open
    // and mean residual is still large.
    if bin_residual == bin_capacity {
        score += 1.5 + 0.05 * open_bins_count as f64 + (mean_residual / cap).max(0.0);
    }

    // Mild preference for fuller bins relative to fleet mean residual.
    score += 0.3 * (mean_residual - post) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into coarse buckets.
    let class = post_residual / 10; // 0..10 harmonic class
    // Dead-space penalty grows superlinearly for small-but-unusable leftovers.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if class >= 1 && class <= 3 {
        // Small leftovers (10..39) are moderately wasteful.
        score += (4 - class) as f64 * 6.0;
    } else if class >= 7 {
        // Large leftovers are attractive: room for future items.
        score -= (class - 6) as f64 * 4.0;
    }

    // Exact-fill reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Coupling with lookahead: prefer residuals that can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
        // Harmonic match: next item leaves a small class again -> chain potential.
        let next_class = (post_residual - next_item_size) / 10;
        if next_class <= 1 {
            score -= 8.0;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Leftover that next item cannot use: penalize proportionally.
        score += (next_item_size as f64 - post_residual as f64) * 0.3;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: neutral-ish baseline, penalize opening new bins
    // unless current residuals are badly fragmented.
    if bin_residual == bin_capacity {
        score = 55.0 + (open_bins_count as f64).sqrt() * 3.0;
        if mean_residual < 15.0 {
            score -= 20.0;
        }
        if post_residual == 0 {
            score -= 60.0;
        }
        if next_item_size > 0 && next_item_size >= bin_capacity {
            score -= 30.0;
        }
    }

    // Progress term: late in the stream, consolidate aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0;

    // Mild penalty for spreading across many bins when mean residual is large.
    if mean_residual > 30.0 && post_residual > 30 {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // possible item (1) are pure waste; residuals below a usable threshold
    // (likely dead for typical next items) are penalized super-linearly.
    let dead_threshold = 15u32;
    if post_residual > 0 && post_residual <= dead_threshold {
        score += (dead_threshold - post_residual + 1) as f64 * 6.0;
    }
    if post_residual == 0 {
        // Perfect fit: reward strongly.
        score -= 40.0;
    }

    // Reward tight fits relative to the bin: small post_residual generally
    // good, but amplify when it still accommodates the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 + (next_item_size as f64) * 0.3;
    } else if next_item_size > 0 {
        // This bin becomes dead for the next item: penalize proportionally
        // to how much of the next item is wasted.
        score += (next_item_size as f64 - post_residual as f64) * 0.5;
    }

    // Last-chance bin pressure: if this is the only fitting bin, strongly
    // prefer using it over opening a new bin (unless dead space is severe).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading; prefer
    // consolidating into existing bins, mildly scaled by stream progress.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64) * (1.0 + 0.5 * progress);

    // Prefer bins whose residual deviates favorably from the mean
    // (tighter-than-average bins are closer to closing).
    if bin_residual != bin_capacity {
        score += (bin_residual as f64 - mean_residual) * 0.15;
    }

    // New-bin candidate: only attractive when no open bin fits well
    // (i.e., we're called with residual == capacity and existing bins are
    // poor). Base cost so a new bin is chosen only when penalties elsewhere
    // dominate; slight discount when many bins are open (spread load).
    if bin_residual == bin_capacity {
        score = 30.0 + (open_bins_count as f64) * 0.2 - (item_size as f64) * 0.1;
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.88;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_pr = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let mut score = pr;
    score += 6.0 * norm_pr * norm_pr * cap;
    score -= 10.0 * norm_pr * norm_pr * norm_pr * cap * (0.5 + progress);
    score += 4.0 * norm_pr * progress * cap;

    // Reward tight fits (small post residual) more strongly later in stream
    score -= 8.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * progress;

    // Lookahead: reward if next item fits the post residual
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        score += 3.0 * (next_item_size as f64 / cap);
    }

    // Last-chance bin: strong reward to use it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize opening new bins when many bins are open with slack
    if bin_residual == bin_capacity {
        score += 5.0 + 2.0 * mean_residual / cap;
        score -= 0.5 * open_bins_count as f64;
    }

    // Penalize waste relative to mean residual of open bins
    score += 0.5 * (pr - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "usable"
    // classes (multiples of 10, or >= next item size) are rewarded.
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Class 1: post_residual is a multiple of 10 -> highly reusable leftover.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    }
    // Class 2: post_residual divisible by 5 but not 10 -> mildly reusable.
    else if post_residual % 5 == 0 && post_residual > 0 {
        score -= 2.5;
    }

    // Perfect fit: zero dead space, always excellent.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead harmonic coupling: leftover that can host the next item is gold.
    if next_item_size > 0 && post_residual >= next_item_size {
        // Reward grows when leftover is an exact harmonic multiple of next item.
        let ratio = post_residual as f64 / next_item_size as f64;
        let harmonic_bonus = if (post_residual % next_item_size) == 0 && post_residual != next_item_size {
            9.0
        } else {
            5.0
        };
        score -= harmonic_bonus * (0.5 + 0.5 * (1.0 - (ratio - ratio.floor()).abs()));
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Dead space that the next item cannot use: penalize proportionally.
        score += (post_residual as f64) * 0.35 * (1.0 + progress);
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Penalize leaving large residuals when many bins are already open (fragmentation).
    let frag = (open_bins_count as f64).sqrt() * (post_residual as f64 / bin_capacity as f64);
    score += 0.8 * frag * progress;

    // Prefer bins tighter than the mean residual (best-fit flavor).
    let diff = bin_residual as f64 - mean_residual;
    score += 0.15 * diff;

    // Mild preference for using existing bins over opening new ones early on.
    if bin_residual == bin_capacity {
        score += 3.0 + 4.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 120.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual == 0 {
        score -= 60.0; // perfect fit
    }

    // Reward tight fits (small post_residual relative to item size).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fill_ratio;

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 2.0;

    // Prefer bins whose residual is close to the item (low waste).
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += gap * 0.3;

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0;
    }
    // Penalize leaving a gap that is too small for the next item.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 15.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 0.0 } else { 80.0 };
        score = bin_capacity as f64 * 0.5 + desperation + open_bins_count as f64 * 2.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 20.0; // new bin useful for a chain of large items
        }
    }

    // Mild stream-progression damping.
    score *= 1.0 + 0.1 * (step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: item + next item exactly fills bin
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 200.0;
    }
    // Next item fits in the residual: strong reward proportional to tightness
    else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0 + (post_residual - next_item_size) as f64 * 0.5;
    }
    // Next item does NOT fit: residual becomes dead space; penalize small unusable residuals
    else if next_item_size > 0 {
        score += 30.0;
    }

    // Tight fit reward: penalize bins where the item leaves little waste
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= 60.0 * (1.0 - tightness) * (1.0 - tightness);

    // Penalize creating residual that is too small to ever be useful (min item ~1, but small slivers waste)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: only attractive when no good fit exists or many bins are open
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let bad_fit = next_item_size > 0 && post_residual < next_item_size;
        let penalty = 120.0 - 40.0 * progress - 30.0 * (open_bins_count as f64 / (open_bins_count as f64 + 4.0));
        score += if bad_fit { penalty * 0.4 } else { penalty };
    } else {
        // Prefer bins with residual close to mean (balanced packing), slight pull
        score += 0.1 * (bin_residual as f64 - mean_residual).abs();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: quadratic bonus for small post_residual
    score -= 3.0 * (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64
        * (item_size as f64 / bin_capacity as f64);

    // Lookahead: if next item fits exactly in post_residual, strongly favor this bin
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        score -= 8.0 * (1.0 - slack as f64 / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Penalize leaving dead space that next item cannot use
        score += 0.5 * post_residual as f64 / bin_capacity as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Penalize opening a new bin when decent fitting bins exist
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let decent_fit_exists = mean_residual > item_size as f64 * 1.05;
        if decent_fit_exists && fitting_bins_count > 0 {
            score += 10.0 + 5.0 * (1.0 - progress);
        } else {
            score -= 2.0 * (open_bins_count as f64 / (open_bins_count as f64 + 1.0));
        }
    }

    // Mild preference to fill bins below mean residual (balance avoidance of fragmentation)
    if bin_residual < bin_capacity {
        score += 0.3 * (mean_residual - bin_residual as f64).abs() / bin_capacity as f64;
    }

    // Time-varying exploration: early on, tolerate looser fits to gather info
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.2 * (1.0 - progress) * ((step_index % 7) as f64 / 7.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Non-linear polynomial coupling of post_residual with progress:
    // later in the stream, waste is punished more aggressively.
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    let poly = pr_norm * pr_norm * (1.0 + 3.0 * progress) + pr_norm * (0.5 + 2.0 * progress * progress);
    score += 20.0 * poly;

    // Reward tight fits (small post_residual relative to item size)
    if item_size > 0 {
        let tightness = 1.0 - pr / (item_size as f64 + pr);
        score -= 10.0 * tightness * tightness;
    }

    // Lookahead: bonus if next item fits the post-residual exactly-ish
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        let gap = ((post_residual as f64) - next_item_size as f64) / cap;
        score -= 6.0 * (1.0 - gap) * (1.0 - gap);
    } else if next_item_size > 0 {
        // next item won't fit: penalize proportionally to wasted potential
        score += 4.0 + 3.0 * progress;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize, more so late in the stream and when
    // open bins already exist and mean residual is large.
    if bin_residual == bin_capacity {
        let mean_pull = (mean_residual / cap).clamp(0.0, 1.0);
        score += 25.0 + 30.0 * mean_pull + 10.0 * progress + (open_bins_count as f64).sqrt() * 2.0;
    } else {
        // Reward using already-open bins, scaled by their relative fullness
        let fill = 1.0 - (bin_residual as f64) / cap;
        score -= 8.0 * fill * fill;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), but treat exact fits specially.
    if post_residual == 0 {
        score -= 1000.0; // perfect fit is always best
    }

    // Harmonic class logic: partition post_residual into capacity-fraction classes.
    // Residuals in the "useful small" band (0..=20) are far more valuable than large ones.
    let pr = post_residual;
    if pr > 0 {
        // Class via integer division thresholds on post_residual
        let class = pr / 10; // 0..10 harmonic band
        // Penalize large dead space super-linearly; small residuals get mild penalty
        score += (class as f64) * (class as f64) * 2.5;
        // Dead space that can never hold typical small items is worse
        if pr < 10 {
            score -= 15.0; // near-full bin is a good outcome anyway
        } else if pr > 50 {
            score += 20.0; // leaving more than half a bin empty is wasteful
        }
    }

    // Lookahead: reward bins whose post_residual can host the next item (k=2 lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        // Bonus scaled by how well next item fills the remainder (harmonic coupling)
        let next_fill = next_item_size as f64 / post_residual as f64;
        score -= 25.0 + 30.0 * next_fill;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Residual too small for next item: mild penalty proportional to wasted potential
        score += 8.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a new bin should only win when no open bin
    // gives a decent fit. Penalize the empty-bin candidate, more so when good fits exist.
    if bin_residual == bin_capacity {
        let mut penalty = 55.0;
        if fitting_bins_count > 0 {
            penalty += 25.0;
        }
        // Late in the stream, consolidation matters more
        let progress = step_index as f64 / (total_items.max(1) as f64);
        penalty += 20.0 * progress;
        // If mean residual across open bins is large, prefer reusing them
        penalty += (mean_residual / 10.0).min(15.0);
        score += penalty;
    }

    // Mild pressure against keeping many bins open with large residuals
    if open_bins_count > 4 {
        score += (open_bins_count as f64 - 4.0) * 1.5;
    }

    // Modulo-arithmetic harmonic class: residuals that are multiples of common
    // item-size blocks (10, 20, 25) are more reusable.
    if pr % 10 == 0 && pr > 0 {
        score -= 6.0;
    }
    if pr % 25 == 0 && pr > 0 {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 1000.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    if post_residual == 0 {
        score -= 500.0; // perfect fill
    } else {
        let tightness = post_residual as f64 / (bin_residual as f64).max(1.0);
        score += tightness * 50.0; // penalize loose fits
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // Open bins pressure: when many bins are open, discourage opening new ones.
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins open or late in stream.
        score += 200.0 + 15.0 * open_bins_count as f64 + 100.0 * progress;
        // But if no existing bin fits well, allow new bin occasionally
        if fitting_bins_count == 0 {
            score -= 250.0;
        }
    } else {
        // Existing bin: mild reward for using it when many bins are open.
        score -= 2.0 * open_bins_count as f64;
    }

    // Lookahead: if the next item fits exactly into post_residual, reward strongly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual >= next_item_size {
            score -= 30.0;
        } else {
            score += 20.0; // next item won't fit here; dead space likely
        }
    }

    // Deviation from mean residual: prefer bins whose residual is close to mean
    // to keep residual distribution balanced, but slightly favor larger residuals.
    score += (bin_residual as f64 - mean_residual).abs() * 0.5
        - (bin_residual as f64 - mean_residual) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (early: keep bins flexible; late: pack tight)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Perfect 2-step lookahead match: post_residual exactly fits next item -> strong reward
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Reward exact match heavily
        if diff == 0.0 {
            score -= 60.0 + 40.0 * (1.0 - progress);
        } else {
            // Penalize proximity mismatch: closer match = lower score
            score += 0.8 * diff;
            // If next item cannot fit in post_residual, penalize proportionally
            if post_residual < next_item_size {
                score += 10.0 + 0.3 * (next_item_size - post_residual) as f64;
            }
        }
        // Bonus if item + next item perfectly fill the bin (post_residual == next_item_size handled above)
        // Chain fill: if next item would leave zero residual after placement too
        if next_item_size > 0 && next_item_size <= post_residual {
            let chain_post = post_residual - next_item_size;
            if chain_post == 0 {
                score -= 25.0;
            }
        }
    } else {
        // Last item: minimize wasted residual aggressively
        score -= 30.0;
    }

    // Tight fit reward: small post_residual relative to item size (good space usage)
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 20.0 * (1.0 - fit_ratio);

    // Compare post_residual to mean residual across open bins:
    // leaving less than the mean is good (this bin is being packed tighter than average)
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 45.0;
    }

    // Penalize opening new bins when many bins are open and mean residual is large
    if bin_residual == bin_capacity {
        // New-bin candidate: base penalty, relaxed if mean residual is small (nothing fits well)
        let mean_fit_pressure = (mean_residual / bin_capacity as f64).max(0.0);
        score += 55.0 - 50.0 * (1.0 - mean_fit_pressure);
        // Late in stream, prefer reusing existing bins even more
        score += 15.0 * progress;
        // If no open bin leaves room for the next item, opening a new bin is more acceptable
        if next_item_size > 0 && mean_residual < next_item_size as f64 {
            score -= 20.0;
        }
    }

    // Dead-space penalty: post_residual too small to ever fit typical items (min size 1..100 unknown,
    // use item_size as proxy for scale)
    let min_useful = (item_size / 4).max(1);
    if post_residual < min_useful {
        score += 12.0;
    }

    // Mild penalty for accumulating many open bins
    score += 0.15 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic bonus for small post residual.
    let tight = (post_residual as f64) / bin_capacity as f64;
    score -= 6.0 * (1.0 - tight * tight);

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Penalize post residuals that are too small for any plausible future item
    // (dead space): residual in [1, 9] is nearly unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            score -= 4.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are quite full.
    if bin_residual == bin_capacity {
        let mean_fill = 1.0 - mean_residual / bin_capacity as f64;
        score += 20.0 - 25.0 * mean_fill;
        // Early in the stream, be more willing to open bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 5.0 * (1.0 - progress);
    } else {
        // Slight preference for bins whose residual is close to the mean (balanced use),
        // but favor below-mean-residual bins (fuller bins) mildly.
        let dev = bin_residual as f64 - mean_residual;
        score += 0.05 * dev;
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.3 * open_bins_count as f64 * tight;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;

    // Penalize small nonzero dead space (unusable slivers) via smooth bump
    let pr = post_residual as f64;
    if pr > 0.0 {
        let sliver = ((cap / 2.0 - pr) / cap).powi(2);
        score += 12.0 * (1.0 - sliver) * (1.0 - progress);
    }

    // Reward tight fits (small post_residual) more strongly later in stream
    let tightness = 1.0 - pr / cap;
    score -= 8.0 * tightness * tightness * (0.5 + progress);

    // Lookahead: reward if next item fits into post_residual
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 6.0 * (1.0 - (pr - next_item_size as f64) / cap);
    } else if next_item_size > 0 {
        score += 4.0 * progress;
    }

    // Last chance bin: strong reward to use it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize spreading across many open bins; encourage consolidation
    score += (open_bins_count as f64).sqrt() * 1.5;

    // New-bin candidate: make it unattractive unless residuals of open bins are very tight
    if bin_residual == bin_capacity {
        score += cap * 0.6 + mean_residual * 0.2 - 20.0 * (1.0 - progress);
    }

    // Mild coupling with mean residual: prefer bins below mean residual (tighter)
    score += 0.3 * (pr - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo arithmetic on residual space
    let post = post_residual as u32;
    let class = post % 10; // decile class of leftover space
    // Reward leftovers that fall into "useful" small classes (tight fits)
    match class {
        0 => score -= 8.0,          // perfect multiple: highly reusable
        1..=3 => score -= 4.0,      // near-perfect fill
        4..=6 => score += 2.0,      // moderately awkward
        _ => score += 5.0,          // large awkward leftovers
    }

    // Integer-division thresholds: residual in quarters of capacity
    let quarter = bin_capacity / 4;
    if post < quarter {
        score -= 6.0; // bin nearly full -> good placement
    } else if post < 2 * quarter {
        score += 0.0;
    } else {
        score += 3.0; // bin still mostly empty after placement -> wasteful
    }

    // Lookahead coupling: does next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= post {
            // harmonic compatibility: next item's class matches leftover
            let compat = (next_item_size % 10) == (post % 10);
            score -= if compat { 10.0 } else { 5.0 };
        } else {
            score += 4.0; // leftover unusable by next item
        }
    } else {
        score += 2.0; // last item: prefer filling existing bins
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless
    // item is large and current bins are fragmented
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = mean_residual / cap;
        let penalty = 15.0 + 20.0 * (1.0 - fragmentation) * (1.0 - progress);
        score += penalty;
        if item_size >= 50 && fragmentation > 0.5 {
            score -= 18.0; // big item into fresh bin when open bins are fragmented
        }
    }

    // Prefer bins whose residual is close to the mean (balance preservation)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Slight preference for tighter fits overall
    score += 0.1 * (post as f64 / cap) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small to hold even the
    // smallest plausible item are pure waste. Penalize them super-linearly.
    let dead_threshold = 12.0f64;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 4.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 10.0;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading items;
    // with few open bins, opening a new one is cheaper.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.3 + 0.7 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline cost plus pressure to keep bin count low.
        score = 45.0 + pressure * 2.0;
        // If lookahead item fits comfortably in the residual this placement
        // would leave, opening a new bin is more attractive.
        if next_item_size > 0 && next_item_size as f64 <= post_residual as f64 {
            score -= 8.0;
        }
        // Never open a new bin when this is the only fitting bin.
        if fitting_bins_count == 1 {
            score += 60.0;
        }
    } else {
        // Prefer bins whose residual is close to the mean (balanced packing),
        // but only mildly, so dead-space logic dominates.
        score += (bin_residual as f64 - mean_residual).abs() * 0.15;
        // If the next item fits exactly in the post residual, big reward.
        if next_item_size > 0 && next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size > 0 && next_item_size > post_residual {
            // Dead space for the lookahead item: penalize proportionally.
            score += (next_item_size.min(bin_capacity) as f64 - post_residual as f64) * 0.2;
        }
        // Slight penalty for using a very full bin when alternatives exist.
        if fitting_bins_count > 2 {
            score += (bin_residual as f64 - item_size as f64).max(0.0) * 0.05;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: this bin's leftover exactly fits the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near-match: next item fits with small slack.
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 30.0 * (1.0 - slack / bin_capacity as f64);
    }
    // Next item will NOT fit in the leftover: penalize proportional dead space.
    else if next_item_size > 0 && post_residual < next_item_size {
        score += 25.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Reward closing bins tightly relative to the average open-bin residual.
    let tightness = (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64;
    score -= 15.0 * tightness;
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Early in the stream, prefer spreading items to build good residual structure.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * (1.0 - progress);

    // New-bin candidate: only attractive when current bin would be badly fragmented
    // or no open bin fits well.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin anyway
        } else if next_item_size > 0 && post_residual as f64 > next_item_size as f64 + 20.0 {
            score += 20.0; // keep existing bins when they fit reasonably
        } else {
            score += 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress of the stream (0..1), with a soft floor for early steps.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let p = progress.clamp(0.0, 1.0);

    // Tightness of fit: reward near-perfect packing, penalize large post residual.
    let tight = post_residual as f64 / bin_capacity as f64;
    score += 25.0 * tight * tight;

    // Lookahead: strongly reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 18.0 - 2.0 * (slack / bin_capacity as f64).min(1.0);
        } else {
            // Post residual is dead space for the next item: mild penalty.
            score += 4.0 + 6.0 * p;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }
    // Crowded choice: slight tie-break penalty so many fitting bins compete on tightness.
    if fitting_bins_count > 2 {
        score += 1.5 * (fitting_bins_count as f64 - 2.0).ln();
    }

    // Global state coupling: prefer filling bins when mean residual is high (waste is piling up).
    score -= 0.15 * (mean_residual - post_residual as f64);

    // Late in the stream, closing out bins matters more: reward low post residual harder.
    score += 10.0 * p * tight;

    // New-bin candidate: only attractive when item fits poorly everywhere
    // (i.e., this empty bin gives a much better post residual than typical open bins).
    if bin_residual == bin_capacity {
        let new_bin_bonus = 12.0 + 20.0 * p + 0.1 * mean_residual;
        // Penalize opening new bins when many bins already fit the item (fragmentation risk).
        let crowd_penalty = 6.0 * (fitting_bins_count as f64).min(8.0);
        // Small intrinsic cost to keep bin count down.
        score = score.max(0.0) + bin_capacity as f64 - new_bin_bonus + crowd_penalty
            + 0.02 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let r = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_r = r / cap;

    // Base: post-residual, scaled smoothly by stream progress
    let mut score = r * (1.0 + 0.35 * t * t);

    // Non-linear penalty for small residuals (dead space), stronger early
    let dead = (1.0 - norm_r).powi(3);
    score += 8.0 * dead * (1.0 - t);

    // Reward tight fits: low post residual relative to item size
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 6.0 * fit_ratio * fit_ratio * (1.0 + t);

    // Last-chance bin bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 12.0 + 10.0 * t;
    }

    // Lookahead coupling: if next item fits post-residual, reward
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= r {
            score -= 4.0 * (nx / cap) * (1.0 - t * 0.5);
        } else {
            score += 2.0 * ((nx - r) / cap) * (1.0 + t);
        }
    }

    // Deviation from mean residual: prefer bins near mean (balance)
    let dev = (r - mean_residual).abs() / cap;
    score += 3.0 * dev * dev;

    // Slight penalty for many open bins relative to progress (encourage consolidation)
    let bins_norm = open_bins_count as f64 / (total_items.max(1) as f64);
    score += 5.0 * bins_norm * (1.0 - t);

    // New-bin candidate: penalize mildly unless residual waste is severe elsewhere
    if bin_residual == bin_capacity {
        score += 3.0 - 2.0 * t;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: capacity fraction classes (mod logic)
    let item_class = item_size / 10;              // 0..=10
    let next_class = next_item_size / 10;
    let post_class = post_residual / 10;          // dead-space class

    // Reward tight fits: post_residual in low classes is good.
    // Exponential penalty on dead space, stronger when post_residual
    // cannot accommodate any plausible future item (small classes).
    if post_residual > 0 {
        let dead = post_residual as f64;
        // dead space below 10 is nearly unusable (min item size 1..100 unknown, but small)
        if post_residual < 10 {
            score += 25.0 * (1.0 - dead / 10.0) + 8.0;
        } else if post_residual < 20 {
            score += 6.0;
        }
        // Wasted fraction penalty scaled by capacity fraction
        score += 0.35 * (dead * dead) / (bin_capacity as f64);
    } else {
        // Perfect fit: strong reward
        score -= 30.0;
    }

    // Lookahead coupling: if the next item fits exactly in post_residual,
    // heavily reward; if post_residual can't fit next item, penalize mildly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            // reward proportional to how much next item consumes of residual
            score -= 6.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here regardless; residual becomes dead weight
            score += 0.10 * (post_residual as f64 - (next_item_size as f64 - post_residual as f64)).abs();
        }
        // Harmonic class match: same class next item benefits from same-class bin
        if next_class == item_class && next_item_size <= post_residual {
            score -= 3.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 {
        score -= 12.0;
    } else if fitting_bins_count > 1 {
        // competition: prefer bins with less residual after placement
        score += 0.05 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate: opening a new bin wastes the residual of existing bins.
    // Penalize new bins unless this item is large and current bin is fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let base = 20.0 + 10.0 * (1.0 - progress);
        // new bin is attractive for very large items (harmonic top classes)
        if item_class >= 7 {
            score = base - 8.0;
        } else {
            score = base;
        }
        // if many bins can already fit, opening new bin is wasteful
        score += 2.0 * fitting_bins_count as f64;
    }

    // Mild preference toward filling bins that are already mostly full
    // (keeps number of open bins low, mean residual coupling).
    let fill_frac = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 4.0 * fill_frac;

    // Penalize bins far from mean residual (fragmentation balancing)
    score += 0.05 * (mean_residual - bin_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever
    // hold a future item (below the minimum plausible item size) are waste.
    // Penalize "unusable" gaps quadratically.
    if post_residual < 10 && post_residual > 0 {
        score += (10 - post_residual) as f64 * 8.0;
    }

    // Reward tight fits: post_residual near zero is excellent.
    score -= ((bin_capacity as f64 - post_residual as f64) / bin_capacity as f64).powi(2) * 15.0;

    // If this bin is the ONLY fitting bin, strongly prefer using it
    // (last-chance placement avoids opening a new bin).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bins pressure: with many open bins, prefer consolidation;
    // with few open bins, tolerate spreading.
    score += open_bins_count as f64 * 0.8;

    // Lookahead coupling: if next item fits exactly in the post_residual,
    // reward this placement; if post_residual can't fit next item but
    // could have if we chose differently, slight penalty.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
        }
        if post_residual > 0 && post_residual < next_item_size {
            score += 4.0;
        }
    }

    // Slightly favor bins whose residual is far from the mean residual
    // (keeps diversity of gap sizes for future odd-sized items).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    // New-bin candidate: make it attractive only when no open bin fits well
    // (i.e., tight fits elsewhere dominate), otherwise discourage it.
    if bin_residual == bin_capacity {
        score += 12.0;
        if open_bins_count == 0 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // exactly (or nearly) matches the next item's size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        let match_gap = (post - nxt).abs();
        // Perfect lookahead match: strong reward.
        if match_gap < 1.0 {
            score -= 40.0;
        } else if post >= nxt {
            // Fractional tightness: closer match -> bigger reward.
            let tightness = 1.0 - (match_gap / bin_capacity as f64);
            score -= 20.0 * tightness * tightness;
        } else {
            // Next item cannot fit here: mild penalty for leaving a
            // residual that is "almost but not quite" usable.
            let near_miss = 1.0 - (match_gap / bin_capacity as f64);
            score += 8.0 * near_miss;
        }
    }

    // Prefer bins tighter than the mean residual (good fits),
    // penalize bins looser than the mean (wasteful placement).
    let mean = if mean_residual.is_finite() { mean_residual } else { 0.0 };
    score += 0.5 * (post_residual as f64 - mean);

    // Last-chance bonus: if this is the only bin that fits, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Discourage opening new bins when decent open bins exist.
    if bin_residual == bin_capacity && open_bins_count > 0 && bin_residual >= item_size {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 10.0 + 10.0 * progress;
    }

    // Small nudge toward filling nearly-full bins first.
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 5.0 * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * 30.0;

    // Reward exact/near-exact fits strongly.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        score -= 40.0;
    }

    // Lookahead: penalize if next item cannot fit in post_residual (dead space risk).
    if next_item_size > 0 {
        if next_item_size > post_residual {
            score += 12.0;
        } else {
            // Reward if the next item fits snugly after this placement.
            let next_leftover = post_residual - next_item_size;
            score -= (next_leftover as f64).min(20.0) * 0.8;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Penalize opening a new bin when many open bins could fit the item.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let pressure = (open_bins_count as f64) * (1.0 - progress);
        score += 25.0 + pressure * 3.0;
        // New bin is more attractive if mean residual across open bins is very low.
        if mean_residual < item_size as f64 * 0.5 {
            score -= 20.0;
        }
    } else {
        // Prefer bins whose residual is close to what is needed (avoid fragmenting large residuals).
        let waste = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
        score += waste * 15.0;
        // Prefer bins with below-average residual (fill emptier bins first keeps big holes flexible).
        if (bin_residual as f64) < mean_residual {
            score -= 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let fit_frac = post / cap;

    // Core: minimize post residual, with smooth polynomial amplification.
    let mut score = post * (1.0 + 1.5 * fit_frac * fit_frac);

    // Reward near-perfect fits (smooth quadratic bonus around zero residual).
    score -= 8.0 * (1.0 - fit_frac).max(0.0) * (1.0 - fit_frac).max(0.0) * item_size as f64 / cap;

    // Lookahead coupling: penalize if the next item cannot use the leftover space.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post < nxt {
            score += 12.0 * (1.0 - post / nxt) * (1.0 - progress);
        } else {
            // Reward bins whose leftover likely fits the next item.
            score -= 4.0 * (1.0 - post / cap) * (nxt / cap);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    } else if fitting_bins_count > 1 {
        // Mild penalty for spreading across many fitting bins; prefer tightest.
        score += 0.8 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate: only attractive when all open bins would waste space.
    if bin_residual == bin_capacity {
        let avg_waste = mean_residual.max(0.0);
        let pressure = 1.0 - (avg_waste / cap).min(1.0);
        score = post + 6.0 + 20.0 * pressure * (1.0 - progress) - 10.0 * progress;
        if fitting_bins_count <= 1 { score -= 20.0; }
    }

    // Late-stream consolidation: prefer reusing existing bins as stream ends.
    score += progress * 3.0 * (open_bins_count as f64).ln_1p();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class logic: classify post_residual by capacity fractions ---
    let cap_f = bin_capacity as f64;
    let post_f = post_residual as f64;
    let frac = post_f / cap_f; // residual as fraction of capacity

    // Integer-division thresholds: quarter classes of the bin
    let quarter = post_residual / 25; // 0..=4 harmonic class
    match quarter {
        0 => score -= 14.0,          // nearly full bin: excellent use
        1 => score -= 6.0,           // leaves 25-49 dead space
        2 => score += 2.0,           // half-ish residual: mediocre
        3 => score += 6.0,           // large residual kept
        _ => score += 9.0,           // bin barely touched
    }

    // Modulo arithmetic: residuals that are "nice" multiples pair well with
    // common item sizes (multiples of 10). Penalize odd leftovers.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 5.0;
    }
    if post_residual % 10 != 0 {
        score += 3.0;
    }

    // Exact fit reward
    if post_residual == 0 {
        score -= 40.0;
    }

    // --- Lookahead coupling: can next item exactly fill the new residual? ---
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0; // perfect chain
        } else if next_item_size <= post_residual {
            let gap = (post_residual - next_item_size) as f64;
            // harmonic penalty: gap scaled by how far it is from a decile
            let decile_gap = gap % 10.0;
            score += gap * 0.15 + decile_gap * 0.3;
        } else {
            // next item cannot use this residual: penalize large wasted residuals
            score += frac * 8.0;
        }
    } else {
        // last item: strongly prefer tight fits
        score -= post_f * 0.2;
    }

    // --- Last-chance bin: strongly favor using it to avoid opening a bin ---
    if fitting_bins_count == 1 {
        score -= 18.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; cheaper late in the stream
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = cap_f * 0.85 - progress * 20.0;
        // Opening a bin is attractive if no bin fits well (large post residual
        // elsewhere) or if the item is huge relative to typical residuals
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
        if item_size as f64 > mean_residual {
            score -= 10.0;
        }
        // lookahead: fresh bin keeps room for the next item
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= (bin_capacity - next_item_size) as f64 * 0.1;
        }
    }

    // Mild pressure to consolidate when many bins are open
    score += open_bins_count as f64 * 0.05 * frac;

    // Prefer bins whose residual is below the mean (filling the emptier ones)
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    } else {
        score += 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Dead space: residuals too small for any item (min size 1) are pure waste.
        if post_residual < 10 {
            score += 60.0;
        } else if post_residual < 20 {
            score += 25.0;
        } else if post_residual < 35 {
            score += 8.0;
        }

        // Reward residuals that can still hold the lookahead item.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0;
            // Even better: lookahead fits tightly.
            let tight = (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
            score -= 30.0 * (1.0 - tight);
        }

        // Reward leaving residual that is "large and round" (reusable).
        let frac = post_residual as f64 / bin_capacity as f64;
        score -= 20.0 * frac;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // Open-bin pressure: discourage scattering across many bins.
    score += 2.0 * open_bins_count as f64;

    // Prefer bins with below-mean residual (they are "more full" -> smaller residual).
    score += (bin_residual as f64 - mean_residual) * 0.5;

    // New-bin candidate handling: default neutral-ish, but allow opening a new bin
    // when all fits would create dead space.
    if bin_residual == bin_capacity {
        let dead_penalty_if_forced: f64 = if post_residual < 10 { 60.0 } else { 0.0 };
        // Base cost of a new bin, discounted early in the stream.
        let progress = step_index as f64 / total_items.max(1) as f64;
        let new_bin_cost = 40.0 + 30.0 * (1.0 - progress);
        score = new_bin_cost + dead_penalty_if_forced;
        // If the next item is large, a fresh bin is attractive.
        if next_item_size > 60 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits (low post_residual relative to capacity).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio) * (bin_capacity as f64) * 0.9;

    // Aggressive 2-step lookahead: if the next item fits exactly into post_residual,
    // heavily reward this placement (chain packing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Reward partial compatibility, scaled by how snugly next item fits.
            let snug = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= snug * 25.0;
        } else {
            // Next item cannot use the leftover; penalize wasted gap.
            let waste = (next_item_size - post_residual) as f64;
            score += waste * 0.35;
        }
    }

    // Compare against mean residual of open bins: prefer bins whose post_residual
    // lands below the mean (tightening the fleet), penalize inflating residuals.
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.5;
    } else {
        score -= (mean_residual - post_residual as f64) * 0.25;
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize opening a new bin when decent existing fits exist.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 + 20.0 * progress;
        // Allow new bins when fleet is small or item is huge relative to mean residual.
        if item_size as f64 > mean_residual + 10.0 {
            score -= 25.0;
        }
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Small penalty for tiny dead space that is hard to fill by typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) more aggressively.
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score += 40.0 * tightness * tightness;

    // Penalize leaving dead space that cannot fit typical future items.
    if post_residual > 0 && post_residual < 10 {
        score -= 5.0; // small leftover is fine only if near-zero
    }

    // Lookahead: if the next item fits exactly into post_residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (next_item_size as f64) / (post_residual as f64);
        } else {
            score += 4.0; // next item won't fit here; slight penalty
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Global state: many open bins -> prefer filling existing ones.
    let pressure = (open_bins_count as f64) / ((total_items as f64).max(1.0));
    score -= 10.0 * pressure * ((bin_residual as f64) / (bin_capacity as f64));

    // Mean residual coupling: penalize bins deviating from mean residual (balance).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.5 * dev;

    // Time horizon: later in stream, be greedier about tight fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 12.0 * progress * (1.0 - tightness);

    // New-bin candidate: make it unattractive unless nothing fits well.
    if bin_residual == bin_capacity {
        score += 20.0 + 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let x = pr / cap;
    // smooth polynomial coupling of post_residual with stream progress
    let t = progress;
    let poly = x * x * (1.0 + t) - 2.0 * x * x * x * (0.5 + t);
    score += 30.0 * poly * (1.0 - 0.5 * t);
    // penalize dead space relative to mean residual across open bins
    score += 0.35 * (pr - mean_residual).abs() * (0.5 + t);
    // reward tight fits more strongly as stream progresses
    score -= (1.0 - x) * (1.0 - x) * (item_size as f64 / cap) * (10.0 + 40.0 * t);
    // lookahead: reward leaving room for the next item, penalize blocking it
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let gap = pr - n;
        if gap >= 0.0 {
            score -= 12.0 * (gap / cap) * (0.3 + 0.7 * t);
        } else {
            score += 8.0 * (-gap / cap) * (1.0 - 0.5 * t);
        }
    }
    // last-chance bin: strong discount to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 {
        score -= 15.0 + 20.0 * t;
    }
    // mild preference for consolidating into fewer bins when many are open
    score += 0.4 * (open_bins_count as f64).ln().max(0.0) * x;
    // new-bin candidate: make it attractive only when no tight option exists
    if bin_residual == bin_capacity {
        score += 45.0 - 10.0 * t + 0.5 * mean_residual;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: which capacity fraction band it lives in.
    let frac = item_size as f64 / bin_capacity as f64;
    let class = (frac * 8.0).floor() as u32; // 0..7 harmonic class

    // Reward tight fits strongly, scaled by harmonic class:
    // large items (high class) should be packed tightly into open bins.
    let tight = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score -= (1.0 - tight).powi(3) * (12.0 + 4.0 * class as f64);

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Modulo logic on post_residual: residuals near multiples of common item
    // sizes (10..=25) are reusable; reward them.
    let mut reusable = 0u32;
    for m in 10..=25 {
        if post_residual % m == 0 && post_residual > 0 {
            reusable += 1;
        }
    }
    score -= 6.0 * reusable as f64;

    // Perfect fit: zero residual is excellent (bin closed cleanly).
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: if the next item fits the post residual exactly
    // or nearly, reward heavily; if next item cannot fit, slight penalty.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let gap = post_residual - next_item_size;
            if gap == 0 {
                score -= 30.0;
            } else if gap < 10 {
                score -= 12.0;
            } else {
                score -= 4.0;
            }
        } else {
            score += 5.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    // or this bin's residual would be badly fragmented anyway.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, amortized by stream progress.
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut nb = 18.0 - 6.0 * progress;
        // If many open bins have large mean residual, prefer filling them.
        nb += (mean_residual / bin_capacity as f64).max(0.0) * 10.0;
        // If very few bins fit the item, opening new is less attractive.
        if fitting_bins_count <= 2 {
            nb += 15.0;
        }
        // Harmonic class of item: big items (class >= 5) justify new bins more.
        if class >= 5 {
            nb -= 10.0;
        }
        score += nb;
    }

    // Mild pressure to prefer bins with less residual among equals.
    score += (bin_residual as f64 / bin_capacity as f64) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no future item (min size 1)
    // can usefully fill are pure waste. Penalize small unusable gaps hard.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 8.0;
    }
    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward tight fits relative to bin capacity (small waste fraction).
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += waste_frac * 20.0;

    // Open-bin pressure: discourage spreading across many bins early on;
    // encourage consolidating when many bins are already open.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.3 + 0.7 * progress);

    // Pull score toward mean residual: prefer bins whose residual is typical
    // (keeps a balanced portfolio of gaps for future items).
    score += (mean_residual - bin_residual as f64).abs() * 0.15;

    // Last-chance bin: strongly favor using it, else a new bin gets opened.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly into this bin's post_residual,
    // reward; if post_residual is smaller than next item, mild penalty.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
        } else if post_residual > 0 {
            score += 5.0;
        }
    }

    // New-bin candidate: opening a bin should only win when no open bin fits
    // well. The large post_residual already penalizes it; add a fixed cost.
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item size.
    if next_item_size > 0 {
        let match_gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += 0.8 * match_gap;
        if post_residual == next_item_size {
            score -= 25.0; // perfect two-item chain
        }
        // Penalize leaving residual that is too small for the next item (dead space risk)
        if post_residual < next_item_size {
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Reward tight fits relative to mean residual of open bins
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 10.0 * tightness;
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize opening new bins when good fits exist
    if bin_residual == bin_capacity {
        score += 20.0;
        if fitting_bins_count > 0 && post_residual as f64 > mean_residual {
            score += 15.0;
        }
        // Prefer new bin late in stream only if few alternatives
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 5.0 * (1.0 - progress);
    }

    // Mild penalty for spreading across too many bins
    score += 0.1 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits: the smaller the post_residual relative to capacity, the better.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - tightness) * 30.0;

    // Penalize dead space: residual too small for the smallest plausible future item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post-residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 + 0.2 * (next_item_size as f64);
        } else {
            // Next item won't fit here; penalize proportionally to wasted potential.
            score += 0.15 * (next_item_size as f64 - post_residual as f64).min(40.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Many open bins: encourage consolidation into existing bins.
    score += 0.6 * open_bins_count as f64;

    // Global residual state: if mean residual is high, prefer filling bins aggressively.
    if mean_residual > 0.0 {
        score -= 0.3 * mean_residual * (1.0 - tightness);
    }

    // Time horizon: late in the stream, avoid opening new bins; early, be more exploratory.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize opening a new bin, more so later in the stream
        // and when existing bins can fit the item.
        score += 45.0 + 40.0 * progress + (if fitting_bins_count > 0 { 30.0 } else { 0.0 });
        if next_item_size > 0 && item_size >= 70 {
            score -= 20.0; // large items pair poorly; a fresh bin may be fine
        }
    } else {
        score -= 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let t = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let fit_ratio = item_size as f64 / cap;
    let post_n = post_residual as f64 / cap;

    // Tight fit reward: strongly nonlinear in post_residual, damped by stream progress
    let tightness = (1.0 - post_n).powi(3);
    score -= 30.0 * tightness * (1.0 + 0.5 * t);

    // Reward bins whose residual is close to the item (best-fit coupling)
    let diff = (bin_residual as f64 - item_size as f64) / cap;
    score -= 20.0 * (1.0 - diff).powi(2) * fit_ratio;

    // Lookahead: favor bins whose post-residual matches next item
    if next_item_size > 0 && next_item_size as f64 <= post_n * cap {
        let match_q = 1.0 - ((post_residual as f64 - next_item_size as f64) / cap).abs();
        score -= 15.0 * match_q * match_q;
    } else if next_item_size > 0 {
        score += 8.0 * t; // dead space for next item penalized more later
    }

    // Last-chance bin: strong reward
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + t);
    }

    // Penalize fragmenting large-residual bins when many bins open
    score += post_n * post_n * (open_bins_count as f64).sqrt() * 2.0;

    // Discourage opening new bins early/mid stream unless residual is tiny
    if bin_residual == bin_capacity {
        score += 12.0 * (1.0 - t) + 10.0 * mean_residual / cap;
    }

    // Mean-residual alignment bonus
    let align = 1.0 - ((mean_residual - post_residual as f64) / cap).abs();
    score -= 6.0 * align;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits; small post_residual is good.
    score -= 0.35 * (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64;

    // Harmonic class of post_residual: classify dead space via integer division.
    let class = post_residual / 10; // decile of residual
    let class_penalty = match class {
        0 => -40.0,           // residual <= 9: nearly perfect packing
        1 => -25.0,           // 10..19: still usable for small items
        2 => -10.0,
        3 => 5.0,             // 30..39: dead zone begins
        4 => 10.0,
        5 => 18.0,
        6 => 26.0,
        7 => 34.0,
        8 => 44.0,
        _ => 55.0,            // 90+: wasteful placement
    };
    score += class_penalty;

    // Nonlinear: squared waste beyond a threshold.
    if post_residual > 30 {
        let waste = (post_residual - 30) as f64;
        score += 0.08 * waste * waste;
    }

    // Lookahead: if the next item fits exactly into post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot follow here; penalize proportionally to overshoot.
            let over = (next_item_size - post_residual) as f64;
            score += 0.15 * over;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 70.0;
    }

    // New-bin candidate handling: only attractive when no good fit exists
    // (e.g., item large relative to mean residual) or many bins are open.
    if bin_residual == bin_capacity {
        let mean_r = mean_residual;
        let scarcity = (mean_r - item_size as f64).max(0.0);
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let bonus = 15.0 + 30.0 * scarcity / bin_capacity as f64
            + 20.0 * (open_bins_count as f64 / 20.0).min(1.0)
            + 10.0 * progress;
        // New bin has post_residual = capacity - item_size; rebase its score.
        score = (bin_capacity - item_size) as f64 * 0.5 - bonus;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        }
        if fitting_bins_count == 1 {
            score += 90.0; // an existing bin is a last chance; prefer it
        }
    }

    // Mild preference to fill older bins first (reduce open-bin spread).
    score += 0.05 * open_bins_count as f64;
    score += 0.02 * (mean_residual - post_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable gaps harder than large residuals
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 8.0;
    }

    // Reward tight fits
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance bin: strong bonus to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Open bins pressure: penalize placements that leave large residual when many bins are open
    score += (open_bins_count as f64) * (post_residual as f64) * 0.05;

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && (post_residual as u32) < next_item_size && post_residual > 0 {
        score += 5.0;
    }

    // New-bin candidate: mild penalty so it only wins when open bins fit poorly
    if bin_residual == bin_capacity {
        score += 12.0 + (open_bins_count as f64) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
