pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits: post_residual dominates, amplify small residuals.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * tightness * tightness;

    // Lookahead: if next item can use the post-residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0 + 4.0 * (next_item_size as f64 / bin_capacity as f64);
    }
    // If next item is nearly a perfect follow-up fit, extra reward.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        if gap <= 4.0 {
            score -= 10.0;
        }
    }
    // Penalize if post-residual is dead space (too small for typical items).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last chance: if this is the only fitting bin, heavily favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    // (mean residual low relative to item) or late in the stream with many bins.
    if bin_residual == bin_capacity {
        let scarcity = (item_size as f64 - mean_residual).max(0.0);
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let base = 15.0
            + 0.6 * scarcity
            + 8.0 * (1.0 - progress)
            + (open_bins_count as f64).sqrt() * 1.5;
        // If no open bin fits well, opening a new bin is fine.
        if fitting_bins_count == 0 {
            score = base - 20.0;
        } else {
            score = base + (item_size as f64) * 0.3;
        }
    }

    // Mild penalty for spreading across many bins when mean residual is high.
    score += 0.05 * open_bins_count as f64 * (mean_residual / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let base = pr;

    // Smooth polynomial coupling of post_residual with stream progress:
    // later in the stream, dead space becomes more costly (tighten up).
    let progress_weight = 0.35 + 0.65 * progress * progress;
    let mut score = base * (1.0 + progress_weight * (pr / cap));

    // Reward near-perfect fits with a smooth cubic falloff.
    let tightness = 1.0 - (pr / cap).min(1.0);
    score -= 12.0 * tightness * tightness * tightness;

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let slack = 1.0 - ((pr - next_item_size as f64) / cap).min(1.0);
        score -= 6.0 * slack * slack;
    } else if next_item_size > 0 {
        // Penalize leaving residual that next item cannot use, scaled by dead space.
        score += 4.0 * (pr / cap);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Mildly discourage proliferating bins relative to mean residual.
    score += 0.05 * (open_bins_count as f64).ln() * (1.0 - (pr / cap));

    // Penalize a brand-new empty bin unless the item fits poorly everywhere.
    if bin_residual == bin_capacity {
        score += 8.0 + 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes of post_residual: exact-fit / near-fit / dead-space classes
    let cap = bin_capacity as f64;
    let pr = post_residual as u32;

    // Class 0: perfect fit -> strong reward
    if pr == 0 {
        score -= 200.0;
    }
    // Class 1: tiny remainder (<= 5) is near-dead space; still good
    else if pr <= 5 {
        score -= 150.0;
    }
    // Class 2: harmonic band 6..=10 — moderately usable by small items (min size 1..10)
    else if pr <= 10 {
        score -= 60.0;
    }
    // Class 3: 11..=20 awkward zone: too small for most, penalize mildly
    else if pr <= 20 {
        score += 15.0;
    }
    // Class 4: 21..=50 usable band
    else if pr <= 50 {
        score -= 10.0;
    }
    // else: large residual, fine — base score already reflects it

    // Integer-division harmonic classes on post_residual (mod 10 buckets)
    let harmonic = (pr / 10) % 4;
    match harmonic {
        0 => score -= 5.0,
        1 => score += 3.0,
        2 => score -= 2.0,
        _ => score += 1.0,
    }

    // Lookahead coupling: reward if next item fits the post residual exactly or nearly
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 120.0;
        } else if next_item_size <= pr {
            let slack = pr - next_item_size;
            score -= (20.0_f64).min(slack as f64 * 2.0);
        } else {
            // next item won't fit here; slight penalty proportional to overshoot
            score += ((next_item_size - pr) as f64).min(30.0) * 0.5;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current bin
    // would leave dead space and new bin keeps large flexibility.
    if bin_residual == bin_capacity {
        // Empty bin: base score is capacity (100). Adjust by stream progress and load.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 30.0 * (1.0 - progress);
        // If mean residual across open bins is high, opening new bin is wasteful
        score += (mean_residual / cap) * 40.0;
        // If item is large, a fresh bin is attractive
        score -= (item_size as f64 / cap) * 25.0;
        // If many bins already fit the item, opening new bin is bad
        if fitting_bins_count > 1 {
            score += 50.0;
        }
    } else {
        // Fitting into an existing bin: reward density
        score -= (item_size as f64 / cap) * 10.0;
        // Slight bonus for keeping number of open bins stable
        if open_bins_count > 0 {
            score -= 5.0;
        }
    }

    // Mean-residual alignment: prefer bins whose residual is near the mean (balanced packing)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead space: residuals too small for the smallest plausible item (1..100 range,
    // but small items exist) are pure waste. Penalize gaps below a usable threshold hard.
    let dead_threshold = 10u32;
    if post_residual > 0 && post_residual < dead_threshold {
        score += 60.0 * (dead_threshold - post_residual) as f64;
    }

    // Perfect fit: strongly reward.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Penalize gaps that cannot fit the known next item (lookahead-aware waste).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0 + 0.5 * (next_item_size - post_residual) as f64;
    }
    // Reward gaps that exactly or comfortably fit the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 * post_residual.min(next_item_size * 2) as f64 / next_item_size as f64;
    }

    // Tight fit reward: fraction of bin consumed by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 40.0 * fill;

    // Last-chance bin: strongly prefer using the only bin that fits,
    // otherwise we open a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading into yet
    // another bin unless the fit is excellent; encourage consolidation.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.8 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Prefer bins whose residual is close to the mean (balanced packing),
    // penalize deviating bins.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.3 * dev;

    // New-bin candidate handling: an empty bin has bin_residual == bin_capacity.
    // It should only win when no open bin offers a decent fit. Make the empty
    // bin mildly unattractive by default.
    if bin_residual == bin_capacity {
        score += 35.0 + 2.0 * open_bins_count as f64;
        // But if the item is large relative to capacity, opening a fresh bin
        // can be fine (avoids fragmenting existing bins).
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 20.0;
        }
    }

    // Penalize leaving residuals in the awkward 1..=15 band even more as the
    // stream progresses (less chance to fill them later).
    if post_residual >= 1 && post_residual <= 15 {
        score += 20.0 * (1.0 + progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fills strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: if the next item fits exactly in the post residual,
    // this placement sets up a perfect follow-up.
    if next_item_size > 0 {
        if post_residual as f64 == next_item_size as f64 {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // Next item fits: reward tight remaining slack after that.
            let post2 = post_residual as f64 - next_item_size as f64;
            score -= 50.0 * (1.0 - post2 / bin_capacity as f64);
        } else {
            // Next item won't fit here: penalize dead space that blocks it.
            score += 30.0;
        }
    }

    // Compare residual against mean residual across open bins.
    let res = post_residual as f64;
    if res < mean_residual * 0.5 {
        score += 20.0; // creating very small unusable residue
    } else if res > mean_residual {
        score += 5.0; // leaving more slack than average
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // New-bin candidate: only attractive when item is huge relative to capacity
    // or no good fits exist elsewhere.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        score += 60.0 - 80.0 * fill_ratio;
        // Early in the stream, opening bins is cheaper.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 40.0 * (1.0 - progress);
    }

    // Mild preference for tighter fits overall.
    score += (bin_residual - item_size) as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post * 1.0;

    // Reward tight fits strongly (small post_residual)
    let tightness = 1.0 - (post / cap);
    score -= 40.0 * tightness * tightness;

    // Penalize dead space that no future small item (min size 1) can use poorly:
    // medium dead zones (residual 20..60) are wasteful
    if post > 0.0 && post < 60.0 {
        let mid = 1.0 - ((post - 30.0).abs() / 30.0).min(1.0);
        score += 12.0 * mid;
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: if next item fits into post_residual, big reward
    if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        let combo = 1.0 - (post_residual - next_item_size as u32) as f64 / cap;
        score -= 30.0 * combo;
    } else if next_item_size > 0 {
        // next item won't fit here; slight penalty proportional to leftover
        score += 5.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Many open bins: encourage filling existing ones, discourage spreading
    let open_f = open_bins_count as f64;
    score += 0.5 * open_f * (post / cap);

    // Mean residual coupling: if this bin's residual is far below mean, prefer it (consolidation)
    let resid = bin_residual as f64;
    let dev = (resid - mean_residual) / cap;
    score -= 10.0 * dev;

    // Time horizon: early in stream, keep bins flexible (prefer larger post_residual);
    // late in stream, pack tightly regardless
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - t) * 8.0 * (post / cap);
    score -= t * 10.0 * tightness;

    // New-bin candidate: only attractive when no open bin fits well
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let poor_fit = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        // base penalty for opening a new bin
        score += 55.0;
        // if nothing fits anywhere, opening a bin is necessary: reduce penalty
        score -= 50.0 * poor_fit;
        // large items justify a fresh bin more than small ones
        score -= 0.15 * item_size as f64;
        // late in stream, avoid opening new bins
        score += 30.0 * t;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual

    // Base: quadratic waste penalty (favor small post_residual)
    let mut score = x * x * cap + 0.35 * pr;

    // Smooth coupling with stream progress: tighten fit preference as stream advances
    score *= 1.0 + 0.8 * progress * x;

    // Reward bins whose residual closely matches the item (smooth bump)
    let fit_quality = 1.0 - (bin_residual as f64 - item_size as f64) / cap;
    score -= 12.0 * fit_quality * fit_quality;

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0 + 10.0 * progress;
    }

    // Many fitting bins: prefer the tightest one mildly; penalize spreading
    if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).ln() * x;
    }

    // Penalize bins far below mean residual (keeps bins balanced)
    score += 0.05 * (mean_residual - pr).abs();

    // Lookahead: reward leaving space compatible with next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (pr - nx).abs();
        let compat = 1.0 - gap / cap;
        if compat > 0.0 {
            score -= 8.0 * compat * compat * (1.0 + progress);
        }
    }

    // New-bin candidate: penalize unless current open bins have large residuals
    if bin_residual == bin_capacity {
        let pressure = mean_residual / cap;
        let urgency = (1.0 - progress).max(0.0);
        score = cap - 6.0 * pressure * (1.0 - urgency) + 4.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class: reward residuals that are "friendly" to future items
    // (multiples of 10 or 20 are common landing zones)
    let pr = post_residual;
    if pr % 10 == 0 && pr > 0 {
        score -= 8.0;
    }
    if pr % 20 == 0 && pr > 0 {
        score -= 6.0;
    }

    // Penalize awkward dead space: small nonzero residuals
    if pr > 0 && pr < 10 {
        score += 25.0;
    }

    // Lookahead coupling: reward if next item fits in post_residual
    if next_item_size > 0 && next_item_size <= pr {
        score -= 15.0;
        // extra reward for tight lookahead fit
        if pr - next_item_size < 10 {
            score -= 10.0;
        }
    } else if next_item_size > 0 && next_item_size <= bin_residual {
        // next fits only in current residual but not post -> mild penalty for wasting
        score += 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless existing fits are poor
    if bin_residual == bin_capacity {
        score += 60.0;
        // early in stream, be generous with opening bins
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        if progress < 0.2 {
            score -= 20.0;
        }
        // if many bins are open with large mean residual, prefer packing into them
        if mean_residual > item_size as f64 * 1.5 {
            score += 20.0;
        }
    }

    // Prefer bins with tighter residual (best-fit flavor) scaled by item size
    score += (bin_residual as f64 - item_size as f64) * 0.3;

    // Fractional capacity coupling: reward residual in [1, item_size) proportion
    let frac = pr as f64 / bin_capacity as f64;
    if frac > 0.0 && frac < 0.1 {
        score += 15.0; // tiny unusable sliver
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // plausible future item are "dead". Penalize non-linearly.
    let dead_threshold = 10u32.min(bin_capacity);
    if post_residual > 0 && post_residual < dead_threshold {
        score += 40.0 * (dead_threshold - post_residual) as f64;
    }

    // Reward tight fits (small post_residual relative to bin).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Exact fit is gold.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: when many bins are open, discourage new bins.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure from open bins.
        score += 20.0 + 6.0 * open_bins_count as f64;
        // But if it's a perfect fit for the lookahead item, a fresh bin is fine.
        if next_item_size > 0 && next_item_size == bin_capacity {
            score -= 100.0;
        }
        // Late in stream, prefer consolidating into open bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 15.0 * progress;
    } else {
        // Favor bins whose residual is close to what the next item needs.
        if next_item_size > 0 {
            let gap = (post_residual as f64 - next_item_size as f64).abs();
            if post_residual as f64 >= next_item_size as f64 {
                score -= 15.0 / (1.0 + gap);
            }
        }
        // Prefer bins below mean residual (use up the emptiest space first).
        if (post_residual as f64) < mean_residual {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fit (small post_residual)
    score = post_residual as f64 * 1.0;

    // Aggressive 2-step lookahead: reward if next item exactly fills post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0; // perfect chaining
        } else if next_item_size <= post_residual {
            // reward proportionally to how well next item uses the leftover
            let fill_ratio = next_item_size as f64 / post_residual as f64;
            score -= 20.0 * fill_ratio;
        } else {
            // next item can't use leftover; penalize dead space relative to gap
            let gap = (next_item_size - post_residual) as f64;
            score += 0.3 * gap;
        }
    }

    // Compare post_residual against mean residual across open bins
    // leaving more than average is wasteful; leaving less is good compaction
    let dev = post_residual as f64 - mean_residual;
    score += 0.5 * dev;

    // Last-chance bin: strongly reward using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Penalize large open-bin count growth pressure mildly
    score += open_bins_count as f64 * 0.05;

    // Penalize leaving residuals too small to be useful for typical items
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // dead space
    }

    // Empty-bin candidate handling: only prefer a new bin if current bin fit is terrible
    if bin_residual == bin_capacity {
        // neutral baseline; slightly above a good fit, below a bad fit
        score = bin_capacity as f64 * 0.6;
        if next_item_size > 0 {
            score -= 0.1 * next_item_size as f64;
        }
    }

    // Slight time adaptation: later in stream, favor compaction more strongly
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score *= 1.0 + 0.1 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize bins whose post-residual is small and hard to reuse.
    let tight_fit_bonus = if post_residual < item_size {
        // dead space smaller than any future item of similar size -> good
        -18.0 * (1.0 - post_residual as f64 / (item_size.max(1) as f64))
    } else {
        0.0
    };
    score += tight_fit_bonus;

    // Penalize post-residuals that are awkward (small but nonzero, hard to fill).
    if post_residual > 0 && post_residual < 12 {
        score += 10.0 - post_residual as f64 * 0.5;
    }

    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }
    // Many fitting bins: mild penalty to encourage diversity of choice among good fits.
    if fitting_bins_count > 2 {
        score += (fitting_bins_count as f64 - 2.0).min(4.0) * 1.5;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, reward strongly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 22.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size < 10 {
            score -= 12.0;
        } else if post_residual < next_item_size && post_residual >= 10 {
            // leftover too small for next item: mild penalty scaled by leftover size
            score += post_residual as f64 * 0.15;
        }
        // If next item is large, prefer bins where this item leaves a complementary gap.
        if next_item_size >= 50 && post_residual >= next_item_size {
            score -= 8.0;
        }
    }

    // Global state: when many bins are open and mean residual is high, prefer filling
    // the emptiest-feeling bins (below-mean residual) to consolidate space.
    if open_bins_count > 0 {
        let rel = bin_residual as f64 - mean_residual;
        score += rel * 0.08;
        // More open bins -> stronger consolidation pressure.
        score += rel * (open_bins_count as f64).ln().max(1.0) * 0.02;
    }

    // Time horizon: early in stream, be more willing to open new bins (penalize
    // cramming less); late in stream, squeeze existing bins harder.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 2.0;      // early: slightly favor new bins via higher existing-bin scores
    score -= progress * 4.0;              // late: favor existing bins

    // New-bin candidate calibration: empty bin should lose unless fit is poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, reduced when item is large or stream is early.
        let size_factor = item_size as f64 / bin_capacity as f64;
        score += 14.0 - 10.0 * size_factor - 6.0 * (1.0 - progress);
        // If no open bin fits well (this is the only candidate), new bin is fine.
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;

    // Tight-fit reward: quadratic in wasted space, stronger late in stream
    let waste_frac = post_residual as f64 / cap;
    score += waste_frac * waste_frac * cap * (0.4 + 0.6 * progress);

    // Reward using bins that are already well-filled
    let fill = (bin_residual as f64) / cap;
    score -= fill * fill * 18.0;

    // Lookahead coupling: bonus if next item fits the post-residual
    if next_item_size > 0 && (post_residual as u64) >= (next_item_size as u64) {
        score -= 10.0 + 6.0 * progress;
    }
    // Penalize if next item nearly fits (blocking risk)
    if next_item_size > 0 && post_residual > 0 && (post_residual as u64) < (next_item_size as u64) {
        let gap = (next_item_size as f64 - post_residual as f64) / cap;
        score += gap * 14.0;
    }

    // Last-chance bin: strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Prefer bins with residual close to mean (balance load)
    score += ((bin_residual as f64 - mean_residual) / cap).abs() * 4.0;

    // New-bin candidate: penalize opening a new bin, more so early/mid stream
    if bin_residual == bin_capacity {
        score += 30.0 + 20.0 * (1.0 - progress);
        // but allow fresh bin if no open bin fits well
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    // Slight preference for fewer open bins
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Harmonic class of the post residual: waste buckets in units of 10.
    // Residuals in [0..10) are nearly dead space -> heavy penalty beyond raw value.
    let dead = post_residual % 10;
    score += dead as f64 * 1.5;

    // Penalize mid-range residuals that are hard to fill later (harmonic classes).
    let cls = (post_residual / 10) as f64;
    if post_residual > 0 {
        score += 8.0 / (1.0 + cls);
    }

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
        if post_residual == next_item_size {
            score -= 20.0;
        }
        // Next item leaves a small remainder class -> still good.
        let nxt_post = post_residual - next_item_size;
        if nxt_post % 10 == 0 && nxt_post > 0 {
            score -= 5.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here; slightly penalize leaving awkward residuals.
        score += 2.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: a fresh bin should only win when fits are poor.
    if bin_residual == bin_capacity {
        // Baseline for opening a new bin: keep it comparable to a mediocre fit.
        score = cap * 0.55 + (open_bins_count as f64) * 0.5;
        // Late in the stream, consolidate more (fewer new bins).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 20.0;
        // If only this new bin fits, opening is unavoidable.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    } else {
        // Prefer bins whose residual is close to the item (tight packing).
        let tightness = 1.0 - (bin_residual as f64 - item_size as f64) / cap;
        score -= tightness * 10.0;
        // Slight preference for bins with below-mean residual (fill emptier-first is wrong;
        // fill tighter bins first to keep large residuals flexible).
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64);
    }
    // Perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward tight fits generally (post_residual small relative to item size).
    score -= 0.5 * (item_size as f64) / (1.0 + post_residual as f64);

    // Last chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad.
    if bin_residual == bin_capacity {
        score += 25.0;
        if fitting_bins_count >= 1 {
            score += 20.0 * (fitting_bins_count as f64);
        }
        // Late in the stream, prefer closing out open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 20.0 * progress;
    }

    // Open-bin pressure: many open bins -> prefer filling existing ones.
    score += 1.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Lookahead: favor residuals that can still host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 {
            score += 6.0;
        }
    }

    // Mean residual coupling: bins far below mean residual are better fill targets.
    score -= 0.3 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
