        }
        // Late in the stream, avoid spawning bins for marginal gains.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        base += 30.0 * progress;
        score += base;
    }

    // Mild penalty when many bins are open: encourage consolidation.
    score += 0.15 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let mut score = post * 1.0;

    // Strongly reward near-perfect fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    }

    // Dead-space penalty: small residuals that few future items can use.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post) * 4.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item (k=2).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual >= next_item_size {
            score -= 30.0 + nxt * 0.3;
            // bonus if next item then leaves a small residual too
            let pr2 = post_residual as u32 - next_item_size;
            if pr2 <= 10 {
                score -= 15.0;
            }
        } else {
            // residual too small for the next item -> less attractive
            score += 10.0;
        }
        // If next item is large, prefer bins with lots of room for it
        if nxt > 50.0 && post < nxt {
            score += (nxt - post) * 0.2;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        // Opening a new bin is penalized when any open bin fits,
        // but attractive when the item is large and fits poorly elsewhere.
        let mut penalty = 120.0;
        if fitting_bins_count == 0 {
            penalty = -500.0; // must open a bin
        } else if item_size > 70 {
            penalty = 20.0; // large items start fresh bins more willingly
        } else if item_size > 50 {
            penalty = 60.0;
        }
        // Late in the stream, avoid waste: opening new bins is fine since
        // leftover capacity is unlikely to be used anyway.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        penalty -= progress * 60.0;
        // Few open bins with big mean residual -> reuse is cheap, discourage new bin
        if open_bins_count > 0 && mean_residual > item as f64 {
            penalty += 40.0;
        }
        score += penalty;
    }

    // Prefer bins whose residual is close to the item (tight packing) globally.
    let tightness = (bin_residual as f64 - item).abs();
    score += tightness * 0.15;

    // Mild pressure to consolidate: bins below mean residual are more filled already.
    score += (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Smooth non-linear coupling of post_residual with stream progress.
    let norm_pr = pr / cap;
    let prog = progress.clamp(0.0, 1.0);
    // Early stream: prefer tight fits (low post_residual) strongly; late stream: relax.
    let tightness = 1.0 + 2.0 * prog * prog;
    score += tightness * norm_pr * norm_pr * cap * 0.35;

    // Cubic interaction: penalize mid-range residual waste more as stream progresses.
    let mid = norm_pr * (1.0 - norm_pr); // peaks at 0.5 residual
    score -= 6.0 * mid * (1.0 - prog);

    // Reward near-perfect fits smoothly.
    let fit_quality = 1.0 - norm_pr;
    score -= 8.0 * fit_quality * fit_quality * fit_quality;

    // Last-chance bonus (only one fitting bin): reward using it.
    if fitting_bins_count == 1 {
        score -= 4.0 + 6.0 * fit_quality;
    }

    // Lookahead: penalize leaving residual that barely fails to fit next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            // next fits: mild reward proportional to how well it will use leftover
            let use_ratio = nx / pr.max(1.0);
            score -= 2.0 * use_ratio * (1.0 - prog);
        } else {
            // next doesn't fit: penalize dead space gap smoothly
            let gap = (nx - pr) / cap;
            score += 5.0 * gap * gap * cap / cap.max(1.0) * 10.0;
        }
    }

    // New-bin candidate: only attractive when open bins are crowded.
    if bin_residual == bin_capacity {
        let crowding = (mean_residual / cap).clamp(0.0, 1.0);
        score = cap * (0.35 + 0.6 * crowding) + 8.0 * (1.0 - prog);
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    }

    // Mild penalty for proliferating open bins late in the stream.
    score += 0.15 * open_bins_count as f64 * (0.5 + 0.5 * prog);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls into
    // "small unusable" classes are rewarded (we filled them well).
    let half = bin_capacity / 2;
    let quarter = bin_capacity / 4;

    // Class-based reward for driving residual into low harmonic classes.
    if post_residual == 0 {
        score -= 60.0; // perfect fit
    } else if post_residual < 10 {
        score -= 40.0;
    } else if post_residual <= quarter {
        score -= 20.0;
    } else if post_residual <= half {
        score -= 5.0;
    } else {
        score += 10.0; // large leftover: poor packing
    }

    // Modulo coupling: residual that is a multiple of common item-size
    // classes (10/20/25) is more likely reusable by future items.
    let reusable = |r: u32| r % 10 == 0 || r % 20 == 0 || r % 25 == 0;
    if post_residual > 0 && reusable(post_residual) {
        score -= 12.0;
    }
    if post_residual > 0 && !reusable(post_residual) && post_residual < 30 {
        score += 15.0; // awkward dead space
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // strongly favor this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 50.0;
        } else if post_residual > next_item_size {
            score -= 8.0;
        } else {
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Last-chance bin: only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate penalty: opening a new bin is wasteful unless
    // every existing fit would leave bad residue.
    if bin_residual == bin_capacity {
        // Base cost of a new bin, softened when many bins are open
        // or mean residual is high (existing bins are fragmented).
        score = cap - score * 0.5;
        if mean_residual > half as f64 {
            score -= 10.0;
        }
        if open_bins_count == 0 {
            score -= 200.0; // must open
        }
    }

    // Mild normalization of raw residual term.
    score += post_residual as f64 * 0.3;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold the
    // smallest plausible future item are "dead". Penalize them heavily.
    let min_item = 1.0f64;
    if (post_residual as f64) < min_item {
        score += 1000.0; // exact fill, perfect
    } else if post_residual < 10 {
        // gap too small for most items -> dead space
        score += 40.0 + (10 - post_residual) as f64 * 5.0;
    } else if post_residual <= 25 {
        // moderately awkward gap
        score += 12.0;
    }

    // Reward tight fits (small post_residual relative to bin capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Lookahead coupling: if the next item fits the post-residual exactly or
    // nearly, reward this placement strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size < post_residual && post_residual - next_item_size < 10 {
            score -= 25.0;
        } else if next_item_size > post_residual {
            // next item won't fit here anyway; slightly penalize leaving a
            // gap that neither helps nor hurts
            score += 5.0;
        }
    }

    // Open-bin pressure: discourage spreading across many bins when a good
    // fit exists, but allow opening new bins when the current fit is bad.
    score += (open_bins_count as f64) * 2.0;

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Mean residual coupling: prefer bins whose residual is below the mean
    // (i.e., fuller bins), keeping emptier bins flexible.
    score += ((bin_residual as f64) - mean_residual) * 0.3;

    // New-bin candidate handling: an empty bin has a large residual; make it
    // attractive only when no decent fit exists among open bins.
    if bin_residual == bin_capacity {
        // baseline competitiveness: slightly worse than a perfect fit,
        // better than creating large dead space.
        score = 55.0 + (open_bins_count as f64) * 1.5;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // pairing large items in fresh bins
        }
    }

    // Mild stream-progression term: later in the stream, consolidate more
    // aggressively (less room to recover from fragmentation).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 8.0 * ((post_residual as f64) / (bin_capacity as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact fit (post_residual near zero)
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 35.0;
    }

    // Aggressive 2-step lookahead: reward if next item fits the post residual
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if (post_residual as f64) >= n {
            // next item fits: reward proportionally to how well it matches
            let slack_after_next = post_residual as f64 - n;
            score -= 25.0 - 0.3 * slack_after_next;
        } else {
            // next item does NOT fit: penalize wasted space the next item could have used
            let waste = n - post_residual as f64;
            if waste < n {
                score += 0.4 * waste;
            }
        }
    }

    // Compare post_residual against mean residual across open bins:
    // leaving a residual far below the mean means this bin becomes dead space
    let pr = post_residual as f64;
    if pr < mean_residual * 0.5 && pr > 0.0 {
        score += 8.0 * (mean_residual - pr) / mean_residual.max(1.0);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    } else if fitting_bins_count > 3 {
        // many alternatives: prefer bins where fit is tightest (post_residual already does this)
        score += 2.0;
    }

    // Penalize opening a brand-new bin unless current bins would leave very poor fits
    if bin_residual == bin_capacity {
        // new bin: score is its full residual; add a fixed opening cost
        score += 30.0;
        // but if the item is large relative to capacity, opening a fresh bin is fine
        score -= 0.2 * item_size as f64;
        // if next item is large and would pair well, slight discount
        if next_item_size > 0 && (bin_capacity as f64 - item_size as f64 - next_item_size as f64).abs() < 10.0 {
            score -= 15.0;
        }
    }

    // Late in the stream: consolidation matters more, tighten scoring
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: prefer bins whose post-residual is small.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * tightness * tightness;

    // Penalize dead space that cannot fit the smallest plausible item (<=100, but small items exist).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // useless sliver
    }

    // Lookahead: if the next item fits exactly into the post-residual, strongly favor this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            score -= 8.0 * (post_residual as f64 - next_item_size as f64).min(20.0) / 20.0;
        } else {
            // next item cannot follow here; slight penalty proportional to gap
            score += 4.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate logic: an empty bin should only win when existing fits are poor.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score = bin_capacity as f64 * 1.15;
        // cheaper to open a new bin early in the stream (more future flexibility)
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 25.0 * (1.0 - progress);
        // cheaper when open bins are already crowded on average
        score -= (mean_residual / bin_capacity as f64).max(0.0) * 20.0;
        // if many bins can fit, opening a new one is wasteful
        score += 6.0 * (fitting_bins_count as f64).min(5.0);
        // big items pair better in a fresh bin
        if item_size >= bin_capacity / 2 {
            score -= 10.0;
        }
        // if next item is large and won't fit anywhere after this placement, fresh bin helps
        if next_item_size > 0 && next_item_size > post_residual.min(bin_residual.saturating_sub(item_size)) {
            score -= 5.0;
        }
    }

    // Mild preference to fill already-open bins as the stream progresses (reduce bin count churn).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (post_residual as f64 / bin_capacity as f64) * 10.0 * progress;

    // Tie-break toward bins close to the mean residual (keeps a balanced portfolio of gaps).
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    // Very late in the stream, aggressively consolidate into fewest bins.
    if progress > 0.9 && bin_residual != bin_capacity {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on: tolerate moderate residuals; later: punish residual waste quadratically.
    let prog_poly = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score += 12.0 * prog_poly * pr_norm * pr_norm * cap * 0.01;

    // Reward tight fits (low post residual), smoothly scaled by item fraction.
    let tightness = 1.0 - pr_norm;
    score -= 8.0 * tightness * tightness * tightness;

    // Lookahead coupling: bonus if post residual can host the next item smoothly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let compat = 1.0 - (pr - nxt).abs() / cap;
        let compat_pos = if compat > 0.0 { compat } else { 0.0 };
        score -= 6.0 * compat_pos * compat_pos * (1.0 + prog_poly);
    } else {
        // Last item: strongly favor filling bins completely.
        score -= 10.0 * tightness;
    }

    // Last-chance bin: strong reward to avoid opening a new bin needlessly.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0 * (1.0 + prog_poly);
    }

    // Penalize bins whose residual deviates negatively from mean residual
    // (keeps a balanced pool of residuals), smooth quadratic coupling.
    let dev = pr - mean_residual;
    score += 0.05 * dev * dev / (1.0 + open_bins_count as f64);

    // Mild penalty for many open bins relative to progress (bin consolidation).
    score += 0.5 * open_bins_count as f64 * (1.0 - prog_poly) * 0.1;

    // Slight preference for larger fill fraction overall.
    score -= 2.0 * (item_size as f64 / cap) * (1.0 + prog_poly);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: integer division into capacity bands.
    let post = post_residual;
    let class = post / 25; // 0: tiny (0-24), 1: small (25-49), 2: medium (50-74), 3: large (75-99)
    match class {
        0 => {
            // Tiny dead space is excellent (near-perfect fit): strong reward.
            score -= 12.0 + (25 - post) as f64 * 0.6;
        }
        1 => {
            // Small residual: still good, mild reward scaled by closeness to 25.
            score -= 4.0 + (post - 25) as f64 * 0.15;
        }
        2 => {
            // Medium residual: wasted half-bin, penalize.
            score += 3.0 + (post - 50) as f64 * 0.1;
        }
        _ => {
            // Large residual: barely better than a fresh bin, heavy penalty.
            score += 8.0 + (post - 75) as f64 * 0.2;
        }
    }

    // Modulo arithmetic on post_residual: residuals near multiples of common
    // item sizes (10, 20, 25, 50) are reusable; reward small mod values.
    let mut reuse = 0.0;
    for &m in &[10u32, 20, 25, 40, 50] {
        let r = post % m;
        let d = r.min(m - r);
        reuse += (m as f64 - d as f64) / m as f64;
    }
    score -= reuse * 1.5;

    // Exact fit: maximal reward.
    if post == 0 {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly in post_residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 20.0;
        } else if next_item_size <= post {
            let leftover = post - next_item_size;
            // Harmonic class of the double-placement leftover.
            if leftover / 25 == 0 {
                score -= 8.0 - leftover as f64 * 0.2;
            } else {
                score += leftover as f64 * 0.05;
            }
        } else {
            // Next item cannot follow here; slight penalty unless this bin
            // would otherwise be stranded.
            score += 2.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 6.0;
    }

    // New-bin candidate handling: make fresh bins moderately attractive only
    // when open bins are congested or the fit here is poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Fresh bin baseline: neutral-ish score; reward grows if many bins
        // are open (fragmentation) or mean residual is small.
        score = cap * 0.5 - open_bins_count as f64 * 0.3 - mean_residual * 0.2 + progress * 2.0;
        if post == 0 { score -= 5.0; }
    }

    // Tie-breaker: prefer tighter bins (smaller residual) via mild scaling.
    score += (bin_residual as f64) * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in the "unusable gap" band
    // (1..=9, too small for any item) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    }
    // Perfect fit is maximally rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward bins whose residual is close to the item (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 30.0 * tightness;

    // Lookahead: reward if the post residual exactly accommodates next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual >= next_item_size {
            score -= 10.0 * (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
        } else if post_residual > 0 {
            // residual becomes dead space relative to lookahead
            score += 15.0 * (next_item_size as f64 - post_residual as f64) / 10.0;
        }
    }

    // Open-bin pressure: when many bins are open, discourage spreading;
    // prefer filling existing bins over opening new ones.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 0.8 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: only attractive when current bin fits are poor
    // (e.g., large mean residual wasted elsewhere) or this is a big item
    // that would leave a dead gap in an open bin.
    if bin_residual == bin_capacity {
        let poor_fit_penalty = if post_residual > 0 && post_residual < 10 { 60.0 * (10.0 - post_residual as f64) } else { 0.0 };
        score = 25.0 + 2.0 * open_bins_count as f64 + 0.3 * mean_residual + poor_fit_penalty;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0;
        }
        // Late in the stream, opening new bins is less desirable.
        score += 30.0 * progress;
    }

    // Mild preference for bins below mean residual (balance conservation).
    score += 0.2 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Penalize dead space that is too small to be useful later.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward post_residual that exactly matches next item (perfect pair).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 30.0 / (1.0 + gap);
        // Penalize leaving residual that is awkwardly close but not equal.
        if gap > 0.0 && post_residual as f64 >= next_item_size as f64 {
            score += 5.0 * (gap / 100.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Compare against mean residual: bins with residual far from mean are either
    // nearly full (good to fill) or unusually empty (keep flexible).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score -= 3.0 * dev / (1.0 + mean_residual);

    // New-bin candidate: only attractive when no good fit exists among open bins.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 50.0;
        } else if item_size as f64 > mean_residual * 0.9 {
            score -= 15.0;
        } else {
            score += 20.0 + 10.0 * (open_bins_count as f64).sqrt();
        }
    }

    // Late in the stream, consolidate aggressively into fewer bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Lookahead: reward bins whose residual can host the next item snugly.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 - slack * 0.08; // snug follow-up pairing bonus
        } else {
            // Next item won't fit here; mild penalty proportional to overshoot.
            let over = (next_item_size - post_residual) as f64;
            score += over * 0.05;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // Penalize leaving dead space that is too small for typical items (1..100 range).
    let dead = post_residual as f64;
    if dead > 0.0 && dead < 12.0 {
        score += (12.0 - dead) * 0.6; // tiny unusable slivers are wasted capacity
    }

    // New-bin candidate: penalize unless it yields a very tight fit.
    if bin_residual == bin_capacity {
        if post_residual <= 8 {
            score -= 6.0; // near-perfect fresh fit
        } else {
            score += 15.0 + (post_residual as f64 - 8.0) * 0.15;
        }
    }

    // Global state: when many bins are open with large mean residual,
    // slightly discourage opening more bins and encourage consolidation.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (open_bins_count as f64).ln().max(0.0) * 0.4;
    score -= mean_residual * 0.03 * (1.0 - progress * 0.5);

    // Tightness coupling: reward filling a bin that was already partially used.
    if bin_residual != bin_capacity {
        let fill = item_size as f64 / bin_residual as f64;
        score -= fill * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;

    // Non-linear waste penalty: dead space becomes costlier as stream progresses
    let waste_curve = (pr / cap).powi(2) * (1.0 + 3.0 * progress * progress);
    score += 4.0 * waste_curve;

    // Reward tight fits: small post_residual relative to item size
    let tightness = 1.0 - (pr / cap);
    score -= 2.0 * tightness.powi(3) * (item_size as f64 / cap);

    // Lookahead coupling: reward residual that matches next item
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        let diff = (pr - next_item_size as f64) / cap;
        score -= 3.0 * (-diff * 10.0).exp() * (0.5 + 0.5 * progress);
    }

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 6.0;
    }

    // Penalize spreading across too many open bins relative to mean residual
    if open_bins_count > 0 {
        let spread = (mean_residual - pr) / cap;
        score += 1.5 * spread.abs();
    }

    // New-bin candidate: penalize opening a new bin unless it enables a very tight future fit
    if bin_residual == bin_capacity {
        score += 8.0 + 5.0 * progress;
        if next_item_size > 0 {
            let gap = (cap - next_item_size as f64) / cap;
            score -= 6.0 * gap.powi(2);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues mod common item-size bands (1..100 unknown dist)
    let r = post_residual;
    // Perfect-fit reward: post_residual in low-dead-space classes
    if r == 0 {
        score -= 1000.0;
    } else {
        // Dead-space penalty grows superlinearly for small unusable residuals
        let frac = r as f64 / bin_capacity as f64;
        score += (0.05 - frac).max(0.0) * 40.0;
        // Harmonic classes: residuals that are sums of typical small sizes (5,10,15,...)
        // are more likely refillable; residuals like 1..4 are nearly dead.
        if r < 5 {
            score += 60.0 * (6 - r) as f64;
        } else if r % 5 == 0 || r % 10 == 0 {
            score -= 15.0;
        }
        // Mid-range residuals divisible by small harmonics are reusable
        if r % 2 == 0 { score -= 3.0; }
        if r % 3 == 0 { score -= 2.0; }
    }

    // Lookahead coupling: if next item fits post_residual, big reward
    if next_item_size > 0 {
        if next_item_size <= r {
            score -= 25.0 + 0.5 * next_item_size as f64;
            // exact harmonic pairing: post_residual == next_item_size
            if next_item_size == r {
                score -= 50.0;
            }
        } else {
            score += 10.0;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible
    if bin_residual == bin_capacity {
        // base cost of a fresh bin
        score = 55.0 + 0.3 * (item_size as f64);
        // early in stream, cheap to open bins; late, expensive
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 40.0 * progress;
        // many open bins -> discourage one more
        score += 3.0 * open_bins_count as f64;
        // if next item is large, a fresh bin is valuable
        if next_item_size > 50 {
            score -= 20.0;
        }
    }

    // Mean-residual coupling: prefer bins deviating favorably from mean
    let dev = bin_residual as f64 - mean_residual;
    score += 0.05 * dev;

    // Mild tightness preference: less wasted space overall
    score += 0.1 * (post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=12) are heavily penalized.
    if post_residual >= 1 && post_residual <= 12 {
        score += (13 - post_residual as i32) as f64 * 25.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Reward residuals that can still host typical future items (>= next item or >= 10).
    if post_residual >= 10 {
        score -= 10.0;
    }
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // Penalize if residual cannot fit the lookahead item (dead space for k=2).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 18.0;
    }

    // Tightness reward: fraction of bin used by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= fill * 20.0;

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 1.5;

    // Mean-residual coupling: placing into a bin whose residual is far above mean wastes capacity.
    let dev = bin_residual as f64 - mean_residual;
    if dev > 0.0 {
        score += dev * 0.3;
    } else {
        score += dev * 0.1;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when no good fit exists elsewhere.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual > 0 && post_residual <= 12;
        if poor_fit {
            score -= 30.0; // opening fresh bin beats creating dead space
        } else {
            score += 25.0 + open_bins_count as f64 * -0.5; // prefer reusing open bins
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward: minimize waste directly
    if post_residual == 0 {
        score -= 200.0;
    }

    // Lookahead coupling: reward when next item exactly fills the new residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 150.0;
        } else if next_item_size <= post_residual {
            // Next item fits: penalize proportionally to leftover dead space after both
            let double_left = (post_residual - next_item_size) as f64;
            score += double_left * 0.6;
            score -= 20.0; // small bonus for keeping next item in same bin
        } else {
            // Next item won't fit here; penalize small residuals (dead space)
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.4;
        }
    }

    // Relative to mean residual: bins tighter than average are better targets
    let res = post_residual as f64;
    score += (res - mean_residual).max(0.0) * 0.5;
    score -= (mean_residual - res).max(0.0) * 0.2;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: penalize moderately so only poor fits trigger opening
    if bin_residual == bin_capacity {
        score += 90.0 + 10.0 * open_bins_count as f64;
        // If next item is large and this bin is fresh, opening may be attractive
        if next_item_size >= 50 {
            score -= 30.0;
        }
    }

    // Late in stream: consolidate, avoid opening bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more aggressively.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * fit_ratio * fit_ratio;

    // Penalize creating dead space that cannot fit even the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score -= 25.0; // near-perfect fill
    }

    // Lookahead: reward if next item fits into post_residual (good chaining).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
            // extra bonus for near-exact chaining
            let chain_gap = post_residual - next_item_size;
            if chain_gap < 10 {
                score -= 8.0;
            }
        } else {
            // next item won't fit here; slight penalty proportional to wasted chain potential
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when the fit into
    // this (empty) bin is naturally good and open bins are crowded/poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 45.0;
        // Cheaper to open new bins early in the stream (more future items to use it).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0 * progress;
        // If many open bins already exist and mean residual is small (poor fits),
        // opening a fresh bin becomes more attractive.
        score -= 0.3 * open_bins_count as f64;
        if mean_residual < item_size as f64 {
            score -= 15.0;
        }
        // If no open bin besides this candidate fits, opening is necessary.
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    // Global pressure: when many bins are open, discourage scattering into
    // low-fill bins; encourage consolidating into bins with larger residuals used well.
    let residual_gap = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * residual_gap;

    // Mild time-dependent tightening: later in stream, waste is costlier.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 10.0 * progress * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer small post-residual, with smooth polynomial coupling to progress.
    let mut score = post * (1.0 + 0.8 * progress * (1.0 - progress) * 4.0);

    // Non-linear penalty for awkward residuals (dead space unlikely to be reused).
    let norm_post = post / cap;
    let awkward = norm_post * (1.0 - norm_post);
    score += 12.0 * awkward * (0.5 + 0.5 * progress);

    // Reward bins that also fit the lookahead item (smooth interaction).
    if next_item_size > 0 && (post_residual as u64) >= next_item_size as u64 {
        let fit_margin = (post_residual - next_item_size) as f64 / cap;
        score -= 10.0 * (1.0 - fit_margin) * (1.0 - fit_margin);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (1.0 + progress);
    }

    // New-bin candidate: penalize opening a bin unless post-residual is large
    // enough to be attractive for future items (smooth threshold-free term).
    if bin_residual == bin_capacity {
        let usefulness = (post / cap).powi(2);
        score = cap - 20.0 * usefulness + 8.0 * open_bins_count as f64 * (0.3 + 0.7 * progress);
        // If mean residual of open bins is already high, opening new bin is cheaper.
        score -= 5.0 * (mean_residual / cap);
    }

    // Mild penalty for bins far from mean residual (fragmentation smoothing).
    let dev = (bin_residual as f64 - mean_residual).abs() / cap;
    score += 4.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: which capacity-fraction band does it occupy?
    let item_class = item_size / (bin_capacity / 4); // 0..3 (tiny, small, medium, large)
    let next_class = if next_item_size > 0 { next_item_size / (bin_capacity / 4) } else { 0 };

    // Reward near-perfect fits (small post_residual gets a strong discount).
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    } else if post_residual <= 20 {
        score -= 40.0;
    }

    // Penalize leaving "dead space": residuals that few future item classes can use.
    // Harmonic classes: a residual is useful if it can host a class-0 or class-1 item.
    let dead_threshold = (bin_capacity / 10) * 1; // 10 units
    if post_residual > 0 && post_residual < dead_threshold {
        score += 60.0; // unusable sliver
    }

    // Coupling with lookahead: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap <= 5 {
            score -= 90.0;
        } else if gap <= 15 {
            score -= 45.0;
        } else {
            score -= 10.0;
        }
    } else if next_item_size > 0 {
        // Next item won't fit here; slight penalty unless post_residual is tiny anyway.
        score += 15.0;
    }

    // Class harmony: pairing a large item with a large leftover is wasteful.
    if item_class >= 2 && post_residual > bin_capacity / 4 {
        score += 20.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits to avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling: prefer reusing open bins unless this bin is crowded
    // relative to the mean residual (i.e., it's already tighter than average).
    if bin_residual == bin_capacity {
        // Brand-new empty bin: baseline cost; make it unattractive unless many bins open.
        score += 30.0 + (open_bins_count as f64) * 2.0;
    } else {
        // Reward filling bins that are already below-mean residual (consolidation).
        let res = bin_residual as f64;
        if res < mean_residual {
            score -= 25.0;
        } else {
            score += 10.0;
        }
    }

    // Stream progression: early on, be more willing to open bins (spread risk);
    // later, squeeze everything into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score -= 40.0 * (1.0 - progress);
    } else {
        score -= 20.0 * progress;
    }

    // Modulo-based tie-breaking on post_residual to break exact ties deterministically.
    score += (post_residual % 7) as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead space avoidance: penalize unusable small gaps harshly.
    // A residual gap is "dead" if it's too small for the smallest plausible item (1..100 range).
    // Use a smooth but steep penalty as post_residual approaches the danger zone.
    let dead_threshold = 12.0; // gaps <= ~12 are nearly unusable for typical items
    if (post_residual as f64) < dead_threshold {
        // Exponential blow-up of penalty as gap shrinks
        score += (dead_threshold - post_residual as f64).powf(2.0) * 8.0;
    }

    // Perfect fit reward: strongly favor placements that leave zero residual
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 3 {
        score -= 20.0; // near-perfect fit also rewarded
    }

    // Coupling with next_item_size lookahead: if the next item fits exactly
    // into the post_residual, this is an excellent chain placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_post = post_residual - next_item_size;
        if next_post == 0 {
            score -= 35.0; // chain perfect fit
        } else if (next_post as f64) < dead_threshold {
            // Next placement would create dead space: penalize this bin
            score += 15.0;
        } else {
            score -= 10.0; // next item fits reasonably: mild reward
        }
    }

    // Open bins pressure: penalize selecting bins when many bins are open,
    // encouraging consolidation into fewer bins to keep closures frequent.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * 2.5 * (0.5 + progress);

    // Mean residual coupling: if this bin's post_residual deviates badly from
    // the mean residual across open bins, penalize (keeps residuals uniform,
    // making future items more likely to fit somewhere).
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.15;

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin wastes the residual of all
    // open bins. Only attractive when this item would create severe dead space
    // in every fitting bin, or when few bins are open with large residuals.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin scales with open bins count
        score += 40.0 + (open_bins_count as f64) * 3.0;
        // But if placing into an existing bin would create dead space,
        // opening a fresh bin becomes relatively better (score here is
        // post_residual = capacity - item_size, naturally large).
        if (post_residual as f64) < dead_threshold {
            score -= 60.0; // fresh bin avoids the dead gap entirely
        }
        // Late in the stream, prefer closing out existing bins
        score -= progress * 10.0;
    }

    // Mild reward for filling large items into tight bins (tight-fit heuristic)
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 12.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact/low waste fits more aggressively than linear.
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * waste_frac * waste_frac;

    // 2-step lookahead: reward when post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 + 0.35 * slack.min(30.0);
        // Bonus when the chain closes perfectly (next item exactly fills bin).
        if slack == 0.0 {
            score -= 15.0;
        }
    } else if next_item_size > 0 {
        // Penalize creating dead space the next item cannot use.
        score += 8.0 * (next_item_size as f64 - post_residual as f64).min(20.0) / 20.0;
    }

    // Prefer bins with residuals below the mean (tighten tight bins first).
    score += 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // New-bin candidate: penalize opening a bin unless current bin would leave
    // unusable dead space or the fit is poor.
    if bin_residual == bin_capacity {
        score += 18.0;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 5.0; // planning a fresh 2-item bin is reasonable
        }
    }

    // Early in the stream, be slightly more willing to open bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 4.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor small post-residual (non-linearly).
    let fit_ratio = post_residual as f64 / cap;
    score += 20.0 * fit_ratio * fit_ratio;

    // Reward using bins that are already "wasted" (large residual) to consolidate.
    let fill_frac = item_size as f64 / bin_residual as f64;
    score -= 15.0 * fill_frac;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, big reward.
    if next_item_size > 0 {
        if next_item_size as f64 == post_residual as f64 {
            score -= 40.0;
        } else if (post_residual as f64) < next_item_size as f64 {
            // post-residual too small for next item: penalize proportionally
            score += 8.0 * (next_item_size as f64 - post_residual as f64) / cap;
        } else {
            // next item fits in the leftover: mild reward
            score -= 6.0 * (next_item_size as f64 / post_residual as f64);
        }
    }

    // New-bin candidate handling: penalize opening a new bin unless the current
    // item fits very poorly everywhere (high fill fraction threshold relaxes it).
    if bin_residual == bin_capacity {
        let base_penalty = 35.0;
        let relief = 30.0 * (1.0 - fill_frac.min(1.0));
        // As stream progresses, slightly more willing to open bins.
        let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += base_penalty - relief - 5.0 * t;
    }

    // Global state: many open bins with high mean residual -> encourage filling
    // existing bins rather than spreading.
    if bin_residual != bin_capacity {
        score -= 5.0 * (open_bins_count as f64).ln().max(0.0) * (mean_residual / cap).min(1.0);
    }

    // Penalize leaving residuals that are awkwardly small but nonzero (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / (total_items as f64 - 1.0) } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Non-linear polynomial coupling: dead space hurts more as stream progresses.
    let norm_post = post / cap;
    score += norm_post * norm_post * (40.0 + 60.0 * progress) * cap * 0.1;

    // Reward tight fits (small post_residual) more strongly over time.
    score -= (1.0 - norm_post) * (1.0 - norm_post) * 15.0 * (0.5 + progress);

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual >= next_item_size {
            let fit_ratio = (post_residual as f64 - nxt) / cap;
            score -= 12.0 * (1.0 - fit_ratio) * (1.0 - fit_ratio);
        } else {
            // Post-residual too small for next item: penalize wasted space.
            score += 6.0 * norm_post * (1.0 + progress);
        }
    }

    // Last chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (0.5 + progress);
    }

    // New-bin candidate: penalize opening new bins, more so early and when
    // open bins already have plenty of room.
    if bin_residual == bin_capacity {
        score += 30.0 + 20.0 * (1.0 - progress);
        if mean_residual > item_size as f64 {
            score += 10.0;
        }
    }

    // Mild preference for balancing residuals across open bins.
    score += 0.05 * (post - mean_residual).abs();

    // Slight penalty for large open-bin fleets encouraging consolidation.
    score += open_bins_count as f64 * 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual mod small integers
    let cap = bin_capacity as f64;
    let pr = post_residual;
    let prf = pr as f64;

    // Reward tight fits: post_residual near zero is great
    if pr == 0 {
        score -= 60.0;
    } else if pr <= 5 {
        score -= 25.0;
    } else if pr <= 10 {
        score -= 10.0;
    }

    // Penalize dead space that can't fit the smallest plausible item (<=10)
    if pr < 10 && pr > 0 {
        score += 5.0;
    }

    // Harmonic class: post_residual divisible by common item sizes => reusable
    if pr >= 10 {
        if pr % 10 == 0 {
            score -= 12.0;
        }
        if pr % 20 == 0 {
            score -= 8.0;
        }
        if pr % 25 == 0 {
            score -= 4.0;
        }
        if pr % 50 == 0 {
            score -= 6.0;
        }
    }

    // Lookahead: does next item fit exactly into post_residual?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size <= pr {
            // next item fits: reward proportional to how much slack remains after next
            let after_next = (pr - next_item_size) as f64;
            score -= 15.0 * (1.0 - after_next / cap);
        } else {
            // next item won't fit here: mild penalty for wasting this bin's space
            score += 6.0;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are crowded
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // base cost of a new bin
        score += 55.0;
        // if mean residual across open bins is small (bins nearly full), new bin is fine
        score -= 30.0 * (1.0 - (mean_residual / cap).min(1.0));
        // early in stream, opening bins is cheaper; late, prefer consolidation
        score += 15.0 * progress;
        // many open bins: discourage adding more
        score += (open_bins_count as f64).ln().max(0.0) * 5.0;
        // large item justifies a fresh bin
        score -= (item_size as f64 / cap) * 20.0;
    }

    // Prefer bins whose residual is close to item (best-fit flavor, non-linear)
    let fit_ratio = (item_size as f64) / (bin_residual.max(1) as f64);
    score -= 20.0 * fit_ratio * fit_ratio;

    // Mild preference for filling bins with larger residuals when many bins open
    score -= (bin_residual as f64 / cap) * (open_bins_count as f64).sqrt();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny residuals are unusable by items >=1,
    // but especially by typical items (>=10). Penalize gaps in [1, 9] heavily.
    if post_residual >= 1 && post_residual <= 9 {
        score += 40.0 + (9 - post_residual) as f64 * 3.0;
    }
    // Medium gaps (10..19) only fit small items; mild penalty.
    else if post_residual >= 10 && post_residual <= 19 {
        score += 6.0;
    }

    // Reward very tight fits (near-perfect packing).
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Fit ratio: prefer bins where the item fills a large fraction of residual.
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fill;

    // Open-bin pressure: with many open bins, discourage spreading; with few,
    // allow filling existing bins aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (1.0 + progress);
    score += 0.6 * pressure;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead (k=2): if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.2 * next_item_size as f64;
    }
    // If next item almost fits (gap smaller than next item), slight penalty.
    else if next_item_size > post_residual && post_residual > 0 {
        score += 4.0;
    }

    // Mean residual coupling: if this bin's residual is far below the mean,
    // it is a "nearly full" bin — finishing it is good.
    let dev = mean_residual - post_residual as f64;
    if dev > 0.0 {
        score -= 0.3 * dev;
    }

    // New-bin candidate: make empty-bin attractive only when no good fit exists.
    // Base new-bin score is post_residual (= capacity - item), which is large;
    // add a mild fixed cost so it only wins when open bins score poorly.
    if bin_residual == bin_capacity {
        score += 5.0;
        // But if there are zero fitting open bins, new bin is the only option;
        // ease the cost.
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact / near-exact fits (post_residual is dead space).
    let post = post_residual as f64;
    if post == 0.0 {
        score -= 60.0; // perfect fit
    } else if post < 10.0 {
        score -= 40.0 - post * 2.0; // near-perfect fit
    } else if post < 20.0 {
        score -= 10.0;
    } else {
        // Penalize large dead space relative to capacity
        score += (post / bin_capacity as f64) * 25.0;
    }

    // 2-step lookahead: reward if the next item fits into the post residual,
    // extra reward for an exact 2-item match.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            let nxt_post = post - nxt;
            if nxt_post == 0.0 {
                score -= 50.0; // exact 2-item chain
            } else {
                score -= 25.0 * (1.0 - nxt_post / bin_capacity as f64);
            }
        } else {
            // Next item won't fit here; mildly penalize leaving awkward residual
            score += 8.0;
        }
    }

    // Last chance: only this bin can fit the item -> strongly favor using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 45.0;
    }

    // Compare residual against mean residual across open bins:
    // prefer bins whose residual is tighter than average (consolidation).
    if mean_residual > 0.0 {
        let rel = (bin_residual as f64) / mean_residual;
        score += (rel - 1.0) * 12.0;
    }

    // Early in the stream, be slightly more willing to consolidate into open bins
    // rather than opening new ones.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score -= (1.0 - progress) * 5.0;
    }

    // Slight penalty when many bins are already open (encourage consolidation).
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more than linearly.
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 45.0 * tightness * tightness;

    // Lookahead: if the next item fits exactly in the post residual, strong bonus.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as i64 - next_item_size as i64) == 0 {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            // next item fits but imperfectly — mild bonus scaled by leftover after next
            let after_next = (post_residual - next_item_size) as f64;
            score -= 18.0 * (1.0 - after_next / cap);
        } else {
            // next item won't fit here: penalize bins whose residual is only slightly too small
            let gap = (next_item_size - post_residual) as f64;
            if gap < 12.0 {
                score += 0.8 * gap;
            }
        }
        // encourage leaving room comparable to the next item size
        score += 0.15 * ((post_residual as f64) - nxt).abs();
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Penalize opening a new bin when healthy open bins exist and residual is large.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let pressure = mean_residual / cap;
        score += 25.0 + 30.0 * pressure - 15.0 * progress;
        if open_bins_count == 0 {
            score -= 100.0; // must open a bin
        }
    } else if fitting_bins_count > 1 {
        // among multiple fitting bins, prefer the one closest in size to the item
        score += 0.05 * (bin_residual as f64 - item_size as f64);
    }

    // Mild global pressure: many open bins with high mean residual -> prefer filling existing bins.
    if bin_residual < bin_capacity {
        score -= 0.02 * mean_residual;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let fit_ratio = pr / cap;

    // Base: post residual, with non-linear penalty on mid-range waste
    let mut score = pr - 18.0 * (fit_ratio * std::f64::consts::PI).sin().abs();

    // Smooth coupling: residual waste weighted by stream progress
    let waste_coupling = fit_ratio * fit_ratio * (1.0 + 3.0 * progress);
    score += 25.0 * waste_coupling;

    // Lookahead: reward if next item fits the post residual (smooth kernel)
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let diff = (pr - ns) / cap;
        score -= 30.0 * (-20.0 * diff * diff).exp();
    }

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin, more so early and when fits exist
    if bin_residual == bin_capacity {
        let open_pressure = (open_bins_count as f64).ln().max(0.0);
        score += 55.0 + 25.0 * (1.0 - progress) + 10.0 * open_pressure;
        if fitting_bins_count > 0 {
            score += 20.0;
        }
    }

    // Mean residual alignment: prefer bins whose post residual matches average slack
    let dev = (pr - mean_residual) / cap;
    score += 8.0 * dev * dev;

    // Tight fit reward (smooth, no piecewise)
    score -= 15.0 * (-8.0 * fit_ratio).exp();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Dead space: residuals too small for the smallest plausible item (<= 9)
    // are nearly unusable; penalize them heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 45.0;
    }

    // Harmonic class of the post residual: multiples of common item sizes
    // (10, 20, 25, 50) are "friendly" gaps that future items can fill.
    let pr = post_residual;
    if pr > 0 {
        if pr % 10 == 0 { score -= 12.0; }
        if pr % 20 == 0 { score -= 6.0; }
        if pr % 25 == 0 { score -= 5.0; }
        if pr % 50 == 0 { score -= 4.0; }
        // Awkward primes / odd gaps are less reusable.
        if pr % 2 == 1 { score += 4.0; }
    }

    // Lookahead: penalize if the next item cannot fit in the post residual
    // (we would strand this bin's gap), reward if it fits snugly.
    if next_item_size > 0 && pr > 0 {
        if next_item_size > pr {
            score += 18.0;
        } else {
            let gap = pr - next_item_size;
            if gap == 0 {
                score -= 25.0; // chains a perfect fit for the next item
            } else if gap < 10 {
                score += 10.0; // creates fresh dead space
            } else {
                score -= 5.0;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: prefer it only when open bins would leave bad gaps.
    if bin_residual == bin_capacity {
        // Neutral-ish baseline; slightly above a good fit, below a bad one.
        score = 55.0 + (open_bins_count as f64).ln().max(0.0) * 2.0;
        // Late in the stream, prefer consolidating into open bins.
        if total_items > 0 && (step_index as f64) / (total_items as f64) > 0.7 {
            score += 15.0;
        }
    }

    // Mild pressure to fill fuller bins when many bins are open.
    score -= (bin_residual as f64 / bin_capacity as f64) * (open_bins_count as f64).min(20.0);

    // Prefer bins whose residual is close to the mean (balanced packing),
    // penalize outliers slightly.
    let diff = (bin_residual as f64 - mean_residual).abs();
    score += diff * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Perfect fit reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Dead space is worse if no future item can use it (lookahead).
    if next_item_size > post_residual && post_residual > 0 {
        score += 12.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Tight fit bonus: relative fill of the bin.
    score -= (item_size as f64 / bin_capacity as f64) * 10.0;

    // Penalize leaving residual far from mean residual (fragmentation).
    let diff = post_residual as f64 - mean_residual;
    score += 0.05 * diff * diff;

    // Late in stream: prefer consolidating into existing bins.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual != bin_capacity {
        score -= 10.0 * progress;
    } else {
        score += 5.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when next item exactly fills post_residual
    if next_item_size > 0 && next_item_size <= post_residual {
        if next_item_size == post_residual {
            score -= 800.0; // chain fit: this bin will be perfectly closed next step
        } else {
            // partial lookahead reward proportional to how small the leftover will be
            let chain_leftover = (post_residual - next_item_size) as f64;
            score -= 100.0 - chain_leftover * 0.8;
        }
    } else if next_item_size > post_residual {
        // next item cannot use this bin's leftover: penalize dead space more strongly
        score += post_residual as f64 * 0.5;
    }

    // Penalize leaving residuals that are likely unusable (small gaps)
    if post_residual > 0 && post_residual < 10 {
        score += 150.0;
    }

    // Compare against mean residual: prefer bins that are tighter than average
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 200.0;
    }

    // New-bin candidate handling: discourage opening a new bin when open bins fit well
    if bin_residual == bin_capacity {
        score += 50.0 + open_bins_count as f64 * 5.0;
        // but if nothing else fits well, allow new bin
        if fitting_bins_count == 0 {
            score -= 300.0;
        }
    }

    // Early in stream: be more liberal with opening bins to build a good pool
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) non-linearly.
    score -= (bin_capacity as f64 - post_residual as f64).powf(1.4) * 0.35;

    // Penalize dead space that cannot fit typical small items.
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // Lookahead: if next item fits exactly in post_residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 12.0;
        } else {
            // Next item won't fit here; slight penalty proportional to overflow.
            score += (next_item_size - post_residual) as f64 * 0.05;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when no open bin is a good fit.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty grows with number of open bins (encourage consolidation).
        score += 15.0 + open_bins_count as f64 * 2.0;
        // If the item leaves a large residual that matches the next item, opening
        // a fresh bin can be good (e.g., pairing 60+40).
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= (post_residual - next_item_size) as f64 * 0.3;
        }
        // Late in the stream, prefer closing out existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Global state: if mean residual is high, prefer filling the emptiest bins
    // (this bin having residual far above mean is a good consolidation target).
    if !is_new_bin {
        let dev = bin_residual as f64 - mean_residual;
        score += dev * 0.1;
    }

    // Exact fill is perfect.
    if post_residual == 0 {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, prefer tight fills (low post_residual); later, weight dead space more.
    let coupling = norm_pr * norm_pr * (0.5 + 2.0 * progress) * cap;
    score += 0.6 * coupling;

    // Reward near-perfect fits with a smooth quadratic bonus.
    let tightness = 1.0 - norm_pr;
    score -= 12.0 * tightness * tightness * (1.0 + progress);

    // Penalize waste relative to mean residual across open bins (smooth interaction).
    score += 0.15 * (pr - mean_residual) * (1.0 + progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - norm_pr);
    }

    // Lookahead: reward leaving space compatible with the next item (smooth kernel).
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let diff = pr - ns;
        let kernel = (-0.0008 * diff * diff).exp();
        score -= 8.0 * kernel * (1.0 + 0.5 * progress);
    }

    // Slight preference for consolidating into fewer bins as stream nears end.
    score += 0.02 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    score = post_residual as f64;

    // Harmonic class logic: classify post_residual by capacity fractions
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap;

    // Penalize dead space in "unusable" harmonic classes
    // post_residual in (0, 10] is nearly dead; [50, 100) is reusable
    if post_residual > 0 {
        if post_residual < 10 {
            score += 40.0 * (1.0 - frac * 10.0);
        } else if post_residual < 25 {
            score += 12.0;
        } else if post_residual < 50 {
            score += 4.0;
        } else {
            score -= 6.0; // half-bin or better residual is valuable
        }
    } else {
        score -= 25.0; // perfect fit: strong reward
    }

    // Modulo-class coupling with next item: reward residuals that can host
    // next_item_size exactly or leave a good class afterward
    if next_item_size > 0 {
        if bin_residual >= next_item_size {
            let next_post = post_residual as i64 - next_item_size as i64;
            if next_post >= 0 {
                // harmonic bonus if next_post is a "nice" class
                let np = next_post as u32;
                if np == 0 {
                    score -= 18.0;
                } else if np % 10 == 0 {
                    score -= 10.0;
                } else if np >= 50 {
                    score -= 6.0;
                } else if np < 10 {
                    score += 8.0;
                }
            }
        } else {
            // this bin can't host next item; slight penalty unless it's a perfect fit now
            if post_residual > 0 { score += 3.0; }
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: make empty bin attractive only when
    // current item is large relative to mean residual or no good fits exist
    if bin_residual == bin_capacity {
        // neutral baseline
        score = cap - item_size as f64;
        // discourage opening new bins when many open bins fit the item
        score += 20.0 * (fitting_bins_count as f64).min(4.0);
        // encourage new bin late in stream if mean residual is small
        if mean_residual < item_size as f64 {
            score -= 10.0;
        }
        // discourage new bin if item is small and mean residual is generous
        if item_size < 30 && mean_residual > 40.0 {
            score += 15.0;
        }
    }

    // Mild stream-progression pressure to consolidate early
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if post_residual > 0 {
        score += 3.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
