pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // can exactly (or nearly) host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 18.0 * (1.0 - gap / bin_capacity as f64);
        // Exact match is a jackpot
        if post_residual == next_item_size {
            score -= 40.0;
        }
    } else if next_item_size > 0 {
        // Next item cannot fit in this bin's leftover: penalize dead space
        let waste = post_residual as f64;
        score += 0.35 * waste;
    }

    // Relative to mean residual: prefer tighter-than-average bins
    score += 0.25 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // Prefer keeping fewer open bins
    score -= 0.5 * (open_bins_count as f64).recip();

    // Penalize opening a new bin when a reasonable fit exists elsewhere
    if bin_residual == bin_capacity && fitting_bins_count > 0 && post_residual as f64 > mean_residual {
        score += 8.0;
    }

    // Slight late-stream tightening: waste matters more as stream ends
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 0.2 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squared waste penalty normalized by capacity.
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score += tightness * tightness * 40.0;

    // Reward exact-ish fits strongly.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Last chance: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Lookahead: if next item fits into post_residual, bonus; if it would leave a new bin nearly empty, penalize opening new bins.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 20.0;
        } else {
            // Next item won't fit here; slightly penalize bins that would strand capacity.
            score += (next_item_size - post_residual) as f64 * 0.1;
        }
    }

    // Penalize opening a new bin when open bins exist with decent residuals.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let open_pressure = open_bins_count as f64;
        let waste = bin_capacity as f64 - item_size as f64;
        // New bin attractive only if existing residuals are all small relative to item.
        let scarcity = if mean_residual < item_size as f64 + 2.0 { 1.0 } else { 0.0 };
        score += waste * 0.5 + open_pressure * 3.0 * (1.0 - progress) - scarcity * 120.0;
        // Late in the stream, discourage new bins more.
        score += progress * 15.0;
        if fitting_bins_count > 0 {
            score += 30.0;
        }
    } else {
        // Prefer filling bins below mean residual (consolidate waste).
        if (bin_residual as f64) > mean_residual {
            score -= 5.0;
        } else {
            score += 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Base: prefer small post-residual, with mild non-linear decay.
    let mut score = post + 0.35 * (post * post) / cap;

    // Reward tight fits (small post_residual relative to capacity) with a smooth saturating term.
    let tightness = 1.0 - (post / cap).min(1.0);
    score -= 12.0 * tightness * tightness * tightness;

    // Non-linear coupling of tightness with stream progress: tighter fits matter more early,
    // dead space penalized more strongly late (remaining capacity becomes precious).
    let late = progress * progress;
    score += 18.0 * (post / cap) * (0.3 + 0.7 * late);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 25.0 + 10.0 * (1.0 - progress);
    } else {
        // Slight penalty when many alternatives exist, favoring the best-fit among them.
        score += 0.6 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Lookahead coupling: if the next item would fit exactly in the post-residual,
    // reward; if next item cannot fit, mild penalty for wasted space.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let gap = (post - nxt) / cap;
            score -= 8.0 * (1.0 - gap) * (1.0 - gap);
        } else {
            score += 5.0 * (1.0 - post / cap);
        }
    }

    // Contextual smoothing: bins far from mean residual get a small quadratic penalty,
    // encouraging residual homogenization across open bins.
    let dev = post - mean_residual;
    score += 0.04 * dev * dev / cap;

    // New-bin candidate handling: an empty bin has post == cap; make it mildly unattractive
    // unless open bins are very fragmented (few fitting bins, high mean residual usage).
    if bin_residual == bin_capacity {
        let fragmentation = (open_bins_count as f64).max(1.0);
        let crowded = (mean_residual / cap).max(0.0).min(1.0);
        score += 6.0 - 4.0 * crowded - 0.15 * fragmentation * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class penalty: dead space in awkward residue classes is worse.
    let cap_f = bin_capacity as f64;
    let post_f = post_residual as f64;
    let frac = post_f / cap_f;

    // Post-residual harmonic class (mod 10): small nonzero residues are dead space.
    let class = (post_residual % 10) as f64;
    if post_residual > 0 {
        score -= 12.0 * (1.0 - class / 9.0);
    } else {
        // Perfect fit: strongly reward closing the bin exactly.
        score -= 40.0;
    }

    // Reward tight fits: small post_residual relative to item size.
    score -= 8.0 * (item_size as f64 / bin_residual.max(1) as f64);

    // Lookahead: if next item fits in the post residual, reward; else penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / cap_f);
        } else {
            let gap = (next_item_size - post_residual) as f64;
            score += 6.0 * (gap / cap_f);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when open bins fit poorly.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / cap_f;
        // Penalize opening new bins when existing mean residual is healthy.
        score += 30.0 * pressure;
        // But reward opening a fresh bin late in the stream for large items.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if item_size > 50 {
            score -= 15.0 * progress;
        }
        // Fresh bin with big item leaves large residual; slight penalty scaled by item.
        score += 0.05 * (bin_capacity - item_size) as f64;
    }

    // Prefer bins below mean residual (fill emptier bins first to consolidate).
    score += 0.10 * (bin_residual as f64 - mean_residual);

    // Mild crowding penalty: many open bins -> prefer consolidation.
    score += 0.5 * open_bins_count as f64 * (1.0 - frac);

    // Small harmonic noise on fraction classes to break ties deterministically.
    let h = ((post_residual as u64).wrapping_mul(2654435761) % 7) as f64;
    score += h * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable gaps (dead space) disproportionately.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 12.0;
    }

    // Reward tight fits: post_residual == 0 is perfect.
    if post_residual == 0 {
        score -= 40.0;
    }

    // If next item could use the post_residual, reward keeping it useful.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    }
    // Penalize if post_residual cannot fit the next item (likely dead space).
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 0.5;

    // Mean residual coupling: prefer bins below mean residual (tighter bins).
    score += (mean_residual - post_residual as f64) * 0.3;

    // Progress-based tightening: later in stream, prefer tighter fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.5;

    // New-bin candidate: mild penalty so it's only chosen when open bins are bad.
    if bin_residual == bin_capacity {
        score += 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but reward exact/very tight fits extra.
    if post_residual == 0 {
        score -= 60.0; // perfect closure
    } else if post_residual <= 10 {
        score -= 25.0; // near-perfect fit, dead space unusable anyway
    } else if post_residual < 20 {
        score -= 10.0;
    }

    // 2-step lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0; // chain completion: perfect 2-step packing
        } else if next_item_size <= post_residual {
            // next item fits: reward proportionally to how well it fills the remainder
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 40.0 * fill;
        } else {
            // next item does NOT fit: penalize leaving residual close to but below next item
            let gap = (next_item_size - post_residual) as f64;
            if gap <= 20.0 {
                score += 15.0 + 0.5 * gap; // near-miss wasted space
            }
        }
    }

    // Compare post_residual against mean residual: leaving above-average residual is wasteful.
    let pr = post_residual as f64;
    if pr > mean_residual {
        score += 0.3 * (pr - mean_residual);
    } else {
        score -= 0.2 * (mean_residual - pr);
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless current item is large
    // (then a fresh bin keeps capacity aligned) and other bins fit poorly.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        // Fresh bin leaves full residual; make it unattractive unless item is large
        score += 35.0 - 40.0 * large_item;
        // If no other bin fits (fitting count excludes new bin logic), new bin is fine
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
        // Early in stream, opening bins is cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
    }

    // Mild penalty for spreading across too many open bins
    score += 0.5 * open_bins_count as f64;

    // Small preference for filling bins more completely overall
    score -= 0.1 * (item_size as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

