    // Penalize dead space: post_residual that is too small to be useful later
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only attractive when existing fits are poor
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let open_pressure = open_bins_count as f64;
        // Base cost of opening a new bin, softened early in the stream
        score += 55.0 - 25.0 * (1.0 - progress);
        // If mean residual across open bins is large, opening a new bin is wasteful
        score += 0.4 * mean_residual;
        // If the next item would fit in the fresh bin, opening is more attractive
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 0.3 * next_item_size as f64;
        }
        // Many open bins with poor fits: allow opening to spread load
        if fit_ratio < 0.5 {
            score -= 10.0;
        }
        let _ = open_pressure;
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual >= next_item_size {
            score -= 0.2 * next_item_size as f64;
        } else {
            // next item cannot use leftover space; mild penalty scaled by gap
            score += 0.1 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Prefer filling bins that are already partially committed when many bins are open
    if open_bins_count > 4 && bin_residual != bin_capacity {
        score -= 5.0;
    }

    // Time-horizon coupling: late in the stream, prioritize compactness harder
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.5 * progress;

    // Mild bonus for matching the mean residual (keeps bin residuals balanced)
    score -= 0.05 * (mean_residual - post_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_post = post / cap;

