    let mut score = 1.0 - (1.0 - norm_post).powi(3);
    score = score * cap * 0.5 + post * 0.6;

    // Smooth coupling with stream progress: later in stream, penalize waste more
    let progress_coupling = norm_post.powi(2) * (0.5 + progress);
    score += progress_coupling * cap;

    // Interaction with mean residual: bin far from mean gets penalized/rewarded
    let dev = post - mean_residual;
    score += 0.25 * dev * dev / cap;

    // Lookahead: reward leaving room for the next item
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if post >= ns {
            score -= 0.35 * (1.0 - ((post - ns) / cap).powi(2));
        } else {
            score += 0.5 * (ns - post);
        }
    }

    // Last-chance bin: strong reward to use it
    if fitting_bins_count == 1 {
        score -= cap * 0.8;
    }

    // Slight penalty for many open bins (encourage consolidation)
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Harmonic class of post_residual: bins whose leftover lands on a
