    }

    // Integer-division threshold: leftover big enough for a typical item
    // (>= next item, or >= 10 min size) stays valuable.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.1 * post_residual as f64;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0; // creates unusable gap for the known next item
    }

    // Lookahead compatibility: post_residual + next fits a harmonic half-class
    let half = bin_capacity / 2;
    if post_residual >= half {
        score -= 3.0;
    }

    // Last-chance bin: strongly reward using it to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: make empty bins unattractive unless nothing fits well.
    if bin_residual == bin_capacity {
        score += 10.0 + 0.05 * open_bins_count as f64;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity && fitting_bins_count == 0 {
            score -= 5.0;
        }
    }

    // Late in the stream, prefer consolidating into open bins.
    score += progress * (post_residual as f64 * 0.15);

    // Deviation from mean residual: bins far from the mean create fragmentation.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that nothing (min size 1..100, but
    // practically small gaps < ~10) can ever fill are pure waste. Penalize hard.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item.max(1) {
        score += 1000.0; // unreachable in practice; guard
    }
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // unusably small gap
    } else if post_residual < 20 {
        score += 15.0; // near-dead space
    }

    // Reward near-perfect fits (post_residual close to 0).
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Reward residual that can still host the lookahead item (k=2 lookahead).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            score += 5.0; // creating a gap the next item cannot use
        }
    }

    // Open-bin pressure: with many bins open, prefer consolidation into existing
    // bins rather than spreading; with few bins, filling is cheap.
    let pressure = open_bins_count as f64 * 1.5;
    score += pressure * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin is only attractive when the item
    // fits poorly everywhere else, or when mean residual is very low.
    if bin_residual == bin_capacity {
        // Baseline new-bin score: moderately high so tight fits in open bins win.
        score = (bin_capacity - item_size) as f64 * 0.6;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: new bin is fine
        }
        if mean_residual < 5.0 {
            score -= 10.0;
        }
    } else {
        // Existing-bin placements get a structural discount vs the new-bin baseline.
        score -= 10.0;
    }

    // Slight late-stream tightening: as the stream progresses, waste matters more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 5.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, penalize large dead space nonlinearly.
    let dead = post_residual as f64 / bin_capacity as f64;
    score += dead * dead * 40.0;

    // 2-step lookahead: if next item fits exactly into post_residual, strongly reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            score -= 15.0;
        } else {
            // next item cannot use this residual: penalize proportionally
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
        // Perfect chain: residual equals next item, and then next residual is tiny
        if post_residual >= next_item_size && (post_residual - next_item_size) <= 5 {
            score -= 25.0;
        }
    }

    // Relative-to-mean residual coupling: prefer bins whose residual is below mean
    // (tighter bins get used first, keeping loose bins flexible).
    let res = post_residual as f64;
    if res < mean_residual {
        score -= (mean_residual - res) * 0.2;
    } else {
        score += (res - mean_residual) * 0.2;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid fragmentation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: discourage opening a new bin unless item is large and
    // no open bin gives a decent fit. Empty-bin call has bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin; reduced late in the stream or when
        // many bins are already open (packing pressure).
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_penalty = 45.0 - 20.0 * progress;
        if open_bins_count > 4 {
            new_bin_penalty -= 5.0;
        }
        // If item fits poorly anywhere (large item, few fitting bins), relax penalty.
        if item_size > 60 && fitting_bins_count <= 2 {
            new_bin_penalty -= 25.0;
        }
        // If next item is huge, a fresh bin may serve both better.
        if next_item_size > 70 && post_residual == bin_capacity {
            new_bin_penalty -= 15.0;
        }
        score += new_bin_penalty.max(0.0);
    }

    // Slight preference for filling larger residual bins when item is small
    // (keep small-residual bins for small items).
    if item_size <= 20 && post_residual > 50 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post_residual).
    score += 0.35 * (post_residual as f64).powf(1.4);

    // Penalize leaving dead space that can't fit typical future items.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 && post_residual < 10 {
        score -= 6.0; // near-perfect fill bonus
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 4.0 + 0.5 * (next_item_size as f64 / 100.0);
        } else {
            score += 2.0 * (next_item_size as f64 - post_residual as f64) / 100.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 8.0;
    }

    // Global pressure: many open bins -> prefer packing into existing ones.
    score += 0.15 * open_bins_count as f64;

    // New-bin candidate logic: only attractive when existing bins fit poorly.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Attractive if item is large and would leave awkward residuals elsewhere,
        // or early in the stream when there's room to plan.
        let waste_penalty = (bin_capacity - item_size) as f64;
        score = score * 0.5 + waste_penalty;
        if progress < 0.3 {
            score -= 3.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 5.0; // fresh bin can host next item too
        }
        if fitting_bins_count <= 2 {
            score += 4.0; // don't open new bins when good options exist
        }
    } else {
        // Prefer bins whose residual is close to mean (balanced usage),
        // but reward below-mean residuals slightly for fragmentation control.
        let dev = bin_residual as f64 - mean_residual;
        score += 0.05 * dev.abs();
    }

    // Late-stream consolidation: tighten up as stream ends.
    if progress > 0.8 {
        score += 0.4 * post_residual as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_post = post / cap;
    let norm_item = item_size as f64 / cap;

    // Base: prefer low post-residual (tight fit), with non-linear sharpening
    let mut score = post * (1.0 + 2.0 * norm_post * norm_post);

    // Smooth interaction: tightness reward grows with stream progress
    let tightness = 1.0 - norm_post;
    score -= tightness * tightness * 30.0 * (0.5 + progress);

    // Penalize creating dead space that likely cannot be used later
    let dead = if norm_post > 0.0 && norm_post < 0.1 { (0.1 - norm_post) * 400.0 } else { 0.0 };
    score += dead;

    // Lookahead coupling: reward residual that can host the next item
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if post >= ns {
            let slack = (post - ns) / cap;
            score -= 12.0 * (1.0 - slack * slack);
        } else {
            score += 8.0 * ((ns - post) / cap);
        }
    }

    // Last-chance bonus: avoid opening a new bin when this is the only fitting one
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + progress);
    }

    // Mild penalty tied to fragmentation relative to mean residual
    score += 0.05 * (mean_residual - post).abs();

    // New-bin candidate should lose unless current bins are poor fits
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * (1.0 - progress) + 5.0 * (open_bins_count as f64).sqrt();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into
    // capacity-fraction buckets (integer division thresholds).
    let post = post_residual as u32;
    let class = post / 10; // decile class of leftover space
    // Odd classes (5..15..25 leftover) tend to be dead space for items >=10
    let odd_penalty = if post > 0 && class % 2 == 1 { 6.0 } else { 0.0 };

    // Reward perfect / near-perfect fits strongly (mod-based harmony)
    if post == 0 {
        score -= 40.0;
    } else if post <= 5 {
        score -= 18.0;
    } else if post <= 10 {
        score -= 8.0;
    } else {
        score += odd_penalty;
    }

    // Harmonic coupling: can the NEXT item exactly fill the post residual?
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 55.0; // chain completion: perfect follow-up
        } else if next_item_size <= post {
            // leftover usable by next item: reward proportionally to fit ratio
            let fit_ratio = next_item_size as f64 / post as f64;
            score -= 15.0 * fit_ratio;
        } else {
            // next item too big for leftover: penalize if leftover is small-dead
            if post < 10 {
                score += 10.0;
            }
            // modulo harmony: does post mod next_item_size leave small residue?
            let m = post % next_item_size.max(1);
            if m <= 5 {
                score -= 6.0;
            } else {
                score += 3.0;
            }
        }
    } else {
        // last item: strongly prefer tightest packing
        score += post as f64 * 0.5;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible (large post residual dead space).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
        if post <= 10 {
            score -= 10.0;
        }
    }

    // New-bin candidate handling: an empty bin has post_residual = capacity - item.
    if bin_residual == bin_capacity {
        // Opening a new bin is attractive only when item is large (harmonic
        // threshold at half capacity) or all existing fits are bad.
        if item_size >= 50 {
            score += 8.0; // slight bias against hoarding new bins for large items? keep mild
        } else {
            score += 20.0; // discourage new bin for small items when fits exist
        }
        // early stream: allow more bins to spread future flexibility
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 15.0 * (1.0 - progress);
    }

    // Mean residual context: if this bin's residual is far below mean, it is
    // already fragmented; placing here keeps clean bins available.
    let dev = mean_residual - bin_residual as f64;
    score += 0.08 * dev;

    // Congestion: many open bins -> prefer consolidating into existing bins.
    score += (open_bins_count as f64).ln().max(0.0) * 2.0;

    // Small tie-breaker on exact tightness using modulo class of item size
    let harmony = (item_size % 10) as f64;
    if post > 0 && (bin_residual % 10) == (item_size % 10) {
        score -= 2.0;
    }
    let _ = harmony;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small positive post_residual is worse than zero.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 8.0;
    }

    // Reward exact fits strongly.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward placements that leave room for the lookahead item (k=2).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 + 0.15 * next_item_size as f64;
        } else if post_residual > 0 {
            score += 6.0; // dead space relative to lookahead
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: prefer consolidating into fewer bins when residuals are plentiful.
    if open_bins_count > 1 {
        score += (open_bins_count as f64).ln() * 4.0 * (1.0 - bin_residual as f64 / bin_capacity as f64);
    }

    // New-bin candidate: only attractive when this item fits poorly everywhere
    // (i.e., large post_residual waste avoided) or bin is fresh and item is large.
    if bin_residual == bin_capacity {
        // Slight bias against opening new bins early, relaxes over the stream.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 18.0 - 10.0 * progress;
        // Opening a bin for a large item that would leave tiny waste is good.
        if post_residual < 10 {
            score -= 30.0;
        }
    }

    // Prefer bins whose residual is close to mean (balanced packing).
    score += (bin_residual as f64 - mean_residual).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when the NEXT item fits into post_residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Great: next item chains into this bin. Reward proportional to tightness.
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 - 0.35 * slack;
        } else {
            // Next item won't fit: penalize dead space left behind, worse when large.
            let dead = (next_item_size - post_residual) as f64;
            score += 0.45 * dead;
        }
        // Bonus if post_residual matches next item almost exactly (perfect chain).
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if diff <= 5.0 {
            score -= 12.0 * (1.0 - diff / 5.0);
        }
    } else {
        // Last item: minimize leftover waste strongly.
        score += 0.2 * post_residual as f64;
    }

    // Penalize bins whose residual deviates far below the mean (they're already tight);
    // mildly favor bins near/above mean residual for flexibility.
    score += 0.15 * (mean_residual - bin_residual as f64).abs();

    // Last-chance bin: if only one bin fits, strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no open bin is a good fit
    // (i.e., this bin would leave the item loose-fitting elsewhere) or near stream end.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit_elsewhere = if next_item_size > 0 && next_item_size <= post_residual { 0.0 } else { 1.0 };
        // Base cost of a fresh bin, discounted when open bins are crowded.
        let crowding = (open_bins_count as f64 * mean_residual) / (open_bins_count.max(1) as f64 * bin_capacity as f64);
        score += 55.0 * poor_fit_elsewhere - 30.0 * crowding - 10.0 * progress;
    }

    // Slight preference for tighter existing fits overall.
    score += 0.05 * (bin_residual as f64 - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: residuals too small for typical future items.
    if post_residual < 10 && post_residual > 0 {
        score += 30.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            score -= 8.0 * (1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64));
        } else {
            // Next item won't fit here; slight penalty proportional to wasted potential.
            score += 4.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
        }
    }

    // Compare against mean residual: prefer bins that keep residual spread balanced.
    let dev = post_residual as f64 - mean_residual;
    score += 0.15 * dev.abs();

    // Prefer fuller bins when many bins are open (containment pressure).
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 10.0 * fill_ratio * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));

    // Time horizon: early in the stream, allow new bins more freely;
    // late in the stream, pack tightly to avoid waste.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 15.0 * progress * fill_ratio;
    score += 10.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: make it attractive only when the item is large and
    // no good fit exists (poor fit into open bins), otherwise keep it unattractive.
    if bin_residual == bin_capacity {
        let poor_fit = fitting_bins_count <= 1 && (bin_capacity - item_size) < next_item_size;
        if poor_fit {
            score -= 20.0;
        } else {
            score += 18.0 + 0.3 * open_bins_count as f64;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr;

    // Non-linear waste penalty: dead space in mid-range residuals is worst
    let waste_curve = norm_pr * (1.0 - norm_pr);
    score += 60.0 * waste_curve * (1.0 + t);

    // Reward tight fits more strongly as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= 25.0 * tightness * tightness * (0.5 + t);

    // Penalize opening a new bin when other bins fit (smoothly relax late in stream)
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count > 0 { 1.0 } else { 0.0 };
        score += 40.0 * scarcity * (1.0 - t * t);
        score += 0.5 * open_bins_count as f64;
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 * (1.0 - t);
    }

    // Lookahead coupling: favor residual that can host next item
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        let compat = if pr >= ni { 1.0 - ((pr - ni) / cap) } else { 0.0 };
        score -= 15.0 * compat * compat;
        score += 10.0 * (1.0 - compat);
    }

    // Mild attraction to bins near mean residual (balance load)
    score += 0.05 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class: classify post_residual into residue classes mod capacity fractions
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;

    // Perfect-fit classes rewarded strongly
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 10 {
        score -= 200.0;
    } else if post_residual % quarter == 0 {
        score -= 60.0; // harmonically aligned dead space is reusable
    } else if post_residual < 10 {
        score += 150.0; // tiny unusable sliver: dead space penalty
    } else if post_residual < quarter {
        score += 40.0; // awkward class
    }

    // Mid-range residual classes: prefer bins whose post_residual can host
    // the next item (lookahead coupling)
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 - slack * 0.3; // reward chains that fit next item
            if slack == 0.0 {
                score -= 120.0; // exact next-item fit
            }
        } else {
            score += 10.0; // next item cannot chain here
        }
    }

    // Large residual classes (integer division thresholds)
    let big_class = post_residual / half;
    if big_class == 0 && post_residual > half {
        score -= 15.0;
    }

    // Tightness ratio coupling
    let tightness = item_size as f64 / bin_residual as f64;
    score += (1.0 - tightness) * 20.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate: penalize opening a bin unless current placement
    // would leave a very awkward residual
    if bin_residual == bin_capacity {
        score = 500.0
            - (item_size as f64 / bin_capacity as f64) * 100.0
            + open_bins_count as f64 * 2.0;
        if next_item_size > 0 && next_item_size > bin_capacity - item_size {
            score -= 80.0;
        }
    }

    // Stream progression: slightly prefer consolidating into fewer bins early
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (1.0 - progress) * 0.5;

    // Mean-residual alignment: prefer bins near the mean residual
    score += ((bin_residual as f64 - mean_residual) / bin_capacity as f64).abs() * 15.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = if total_items > 1 { step_index as f64 / (total_items as f64 - 1.0) } else { 0.0 };

    // --- Strict dead-space avoidance ---
    // Tiny nonzero gaps are "unusable dead space": penalize them far above
    // their nominal size so a bin leaving a usable larger residual is preferred.
    let dead_zone = 12.0f64;
    if post > 0.0 && post < dead_zone {
        let severity = (dead_zone - post) / dead_zone; // smaller gap => more severe waste
        score += (60.0 + 40.0 * severity) * (1.0 + 0.5 * progress);
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 25.0;
    }

    // --- Lookahead coupling ---
    // If the next item cannot use this residual, the gap is likely to stay dead.
    if next_item_size > 0 && post > 0.0 && post < next_item_size as f64 {
        score += 15.0 + 0.5 * (next_item_size as f64 - post);
    }

    // --- Last-chance bin pressure ---
    // If this is the only open bin that fits, using it avoids opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0 + 2.0 * open_bins_count as f64;
    }

    // --- New-bin candidate handling ---
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Opening pressure grows with open-bin count and stream progression.
        score += 35.0 + 4.0 * open_bins_count as f64 + 20.0 * progress;
        // Large items naturally belong in a fresh bin.
        score -= 0.3 * (item - 0.5 * cap).max(0.0);
    } else {
        // Mild progressive bonus for filling existing bins.
        score -= 2.0 * progress;
    }

    // --- Mean-residual coupling ---
    // Bins whose current residual is well below the mean are efficient fillers.
    score -= 0.1 * (mean_residual - bin_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact / near-exact fits are gold: subtract heavily.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Reward tight fits relative to capacity.
        score -= 2.0 * (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64;

        // 2-step lookahead: if next item fits the post residual, big reward.
        if next_item_size > 0 && post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 50.0 + 0.5 * slack;
        } else if next_item_size > 0 && post_residual < next_item_size {
            // Dead space: post residual too small for next item.
            score += 10.0 + (next_item_size - post_residual) as f64;
        }

        // Penalize leaving fragments smaller than the minimum item size (1..=100 unknown, use small threshold).
        if post_residual > 0 && post_residual < 10 {
            score += 30.0 + post_residual as f64;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: only attractive when many open bins are fragmented
    // or mean residual is high (open bins are wasteful).
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let fragmentation = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score += 80.0 - 60.0 * fragmentation - 20.0 * progress;
        if open_bins_count == 0 {
            score -= 500.0; // must open a bin
        }
    }

    // Mild preference to fill bins with lower residual than the mean.
    score -= 0.3 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that is unusable for typical items (below min item size)
    if post_residual < 10 {
        score -= 25.0; // perfect closure of a bin is excellent
    } else if post_residual < item_size.min(40) {
        score -= 6.0; // moderately useful leftover
    } else {
        score += 4.0; // large leftover: was it worth using this bin?
    }

    // Lookahead: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; slightly penalize leaving awkward gap
            let gap = (post_residual.saturating_sub(1)) as f64;
            if gap < next_item_size as f64 {
                score += 3.0 * (1.0 - gap / next_item_size as f64);
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 + 0.25 * item_size as f64;
    }

    // New-bin candidate logic: only attractive when existing fits are poor
    if bin_residual == bin_capacity {
        // Base penalty so new bins are opened only when needed
        score += 20.0;
        // If item is large relative to mean residual, existing bins are tight -> new bin more OK
        let squeeze = item_size as f64 / mean_residual.max(1.0);
        if squeeze > 0.8 {
            score -= 14.0 * (squeeze - 0.8).min(1.5);
        }
        // Early in stream, allow more bins (build diversity of partial bins)
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 8.0 * (1.0 - progress);
        // Few open bins -> opening is cheaper
        score -= 2.0 * (open_bins_count as f64).ln().max(0.0);
    }

    // Prefer bins whose residual is below the mean (filling the fullest bins first)
    let res = bin_residual as f64;
    if res < mean_residual {
        score -= 5.0 * (1.0 - res / mean_residual.max(1.0));
    } else {
        score += 3.0 * (res - mean_residual) / bin_capacity as f64;
    }

    // Mild time-decay pressure: later in stream, waste matters more
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress in (0,1)
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Non-linear waste shaping: quadratic penalty on large post_residual,
    // amplified as the stream progresses (late-stage fragmentation is costlier).
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    score += 0.35 * norm_pr * norm_pr * (0.5 + progress) * cap;

    // Lookahead coupling: reward bins whose post_residual can host the next item,
    // with a smooth interaction between fit tightness and progress.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64 / cap;
        score -= 6.0 * (1.0 - slack * slack) * (0.6 + 0.4 * progress);
    } else if next_item_size > 0 {
        // Next item cannot follow here: mild penalty growing with progress.
        score += 2.0 * (0.5 + progress);
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // scaled smoothly by how crowded the open-bin pool is.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0 + 0.5 * open_bins_count as f64;
    }

    // Penalize opening a brand-new bin (bin_residual == bin_capacity),
    // unless it would be a near-perfect fit for the item; the penalty
    // relaxes smoothly as the mean residual of open bins grows (open
    // bins are fragmented, so a fresh bin is more attractive).
    if bin_residual == bin_capacity {
        let perfect_fit = (cap - item_size as f64) / cap;
        let fragmentation = (mean_residual / cap).clamp(0.0, 1.0);
        let penalty = 10.0 * (1.0 - perfect_fit * perfect_fit) * (1.0 - 0.7 * fragmentation);
        score += penalty;
    }

    // Slight preference for tighter existing fits via interaction with mean residual.
    if bin_residual < bin_capacity {
        let tightness = 1.0 - (bin_residual as f64 / cap);
        score -= 1.5 * tightness * tightness;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post-residual: small post_residual is good (tight fit).
    let cls = post_residual / 10; // residual decade class 0..=9
    // Non-linear reward for tight fits (low class), quadratic in class.
    score += (cls as f64) * (cls as f64) * 2.5;

    // Perfect fit: absolute best.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space penalty: residual too small for any plausible item (sizes 1..=100).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // unusable sliver
    }

    // Lookahead coupling: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size <= post_residual {
            // reward proportional to how well next item fills remainder
            let frac = next_item_size as f64 / post_residual as f64;
            score -= 60.0 * frac;
        } else {
            // next item cannot use this residual; penalize leaving big gaps
            score += 0.3 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: make empty bin attractive only when current fits are poor.
    if bin_residual == bin_capacity {
        // Baseline cost of opening a new bin; decreases as stream matures.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 55.0 - 15.0 * progress;
        // Open new bin if existing bins have large mean residual mismatch with item
        let mismatch = (mean_residual - item_size as f64).abs();
        score -= 0.4 * mismatch;
        if next_item_size > 0 && next_item_size >= bin_capacity - item_size.min(bin_capacity) {
            // roomy bin good for pairing with next item
            score -= 10.0;
        }
    } else {
        // Mild bonus for bins whose residual is harmonically aligned with item size
        if bin_residual % item_size.max(1) == 0 && item_size > 0 {
            score -= 5.0;
        }
        // Penalize bins whose residual leaves awkward remainder classes
        let rem = post_residual % 25;
        if rem != 0 && rem < 10 {
            score += 8.0;
        }
    }

    // Slight preference to consolidate into fewer bins when many are open.
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // plausible item (<= 1..10) are pure waste. Penalize quadratically.
    if post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 8.0;
    } else if post_residual < 20 {
        // "awkward zone": only usable by tiny items; mild penalty
        score += 6.0 + (20 - post_residual) as f64 * 0.5;
    } else {
        // Usable residual: reward proportionally to how reusable it is
        score -= (post_residual as f64 - 20.0) * 0.35;
    }

    // Reward tight fits (post_residual small but still usable)
    if post_residual >= 10 && post_residual <= 30 {
        score -= (30 - post_residual) as f64 * 0.4;
    }

    // Last-chance bonus: if this is the ONLY bin that fits, strongly prefer it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage opening new bins when few bins are open
    // (early stream), encourage consolidation when many are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure scaled by open bins
        score = bin_capacity as f64 * 0.9;
        score += open_bins_count as f64 * 2.0;
        // Early on, opening new bins is cheaper (spread items out)
        score -= (1.0 - progress) * 15.0;
        // If no existing bin fits well (all residuals small), new bin is fine
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
        // Lookahead: if next item is large, a fresh bin is valuable
        if next_item_size > 0 && next_item_size >= 50 {
            score -= 10.0;
        }
    } else {
        // Placing into an existing bin: reward keeping bin count down
        score -= 5.0;
        // If many bins are open, consolidation is extra valuable
        if open_bins_count > 4 {
            score -= (open_bins_count.min(20) as f64) * 0.5;
        }
        // Lookahead synergy: if next item fits into this bin's post_residual,
        // reward the placement (chain packing).
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 12.0;
        } else if next_item_size > 0 && post_residual < next_item_size && post_residual < 10 {
            score += 10.0; // creates dead space before a known next item
        }
        // Prefer bins whose residual is close to the mean (balanced packing)
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness;

    // Aggressive 2-step lookahead: reward exact match of post_residual to next item
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 * (-diff / 25.0).exp();
        // Perfect chain: next item exactly fills the bin
        if post_residual == next_item_size {
            score -= 100.0;
        }
        // Penalize if next item cannot follow into this bin's residual
        if post_residual < next_item_size {
            score += 15.0;
        }
    }

    // Relative to mean residual: prefer bins with residual below mean (denser bins)
    let rel = post_residual as f64 - mean_residual;
    score += 0.5 * rel;

    // Last-chance bin: strong reward to use it, avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // New-bin candidate: penalize opening a new bin unless nothing fits well
    if bin_residual == bin_capacity {
        score += 120.0;
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
        // Late in stream, prefer closing out existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
    }

    // Penalize large dead space that likely becomes unusable
    if post_residual > 0 && post_residual < 10 {
        score -= 25.0; // nearly perfect fill
    }
    if post_residual > 50 {
        score += 10.0;
    }

    // Slight preference to keep fewer open bins balanced
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize leaving dead space that likely cannot be used by the next item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 0.6 * (next_item_size - post_residual) as f64;
        } else {
            // Reward leaving exactly enough room for the lookahead item.
            score -= 0.5 * (post_residual == next_item_size) as i32 as f64;
        }
    } else {
        // Last item: strongly prefer filling an existing bin as fully as possible.
        score -= 10.0 * tightness;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin wastes residual space in all
    // open bins; make it attractive only when existing fits are poor or few bins fit.
    if bin_residual == bin_capacity {
        let waste = mean_residual * open_bins_count as f64;
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let fit_pressure = 1.0 / (fitting_bins_count as f64 + 1.0);
        // Base cost of a fresh bin, discounted when open bins are mostly full
        // (little to waste) and late in the stream or few bins fit.
        score += 55.0 - 0.35 * waste - 10.0 * progress - 20.0 * fit_pressure;
        // Never open a new bin for the final item.
        if next_item_size == 0 {
            score += 100.0;
        }
    }

    // Mild preference for spreading load when many bins are open with slack
    // (encourages consolidating into low-residual bins otherwise).
    if bin_residual != bin_capacity {
        score += 0.15 * (bin_residual as f64 - mean_residual).max(-10.0).min(10.0);
    }

    // Slight time-varying exploration term to break ties differently over the stream.
    let phase = ((step_index as f64 * 0.37).sin()) * 0.5;
    score += phase * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer small post residual (tight fit), scaled non-linearly.
    let mut score = pr.powf(1.35);

    // Reward near-perfect fits with a smooth exponential bonus.
    let tightness = 1.0 - (pr / cap);
    score -= 22.0 * tightness.powf(3.5);

    // Lookahead coupling: reward residuals that can host the next item,
    // penalize residuals that nearly-but-don't fit it (dead space).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let gap = pr - nxt;
            score -= 10.0 * (1.0 - gap / cap).powf(2.0);
        } else {
            let miss = (nxt - pr) / cap;
            score += 14.0 * miss.powf(1.5) * (1.0 + progress);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 18.0 * (1.0 + progress);
    }

    // Fragmentation pressure: penalize leaving residuals far from the
    // current mean residual (creates outlier dead space), smoothly.
    let dev = (pr - mean_residual).abs() / cap;
    score += 6.0 * dev.powf(2.0) * (0.5 + progress);

    // Late in the stream, waste hurts more: amplify post_residual.
    score += 8.0 * progress * (pr / cap).powf(2.0);

    // New-bin candidate: make it attractive only when the item fits poorly
    // everywhere else (large post_residual elsewhere dominates); a fresh
    // bin has pr = cap - item, which naturally competes via the terms above.
    if bin_residual == bin_capacity {
        score += 4.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic classes: small post_residual is dead space; penalize by class
    let pr = post_residual;
    if pr > 0 {
        // class = which "harmonic bucket" the dead space falls into
        let class = match pr {
            0..=5 => 0,
            6..=10 => 1,
            11..=20 => 2,
            21..=30 => 3,
            31..=50 => 4,
            _ => 5,
        };
        score += class as f64 * 12.0;
    }

    // Modulo logic: dead space that could combine with next item (residual mod next_item_size == 0)
    if next_item_size > 0 && pr >= next_item_size {
        score -= 8.0; // next item fits exactly after this one
        if pr % next_item_size == 0 {
            score -= 6.0; // perfect chaining potential
        }
    } else if next_item_size > 0 {
        // next item cannot use this bin anyway; dead space value drops
        score += 5.0;
    }

    // Integer-division threshold: fraction of capacity wasted
    let waste_frac = post_residual as f64 / cap;
    score += waste_frac * waste_frac * 30.0;

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: only open when item is large and nothing decent fits
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64).max(1.0);
        let tight = fitting_bins_count == 0 || waste_frac > 0.6;
        if tight {
            score -= 40.0;
        } else {
            score += 80.0 + pressure * 2.0;
        }
    }

    // Prefer fuller bins relative to mean residual
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Mild stream-phase coupling: early on, be conservative with new bins
    let phase = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += (1.0 - phase) * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item (1..=100) are pure waste.
    if post_residual == 0 {
        score -= 1000.0; // perfect fit: excellent
    } else if post_residual < 10 {
        score += 120.0; // unusable tiny gap: heavy penalty
    } else if post_residual < 20 {
        score += 60.0;
    } else if post_residual < 35 {
        score += 25.0;
    } else if post_residual < 60 {
        score += 8.0;
    }

    // Reward bins whose residual was already tight (good packing density).
    let fill_frac = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 30.0 * fill_frac;

    // Lookahead: if the next item fits exactly into the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 150.0;
        } else if next_item_size <= post_residual {
            score -= 40.0;
        } else {
            // next item can't use this gap; small gap becomes more wasteful
            if post_residual < next_item_size {
                score += 10.0;
            }
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor filling existing bins.
    let open_pressure = (open_bins_count as f64).ln().max(0.0);
    score += 6.0 * open_pressure;

    // New-bin candidate logic: opening a new bin is only attractive when the item
    // fits poorly everywhere else (large item, tight residuals elsewhere).
    if bin_residual == bin_capacity {
        let tight_elsewhere = mean_residual < item_size as f64 * 0.5;
        if tight_elsewhere || fitting_bins_count == 0 {
            score -= 50.0; // allow opening a fresh bin
        } else {
            score += 45.0 + 0.5 * mean_residual; // prefer reusing open bins
        }
    }

    // Early stream: slightly prefer consolidating into few bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: reward tight fits (small post_residual) with a non-linear bonus.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 60.0 * tightness * tightness;

    // Lookahead: if the next item exactly fills post_residual, strong bonus;
    // if it fits, mild bonus; if it wastes the residual, penalty.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size < post_residual {
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 25.0 * fill * fill;
        } else {
            score += 15.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Penalize opening new bins when existing bins have plenty of room,
    // but allow it late in the stream or when open bins are fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 + 40.0 * (1.0 - progress)
            + 0.5 * (mean_residual / bin_capacity as f64) * 50.0;
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Prefer bins whose residual deviates from the mean in a useful way:
    // a bin with residual close to item_size is a perfect fit.
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.3 * gap;

    // Slight penalty for many small leftover slivers across bins.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Non-linear coupling of post_residual with stream progress
    let tight = 1.0 - (pr / cap).powf(2.0); // reward small post residual quadratically
    score -= 18.0 * tight * (0.4 + 0.6 * progress);

    // Penalize leaving residuals that no plausible item can use (dead space), smooth
    let dead = (pr / cap).powf(3.0);
    score += 25.0 * dead * (1.0 - progress);

    // Lookahead: reward if next item fits the post residual
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let fit_quality = 1.0 - (pr - next_item_size as f64) / cap;
        score -= 12.0 * fit_quality * (1.0 - progress);
    } else if next_item_size > 0 {
        score += 6.0 * (next_item_size as f64 - pr) / cap;
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 - (pr / cap));
    }

    // Mild penalty for spreading across many open bins
    score += (open_bins_count as f64).ln() * 2.0 * (1.0 - progress);

    // Smooth residual-mean alignment bonus
    score -= 4.0 * (-((pr - mean_residual) / cap).powi(2));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls into "usable" classes
    // (multiples of small sizes) are more attractive because future items likely fit.
    let pr = post_residual;
    let class_bonus: f64 = if pr == 0 {
        -40.0 // perfect fit
    } else if pr % 10 == 0 {
        -12.0
    } else if pr % 5 == 0 {
        -6.0
    } else if pr <= 10 {
        0.0
    } else {
        4.0 // awkward residual
    };
    score += class_bonus;

    // Dead space penalty: residual too small for the smallest plausible next item.
    if pr > 0 && pr < 10 {
        score += 25.0;
    }

    // Lookahead coupling: does next_item_size divide into post_residual nicely?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0; // exact next-item match
        } else if next_item_size <= pr {
            let frac = next_item_size as f64 / pr as f64;
            score -= 10.0 * frac; // better use of remaining space
        } else {
            // next item won't fit here; penalize wasting large residuals
            score += 0.05 * (next_item_size - pr) as f64;
        }
        // Harmonic pairing: item_size + next_item_size near capacity
        let pair = item_size as f64 + next_item_size as f64;
        if (pair - cap).abs() < 5.0 {
            score -= 8.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only open a new bin if current residuals are fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual - cap * 0.5).abs();
        // prefer new bin when open bins are half-empty (fragmented) and many are open
        score = cap * 0.75 + fragmentation * 0.3 + open_bins_count as f64 * 0.5 - progress * 10.0;
        if pr == bin_capacity && next_item_size > 0 && next_item_size >= 50 {
            score -= 15.0; // large item with lookahead: fresh bin ok
        }
    }

    // Mild preference for tighter bins overall relative to mean residual.
    score -= 0.1 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is ideal: strong reward.
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // Dead-space penalty: small unusable gaps are worst.
        // Treat gaps below the minimum plausible item size as dead space.
        let dead = (20u32).saturating_sub(post_residual) as f64;
        score += dead * dead * 0.35;

        // Moderate gaps that can't fit the lookahead item are also penalized.
        if next_item_size > 0 && post_residual < next_item_size {
            score += 12.0 + 0.25 * (next_item_size - post_residual) as f64;
        } else if next_item_size > 0 {
            // Reward bins that can still take the next item.
            score -= 6.0;
        }
    }

    // New-bin candidate: prefer opening a new bin only when fits are poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 25.0;
        // If this item is a last-chance fit, strongly prefer using the open bin.
        if fitting_bins_count == 1 {
            score += 40.0;
        }
        // More open bins => less eager to open another.
        score += 3.0 * open_bins_count as f64;
        // Early in stream, opening bins is cheaper (builds a pool).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 15.0 * (1.0 - progress);
    } else {
        // Reward using existing bins, more so when many are open.
        score -= 2.0 * open_bins_count as f64;
        // Last-chance bin: strong reward to avoid opening a new bin.
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
        // Prefer bins tighter than average (better fit quality).
        score -= 0.5 * (mean_residual - bin_residual as f64);
    }

    // Waste ratio: fraction of the used space that is wasted.
    if item_size > 0 {
        let waste_frac = post_residual as f64 / bin_capacity as f64;
        score += 10.0 * waste_frac;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong base preference for tight fits (small post_residual).
    score += (post_residual as f64 / bin_capacity as f64) * 40.0;

    // 2-step lookahead: reward exact match of post_residual with next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if post_residual >= next_item_size {
            let gap = pr - nxt;
            // Perfect chain fit: big reward.
            if gap == 0.0 {
                score -= 60.0;
            } else {
                // Penalize leftover after the chain fit, scaled by gap size.
                score += (gap / bin_capacity as f64) * 30.0;
            }
        } else {
            // Next item cannot follow; penalize proportionally to how close we missed.
            score += (nxt - pr) * 0.35;
        }
    } else {
        // Last item: just minimize post_residual.
        score += 10.0;
    }

    // Relative-to-mean term: prefer bins whose residual deviates favorably.
    let res = bin_residual as f64;
    score += (res - mean_residual) * 0.25;

    // Last-chance bin: strong reward to use it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Slight preference to fill many open bins when few remain.
    if open_bins_count > 0 {
        score -= 1.0 / open_bins_count as f64;
    }

    // Mild progression term: later in stream, be slightly more conservative.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 2.0;

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // Penalize opening a new bin mildly; it competes via post_residual (=capacity).
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Lookahead: reward bins where the next item also fits snugly (k=2 chaining).
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_slack = (post_residual - next_item_size) as f64;
        score -= 2.5 - chain_slack * 0.04; // tighter chain => bigger reward
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count <= 1 && bin_residual != bin_capacity {
        score -= 6.0;
    }

    // Near-perfect closure bonus: leaving almost nothing behind.
    if post_residual < 10 {
        score -= 8.0;
    } else if post_residual < 20 {
        score -= 3.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless the item
    // is large (poor fit likely elsewhere) or late in the stream.
    if bin_residual == bin_capacity {
        let t = step_index as f64 / (total_items.max(1) as f64);
        let mut new_bin_penalty = 14.0 - item_size as f64 * 0.12 - t * 5.0;
        if open_bins_count == 0 {
            new_bin_penalty -= 30.0; // must open a bin
        }
        if mean_residual > 0.0 && item_size as f64 > mean_residual {
            new_bin_penalty -= 6.0; // item bigger than typical residual -> new bin attractive
        }
        score += new_bin_penalty.max(-30.0);
    }

    // Mild preference for bins whose residual is close to the mean (balanced packing).
    score += (bin_residual as f64 - mean_residual).abs() * 0.02;

    // Small time-horizon modulation: slightly greedier early, more conservative late.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (post_residual as f64) * 0.03;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual

    // Base: post residual, mildly non-linear in progress
    let mut score = pr * (1.0 + 0.5 * progress * (1.0 - x));

    // Polynomial coupling: penalize large dead space, more so late in stream
    score += 40.0 * x * x * (0.5 + progress);

    // Reward tight fits
    score -= 20.0 * (1.0 - x) * (1.0 - x) * (1.0 + progress);

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening new bins unless current bin would be wasted
    if bin_residual == bin_capacity {
        // attractive if post residual is small relative to next item
        let nxt = next_item_size as f64;
        if nxt > 0.0 && pr >= nxt {
            score -= 15.0 + 10.0 * (1.0 - pr / nxt.max(1.0).min(cap));
        } else {
            score += 25.0 * (0.5 + progress);
        }
    } else if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        // leaving room for the next item is good
        score -= 8.0;
    }

    // Discourage spreading across too many bins with high mean residual
    score += 0.02 * open_bins_count as f64 * (mean_residual / cap).powi(2);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near 0 is ideal.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // Harmonic class of post_residual: dead space is only "reusable" if it
    // can host a future item. Classify residual into modulo buckets of 10
    // (item sizes 1..100, capacity 100 -> decade classes).
    let decade = (post_residual / 10) as f64;
    let rem = (post_residual % 10) as f64;
    // Residuals that are multiples of 10 are more likely reusable; reward them.
    if rem == 0.0 {
        score -= 8.0 + 2.0 * (decade.min(5.0));
    } else {
        // Penalize small unusable remainders (dead space).
        score += rem * 0.35;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // this placement is doubly good.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size < post_residual {
            let slack = post_residual - next_item_size;
            if slack <= 5 {
                score -= 18.0;
            } else {
                score += slack as f64 * 0.12;
            }
        } else {
            // Next item cannot use this bin's leftover: mild penalty for
            // large leftovers that strand the lookahead.
            score += 3.0;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits,
    // avoiding a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        // Among many candidates, prefer the fullest (smallest residual) more.
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when existing fits are poor
        // (post_residual large) or nothing else fits well.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Base cost of a new bin: high, but decreases late in the stream
        // when leftover open bins are unlikely to be filled anyway.
        let base = 55.0 - 25.0 * progress;
        // If this bin is the only fitter, opening a bin is neutral-ish.
        let escape = if fitting_bins_count <= 1 { 25.0 } else { 0.0 };
        score = base + escape + (item_size as f64) * 0.1;
        // If the next item is large, opening a fresh bin preserves space.
        if next_item_size > bin_capacity / 2 {
            score -= 15.0;
        }
    }

    // Mild global pressure: many open bins with high mean residual ->
    // encourage filling existing bins rather than spreading.
    if open_bins_count > 4 && mean_residual > 30.0 {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins whose post_residual is very small.
    if post_residual <= 2 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // Strict dead space avoidance: penalize small unusable gaps that no
    // realistic item can fill (gap too small relative to capacity).
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * 6.0;
    }

    // Reward bins whose residual exactly matches item_size (perfect fill).
    if post_residual == 0 {
        score -= 80.0;
    }

    // Lookahead coupling: if the next item fits into the post_residual,
    // reward this bin; if next item leaves a bad gap, penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 18.0 + 0.25 * next_item_size as f64;
        } else {
            let gap = next_item_size - post_residual;
            if gap <= 10 {
                score += 10.0;
            }
        }
    }

    // Open bins pressure: discourage spreading across many bins when
    // mean residual is already large.
    let pressure = open_bins_count as f64 * (mean_residual / bin_capacity as f64);
    score += pressure * 4.0;

    // Last-chance bonus: if this is the only bin that fits, strongly favor it.
    if fitting_bins_count == 1 {
        score -= 50.0;
    }

    // New-bin candidate: make opening a new bin unattractive unless the
    // current bin would leave a large dead gap or is a bad fit overall.
    if bin_residual == bin_capacity {
        score += 30.0 + 0.5 * item_size as f64;
        if fitting_bins_count == 0 {
            score -= 45.0; // no existing bin fits: opening new bin is fine
        }
        if item_size >= 60 {
            score -= 25.0; // large items start fresh bins reasonably
        }
    }

    // Stream progression: early on, be more willing to open bins (spread);
    // later, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 5.0 - progress * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact 2-step lookahead match: item + next item fill bin perfectly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // Penalize leftover after a hypothetical next-item placement; small slack is ok.
            score += slack * 0.5;
        } else {
            // Next item cannot follow into this bin; dead space penalty grows with gap.
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.35;
        }
    } else {
        // Last item: prefer tightest fit only.
        score += 0.0;
    }

    // Reward bins whose residual is already below mean (consolidating fragmented space).
    let resid = post_residual as f64;
    if resid < mean_residual {
        score -= (mean_residual - resid) * 0.25;
    } else {
        score += (resid - mean_residual) * 0.15;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Mild pressure to fill bins as stream progresses (avoid leaving many near-empty bins).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0;

    // New-bin candidate: only attractive if no open bin fits well; make it slightly worse
    // than a decent existing fit but better than a terrible one.
    if bin_residual == bin_capacity {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor small post_residual (best-fit core).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Perfect fit gets a large bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item can use this bin's post-residual,
    // reward; otherwise penalize leaving a gap that matches nothing.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            score += 4.0 * (1.0 - post_residual as f64 / (next_item_size.max(1) as f64));
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: open a new bin only when existing fits are poor.
    if bin_residual == bin_capacity {
        let waste_ratio = post_residual as f64 / bin_capacity as f64;
        score += 10.0
            + 20.0 * waste_ratio
            + 0.05 * open_bins_count as f64
            + (1.0 - (step_index as f64 / total_items.max(1) as f64)) * 5.0;
    }

    // Penalize bins whose residual deviates far below the mean (fragmented bins).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Late in the stream, consolidate: prefer filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 6.0 * progress * (bin_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with non-linear polynomial shaping over stream progress.
    // Early on, prefer leaving large residuals (favor bins with big post_residual);
    // late in stream, prefer tight fits (penalize large post_residual).
    let progress_coupling = 1.0 + 2.0 * progress * (1.0 - progress) * 4.0; // smooth bump peaking mid-stream
    let mut score = pr * (0.5 + progress) + progress_coupling * norm_pr * norm_pr * cap * 0.5;

    // Non-linear reward for near-perfect fits (post_residual small polynomially).
    let tightness = (1.0 - norm_pr).powi(4);
    score -= tightness * cap * (0.6 + 0.8 * progress);

    // Lookahead coupling: reward if next item fits into post_residual (smooth polynomial).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fit_margin = (pr - nx) / cap;
        if fit_margin >= 0.0 {
            score -= (1.0 - fit_margin).powi(3) * cap * 0.8;
        } else {
            score += (-fit_margin).powi(2) * cap * 0.3;
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= cap * (1.2 + progress);
    }

    // Penalize bins whose residual is far from mean residual (fragmentation signal),
    // scaled non-linearly by number of open bins.
    let dev = (pr - mean_residual).abs() / cap;
    score += dev * dev * cap * (open_bins_count.min(20) as f64).sqrt() * 0.15;

    // New-bin candidate (empty bin): make it moderately attractive only when
    // open bins would leave very bad fits, and early in the stream.
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count <= 1 { 1.0 } else { 0.0 };
        score = pr * (0.5 + progress)
            + cap * 0.9
            - cap * 1.5 * (1.0 - progress).powi(2) * scarcity;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: residues divisible by small
    // "harmonic" denominators (2,4,5,10) are more reusable by future items.
    let pr = post_residual;
    let harmonic_bonus = if pr == 0 {
        60.0 // perfect fit: huge reward
    } else if pr % 10 == 0 {
        25.0
    } else if pr % 5 == 0 {
        15.0
    } else if pr % 4 == 0 {
        10.0
    } else if pr % 2 == 0 {
        5.0
    } else {
        0.0
    };
    score -= harmonic_bonus;

    // Dead-space penalty: tiny unusable leftovers (1..=3) are wasted space.
    if pr > 0 && pr < 4 {
        score += 18.0;
    }

    // Lookahead coupling: does next_item_size fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Next item fits here: strong reward, scaled by how tight the
            // two-item packing is (integer division on the pair).
            let pair_waste = pr - next_item_size;
            score -= 20.0 - (pair_waste as f64).min(20.0);
            if pair_waste % 10 == 0 { score -= 6.0; }
        } else {
            // Next item cannot follow into this bin: mild penalty, worse
            // when the leftover is small-but-nonzero (dead end).
            let gap = (next_item_size - pr) as f64;
            score += (gap / 20.0).min(8.0);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive
    // when no open bin offers a decent fit. Penalize the empty-bin call
    // proportionally to how many bins already fit the item, but relax it
    // when the item is large relative to capacity (hard to place later).
    if bin_residual == bin_capacity {
        let fit_pressure = if fitting_bins_count == 0 { 0.0 } else { 35.0 + 10.0 * fitting_bins_count as f64 };
        score += fit_pressure;
        // Large items benefit from a fresh bin; small items should reuse.
        let size_frac = item_size as f64 / bin_capacity as f64;
        if size_frac > 0.6 {
            score -= 25.0 * (size_frac - 0.6) / 0.4;
        } else {
            score += 12.0 * (0.6 - size_frac) / 0.6;
        }
    }

    // Prefer filling bins that are already mostly full (low residual):
    // best-fit bias scaled by current fill fraction.
    let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 10.0 * fill;

    // Mild pressure to consolidate: many open bins with high mean residual
    // suggests fragmentation; reward placements into low-residual bins.
    score += 0.05 * mean_residual - 0.05 * bin_residual as f64;

    // Late-stream tightening: as the stream progresses, be greedier about
    // exact fits and less willing to spread across bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * progress * harmonic_bonus / 60.0;

    // Modulo threshold on item size: items in "harmonic" classes of 25/50
    // pair well with complementary residuals; slight reward.
    if (item_size % 25 == 0) && (bin_residual % 25 == 0) {
        score -= 7.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64) / 10.0;
    }
    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Reward tight fits relative to residual.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * tightness;

    // Open bins pressure: discourage spreading when many bins already open.
    score += 2.0 * open_bins_count as f64;

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin, unless current item is huge
    // relative to all residuals (poor fits elsewhere) or lookahead pairs well.
    if bin_residual == bin_capacity {
        score += 45.0;
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 15.0; // new bin can host a pair
        }
        if item_size >= 60 {
            score -= 30.0; // big items prefer fresh bins
        }
    }

    // Lookahead synergy: penalize leaving a residual that only slightly misses
    // the next item, reward residuals that exactly fit the next item.
    if next_item_size > 0 {
        if post_residual as u32 == next_item_size {
            score -= 35.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        }
    }

    // Mean residual coupling: prefer bins deviating below mean (consolidate small gaps).
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Mild stream-progression urgency: late in the stream, favor tighter packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

