pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic bonus for small post-residual.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tight * tight;

    // Penalize post-residual that is small but unusable for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward if next item fits the post-residual exactly or well.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size < post_residual {
            score -= 20.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item cannot use leftover; penalize proportionally.
            score += 10.0 * ((next_item_size - post_residual) as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Global pressure: when many bins are open, prefer filling existing ones.
    let pressure = (open_bins_count as f64 / (open_bins_count as f64 + 5.0)) * (mean_residual / bin_capacity as f64);
    score -= 30.0 * pressure * tight;

    // Time horizon: early in stream, be pickier (penalize mediocre fits);
    // late in stream, accept good-enough fits to consolidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 15.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: baseline score so it only wins when fits are bad.
    if bin_residual == bin_capacity {
        score = 55.0 + 20.0 * (1.0 - progress);
        // If the only fitting option is terrible, opening a new bin is fine.
        if fitting_bins_count == 1 {
            score -= 10.0;
        }
        // Late in the stream, discourage opening extra bins.
        score -= 25.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress.
    let poly = norm_pr * (1.0 + progress * norm_pr + (1.0 - progress) * norm_pr * norm_pr);
    let mut score = poly * cap;

    // Reward tight fits (small post_residual), more strongly later in stream.
    let tight = 1.0 - norm_pr;
    score -= tight * tight * (10.0 + 40.0 * progress);

    // Penalize dead space that next item cannot use.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            score += (nxt - pr) * (1.0 + progress);
        } else {
            score -= (pr - nxt).min(pr) * 0.3 * (1.0 - progress);
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0 + 25.0 * progress;
    }

    // Mild penalty for spreading across many open bins when mean residual is high.
    score += (open_bins_count as f64).ln() * (mean_residual - pr).abs() * 0.05;

    // New-bin candidate: penalize slightly so it is only chosen when fits are bad.
    if bin_residual == bin_capacity {
        score += 15.0 + 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residuals near "useful" sizes are preferred.
    // Useful residual classes: 0 (perfect), small multiples that match common item sizes.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit
    } else if pr < 10 {
        score -= 40.0; // near-perfect, dead space minimal
    } else {
        // penalize residuals in "dead zones" that few item sizes can use
        let cls = pr / 10; // integer division threshold class 1..10
        match cls {
            1 => score -= 25.0, // 10..19: almost any item fits
            2 => score -= 12.0,
            3 => score -= 4.0,
            4 => score += 2.0,
            5 => score += 6.0,
            6 => score += 4.0,
            7 => score += 0.0,
            8 => score -= 2.0,
            9 => score -= 5.0, // 90..99: nearly empty bin, flexible
            _ => score -= 10.0,
        }
    }

    // Lookahead coupling: reward residuals that exactly or nearly fit next item.
    if next_item_size > 0 && next_item_size <= pr {
        let slack = pr - next_item_size;
        if slack == 0 {
            score -= 45.0;
        } else if slack <= 5 {
            score -= 25.0;
        } else {
            score -= (10.0_f64.min(15.0 / (1.0 + slack as f64 / 20.0)));
        }
    } else if next_item_size > pr {
        // next item won't fit here; mild penalty scaled by how badly
        score += ((next_item_size - pr) as f64).min(30.0) * 0.3;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when existing fit is terrible.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score = 55.0 + (open_bins_count as f64).sqrt() * 4.0;
        // allow early stream to open bins more freely
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 15.0;
        // if next item is huge, a fresh bin is attractive
        if next_item_size >= 70 {
            score -= 20.0;
        }
    }

    // Prefer bins tighter than the mean residual (compactness pressure).
    score += (mean_residual - bin_residual as f64) * 0.15;

    // Small tie-breaker: prefer fewer open bins.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

