    // New-bin candidate: keep it slightly unattractive unless residuals are poor
    if bin_residual == bin_capacity {
        score += 3.0 - 2.5 * progress - 0.02 * mean_residual;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead-space quality via integer division buckets
    let post = post_residual as u32;
    let class = post / 10; // 0..10 harmonic classes
    match class {
        0 => score -= 12.0,           // near-perfect fit
        1 => score -= 6.0,            // excellent
        2 => score -= 3.0,            // good (fits items 10..20)
        3 | 4 => score -= 1.0,        // usable
        5 | 6 => { /* neutral: mid residuals */ }
        7 | 8 => score += 2.0,        // awkward dead space
        _ => score += 4.0,            // large waste in an open bin
    }

    // Modulo-5 residue: residuals divisible by 5 pair well with typical item sizes
    if post % 5 == 0 {
        score -= 1.5;
    }
    if post % 2 == 0 {
        score -= 0.5;
    }

    // Tightness reward: fraction of bin consumed
    let fill = (bin_capacity - post_residual) as f64 / cap;
    score -= 10.0 * fill * fill;

    // Lookahead coupling: does post_residual exactly fit next item?
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post as f64) >= nxt {
            let slack = post as f64 - nxt;
            if slack <= 2.0 {
                score -= 8.0; // perfect chaining
            } else if slack <= 10.0 {
                score -= 3.0;
            } else {
                score += slack / 20.0;
            }
        } else {
            // next item cannot fit here; leftover is dead until later
            score += 1.0 + (nxt - post as f64) / 40.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when current fit is terrible or many bins open with high mean residual
    if bin_residual == bin_capacity {
        let bad_fit = post_residual as f64 > cap * 0.4; // would leave >40% empty
        let pressure = mean_residual / cap;
        let mut nb = 5.0;
        if bad_fit { nb -= 6.0; }
        if open_bins_count == 0 { nb -= 20.0; }
        if pressure > 0.5 { nb -= 2.0 * (pressure - 0.5); }
        if fitting_bins_count == 0 { nb -= 10.0; }
        // early stream: prefer consolidating into few bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        nb += 4.0 * (1.0 - progress);
        score += nb;
    }

    // Slight penalty for proliferating open bins when this bin is roomy
    if open_bins_count > 4 && post_residual as f64 > mean_residual {
        score += 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // later are heavily penalized (items range 1..100, so treat < 12 as dead).
    if post_residual > 0 {
        if post_residual < 12 {
            score += 60.0 * (1.0 - post_residual as f64 / 12.0);
        }
    } else {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Reward tight fits relative to bin residual (waste ratio).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fit_ratio;

    // Open-bin pressure: with many open bins, prefer filling existing ones;
    // opening yet another bin dilutes capacity utilization.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln() * (0.5 + progress);
    score += pressure * 3.0;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits into post_residual, reward
    // this placement (creates a useful gap); otherwise penalize leaving a
    // gap that the next item cannot use.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 8.0;
        }
    }

    // Mean-residual coupling: placing into a bin whose residual deviates
    // favorably from the mean (large residual) is preferred.
    score -= 0.05 * (bin_residual as f64 - mean_residual);

    // New-bin candidate logic: an empty bin is only attractive when the
    // current item is large and existing residuals are small.
    if bin_residual == bin_capacity {
        let desperation = (item_size as f64 / bin_capacity as f64)
            * (1.0 - mean_residual / bin_capacity as f64).max(0.0);
        score += 18.0 - 30.0 * desperation;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    }

    // 2-step lookahead: strongly reward bins whose residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // Perfect chain match is excellent; larger slack is progressively less useful.
            score -= 120.0 - slack.min(90.0);
        } else {
            // Next item won't fit here; penalize wasted residual proportional to gap.
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.8;
        }
    }

    // Penalize large residual waste relative to mean residual of open bins.
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.5;
    } else {
        score -= (mean_residual - post_residual as f64) * 0.3;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // New-bin candidate: only attractive when no good existing option exists.
    if bin_residual == bin_capacity {
        let base = 90.0;
        // Discourage opening bins early in the stream or when many bins already open.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let penalty = base + (open_bins_count as f64) * 4.0 + (1.0 - progress) * 20.0;
        // If next item is huge, a fresh bin is more reasonable.
        let relief = if next_item_size > 60 { 40.0 } else { 0.0 };
        score += penalty - relief;
    }

    // Small bonus for tight fits normalized by capacity.
    score += (post_residual as f64 / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: quadratic penalty on wasted space relative to capacity.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 12.0 * tightness * tightness;

    // Lookahead: reward if the next item can chain into the post residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Chain bonus proportional to how well next item fills the leftover.
            let chain_fill = next_item_size as f64 / post_residual as f64;
            score -= 6.0 * chain_fill;
        } else {
            // Post residual too small for next item: mild dead-space penalty.
            score += 2.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, reward using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // Penalize opening a brand-new bin when decent alternatives exist,
    // unless the item fits badly everywhere (post_residual is huge in that case anyway).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let avg_open = mean_residual / open_bins_count.max(1) as f64;
        // If mean residual across open bins can't comfortably hold the item,
        // opening a new bin is more acceptable; otherwise penalize.
        let avg_post = avg_open - item_size as f64;
        if avg_post >= 0.0 {
            score += 20.0 - 10.0 * progress;
        } else {
            score += 4.0;
        }
        // Early in the stream, opening bins is cheaper; late, reuse is critical.
        score += 6.0 * (1.0 - progress);
    }

    // Mild bonus for reusing bins that are already quite full (consolidation).
    let fill_ratio = 1.0 - bin_residual as f64 / bin_capacity as f64;
    if bin_residual < bin_capacity {
        score -= 4.0 * fill_ratio * fill_ratio;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr;

    // Smooth non-linear coupling: dead space penalized more as stream progresses
    score += 60.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits (small post_residual) with a smooth saturating term
    score -= 40.0 * (-norm_pr * 6.0).exp() * (1.0 - progress);

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 55.0 * (1.0 - progress * 0.5);
    }

    // Lookahead: reward leaving space compatible with the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let diff = (pr - nx).abs();
        let fit_next = if pr >= nx { 1.0 } else { 0.0 };
        score += 0.35 * diff;
        score -= 25.0 * fit_next * (-((pr - nx) / cap).abs() * 8.0).exp();
    } else {
        // Last item: minimize leftover aggressively
        score += 0.8 * pr;
    }

    // Slight preference for bins already below mean residual (consolidation)
    let dev = (pr - mean_residual) / cap;
    score += 12.0 * dev * dev;

    // Mild penalty for spreading across many open bins early on
    score += 1.5 * open_bins_count as f64 * (1.0 - progress) * 0.1;

    // New-bin candidate: make it attractive only when no open bin fits well
    if bin_residual == bin_capacity {
        score = 0.9 * cap + 0.5 * pr;
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
        if next_item_size > 0 && next_item_size as f64 <= pr {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual into residue classes mod 10.
    // Small residues (tight fits) are rewarded; mid-range residues (10..40)
    // are "dead zones" unlikely to be filled by future items.
    let post_class = post_residual % 10;
    let post_decade = post_residual / 10;

    // Reward exact-tight fits (post_residual in 0..10).
    if post_residual < 10 {
        score -= 25.0 + (10 - post_residual) as f64 * 2.0;
    } else if post_residual <= 30 {
        // Dead zone: penalize leaving 10..30 free space.
        score += (30 - post_residual) as f64 * 1.5;
    } else if post_residual <= 50 {
        // Moderately reusable space.
        score += 5.0;
    }

    // Decade granularity: even decades of residual are more "usable" targets.
    if post_decade % 2 == 0 && post_residual > 0 {
        score -= 4.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // Next item fits, but how tightly?
            let gap = post_residual - next_item_size;
            if gap < 10 {
                score -= 20.0;
            } else {
                score -= 10.0 - gap as f64 * 0.1;
            }
        } else {
            // Next item will NOT fit here: penalize bins that block the lookahead.
            let overflow = next_item_size - post_residual;
            score += overflow as f64 * 0.3;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // Among many candidates, prefer tighter residual spread.
        score += (fitting_bins_count as f64).ln() * 3.0;
    }

    // Prefer bins below mean residual (fills emptier bins first,
    // keeping tight bins for tight items).
    if (bin_residual as f64) > mean_residual {
        score += (bin_residual as f64 - mean_residual) * 0.4;
    } else {
        score -= (mean_residual - bin_residual as f64) * 0.2;
    }

    // New-bin candidate: opening a fresh bin is only attractive when
    // no good fit exists elsewhere. Penalize it by default, scaled by
    // how many open bins could fit the item and stream progress.
    if bin_residual == bin_capacity {
        let base_penalty = 35.0;
        let fit_penalty = fitting_bins_count as f64 * 12.0;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Late in the stream, closing out bins is more valuable.
        let late_discount = progress * 10.0;
        score = base_penalty + fit_penalty - late_discount;
        // If the item is large, a fresh bin wastes less capacity.
        if item_size > bin_capacity / 2 {
            score -= 8.0;
        }
    }

    // Mild normalization by capacity fraction of the item itself.
    score -= item_size as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 100.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / (bin_residual.max(1) as f64);
    score -= 20.0 * tightness;

    // Penalize leaving a gap that could still fit a typical item but is awkward.
    if post_residual >= 10 && post_residual < 40 {
        score += 0.4 * (40 - post_residual) as f64;
    }

    // Lookahead: if next item fits exactly in the post residual, reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 50.0;
        } else if post_residual >= next_item_size {
            score -= 5.0;
        } else {
            // next item cannot use this gap: mild penalty scaled by gap size
            score += 0.2 * post_residual as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones,
    // but with few open bins allow consolidation.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure; also penalize since
        // residual 100 is never "wasted" immediately.
        score += 35.0 + pressure;
        // Allow new bin if all existing fits are terrible (post_residual tiny).
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    }

    // Slight preference for bins below mean residual (consolidate emptier bins' space).
    score += 0.1 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact 2-step lookahead match: bin closes perfectly after next item.
    if next_item_size > 0 {
        let chain = post_residual as i64 - next_item_size as i64;
        if chain == 0 {
            score -= 200.0; // perfect: post_residual fits next item exactly
        } else if chain > 0 && chain <= 10 {
            score -= 120.0 - (chain as f64) * 8.0; // near-exact chain
        } else if chain < 0 {
            // next item cannot fit here; mild penalty scaled by overflow
            score += (chain.unsigned_abs() as f64).min(60.0) * 0.5;
        } else {
            // chain positive but large: dead space after next item
            score += (chain as f64) * 0.8;
        }
    } else {
        // Last item: minimize leftover directly (already base score).
        if post_residual == 0 {
            score -= 150.0;
        }
    }

    // Prefer bins whose residual is below mean residual (tight fits), penalize loose bins.
    let diff = bin_residual as f64 - mean_residual;
    score += diff * 0.35;

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 90.0;
    }

    // New-bin candidate: only attractive when no open bin is a good home,
    // i.e. penalize opening new bins when there are fitting bins and stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fitting_pressure = if fitting_bins_count > 0 {
            (fitting_bins_count as f64).min(5.0)
        } else {
            0.0
        };
        score += 60.0 + fitting_pressure * 40.0 + progress * 30.0;
        // If item is large relative to capacity, a fresh bin is less bad.
        score -= (item_size as f64 / bin_capacity as f64) * 40.0;
        // Lookahead: a fresh bin can host both current and next item.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 70.0;
        }
    }

    // Slight preference for filling bins with small residuals (tight packing).
    score += (bin_residual as f64 / bin_capacity as f64) * 5.0;

    // Encourage consolidation when many bins are open.
    score -= (open_bins_count.min(20) as f64) * 1.5 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits: residual wasted after placement, quadratic penalty.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 2.5 * fit_ratio * post_residual as f64;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 80.0;
        } else if post_residual >= next_item_size {
            score -= 0.5 * (post_residual - next_item_size) as f64;
        } else {
            // next item won't fit here; penalize leaving awkward space
            score += 0.3 * (next_item_size - post_residual) as f64;
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Penalize opening a new bin when open bins exist and can fit the item.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        if open_bins_count > 0 {
            // New-bin candidate: base penalty, softened if it's genuinely a bad fit elsewhere.
            let waste = post_residual as f64; // = capacity - item_size
            score += 55.0 - 0.15 * waste + 10.0 * progress;
            // If many bins fit the item, opening a new one is wasteful.
            if fitting_bins_count > 2 {
                score += 25.0;
            }
        }
        // Late in stream, prefer consolidating into existing bins.
        score += 5.0 * mean_residual / bin_capacity as f64;
    }

    // Prefer filling bins with larger residuals less when mean residual is low (bins already tight).
    if mean_residual < post_residual as f64 {
        score += 0.2 * (post_residual as f64 - mean_residual);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let prn = pr / cap; // normalized post residual in [0,1]
    let x = progress;
    let coupling = prn * prn * (1.0 - x) - prn * x * x + 2.0 * prn * prn * prn * x;
    score += 12.0 * coupling;

    // Penalize small dead space more strongly as stream progresses (wasted capacity late)
    let dead = (prn - 0.5) * (prn - 0.5);
    score += 8.0 * dead * (0.5 + x);

    // Reward tight fits (small post residual) with a smooth saturating term
    score -= 15.0 * (1.0 - prn) * (1.0 - prn) * (1.0 - x * 0.5);

    // Lookahead: bonus if next item fits in post residual
    if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        score -= 6.0 * (1.0 - x * 0.5);
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0 * (1.0 - x);
    }

    // New-bin candidate: penalize opening a bin when decent fits exist
    if bin_residual == bin_capacity {
        score += 5.0 + 20.0 * (1.0 - x) + (open_bins_count as f64) * 0.5;
    } else {
        // Slight preference for fuller bins relative to mean residual
        score -= (mean_residual - pr) * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class: how well post_residual decomposes into likely future item sizes
    let pr = post_residual;
    let pr_f = pr as f64;
    // Small dead space is bad (unusable); medium dead space may be reusable
    if pr > 0 {
        let dead_penalty = match pr {
            1..=5 => 40.0,
            6..=15 => 20.0,
            16..=30 => 8.0,
            _ => 0.0,
        };
        score += dead_penalty;
    }

    // Lookahead: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 500.0;
        } else if next_item_size <= pr {
            // reward proportional to how much of the residual the next item consumes
            let fill = next_item_size as f64 / pr_f;
            score -= 60.0 * fill;
        } else {
            // next item cannot use this residual; penalize residual size
            score += 10.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // Tightness reward: prefer bins where item fills a large fraction of residual
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 50.0 * tightness;

    // Prefer bins with residual below mean (consolidate near-full bins)
    score -= (mean_residual - pr_f) * 0.5;

    // Modulo / harmonic class logic on post_residual: residuals divisible by
    // common item sizes (10, 20, 25, 50) are more reusable
    if pr > 0 {
        let mut harmonic_bonus = 0.0;
        for m in [10u32, 20, 25, 50].iter() {
            if pr % m == 0 {
                harmonic_bonus += 15.0;
            }
        }
        score -= harmonic_bonus;
        // integer-division threshold: residual in a "quarter class" is predictable
        let q = pr / 25;
        score -= q as f64 * 3.0;
    }

    // New-bin candidate: only open a new bin when no open bin is a good fit
    if bin_residual == bin_capacity {
        // base penalty so open bins are preferred unless they're poor
        score += 120.0;
        // early in stream, opening bins is cheaper
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 80.0 * (1.0 - progress);
        // if many bins fit already, discourage opening another
        if fitting_bins_count > 0 {
            score += 60.0 * fitting_bins_count as f64;
        }
    }

    // mild preference for fewer open bins when placing into an existing bin
    score -= 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // --- Strict dead-space avoidance ---
    // Small unusable gaps (< 10) are heavily penalized; the smaller the gap,
    // the worse it is (it can never be filled by items >= 10 later... or by
    // most items at all), so punish proportionally to its uselessness.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0 - 2.5 * post_residual as f64;
    }
    // Medium dead space (10..20) is risky too, mild penalty.
    else if post_residual >= 10 && post_residual < 20 {
        score += 4.0 - 0.2 * post_residual as f64;
    }

    // --- Lookahead coupling (k=2) ---
    // If the next item fits into the post-residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 5.0 + 0.05 * next_item_size as f64;
    } else if next_item_size > post_residual && post_residual > 0 {
        // Post-residual too small for the lookahead item: slight penalty
        // unless it is already dead space (handled above).
        score += 1.5;
    }

    // --- New-bin candidate handling ---
    if is_new_bin {
        // Prefer existing bins when any open bin fits; escalate with the
        // number of fitting alternatives available.
        if fitting_bins_count > 0 {
            score += 10.0 + 2.0 * fitting_bins_count as f64 + 0.2 * open_bins_count as f64;
        }
        // Opening a new bin is more acceptable early in the stream when the
        // item is large (few future chances to pair it).
        if item_size > 60 {
            score -= 6.0 * (1.0 - progress);
        }
    } else {
        // --- Open-bins pressure: reward using existing bins, especially ---
        // --- when this is the last chance before opening a new bin.      ---
        if fitting_bins_count == 1 {
            score -= 7.0;
        }
        // Slight preference for bins with lower residual (tighter, fuller bins)
        // to consolidate packing.
        score += 0.05 * mean_residual;
        score -= 0.1 * open_bins_count as f64;
    }

    // Reward placing large items (hard to place later) into any fitting bin.
    score -= 0.08 * item_size as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = 0.0;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Penalize wasted residual relative to item size (dead space ratio).
    let waste = post_residual as f64 / cap;
    score += 2.0 * waste * (item_size as f64 / cap);

    // Reward tight fits strongly.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    } else if post_residual <= 10 {
        score -= 6.0;
    }

    // Penalize leaving residual that no future item of size >= 10 can use well.
    if post_residual < 10 && post_residual > 0 {
        score += 8.0;
    }

    // Lookahead: if next item fits in the post residual, reward this placement.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post_residual as f64 {
            score -= 10.0 + 0.1 * (cap - nxt);
            // Bonus for exact pairing (item + next fills bin).
            if (item_size as f64 + nxt) as u32 == bin_capacity {
                score -= 15.0;
            }
        } else {
            // Next item won't fit here; slight penalty proportional to gap.
            score += 0.05 * (nxt - post_residual as f64);
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Crowd control: when many bins are open, prefer filling existing ones
    // over opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let crowd = open_bins_count as f64 / (cap * 0.5 + 1.0);
    score += crowd * (1.0 + progress);

    // Mean residual coupling: prefer bins with residual close to (or below) the mean,
    // which tends to keep a diverse residual portfolio.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.08 * dev;

    // New-bin candidate handling: empty bin gets a baseline penalty so it's
    // only chosen when no open bin scores better (poor fits everywhere).
    if bin_residual == bin_capacity {
        score = 55.0 + 0.5 * (item_size as f64 / cap) * 20.0;
        // Open a new bin early in the stream more readily (builds portfolio).
        score -= 20.0 * (1.0 - progress);
        // If next item is large and current item is small, opening fresh bin
        // preserves flexibility.
        if next_item_size as f64 > 0.5 * cap {
            score -= 8.0;
        }
        // Many fitting bins exist -> definitely don't open a new one.
        if fitting_bins_count > 1 {
            score += 15.0;
        }
    }

    // Late in the stream, tighten up: consolidate aggressively.
    score -= 5.0 * progress * (1.0 - post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear polynomial coupling: reward tight fits more strongly as stream progresses.
    let norm_pr = pr / cap;
    let poly = norm_pr * norm_pr * (1.0 + 3.0 * progress) + norm_pr * progress * progress;
    score += 2.5 * cap * poly;

    // Penalize waste relative to mean residual (dead space that likely won't be reused).
    let waste = (pr as f64 - mean_residual).max(0.0);
    score += 0.3 * waste * (0.5 + progress);

    // Reward bins whose leftover can host the next item (chaining).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 4.0 + 3.0 * (next_item_size as f64 / cap) * (1.0 + progress);
    } else if next_item_size > 0 {
        score += 2.0 * (1.0 - progress);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0 * (1.0 + progress);
    }

    // New-bin candidate: prefer opening a new bin only when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 12.0 + 10.0 * (1.0 - progress) + 0.5 * open_bins_count as f64;
        if fitting_bins_count > 0 && post_residual >= next_item_size {
            score += 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "usable" the leftover space is.
    // Residuals divisible into common item-size classes (10..80) are more valuable.
    let pr = post_residual;
    let mut class_bonus = 0.0;
    if pr == 0 {
        class_bonus -= 60.0; // perfect fit, ideal
    } else if pr >= 1 && pr <= 10 {
        class_bonus += 25.0; // tiny dead space, nearly unusable
    } else {
        // count divisors of pr in plausible item-size range (harmonic usability)
        let mut divs = 0u32;
        for d in 10..=80u32 {
            if pr % d == 0 { divs += 1; }
        }
        class_bonus -= divs as f64 * 8.0;
        // fractional capacity class of the leftover
        let frac = pr as f64 / cap;
        class_bonus += (frac * 40.0).sin().abs() * 5.0;
    }
    score += class_bonus;

    // Integer-division thresholds on post_residual
    if pr / 10 >= 5 { score -= 5.0; }        // leftover >= 50: half-capable
    if pr >= 40 && pr < 50 { score += 6.0; } // awkward gap zone

    // Lookahead coupling: if next item fits in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 30.0 + (next_item_size as f64 / cap) * 20.0;
        } else {
            score += 8.0; // forces future new bin
        }
        // modulo harmony between next item and residual
        if pr % next_item_size.max(1) == 0 && next_item_size > 0 {
            score -= 10.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: only attractive when current bins are crowded or fit is terrible
    let is_new_bin = bin_residual == bin_capacity && bin_capacity > 0;
    if is_new_bin {
        let pressure = (open_bins_count as f64) * (mean_residual / cap);
        let poor_fit = (item_size as f64 / cap) < 0.35;
        score = 55.0 - pressure * 4.0;
        if poor_fit && next_item_size > 0 && next_item_size >= bin_residual {
            score -= 20.0;
        }
        if fitting_bins_count <= 1 { score -= 30.0; }
    }

    // Mild tightness reward relative to mean residual across open bins
    if !is_new_bin {
        let tight = (bin_residual as f64 - mean_residual) / cap;
        score -= tight * 12.0;
        // slight stream-progress annealing toward consolidation
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += (1.0 - progress) * 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for likely future items are wasted.
    // Treat residuals below a "usable threshold" as dead space and penalize quadratically.
    let usable_threshold = 30.0_f64.max(next_item_size as f64);
    if (post_residual as f64) < usable_threshold {
        let deficit = usable_threshold - post_residual as f64;
        score += deficit * deficit * 0.15;
    }

    // Perfect fit is excellent.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Tight fit reward: item fills most of the bin.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 20.0;

    // Lookahead coupling: if the next item fits exactly in post_residual, strongly favor.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item cannot follow here; penalize proportionally to leftover waste.
        score += (post_residual as f64) * 0.3;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading into new/partial bins.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual.max(1.0) / 10.0);
    score += pressure * 0.5;

    // New-bin candidate handling: only attractive when open bins are crowded or fits are poor.
    if bin_residual == bin_capacity {
        let crowded = if mean_residual > 0.0 { mean_residual / bin_capacity as f64 } else { 0.0 };
        let poor_fit = (item_size as f64 / bin_capacity as f64) < 0.5;
        if crowded < 0.3 || poor_fit {
            score -= 15.0 + crowded * 20.0;
        } else {
            score += 30.0;
        }
        // Early in stream, a fresh bin is fine.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Core: prefer tight fits (small post_residual relative to capacity).
    score += 0.5 * (post_residual as f64 / cap);

    // Aggressive 2-step lookahead: reward if the next item exactly fills the post-residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if nxt <= pr {
            let slack = pr - nxt;
            score -= 4.0 * (1.0 - slack / cap);
        } else {
            // Next item cannot fit here: mild penalty for blocking potential.
            score += 0.5 * ((nxt - pr) / cap);
        }
        // Perfect chain: next item fills bin completely.
        if next_item_size == post_residual {
            score -= 3.0;
        }
    }

    // Relative to mean residual: prefer bins whose post-residual is below average
    // (concentrate waste in few bins rather than spreading it).
    let pr = post_residual as f64;
    if mean_residual > 0.0 {
        score += 0.3 * (pr - mean_residual) / cap;
    }

    // Last chance bin: strongly reward using the only bin that fits,
    // avoiding a new-bin opening.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 6.0;
    }

    // New-bin candidate: penalize opening a new bin unless current item is huge
    // and would leave a very tight fit elsewhere anyway.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 8.0 - 2.0 * item_size as f64 / 100.0 + 2.0 * progress;
        // Opening a new bin is more attractive if many bins are open already
        // (parallelism for future items).
        score -= (open_bins_count as f64).ln().max(0.0);
        // If next item is small, a fresh bin is valuable.
        if next_item_size > 0 && (next_item_size as f64) <= 0.3 * cap {
            score -= 2.0;
        }
    }

    // Penalize creating dead space that nothing (min size 1..) can use well:
    // small nonzero post_residuals are the worst.
    if post_residual > 0 && post_residual < 10 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Prefer tight fits: reward small post_residual non-linearly.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * tightness * 40.0;

    // Exact fit is excellent.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Penalize dead space that no future item (min size 1..10) can use.
    if post_residual < 10 && post_residual > 0 {
        score += 25.0; // unusable sliver
    }

    // Lookahead: reward bins whose residual can also host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 + 0.15 * next_item_size as f64;
        } else {
            // residual wasted for the next item: mild penalty scaled by waste
            score += 0.1 * (next_item_size as f64 - post_residual as f64).min(50.0);
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Many open bins with high mean residual: encourage consolidating into existing space.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if mean_residual > item_size as f64 * 1.5 && open_bins_count > 2 {
        score -= 10.0 + 5.0 * progress;
    }

    // New-bin candidate: only attractive when current bins fit poorly or are nearly full.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let poor_alternatives = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let avg_fit_quality = (mean_residual - item_size as f64).max(0.0);
        // Opening a new bin is good early or when existing bins leave large unusable gaps.
        score = 70.0
            - 40.0 * poor_alternatives
            - 0.3 * avg_fit_quality
            + 20.0 * progress
            - (open_bins_count as f64).min(10.0);
        if next_item_size > 0 && bin_capacity >= next_item_size {
            score -= 5.0;
        }
    }

    // Mild preference for fuller bins overall.
    score -= 0.2 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let fit_ratio = item_size as f64 / cap;

    // Smooth polynomial coupling: reward tight fits more as stream progresses
    let tightness = 1.0 - (pr / cap);
    score -= 12.0 * tightness.powi(2) * (0.4 + 0.6 * progress);

    // Penalize large dead space non-linearly
    score += 0.35 * (pr / cap).powi(3) * cap;

    // Last-chance bonus (smooth)
    if fitting_bins_count == 1 {
        score -= 6.0 + 10.0 * tightness;
    }

    // Lookahead: reward residuals that can host the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            score -= 5.0 * (nx / cap) * (1.0 - (pr - nx) / cap);
        } else {
            score += 2.0 * ((nx - pr) / cap);
        }
    }

    // Crowd penalty: many open bins with low mean residual -> prefer filling existing
    let crowd = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
    score -= crowd * (mean_residual / cap) * 4.0;

    // New-bin candidate: penalize opening a fresh bin unless current fit is terrible
    if bin_residual == bin_capacity {
        score += 8.0 - 14.0 * tightness * (1.0 - fit_ratio);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "usable"
    // residue classes (multiples of small divisors) are less penalized.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Penalize dead space quadratically, but reward residues that other
    // typical items could still fill.
    score += 0.35 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // Harmonic class: post_residual divisible by small numbers (2,3,4,5)
    // is more "packable" by future items -> subtract a bonus.
    let mut harmonic_bonus = 0.0;
    if post_residual > 0 {
        if post_residual % 2 == 0 { harmonic_bonus += 1.0; }
        if post_residual % 3 == 0 { harmonic_bonus += 1.0; }
        if post_residual % 5 == 0 { harmonic_bonus += 1.5; }
        if post_residual % 10 == 0 { harmonic_bonus += 2.0; }
    }
    // Bonus decays as the stream progresses (late stage: prefer exact fits).
    score -= harmonic_bonus * (1.2 - 0.7 * progress);

    // Integer-division thresholds on post_residual: classify leftover size.
    let pr_class = post_residual / 10; // 0..=10
    match pr_class {
        0 => score -= 6.0,          // near-perfect fit
        1 => score -= 3.0,          // small leftover, still useful
        2 | 3 => score -= 1.0,      // medium leftover
        4..=6 => { /* neutral: dead-ish zone */ }
        _ => score += 2.0,          // huge leftover wasted
    }

    // Lookahead coupling: if the next item exactly fits the post_residual,
    // strongly reward; if next item is close (within a harmonic band), reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 15.0;
        } else if next_item_size <= post_residual {
            let gap = post_residual - next_item_size;
            if gap <= 5 { score -= 6.0; }
            else if gap <= 10 { score -= 3.0; }
        } else {
            // next item cannot fit here anyway; slight penalty for wasting
            // this bin's capacity on the current item.
            score += 1.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    } else if fitting_bins_count > 1 {
        // Among several candidates, prefer tighter fits (already via
        // post_residual), but add mild pressure to keep bin count low.
        score -= 0.5 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Opening a new bin is only attractive when no open bin gives a good fit.
    if bin_residual == bin_capacity {
        // Base cost of consuming a fresh bin.
        score = 55.0 + 0.3 * post_residual as f64;
        // Late in the stream, opening new bins is slightly cheaper than
        // fragmenting; early, prefer filling existing bins.
        score -= 10.0 * progress;
        // If many open bins already, opening more is costly.
        score += 1.5 * open_bins_count as f64;
        // If the item fits a fresh bin with harmonic-friendly leftover,
        // reduce the new-bin cost a bit.
        if post_residual > 0 && post_residual % 10 == 0 {
            score -= 4.0;
        }
    }

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it is already "tight" -> placing here keeps fragmentation low.
    let dev = mean_residual - bin_residual as f64;
    score -= 0.25 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (below min item size ~1..10)
    // are heavily penalized since nothing can ever fill them.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    }

    // Moderate penalty for gaps that only a tiny item could use.
    if post_residual >= 10 && post_residual < 25 {
        score += 12.0;
    }

    // Reward exact or near-exact fills strongly.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward leaving a gap that exactly fits the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }

    // Open-bin pressure: penalize spreading across many bins slightly,
    // but reward using a nearly-full bin (low residual relative to capacity).
    score += open_bins_count as f64 * 0.5;

    // Last-chance bin: strongly prefer using the only bin that fits,
    // avoiding opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize mildly so it only wins when open bins fit poorly.
    if bin_residual == bin_capacity {
        score += 15.0;
    }

    // Align with mean residual: prefer bins with residual below mean (tighter bins).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Progress coupling: as stream advances, tighten packing further.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when the next item fits into the post residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // exact 2-chain match strongly favored
            let slack = (post_residual - next_item_size) as f64;
            score -= 120.0 - slack.min(120.0);
        } else {
            // next item won't fit here: penalize leftover dead space
            let dead = post_residual as f64;
            score += 0.5 * dead;
        }
    } else {
        // last item: prefer minimal waste
        score += 0.2 * post_residual as f64;
    }

    // Compare post_residual against mean residual of open bins
    if post_residual as f64 > mean_residual {
        score += 0.3 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.3 * (mean_residual - post_residual as f64);
    }

    // Last-chance bin bonus: only bin that fits the item
    if fitting_bins_count == 1 {
        score -= 200.0;
    }

    // New-bin candidate handling: only open a new bin when no open bin fits well
    if bin_residual == bin_capacity {
        // base penalty for opening a new bin
        score += 150.0;
        if fitting_bins_count == 0 {
            score -= 500.0; // no alternative: opening is fine
        } else if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            // fresh bin gives a great 2-step runway
            score -= 100.0;
        }
        // opening a bin late in the stream is more costly (less time to fill)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 100.0 * progress;
    }

    // Tightness bonus relative to bin capacity
    score -= 0.2 * (bin_capacity - post_residual) as f64;

    // Slight penalty for too many open bins
    score += 2.0 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong best-fit pull: reward tight fits (small post_residual).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 8.0 * fit_ratio * fit_ratio;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    // Lookahead: if the next item fits into the post residual, reward this bin.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
        } else if next_item_size <= bin_residual {
            // bin could take next item now but not after placing current: mild penalty
            score += 4.0;
        }
        // If next item is large and this bin would be nearly full, that's fine.
        if next_item_size > post_residual && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.05;
        }
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize opening a new bin when existing bins fit well.
    if bin_residual == bin_capacity {
        // New-bin candidate base cost.
        score += 25.0;
        // More open bins with slack -> discourage new bin.
        score += open_bins_count as f64 * 2.0;
        // If mean residual is high, existing bins have room: penalize new bin more.
        score += mean_residual * 0.3;
        // Early in stream, opening bins is fine (builds inventory); later, prefer consolidation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 20.0;
        // If no other bin fits (fitting_bins_count == 0 effectively means only new bin), allow it.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // If next item is large, a fresh bin is attractive.
        if next_item_size > 60 {
            score -= 10.0;
        }
    } else {
        // Existing bin: mild reward for using open bins, scaled by how full it already is.
        let used_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= 5.0 * used_ratio;
        // Penalize leaving a residual that is awkwardly small but nonzero (dead space).
        if post_residual > 0 && post_residual < item_size.min(30) {
            score += 6.0;
        }
    }

    // Global slack balancing: prefer bins whose residual is near the mean (keeps spread even).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    // Late-stream consolidation pressure: fewer wasted slivers.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += fit_ratio * progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let residual_norm = pr / cap;
    let fill = 1.0 - residual_norm;

    // Base cost: wasted residual, amplified quadratically as stream progresses
    let mut score = pr;
    score += progress * pr * pr / cap;

    // Reward high fill ratio with smooth cubic coupling to progress
    score -= 30.0 * fill * fill * fill * (0.5 + progress);

    // Penalize dead space that cannot fit typical future items (non-linear threshold-free)
    let dead = residual_norm * (1.0 - residual_norm);
    score += 20.0 * dead * (1.0 - fill);

    // Lookahead coupling: bonus if next item fits exactly into post residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt).abs();
        score -= 25.0 * (1.0 - gap / cap).max(0.0) * (pr >= nxt) as i32 as f64;
        score += 10.0 * (gap / cap) * (pr < nxt) as i32 as f64;
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + progress);
    }

    // Penalize proliferation of open bins when residuals are large (smooth coupling)
    let mean_norm = mean_residual / cap;
    score += 0.5 * open_bins_count as f64 * mean_norm * mean_norm;

    // New-bin candidate: only attractive when current bins fit poorly
    let is_new_bin = (bin_residual == bin_capacity) as i32 as f64;
    score += is_new_bin * (40.0 + 20.0 * progress) * (1.0 - (item_size as f64 / cap)).powi(3);
    score -= is_new_bin * 30.0 * (item_size as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base best-fit pull: prefer tight fits.
    score += (bin_residual as f64 - item_size as f64) * 0.1;

    // Harmonic class of post_residual: reward residuals in "useful" bands.
    // Residuals divisible by small classes (<=10, or in 20..=30, or >=40) are reusable.
    let pr = post_residual;
    if pr == 0 {
        score -= 30.0; // perfect fit is excellent
    } else if pr <= 10 {
        score -= 12.0; // small dead space, nearly full
    } else if pr >= 40 {
        score -= 8.0; // large residual still very usable
    } else if pr >= 20 {
        score -= 3.0; // medium band
    } else {
        score += 10.0; // awkward 11..19 band: dead-space penalty
    }

    // Modulo arithmetic on post_residual vs next_item_size:
    // reward when the next item exactly divides / fits the residual.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0; // next item perfectly consumes residual
        } else if next_item_size < pr {
            score -= (pr - next_item_size) as f64 * 0.3;
            if pr % next_item_size == 0 {
                score -= 5.0; // harmonic divisibility bonus
            }
        } else {
            score += 4.0; // next item cannot use this residual
        }
        // gcd-like harmonic check via modulo chain
        let mut a = pr;
        let mut b = next_item_size;
        while b > 0 {
            let t = a % b;
            a = b;
            b = t;
        }
        if a > 0 && a <= 5 {
            score -= 3.0; // small common divisor => harmonically compatible sizes
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad
    // or many bins are already open (spread load late in stream).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0
            - 5.0 * (fitting_bins_count == 0) as i32 as f64
            - 10.0 * progress
            - (open_bins_count as f64 * 0.05);
        // Opening a new bin is fine if this item would leave an awkward residual elsewhere.
        if pr > 10 && pr < 20 {
            score -= 12.0;
        }
    }

    // Mean residual coupling: if this bin is far below mean residual, it's a
    // straggler bin; prefer filling it to consolidate.
    let diff = mean_residual - post_residual as f64;
    if diff > 0.0 {
        score -= diff * 0.2;
    } else {
        score += (-diff) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small for the smallest
    // plausible item (1..=10) are pure waste -> heavy penalty.
    if post_residual >= 1 && post_residual <= 10 {
        score += 60.0 - 5.0 * post_residual as f64;
    }

    // Perfect / near-perfect fits are highly desirable.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Reward bins whose residual exactly matches the next item (k=2 lookahead).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 45.0;
    } else if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 10 {
        score -= 20.0;
    }
    // Penalize leaving a gap that just barely fails to host the next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }

    // Last-chance bin: only open bin that fits -> strong reward to avoid new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 55.0;
    }

    // Open-bin pressure: many open bins -> discourage opening yet another bin,
    // and slightly favor filling existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln().max(0.0) * (1.0 + progress);
    score += pressure * 4.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins already open.
        score += 25.0 + pressure * 6.0;
        // But allow a fresh bin if the item is huge and no tight fit exists.
        if item_size > 70 && open_bins_count > 0 {
            score -= 10.0;
        }
    }

    // Prefer bins with residual below the mean residual (tighter bins first).
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.5;

    // Waste-awareness: big items should go into big gaps.
    if item_size >= 50 && bin_residual < item_size + 5 {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item fits the post residual exactly-ish
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 18.0 - 0.35 * slack; // prefer post_residual ~= next_item_size
    }
    // Penalize post_residual too small to ever be useful (dead space)
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.5;
    }
    // Penalize dead space below minimum plausible item size
    if post_residual < 10 {
        score += 25.0;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 30.0;
    }

    // Relative to mean residual: prefer bins with more remaining space than average
    score -= (bin_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 22.0;
    }

    // New-bin candidate: penalize moderately so it's chosen only when fits are bad
    if bin_residual == bin_capacity {
        score += 15.0;
        // opening a new bin is more attractive early when lookahead is poor
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 8.0 * (1.0 - progress);
    }

    // Mild pressure against hoarding many open bins
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual (tight fit).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 20.0 * fit_ratio * fit_ratio;

    // Dead-space penalty: post_residual too small for the lookahead item.
    if next_item_size > 0 && post_residual < next_item_size {
        let waste = (next_item_size - post_residual) as f64;
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 6.0 * waste * (1.0 - 0.5 * progress);
    }
    // Reward: post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin when alternatives exist,
    // but allow it when open bins would leave very poor fits.
    if bin_residual == bin_capacity {
        let alt_pressure = if fitting_bins_count == 0 { 0.0 } else { 18.0 };
        let mean_gap = (mean_residual - item_size as f64).abs();
        score += 30.0 + alt_pressure - mean_gap.min(30.0);
    } else {
        // Mild reward for draining existing bins when many are open.
        score -= (open_bins_count as f64).min(10.0) * 0.5;
        // Prefer bins whose residual is close to the item (best-fit flavor).
        let tightness = (bin_residual - item_size) as f64;
        score += 0.3 * tightness;
    }

    // Late in the stream: consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 4.0 * progress * (1.0 - fit_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (0.5 + 1.5 * progress) + norm_pr * (1.0 - progress) * 0.5;
    score += poly * cap * 0.3;

    // Reward tight fits more aggressively as stream progresses
    score -= (1.0 - norm_pr) * (1.0 + progress) * 10.0;

    // Lookahead: reward residual that can hold the next item
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 8.0 + 6.0 * progress;
    } else if next_item_size > 0 {
        score += 4.0 * progress;
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Penalize opening a brand-new bin when good alternatives may exist
    if bin_residual == bin_capacity {
        score += 20.0 + 10.0 * (1.0 - progress);
        // But allow new bin if open bins are all nearly full
        if mean_residual < item_size as f64 * 0.35 {
            score -= 25.0;
        }
    }

    // Mild penalty for accumulating many open bins with large mean residual
    score += (open_bins_count as f64).ln() * mean_residual * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: quantize post_residual into capacity fractions
    let frac = post_residual as f64 / cap;
    let class = (frac * 8.0).floor() as i32; // 0..7 harmonic classes
    let class_bonus: f64 = match class {
        0 => -40.0,                    // perfect / near-perfect fit
        1 => -18.0,                    // small dead space, still usable
        2 => -6.0,
        3 => 0.0,
        4 => 6.0,
        5 => 14.0,
        6 => 24.0,
        _ => 34.0,                     // large waste
    };
    score += class_bonus;

    // Modulo arithmetic on post_residual: leftovers divisible by small units pair well
    if post_residual > 0 {
        if post_residual % 10 == 0 { score -= 12.0; }
        else if post_residual % 5 == 0 { score -= 6.0; }
        if post_residual <= 10 && post_residual > 0 { score += 25.0; } // tiny dead space penalty
    } else {
        score -= 30.0; // exact fill is ideal
    }

    // Lookahead: does the next item fit the post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // reward proportional to how snugly next item nests
            let snug = 1.0 - (post_residual - next_item_size) as f64 / cap;
            score -= 10.0 + 20.0 * snug;
        } else {
            // next item won't fit here; penalize if we leave large unusable space
            score += 8.0;
        }
        // integer-division threshold: next item in same harmonic half-class
        let a = post_residual / 25;
        let b = next_item_size / 25;
        if a == b && a > 0 { score -= 8.0; }
    } else {
        // last item: prefer exact fills aggressively
        score -= 20.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 {
        score -= 35.0;
    } else if fitting_bins_count > 1 {
        // among many candidates, prefer tighter fits
        score += 3.0 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate handling: only attractive if nothing fits well
    let is_new_bin = bin_residual == bin_capacity && item_size <= bin_capacity;
    if is_new_bin {
        let open_penalty = 55.0 + 2.0 * open_bins_count as f64;
        // opening a new bin costs more early in the stream
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = post_residual as f64 + open_penalty * (1.0 - 0.4 * progress);
        // but if the current bin would be wrecked (huge dead space), opening is fine
        if !is_new_bin { score += 100.0; }
        // if next item is large and current residual is small, new bin gains value
        if next_item_size > 0 && next_item_size > bin_residual {
            score -= 15.0;
        }
        // mean residual high => open bins are full of dead space, allow new bin
        if mean_residual > 0.5 * cap {
            score -= 20.0;
        }
    }

    // Mild tightness preference relative to mean residual of open bins
    score -= 0.15 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small non-zero post_residual is worst.
    if post_residual > 0 {
        if post_residual <= 10 {
            score += 40.0; // unusable sliver (min item size 1..100, but tiny gaps rarely reusable)
        } else if post_residual < 20 {
            score += 18.0;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // Reward tight fits generally: post_residual small relative to residual.
    let tightness = post_residual as f64 / bin_residual as f64;
    score += 25.0 * tightness;

    // Lookahead coupling: if next item fits into the post_residual, reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0 * (next_item_size as f64 / post_residual as f64);
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 8.0; // dead space that lookahead cannot use
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> discourage fragmenting further unless tight fit.
    let pressure = open_bins_count as f64 / (step_index as f64 + 1.0).max(1.0);
    score += 5.0 * pressure * (post_residual as f64 / bin_capacity as f64);

    // Mean residual coupling: prefer bins below mean residual (fill emptier-tail bins first)
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    } else {
        score += 2.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when no decent fit exists.
    if bin_residual == bin_capacity {
        // Baseline for a fresh bin: moderate score; beaten only by good existing fits.
        score = bin_capacity as f64 * 0.5 + open_bins_count as f64 * 2.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        } else if fitting_bins_count == 1 {
            // keep last-chance bin preferred: new bin should lose
            score += 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact/near match of post_residual with next_item_size
    if next_item_size > 0 {
        let lookahead_diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect 2-step fill is excellent
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual > next_item_size {
            // next item fits after this placement: mild reward scaled by closeness
            score -= 25.0 * (1.0 - lookahead_diff / bin_capacity as f64).max(0.0);
        } else {
            // next item won't fit: penalize leftover that is too small to be useful
            score += 12.0 + lookahead_diff * 0.15;
        }

        // Double-perfect: post_residual == next item AND residual was exactly item_size
        if bin_residual == item_size && post_residual == next_item_size {
            score -= 40.0;
        }
    } else {
        // Last item: prefer tightest fill
        score += 10.0 * post_residual as f64 / bin_capacity as f64;
    }

    // Tight fit reward: small post_residual is good, but avoid dead space (<10 unusable)
    if post_residual > 0 && post_residual < 10 {
        score += 18.0; // dead space penalty
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Relative to mean residual: bins tighter than average are better targets
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Penalize wasting a large residual on a small item when many bins are open
    if post_residual as f64 > mean_residual * 1.5 && open_bins_count > 2 {
        score += 8.0;
    }

    // New-bin candidate: only attractive when no open bin gives a decent fit
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 20.0; // nothing fits elsewhere: open new bin
        } else {
            // discourage opening fresh bins when decent fits exist
            let best_possible = if next_item_size > 0 {
                (bin_capacity as i64 - item_size as i64 - next_item_size as i64).abs() as f64
            } else {
                (bin_capacity as i64 - item_size as i64) as f64
            };
            score += 25.0 + best_possible * 0.1;
        }
    }

    // Early stream: slightly favor consolidation into few bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Normalized fill ratio of this bin after placement
    let fill = 1.0 - (post_residual as f64 / bin_capacity as f64);

    // Reward tight fits: penalize large post_residual more than linearly
    score += 0.35 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // Reward high fill ratio
    score -= 12.0 * fill * fill;

    // Perfect or near-perfect fit gets a strong bonus
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Lookahead coupling: if the next item fits into the post-residual,
    // this placement is especially valuable (chain packing).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0 + 0.15 * (next_item_size as f64);
        } else {
            // Dead space that the next item cannot use is worse
            let waste = post_residual as f64 - if post_residual >= next_item_size { next_item_size as f64 } else { 0.0 };
            score += 0.10 * waste;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin should only win when
    // existing fits are poor. Penalize the empty bin moderately so it is
    // chosen only when all open bins would leave large residuals.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, decaying as stream progresses
        // (early on, opening bins is cheaper; late, prefer consolidation)
        let open_cost = 30.0 * (1.0 - 0.5 * progress);
        score += open_cost;
        // But if many bins are open already, discourage spreading further
        score += 0.8 * open_bins_count as f64;
    }

    // Global residual balance: prefer bins whose residual is below the mean
    // (pack fuller bins first, keep large-residual bins flexible)
    let res_f = bin_residual as f64;
    if mean_residual > 0.0 {
        score += 0.25 * (res_f - mean_residual);
    }

    // Slight preference for bins that can still host mid-size items afterwards
    if post_residual >= 10 && post_residual < 40 {
        score -= 3.0;
    }

    // Mild noise-free tie-breaking by residual (prefer emptier bins slightly)
    score += 0.01 * res_f;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let resid = bin_residual as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    let mut score = post;

    // Reward tight fits: smooth quadratic coupling of post_residual with item fraction.
    let fit_quality = 1.0 - (post / cap);
    score -= 30.0 * fit_quality * fit_quality * (item / cap);

    // Penalize large dead space non-linearly (cubic in wasted fraction).
    let waste = post / cap;
    score += 20.0 * waste * waste * waste * cap * 0.1;

    // Lookahead: reward bins whose post-residual matches the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post - nxt).abs();
        if post >= nxt {
            score -= 12.0 * (1.0 - gap / cap) * (0.5 + 0.5 * progress);
        } else {
            score += 6.0 * (gap / cap);
        }
    }

    // Last-chance bonus: strongly favor the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: mildly discourage opening a new bin early,
    // encourage it late when mean residual is fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap - 0.5).abs();
        score += 18.0 * (1.0 - progress) - 15.0 * fragmentation * progress;
        score += open_bins_count as f64 * 0.5;
    }

    // Discourage spreading across many bins when mean residual is low (near-full bins).
    score += 0.3 * (mean_residual - resid).abs();

    // Smooth progress coupling: slight preference for filling older bins as stream advances.
    score -= 5.0 * progress * (1.0 - resid / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Base: prefer tight fits (small post_residual), with harmonic classes ---
    // Classify post_residual into "dead space" classes via capacity fractions.
    let cap_f = bin_capacity as f64;
    let post_f = post_residual as f64;

    // Dead-space penalty grows superlinearly once residual is unusable (< smallest item 1..10 band)
    if post_residual == 0 {
        score -= 50.0; // perfect fit is heavily rewarded
    } else if post_residual < 10 {
        score -= 20.0; // near-perfect: residual likely unusable anyway -> good
    } else {
        // Harmonic class: which fraction of capacity does the dead space occupy?
        let classes = [10.0, 20.0, 25.0, 33.3, 50.0];
        let mut class_pen = 0.0;
        for (i, c) in classes.iter().enumerate() {
            if post_f <= c {
                class_pen = (i as f64 + 1.0) * 3.0;
                break;
            }
            class_pen = 18.0;
        }
        score += class_pen;
        // Superlinear blowup for large unusable residuals
        score += (post_f / cap_f).powi(3) * 30.0;
    }

    // --- Lookahead (k=2): reward bins whose leftover can host the next item ---
    if next_item_size > 0 && post_residual >= next_item_size {
        // exact chain fit: post_residual == next_item_size is ideal
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 - (slack / 10.0).min(8.0);
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item can't use this residual: penalize proportionally
        score += ((next_item_size - post_residual) as f64) * 0.15;
    }

    // --- Last-chance logic: this is the only bin that fits; avoid opening new bin ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin: base cost of +capacity worth of fresh space.
        let mut nb = 60.0;
        // If existing bins fit poorly (large mean residual wasted), new bin is more attractive
        let spread = (mean_residual - post_f).abs();
        nb -= spread * 0.2;
        // If many open bins already, discourage proliferation slightly less (parallelism ok)
        nb -= (open_bins_count as f64).ln() * 2.0;
        // Early in stream: new bins cheap (building diversity)
        let progress = step_index as f64 / total_items.max(1) as f64;
        nb += progress * 10.0;
        // Perfect fit in existing bin should beat new bin
        if post_residual == 0 && bin_residual != bin_capacity { nb += 100.0; }
        score += nb;
    }

    // --- Mean-residual coupling: prefer bins whose residual is near the mean (keeps fleet balanced) ---
    score += ((post_f - mean_residual) / 10.0).powi(2) * 0.5;

    // --- Modulo arithmetic flavor: residual congruence classes ---
    // Residuals that are multiples of common item sizes (10, 20, 25) are more reusable.
    let r = post_residual;
    if r % 10 == 0 { score -= 2.0; }
    if r % 25 == 0 { score -= 1.5; }
    if r % 5 == 0 && r % 10 != 0 { score -= 0.5; }
    // Odd/prime-ish residuals are dead weight
    if r % 2 == 1 && r > 10 { score += 1.0; }

    // Integer-division threshold: bucket the residual into quarters of capacity
    let quarter = bin_capacity / 4;
    let bucket = r / quarter;
    score += bucket as f64 * 1.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead space avoidance: penalize small unusable gaps hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Moderate penalty for gaps below typical small-item size (1..=9 range handled above),
    // plus soft penalty for gaps that likely cannot absorb a future item.
    if post_residual > 0 && post_residual < 20 {
        score += 25.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Open-bin pressure: discourage spreading across many open bins.
    score += open_bins_count as f64 * 1.5;

    // Encourage using bins that are already fairly full (low residual before placement).
    score += (bin_residual as f64 - item_size as f64).max(0.0) * 0.3;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 15.0;
    }
    // Penalize if next item cannot fit in the post residual.
    if next_item_size > 0 && (post_residual as f64) < next_item_size as f64 {
        score += 10.0;
    }

    // New-bin candidate handling: make empty bin attractive only when it's early
    // or existing bins are poor fits; otherwise penalize opening new bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 + progress * 50.0 + open_bins_count as f64 * 2.0;
        // If the new bin would be the last chance anyway (no fitting bins besides it),
        // allow it more readily.
        if fitting_bins_count <= 1 {
            score -= 55.0;
        }
    }

    // Mean residual coupling: if mean residual is high, prefer filling existing bins more.
    score += (mean_residual - post_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let capacity = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        if post_residual as f64 >= nxt {
            // Next item can fit exactly here afterwards.
            if diff < 1.0 {
                score -= 50.0;
            } else if diff <= 10.0 {
                score -= 25.0 * (1.0 - diff / 10.0);
            } else {
                score -= 8.0 * (1.0 - (diff / capacity).min(1.0));
            }
        } else {
            // Next item won't fit: penalize wasted potential.
            score += 5.0 + 10.0 * (nxt - post_residual as f64) / capacity;
        }
    }

    // Compare post_residual to mean residual: avoid making bin much worse than average.
    score += 0.3 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let poor_fit = (post_residual as f64) > 40.0;
        if poor_fit || fitting_bins_count == 0 {
            score -= 30.0;
        } else {
            score += 25.0 + 0.2 * open_bins_count as f64;
        }
    }

    // Early in the stream, be more willing to open bins for large items.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if item_size >= 60 && progress < 0.3 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post * 1.0;

    // Strongly reward near-perfect fits (tight packing).
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    }

    // Penalize dead space relative to capacity: small unusable leftovers hurt more
    // when they are below the minimum item size (assume min item ~1..10 band).
    let dead_zone = 10.0;
    if post > 0.0 && post < dead_zone {
        score += (dead_zone - post) * 2.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, big reward.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if (post_residual as u64) == (next_item_size as u64) {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / cap);
        } else {
            // Next item won't fit here: slight penalty proportional to how much
            // leftover would be stranded.
            score += 5.0 * (post / cap);
        }
        // Reward leaving room for the known next item when it's large.
        if next_item_size >= item_size && next_item_size <= post_residual {
            score -= 6.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when open bins are very
    // fragmented (high mean residual spread) or few bins fit the item.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post).abs();
        let pressure = if open_bins_count == 0 {
            -50.0 // must open first bin
        } else if fitting_bins_count == 0 {
            -10.0
        } else {
            // New bin competes with existing bins: penalize unless existing
            // residuals are large (bad fits) and many bins are open.
            (mean_residual / cap) * 30.0 + (open_bins_count as f64).ln() * 5.0 - 25.0
        };
        score = score.max(0.0) + pressure + fragmentation * 0.5;
    } else {
        // Existing bin: mild reward for keeping bins consolidated when many are open.
        score -= (open_bins_count as f64).ln().max(0.0) * 2.0;
    }

    // Time horizon: early in the stream, be conservative (keep residuals flexible);
    // late in the stream, pack aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 - 0.15 * progress;
    if progress > 0.8 {
        score -= post * 0.1; // squeeze harder near the end
    }

    // Mean-residual coupling: prefer bins whose residual deviates favorably from mean
    // (below-mean residual bins are closer to full -> use them).
    let bin_res = bin_residual as f64;
    if bin_res < mean_residual {
        score -= (mean_residual - bin_res) * 0.3;
    } else {
        score += (bin_res - mean_residual) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64 / bin_capacity as f64;
    let br = bin_residual as f64 / bin_capacity as f64;
    let it = item_size as f64 / bin_capacity as f64;
    let ni = next_item_size as f64 / bin_capacity as f64;

    // Smooth non-linear coupling: quadratic post_residual shaping with progress
    score += 8.0 * pr * pr * (1.0 + progress) * (1.0 + progress);
    score -= 4.0 * pr * pr * pr * (0.5 + progress);

    // Reward tight fits (post_residual near zero) more strongly as stream progresses
    score -= 6.0 * (1.0 - pr) * (1.0 - pr) * (0.4 + progress);

    // Lookahead coupling: penalize wasted space that next item cannot use
    if next_item_size > 0 {
        let usable = if pr >= ni { (pr - ni) / 100.0 } else { 0.0 };
        score -= 5.0 * usable * (0.5 + progress);
        score += 3.0 * if pr < ni { (ni - pr) / 100.0 } else { 0.0 };
    }

    // Penalize opening/using bins with large residual relative to mean residual
    score += 2.0 * (pr - mean_residual / bin_capacity as f64).abs();

    // Last-chance bin: strong reward to use it rather than open new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0 * (0.5 + progress);
    }

    // New-bin candidate: penalize proportionally to progress (prefer consolidation late)
    if bin_residual == bin_capacity {
        score += 12.0 * (0.3 + progress) + 0.5 * open_bins_count as f64;
    } else {
        score -= 2.0 * br * it * (1.0 + progress);
    }

    score
}

