    if next_item_size > 0 {
        let next = next_item_size as f64;
        let diff = (post_residual as f64 - next).abs();
        // Perfect chain match: strong bonus.
        if post_residual as u32 == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Next item could still fit here later; mild bonus scaled by closeness.
            score -= 25.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Dead space the next item cannot use: penalize proportionally.
            score += 0.5 * diff;
        }
        // If post_residual is too small for any plausible future item (min size 1),
        // waste is nearly certain unless it's zero.
        if post_residual > 0 && post_residual < 10 {
            score += 15.0;
        }
    }

    // Relative-to-mean coupling: bins with residual far below mean are already tight;
    // filling them is good if fit is tight, bad if it leaves odd scraps.
    let pr = post_residual as f64;
    if pr < mean_residual * 0.35 && pr > 0.0 {
        score += 8.0;
    } else if pr >= mean_residual {
