    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when existing fits are terrible
    // (very large post_residual elsewhere) or stream is early with many bins open.
    if bin_residual == bin_capacity {
        // Neutral base for a fresh bin; make it slightly worse than a decent fit
        // but better than a horrible one.
        score = bin_capacity as f64 * 0.75;
        if next_item_size > 0 && (next_item_size as f64 - item_size as f64).abs() < 1.0 {
            // next item similar size -> fresh bin can chain pair
            score -= 20.0;
        }
        if fitting_bins_count == 1 {
            // there exists exactly one fitting bin; opening new bin competes with it
            score += 10.0;
        }
        let progress = step_index as f64 / total_items.max(1) as f64;
        if open_bins_count > 8 && progress < 0.5 {
            score -= 5.0; // early consolidation pressure relief
        }
    }

    // Slight preference to keep number of open bins low: filling existing bins
    // is rewarded when many bins are open.
    score -= (open_bins_count.min(20) as f64) * 0.3 * (1.0 - pr / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly prefer bins where the item fills most of the space.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fill_ratio * fill_ratio;

    // Lookahead: reward if the next item fits into the post-residual (chain placement).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let chain_waste = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - chain_waste / bin_capacity as f64);
        } else {
            // Penalize residuals too small for the next item (dead space risk).
            let dead = (next_item_size - post_residual) as f64;
            score += 0.25 * dead;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: penalize opening a new bin, more so when the
    // current item is small or many bins are already open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let size_pen = 1.2 * (item_size as f64 / 100.0);
        score += 30.0 + 10.0 * open_bins_count as f64 + 20.0 * (1.0 - progress) - size_pen;
    }

    // Prefer bins whose residual is below the mean residual (consolidating fuller bins).
    score += 0.15 * (mean_residual - bin_residual as f64).max(0.0);

    // Mild penalty for leaving awkward mid-range residuals.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let it = item_size as f64;
    let nx = next_item_size as f64;

    // Base: reward tight packing via non-linear decay of post_residual
    let mut score = pr * pr / cap;

    // Smooth coupling of tightness with stream progress:
    // later in the stream, tolerate larger residuals less (favor filling old bins)
    let tightness = 1.0 - (pr / cap);
    score -= 8.0 * tightness * (progress * progress);

    // Lookahead coupling: reward if next item fits the post-residual,
    // scaled smoothly by how close the next item is to the leftover space
    if nx > 0.0 {
        let gap = (pr - nx).abs();
        let fit_bonus = (1.0 - gap / cap).max(0.0);
        score -= 5.0 * fit_bonus * fit_bonus;
        // penalize leaving a residual that is almost-but-not-quite the next item
        let near_miss = (pr / nx).max(0.0).min(2.0);
        score += 2.0 * (near_miss - 1.0).abs() * (pr / cap);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 6.0 + 4.0 * progress;
    }

    // New-bin candidate: penalize opening a bin unless it enables a very tight fit
    if bin_residual == bin_capacity {
        let waste = pr; // space left empty in a fresh bin
        score += 10.0 + waste as f64 * 0.5 - 6.0 * (1.0 - pr / cap) * progress;
        // opening bins when many are open and mean residual is high is bad
        score += 0.5 * open_bins_count as f64 + 0.05 * mean_residual;
    } else {
        // mild preference to consolidate into bins with low mean residual
        score += 0.02 * mean_residual;
    }

    // Slight preference for larger item placements filling big chunks
    score -= 0.03 * it;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic bonus for small post_residual.
    let tight = (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64;
    score -= 40.0 * tight * tight;

    // Penalize unusable dead space: residual too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Harmonic class: post_residual modulo classes — reward residuals that
    // align with common item size classes (multiples of 10).
    let class = post_residual % 10;
    score -= match class {
        0 => 12.0,
        1 | 9 => -2.0,
        _ => 0.0,
    };

    // Lookahead: if next item fits in post_residual, reward this placement strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0; // perfect pairing
        } else if next_item_size <= post_residual {
            score -= 15.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; penalize leaving awkward gaps
            let gap = (post_residual as f64 - (post_residual as f64 % 10.0)) / 10.0;
            score += 3.0 * gap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin should only win when the
    // current item fits poorly everywhere else.
    if bin_residual == bin_capacity {
        // Neutral-ish base for a fresh bin, penalized slightly so a decent
        // existing fit wins, but rewarded when existing fits are bad.
        score += 30.0;
        if mean_residual < item_size as f64 {
            score -= 45.0; // open bins are too full -> new bin is better
        }
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    } else {
        // Prefer filling fuller bins (small residual before placement).
        score += 10.0 * (bin_residual as f64 / bin_capacity as f64);
    }

    // Stream progression: as stream advances, be slightly more conservative
    // about opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - progress);
    }

    // Many open bins with high mean residual: discourage spreading, encourage
    // consolidation into existing bins.
    if open_bins_count > 3 && mean_residual > item_size as f64 * 1.5 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold even the
    // minimum plausible item are "unusable" and heavily penalized.
    let dead_threshold = 10u32.min(bin_capacity / 10);
    if post_residual < dead_threshold {
        score += 40.0 * (dead_threshold - post_residual) as f64;
    }

    // Penalize residuals in the awkward mid-range (too big to waste, too
    // small to be reliably reusable by future items).
    if post_residual > 0 && post_residual <= 15 {
        score += 8.0;
    }

    // Reward near-perfect fits (post_residual small but nonzero).
    if post_residual > 0 && post_residual <= 5 {
        score -= 15.0;
    }

    // Exact fill is ideal.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead coupling: if the next item fits the post-residual exactly,
    // strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        if post_residual == next_item_size {
            score -= 25.0;
        } else {
            score -= 5.0;
        }
    }
    // If next item does NOT fit post-residual, mild penalty for creating
    // a bin that likely gets closed after this item.
    else if next_item_size > 0 && post_residual > 0 {
        score += 6.0;
    }

    // Open-bin pressure: discourage spreading across many bins; the more
    // bins already open, the more we prefer packing into existing ones.
    score += 2.0 * open_bins_count as f64;

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a fresh bin should only win when
    // no existing bin offers a decent fit. Make the empty-bin baseline
    // moderately high but beatable by good fits elsewhere.
    if bin_residual == bin_capacity {
        // Baseline: fresh bin leaves a large residual = potential waste,
        // but preserves tight fits in existing bins.
        score = 60.0 + item_size as f64 * 0.3;

        // Early in the stream, opening bins is cheaper (more future items
        // to fill them).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * (1.0 - progress);

        // If many bins are open, avoid adding another.
        score += 3.0 * open_bins_count as f64;

        // If no existing bin can fit at all, opening is necessary.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it is a tight bin — prefer using tight bins first to close them out.
    let tightness = mean_residual - bin_residual as f64;
    score -= 0.3 * tightness;

    // Slight preference for bins whose residual closely matches item size.
    let fit_gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.2 * fit_gap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect/near-perfect fits strongly (post_residual close to 0).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 2 {
        score -= 500.0;
    } else {
        // Squared penalty on wasted space, normalized by capacity.
        score += (post_residual as f64 / bin_capacity as f64).powi(2) * 200.0;
    }

    // Aggressive 2-step lookahead: reward bins whose residual after placement
    // exactly (or nearly) matches the next item size.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if post_residual as f64 == next {
            score -= 800.0; // perfect chain: this bin will be exactly filled next step
        } else {
            let gap = (post_residual as f64 - next).abs();
            if gap <= 5.0 {
                score -= 400.0 * (1.0 - gap / 5.0);
            } else if gap <= 20.0 {
                score -= 100.0 * (1.0 - gap / 20.0);
            } else {
                // residual too large to be useful for the next item: penalize
                score += gap * 0.5;
            }
        }
    }

    // Compare post_residual against mean residual across open bins:
    // leaving below-average residual is good (tight packing).
    score -= (mean_residual - post_residual as f64) * 2.0;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 600.0;
    }

    // New-bin candidate (empty bin): penalize opening new bins when decent
    // alternatives exist, unless very early in the stream or many bins open.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 300.0 + 200.0 * progress;
        if open_bins_count == 0 {
            score -= 1000.0; // must open a bin
        }
    }

    // Slight preference for bins with less residual before placement (tighter bins first).
    score += bin_residual as f64 * 0.1;

    // Mild late-stream tightening: waste matters more as stream progresses.
    score += (post_residual as f64) * (step_index as f64 / (total_items.max(1) as f64)) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (low post residual).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Penalize large dead space that no typical item can use.
    if post_residual > 0 && post_residual < 10 {
        score -= 15.0; // tiny sliver: excellent
    } else if post_residual >= 10 && post_residual < 31 {
        score -= 6.0;  // usable by most items
    } else if post_residual > 80 {
        score += 5.0;  // near-empty fit wastes the bin
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else {
        // More competing bins => mild penalty to encourage consolidation.
        score += 2.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Lookahead: reward if next item fits the post residual (chaining).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize leaving awkward gaps.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.15 * gap;
        }
    }

    // Global state coupling: many open bins with high mean residual
    // -> prefer filling existing bins rather than opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let crowding = (open_bins_count as f64).ln().max(0.0);
    score += crowding * (mean_residual / bin_capacity as f64) * 3.0 * (1.0 - progress);

    // New-bin candidate: penalize opening a new bin, more so early when
    // consolidation is cheap and later only if the fit is truly poor.
    if bin_residual == bin_capacity {
        let fit_quality = 1.0 - (item_size as f64 / bin_capacity as f64);
        score += 20.0 + 30.0 * (1.0 - progress) * fit_quality;
    }

    // Slight time decay: early on, be pickier about loose fits.
    score += (1.0 - progress) * (post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Non-linear tightness reward: quadratic coupling of post_residual with capacity fraction.
    let cap_frac = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - cap_frac) * (1.0 - cap_frac) * (bin_capacity as f64) * 0.5;

    // Smooth stream-progress coupling: later in stream, waste penalized more (convex).
    let waste_penalty = post_residual as f64 * post_residual as f64 / (bin_capacity as f64 * bin_capacity as f64);
    score += waste_penalty * (100.0 + 200.0 * progress * progress);

    // Reward filling bins deeply when many bins are open.
    let fill_frac = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= fill_frac * fill_frac * (open_bins_count as f64).ln().max(1.0) * 10.0;

    // Last-chance bonus: if this is the only fitting bin, strongly favor it.
    if fitting_bins_count == 1 {
        score -= 50.0 + 30.0 * progress;
    }

    // Lookahead coupling: prefer leaving residuals that fit the next item.
    if next_item_size > 0 {
        let diff = post_residual as f64 - next_item_size as f64;
        if diff >= 0.0 {
            score -= (1.0 - diff / bin_capacity as f64) * 25.0;
        } else {
            score += (-diff / bin_capacity as f64) * 40.0;
        }
    }

    // Penalize opening a new bin, more strongly early in the stream and when open bins are underused.
    if bin_residual == bin_capacity {
        score += 80.0 + 60.0 * (1.0 - progress) + 2.0 * open_bins_count as f64;
    } else {
        // Mild reward for consolidating into existing bins when mean residual is high.
        score -= mean_residual / bin_capacity as f64 * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect-fit classes get strong rewards
    let post = post_residual as u32;
    if post == 0 {
        score -= 500.0; // perfect fit
    } else if post <= 10 {
        score -= 150.0; // near-perfect: dead space <= min item
    } else if post < 20 {
        score -= 40.0;
    } else if post < 40 {
        score += 20.0;
    } else {
        score += 60.0;
    }

    // Modulo-class logic on post_residual: residuals in multiples of 10 are reusable
    if post % 10 == 0 && post > 0 {
        score -= 25.0;
    }
    if post % 20 == 0 && post > 0 {
        score -= 15.0;
    }

    // Integer-division threshold: can post_residual host the next item?
    if next_item_size > 0 {
        if post >= next_item_size {
            score -= 80.0 + (next_item_size as f64) * 0.3; // lookahead pairing bonus
            if post == next_item_size {
                score -= 120.0; // exact lookahead chain
            }
        } else {
            score += (next_item_size - post) as f64 * 0.8; // unusable for lookahead
        }
        // Harmonic pair: post + next divides capacity evenly
        if (post + next_item_size as u32) == bin_capacity {
            score -= 200.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 100.0;
    }

    // New-bin candidate: penalize opening unless current fit is terrible
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / cap_f;
        score += 120.0 - 80.0 * tightness; // big items justify new bins
        if fitting_bins_count == 0 {
            score -= 300.0; // nothing else fits
        }
    }

    // Prefer filling bins that are already relatively full (small residual)
    score += (bin_residual as f64) * 0.15;

    // Mean-residual coupling: penalize deviating far from fleet mean
    score += ((bin_residual as f64) - mean_residual).abs() * 0.3;

    // Late-stream pressure: consolidate as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 30.0 * (open_bins_count.min(20) as f64 / 20.0);

    // Small reward for many fitting alternatives being irrelevant here; keep stable
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = 0.0;

    // Base: prefer tight fit (small post_residual), but penalize unusable dead space.
    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 200.0;
    } else if post_residual < 10 {
        // Dead space below minimum item size: very bad.
        score += (10.0 - post_residual as f64) * 8.0;
    } else if post_residual <= 20 {
        // Small gap that only tiny items can use: moderately bad.
        score += (20.0 - post_residual as f64) * 2.0;
    } else {
        // Usable residual: mild preference for smaller.
        score += post_residual as f64 * 0.3;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: penalize opening a new bin when open bins exist and
    // mean residual across open bins is large enough to absorb the item.
    if bin_residual == bin_capacity {
        score += 100.0;
        if open_bins_count > 0 {
            // If the average open residual can comfortably fit the item,
            // opening a new bin is wasteful.
            if mean_residual >= item_size as f64 + 5.0 {
                score += 80.0;
            }
            // Pressure grows with number of open bins.
            score += open_bins_count as f64 * 5.0;
        }
        // Lookahead: if the next item is large, keeping residuals consolidated is good.
        if next_item_size > 0 && next_item_size as f64 > mean_residual {
            score -= 20.0;
        }
    } else {
        // Reward placing into existing bins, more so when many bins are open.
        score -= open_bins_count as f64 * 2.0;
    }

    // Lookahead synergy: if the post residual matches the next item size well,
    // reward this placement (chaining future items).
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap <= 10 {
            score -= 30.0 - gap as f64;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item cannot use this residual: slight penalty proportional to waste.
        score += (next_item_size as f64 - post_residual as f64).min(20.0) * 0.5;
    }

    // Mild preference for filling older bins early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Base: penalize wasted residual, favor tight fits
    score += 0.5 * (post_residual as f64 / cap) * (post_residual as f64 / cap) * cap;

    // Aggressive 2-step lookahead: reward when next item exactly fills post_residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64 - nxt).abs() < 1.0 {
            score -= 40.0; // perfect chain: next item seals this bin
        } else if next_item_size <= post_residual {
            // next item fits: reward proportional to how much of post_residual it consumes
            let fill = nxt / post_residual as f64;
            score -= 25.0 * fill;
        } else {
            // next item cannot fit here: penalize leftover dead space
            score += 0.3 * (post_residual as f64 - nxt).min(post_residual as f64);
        }
    }

    // Compare post_residual against mean residual of open bins
    if post_residual as f64 > mean_residual {
        score += 0.15 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.15 * (mean_residual - post_residual as f64);
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin gets a moderate default score
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive if no good fit exists;
        // make it slightly worse than a tight existing fit but better than a terrible one
        score += 20.0;
        // If next item is large and current item small, new bin keeps flexibility
        if next_item_size > post_residual as u32 && post_residual > 0 {
            score -= 10.0;
        }
    }

    // Late in stream: prefer closing bins tightly (fewer open bins)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / cap);

    // Penalize leaving residuals in the awkward 1..=9 dead zone
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Penalize leaving dead space that few future items could use.
    if post_residual > 0 && post_residual < 10 {
        score -= 15.0; // near-perfect fill
    } else if post_residual >= 10 && post_residual < 20 {
        score += 5.0; // awkward small gap
    }

    // Lookahead: reward if the next item can fit into the post-residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
            // extra reward if next item almost exactly fills the leftover
            let nxt_fit = next_item_size as f64 / post_residual.max(1) as f64;
            score -= 8.0 * nxt_fit;
        } else {
            // next item won't fit here: penalize large leftovers slightly
            score += 3.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    // or the open-bin pool is heavily fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = if open_bins_count > 0 { mean_residual / bin_capacity as f64 } else { 0.0 };
        // Opening a new bin is penalized normally...
        score += 30.0;
        // ...but rewarded when existing bins are fragmented or none fit well.
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
        if fragmentation > 0.5 {
            score -= 20.0 * (fragmentation - 0.5);
        }
        // Early in the stream, opening bins is cheaper (more future items to fill them).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * (1.0 - progress);
    }

    // Mild preference for filling bins with below-average residual (balance the pool).
    if bin_residual < bin_capacity {
        let diff = bin_residual as f64 - mean_residual;
        score += 0.05 * diff;
    }

    // Small penalty per open bin to discourage hoarding many half-empty bins.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Tight fit reward: strongly favor small post residuals (non-linear)
    let tight = 1.0 - (pr / cap);
    score -= 12.0 * tight * tight * tight;

    // Penalize large unusable residuals more than linearly (dead space)
    score += 0.35 * pr * pr / cap;

    // Stream-progress coupling: as stream advances, prefer tighter packing
    score -= 8.0 * progress * tight * tight;

    // Last-chance bin bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Discourage opening a new bin when reasonable fits exist
    let is_new_bin = (bin_residual as f64 - cap).abs() < 1e-9;
    if is_new_bin {
        score += 18.0 + 6.0 * progress;
        // But if no existing bin fits well, allow opening
        let waste_vs_next = if next_item_size > 0 && (next_item_size as f64) > pr {
            (next_item_size as f64 - pr) / cap
        } else { 0.0 };
        score -= 20.0 * waste_vs_next;
    }

    // Lookahead: reward residuals that still fit the next item
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if pr >= n {
            score -= 6.0 * (1.0 - ((pr - n) / cap).abs());
        } else {
            score += 4.0 * ((n - pr) / cap);
        }
    }

    // Mean-residual coupling: prefer bins whose residual is near the mean (balance)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 3.0 * dev * dev;

    // Mild penalty for many open bins (encourage consolidation)
    score += 0.15 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit: strongest reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: classify leftover into usable bands.
    // Leftovers that are too small to hold even the smallest item (1) are dead space;
    // leftovers below typical item sizes are "awkward" classes.
    let pr = post_residual;
    if pr > 0 {
        // Dead-space penalty grows super-linearly for tiny unusable leftovers.
        if pr < 10 {
            score += 60.0 + (10 - pr) as f64 * 8.0;
        } else if pr < 25 {
            score += 25.0;
        } else if pr < 50 {
            score += 10.0;
        }
        // Modulo-class logic: leftovers that are multiples of common item sizes
        // (e.g., divisible by 10 or 25) are more reusable.
        if pr % 10 == 0 {
            score -= 12.0;
        } else if pr % 5 == 0 {
            score -= 5.0;
        }
    }

    // Lookahead coupling: reward if the next item fits exactly in the post residual.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 400.0;
        } else if next_item_size <= pr {
            score -= (pr - next_item_size) as f64 * 1.5;
        } else {
            // Next item cannot use the leftover: penalize proportionally to waste.
            score += (next_item_size - pr).min(100) as f64 * 0.5;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: only attractive if no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        let decent_fit = post_residual == 0 || (next_item_size > 0 && next_item_size == post_residual);
        if fitting_bins_count > 0 && !decent_fit {
            // Opening a new bin wastes mean_residual across all open bins.
            score += 80.0 + mean_residual * 0.3 + (open_bins_count as f64) * 2.0;
        } else {
            score -= 30.0;
        }
    }

    // Prefer filling bins that are already relatively full (small residual).
    score += (bin_residual as f64 / cap) * 20.0;

    // Mild pressure to consolidate as the stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * (0.5 + 0.5 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize dead space: residuals too small for likely future items
    let dead_threshold = 20.0;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 6.0;
    }
    if post_residual == 0 {
        score -= 40.0; // perfect fit strongly rewarded
    }

    // Reward tight fits relative to bin residual
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 30.0;

    // Open bins pressure: discourage spreading across many bins
    score += open_bins_count as f64 * 0.8;

    // New-bin candidate: penalize opening a new bin unless current fits are bad
    if bin_residual == bin_capacity {
        score += 25.0;
        // allow new bin if no good fit exists among open bins
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    // Last chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead: favor bins whose post-residual can host the next item
    if next_item_size > 0 {
        if (post_residual as u64) >= (next_item_size as u64) {
            score -= 12.0;
        } else if post_residual > 0 {
            score += (next_item_size as f64 - post_residual as f64) * 0.5;
        }
    }

    // Mean residual coupling: avoid bins far below mean residual (wasted capacity)
    score += (mean_residual - post_residual as f64).abs() * 0.3;

    // Stream progression: tighten packing as stream advances
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // 2-step lookahead: strongly reward if the next item exactly fits the post residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect 2-step match
        } else if next_item_size <= post_residual {
            let leftover2 = post_residual - next_item_size;
            // reward proportional to how small the second leftover is
            score -= 30.0 * (1.0 - leftover2 as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here after placement: penalize wasted lookahead potential
            score += 8.0 + 0.1 * (next_item_size - post_residual) as f64;
        }
    } else {
        // last item: minimize residual as tightly as possible
        score += 0.0;
    }

    // Penalize large dead space relative to mean residual of open bins
    score += 0.5 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Tight fit reward: residual close to zero is good
    let tightness = 1.0 - post_residual as f64 / bin_capacity as f64;
    score -= 10.0 * tightness * tightness;

    // Slight preference to fill older/more numerous bins as stream progresses
    score -= 0.05 * open_bins_count as f64 * (0.5 + progress);

    // New-bin candidate: make it moderately attractive only when the item is large
    // relative to residual elsewhere (empty-bin call has bin_residual == bin_capacity)
    if bin_residual == bin_capacity {
        // opening a new bin: base penalty so it's chosen only for good reason
        score += 12.0 - 6.0 * (item_size as f64 / bin_capacity as f64);
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // large stream items benefit from a fresh bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 18.0 * fit_ratio;

    // Penalize dead space relative to smallest plausible future item
    if post_residual > 0 {
        score += (post_residual as f64 / 10.0).powi(2) * 0.35;
    }

    // Lookahead: reward if next item fits into post_residual
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 14.0 + 0.12 * next_item_size as f64;
    }
    // Penalize if next item is slightly larger than post_residual (near-miss waste)
    if next_item_size > post_residual && next_item_size - post_residual <= 12 {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }
    // Many fitting bins: mild penalty to keep options open for other bins
    if fitting_bins_count > 2 {
        score += 2.0 * (fitting_bins_count as f64 - 2.0);
    }

    // Global state: if mean residual is high, encourage consolidating into existing bins
    score -= 0.08 * mean_residual;

    // Time horizon: early in stream, opening bins is cheap; late, consolidate
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 30.0 } else { 12.0 + 6.0 * progress };
        score += desperation + open_bins_count as f64 * 0.5;
        // A new bin is good if the item is large (fills a fresh bin well)
        score -= 0.15 * item_size as f64;
    }

    // Prefer bins whose residual is close to item size (avoid splitting big residuals badly)
    score += 0.05 * (bin_residual as f64 - item_size as f64 - post_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let post_norm = post / cap;

    // Base: tight fit preferred, non-linearly weighted by stream progress.
    let mut score = post_norm.powf(1.0 + 1.5 * progress);

    // Dead-space penalty grows with progress (less time to recover wasted space).
    score += 2.0 * progress * post_norm * post_norm;

    // Reward near-perfect fits smoothly.
    score -= 3.0 * (-((post_norm - 0.05) * (post_norm - 0.05)) / 0.02).exp();

    // Lookahead coupling: penalize if next item cannot use the post residual.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if next > post {
            score += 1.5 * progress * ((next - post) / cap);
        } else {
            // Smooth reward when residual can host the next item.
            let fit_quality = 1.0 - (post - next) / cap;
            score -= 1.2 * fit_quality * fit_quality;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 5.0 + 3.0 * (1.0 - progress);
    }

    // Mean-residual spread: prefer bins deviating below mean residual (tighter bins).
    let dev = (post - mean_residual) / cap;
    score += 0.8 * dev * dev - 0.4 * dev;

    // Mild pressure to consolidate when many bins are open.
    score += 0.05 * (open_bins_count as f64).ln().max(0.0) * post_norm;

    // Slight penalty for opening a brand-new bin (empty candidate), softened late in stream.
    if bin_residual == bin_capacity {
        score += 1.0 + 2.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into
    // capacity-fraction buckets. Leftovers in "awkward" classes (small but
    // unusable slivers) are penalized; generous usable classes rewarded.
    let frac = post_residual as f64 / bin_capacity as f64;
    let class = (frac * 8.0).floor() as i64; // 0..7 harmonic classes
    let class_penalty = match class {
        0 => 0.0,                       // perfect fit
        1 => 6.0,                       // tiny dead sliver (1/8..1/4)
        2 => 2.0,
        3 => 0.0,
        4 => -1.0,                      // ~half bin left: quite reusable
        5 => 0.0,
        6 => 2.0,
        _ => 4.0,                       // nearly empty bin wasted on small item
    };
    score += class_penalty;

    // Integer-division thresholds on post_residual: which standard small
    // item sizes (<= 100/4, /3, /2) could still fit? Reward usability.
    let usable = (post_residual >= 25) as i32 as f64 * 3.0
               + (post_residual >= 34) as i32 as f64 * 3.0
               + (post_residual >= 50) as i32 as f64 * 4.0;
    score -= usable;

    // Lookahead: if the next item fits exactly into post_residual, strongly
    // favor this bin; if it fits at all, mild reward; if it would be forced
    // elsewhere while this bin had room, mild penalty.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (post_residual - next_item_size) as f64 / bin_capacity as f64;
        } else {
            score += 2.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a
    // new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0 + item_size as f64 * 0.1;
    }

    // New-bin candidate: only attractive when open bins are crowded or the
    // fit into any open bin would be poor. Penalize default new bins.
    if bin_residual == bin_capacity {
        let crowding = mean_residual / bin_capacity as f64;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0
               - 20.0 * crowding
               - 10.0 * (1.0 - progress)
               + if next_item_size > 0 && next_item_size > bin_capacity - item_size { 5.0 } else { 0.0 };
    }

    // Mild preference for filling bins that are already relatively full
    // (best-fit flavor weighted by global mean residual).
    score += 0.5 * (mean_residual - bin_residual as f64).max(0.0);

    // Tiny tie-break toward fewer open bins.
    score += 0.01 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small for any future item
    // (items >= 1, but practically small gaps below ~10 are unusable dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 6.0;
    } else if post_residual < 25 {
        // Small-but-usable gaps: moderate penalty to avoid wasting them on poor fits.
        score += (25 - post_residual) as f64 * 1.5;
    }

    // Reward tight fits: small post_residual relative to item size.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 30.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: if the next item fits exactly or well into post_residual, reward strongly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Post residual can't host next item: mild penalty proportional to gap.
            score += ((next_item_size - post_residual) as f64).min(30.0) * 0.4;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones
    // (penalize the new-bin candidate whose residual == capacity).
    if bin_residual == bin_capacity {
        score += 20.0 + open_bins_count as f64 * 3.0;
        // But if no real pressure and mean residual is large, new bin is fine.
        if open_bins_count == 0 {
            score -= 100.0;
        }
    } else {
        // Mild preference for bins with below-mean residual (consolidating fuller bins).
        score += (mean_residual - bin_residual as f64).clamp(-20.0, 20.0) * 0.5;
    }

    // Stream progression: later in the stream, be slightly more conservative
    // about leaving small gaps (less future to recover from them).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 && post_residual < 20 {
        score += progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-exact fits (small dead space)
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 50.0;
    } else if post_residual <= 15 {
        score -= 10.0;
    }

    // 2-step lookahead: reward bins whose leftover matches the next item
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if diff == 0.0 {
            score -= 300.0;
        } else if next_item_size <= post_residual {
            // next item fits exactly in the leftover: strong chain bonus
            score -= 100.0 / (1.0 + diff / 10.0);
        } else {
            // leftover too small for next item: penalize dead space relative to mean residual
            score += diff * 0.3 + (mean_residual - post_residual as f64).abs() * 0.1;
        }
    }

    // Penalize bins far below mean residual (wasting a roomy bin on a poor fit)
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.2;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: prefer it only when current bin would leave large awkward residual
    if bin_residual == bin_capacity {
        score = post_residual as f64 + 25.0;
        if next_item_size > 0 {
            let diff = (bin_capacity as i64 - item_size as i64 - next_item_size as i64).abs() as f64;
            score -= 80.0 / (1.0 + diff / 10.0);
        }
        if fitting_bins_count <= 1 {
            score -= 60.0; // no good alternative, opening new bin is fine
        }
    }

    // Early in the stream, be slightly more willing to open fresh bins
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        if bin_residual == bin_capacity {
            score -= 30.0 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual close to zero is best.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that can never fit a typical item: if post_residual
    // is below the smallest plausible item (1..100 unknown, use ~10), it's waste.
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly favor this bin (chain placement).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            // next item won't fit here; penalize proportionally to leftover waste
            score += 0.15 * post_residual as f64;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: neutral-ish baseline, opened only when
    // existing fits are poor. Slightly discourage early on when few bins open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut nb = 35.0;
        // As stream progresses and many bins are open with large mean residual,
        // opening a new bin is less attractive.
        nb += 0.05 * mean_residual;
        nb -= 10.0 * progress;
        // If no bin currently fits the item well, allow new bin more readily.
        if fitting_bins_count == 0 {
            nb -= 30.0;
        }
        if open_bins_count == 0 {
            nb = -100.0;
        }
        score += nb;
    }

    // Mild global pressure: with many open bins, prefer consolidating into
    // emptier bins (large residual) to avoid spreading items thin.
    if open_bins_count > 3 {
        score += 0.03 * (open_bins_count as f64) * (bin_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // waste matters more as the stream advances (fewer chances to fill gaps).
    let progress_weight = 1.0 + 3.0 * progress * progress;
    score += progress_weight * (norm_pr * norm_pr) * cap;

    // Reward tight fits (small post_residual) with a smooth saturating bonus.
    score -= 8.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 + 0.5 * progress);

    // Penalize dead space that cannot fit the lookahead item (smooth interaction).
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr).max(0.0) / cap;
        score += 10.0 * gap * gap * cap * (0.5 + 0.5 * progress);
        // Bonus if post_residual exactly accommodates the next item (smooth).
        let fit_next = 1.0 - ((pr - next_item_size as f64).abs() / cap).min(1.0);
        score -= 6.0 * fit_next * fit_next;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 * (1.0 + progress);
    }

    // New-bin candidate: penalize opening a new bin unless all open bins fit poorly.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let avg_tight = 1.0 - (mean_residual / cap);
        score += 20.0 + 10.0 * (1.0 - avg_tight) - 8.0 * (1.0 - norm_item);
        // Late in the stream, prefer closing out existing bins.
        score += 15.0 * progress;
    } else {
        // Mildly favor bins below mean residual (balancing load across open bins).
        score += 0.3 * (pr - mean_residual) * (0.5 + 0.5 * progress);
    }

    // Smooth open-bin count regularization: avoid uncontrolled bin proliferation.
    score += (open_bins_count as f64).ln() * 2.0 * (0.3 + 0.7 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals near multiples of
    // common small sizes (10, 20, 25, 50) are more reusable.
    let pr = post_residual;
    let mut bonus = 0.0;
    if pr == 0 {
        bonus -= 60.0; // perfect fit: ideal
    } else {
        if pr % 10 == 0 { bonus -= 18.0; }
        if pr % 25 == 0 { bonus -= 12.0; }
        if pr % 20 == 0 { bonus -= 8.0; }
        if pr % 50 == 0 { bonus -= 10.0; }
        // Integer-division thresholds: small residuals are dead space
        if pr < 10 { bonus += 30.0; }
        else if pr < 20 { bonus += 12.0; }
        else if pr < 30 { bonus += 4.0; }
    }
    score += bonus;

    // Lookahead coupling: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size <= pr {
            score -= 12.0 * (next_item_size as f64 / cap_f);
            // harmonic class match between next item and residual
            if pr % next_item_size.max(1) == 0 { score -= 10.0; }
        } else {
            // next item cannot use this residual: penalize proportionally
            score += 6.0 * (1.0 - pr as f64 / cap_f);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Prefer tighter bins when many bins are open (fragmentation control)
    let tightness = 1.0 - (bin_residual as f64 / cap_f);
    score += 0.15 * open_bins_count as f64 * tightness;

    // Progress-based mild adjustment toward mean residual alignment
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.05 * progress * (post_residual as f64 - mean_residual);

    // New-bin candidate handling: penalize opening a new bin unless the
    // current fit is poor (large post_residual or dead space)
    if bin_residual == bin_capacity {
        let poor_fit = if post_residual == 0 { 0.0 }
            else if post_residual < 10 { 15.0 }
            else { (post_residual as f64 / cap_f) * 35.0 };
        score = cap_f * 0.8 + poor_fit - 8.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // possible item (size 1..=min_item) are pure waste; penalize hard.
    let dead_zone: f64 = 12.0;
    if post_residual > 0 && (post_residual as f64) < dead_zone {
        score += (dead_zone - post_residual as f64) * 6.0;
    }
    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Tight fit reward: fraction of bin used by this placement.
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= tightness * 15.0;

    // Lookahead: reward if next item fits the post residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        score += 5.0;
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, avoid opening new ones.
    let new_bin = bin_residual == bin_capacity;
    if new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 + 3.0 * open_bins_count as f64 + 10.0 * (1.0 - progress);
        // If no open bin fits well, opening a new bin is fine.
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
        // Opening a new bin is attractive when mean residual is small.
        score -= mean_residual * 0.2;
    } else {
        // Mild preference for bins with larger residual (keep small ones for small items).
        score += (bin_capacity as f64 - bin_residual as f64) * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect 2-step lookahead match: this bin's leftover
    // exactly fits the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual > next_item_size {
            // Leftover can still fit the next item: mild bonus proportional to slack.
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 - slack.min(40.0) * 0.3;
        } else {
            // Leftover too small for the next item: penalize dead space quadratically.
            let dead = (next_item_size - post_residual) as f64;
            score += dead * dead * 0.05;
        }
    }

    // Penalize very small post residuals (wasted space) unless a perfect match.
    if post_residual > 0 && post_residual < 10 && (next_item_size == 0 || post_residual != next_item_size) {
        score += 15.0;
    }

    // Prefer bins with residuals below the mean residual (tighter bins first),
    // keeping loose bins available for larger future items.
    let resid_f = post_residual as f64;
    if mean_residual > 0.0 {
        score += (resid_f - mean_residual) * 0.25;
    }

    // Last-chance bin: if this is the only open bin that fits the item,
    // strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // current bins would leave very poor fits (large dead space).
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 30.0;
        // If no existing-bin candidate is a great fit (post_residual tiny),
        // make new bin competitive: reduce its penalty.
        let poor_fit = (bin_residual - item_size) as f64;
        if next_item_size > 0 && poor_fit < next_item_size as f64 {
            score -= 45.0;
        }
        // Early in the stream, opening bins is cheaper (more future items to fill them).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Perfect fit gets a big bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    // Penalize leaving dead space that no future item (min size 1, typical >=10) can use.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // unusable sliver
    }

    // Lookahead: reward if next item fits into the post-residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // chainability is good, but not too good (keep some slack)
            let slack_ratio = post_residual as f64 / (next_item_size as f64 + 1.0);
            score -= 8.0 * (1.0 - (-slack_ratio).exp()).min(1.0);
        } else {
            // next item won't fit here; if this residual is small it's fine, if large it's waste
            let waste = post_residual as f64 - next_item_size as f64;
            if waste > 20.0 {
                score += waste * 0.15;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin, more so when open bins exist
    // and mean residual is large enough to absorb the item.
    if bin_residual == bin_capacity {
        let mut penalty = 40.0;
        if open_bins_count > 0 {
            penalty += (open_bins_count as f64).ln() * 10.0;
            // if mean residual comfortably fits item, discourage new bin harder
            if mean_residual >= item_size as f64 {
                penalty += 25.0;
            }
        }
        // Early in stream, opening bins is cheaper (more future items to fill them).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        penalty *= (1.0 - 0.5 * progress);
        score += penalty;
    }

    // Mild preference for filling bins with larger residual when many bins are open.
    if open_bins_count > 3 {
        score += 0.05 * (bin_residual as f64 - mean_residual);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;

    // Base: wasted space after placement, non-linearly amplified with stream progress
    let pr = post_residual as f64;
    let mut score = pr * (1.0 + 0.8 * progress) + 0.004 * pr * pr / cap;

    // Reward tight fits (small post_residual) with a smooth quadratic discount
    score -= 12.0 * (1.0 - pr / cap) * (1.0 - pr / cap);

    // Lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0 + 4.0 * progress;
    }

    // Penalize dead space that neither fits the next item nor is tiny
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 5 {
        score += 4.0 + 6.0 * progress;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Nudge toward bins with residuals close to the mean (balance load)
    score += 0.15 * (pr - mean_residual).abs();

    // New-bin candidate (empty bin): penalize so it's chosen only when open bins waste more
    if bin_residual == bin_capacity {
        score += 10.0 + 25.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let post_f = post_residual as f64;
    let mut score = post_f;

    // Harmonic class of post_residual: perfect fits (class 0) strongly rewarded.
    let k = 10u32;
    let class = post_residual % k;
    if class == 0 {
        score -= 12.0; // dead-space-free residual in harmonic class
    } else if class >= 7 {
        score += 6.0; // large unusable sliver
    }

    // Integer-division thresholds on post_residual
    if post_residual <= 10 && post_residual > 0 {
        score += 25.0; // tiny sliver = dead space
    }
    if post_residual == 0 {
        score -= 20.0;
    }

    // Capacity-fraction coupling: residual as fraction of capacity
    let frac = post_f / cap_f;
    if frac < 0.1 {
        score += 8.0 * (0.1 - frac) * 10.0;
    }

    // Lookahead: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // exact harmonic match bonus
            if post_residual % next_item_size.max(1) == 0 {
                score -= 10.0;
            } else {
                score -= 5.0;
            }
        } else {
            score += 4.0;
        }
    } else {
        // last item: prefer closing bins tightly
        score -= 15.0;
    }

    // Last-chance bin: strongly favor using it over opening a new bin
    if fitting_bins_count == 1 {
        score -= 18.0;
    }

    // New-bin candidate: penalize opening unless current bin fit is terrible
    if bin_residual == bin_capacity {
        score += 30.0;
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0;
        }
    }

    // Stream progression & congestion coupling
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64).ln() * 2.0 * progress;
    score += (mean_residual - post_f).abs() * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for typical future items are wasted.
    // Treat gaps < 10 (min item) as fully dead; gaps 10..=20 as partially dead.
    if post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 5.0;
    } else if post_residual <= 20 {
        score += (21 - post_residual) as f64 * 1.5;
