    }

    // Open-bin pressure: when many bins are open, discourage opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let new_bin = (bin_residual == bin_capacity) as i32 as f64;
    score += new_bin * (8.0 + open_bins_count as f64 * 2.0 + progress * 10.0);

    // Lookahead: if the next item fits the post-residual, reward leaving that gap.
    if next_item_size > 0 && post_residual >= next_item_size {
