    // Time horizon: later in the stream, be more conservative — prefer
    // filling existing bins tightly rather than spreading.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * (post_residual as f64) * 0.1;

    // Mild preference to balance residuals across bins: bins below mean
    // residual are slightly favored (keeps a spread of sizes available).
    score -= (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;
    // Non-linear polynomial coupling of post_residual with stream progress
    let norm_pr = pr / cap;
    let poly = progress * progress;
    score += 6.0 * norm_pr * norm_pr * (1.0 + poly);
    // Reward tight fits, amplified late in stream
    score -= (1.0 - norm_pr) * (1.0 + 2.0 * progress) * 3.0;
    // Penalize dead space unusable by next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx {
            score += (nx - pr) * (0.5 + progress);
        } else {
            score -= (pr - nx).min(20.0) * 0.2;
        }
    }
    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 4.0;
    }
    // Mild penalty for opening new bins late
    if bin_residual == bin_capacity {
        score += 2.0 + 4.0 * progress + 0.1 * open_bins_count as f64;
    }
    // Mean residual coupling
    score += 0.05 * (mean_residual - pr).abs();
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward near-zero and large usable residuals,
    // penalize "dead zones" (small unusable slivers).
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit: best possible outcome
    } else if pr <= 10 {
        // tiny sliver, likely unusable dead space (items >= 1..100 though, so mild)
        score += 12.0 * (1.0 - pr as f64 / 10.0);
    } else if pr <= 20 {
        // second dead zone: only small items can use it
        score += 6.0;
    } else if pr >= 80 {
        // large residual remains: bin still very usable
        score -= 10.0;
    } else {
        // mid-band: mild quadratic smoothing toward tighter fits
        score += 0.05 * (50.0 - pr as f64).abs();
    }

    // Integer-division harmonic classes: residuals that are exact divisors of
    // common item sizes are more likely to be filled later.
    for &d in &[10u32, 20, 25, 50] {
        if pr >= d && pr % d == 0 {
            score -= 4.0;
        }
    }

    // Lookahead coupling: does post_residual fit the next item?
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 8.0 + 0.1 * next_item_size as f64;
        } else {
            // next item won't fit here; penalize less if residual is large
            score += 3.0 * (next_item_size - pr) as f64 / cap;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoiding opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is huge
    // or existing bins are badly fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap).clamp(0.0, 1.0);
        let mut penalty = 45.0 - 30.0 * fragmentation;
        if item_size >= 60 {
            penalty -= 10.0; // big items are hard to place later; fresh bin ok
        }
        if open_bins_count == 0 {
            penalty = -100.0; // must open first bin
        }
        score += penalty;
    }

    // Stream progression: later in the stream, prefer consolidating into
    // fewer bins (tighten preference for filling existing bins).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 8.0 * progress * (1.0 - post_residual as f64 / cap);

    // Mild tie-break toward bins with residuals close to the item size
    // (best-fit flavor) using a harmonic ratio.
    if bin_residual > 0 {
        let ratio = item_size as f64 / bin_residual as f64;
        score -= 5.0 * ratio * ratio;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Strict dead-space avoidance: residuals too small for the minimum item
    // (1 here, but practically small gaps) are pure waste -> heavy penalty.
    if post > 0.0 && post < 10.0 {
        score += 40.0 * (10.0 - post) / 10.0;
    }
    // Perfect fit reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead coupling: reward if the next item can reuse the post residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            score -= 15.0 * (1.0 - (post - nxt) / cap);
        } else {
            // Next item won't fit in the gap: penalize proportionally to waste.
            score += 8.0 * (1.0 - post / cap);
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a bin is expensive when few bins open,
    // but attractive when many open bins have large mean residual (fragmentation).
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 / (1.0 + mean_residual / cap);
        score += 20.0 + 5.0 * pressure;
        if fitting_bins_count == 0 {
            score -= 100.0; // forced open
        }
    } else {
        // Prefer bins with residual close to item (tight fit) among open bins.
        score -= 10.0 * (1.0 - (bin_residual as f64 - item_size as f64) / cap).abs() * 0.5;
        // Mild pressure: filling nearly-full bins first reduces bin sprawl.
        score += 0.05 * open_bins_count as f64 * (1.0 - bin_residual as f64 / cap);
    }

    // Late-stream urgency: consolidate as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits: small post_residual is already favored by base,
    // add extra bonus for very tight fits.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 6.0 * tightness * tightness;

    // Aggressive 2-step lookahead: if the next item fits exactly into post_residual,
    // strongly reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_post = post_residual - next_item_size;
        if next_post == 0 {
            score -= 40.0; // perfect two-item packing
        } else {
            let r = next_post as f64 / (bin_capacity as f64);
            score -= 18.0 * (1.0 - r) * (1.0 - r);
        }
    } else if next_item_size > 0 {
        // Penalize creating residual that the next item cannot use (dead space risk)
        let waste = (post_residual as f64).min(next_item_size as f64);
        score += 0.5 * waste;
    }

    // Relative to mean residual: prefer bins with below-mean residual (denser bins)
    let rel = (bin_residual as f64) - mean_residual;
    score -= 0.15 * rel;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize opening a new bin when it would leave a large
    // residual relative to typical item sizes, unless current bins are all bad fits.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 + 5.0 * (1.0 - progress);
        if fitting_bins_count > 0 {
            score += 8.0 * (fitting_bins_count as f64).min(3.0);
        }
    }

    // Mild penalty for spreading across too many open bins
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: reward small post_residual non-linearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio).powi(6) * 40.0;

    // Penalize dead space that cannot fit the next item (wasted capacity).
    if next_item_size > 0 {
        if post_residual < next_item_size {
            let wasted = (next_item_size - post_residual) as f64;
            score += wasted * 0.6;
        } else {
            // Reward leaving exactly enough room for the next item.
            let gap = (post_residual - next_item_size) as f64;
            score -= (1.0 / (1.0 + gap)) * 8.0;
        }
    }

    // Last-resort bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: only attractive when current bins are crowded
    // or the item fits nowhere well.
    if bin_residual == bin_capacity {
        let crowd = if open_bins_count > 0 {
            mean_residual / bin_capacity as f64
        } else {
            0.0
        };
        // Opening a new bin is penalized when existing bins are roomy.
        score += 55.0 - crowd * 70.0;
        // If only one bin fits, discourage opening a new one.
        if fitting_bins_count <= 1 {
            score += 45.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 20.0;
    }

    // Mild preference for bins with low residual (best-fit bias) scaled by
    // how many alternatives exist.
    score += (bin_residual as f64 / bin_capacity as f64) * 10.0
        + (fitting_bins_count as f64).ln().max(0.0) * 2.0;

    // Small dynamic time-coupling: encourage tight packing as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_capacity - post_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Smooth non-linear coupling: progress-weighted dead-space penalty
    let dead_space = post_residual as f64 / bin_capacity as f64;
    score += 25.0 * dead_space * dead_space * (1.0 + progress);

    // Reward tight fits with a smooth quadratic bonus
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * tightness * tightness;

    // Penalize very small residuals only early (they become dead space later)
    let small_res_penalty = (1.0 - progress) * (post_residual as f64 / bin_capacity as f64).powi(4);
    score += 40.0 * small_res_penalty;

    // Lookahead: favor leaving space for the next item (smooth interaction)
    if next_item_size > 0 {
        let gap = post_residual as f64 - next_item_size as f64;
        if gap >= 0.0 {
            score -= 8.0 * (gap / bin_capacity as f64).min(1.0);
        } else {
            score += 6.0 * (-gap / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless nothing else fits well
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        score += 35.0 * scarcity + 10.0 * (open_bins_count as f64).ln().max(0.0);
        // Late in the stream, opening new bins is less wasteful
        score -= 15.0 * progress;
    }

    // Mild penalty tied to mean residual mismatch (avoid fragmenting balanced bins)
    score += 0.05 * (mean_residual - post_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo arithmetic on capacity fractions
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap;
    let class = (post_residual % (bin_capacity / 10).max(1)) as f64;

    // Reward residuals that lie in "harmonic" classes (multiples of 10, 20, 25, 50)
    if post_residual % 10 == 0 { score -= 6.0; }
    if post_residual % 20 == 0 { score -= 4.0; }
    if post_residual % 50 == 0 { score -= 5.0; }
    if post_residual % 25 == 0 { score -= 3.0; }

    // Penalize awkward classes (odd residuals, near-but-not-exact fits)
    if post_residual % 2 == 1 { score += 3.0; }
    if post_residual > 0 && post_residual < 10 { score += 8.0; } // dead space

    // Perfect fit is heavily rewarded
    if post_residual == 0 { score -= 40.0; }

    // Lookahead coupling: if next item fits exactly into post_residual, big bonus
    if next_item_size > 0 {
        if next_item_size == post_residual { score -= 30.0; }
        else if next_item_size < post_residual {
            let slack = post_residual - next_item_size;
            score -= 10.0 * (1.0 - slack as f64 / cap);
            if slack % 10 == 0 { score -= 3.0; }
        } else {
            score += 5.0; // next item won't fit here
        }
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 { score -= 15.0; }

    // Mean residual coupling: prefer bins with residual near mean (balanced packing)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // New-bin candidate: only attractive if no good harmonic fit exists
    if bin_residual == bin_capacity {
        score = cap * 0.9 + 10.0 - (item_size as f64 / cap) * 20.0;
        if fitting_bins_count == 0 { score -= 60.0; }
        if next_item_size > 0 && next_item_size >= item_size { score -= 5.0; }
    }

    // Mild stream-progression pressure to consolidate later
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 2.0 * progress * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hardest.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0; // tiny dead space: worst outcome
        } else if post_residual < 20 {
            score += 25.0;
        } else if post_residual < 35 {
            score += 8.0;
        } else {
            // Large residual remains reusable: reward proportional to size
            score -= 0.35 * post_residual as f64;
        }
    } else {
        // Perfect fit: strong reward
        score -= 40.0;
    }

    // Open-bin pressure: discourage spreading across too many bins
    score += 2.0 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Lookahead: reward leaving room for the next item
    if next_item_size > 0 {
        if post_residual as u32 >= next_item_size {
            score -= 12.0;
        } else {
            score += 10.0;
        }
    }

    // New-bin candidate handling: only prefer opening a new bin if all
    // open bins would create severe dead space and pressure is high.
    if bin_residual == bin_capacity {
        score = 45.0 + 3.0 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let next = next_item_size as f64;
    let mut score = post;

    // Base: penalize residual waste quadratically (dead space is bad).
    score += 0.02 * post * post / cap;

    // Aggressive 2-step lookahead: reward when post_residual matches next item size.
    if next > 0.0 && post >= next {
        let gap = post - next;
        score -= 30.0 * (1.0 - gap / cap); // perfect match for next item => strong reward
        score -= 0.05 * gap; // mild bonus for small leftover after next item
    } else if next > 0.0 && post < next {
        // Leftover too small for next item: penalize proportionally to how close we came.
        let miss = (next - post) / cap;
        score += 25.0 * miss;
    }

    // Compare against mean residual across open bins: prefer bins whose post residual
    // is below mean (tight packing), penalize bins already much tighter than mean.
    let dev = post - mean_residual;
    score += 0.15 * dev;

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate (empty bin): only attractive when current fit is poor.
    if bin_residual == bin_capacity {
        let fit_quality = post / cap; // = 1 - item/cap for a fresh bin
        // Opening a new bin leaves residual = cap - item; penalize unless item is large.
        score += 10.0 * (1.0 - fit_quality);
        // More open bins => prefer reusing; penalize opening another.
        score += 3.0 * (open_bins_count as f64);
        // Early in stream, opening new bins is cheaper (future items need space).
        if total_items > 0 {
            let progress = step_index as f64 / total_items as f64;
            score += 15.0 * progress;
        }
    }

    // Slight preference to fill fuller bins (small post residual) overall.
    score -= 0.3 * (1.0 - post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Lookahead reward: if the next item can also fit in the leftover space,
    // strongly favor this bin (chained packing).
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 30.0 + 0.5 * (post_residual - next_item_size) as f64;
    }
    // Penalize leaving a residual that is too small to ever be useful
    // (dead space below the minimum plausible item size).
    if post_residual < 5 {
        score += 10.0;
    }

    // Perfect-fit bonus: exact fill is ideal.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bonus: if this is the only bin that fits the item,
    // strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when all open bins
    // are crowded (mean residual low) relative to the item, or too many bins
    // are already open relative to progress.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowd = mean_residual / bin_capacity as f64;
        // Reward new bin when open bins are tight, penalize when plenty of room.
        score += 80.0 * crowd - 20.0 * (1.0 - progress);
        if fitting_bins_count > 0 {
            score += 60.0; // discourage opening new bin when others fit
        }
    } else {
        // Mild preference for filling bins with larger residual (waste reduction).
        score -= 0.1 * (bin_capacity - bin_residual) as f64;
    }

    // Slight time pressure: later in the stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (small post_residual), non-linearly scaled.
    let mut score = pr * pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress.
    // Early on, dead space matters less; later, minimize it aggressively.
    let t = progress * progress;
    score *= 1.0 + 2.0 * t * norm_pr;

    // Reward filling bins that leave post_residual matching the next item (lookahead harmony).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let harmony = 1.0 - ((pr - nx).abs() / cap);
        score -= 25.0 * harmony * harmony * (0.5 + progress);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0 * (1.0 - norm_pr);
    }

    // Slight preference for bins with residuals near the mean (balanced packing),
    // smoothly penalizing outliers.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // New-bin candidate: penalize mildly so it's chosen only when fits are bad,
    // with the penalty easing as the stream progresses.
    if bin_residual == bin_capacity {
        score += 30.0 * (1.0 - 0.5 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: which capacity fraction band does it fall into?
    // Bands: (0,10], (10,25], (25,50], (50,75], (75,100). Small residuals = tight fit = good.
    let band = match post_residual {
        0 => 0u32,
        1..=10 => 1,
        11..=25 => 2,
        26..=50 => 3,
        51..=75 => 4,
        _ => 5,
    };
    score += band as f64 * 6.0;

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 250.0;
    }

    // Dead-space penalty: residual too small to ever be useful (min item is 1 per interface,
    // but small residuals are hard to fill). Penalize modulo-based "wasted" classes.
    let waste = post_residual % 10;
    score += waste as f64 * 0.8;

    // Coupling with lookahead item: if next item fits exactly or well into post_residual, reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0;
        } else if next_item_size <= post_residual {
            let nxt_post = post_residual - next_item_size;
            // reward small double-fill remainder, harmonic classes again
            if nxt_post <= 10 {
                score -= 40.0;
            } else if nxt_post <= 25 {
                score -= 20.0;
            }
        } else {
            // next item cannot use this bin's remainder: penalize proportionally
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 90.0;
        if post_residual <= 25 {
            score -= 30.0;
        }
    }

    // New-bin candidate handling: opening a new bin is only attractive when the current item
    // fits poorly everywhere. Penalize the empty-bin candidate by default...
    if bin_residual == bin_capacity {
        score += 70.0;
        // ...but allow it when open bins are nearly full on average (mean_residual small)
        // or many bins are open and item is large.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let item_frac = item_size as f64 / bin_capacity as f64;
        if mean_residual < item_size as f64 * 1.2 && open_bins_count > 0 {
            score -= 100.0;
        }
        if item_frac > 0.7 && open_bins_count > 2 {
            score -= 55.0;
        }
        // mild time-dependent dither to break ties across the stream
        score += ((step_index % 7) as f64) * 0.5 * progress;
    }

    // Prefer bins with residual close to item size (tight fits among open bins).
    let tightness = (bin_residual - item_size) as f64;
    score += tightness * 0.15;

    // Mild preference to fill bins when many are open (reduce fragmentation).
    score += (open_bins_count as f64).ln().max(0.0) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small to hold even the smallest item
    // (or too small for the lookahead item) are unusable dead space.
    if post_residual > 0 && post_residual < item_size.min(10) {
        score += 40.0;
    }
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.6;
    }

    // Reward tight fits (small post_residual) super-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 20.0 * tightness * tightness;

    // Perfect fill is ideal.
    if post_residual == 0 {
        score -= 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, prefer reusing existing ones
    // over opening new bins; make the fresh-bin candidate less attractive.
    if bin_residual == bin_capacity {
        score += 12.0 + 3.0 * open_bins_count as f64;
    } else {
        score -= 2.0 * (open_bins_count as f64).ln().max(0.0);
    }

    // Prefer bins with residuals below the mean (consolidate small gaps).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.05 * dev;

    // Early in the stream, be more willing to open bins (keep flexibility);
    // late in the stream, squeeze into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post-residual can host the next item exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0; // perfect 2-step pairing
        } else if post_residual > next_item_size {
            score -= 15.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // dead space after this placement relative to next item
            score += 0.6 * (next_item_size - post_residual) as f64;
        }
    }

    // Tight fits preferred: relative fill ratio
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fill * fill;

    // Penalize divergence from mean residual (keep bin population homogeneous)
    score += 0.25 * (bin_residual as f64 - mean_residual).abs();

    // Last-chance bin bonus: avoid opening a new bin when only this one fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Late in the stream, consolidate harder into existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: penalize slightly so it's chosen only when open bins fit badly
    if bin_residual == bin_capacity {
        score += 12.0 + 0.3 * item_size as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = 0.0;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: penalize leftover space, but with a non-linear (quadratic) coupling
    // so small residuals are heavily favored (tight packing).
    let mut score = pr + (pr / cap) * pr * 0.8;

    // Smooth progress coupling: later in the stream, waste is costlier.
    score *= 1.0 + 0.5 * progress * (pr / cap);

    // Lookahead: reward residuals that can still host the next item,
    // with a smooth non-linear fit-quality term.
    if next_item_size > 0 && next_item_size <= post_residual {
        let fit_quality = next_item_size as f64 / (pr + 1.0);
        score -= 6.0 * fit_quality * (1.0 - fit_quality) * 4.0;
    } else if next_item_size > 0 {
        // Dead space relative to the next item: smooth penalty.
        let gap = (next_item_size as f64 - pr).max(0.0) / cap;
        score += 4.0 * gap * gap * cap;
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0;
    }

    // Mild penalty when many bins are open and residual is large (fragmentation).
    score += 0.05 * (open_bins_count as f64) * (pr / cap) * (pr / cap);

    // New-bin candidate: make it moderately attractive only when residuals
    // across open bins are large relative to the item.
    if bin_residual == bin_capacity {
        let tightness = (mean_residual / cap).clamp(0.0, 1.0);
        score = 5.0 + 10.0 * (1.0 - tightness) * (1.0 - tightness);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // ---- NEW-BIN CANDIDATE (empty bin) ----
    if bin_residual == bin_capacity {
        // Base reluctance to open a new bin; scaled by how full the stream is.
        let mut score = cap * 1.6 + progress * 15.0;
        // Harmonic class of the current item (quarter-capacity classes):
        // big items (class 2-3) justify opening fresh capacity more.
        let class = item_size / 25;
        score -= class as f64 * 8.0;
        // If the lookahead item would nest perfectly in the fresh bin's
        // post-residual harmonic slot, mild discount; otherwise penalty.
        if next_item_size > 0 {
            let pr = bin_capacity.saturating_sub(next_item_size);
            let slot = pr % 10;
            score += slot as f64 * 0.5;
            if pr >= 10 { score -= 6.0; }
        }
        // If this item has no other home, the new bin becomes attractive.
        if fitting_bins_count == 0 {
            score -= cap * 2.0;
        }
        return score;
    }

    // ---- EXISTING BIN SCORING ----
    let mut score = post_residual as f64;

    // Tightness reward: fraction of capacity consumed by this placement.
    let used_frac = 1.0 - post_residual as f64 / cap;
    score -= used_frac * 22.0;

    // Dead-space penalty: residual below the smallest item class is unusable.
    if post_residual < 10 {
        score += 30.0;
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Harmonic residue class of the leftover space (modulo 10 slots):
    // rounder residuals (near multiples of 10) recombine better with
    // common item sizes, so penalize odd/awkward leftovers mildly.
    let slot = post_residual % 10;
    score += slot as f64 * 0.6;

    // Lookahead compatibility (k=2): reward bins that can also host the
    // next item; penalize near-misses proportionally.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            // extra bonus if the pair exactly partitions the bin
            if post_residual == next_item_size { score -= 10.0; }
        } else {
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.35;
        }
    }

    // Last-chance bin: if this is the only open bin that fits, prefer it
    // strongly over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 18.0;
    }

    // Mild bonus when this bin sits below the mean residual (using up
    // the emptiest bins first keeps tight bins available).
    if (post_residual as f64) < mean_residual {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.17;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for a perfect 2-step lookahead match: post_residual == next_item_size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Reward if next item can still fit after this placement (pairing bonus)
    else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0 + 0.5 * (post_residual - next_item_size) as f64;
    }
    // Penalize residual too small for the next item (dead space relative to lookahead)
    else if next_item_size > 0 && post_residual < next_item_size {
        score += 0.3 * (next_item_size - post_residual) as f64;
    }

    // Penalize large leftover residual relative to mean residual of open bins
    score += 0.4 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: strongly reward using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: make it attractive only when it avoids wasting space.
    // Base penalty so open bins are preferred unless their fits are poor.
    if bin_residual == bin_capacity {
        score += 80.0;
        // If next item is huge relative to typical post-fit residuals, opening fresh helps
        if next_item_size > 60 {
            score -= 40.0;
        }
    }

    // Mild early-stream preference to consolidate into few bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly prefer bins where the item nearly fills the residual.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize small dead space (waste) super-linearly.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0; // unusable sliver
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / (bin_capacity as f64));
        } else {
            score += 4.0;
        }
        // Perfect chain: post_residual exactly fits next item
        if post_residual == next_item_size {
            score -= 12.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin is costly unless current bins fit poorly.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let avg_fit_gap = (mean_residual - item_size as f64).abs();
        score = 55.0 + avg_fit_gap * 0.4 - 20.0 * progress;
        if fitting_bins_count == 0 {
            score -= 60.0; // must open
        }
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score += 5.0; // pairing potential in fresh bin
        }
    } else {
        // Prefer bins with residual close to item size (minimize leftover variance).
        let gap = (bin_residual as f64 - item_size as f64) / (bin_capacity as f64);
        score += 8.0 * gap;
        // Mildly prefer bins below mean residual (consolidate emptier bins).
        if (bin_residual as f64) < mean_residual {
            score -= 2.0;
        }
        // Load balancing: penalize when many bins are open and this one is already crowded.
        let crowding = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
        score += 0.3 * crowding;
    }

    // Time horizon: early on, be exploratory (favor balanced placements); late, be greedy.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - progress) * 3.0 * (1.0 - (post_residual as f64 / bin_capacity as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: wasted space, with a super-linear penalty so near-full placements are favored.
    let mut score = post + 25.0 * norm_post * norm_post;

    // Smooth non-linear coupling of waste with stream progress:
    // early on, be lenient about leftover space; late, tighten up strongly.
    score *= 1.0 + 0.8 * progress * (1.0 - norm_post) * (1.0 - norm_post) - 0.35 * progress;

    // Lookahead: reward bins whose post_residual matches the next item well.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let slack = (post - nxt).abs();
        let match_q = 1.0 - slack / cap;
        if match_q > 0.0 {
            let coupling = match_q * match_q * (1.0 - progress * 0.5);
            score -= 12.0 * coupling;
        }
        // Penalize leaving a gap that no small item can plausibly use.
        if post > 0.0 && nxt > post {
            score += 6.0 * (nxt - post) / cap;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Crowding effect: with many open bins, discourage spreading into low-fill bins.
    let crowding = (open_bins_count as f64).ln().max(0.0);
    score += 2.0 * crowding * (norm_post - mean_residual / cap).abs();

    // New-bin candidate handling: make it attractive only when no open bin fits tightly.
    if bin_residual == bin_capacity {
        let best_tightness = (mean_residual / cap).max(0.0);
        score = post + 30.0 * best_tightness * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: residuals divisible by common item classes
    // (items 1..100, so multiples of 10 and 5 are reusable "harmonics")
    let pr = post_residual;
    if pr > 0 {
        if pr % 10 == 0 {
            score -= 12.0; // highly reusable residual class
        } else if pr % 5 == 0 {
            score -= 6.0;
        } else if pr % 2 == 0 {
            score -= 2.0;
        } else {
            score += 4.0; // odd residuals pair poorly
        }
        // Small dead space is bad: penalize tiny unusable residuals
        if pr < 5 {
            score += 25.0;
        }
    }

    // Lookahead coupling: does post_residual exactly host the next item?
    if next_item_size > 0 {
        if pr == next_item_size {
            score -= 40.0;
        } else if pr > next_item_size {
            let r2 = pr - next_item_size;
            score -= 8.0;
            if r2 % 10 == 0 { score -= 4.0; }
        } else {
            score += 10.0; // next item can't use this residual
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: prefer it only when it's early or open bins are tight
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let tight = if mean_residual > 0.0 { mean_residual / bin_capacity as f64 } else { 0.0 };
        // penalize new bins more when many bins are open and mean residual is low
        score += 45.0 + 30.0 * tight - 20.0 * progress + 2.0 * open_bins_count as f64;
    } else {
        // Prefer bins whose residual is close to item (tight fit) beyond raw post_residual
        let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
        score += 10.0 * tightness;
        // Prefer fuller bins (low residual) generally
        score += 0.05 * bin_residual as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // for typical future items are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 35 {
        score += 8.0;
    } else {
        // Larger usable residuals are rewarded.
        score -= (post_residual as f64) * 0.15;
    }

    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Pressure from number of open bins: with many open bins, prefer
    // consolidating into existing bins rather than opening new ones.
    score += (open_bins_count as f64) * 0.5;

    // New-bin candidate: it must only win when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, scaled by stream progress
        // (later in the stream, wasted capacity matters more per-bin).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 45.0 + 30.0 * progress;

        // If a lookahead item could combine with this item in a fresh bin,
        // opening a new bin becomes more attractive.
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 20.0;
        }
        // If the current item barely fits anywhere (large item), a fresh bin
        // is a reasonable place for it.
        if item_size >= 70 {
            score -= 15.0;
        }
    } else {
        // Reward bins whose residual is close to the item (tight fits).
        let tightness = (bin_residual - item_size) as f64;
        score += tightness * 0.05;
    }

    // Coupling with mean residual: if the average open-bin residual is high,
    // there is slack available, so prefer existing bins slightly more.
    if bin_residual != bin_capacity {
        score -= (mean_residual - post_residual as f64).max(0.0) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect or near-perfect fits (minimal dead space).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 50.0;
    }

    // Aggressive 2-step lookahead: strongly reward bins whose post_residual
    // exactly matches the next item (chains items tightly).
    if next_item_size > 0 {
        let lookahead_gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 40.0 / (1.0 + lookahead_gap);
        if post_residual == next_item_size {
            score -= 200.0;
        }
        // Penalize post_residual that is too small to host the next item
        // only mildly; a small dead space may still be acceptable.
        if post_residual < next_item_size {
            score += 0.3 * (next_item_size - post_residual) as f64;
        }
    }

    // Compare post_residual against mean residual: prefer bins that end
    // tighter than average (consolidating space).
    score -= 2.0 * (mean_residual - post_residual as f64);

    // Last-chance bin: if this is the only bin that fits, heavily favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is huge
    // relative to capacity (poor fit elsewhere) or few bins are open.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        score += 80.0 - 60.0 * fill_ratio;
        if fitting_bins_count == 0 {
            score -= 500.0; // no alternative: must open new bin
        }
        if open_bins_count == 0 {
            score -= 500.0;
        }
    }

    // Mild preference for filling existing bins as the stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (waste minimization core).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * 8.0;

    // Perfect-fit bonus: nearly full bin is ideal.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Dead-space penalty: residual too small for typical future items.
    let min_item = 1.0f64;
    if (post_residual as f64) < min_item {
        score += 100.0;
    }

    // Lookahead: favor bins whose residual pairs with next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual >= next_item_size {
            score -= 12.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            score += 4.0 + gap * 0.05;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a bin is expensive; only attractive
    // when current bins would leave large waste (poor fits).
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let waste_elsewhere = (mean_residual - item_size as f64).max(0.0);
        score = 30.0 + 0.3 * open_bins_count as f64
              + 0.5 * waste_elsewhere
              - 10.0 * progress;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 5.0; // fresh bin pairs well with next item
        }
    }

    // Global pressure: many open bins with high mean residual -> prefer
    // consolidating into existing space.
    if open_bins_count > 2 && mean_residual > 20.0 && bin_residual < bin_capacity {
        score -= (mean_residual - 20.0).min(15.0) * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Non-linear cost of leftover space: convex in post_residual, so tight fits are favored,
    // but the cost curve flattens for mid-size residuals (still reusable).
    let mut score = (pr / cap).powf(1.7) * 60.0 + (pr / cap) * 20.0;

    // Strong penalty if the next item cannot use this leftover (dead space until refilled),
    // scaled by how large the next item is relative to capacity.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx {
            score += 25.0 + 30.0 * (nx / cap) + 10.0 * progress;
        } else {
            // Reward leftover that exactly accommodates the next item (smooth coupling).
            let gap = (pr - nx) / cap;
            score -= 15.0 * (-gap * 12.0).exp();
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0 * (1.0 - progress * 0.5);
    }

    // New empty bin candidate: neutral-ish baseline; only attractive when existing bins
    // would leave very tight or very wasteful fits, or many bins already open.
    if bin_residual == bin_capacity {
        let spread = (mean_residual - pr).abs();
        score = 35.0 + 0.05 * open_bins_count as f64 + 10.0 * (1.0 - progress);
        if fitting_bins_count == 1 {
            score += 50.0; // never open a new bin when a last-chance bin exists
        }
        if next_item_size > 0 && (bin_capacity as u32 - post_residual) >= next_item_size {
            // empty bin trivially fits next item; slight bonus early when future is uncertain
            score -= 5.0 * (1.0 - progress);
        }
        let _ = spread;
    }

    // Mild stream-progress coupling: later in the stream, consolidate more aggressively
    // (prefer filling existing bins over leaving spread-out residuals).
    score += 8.0 * progress * (pr / cap);

    // Slight reward for bins already below mean residual (consolidation).
    score -= 3.0 * ((mean_residual - pr) / cap).clamp(-1.0, 1.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Harmonic class of the post residual: residues divisible by common size
    // buckets (10/20/25/50) are more reusable -> reward them.
    let pr = post_residual;
    if pr > 0 {
        let mut bonus = 0.0;
        if pr % 10 == 0 { bonus += 6.0; }
        if pr % 20 == 0 { bonus += 4.0; }
        if pr % 25 == 0 { bonus += 3.0; }
        if pr % 50 == 0 { bonus += 5.0; }
        score -= bonus;
    } else {
        // Perfect fit: strongly favored.
        score -= 60.0;
    }

    // Small dead space is worse than it looks: penalize tiny residuals
    // (1..=9) that are hard to fill with typical item sizes.
    if pr > 0 && pr < 10 {
        score += 25.0;
    }

    // Lookahead: if next item fits exactly in the post residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / cap);
        } else {
            // Next item cannot use this bin's remainder; mild penalty scaled
            // by how much capacity is stranded.
            score += 0.15 * pr as f64;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, discounted when many bins are open
        // (fragmentation risk) or late in the stream.
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_cost = 35.0 + 0.4 * open_bins_count as f64;
        // If mean residual across open bins is small, open bins are nearly
        // full -> opening a new bin is more attractive.
        if mean_residual < item_size as f64 {
            new_bin_cost -= 20.0;
        }
        if progress > 0.9 {
            new_bin_cost -= 5.0;
        }
        score = new_bin_cost + (cap - item_size as f64) * 0.1;
    }

    // Prefer tighter fits generally: normalize by capacity fraction used.
    score -= 10.0 * (item_size as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let is_new_bin = bin_residual == bin_capacity;
    let mut score = post_residual as f64;

    if is_new_bin {
        // New empty bin: moderate default score; chosen only when no open bin fits well.
        // Slightly cheaper to open early, more expensive late (avoid bin sprawl at the end).
        return 55.0 + 20.0 * progress;
    }

    // Strict dead-space avoidance: gaps too small to hold a plausible item are wasted.
    // Penalize unusable slivers (post_residual in 1..10) heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 45.0 + 10.0 * (10 - post_residual) as f64;
    }
    // Penalize awkward mid-range gaps that few item sizes can exploit.
    if post_residual >= 10 && post_residual < 25 {
        score += 12.0;
    }

    // Reward tight fills: fraction of the residual consumed by this item.
    if bin_residual > 0 {
        score -= 30.0 * (item_size as f64 / bin_residual as f64);
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 20.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post gap, reward strongly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item cannot use this gap: gap is dead weight
        score += 6.0;
    }

    // Last-chance pressure: if this is the only open bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Open-bins pressure: when many bins are open, favor consolidating into existing bins.
    score -= open_bins_count as f64 * 1.5;

    // Mild alignment with mean residual: bins already below-average residual are closer to
    // being "closed out"; prefer filling those.
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    } else {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small dead space), non-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize residuals that are too small to ever host a future item
    // (dead space below the minimum item size is pure waste).
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // Lookahead coupling: reward bins whose leftover can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 + 0.05 * next_item_size as f64;
        } else {
            // leftover cannot serve the next item; slight penalty
            score += 3.0;
        }
        // Perfect pair fit: item + next item exactly fills the bin
        if item_size + next_item_size == bin_residual {
            score -= 20.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a bin is expensive unless the item
    // is large or no good fits exist.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        // Prefer new bins early (long horizon to amortize) and for large items.
        let new_bin_bonus = 20.0 * (1.0 - progress) + 25.0 * fill_ratio;
        // But if several bins already fit, opening a new one is wasteful.
        let crowding_penalty = 10.0 * (fitting_bins_count as f64).min(5.0);
        score -= new_bin_bonus - crowding_penalty;
        // Discard the generic tightness/post-residual advantage of an empty bin
        score += post_residual as f64; // neutralize base term for empty bin
        score += 60.0 * fill_ratio - 10.0; // recalibrate: empty bin competes on merit
    }

    // Global state: many open bins with slack -> prefer reusing bins with
    // residual close to the mean (keeps the fleet balanced).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.3 * dev;

    // Late in the stream, consolidation matters more: penalize spreading.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if open_bins_count > 1 {
        score += 2.0 * progress * (open_bins_count as f64).ln();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr_norm = pr / cap;

    let mut score = pr;

    // Non-linear penalty for mid-range dead space (worst residuals are ~half full);
    // weight fades as the stream progresses (less time to fill awkward bins).
    score += 10.0 * pr_norm * (1.0 - pr_norm) * (1.0 - progress);

    // Lookahead: strongly reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= 6.0 + 5.0 * (nxt / cap);
        } else {
            score += 2.5 * (nxt / cap) * (1.0 - progress);
        }
    }

    // Last-chance bin: if this is the only open bin that fits, use it rather than open a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin while open bins can fit;
    // but if no open bin fits, opening is necessary (remove penalty).
    if bin_residual == bin_capacity {
        score += 12.0 + 10.0 * progress;
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
    }

    // Prefer tighter bins relative to the current mean residual of open bins.
    score += 0.4 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues mod small moduli proxy "dead space quality".
    let pr = post_residual;
    let r10 = (pr % 10) as f64;
    let r20 = (pr % 20) as f64;
    let r5 = (pr % 5) as f64;

    // Reward residuals whose harmonic class is highly reusable (small residue mod 10,
    // i.e. residual aligns with typical item granularity).
    score -= (10.0 - r10) * 0.35;
    score -= (20.0 - r20) * 0.15;
    score -= (5.0 - r5) * 0.10;

    // Penalize awkward mid-range dead zones: post_residual in (0, 10) is nearly unusable.
    if pr > 0 && pr < 10 {
        score += 12.0;
    }
    // Perfect fit is ideal.
    if pr == 0 {
        score -= 50.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 60.0;
        } else if next_item_size <= pr {
            score -= (pr - next_item_size) as f64 * 0.8;
            // Harmonic match between next item and residual class.
            if (pr % 10) == (next_item_size % 10) {
                score -= 6.0;
            }
        } else {
            // Next item won't fit here: penalize more if this bin would be left fragmented.
            score += (next_item_size - pr) as f64 * 0.25;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible.
    if bin_residual == bin_capacity {
        score += 30.0;
        // But if next item is large and current post_residual tiny, new bin is attractive.
        if next_item_size > 0 && next_item_size > pr && pr < 15 {
            score -= 45.0;
        }
        // Early in stream, prefer consolidation into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 8.0;
    }

    // Mean residual coupling: prefer bins whose residual is below mean (tighter packing).
    score -= (mean_residual - bin_residual as f64) * 0.4;

    // Many open bins: encourage filling existing ones rather than spreading.
    if open_bins_count > 3 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in the "unusable gap" band
    // (too small to hold even the smallest plausible next item) are heavily penalized.
    let min_useful = 10.0_f64.min(bin_capacity as f64 * 0.1);
    let gap = post_residual as f64;
    if gap > 0.0 && gap < min_useful {
        score += (min_useful - gap) * 12.0;
    }

    // Non-linear penalty on wasted capacity fraction (quadratic dead-space pressure).
    let waste_frac = gap / bin_capacity as f64;
    score += waste_frac * waste_frac * 60.0;

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 25.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    } else if gap >= next_item_size as f64 && next_item_size > 0 {
        // Reward leaving room exactly for the lookahead item.
        score -= 15.0;
    } else if next_item_size > 0 && gap > 0.0 && gap < next_item_size as f64 {
        // Penalize blocking the known next item.
        score += (next_item_size as f64 - gap) * 4.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is excellent.
    score += open_bins_count as f64 * 1.5;

    // New-bin candidate: neutral-ish baseline, only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 20.0 + mean_residual * 0.3;
        // If nothing else fits, new bin becomes the escape hatch.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Mild stream-progression drift: later in stream, prefer consolidating.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * gap * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong base: prefer tight fits (low post_residual).
    score += (post_residual as f64 / bin_capacity as f64) * 20.0;

    // 2-step lookahead: reward if next item exactly/nearly matches post_residual.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual >= next_item_size {
            // Next item fits perfectly here -> big reward.
            score -= 15.0 * (1.0 - gap / bin_capacity as f64);
            if gap == 0.0 {
                score -= 25.0;
            }
        } else {
            // Post-residual too small for next item: penalize wasted space
            // proportional to how far below next_item_size we land.
            score += 0.15 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Compare residual to mean residual across open bins: prefer leaving
    // residuals near the mean (balanced packing), penalize outliers.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.08 * dev;

    // Last chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // no open bin offers a decent fit (post_residual large relative to item).
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // Mild penalty so tight fits in existing bins usually win;
        // shrinks late in the stream when closing out bins matters less.
        score = 45.0 - 10.0 * progress;
        if next_item_size > 0 && next_item_size >= bin_capacity {
            score -= 20.0; // next item needs a full bin anyway
        }
    }

    // Small tie-break: prefer bins with more residual consumed overall.
    score -= 0.01 * (bin_residual - post_residual) as f64;

    // Penalize very small unusable slivers unless next item can use them.
    if post_residual < 10 && (next_item_size == 0 || next_item_size > post_residual) {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Reward tight fits: penalize proportionally wasted space.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Reward near-exact fills (post_residual close to 0).
    if post_residual <= 5 {
        score -= 20.0;
    } else if post_residual <= 10 {
        score -= 8.0;
    }

    // Lookahead: if next item fits in the post-residual, this is a great bin.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0 + 0.15 * next_item_size as f64;
        } else if post_residual > 0 && post_residual < 10 {
            // Small dead space that next item cannot use: acceptable.
            score -= 2.0;
        } else {
            // Large unusable leftover for the known next item: penalize.
            score += 0.1 * (post_residual as f64 - next_item_size as f64).min(30.0);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // Among many fitting bins, prefer the one leaving least waste (already via post_residual),
        // but add mild penalty scaled by competition to break ties toward fuller bins.
        score += 0.5 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate handling: opening a new bin is expensive; discourage unless
    // no good fit exists or item is huge relative to residuals.
    if bin_residual == bin_capacity {
        let open_cost = 40.0 + 10.0 * (1.0 - progress);
        // If item is large and mean residual is small, opening may be wise.
        let desperate = (item_size as f64 / bin_capacity as f64) * 30.0
            + (mean_residual < item_size as f64) as i32 as f64 * 15.0;
        score += open_cost - desperate;
    }

    // Prefer bins with residuals below mean (fill the emptier-tail bins to consolidate).
    let res_diff = bin_residual as f64 - mean_residual;
    score += 0.05 * res_diff;

    // Early in stream: encourage keeping some bins open for future large items.
    if progress < 0.3 && post_residual > 50 {
        score += 5.0 * (1.0 - progress);
    }

    // Late in stream: squeeze every bin hard.
    if progress > 0.8 {
        score -= 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let fill_ratio = 1.0 - (post_residual as f64 / cap);

    // Reward tight fits (small post_residual) more strongly as the stream progresses.
    let tightness = (post_residual as f64 / cap).powi(3);
    score -= (1.0 + 2.0 * progress) * (cap - tightness * cap) * 0.5;

    // Penalize leaving residuals that are hard to reuse: quadratic penalty on
    // small-but-not-zero leftovers, scaled by mean residual context.
    let dead = post_residual as f64;
    score += dead * dead / cap * (0.5 + progress);

    // Reward filling bins close to capacity with a smooth saturating term.
    score -= fill_ratio * fill_ratio * 30.0 * (0.4 + 0.6 * progress);

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 + 20.0 * progress;
    }

    // New-bin candidate: penalize opening new bins mildly, growing with progress
    // and number of open bins, unless it is genuinely needed.
    if bin_residual == bin_capacity {
        score += 15.0 + 10.0 * progress + 1.5 * open_bins_count as f64;
        // If the next item would fit perfectly in the fresh bin, soften the penalty.
        if next_item_size > 0 && next_item_size <= bin_capacity {
            let perfect = (next_item_size as f64 / cap - 1.0).abs();
            score -= 10.0 * (1.0 - perfect).max(0.0);
        }
    }

    // Lookahead coupling: if next item fits in the would-be post_residual,
    // reward this placement (good chaining).
    if next_item_size > 0 && next_item_size <= post_residual {
        let chain = post_residual as f64 - next_item_size as f64;
        score -= 8.0 * (1.0 - chain / cap).max(0.0);
    } else if next_item_size > post_residual as u32 && post_residual > 0 {
        // Penalize creating residuals that block the next item.
        score += 6.0 * (next_item_size as f64 - post_residual as f64) / cap;
    }

    // Mean residual alignment: prefer bins whose resulting residual is near the mean
    // (keeps a balanced portfolio of residuals for future items).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.05 * dev * (1.0 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tight-fit reward: strong bonus for small post_residual.
    if post_residual == 0 {
        score -= 1000.0; // perfect fill
    } else {
        // Harmonic class of post_residual: how many items of the smallest
        // possible size (1) could still fit — quantize dead space.
        let dead_class = post_residual / 10; // decile of wasted space
        score += dead_class as f64 * 3.0;

        // Non-linear penalty: residuals that are awkward (not multiples of
        // common item sizes) are less likely to be filled later.
        let awkward = (post_residual % 10 != 0) as f64;
        score += awkward * 2.0;

        // Reward residuals that match harmonic classes of likely next items.
        if next_item_size > 0 {
            let gap = post_residual as i64 - next_item_size as i64;
            if gap == 0 {
                score -= 500.0; // next item fits perfectly after this one
            } else if gap > 0 && (gap as u32) < 10 {
                score -= 50.0; // near-perfect chain fit
            } else if gap < 0 {
                score += 20.0; // next item won't chain here
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // Fractional capacity coupling: penalize bins whose residual is a small
    // awkward fraction of capacity after placement.
    let frac = post_residual as f64 / cap;
    if frac > 0.0 && frac < 0.1 {
        score += 15.0; // tiny sliver, likely dead space
    }

    // New-bin candidate handling: empty bin gets a mild opening cost so we
    // prefer existing bins unless they fit poorly.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Opening cost grows as stream progresses (less chance to reuse).
        score += 60.0 + 40.0 * progress + 2.0 * open_bins_count as f64;
        // But if no existing bin fits well, opening is fine — the base
        // post_residual (= capacity) already ranks it sensibly.
    } else {
        // Prefer fuller bins (best-fit bias beyond raw post_residual).
        let fullness = (bin_capacity - bin_residual) as f64 / cap;
        score -= 25.0 * fullness;
    }

    // Mean-residual coupling: if this bin's post-residual is far below the
    // mean residual of open bins, we're consolidating space well.
    score -= 0.3 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold any item (1..=100 range)
    // are pure waste. Penalize hard as post_residual approaches unusable sizes.
    let dead_zone: u32 = 9;
    if post_residual > 0 && post_residual <= dead_zone {
        score += (dead_zone as f64 - post_residual as f64) * 40.0 + 25.0;
    } else if post_residual == 0 {
        // Perfect fit is ideal: strong reward.
        score -= 60.0;
    }

    // Nonlinear penalty for leaving large-but-awkward gaps that few item sizes
    // can pair with: residual in (dead_zone, 20) is semi-usable.
    if post_residual > dead_zone && post_residual < 20 {
        score += (20.0 - post_residual as f64) * 2.0;
    }

    // Tightness reward: the smaller the item relative to the residual, the better
    // the fill ratio of this placement.
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill * 15.0;

    // Open-bin pressure: with many open bins, prefer consolidating into existing
    // bins rather than spreading; penalize new-bin candidates.
    let pressure = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when item is large (would leave
        // small residual anywhere) or no good fits exist.
        let large_item_bonus = if item_size > 60 { 10.0 } else { 0.0 };
        score += 30.0 + pressure * 45.0 - large_item_bonus;
    } else {
        score -= 5.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: reward this bin if its post_residual matches the next
    // item size (chaining placements), penalize if next item can't use leftover.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 1.5;
        }
    }

    // Mean-residual coupling: if this bin is far below mean residual, it's already
    // "tight"; prefer filling tight bins to close them out.
    let dev = mean_residual - bin_residual as f64;
    score -= dev * 0.3;

    // Mild stream-progression term: later in the stream, be slightly more eager
    // to close bins perfectly.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        if post_residual == 0 {
            score -= progress * 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near-match reward: next item almost fills the remaining space.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        // Tight fit bonus decays quickly with slack.
        score -= 40.0 / (1.0 + slack * 0.25);
        // Penalize leaving space smaller than the next item (dead space).
        if post_residual < next_item_size {
            score += 15.0;
        }
    } else if next_item_size > 0 {
        // Next item cannot fit in the post residual: dead space penalty.
        score += 12.0 + (next_item_size - post_residual) as f64 * 0.15;
    }

    // Reward using bins with low residual relative to the mean (tighten full bins).
    let residual_f = bin_residual as f64;
    if residual_f < mean_residual {
        score -= (mean_residual - residual_f) * 0.2;
    } else {
        score += (residual_f - mean_residual) * 0.1;
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no open bin fits or item is huge.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Penalize opening a new bin; overcome only via strong lookahead mismatch elsewhere.
        score += 45.0 + open_bins_count as f64 * 2.0;
        if next_item_size > 0 && item_size >= next_item_size {
            score -= 10.0;
        }
    }

    // Late in stream: prefer filling existing bins tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * (bin_capacity as f64 - post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual) more aggressively.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 0.6 * tightness * tightness * (bin_residual as f64);

    // Penalize dead space that cannot host the next item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 0.35 * (next_item_size - post_residual) as f64;
        } else {
            // Reward leaving room for the lookahead item.
            score -= 0.15 * (post_residual as f64 / next_item_size as f64).min(2.0);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Penalize spreading across many bins when mean residual is high.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.05 * open_bins_count as f64 * (0.5 + 0.5 * (1.0 - progress));

    // Prefer bins whose residual is close to the mean (balanced packing).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.1 * dev;

    // New-bin candidate: only attractive when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity && post_residual == bin_capacity - item_size;
    if is_new_bin {
        let waste_threshold = 0.5 * bin_capacity as f64;
        if post_residual as f64 > waste_threshold {
            // Large leftover after placement: opening fresh is reasonable.
            score -= 3.0 + 0.02 * open_bins_count as f64;
        } else {
            // Discourage opening new bins for good fits elsewhere.
            score += 8.0 + 0.1 * (bin_capacity - post_residual) as f64;
        }
        // Early in the stream, new bins are cheaper; late, avoid fragmentation.
        score += 4.0 * progress;
    }

    // Mild preference for fuller bins overall.
    score -= 0.02 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit_ratio = item_size as f64 / cap;
    let pr_norm = pr / cap;

    // Base: penalize leftover space, weighted by stream progress (late stream -> tighter packing)
    let mut score = pr * (1.0 + 0.8 * progress);

    // Smooth non-linear coupling: quadratic waste term for awkward residuals
    let waste = pr_norm * pr_norm;
    score += 40.0 * waste * (0.5 + progress);

    // Reward high fill ratio with a saturating term
    score -= 20.0 * fit_ratio * (1.0 - fit_ratio) * 4.0;

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: bonus if next item fits the post residual
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 8.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        // penalize residuals that waste space relative to next item
        score += 5.0 * ((pr - next_item_size as f64).abs() / cap);
    }

    // New-bin candidate: penalize opening a new bin unless residuals are tight
    if bin_residual == bin_capacity {
        let tightness = (mean_residual / cap).max(0.0).min(1.0);
        score += 10.0 + 30.0 * (1.0 - tightness) * (1.0 - progress);
    }

    // Mild penalty for many open bins with high mean residual (fragmentation)
    score += 0.05 * open_bins_count as f64 * (mean_residual / cap - pr_norm).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), penalize large waste.
    score = post_residual as f64 * 1.0;

    // Harmonic class of post_residual: residuals near multiples of common item sizes
    // (e.g., 0, 10, 20, 25, 50) are more reusable. Penalize "dead zone" residuals
    // that are too small to hold even the minimum item (1..=100 range, min ~10).
    if post_residual > 0 && post_residual < 10 {
        score += 30.0; // unusable sliver
    }

    // Modulo classes: residual divisible by 25 or 50 is highly reusable.
    if post_residual % 50 == 0 {
        score -= 6.0;
    } else if post_residual % 25 == 0 {
        score -= 3.0;
    } else if post_residual % 10 == 0 {
        score -= 1.5;
    }

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead: if next item fits in post_residual, reward this bin strongly.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
        // Extra reward if it fits exactly into a harmonic class residual.
        if post_residual - next_item_size == 0 {
            score -= 20.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item won't fit here; mild penalty for leaving a stranded residual.
        score += 4.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate (empty bin): penalize opening a new bin unless residuals
    // across open bins are already tight (mean_residual small).
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 + 5.0;
        // Allow opening a new bin when existing bins are fragmented.
        if mean_residual < 8.0 && open_bins_count > 0 {
            score -= 10.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        if total_items > 0 && (step_index as f64) / (total_items as f64) > 0.85 {
            score += 15.0;
        }
    }

    // Fragmentation guard: many open bins with high mean residual -> prefer
    // filling existing bins rather than spreading.
    if open_bins_count > 3 && mean_residual > 30.0 && bin_residual != bin_capacity {
        score -= 3.0;
    }

    // Integer-division threshold: residual in [item_min, 2*item_min) is precious;
    // avoid wasting it on a big item when a smaller chunk could use it later.
    if post_residual >= 1 && post_residual < 20 && item_size > 50 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any future
    // item (min size 1, but practically small gaps) are dead weight.
    // Penalize "unusable" gaps sharply: post_residual in (0..=item_size) range
    // that cannot accommodate the next item is wasted.
    if post_residual > 0 {
        if next_item_size > 0 && post_residual < next_item_size {
            // Dead space relative to the lookahead item: heavy penalty scaled
            // by how close the dead gap is to being useful.
            let deadness = 1.0 - (post_residual as f64 / next_item_size as f64);
            score += 12.0 * deadness;
        }
        // General small-gap penalty: gaps below 10 are almost never reusable.
        if post_residual < 10 {
            score += 15.0;
        } else if post_residual < 20 {
            score += 6.0;
        }
    } else {
        // Perfect fill: strong reward.
        score -= 25.0;
    }

    // Reward tight fits: fraction of bin used by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 10.0 * fill_ratio;

    // Last-chance bin pressure: if this is the only fitting bin, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: discourage opening new bins when many are already open.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 8.0 + 2.0 * open_bins_count as f64;
        // If no open bin fits at all, opening a new bin is fine.
        if fitting_bins_count == 0 {
            score -= 15.0;
        }
    } else {
        // Mild reward for consolidating into existing bins.
        score -= 1.0 * open_bins_count as f64 / 10.0;
    }

    // Early in the stream, be slightly more willing to open bins (flexibility);
    // late in the stream, squeeze existing bins harder.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Coupling with mean residual: prefer bins whose residual is below the mean
    // (filling the emptier-feeling bins first keeps tight bins tight).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual (best fit), scaled.
    score = post_residual as f64 * 1.0;

    // Perfect 2-step match: post_residual exactly equals next item size.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0; // perfect chaining
        } else if post_residual >= next_item_size {
            // next item fits here: reward proportionally to how snugly
            let slack_after_next = post_residual - next_item_size;
            score -= (next_item_size as f64) * 0.3 - (slack_after_next as f64) * 0.15;
        } else {
            // next item won't fit here; penalize small unusable leftovers
            if post_residual < 10 {
                score += 15.0; // dead space below minimum item size
            } else {
                score += (next_item_size - post_residual) as f64 * 0.05;
            }
        }
    }

    // Relative-to-mean coupling: bins with residual far below mean are
    // already tight; placing here concentrates waste less.
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += dev * 10.0;

    // Last-chance bonus: if this is the only fitting bin, strongly favor it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin should only win when
    // no open bin gives a good fit. Make the empty bin moderately unattractive.
    if bin_residual == bin_capacity {
        // cost of a fresh bin: base plus a term that shrinks when many
        // items remain (amortization) and when open bins are crowded.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 55.0 - 20.0 * progress + (open_bins_count as f64).min(10.0) * 0.5;
        // But if the item perfectly consumes a fresh bin, that's fine.
        if item_size >= bin_capacity {
            score -= 100.0;
        }
        // If lookahead item is large and current item is small, a fresh bin
        // lets both pack cleanly.
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity && post_residual >= next_item_size {
            score -= 30.0;
        }
    }

    // Mild preference to fill older/crowded fleets when few bins open.
    if open_bins_count > 3 && bin_residual != bin_capacity {
        score -= (open_bins_count.min(20) as f64) * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits strongly.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fill_ratio * fill_ratio;

    // Penalize small dead space that no future item (min size 1) can use efficiently.
    if post_residual > 0 {
        let dead = post_residual as f64;
        score += 8.0 * (1.0 - dead / cap) * (dead / cap).exp();
    }

    // Lookahead: if next item fits into post_residual, big reward.
    if next_item_size > 0 && (post_residual as u64) >= (next_item_size as u64) {
        score -= 10.0;
        let combo = (item_size as f64 + next_item_size as f64) / cap;
        score -= 6.0 * combo;
    } else if next_item_size > 0 {
        // Next item won't fit here; mild penalty proportional to leftover mismatch.
        let mismatch = (post_residual as f64 - next_item_size as f64).abs();
        score += 0.05 * mismatch;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Global state: many open bins with high mean residual -> prefer filling existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 0.02 * open_bins_count as f64 * (mean_residual / cap);
    score -= 3.0 * progress;

    // New-bin candidate: penalize opening a new bin, more so early and when
    // existing bins could fit (fitting_bins_count > 0 for open bins).
    if bin_residual == bin_capacity {
        let mut nb = 20.0 + 10.0 * (1.0 - progress);
        if fitting_bins_count > 0 {
            nb += 8.0;
        }
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            nb += 5.0; // a fresh bin is fine for pairing with the next item
        }
        score += nb;
    }

    // Mild noise-free tiebreak: prefer bins with residual close to item size.
    score += 0.01 * ((bin_residual as f64 - item_size as f64) / cap).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let x = pr / cap; // normalized post residual

    // Non-linear polynomial coupling of post_residual with stream progress.
    let poly = x * x * (1.0 - x) + 0.5 * x * x * x;
    let mut score = pr + 40.0 * poly * (0.5 + progress);

    // Reward tight fits more strongly as the stream progresses.
    score -= 12.0 * (1.0 - x) * x * (1.0 + progress);

    // Penalize creating dead space that cannot fit the next item.
    if next_item_size > 0 && (post_residual as u32) < next_item_size && post_residual > 0 {
        score += 8.0 + 0.3 * pr * (1.0 - pr / cap);
    }

    // Reward perfectly filling a bin.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // Mild penalty for spreading residuals when many bins are open.
    score += 0.05 * (open_bins_count as f64) * (x - mean_residual / cap).abs();

    // New-bin candidate: neutral baseline with slight openness preference early.
    if bin_residual == bin_capacity {
        score = 30.0 + 20.0 * progress - 0.2 * (fitting_bins_count as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is ideal
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: residues that are "usable" by small items
    let cap_f = bin_capacity as f64;
    let post_f = post_residual as f64;
    let fill_fraction = 1.0 - post_f / cap_f;

    // Reward high fill fraction non-linearly
    score -= 40.0 * fill_fraction * fill_fraction;

    // Dead-space penalty: post_residual too small to fit typical small items
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // unusable sliver
    }

    // Harmonic classes via integer division: post_residual buckets of size 10
    let bucket = post_residual / 10;
    let in_bucket = post_residual % 10;
    // Buckets that can host common item sizes (10..80) are more valuable
    let bucket_value = match bucket {
        0 => 0.0,
        1 => 5.0,  // can fit item 10 exactly-ish
        2 => 8.0,
        3 => 10.0,
        4 => 12.0,
        5 => 14.0,
        6 => 16.0,
        7 => 18.0,
        _ => 20.0,
    };
    score -= bucket_value;

    // Penalize awkward in-bucket residue (large leftover within bucket)
    score += 0.3 * in_bucket as f64;

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 200.0;
        } else if next_item_size <= post_residual {
            score -= 0.5 * next_item_size as f64;
            // modulo harmony: next item leaves another clean bucket
            if post_residual % 10 >= next_item_size % 10 && post_residual >= next_item_size {
                score -= 5.0;
            }
        } else {
            // next item won't fit here; slightly penalize keeping bin too full
            score += 0.2 * (next_item_size as f64 - post_f).max(0.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are very full
    if bin_residual == bin_capacity {
        score += 250.0;
        // discount new bin slightly when few bins open or stream is early
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 100.0 * (1.0 - progress) * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));
    }

    // Prefer bins with below-mean residual (pack tight bins first, keep loose bins flexible)
    score += 0.15 * (mean_residual - post_f);

    // Mild pressure to consolidate when many bins are open
    score += 0.5 * open_bins_count as f64 * (post_f / cap_f);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize residuals that are too small to be
    // useful for typical future items (unusable gaps).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let dead_threshold = 10.0 + 20.0 * (1.0 - progress); // later in stream, tolerate less waste
    if (post_residual as f64) > 0.0 && (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 2.5;
    }

    // Reward tight fits (small post_residual) with a super-linear bonus.
    if post_residual > 0 {
        score -= 40.0 * (1.0 - (post_residual as f64) / (bin_capacity as f64)).powi(3);
    } else {
        // Perfect fill is excellent.
        score -= 60.0;
    }

    // Open bins pressure: with many open bins, prefer filling existing ones;
    // opening new bins is penalized via the empty-bin candidate naturally, but
    // add pressure to keep score of existing bins lower.
    score += (open_bins_count as f64) * 0.8;

    // Lookahead: if next item fits in the post_residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0 + 0.3 * (next_item_size as f64);
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here; slightly penalize leaving a gap that traps it.
        score += 5.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Mean residual coupling: prefer bins whose residual is below mean
    // (i.e., more filled bins) to consolidate content.
    score += ((bin_residual as f64) - mean_residual) * 0.4;

    // Penalize the brand-new empty bin candidate unless existing fits are poor.
    if bin_residual == bin_capacity {
        score += 30.0 + (open_bins_count as f64) * 2.0;
        // But allow opening a new bin early in the stream when few bins exist.
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer exact/near-exact fits: dead space below smallest item (1) is waste.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 10 {
        score -= 500.0;
    }

    // 2-step lookahead: reward when the next item fits into post_residual (chain placement).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 60.0 + 0.5 * next_item_size as f64;
        } else {
            // Penalize residual that is too small for the next item but large enough to be "wasted"
            let waste = post_residual as f64 - (post_residual.min(next_item_size - 1) as f64);
            score += 0.3 * waste;
        }
    }

    // Favor bins tighter than the mean residual (good fits), penalize loose bins.
    score += 0.4 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: keep it neutral-ish; only attractive when open bins are crowded.
    if bin_residual == bin_capacity {
        score += 40.0 + 2.0 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 300.0;
        }
    }

    // Early in the stream, allow spreading across bins slightly more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.1 * (1.0 - progress);

    score
}
